struct Token {
    std::string type; // "LABEL", "INSTRUCTION", "REGISTER", "IMMEDIATE", "LABEL_REF"
    std::string value;
};

std::vector<Token> tokenize(const std::string& line) {
    std::vector<Token> tokens;
    std::regex token_regex(R"((\w+):|(\w+)|(\$?\w+)|(-?\d+))");
    std::smatch matches;

    std::string::const_iterator searchStart(line.cbegin());
    while (std::regex_search(searchStart, line.cend(), matches, token_regex)) {
        if (matches[1].matched) {
            tokens.push_back({"LABEL", matches[1]});
        } else if (matches[2].matched) {
            tokens.push_back({"INSTRUCTION", matches[2]});
        } else if (matches[3].matched) {
            tokens.push_back({"REGISTER", matches[3]});
        } else if (matches[4].matched) {
            tokens.push_back({"IMMEDIATE", matches[4]});
        }
        searchStart = matches.suffix().first;
    }

    return tokens;
}

