std::vector<std::string> tokenize(const std::string& text) {
    std::regex word_regex("\\b\\w+\\b");
    auto words_begin = std::sregex_iterator(text.begin(), text.end(), word_regex);
    auto words_end = std::sregex_iterator();
    std::vector<std::string> words;
    for (std::sregex_iterator i = words_begin; i != words_end; ++i) {
        words.push_back((*i).str());
    }
    return words;
}

std::unordered_map<std::string, std::vector<std::string>> buildGraph(const std::vector<std::string>& words) {
    std::unordered_map<std::string, std::vector<std::string>> graph;
    for (const auto& word : words) {
        for (const auto& nextWord : words) {
            if (word.back() == nextWord.front()) {
                graph[word].push_back(nextWord);
            }
        }
    }
    return graph;
}

std::vector<std::string> longestWordChain(const std::string& text) {
    std::vector<std::string> words = tokenize(text);
    std::unordered_map<std::string, std::vector<std::string>> graph = buildGraph(words);
    std::unordered_set<std::string> visited;
    std::vector<std::string> longestChain;

    std::function<void(const std::string&, std::vector<std::string>&)> dfs = [&](const std::string& word, std::vector<std::string>& chain) {
        if (visited.count(word)) return;
        visited.insert(word);
        chain.push_back(word);
        for (const auto& nextWord : graph[word]) {
            dfs(nextWord, chain);
        }
        if (chain.size() > longestChain.size()) {
            longestChain = chain;
        }
        chain.pop_back();
        visited.erase(word);
    };

    for (const auto& word : words) {
        std::vector<std::string> chain;
        dfs(word, chain);
    }
    return longestChain;
}

int main() {
    std::string text = "I love Python and Java and Rust and Ruby.";
    std::vector<std::string> result = longestWordChain(text);
    for (const auto& word : result) {
        std::cout << word << " ";
    }
    std::cout << std::endl;
    return 0;
}

