#include <wx/wx.h>

class MyFrame : public wxFrame {
public:
    MyFrame() : wxFrame(NULL, wxID_ANY, "ComboBox Example", wxDefaultPosition, wxSize(300, 150)) {
        wxPanel* panel = new wxPanel(this, wxID_ANY);

        wxString choices[] = { "Option 1", "Option 2", "Option 3" };
        comboBox = new wxComboBox(panel, wxID_ANY, wxEmptyString, wxDefaultPosition, wxDefaultSize, 3, choices, wxCB_SORT);

        comboBox->Bind(wxEVT_COMBOBOX, &MyFrame::OnComboBoxSelect, this);

        wxSizer* sizer = new wxBoxSizer(wxVERTICAL);
        sizer->Add(comboBox, 0, wxALL, 10);
        panel->SetSizer(sizer);
    }

    void OnComboBoxSelect(wxCommandEvent& event) {
        wxString selectedText = comboBox->GetValue();

        // Check if the selected element is already present in the ComboBox's choices
        bool exists = false;
        for (wxString choice : comboBox->GetStrings()) {
            if (choice == selectedText) {
                exists = true;
                break;
            }
        }

        // Add a new element only if it doesn't already exist
        if (!exists && !selectedText.empty()) {
            comboBox->Append(selectedText);
        }

        event.Skip(); // Allow further event processing
    }

private:
    wxComboBox* comboBox;
};

class MyApp : public wxApp {
public:
    bool OnInit() {
        MyFrame* frame = new MyFrame();
        frame->Show();
        return true;
    }
};

wxIMPLEMENT_APP(MyApp);

#include <atomic>

using u64 = unsigned long long;

struct Bucket {
    u64 mLeaves[16] = {};
};

struct BucketMap {
    u64 acquire() noexcept {
        while (true) {
            u64 map = mData.load(std::memory_order_relaxed);

            u64 index = (map & 1) ? 1 : 0;
            auto mask = u64(1) << index;

            auto previous =
                mData.fetch_or(mask, std::memory_order_relaxed);
            if ((previous & mask) == 0) {
                return index;
            }
        }
    }

    __attribute__((noinline)) Bucket acquireBucket() noexcept {
        acquire();
        return Bucket();
    }

    std::atomic<u64> mData{ 1 };
};

int main() {
    BucketMap map;
    map.acquireBucket();
    return 0;
}

