using namespace clang::ast_matchers;

class CustomCheck : public clang::tidy::ClangTidyCheck {
public:
  CustomCheck(StringRef Name, ClangTidyContext *Context)
      : ClangTidyCheck(Name, Context) {}

  void registerMatchers(ast_matchers::MatchFinder *Finder) override {
    Finder->addMatcher(callExpr(callee(functionDecl(hasName("old_function")))).bind("call"), this);
  }

  void check(const MatchFinder::MatchResult &Result) override {
    const auto *Call = Result.Nodes.getNodeAs<CallExpr>("call");
    if (!Call)
      return;

    auto &Rewriter = *Result.Rewriter;
    Rewriter.InsertText(Call->getBeginLoc(), "new_function();\n", true, true);
  }
};

static RegisterCheck<CustomCheck> X("custom-check", "Custom Clang-Tidy Check");

