  std::vector<int> find_primes_for(int start, int end) {
      if (start > end) throw std::invalid_argument("Start must be less than or equal to end.");
      std::vector<int> primes;
      for (int num = std::max(2, start); num <= end; ++num) {
          bool is_prime = true;
          for (int divisor = 2; divisor <= std::sqrt(num); ++divisor) {
              if (num % divisor == 0) {
                  is_prime = false;
                  break;
              }
          }
          if (is_prime) primes.push_back(num);
      }
      return primes;
  }

