// Function to convert numpy.uint8 to unsigned char
unsigned char convert_numpy_uint8(PyObject* obj) {
    if (PyArray_Check(obj)) {
        PyArrayObject* array = reinterpret_cast<PyArrayObject*>(obj);
        if (PyArray_TYPE(array) == NPY_UINT8) {
            return *reinterpret_cast<unsigned char*>(PyArray_DATA(array));
        }
    }
    throw boost::python::error_already_set();
}

