double vector_length(const std::vector<double>& a) {
    double sum = 0.0;
    for (size_t i = 0; i < a.size(); ++i) {
        sum += a[i] * a[i];
    }
    // Ensure the sum is non-negative
    if (sum < 0.0) {
        // This should never happen, but we handle it to avoid undefined behavior
        sum = 0.0;
    }
    return std::sqrt(sum);
}

