std::string longestCommonSubstring(const std::string& s1, const std::string& s2) {
    int m = s1.size();
    int n = s2.size();

    // DP table to store lengths of longest common suffixes
    std::vector<std::vector<int>> dp(m + 1, std::vector<int>(n + 1, 0));

    // Variables to track the maximum length and its ending position
    int maxLength = 0;
    int endIndex = -1;

    // Fill the DP table
    for (int i = 1; i <= m; ++i) {
        for (int j = 1; j <= n; ++j) {
            if (s1[i - 1] == s2[j - 1]) {
                dp[i][j] = dp[i - 1][j - 1] + 1;
                if (dp[i][j] > maxLength) {
                    maxLength = dp[i][j];
                    endIndex = i - 1;
                }
            } else {
                dp[i][j] = 0;
            }
        }
    }

    // Reconstruct the longest common substring
    if (maxLength == 0) {
        return "";
    }

    return s1.substr(endIndex - maxLength + 1, maxLength);
}

int main() {
    std::string s1 = "abcde";
    std::string s2 = "abfcd";

    std::string result = longestCommonSubstring(s1, s2);
    std::cout << "Longest Common Substring: " << result << std::endl;

    return 0;
}

