u64 acquire() noexcept {
    while (true) {
        u64 map = mData;

        u64 index = (map & 1) ? 1 : 0;
        auto mask = u64(1) << index;

        auto previous =
            __atomic_fetch_or(&mData, mask, __ATOMIC_SEQ_CST);
        if ((previous & mask) == 0) {
            return index;
        }
    }
}

