#define BLOCK_SIZE 256

__global__ void rowSumKernel(const float* __restrict__ d_matrix, float* __restrict__ d_rowSums, int numRows, int numCols) {
    __shared__ float sharedMem[BLOCK_SIZE];
    int row = blockIdx.x;
    int tid = threadIdx.x;
    int start = row * numCols + tid;
    int stride = BLOCK_SIZE;

    float sum = 0.0f;
    for (int i = start; i < (row + 1) * numCols; i += stride) {
        sum += d_matrix[i];
    }

    sharedMem[tid] = sum;
    __syncthreads();

    for (int s = BLOCK_SIZE / 2; s > 0; s >>= 1) {
        if (tid < s) {
            sharedMem[tid] += sharedMem[tid + s];
        }
        __syncthreads();
    }

    if (tid == 0) {
        d_rowSums[row] = sharedMem[0];
    }
}

void rowSumCUDA(const float* h_matrix, float* h_rowSums, int numRows, int numCols) {
    float* d_matrix;
    float* d_rowSums;
    size_t matrixSize = numRows * numCols * sizeof(float);
    size_t rowSumsSize = numRows * sizeof(float);

    cudaMalloc((void**)&d_matrix, matrixSize);
    cudaMalloc((void**)&d_rowSums, rowSumsSize);

    cudaMemcpy(d_matrix, h_matrix, matrixSize, cudaMemcpyHostToDevice);

    dim3 blockSize(BLOCK_SIZE);
    dim3 gridSize((numRows + blockSize.x - 1) / blockSize.x);

    rowSumKernel<<<gridSize, blockSize>>>(d_matrix, d_rowSums, numRows, numCols);

    cudaMemcpy(h_rowSums, d_rowSums, rowSumsSize, cudaMemcpyDeviceToHost);

    cudaFree(d_matrix);
    cudaFree(d_rowSums);
}

int main() {
    int numRows = 90000;
    int numCols = 1000;
    std::vector<float> h_matrix(numRows * numCols, 1.0f);
    std::vector<float> h_rowSums(numRows, 0.0f);

    auto start = std::chrono::high_resolution_clock::now();
    rowSumCUDA(h_matrix.data(), h_rowSums.data(), numRows, numCols);
    auto end = std::chrono::high_resolution_clock::now();

    std::chrono::duration<double> duration = end - start;
    std::cout << "CUDA Time Elapsed: " << duration.count() * 1000 << " ms" << std::endl;

    return 0;
}

