std::vector<double> quaternionMultiply(const std::vector<double>& q1, const std::vector<double>& q2) {
    double w1 = q1[0];
    double x1 = q1[1];
    double y1 = q1[2];
    double z1 = q1[3];

    double w2 = q2[0];
    double x2 = q2[1];
    double y2 = q2[2];
    double z2 = q2[3];

    double w = w1 * w2 - x1 * x2 - y1 * y2 - z1 * z2;
    double x = w1 * x2 + x1 * w2 + y1 * z2 - z1 * y2;
    double y = w1 * y2 - x1 * z2 + y1 * w2 + z1 * x2;
    double z = w1 * z2 + x1 * y2 - y1 * x2 + z1 * w2;

    return {w, x, y, z};
}

int main() {
    std::vector<double> q1 = {0.98, 0.08, 0.17, -0.01};
    std::vector<double> q2 = {0.70, 0.70, 0.0, 0.0};

    std::vector<double> result = quaternionMultiply(q1, q2);

    for (double val : result) {
        std::cout << val << " ";
    }
    std::cout << std::endl;

    return 0;
}

