/* Define the Sequence object */
typedef struct {
    PyObject_HEAD
    size_t max;
} SequenceObject;

static int Sequence_Init(SequenceObject *self, PyObject *args, PyObject *kwds) {
    if (!PyArg_ParseTuple(args, "k", &(self->max))) {
        return -1;
    }
    return 0;
}

static PyObject* Sequence_data(SequenceObject *self, PyObject *args) {
    IterObject* iter = (IterObject*)IterObjectType.tp_alloc(&IterObjectType, 0);
    if (iter != NULL) {
        iter->max = self->max;
        iter->current = 0;
    }
    return (PyObject*)iter;
}

