/* Module definition */
static PyModuleDef sequence_module = {
    PyModuleDef_HEAD_INIT,
    "sequence",   /* name of module */
    NULL,         /* module documentation, may be NULL */
    -1,           /* size of per-interpreter state of the module, or -1 if the module keeps state in global variables. */
    NULL
};

/* Module initialization function */
PyMODINIT_FUNC PyInit_sequence(void) {
    PyObject* m;

    IterObjectType.tp_new = PyType_GenericNew;
    if (PyType_Ready(&IterObjectType) < 0)
        return NULL;

    Sequence_Type.tp_new = PyType_GenericNew;
    if (PyType_Ready(&Sequence_Type) < 0)
        return NULL;

    m = PyModule_Create(&sequence_module);
    if (m == NULL)
        return NULL;

    Py_INCREF(&Sequence_Type);
    PyModule_AddObject(m, "Sequence", (PyObject*)&Sequence_Type);

    Py_INCREF(&IterObjectType);
    PyModule_AddObject(m, "IterObject", (PyObject*)&IterObjectType);

    return m;
}

