#include <atomic>
#include <tuple>

typedef struct {
    std::atomic<std::uint64_t> low;
    std::atomic<std::uint64_t> high;
} uint128_atomic;

uint128_atomic load_relaxed(const uint128_atomic* atomic) {
    return {atomic->low.load(std::memory_order_relaxed),
            atomic->high.load(std::memory_order_relaxed)};
}

bool cmpexch_weak_relaxed(uint128_atomic* atomic, uint128_atomic* expected, uint128_atomic desired) {
    std::uint64_t old_low = expected->low.load(std::memory_order_relaxed);
    std::uint64_t old_high = expected->high.load(std::memory_order_relaxed);
    bool matched = atomic->low.compare_exchange_weak(old_low, desired.low, std::memory_order_relaxed);
    if (matched) {
        matched = atomic->high.compare_exchange_weak(old_high, desired.high, std::memory_order_relaxed);
    }
    return matched;
}

void store_relaxed(uint128_atomic* atomic, uint128_atomic val) {
    atomic->low.store(val.low, std::memory_order_relaxed);
    atomic->high.store(val.high, std::memory_order_relaxed);
}

#include <Adafruit_NeoPixel.h>

#define LED_PIN 6
#define NUM_LEDS 22
#define BUTTON_PIN 2

Adafruit_NeoPixel leds = Adafruit_NeoPixel(NUM_LEDS, LED_PIN, NEO_GRB + NEO_KHZ800);

enum FlameMode { ModeA, ModeB, ModeC };
FlameMode currentMode = ModeA;

int buttonState = 0;
int lastButtonState = 0;
unsigned long lastDebounceTime = 0;
unsigned long debounceDelay = 50;

void setup() {
  leds.begin();
  pinMode(BUTTON_PIN, INPUT_PULLUP);
}

void loop() {
  readButton();

  switch (currentMode) {
    case ModeA:
      drawFlame(255, 95, 0);  // normal fire color
      break;
    case ModeB:
      drawFlame(0, 255, 0);   // green/yellow flame with more green than yellow
      break;
    case ModeC:
      drawFlame(0, 0, 255);   // blue/white flame
      break;
  }
}

void drawFlame(uint8_t r, uint8_t g, uint8_t b) {
  for (int i = 0; i < NUM_LEDS; i++) {
    int flicker = random(128, 256);  // add flickering effect
    leds.setPixelColor(i, r * flicker / 255, g * flicker / 255, b * flicker / 255);
  }
  leds.show();
}

void readButton() {
  int reading = digitalRead(BUTTON_PIN);

  if (reading != lastButtonState) {
    lastDebounceTime = millis();
  }

  if ((millis() - lastDebounceTime) > debounceDelay) {
    if (reading != buttonState) {
      buttonState = reading;

      if (buttonState == LOW) {
        switchFlameMode();
      }
    }
  }

  lastButtonState = reading;
}

void switchFlameMode() {
  switch (currentMode) {
    case ModeA:
      currentMode = ModeB;
      break;
    case ModeB:
      currentMode = ModeC;
      break;
    case ModeC:
      currentMode = ModeA;
      break;
  }
}

