uint64_t rdtscp() {
    uint32_t lo, hi;
    __asm__ __volatile__("rdtscp" : "=a"(lo), "=d"(hi) : : "rcx");
    return ((uint64_t)hi << 32) | lo;
}

int main() {
    unsigned long long t1, t2;
    const int num_nops = 1000000;

    t1 = rdtscp();
    for (int i = 0; i < num_nops; ++i) {
        asm volatile("nop");
    }
    t2 = rdtscp();
    printf("rdtscp for %d NOPs: %llu cycles\n", num_nops, t2 - t1);

    t1 = rdtscp();
    for (int i = 0; i < num_nops; ++i) {
        asm volatile("nop; nop; nop; nop; nop; nop; nop;");
    }
    t2 = rdtscp();
    printf("rdtscp for %d * 7 NOPs: %llu cycles\n", num_nops, t2 - t1);

    return 0;
}

