class Person {
private:
    std::string name;
    std::set<std::string> nicknames;
    std::set<std::string> titles;

public:
    Person(const std::string& name) : name(name) {}

    // Add a nickname
    void addNickname(const std::string& nickname) {
        if (nickname.empty()) {
            throw std::invalid_argument("Nickname cannot be empty.");
        }
        nicknames.insert(nickname);
    }

    // Delete a nickname
    void deleteNickname(const std::string& nickname) {
        if (nicknames.erase(nickname) == 0) {
            throw std::invalid_argument("Nickname does not exist.");
        }
    }

    // Update a nickname
    void updateNickname(const std::string& oldNickname, const std::string& newNickname) {
        if (oldNickname == newNickname) {
            return; // No change needed
        }
        if (nicknames.find(oldNickname) == nicknames.end()) {
            throw std::invalid_argument("Old nickname does not exist.");
        }
        if (!newNickname.empty()) {
            nicknames.erase(oldNickname);
            nicknames.insert(newNickname);
        } else {
            throw std::invalid_argument("New nickname cannot be empty.");
        }
    }

    // Add a title
    void addTitle(const std::string& title) {
        if (title.empty()) {
            throw std::invalid_argument("Title cannot be empty.");
        }
        titles.insert(title);
    }

    // Delete a title
    void deleteTitle(const std::string& title) {
        if (titles.erase(title) == 0) {
            throw std::invalid_argument("Title does not exist.");
        }
    }

    // Update a title
    void updateTitle(const std::string& oldTitle, const std::string& newTitle) {
        if (oldTitle == newTitle) {
            return; // No change needed
        }
        if (titles.find(oldTitle) == titles.end()) {
            throw std::invalid_argument("Old title does not exist.");
        }
        if (!newTitle.empty()) {
            titles.erase(oldTitle);
            titles.insert(newTitle);
        } else {
            throw std::invalid_argument("New title cannot be empty.");
        }
    }

    // Retrieve nicknames
    const std::set<std::string>& getNicknames() const {
        return nicknames;
    }

    // Retrieve titles
    const std::set<std::string>& getTitles() const {
        return titles;
    }

    // Retrieve the person's name
    const std::string& getName() const {
        return name;
    }
};

#include <windows.h>

LRESULT CALLBACK WndProc(HWND hwnd, UINT msg, WPARAM wParam, LPARAM lParam);

int WINAPI WinMain(HINSTANCE hInstance, HINSTANCE hPrevInstance, LPSTR lpCmdLine, int nCmdShow) {
    WNDCLASS wc = {0};
    wc.lpfnWndProc = WndProc;
    wc.hInstance = hInstance;
    wc.hbrBackground = CreateSolidBrush(RGB(255, 255, 255));
    wc.lpszClassName = "MyWndClass";
    RegisterClass(&wc);

    HWND hwnd = CreateWindow(
        "MyWndClass",
        "Draggable and Transparent Window",
        WS_OVERLAPPEDWINDOW,
        CW_USEDEFAULT, CW_USEDEFAULT, 400, 300,
        NULL, NULL, hInstance, NULL
    );
    SetWindowLong(hwnd, GWL_EXSTYLE, GetWindowLong(hwnd, GWL_EXSTYLE) | WS_EX_LAYERED);

    ShowWindow(hwnd, nCmdShow);

    MSG msg = {0};
    while (GetMessage(&msg, NULL, 0, 0)) {
        TranslateMessage(&msg);
        DispatchMessage(&msg);
    }
    return msg.wParam;
}

LRESULT CALLBACK WndProc(HWND hwnd, UINT msg, WPARAM wParam, LPARAM lParam) {
    static POINT offset;
    static BOOL dragging = FALSE;
    switch (msg) {
        case WM_DESTROY:
            PostQuitMessage(0);
            break;
        case WM_LBUTTONDOWN:
            offset.x = GET_X_LPARAM(lParam);
            offset.y = GET_Y_LPARAM(lParam);
            dragging = TRUE;
            SetLayeredWindowAttributes(hwnd, 0, 200, LWA_ALPHA);
            SetCursor(LoadCursor(NULL, IDC_SIZEALL));
            break;
        case WM_MOUSEMOVE:
            if (dragging) {
                int x = GET_X_LPARAM(lParam) - offset.x;
                int y = GET_Y_LPARAM(lParam) - offset.y;
                SetWindowPos(hwnd, NULL, x, y, 0, 0, SWP_NOSIZE | SWP_NOZORDER | SWP_NOACTIVATE);
            }
            break;
        case WM_LBUTTONUP:
            dragging = FALSE;
            SetLayeredWindowAttributes(hwnd, 0, 255, LWA_ALPHA);
            SetCursor(LoadCursor(NULL, IDC_ARROW));
            break;
        default:
            return DefWindowProc(hwnd, msg, wParam, lParam);
    }
    return 0;
}

