#include <windows.h>
#include <ras.h>
#include <iphlpapi.h>
#include <stdio.h>

#pragma comment(lib, "rasapi32.lib")
#pragma comment(lib, "iphlpapi.lib")

void GetRASConnectionIP(HRASCONN hRasConn)
{
    // Step 1: Get RAS connection status
    RASCONNSTATUS rasConnStatus = { sizeof(RASCONNSTATUS) };
    if (RasGetConnectStatus(hRasConn, &rasConnStatus) == ERROR_SUCCESS)
    {
        printf("RAS connection device name: %s\n", rasConnStatus.szDeviceName);

        // Step 2: Get all network adapters information
        PIP_ADAPTER_ADDRESSES pAdapterAddresses = NULL;
        ULONG ulOutBufLen = 0;
        ULONG dwRetVal = 0;

        // Make an initial call to GetAdaptersAddresses to get the necessary size of the buffer
        dwRetVal = GetAdaptersAddresses(AF_UNSPEC, GAA_FLAG_INCLUDE_PREFIX, NULL, pAdapterAddresses, &ulOutBufLen);
        if (dwRetVal == ERROR_BUFFER_OVERFLOW)
        {
            pAdapterAddresses = (IP_ADAPTER_ADDRESSES*)malloc(ulOutBufLen);
            if (pAdapterAddresses == NULL)
            {
                printf("Memory allocation failed\n");
                return;
            }
        }

        // Make a second call to GetAdaptersAddresses to get the actual data
        dwRetVal = GetAdaptersAddresses(AF_UNSPEC, GAA_FLAG_INCLUDE_PREFIX, NULL, pAdapterAddresses, &ulOutBufLen);
        if (dwRetVal == NO_ERROR)
        {
            PIP_ADAPTER_ADDRESSES pAdapter = pAdapterAddresses;
            while (pAdapter)
            {
                // Step 3: Match the device name with the adapter description or name
                if (wcscmp(pAdapter->Description, rasConnStatus.szDeviceName) == 0 || wcscmp(pAdapter->FriendlyName, rasConnStatus.szDeviceName) == 0)
                {
                    PIP_ADAPTER_UNICAST_ADDRESS pUnicast = pAdapter->FirstUnicastAddress;
                    while (pUnicast)
                    {
                        if (pUnicast->Address.lpSockaddr->sa_family == AF_INET)
                        {
                            char ipStringBuffer[46];
                            DWORD ipStringSize = 46;
                            if (GetIPAddressString(pUnicast->Address.lpSockaddr, ipStringBuffer, &ipStringSize))
                            {
                                printf("RAS connection IP address: %s\n", ipStringBuffer);
                            }
                        }
                        pUnicast = pUnicast->Next;
                    }
                    break;
                }
                pAdapter = pAdapter->Next;
            }
        }
        else
        {
            printf("GetAdaptersAddresses failed with error: %d\n", dwRetVal);
        }

        if (pAdapterAddresses)
        {
            free(pAdapterAddresses);
        }
    }
    else
    {
        printf("RasGetConnectStatus failed\n");
    }
}

// Helper function to convert sockaddr to string
BOOL GetIPAddressString(const sockaddr* pAddr, char* pStringBuffer, DWORD* pStringSize)
{
    struct sockaddr_in* pAddrIn = (struct sockaddr_in*)pAddr;
    return (inet_ntop(AF_INET, &pAddrIn->sin_addr, pStringBuffer, *pStringSize) != NULL);
}

int main()
{
    // Assume you have a valid HRASCONN handle
    HRASCONN hRasConn = /* Your HRASCONN handle */;

    GetRASConnectionIP(hRasConn);

    return 0;
}

class JammingWeapon : Weapon
{
    float fJamChance;
    int iJamTimer;
    bool bJammed;

    Default
    {
        fJamChance = 0.05; // 5% chance of jamming
        iJamTimer = 70; // Jamming period in tics
        bJammed = false;
    }

    States
    {
    Ready:
        WEAP B 1 A_WeaponReady;
        Loop;

    Deselect:
        TNT1 A 0 A_JamCheck; // Add the jamming check
        WEAP C 1 A_Lower;
        Loop;

    Select:
        TNT1 A 0 A_JamCheck; // Add the jamming check
        WEAP C 1 A_Raise;
        Loop;

    Fire:
        WEAP A 0 Bright A_PlaySound("weapons/pistol", CHAN_WEAPON);
        TNT1 A 0 A_JamCheck; // Add the jamming check

        WEAP A 0 A_GunFlash;
        WEAP A 1 Bright;
        WEAP A 0 A_FireBullets(1, 1, 1, 5, "BulletPuff");

        WEAP A 0 A_ReFire;
        Goto Ready;

    Flash:
        TNT1 A 0 A_JamCheck; // Add the jamming check
        Goto LightDone;

    Jam:
        WEAP A 3 A_PlaySound("weapons/jam", CHAN_WEAPON);
        WEAP A 3;
        WEAP A 3;
        WEAP A 0 A_JamCooldown;
        Goto Ready;

    LightDone:
        TNT1 A 0 A_Light0;
        Stop;
    }

    override void PostBeginPlay()
    {
        Super.PostBeginPlay();
    }

    private state void A_JamCheck()
    {
        if (bJammed)
            Goto Jam;

        if (random() < fJamChance)
        {
            bJammed = true;
            Goto Jam;
        }
    }

    private state void A_JamCooldown()
    {
        iJamTimer--;
        if (iJamTimer <= 0)
        {
            bJammed = false;
            iJamTimer = 70;
        }
    }
}

