#include <iostream>
#include <cmath>
#include <chrono>
#include <vector>

const unsigned int k_max = 40000;
const unsigned int N = 10000;

int main()
{
    std::vector<double> data1(N);
    std::vector<double> data2(N);
    std::vector<double> coefs1(k_max, 0.0);
    std::vector<double> coefs2(k_max, 0.0);

    auto start = std::chrono::high_resolution_clock::now();

    for (unsigned int k = 1; k <= k_max; ++k) {
        std::vector<double> cos_k(N);
        std::vector<double> sin_k(N);

        for (unsigned int j = 0; j < N; ++j) {
            cos_k[j] = std::cos(k * data1[j]);
            sin_k[j] = std::sin(k * data1[j]);
        }

        coefs1[k-1] += (data2[N-1] - data2[0]) + std::inner_product(data2.begin(), data2.end()-1, cos_k.begin(), 0.0, std::plus<double>(), std::minus<double>());
        coefs2[k-1] += std::inner_product(data2.begin(), data2.end()-1, sin_k.begin(), 0.0, std::plus<double>(), std::minus<double>());
    }

    auto stop = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration_cast<std::chrono::seconds>(stop - start);

    std::cout << "Time: " << duration.count() << " seconds" << std::endl;
    return 0;
}

