struct InsertInlineAsmPass : public FunctionPass {
  static char ID; // Pass identification, replacement for typeid
  InsertInlineAsmPass() : FunctionPass(ID) {}

  bool runOnFunction(Function &F) override {
    IRBuilder<> Builder(&F.getEntryBlock(), F.getEntryBlock().begin());

    // Define the inline assembly
    const char *AsmString = "bswap $0";
    const char *Constraints = "=r,r";
    Type *ResultType = Type::getInt32Ty(F.getContext());
    std::vector<Type *> ArgTypes = {Type::getInt32Ty(F.getContext())};
    FunctionType *FTy = FunctionType::get(ResultType, ArgTypes, false);

    // Create the InlineAsm object
    InlineAsm *IA = InlineAsm::get(FTy, AsmString, Constraints, false, false);

    // Create the call instruction
    Value *Arg = ConstantInt::get(Type::getInt32Ty(F.getContext()), 1234); // Example argument
    CallInst *Call = Builder.CreateCall(IA, Arg, "bswap_result");

    // Optionally, you can insert the call instruction at a specific position
    // For example, to insert it before the first instruction in the entry block:
    // Instruction *InsertBefore = &F.getEntryBlock().front();
    // CallInst *Call = Builder.CreateCall(IA, Arg, "bswap_result", InsertBefore);

    return true; // Return true to indicate that the function was modified
  }
};

