#include <iostream>
#include <optional>

class Node {
public:
    int value;
    Node* prev;
    Node* next;

    Node(int val) : value(val), prev(nullptr), next(nullptr) {}
};

class SelfOrganizingList {
private:
    Node* head;
    Node* tail;

public:
    SelfOrganizingList() : head(nullptr), tail(nullptr) {}

    ~SelfOrganizingList() {
        while (head != nullptr) {
            Node* temp = head;
            head = head->next;
            delete temp;
        }
    }

    void insert(int value) {
        Node* newNode = new Node(value);
        if (head == nullptr) {
            head = tail = newNode;
        } else {
            newNode->next = head;
            head->prev = newNode;
            head = newNode;
        }
    }

    bool remove(int value) {
        Node* current = head;
        while (current != nullptr) {
            if (current->value == value) {
                if (current->prev) {
                    current->prev->next = current->next;
                } else {
                    head = current->next;
                }
                if (current->next) {
                    current->next->prev = current->prev;
                } else {
                    tail = current->prev;
                }
                delete current;
                return true;
            }
            current = current->next;
        }
        return false;
    }

    std::optional<int> search(int value) {
        Node* current = head;
        while (current != nullptr) {
            if (current->value == value) {
                moveToFront(current);
                return current->value;
            }
            current = current->next;
        }
        return std::nullopt;
    }

private:
    void moveToFront(Node* node) {
        if (node == head) return;

        if (node->prev) {
            node->prev->next = node->next;
        }
        if (node->next) {
            node->next->prev = node->prev;
        }
        if (node == tail) {
            tail = node->prev;
        }

        node->next = head;
        node->prev = nullptr;
        head->prev = node;
        head = node;
    }
};

int main() {
    SelfOrganizingList list;
    list.insert(1);
    list.insert(2);
    list.insert(3);
    list.insert(4);

    std::cout << "Search for 3: " << list.search(3).value_or(-1) << std::endl;
    std::cout << "Search for 1: " << list.search(1).value_or(-1) << std::endl;
    std::cout << "Search for 2: " << list.search(2).value_or(-1) << std::endl;

    list.remove(3);
    std::cout << "Search for 3 after removal: " << list.search(3).value_or(-1) << std::endl;

    return 0;
}

