__global__ void simple_copy(float *outdata, const float *indata, int width, int height) {
    __shared__ float tile[TILE_DIM][TILE_DIM];

    int x = blockIdx.x * TILE_DIM + threadIdx.x;
    int y = blockIdx.y * TILE_DIM + threadIdx.y;

    if (x < width && y < height) {
        tile[threadIdx.y][threadIdx.x] = indata[y * width + x];
    }

    __syncthreads();

    if (x < width && y < height) {
        outdata[y * width + x] = tile[threadIdx.y][threadIdx.x];
    }
}

