template <typename T>
class DoublyLinkedList {
public:
    struct Node {
        T data;
        Node* prev;
        Node* next;
        Node(T data) : data(data), prev(nullptr), next(nullptr) {}
    };

    DoublyLinkedList() : head(nullptr), tail(nullptr) {}

    ~DoublyLinkedList() {
        while (head) {
            Node* temp = head;
            head = head->next;
            delete temp;
        }
    }

    void insert(T data) {
        Node* newNode = new Node(data);
        if (!head) {
            head = tail = newNode;
        } else {
            tail->next = newNode;
            newNode->prev = tail;
            tail = newNode;
        }
        nodeMap[data] = newNode;
    }

    Node* search(T data) {
        if (nodeMap.find(data) != nodeMap.end()) {
            return nodeMap[data];
        }
        return nullptr;
    }

    void remove(T data) {
        if (nodeMap.find(data) != nodeMap.end()) {
            Node* node = nodeMap[data];
            if (node->prev) node->prev->next = node->next;
            if (node->next) node->next->prev = node->prev;
            if (node == head) head = node->next;
            if (node == tail) tail = node->prev;
            delete node;
            nodeMap.erase(data);
        }
    }

private:
    Node* head;
    Node* tail;
    std::unordered_map<T, Node*> nodeMap;
};

int main() {
    DoublyLinkedList<int> list;
    list.insert(1);
    list.insert(2);
    list.insert(3);

    DoublyLinkedList<int>::Node* node = list.search(2);
    if (node) {
        std::cout << "Found: " << node->data << std::endl;
    } else {
        std::cout << "Not found" << std::endl;
    }

    list.remove(2);
    node = list.search(2);
    if (node) {
        std::cout << "Found: " << node->data << std::endl;
    } else {
        std::cout << "Not found" << std::endl;
    }

    return 0;
}

