uint64_t htonll(uint64_t value) {
    static const int isLittleEndian = (1 == *(uint8_t *)&(uint32_t){1});
    if (isLittleEndian) {
        return ((uint64_t)htonl(value) << 32) | htonl(value >> 32);
    }
    return value;
}

