// Vector operations
std::array<double, 3> operator-(const std::array<double, 3>& a, const std::array<double, 3>& b) {
    return {a[0] - b[0], a[1] - b[1], a[2] - b[2]};
}

double dot(const std::array<double, 3>& a, const std::array<double, 3>& b) {
    return a[0] * b[0] + a[1] * b[1] + a[2] * b[2];
}

double norm(const std::array<double, 3>& a) {
    return std::sqrt(dot(a, a));
}

std::array<double, 3> normalize(const std::array<double, 3>& a) {
    double n = norm(a);
    return {a[0] / n, a[1] / n, a[2] / n};
}

// Cube class
class Cube {
public:
    Cube(const std::array<double, 3>& pos, const double ext)
        : _position(pos), _extent(ext) {}

    std::array<double, 3> center() const { return _position; }
    double min(const unsigned int idim) const { return _position[idim] - _extent / 2; }
    double max(const unsigned int idim) const { return _position[idim] + _extent / 2; }
    double extent() const { return _extent; }

private:
    std::array<double, 3> _position;
    double _extent;
};

// Cone class
class Cone {
public:
    Cone(const std::array<double, 3>& vert, const std::array<double, 3>& bas, const double ang)
        : _vertex(vert), _base(bas), _angle(ang) {}

    std::array<double, 3> vertex() const { return _vertex; }
    std::array<double, 3> base() const { return _base; }
    double angle() const { return _angle; }
    double height() const { return norm(_vertex - _base); }
    double radius() const { return std::tan(_angle) * height(); }

private:
    std::array<double, 3> _vertex;
    std::array<double, 3> _base;
    double _angle;
};

// Check if a point is inside the cone
bool isInsideCone(const Cone& cone, const std::array<double, 3>& point) {
    std::array<double, 3> v = cone.vertex();
    std::array<double, 3> b = cone.base();
    std::array<double, 3> d = normalize(b - v);
    double h = cone.height();
    double r = cone.radius();
    double t = dot(point - v, d);

    if (t < 0 || t > h) return false;

    std::array<double, 3> p = v + t * d;
    double dist = norm(point - p);

    return dist <= r * t / h;
}

// Check if the cube and cone intersect
bool doesIntersect(const Cube& cube, const Cone& cone) {
    // Check all 8 vertices of the cube
    for (int i = 0; i < 2; ++i) {
        for (int j = 0; j < 2; ++j) {
            for (int k = 0; k < 2; ++k) {
                std::array<double, 3> vertex = {
                    cube.min(0) + i * cube.extent(),
                    cube.min(1) + j * cube.extent(),
                    cube.min(2) + k * cube.extent()
                };
                if (isInsideCone(cone, vertex)) return true;
            }
        }
    }

    // Check all 12 edges of the cube
    for (int i = 0; i < 2; ++i) {
        for (int j = 0; j < 2; ++j) {
            for (int k = 0; k < 2; ++k) {
                std::array<double, 3> v1 = {
                    cube.min(0) + i * cube.extent(),
                    cube.min(1) + j * cube.extent(),
                    cube.min(2) + k * cube.extent()
                };
                for (int l = 0; l < 3; ++l) {
                    int next = (l + 1) % 3;
                    std::array<double, 3> v2 = v1;
                    v2[l] += (i == 0 ? cube.extent() : -cube.extent());
                    if (isInsideCone(cone, v2)) return true;
                    if (isInsideCone(cone, (v1 + v2) / 2.0)) return true;
                }
            }
        }
    }

    // Check all 6 faces of the cube
    for (int i = 0; i < 2; ++i) {
        for (int j = 0; j < 2; ++j) {
            for (int k = 0; k < 2; ++k) {
                std::array<double, 3> v1 = {
                    cube.min(0) + i * cube.extent(),
                    cube.min(1) + j * cube.extent(),
                    cube.min(2) + k * cube.extent()
                };
                for (int l = 0; l < 3; ++l) {
                    int next = (l + 1) % 3;
                    std::array<double, 3> v2 = v1;
                    v2[l] += (i == 0 ? cube.extent() : -cube.extent());
                    std::array<double, 3> v3 = v1;
                    v3[next] += (j == 0 ? cube.extent() : -cube.extent());
                    std::array<double, 3> v4 = v2;
                    v4[next] += (j == 0 ? cube.extent() : -cube.extent());
                    if (isInsideCone(cone, (v1 + v2 + v3 + v4) / 4.0)) return true;
                }
            }
        }
    }

    return false;
}

int main() {
    Cube cube({0.0, 0.0, 0.0}, 2.0);
    Cone cone({0.0, 0.0, 5.0}, {0.0, 0.0, 0.0}, M_PI / 4.0);

    if (doesIntersect(cube, cone)) {
        std::cout << "The cube and cone intersect." << std::endl;
    } else {
        std::cout << "The cube and cone do not intersect." << std::endl;
    }

    return 0;
}

