class MultiDimArray {
public:
    MultiDimArray(const std::vector<int>& dimensions) : dimensions_(dimensions) {
        if (dimensions.empty() || dimensions.size() > 10) {
            throw std::invalid_argument("Dimensions must be between 1 and 10.");
        }
        for (int dim : dimensions) {
            if (dim <= 0) {
                throw std::invalid_argument("All dimensions must be positive.");
            }
        }
        initializeArray();
    }

    int& operator()(const std::vector<int>& indices) {
        if (indices.size() != dimensions_.size()) {
            throw std::out_of_range("Indices size does not match dimensions.");
        }
        for (int i = 0; i < indices.size(); ++i) {
            if (indices[i] < 0 || indices[i] >= dimensions_[i]) {
                throw std::out_of_range("Index out of range.");
            }
        }
        return data_[linearIndex(indices)];
    }

    const int& operator()(const std::vector<int>& indices) const {
        if (indices.size() != dimensions_.size()) {
            throw std::out_of_range("Indices size does not match dimensions.");
        }
        for (int i = 0; i < indices.size(); ++i) {
            if (indices[i] < 0 || indices[i] >= dimensions_[i]) {
                throw std::out_of_range("Index out of range.");
            }
        }
        return data_[linearIndex(indices)];
    }

private:
    std::vector<int> dimensions_;
    std::vector<int> data_;
    std::vector<int> strides_;

    void initializeArray() {
        int totalSize = 1;
        for (int dim : dimensions_) {
            totalSize *= dim;
        }
        data_.resize(totalSize, 0);

        strides_.resize(dimensions_.size());
        strides_.back() = 1;
        for (int i = dimensions_.size() - 2; i >= 0; --i) {
            strides_[i] = strides_[i + 1] * dimensions_[i + 1];
        }
    }

    int linearIndex(const std::vector<int>& indices) const {
        int index = 0;
        for (size_t i = 0; i < indices.size(); ++i) {
            index += indices[i] * strides_[i];
        }
        return index;
    }
};

int main() {
    try {
        MultiDimArray array({3, 4, 2}); // 3x4x2 array

        // Access and modify elements
        array({1, 2, 1}) = 42;
        std::cout << "Element at (1, 2, 1): " << array({1, 2, 1}) << std::endl;

        // Out-of-bounds access (should throw an exception)
        array({3, 2, 1});
    } catch (const std::exception& e) {
        std::cerr << "Error: " << e.what() << std::endl;
    }

    return 0;
}

