class User {
public:
    std::string id;
    std::string name;
    int age;

    std::string serialize() const {
        return id + "|" + name + "|" + std::to_string(age);
    }

    static User deserialize(const std::string& data) {
        User user;
        size_t pos1 = data.find('|');
        size_t pos2 = data.find('|', pos1 + 1);
        user.id = data.substr(0, pos1);
        user.name = data.substr(pos1 + 1, pos2 - pos1 - 1);
        user.age = std::stoi(data.substr(pos2 + 1));
        return user;
    }
};

class UserRepository {
private:
    rocksdb::DB* db;
    rocksdb::Options options;

public:
    UserRepository(const std::string& db_path) {
        options.create_if_missing = true;
        rocksdb::Status status = rocksdb::DB::Open(options, db_path, &db);
        if (!status.ok()) {
            std::cerr << "Error opening database: " << status.ToString() << std::endl;
        }
    }

    ~UserRepository() {
        delete db;
    }

    rocksdb::Status insert(const User& user) {
        return db->Put(rocksdb::WriteOptions(), user.id, user.serialize());
    }

    rocksdb::Status update(const User& user) {
        return db->Put(rocksdb::WriteOptions(), user.id, user.serialize());
    }

    rocksdb::Status remove(const std::string& id) {
        return db->Delete(rocksdb::WriteOptions(), id);
    }

    rocksdb::Status get(const std::string& id, User& user) {
        std::string value;
