struct Vector3 {
    float x, y, z;

    Vector3(float _x = 0.0f, float _y = 0.0f, float _z = 0.0f)
        : x(_x), y(_y), z(_z) { }

    // Normalize the vector
    Vector3& normalize() {
        float magnitude = std::sqrt(x * x + y * y + z * z);
        x /= magnitude;
        y /= magnitude;
        z /= magnitude;
        return *this;
    }

    // Multiply the vector by a scalar value
    Vector3 operator*(float scalar) const {
        return Vector3(x * scalar, y * scalar, z * scalar);
    }

    // Add two vectors together
    Vector3 operator+(const Vector3& other) const {
        return Vector3(x + other.x, y + other.y, z + other.z);
    }

    // Subtract a vector from another vector
    Vector3 operator-(const Vector3& other) const {
        return Vector3(x - other.x, y - other.y, z - other.z);
    }

    // Dot product of two vectors
    float dot(const Vector3& other) const {
        return x * other.x + y * other.y + z * other.z;
    }
};

// Function to transform a vector
Vector3 tFormVector(const Vector3& vector, const Vector3& pivotRotation) {
    float xRadians = pivotRotation.x * (3.14159265359f / 180.0f);
    float yRadians = pivotRotation.y * (3.14159265359f / 180.0f);
    float zRadians = pivotRotation.z * (3.14159265359f / 180.0f);

    float sinX = std::sin(xRadians);
    float cosX = std::cos(xRadians);
    float sinY = std::sin(yRadians);
    float cosY = std::cos(yRadians);
    float sinZ = std::sin(zRadians);
    float cosZ = std::cos(zRadians);

    Vector3 transformedVector;

    transformedVector.x = vector.x * (cosY * cosZ) + vector.y * (sinX * sinY * cosZ - cosX * sinZ) + vector.z * (cosX * sinY * cosZ + sinX * sinZ);
    transformedVector.y = vector.x * (cosY * sinZ) + vector.y * (sinX * sinY * sinZ + cosX * cosZ) + vector.z * (cosX * sinY * sinZ - sinX * cosZ);
    transformedVector.z = vector.x * (-sinY) + vector.y * (sinX * cosY) + vector.z * (cosX * cosY);

    return transformedVector;
}

int main() {
    Vector3 p(0, 0, 0);
    Vector3 pivotRotation(-5, -15, 25);

    Vector3 inputVector(0, 0, 1);
    Vector3 transformedVector = tFormVector(inputVector, pivotRotation);

    std::cout << "'One step forward' vector is (" << transformedVector.x << ", "
              << transformedVector.y << ", " << transformedVector.z << ")\n";

    return 0;
}

