// Function to check if a number is prime
bool isPrime(int n) {
    if (n <= 1) return false;
    if (n <= 3) return true;
    if (n % 2 == 0 || n % 3 == 0) return false;
    for (int i = 5; i * i <= n; i += 6) {
        if (n % i == 0 || n % (i + 2) == 0) return false;
    }
    return true;
}

// Function to calculate the sum of digits of a number
int sumOfDigits(int n) {
    int sum = 0;
    while (n > 0) {
        sum += n % 10;
        n /= 10;
    }
    return sum;
}

// Function to find the largest prime number in the vector and return the sum of its digits
int largestPrimeSum(std::vector<int> &vec) {
    int maxPrime = -1;
    for (int num : vec) {
        if (isPrime(num) && num > maxPrime) {
            maxPrime = num;
        }
    }
    return maxPrime != -1 ? sumOfDigits(maxPrime) : 0;
}

