typedef std::array<uint8_t, 3> Vec3B;
typedef std::array<int32_t, 3> Vec3I;

Vec3B v3bSpread(Vec3B const& source, Vec3B dest, int32_t drop) {
    // Convert to __m128i (128-bit integer vector)
    __m128i intSource = _mm_setr_epi32(source[0], source[1], source[2], 0);
    __m128i intDest = _mm_setr_epi32(dest[0], dest[1], dest[2], 0);
    __m128i intDrop = _mm_set1_epi32(drop);

    // Check the condition
    __m128i cond1 = _mm_add_epi32(intDest, intDrop);
    __m128i cond2 = _mm_cmpgt_epi32(intSource, cond1);
    int condMask = _mm_movemask_epi8(cond2);

    if (condMask == 0) {
        return dest;
    } else {
        // Compute the maximum
        __m128i maxVal = _mm_max_epi32(intSource, _mm_shuffle_epi32(intSource, _MM_SHUFFLE(2, 2, 2, 1)));
        maxVal = _mm_max_epi32(maxVal, _mm_shuffle_epi32(maxVal, _MM_SHUFFLE(2, 2, 2, 0)));

        // Compute the result
        __m128i result = _mm_sub_epi32(intSource, _mm_div_epi32(_mm_mullo_epi32(intSource, intDrop), maxVal));
        result = _mm_max_epi32(result, intDest);

        // Extract the result
        int32_t resultArray[4];
        _mm_storeu_si128((__m128i*)resultArray, result);

        return {static_cast<uint8_t>(resultArray[0]), static_cast<uint8_t>(resultArray[1]), static_cast<uint8_t>(resultArray[2])};
    }
}

#include <iostream>
#include <vector>
#include <string>
#include <algorithm>

using namespace std;

pair<int, pair<int, int>> findLongestCommonSubstring(const string& s1, const string& s2) {
    int n = s1.length();
    int m = s2.length();

    // Create a 2D DP table
    vector<vector<int>> dp(n + 1, vector<int>(m + 1, 0));

    // Variables to store the length of the longest common substring and its starting indices
    int maxLength = 0;
    int endIdxS1 = -1;
    int endIdxS2 = -1;

    // Fill the DP table
    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= m; ++j) {
            if (s1[i - 1] == s2[j - 1]) {
                dp[i][j] = dp[i - 1][j - 1] + 1;
                if (dp[i][j] > maxLength) {
                    maxLength = dp[i][j];
                    endIdxS1 = i - 1;
                    endIdxS2 = j - 1;
                }
            } else {
                dp[i][j] = 0;
            }
        }
    }

    // Calculate the starting indices
    int startIdxS1 = endIdxS1 - maxLength + 1;
    int startIdxS2 = endIdxS2 - maxLength + 1;

    return {maxLength, {startIdxS1, startIdxS2}};
}

int main() {
    string s1, s2;
    cout << "Enter the first string: ";
    cin >> s1;
    cout << "Enter the second string: ";
    cin >> s2;

    auto result = findLongestCommonSubstring(s1, s2);
    int maxLength = result.first;
    int startIdxS1 = result.second.first;
    int startIdxS2 = result.second.second;

    if (maxLength > 0) {
        cout << "Longest common substring: " << s1.substr(startIdxS1, maxLength) << endl;
        cout << "Starting index in the first string: " << startIdxS1 << endl;
        cout << "Starting index in the second string: " << startIdxS2 << endl;
    } else {
        cout << "No common substring found." << endl;
    }

    return 0;
}

