// Function to find the export address table
PIMAGE_EXPORT_DIRECTORY GetExportDirectory(HMODULE hModule) {
    PIMAGE_DOS_HEADER pDosHeader = (PIMAGE_DOS_HEADER)hModule;
    PIMAGE_NT_HEADERS pNtHeaders = (PIMAGE_NT_HEADERS)((BYTE*)hModule + pDosHeader->e_lfanew);
    PIMAGE_EXPORT_DIRECTORY pExportDir = (PIMAGE_EXPORT_DIRECTORY)((BYTE*)hModule + pNtHeaders->OptionalHeader.DataDirectory[IMAGE_DIRECTORY_ENTRY_EXPORT].VirtualAddress);
    return pExportDir;
}

// Function to hook an exported function by name
bool HookExportedFunction(HMODULE hModule, const char* functionName, void* hookFunction) {
    PIMAGE_EXPORT_DIRECTORY pExportDir = GetExportDirectory(hModule);
    if (!pExportDir) {
        return false;
    }

    DWORD* pAddressTable = (DWORD*)((BYTE*)hModule + pExportDir->AddressOfFunctions);
    DWORD* pNameTable = (DWORD*)((BYTE*)hModule + pExportDir->AddressOfNames);
    WORD* pOrdinalTable = (WORD*)((BYTE*)hModule + pExportDir->AddressOfNameOrdinals);

    for (unsigned int i = 0; i < pExportDir->NumberOfNames; ++i) {
        const char* pName = (const char*)hModule + pNameTable[i];
        if (strcmp(pName, functionName) == 0) {
            DWORD oldProtect;
            VirtualProtect((LPVOID)(hModule + pAddressTable[pOrdinalTable[i]]), sizeof(DWORD), PAGE_EXECUTE_READWRITE, &oldProtect);
            DWORD* pFunctionAddress = (DWORD*)(hModule + pAddressTable[pOrdinalTable[i]]);
            *pFunctionAddress = (DWORD)hookFunction;
            VirtualProtect((LPVOID)(hModule + pAddressTable[pOrdinalTable[i]]), sizeof(DWORD), oldProtect, &oldProtect);
            return true;
        }
    }

    return false;
}

int main() {
    HMODULE hModule = GetModuleHandleA("YourDLL.dll"); // Replace with your DLL name
    if (!hModule) {
        printf("Failed to get module handle.\n");
        return 1;
    }

    if (HookExportedFunction(hModule, "OriginalFunction", HookFunction)) {
        printf("Hooked 'OriginalFunction' successfully.\n");
    } else {
        printf("Failed to hook 'OriginalFunction'.\n");
        return 1;
    }

    // Call the original function to test the hook
    OriginalFunction();

    return 0;
}

