void swap(int* m, int* n) {
    int t = *m;
    *m = *n;
    *n = t;
}

void Descend(int &a, int &b, int &c) {
    if (a < b) {
        swap(&a, &b);
    }
    if (a < c) {
        swap(&a, &c);
    }
    if (b < c) {
        swap(&b, &c);
    }
}

