#include <stdio.h>
#include <stdlib.h>

typedef struct {
    int u;
    int v;
    int weight;
} Edge;

typedef struct {
    int n;
    int **edges;
} MGraph;

int cmp(const void *a, const void *b) {
    return ((Edge *)a)->weight - ((Edge *)b)->weight;
}

void Kruskal(MGraph g) {
    int i, j, k;
    int edge_count = 0;
    int *visited = (int *)malloc(g.n * sizeof(int));
    for (i = 0; i < g.n; i++) {
        visited[i] = 0;
    }

    Edge *edges = (Edge *)malloc((g.n * (g.n - 1) / 2) * sizeof(Edge));
    k = 0;
    for (i = 0; i < g.n; i++) {
        for (j = i + 1; j < g.n; j++) {
            if (g.edges[i][j] != 32767) {
                edges[k].u = i;
                edges[k].v = j;
                edges[k].weight = g.edges[i][j];
                k++;
            }
        }
    }
    qsort(edges, g.n * (g.n - 1) / 2, sizeof(Edge), cmp);

    while (edge_count < g.n - 1) {
        int min = 32767;
        int u, v;
        for (i = 0; i < g.n * (g.n - 1) / 2; i++) {
            if (!visited[edges[i].u] || !visited[edges[i].v]) {
                if (edges[i].weight < min) {
                    min = edges[i].weight;
                    u = edges[i].u;
                    v = edges[i].v;
                }
            }
        }
        printf("(%d,%d):%d\n", u, v, min);
        visited[u] = 1;
        visited[v] = 1;
        edge_count++;
    }

    free(visited);
    free(edges);
}

int main() {
    int n, e;
    scanf("%d %d", &n, &e);
    MGraph g;
    g.n = n;
    g.edges = (int **)malloc(n * sizeof(int *));
    for (int i = 0; i < n; i++) {
        g.edges[i] = (int *)malloc(n * sizeof(int));
    }
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            scanf("%d", &g.edges[i][j]);
        }
    }
    printf("Krusal:\n");
    Kruskal(g);
    return 0;
}

