    };
}

std::string GetPerformanceCounterName() {
    LCID lcid = GetSystemDefaultUILanguage();
    char localeName[LOCALE_NAME_MAX_LENGTH];
    GetLocaleInfoA(lcid, LOCALE_SISO639LANGNAME, localeName, LOCALE_NAME_MAX_LENGTH);

    std::map<std::string, std::string> counterMap = GetPerformanceCounterMap();
    auto it = counterMap.find(localeName);
    if (it != counterMap.end()) {
        return it->second;
    }
    return "\\Processor(_Total)\\% Processor Time"; // Default to English
}

double GetProcessorLoad() {
    PDH_HQUERY hQuery;
    PDH_HCOUNTER hCounter;
    PDH_FMT_COUNTERVALUE pdhValue;

    if (PdhOpenQuery(NULL, NULL, &hQuery) != ERROR_SUCCESS) {
        return -1.0;
    }

    std::string counterPath = GetPerformanceCounterName();
    if (PdhAddCounter(hQuery, counterPath.c_str(), NULL, &hCounter) != ERROR_SUCCESS) {
        PdhCloseQuery(hQuery);
        return -1.0;
    }

    if (PdhCollectQueryData(hQuery) != ERROR_SUCCESS) {
        PdhCloseQuery(hQuery);
        return -1.0;
    }

    Sleep(1000); // Wait for data to be collected

    if (PdhCollectQueryData(hQuery) != ERROR_SUCCESS) {
        PdhCloseQuery(hQuery);
        return -1.0;
    }

    if (PdhGetFormattedCounterValue(hCounter, PDH_FMT_DOUBLE, NULL, &pdhValue) != ERROR_SUCCESS) {
        PdhCloseQuery(hQuery);
        return -1.0;
    }

    PdhCloseQuery(hQuery);

    return pdhValue.doubleValue;
}

int main() {
    double load = GetProcessorLoad();
    if (load != -1.0) {
        printf("Processor Load: %.2f%%\n", load);
    } else {
        printf("Failed to get processor load.\n");
    }
    return 0;
}

#include <iostream>
#include <fstream>
#include <string>
#include <vector>

std::vector<long> readCPUUsage() {
    std::ifstream file("/proc/stat");
    std::string line;
    std::getline(file, line);
    std::istringstream ss(line);
    std::vector<long> values;
    std::string tmp;
    ss >> tmp; // Skip the "cpu" label
    while (ss >> tmp) {
        values.push_back(std::stol(tmp));
    }
    return values;
}

double calculateCPUUsage(const std::vector<long>& prev, const std::vector<long>& curr) {
    long prevTotal = 0, currTotal = 0;
    for (int i = 0; i < prev.size(); ++i) {
        prevTotal += prev[i];
        currTotal += curr[i];
    }
    long totalDiff = currTotal - prevTotal;

    long prevIdle = prev[3];
    long currIdle = curr[3];
    long idleDiff = currIdle - prevIdle;

    return (1.0 - (idleDiff / static_cast<double>(totalDiff))) * 100.0;
}

void printCPUUsage() {
    auto prev = readCPUUsage();
    std::this_thread::sleep_for(std::chrono::seconds(1));
    auto curr = readCPUUsage();
    double usage = calculateCPUUsage(prev, curr);
    std::cout << "CPU Usage: " << usage << "%" << std::endl;
}

