#include <iostream>
#include <vector>
#include <cstdlib>
#include <ctime>

using namespace std;

const int GRID_SIZE = 5;
const int NUM_MINES = 5;

class Minesweeper {
public:
    Minesweeper() {
        srand(time(0));
        placeMines();
        calculateNumbers();
    }

    void play() {
        while (true) {
            printBoard();
            int row, col;
            cout << "Enter the row and column to reveal (0-4): ";
            cin >> row >> col;

            if (row < 0 || row >= GRID_SIZE || col < 0 || col >= GRID_SIZE) {
                cout << "Invalid input. Try again." << endl;
                continue;
            }

            if (board[row][col] == -1) {
                cout << "Game Over! You hit a mine." << endl;
                revealBoard();
                break;
            }

            if (board[row][col] == 0) {
                revealEmptyCells(row, col);
            } else {
                revealed[row][col] = true;
            }

            if (checkWin()) {
                cout << "Congratulations! You won the game." << endl;
                revealBoard();
                break;
            }
        }
    }

private:
    vector<vector<int>> board;
    vector<vector<bool>> revealed;

    void placeMines() {
        board.resize(GRID_SIZE, vector<int>(GRID_SIZE, 0));
        revealed.resize(GRID_SIZE, vector<bool>(GRID_SIZE, false));

        int minesPlaced = 0;
        while (minesPlaced < NUM_MINES) {
            int row = rand() % GRID_SIZE;
            int col = rand() % GRID_SIZE;
            if (board[row][col] != -1) {
                board[row][col] = -1;
                minesPlaced++;
            }
        }
    }

    void calculateNumbers() {
        for (int row = 0; row < GRID_SIZE; row++) {
            for (int col = 0; col < GRID_SIZE; col++) {
                if (board[row][col] == -1) {
                    continue;
                }
                int count = 0;
                for (int dr = -1; dr <= 1; dr++) {
                    for (int dc = -1; dc <= 1; dc++) {
                        int r = row + dr, c = col + dc;
                        if (r >= 0 && r < GRID_SIZE && c >= 0 && c < GRID_SIZE && board[r][c] == -1) {
                            count++;
                        }
                    }
                }
                board[row][col] = count;
            }
        }
    }

    void revealEmptyCells(int row, int col) {
        if (row < 0 || row >= GRID_SIZE || col < 0 || col >= GRID_SIZE || revealed[row][col]) {
            return;
        }

        revealed[row][col] = true;
        if (board[row][col] == 0) {
            for (int dr = -1; dr <= 1; dr++) {
                for (int dc = -1; dc <= 1; dc++) {
                    revealEmptyCells(row + dr, col + dc);
                }
            }
        }
    }

    void printBoard() {
        for (int row = 0; row < GRID_SIZE; row++) {
            for (int col = 0; col < GRID_SIZE; col++) {
                if (revealed[row][col]) {
                    if (board[row][col] == -1) {
                        cout << "M ";
                    } else {
                        cout << board[row][col] << " ";
                    }
                } else {
                    cout << "# ";
                }
            }
            cout << endl;
        }
    }

    void revealBoard() {
        for (int row = 0; row < GRID_SIZE; row++) {
            for (int col = 0; col < GRID_SIZE; col++) {
                if (board[row][col] == -1) {
                    cout << "M ";
                } else {
                    cout << board[row][col] << " ";
                }
            }
            cout << endl;
        }
    }

    bool checkWin() {
        for (int row = 0; row < GRID_SIZE; row++) {
            for (int col = 0; col < GRID_SIZE; col++) {
                if (board[row][col] != -1 && !revealed[row][col]) {
                    return false;
                }
            }
        }
        return true;
    }
};

int main() {
    Minesweeper game;
    game.play();
    return 0;
}

