class IRNode {
public:
    virtual std::string generateAssembly() const = 0;
};

class IfNode : public IRNode {
private:
    IRNode* condition;
    IRNode* trueBlock;
    IRNode* falseBlock;
    std::string label;

public:
    IfNode(IRNode* cond, IRNode* trueBlock, IRNode* falseBlock, std::string label)
        : condition(cond), trueBlock(trueBlock), falseBlock(falseBlock), label(label) {}

    std::string generateAssembly() const override {
        std::string assembly = "";

        assembly += condition->generateAssembly();
        assembly += "jmp .false" + label + "\n";
        assembly += ".true" + label + ":\n";
        assembly += trueBlock->generateAssembly();
        assembly += "jmp .end" + label + "\n";
        assembly += ".false" + label + ":\n";
        assembly += falseBlock->generateAssembly();
        assembly += ".end" + label + ":\n";

        return assembly;
    }
};

class ComparisonNode : public IRNode {
private:
    std::string op;
    IRNode* left;
    IRNode* right;

public:
    ComparisonNode(std::string op, IRNode* left, IRNode* right)
        : op(op), left(left), right(right) {}

    std::string generateAssembly() const override {
        std::string assembly = "";

        assembly += left->generateAssembly();
        assembly += right->generateAssembly();
        assembly += "cmp %eax, %ebx\n";
        assembly += "je .true" + label + "\n";
        assembly += "jmp .false" + label + "\n";

        return assembly;
    }
};

// Example usage
int main() {
    IRNode* condition = new ComparisonNode("==", new ConstantNode(1), new ConstantNode(1));
    IRNode* trueBlock = new BlockNode({ new InstructionNode("mov $1, %eax") });
    IRNode* falseBlock = new BlockNode({ new InstructionNode("mov $0, %eax") });

    IfNode* ifNode = new IfNode(condition, trueBlock, falseBlock, "if1");

    std::string assembly = ifNode->generateAssembly();
    std::cout << assembly << std::endl;

    delete condition;
    delete trueBlock;
    delete falseBlock;
    delete ifNode;

    return 0;
}

