// Function to find the length of the longest increasing subsequence
int lengthOfLIS(vector<int>& nums) {
    if (nums.empty()) return 0;

    vector<int> tails;
    for (int num : nums) {
        // Use binary search to find the insertion point of num in tails
        auto it = lower_bound(tails.begin(), tails.end(), num);
        if (it == tails.end()) {
            // If num is greater than all elements in tails, append it
            tails.push_back(num);
        } else {
            // Otherwise, replace the element at the found position
            *it = num;
        }
    }
    return tails.size();
}

// Function to reconstruct the longest increasing subsequence
vector<int> longestIncreasingSubsequence(vector<int>& nums) {
    if (nums.empty()) return {};

    vector<int> tails;
    vector<int> indices(nums.size(), -1);
    vector<int> prev(nums.size(), -1);

    for (int i = 0; i < nums.size(); ++i) {
        auto it = lower_bound(tails.begin(), tails.end(), nums[i]);
        int idx = it - tails.begin();
        if (it == tails.end()) {
            tails.push_back(nums[i]);
        } else {
            *it = nums[i];
        }
        indices[idx] = i;
        if (idx > 0) {
            prev[i] = indices[idx - 1];
        }
    }

    vector<int> lis;
    for (int i = indices.back(); i >= 0; i = prev[i]) {
        lis.push_back(nums[i]);
    }
    reverse(lis.begin(), lis.end());
    return lis;
}

int main() {
    vector<int> nums = {10, 9, 2, 5, 3, 7, 101, 18};

    int length = lengthOfLIS(nums);
    cout << "Length of the longest increasing subsequence: " << length << endl;

    vector<int> lis = longestIncreasingSubsequence(nums);
    cout << "The longest increasing subsequence: ";
    for (int num : lis) {
        cout << num << " ";
    }
    cout << endl;

    return 0;
}

