#include <xmmintrin.h>

inline __m128 sse_dot4(__m128 a, __m128 b)
{
    const __m128 mult = _mm_mul_ps(a, b);

    // Sum the first and second elements
    const __m128 sum1 = _mm_add_ss(mult, _mm_shuffle_ps(mult, mult, _MM_SHUFFLE(0, 0, 0, 1)));

    // Sum the third and fourth elements
    const __m128 sum2 = _mm_add_ss(mult, _mm_shuffle_ps(mult, mult, _MM_SHUFFLE(0, 0, 0, 2)));

    // Sum the results of the two previous sums
    const __m128 sum3 = _mm_add_ss(sum1, _mm_shuffle_ps(sum2, sum2, _MM_SHUFFLE(0, 0, 0, 0)));

    return sum3;
}

#include <QCoreApplication>
