float Polynomial(int n, int a[], float x0) 
{   
    int i;
    float P = 0;

    if(n == 0)
    {
        P = a[0];
    }
    else
    {
        P = a[0];
        for(i = 1; i <= n; i++)
        {
            P += a[i] * x0;
            x0 *= x0;
        }
    }

    return P;  // Return the calculated value of the polynomial P
}

