DWORD Rva2Offset(DWORD rva, PIMAGE_SECTION_HEADER psh, PIMAGE_NT_HEADERS pnt)
{
    for (int i = 0; i < pnt->FileHeader.NumberOfSections; i++) {
        if (rva >= psh[i].VirtualAddress && rva < psh[i].VirtualAddress + psh[i].Misc.VirtualSize) {
            return (rva - psh[i].VirtualAddress) + psh[i].PointerToRawData;
        }
    }
    return 0;
}

void ResolveImports(LPVOID base, PIMAGE_NT_HEADERS pnt)
{
    PIMAGE_IMPORT_DESCRIPTOR pImportDesc = (PIMAGE_IMPORT_DESCRIPTOR)((char*)base + pnt->OptionalHeader.DataDirectory[IMAGE_DIRECTORY_ENTRY_IMPORT].VirtualAddress);

    while (pImportDesc->Name) {
        char* szDllName = (char*)base + pImportDesc->Name;
        HMODULE hModule = LoadLibraryA(szDllName);
        if (hModule) {
            PIMAGE_THUNK_DATA pThunk = (PIMAGE_THUNK_DATA)((char*)base + pImportDesc->OriginalFirstThunk);
            PIMAGE_THUNK_DATA pFunc = (PIMAGE_THUNK_DATA)((char*)base + pImportDesc->FirstThunk);

            while (pThunk->u1.Function) {
                if (IMAGE_SNAP_BY_ORDINAL(pThunk->u1.Ordinal)) {
                    pFunc->u1.Function = (ULONG_PTR)GetProcAddress(hModule, (LPCSTR)IMAGE_ORDINAL(pThunk->u1.Ordinal));
                } else {
                    PIMAGE_IMPORT_BY_NAME pImportByName = (PIMAGE_IMPORT_BY_NAME)((char*)base + pThunk->u1.AddressOfData);
                    pFunc->u1.Function = (ULONG_PTR)GetProcAddress(hModule, (char*)pImportByName->Name);
                }
                pThunk++;
                pFunc++;
            }
        }
        pImportDesc++;
    }
}

void ApplyRelocations(LPVOID base, PIMAGE_NT_HEADERS pnt, DWORD delta)
{
    PIMAGE_BASE_RELOCATION pBaseReloc = (PIMAGE_BASE_RELOCATION)((char*)base + pnt->OptionalHeader.DataDirectory[IMAGE_DIRECTORY_ENTRY_BASERELOC].VirtualAddress);

    while (pBaseReloc->VirtualAddress) {
        PWORD relocs = (PWORD)((char*)pBaseReloc + sizeof(IMAGE_BASE_RELOCATION));
        DWORD entries = (pBaseReloc->SizeOfBlock - sizeof(IMAGE_BASE_RELOCATION)) / sizeof(WORD);

        for (DWORD i = 0; i < entries; i++) {
            DWORD rva = pBaseReloc->VirtualAddress + (relocs[i] & 0xFFF);
            DWORD type = (relocs[i] >> 12);

            switch (type) {
                case IMAGE_REL_BASED_HIGHLOW:
                    *(PDWORD)((char*)base + rva) += delta;
                    break;
            }
        }

        pBaseReloc = (PIMAGE_BASE_RELOCATION)((char*)pBaseReloc + pBaseReloc->SizeOfBlock);
    }
}

int main(int argc, char* argv[])
{
    if (argc < 2) {
        std::cerr << "Usage: " << argv[0] << " <path_to_executable>" << std::endl;
        return 1;
    }

    std::ifstream file(argv[1], std::ios::binary | std::ios::ate);
    if (!file) {
        std::cerr << "Failed to open file: " << argv[1] << std::endl;
        return 1;
    }

    std::streamsize size = file.tellg();
    file.seekg(0, std::ios::beg);
    std::vector<BYTE> buffer(size);
    if (!file.read((char*)buffer.data(), size)) {
        std::cerr << "Failed to read file: " << argv[1] << std::endl;
        return 1;
    }

    PIMAGE_DOS_HEADER dosHeader = (PIMAGE_DOS_HEADER)buffer.data();
    PIMAGE_NT_HEADERS ntHeaders = (PIMAGE_NT_HEADERS)((char*)buffer.data() + dosHeader->e_lfanew);

    if (dosHeader->e_magic != IMAGE_DOS_SIGNATURE || ntHeaders->Signature != IMAGE_NT_SIGNATURE) {
        std::cerr << "Invalid PE file" << std::endl;
        return 1;
    }

    SIZE_T imageSize = ntHeaders->OptionalHeader.SizeOfImage;
    LPVOID base = VirtualAlloc(nullptr, imageSize, MEM_COMMIT | MEM_RESERVE, PAGE_EXECUTE_READWRITE);
    if (!base) {
        std::cerr << "Failed to allocate memory" << std::endl;
        return 1;
    }

    memcpy(base, buffer.data(), ntHeaders->OptionalHeader.SizeOfHeaders);

    PIMAGE_SECTION_HEADER sectionHeader = (PIMAGE_SECTION_HEADER)((char*)ntHeaders + sizeof(IMAGE_NT_HEADERS));
    for (int i = 0; i < ntHeaders->FileHeader.NumberOfSections; i++) {
        memcpy((char*)base + sectionHeader[i].VirtualAddress, (char*)buffer.data() + sectionHeader[i].PointerToRawData, sectionHeader[i].SizeOfRawData);
    }

    ApplyRelocations(base, ntHeaders, (DWORD)base - ntHeaders->OptionalHeader.ImageBase);
    ResolveImports(base, ntHeaders);

    typedef void (*EntryPointFunc)(void);
    EntryPointFunc entryPoint = (EntryPointFunc)((char*)base + ntHeaders->OptionalHeader.AddressOfEntryPoint);

    // Execute the entry point
    entryPoint();

    VirtualFree(base, 0, MEM_RELEASE);

    return 0;
}

BOOL CNamedPipe::SendMessage(CString message)
{
    DWORD dwSent;

    if (m_hOutPipeHandle == NULL || m_hOutPipeHandle == INVALID_HANDLE_VALUE)
    {
        return FALSE;
    }
    else
    {
        BOOL bOK = WriteFile(m_hOutPipeHandle, message, message.GetLength() + 1, &dwSent, NULL);
        if (!bOK || (message.GetLength() + 1) != dwSent)
        {
            return FALSE;
        }

        // Flush the buffer to ensure the data is sent
        if (!FlushFileBuffers(m_hOutPipeHandle))
        {
            return FALSE;
        }

        return TRUE;
    }
}

