#include <cuda_runtime.h>
#include <iostream>
#include <cmath>

#define BLOCK_SIZE 16

__global__ void computeEuclideanDistance(float *A, float *B, float *C, int n, int m) {
    __shared__ float B_shared[BLOCK_SIZE * 128];

    int rowA = blockIdx.x;
    int colB_start = blockIdx.y * BLOCK_SIZE + threadIdx.x;
    int colB_end = colB_start + BLOCK_SIZE;

    // Load B into shared memory
    for (int i = colB_start; i < colB_end && i < m; i++) {
        for (int j = 0; j < 128; j++) {
            B_shared[(i - colB_start) * 128 + j] = B[i * 128 + j];
        }
    }
    __syncthreads();

    // Compute distances
    for (int j = colB_start; j < colB_end && j < m; j++) {
        float sum = 0.0f;
        for (int k = 0; k < 128; k++) {
            float diff = A[rowA * 128 + k] - B_shared[(j - colB_start) * 128 + k];
            sum += diff * diff;
        }
        C[rowA * m + j] = sqrtf(sum);
    }
}

int main() {
    int n = 1000;
    int m = 1000;
    size_t sizeA = n * 128 * sizeof(float);
    size_t sizeB = m * 128 * sizeof(float);
    size_t sizeC = n * m * sizeof(float);

    float *h_A = new float[n * 128];
    float *h_B = new float[m * 128];
    float *h_C = new float[n * m];

    // Initialize A and B (for example, with random values)
    for (int i = 0; i < n * 128; i++) {
        h_A[i] = static_cast<float>(rand()) / RAND_MAX;
    }
    for (int i = 0; i < m * 128; i++) {
        h_B[i] = static_cast<float>(rand()) / RAND_MAX;
    }

    float *d_A, *d_B, *d_C;
    cudaMalloc(&d_A, sizeA);
    cudaMalloc(&d_B, sizeB);
    cudaMalloc(&d_C, sizeC);

    cudaMemcpy(d_A, h_A, sizeA, cudaMemcpyHostToDevice);
    cudaMemcpy(d_B, h_B, sizeB, cudaMemcpyHostToDevice);

    dim3 threadsPerBlock(BLOCK_SIZE, 1);
    dim3 blocksPerGrid((m + BLOCK_SIZE - 1) / BLOCK_SIZE, n);

    computeEuclideanDistance<<<blocksPerGrid, threadsPerBlock>>>(d_A, d_B, d_C, n, m);

    cudaMemcpy(h_C, d_C, sizeC, cudaMemcpyDeviceToHost);

    // Clean up
    cudaFree(d_A);
    cudaFree(d_B);
    cudaFree(d_C);
    delete[] h_A;
    delete[] h_B;
    delete[] h_C;

    return 0;
}

