void permute_8bit_blocks(const uint8_t* in, uint8_t* out, const uint8_t* perm) {
    __m256i in_vec = _mm256_loadu_si256(reinterpret_cast<const __m256i*>(in));
    __m256i perm_vec = _mm256_loadu_si256(reinterpret_cast<const __m256i*>(perm));
    __m256i out_vec = _mm256_shuffle_epi8(in_vec, perm_vec);
    _mm256_storeu_si256(reinterpret_cast<__m256i*>(out), out_vec);
}

