std::string compressCharArray(const char* array, int size) {
    std::string compressed;
    for (int i = 0; i < size; ++i) {
        int asciiValue = static_cast<int>(array[i]);
        std::string binaryRepresentation;
        while (asciiValue != 0) {
            binaryRepresentation.insert(binaryRepresentation.begin(), (asciiValue % 2 == 1) ? '1' : '0');
            asciiValue /= 2;
        }
        while (binaryRepresentation.length() < 8) {
            binaryRepresentation.insert(binaryRepresentation.begin(), '0');
        }
        compressed += binaryRepresentation;
    }
    return compressed;
}

