    }
}

int main() {
    DWORD pid = 0;
    cout << "PID: ";
    cin >> dec >> pid;
    HANDLE hProcess = OpenProcess(PROCESS_ALL_ACCESS, FALSE, pid);
    if (!hProcess) {
        cout << "OpenProcess failed GLE = " << dec << GetLastError() << endl;
        return EXIT_FAILURE;
    }

    void* buf = VirtualAllocEx(hProcess, NULL, 4096, MEM_COMMIT, PAGE_EXECUTE_READWRITE);
    if (!buf) {
        cout << "VirtualAllocEx failed GLE = " << dec << GetLastError() << endl;
        return EXIT_FAILURE;
    }

    SIZE_T size = (SIZE_T)((char*)&MakeABeep - (char*)&MakeABeep + 1);
    BOOL wpmStatus = WriteProcessMemory(hProcess, buf, (void*)&MakeABeep, size, NULL);
    if (!wpmStatus) {
        cout << "WriteProcessMemory failed GLE = " << dec << GetLastError() << endl;
        return EXIT_FAILURE;
    }

    HANDLE hThread = CreateRemoteThread(hProcess, NULL, 0, (LPTHREAD_START_ROUTINE)buf, NULL, 0, NULL);
    if (!hThread) {
        cout << "CreateRemoteThread failed GLE = " << dec << GetLastError() << endl;
        return EXIT_FAILURE;
