// Function to perform binary search to find the first occurrence of the target
int findFirstOccurrence(const std::vector<int>& arr, int target) {
    int left = 0;
    int right = arr.size() - 1;
    int result = -1;
    while (left <= right) {
        int mid = left + (right - left) / 2;
        if (arr[mid] == target) {
            result = mid;
            right = mid - 1; // Continue to search in the left half
        } else if (arr[mid] < target) {
            left = mid + 1;
        } else {
            right = mid - 1;
        }
    }
    return result;
}

// Function to perform binary search to find the last occurrence of the target
int findLastOccurrence(const std::vector<int>& arr, int target) {
    int left = 0;
    int right = arr.size() - 1;
    int result = -1;
    while (left <= right) {
        int mid = left + (right - left) / 2;
        if (arr[mid] == target) {
            result = mid;
            left = mid + 1; // Continue to search in the right half
        } else if (arr[mid] < target) {
            left = mid + 1;
        } else {
            right = mid - 1;
        }
    }
    return result;
}

// Function to count the number of occurrences of the target in the array
int countOccurrences(const std::vector<int>& arr, int target) {
    int first = findFirstOccurrence(arr, target);
    if (first == -1) {
        return 0; // Target is not present in the array
    }
    int last = findLastOccurrence(arr, target);
    return last - first + 1;
}

int main() {
    std::vector<int> arr = {1, 2, 2, 2, 3, 4, 5};
    int target = 2;
    int count = countOccurrences(arr, target);
    std::cout << "Number of occurrences of " << target << ": " << count << std::endl;
    return 0;
}

#include <iostream>
#include <cmath> // for std::sqrt

class Point3D {
public:
    // Constructor
    Point3D(double x = 0.0, double y = 0.0, double z = 0.0) : x(x), y(y), z(z) {}

    // Getters and Setters
    double getX() const { return x; }
    double getY() const { return y; }
    double getZ() const { return z; }

    void setX(double x) { this->x = x; }
    void setY(double y) { this->y = y; }
    void setZ(double z) { this->z = z; }

    // Method to calculate the distance between two points
    double distanceTo(const Point3D& other) const {
        double dx = x - other.x;
        double dy = y - other.y;
        double dz = z - other.z;
        return std::sqrt(dx * dx + dy * dy + dz * dz);
    }

private:
    double x, y, z; // Coordinates of the point
};

int main() {
    // Create two points
    Point3D point1(1.0, 2.0, 3.0);
    Point3D point2(4.0, 5.0, 6.0);

    // Calculate the distance between the two points
    double distance = point1.distanceTo(point2);

    // Output the result
    std::cout << "The distance between the points is: " << distance << std::endl;

    return 0;
}

#include <iostream>
#include <thread>
#include <chrono>
#include <cstdio>

extern "C" {
#include <libavformat/avformat.h>
#include <libavutil/opt.h>
#include <libavutil/time.h>
}

char recv_packet(AVFormatContext *inputFormatContext, AVPacket *pkt)
{
    return av_read_frame(inputFormatContext, pkt) >= 0;
}

int main(int argc, char *argv[])
{
    if (argc != 4)
    {
        std::cerr << "Usage: " << argv[0] << " <input.mp4> <host> <port>" << std::endl;
        return 1;
    }

    const char *inputFilename = argv[1];
    const char *host = argv[2];
    int port = std::stoi(argv[3]);

    av_register_all();
    avformat_network_init();

    AVFormatContext *inputFormatContext = nullptr;
    if (avformat_open_input(&inputFormatContext, inputFilename, nullptr, nullptr) < 0)
    {
        std::cerr << "Could not open input file: " << inputFilename << std::endl;
        return 2;
    }

    if (avformat_find_stream_info(inputFormatContext, nullptr) < 0)
    {
        std::cerr << "Could not find stream info" << std::endl;
        return 3;
    }

    av_dump_format(inputFormatContext, 0, inputFilename, 0);

    int videoStreamIndex = -1;
    int audioStreamIndex = -1;

    for (unsigned int i = 0; i < inputFormatContext->nb_streams; i++)
    {
        if (inputFormatContext->streams[i]->codecpar->codec_type == AVMEDIA_TYPE_VIDEO)
        {
            videoStreamIndex = i;
        }
        else if (inputFormatContext->streams[i]->codecpar->codec_type == AVMEDIA_TYPE_AUDIO)
        {
            audioStreamIndex = i;
        }
    }

    if (videoStreamIndex == -1 || audioStreamIndex == -1)
    {
        std::cerr << "Could not find video and/or audio stream" << std::endl;
        return 4;
    }

    // Set up output.
    AVFormatContext *outputFormatContext = nullptr;
    if (avformat_alloc_output_context2(&outputFormatContext, nullptr, "rtp", nullptr) < 0)
    {
        std::cerr << "Could not allocate output context" << std::endl;
        return 5;
    }

    for (int i = 0; i < inputFormatContext->nb_streams; i++)
    {
        AVStream *inputStream = inputFormatContext->streams[i];
        AVStream *outputStream = avformat_new_stream(outputFormatContext, nullptr);
        if (!outputStream) {
            std::cerr << "Could not allocate stream" << std::endl;
            return 6;
        }

        avcodec_parameters_copy(outputStream->codecpar, inputStream->codecpar);
        if (i == videoStreamIndex)
        {
            outputStream->codecpar->codec_tag = AV_RTP_PAYLOAD_H264;
        }
        else if (i == audioStreamIndex)
        {
            outputStream->codecpar->codec_tag = AV_RTP_PAYLOAD_AAC;
        }
    }

    av_dump_format(outputFormatContext, 0, host, 1);

    AVDictionary *outputOptions = nullptr;
    av_dict_set_int(&outputOptions, "ttl", 64, 0);
    av_dict_set_int(&outputOptions, "localport", 8000, 0);

    std::string outputUri = "rtp://" + std::string(host) + ":" + std::to_string(port);
    if (avio_open2(&outputFormatContext->pb, outputUri.c_str(), AVIO_FLAG_WRITE, nullptr, &outputOptions) < 0)
    {
        std::cerr << "Could not open output" << std::endl;
        return 7;
    }

    if (avformat_write_header(outputFormatContext, nullptr) < 0)
    {
        std::cerr << "Could not write header" << std::endl;
        return 8;
    }

    // Start streaming.
    AVPacket packet;
    av_init_packet(&packet);
    int64_t lastVideoPts = 0;
    int64_t lastAudioPts = 0;

    while (recv_packet(inputFormatContext, &packet))
    {
        int streamIndex = packet.stream_index;
        AVRational timeBase = inputFormatContext->streams[streamIndex]->time_base;

        if (streamIndex == videoStreamIndex || streamIndex == audioStreamIndex)
        {
            AVPacket outputPacket;
            av_init_packet(&outputPacket);
            av_packet_ref(&outputPacket, &packet);

            av_packet_rescale_ts(&packet, timeBase, outputFormatContext->streams[streamIndex]->time_base);
            av_write_frame(outputFormatContext, &outputPacket);
            av_packet_unref(&outputPacket);

            // Sleep for synchronization.
            std::this_thread::sleep_until(std::chrono::system_clock::now() + std::chrono::duration<int64_t, std::micro>(av_rescale_q(packet.pts - (streamIndex == videoStreamIndex ? lastVideoPts : lastAudioPts), timeBase, {1, 1000000})));
            if (streamIndex == videoStreamIndex)
            {
                lastVideoPts = packet.pts;
            }
            else
            {
                lastAudioPts = packet.pts;
            }
        }

        av_packet_unref(&packet);
    }

    av_write_trailer(outputFormatContext);
    avio_closep(&outputFormatContext->pb);

    // Cleaning up.
    avformat_free_context(outputFormatContext);
    avformat_close_input(&inputFormatContext);

    return 0;
}

