    args = env->NewObjectArray(1, stringClass, jstr);
    if (args == NULL) {
        goto destroy;
    }
    env->CallStaticVoidMethod(cls, mid, args);

destroy:
    if (env->ExceptionOccurred()) {
        env->ExceptionDescribe();
    }
    jvm->DestroyJavaVM();
    return 0;
}

