#include <iostream>
#include <vector>
#include <cmath>
#include <algorithm>
#include <limits>

struct City {
    int x, y;
};

double distance(const City& a, const City& b) {
    return std::sqrt(std::pow(a.x - b.x, 2) + std::pow(a.y - b.y, 2));
}

double totalDistance(const std::vector<int>& tour, const std::vector<City>& cities) {
    double total = 0.0;
    for (size_t i = 0; i < tour.size(); ++i) {
        total += distance(cities[tour[i]], cities[tour[(i + 1) % tour.size()]]);
    }
    return total;
}

void twoOpt(std::vector<int>& tour, const std::vector<City>& cities) {
    bool improved = true;
    while (improved) {
        improved = false;
        for (size_t i = 1; i < tour.size() - 2; ++i) {
            for (size_t j = i + 1; j < tour.size(); ++j) {
                double currentDistance = distance(cities[tour[i - 1]], cities[tour[i]]) + distance(cities[tour[j]], cities[tour[(j + 1) % tour.size()]]);
                double newDistance = distance(cities[tour[i - 1]], cities[tour[j]]) + distance(cities[tour[i]], cities[tour[(j + 1) % tour.size()]]);
                if (newDistance < currentDistance) {
                    std::reverse(tour.begin() + i, tour.begin() + j + 1);
                    improved = true;
                }
            }
        }
    }
}

int main() {
    std::vector<City> cities = {{0, 0}, {1, 5}, {5, 1}, {5, 5}, {1, 1}};
    std::vector<int> tour(cities.size());
    for (size_t i = 0; i < cities.size(); ++i) {
        tour[i] = i;
    }

    std::cout << "Initial tour: ";
    for (int city : tour) {
        std::cout << city << " ";
    }
    std::cout << "\nInitial distance: " << totalDistance(tour, cities) << std::endl;

    twoOpt(tour, cities);

    std::cout << "Optimized tour: ";
    for (int city : tour) {
        std::cout << city << " ";
    }
    std::cout << "\nOptimized distance: " << totalDistance(tour, cities) << std::endl;

    return 0;
}

#include <iostream>
#include <vector>

using namespace std;

// Function to find the first occurrence of the target value
int findFirstOccurrence(const vector<int>& arr, int target) {
    int left = 0, right = arr.size() - 1;
    int result = -1;
    while (left <= right) {
        int mid = left + (right - left) / 2;
        if (arr[mid] == target) {
            result = mid;
            right = mid - 1; // Continue searching in the left half
        } else if (arr[mid] < target) {
            left = mid + 1;
        } else {
            right = mid - 1;
        }
    }
    return result;
}

// Function to find the last occurrence of the target value
int findLastOccurrence(const vector<int>& arr, int target) {
    int left = 0, right = arr.size() - 1;
    int result = -1;
    while (left <= right) {
        int mid = left + (right - left) / 2;
        if (arr[mid] == target) {
            result = mid;
            left = mid + 1; // Continue searching in the right half
        } else if (arr[mid] < target) {
            left = mid + 1;
        } else {
            right = mid - 1;
        }
    }
    return result;
}

// Function to find the first and last occurrence of the target value
pair<int, int> findFirstAndLast(const vector<int>& arr, int target) {
    int first = findFirstOccurrence(arr, target);
    if (first == -1) {
        return {-1, -1}; // Target not found
    }
    int last = findLastOccurrence(arr, target);
    return {first, last};
}

int main() {
    vector<int> arr = {1, 2, 2, 2, 3, 4, 4, 5, 6};
    int target = 2;
    auto [first, last] = findFirstAndLast(arr, target);
    if (first == -1) {
        cout << "Target not found" << endl;
    } else {
        cout << "First occurrence at index: " << first << endl;
        cout << "Last occurrence at index: " << last << endl;
    }
    return 0;
}

#include <iostream>
#include <thread>
#include <deque>
#include <functional>
#include <future>
#include <mutex>
#include <condition_variable>
#include <vector>
#include <memory>
#include <chrono>

class ZYLThreadPool {
public:
    ZYLThreadPool(size_t minThreads = 20, size_t maxThreads = 200)
        : _minThreads(minThreads)
        , _maxThreads(maxThreads)
        , _stop(false) {
        worker_threads.reserve(_maxThreads);
        for (size_t i = 0; i < _minThreads; ++i) {
            create_thread();
        }
    }

    void create_thread() {
        worker_threads.emplace_back([this] {
            for (;;) {
                std::function<void()> task;
                {
                    std::unique_lock<std::mutex> lock(this->_mutex);
                    this->_condVar.wait(lock, [this] {
                        return this->_stop || !this->_taskQueue.empty();
                    });
                    if (this->_stop && this->_taskQueue.empty())
                        return;
                    task = std::move(this->_taskQueue.front());
                    this->_taskQueue.pop_front();
                }
                task();
            }
        });
    }

    template <typename F, typename... Args>
    auto submit(F&& f, Args&&... args)
        -> std::future<typename std::result_of<F(Args...)>::type> {
        using return_type = typename std::result_of<F(Args...)>::type;

        auto task = std::make_shared<
            std::packaged_task<return_type()>>(std::bind(std::forward<F>(f), std::forward<Args>(args)...));

        std::future<return_type> result = task->get_future();
        {
            std::unique_lock<std::mutex> lock(_mutex);
            if (_stop) {
                throw std::runtime_error("Submit on stopped ZYLThreadPool");
            }
            if (_taskQueue.size() >= worker_threads.size() && worker_threads.size() < _maxThreads) {
                create_thread();
            }
            _taskQueue.emplace_back([task] { (*task)(); });
        }
        _condVar.notify_one();
        return result;
    }

    void cancel() {
        std::unique_lock<std::mutex> lock(_mutex);
        if (!_stop) {
            _stop = true;
            _condVar.notify_all();
        }
        for (std::thread& worker : worker_threads)
            worker.join();
    }

    size_t getNumTasks() {
        std::unique_lock<std::mutex> lock(_mutex);
        return _taskQueue.size();
    }

    ~ZYLThreadPool() {
        cancel();
    }

private:
    std::vector<std::thread> worker_threads;
    std::deque<std::function<void()>> _taskQueue;
    size_t _minThreads;
    size_t _maxThreads;
    std::mutex _mutex;
    std::condition_variable _condVar;
    bool _stop;
};

class Test {
public:
    Test(double devid)
        : _devid(devid)
        , _running(true) {
    }

    void start(ZYLThreadPool& threadPool) {
        _future = threadPool.submit(&Test::_task, this);
    }

    void stop() {
        {
            _running = false;
            std::unique_lock<std::mutex> lock(_mutex);

            if (_future.valid()) {
                _future.get();
                lock.unlock();
                _cleanupResources();
            }
        }
    }

private:
    std::mutex _mutex;
    double _devid;
    std::deque<double> _dequeue_packets;
    std::future<void> _future;
    bool _running;

    void _cleanupResources() {
        std::unique_lock<std::mutex> lock(_mutex);
        _dequeue_packets.clear();
    }

    void _task() {
        std::unique_lock<std::mutex> lock(_mutex);
        while (_running) {
            if (_dequeue_packets.empty()) {
                std::cout << "running task" << std::endl;
                continue;
            }
            double packet = _dequeue_packets.front();
            _dequeue_packets.pop_front();
            lock.unlock();
            std::cout << "running task" << std::endl;
            lock.lock();
        }
    }
};

int main() {
    ZYLThreadPool zylThreadPool(20, 200);
    std::vector<std::shared_ptr<Test>> tests;

    for (int i = 0; i < 100; ++i) {
        auto test = std::make_shared<Test>(1.0);
        test->start(zylThreadPool);
        tests.push_back(test);
    }

    std::this_thread::sleep_for(std::chrono::seconds(3));

    for (auto& test : tests) {
        test->stop();
    }
    tests.clear();

    for (int i = 0; i < 3; ++i) {
        auto test = std::make_shared<Test>(1.0);
        test->start(zylThreadPool);
        tests.push_back(test);
    }

    std::this_thread::sleep_for(std::chrono::seconds(3));

    for (auto& test : tests) {
        test->stop();
    }

    return 0;
}

