// Function to check if a number is prime
bool isPrime(int n) {
    if (n <= 1)
        return false;

    if (n == 2)
        return true;

    if (n % 2 == 0)
        return false;

    for (int i = 3; i <= sqrt(n); i += 2) {
        if (n % i == 0)
            return false;
    }

    return true;
}

// Function to find the prime number with the maximum number of digits
int findLongestPrimeNumberDigits(vector<int> lst) {
    int maxDigits = 0;
    int maxPrime = 0;

    for (int i = 0; i < lst.size(); i++) {
        if (isPrime(lst[i])) {
            int digits = 0;
            int num = lst[i];
            while (num != 0) {
                digits++;
                num /= 10;
            }

            if (digits > maxDigits) {
                maxDigits = digits;
                maxPrime = lst[i];
            }
        }
    }

    if (maxPrime == 0)
        return -1; // Return -1 if no prime number is found

    return maxPrime;
}

int main() {
    vector<int> lst = {1, 3, 131, 323, 5107, 34, 8278, 109, 163, 2323, 321, 3039, 31};
    int result = findLongestPrimeNumberDigits(lst);
    printf("The prime number with the maximum number of digits is: %d\n", result);
    return 0;
}

