GLuint compileShader(GLenum type, const char* source) {
    GLuint shader = glCreateShader(type);
    GL_CHECK(glShaderSource(shader, 1, &source, nullptr));
    GL_CHECK(glCompileShader(shader));

    GLint success;
    GL_CHECK(glGetShaderiv(shader, GL_COMPILE_STATUS, &success));
    if (success != GL_TRUE) {
        char infoLog[512];
        GL_CHECK(glGetShaderInfoLog(shader, 512, nullptr, infoLog));
        std::cerr << "Failed to compile shader: " << infoLog << std::endl;
        exit(1);
    }

    return shader;
}

GLuint createProgram() {
    GLuint vertexShader = compileShader(GL_VERTEX_SHADER, vertexShaderSource);
    GLuint fragmentShader = compileShader(GL_FRAGMENT_SHADER, fragmentShaderSource);

    GLuint program = glCreateProgram();
    GL_CHECK(glAttachShader(program, vertexShader));
    GL_CHECK(glAttachShader(program, fragmentShader));

    GL_CHECK(glLinkProgram(program));

    GLint success;
    GL_CHECK(glGetProgramiv(program, GL_LINK_STATUS, &success));
    if (success != GL_TRUE) {
        char infoLog[512];
        GL_CHECK(glGetProgramInfoLog(program, 512, nullptr, infoLog));
        std::cerr << "Failed to link program: " << infoLog << std::endl;
        exit(1);
    }

    GL_CHECK(glDeleteShader(vertexShader));
    GL_CHECK(glDeleteShader(fragmentShader));

    return program;
}

