asm volatile (
    "sub %1, %2, %3\n\t"  // %1 = %2 - %3
    "it  eq\n\t"          // if equal (Z flag set)
    "moveq %0, #1\n\t"    // Z_FLAG = 1 if Z flag is set
    "it  lt\n\t"          // if less than (N flag set)
    "movlt %0, #1\n\t"    // N_FLAG = 1 if N flag is set
    "it  cs\n\t"          // if carry set (C flag set)
    "movcs %0, #0\n\t"    // C_FLAG = 1 if C flag is set
    "it  vs\n\t"          // if overflow (V flag set)
    "movvs %0, #1"        // V_FLAG = 1 if V flag is set
    : "=r" (Z_FLAG), "=r" (N_FLAG), "=r" (C_FLAG), "=r" (V_FLAG)
    : "r" (reg[dest].I), "r" (reg[base].I), "r" (value)
    : "cc"  // clobbers the condition codes
);

