void add_large_numbers(uint64_t* ans, const uint64_t* a, const uint64_t* b, int n) {
    uint64_t carry = 0;
    for (int i = 0; i < n; i++) {
        uint64_t sum;
        __asm__(
            "add %[b], %[a]\n\t"  // a + b
            "adc $0, %[carry]\n\t" // add carry (initially 0, then 1 if carry)
            : [sum] "=r" (sum), [carry] "=r" (carry)
            : [a] "r" (a[i]), [b] "r" (b[i]), [carry] "r" (carry)
            : "cc" // clobber list: condition codes
        );
        ans[i] = sum;
    }
}

