   // Custom type caster for MPI_Comm
   namespace pybind11 {
   namespace detail {
       template <>
       struct type_caster<MPI_Comm> {
       public:
           PYBIND11_TYPE_CASTER(MPI_Comm, _("MPI_Comm"));

           bool load(py::handle src, bool) {
               if (!py::isinstance<py::capsule>(src)) {
                   return false;
               }
               MPI_Comm *comm = static_cast<MPI_Comm *>(PyCapsule_GetPointer(src.ptr(), "MPI_Comm"));
               if (comm == nullptr) {
                   return false;
               }
               value = *comm;
               return true;
           }

           static py::handle cast(MPI_Comm src, py::return_value_policy, py::handle) {
               py::object capsule = py::capsule(new MPI_Comm(src), "MPI_Comm", [](void *v) {
                   MPI_Comm *comm = static_cast<MPI_Comm *>(v);
                   MPI_Comm_free(comm);
               });
               return capsule.release();
           }
       };
   }
   }

   class SomeComputation {
       float multiplier;
       std::vector<int> test;
       MPI_Comm comm_;

   public:
       void Init() {
           int rank;
           MPI_Comm_rank(comm_, &rank);
           test.clear();
           test.resize(10, rank);
       }

       void set_comm(MPI_Comm comm) {
           this->comm_ = comm;
       }

       SomeComputation(float multiplier_) : multiplier(multiplier_) {}
       ~SomeComputation() { std::cout << "Destructor Called!\n"; }

       float compute(float input) {
           std::this_thread::sleep_for(std::chrono::milliseconds((int)input * 10));
           for (int i = 0; i != 10; ++i) {
               std::cout << test[i] << " ";
           }
           std::cout << std::endl;
           return multiplier * input;
       }
   };

