    uint_t win_size = 512;
    fvec_t *input;
    fvec_t *beat_output;
    aubio_tempo_t *tempo;

    source = new_aubio_source(filename, 0, hop_size);
    input = new_fvec(hop_size);
    beat_output = new_fvec(1);
    tempo = new_aubio_tempo("default", win_size, hop_size, aubio_source_get_samplerate(source));

    smpl_t read = hop_size;
    while (read == hop_size) {
        aubio_source_do(source, input, &read);
        aubio_tempo_do(tempo, input, beat_output);
        if (fvec_get_sample(beat_output, 0) > 0) {
            // A beat was detected
            // Do something (e.g., log the time, trigger an event)
        }
    }

    del_aubio_tempo(tempo);
    del_fvec(beat_output);
    del_fvec(input);
    del_aubio_source(source);
}

JNIEnv* GetJniEnvHandle() {
    ThreadInfo();
    JNIEnv *envLoc;
    jint envRes = vm->GetEnv((void**)&envLoc, JNI_VERSION_1_4);

    if (envRes == JNI_OK) {
        // Thread is already attached, return the JNIEnv pointer
        return envLoc;
    } else if (envRes == JNI_EDETACHED) {
        // Thread is not attached, attach it and get the JNIEnv pointer
        envRes = vm->AttachCurrentThread((void**)&envLoc, NULL);
        if (envRes != JNI_OK) {
            Log("Error attaching current thread to JVM");
            return nullptr;
        }
        return envLoc;
    } else {
        // Other error occurred
        Log("Error obtaining JNIEnv* handle");
        return nullptr;
    }
}

