std::vector<Card> createDeck() {
    std::vector<Card> deck;
    for (int suit = 0; suit < 4; ++suit) {
        for (int rank = 0; rank < 13; ++rank) {
            deck.emplace_back(static_cast<Suit>(suit), static_cast<Rank>(rank));
        }
    }
    return deck;
}

