        cout<<a[i]<<" ";
    cout<<endl;

    mergeSort(a, 0, n - 1);

    cout<<"Sorted array is: "<<endl;
    for(int i=0;i<n;i++)
        cout<<a[i]<<" ";
    cout<<endl;

    return 0;
}

