void insertionSort(std::vector<int>& arr, int left, int right) {
    for (int i = left + 1; i <= right; ++i) {
        int key = arr[i];
        int j = i - 1;
        while (j >= left && arr[j] > key) {
            arr[j + 1] = arr[j];
            --j;
        }
        arr[j + 1] = key;
    }
}

void heapify(std::vector<int>& arr, int n, int i) {
    int largest = i;
    int left = 2 * i + 1;
    int right = 2 * i + 2;

    if (left < n && arr[left] > arr[largest])
        largest = left;

    if (right < n && arr[right] > arr[largest])
        largest = right;

    if (largest != i) {
        std::swap(arr[i], arr[largest]);
        heapify(arr, n, largest);
    }
}

void heapSort(std::vector<int>& arr, int n) {
    for (int i = n / 2 - 1; i >= 0; --i)
        heapify(arr, n, i);

    for (int i = n - 1; i >= 0; --i) {
        std::swap(arr[0], arr[i]);
        heapify(arr, i, 0);
    }
}

void introsortUtil(std::vector<int>& arr, int begin, int end, int depthLimit) {
    if (end - begin > 16) {
        if (depthLimit == 0) {
            heapSort(arr, end - begin + 1);
            return;
        }
        depthLimit = depthLimit - 1;
        int pivot = std::partition(arr.begin() + begin, arr.begin() + end, std::less<int>());
        introsortUtil(arr, begin, pivot - begin - 1, depthLimit);
        introsortUtil(arr, pivot - begin, end, depthLimit);
    } else {
        insertionSort(arr, begin, end);
    }
}

void introsort(std::vector<int>& arr) {
    int depthLimit = 2 * std::log(arr.size());
    introsortUtil(arr, 0, arr.size() - 1, depthLimit);
}

int main() {
    std::vector<int> array = {34, 7, 23, 32, 5, 62, 1, 89, 45, 21, 12, 34, 56, 78, 90, 12, 34, 56, 78, 90};
    introsort(array);
    for (int num : array) {
        std::cout << num << " ";
    }
    return 0;
}

