#include <iostream>

class FrangiFilter {
public:
    FrangiFilter(double sigma = 1.0, double beta1 = 1.0, double beta2 = 2.0) 
        : sigma(sigma), beta1(beta1), beta2(beta2) {}

    cv::Mat enhanceImage(const cv::Mat& input) {
        cv::Mat grayImage;
        cv::cvtColor(input, grayImage, cv::COLOR_BGR2GRAY);

        cv::Mat hessianMatrix;
        computeHessianMatrix(grayImage, hessianMatrix);

        cv::Mat lambda1, lambda2;
        computeEigenvalues(hessianMatrix, lambda1, lambda2);

        cv::Mat frangiResponse;
        computeFrangiResponse(lambda1, lambda2, frangiResponse);

        normalizeFrangiResponse(frangiResponse);

        return frangiResponse;
    }

private:
    double sigma;
    double beta1;
    double beta2;

    void computeHessianMatrix(const cv::Mat& input, cv::Mat& output) {
        cv::Mat dx, dy;
        cv::Sobel(input, dx, CV_64F, 1, 0, 3, 1, 0, cv::BORDER_DEFAULT);
        cv::Sobel(input, dy, CV_64F, 0, 1, 3, 1, 0, cv::BORDER_DEFAULT);

        cv::Mat dx2, dy2, dxy;
        cv::multiply(dx, dx, dx2);
        cv::multiply(dy, dy, dy2);
        cv::multiply(dx, dy, dxy);

        cv::GaussianBlur(dx2, dx2, cv::Size(0, 0), sigma);
        cv::GaussianBlur(dy2, dy2, cv::Size(0, 0), sigma);
        cv::GaussianBlur(dxy, dxy, cv::Size(0, 0), sigma);

        output.create(input.size(), CV_64FC3);
        cv::MatIterator_<cv::Vec<double, 3>> it = output.begin<cv::Vec<double, 3>>();
        cv::MatIterator_<double> dx2Iter = dx2.begin<double>(), dy2Iter = dy2.begin<double>(), dxyIter = dxy.begin<double>();

        while (it != output.end<cv::Vec<double, 3>>()) {
            (*it)[0] = *dx2Iter;
            (*it)[1] = *dy2Iter;
            (*it)[2] = *dxyIter;

            ++it;
            ++dx2Iter;
            ++dy2Iter;
            ++dxyIter;
        }
    }

    void computeEigenvalues(const cv::Mat& input, cv::Mat& lambda1, cv::Mat& lambda2) {
        std::vector<cv::Mat> eigenvalues;
        cv::eigen(input, eigenvalues);

        lambda1 = eigenvalues[0];
        lambda2 = eigenvalues[1];
    }

    void computeFrangiResponse(const cv::Mat& lambda1, const cv::Mat& lambda2, cv::Mat& output) {
        output.create(lambda1.size(), CV_64F);

        cv::MatIterator_<double> it = output.begin<double>();
        cv::MatConstIterator_<double> lambda1Iter = lambda1.begin<double>(), lambda2Iter = lambda2.begin<double>();

        while (it != output.end<double>()) {
            double alpha = std::sqrt(*lambda2Iter) / std::sqrt(*lambda1Iter);
            double beta = std::sqrt(*lambda1Iter) / std::sqrt(*lambda2Iter);

            *it = std::exp(-(*lambda1Iter * *lambda1Iter) / (2.0 * beta1 * beta1)) 
                * (1 - std::exp(-alpha * alpha / (2.0 * beta2 * beta2)));

            ++it;
            ++lambda1Iter;
            ++lambda2Iter;
        }
    }

    void normalizeFrangiResponse(cv::Mat& input) {
        double minVal, maxVal;
        cv::minMaxLoc(input, &minVal, &maxVal);

        input -= minVal;
        input /= (maxVal - minVal);
    }
};

int main() {
    cv::Mat image = cv::imread("input.png");
    if (image.empty()) {
        std::cout << "Failed to read image!" << std::endl;
        return -1;
    }

    FrangiFilter frangiFilter;
    cv::Mat enhancedImage = frangiFilter.enhanceImage(image);
    cv::imshow("Enhanced Image", enhancedImage);
    cv::waitKey(0);

    return 0;
}

