typedef std::array<std::complex<double>, 4> ArrayComplex4;
PYBIND11_MAKE_OPAQUE(ArrayComplex4);

namespace py = pybind11;
using namespace my_namespace;

// Custom converter for std::array<std::complex<double>, 4>
void bind_array_complex4(py::module_ &m) {
    py::class_<ArrayComplex4>(m, "ArrayComplex4")
        .def(py::init<>())
        .def(py::init([](const std::vector<std::complex<double>>& vec) {
            if (vec.size() != 4) {
                throw std::invalid_argument("ArrayComplex4 must have exactly 4 elements");
            }
            return ArrayComplex4{vec[0], vec[1], vec[2], vec[3]};
        }))
        .def("at", [](const ArrayComplex4& self, size_t index) {
            if (index >= 4) {
                throw std::out_of_range("Index out of range");
            }
            return self[index];
        })
        .def("__getitem__", [](const ArrayComplex4& self, size_t index) {
            if (index >= 4) {
                throw std::out_of_range("Index out of range");
            }
            return self[index];
        })
        .def("__setitem__", [](ArrayComplex4& self, size_t index, const std::complex<double>& value) {
            if (index >= 4) {
                throw std::out_of_range("Index out of range");
            }
            self[index] = value;
        })
        .def("__repr__", [](const ArrayComplex4& self) {
            return "ArrayComplex4([" + py::str(self[0]) + ", " + py::str(self[1]) + ", " + py::str(self[2]) + ", " + py::str(self[3]) + "])";
        });
}

