   public:
       PythonThread(QObject *parent = nullptr) : QThread(parent) {}

   signals:
       void resultReady(const QString &result);

   protected:
       void run() override {
           Py_Initialize();
           PyRun_SimpleString("import sys");
           PyRun_SimpleString("sys.path.append('./')");

           PyObject *pModule = PyImport_ImportModule("your_module");
           if (pModule != NULL) {
               PyObject *pFunc = PyObject_GetAttrString(pModule, "your_function");
               if (pFunc && PyCallable_Check(pFunc)) {
                   PyObject *pArgs = PyTuple_New(1);
                   PyObject *pValue = PyUnicode_FromString("your_argument");
                   PyTuple_SetItem(pArgs, 0, pValue);

                   PyObject *pResult = PyObject_CallObject(pFunc, pArgs);
                   if (pResult != NULL) {
                       const char *result = PyUnicode_AsUTF8(pResult);
                       QMetaObject::invokeMethod(this, [this, result]() {
                           emit resultReady(QString(result));
                       }, Qt::QueuedConnection);
                   }

                   Py_DECREF(pArgs);
                   Py_DECREF(pFunc);
               }
               Py_DECREF(pModule);
