double findMedian(vector<double>& nums) {
    int size = nums.size();
    // Sort the vector
    sort(nums.begin(), nums.end());

    if (size % 2 == 0) {
        return (nums[size / 2 - 1] + nums[size / 2]) / 2.0;
    } else {
        return nums[size / 2];
    }
}

double findMode(vector<double>& nums) {
    unordered_map<double, int> frequencyMap;
    for (double num : nums) {
        frequencyMap[num]++;
    }

    double mode = nums[0];
    int maxCount = 0;
    for (const auto& pair : frequencyMap) {
        if (pair.second > maxCount) {
            maxCount = pair.second;
            mode = pair.first;
        }
    }

    return mode;
}

int main() {
    vector<double> nums = {1.5, 3.0, 4.5, 2.5, 5.0};

    double median = findMedian(nums);
    cout << "Median is: " << median << endl;

    double mode = findMode(nums);
    cout << "Mode is: " << mode << endl;

    return 0;
}

