namespace py = pybind11;

template<typename T, int N> struct vec {
  explicit vec(const T* data_) {
    for (int i = 0; i < N; ++i) { this->data[i] = data_[i]; }
  }
  T data[N];
};

vec<double, 2> return_vector(double t) {
  double v[] = {t, t};
  return vec<double, 2>{v};
}

namespace pybind11 { namespace detail {
  template <typename T, int N> struct type_caster<vec<T, N>>
  {
  private:
    using _vecTN = vec<T, N>;

  public:
    PYBIND11_TYPE_CASTER(_vecTN, _("vec<T, N>"));

    bool load(py::handle src, bool convert)
    {
      if (!convert && !py::array_t<T>::check_(src)) { return false; }
      auto buf = py::array_t<T>::ensure(src);
      if (!buf || buf.ndim() != 1 || buf.size() != N) { return false; }
      value = _vecTN{buf.data()};
      return true;
    }

    static py::handle cast(const _vecTN& src,
        py::return_value_policy policy, py::handle parent)
    {
      py::array_t<T> a({N});
      for (auto i = 0; i < N; ++i) { a.mutable_at(i) = src.data[i]; }
      return a.release();
    }
  };
}}

template struct pybind11::detail::type_caster<vec<double, 2>>;

// Custom converter function
vec<double, 2> return_vector_custom(const py::array_t<double>& input) {
  if (input.ndim() != 1 || input.size() != 1) {
    throw std::runtime_error("Input must be a 1D array with a single element.");
  }
  double t = input.at(0);
  return return_vector(t);
}

PYBIND11_MODULE(mylib, m) {
  m.def("return_vector", py::vectorize(&return_vector));
  m.def("return_vector_custom", &return_vector_custom);
}

#include <array>
#include <iostream>

void shift_left(std::array<unsigned long long, 20>& a, unsigned int n) {
    if (n == 0) return;

    const unsigned int bits_per_element = 64;
    unsigned int full_shifts = n / bits_per_element;
    unsigned int partial_shift = n % bits_per_element;

    if (full_shifts >= a.size()) {
        std::fill(a.begin(), a.end(), 0);
        return;
    }

    // Shift full elements
    for (int i = a.size() - 1; i >= full_shifts; --i) {
        a[i] = a[i - full_shifts];
    }
    std::fill(a.begin(), a.begin() + full_shifts, 0);

    // Handle partial shift
    if (partial_shift > 0) {
        unsigned long long carry = 0;
        for (int i = a.size() - 1; i >= 0; --i) {
            unsigned long long temp = a[i] << partial_shift;
            a[i] = temp | carry;
            carry = a[i - 1] >> (bits_per_element - partial_shift);
        }
    }
}

void shift_right(std::array<unsigned long long, 20>& a, unsigned int n) {
    if (n == 0) return;

    const unsigned int bits_per_element = 64;
    unsigned int full_shifts = n / bits_per_element;
    unsigned int partial_shift = n % bits_per_element;

    if (full_shifts >= a.size()) {
        std::fill(a.begin(), a.end(), 0);
        return;
    }

    // Shift full elements
    for (int i = 0; i < a.size() - full_shifts; ++i) {
        a[i] = a[i + full_shifts];
    }
    std::fill(a.begin() + a.size() - full_shifts, a.end(), 0);

    // Handle partial shift
    if (partial_shift > 0) {
        unsigned long long carry = 0;
        for (int i = 0; i < a.size(); ++i) {
            unsigned long long temp = a[i] >> partial_shift;
            a[i] = temp | carry;
            carry = a[i + 1] << (bits_per_element - partial_shift);
        }
    }
}

int main() {
    std::array<unsigned long long, 20> a = { /* Initialize with some values */ };

    // Example usage
    shift_left(a, 5);
    // shift_right(a, 5);

    for (const auto& val : a) {
        std::cout << val << " ";
    }
    std::cout << std::endl;

    return 0;
}

