std::vector<std::string> preprocessText(const std::string& text) {
    std::vector<std::string> words;
    std::regex word_regex(R"(\b\w+\b)");
    auto words_begin = std::sregex_iterator(text.begin(), text.end(), word_regex);
    auto words_end = std::sregex_iterator();
    for (std::sregex_iterator i = words_begin; i != words_end; ++i) {
        words.push_back((*i).str());
    }
    return words;
}

std::unordered_map<std::string, std::vector<std::string>> buildGraph(const std::vector<std::string>& words) {
    std::unordered_map<std::string, std::vector<std::string>> graph;
    for (const auto& word : words) {
        for (size_t i = 1; i < word.size(); ++i) {
            std::string prefix = word.substr(0, i);
            if (std::find(words.begin(), words.end(), prefix) != words.end()) {
                graph[prefix].push_back(word);
            }
        }
    }
    return graph;
}

int findLongestWordChain(const std::unordered_map<std::string, std::vector<std::string>>& graph, const std::unordered_set<std::string>& words) {
    std::unordered_map<std::string, int> memo;
    for (const auto& word : words) {
        dfs(word, graph, memo);
    }
    int maxLength = 0;
    for (const auto& entry : memo) {
        maxLength = std::max(maxLength, entry.second);
    }
    return maxLength;
}

int dfs(const std::string& word, const std::unordered_map<std::string, std::vector<std::string>>& graph, std::unordered_map<std::string, int>& memo) {
    if (memo.find(word) == memo.end()) {
        int maxLength = 1;
        for (const auto& neighbor : graph.at(word)) {
            maxLength = std::max(maxLength, 1 + dfs(neighbor, graph, memo));
        }
        memo[word] = maxLength;
    }
    return memo[word];
}

int main() {
    std::string text = "I am a software engineer and I love programming.";
    std::vector<std::string> words = preprocessText(text);
    std::unordered_set<std::string> wordSet(words.begin(), words.end());
    std::unordered_map<std::string, std::vector<std::string>> graph = buildGraph(words);
    std::cout << findLongestWordChain(graph, wordSet) << std::endl;
    return 0;
}

