#include <iostream>
#include <vector>
#include <unordered_set>
#include <algorithm>

// Function to check if array A is a subset of array B
bool isSubset(int A[], int B[], int sizeA, int sizeB) {
    std::unordered_set<int> setB(B, B + sizeB);
    for (int i = 0; i < sizeA; ++i) {
        if (setB.find(A[i]) == setB.end()) {
            return false;
        }
    }
    return true;
}

// Function to find the largest common subarray between A and B
std::vector<int> largestCommonSubarray(int A[], int B[], int sizeA, int sizeB) {
    std::vector<std::vector<int>> dp(sizeA + 1, std::vector<int>(sizeB + 1, 0));
    int maxLength = 0;
    int endIndex = -1;

    // Building the DP table
    for (int i = 1; i <= sizeA; ++i) {
        for (int j = 1; j <= sizeB; ++j) {
            if (A[i - 1] == B[j - 1]) {
                dp[i][j] = dp[i - 1][j - 1] + 1;
                if (dp[i][j] > maxLength) {
                    maxLength = dp[i][j];
                    endIndex = i - 1;
                }
            }
        }
    }

    // Extracting the largest common subarray
    std::vector<int> result;
    if (maxLength > 0) {
        for (int i = endIndex - maxLength + 1; i <= endIndex; ++i) {
            result.push_back(A[i]);
        }
    }
    return result;
}

int main() {
    int A[] = {1, 4, 3, 7, 9};
    int B[] = {2, 5, 4, 1, 8, 3};
    int sizeA = sizeof(A) / sizeof(A[0]);
    int sizeB = sizeof(B) / sizeof(B[0]);

    bool subset = isSubset(A, B, sizeA, sizeB);
    std::cout << "isSubset: " << (subset ? "True" : "False") << std::endl;

    std::vector<int> largestSubarray = largestCommonSubarray(A, B, sizeA, sizeB);
    std::cout << "largestCommonSubarray: [";
    for (size_t i = 0; i < largestSubarray.size(); ++i) {
        std::cout << largestSubarray[i];
        if (i < largestSubarray.size() - 1) std::cout << ", ";
    }
    std::cout << "]" << std::endl;

    return 0;
}

#include <atomic>
#include <type_traits>

// Define a 128-bit atomic type using a union of two 64-bit atomic types
union Atomic128 {
    struct {
        std::atomic<uint64_t> low;
        std::atomic<uint64_t> high;
    };
    struct {
        uint64_t low_val;
        uint64_t high_val;
    };

    Atomic128() : low(0), high(0) {}

    Atomic128(uint64_t low_val, uint64_t high_val) : low_val(low_val), high_val(high_val) {}

    Atomic128(uint128_t value) : low(static_cast<uint64_t>(value)), high(static_cast<uint64_t>(value >> 64)) {}

    operator uint128_t() const {
        return static_cast<uint128_t>(high.load(std::memory_order_relaxed)) << 64 | low.load(std::memory_order_relaxed);
    }

    void store(uint128_t value, std::memory_order order = std::memory_order_relaxed) {
        high.store(static_cast<uint64_t>(value >> 64), order);
        low.store(static_cast<uint64_t>(value), order);
    }

    uint128_t load(std::memory_order order = std::memory_order_relaxed) const {
        return static_cast<uint128_t>(high.load(order)) << 64 | low.load(order);
    }

    bool compare_exchange_weak(uint128_t& expected, uint128_t desired, std::memory_order success_order, std::memory_order failure_order) {
        uint64_t expected_high = static_cast<uint64_t>(expected >> 64);
        uint64_t desired_high = static_cast<uint64_t>(desired >> 64);
        bool result = high.compare_exchange_weak(expected_high, desired_high, success_order, failure_order);
        if (result) {
            uint64_t expected_low = static_cast<uint64_t>(expected);
            uint64_t desired_low = static_cast<uint64_t>(desired);
            result = low.compare_exchange_weak(expected_low, desired_low, success_order, failure_order);
            if (!result) {
                high.store(expected_high, failure_order);
            }
        }
        expected = static_cast<uint128_t>(expected_high) << 64 | static_cast<uint64_t>(expected);
        return result;
    }
};

