int levenshteinDistance(const std::string &s, const std::string &t) {
    int n = s.size();
    int m = t.size();
    std::vector<std::vector<int>> d(n + 1, std::vector<int>(m + 1, 0));

    for (int i = 0; i <= n; ++i) {
        d[i][0] = i;
    }
    for (int j = 0; j <= m; ++j) {
        d[0][j] = j;
    }

    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= m; ++j) {
            int cost = (s[i - 1] == t[j - 1]) ? 0 : 1;
            d[i][j] = std::min({d[i - 1][j] + 1, d[i][j - 1] + 1, d[i - 1][j - 1] + cost});
        }
    }
    return d[n][m];
}

