    Vehicle(std::string make, std::string model, int year, std::string color, float price)
        : make(make), model(model), year(year), color(color), price(price) {}

    bool operator==(const Vehicle& other) const {
        return make == other.make && model == other.model && year == other.year && color == other.color && price == other.price;
    }

    bool operator<(const Vehicle& other) const {
        if (year != other.year) return year < other.year;
        return price > other.price; // Note: price is in descending order
    }
};

