    // Parameters of the model
    sm::vec<float, 3> offset = { 0.00, 0.00, 0.00 };   // a within-scene offset
    sm::vec<float, 3> e1 =     { 1,    0, 0 };
    sm::vec<float, 3> e2 =     { 0.5,  1, 0 };
    sm::vec<float, 3> e3 =     { 0,    0, 1 };
