// Function to send a query to the interactor
long long query(const std::vector<long long>& q) {
    if (q.empty()) {
        return 0;
    }
    std::cout << "0 " << q.size();
    for (long long x : q) {
        std::cout << " " << x;
    }
    std::cout << std::endl;
    long long collisions;
    std::cin >> collisions;
    if (collisions == -1) exit(0);
    return collisions;
