using namespace lbug::main;
namespace lbug {
namespace benchmark {
const char* BENCHMARK_SUFFIX = ".benchmark";
BenchmarkRunner::BenchmarkRunner(const std::string& datasetPath,
    std::unique_ptr<BenchmarkConfig> config)
    : config{std::move(config)} {
    database = std::make_unique<Database>(datasetPath,
        SystemConfig(this->config->bufferPoolSize, this->config->numThreads));
    spdlog::set_level(spdlog::level::debug);
}
void BenchmarkRunner::registerBenchmarks(const std::string& path) {
    if (std::filesystem::is_regular_file(path)) {
        registerBenchmark(path);
    } else if (std::filesystem::is_directory(path)) {
        for (auto& f : std::filesystem::directory_iterator(path)) {
            registerBenchmark(f.path().string());
        }
    }
}
void BenchmarkRunner::runAllBenchmarks() {
    for (auto& benchmark : benchmarks) {
        try {
            runBenchmark( // NOLINT(clang-analyzer-optin.cplusplus.UninitializedObject): spdlog has
                          // an unitialized object.
                benchmark.get());
        } catch (std::exception& e) {
            spdlog::error("Error encountered while running benchmark {}: {}.", benchmark->name,
                e.what());
        }
    }
}
void BenchmarkRunner::registerBenchmark(const std::string& path) {
    if (path.ends_with(BENCHMARK_SUFFIX)) {
        auto benchmark = std::make_unique<Benchmark>(path, database.get(), *config);
        spdlog::info("Register benchmark {}", benchmark->name);
        benchmarks.push_back(std::move(benchmark));
    }
}
double BenchmarkRunner::computeAverageOfLastRuns(const double* runTimes, const int& len,
    const int& lastRunsToAverage) {
    double sum = 0;
    for (int i = len - lastRunsToAverage; i < len; ++i) {
        sum += runTimes[i];
    }
    return sum / lastRunsToAverage;
}
void BenchmarkRunner::runBenchmark(Benchmark* benchmark) const {
    spdlog::info(
        "Running benchmark {} with {} thread", // NOLINT(clang-analyzer-optin.cplusplus.UninitializedObject):
                                               // spdlog has an unitialized object.
        benchmark->name, config->numThreads);
    if (!benchmark->preRun.empty()) {
        spdlog::info("Prerun. {}", benchmark->preRun);
        benchmark->conn->query(benchmark->preRun);
    }
    for (auto i = 0u; i < config->numWarmups; ++i) {
        spdlog::info("Warm up");
        benchmark->run();
    }
    profileQueryIfEnabled(benchmark);
    std::vector<double> runTimes(config->numRuns);
    for (auto i = 0u; i < config->numRuns; ++i) {
        auto queryResult = benchmark->run();
        benchmark->log(i + 1, *queryResult);
        runTimes[i] = queryResult->getQuerySummary()->getExecutionTime();
    }
    spdlog::info("Time Taken (Average of Last {} runs) (ms): {}", config->numRuns,
        computeAverageOfLastRuns(&runTimes[0], config->numRuns,
            config->numRuns /* numRunsToAverage */));
    if (!benchmark->postRun.empty()) {
        spdlog::info("PostRun. {}", benchmark->postRun);
        benchmark->conn->query(benchmark->postRun);
    }
}
void BenchmarkRunner::profileQueryIfEnabled(Benchmark* benchmark) const {
    if (config->enableProfile && !config->outputPath.empty()) {
        auto profileInfo = benchmark->runWithProfile();
        std::ofstream profileFile(config->outputPath + "/" + benchmark->name + "_profile.txt",
            std::ios_base::app);
        profileFile << profileInfo->getNext()->toString() << '\n';
        profileFile.flush();
        profileFile.close();
    }
}
} // namespace benchmark
} // namespace lbug

#include <vector>
#include <queue>
using namespace std;
class Solution {
public:
    vector<int> maxSlidingWindow(vector<int>& nums, int k) {
        vector<int> result;
        priority_queue<pair<int, int>> maxHeap;
        // Push the first 'k' elements into the max-heap
        for(int i = 0; i < k; i++) {
            maxHeap.push({nums[i], i});  // Use the correct pair syntax
        }
        // The largest element in the first window is the root of the max-heap
        result.push_back(maxHeap.top().first);
        // Now slide the window across the array
        for(int j = k; j < nums.size(); j++) {
            // Push the current element into the heap
            maxHeap.push({nums[j], j});
            // Remove elements from the heap that are out of the window's range
            while(!maxHeap.empty() && maxHeap.top().second <= j - k) {
                maxHeap.pop();
            }
            // Add the largest element in the current window
            result.push_back(maxHeap.top().first);
        }

        return result;
    }
};

#include <cstdint>
#include <cstdlib>
#include <cstring>
#include <cstdio>
// A modified jenkins_one_at_a_time_hash initialized by non-zero,
// so that simple_hash(0) != 0. See also
// https://en.wikipedia.org/wiki/Jenkins_hash_function
static uint32_t simple_hash(const uint8_t *Data, size_t Size) {
  uint32_t Hash = 0x12039854;
  for (uint32_t i = 0; i < Size; i++) {
    Hash += Data[i];
    Hash += (Hash << 10);
    Hash ^= (Hash >> 6);
  }
  Hash += (Hash << 3);
  Hash ^= (Hash >> 11);
  Hash += (Hash << 15);
  return Hash;
}
extern "C" int LLVMFuzzerTestOneInput(const uint8_t *Data, size_t Size) {
  if (Size < 14)
    return 0;
  uint32_t Hash = simple_hash(&Data[0], Size - 4);
  uint32_t Want = reinterpret_cast<const uint32_t *>(&Data[Size - 4])[0];
  if (Hash != Want)
    return 0;
  fprintf(stderr, "BINGO; simple_hash defeated: %x == %x\n", (unsigned int)Hash,
          (unsigned int)Want);
  exit(1);
  return 0;
}

