void glTexGen(int coord, int mode, FloatBuffer *vec)
{
	float *data = vec->_getDataPointer();
	RenderManager.StateSetTexGenCol( coord, data[0], data[1], data[2], data[3], mode == GL_EYE_PLANE );
}
