	expect_print("2.0");
	expect_print("123.0");
	/*
	 * We hit the possibility of roundoff errors whenever the fractional
	 * component isn't a round binary number; only check these here (we
	 * round-trip properly in the stress test).
	 */
	expect_print("1.5");
