  return GenericToNVVM().runOnModule(M) ? PreservedAnalyses::none()
                                        : PreservedAnalyses::all();
}

#include <bits/stdc++.h>
using namespace std;
/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     TreeNode *left;
 *     TreeNode *right;
 *     TreeNode() : val(0), left(nullptr), right(nullptr) {}
 *     TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
 *     TreeNode(int x, TreeNode *left, TreeNode *right) : val(x), left(left), right(right) {}
 * };
 */
struct TreeNode {
      int val;
      TreeNode *left;
      TreeNode *right;
      TreeNode() : val(0), left(nullptr), right(nullptr) {}
      TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
      TreeNode(int x, TreeNode *left, TreeNode *right) : val(x), left(left), right(right) {}
  };
class Solution {
public:
    int total = 0;
    void inOrder(TreeNode* root, int low, int high) {
        if (root == NULL) return;
        if (root->val > low) {
            inOrder(root->left, low, high);
        }
        if (root->val >= low && root->val <= high) {
            total += root->val;
        }
        if (root->val < high) {
            inOrder(root->right, low, high);
        }
    }
    int rangeSumBST(TreeNode* root, int low, int high) {
        total = 0; // Reset total for each call
        inOrder(root, low, high);
        return total;
    }
};
int main() {
    // Example usage
    TreeNode* root = new TreeNode(10);
    root->left = new TreeNode(5);
    root->right = new TreeNode(15);
    root->left->left = new TreeNode(3);
    root->left->right = new TreeNode(7);
    root->right->right = new TreeNode(18);
    Solution solution;
    int low = 7, high = 15;
    int result = solution.rangeSumBST(root, low, high);

    cout << "Range Sum BST: " << result << endl; // Output should be the sum of values in the range [7, 15]
    return 0;
}

#include <iostream>
#include <vector>
using namespace std;
int main(){
    vector<int> v;
    vector<int> v1(5, 10);  // 5 elements with value 10
    vector<int>v2 = {1,2,3,4,5};
    vector<int> v3(v2);    // copy of v2

    for(int i = 1; i<=10; i++){
        v.push_back(i);
    }

    //Method 1: For  Loop
    // for(int i = 0; i<v.size(); i++){
    //     cout<<v[i]<<" ";
    //     }

    //Method 2: Range-based for loop
    for(int i: v){
        cout<<i<<" ";
    }
    cout<<endl;
    v.pop_back();
    v.emplace_back(10);    // insert at the end of the vector. Creates inplace object.
    cout << "value at 5th index: " << v.at(5) << endl;
    cout<<v.front()<<endl;
    cout<<v.back()<<endl;
    v.pop_back();
    cout<<v.size()<<endl;
    cout<<v.capacity()<<endl;
    cout<<v.max_size()<<endl;

    v.erase(v.begin()+2);   // erase 3rd element
    v.erase(v.begin()+2, v.begin()+4);   // erase 3rd and 4th element(range)
    v.clear();  // clear the vector
    cout<<v.empty()<<endl;  // check if vector is empty or not
    v.insert(v.begin(), 5); // insert 5 at the beginning
    // erase and clear affect the size of the vector but not the capacity.
    //Iterators
    vector<int> v4 = {1,2,3,4,5};
    vector<int>::iterator it ; // we can also use auto
    for(it = v4.begin(); it!=v4.end(); it++){
        cout<<*it<<" ";
