#include <TranslatorRoster.h>
#include <TranslatorFormats.h>
#include <DataIO.h>
#include <File.h>
#include <Entry.h>
#include <Message.h>
#include <iostream>
int main() {
    // Open the Markdown file for reading
    BFile markdownFile("./sample.md", B_READ_ONLY);
    if (markdownFile.InitCheck() != B_OK) {
        std::cerr << "Failed to open sample.md\n";
        return 1;
    }
    // Create the text file for writing (overwrite if exists)
    BFile txtFile("./sample.txt", B_CREATE_FILE | B_ERASE_FILE | B_WRITE_ONLY);
    if (txtFile.InitCheck() != B_OK) {
        std::cerr << "Failed to create sample.txt\n";
        return 1;
    }
    // Get the default translator roster
    BTranslatorRoster* roster = BTranslatorRoster::Default();
    if (!roster) {
        std::cerr << "Failed to get translator roster\n";
        return 1;
    }
    // Prepare identification info
    BMessage ext;
    ext.AddString("name", "./sample.md");
    ext.AddString("BEOS:TYPE", "text/markdown");
    translator_info tinfo;
    status_t result = roster->Identify(&markdownFile, &ext, &tinfo);
    if (result == B_OK) {
        const char* name = nullptr;
        const char* info = nullptr;
        int32 version = 0;
        // Get translator details
        if (roster->GetTranslatorInfo(tinfo.translator, &name, &info, &version) == B_OK) {
            std::cout << "Translator selected: " << name << " (version " << version << ")\n";
            std::cout << "Info: " << info << "\n";
        } else {
            std::cerr << "Error: GetTranslatorInfo() failed\n";
        }
    } else {
        std::cerr << "Identify failed: " << result << "\n";
        return 1;
    }
    // Reset file pointer to the beginning before translation
    markdownFile.Seek(0, SEEK_SET);
    // Translate the Markdown file to plain text
    status_t status = roster->Translate(&markdownFile, nullptr, &ext, &txtFile, B_TRANSLATOR_TEXT);
    if (status != B_OK) {
        std::cerr << "Translation failed: " << status << "\n";
        return 1;
    } else {
        std::cout << "Saved txt file: sample.txt\n";
    }
    return 0;
}

#include <gtest/gtest.h>
#include "ros2_medkit_fault_manager/correlation/pattern_matcher.hpp"
using namespace ros2_medkit_fault_manager::correlation;
class PatternMatcherTest : public ::testing::Test {
 protected:
  void SetUp() override {
  }
};
// ============================================================================
// Static matches_wildcard tests
// ============================================================================
TEST_F(PatternMatcherTest, ExactMatch) {
  EXPECT_TRUE(PatternMatcher::matches_wildcard("MOTOR_COMM_FL", "MOTOR_COMM_FL"));
  EXPECT_FALSE(PatternMatcher::matches_wildcard("MOTOR_COMM_FL", "MOTOR_COMM_FR"));
  EXPECT_FALSE(PatternMatcher::matches_wildcard("MOTOR_COMM_FL", "MOTOR_COMM"));
  EXPECT_FALSE(PatternMatcher::matches_wildcard("MOTOR_COMM", "MOTOR_COMM_FL"));
}
TEST_F(PatternMatcherTest, WildcardSuffix) {
  EXPECT_TRUE(PatternMatcher::matches_wildcard("MOTOR_COMM_FL", "MOTOR_COMM_*"));
  EXPECT_TRUE(PatternMatcher::matches_wildcard("MOTOR_COMM_FR", "MOTOR_COMM_*"));
  EXPECT_TRUE(PatternMatcher::matches_wildcard("MOTOR_COMM_REAR_LEFT", "MOTOR_COMM_*"));
  EXPECT_FALSE(PatternMatcher::matches_wildcard("SENSOR_COMM_FL", "MOTOR_COMM_*"));
  EXPECT_FALSE(PatternMatcher::matches_wildcard("MOTOR_TIMEOUT", "MOTOR_COMM_*"));
}
TEST_F(PatternMatcherTest, WildcardPrefix) {
  EXPECT_TRUE(PatternMatcher::matches_wildcard("MOTOR_COMM_FL", "*_COMM_FL"));
  EXPECT_TRUE(PatternMatcher::matches_wildcard("SENSOR_COMM_FL", "*_COMM_FL"));
  EXPECT_TRUE(PatternMatcher::matches_wildcard("FRONT_MOTOR_COMM_FL", "*_COMM_FL"));
  EXPECT_FALSE(PatternMatcher::matches_wildcard("MOTOR_COMM_FR", "*_COMM_FL"));
  EXPECT_FALSE(PatternMatcher::matches_wildcard("MOTOR_TIMEOUT_FL", "*_COMM_FL"));
}
TEST_F(PatternMatcherTest, WildcardMiddle) {
  EXPECT_TRUE(PatternMatcher::matches_wildcard("MOTOR_COMM_FL", "MOTOR_*_FL"));
  EXPECT_TRUE(PatternMatcher::matches_wildcard("MOTOR_TIMEOUT_FL", "MOTOR_*_FL"));
  EXPECT_TRUE(PatternMatcher::matches_wildcard("MOTOR_DRIVE_COMM_FL", "MOTOR_*_FL"));
  EXPECT_FALSE(PatternMatcher::matches_wildcard("MOTOR_COMM_FR", "MOTOR_*_FL"));
  EXPECT_FALSE(PatternMatcher::matches_wildcard("SENSOR_COMM_FL", "MOTOR_*_FL"));
}
TEST_F(PatternMatcherTest, MultipleWildcards) {
  EXPECT_TRUE(PatternMatcher::matches_wildcard("MOTOR_COMM_FL", "*_COMM_*"));
  EXPECT_TRUE(PatternMatcher::matches_wildcard("SENSOR_COMM_REAR", "*_COMM_*"));
  EXPECT_TRUE(PatternMatcher::matches_wildcard("A_COMM_B", "*_COMM_*"));
  EXPECT_FALSE(PatternMatcher::matches_wildcard("MOTOR_TIMEOUT_FL", "*_COMM_*"));
}
TEST_F(PatternMatcherTest, WildcardOnly) {
  EXPECT_TRUE(PatternMatcher::matches_wildcard("ANYTHING", "*"));
  EXPECT_TRUE(PatternMatcher::matches_wildcard("", "*"));
  EXPECT_TRUE(PatternMatcher::matches_wildcard("MOTOR_COMM_FL", "*"));
}
TEST_F(PatternMatcherTest, WildcardEdgeCases) {
  // Empty pattern
  EXPECT_FALSE(PatternMatcher::matches_wildcard("MOTOR", ""));
  EXPECT_TRUE(PatternMatcher::matches_wildcard("", ""));
  // Multiple consecutive wildcards
  EXPECT_TRUE(PatternMatcher::matches_wildcard("MOTOR_COMM_FL", "MOTOR**FL"));
  EXPECT_TRUE(PatternMatcher::matches_wildcard("ABC", "***"));
}
TEST_F(PatternMatcherTest, SpecialRegexCharacters) {
  // Ensure regex special characters are escaped
  EXPECT_TRUE(PatternMatcher::matches_wildcard("MOTOR.COMM", "MOTOR.COMM"));
  EXPECT_FALSE(PatternMatcher::matches_wildcard("MOTORXCOMM", "MOTOR.COMM"));  // . should not be regex dot
  EXPECT_TRUE(PatternMatcher::matches_wildcard("MOTOR[1]", "MOTOR[1]"));
  EXPECT_TRUE(PatternMatcher::matches_wildcard("MOTOR+COMM", "MOTOR+COMM"));
  EXPECT_TRUE(PatternMatcher::matches_wildcard("MOTOR?COMM", "MOTOR?COMM"));
}
// ============================================================================
// PatternMatcher class tests
// ============================================================================
TEST_F(PatternMatcherTest, MatchesPatternById) {
  std::map<std::string, FaultPattern> patterns;
  patterns["motor_errors"] = {"motor_errors", {"MOTOR_COMM_*", "MOTOR_TIMEOUT_*"}};
  patterns["sensor_issues"] = {"sensor_issues", {"SENSOR_*"}};
  PatternMatcher matcher(patterns);
  // motor_errors pattern
  EXPECT_TRUE(matcher.matches("MOTOR_COMM_FL", "motor_errors"));
  EXPECT_TRUE(matcher.matches("MOTOR_COMM_FR", "motor_errors"));
  EXPECT_TRUE(matcher.matches("MOTOR_TIMEOUT_DRIVE", "motor_errors"));
  EXPECT_FALSE(matcher.matches("SENSOR_COMM_FL", "motor_errors"));
  // sensor_issues pattern
  EXPECT_TRUE(matcher.matches("SENSOR_LIDAR", "sensor_issues"));
  EXPECT_TRUE(matcher.matches("SENSOR_IMU_TIMEOUT", "sensor_issues"));
  EXPECT_FALSE(matcher.matches("MOTOR_COMM_FL", "sensor_issues"));
  // Unknown pattern
  EXPECT_FALSE(matcher.matches("MOTOR_COMM_FL", "nonexistent"));
}
TEST_F(PatternMatcherTest, MatchesAnyFromList) {
  std::map<std::string, FaultPattern> patterns;  // Empty - not used
  PatternMatcher matcher(patterns);
  std::vector<std::string> codes = {"MOTOR_COMM_*", "DRIVE_*", "ESTOP_001"};
  EXPECT_TRUE(matcher.matches_any("MOTOR_COMM_FL", codes));
  EXPECT_TRUE(matcher.matches_any("DRIVE_FAULT", codes));
  EXPECT_TRUE(matcher.matches_any("ESTOP_001", codes));
  EXPECT_FALSE(matcher.matches_any("SENSOR_TIMEOUT", codes));
  EXPECT_FALSE(matcher.matches_any("ESTOP_002", codes));
}
TEST_F(PatternMatcherTest, FindMatchingPatterns) {
  std::map<std::string, FaultPattern> patterns;
  patterns["motor_errors"] = {"motor_errors", {"MOTOR_*"}};
  patterns["comm_errors"] = {"comm_errors", {"*_COMM_*"}};
  patterns["timeout_errors"] = {"timeout_errors", {"*_TIMEOUT"}};
  PatternMatcher matcher(patterns);
  // MOTOR_COMM_FL matches motor_errors and comm_errors
  auto matches = matcher.find_matching_patterns("MOTOR_COMM_FL");
  EXPECT_EQ(2u, matches.size());
  EXPECT_NE(std::find(matches.begin(), matches.end(), "motor_errors"), matches.end());
  EXPECT_NE(std::find(matches.begin(), matches.end(), "comm_errors"), matches.end());
  // SENSOR_TIMEOUT matches timeout_errors only
  matches = matcher.find_matching_patterns("SENSOR_TIMEOUT");
  EXPECT_EQ(1u, matches.size());
  EXPECT_EQ("timeout_errors", matches[0]);
  // UNKNOWN matches nothing
  matches = matcher.find_matching_patterns("UNKNOWN_ERROR");
  EXPECT_TRUE(matches.empty());
}
TEST_F(PatternMatcherTest, EmptyPatterns) {
  std::map<std::string, FaultPattern> patterns;
  PatternMatcher matcher(patterns);
  EXPECT_FALSE(matcher.matches("MOTOR_COMM_FL", "any_pattern"));
  EXPECT_TRUE(matcher.find_matching_patterns("MOTOR_COMM_FL").empty());
}
TEST_F(PatternMatcherTest, PatternWithNoCodes) {
  std::map<std::string, FaultPattern> patterns;
  patterns["empty_pattern"] = {"empty_pattern", {}};  // No codes
  PatternMatcher matcher(patterns);
  EXPECT_FALSE(matcher.matches("MOTOR_COMM_FL", "empty_pattern"));
}
TEST_F(PatternMatcherTest, ExactMatchPerformance) {
  // Exact matches should be fast (no regex)
  std::map<std::string, FaultPattern> patterns;
  patterns["exact"] = {"exact", {"MOTOR_COMM_FL", "MOTOR_COMM_FR", "MOTOR_COMM_RL", "MOTOR_COMM_RR"}};
  PatternMatcher matcher(patterns);
  // These should use fast string comparison, not regex
  EXPECT_TRUE(matcher.matches("MOTOR_COMM_FL", "exact"));
  EXPECT_TRUE(matcher.matches("MOTOR_COMM_FR", "exact"));
  EXPECT_FALSE(matcher.matches("MOTOR_COMM_FRONT", "exact"));
}
TEST_F(PatternMatcherTest, MixedExactAndWildcard) {
  std::map<std::string, FaultPattern> patterns;
  patterns["mixed"] = {"mixed", {"ESTOP_001", "MOTOR_*", "SENSOR_LIDAR"}};
  PatternMatcher matcher(patterns);
  EXPECT_TRUE(matcher.matches("ESTOP_001", "mixed"));     // Exact
  EXPECT_TRUE(matcher.matches("MOTOR_COMM", "mixed"));    // Wildcard
  EXPECT_TRUE(matcher.matches("SENSOR_LIDAR", "mixed"));  // Exact
  EXPECT_FALSE(matcher.matches("ESTOP_002", "mixed"));
  EXPECT_FALSE(matcher.matches("SENSOR_IMU", "mixed"));
}
int main(int argc, char ** argv) {
  ::testing::InitGoogleTest(&argc, argv);
  return RUN_ALL_TESTS();
}

#include "ARM.h"
#include "ARMMachineFunctionInfo.h"
#include "ARMSubtarget.h"
#include "MCTargetDesc/ARMBaseInfo.h"
#include "Thumb2InstrInfo.h"
#include "llvm/ADT/SmallVector.h"
#include "llvm/ADT/Statistic.h"
#include "llvm/ADT/StringRef.h"
#include "llvm/CodeGen/MachineBasicBlock.h"
#include "llvm/CodeGen/MachineFunction.h"
#include "llvm/CodeGen/MachineFunctionPass.h"
#include "llvm/CodeGen/MachineInstr.h"
#include "llvm/CodeGen/MachineInstrBuilder.h"
#include "llvm/CodeGen/MachineInstrBundle.h"
#include "llvm/CodeGen/MachineOperand.h"
#include "llvm/IR/DebugLoc.h"
#include "llvm/MC/MCInstrDesc.h"
#include "llvm/MC/MCRegisterInfo.h"
#include "llvm/Support/Debug.h"
#include <cassert>
#include <new>
using namespace llvm;
#define DEBUG_TYPE "arm-mve-vpt"
namespace {
class MVEVPTBlock : public MachineFunctionPass {
public:
  static char ID;
  const Thumb2InstrInfo *TII;
  const TargetRegisterInfo *TRI;
  MVEVPTBlock() : MachineFunctionPass(ID) {}
  bool runOnMachineFunction(MachineFunction &Fn) override;
  MachineFunctionProperties getRequiredProperties() const override {
    return MachineFunctionProperties().set(
        MachineFunctionProperties::Property::NoVRegs);
  }
  StringRef getPassName() const override {
    return "MVE VPT block insertion pass";
  }
private:
  bool InsertVPTBlocks(MachineBasicBlock &MBB);
};
char MVEVPTBlock::ID = 0;
} // end anonymous namespace
INITIALIZE_PASS(MVEVPTBlock, DEBUG_TYPE, "ARM MVE VPT block pass", false, false)
static MachineInstr *findVCMPToFoldIntoVPST(MachineBasicBlock::iterator MI,
                                            const TargetRegisterInfo *TRI,
                                            unsigned &NewOpcode) {
  // Search backwards to the instruction that defines VPR. This may or not
  // be a VCMP, we check that after this loop. If we find another instruction
  // that reads cpsr, we return nullptr.
  MachineBasicBlock::iterator CmpMI = MI;
  while (CmpMI != MI->getParent()->begin()) {
    --CmpMI;
    if (CmpMI->modifiesRegister(ARM::VPR, TRI))
      break;
    if (CmpMI->readsRegister(ARM::VPR, TRI))
      break;
  }
  if (CmpMI == MI)
    return nullptr;
  NewOpcode = VCMPOpcodeToVPT(CmpMI->getOpcode());
  if (NewOpcode == 0)
    return nullptr;
  // Search forward from CmpMI to MI, checking if either register was def'd
  if (registerDefinedBetween(CmpMI->getOperand(1).getReg(), std::next(CmpMI),
                             MI, TRI))
    return nullptr;
  if (registerDefinedBetween(CmpMI->getOperand(2).getReg(), std::next(CmpMI),
                             MI, TRI))
    return nullptr;
  return &*CmpMI;
}
// Advances Iter past a block of predicated instructions.
// Returns true if it successfully skipped the whole block of predicated
// instructions. Returns false when it stopped early (due to MaxSteps), or if
// Iter didn't point to a predicated instruction.
static bool StepOverPredicatedInstrs(MachineBasicBlock::instr_iterator &Iter,
                                     MachineBasicBlock::instr_iterator EndIter,
                                     unsigned MaxSteps,
                                     unsigned &NumInstrsSteppedOver) {
  ARMVCC::VPTCodes NextPred = ARMVCC::None;
  Register PredReg;
  NumInstrsSteppedOver = 0;
  while (Iter != EndIter) {
    if (Iter->isDebugInstr()) {
      // Skip debug instructions
      ++Iter;
      continue;
    }
    NextPred = getVPTInstrPredicate(*Iter, PredReg);
    assert(NextPred != ARMVCC::Else &&
           "VPT block pass does not expect Else preds");
    if (NextPred == ARMVCC::None || MaxSteps == 0)
      break;
    --MaxSteps;
    ++Iter;
    ++NumInstrsSteppedOver;
  };
  return NumInstrsSteppedOver != 0 &&
         (NextPred == ARMVCC::None || Iter == EndIter);
}
// Returns true if at least one instruction in the range [Iter, End) defines
// or kills VPR.
static bool IsVPRDefinedOrKilledByBlock(MachineBasicBlock::iterator Iter,
                                        MachineBasicBlock::iterator End) {
  for (; Iter != End; ++Iter)
    if (Iter->definesRegister(ARM::VPR) || Iter->killsRegister(ARM::VPR))
      return true;
  return false;
}
// Creates a T, TT, TTT or TTTT BlockMask depending on BlockSize.
static ARM::PredBlockMask GetInitialBlockMask(unsigned BlockSize) {
  switch (BlockSize) {
  case 1:
    return ARM::PredBlockMask::T;
  case 2:
    return ARM::PredBlockMask::TT;
  case 3:
    return ARM::PredBlockMask::TTT;
  case 4:
    return ARM::PredBlockMask::TTTT;
  default:
    llvm_unreachable("Invalid BlockSize!");
  }
}
// Given an iterator (Iter) that points at an instruction with a "Then"
// predicate, tries to create the largest block of continuous predicated
// instructions possible, and returns the VPT Block Mask of that block.
//
// This will try to perform some minor optimization in order to maximize the
// size of the block.
static ARM::PredBlockMask
CreateVPTBlock(MachineBasicBlock::instr_iterator &Iter,
               MachineBasicBlock::instr_iterator EndIter,
               SmallVectorImpl<MachineInstr *> &DeadInstructions) {
  MachineBasicBlock::instr_iterator BlockBeg = Iter;
  (void)BlockBeg;
  assert(getVPTInstrPredicate(*Iter) == ARMVCC::Then &&
         "Expected a Predicated Instruction");
  LLVM_DEBUG(dbgs() << "VPT block created for: "; Iter->dump());
  unsigned BlockSize;
  StepOverPredicatedInstrs(Iter, EndIter, 4, BlockSize);
  LLVM_DEBUG(for (MachineBasicBlock::instr_iterator AddedInstIter =
                      std::next(BlockBeg);
                  AddedInstIter != Iter; ++AddedInstIter) {
    if (AddedInstIter->isDebugInstr())
      continue;
    dbgs() << "  adding: ";
    AddedInstIter->dump();
  });
  // Generate the initial BlockMask
  ARM::PredBlockMask BlockMask = GetInitialBlockMask(BlockSize);
  // Remove VPNOTs while there's still room in the block, so we can make the
  // largest block possible.
  ARMVCC::VPTCodes CurrentPredicate = ARMVCC::Else;
  while (BlockSize < 4 && Iter != EndIter &&
         Iter->getOpcode() == ARM::MVE_VPNOT) {
    // Try to skip all of the predicated instructions after the VPNOT, stopping
    // after (4 - BlockSize). If we can't skip them all, stop.
    unsigned ElseInstCnt = 0;
    MachineBasicBlock::instr_iterator VPNOTBlockEndIter = std::next(Iter);
    if (!StepOverPredicatedInstrs(VPNOTBlockEndIter, EndIter, (4 - BlockSize),
                                  ElseInstCnt))
      break;
    // Check if this VPNOT can be removed or not: It can only be removed if at
    // least one of the predicated instruction that follows it kills or sets
    // VPR.
    if (!IsVPRDefinedOrKilledByBlock(Iter, VPNOTBlockEndIter))
      break;
    LLVM_DEBUG(dbgs() << "  removing VPNOT: "; Iter->dump());
    // Record the new size of the block
    BlockSize += ElseInstCnt;
    assert(BlockSize <= 4 && "Block is too large!");
    // Record the VPNot to remove it later.
    DeadInstructions.push_back(&*Iter);
    ++Iter;
    // Replace the predicates of the instructions we're adding.
    // Note that we are using "Iter" to iterate over the block so we can update
    // it at the same time.
    for (; Iter != VPNOTBlockEndIter; ++Iter) {
      if (Iter->isDebugInstr())
        continue;
      // Find the register in which the predicate is
      int OpIdx = findFirstVPTPredOperandIdx(*Iter);
      assert(OpIdx != -1);
      // Change the predicate and update the mask
      Iter->getOperand(OpIdx).setImm(CurrentPredicate);
      BlockMask = expandPredBlockMask(BlockMask, CurrentPredicate);
      LLVM_DEBUG(dbgs() << "  adding : "; Iter->dump());
    }
    CurrentPredicate =
        (CurrentPredicate == ARMVCC::Then ? ARMVCC::Else : ARMVCC::Then);
  }
  return BlockMask;
}
bool MVEVPTBlock::InsertVPTBlocks(MachineBasicBlock &Block) {
  bool Modified = false;
  MachineBasicBlock::instr_iterator MBIter = Block.instr_begin();
  MachineBasicBlock::instr_iterator EndIter = Block.instr_end();
  SmallVector<MachineInstr *, 4> DeadInstructions;
  while (MBIter != EndIter) {
    MachineInstr *MI = &*MBIter;
    Register PredReg;
    DebugLoc DL = MI->getDebugLoc();
    ARMVCC::VPTCodes Pred = getVPTInstrPredicate(*MI, PredReg);
    // The idea of the predicate is that None, Then and Else are for use when
    // handling assembly language: they correspond to the three possible
    // suffixes "", "t" and "e" on the mnemonic. So when instructions are read
    // from assembly source or disassembled from object code, you expect to
    // see a mixture whenever there's a long VPT block. But in code
    // generation, we hope we'll never generate an Else as input to this pass.
    assert(Pred != ARMVCC::Else && "VPT block pass does not expect Else preds");
    if (Pred == ARMVCC::None) {
      ++MBIter;
      continue;
    }
    ARM::PredBlockMask BlockMask =
        CreateVPTBlock(MBIter, EndIter, DeadInstructions);
    // Search back for a VCMP that can be folded to create a VPT, or else
    // create a VPST directly
    MachineInstrBuilder MIBuilder;
    unsigned NewOpcode;
    LLVM_DEBUG(dbgs() << "  final block mask: " << (unsigned)BlockMask << "\n");
    if (MachineInstr *VCMP = findVCMPToFoldIntoVPST(MI, TRI, NewOpcode)) {
      LLVM_DEBUG(dbgs() << "  folding VCMP into VPST: "; VCMP->dump());
      MIBuilder = BuildMI(Block, MI, DL, TII->get(NewOpcode));
      MIBuilder.addImm((uint64_t)BlockMask);
      MIBuilder.add(VCMP->getOperand(1));
      MIBuilder.add(VCMP->getOperand(2));
      MIBuilder.add(VCMP->getOperand(3));
      // We need to remove any kill flags between the original VCMP and the new
      // insertion point.
      for (MachineInstr &MII :
           make_range(VCMP->getIterator(), MI->getIterator())) {
        MII.clearRegisterKills(VCMP->getOperand(1).getReg(), TRI);
        MII.clearRegisterKills(VCMP->getOperand(2).getReg(), TRI);
      }
      VCMP->eraseFromParent();
    } else {
      MIBuilder = BuildMI(Block, MI, DL, TII->get(ARM::MVE_VPST));
      MIBuilder.addImm((uint64_t)BlockMask);
    }
    // Erase all dead instructions (VPNOT's). Do that now so that they do not
    // mess with the bundle creation.
    for (MachineInstr *DeadMI : DeadInstructions)
      DeadMI->eraseFromParent();
    DeadInstructions.clear();
    finalizeBundle(
        Block, MachineBasicBlock::instr_iterator(MIBuilder.getInstr()), MBIter);
    Modified = true;
  }
  return Modified;
}
bool MVEVPTBlock::runOnMachineFunction(MachineFunction &Fn) {
  const ARMSubtarget &STI = Fn.getSubtarget<ARMSubtarget>();
  if (!STI.isThumb2() || !STI.hasMVEIntegerOps())
    return false;
  TII = static_cast<const Thumb2InstrInfo *>(STI.getInstrInfo());
  TRI = STI.getRegisterInfo();
  LLVM_DEBUG(dbgs() << "********** ARM MVE VPT BLOCKS **********\n"
                    << "********** Function: " << Fn.getName() << '\n');
  bool Modified = false;
  for (MachineBasicBlock &MBB : Fn)
    Modified |= InsertVPTBlocks(MBB);
  LLVM_DEBUG(dbgs() << "**************************************\n");
  return Modified;
}
/// createMVEVPTBlock - Returns an instance of the MVE VPT block
/// insertion pass.
FunctionPass *llvm::createMVEVPTBlockPass() { return new MVEVPTBlock(); }

