    case argoFan_t::FAN_MEDIUM:
    case argoFan_t::FAN_LOW:
    case argoFan_t::FAN_LOWER:
    case argoFan_t::FAN_LOWEST:
      _.Fan = static_cast<uint8_t>(fan);
      break;
    default:
      _.Fan = static_cast<uint8_t>(argoFan_t::FAN_AUTO);
