  switch (mode) {
    case argoMode_t::COOL: return stdAc::opmode_t::kCool;
    case argoMode_t::DRY : return stdAc::opmode_t::kDry;
    case argoMode_t::FAN : return stdAc::opmode_t::kFan;
    case argoMode_t::HEAT : return stdAc::opmode_t::kHeat;
