{
    CUDA_EXTERNAL_MEMORY_BUFFER_DESC desc = {};
    desc.offset = offset;
    desc.size = size;
    CUdeviceptr ptr = 0;
    SGL_CU_CHECK(cuExternalMemoryGetMappedBuffer(&ptr, ext_mem, &desc));
    return reinterpret_cast<void*>(ptr);
}
