    NativeHandle shared_handle = fence->shared_handle();
    SGL_CHECK(shared_handle, "Fence shared handle creation failed.");
    CUDA_EXTERNAL_SEMAPHORE_HANDLE_DESC desc = {};
    switch (fence->device()->type()) {
#if SGL_WINDOWS
