		SetState(SNM_INT_STATE_INITIALISE_FAILED);
		return;
	}
	SetState(SNM_INT_STATE_SIGNING_IN);
	// 	AttemptPSNSignIn(NULL, NULL);
	// 	SonyHttp::init();
