void SQRNetworkManager_Vita::ProcessJoinablePresenceData()
{
	static SceNpBasicGamePresence presenceDetails;
	int ret = sceNpBasicGetGamePresenceOfFriend(&m_joinablePresenceParam.npId, &presenceDetails);
	if( ret == 0 )
	{
