END_PROPSYNCS
BEGIN_SAVES(TransConstraint)
    SAVE_REVS(4, 0)
    SAVE_SUPERCLASS(Hmx::Object)
    SAVE_SUPERCLASS(RndPollable)
    SAVE_SUPERCLASS(RndHighlightable)
    bs << mParent;
    bs << mChild;
    bs << mStaticCube;
    for (int i = 0; i < 3; i++) {
        bs << mTracks[i];
    }
    bs << mSpeed;
    bs << mAffectScale;
    bs << mUseUITime;
END_SAVES
BEGIN_COPYS(TransConstraint)
    COPY_SUPERCLASS(Hmx::Object)
    COPY_SUPERCLASS(RndPollable)
    COPY_SUPERCLASS(RndHighlightable)
    CREATE_COPY(TransConstraint)
    BEGIN_COPYING_MEMBERS
        COPY_MEMBER(mParent)
        COPY_MEMBER(mChild)
        COPY_MEMBER(mStaticCube)
        for (int i = 0; i < 3; i++) {
            COPY_MEMBER(mTracks[i])
        }
        COPY_MEMBER(mSpeed)
        COPY_MEMBER(mAffectScale)
        COPY_MEMBER(mUseUITime)
    END_COPYING_MEMBERS
END_COPYS
INIT_REVS(4, 0)
BEGIN_LOADS(TransConstraint)
    LOAD_REVS(bs)
    ASSERT_REVS(4, 0)
    LOAD_SUPERCLASS(Hmx::Object)
    LOAD_SUPERCLASS(RndPollable)
    LOAD_SUPERCLASS(RndHighlightable)
    bs >> mParent;
    bs >> mChild;
    bs >> mStaticCube;
    for (int i = 0; i < 3; i++) {
        d >> mTracks[i];
    }
    if (d.rev > 0) {
        bs >> mSpeed;
    }
    if (d.rev > 1) {
        if (d.rev <= 3) {
            bool b;
            d >> b;
        }
        d >> mAffectScale;
    }
    if (d.rev > 2) {
        d >> mUseUITime;
    }
END_LOADS
void TransConstraint::Enter() {
    RndPollable::Enter();
    SnapToParent();
}
void TransConstraint::SetScaleVectorOnTransform(RndTransformable *trans, Vector3 &v) {
    MILO_ASSERT(trans, 0x80);
    Vector3 va0;
    Hmx::Matrix3 m90;
    Transform tf60 = trans->WorldXfm();
    MakeEuler(tf60.m, va0);
    MakeRotMatrix(va0, m90, true);
    Scale(m90, v, m90);
    tf60.m = m90;
    trans->SetWorldXfm(tf60);
}
void TransConstraint::SnapToParent() {
    if (mParent && mChild) {
        Vector3 v50 = mParent->WorldXfm().v;
        Vector3 v70 = mChild->WorldXfm().v;
        for (int i = 0; i < 3; i++) {
            if (mTracks[i]) {
                v70[i] = v50[i];
            }
        }
        mChild->SetWorldPos(v70);
        if (mAffectScale) {
            Vector3 v40;
            MakeScale(mParent->WorldXfm().m, v40);
            Vector3 v60;
            MakeScale(mChild->WorldXfm().m, v60);
            for (int i = 0; i < 3; i++) {
                if (mTracks[i]) {
                    v60[i] = v40[i];
                }
            }
            SetScaleVectorOnTransform(mChild, v60);
        }
    }
}

#include <iostream>
#include <vector>
#include <string>
#include <set>
#include <algorithm>
// Function to solve a single test case
void solve() {
    int n;
    std::cin >> n;
    std::set<std::string> found_words;
    // Iterate through all possible starting letters
    for (char c = 'a'; c <= 'z'; ++c) {
        if (found_words.size() == n) {
            break;
        }
        std::string prefix(1, c);
        int k_to_ask = 1;
        // Exponentially probe for the number of words with the current prefix
        while (true) {
            if (found_words.size() == n) {
                break;
            }
            std::cout << "query " << prefix << " " << k_to_ask << std::endl;
            int k_returned;
            std::cin >> k_returned;
            for (int i = 0; i < k_returned; ++i) {
                std::string word;
                std::cin >> word;
                found_words.insert(word);
            }
            if (k_returned < k_to_ask) {
                // If fewer words are returned than requested, we have found all for this prefix
                break;
            }

            if (k_to_ask == n) {
                // If we ask for n and get n, we must have all words for this prefix
                // as there are only n words in total.
                break;
            }
            // Double the number of words to ask for in the next query
            k_to_ask *= 2;
            if (k_to_ask > n) {
                k_to_ask = n;
            }
        }
    }
    // Output the final answer
    std::cout << "answer";
    for (const auto& word : found_words) {
        std::cout << " " << word;
    }
    std::cout << std::endl;
}
int main() {
    // Fast I/O
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(NULL);
    int t;
    std::cin >> t;
    while (t--) {
        solve();
    }
    return 0;
}

