  ASSERT_NEAR(quaternion.getX(), 0, 0.005);
  ASSERT_NEAR(quaternion.getY(), 0.2588, 0.005);
  ASSERT_NEAR(quaternion.getZ(), 0, 0.005);
  ASSERT_NEAR(quaternion.getW(), 0.9659, 0.005);
