  eulerAngles = result.getRotateInEulerYPB();
  // expected the value
  ASSERT_NEAR(toDeg(eulerAngles.getX()), 0, 0.001);
  ASSERT_NEAR(toDeg(eulerAngles.getY()), 0, 0.001);
  ASSERT_NEAR(toDeg(eulerAngles.getZ()), 23, 0.001);
}

