    TelemInfoV01 data = CreateBasicTestTelemetry(20.0, 0.20);
    data.mSteeringShaftTorque = 20.0;

    double force = 0.0;
    for (int i = 0; i < FILTER_SETTLING_FRAMES; i++) force = engine.calculate_force(&data);

