EnderCrystalModel::EnderCrystalModel(float g) 
{
	glass = new ModelPart(this, L"glass");
	glass->texOffs(0, 0)->addBox(-4, -4, -4, 8, 8, 8);
	cube = new ModelPart(this, L"cube");
	cube->texOffs(32, 0)->addBox(-4, -4, -4, 8, 8, 8);
