// Main function to generate and store 2D data in HDF5 format
int main(void)
{
    int nrow = 5;
    int ncol = 4;

    vector<vector<double>> vec2d;
    vec2d.resize(nrow, vector<double>(ncol, 0.0));

    srand((unsigned)time(0));

    typename vector<vector<double>>::iterator row;
    typename vector<double>::iterator col;

    // Fill and print the 2D vector
    for (row = vec2d.begin(); row != vec2d.end(); row++)
    {
        cout << endl;
        for (col = row->begin(); col != row->end(); col++)
        {
            *col = (rand() / (RAND_MAX + 1.0));
            cout << *col << '\t';
        }
    }
    cout << endl;

    // Convert 2D vector to 1D vector for HDF5 storage
    vector<double> flatVec(nrow * ncol);
    for (int i = 0; i < nrow; ++i)
    {
        for (int j = 0; j < ncol; ++j)
        {
            flatVec[i * ncol + j] = vec2d[i][j];
        }
    }

    // Create HDF5 file and dataset
    H5File file("test.h5", H5F_ACC_TRUNC);

    hsize_t dimsf[2];
    dimsf[0] = nrow;
    dimsf[1] = ncol;
    DataSpace dataspace(2, dimsf);

    DataType datatype(H5::PredType::NATIVE_DOUBLE);
    DataSet dataset = file.createDataSet("data", datatype, dataspace);

    dataset.write(flatVec.data(), H5::PredType::NATIVE_DOUBLE);

    cout << endl << " vec2d has " << endl;
    for (row = vec2d.begin(); row != vec2d.end(); row++)
    {
        cout << endl;
        for (col = row->begin(); col != row->end(); col++)
        {
            cout << *col << '\t';
        }
    }
    cout << endl;

    dataset.close();
    dataspace.close();
    file.close();

    return 0;
}

#include <clang-c/Index.h>
#include <graphviz/graphviz.h>

// Traverses the AST and builds a graph representation
void traverseAST(CXTranslationUnit tu, CXCursor cursor, Agraph_t* graph, Agnode_t* parent)
{
    CXCursorKind kind = clang_getCursorKind(cursor);
    CXString spelling = clang_getCursorSpelling(cursor);
    const char* name = clang_getCString(spelling);

    Agnode_t* node = agnode(graph, name, 1);
    if (parent) {
        agedge(graph, parent, node, 0, 1);
    }

    clang_disposeString(spelling);

    // Handle function declarations and C++ methods
    if (kind == CXCursor_FunctionDecl || kind == CXCursor_CXXMethod) {
        CXCursor child = clang_getCursorDefinition(cursor);
        while (child.kind != CXCursor_InvalidFile) {
            traverseAST(tu, child, graph, node);
            child = clang_getCursorLexicalParent(child);
        }
    }
    // Handle compound statements (blocks of code)
    else if (kind == CXCursor_CompoundStmt) {
        CXChildVisitResult result = CXChildVisit_Continue;
        clang_visitChildren(cursor, [](CXCursor c, CXCursor parent, CXClientData client_data) {
            Agraph_t* graph = (Agraph_t*)client_data;
            traverseAST(clang_Cursor_getTranslationUnit(parent), c, graph, (Agnode_t*)client_data);
            return CXChildVisit_Continue;
        }, node);
    }
    // Handle control flow statements: if, while, for
    else if (kind == CXCursor_IfStmt || kind == CXCursor_WhileStmt || kind == CXCursor_ForStmt) {
        CXChildVisitResult result = CXChildVisit_Continue;
        clang_visitChildren(cursor, [](CXCursor c, CXCursor parent, CXClientData client_data) {
            Agraph_t* graph = (Agraph_t*)client_data;
            traverseAST(clang_Cursor_getTranslationUnit(parent), c, graph, (Agnode_t*)client_data);
            return CXChildVisit_Continue;
        }, node);
    }
}

int main()
{
    const char* code = R"code(
        int factorial(int n) {
            if (n == 0) {
                return 1;
            } else {
                return n * factorial(n - 1);
            }
        }

        int main() {
            int num = 5;
            int result = factorial(num);
            std::cout << "Factorial of " << num << " is " << result << std::endl;
            return 0;
        }
    )code";

    // Create Clang index and parse translation unit
    CXIndex index = clang_createIndex(0, 0);
    CXTranslationUnit tu = clang_parseTranslationUnit(index, 0, 0, 0, 0, 0, CXTranslationUnit_None);

    // Set up unsaved file for parsing
    CXUnsavedFile unsavedFile = { "factorial.cpp", code, strlen(code) };
    clang_reparseTranslationUnit(tu, 1, &unsavedFile, CXReparse_None);

    // Get root cursor and create Graphviz graph
    CXCursor cursor = clang_getTranslationUnitCursor(tu);
    Agraph_t* graph = agopen("Algorithm Execution Flow", Agdirected, 0);
    traverseAST(tu, cursor, graph, 0);

    // Output graph in DOT format
    agwrite(graph, stdout);
    agclose(graph);
    clang_disposeTranslationUnit(tu);
    clang_disposeIndex(index);

    return 0;
}

#include <vector>
#include <string>
#include <sstream>
#include <regex>

// Token structure for assembly parsing
struct Token {
    std::string type; // "LABEL", "INSTRUCTION", "REGISTER", "IMMEDIATE", "LABEL_REF"
    std::string value;
};

// Tokenizes a single line of assembly code
std::vector<Token> tokenize(const std::string& line)
{
    std::vector<Token> tokens;
    std::regex token_regex(R"((\w+):|(\w+)|(\$?\w+)|(-?\d+))");
    std::smatch matches;

    std::string::const_iterator searchStart(line.cbegin());
    while (std::regex_search(searchStart, line.cend(), matches, token_regex))
    {
        if (matches[1].matched) {
            tokens.push_back({"LABEL", matches[1]});
        } else if (matches[2].matched) {
            tokens.push_back({"INSTRUCTION", matches[2]});
        } else if (matches[3].matched) {
            tokens.push_back({"REGISTER", matches[3]});
        } else if (matches[4].matched) {
            tokens.push_back({"IMMEDIATE", matches[4]});
        }
        searchStart = matches.suffix().first;
    }

    return tokens;
}

