#include <atomic>

using u64 = unsigned long long;

// Bucket structure for storing leaves
struct Bucket {
    u64 mLeaves[16] = {};
};

// BucketMap manages atomic access to buckets
struct BucketMap {
    // Acquires an index atomically
    u64 acquire() noexcept {
        while (true) {
            u64 map = mData.load(std::memory_order_relaxed);

            u64 index = (map & 1) ? 1 : 0;
            auto mask = u64(1) << index;

            auto previous =
                mData.fetch_or(mask, std::memory_order_relaxed);
            if ((previous & mask) == 0) {
                return index;
            }
        }
    }

    // Acquires a bucket (noinline hint)
    __attribute__((noinline)) Bucket acquireBucket() noexcept {
        acquire();
        return Bucket();
    }

    std::atomic<u64> mData{ 1 };
};

// Main function
int main()
{
    BucketMap map;
    map.acquireBucket();
    return 0;
}

#include "greenwald_khanna.h"

// Calculates percentiles using Greenwald-Khanna algorithm
std::vector<double> CalculatePercentiles(const std::vector<double>& data, const std::vector<double>& percentiles, double epsilon)
{
    greenwald_khanna<double> gk(epsilon);
    for(double value : data)
    {
        gk.insert(value);
    }
    // Compute quantiles for each percentile
    std::vector<double> results;
    for(double percentile : percentiles)
    {
        results.push_back(gk.quantile(percentile));
    }
    return results;

}

