// Syscall wrapper function
template<typename RetType, typename... Args>
RetType syscall(uint32_t syscall_number, Args... args)
{
    uint32_t arg0 = (uint32_t)(args)[0];
    uint32_t arg1 = (uint32_t)(args)[1];
    uint32_t arg2 = (uint32_t)(args)[2];
    uint32_t arg3 = (uint32_t)(args)[3];

    RetType result;
    asm volatile(
        "swi 0"
        : "=r"(result)
        : "r"(syscall_number), "r"(arg0), "r"(arg1), "r"(arg2), "r"(arg3)
        : "r0", "r1", "r2", "r3", "memory"
    );
    return result;

}

