// Function to find the smallest missing positive integer
int findMissingPositive(vector<int>& nums)
{
    int n = nums.size();

    // Step 1: Replace all non-positive numbers with n + 1
    for(int i=0;i<n;++i)
    {
        if(nums[i]<=0)
        {
            nums[i] = n+1;
        }
    }

    // Step 2: Mark the presence of elements
    for(int i=0;i<n;++i)
    {
        int num = abs(nums[i]);
        if(num<=n)
        {
            nums[num-1] = -abs(nums[num-1]);
        }
    }

    // Step 3: Find the first positive number
    for(int i=0;i<n;++i)
    {
        if(nums[i]>0)
        {
            return i+1;
        }
    }

    // If all numbers are negative, return n + 1
    return n+1;
}

int main()
{
    vector<int> nums = {3,4,-1,1};
    int missing = findMissingPositive(nums);
    cout<<"The smallest missing positive integer is: "<<missing<<endl;
    return 0;

}

