using namespace std;

// Check if character is an operator
bool isOperator(char c)
{
    return c == '+' || c == '-' || c == '*' || c == '/';
}

// Apply operator to two operands
int applyOperator(int a, int b, char op)
{
    switch (op)
    {
        case '+': return a + b;
        case '-': return a - b;
        case '*': return a * b;
        case '/': 
            if (b == 0)
            {
                cout << "Error: Division by zero" << endl;
                exit(1);
            }
            return a / b;
        default: 
            cout << "Error: Unknown operator" << endl;
            exit(1);
    }
}

// Evaluate postfix expression
int evaluatePostfixExpression(const string& expression)
{
    stack<int> stack;
    stringstream ss(expression);
    string token;

    while (ss >> token)
    {
        if (isOperator(token[0]) && token.length() == 1)
        {
            if (stack.size() < 2)
            {
                cout << "Error: Invalid expression" << endl;
                exit(1);
            }
            int b = stack.top(); stack.pop();
            int a = stack.top(); stack.pop();
            int result = applyOperator(a, b, token[0]);
            stack.push(result);
        } else {
            try {
                int value = stoi(token);
                stack.push(value);
            } catch (const invalid_argument& e) {
                cout << "Error: Invalid operand" << endl;
                exit(1);
            }
        }
    }

    if (stack.size() != 1)
    {
        cout << "Error: Invalid expression" << endl;
        exit(1);
    }

    return stack.top();
}

// Main function
int main()
{
    string expression;
    cout << "Enter a postfix expression: ";
    getline(cin, expression);

    int result = evaluatePostfixExpression(expression);
    cout << "The result is: " << result << endl;

    return 0;
}

__global__ void simple_copy(float *outdata, const float *indata)
{
    // Calculate global coordinates
    int x = blockIdx.x * TILE_DIM + threadIdx.x;
    int y = blockIdx.y * TILE_DIM + threadIdx.y;
    int width = gridDim.x * TILE_DIM;

    // Inline assembly for memory copy
    asm(".reg .u32 idx, idx2, offset, base_addr, base_addr2;\n"
        "mov.u32 idx, %1;\n"
        "mov.u32 idx2, %2;\n"
        "mov.u32 offset, %3;\n"
        "mov.u32 base_addr, %4;\n"
        "mov.u32 base_addr2, %5;\n"
        "shl.b32 offset, offset, 2;\n"
        "add.u32 base_addr, base_addr, offset;\n"
        "add.u32 base_addr2, base_addr2, offset;\n"
        "ld.global.f32 %0, [base_addr];\n"
        "st.global.f32 [base_addr2], %0;\n"
        : "=f"(outdata[y * width + x])
        : "r"(y * width + x), "r"(sizeof(float)), "r"(indata), "r"(outdata)
        : "idx", "idx2", "offset", "base_addr", "base_addr2"
    );
}

#include <condition_variable>
#include <mutex>

// CountDownLatch implementation
class CountDownLatch {
public:
    // Constructor with count
    explicit CountDownLatch(size_t count) : _count(count) {}

    // Wait until count reaches zero
    void wait()
    {
        std::unique_lock<std::mutex> lock(_mutex);
        _cond_var.wait(lock, [this] { return _count == 0; });
    }

    // Decrease the count
    void count_down()
    {
        std::unique_lock<std::mutex> lock(_mutex);
        if (_count > 0)
        {
            --_count;
            if (_count == 0)
            {
                _cond_var.notify_all();
            }
        }
    }

private:
    size_t _count;
    std::mutex _mutex;
    std::condition_variable _cond_var;
};

