// Acquires an index by atomically setting a bit
u64 acquire() noexcept
{
    while(true)
    {
        u64 map = mData;

        // Determine which bit to set: prefer bit 1 if set, otherwise bit 0
        u64 index = (map & 1) ? 1 : 0;
        auto mask = u64(1) << index;

        // Atomically set the bit and get previous value
        auto previous =
            __atomic_fetch_or(&mData, mask, __ATOMIC_SEQ_CST);

        // Check if the bit was already set in previous value
        if((previous & mask) == 0)
        {
            return index;
        }
    }
}

