// Student class definition
class Student {
public:
    std::string name;
    int age;
    std::string course;
    char grade;
    float gpa;

    // Constructor with validation
    Student(const std::string& name, int age, const std::string& course, char grade, float gpa)
        : name(name), age(age), course(course), grade(grade), gpa(gpa) {
        validate();
    }

    // Update student information
    void update(int age, const std::string& course, char grade, float gpa) {
        this->age = age;
        this->course = course;
        this->grade = grade;
        this->gpa = gpa;
        validate();
    }

private:
    // Validation method
    void validate() {
        if (name.length() < 2 || name.length() > 50) {
            throw std::invalid_argument("Name length must be between 2 and 50 characters.");
        }
        if (age < 18 || age > 35) {
            throw std::invalid_argument("Age must be between 18 and 35.");
        }
        if (course.length() < 5 || course.length() > 100) {
            throw std::invalid_argument("Course length must be between 5 and 100 characters.");
        }
        if (grade != 'A' && grade != 'B' && grade != 'C' && grade != 'D' && grade != 'F') {
            throw std::invalid_argument("Grade must be one of 'A', 'B', 'C', 'D', or 'F'.");
        }
        if (gpa < 0.0 || gpa > 4.0) {
            throw std::invalid_argument("GPA must be between 0.0 and 4.0.");
        }
    }
};

// Student database class
class StudentDatabase {
private:
    std::map<std::string, Student> students;

public:
    // Add a new student
    void addStudent(const std::string& name, int age, const std::string& course, char grade, float gpa) {
        if (students.find(name) != students.end()) {
            throw std::runtime_error("Student with this name already exists.");
        }
        students[name] = Student(name, age, course, grade, gpa);
    }

    // Update existing student
    void updateStudent(const std::string& name, int age, const std::string& course, char grade, float gpa) {
        auto it = students.find(name);
        if (it == students.end()) {
            throw std::runtime_error("Student not found.");
        }
        it->second.update(age, course, grade, gpa);
    }

    // Get student by name
    Student getStudent(const std::string& name) const {
        auto it = students.find(name);
        if (it == students.end()) {
            throw std::runtime_error("Student not found.");
        }
        return it->second;
    }
};

// Main function
int main()
{
    StudentDatabase db;

    try {
        db.addStudent("Alice", 22, "Computer Science", 'A', 3.9);
        db.addStudent("Bob", 20, "Mathematics", 'B', 3.5);
        db.addStudent("Charlie", 21, "Physics", 'C', 3.0);

        db.updateStudent("Alice", 23, "Computer Science", 'A', 3.8);

        Student alice = db.getStudent("Alice");
        std::cout << "Name: " << alice.name << ", Age: " << alice.age << ", Course: " << alice.course
                  << ", Grade: " << alice.grade << ", GPA: " << alice.gpa << std::endl;

    } catch (const std::exception& e) {
        std::cerr << "Error: " << e.what() << std::endl;
    }

    return 0;

}

