// Checks if the given string is a valid email address
bool isEmailAddress(const QString &strEmailAddr)
{
    // Return false if the email address is empty
    if(strEmailAddr.isEmpty())
        return false;

    // Define the email pattern
    QString strPatt = "[A-Z0-9._%+-]+@[A-Z0-9.-]+\\.[A-Z]{2,4}";
    QRegExp rx(strPatt, Qt::CaseInsensitive); // Make the pattern case-insensitive

    // Return whether the email matches the pattern exactly
    return rx.exactMatch(strEmailAddr);
}

