// TicTacToe board initialization
char board[3][3] = { {'1', '2', '3'}, {'4', '5', '6'}, {'7', '8', '9'} };
char currentMarker;
int row, col;

// Function to display the TicTacToe board
void displayBoard()
{
    cout << " " << board[0][0] << " | " << board[0][1] << " | " << board[0][2] << endl;
    cout << "-----------" << endl;
    cout << " " << board[1][0] << " | " << board[1][1] << " | " << board[1][2] << endl;
    cout << "-----------" << endl;
    cout << " " << board[2][0] << " | " << board[2][1] << " | " << board[2][2] << endl;
}

// Function to get the player's move
void getMove()
{
    int move;
    cout << "Player " << currentMarker << ", enter your move (1-9): ";
    cin >> move;
    move--; // Adjusting for 0-based indexing
    row = move / 3;
    col = move % 3;

    if(board[row][col] != 'X' && board[row][col] != 'O')
    {
        board[row][col] = currentMarker;
    }
    else
    {
        cout << "Invalid move! Try again." << endl;
        getMove();
    }
}

// Function to check for a win
bool checkWin()
{
    // Check rows
    for(int i = 0; i < 3; i++)
    {
        if(board[i][0] == board[i][1] && board[i][1] == board[i][2])
            return true;
    }

    // Check columns
    for(int i = 0; i < 3; i++)
    {
        if(board[0][i] == board[1][i] && board[1][i] == board[2][i])
            return true;
    }

    // Check diagonals
    if(board[0][0] == board[1][1] && board[1][1] == board[2][2])
        return true;

    if(board[0][2] == board[1][1] && board[1][1] == board[2][0])
        return true;

    return false;
}

// Function to check for a draw
bool checkDraw()
{
    for(int i = 0; i < 3; i++)
    {
        for(int j = 0; j < 3; j++)
        {
            if(board[i][j] != 'X' && board[i][j] != 'O')
                return false;
        }
    }
    return true;
}

// Main function
int main()
{
    char playAgain = 'Y';
    while(playAgain == 'Y' || playAgain == 'y')
    {
        for(int i = 0; i < 9; i++)
        {
            displayBoard();
            if(i % 2 == 0)
            {
                currentMarker = 'X';
            }
            else
            {
                currentMarker = 'O';
            }
            getMove();

            if(checkWin())
            {
                displayBoard();
                cout << "Player " << currentMarker << " wins!" << endl;
                break;
            }
            else if(checkDraw())
            {
                displayBoard();
                cout << "It's a draw!" << endl;
                break;
            }
        }

        cout << "Do you want to play again? (Y/N): ";
        cin >> playAgain;
        if(playAgain == 'Y' || playAgain == 'y')
        {
            for(int i = 0; i < 3; i++)
            {
                for(int j = 0; j < 3; j++)
                {
                    board[i][j] = '1' + i * 3 + j;
                }
            }
        }
    }
    return 0;

}

