#define BUFFER_SIZE 256  // Adjust the buffer size as per your requirements

byte dataBuffer[BUFFER_SIZE];
unsigned int bufferHead = 0;
unsigned int bufferTail = 0;

// Adds data to the buffer
void addToBuffer(byte data)
{
    bufferHead = (bufferHead + 1) % BUFFER_SIZE;  // Wrap around if buffer is full
    dataBuffer[bufferHead] = data;
    if(bufferHead == bufferTail)
    {
        bufferTail = (bufferTail + 1) % BUFFER_SIZE;  // Remove oldest data when buffer is full
    }
}

// Reads data from the buffer
byte readFromBuffer()
{
    if(bufferTail != bufferHead)
    {
        bufferTail = (bufferTail + 1) % BUFFER_SIZE;
        return dataBuffer[bufferTail];
    }
    else
    {
        return 0;  // Return a default value if buffer is empty
    }
}

