// Native method for detecting and matching
JNIEXPORT jint JNICALL 
Java_com_sfarbac_rtmatching_nativeClass_detectAndMatch
(JNIEnv *env, jobject obj, jlong addrRgba, jlong addrTrick, jstring path)
{
    // Reference to input matrices
    Mat& camPic = *(Mat*)addrRgba;
    Mat& camTric = *(Mat*)addrTrick;

    // Get UTF length and characters from Java string
    const jsize len = env->GetStringUTFLength(path);
    const char* strChars = env->GetStringUTFChars(path, (jboolean *)0);
    string fileName(strChars, len);

    // Get the AssetManager from the Java environment
    jobject assetManagerObj = env->GetActivity()->assetManager;
    AAssetManager* assetManager = AAssetManager_fromJava(env, assetManagerObj);

    // Open the asset file
    AAsset* asset = AAssetManager_open(assetManager, fileName.c_str(), AASSET_MODE_STREAMING);
    if (asset == nullptr)
    {
        __android_log_print(ANDROID_LOG_ERROR, "TRACKERS", "Can not open asset file: %s", fileName.c_str());
        env->ReleaseStringUTFChars(path, strChars);
        return -1;
    }

    // Get the size of the asset file
    off_t bufferSize = AAsset_getLength(asset);

    // Read the asset file into a buffer
    char* buffer = new char[bufferSize];
    AAsset_read(asset, buffer, bufferSize);
    AAsset_close(asset);

    // Decode the buffer into a cv::Mat
    Mat img = imdecode(Mat(1, bufferSize, CV_8UC1, buffer), IMREAD_GRAYSCALE);

    // Clean up allocated memory
    delete[] buffer;

    if (img.empty())
    {
        __android_log_print(ANDROID_LOG_ERROR, "TRACKERS", "Can not decode image");
        env->ReleaseStringUTFChars(path, strChars);
        return -1;
    }

    // Assign decoded image to output matrix
    camTric = img;

    // Release Java string resources
    env->ReleaseStringUTFChars(path, strChars);

    return 1;
}

