// Template function to check if a number is a power of two
template<class IntType>
inline bool is_power_of_two(const IntType x)
{
    return (x != 0) && ((x & (x - 1)) == 0);
}

// Specialization for unsigned int using inline assembly
template<>
inline bool is_power_of_two<unsigned int>(const unsigned int x)
{
    bool result;
    __asm__ ("testl %1, %1 \n\t"
             "jz 1f \n\t"
             "andl %1, %1 \n\t"
             "je 1f \n\t"
             "movl $1, %0 \n\t"
             "jmp 2f \n\t"
             "1: movl $0, %0 \n\t"
             "2:"
             : "=r" (result)
             : "r" (x & (x - 1))
             : "cc");
    return result;
}

int main()
{
    unsigned int test = 16;
    // Output the result of checking if test is a power of two
    std::cout << "is_power_of_two(" << test << ") = " << is_power_of_two(test) << std::endl;
