// Function to check if the array is already sorted
std::string isSorted(const std::vector<int>& arr)
{
    for(size_t i=1;i<arr.size();++i)
    {
        if(arr[i-1]>arr[i])
        {
            return std::string();
        }
    }
    // Array is sorted
    return "Array is already sorted";
}

// Function to sort the array using bubble sort
std::vector<int> bubbleSort(std::vector<int>& arr)
{
    bool swapped;
    int n = arr.size();
    for(int i=0;i<n-1;++i)
    {
        swapped = false;
        for(int j=0;j<n-i-1;++j)
        {
            if(arr[j]>arr[j+1])
            {
                std::swap(arr[j],arr[j+1]);
                swapped = true;
            }
        }
        // If no two elements were swapped by inner loop, then break
        if(!swapped)
        {
            break;
        }
    }
    return arr;
}

int main()
{
    std::vector<int> arr = {4,2,1,7,10};
    std::string sortedMessage = isSorted(arr);

    if(!sortedMessage.empty())
    {
        std::cout<<sortedMessage<<std::endl;
    }
    else
    {
        std::vector<int> sortedArr = bubbleSort(arr);
        std::cout<<"Sorted array: ";
        for(int num : sortedArr)
        {
            std::cout<<num<<" ";
        }
        std::cout<<std::endl;
    }

    return 0;

}

