// Register the SecureComputation operation
REGISTER_OP("SecureComputation")
    .Input("input_data: float")
    .Attr("role: string")
    .Attr("privacy_epsilon: float = 1.0")
    .Output("output_data: float")
    .SetShapeFn([](tensorflow::shape_inference::InferenceContext* c) {
      c->set_output(0, c->input(0));
      return tensorflow::Status::OK();
    });

namespace tensorflow {

// Implementation of the SecureComputation kernel
class SecureComputationOp : public OpKernel {
 public:
  explicit SecureComputationOp(OpKernelConstruction* context)
      : OpKernel(context) {
    OP_REQUIRES_OK(context, context->GetAttr("role", &role_));
    OP_REQUIRES_OK(context, context->GetAttr("privacy_epsilon", &privacy_epsilon_));
  }

  void Compute(OpKernelContext* context) override {
    // Retrieve input tensor
    const Tensor& input_data = context->input(0);

    // Create output tensor shape based on input shape
    TensorShape output_shape(input_data.shape());
    Tensor* output_data = nullptr;
    OP_REQUIRES_OK(context, context->allocate_output(0, output_shape, &output_data));

    if (role_ == "guest") {
      // If role is guest, then copy input data to output
      *output_data = input_data;
    } else if (role_ == "host") {
      // If role is host, then add differential privacy noise to input data
      float noise_scale = 1.0 / privacy_epsilon_;
      AddPrivateNoise(context, input_data, output_data, noise_scale);
    } else {
      OP_REQUIRES(context, false, errors::InvalidArgument("Invalid role: ", role_));
    }
  }

 private:
  void AddPrivateNoise(OpKernelContext* context, const Tensor& input_data,
                       Tensor* output_data, float noise_scale) {
    auto input_flat = input_data.flat<float>();
    auto output_flat = output_data->flat<float>();

    // Initialize random generator for noise
    std::random_device rd;
    std::normal_distribution<float> distribution(0.0, noise_scale);

    for (int i = 0; i < input_flat.size(); i++) {
      float noise = distribution(rd);
      output_flat(i) = input_flat(i) + noise;
    }
  }

  string role_;
  float privacy_epsilon_;
};

// Register the kernel for CPU device
REGISTER_KERNEL_BUILDER(Name("SecureComputation").Device(DEVICE_CPU), SecureComputationOp);

