typedef unsigned int Dword;

void ACpuid(Dword type, Dword* eax, Dword* ebx, Dword* ecx, Dword* edx) {
    // Assembly implementation of cpuid
    __asm {
        mov eax, type
        cpuid
        mov [eax], eax
        mov [ebx], ebx
        mov [ecx], ecx
        mov [edx], edx
    }
}

