// Function to get status from shared memory
DLL int getStatus(SYSTEM_OUTPUT* output)
{
    HANDLE hMapFile;
    STATUS_DATA* pBuf;

    // Open existing file mapping object
    hMapFile = OpenFileMapping(
        FILE_MAP_READ,
        FALSE,
        szName);

    if (hMapFile == NULL) 
    { 
        _tprintf(TEXT("Could not open file mapping object (%d).\n"), GetLastError());
        return -2;
    } 

    // Map view of file into address space
    pBuf = (STATUS_DATA*) MapViewOfFile(hMapFile, FILE_MAP_READ, 0, 0, 0);                                          

    if (pBuf == NULL) 
    { 
        _tprintf(TEXT("Could not map view of file (%d).\n"), GetLastError()); 
        CloseHandle(hMapFile);  
        return -1;
    }

    // Debugging: Print values from shared memory
    _tprintf(TEXT("ReadyForConnect: %hu\n"), pBuf->engine[0].ReadyForConnect);
    _tprintf(TEXT("VizVersionStr: %s\n"), pBuf->engine[0].VizVersionStr);
    _tprintf(TEXT("NameOfFile: %s\n"), pBuf->engine[0].NameOfFile);

    // Copy data to output structure
    output->ReadyForConnect = pBuf->engine[0].ReadyForConnect;              
    memcpy(output->VizVersionStr, pBuf->engine[0].VizVersionStr, sizeof(pBuf->engine[0].VizVersionStr));
    memcpy(output->NameOfFile, pBuf->engine[0].NameOfFile, sizeof(pBuf->engine[0].NameOfFile));

    // Debugging: Print values after copying
    _tprintf(TEXT("Output ReadyForConnect: %hu\n"), output->ReadyForConnect);
    _tprintf(TEXT("Output VizVersionStr: %s\n"), output->VizVersionStr);
    _tprintf(TEXT("Output NameOfFile: %s\n"), output->NameOfFile);

    // Clean up resources
    CloseHandle(hMapFile);
    UnmapViewOfFile(pBuf);  

    return 0;
}

