#include <jni.h>
#include <xgboost/c_api.h>

extern "C" {
    // Load XGBoost model from path
    JNIEXPORT void JNICALL Java_com_example_XGBoostJNI_loadModel(JNIEnv *env, jobject /* this */, jstring modelPath) {
        const char *path = env->GetStringUTFChars(modelPath, nullptr);
        BoosterHandle handle;
        XGBoosterCreate(nullptr, 0, &handle);
        XGBoosterLoadModel(handle, path);
        env->ReleaseStringUTFChars(modelPath, path);
    }

    // Predict using loaded model
    JNIEXPORT jdouble JNICALL Java_com_example_XGBoostJNI_predict(JNIEnv *env, jobject /* this */, jdoubleArray features) {
        jdouble *featuresPtr = env->GetDoubleArrayElements(features, nullptr);
        int n = env->GetArrayLength(features);
        DMatrixHandle dmatrix;
        XGDMatrixCreateFromMat(featuresPtr, n, 1, -1, &dmatrix);
        BoosterHandle handle;  // Assume this is set up elsewhere
        float *outResult;
        XGBoosterPredict(handle, dmatrix, 0, 1, &outResult);
        env->ReleaseDoubleArrayElements(features, featuresPtr, 0);
        return outResult[0];
    }
}

