#include <cctype> // for isspace function

// Function to remove extra spaces from a string
std::string removeExtraSpaces(const std::string& input)
{
    if (input.empty()) return input;

    std::string result;
    bool inSpace = false; // Flag to track if we are in a sequence of spaces

    for (size_t i = 0; i < input.length(); ++i)
    {
        if (std::isspace(input[i]))
        {
            if (!inSpace && !result.empty())
            {
                result += ' '; // Add a single space if we are not already in a space sequence
            }
            inSpace = true;
        }
        else
        {
            result += input[i];
            inSpace = false;
        }
    }

    // Remove trailing space if it exists
    if (!result.empty() && result.back() == ' ')
    {
        result.pop_back();
    }

    return result;
}

// Function to test the removeExtraSpaces function
void testRemoveExtraSpaces()
{
    std::string test1 = "  Hello   World!  ";
    std::string expected1 = "Hello World!";
    assert(removeExtraSpaces(test1) == expected1);

    std::string test2 = "  This is    a test  ";
    std::string expected2 = "This is a test";
    assert(removeExtraSpaces(test2) == expected2);

    std::string test3 = "NoExtraSpaces";
    std::string expected3 = "NoExtraSpaces";
    assert(removeExtraSpaces(test3) == expected3);

    std::string test4 = " ";
    std::string expected4 = "";
    assert(removeExtraSpaces(test4) == expected4);

    std::string test5 = "   ";
    std::string expected5 = "";
    assert(removeExtraSpaces(test5) == expected5);

    // Print success message
    std::cout << "All tests passed!" << std::endl;
}

int main()
{
    testRemoveExtraSpaces();
    return 0;

}

