#include <iostream>
#include <vector>
#include <string>

// Generates a 3D Pascal-like pyramid
std::vector<std::vector<std::vector<int>>> generatePascalPyramid(int levels)
{
    std::vector<std::vector<std::vector<int>>> pyramid(levels);

    for(int level = 0; level < levels; ++level)
    {
        pyramid[level] = std::vector<std::vector<int>>(level + 1, std::vector<int>(level + 1, 0));

        for(int i = 0; i <= level; ++i)
        {
            for(int j = 0; j <= level; ++j)
            {
                if(i == 0 || j == 0 || i == j)
                {
                    pyramid[level][i][j] = 1;
                }
                else
                {
                    int value = pyramid[level - 1][i - 1][j] + pyramid[level - 1][i][j - 1] + pyramid[level - 1][i - 1][j - 1];
                    if(value % 2 == 0)
                    {
                        std::cout << "Error: Even number " << value << " at level " << level << " position (" << i << ", " << j << ")" << std::endl;
                        pyramid[level][i][j] = -1;  // Mark with -1 for error
                    }
                    else
                    {
                        pyramid[level][i][j] = value;
                    }
                }
            }
        }
    }

    return pyramid;
}

int main()
{
    int levels = 5;
    auto pyramid = generatePascalPyramid(levels);

    for(int level = 0; level < levels; ++level)
    {
        for(int i = 0; i <= level; ++i)
        {
            for(int j = 0; j <= level; ++j)
            {
                std::cout << pyramid[level][i][j] << " ";
            }
            std::cout << std::endl;
        }
        std::cout << std::endl;
    }

    return 0;

}

