using namespace std;

// Checks if a number is prime
bool isPrime(int n)
{
    if(n <= 1) return false;
    for(int i = 2; i <= sqrt(n); i++)
    {
        if(n % i == 0) return false;
    }
    return true;
}

// Generates a random number with specified length
int generateRandom(int length)
{
    int minNum = pow(10, length - 1);
    int maxNum = pow(10, length) - 1;
    return rand() % (maxNum - minNum + 1) + minNum;
}

// Finds a prime number with specified length
int findPrime(int length)
{
    srand(time(0));
    int num = generateRandom(length);
    while(!isPrime(num))
    {
        num = generateRandom(length);
    }
    return num;
}

int main()
{
    int length = 3;
    int prime = findPrime(length);
    // Output the result
    cout << "A prime number of length " << length << " is: " << prime << endl;
    return 0;

}

#include <altivec.h>
#undef vector

// Type definition for vector of unsigned chars
typedef __vector unsigned char uint8x16_p;

// Fast load 8 bytes into vector
uint8x16_p VectorFastLoad8(const void* p)
{
    long offset = 0;
    uint8x16_p res;

    // Inline assembly to load vector data
    __asm("lxvd2x %x0, %1, %2"
          : "=wa" (res)
          : "r" (p), "r" (offset / 4)
          : "memory");

    return res;
}

#include <stdio.h>
#include <stdint.h>

// Reads the time-stamp counter
uint64_t rdtscp()
{
    uint32_t lo, hi;
    __asm__ __volatile__("rdtscp" : "=a"(lo), "=d"(hi) : : "rcx");
    return ((uint64_t)hi << 32) | lo;
}

int main()
{
    unsigned long long t1, t2;
    const int num_nops = 1000000;

    // First measurement: single NOP per iteration
    t1 = rdtscp();
    for(int i=0; i<num_nops; ++i)
    {
        asm volatile("nop");
    }
    t2 = rdtscp();
    printf("rdtscp for %d NOPs: %llu cycles\n", num_nops, t2 - t1);

    // Second measurement: seven NOPs per iteration
    t1 = rdtscp();
    for(int i=0; i<num_nops; ++i)
    {
        asm volatile("nop; nop; nop; nop; nop; nop; nop;");
    }
    t2 = rdtscp();
    printf("rdtscp for %d * 7 NOPs: %llu cycles\n", num_nops, t2 - t1);

    return 0;
}

#include <jni.h>
#include <android/asset_manager.h>
#include <android/asset_manager_jni.h>
#include <string>
#include <vector>

// Loads shader source from asset file
std::string loadShaderSource(AAssetManager* assetManager, const std::string& filename)
{
    AAsset* asset = AAssetManager_open(assetManager, filename.c_str(), AASSET_MODE_STREAMING);
    if (!asset)
    {
        return "";
    }

    off_t length = AAsset_getLength(asset);
    std::vector<char> buffer(length + 1);
    AAsset_read(asset, buffer.data(), length);
    buffer[length] = '\0'; // Null-terminate the string
    AAsset_close(asset);

    return std::string(buffer.data());

}

