    int numbers[] = {1, 2, 3, 4, 5};
    auto num_numbers = sizeof(numbers)/sizeof(numbers[0]);
    // Compute and return the sum of array elements
    return std::accumulate(numbers, numbers + num_numbers, 0);

}

#include <boost/asio.hpp>
#include <boost/array.hpp>
#include <iostream>
#include <thread>
#include <chrono>

using boost::asio::ip::udp;

// Multicast sender function
void multicast_sender(const std::string& multicast_address, unsigned short port)
{
    boost::asio::io_context io_context;
    udp::socket socket(io_context);
    udp::endpoint multicast_endpoint = udp::endpoint(udp::address::from_string(multicast_address), port);
    socket.open(udp::v4());

    // Heartbeat message
    boost::array<char, 1> heartbeat = {{ 'H' }};

    while(true)
    {
        socket.send_to(boost::asio::buffer(heartbeat), multicast_endpoint);
        std::this_thread::sleep_for(std::chrono::seconds(5));
    }
}

// Multicast receiver function
void multicast_receiver(const std::string& multicast_address, unsigned short port)
{
    boost::asio::io_context io_context;
    udp::socket socket(io_context, udp::endpoint(udp::v4(), port));
    socket.set_option(udp::socket::reuse_address(true));

    udp::endpoint multicast_endpoint = udp::endpoint(udp::address::from_string(multicast_address), port);
    socket.set_option(udp::socket::join_group(multicast_endpoint.address()));

    // Buffer for incoming messages
    boost::array<char, 1> receive_buffer;
    while(true)
    {
        udp::endpoint sender_endpoint;
        size_t length = socket.receive_from(boost::asio::buffer(receive_buffer), sender_endpoint);
        if(receive_buffer[0] == 'H')
        {
            std::cout << "Heartbeat received from " << sender_endpoint << std::endl;
        }
    }
}

int main()
{
    std::string multicast_address = "239.255.255.250";
    unsigned short port = 12345;

    // Start sender and receiver threads
    std::thread sender_thread(multicast_sender, multicast_address, port);
    std::thread receiver_thread(multicast_receiver, multicast_address, port);

    sender_thread.join();
    receiver_thread.join();

    return 0;

}

#include <iostream>
