#include <stdexcept>

// Function to add two integers with overflow checking
long long add_integers(long long a, long long b)
{
    try
    {
        // Check for overflow
        if(a > 0 && b > std::numeric_limits<long long>::max() - a)
        {
            throw std::overflow_error("Input values are too large to handle.");
        }
        if(a < 0 && b < std::numeric_limits<long long>::min() - a)
        {
            throw std::underflow_error("Input values are too small to handle.");
        }

        // Perform addition
        long long result = a + b;
        return result;
    }
    catch(const std::overflow_error& e)
    {
        std::cerr << e.what() << std::endl;
        return 0;
    }
    catch(const std::underflow_error& e)
    {
        std::cerr << e.what() << std::endl;
        return 0;
    }
    catch(const std::exception& e)
    {
        std::cerr << "An unexpected error occurred: " << e.what() << std::endl;
        return 0;
    }
}

int main()
{
    long long a = 1234567890123456789LL;
    long long b = 9876543210987654321LL;
    // Print the result of adding two large integers
    std::cout << "Result: " << add_integers(a, b) << std::endl;
    return 0;

}

