using namespace std;

// Function to get CPU feature flags using cpuid instruction
inline unsigned int get_cpu_feature_flags()
{
    unsigned int features;

    // Inline assembly to execute CPUID instruction
    asm volatile (
        "push %%eax\n\t"
        "push %%ebx\n\t"
        "push %%ecx\n\t"
        "push %%edx\n\t"
        "mov $1, %%eax\n\t"
        "cpuid\n\t"
        "mov %%edx, %0\n\t"
        "pop %%edx\n\t"
        "pop %%ecx\n\t"
        "pop %%ebx\n\t"
        "pop %%eax\n\t"
        : "=r" (features)  // Output operand
        :                  // No input operands
        : "eax", "ebx", "ecx", "edx"  // Clobbered registers
    );

    return features;
}

int main()
{
    // Check for SSE2 support (bit 26 of EDX)
    static const bool cpu_supports_sse2 = (get_cpu_feature_flags() & 0x04000000) != 0;

    // Output whether SSE2 is supported
    cout<<(cpu_supports_sse2 ? "Supports SSE2" : "Does NOT support SSE2")<<endl;

    return 0;
}

