typedef vector<Line> LineArray;

// Forward declaration of the core function
Eigen::MatrixXd f(const LineArray& lines);

// Wrapper function to convert Eigen::MatrixXd to std::vector<std::vector<double>>
vector<vector<double>> f_wrapper(const LineArray& lines)
{
    Eigen::MatrixXd result = f(lines);
    vector<vector<double>> result_vector(result.rows(), vector<double>(result.cols()));
    for(int i=0; i<result.rows(); ++i)
    {
        for(int j=0; j<result.cols(); ++j)
        {
            result_vector[i][j] = result(i, j);
        }
    }
    return result_vector;
}

