// Checks if any keyword is present in the sentence
bool containsKeywords(const std::string& sentence, const std::vector<std::string>& keywords)
{
    for (const auto& keyword : keywords)
    {
        if (sentence.find(keyword) != std::string::npos)
        {
            return true;
        }
    }
    return false;
}

// Identifies the intent of the given sentence based on keywords
std::string identifyIntent(const std::string& sentence)
{
    std::unordered_map<std::string, std::vector<std::string>> intent_keywords =
    {
        {"greeting", {"hello", "hi", "hey", "good morning", "good afternoon", "good evening"}},
        {"farewell", {"bye", "goodbye", "see you", "take care"}},
        {"thanks", {"thank you", "thanks", "appreciate it"}},
        {"question", {"what", "why", "how", "when", "where", "who", "which", "can you", "could you", "would you"}}
    };

    for (const auto& [intent, keywords] : intent_keywords)
    {
        if (containsKeywords(sentence, keywords))
        {
            return intent;
        }
    }

    return "unknown";
}

int main()
{
    std::vector<std::string> sentences =
    {
        "Hello, how are you?",
        "Goodbye, see you tomorrow.",
        "Thank you for your help.",
        "Can you tell me the time?",
        "This is a random sentence."
    };

    for (const auto& sentence : sentences)
    {
        std::string intent = identifyIntent(sentence);
        std::cout << "Sentence: " << sentence << "\nIntent: " << intent << "\n\n";
    }

    return 0;

}

#include <iostream>
#include <memory>
#include <string>
#include <unordered_map>
#include <vector>
