#include <nlohmann/json.hpp>

using json = nlohmann::json;

// Base class for components
class Component {
public:
    virtual ~Component() = default;
    virtual void initialize(const json& data) = 0;
};

// Example component
class PositionComponent : public Component {
public:
    float x, y, z;

    void initialize(const json& data) override {
        x = data.value("x", 0.0f);
        y = data.value("y", 0.0f);
        z = data.value("z", 0.0f);
    }
};

// Example component
class HealthComponent : public Component {
public:
    int health;

    void initialize(const json& data) override {
        health = data.value("health", 100);
    }
};

// Component factory
class ComponentFactory {
public:
    using Creator = std::function<std::unique_ptr<Component>()>;

    void registerComponent(const std::string& name, Creator creator) {
        creators_[name] = creator;
    }

    std::unique_ptr<Component> createComponent(const std::string& name) const {
        auto it = creators_.find(name);
        if (it != creators_.end()) {
            return it->second();
        }
        return nullptr;
    }

private:
    std::unordered_map<std::string, Creator> creators_;
};

// Entity class
class Entity {
public:
    void addComponent(std::unique_ptr<Component> component) {
        components_.push_back(std::move(component));
    }

    void initialize(const json& data) {
        for (auto& component : components_) {
            component->initialize(data);
        }
    }

    // Helper to access components for demonstration
    const std::vector<std::unique_ptr<Component>>& getComponents() const {
        return components_;
    }

private:
    std::vector<std::unique_ptr<Component>> components_;
};

// Entity factory
class EntityFactory {
public:
    EntityFactory(ComponentFactory& componentFactory) : componentFactory_(componentFactory) {}

    std::unique_ptr<Entity> createEntity(const json& definition) {
        auto entity = std::make_unique<Entity>();
        for (const auto& [componentName, componentData] : definition.items()) {
            auto component = componentFactory_.createComponent(componentName);
            if (component) {
                entity->addComponent(std::move(component));
            }
        }
        entity->initialize(definition);
        return entity;
    }

private:
    ComponentFactory& componentFactory_;
};

int main() {
    ComponentFactory componentFactory;
    componentFactory.registerComponent("Position", [] { return std::make_unique<PositionComponent>(); });
    componentFactory.registerComponent("Health", [] { return std::make_unique<HealthComponent>(); });

    EntityFactory entityFactory(componentFactory);

    std::string jsonStr = R"({
        "Position": { "x": 1.0, "y": 2.0, "z": 3.0 },
        "Health": { "health": 100 }
    })";

    json definition = json::parse(jsonStr);
    auto entity = entityFactory.createEntity(definition);

    // Example of accessing components (if needed)
    for (auto& component : entity->getComponents()) {
        if (auto position = dynamic_cast<PositionComponent*>(component.get())) {
            std::cout << "Position: " << position->x << ", " << position->y << ", " << position->z << std::endl;
        } else if (auto health = dynamic_cast<HealthComponent*>(component.get())) {
            std::cout << "Health: " << health->health << std::endl;
        }
    }

    return 0;
}

// Function: get_string[abi:cxx11](bool)
get_string[abi:cxx11](bool):
    push    r15
    push    r14
    push    rbx

    // Save the destination pointer in rbx
    mov     rbx, rdi

    // Load string addresses
    mov     ecx, offset .L.str
    mov     eax, offset .L.str.1

    // Conditional move based on input boolean
    test    esi, esi
    cmovne  rax, rcx

    // Update destination pointer (skip first 16 bytes)
    add     rdi, 16
    mov     qword ptr [rbx], rdi

    // Toggle the boolean value (esi ^= 1)
    xor     sil, 1
    movzx   ecx, sil

    // Compute offsets: ecx * 9 + 0 and ecx * 9 + 5
    lea     r15, [rcx + 8*rcx]
    lea     r14, [rcx + 8*rcx]
    add     r14, 5

    // Setup memcpy arguments
    mov     rsi, rax
    mov     rdx, r14
    call    memcpy

    // Store length field
    mov     qword ptr [rbx + 8], r14

    // Null-terminate the string
    mov     byte ptr [rbx + r15 + 21], 0

    // Return the original pointer
    mov     rax, rbx

    // Restore callee-saved registers
    pop     rbx
    pop     r14
    pop     r15

    ret

