// Generates Fibonacci sequence up to n elements
std::vector<int> fibonacci(int n)
{
    if(n <= 0) return {};
    if(n == 1) return {0};
    if(n == 2) return {0, 1};

    std::vector<int> fibSequence = {0, 1};
    for(int i = 2; i < n; ++i)
    {
        int nextValue = fibSequence[i - 1] + fibSequence[i - 2];
        fibSequence.push_back(nextValue);
    }

    return fibSequence;
}

int main()
{
    int n = 10;
    std::vector<int> result = fibonacci(n);
    for(int num : result)
    {
        std::cout << num << " ";
    }
    // Print newline
    std::cout << std::endl;
    return 0;

}

