// Function to calculate the determinant of a matrix
double determinant(const std::vector<std::vector<double>>& matrix)
{
    int n = matrix.size();

    // Base case for 1x1 matrix
    if(n == 1)
    {
        return matrix[0][0];
    }

    // Base case for 2x2 matrix
    if(n == 2)
    {
        return matrix[0][0] * matrix[1][1] - matrix[0][1] * matrix[1][0];
    }

    double det = 0.0;

    // Calculate the determinant using cofactor expansion
    for(int col = 0; col < n; ++col)
    {
        std::vector<std::vector<double>> submatrix(n - 1, std::vector<double>(n - 1));

        // Form the submatrix by removing the first row and the current column
        for(int i = 1; i < n; ++i)
        {
            for(int j = 0, k = 0; j < n; ++j)
            {
                if(j != col)
                {
                    submatrix[i - 1][k++] = matrix[i][j];
                }
            }
        }

        // Add the cofactor to the determinant
        det += matrix[0][col] * std::pow(-1, col) * determinant(submatrix);
    }

    return det;
}

int main()
{
    // Example matrix
    std::vector<std::vector<double>> matrix =
    {
        {1, 2, 3},
        {4, 5, 6},
        {7, 8, 9}
    };

    double det = determinant(matrix);
    std::cout << "The determinant of the matrix is: " << det << std::endl;

    return 0;

}

