// Subtracts from histogram based on bit positions
void histSubtractFromBits(uint64_t* cursor, uint16_t* hist)
{
    for(int i=0;i<4;++i)
    {
        uint64_t word = cursor[i];
        for(int bit=0;bit<64;++bit)
        {
            if(word & (1ULL << bit))
            {
                hist[i * 64 + bit] -= 1;
            }
        }
    }
}

