// Encrypts a file using 3DES in CBC mode
void encryptFile(const std::string& inputFilePath, const std::string& outputFilePath, const unsigned char* key, const unsigned char* iv)
{
    // Open input and output files in binary mode
    std::ifstream inputFile(inputFilePath, std::ios::binary);
    std::ofstream outputFile(outputFilePath, std::ios::binary);

    if (!inputFile.is_open() || !outputFile.is_open())
    {
        std::cerr << "Error opening file." << std::endl;
        return;
    }

    // Buffer for processing data in chunks
    std::vector<unsigned char> buffer(1024);

    // Initialize DES key schedules for 3-key 3DES
    DES_key_schedule keySchedule1, keySchedule2, keySchedule3;
    DES_set_key((DES_cblock*)key, &keySchedule1);
    DES_set_key((DES_cblock*)(key + 8), &keySchedule2);
    DES_set_key((DES_cblock*)(key + 16), &keySchedule3);

    // Process the file in chunks
    while (inputFile.read((char*)buffer.data(), buffer.size()))
    {
        size_t bytes_read = inputFile.gcount();
        DES_ede3_cbc_encrypt(buffer.data(), buffer.data(), bytes_read, &keySchedule1, &keySchedule2, &keySchedule3, (DES_cblock*)iv, DES_ENCRYPT);
        outputFile.write((char*)buffer.data(), bytes_read);
    }

    // Handle remaining bytes in the last partial block
    size_t bytes_read = inputFile.gcount();
    if (bytes_read > 0)
    {
        DES_ede3_cbc_encrypt(buffer.data(), buffer.data(), bytes_read, &keySchedule1, &keySchedule2, &keySchedule3, (DES_cblock*)iv, DES_ENCRYPT);
        outputFile.write((char*)buffer.data(), bytes_read);
    }

    // Close files
    inputFile.close();
    outputFile.close();
}

