#include <cuda_runtime.h>
#include <thrust/device_vector.h>
#include <thrust/sort.h>
#include <thrust/execution_policy.h>

struct Point {
    float x, y;
};

struct Node {
    int start, end;  // Range of points in the array
    int axis;        // Splitting axis (0 for x, 1 for y)
    float value;     // Splitting value
    int left, right; // Indices of left and right children
};

__global__ void buildKdTreeKernel(Point* points, Node* nodes, int* stack, int* stackSize, int* nextNodeIndex) {
    int tid = blockIdx.x * blockDim.x + threadIdx.x;
    if (tid >= *stackSize) return;

    int nodeIndex = stack[tid];
    Node& node = nodes[nodeIndex];
    int start = node.start;
    int end = node.end;
    int axis = node.axis;

    // Sort points along the current axis
    thrust::sort(thrust::device, points + start, points + end, [axis] __device__ (const Point& a, const Point& b) {
        return (axis == 0) ? a.x < b.x : a.y < b.y;
    });

    // Find the median point
    int median = (start + end) / 2;
    float value = (axis == 0) ? points[median].x : points[median].y;

    // Create left and right child nodes
    int leftIndex = atomicAdd(nextNodeIndex, 1);
    int rightIndex = atomicAdd(nextNodeIndex, 1);

    nodes[leftIndex] = {start, median, 1 - axis, 0, -1, -1};
    nodes[rightIndex] = {median + 1, end, 1 - axis, 0, -1, -1};

    node.value = value;
    node.left = leftIndex;
    node.right = rightIndex;

    // Add child nodes to the stack
    stack[*stackSize] = leftIndex;
    stack[++*stackSize] = rightIndex;
}

void buildKdTree(Point* d_points, int numPoints, Node* d_nodes, int maxNodes)
{
    // Initialize the root node
    Node root = {0, numPoints, 0, 0, -1, -1};
    cudaMemcpy(d_nodes, &root, sizeof(Node), cudaMemcpyHostToDevice);

    // Initialize the stack
    int* d_stack;
    cudaMalloc(&d_stack, maxNodes * sizeof(int));
    int* d_stackSize;
    cudaMalloc(&d_stackSize, sizeof(int));
    int* d_nextNodeIndex;
    cudaMalloc(&d_nextNodeIndex, sizeof(int));

    int stackSize = 1;
    int nextNodeIndex = 1;
    cudaMemcpy(d_stack, &root, sizeof(Node), cudaMemcpyHostToDevice);
    cudaMemcpy(d_stackSize, &stackSize, sizeof(int), cudaMemcpyHostToDevice);
    cudaMemcpy(d_nextNodeIndex, &nextNodeIndex, sizeof(int), cudaMemcpyHostToDevice);

    // Kernel launch configuration
    int blockSize = 256;
    int gridSize = (maxNodes + blockSize - 1) / blockSize;

    // Main loop to build the kd-tree
    while (stackSize > 0) {
        buildKdTreeKernel<<<gridSize, blockSize>>>(d_points, d_nodes, d_stack, d_stackSize, d_nextNodeIndex);
        cudaDeviceSynchronize();

        // Update stack size and next node index
        cudaMemcpy(&stackSize, d_stackSize, sizeof(int), cudaMemcpyDeviceToHost);
        cudaMemcpy(&nextNodeIndex, d_nextNodeIndex, sizeof(int), cudaMemcpyDeviceToHost);
    }

    cudaFree(d_stack);
    cudaFree(d_stackSize);
    cudaFree(d_nextNodeIndex);
}

