// Definition for singly-linked list.
struct ListNode {
    int val;
    ListNode *next;
    ListNode(int x) : val(x), next(NULL) {}
};

// Detects if a cycle exists in the linked list using Floyd's algorithm
bool hasCycle(ListNode *head)
{
    // Check for empty list or single node
    if (head == NULL || head->next == NULL) {
        return false;
    }

    // Initialize two pointers
    ListNode *tortoise = head;
    ListNode *hare = head;

    // Traverse the list with different speeds
    while (hare != NULL && hare->next != NULL) {
        tortoise = tortoise->next;      // Move one step
        hare = hare->next->next;        // Move two steps

        // If pointers meet, cycle detected
        if (tortoise == hare) {
            return true;
        }
    }

    // No cycle found
    return false;
}

int main()
{
    // Example usage:
    ListNode *node1 = new ListNode(1);
    ListNode *node2 = new ListNode(2);
    ListNode *node3 = new ListNode(3);
    ListNode *node4 = new ListNode(4);

    node1->next = node2;
    node2->next = node3;
    node3->next = node4;
    node4->next = node2;  // Creating a cycle

    // Check for cycle and output result
    if (hasCycle(node1)) {
        std::cout << "Cycle detected." << std::endl;
    } else {
        std::cout << "No cycle detected." << std::endl;
    }

    // Clean up memory
    delete node1;
    delete node2;
    delete node3;
    delete node4;

    return 0;
}

