// Disassembles code using Capstone
void disassembleCode(uint8_t *bytearray, long size, uint64_t startAddress)
{
    csh handle;
    cs_insn *insn;
    size_t count;
    std::string output;

    if (cs_open(CS_ARCH_X86, CS_MODE_64, &handle) == CS_ERR_OK)
    {
        count = cs_disasm(handle, bytearray, size, startAddress, 0, &insn);
        printf("\nCOUNT:%lu", count);
        if (count > 0)
        {
            for (size_t j = 0; j < count; j++)
            {
                char buffer[512];
                int i = sprintf(buffer, "0x%" PRIx64 ":\t%s\t\t%s\n", insn[j].address, insn[j].mnemonic, insn[j].op_str);
                output += buffer;
            }
            cs_free(insn, count);
        }
        else
        {
            output = "ERROR: Failed to disassemble given code!\n";
        }
        cs_close(&handle);
        std::cout << output;
    }
}

// Extracts the __text section from a Mach-O file
bool extractTextSegment(const char *filename, uint8_t **code, uint64_t *size, uint64_t *startAddress)
{
    std::ifstream file(filename, std::ios::binary);
    if (!file)
    {
        std::cerr << "Failed to open file: " << filename << std::endl;
        return false;
    }

    file.seekg(0, std::ios::end);
    size_t fileSize = file.tellg();
    file.seekg(0, std::ios::beg);

    uint8_t *buffer = new uint8_t[fileSize];
    file.read((char *)buffer, fileSize);
    file.close();

    struct mach_header_64 *header = (struct mach_header_64 *)buffer;
    if (header->magic != MH_MAGIC_64)
    {
        std::cerr << "Not a valid Mach-O 64-bit file." << std::endl;
        delete[] buffer;
        return false;
    }

    struct load_command *lc = (struct load_command *)(buffer + sizeof(struct mach_header_64));
    for (uint32_t i = 0; i < header->ncmds; i++)
    {
        if (lc->cmd == LC_SEGMENT_64)
        {
            struct segment_command_64 *seg = (struct segment_command_64 *)lc;
            if (strcmp(seg->segname, "__TEXT") == 0)
            {
                for (uint32_t j = 0; j < seg->nsects; j++)
                {
                    struct section_64 *sect = (struct section_64 *)((char *)seg + sizeof(struct segment_command_64) + j * sizeof(struct section_64));
                    if (strcmp(sect->sectname, "__text") == 0)
                    {
                        *code = buffer + sect->offset;
                        *size = sect->size;
                        *startAddress = sect->addr;
                        return true;
                    }
                }
            }
        }
        lc = (struct load_command *)((char *)lc + lc->cmdsize);
    }

    delete[] buffer;
    return false;
}

int main()
{
    uint8_t *code;
    uint64_t size, startAddress;

    if (extractTextSegment("path/to/your/dylib", &code, &size, &startAddress))
    {
        disassembleCode(code, size, startAddress);
    }
    else
    {
        std::cerr << "Failed to extract code segment." << std::endl;
    }

    return 0;
}

#include <iostream>
