// Function to convert a string to lowercase
std::string toLower(const std::string& str)
{
    std::string lowerStr = str;
    std::transform(lowerStr.begin(), lowerStr.end(), lowerStr.begin(), ::tolower);
    return lowerStr;
}

// Function to split a string into words
std::vector<std::string> split(const std::string& str)
{
    std::istringstream iss(str);
    std::vector<std::string> words;
    std::string word;
    while (iss >> word)
    {
        words.push_back(word);
    }
    return words;
}

// Function to check if a word is in the dictionary
bool isCorrect(const std::string& word, const std::unordered_set<std::string>& dictionary)
{
    return dictionary.find(toLower(word)) != dictionary.end();
}

// Function to correct a word (simple approach: return the word itself if not found)
std::string correctWord(const std::string& word, const std::unordered_set<std::string>& dictionary)
{
    if (isCorrect(word, dictionary))
    {
        return word;
    }
    // Simple correction: return the word itself if not found
    return word;
}

// Function to correct a sentence
std::string correctSentence(const std::string& sentence, const std::unordered_set<std::string>& dictionary)
{
    std::vector<std::string> words = split(sentence);
    std::string correctedSentence;
    for (const auto& word : words)
    {
        correctedSentence += correctWord(word, dictionary) + " ";
    }
    if (!correctedSentence.empty())
    {
        correctedSentence.pop_back(); // Remove the trailing space
    }
    return correctedSentence;
}

int main()
{
    // Predefined dictionary
    std::unordered_set<std::string> dictionary =
    {
        "the", "quick", "brown", "fox", "jumps", "over", "lazy", "dog", "a", "an", "is", "are", "this", "that"
    };

    std::string sentence;
    std::cout << "Enter a sentence: ";
    std::getline(std::cin, sentence);

    std::string correctedSentence = correctSentence(sentence, dictionary);

    std::cout << "Corrected sentence: " << correctedSentence << std::endl;

    return 0;

}

#include <iostream>
#include <unordered_map>

// Template class for Doubly Linked List
template <typename T>
class DoublyLinkedList {
public:
    struct Node {
        T data;
        Node* prev;
        Node* next;
        // Constructor for Node
        Node(T data) : data(data), prev(nullptr), next(nullptr) {}
    };

    // Constructor
    DoublyLinkedList() : head(nullptr), tail(nullptr) {}

    // Destructor
    ~DoublyLinkedList() {
        while (head) {
            Node* temp = head;
            head = head->next;
            delete temp;
        }
    }

    // Insert a new node at the end
    void insert(T data) {
        Node* newNode = new Node(data);
        if (!head) {
            head = tail = newNode;
        } else {
            tail->next = newNode;
            newNode->prev = tail;
            tail = newNode;
        }
        nodeMap[data] = newNode;
    }

    // Search for a node by value
    Node* search(T data) {
        if (nodeMap.find(data) != nodeMap.end()) {
            return nodeMap[data];
        }
        return nullptr;
    }

    // Remove a node by value
    void remove(T data) {
        if (nodeMap.find(data) != nodeMap.end()) {
            Node* node = nodeMap[data];
            if (node->prev) node->prev->next = node->next;
            if (node->next) node->next->prev = node->prev;
            if (node == head) head = node->next;
            if (node == tail) tail = node->prev;
            delete node;
            nodeMap.erase(data);
        }
    }

private:
    Node* head;
    Node* tail;
