// Converts to network byte order for 64-bit values
uint64_t htonll(uint64_t value)
{
    static const int isLittleEndian = (1 == *(uint8_t *)&(uint32_t){1});
    if(isLittleEndian)
    {
        return ((uint64_t)htonl(value) << 32) | htonl(value >> 32);
    }
    return value;
}

// Converts from network byte order for 64-bit values
uint64_t ntohll(uint64_t value)
{
    static const int isLittleEndian = (1 == *(uint8_t *)&(uint32_t){1});
    if(isLittleEndian)
    {
        return ((uint64_t)ntohl(value) << 32) | ntohl(value >> 32);
    }
    return value;
}

