// Computes the mean of a vector of integers
double mean(const std::vector<int>& numbers)
{
    // Handle empty vector case
    if(numbers.empty())
    {
        return 0.0;
    }
    int sum = 0;
    // Iterate through each number and accumulate sum
    for(int number : numbers)
    {
        sum += number;
    }
    // Cast to double for floating-point division
    return static_cast<double>(sum) / numbers.size();
}

int main()
{
    std::vector<int> numbers = {1, 2, 3, 4, 5};
    // Output the mean value
    std::cout<<mean(numbers)<<std::endl;
    return 0;

}

