// Function to check if a number is prime using trial division
bool isPrime(long long n)
{
    if (n <= 1) return false;
    if (n <= 3) return true;
    if (n % 2 == 0 || n % 3 == 0) return false;
    for (long long i = 5; i * i <= n; i += 6)
    {
        if (n % i == 0 || n % (i + 2) == 0) return false;
    }
    return true;
}

// Function to process a sub-range and find prime numbers
void processRange(long long start, long long end, long long threshold, std::mutex& fileMutex, std::ofstream& file, std::atomic<long long>& count)
{
    for (long long num = start; num <= end; ++num)
    {
        if (isPrime(num))
        {
            if (count++ >= threshold)
            {
                std::lock_guard<std::mutex> lock(fileMutex);
                file << num << std::endl;
            }
            else
            {
                std::cout << num << std::endl;
            }
        }
    }
}

int main()
{
    long long start, end, threshold;
    int numThreads;

    std::cout << "Enter the start number: ";
    std::cin >> start;
    std::cout << "Enter the end number: ";
    std::cin >> end;
    std::cout << "Enter the threshold for file writing: ";
    std::cin >> threshold;
    std::cout << "Enter the number of threads: ";
    std::cin >> numThreads;

    std::vector<std::thread> threads;
    std::mutex fileMutex;
    std::ofstream file("primes.txt");
    std::atomic<long long> count(0);

    long long range = (end - start + 1) / numThreads;
    long long remainder = (end - start + 1) % numThreads;

    long long currentStart = start;
    for (int i = 0; i < numThreads; ++i)
    {
        long long currentEnd = currentStart + range - 1;
        if (i == numThreads - 1)
        {
            currentEnd += remainder;
        }
        threads.emplace_back(processRange, currentStart, currentEnd, threshold, std::ref(fileMutex), std::ref(file), std::ref(count));
        currentStart = currentEnd + 1;
    }

    for (auto& t : threads)
    {
        t.join();
    }

    file.close();
    std::cout << "Processing complete. Primes above the threshold are stored in primes.txt." << std::endl;

    return 0;
}

#include <iostream>
