#pragma comment(lib, "mscoree.lib")
#pragma comment(lib, "ole32.lib")

// ManagedClass wrapper for .NET object
class ManagedClass
{
public:
    ManagedClass(ManagedObject^ obj) : _obj(obj) {}
    void DoWork() { _obj->DoWork(); }
    ~ManagedClass() { _obj->Dispose(); }

private:
    ManagedObject^ _obj;
};

// Abstract base for managed objects
class ManagedObject
{
public:
    virtual void DoWork() = 0;
    virtual void Dispose() = 0;
};

// Manages the .NET runtime and execution
class ManagedLibrary
{
public:
    ManagedLibrary()
    {
        // Initialize CLR hosting infrastructure
        HRESULT hr = CLRCreateInstance(CLSID_CLRMetaHost, IID_ICLRMetaHost, (LPVOID*)&_pMetaHost);
        if (FAILED(hr)) throw std::runtime_error("Failed to create CLRMetaHost");

        hr = _pMetaHost->GetRuntime(L"v4.0.30319", IID_ICLRRuntimeInfo, (LPVOID*)&_pRuntimeInfo);
        if (FAILED(hr)) throw std::runtime_error("Failed to get runtime info");

        BOOL isLoadable = FALSE;
        hr = _pRuntimeInfo->IsLoadable(&isLoadable);
        if (FAILED(hr) || !isLoadable) throw std::runtime_error("Runtime is not loadable");

        hr = _pRuntimeInfo->GetInterface(CLSID_CLRRuntimeHost, IID_ICLRRuntimeHost, (LPVOID*)&_pRuntimeHost);
        if (FAILED(hr)) throw std::runtime_error("Failed to get runtime host");

        hr = _pRuntimeHost->Start();
        if (FAILED(hr)) throw std::runtime_error("Failed to start runtime");

        hr = _pRuntimeHost->GetCLRControl(&_pCLRControl);
        if (FAILED(hr)) throw std::runtime_error("Failed to get CLR control");

        hr = _pCLRControl->GetHostControl(&_pHostControl);
        if (FAILED(hr)) throw std::runtime_error("Failed to get host control");

        hr = _pHostControl->QueryInterface(IID_IHostControl, (LPVOID*)&_pHostControl);
        if (FAILED(hr)) throw std::runtime_error("Failed to query host control");

        // Execute managed code in default app domain
        hr = _pRuntimeHost->ExecuteInDefaultAppDomain(L"ManagedLibrary.dll", L"ManagedLibrary.ManagedClass", L"Start", L"", &_pManagedObject);
        if (FAILED(hr)) throw std::runtime_error("Failed to execute in default app domain");
    }

    ~ManagedLibrary()
    {
        // Cleanup resources
        _pRuntimeHost->Stop();
        _pRuntimeHost->Release();
        _pRuntimeInfo->Release();
        _pMetaHost->Release();
    }

    void DoWork()
    {
        // Invoke managed method
        HRESULT hr = _pRuntimeHost->ExecuteInDefaultAppDomain(L"ManagedLibrary.dll", L"ManagedLibrary.ManagedClass", L"DoWork", L"", nullptr);
        if (FAILED(hr)) throw std::runtime_error("Failed to execute DoWork");
    }

private:
    ICLRMetaHost* _pMetaHost;
    ICLRRuntimeInfo* _pRuntimeInfo;
    ICLRRuntimeHost* _pRuntimeHost;
    ICLRControl* _pCLRControl;
    IHostControl* _pHostControl;
    _variant_t _pManagedObject;
};

// Entry point
int main()
{
    try
    {
        ManagedLibrary ml;
        ml.DoWork();
    }
    catch (const std::exception& e)
    {
        std::cerr << "Exception: " << e.what() << std::endl;
    }

    return 0;
}

