#include <iostream>
#include <cmath>

// Function to check if a number is prime
bool isPrime(int n)
{
    if (n <= 1)
    {
        return false; // 0 and 1 are not prime numbers
    }
    if (n == 2)
    {
        return true; // 2 is the only even prime number
    }
    if (n % 2 == 0)
    {
        return false; // Exclude other even numbers
    }
    // Check for factors from 3 to the square root of n
    for(int i=3;i<=std::sqrt(n);i+=2)
    {
        if(n%i==0)
        {
            return false;
        }
    }
    return true;
}

int main()
{
    std::cout<<"Prime numbers between 1 and 100 are:"<<std::endl;
    for(int i=1;i<=100;++i)
    {
        if(isPrime(i))
        {
            std::cout<<i<<" ";
        }
    }
    std::cout<<std::endl;
    return 0;

}

