// User class definition
class User {
public:
    std::string id;
    std::string name;
    int age;

    // Serialize user data to string
    std::string serialize() const {
        return id + "|" + name + "|" + std::to_string(age);
    }

    // Deserialize string to user object
    static User deserialize(const std::string& data) {
        User user;
        size_t pos1 = data.find('|');
        size_t pos2 = data.find('|', pos1 + 1);
        user.id = data.substr(0, pos1);
        user.name = data.substr(pos1 + 1, pos2 - pos1 - 1);
        user.age = std::stoi(data.substr(pos2 + 1));
        return user;
    }
};

// Repository for managing users in RocksDB
class UserRepository {
private:
    rocksdb::DB* db;
    rocksdb::Options options;

public:
    // Constructor initializes database connection
    UserRepository(const std::string& db_path) {
        options.create_if_missing = true;
        rocksdb::Status status = rocksdb::DB::Open(options, db_path, &db);
        if (!status.ok()) {
            std::cerr << "Error opening database: " << status.ToString() << std::endl;
        }
    }

    // Destructor cleans up database resources
    ~UserRepository() {
        delete db;
    }

    // Insert a new user
    rocksdb::Status insert(const User& user) {
        return db->Put(rocksdb::WriteOptions(), user.id, user.serialize());
    }

    // Update an existing user
    rocksdb::Status update(const User& user) {
        return db->Put(rocksdb::WriteOptions(), user.id, user.serialize());
    }

    // Remove a user by ID
    rocksdb::Status remove(const std::string& id) {
        return db->Delete(rocksdb::WriteOptions(), id);
    }

    // Get a user by ID
    rocksdb::Status get(const std::string& id, User& user) {
        std::string value;
        rocksdb::Status status = db->Get(rocksdb::ReadOptions(), id, &value);
        if (status.ok()) {
            user = User::deserialize(value);
        }
        return status;
    }
};

// Main function demonstrating usage
int main()
{
    UserRepository repo("path/to/db");

    User user1;
    user1.id = "1";
    user1.name = "Alice";
    user1.age = 30;

    repo.insert(user1);

    User user2;
    repo.get("1", user2);
    std::cout << "User found: " << user2.name << " (age: " << user2.age << ")" << std::endl;

    user2.name = "Alice Smith";
    repo.update(user2);

    repo.remove("1");

    return 0;

}

#include <iostream>
