// Function to load the TensorFlow model
TF_Graph* LoadModel(const char* model_path)
{
    TF_Graph* graph = TF_NewGraph();
    TF_Status* status = TF_NewStatus();
    TF_SessionOptions* session_options = TF_NewSessionOptions();

    TF_Buffer* graph_def = TF_NewBuffer();
    TF_ReadFileToBuffer(TF_NewSessionOptions(), model_path, graph_def, status);
    if (TF_GetCode(status) != TF_OK)
    {
        std::cerr << "Error reading model: " << TF_Message(status) << std::endl;
        TF_DeleteStatus(status);
        return nullptr;
    }

    TF_ImportGraphDefOptions* import_options = TF_NewImportGraphDefOptions();
    TF_GraphImportGraphDef(graph, graph_def, import_options, status);
    if (TF_GetCode(status) != TF_OK)
    {
        std::cerr << "Error importing graph: " << TF_Message(status) << std::endl;
        TF_DeleteStatus(status);
        return nullptr;
    }

    TF_DeleteBuffer(graph_def);
    TF_DeleteImportGraphDefOptions(import_options);
    TF_DeleteStatus(status);
    return graph;
}

// Function to run the model and get the sentiment
void RunSentimentAnalysis(TF_Graph* graph, const char* input_sentence)
{
    TF_SessionOptions* session_options = TF_NewSessionOptions();
    TF_Status* status = TF_NewStatus();
    TF_Session* session = TF_NewSession(graph, session_options, status);

    if (TF_GetCode(status) != TF_OK)
    {
        std::cerr << "Error creating session: " << TF_Message(status) << std::endl;
        TF_DeleteSession(session, status);
        TF_DeleteSessionOptions(session_options);
        TF_DeleteStatus(status);
        return;
    }

    // Define input and output tensors
    const char* input_name = "input_tensor_name:0";
    const char* output_name = "output_tensor_name:0";

    TF_Output input_op = {TF_GraphOperationByName(graph, input_name), 0};
    TF_Output output_op = {TF_GraphOperationByName(graph, output_name), 0};

    // Convert input sentence to a tensor
    TF_Tensor* input_tensor = TF_NewTensor(TF_STRING, nullptr, 0, &input_sentence, sizeof(input_sentence), nullptr, nullptr);

    // Run the session
    std::vector<TF_Output> inputs = {input_op};
    std::vector<TF_Tensor*> input_tensors = {input_tensor};
    std::vector<TF_Output> outputs = {output_op};
    std::vector<TF_Tensor*> output_tensors(1);

    TF_SessionRun(session, nullptr, &inputs[0], &input_tensors[0], 1, &outputs[0], &output_tensors[0], 1, nullptr, 0, nullptr, status);

    if (TF_GetCode(status) != TF_OK)
    {
        std::cerr << "Error running session: " << TF_Message(status) << std::endl;
        TF_DeleteSession(session, status);
        TF_DeleteSessionOptions(session_options);
        TF_DeleteStatus(status);
        return;
    }

    // Process the output
    float* output_data = static_cast<float*>(TF_TensorData(output_tensors[0]));
    int output_size = TF_TensorByteSize(output_tensors[0]) / sizeof(float);

    std::string sentiment = (output_data[0] > 0.5) ? "Positive" : "Negative";
    std::cout << "Sentiment: " << sentiment << std::endl;

    // Clean up
    TF_DeleteTensor(input_tensor);
    TF_DeleteTensor(output_tensors[0]);
    TF_DeleteSession(session, status);
    TF_DeleteSessionOptions(session_options);
    TF_DeleteStatus(status);
}

int main()
{
    const char* model_path = "path_to_your_model.pb";
    const char* input_sentence = "I love this product!";

    TF_Graph* graph = LoadModel(model_path);
    if (graph)
    {
        RunSentimentAnalysis(graph, input_sentence);
        TF_DeleteGraph(graph);
    }

    return 0;
}

