#include <iostream>
#include <vector>

// Tic Tac Toe game class
class TicTacToe {
public:
    // Constructor initializes the board and current player
    TicTacToe()
    {
        board = std::vector<std::vector<char>>(3, std::vector<char>(3, ' '));
        currentPlayer = 'X';
    }

    // Displays the current state of the board
    void displayBoard() const
    {
        for(int i=0;i<3;++i)
        {
            for(int j=0;j<3;++j)
            {
                std::cout<<board[i][j];
                if(j<2) std::cout<<" | ";
            }
            std::cout<<std::endl;
            if(i<2) std::cout<<"---------"<<std::endl;
        }
    }

    // Attempts to make a move at the specified position
    bool makeMove(int row, int col)
    {
        if(row<0||row>=3||col<0||col>=3||board[row][col]!=' ')
        {
            return false; // Invalid move
        }
        board[row][col] = currentPlayer;
        togglePlayer();
        return true;
    }

    // Checks if there's a winner or draw
    char checkWinner() const
    {
        // Check rows and columns
        for(int i=0;i<3;++i)
        {
            if(board[i][0]==board[i][1]&&board[i][1]==board[i][2]&&board[i][0]!=' ')
            {
                return board[i][0]; // Winner in row
            }
            if(board[0][i]==board[1][i]&&board[1][i]==board[2][i]&&board[0][i]!=' ')
            {
                return board[0][i]; // Winner in column
            }
        }

        // Check diagonals
        if(board[0][0]==board[1][1]&&board[1][1]==board[2][2]&&board[0][0]!=' ')
        {
            return board[0][0]; // Winner in diagonal
        }
        if(board[0][2]==board[1][1]&&board[1][1]==board[2][0]&&board[0][2]!=' ')
        {
            return board[0][2]; // Winner in diagonal
        }

        // Check for draw
        for(int i=0;i<3;++i)
        {
            for(int j=0;j<3;++j)
            {
                if(board[i][j]==' ')
                {
                    return ' '; // Game is not over
                }
            }
        }

        return 'D'; // Draw
    }

private:
    std::vector<std::vector<char>> board;
    char currentPlayer;

    // Switches the current player
    void togglePlayer()
    {
        currentPlayer = (currentPlayer=='X') ? 'O' : 'X';
    }
};

int main()
{
    TicTacToe game;
    game.displayBoard();

    // Example moves
    game.makeMove(0, 0);
    game.makeMove(1, 1);
    game.makeMove(0, 1);
    game.makeMove(1, 2);
    game.makeMove(0, 2);

    game.displayBoard();

    char winner = game.checkWinner();
    if(winner=='X'||winner=='O')
    {
        std::cout<<"Player "<<winner<<" wins!"<<std::endl;
    }
    else if(winner=='D')
    {
        std::cout<<"The game is a draw!"<<std::endl;
    }
    else
    {
        std::cout<<"The game is still ongoing!"<<std::endl;
    }

    return 0;

}

