// Structure definition for versionized pointer
struct TVersionizedPointer {
  std::intptr_t Ver;
  void* Ptr;
};

// Storage structure for versionized pointer
struct TVersionizedPointerStorage {
  char data[2 * sizeof(TVersionizedPointer)];
};

// Gets aligned versionized pointer from storage
TVersionizedPointer* GetVersionizedPointer(TVersionizedPointerStorage& PointerStorage)
{
    const size_t vp_size = sizeof(TVersionizedPointer);
    // Align address to vp_size boundary
    void* alignedAddress = reinterpret_cast<void*>(
        (reinterpret_cast<std::intptr_t>(&PointerStorage) + (vp_size - 1)) & ~(vp_size - 1)
    );
    return reinterpret_cast<TVersionizedPointer*>(alignedAddress);
}

