#include <windows.h>
#include <stdio.h>

// Function to check elevation and UAC status
BOOL IsCodeSigningPolicyEnabled()
{
    HANDLE hToken;
    TOKEN_ELEVATION Elevation;
    DWORD cbSize = sizeof(TOKEN_ELEVATION);

    // Open the access token associated with the calling process
    if (!OpenProcessToken(GetCurrentProcess(), TOKEN_QUERY, &hToken))
    {
        printf("OpenProcessToken failed with error %u\n", GetLastError());
        return FALSE;
    }

    // Get the elevation information
    if (!GetTokenInformation(hToken, TokenElevation, &Elevation, sizeof(Elevation), &cbSize))
    {
        printf("GetTokenInformation failed with error %u\n", GetLastError());
        CloseHandle(hToken);
        return FALSE;
    }

    // Check if the process is elevated
    if (Elevation.TokenIsElevated)
    {
        printf("The process is elevated.\n");
    }
    else
    {
        printf("The process is not elevated.\n");
    }

    // Check if User Account Control (UAC) is enabled
    HKEY hKey;
    if (RegOpenKeyEx(HKEY_LOCAL_MACHINE, TEXT("SOFTWARE\\Microsoft\\Windows\\CurrentVersion\\Policies\\System"), 0, KEY_READ, &hKey) == ERROR_SUCCESS)
    {
        DWORD dwValue;
        DWORD dwSize = sizeof(DWORD);
        if (RegQueryValueEx(hKey, TEXT("EnableLUA"), NULL, NULL, (LPBYTE)&dwValue, &dwSize) == ERROR_SUCCESS)
        {
            if (dwValue == 1)
            {
                printf("User Account Control (UAC) is enabled.\n");
            }
            else
            {
                printf("User Account Control (UAC) is disabled.\n");
            }
        }
        RegCloseKey(hKey);
    }

    CloseHandle(hToken);

    // Note: This does not directly check if code signing policy is enabled, but it provides related information.
    return Elevation.TokenIsElevated;
}

int main()
{
    if (IsCodeSigningPolicyEnabled())
    {
        printf("Code signing policy is likely enabled.\n");
    }
    else
    {
        printf("Code signing policy is likely not enabled.\n");
    }
    return 0;

}

