#include <iostream>
#include <unordered_set>

struct Node {
    int value;
    Node* both; // XOR of next and prev

    Node(int val) : value(val), both(nullptr) {}
};

struct XORLinkedList {
    Node* head;
    Node* tail;

    XORLinkedList() : head(nullptr), tail(nullptr) {}

    Node* XOR(Node* a, Node* b) {
        return reinterpret_cast<Node*>(reinterpret_cast<uintptr_t>(a) ^ reinterpret_cast<uintptr_t>(b));
    }

    void add(int value) {
        Node* newNode = new Node(value);
        if (!head) {
            head = tail = newNode;
            return;
        }
        Node* prevNode = tail;
        Node* nextNode = XOR(tail->both, nullptr);
        tail->both = XOR(newNode, nextNode);
        newNode->both = XOR(prevNode, nullptr);
        tail = newNode;
    }

    void reverse() {
        Node* curr = head;
        Node* prev = nullptr;
        Node* next = nullptr;

        while (curr) {
            next = XOR(prev, curr->both);
            curr->both = XOR(prev, next);
            prev = curr;
            curr = next;
        }

        head = prev; // last node is now the head
    }

    void print() {
        Node* curr = head;
        Node* prev = nullptr;
        Node* next;

        while (curr) {
            std::cout << curr->value << " ";
            next = XOR(prev, curr->both);
            prev = curr;
            curr = next;
        }
        std::cout << std::endl;
    }
};

// Main function to demonstrate XOR linked list operations
int main()
{
    XORLinkedList list;
    list.add(1);
    list.add(2);
    list.add(3);
    list.print(); // 1 2 3

    list.reverse();
    list.print(); // 3 2 1

    return 0;
}

