// Makes an HTTP request to the given URL and returns the response body
std::string makeRequest(const std::string& url)
{
    CURL *curl;
    CURLcode res;
    std::string readBuffer;

    // Initialize curl globally
    curl_global_init(CURL_GLOBAL_DEFAULT);

    // Initialize a curl session
    curl = curl_easy_init();

    if (curl) {
        // Set the URL for the request
        curl_easy_setopt(curl, CURLOPT_URL, url.c_str());

        // Set the callback function to handle received data
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, [](char *ptr, size_t size, size_t nmemb, std::string *data) {
            data->append(ptr, size * nmemb);
            return size * nmemb;
        });

        // Set the data pointer for the write callback
        curl_easy_setopt(curl, CURLOPT_WRITEDATA, &readBuffer);

        // Perform the request
        res = curl_easy_perform(curl);

        // Clean up the curl handle
        curl_easy_cleanup(curl);
    }

    // Clean up global curl resources
    curl_global_cleanup();

    return readBuffer;
}

int main()
{
    // Define the target URL
    std::string url = "http://localhost:5000/api/mycontroller/myfunction";

    // Make the request and store the response
    std::string response = makeRequest(url);

