// Swaps two integers using pointers
void swap(int* m, int* n)
{
    int t = *m;
    *m = *n;
    *n = t;
}

// Sorts three integers in descending order
void Descend(int &a, int &b, int &c)
{
    if(a < b)
    {
        swap(&a, &b);
    }
    if(a < c)
    {
        swap(&a, &c);
    }
    if(b < c)
    {
        swap(&b, &c);
    }
}

#include <llvm/ExecutionEngine/Orc/LLJIT.h>
#include <llvm/IR/IRBuilder.h>
#include <llvm/IR/Module.h>
#include <llvm/Support/TargetSelect.h>

using namespace llvm;

// Main function to demonstrate LLVM JIT execution
int main()
{
    // Initialize native target components
    InitializeNativeTarget();
    InitializeNativeTargetAsmPrinter();
    InitializeNativeTargetAsmParser();

    // Create LLJIT instance
    auto J = cantFail(LLJITBuilder().create());

    // Get execution session and context
    auto &Ctx = J->getExecutionSession().getTargetTriple().getLLVMContext();

    // Create a new module
    std::unique_ptr<Module> M = std::make_unique<Module>("module", Ctx);
    IRBuilder<> Builder(Ctx);

    // Define function type: void myFunction()
    FunctionType *FT = FunctionType::get(Type::getVoidTy(Ctx), false);
    Function *F = Function::Create(FT, Function::ExternalLinkage, "myFunction", M.get());

    // Create basic block and set insertion point
    BasicBlock *BB = BasicBlock::Create(Ctx, "entry", F);
    Builder.SetInsertPoint(BB);

    // Emit x86 xadd instruction via intrinsic
    Builder.CreateCall(
        Intrinsic::getDeclaration(M.get(), Intrinsic::x86_xadd_32),
        {Builder.getInt32(0), Builder.getInt32(1)}
    );

    // Return from function
    Builder.CreateRetVoid();

    // Add module to JIT and lookup function
    cantFail(J->addIRModule(std::move(M)));
    auto FPtr = cantFail(J->lookup("myFunction"));

    // Cast function pointer and execute
    typedef void (*FunctionType)();
    FunctionType MyFunction = (FunctionType)(intptr_t)FPtr;
    MyFunction();

    return 0;
}

