// Atomic variables for thread synchronization
std::atomic<int> x(0);
std::atomic<int> y(0);
int r1, r2;

// Thread 1: writes to x and reads from y
void thread1()
{
    x.store(1, std::memory_order_seq_cst);
    r1 = y.load(std::memory_order_seq_cst);
}

// Thread 2: writes to y and reads from x
void thread2()
{
    y.store(1, std::memory_order_seq_cst);
    r2 = x.load(std::memory_order_seq_cst);
}

int main()
{
    // Create threads
    std::thread t1(thread1);
    std::thread t2(thread2);

    // Wait for both threads to complete
    t1.join();
    t2.join();

    // Verify at least one thread observed the other's write
    assert(r1 != 0 || r2 != 0); // This should always be true

}

#include <iostream>
#include <vector>
#include <cstdlib>
#include <ctime>

using namespace std;

const int GRID_SIZE = 5;
const int NUM_MINES = 5;

class Minesweeper {
public:
    Minesweeper() {
        srand(time(0));
        placeMines();
        calculateNumbers();
    }

    void play()
    {
        while (true) {
            printBoard();
            int row, col;
            cout << "Enter the row and column to reveal (0-4): ";
            cin >> row >> col;

            if (row < 0 || row >= GRID_SIZE || col < 0 || col >= GRID_SIZE) {
                cout << "Invalid input. Try again." << endl;
                continue;
            }

            if (board[row][col] == -1) {
                cout << "Game Over! You hit a mine." << endl;
                revealBoard();
                break;
            }

            if (board[row][col] == 0) {
                revealEmptyCells(row, col);
            } else {
                revealed[row][col] = true;
            }

            if (checkWin()) {
                cout << "Congratulations! You won the game." << endl;
                revealBoard();
                break;
            }
        }
    }

private:
    vector<vector<int>> board;
    vector<vector<bool>> revealed;

    // Places mines randomly on the board
    void placeMines()
    {
        board.resize(GRID_SIZE, vector<int>(GRID_SIZE, 0));
        revealed.resize(GRID_SIZE, vector<bool>(GRID_SIZE, false));

        int minesPlaced = 0;
        while (minesPlaced < NUM_MINES) {
            int row = rand() % GRID_SIZE;
            int col = rand() % GRID_SIZE;
            if (board[row][col] != -1) {
                board[row][col] = -1;
                minesPlaced++;
            }
        }
    }

    // Calculates the number of adjacent mines for each cell
    void calculateNumbers()
    {
        for (int row = 0; row < GRID_SIZE; row++) {
            for (int col = 0; col < GRID_SIZE; col++) {
                if (board[row][col] == -1) {
                    continue;
                }
                int count = 0;
                for (int dr = -1; dr <= 1; dr++) {
                    for (int dc = -1; dc <= 1; dc++) {
                        int r = row + dr, c = col + dc;
                        if (r >= 0 && r < GRID_SIZE && c >= 0 && c < GRID_SIZE && board[r][c] == -1) {
                            count++;
                        }
                    }
                }
                board[row][col] = count;
            }
        }
    }

    // Recursively reveals empty cells using flood fill
    void revealEmptyCells(int row, int col)
    {
        if (row < 0 || row >= GRID_SIZE || col < 0 || col >= GRID_SIZE || revealed[row][col]) {
            return;
        }

        revealed[row][col] = true;
        if (board[row][col] == 0) {
            for (int dr = -1; dr <= 1; dr++) {
                for (int dc = -1; dc <= 1; dc++) {
                    revealEmptyCells(row + dr, col + dc);
                }
            }
        }
    }

    // Prints the current state of the board
    void printBoard()
    {
        for (int row = 0; row < GRID_SIZE; row++) {
            for (int col = 0; col < GRID_SIZE; col++) {
                if (revealed[row][col]) {
                    if (board[row][col] == -1) {
                        cout << "M ";
                    } else {
                        cout << board[row][col] << " ";
                    }
                } else {
                    cout << "# ";
                }
            }
            cout << endl;
        }
    }

    // Reveals all mines when game ends
    void revealBoard()
    {
        for (int row = 0; row < GRID_SIZE; row++) {
            for (int col = 0; col < GRID_SIZE; col++) {
                if (board[row][col] == -1) {
                    cout << "M ";
                } else {
                    cout << board[row][col] << " ";
                }
            }
            cout << endl;
        }
    }

    // Checks if player has won
    bool checkWin()
    {
        for (int row = 0; row < GRID_SIZE; row++) {
            for (int col = 0; col < GRID_SIZE; col++) {
                if (board[row][col] != -1 && !revealed[row][col]) {
                    return false;
                }
            }
        }
        return true;
    }
};

// Main function to start the game
int main()
{
    Minesweeper game;
    game.play();
    return 0;
}

