// Loads armature data from a JSON file into the 3D scene
void loadArmatureFromJson(const QString &jsonFilePath, Qt3DCore::QEntity *rootEntity)
{
    QFile file(jsonFilePath);
    if (!file.open(QIODevice::ReadOnly | QIODevice::Text))
    {
        qWarning("Failed to open JSON file");
        return;
    }

    QByteArray jsonData = file.readAll();
    QJsonDocument doc = QJsonDocument::fromJson(jsonData);
    QJsonObject jsonObject = doc.object();

    // Load skeleton
    Qt3DRender::QSkeleton *skeleton = new Qt3DRender::QSkeleton(rootEntity);
    Qt3DRender::QSkeletonLoader *skeletonLoader = new Qt3DRender::QSkeletonLoader(rootEntity);
    skeletonLoader->setSource(QUrl::fromLocalFile(jsonFilePath));
    skeleton->setLoader(skeletonLoader);

    // Load animations
    QJsonArray animations = jsonObject.value("animations").toArray();
    for (const QJsonValue &animationValue : animations)
    {
        QJsonObject animationObject = animationValue.toObject();
        Qt3DAnimation::QAnimationClip *clip = new Qt3DAnimation::QAnimationClip(rootEntity);
        clip->setDuration(animationObject.value("duration").toDouble());
        clip->setLoopCount(animationObject.value("loopCount").toInt());

        QJsonArray channels = animationObject.value("channels").toArray();
        for (const QJsonValue &channelValue : channels)
        {
            QJsonObject channelObject = channelValue.toObject();
            Qt3DAnimation::QChannelMapper *mapper = new Qt3DAnimation::QChannelMapper(rootEntity);
            mapper->setChannelName(channelObject.value("channelName").toString());
            mapper->setBoneName(channelObject.value("boneName").toString());

            QJsonArray keys = channelObject.value("keys").toArray();
            for (const QJsonValue &keyValue : keys)
            {
                QJsonObject keyObject = keyValue.toObject();
                Qt3DAnimation::QKeyframe *keyframe = new Qt3DAnimation::QKeyframe(rootEntity);
                keyframe->setTime(keyObject.value("time").toDouble());
                keyframe->setTranslation(QVector3D(
                    keyObject.value("translationX").toDouble(),
                    keyObject.value("translationY").toDouble(),
                    keyObject.value("translationZ").toDouble()
                ));
                keyframe->setRotation(QQuaternion(
                    keyObject.value("rotationW").toDouble(),
                    keyObject.value("rotationX").toDouble(),
                    keyObject.value("rotationY").toDouble(),
                    keyObject.value("rotationZ").toDouble()
                ));
                keyframe->setScale(QVector3D(
                    keyObject.value("scaleX").toDouble(),
                    keyObject.value("scaleY").toDouble(),
                    keyObject.value("scaleZ").toDouble()
                ));
                mapper->addKeyframe(keyframe);
            }

            clip->addChannelMapper(mapper);
        }

        Qt3DAnimation::QClipAnimator *clipAnimator = new Qt3DAnimation::QClipAnimator(rootEntity);
        clipAnimator->setClip(clip);
        clipAnimator->setTarget(skeleton);
        rootEntity->addComponent(clipAnimator);
    }
}

