// Function to find maximum value in a vector
int find_max(const std::vector<int>& arr)
{
    // Handle empty array case
    if (arr.empty()) return INT_MIN;

    int max_value = arr[0];
    // Iterate through all elements
    for(int num : arr)
    {
        if(num > max_value)
        {
            max_value = num;
        }
    }
    return max_value;
}

