// Base class for IR nodes
class IRNode {
public:
    virtual std::string generateAssembly() const = 0;
};

// If node implementation
class IfNode : public IRNode {
private:
    IRNode* condition;
    IRNode* trueBlock;
    IRNode* falseBlock;
    std::string label;

public:
    // Constructor
    IfNode(IRNode* cond, IRNode* trueBlock, IRNode* falseBlock, std::string label)
        : condition(cond), trueBlock(trueBlock), falseBlock(falseBlock), label(label) {}

    // Generate assembly code
    std::string generateAssembly() const override {
        std::string assembly = "";

        assembly += condition->generateAssembly();
        assembly += "jmp .false" + label + "\n";
        assembly += ".true" + label + ":\n";
        assembly += trueBlock->generateAssembly();
        assembly += "jmp .end" + label + "\n";
        assembly += ".false" + label + ":\n";
        assembly += falseBlock->generateAssembly();
        assembly += ".end" + label + ":\n";

        return assembly;
    }
};

// Comparison node implementation
class ComparisonNode : public IRNode {
private:
    std::string op;
    IRNode* left;
    IRNode* right;
    std::string label;  // Added missing label member

public:
    // Constructor
    ComparisonNode(std::string op, IRNode* left, IRNode* right)
        : op(op), left(left), right(right), label("comp") {}  // Initialize label

    // Generate assembly code
    std::string generateAssembly() const override {
        std::string assembly = "";

        assembly += left->generateAssembly();
        assembly += right->generateAssembly();
        assembly += "cmp %eax, %ebx\n";
        assembly += "je .true" + label + "\n";
        assembly += "jmp .false" + label + "\n";

        return assembly;
    }
};

// Placeholder classes to make the example compile
class ConstantNode : public IRNode {
private:
    int value;
public:
    ConstantNode(int v) : value(v) {}
    std::string generateAssembly() const override {
        return "mov $" + std::to_string(value) + ", %eax\n";
    }
};

class InstructionNode : public IRNode {
private:
    std::string instruction;
public:
    InstructionNode(std::string instr) : instruction(instr) {}
    std::string generateAssembly() const override {
        return instruction + "\n";
    }
};

class BlockNode : public IRNode {
private:
    std::vector<IRNode*> instructions;
public:
    BlockNode(std::vector<IRNode*> insts) : instructions(insts) {}
    std::string generateAssembly() const override {
        std::string result;
        for (auto* inst : instructions) {
            result += inst->generateAssembly();
        }
        return result;
    }
};

// Main function - Example usage
int main()
{
    // Create condition: 1 == 1
    IRNode* condition = new ComparisonNode("==", new ConstantNode(1), new ConstantNode(1));

    // Create true block
    IRNode* trueBlock = new BlockNode({ new InstructionNode("mov $1, %eax") });

    // Create false block
    IRNode* falseBlock = new BlockNode({ new InstructionNode("mov $0, %eax") });

    // Create if node
    IfNode* ifNode = new IfNode(condition, trueBlock, falseBlock, "if1");

    // Generate and print assembly
    std::string assembly = ifNode->generateAssembly();
    std::cout << assembly << std::endl;

    // Clean up memory
    delete condition;
    delete trueBlock;
    delete falseBlock;
    delete ifNode;

    return 0;
}

