// Type alias for unsigned 32-bit integer
using T = uint32_t; // or uint64_t

// Performs a bitwise shift operation combining bits from x and y
T shift(T x, T y, T n)
{
    // Create mask with n least significant bits set
    T mask = (T(1) << n) - 1;
    // Shift x right by n, then OR with (y & mask) shifted left by (digits - n)
    return (x >> n) | ((y & mask) << (std::numeric_limits<T>::digits - n));
}

