// Function to find union of two sorted arrays
std::vector<int> findUnion(const std::vector<int>& arr1, const std::vector<int>& arr2)
{
    std::vector<int> unionSet;
    size_t i = 0, j = 0;

    // Traverse both arrays
    while(i < arr1.size() && j < arr2.size())
    {
        if(arr1[i] < arr2[j])
        {
            if(unionSet.empty() || unionSet.back() != arr1[i])
            {
                unionSet.push_back(arr1[i]);
            }
            ++i;
        }
        else if(arr1[i] > arr2[j])
        {
            if(unionSet.empty() || unionSet.back() != arr2[j])
            {
                unionSet.push_back(arr2[j]);
            }
            ++j;
        }
        else // Elements are equal
        {
            if(unionSet.empty() || unionSet.back() != arr1[i])
            {
                unionSet.push_back(arr1[i]);
            }
            ++i;
            ++j;
        }
    }

    // Add remaining elements from arr1
    while(i < arr1.size())
    {
        if(unionSet.empty() || unionSet.back() != arr1[i])
        {
            unionSet.push_back(arr1[i]);
        }
        ++i;
    }

    // Add remaining elements from arr2
    while(j < arr2.size())
    {
        if(unionSet.empty() || unionSet.back() != arr2[j])
        {
            unionSet.push_back(arr2[j]);
        }
        ++j;
    }

    return unionSet;
}

int main()
{
    std::vector<int> arr1 = {1, 2, 4, 5, 6};
    std::vector<int> arr2 = {2, 3, 5, 7};

    std::vector<int> result = findUnion(arr1, arr2);

    std::cout << "Union of the two arrays is: ";
    for(int num : result)
    {
        std::cout << num << " ";
    }
    std::cout << std::endl;

    return 0;
}

#include <immintrin.h>

// Calculates attributes using SIMD
void calculate_attributes(float* array, float* c, float* d, int n)
{
    __m256 vec_a, vec_b, vec_e, vec_c, vec_d;
    for(int i=0;i<n;i+=8)
    {
        vec_a = _mm256_loadu_ps(&array[i*3+0]);
        vec_b = _mm256_loadu_ps(&array[i*3+1]);
        vec_e = _mm256_loadu_ps(&array[i*3+2]);

        // Perform calculations using SIMD instructions
        vec_c = _mm256_add_ps(vec_a, vec_b);
        vec_d = _mm256_sub_ps(vec_a, vec_e);

        _mm256_storeu_ps(&c[i], vec_c);
        _mm256_storeu_ps(&d[i], vec_d);
    }
}

