// Main function for text-to-speech using SAPI and Qt
int main(int argc, char *argv[])
{
    QCoreApplication a(argc, argv);

    // Initialize COM
    CoInitialize(NULL);

    ISpVoice *pVoice = NULL;
    HRESULT hr = CoCreateInstance(CLSID_SpVoice, NULL, CLSCTX_ALL, IID_ISpVoice, (void **)&pVoice);

    if (FAILED(hr)) 
    {
        std::cerr << "Failed to create SAPI voice object" << std::endl;
        return -1;
    }

    // Enumerate available voices
    ISpObjectToken *pToken = NULL;
    IEnumSpObjectTokens *pEnum = NULL;

    hr = SpEnumTokens(SPCAT_VOICES, NULL, NULL, &pEnum);

    if (SUCCEEDED(hr)) 
    {
        while (pEnum->Next(1, &pToken, NULL) == S_OK) 
        {
            SPVOICESTATUS status;
            hr = pVoice->GetStatus(&status, NULL);

            if (SUCCEEDED(hr)) 
            {
                SPVOICECATEGORY category;
                pToken->GetCategory(&category);

                if (category == SPCAT_VOICES) 
                {
                    BSTR bstrId, bstrName;
                    pToken->GetId(&bstrId);
                    pToken->GetDescription(&bstrName);

                    std::wcout << L"Voice ID: " << bstrId << L", Name: " << bstrName << std::endl;

                    SysFreeString(bstrId);
                    SysFreeString(bstrName);
                }
            }

            pToken->Release();
        }

        pEnum->Release();
    }

    // Set the desired Acapela voice
    hr = SpFindBestToken(SPCAT_VOICES, L"Name=Acapela Voice Name", NULL, &pToken);

    if (SUCCEEDED(hr)) 
    {
        hr = pVoice->SetVoice(pToken);

        if (FAILED(hr)) 
        {
            std::cerr << "Failed to set the Acapela voice" << std::endl;
        }
    } 
    else 
    {
        std::cerr << "Acapela voice not found" << std::endl;
    }

    // Speak some text
    hr = pVoice->Speak(L"Hello, this is an Acapela voice.", SPF_DEFAULT, NULL);

    if (FAILED(hr)) 
    {
        std::cerr << "Failed to speak text" << std::endl;
    }

    // Clean up resources
    if (pToken) pToken->Release();
    if (pVoice) pVoice->Release();

    CoUninitialize();

    return a.exec();
}

