// RAII class to execute a function on scope exit
class FrameExitTask {
    std::function<void()> func_;
public:
    // Constructor stores the function
    FrameExitTask(std::function<void()> func) : func_(func) {}

    // Destructor executes the stored function
    ~FrameExitTask() {
        func_();
    }

    // Delete copy and move operations
    FrameExitTask& operator=(const FrameExitTask&) = delete;
    FrameExitTask(const FrameExitTask&) = delete;
    FrameExitTask& operator=(FrameExitTask&&) = delete;
    FrameExitTask(FrameExitTask&&) = delete;
};

