#include <chrono>

// Assembly version using inline assembly
void asm_version(int ia_array[5][5][5])
{
    int i = 0, j = 0, k = 0;
    while (i < 5)
    {
        ia_array[i][j][k] = 0;
        __asm inc k;

        if (k > 4)
        {
            __asm inc j;
            __asm mov k, 0;
        }
        if (j > 4)
        {
            __asm inc i;
            __asm mov j, 0;
        }
    }
}

// Loop version using nested for loops
void loop_version(int ia_array[5][5][5])
{
    for(int i=0;i<5;++i)
    {
        for(int j=0;j<5;++j)
        {
            for(int k=0;k<5;++k)
            {
                ia_array[i][j][k] = 0;
            }
        }
    }
}

int main()
{
    int ia_array1[5][5][5];
    int ia_array2[5][5][5];

    auto start1 = std::chrono::high_resolution_clock::now();
    asm_version(ia_array1);
    auto end1 = std::chrono::high_resolution_clock::now();
    auto duration1 = std::chrono::duration_cast<std::chrono::microseconds>(end1 - start1);

    auto start2 = std::chrono::high_resolution_clock::now();
    loop_version(ia_array2);
    auto end2 = std::chrono::high_resolution_clock::now();
    auto duration2 = std::chrono::duration_cast<std::chrono::microseconds>(end2 - start2);

    // Output timing results
    std::cout<<"ASM version took: "<<duration1.count()<<" microseconds"<<std::endl;
    std::cout<<"Loop version took: "<<duration2.count()<<" microseconds"<<std::endl;

    return 0;

}

#include <arpa/inet.h>  // for htonl and ntohl

// Sends a float array over a socket in big-endian format
void sendFloatArray(SOCKET csock, const float* arr, int size)
{
    char buffer[12 * sizeof(float)];
    for(int i=0;i<size;++i)
    {
        uint32_t floatAsInt = *reinterpret_cast<uint32_t*>(&arr[i]);
        uint32_t bigEndianFloat = htonl(floatAsInt);
        memcpy(&buffer[i * sizeof(float)], &bigEndianFloat, sizeof(float));
    }
    // Send the buffer
    send(csock, buffer, size * sizeof(float), 0);
}

