// Parses a Python-style dictionary string into a C++ map
std::map<std::string, std::string> parsePythonStrDict(const std::string &strDict)
{
    std::map<std::string, std::string> parsedDict;

    std::size_t start = strDict.find('{');
    std::size_t end = strDict.rfind('}');
    std::string keyValuePairs = strDict.substr(start + 1, end - start - 1);

    std::stringstream ss(keyValuePairs);
    std::string keyValuePair;

    while (std::getline(ss, keyValuePair, ','))
    {
        std::size_t colonPos = keyValuePair.find(':');
        std::string key = keyValuePair.substr(0, colonPos);
        std::string value = keyValuePair.substr(colonPos + 1);

        // Trim whitespace and quotes from key
        key = key.substr(key.find_first_not_of(" '\"{"));
        key = key.substr(0, key.find_last_not_of(" '\"}") + 1);

        // Trim whitespace and quotes from value
        value = value.substr(value.find_first_not_of(" '\""));
        value = value.substr(0, value.find_last_not_of(" '\"") + 1);

        parsedDict[key] = value;
    }

    return parsedDict;
}

int main()
{
    std::string pythonStrDict = "{'item1': 1, 'item2': 2.0, 'item3': 'a string', 'item4': 'another string'}";

    std::map<std::string, std::string> myMap = parsePythonStrDict(pythonStrDict);

    for (const auto &item : myMap)
    {
        std::cout << item.first << ": " << item.second << std::endl;
    }

    return 0;
}

