// Template class for enum-like functionality
template <typename T, typename ValueT>
class Enum {
public:
    // Returns the vector of all enum values
    static std::vector<T>& values() {
        static std::vector<T> gValues;
        return gValues;
    }

    // Convert from name to enum value
    static T fromName(const std::string& name) {
        for (const auto& value : values()) {
            if (value.getName() == name) {
                return value;
            }
        }
        throw std::invalid_argument("No enum value with name: " + name);
    }

    // Convert from underlying value to enum value
    static T fromValue(const ValueT& value) {
        for (const auto& enumValue : values()) {
            if (enumValue.getValue() == value) {
                return enumValue;
            }
        }
        throw std::invalid_argument("No enum value with value: " + std::to_string(value));
    }

    // Get the name of the enum value
    std::string getName() const {
        return mName;
    }

    // Get the underlying value
    ValueT getValue() const {
        return mValue;
    }

    // Equality operator
    bool operator==(const T& other) const {
        return mName == other.mName && mValue == other.mValue;
    }

    // Inequality operator
    bool operator!=(const T& other) const {
        return !(*this == other);
    }

protected:
    // Protected constructor to ensure only derived classes can instantiate
    Enum(const std::string& name, const ValueT& value) : mName(name), mValue(value) {
        values().push_back(static_cast<T>(*this));
    }

private:
    std::string mName;
    ValueT mValue;
};

