// Get current tick count using RDTSC instruction
uint64_t getTicks()
{
    uint64_t ticks;
    __asm__ __volatile__("rdtsc" : "=A"(ticks));
    return ticks;
}

// Calculate processor speed in Hz
double ProcSpeedCalc()
{
    // Replace with your actual CPU frequency in Hz
    return 3.2e9;  // Example: 3.2 GHz
}

// Write data to memory without caching (using streaming stores)
void memory_notCache_write_128(void* src, long blocks_amount)
{
    __m128i xmm0 = _mm_setzero_si128();
    __m128i xmm1 = _mm_setzero_si128();
    __m128i xmm2 = _mm_setzero_si128();
    __m128i xmm3 = _mm_setzero_si128();
    __m128i xmm4 = _mm_setzero_si128();
    __m128i xmm5 = _mm_setzero_si128();
    __m128i xmm6 = _mm_setzero_si128();
    __m128i xmm7 = _mm_setzero_si128();

    char* esi = static_cast<char*>(src);
    for(long i=0; i<blocks_amount; ++i)
    {
        _mm_stream_si128(reinterpret_cast<__m128i*>(esi + 0*16), xmm0);
        _mm_stream_si128(reinterpret_cast<__m128i*>(esi + 1*16), xmm1);
        _mm_stream_si128(reinterpret_cast<__m128i*>(esi + 2*16), xmm2);
        _mm_stream_si128(reinterpret_cast<__m128i*>(esi + 3*16), xmm3);
        _mm_stream_si128(reinterpret_cast<__m128i*>(esi + 4*16), xmm4);
        _mm_stream_si128(reinterpret_cast<__m128i*>(esi + 5*16), xmm5);
        _mm_stream_si128(reinterpret_cast<__m128i*>(esi + 6*16), xmm6);
        _mm_stream_si128(reinterpret_cast<__m128i*>(esi + 7*16), xmm7);
        esi += 128;
    }
}

int main()
{
    unsigned __int64 tick1, tick2;
    const long nBytes = 32 * KByte;
    const long blocks_amount = nBytes / 128;

    char* source = static_cast<char*>(_mm_malloc(nBytes, 16));

    tick1 = getTicks();
    memory_notCache_write_128(source, blocks_amount);
    tick2 = getTicks();

    double time = static_cast<double>(tick2 - tick1) / ProcSpeedCalc();
    std::cout << "Time WRITE_128 [seconds]:" << time << std::endl;
    std::cout << "Write Speed [MB/s]:" << static_cast<double>(nBytes) / time / MByte << std::endl;

    _mm_free(source);
    return 0;
}

