// Calculates the mean of a vector of numbers
double calculateMean(const std::vector<double>& numbers)
{
    if(numbers.empty())
    {
        return 0;
    }
    double sum = 0;
    for(double number : numbers)
    {
        sum += number;
    }
    // Return average
    return sum / numbers.size();
}

int main()
{
    std::vector<double> numbers = {1, 2, 3, 4, 5};
    double meanValue = calculateMean(numbers);
    // Print the mean value
    std::cout<<"Mean value: "<<meanValue<<std::endl;
    return 0;

}

