// Function to get the current call stack size
int CallStackSize()
{
    void* callStack[1024];
    unsigned int frames;
    SYMBOL_INFO* symbol;
    HANDLE process;

    // Initialize the process handle
    process = GetCurrentProcess();

    // Initialize symbol handler
    SymInitialize(process, NULL, TRUE);

    // Capture the stack back trace
    frames = CaptureStackBackTrace(0, 1024, callStack, NULL);

    // Clean up symbol handler
    SymCleanup(process);

    // Return the number of frames captured
    return frames;
}

