// Reverses the byte order of 32-bit values in an array
void my_function(uint32_t *src, uint32_t *dst)
{
    // Load 4 32-bit values as uint8x16_t
    uint8x16_t x = vreinterpretq_u8_u32(vld1q_u32(src));
    // Reverse bytes within each 32-bit element
    uint8x16_t y = vrev32q_u8(x);
    // Store result back as uint32_t values
    vst1q_u32(dst, vreinterpretq_u32_u8(y));
