// Definition for singly-linked list.
struct ListNode {
    int val;
    ListNode *next;
    ListNode(int x) : val(x), next(NULL) {}
};

// Function to detect a cycle in a linked list.
bool hasCycle(ListNode *head)
{
    if(head == NULL || head->next == NULL)
    {
        return false;
    }

    ListNode *slow = head;
    ListNode *fast = head;

    while(fast != NULL && fast->next != NULL)
    {
        slow = slow->next;          // Move slow pointer by one step
        fast = fast->next->next;    // Move fast pointer by two steps

        if(slow == fast)            // If they meet, there is a cycle
        {
            return true;
        }
    }

    return false;  // If we reach here, there is no cycle
}

// Function to create a linked list with a cycle for testing.
ListNode* createListWithCycle()
{
    ListNode *head = new ListNode(1);
    ListNode *second = new ListNode(2);
    ListNode *third = new ListNode(3);
    ListNode *fourth = new ListNode(4);

    head->next = second;
    second->next = third;
    third->next = fourth;
    fourth->next = second;  // Creating a cycle

    return head;
}

// Main function to test the cycle detection.
int main()
{
    ListNode *head = createListWithCycle();

    if(hasCycle(head))
    {
        cout << "Cycle detected in the linked list." << endl;
    }
    else
    {
        cout << "No cycle detected in the linked list." << endl;
    }

    return 0;
}

