#include <cmath>
#include <random>
#include <limits>

// Q-learning implementation for a simple grid world

const int NUM_STATES = 5;
const int NUM_ACTIONS = 2;
const double LEARNING_RATE = 0.1;
const double DISCOUNT_FACTOR = 0.9;
const double EXPLORATION_RATE = 0.1;
const int NUM_EPISODES = 1000;

// Q-table initialization
std::vector<std::vector<double>> Q(NUM_STATES, std::vector<double>(NUM_ACTIONS, 0.0));

// Get next state and reward based on current state and action
std::pair<int, double> get_next_state_and_reward(int state, int action)
{
    int next_state = state + action;
    double reward = 0.0;

    if (next_state < 0 || next_state >= NUM_STATES)
    {
        next_state = state;
        reward = -1.0;
    }
    else if (next_state == NUM_STATES - 1)
    {
        reward = 10.0;
    }

    return {next_state, reward};
}

// Epsilon-greedy action selection
int choose_action(int state)
{
    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_real_distribution<> dis(0.0, 1.0);

    if (dis(gen) < EXPLORATION_RATE)
    {
        // Exploration: random action
        std::uniform_int_distribution<> action_dist(0, NUM_ACTIONS - 1);
        return action_dist(gen);
    }
    else
    {
        // Exploitation: best action
        double max_q = -std::numeric_limits<double>::max();
        int best_action = 0;
        for (int action = 0; action < NUM_ACTIONS; ++action)
        {
            if (Q[state][action] > max_q)
            {
                max_q = Q[state][action];
                best_action = action;
            }
        }
        return best_action;
    }
}

// Main Q-learning loop
void q_learning()
{
    for (int episode = 0; episode < NUM_EPISODES; ++episode)
    {
        int state = 0;

        while (state != NUM_STATES - 1)
        {
            int action = choose_action(state);
            auto [next_state, reward] = get_next_state_and_reward(state, action);

            double max_q_next = -std::numeric_limits<double>::max();
            for (int next_action = 0; next_action < NUM_ACTIONS; ++next_action)
            {
                if (Q[next_state][next_action] > max_q_next)
                {
                    max_q_next = Q[next_state][next_action];
                }
            }

            Q[state][action] += LEARNING_RATE * (reward + DISCOUNT_FACTOR * max_q_next - Q[state][action]);

            state = next_state;
        }
    }
}

// Display the learned Q-values
void print_q_table()
{
    for (int state = 0; state < NUM_STATES; ++state)
    {
        for (int action = 0; action < NUM_ACTIONS; ++action)
        {
            std::cout << "Q(" << state << ", " << action << ") = " << Q[state][action] << std::endl;
        }
    }
}

int main()
{
    q_learning();
    print_q_table();
    return 0;
}

