// Main function to find the minimum sum subarray of size m
int main()
{
    long long n, m, k;
    cin.sync_with_stdio(false);
    cin >> n >> m >> k;

    long long sum = 0, minSum = 0;
    long long startIndex = 1, endIndex = m;

    queue<long long> q;

    for (long long i = 1; i <= n; i++)
    {
        long long a;
        cin >> a;
        sum += a;
        q.push(a);

        if (i >= m)
        {
            if (i > m)
            {
                sum -= q.front();
                q.pop();
            }

            if (sum < minSum)
            {
                minSum = sum;
                startIndex = i - m + 1;
                endIndex = i;
            }
        }
    }

    // Output the starting and ending indices
    cout << startIndex << " " << endIndex << endl;

    return 0;

}

