#include <cuda_runtime.h>

// Texture reference declaration
texture<float, 2, cudaReadModeElementType> tex;

// Kernel function to copy texture data to output array
__global__ void kernel(float *output, int width, int height)
{
    int x = blockIdx.x * blockDim.x + threadIdx.x;
    int y = blockIdx.y * blockDim.y + threadIdx.y;

    if(x < width && y < height)
    {
        output[y * width + x] = tex2D(tex, x, y);
    }
}

int main()
{
    float *d_data;
    // Allocate device memory
    cudaMalloc(&d_data, width * height * sizeof(float));
    // Copy data from host to device
    cudaMemcpy(d_data, h_data, width * height * sizeof(float), cudaMemcpyHostToDevice);

    // Create channel descriptor
    cudaChannelFormatDesc channelDesc = cudaCreateChannelDesc<float>();
    // Bind 2D texture
    cudaBindTexture2D(0, &tex, d_data, &channelDesc, width, height, width * sizeof(float));

    // Define block and grid dimensions
    dim3 blockSize(16, 16);
    dim3 gridSize((width + blockSize.x - 1) / blockSize.x, (height + blockSize.y - 1) / blockSize.y);

    // Launch kernel
    kernel<<<gridSize, blockSize>>>(d_data, width, height);

    // Cleanup resources
    cudaUnbindTexture(tex);
    cudaFree(d_data);

    return 0;
}

#include <iostream>

// Evaluates a polynomial at a given point
float Polynomial(int n, int a[], float x0) 
{   
    int i;
    float P = 0;

    // Handle constant case
    if(n == 0)
    {
        P = a[0];
    }
    else
    {
        P = a[0];
        for(i = 1; i <= n; i++)
        {
            P += a[i] * x0;
            x0 *= x0;
        }
    }

    // Return the result
    return P;  
}

