// Prefetches a memory line into cache
void prefetch_line(void* addr, int level)
{
    switch(level)
    {
        case 0: _mm_prefetch((char*)addr, _MM_HINT_T0); break;
        case 1: _mm_prefetch((char*)addr, _MM_HINT_T1); break;
        case 2: _mm_prefetch((char*)addr, _MM_HINT_T2); break;
        case 3: _mm_prefetch((char*)addr, _MM_HINT_NTA); break;
    }
}

