#include <immintrin.h>

struct vector4 {
    float x, y, z, w;
};

// Performs SIMD-based vector calculation
void assemblycalc(vector4 &p, vector4 &sc, float m, vector4 &xy, vector4 &result)
{
    __m128 px = _mm_loadu_ps(&p.x);
    __m128 scx = _mm_loadu_ps(&sc.x);
    __m128 m128 = _mm_set1_ps(m);
    __m128 xy128 = _mm_loadu_ps(&xy.x);

    // Compute (px * c - py * s) and (px * s - py * c)
    __m128 psc = _mm_mul_ps(px, scx); // (px * c, py * c, pz * c, pw * c)
    __m128 pss = _mm_shuffle_ps(psc, psc, _MM_SHUFFLE(2, 3, 0, 1)); // (py * c, px * c, pw * c, pz * c)
    __m128 psc_swapped = _mm_shuffle_ps(psc, psc, _MM_SHUFFLE(1, 0, 3, 2)); // (px * s, py * s, pz * s, pw * s)
    __m128 pss_swapped = _mm_shuffle_ps(psc_swapped, psc_swapped, _MM_SHUFFLE(2, 3, 0, 1)); // (py * s, px * s, pw * s, pz * s)

    __m128 psc_sub_pss = _mm_sub_ps(psc, pss_swapped); // (px * c - py * s, py * c - px * s, pz * c - pw * s, pw * c - pz * s)
    __m128 pss_sub_psc = _mm_sub_ps(pss, psc_swapped); // (py * c - px * s, px * c - py * s, pw * c - pz * s, pz * c - pw * s)

    // Scale the results
    __m128 scaled_psc_sub_pss = _mm_mul_ps(psc_sub_pss, m128);
    __m128 scaled_pss_sub_psc = _mm_mul_ps(pss_sub_psc, m128);

    // Subtract from xy
    __m128 result128 = _mm_sub_ps(xy128, scaled_psc_sub_pss);
    __m128 result128_2 = _mm_sub_ps(xy128, scaled_pss_sub_psc);

    // Store the results
    _mm_storeu_ps(&result.x, result128);
    _mm_storeu_ps(&result.y, result128_2);
}

#include <immintrin.h>
