#pragma comment(lib, "ws2_32.lib")

class Connectivity
{
public:
    class ConnectionInformation
    {
    public:
        ConnectionInformation(SOCKET conn) : connection(conn), isClosed(false), sendError(false)
        {
            event = WSACreateEvent();
            if (event == WSA_INVALID_EVENT)
            {
                std::cerr << "Failed to create event: " << WSAGetLastError() << std::endl;
                return;
            }

            // Register for FD_WRITE events
            if (WSAEventSelect(connection, event, FD_WRITE) == SOCKET_ERROR)
            {
                std::cerr << "Failed to register for events: " << WSAGetLastError() << std::endl;
                WSACloseEvent(event);
                event = WSA_INVALID_EVENT;
                return;
            }
        }

        ~ConnectionInformation()
        {
            if (event != WSA_INVALID_EVENT)
            {
                WSAEventSelect(connection, event, 0); // Unregister events
                WSACloseEvent(event);
            }
        }

        void SendData(unsigned char data[], const int length)
        {
            if (isClosed || sendError)
                return;

            std::lock_guard<std::mutex> lock(syncRoot);

            sendInfo.buf = (char*)data;
            sendInfo.len = length;

            // Wait for the FD_WRITE event
            DWORD waitResult = WSAWaitForMultipleEvents(1, &event, FALSE, INFINITE, FALSE);
            if (waitResult == WSA_WAIT_EVENT_0)
            {
                // Event is signaled, socket is ready to send data
                if (WSASend(connection, &sendInfo, 1, &bytesSent, 0, NULL, NULL) == SOCKET_ERROR)
                {
                    int state = WSAGetLastError();
                    if (state != WSA_IO_PENDING)
                    {
                        std::cerr << "WSASend failed: " << state << std::endl;
                        sendError = true;
                    }
                }
            }
            else
            {
                std::cerr << "WSAWaitForMultipleEvents failed: " << waitResult << std::endl;
                sendError = true;
            }
        }

    private:
        SOCKET connection;
        WSAEvent event;
        bool isClosed;
        bool sendError;
        std::mutex syncRoot;
        WSABUF sendInfo;
        DWORD bytesSent;
    };
};

