#include <SDL2/SDL.h>
#include <iostream>
#include <vector>
#include <cmath>

const int WINDOW_WIDTH = 800;
const int WINDOW_HEIGHT = 600;
const int MAX_STEPS = 100;
const float MAX_DIST = 100.0f;
const float SURF_DIST = 0.01f;

struct Vec3 {
    float x, y, z;

    Vec3 operator+(const Vec3& other) const {
        return {x + other.x, y + other.y, z + other.z};
    }

    Vec3 operator-(const Vec3& other) const {
        return {x - other.x, y - other.y, z - other.z};
    }

    Vec3 operator*(float scalar) const {
        return {x * scalar, y * scalar, z * scalar};
    }

    Vec3 operator/(float scalar) const {
        return {x / scalar, y / scalar, z / scalar};
    }

    float dot(const Vec3& other) const {
        return x * other.x + y * other.y + z * other.z;
    }

    float length() const {
        return std::sqrt(x * x + y * y + z * z);
    }

    Vec3 normalize() const {
        float len = length();
        return {x / len, y / len, z / len};
    }

    // Cross product for camera basis vectors
    Vec3 cross(const Vec3& other) const {
        return {
            y * other.z - z * other.y,
            z * other.x - x * other.z,
            x * other.y - y * other.x
        };
    }
};

// Distance function for scene
float map(const Vec3& p) {
    // Define a simple sphere
    return p.length() - 1.0f;
}

// Ray marching function
float trace(const Vec3& ro, const Vec3& rd) {
    float t = 0.0f;
    for (int i = 0; i < MAX_STEPS; i++) {
        Vec3 p = ro + rd * t;
        float d = map(p);
        if (d < SURF_DIST) return t;
        t += d;
        if (t > MAX_DIST) return -1.0f;
    }
    return -1.0f;
}

// Ambient occlusion calculation
float ambientOcclusion(const Vec3& p, const Vec3& n) {
    float occ = 0.0f;
    float w = 1.0f;
    for (float step = 0.01f; step < 1.0f; step *= 2.0f) {
        float d = map(p + n * step);
        occ += (d - step) * w;
        w *= 0.5f;
    }
    return 1.0f - (occ * 1.0f);
}

// Lighting and shading
Vec3 shade(const Vec3& p, const Vec3& n) {
    Vec3 lightDir = {1.0f, 1.0f, 1.0f}.normalize();
    float diff = std::max(0.0f, n.dot(lightDir));
    float ao = ambientOcclusion(p, n);
    return {diff * ao, diff * ao, diff * ao};
}

int main(int argc, char* argv[]) {
    if (SDL_Init(SDL_INIT_VIDEO) < 0) {
        std::cerr << "SDL could not initialize! SDL_Error: " << SDL_GetError() << std::endl;
        return -1;
    }

    SDL_Window* window = SDL_CreateWindow("Ray March Renderer", 
                                          SDL_WINDOWPOS_UNDEFINED, 
                                          SDL_WINDOWPOS_UNDEFINED, 
                                          WINDOW_WIDTH, 
                                          WINDOW_HEIGHT, 
                                          SDL_WINDOW_SHOWN);
    if (!window) {
        std::cerr << "Window could not be created! SDL_Error: " << SDL_GetError() << std::endl;
        SDL_Quit();
        return -1;
    }

    SDL_Renderer* renderer = SDL_CreateRenderer(window, -1, SDL_RENDERER_ACCELERATED);
    if (!renderer) {
        std::cerr << "Renderer could not be created! SDL_Error: " << SDL_GetError() << std::endl;
        SDL_DestroyWindow(window);
        SDL_Quit();
        return -1;
    }

    SDL_Texture* texture = SDL_CreateTexture(renderer, 
                                             SDL_PIXELFORMAT_RGBA8888, 
                                             SDL_TEXTUREACCESS_STREAMING, 
                                             WINDOW_WIDTH, 
                                             WINDOW_HEIGHT);
    if (!texture) {
        std::cerr << "Texture could not be created! SDL_Error: " << SDL_GetError() << std::endl;
        SDL_DestroyRenderer(renderer);
        SDL_DestroyWindow(window);
        SDL_Quit();
        return -1;
    }

    std::vector<Uint32> pixels(WINDOW_WIDTH * WINDOW_HEIGHT);

    // Camera setup
    Vec3 cameraPos = {0.0f, 0.0f, 3.0f};
    Vec3 cameraTarget = {0.0f, 0.0f, 0.0f};
    Vec3 cameraDir = (cameraTarget - cameraPos).normalize();
    Vec3 cameraRight = {1.0f, 0.0f, 0.0f}.normalize();
    Vec3 cameraUp = cameraRight.cross(cameraDir).normalize();

    bool running = true;
    SDL_Event e;
    while (running) {
        while (SDL_PollEvent(&e) != 0) {
            if (e.type == SDL_QUIT) {
                running = false;
            }
        }

        // Render loop
        for (int y = 0; y < WINDOW_HEIGHT; y++) {
            for (int x = 0; x < WINDOW_WIDTH; x++) {
                float u = (2.0f * x - WINDOW_WIDTH) / WINDOW_WIDTH;
                float v = (2.0f * y - WINDOW_HEIGHT) / WINDOW_HEIGHT;
                Vec3 rayDir = (cameraDir + cameraRight * u + cameraUp * v).normalize();
                float t = trace(cameraPos, rayDir);

                if (t > 0.0f) {
                    Vec3 p = cameraPos + rayDir * t;
                    // Approximate normal using finite differences
                    Vec3 offset = {0.001f, 0.0f, 0.0f};
                    Vec3 nx = map(p + offset) - map(p - offset);
                    Vec3 ny = map(Vec3(p.x, p.y + 0.001f, p.z)) - map(Vec3(p.x, p.y - 0.001f, p.z));
                    Vec3 nz = map(Vec3(p.x, p.y, p.z + 0.001f)) - map(Vec3(p.x, p.y, p.z - 0.001f));
                    Vec3 n = Vec3(nx, ny, nz).normalize();

                    Vec3 color = shade(p, n);
                    pixels[y * WINDOW_WIDTH + x] = SDL_MapRGB(renderer->format, 
                                                              static_cast<Uint8>(color.x * 255), 
                                                              static_cast<Uint8>(color.y * 255), 
                                                              static_cast<Uint8>(color.z * 255));
                } else {
                    pixels[y * WINDOW_WIDTH + x] = SDL_MapRGB(renderer->format, 0, 0, 0);
                }
            }
        }

        SDL_UpdateTexture(texture, NULL, pixels.data(), WINDOW_WIDTH * sizeof(Uint32));
        SDL_RenderClear(renderer);
        SDL_RenderCopy(renderer, texture, NULL, NULL);
        SDL_RenderPresent(renderer);
    }

    SDL_DestroyTexture(texture);
    SDL_DestroyRenderer(renderer);
    SDL_DestroyWindow(window);
    SDL_Quit();
    return 0;
}

#include <cuda_runtime.h>
#include <iostream>

// Block size for matrix multiplication
#define BLOCK_SIZE 16

// Kernel function for matrix multiplication
__global__ void matrixMulKernel(float *A, float *B, float *C, int width)
{
    // Calculate global row and column indices
    int row = blockIdx.y * blockDim.y + threadIdx.y;
    int col = blockIdx.x * blockDim.x + threadIdx.x;

    float sum = 0.0f;

    // Loop over tiles
    for(int m=0; m<width; m+=BLOCK_SIZE)
    {
        // Shared memory for tile data
        __shared__ float As[BLOCK_SIZE][BLOCK_SIZE];
        __shared__ float Bs[BLOCK_SIZE][BLOCK_SIZE];

        // Load tile of matrix A into shared memory
        int rowA = row * width + m + threadIdx.x;
        int colA = m + threadIdx.y;
        As[threadIdx.y][threadIdx.x] = (rowA < width * width && colA < width) ? A[rowA] : 0.0f;

        // Load tile of matrix B into shared memory
        int rowB = m + threadIdx.x;
        int colB = col + threadIdx.y;
        Bs[threadIdx.y][threadIdx.x] = (rowB < width && colB < width) ? B[rowB * width + colB] : 0.0f;

        __syncthreads();

        // Compute partial dot product for this tile
        for(int k=0; k<BLOCK_SIZE; ++k)
        {
            sum += As[threadIdx.y][k] * Bs[k][threadIdx.x];
        }

        __syncthreads();
    }

    // Store result in output matrix
    int index = row * width + col;
    if(row < width && col < width)
    {
        C[index] = sum;
    }
}

// Host function to launch kernel
void matrixMul(float *A, float *B, float *C, int width)
{
    dim3 dimBlock(BLOCK_SIZE, BLOCK_SIZE);
    dim3 dimGrid((width + BLOCK_SIZE - 1) / BLOCK_SIZE, (width + BLOCK_SIZE - 1) / BLOCK_SIZE);

    matrixMulKernel<<<dimGrid, dimBlock>>>(A, B, C, width);

    cudaDeviceSynchronize();
}

int main()
{
    int width = 1024; // Example matrix size
    size_t size = width * width * sizeof(float);

    // Allocate host memory
    float *h_A, *h_B, *h_C;
    h_A = (float *)malloc(size);
    h_B = (float *)malloc(size);
    h_C = (float *)malloc(size);

    // Initialize h_A and h_B with data

    // Allocate device memory
    float *d_A, *d_B, *d_C;
    cudaMalloc(&d_A, size);
    cudaMalloc(&d_B, size);
    cudaMalloc(&d_C, size);

    // Copy input data to device
    cudaMemcpy(d_A, h_A, size, cudaMemcpyHostToDevice);
    cudaMemcpy(d_B, h_B, size, cudaMemcpyHostToDevice);

    // Launch matrix multiplication kernel
    matrixMul(d_A, d_B, d_C, width);

    // Copy result back to host
    cudaMemcpy(h_C, d_C, size, cudaMemcpyDeviceToHost);

    // Use h_C for further processing

    // Cleanup
    free(h_A);
    free(h_B);
    free(h_C);
    cudaFree(d_A);
    cudaFree(d_B);
    cudaFree(d_C);

    return 0;
}

