namespace caffe {

template <typename Dtype>
class WeightedSigmoidCrossEntropyLossLayer : public LossLayer<Dtype> {
 public:
  explicit WeightedSigmoidCrossEntropyLossLayer(const LayerParameter& param)
      : LossLayer<Dtype>(param) {}

  virtual void LayerSetUp(const vector<Blob<Dtype>*>& bottom,
                          const vector<Blob<Dtype>*>& top);
  virtual void Reshape(const vector<Blob<Dtype>*>& bottom,
                       const vector<Blob<Dtype>*>& top);
  virtual void Forward_cpu(const vector<Blob<Dtype>*>& bottom,
                           const vector<Blob<Dtype>*>& top);
  virtual void Backward_cpu(const vector<Blob<Dtype>*>& top,
                            const vector<bool>& propagate_down,
                            const vector<Blob<Dtype>*>& bottom);

 protected:
  Blob<Dtype> prob_;
  Blob<Dtype> label_;
  Blob<Dtype> weighted_label_;
  Blob<Dtype> loss_weight_;
  Dtype positive_weight_;
  Dtype negative_weight_;
};

template <typename Dtype>
void WeightedSigmoidCrossEntropyLossLayer<Dtype>::LayerSetUp(
    const vector<Blob<Dtype>*>& bottom, const vector<Blob<Dtype>*>& top) {
  // Set class weights for imbalanced data
  positive_weight_ = 1.0 / 0.05;   // Weight for positive class (inverse frequency)
  negative_weight_ = 1.0 / 0.95;   // Weight for negative class (inverse frequency)
}

template <typename Dtype>
void WeightedSigmoidCrossEntropyLossLayer<Dtype>::Reshape(
    const vector<Blob<Dtype>*>& bottom, const vector<Blob<Dtype>*>& top) {
  LossLayer<Dtype>::Reshape(bottom, top);

  prob_.ReshapeLike(*bottom[0]);
  label_.ReshapeLike(*bottom[1]);
  weighted_label_.ReshapeLike(*bottom[1]);
  loss_weight_.ReshapeLike(*bottom[1]);
}

template <typename Dtype>
void WeightedSigmoidCrossEntropyLossLayer<Dtype>::Forward_cpu(
    const vector<Blob<Dtype>*>& bottom, const vector<Blob<Dtype>*>& top) {
  const Dtype* bottom_data = bottom[0]->cpu_data();
  const Dtype* bottom_label = bottom[1]->cpu_data();

  Dtype* prob_data = prob_.mutable_cpu_data();
  Dtype* weighted_label_data = weighted_label_.mutable_cpu_data();
  Dtype* loss_weight_data = loss_weight_.mutable_cpu_data();

  int num = bottom[0]->num();
  int dim = bottom[0]->count() / num;

  // Compute sigmoid activation
  for (int i = 0; i < num; ++i) {
    for (int j = 0; j < dim; ++j) {
      prob_data[i * dim + j] = 1.0 / (1.0 + exp(-bottom_data[i * dim + j]));
    }
  }

  // Compute per-sample weights based on labels
  for (int i = 0; i < num; ++i) {
    for (int j = 0; j < dim; ++j) {
      weighted_label_data[i * dim + j] = 
          bottom_label[i * dim + j] * positive_weight_ + 
          (1 - bottom_label[i * dim + j]) * negative_weight_;
    }
  }

  // Compute weighted cross-entropy loss
  Dtype loss = 0.0;
  for (int i = 0; i < num; ++i) {
    for (int j = 0; j < dim; ++j) {
      loss += -bottom_label[i * dim + j] * log(prob_data[i * dim + j]) -
              (1 - bottom_label[i * dim + j]) * log(1 - prob_data[i * dim + j]) *
              weighted_label_data[i * dim + j];
    }
  }

  loss /= num;
  top[0]->mutable_cpu_data()[0] = loss;
}

template <typename Dtype>
void WeightedSigmoidCrossEntropyLossLayer<Dtype>::Backward_cpu(
    const vector<Blob<Dtype>*>& top, const vector<bool>& propagate_down,
    const vector<Blob<Dtype>*>& bottom) {
  if (!propagate_down[0]) {
    return;
  }

  const Dtype* bottom_data = bottom[0]->cpu_data();
  const Dtype* bottom_label = bottom[1]->cpu_data();
  const Dtype* prob_data = prob_.cpu_data();
  const Dtype* weighted_label_data = weighted_label_.cpu_data();

  Dtype* bottom_diff = bottom[0]->mutable_cpu_diff();
  int num = bottom[0]->num();
  int dim = bottom[0]->count() / num;

  // Compute gradient with respect to logits
  for (int i = 0; i < num; ++i) {
    for (int j = 0; j < dim; ++j) {
      bottom_diff[i * dim + j] = 
          (prob_data[i * dim + j] - bottom_label[i * dim + j]) * 
          weighted_label_data[i * dim + j];
    }
  }

  // Scale by top gradient and normalize by batch size
  caffe_cpu_scale(bottom[0]->count(), top[0]->cpu_diff()[0] / num, bottom_diff, bottom_diff);
}

