#include <random>

// Main function for probability simulation
int main()
{
    // Initialize random number generator with current time
    std::mt19937 engine(time(0));

    // Discard first 10 million values to improve randomness
    engine.discard(10000000);

    // Define uniform real distribution between 0.0 and 1.0
    std::uniform_real_distribution<double> uniform_real(0.0, 1.0);

    // Set probabilities for events A, B, C
    double prA = 6.0 / 7.0;
    double prB = 4.0 / 5.0;
    double prC = 3.0 / 4.0;

    // Number of trials (1 million)
    uint64_t trails = 1000000;
    uint64_t total_success = 0;

    // Run simulation
    for (uint64_t i = 0; i < trails; ++i)
    {
        int current_success = 0;

        // Check each event independently
        if (uniform_real(engine) < prA) ++current_success;
        if (uniform_real(engine) < prB) ++current_success;
        if (uniform_real(engine) < prC) ++current_success;

        // Count cases where exactly 2 events occur
        if (current_success == 2)
            ++total_success;

        // Calculate running probability estimate
        double prob = static_cast<double>(total_success) / (i + 1);

        // Print progress every 100,000 iterations
        if ((i % 100000) == 0)
        {
            printf("%05llu Pr(...) = %12.10f  error:%15.13f\n",
                   i,
                   prob,
                   std::abs((27.0 / 70.0) - prob));
        }
    }

    // Output final probability result
    double final_prob = static_cast<double>(total_success) / trails;
    printf("Final Pr(...) = %12.10f  error:%15.13f\n",
           final_prob,
           std::abs((27.0 / 70.0) - final_prob));

    return 0;
}

