// Function to extract a jvalue from a jobject
jvalue extractJValue(JNIEnv *env, jobject obj, const char *signature)
{
    jvalue value;
    if(signature[0] == 'Z')
    {
        value.z = env->CallBooleanMethod(obj, env->GetMethodID(env->GetObjectClass(obj), "booleanValue", "()Z"));
    }
    else if(signature[0] == 'B')
    {
        value.b = env->CallByteMethod(obj, env->GetMethodID(env->GetObjectClass(obj), "byteValue", "()B"));
    }
    else if(signature[0] == 'C')
    {
        value.c = env->CallCharMethod(obj, env->GetMethodID(env->GetObjectClass(obj), "charValue", "()C"));
    }
    else if(signature[0] == 'S')
    {
        value.s = env->CallShortMethod(obj, env->GetMethodID(env->GetObjectClass(obj), "shortValue", "()S"));
    }
    else if(signature[0] == 'I')
    {
        value.i = env->CallIntMethod(obj, env->GetMethodID(env->GetObjectClass(obj), "intValue", "()I"));
    }
    else if(signature[0] == 'J')
    {
        value.j = env->CallLongMethod(obj, env->GetMethodID(env->GetObjectClass(obj), "longValue", "()J"));
    }
    else if(signature[0] == 'F')
    {
        value.f = env->CallFloatMethod(obj, env->GetMethodID(env->GetObjectClass(obj), "floatValue", "()F"));
    }
    else if(signature[0] == 'D')
    {
        value.d = env->CallDoubleMethod(obj, env->GetMethodID(env->GetObjectClass(obj), "doubleValue", "()D"));
    }
    else if(signature[0] == 'L' || signature[0] == '[')
    {
        value.l = obj;
    }
    else
    {
        // Handle other types if necessary
        std::cerr << "Unsupported type: " << signature << std::endl;
    }
    return value;
}

// Native method to create an object using the constructor with variable arguments
jobject createObject(JNIEnv *env, jobjectArray args, const char *signature)
{
    // Get the number of arguments
    int argc = env->GetArrayLength(args);

    // Parse the method signature to get the parameter types
    const char *sig = signature;
    while(*sig != '(') sig++;
    sig++; // Skip the '('
    int paramCount = 0;
    while(*sig != ')')
    {
        if(*sig == 'L')
        {
            while(*sig != ';') sig++;
        }
        sig++;
        paramCount++;
    }

    // Ensure the number of arguments matches the number of parameters in the signature
    if(argc != paramCount)
    {
        std::cerr << "Number of arguments does not match the signature" << std::endl;
        return nullptr;
    }

    // Create a jvalue array for the arguments
    jvalue *jvalues = new jvalue[argc];

    // Extract the jvalues from the jobjectArray
    for(int i = 0; i < argc; i++)
    {
        jobject obj = env->GetObjectArrayElement(args, i);
        jvalues[i] = extractJValue(env, obj, &signature[i + 1]);
    }

    // Get the class and method ID for the constructor
    const char *className = "Your/Target/Class"; // Replace with the actual class name
    jclass clazz = env->FindClass(className);
    if(clazz == nullptr)
    {
        std::cerr << "Class not found: " << className << std::endl;
        delete[] jvalues;
        return nullptr;
    }

    jmethodID constructor = env->GetMethodID(clazz, "<init>", signature);
    if(constructor == nullptr)
    {
        std::cerr << "Constructor not found: " << signature << std::endl;
        delete[] jvalues;
        return nullptr;
    }

    // Create the new object
    jobject result = env->NewObjectA(clazz, constructor, jvalues);

    // Clean up
    delete[] jvalues;

    return result;
}

// Example JNI native method
extern "C"
JNIEXPORT jobject JNICALL Java_com_example_YourClass_createObject(JNIEnv *env, jobject obj, jobjectArray args, jstring sig)
{
    const char *signature = env->GetStringUTFChars(sig, nullptr);
    jobject result = createObject(env, args, signature);
    env->ReleaseStringUTFChars(sig, signature);
    return result;
}

