// Reduces a fraction to its simplest form
std::pair<int, int> reduce_fraction(int numerator, int denominator)
{
    int gcd = std::gcd(numerator, denominator);
    return {numerator / gcd, denominator / gcd};
}

// Counts unique slopes formed by points relative to origin
std::map<std::pair<int, int>, int> count_slopes(const std::vector<std::pair<int, int>>& points)
{
    std::map<std::pair<int, int>, int> slopes;
    for (const auto& point : points)
    {
        int x = point.first;
        int y = point.second;
        if (y == 0)
        {
            slopes[{1, 0}]++;
        }
        else
        {
            auto reduced = reduce_fraction(x, y);
            slopes[reduced]++;
        }
    }
    return slopes;
}

int main()
{
    std::vector<std::pair<int, int>> points = {{1, 2}, {2, 4}, {3, 0}, {1, 3}, {2, 6}};
    auto slopes = count_slopes(points);
    for (const auto& [slope, count] : slopes)
    {
        std::cout << "(" << slope.first << ", " << slope.second << "): " << count << std::endl;
    }
    return 0;

}

