#include <iostream>
using namespace std;

#define UNASSIGNED 0
#define N 9

// Check if placing 'num' at grid[row][col] is safe according to Sudoku rules
bool isSafe(int grid[N][N], int row, int col, int num)
{
    // Check if 'num' is already placed in current row
    for (int i = 0; i < N; i++)
    {
        if (grid[row][i] == num)
        {
            return false;
        }
    }

    // Check if 'num' is already placed in current column
    for (int i = 0; i < N; i++)
    {
        if (grid[i][col] == num)
        {
            return false;
        }
    }

    // Check if 'num' is already placed in current 3x3 sub-grid
    int startRow = row - row % 3;
    int startCol = col - col % 3;
    for (int i = 0; i < 3; i++)
    {
        for (int j = 0; j < 3; j++)
        {
            if (grid[startRow + i][startCol + j] == num)
            {
                return false;
            }
        }
    }

    // If 'num' is not already placed in current row, column or sub-grid, it is safe to place 'num' in the current cell
    return true;
}

// Find the first empty cell in the grid (marked as UNASSIGNED)
bool findEmptyCell(int grid[N][N], int& row, int& col)
{
    // Find the first empty cell in the grid
    for (row = 0; row < N; row++)
    {
        for (col = 0; col < N; col++)
        {
            if (grid[row][col] == UNASSIGNED)
            {
                return true;
            }
        }
    }

    // If no empty cell is found, it means the grid is solved
    return false;
}

// Solve Sudoku using backtracking
bool solveSudoku(int grid[N][N])
{
    int row, col;

    // Check if all cells are filled
    if (!findEmptyCell(grid, row, col))
    {
        return true;
    }

    // Try all possible numbers in the empty cell
    for (int num = 1; num <= 9; num++)
    {
        if (isSafe(grid, row, col, num))
        {
            // Place the number in the current cell
            grid[row][col] = num;

            // Recur to solve the remaining grid
            if (solveSudoku(grid))
            {
                return true;
            }

            // If the current number doesn't lead to a solution, undo the current cell and try the next number
            grid[row][col] = UNASSIGNED;
        }
    }

    // If no number in the range [1, 9] leads to a solution, backtrack to the previous cell
    return false;
}

// Display the Sudoku grid
void displayGrid(int grid[N][N])
{
    for (int i = 0; i < N; i++)
    {
        for (int j = 0; j < N; j++)
        {
            cout << grid[i][j] << " ";
        }
        cout << endl;
    }
}

int main()
{
    int grid[N][N] =
    {
        {3, 0, 6, 5, 0, 8, 4, 0, 0},
        {5, 2, 0, 0, 0, 0, 0, 0, 0},
        {0, 8, 7, 0, 0, 0, 0, 3, 1},
        {0, 0, 3, 0, 1, 0, 0, 8, 0},
        {9, 0, 0, 8, 6, 3, 0, 0, 5},
        {0, 5, 0, 0, 9, 0, 6, 0, 0},
        {1, 3, 0, 0, 0, 0, 2, 5, 0},
        {0, 0, 0, 0, 0, 0, 0, 7, 4},
        {0, 0, 5, 2, 0, 6, 3, 0, 0}
    };

    if (solveSudoku(grid))
    {
        cout << "Sudoku solved.\n";
        displayGrid(grid);
    }
    else
    {
        cout << "No solution exists.\n";
    }

    return 0;
}

#include <iostream>
using namespace std;

// Node class for BST
class Node {
public:
    int key;
    Node* left;
    Node* right;

    Node(int k) : key(k), left(nullptr), right(nullptr) {}
};

// Binary Search Tree class
class BST {
public:
    Node* root;

    BST() : root(nullptr) {}

    void insert(int key) {
        root = insertRec(root, key);
    }

    void inorder() {
        inorderRec(root);
        cout << endl;
    }

    void deleteKey(int key) {
        root = deleteRec(root, key);
    }

private:
    // Recursive insert function
    Node* insertRec(Node* root, int key) {
        if (root == nullptr) {
            root = new Node(key);
            return root;
        }
        if (key < root->key) {
            root->left = insertRec(root->left, key);
        } else if (key > root->key) {
            root->right = insertRec(root->right, key);
        }
        return root;
    }

    // Inorder traversal helper
    void inorderRec(Node* root) {
        if (root != nullptr) {
            inorderRec(root->left);
            cout << root->key << " ";
            inorderRec(root->right);
        }
    }

    // Find minimum value node in subtree
    Node* minValueNode(Node* root) {
        Node* current = root;
        while (current && current->left != nullptr) {
            current = current->left;
        }
        return current;
    }

    // Recursive delete function
    Node* deleteRec(Node* root, int key) {
        if (root == nullptr) return root;

        if (key < root->key) {
            root->left = deleteRec(root->left, key);
        } else if (key > root->key) {
            root->right = deleteRec(root->right, key);
        } else {
            // Node with only one child or no child
            if (root->left == nullptr) {
                Node* temp = root->right;
                delete root;
                return temp;
            } else if (root->right == nullptr) {
                Node* temp = root->left;
                delete root;
                return temp;
            }

            // Node with two children: get inorder successor
            Node* temp = minValueNode(root->right);
            root->key = temp->key;
            root->right = deleteRec(root->right, temp->key);
        }
        return root;
    }
};

int main() {
    BST tree;

    tree.insert(50);
    tree.insert(30);
    tree.insert(20);
    tree.insert(40);
    tree.insert(70);
    tree.insert(60);
    tree.insert(80);

    cout << "Inorder traversal of the given tree: ";
    tree.inorder();

    tree.deleteKey(20);
    cout << "Inorder traversal after deleting 20: ";
    tree.inorder();

    tree.deleteKey(30);
    cout << "Inorder traversal after deleting 30: ";
    tree.inorder();

    tree.deleteKey(50);
    cout << "Inorder traversal after deleting 50: ";
    tree.inorder();

    return 0;
}

