#include <vector>
using namespace std;

// Performs insertion sort on the array
void insertion_sort(vector<int>& arr)
{
    for(int i=1;i<arr.size();++i)
    {
        int key = arr[i];
        int j = i - 1;
        // Shift elements greater than key to the right
        while(j >= 0 && key < arr[j])
        {
            arr[j + 1] = arr[j];
            --j;
        }
        // Place key at its correct position
        arr[j + 1] = key;
    }
}

