// City structure definition
struct City {
    int x, y;
};

// Calculate Euclidean distance between two cities
double distance(const City& a, const City& b) {
    return std::sqrt(std::pow(a.x - b.x, 2) + std::pow(a.y - b.y, 2));
}

// Compute total tour distance
double totalDistance(const std::vector<int>& tour, const std::vector<City>& cities) {
    double total = 0.0;
    for (size_t i = 0; i < tour.size(); ++i) {
        total += distance(cities[tour[i]], cities[tour[(i + 1) % tour.size()]]);
    }
    return total;
}

// 2-opt local search optimization
void twoOpt(std::vector<int>& tour, const std::vector<City>& cities) {
    bool improved = true;
    while (improved) {
        improved = false;
        for (size_t i = 1; i < tour.size() - 2; ++i) {
            for (size_t j = i + 1; j < tour.size(); ++j) {
                double currentDistance = distance(cities[tour[i - 1]], cities[tour[i]]) + distance(cities[tour[j]], cities[tour[(j + 1) % tour.size()]]);
                double newDistance = distance(cities[tour[i - 1]], cities[tour[j]]) + distance(cities[tour[i]], cities[tour[(j + 1) % tour.size()]]);
                if (newDistance < currentDistance) {
                    std::reverse(tour.begin() + i, tour.begin() + j + 1);
                    improved = true;
                }
            }
        }
    }
}

int main()
{
    // Define city coordinates
    std::vector<City> cities = {{0, 0}, {1, 5}, {5, 1}, {5, 5}, {1, 1}};
    std::vector<int> tour(cities.size());
    for (size_t i = 0; i < cities.size(); ++i) {
        tour[i] = i;
    }

    // Output initial tour and distance
    std::cout << "Initial tour: ";
    for (int city : tour) {
        std::cout << city << " ";
    }
    std::cout << "\nInitial distance: " << totalDistance(tour, cities) << std::endl;

    // Apply 2-opt optimization
    twoOpt(tour, cities);

    // Output optimized tour and distance
    std::cout << "Optimized tour: ";
    for (int city : tour) {
        std::cout << city << " ";
    }
    std::cout << "\nOptimized distance: " << totalDistance(tour, cities) << std::endl;

    return 0;
}

#include <iostream>
#include <vector>

using namespace std;

// Function to find the first occurrence of the target value
int findFirstOccurrence(const vector<int>& arr, int target)
{
    int left = 0, right = arr.size() - 1;
    int result = -1;
    while(left <= right)
    {
        int mid = left + (right - left) / 2;
        if(arr[mid] == target)
        {
            result = mid;
            right = mid - 1; // Continue searching in the left half
        }
        else if(arr[mid] < target)
        {
            left = mid + 1;
        }
        else
        {
            right = mid - 1;
        }
    }
    return result;
}

// Function to find the last occurrence of the target value
int findLastOccurrence(const vector<int>& arr, int target)
{
    int left = 0, right = arr.size() - 1;
    int result = -1;
    while(left <= right)
    {
        int mid = left + (right - left) / 2;
        if(arr[mid] == target)
        {
            result = mid;
            left = mid + 1; // Continue searching in the right half
        }
        else if(arr[mid] < target)
        {
            left = mid + 1;
        }
        else
        {
            right = mid - 1;
        }
    }
    return result;
}

// Function to find the first and last occurrence of the target value
pair<int, int> findFirstAndLast(const vector<int>& arr, int target)
{
    int first = findFirstOccurrence(arr, target);
    if(first == -1)
    {
        return {-1, -1}; // Target not found
    }
    int last = findLastOccurrence(arr, target);
    return {first, last};
}

int main()
{
    vector<int> arr = {1, 2, 2, 2, 3, 4, 4, 5, 6};
    int target = 2;
    auto [first, last] = findFirstAndLast(arr, target);
    if(first == -1)
    {
        cout << "Target not found" << endl;
    }
    else
    {
        cout << "First occurrence at index: " << first << endl;
        cout << "Last occurrence at index: " << last << endl;
    }
    return 0;

}

#include <iostream>
