// Checks if a character is a lowercase consonant
bool isLowercaseConsonant(char c)
{
    return islower(c) && c != 'a' && c != 'e' && c != 'i' && c != 'o' && c != 'u';
}

// Calculates sum of ASCII values of lowercase consonants at odd indices
int sumOfLowercaseConsonantsAtOddIndices(const std::string& str)
{
    int sum = 0;
    for(size_t i=1; i<str.length(); i+=2) // Start from index 1 and increment by 2
    {
        if(isLowercaseConsonant(str[i]))
        {
            sum += static_cast<int>(str[i]);
        }
    }
    return sum;
}

