// Macro to check OpenGL errors after each call
#define GL_CHECK(x)                                                         \
    x;                                                                       \
    {                                                                         \
        GLenum glError = glGetError();                                       \
        if(glError != GL_NO_ERROR) {                                         \
            std::cout << "glGetError() = " << glError << " in " << __FILE__  \
