    GL_CHECK(glBindBuffer(GL_ARRAY_BUFFER, positionBuffer));
    GL_CHECK(glBufferData(GL_ARRAY_BUFFER, sizeof(positions), positions, GL_STATIC_DRAW));

    GLuint positionLocation = glGetAttribLocation(program, "position");
    GL_CHECK(glEnableVertexAttribArray(positionLocation));
    GL_CHECK(glVertexAttribPointer(positionLocation, 2, GL_FLOAT, GL_FALSE, 0, 0));

    // Set up texture coordinate buffer
    GLuint texCoordBuffer;
    GL_CHECK(glGenBuffers(1, &texCoordBuffer));
    GL_CHECK(glBindBuffer(GL_ARRAY_BUFFER, texCoordBuffer));
    GL_CHECK(glBufferData(GL_ARRAY_BUFFER, sizeof(texCoords), texCoords, GL_STATIC_DRAW));

    GLuint texCoordLocation = glGetAttribLocation(program, "texCoord");
    GL_CHECK(glEnableVertexAttribArray(texCoordLocation));
    GL_CHECK(glVertexAttribPointer(texCoordLocation, 2, GL_FLOAT, GL_FALSE, 0, 0));

    // Create and configure texture
    GLuint texture;
    GL_CHECK(glGenTextures(1, &texture));
    GL_CHECK(glActiveTexture(GL_TEXTURE0));
    GL_CHECK(glBindTexture(GL_TEXTURE_2D, texture));

    cv::Mat inputImage0 = cv::imread("input0.png");
