    GL_CHECK(glTexImage2D(GL_TEXTURE_2D, 0, GL_RGBA, inputImage0.cols, inputImage0.rows, 0, GL_RGBA, GL_UNSIGNED_BYTE, inputImage0.data));

    GLint textureSamplerLocation = glGetUniformLocation(program, "textureSampler");
    GL_CHECK(glUniform1i(textureSamplerLocation, 0));

    // Render loop
    while (true) {
        GLenum glError = glGetError();
        if(glError != GL_NO_ERROR) {
            std::cout << "glGetError() = " << glError << std::endl;
            break;
        }

        GL_CHECK(glClear(GL_COLOR_BUFFER_BIT | GL_DEPTH_BUFFER_BIT));
