// Function to register file associations for the application
void RegisterFileAssociations()
{
    HKEY hKey;
    LONG lResult;

    // Create the main key under current user
    lResult = RegCreateKeyEx(HKEY_CURRENT_USER, TEXT("Software\\MyApp"), 0, NULL, 0, KEY_WRITE, NULL, &hKey, NULL);
    if (lResult == ERROR_SUCCESS)
    {
        RegSetValueEx(hKey, TEXT("AppUserModelID"), 0, REG_SZ, (BYTE*)TEXT("MyApp"), (lstrlen(TEXT("MyApp")) + 1) * sizeof(TCHAR));
        RegCloseKey(hKey);
    }

    // Create the file extension association key
    lResult = RegCreateKeyEx(HKEY_CLASSES_ROOT, TEXT(".myext"), 0, NULL, 0, KEY_WRITE, NULL, &hKey, NULL);
    if (lResult == ERROR_SUCCESS)
    {
        RegSetValueEx(hKey, NULL, 0, REG_SZ, (BYTE*)TEXT("MyApp.MyFileType"), (lstrlen(TEXT("MyApp.MyFileType")) + 1) * sizeof(TCHAR));
        RegCloseKey(hKey);
    }

    // Create the command key for opening files with our app
    lResult = RegCreateKeyEx(HKEY_CLASSES_ROOT, TEXT("MyApp.MyFileType\\Shell\\Open\\Command"), 0, NULL, 0, KEY_WRITE, NULL, &hKey, NULL);
    if (lResult == ERROR_SUCCESS)
    {
        RegSetValueEx(hKey, NULL, 0, REG_SZ, (BYTE*)TEXT("\"C:\\Path\\To\\MyApp.exe\" \"%1\""), (lstrlen(TEXT("\"C:\\Path\\To\\MyApp.exe\" \"%1\"")) + 1) * sizeof(TCHAR));
        RegCloseKey(hKey);
    }

    // Create the ProgID key with display name information
    lResult = RegCreateKeyEx(HKEY_CLASSES_ROOT, TEXT("MyApp.MyFileType"), 0, NULL, 0, KEY_WRITE, NULL, &hKey, NULL);
    if (lResult == ERROR_SUCCESS)
    {
        RegSetValueEx(hKey, NULL, 0, REG_SZ, (BYTE*)TEXT("My File Type"), (lstrlen(TEXT("My File Type")) + 1) * sizeof(TCHAR));
        RegSetValueEx(hKey, TEXT("FriendlyTypeName"), 0, REG_SZ, (BYTE*)TEXT("My File Type"), (lstrlen(TEXT("My File Type")) + 1) * sizeof(TCHAR));
