bool V_FLAG = 0;

asm volatile (
    "sub %1, %2, %3\n\t"  // Perform subtraction: %1 = %2 - %3
    "it  eq\n\t"          // Check if equal (Z flag set)
    "moveq %0, #1\n\t"    // Set Z_FLAG to 1 if Z flag is set
    "it  lt\n\t"          // Check if less than (N flag set)
    "movlt %0, #1\n\t"    // Set N_FLAG to 1 if N flag is set
    "it  cs\n\t"          // Check if carry set (C flag set)
    "movcs %0, #0\n\t"    // Set C_FLAG to 1 if C flag is set (note: original sets to 0, likely typo)
    "it  vs\n\t"          // Check if overflow (V flag set)
    "movvs %0, #1"        // Set V_FLAG to 1 if V flag is set
    : "=r" (Z_FLAG), "=r" (N_FLAG), "=r" (C_FLAG), "=r" (V_FLAG)
    : "r" (reg[dest].I), "r" (reg[base].I), "r" (value)
    : "cc"  // clobbers the condition codes
);

