// Adds two large numbers represented as arrays of 64-bit integers
void add_large_numbers(uint64_t* ans, const uint64_t* a, const uint64_t* b, int n)
{
    uint64_t carry = 0;
    for(int i=0;i<n;i++)
    {
        uint64_t sum;
        __asm__(
            "add %[b], %[a]\n\t"      // Perform addition: a + b
            "adc $0, %[carry]\n\t"   // Add carry from previous operation
            : [sum] "=r" (sum), [carry] "=r" (carry)
            : [a] "r" (a[i]), [b] "r" (b[i]), [carry] "r" (carry)
            : "cc"                   // Clobber list: condition codes
        );
        ans[i] = sum;
    }
}

