// Computes the nth Fibonacci number iteratively
int fib(int n)
{
    if (n < 2) return n;
    int a = 0, b = 1, c;
    for(int i=2; i<=n; ++i)
    {
        c = a + b;
        a = b;
        b = c;
    }
    return b;
}

