// Convert native C string to Java string
jstring JNU_NewStringNative(const char *str)
{
    jstring result;
    jbyteArray bytes = 0;
    jclass Cstr;
    int len;
    len = strlen(str);
    bytes = env->NewByteArray(len);
    Cstr = env->FindClass(STRING);
    if (bytes != NULL)
    {
        jmethodID mid;
        env->SetByteArrayRegion(bytes, 0, len, (jbyte *)str);
        mid = env->GetMethodID(Cstr, "<init>", "([B)V");
        result = (jstring) env->NewObject(Cstr, mid, bytes);
        env->DeleteLocalRef(bytes);
        return result;
    }
    return NULL;
}

// Parse LaTeX input using SnuggleTeX
int parse_latex(char* input)
{
    jclass engine, Cinput, Csession;
    jmethodID mid;
    jstring jstr;
    jclass stringClass;
    jobjectArray args;
    jstring latex = JNU_NewStringNative(input);
    jstring result;

    engine = env->FindClass(SNUGGLE_ENGINE);
    Cinput = env->FindClass(SNUGGLE_INPUT);
    Csession = env->FindClass(SNUGGLE_SESSION);

    if (engine == NULL) return -1;

    // Create SnuggleEngine instance
    mid = env->GetMethodID(engine, "<init>", "()V");
    jobject snuggle = env->NewObject(engine, mid);

    // Create SnuggleSession instance
    mid = env->GetMethodID(engine, "createSession", "()Luk/ac/ed/ph/snuggletex/SnuggleSession;");
    jobject session = env->CallObjectMethod(snuggle, mid);

    // Create SnuggleInput instance
    mid = env->GetMethodID(Cinput, "<init>", "(Ljava/lang/String;)V");
    jobject input_elem = env->NewObject(Cinput, mid, latex);

    // Parse input
    mid = env->GetMethodID(Csession, "parseInput", "(Luk/ac/ed/ph/snuggletex/SnuggleInput;)V");
    env->CallVoidMethod(session, mid);

    // Build XML string
    mid = env->GetMethodID(Csession, "buildXMLString", "()Ljava/lang/String;");
    result = (jstring) env->CallObjectMethod(session, mid);

    if (env->ExceptionCheck())
    {
        jthrowable exc = env->ExceptionOccurred();
        env->ExceptionDescribe();
        env->ExceptionClear();
        return -1;
    }

    const char *xml_str = env->GetStringUTFChars(result, NULL);
    cout << "XML String: " << xml_str << endl;
    env->ReleaseStringUTFChars(result, xml_str);

    return 0;
}

// Main function
