#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <iostream>
#include <fstream>

using namespace std;

// Number of threads and array size
unsigned int NUM_THREADS = 10;
unsigned int NUM_SIZE = 1000000;

// Structure for thread arguments
struct printStruct {
    int* pstart; // pointer to the starting array element
    int size;
};

// Bubble sort function for each thread
void* bubblesort(void* ptr) {
    printStruct* arg = (printStruct*)ptr;
    int* sortArray = arg->pstart;
    int elements = arg->size;

    for(int i=0; i<(elements-1); i++) {
        for(int j=0; j<(elements-1-i); j++) {
            if(sortArray[j] > sortArray[j+1]) {
                int temp = sortArray[j];
                sortArray[j] = sortArray[j+1];
                sortArray[j+1] = temp;
            }
        }
    }
    return NULL;
}

// Merge two sorted arrays
void merge(int* left, int* right, int leftSize, int rightSize) {
    int leftIndex = 0, rightIndex = 0, mergedIndex = 0;
    int* temp = new int[leftSize + rightSize];

    while(leftIndex < leftSize && rightIndex < rightSize) {
        if(left[leftIndex] < right[rightIndex]) {
            temp[mergedIndex++] = left[leftIndex++];
        } else {
            temp[mergedIndex++] = right[rightIndex++];
        }
    }

    while(leftIndex < leftSize) {
        temp[mergedIndex++] = left[leftIndex++];
    }

    while(rightIndex < rightSize) {
        temp[mergedIndex++] = right[rightIndex++];
    }

    for(int i=0; i<mergedIndex; i++) {
        left[i] = temp[i];
    }

    delete[] temp;
}

// Main function
int main(int argc, char* argv[]) {
    ifstream numFile(argv[1]);
    int elements = 0;
    int sortArray[NUM_SIZE];
    int size; // size of the array = size of the elements
    int temp;

    while(numFile >> size) {
        sortArray[elements] = size;
        elements++;
    }

    numFile.close();

    // Initialize thread sections
    printStruct section[NUM_THREADS];
    int sectionSize = NUM_SIZE / NUM_THREADS;

    // Create and join threads
    for(int i=0; i<NUM_THREADS; i++) {
        section[i].pstart = &sortArray[i * sectionSize];
        section[i].size = sectionSize;
        pthread_t thread;
        pthread_create(&thread, NULL, bubblesort, (void*)&section[i]);
        pthread_join(thread, NULL);
    }

    // Handle remaining elements
    int remainingSize = NUM_SIZE - (NUM_THREADS * sectionSize);

    if(remainingSize > 0) {
        merge(&sortArray[(NUM_THREADS - 2) * sectionSize], &sortArray[(NUM_THREADS - 1) * sectionSize], sectionSize, remainingSize);
    }

    // Merge all sorted sections
    for(int i=NUM_THREADS-2; i>=0; i--) {
        merge(&sortArray[i * sectionSize], &sortArray[(i+1) * sectionSize], sectionSize, sectionSize);
    }

    // Write result to output file
    ofstream outFile(argv[2]);

    for(int i=0; i<NUM_SIZE; i++) {
        outFile << sortArray[i] << endl;
    }

    outFile.close();

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

// Merge function to merge two subarrays
void merge(vector<int> &a, int low, int mid, int high)
{
    int n1 = mid - low + 1;
    int n2 = high - mid;

    vector<int> left(n1), right(n2);

    for(int i = 0; i < n1; i++)
        left[i] = a[low + i];
    for(int i = 0; i < n2; i++)
        right[i] = a[mid + 1 + i];

    int i = 0, j = 0, k = low;
    while(i < n1 && j < n2)
    {
        if(left[i] <= right[j])
        {
            a[k++] = left[i++];
        }
        else
        {
            a[k++] = right[j++];
        }
    }

    while(i < n1)
        a[k++] = left[i++];

    while(j < n2)
        a[k++] = right[j++];
}

// Merge sort function
void mergeSort(vector<int> &a, int low, int high)
{
    if(low < high)
    {
        int mid = low + (high - low) / 2;
        mergeSort(a, low, mid);
        mergeSort(a, mid + 1, high);
        merge(a, low, mid, high);
    }
}

int main()
{
    vector<int> a = {12, 11, 13, 5, 6, 7};
    int n = a.size();

    // Print original array
    cout << "Given array is: " << endl;
    for(int i = 0; i < n; i++)
        cout << a[i] << " ";
    cout << endl;

    // Sort the array
    mergeSort(a, 0, n - 1);

    // Print sorted array
    cout << "Sorted array is: " << endl;
    for(int i = 0; i < n; i++)
        cout << a[i] << " ";
    cout << endl;

    return 0;
}

#include <algorithm>
#include <vector>
#include <iostream>
#include <cmath>

// Insertion sort for small subarrays
void insertionSort(std::vector<int>& arr, int left, int right)
{
    for(int i=left+1;i<=right;++i)
    {
        int key = arr[i];
        int j = i - 1;
        while(j >= left && arr[j] > key)
        {
            arr[j + 1] = arr[j];
            --j;
        }
        arr[j + 1] = key;
    }
}

// Heapify function for heap sort
void heapify(std::vector<int>& arr, int n, int i)
{
    int largest = i;
    int left = 2 * i + 1;
    int right = 2 * i + 2;

    if(left < n && arr[left] > arr[largest])
        largest = left;

    if(right < n && arr[right] > arr[largest])
        largest = right;

    if(largest != i)
    {
        std::swap(arr[i], arr[largest]);
        heapify(arr, n, largest);
    }
}

// Heap sort implementation
void heapSort(std::vector<int>& arr, int n)
{
    for(int i=n/2-1;i>=0;--i)
        heapify(arr, n, i);

    for(int i=n-1;i>=0;--i)
    {
        std::swap(arr[0], arr[i]);
        heapify(arr, i, 0);
    }
}

// Introsort utility function
void introsortUtil(std::vector<int>& arr, int begin, int end, int depthLimit)
{
    if(end - begin > 16)
    {
        if(depthLimit == 0)
        {
            heapSort(arr, end - begin + 1);
            return;
        }
        depthLimit = depthLimit - 1;
        int pivot = std::partition(arr.begin() + begin, arr.begin() + end, std::less<int>()) - arr.begin();
        introsortUtil(arr, begin, pivot - 1, depthLimit);
        introsortUtil(arr, pivot, end, depthLimit);
    }
    else
    {
        insertionSort(arr, begin, end);
    }
}

// Main introsort function
void introsort(std::vector<int>& arr)
{
    int depthLimit = 2 * static_cast<int>(std::log(arr.size()));
    introsortUtil(arr, 0, arr.size() - 1, depthLimit);
}

int main()
{
    std::vector<int> array = {34, 7, 23, 32, 5, 62, 1, 89, 45, 21, 12, 34, 56, 78, 90, 12, 34, 56, 78, 90};
    introsort(array);
    for(int num : array)
    {
        std::cout << num << " ";
    }
    return 0;
}

