using namespace std;

// Function to fetch the content of a URL
string fetchContent(const string& url) {
    httplib::Client cli(url);
    auto res = cli.Get("/");
    if (res && res->status == 200) {
        return res->body;
    } else {
        cerr << "Failed to fetch URL: " << url << endl;
        return "";
    }
}

// Function to parse HTML and extract links
vector<string> extractLinks(const string& content, const string& base_url) {
    vector<string> links;
    simple_html_dom_parser parser;
    auto dom = parser.parse(content);
    for (auto& link : dom->find("a")) {
        string href = link->attr("href");
        if (!href.empty() && href[0] == '/') {
            // Convert relative URL to absolute URL
            href = base_url + href;
        }
        links.push_back(href);
    }
    return links;
}

// Function to crawl a URL
void crawlURL(const string& url, queue<string>& url_queue, set<string>& visited) {
    if (visited.find(url) != visited.end()) {
        return;
    }

    visited.insert(url);
    string content = fetchContent(url);
    if (!content.empty()) {
        vector<string> links = extractLinks(content, url);
        for (const auto& link : links) {
            url_queue.push(link);
        }
    }
}

// Main function
int main()
{
    string start_url = "http://example.com";
    queue<string> url_queue;
    set<string> visited;

    url_queue.push(start_url);

    while (!url_queue.empty())
    {
        string url = url_queue.front();
        url_queue.pop();

        thread t(crawlURL, url, ref(url_queue), ref(visited));
        t.join();
    }

    return 0;
}

