// Invokes a stdcall function using inline assembly
inline uint64_t invoke_stdcall(uint64_t (* stdcall_func)())
{
    unsigned long hi32, lo32;
    asm(
        "call %2"
        : "=d" (hi32), "=a" (lo32)
        : "m" (stdcall_func)
        : "%eax", "%edx", "%ecx"
    );
    // Combine high and low 32-bit values into a 64-bit result
    return static_cast<uint64_t>(hi32) << 32 | static_cast<uint32_t>(lo32);
}

