// Define a table as a vector of maps
using Table = std::vector<std::map<std::string, std::string>>;

// Function to evaluate a comparison
bool evaluateComparison(const std::string& lhs, const std::string& op, const std::string& rhs) {
    if (op == "==") return lhs == rhs;
    if (op == "!=") return lhs != rhs;
    if (op == "<") return lhs < rhs;
    if (op == ">") return lhs > rhs;
    if (op == "<=") return lhs <= rhs;
    if (op == ">=") return lhs >= rhs;
    return false;
}

// Function to evaluate a Boolean query on a row
bool evaluateQuery(const std::map<std::string, std::string>& row, const std::string& query) {
    std::istringstream iss(query);
    std::string token;
    std::vector<std::string> tokens;

    // Tokenize the query
    while (iss >> token) {
        tokens.push_back(token);
    }

    bool result = false;
    bool current = false;
    bool negate = false;
    std::string lhs, op, rhs;

    for (size_t i = 0; i < tokens.size(); ++i) {
        if (tokens[i] == "NOT") {
            negate = true;
            continue;
        }

        if (i + 2 < tokens.size() && (tokens[i + 1] == "==" || tokens[i + 1] == "!=" || tokens[i + 1] == "<" || tokens[i + 1] == ">" || tokens[i + 1] == "<=" || tokens[i + 1] == ">=")) {
            lhs = row.at(tokens[i]);
            op = tokens[i + 1];
            rhs = row.at(tokens[i + 2]);
            current = evaluateComparison(lhs, op, rhs);
            i += 2;
        } else {
            current = row.at(tokens[i]) == "true";
        }

        if (negate) {
            current = !current;
            negate = false;
        }

        if (i == 0) {
            result = current;
        } else {
            if (tokens[i - 1] == "AND") {
                result = result && current;
            } else if (tokens[i - 1] == "OR") {
                result = result || current;
            }
        }
    }

    return result;
}

// Function to evaluate the Boolean query on two tables
bool evaluateBooleanQuery(const Table& T1, const Table& T2, const std::string& query) {
    for (const auto& row : T1) {
        if (evaluateQuery(row, query)) {
            return true;
        }
    }

    for (const auto& row : T2) {
        if (evaluateQuery(row, query)) {
            return true;
        }
    }

    return false;
}

int main()
{
    // Example tables
    Table T1 = {
        {{"name", "Alice"}, {"age", "30"}, {"city", "New York"}},
        {{"name", "Bob"}, {"age", "25"}, {"city", "Los Angeles"}}
    };

    Table T2 = {
        {{"name", "Charlie"}, {"age", "35"}, {"city", "Chicago"}},
        {{"name", "Diana"}, {"age", "28"}, {"city", "New York"}}
    };

    // Example query
    std::string query = "city == New York OR age > 30";

    // Evaluate the query
    bool result = evaluateBooleanQuery(T1, T2, query);

    // Output the result
    std::cout << "Result: " << (result ? "true" : "false") << std::endl;

    return 0;

}

