// Example function to trace
void removeHtmlMarkup(const std::string& s)
{
    bool tag = false;
    bool quote = false;
    std::string out = " ";

    for(char c : s)
    {
        TRACEIT;
        if(c == 'c' && !quote)
        {
            tag = true;
        }
        else if(c == '>' && !quote)
        {
            tag = false;
        }
        else if(c == '"' || c == '\'' && tag)
        {
            quote = !quote;
        }
        else if(!tag)
        {
            out += c;
        }
    }
    TRACEIT;
    return out;
}

int main()
{
    TRACEIT;
    std::string s = removeHtmlMarkup("\"<");
    TRACEIT;
    std::cout << "Result: " << s << std::endl;
