#include <cstdint>

// Compares and swaps 128-bit values atomically
template<typename T>
inline bool cas(volatile T *src, T cmp, T with)
{
    uint64_t *srcP = (uint64_t*)src;
    uint64_t *cmpP = (uint64_t*)&cmp;
    uint64_t *withP = (uint64_t*)&with;
    unsigned char result = 0;

    __asm__ __volatile__ (
        "lock; cmpxchg16b %1\n\t"
        "setz %0\n\t"
        : "=q"(result)  /* output */
        : "m"(*srcP),   /* input: memory location to compare and swap */
          "a"((uint64_t)cmpP[0]),  /* input: lower 64 bits of cmp */
          "d"((uint64_t)cmpP[1]),  /* input: upper 64 bits of cmp */
          "b"((uint64_t)withP[0]), /* input: lower 64 bits of with */
          "c"((uint64_t)withP[1])  /* input: upper 64 bits of with */
        : "memory", "cc"  /* clobbered items */
    );

    return result;
}

