// Reverses the bits of a 32-bit unsigned integer using inline assembly
uint32_t reverseBits(volatile uint32_t n)
{
    uint32_t result = 0;
    __asm__ (".intel_syntax\n"
             "mov eax, %1 \n"
             "mov ecx, 32 \n"
             "myloop: \n"
             "shr eax, 1 \n"
             "adc %0, %0 \n"
             "loop myloop \n"
             "mov %0, eax \n"
             : [result] "=r"(result) : [n] "r"(n) : "eax", "ecx");

    return result;

}

