// Function to find the longest repeated substring
string findLongestRepeatedSubstring(const string &s)
{
    int n = s.size();
    string result = "";
    for (int len = n / 2; len > 0; --len)
    {
        for (int i = 0; i <= n - len; ++i)
        {
            string sub = s.substr(i, len);
            if (s.find(sub, i + len) != string::npos)
            {
                if (sub.size() > result.size())
                {
                    result = sub;
                }
            }
        }
    }
    return result;
}

// Function to compress the string
string compressString(const string &s)
{
    string compressed = s;
    while (true)
    {
        string longestRepeated = findLongestRepeatedSubstring(compressed);
        if (longestRepeated.empty()) break;

        int count = 0;
        size_t pos = 0;
        while ((pos = compressed.find(longestRepeated, pos)) != string::npos)
        {
            ++count;
            pos += longestRepeated.size();
        }

        if (count > 1)
        {
            string replacement = "[" + longestRepeated + "]" + to_string(count);
            compressed = s.substr(0, compressed.find(longestRepeated)) + replacement;
        }
        else
        {
            break;
        }
    }
    return compressed;
}

// Function to process the file
void processFile(const string &inputFile, const string &outputFile)
{
    ifstream infile(inputFile);
    ofstream outfile(outputFile);

    if (!infile.is_open() || !outfile.is_open())
    {
        cerr << "Error opening file." << endl;
        return;
    }

    string line;
    while (getline(infile, line))
    {
        if (line.find("d+c+d+f+d+c+d+f+d+c+d+f+d+c+d+f+") != string::npos)
        {
            string compressed = compressString(line);
            outfile << compressed << endl;
        }
        else
        {
            outfile << line << endl;
        }
    }

    infile.close();
    outfile.close();
}

// Main function
int main()
{
    string inputFile = "input.txt";
    string outputFile = "output.txt";
    processFile(inputFile, outputFile);
    return 0;

}

