// Typemap for converting Python list to QList
%typemap(in) QList<$1_template_type> (QList<$1_template_type> temp) {
    if (PyList_Check($input)) {
        int size = PyList_Size($input);
        for (int i = 0; i < size; i++) {
            PyObject* item = PyList_GetItem($input, i);
            $1_template_type value;
            if (SWIG_ConvertPtr(item, (void**)&value, $1_descriptor, 0) == -1) {
                SWIG_exception_fail(SWIG_TypeError, "Type error in input list");
            }
            temp.append(value);
        }
        $1 = temp;
    } else {
        SWIG_exception_fail(SWIG_TypeError, "Expected a list");
    }
}

// Typemap for converting QList to Python list
%typemap(out) QList<$1_template_type> {
    PyObject* list = PyList_New($1.size());
    for (int i = 0; i < $1.size(); i++) {
        PyObject* item = SWIG_NewPointerObj(SWIG_as_voidptr($1[i]), $1_descriptor, SWIG_POINTER_OWN);
        PyList_SetItem(list, i, item);
    }
    $result = list;
}

// Extend QList with Python-specific methods
%extend QList<$1_template_type> {
    // Make the list iterable
    PyObject* __iter__() {
        return PySequence_Fast($self, "QList is not iterable");
    }

    // Support indexing: list[index]
    PyObject* __getitem__(int index) {
        if (index < 0 || index >= $self->size()) {
            PyErr_SetString(PyExc_IndexError, "QList index out of range");
            return NULL;
        }
        return SWIG_NewPointerObj(SWIG_as_voidptr((*$self)[index]), $1_descriptor, SWIG_POINTER_OWN);
    }

    // Support len(list)
    int __len__() {
        return $self->size();
    }
}

