class Matrix3D {
public:
    // Constructor initializes dimensions and data vector
    Matrix3D(int n, int m, int p) : n(n), m(m), p(p), data(n * m * p) {}

    // Access element at (i, j, k) with bounds checking
    double& operator()(int i, int j, int k) {
        if (i < 0 || i >= n || j < 0 || j >= m || k < 0 || k >= p) {
            throw std::out_of_range("Index out of range");
