class PyOStreamBuffer : public std::streambuf {
public:
    // Constructor initializes buffer and file pointer
    PyOStreamBuffer(PyFileObject* file) : file(file) {
        setp(buffer, buffer + sizeof(buffer) - 1);
    }

protected:
    // Handle overflow characters
    int overflow(int c) override {
        if (c != EOF) {
            PyFile_WriteString((char*)&c, 1, (PyObject*)file);
        }
        return 0;
    }

    // Synchronize buffer with Python file
    int sync() override {
        PyFile_WriteString(pbase(), pptr() - pbase(), (PyObject*)file);
        pbump(-1 * (pptr() - pbase()));
