// Function to find the longest word chain
std::pair<int, std::string> longestWordChain(const std::string& text)
{
    // Remove non-word and non-space characters
    std::regex re("[^\\w\\s]");
    std::string processedText = std::regex_replace(text, re, "");

    // Parse words into vector
    std::istringstream iss(processedText);
    std::vector<std::string> words{std::istream_iterator<std::string>{iss},
                                   std::istream_iterator<std::string>{}};

    int maxLength = 0;
    std::string maxChain;

    // Check all possible contiguous subsequences
    for(size_t i = 0; i < words.size(); ++i)
    {
        for(size_t j = i; j < words.size(); ++j)
        {
            int currentLength = j - i + 1;
            if(currentLength > maxLength)
            {
                maxLength = currentLength;
                maxChain = "";
                for(size_t k = i; k <= j; ++k)
                {
                    maxChain += words[k] + " ";
                }
            }
        }
    }

    return {maxLength, maxChain};
}

int main()
{
    std::string text = "This is a sample sentence, with commas, and other punctuation!";
    auto [length, chain] = longestWordChain(text);
    // Output the result
    std::cout<<length<<": "<<chain<<std::endl;
    return 0;

}

