// Function to compute the magic number and shift amount
struct MagicDivision {
    uint64_t magic;
    int shift;
};

MagicDivision computeMagicDivision(uint64_t d)
{
    if (d == 0) {
        throw std::invalid_argument("Divisor cannot be zero");
    }

    uint64_t nc = (uint64_t)1 << 32;
    uint64_t n = nc;
    uint64_t a = d;
    uint64_t q1 = 0, r1 = n;
    uint64_t q2 = 1, r2 = 0;
    uint64_t q, r;
    int s = 0;

    while (r1 >= d) {
        q = r1 / d;
        r = r1 % d;
        r1 = r2;
        r2 = r;
        q1 = q2;
        q2 = q1 + q * q2;
        s++;
    }

    uint64_t magic = (q1 + 1) * nc;
    int shift = 32 - s;

    return {magic, shift};
}

// Function to perform the division using the magic number and shift amount
uint64_t magicDivide(uint64_t numerator, const MagicDivision& md)
{
    uint64_t result = (numerator * md.magic) >> md.shift;
    return result;
}

int main()
{
    uint64_t d = 7; // Example divisor
    MagicDivision md = computeMagicDivision(d);

    uint64_t num1 = 100;
    uint64_t num2 = 200;
    uint64_t num3 = 300;

    uint64_t result1 = magicDivide(num1, md);
    uint64_t result2 = magicDivide(num2, md);
    uint64_t result3 = magicDivide(num3, md);

    std::cout << "Result of " << num1 << " / " << d << " = " << result1 << std::endl;
    std::cout << "Result of " << num2 << " / " << d << " = " << result2 << std::endl;
    std::cout << "Result of " << num3 << " / " << d << " = " << result3 << std::endl;

    return 0;

}

