// Thread class for executing Python code
class PythonThread : public QThread {
    Q_OBJECT

public:
    // Constructor
    PythonThread(QObject *parent = nullptr) : QThread(parent) {}

signals:
    // Signal emitted when result is ready
    void resultReady(const QString &result);

protected:
    // Override run method to implement thread logic
    void run() override {
        // Initialize Python interpreter
        Py_Initialize();

        // Add current directory to Python path
        PyRun_SimpleString("import sys");
        PyRun_SimpleString("sys.path.append('./')");

        // Import the specified module
        PyObject *pModule = PyImport_ImportModule("your_module");
        if (pModule != NULL) {
            // Get the function from the module
            PyObject *pFunc = PyObject_GetAttrString(pModule, "your_function");

            // Check if function exists and is callable
            if (pFunc && PyCallable_Check(pFunc)) {
                // Prepare arguments for the function call
                PyObject *pArgs = PyTuple_New(1);
                PyObject *pValue = PyUnicode_FromString("your_argument");
                PyTuple_SetItem(pArgs, 0, pValue);

                // Call the Python function
                PyObject *pResult = PyObject_CallObject(pFunc, pArgs);

                // Process the result if available
                if (pResult != NULL) {
                    const char *result = PyUnicode_AsUTF8(pResult);
                    QMetaObject::invokeMethod(this, [this, result]() {
                        emit resultReady(QString(result));
                    }, Qt::QueuedConnection);
                }

                // Clean up references
                Py_DECREF(pArgs);
                Py_DECREF(pFunc);
            }

            // Decrement module reference count
            Py_DECREF(pModule);
        }

        // Finalize Python interpreter
        Py_Finalize();
    }
};

// Main window class
class MainWindow : public QWidget {
    Q_OBJECT

public:
    // Constructor
    MainWindow(QWidget *parent = nullptr) : QWidget(parent) {
        QVBoxLayout *layout = new QVBoxLayout(this);

        // Create UI elements
        pythonConsole = new QTextEdit(this);
        pythonInput = new QLineEdit(this);
        runButton = new QPushButton("Run Python Code", this);

        // Add widgets to layout
        layout->addWidget(pythonConsole);
        layout->addWidget(pythonInput);
        layout->addWidget(runButton);

        // Connect button click to handler
        connect(runButton, &QPushButton::clicked, this, &MainWindow::runPythonCode);
    }

private slots:
    // Slot to handle running Python code
    void runPythonCode() {
        // Create and configure thread
        pythonThread = new PythonThread(this);
        connect(pythonThread, &PythonThread::resultReady, this, &MainWindow::onResultReady);

        // Disable controls during execution
        pythonInput->setEnabled(false);
        runButton->setEnabled(false);

        // Start the thread
        pythonThread->start();
    }

    // Slot to handle results from Python thread
    void onResultReady(const QString &result) {
        // Display result in console
        pythonConsole->append(result);

        // Re-enable controls
        pythonInput->setEnabled(true);
        runButton->setEnabled(true);

        // Clean up thread object
        pythonThread->deleteLater();
    }

private:
    // UI components
    QTextEdit *pythonConsole;
    QLineEdit *pythonInput;
    QPushButton *runButton;

    // Thread instance
    PythonThread *pythonThread;
};

// Main entry point
int main(int argc, char *argv[]) {
    QApplication app(argc, argv);

    MainWindow window;
    window.show();

    return app.exec();
}

