#include <boost/accumulators/accumulators.hpp>
#include <boost/accumulators/statistics/stats.hpp>
#include <boost/accumulators/statistics/count.hpp>
#include <boost/accumulators/statistics/mean.hpp>
#include <boost/accumulators/statistics/variance.hpp>

namespace acc = boost::accumulators;

// Main function to compute statistics of returns
int main()
{
    // Define accumulator set with count, mean, and variance
    acc::accumulator_set<double, acc::stats<acc::tag::count,
                                            acc::tag::mean,
                                            acc::tag::variance>> stats;

    double prev = NAN;
    bool first = true;

    // Process each value in the sequence
    for (double val : { 1, 1, 2, 1, 3, 2, 3, 4, 6, 3, 2, 1 })
    {
        if (first)
        {
            first = false;
            prev = val;
            continue;
        }

        // Compute return: (current - previous) / previous
        const double ret = (val - prev) / prev;
        stats(ret);
        prev = val;
    }

    // Extract statistics
    double n = acc::count(stats);
    double mean = acc::mean(stats);
    double variance = acc::variance(stats) * n / (n - 1); // Apply Bessel's correction

    // Output results with high precision
    std::cout << std::setprecision(16)
              << "count:    " << n << '\n'
              << "mean:     " << mean << '\n'
              << "variance: " << variance << '\n';

    return 0;
}

