// Global runtime host and info pointers
ICLRRuntimeHost* pHost = NULL;
ICLRRuntimeInfo* pRuntimeInfo = NULL;

// Initialize the CLR runtime
HRESULT InitializeCLR()
{
    HRESULT hr = S_OK;

    // Specify the version of the CLR you want to use
    const wchar_t* pwszVersion = L"v4.0.30319";

    // Get the runtime information
    hr = CLRCreateInstance(CLSID_CLRMetaHost, IID_ICLRRuntimeInfo, (LPVOID*)&pRuntimeInfo);
    if (FAILED(hr))
    {
        return hr;
    }

    // Check if the runtime is supported
    BOOL fLoadable = FALSE;
    hr = pRuntimeInfo->IsLoadable(&fLoadable);
    if (FAILED(hr) || !fLoadable)
    {
        pRuntimeInfo->Release();
        return hr;
    }

    // Load the runtime
    hr = pRuntimeInfo->GetInterface(CLSID_CLRRuntimeHost, IID_ICLRRuntimeHost, (LPVOID*)&pHost);
    if (FAILED(hr))
    {
        pRuntimeInfo->Release();
        return hr;
    }

    // Start the runtime
    hr = pHost->Start();
    if (FAILED(hr))
    {
        pHost->Release();
        pRuntimeInfo->Release();
        return hr;
    }

    return S_OK;
}

// Shutdown the CLR runtime
void ShutdownCLR()
{
    if (pHost)
    {
        pHost->Stop();
        pHost->Release();
    }
    if (pRuntimeInfo)
    {
        pRuntimeInfo->Release();
    }
}

