__inline__ __device__ uint32_t per_byte_bit_left_rotate(uint32_t input, uint8_t amount)
{
    // Perform left rotation on each byte independently
    uint32_t result = 0;
    uint32_t mask = (1 << amount) - 1;

    for(int i=0;i<4;++i)
    {
        uint8_t byte = (input >> (8 * i)) & 0xFF;
        uint8_t rotated = ((byte << amount) & 0xFF) | (byte >> (8 - amount));
        result |= rotated << (8 * i);
    }

    return result;
}

