// Matrix size constant
const int N = 1024;

// CPU matrix multiplication function
void matrixMultiplyCPU(const std::vector<std::vector<int>>& A, 
                       const std::vector<std::vector<int>>& B, 
                       std::vector<std::vector<int>>& C)
{
    for(int i=0; i<N; ++i)
    {
        for(int j=0; j<N; ++j)
        {
            C[i][j] = 0;
            for(int k=0; k<N; ++k)
            {
                C[i][j] += A[i][k] * B[k][j];
            }
        }
    }
}

int main()
{
