struct YuvFrame {
    int width;
    int height;
    uint8_t *data;
    uint8_t *y;
    uint8_t *u;
    uint8_t *v;
};

static struct YuvFrame i420_input_frame;
static struct YuvFrame i420_output_frame;

extern "C" {

JNIEXPORT jbyteArray JNICALL
Java_com_android_camera3_camera_hardware_session_output_photo_yuv_YuvJniInterface_scale420YuvByteArray(
        JNIEnv *env, jclass /*clazz*/, jbyteArray yuvByteArray_, jint src_width, jint src_height,
        jint out_width, jint out_height) {

    jbyte *yuvByteArray = env->GetByteArrayElements(yuvByteArray_, NULL);

    // Get input and output length
    int input_size = env->GetArrayLength(yuvByteArray_);
    int out_size = out_height * out_width * 3 / 2;

    // Generate input frame
    i420_input_frame.width = src_width;
    i420_input_frame.height = src_height;
    i420_input_frame.data = (uint8_t *) yuvByteArray;
    i420_input_frame.y = i420_input_frame.data;
    i420_input_frame.u = i420_input_frame.y + src_width * src_height;
    i420_input_frame.v = i420_input_frame.u + (src_width * src_height) / 4;

    // Generate output frame
    if (i420_output_frame.data != nullptr) {
        delete[] i420_output_frame.data;
    }
    i420_output_frame.width = out_width;
    i420_output_frame.height = out_height;
    i420_output_frame.data = new unsigned char[out_size];
    i420_output_frame.y = i420_output_frame.data;
    i420_output_frame.u = i420_output_frame.y + out_width * out_height;
    i420_output_frame.v = i420_output_frame.u + (out_width * out_height) / 4;

    libyuv::FilterMode mode = libyuv::FilterModeEnum::kFilterBilinear;

    int result = libyuv::I420Scale(
        i420_input_frame.y, i420_input_frame.width,  // Y plane and stride
        i420_input_frame.u, i420_input_frame.width / 2,  // U plane and stride
        i420_input_frame.v, i420_input_frame.width / 2,  // V plane and stride
        i420_input_frame.width, i420_input_frame.height,  // Input width and height
        i420_output_frame.y, i420_output_frame.width,  // Y plane and stride
        i420_output_frame.u, i420_output_frame.width / 2,  // U plane and stride
        i420_output_frame.v, i420_output_frame.width / 2,  // V plane and stride
        i420_output_frame.width, i420_output_frame.height,  // Output width and height
        mode
    );

    LOGD("Image result %d", result);

    // Convert the output to a Java byte array
    jbyteArray outputByteArray = env->NewByteArray(out_size);
    env->SetByteArrayRegion(outputByteArray, 0, out_size, (jbyte *) i420_output_frame.data);

    env->ReleaseByteArrayElements(yuvByteArray_, yuvByteArray, 0);

    return outputByteArray;
}

