    int word_iterate(const char* str, int len)
    {
        UErrorCode status = U_ZERO_ERROR;
        UChar* ustr = new UChar[len / 2 + 1];
        u_strFromUTF8(ustr, len / 2 + 1, nullptr, str, len, &status);
        if (U_FAILURE(status))
        {
            delete[] ustr;
            return -1;
        }

        BreakIterator* bi = BreakIterator::createWordInstance(Locale::getDefault(), status);
        if (U_FAILURE(status))
        {
            delete[] ustr;
            return -1;
        }

        bi->setText(ustr, len / 2, status);
        if (U_FAILURE(status))
        {
            delete[] ustr;
            delete bi;
            return -1;
        }

        int32_t start = bi->first();
        int32_t end = bi->next();

        while (end != BreakIterator::DONE)
        {
            // Process the word from start to end
            // For example, print the word
            UChar* word = new UChar[end - start + 1];
            u_strncpy(word, ustr + start, end - start, &status);
            word[end - start] = 0;

            char* word_utf8 = new char[u_strToUTF8(nullptr, 0, nullptr, word, -1, &status) + 1];
