// Function to return precedence of operators
int precedence(char op)
{
    if (op == '+' || op == '-') return 1;
    if (op == '*' || op == '/') return 2;
    return 0;
}

// Check if character is an operator
bool isOperator(char c)
{
    return c == '+' || c == '-' || c == '*' || c == '/';
}

// Check if character is an operand (letter or digit)
bool isOperand(char c)
{
    return std::isalpha(c) || std::isdigit(c);
}

// Convert infix expression to postfix
std::string infixToPostfix(const std::string& infix)
{
    std::stack<char> stack;
    std::string postfix;

    // Process each character in the infix expression
    for (char c : infix)
    {
        if (isOperand(c))
        {
            postfix += c;
        }
        else if (c == '(')
        {
            stack.push(c);
        }
        else if (c == ')')
        {
            while (!stack.empty() && stack.top() != '(')
            {
                postfix += stack.top();
                stack.pop();
            }
            stack.pop();  // Pop '('
        }
        else if (isOperator(c))
        {
            while (!stack.empty() && precedence(c) <= precedence(stack.top()))
            {
                postfix += stack.top();
                stack.pop();
            }
            stack.push(c);
        }
    }

    // Pop remaining operators from stack
    while (!stack.empty())
    {
        postfix += stack.top();
        stack.pop();
    }

    return postfix;
}

#include <Python.h>
#include <string>
#include <unordered_map>

// A simple in-memory module storage
std::unordered_map<std::string, std::string> memory_modules;

// Custom module loader
extern "C" PyObject* custom_module_loader(PyObject* self, PyObject* args)
{
    PyObject* name_obj;
    if (!PyArg_ParseTuple(args, "O", &name_obj))
    {
        return nullptr;
    }

    const char* name = PyUnicode_AsUTF8(name_obj);
    if (name == nullptr)
    {
        return nullptr;
    }

    auto it = memory_modules.find(name);
    if (it == memory_modules.end())
    {
        PyErr_Format(PyExc_ImportError, "No module named '%s' found in memory", name);
        return nullptr;
    }

    const std::string& code = it->second;
    PyObject* module = PyModule_New(name);
    if (module == nullptr)
    {
        return nullptr;
    }

    if (PyRun_String(code.c_str(), Py_file_input, module->ob_dict, module->ob_dict) == nullptr)
    {
        Py_DECREF(module);
        return nullptr;
    }

    return module;
}

// Register the custom module loader
extern "C" void register_custom_loader()
{
    PyObject* meta_path = PySys_GetObject("meta_path");
    if (meta_path == nullptr)
    {
        return;
    }

    PyObject* loader = PyCFunction_NewEx(&PyCFunctionDef{
        (char*)"custom_module_loader",
        (PyCFunction)custom_module_loader,
        nullptr,
        nullptr
    }, nullptr);

    if (loader != nullptr)
    {
        PyList_Insert(meta_path, 0, loader);
        Py_DECREF(loader);
    }
}

// Example usage
int main()
{
    Py_Initialize();

    // Add a module to memory
    memory_modules["mymodule"] = R"(
def hello():
    return "Hello from mymodule!"
)";

    // Register the custom loader
    register_custom_loader();

    // Import the module
    PyObject* module = PyImport_ImportModule("mymodule");
    if (module == nullptr)
    {
        PyErr_Print();
        return 1;
    }

    // Call a function from the module
    PyObject* hello_func = PyObject_GetAttrString(module, "hello");
    if (hello_func == nullptr)
    {
        PyErr_Print();
        return 1;
    }

    PyObject* result = PyObject_CallObject(hello_func, nullptr);
    if (result == nullptr)
    {
        PyErr_Print();
        return 1;
    }

    const char* message = PyUnicode_AsUTF8(result);
    if (message == nullptr)
    {
        return 1;
    }

    std::cout << "Result: " << message << std::endl;

    Py_DECREF(module);
    Py_DECREF(hello_func);
    Py_DECREF(result);

    Py_Finalize();
    return 0;
}

#include <iostream>
#include <vector>
#include <cmath>

// Computes the cost function for linear regression
double compute_cost(const std::vector<double>& x, const std::vector<double>& y, double theta0, double theta1)
{
    int m = x.size();
    double cost = 0.0;
    for(int i=0;i<m;++i)
    {
        double h = theta0 + theta1 * x[i];
        cost += std::pow(h - y[i], 2);
    }
    return cost / (2 * m);
}

// Performs gradient descent to minimize the cost function
void gradient_descent(const std::vector<double>& x, const std::vector<double>& y, double& theta0, double& theta1, double alpha, int num_iterations)
{
    int m = x.size();
    for(int iter=0;iter<num_iterations;++iter)
    {
        double grad0 = 0.0;
        double grad1 = 0.0;
        for(int i=0;i<m;++i)
        {
            double h = theta0 + theta1 * x[i];
            grad0 += (h - y[i]);
            grad1 += (h - y[i]) * x[i];
        }
        theta0 -= alpha * grad0 / m;
        theta1 -= alpha * grad1 / m;

        // Optionally print the cost to monitor convergence
        double cost = compute_cost(x, y, theta0, theta1);
        std::cout<<"Iteration "<<iter<<" - Cost: "<<cost<<std::endl;
    }
}

int main()
{
    std::vector<double> x = {1, 2, 3, 4, 5};
    std::vector<double> y = {2, 4, 5, 4, 5};

    double theta0 = 0.0;
    double theta1 = 0.0;
    double alpha = 0.01;
    int num_iterations = 1000;

    gradient_descent(x, y, theta0, theta1, alpha, num_iterations);

    std::cout<<"Final theta0: "<<theta0<<", theta1: "<<theta1<<std::endl;

    return 0;

}

