// Native function for image processing using OpenCV
extern "C"
JNIEXPORT jbyteArray JNICALL
Java_com_my_package_name_MyNativeClass_myFunction(JNIEnv* env, jobject /* this */, jbyteArray data)
{
    // Get pointer to the input byte array
    jbyte* dataPtr = env->GetByteArrayElements(data, nullptr);
    int length = env->GetArrayLength(data);

    // Convert jbyteArray to std::vector<uchar>
    std::vector<uchar> vecData(dataPtr, dataPtr + length);
    cv::Mat mat = cv::imdecode(vecData, cv::IMREAD_UNCHANGED);

    // Check if decoding was successful
    if (mat.empty())
    {
        env->ReleaseByteArrayElements(data, dataPtr, 0);
        return nullptr;
    }

    // Apply Canny edge detection
    cv::Mat edges;
    cv::Canny(mat, edges, 50, 150);

    // Encode result as JPEG
    std::vector<uchar> vecEdges;
    cv::imencode(".jpg", edges, vecEdges);

    // Create and populate Java byte array for result
    jbyteArray result = env->NewByteArray(vecEdges.size());
    env->SetByteArrayRegion(result, 0, vecEdges.size(), reinterpret_cast<const jbyte*>(vecEdges.data()));

    // Release native resources
    env->ReleaseByteArrayElements(data, dataPtr, 0);

    return result;
}

