// Compares two strings using SSE instructions
bool compare_strings_sse(const char* s1, const char* s2, size_t length)
{
    for(size_t i=0; i<length; i+=16)
    {
        __m128i v1 = _mm_loadu_si128(reinterpret_cast<const __m128i*>(s1 + i));
        __m128i v2 = _mm_loadu_si128(reinterpret_cast<const __m128i*>(s2 + i));
        // Check if any bytes differ
        if(_mm_cmpneq_epi8(v1, v2))
        {
            return false;
        }
    }
