#include <vector>
#include <stdexcept>

// A min-heap implementation using a vector
class BinaryHeap {
public:
    BinaryHeap() = default;

    // Insert a new element into the heap
    void insert(int value) {
        heap.push_back(value);
        siftUp(heap.size() - 1);
    }

    // Remove and return the minimum element from the heap
    int extractMin() {
        if (heap.empty()) {
            throw std::runtime_error("Heap is empty");
        }

        int root = heap[0];
        heap[0] = heap.back();
        heap.pop_back();
        siftDown(0);

        return root;
    }

    // Get the minimum element without removing it
    int getMin() const {
        if (heap.empty()) {
            throw std::runtime_error("Heap is empty");
        }
        return heap[0];
    }

    // Check if the heap is empty
    bool isEmpty() const {
        return heap.empty();
    }

    // Get the number of elements in the heap
    size_t size() const {
        return heap.size();
    }

private:
    std::vector<int> heap;

    // Sift up the element at index i to its correct position
    void siftUp(int i) {
        while (i > 0) {
            int parent = (i - 1) / 2;
            if (heap[i] < heap[parent]) {
                std::swap(heap[i], heap[parent]);
                i = parent;
            } else {
                break;
            }
        }
    }

    // Sift down the element at index i to its correct position
    void siftDown(int i) {
        int size = heap.size();
        while (2 * i + 1 < size) {
            int left = 2 * i + 1;
            int right = 2 * i + 2;
            int smallest = i;

            if (left < size && heap[left] < heap[smallest]) {
                smallest = left;
            }

            if (right < size && heap[right] < heap[smallest]) {
                smallest = right;
            }

            if (smallest != i) {
                std::swap(heap[i], heap[smallest]);
                i = smallest;
            } else {
                break;
            }
        }
    }
};

// Example usage
int main() {
    BinaryHeap heap;

    heap.insert(3);
    heap.insert(2);
    heap.insert(15);
    heap.insert(5);
    heap.insert(4);
    heap.insert(45);

    while (!heap.isEmpty()) {
        std::cout << heap.extractMin() << " ";
    }

    return 0;
}

