// Thread pool implementation
class ZYLThreadPool {
public:
    // Constructor with max_threads parameter
    ZYLThreadPool(size_t max_threads = 200)
    : stop(false) {
        if (max_threads > 200)
            throw std::invalid_argument("max_threads cannot be greater than 200");

        for (size_t i = 0; i < max_threads; ++i)
            workers.emplace_back([this](){
                while (true) {
                    std::unique_lock<std::mutex> lock(this->queue_mutex);
                    this->condition.wait(lock, [this](){
                        return this->stop || !this->tasks.empty();
                    });

                    if (this->stop && this->tasks.empty())
                        return;

                    auto task = std::move(this->tasks.front());
                    this->tasks.pop();
                    lock.unlock();
                    task.second();
                }
            }
        );
    }

    // Submit function template
    template<class F, class... Args>
    auto submit(F&& f, Args&&... args) -> std::future<typename std::result_of<F(Args...)>::type> {
        using return_type = typename std::result_of<F(Args...)>::type;
        auto task = std::make_shared<std::packaged_task<return_type()>>(std::bind(std::forward<F>(f), std::forward<Args>(args)...));
        std::future<return_type> future_result = task->get_future();

        {
            std::unique_lock<std::mutex> lock(queue_mutex);
            if (stop)
                throw std::runtime_error("submit on a stopped ZYLThreadPool");

            tasks.emplace(std::make_pair(future_result, [task](){ (*task)(); }));
        }

        condition.notify_one();
        return future_result;
    }

    // Cancel function
    void cancel(std::future<void>& future) {
        std::unique_lock<std::mutex> lock(queue_mutex);
        auto it = std::find_if(tasks.begin(), tasks.end(), [&](const Task& task) { return task.first == future; });
        if (it != tasks.end()) {
            tasks.erase(it);
            lock.unlock();
        } else if (stop) {
            throw std::runtime_error("cancel on a stopped ZYLThreadPool");
        } else {
            lock.unlock();
            future.get();
        }
    }

    // Destructor
    ~ZYLThreadPool() {
        {
            std::unique_lock<std::mutex> lock(queue_mutex);
            stop = true;
        }

        condition.notify_all();
        for (std::thread& worker : workers)
            worker.join();
    }

private:
    // Task type definition
    using Task = std::pair<
        std::future<void>,
        std::function<void()>
    >;

    std::vector<std::thread> workers;
    std::queue<Task> tasks;

    std::mutex queue_mutex;
    std::condition_variable condition;
    std::atomic_bool stop;
};

// Main function
int main()
{
    ZYLThreadPool pool(4);

    auto result1 = pool.submit([](int x, int y){ return x * y; }, 3, 4);
    auto result2 = pool.submit([](int x, int y){ return x + y; }, 8, 9);

    std::cout << "result1: " << result1.get() << std::endl;
    std::cout << "result2: " << result2.get() << std::endl;

    return 0;
}

