// Template function for testing with compile-time enable flag
template<bool Enable>
void test_tmp()
{
    // Initialize arrays
    float dst[4] = {1.0, 1.0, 1.0, 1.0};
    float src[4] = {1.0, 2.0, 3.0, 4.0};
    float * dst_addr = dst;
    float * src_addr = src;

    // First assembly block: load and add operations
    asm volatile (
        "vld1.32    {q0}, [%[src]]  \n"
        "vld1.32    {q1}, [%[dst]]  \n"
        "vadd.f32   q0, q0, q1      \n"
        "vadd.f32   q0, q0, q1      \n"
        : [src] "+r" (src_addr),
          [dst] "+r" (dst_addr)
        :
        : "q0", "q1", "memory"
    );

    // Conditional compilation based on Enable template parameter
    if constexpr (Enable) {
        asm volatile (
            "vadd.f32   q0, q0, q1      \n"
            : [src] "+r" (src_addr),
              [dst] "+r" (dst_addr)
            :
            : "q0", "q1", "memory"
        );
    }

    // Store result back to dst array
    asm volatile (
        "vst1.32    {q0}, [%[dst]]  \n"
        : [src] "+r" (src_addr),
          [dst] "+r" (dst_addr)
        :
        : "q0", "q1", "memory"
    );

    // Print results
    for (int i = 0; i < 4; i++)
    {
        std::printf("%f, ", dst[i]);
    }
}

// Explicit template instantiations
template void test_tmp<true>();
template void test_tmp<false>();

int main()
{
    // Call with Enable=true
    test_tmp<true>();
    std::cout << std::endl;
    // Call with Enable=false
    test_tmp<false>();
    return 0;
}

