#include <Wire.h>
#include <esp_now.h>
#include <WiFi.h>

// I2C address for the screen
#define SCREEN_I2C_ADDRESS 0x3C

// Buffer size for screen data
#define BUFFER_SIZE 512

// ESP-NOW communication channel
#define ESP_NOW_CHANNEL 0

// Structure for screen data transmission
typedef struct __attribute__((packed)) {
  uint8_t data[BUFFER_SIZE];
  size_t size;
} ScreenData;

// Queue to hold screen data
QueueHandle_t screenBuffer;

// Callback function for receiving ESP-NOW data
void onReceive(const uint8_t* macAddress, const uint8_t* data, int dataLength) {
  ScreenData receivedData;
  memcpy(&receivedData, data, sizeof(receivedData));
  xQueueSendFromISR(screenBuffer, &receivedData, NULL);
}

// Setup function: initialize peripherals and communication
void setup() {
  Serial.begin(115200);

  // Initialize I2C for communication with RP2040
  Wire.begin();

  // Initialize ESP-NOW communication
  if (esp_now_init() != ESP_OK) {
    Serial.println("ESP-NOW initialization failed");
    return;
  }

  // Register callback for receiving data
  esp_now_register_recv_cb(onReceive);

  // Create queue for screen data buffer
  screenBuffer = xQueueCreate(1, sizeof(ScreenData));

  // Configure ESP-NOW peer device
  esp_now_peer_info_t peer;
  memcpy(peer.peer_addr, (uint8_t[]){0xCA, 0xFE, 0xBA, 0xBE, 0xFA, 0xCE}, 6); // Replace with actual MAC address of ESP32 microcontroller 2
  peer.channel = ESP_NOW_CHANNEL;
  peer.encrypt = false;

  if (esp_now_add_peer(&peer) != ESP_OK) {
    Serial.println("Failed to add ESP-NOW peer");
    return;
  }

  Serial.println("Setup complete");
}

// Main loop: read screen data and transmit via ESP-NOW
void loop() {
  ScreenData screenData;

  // Read screen data from RP2040 through I2C
  Wire.beginTransmission(SCREEN_I2C_ADDRESS);
  Wire.write(0x00); // Data start address
  Wire.endTransmission(false);

  Wire.requestFrom(SCREEN_I2C_ADDRESS, BUFFER_SIZE);
  screenData.size = Wire.readBytes(screenData.data, BUFFER_SIZE);

  // Send screen data to buffer for processing
  if (xQueueSend(screenBuffer, &screenData, portMAX_DELAY) != pdTRUE) {
    Serial.println("Failed to send screen data to buffer");
  }

  delay(1000); // Adjust delay as needed
}

typedef struct {
    float re;
    float im;
} dcmplx;

// Complex convolution function using inline assembly
dcmplx ComplexConv(int len, dcmplx *hat, dcmplx *buf)
{
    dcmplx xout;

    // Initialize real and imaginary parts to zero
    xout.re = xout.im = 0.0;

    asm volatile (
        "movs r3, #0\n\t"
        ".loop:\n\t"
        "vldr s11, [%[hat], #4]\n\t"      // Load imaginary part of hat
        "vldr s13, [%[hat]]\n\t"          // Load real part of hat
        "vneg.f32 s11, s11\n\t"           // Negate imaginary part of hat
        "vldr s15, [%[buf], #4]\n\t"      // Load imaginary part of buf
        "vldr s12, [%[buf]]\n\t"          // Load real part of buf
        "vmul.f32 s14, s15, s13\n\t"      // s14 = buf_im * hat_re
        "vmul.f32 s15, s11, s15\n\t"      // s15 = -hat_im * buf_im
        "adds %[hat], #8\n\t"             // Advance hat pointer by 8 bytes
        "vmla.f32 s14, s11, s12\n\t"      // s14 += -hat_im * buf_re
        "vnmls.f32 s15, s12, s13\n\t"     // s15 -= buf_re * hat_re
        "adds %[buf], #8\n\t"             // Advance buf pointer by 8 bytes
        "vadd.f32 s1, s1, s14\n\t"        // Accumulate real part
        "vadd.f32 s0, s0, s15\n\t"        // Accumulate imaginary part
        "adds r3, r3, #1\n\t"             // Increment counter
        "cmp r3, %[len]\n\t"              // Compare with length
        "bne .loop\n\t"                   // Branch if not equal
        : "=t"(xout.re), "=t"(xout.im)
        : [hat]"r"(hat), [buf]"r"(buf), [len]"r"(len)
        : "s0", "s1", "s11", "s12", "s13", "s14", "s15", "r3", "cc", "memory"
    );

    return xout;
}

