extern "C" rocprofiler_tool_configure_result_t*
rocprofiler_configure(uint32_t                 version,
                      const char*              runtime_version,
                      uint32_t                 priority,
                      rocprofiler_client_id_t* id)
{
    // set the client name
    id->name = "ExampleTool";

    // store client info
    client::client_id = id;

    // compute major/minor/patch version info
    uint32_t major = version / 10000;
    uint32_t minor = (version % 10000) / 100;
    uint32_t patch = version % 100;

    // generate info string
    auto info = std::stringstream{};
    info << id->name << " (priority=" << priority << ") is using rocprofiler-sdk v" << major << "."
         << minor << "." << patch << " (" << runtime_version << ")";
    std::clog << info.str() << std::endl;

    auto* client_tool_data = new std::vector<client::source_location>{};
    client_tool_data->emplace_back(
        client::source_location{__FUNCTION__, __FILE__, __LINE__, info.str()});

    // create configure data
    static auto cfg =
        rocprofiler_tool_configure_result_t{sizeof(rocprofiler_tool_configure_result_t),
                                            &client::tool_init,
                                            &client::tool_fini,
                                            static_cast<void*>(client_tool_data)};

    // return pointer to configure data
    return &cfg;
}

#include <bits/stdc++.h>
using namespace std;

// Main function to solve the problem
int main()
{
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int q;
    if (!(cin >> q)) return 0;

    vector<unsigned long long> ks(q);
    for (int i = 0; i < q; ++i) cin >> ks[i];

    // Process each query
    for (int qi = 0; qi < q; ++qi)
    {
        unsigned long long k = ks[qi]; // k >= 2
        vector<long long> arr;

        long long low = -1, high = 0;

        // Start with single element (F = 2)
        arr.push_back(0);

        // Find most significant bit position
        int msb = 63 - __builtin_clzll(k); // floor(log2(k))

        // Build the array based on binary representation of k
        for (int i = msb - 1; i >= 0; --i)
        {
            if ((k >> i) & 1ULL)
            {
                arr.push_back(low--); // +1 operation: append smallest
            }
            if (i != 0)
            {
                arr.push_back(++high); // *2 operation: append largest
            }
        }

        int n = (int)arr.size();
        vector<pair<long long, int>> vp(n);

        // Create pairs of (value, original index)
        for (int i = 0; i < n; ++i) vp[i] = {arr[i], i};

        // Sort by value to determine ranks
        sort(vp.begin(), vp.end());

        // Build permutation based on ranks
        vector<int> perm(n);
        for (int rank = 0; rank < n; ++rank)
        {
            perm[vp[rank].second] = rank;
        }

        // Output results
        cout << n << "\n";
        for (int i = 0; i < n; ++i)
        {
            if (i) cout << ' ';
            cout << perm[i];
        }
        cout << "\n";
    }

    return 0;
}

