    ///////////////////////////////// NORMALIZE PLANE \\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\*
    /////
    /////	This normalizes a plane (A side) from a given frustum.
    /////
    ///////////////////////////////// NORMALIZE PLANE \\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\*

void Frustum::normalizePlane(float **frustum, int side)
{
    float magnitude = (float) sqrt(frustum[side][A] * frustum[side][A] + frustum[side][B] * frustum[side][B] + frustum[side][C] * frustum[side][C]);

    // Then we divide the plane's values by it's magnitude.
    // This makes it easier to work with.
    frustum[side][A] /= magnitude;
    frustum[side][B] /= magnitude;
    frustum[side][C] /= magnitude;
    frustum[side][D] /= magnitude;
}

void Frustum::calculateFrustum()
{
    _proj->clear();
    _modl->clear();
    _clip->clear();

    // glGetFloatv() is used to extract information about our OpenGL world.
    // Below, we pass in GL_PROJECTION_MATRIX to abstract our projection matrix.
    // It then stores the matrix into an array of [16].
    glGetFloat(GL_PROJECTION_MATRIX, _proj);

    // By passing in GL_MODELVIEW_MATRIX, we can abstract our model view matrix.
    // This also stores it in an array of [16].
    glGetFloat(GL_MODELVIEW_MATRIX, _modl);

    _proj->flip()->limit(16);
    _proj->get(&proj);

    _modl->flip()->limit(16);
    _modl->get(&modl);

    // Now that we have our modelview and projection matrix, if we combine these 2 matrices,
    // it will give us our clipping planes.  To combine 2 matrices, we multiply them.
    clip[0] = modl[0] * proj[0] + modl[1] * proj[4] + modl[2] * proj[8] + modl[3] * proj[12];
    clip[1] = modl[0] * proj[1] + modl[1] * proj[5] + modl[2] * proj[9] + modl[3] * proj[13];
    clip[2] = modl[0] * proj[2] + modl[1] * proj[6] + modl[2] * proj[10] + modl[3] * proj[14];
    clip[3] = modl[0] * proj[3] + modl[1] * proj[7] + modl[2] * proj[11] + modl[3] * proj[15];
    clip[4] = modl[4] * proj[0] + modl[5] * proj[4] + modl[6] * proj[8] + modl[7] * proj[12];
    clip[5] = modl[4] * proj[1] + modl[5] * proj[5] + modl[6] * proj[9] + modl[7] * proj[13];
    clip[6] = modl[4] * proj[2] + modl[5] * proj[6] + modl[6] * proj[10] + modl[7] * proj[14];
    clip[7] = modl[4] * proj[3] + modl[5] * proj[7] + modl[6] * proj[11] + modl[7] * proj[15];
    clip[8] = modl[8] * proj[0] + modl[9] * proj[4] + modl[10] * proj[8] + modl[11] * proj[12];
    clip[9] = modl[8] * proj[1] + modl[9] * proj[5] + modl[10] * proj[9] + modl[11] * proj[13];
    clip[10] = modl[8] * proj[2] + modl[9] * proj[6] + modl[10] * proj[10] + modl[11] * proj[14];
    clip[11] = modl[8] * proj[3] + modl[9] * proj[7] + modl[10] * proj[11] + modl[11] * proj[15];
    clip[12] = modl[12] * proj[0] + modl[13] * proj[4] + modl[14] * proj[8] + modl[15] * proj[12];
    clip[13] = modl[12] * proj[1] + modl[13] * proj[5] + modl[14] * proj[9] + modl[15] * proj[13];
    clip[14] = modl[12] * proj[2] + modl[13] * proj[6] + modl[14] * proj[10] + modl[15] * proj[14];
    clip[15] = modl[12] * proj[3] + modl[13] * proj[7] + modl[14] * proj[11] + modl[15] * proj[15];

    // Now we actually want to get the sides of the frustum.  To do this we take
    // the clipping planes we received above and extract the sides from them.

    // This will extract the RIGHT side of the frustum
    m_Frustum[RIGHT][A] = clip[3] - clip[0];
    m_Frustum[RIGHT][B] = clip[7] - clip[4];
    m_Frustum[RIGHT][C] = clip[11] - clip[8];
    m_Frustum[RIGHT][D] = clip[15] - clip[12];

    // Now that we have a normal (A,B,C) and a distance (D) to the plane,
    // we want to normalize that normal and distance.
    // Normalize the RIGHT side
    normalizePlane(m_Frustum, RIGHT);

    // This will extract the LEFT side of the frustum
    m_Frustum[LEFT][A] = clip[3] + clip[0];
    m_Frustum[LEFT][B] = clip[7] + clip[4];
    m_Frustum[LEFT][C] = clip[11] + clip[8];
    m_Frustum[LEFT][D] = clip[15] + clip[12];

    // Normalize the LEFT side
    normalizePlane(m_Frustum, LEFT);

    // This will extract the BOTTOM side of the frustum
    m_Frustum[BOTTOM][A] = clip[3] + clip[1];
    m_Frustum[BOTTOM][B] = clip[7] + clip[5];
    m_Frustum[BOTTOM][C] = clip[11] + clip[9];
    m_Frustum[BOTTOM][D] = clip[15] + clip[13];

    // Normalize the BOTTOM side
    normalizePlane(m_Frustum, BOTTOM);

    // This will extract the TOP side of the frustum
    m_Frustum[TOP][A] = clip[3] - clip[1];
    m_Frustum[TOP][B] = clip[7] - clip[5];
    m_Frustum[TOP][C] = clip[11] - clip[9];
    m_Frustum[TOP][D] = clip[15] - clip[13];

    // Normalize the TOP side
    normalizePlane(m_Frustum, TOP);

    // This will extract the BACK side of the frustum
    m_Frustum[BACK][A] = clip[3] - clip[2];
    m_Frustum[BACK][B] = clip[7] - clip[6];
    m_Frustum[BACK][C] = clip[11] - clip[10];
    m_Frustum[BACK][D] = clip[15] - clip[14];

    // Normalize the BACK side
    normalizePlane(m_Frustum, BACK);

    // This will extract the FRONT side of the frustum
    m_Frustum[FRONT][A] = clip[3] + clip[2];
    m_Frustum[FRONT][B] = clip[7] + clip[6];
    m_Frustum[FRONT][C] = clip[11] + clip[10];
    m_Frustum[FRONT][D] = clip[15] + clip[14];

    // Normalize the FRONT side
    normalizePlane(m_Frustum, FRONT);
}

#include <iostream>
#include <vector>
#include <algorithm>
#include <random>
#include <numeric>
#include <chrono>

using namespace std;

// Function to handle each test case
void solve() 
{
    int n;
    if (!(cin >> n)) return;

    // Initial set of pens P. We don't know their ink values.
    vector<int> P(n);
    iota(P.begin(), P.end(), 0);

    // Shuffle P to ensure random matchups, which is crucial for the heuristic to work well.
    unsigned seed = std::chrono::system_clock::now().time_since_epoch().count();
    shuffle(P.begin(), P.end(), std::default_random_engine(seed));

    // Set H will store "heavy" pens (candidates that have survived at least one round).
    vector<int> H;

    // Helper lambda for querying a pen
    auto query = [&](int id) -> int 
    {
        cout << "0 " << id << endl;
        int res;
        cin >> res;
        return res;
    };

    // We continue until we have exactly 2 pens left.
    // The strategy is to eliminate pens that run out of ink (return 0).
    // We prioritize checking unknown pens (from P) against known survivors (from H) 
    // to minimize ink consumption on the survivors.
    while (P.size() + H.size() > 2) 
    {
        if (P.empty()) 
        {
            // Only verified pens left, we must pit them against each other.
            // This is the "endgame" where survivors battle.
            int u = H.back(); 
            H.pop_back();
            int v = H.back(); 
            H.pop_back();

            if (query(u) == 0) 
            {
                // u is empty, remove u. v survives and returns to H.
                H.push_back(v);
            } 
            else 
            {
                // u has ink. Check v.
                if (query(v) == 0) 
                {
                    // v is empty, remove v. u survives and returns to H.
                    H.push_back(u);
                } 
                else 
                {
                    // Both have ink. Both return to H.
                    H.push_back(u);
                    H.push_back(v);
                }
            }
        } 
        else 
        {
            // Pick a challenger u from P
            int u = P.back(); 
            P.pop_back();

            if (H.empty()) 
            {
                // No gatekeepers in H, so pick another challenger v from P
                int v = P.back(); 
                P.pop_back();

                if (query(u) == 0) 
                {
                    // u failed. v returns to P (untouched/unverified)
                    P.push_back(v);
                } 
                else 
                {
                    // u passed. Check v.
                    if (query(v) == 0) 
                    {
                        // v failed. u promoted to H
                        H.push_back(u);
                    } 
                    else 
                    {
                        // Both passed. Both promoted to H
                        H.push_back(u);
                        H.push_back(v);
                    }
                }
            } 
            else 
            {
                // Pick a gatekeeper v from H
                int v = H.back(); 
                H.pop_back();

                // Query u first. u is more likely to be 0/small.
                if (query(u) == 0) 
                {
                    // u failed. v saved (untouched) and returns to H
                    H.push_back(v);
                } 
                else 
                {
                    // u passed. Now we must risk v.
                    if (query(v) == 0) 
                    {
                        // v died. u replaces v in H
                        H.push_back(u);
                    } 
                    else 
                    {
                        // Both survived. Both in H.
                        H.push_back(u);
                        H.push_back(v);
                    }
                }
            }
        }
    }

    // Gather the remaining 2 pens
    vector<int> res;
    res.insert(res.end(), P.begin(), P.end());
    res.insert(res.end(), H.begin(), H.end());

    // Output result
    cout << "1 " << res[0] << " " << res[1] << endl;
}

int main() 
{
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int t;
    if (cin >> t) 
    {
        while (t--) 
        {
            solve();
        }
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

vector<vector<int>> adj;
vector<vector<int>> sets;
vector<int> central;
vector<pair<int, int>> decomp_edges;
int cur_id;

// Build decomposition recursively
void build(int u, int par, int incoming_bag) {
    int c = central[u];
    if (incoming_bag != 0) {
        decomp_edges.push_back({c, incoming_bag});
    }
    for (int v : adj[u]) {
        if (v == par) continue;
        int b = cur_id++;
        sets[b] = {u, v};
        decomp_edges.push_back({c, b});
        build(v, u, b);
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
