// Non-deterministic integer helper
int __VERIFIER_nondet_int();

/*
 * Based on "SYNERGY: A New Algorithm for Property Checking" by Gulavani et al.
 */

int main()
{
    int i, c;

    // Initialize loop variables
    i = 0;
    c = 0;

    // Sum integers from 0 to 999
    while(i < 1000)
    {
        c = c + i;
        i = i + 1;
    }

    // Assert non-negativity of sum
    sassert(c >= 0);
}

