// Handle input events
void UIScene_SettingsAudioMenu::handleInput(
    int   iPad,
    int   key,
    bool  repeat,
    bool  pressed,
    bool  released,
    bool& handled
)
{
    // app.DebugPrintf("UIScene_DebugOverlay handling input for pad %d, key %d,
    // down- %s, pressed- %s, released- %s\n", iPad, key, down?"TRUE":"FALSE",
    // pressed?"TRUE":"FALSE", released?"TRUE":"FALSE");
    ui.AnimateKeyPress(m_iPad, key, repeat, pressed, released);

    switch (key)
    {
    case ACTION_MENU_CANCEL:
        if (pressed)
        {
            navigateBack();
        }
        break;

    case ACTION_MENU_OK:
#ifdef __ORBIS__
    case ACTION_MENU_TOUCHPAD_PRESS:
#endif
        sendInputToMovie(key, repeat, pressed, released);
        break;

    case ACTION_MENU_UP:
    case ACTION_MENU_DOWN:
    case ACTION_MENU_LEFT:
    case ACTION_MENU_RIGHT:
        sendInputToMovie(key, repeat, pressed, released);
        break;
    }
}

// Handle slider movement events
void UIScene_SettingsAudioMenu::handleSliderMove(
    F64 sliderId,
    F64 currentValue
)
{
    WCHAR TempString[256];
    int   value = (int)currentValue;

    switch ((int)sliderId)
    {
    case eControl_Music:
        m_sliderMusic.handleSliderMove(value);
        app.SetGameSettings(m_iPad, eGameSetting_MusicVolume, value);
        swprintf(
            (WCHAR*)TempString,
            256,
            L"%ls: %d%%",
            app.GetString(IDS_SLIDER_MUSIC),
            value
        );
        m_sliderMusic.setLabel(TempString);
        break;

    case eControl_Sound:
        m_sliderSound.handleSliderMove(value);
        app.SetGameSettings(m_iPad, eGameSetting_SoundFXVolume, value);
        swprintf(
            (WCHAR*)TempString,
            256,
            L"%ls: %d%%",
            app.GetString(IDS_SLIDER_SOUND),
            value
        );
        m_sliderSound.setLabel(TempString);
        break;
    }
}

