// Free addrinfo structure and associated resources
void freeaddrinfo(struct addrinfo *p)
{
    size_t cnt;

    // Count the number of entries in the list
    for (cnt = 1; p->ai_next; cnt++, p = p->ai_next);

    // Get the base buffer pointer
    struct aibuf *b = (void *)((char *)p - offsetof(struct aibuf, ai));
    b -= b->slot;

    // Lock the buffer
    LOCK(b->lock);

    // Decrement reference count and free if no longer referenced
    if (!(b->ref -= cnt)) 
        free(b);
    else 
        UNLOCK(b->lock);
}

