// Retrieves a string from the game's string table, with support for replacements and overrides
const char *__fastcall GetString(int stringtable, int unused, int string_id, bool *valid)
{
    // Get the singleton instance of GameStr
    GameStr *t = ZealService::get_instance()->gamestr_hook.get();

    // Check if there's a replacement for this string ID
    if (t->str_replacements.count(string_id) > 0)
    {
        if (valid) *valid = true;
        return t->str_replacements[string_id];
    }

    // Check if the string should be suppressed (empty string)
    if (t->str_noprint.count(string_id) && t->str_noprint[string_id])
        return "";

    // Fall back to original function
    const char *d = ZealService::get_instance()->hooks->hook_map["GetString"]->original(GetString)(stringtable, unused,
                                                                                                     string_id, valid);
    return d;
}

