// Template function to average face data onto vertices
template<typename DerivedV,typename DerivedF,typename DerivedS>
IGL_INLINE void igl::average_onto_vertices(
    const Eigen::MatrixBase<DerivedV> &V,
    const Eigen::MatrixBase<DerivedF> &F,
    const Eigen::MatrixBase<DerivedS> &S,
    Eigen::MatrixBase<DerivedS> &SV)
{
  // Initialize output matrix and count vector
  SV = DerivedS::Zero(V.rows(),S.cols());
  Eigen::Matrix<typename DerivedF::Scalar,Eigen::Dynamic,1> COUNT(V.rows());
  COUNT.setZero();

  // Accumulate values from faces to vertices
  for (int i = 0; i < F.rows(); ++i)
  {
    for (int j = 0; j < F.cols(); ++j)
    {
      SV.row(F(i,j)) += S.row(i);
      COUNT[F(i,j)]++;
    }
  }

  // Average by dividing by the count of contributions per vertex
  for (int i = 0; i < V.rows(); ++i)
    SV.row(i) /= COUNT[i];
}

