using namespace std;

class Solution {
public:
    // Counts binary substrings with equal 0s and 1s in contiguous groups
    int countBinarySubstrings(string s)
    {
        int prev = 0;   // length of previous group
        int curr = 1;   // length of current group
        int ans = 0;

        for (int i = 1; i < s.size(); i++)
        {
            if (s[i] == s[i - 1])
            {
                // same group, increase current count
                curr++;
            }
            else
            {
                // count valid substrings between groups
                ans += min(prev, curr);
                prev = curr;            // move current to previous
                curr = 1;               // reset current group count
            }
        }

        // add for the last group pair
        ans += min(prev, curr);
        return ans;
    }
};

