    d_print_mat(1, ng[0], ug0, 1);
    d_print_mat(ng[0], nu[0], D0, ng[0]);
    d_print_mat(ng[0], nx[0], C0, ng[0]);
    d_print_mat(1, ng[1], lg1, 1);
    d_print_mat(1, ng[1], ug1, 1);
    d_print_mat(ng[1], nu[1], D1, ng[1]);
    d_print_mat(ng[1], nx[1], C1, ng[1]);
