    d_ocp_qcqp_set_idxbu(ii, idxbu0, &ocp_qp);
    d_ocp_qcqp_set_lbu(ii, lbu0, &ocp_qp);
    d_ocp_qcqp_set_ubu(ii, ubu0, &ocp_qp);
