// LoadingSpinner constructor
LoadingSpinner::LoadingSpinner(QWidget* parent)
    : QLabel(parent)
    , m_angle(0)
{
    setFixedSize(60, 60);
    setScaledContents(true);
    setAlignment(Qt::AlignCenter);

    // Initialize timer and connect to rotate slot
    m_timer = new QTimer(this);
    connect(m_timer, &QTimer::timeout, this, &LoadingSpinner::rotate);
}

// Start the spinner animation
void LoadingSpinner::start()
{
    m_timer->start(50);
    show();
}

// Stop the spinner animation
void LoadingSpinner::stop()
{
    m_timer->stop();
    hide();
}

// Rotate the spinner by 30 degrees
void LoadingSpinner::rotate()
{
    m_angle = (m_angle + 30) % 360;
    update();
}

// Custom painting for the spinner
void LoadingSpinner::paintEvent(QPaintEvent* event)
{
    Q_UNUSED(event);

    QPainter painter(this);
    painter.setRenderHint(QPainter::Antialiasing);

    // Material Design 3 circular progress indicator
    QPen pen(Colors::toQColor(Colors::PRIMARY), 3);
    pen.setCapStyle(Qt::RoundCap);
    painter.setPen(pen);

    QRect spinRect(10, 10, 40, 40);
    int startAngle = -m_angle * 16;
    int spanAngle = 270 * 16;
    painter.drawArc(spinRect, startAngle, spanAngle);
}

