#include "rest_server/serened.h"
#include <absl/functional/overload.h>
#include "general_server/server_options_feature.h"
#include "rest_server/serened_includes.h"

using namespace sdb;
using namespace sdb::app;

// Static assertion for LoggerFeature ID
static_assert(SerenedServer::id<LoggerFeature>() == 0);

// Non-server features list
constexpr auto kNonServerFeatures = std::array{
#ifdef SDB_CLUSTER
  SerenedServer::id<AgencyFeature>(),
  SerenedServer::id<ClusterFeature>(),
#endif
#ifdef SERENEDB_HAVE_FORK
  SerenedServer::id<SupervisorFeature>(),
  SerenedServer::id<DaemonFeature>(),
#endif
  SerenedServer::id<GeneralServerFeature>(),
  SerenedServer::id<HttpEndpointProvider>(),
  SerenedServer::id<LogBufferFeature>(),
  SerenedServer::id<ServerFeature>(),
  SerenedServer::id<SslServerFeature>(),
  SerenedServer::id<StatisticsFeature>(),
};

// Initialize OpenSSL once
static const boost::asio::ssl::detail::openssl_init<true> kSslInit{};

// Main server execution function
static int RunServer(int argc, char** argv, GlobalContext& context)
{
    try
    {
        CrashHandler::installCrashHandler();
        std::string name = context.binaryName();

        // Setup program options
        auto options = std::make_shared<sdb::options::ProgramOptions>(
            argv[0], "Usage: " + name + " [<options>]",
            "For more information use:", SBIN_DIRECTORY);

        int ret{EXIT_FAILURE};
        SerenedServer server{options, SBIN_DIRECTORY};
        ServerState state;

        // Add reporter to handle state changes
        server.addReporter(
            {[&](SerenedServer::State state) {
                 CrashHandler::SetState(magic_enum::enum_name(state));
                 if (state == SerenedServer::State::InStart)
                 {
                     // drop privileges before starting features
                     server.getFeature<PrivilegeFeature>().dropPrivilegesPermanently();
                 }
             },
             {}});

        // Add features using overload pattern
        server.addFeatures(absl::Overload{
            []<typename T>(auto& server, type::Tag<T>) {
                return std::make_unique<T>(server);
            },
            [&ret](auto& server, type::Tag<CheckVersionFeature>) {
                return std::make_unique<CheckVersionFeature>(server, &ret,
                                                             kNonServerFeatures);
            },
            [&name](auto& server, type::Tag<ConfigFeature>) {
                return std::make_unique<ConfigFeature>(
                    server, name, [] { return GetServerOptions().app_print_version; });
            },
            [](auto& server, type::Tag<InitDatabaseFeature>) {
                return std::make_unique<InitDatabaseFeature>(server,
                                                             kNonServerFeatures);
            },
            [](auto& server, type::Tag<LoggerFeature>) {
                return std::make_unique<LoggerFeature>(server, true);
            },
            [](auto& server, type::Tag<NetworkFeature>) {
                auto& metrics = server.template getFeature<metrics::MetricsFeature>();
                return std::make_unique<NetworkFeature>(
                    server, metrics, network::ConnectionPool::Config{metrics});
            },
            [&ret](auto& server, type::Tag<ServerFeature>) {
                return std::make_unique<ServerFeature>(server, &ret);
            },
            [&name](auto& server, type::Tag<TempPath>) {
                return std::make_unique<TempPath>(server, name);
            },
            [](auto& server, type::Tag<SslServerFeature>) {
                return std::make_unique<SslServerFeature>(server);
            },
            [&ret](auto& server, type::Tag<UpgradeFeature>) {
                return std::make_unique<UpgradeFeature>(server, &ret,
                                                        kNonServerFeatures);
            },
            [](auto& server, type::Tag<HttpEndpointProvider>) {
                return std::make_unique<EndpointFeature>(server);
            },
        });

        try
        {
            server.run(argc, argv);
            if (server.helpShown())
            {
                // --help was displayed
                ret = EXIT_SUCCESS;
            }
        }
        catch (const std::exception& ex)
        {
            SDB_ERROR("xxxxx", Logger::FIXME,
                      "serened terminated because of an exception: ", ex.what());
            ret = EXIT_FAILURE;
        }
        catch (...)
        {
            SDB_ERROR("xxxxx", Logger::FIXME,
                      "serened terminated because of an exception of "
                      "unknown type");
            ret = EXIT_FAILURE;
        }

        log::Flush();
        return context.exit(ret);
    }
    catch (const std::exception& ex)
    {
        SDB_ERROR("xxxxx", Logger::FIXME,
                  "serened terminated because of an exception: ", ex.what());
    }
    catch (...)
    {
        SDB_ERROR("xxxxx", Logger::FIXME,
                  "serened terminated because of an exception of "
                  "unknown type");
    }
    exit(EXIT_FAILURE);
}

// Entry point
int main(int argc, char* argv[])
{
    std::string workdir(basics::file_utils::CurrentDirectory().result());
    GlobalContext context(argc, argv, SBIN_DIRECTORY);
    gRestartAction = nullptr;

    int res = RunServer(argc, argv, context);
    if (res != 0)
    {
        return res;
    }

    if (gRestartAction == nullptr)
    {
        return 0;
    }

    try
    {
        res = (*gRestartAction)();
    }
    catch (...)
    {
        res = -1;
    }

    delete gRestartAction;

    if (res != 0)
    {
        std::cerr << "FATAL: RestartAction returned non-zero exit status: " << res
                  << ", giving up." << std::endl;
        return res;
    }

    // Restart logic for Linux/OSX
#if defined(__linux__)
    res = chdir(workdir.c_str());
    if (res != 0)
    {
        std::cerr << "WARNING: could not change into directory '" << workdir << "'"
                  << std::endl;
    }
    if (execvp(argv[0], argv) == -1)
    {
        std::cerr << "WARNING: could not execvp ourselves, restore will not work!"
                  << std::endl;
    }
#endif
}

#include "test/jemalloc_test.h"
#include "jemalloc/internal/fxp.h"

// Converts fxp_t to double
static double
fxp2double(fxp_t a) {
	double intpart = (double)(a >> 16);
	double fracpart = (double)(a & ((1U << 16) - 1)) / (1U << 16);
	return intpart + fracpart;
}

/* Is a close to b? */
static bool
double_close(double a, double b) {
	/*
	 * Our implementation doesn't try for precision.  Correspondingly, don't
	 * enforce it too strenuously here; accept values that are close in
	 * either relative or absolute terms.
	 */
	return fabs(a - b) < 0.01 || fabs(a - b) / a < 0.01;
}

static bool
fxp_close(fxp_t a, fxp_t b) {
	return double_close(fxp2double(a), fxp2double(b));
}

static fxp_t
xparse_fxp(const char *str) {
	fxp_t result;
	bool err = fxp_parse(&result, str, NULL);
	assert_false(err, "Invalid fxp string: %s", str);
	return result;
}

static void
expect_parse_accurate(const char *str, const char *parse_str) {
	double true_val = strtod(str, NULL);
	fxp_t fxp_val;
	char *end;
	bool err = fxp_parse(&fxp_val, parse_str, &end);
	expect_false(err, "Unexpected parse failure");
	expect_ptr_eq(parse_str + strlen(str), end,
	    "Didn't parse whole string");
	expect_true(double_close(fxp2double(fxp_val), true_val),
	    "Misparsed %s", str);
}

static void
parse_valid_trial(const char *str) {
	/* The value it parses should be correct. */
	expect_parse_accurate(str, str);
	char buf[100];
	snprintf(buf, sizeof(buf), "%swith_some_trailing_text", str);
	expect_parse_accurate(str, buf);
	snprintf(buf, sizeof(buf), "%s with a space", str);
	expect_parse_accurate(str, buf);
	snprintf(buf, sizeof(buf), "%s,in_a_malloc_conf_string:1", str);
	expect_parse_accurate(str, buf);
}

TEST_BEGIN(test_parse_valid) {
	parse_valid_trial("0");
	parse_valid_trial("1");
	parse_valid_trial("2");
	parse_valid_trial("100");
	parse_valid_trial("345");
	parse_valid_trial("00000000123");
	parse_valid_trial("00000000987");
	parse_valid_trial("0.0");
	parse_valid_trial("0.00000000000456456456");
	parse_valid_trial("100.00000000000456456456");
	parse_valid_trial("123.1");
	parse_valid_trial("123.01");
	parse_valid_trial("123.001");
	parse_valid_trial("123.0001");
	parse_valid_trial("123.00001");
	parse_valid_trial("123.000001");
	parse_valid_trial("123.0000001");
	parse_valid_trial(".0");
	parse_valid_trial(".1");
	parse_valid_trial(".01");
	parse_valid_trial(".001");
	parse_valid_trial(".0001");
	parse_valid_trial(".00001");
	parse_valid_trial(".000001");
	parse_valid_trial(".1");
	parse_valid_trial(".10");
	parse_valid_trial(".100");
	parse_valid_trial(".1000");
	parse_valid_trial(".100000");
}
TEST_END

static void
expect_parse_failure(const char *str) {
	fxp_t result = FXP_INIT_INT(333);
	char *end = (void *)0x123;
	bool err = fxp_parse(&result, str, &end);
	expect_true(err, "Expected a parse error on: %s", str);
	expect_ptr_eq((void *)0x123, end,
	    "Parse error shouldn't change results");
	expect_u32_eq(result, FXP_INIT_INT(333),
	    "Parse error shouldn't change results");
}

TEST_BEGIN(test_parse_invalid) {
	expect_parse_failure("123.");
	expect_parse_failure("3.a");
	expect_parse_failure(".a");
	expect_parse_failure("a.1");
	expect_parse_failure("a");
	/* A valid string, but one that overflows. */
	expect_parse_failure("123456789");
	expect_parse_failure("0000000123456789");
	expect_parse_failure("1000000");
}
TEST_END

static void
expect_init_percent(unsigned percent, const char *str) {
	fxp_t result_init = FXP_INIT_PERCENT(percent);
	fxp_t result_parse = xparse_fxp(str);
	expect_u32_eq(result_init, result_parse,
	    "Expect representations of FXP_INIT_PERCENT(%u) and "
	    "fxp_parse(\"%s\") to be equal; got %x and %x",
	    percent, str, result_init, result_parse);
}

/*
 * Every other test uses either parsing or FXP_INIT_INT; it gets tested in those
 * ways.  We need a one-off for the percent-based initialization, though.
 */
TEST_BEGIN(test_init_percent) {
	expect_init_percent(100, "1");
	expect_init_percent(75, ".75");
	expect_init_percent(1, ".01");
	expect_init_percent(50, ".5");
}
TEST_END

static void
expect_add(const char *astr, const char *bstr, const char* resultstr) {
	fxp_t a = xparse_fxp(astr);
	fxp_t b = xparse_fxp(bstr);
	fxp_t result = xparse_fxp(resultstr);
	expect_true(fxp_close(fxp_add(a, b), result),
	    "Expected %s + %s == %s", astr, bstr, resultstr);
}

TEST_BEGIN(test_add_simple) {
	expect_add("0", "0", "0");
	expect_add("0", "1", "1");
	expect_add("1", "1", "2");
	expect_add("1.5", "1.5", "3");
	expect_add("0.1", "0.1", "0.2");
	expect_add("123", "456", "579");
}
TEST_END

static void
expect_sub(const char *astr, const char *bstr, const char* resultstr) {
	fxp_t a = xparse_fxp(astr);
	fxp_t b = xparse_fxp(bstr);
	fxp_t result = xparse_fxp(resultstr);
	expect_true(fxp_close(fxp_sub(a, b), result),
	    "Expected %s - %s == %s", astr, bstr, resultstr);
}

TEST_BEGIN(test_sub_simple) {
	expect_sub("0", "0", "0");
	expect_sub("1", "0", "1");
	expect_sub("1", "1", "0");
	expect_sub("3.5", "1.5", "2");
