// Converts string to integer
int atoi(const char *s)
{
    int n = 0, neg = 0;

    // Skip leading whitespace
    while (isspace(*s)) 
        s++;

    // Check for sign
    switch (*s) {
    case '-': 
        neg = 1;
    case '+': 
        s++;
    }

    /* Compute n as a negative number to avoid overflow on INT_MIN */
    while (isdigit(*s))
        n = 10*n - (*s++ - '0');

    // Return with appropriate sign
    return neg ? n : -n;
}

