using namespace std;

class Solution {
    public:
        int reverse(int x) {
           int reversed = 0;

           while (x != 0) {
            if(reversed > INT_MAX/10 || reversed < INT_MIN/10) return 0;

            reversed = reversed * 10 + x % 10;
            x /= 10;
           }
         return reversed;
        }
        bool isPalindrome(int x) {
            if(x < 0) return false;

            int rev = reverse(x);
            return rev == x;

        }
    };

