    result.push_back(
        std::make_unique<ScalarFunction>(name,
                                         std::vector<LogicalTypeID>{},
                                         LogicalTypeID::DOUBLE,
                                         ScalarFunction::NullaryAuxilaryExecFunction<double, Rand>));
    return result;
}

