#include <set>
#include <algorithm>

using namespace std;

// Solves the word discovery problem using exponential search per starting character
void solve()
{
    int N;
    if (!(cin >> N)) return;

    // Set to store unique words found so far (automatically sorted)
    set<string> found_words;

    // Iterate through each letter from 'a' to 'z'
    for (char c = 'a'; c <= 'z'; ++c)
    {
        // Early termination if we've found all required words
        if (found_words.size() == N) break;

        string s(1, c);
        int local_found = 0;   // Words starting with current character found so far
        int limit = 1;         // Current query size target

        while (found_words.size() < N)
        {
            // Double limit if it's not greater than what we already have
            if (limit <= local_found)
            {
                limit *= 2;
                continue;
            }

            // Calculate remaining possible words starting with current character
            int other_found = found_words.size() - local_found;
            int remaining_possible_local = N - other_found;

            // Determine actual K to query: min of limit and theoretical maximum
            int K = min(limit, remaining_possible_local);

            // Ensure K is strictly greater than what we already have
            if (K <= local_found)
            {
                limit *= 2;
                continue;
            }

            cout << "query " << s << " " << K << endl;
            int k;
            cin >> k;

            // Read k words and insert into our set
            for (int i = 0; i < k; ++i)
            {
                string w;
                cin >> w;
                found_words.insert(w);
            }

            local_found = k;

            // If service returned fewer words than requested, no more words start with this character
            if (k < K) break;

            // Check global termination condition
            if (found_words.size() == N) break;

            // Otherwise, double the limit to search for more words
            limit *= 2;
        }
    }

    // Output the answer
    cout << "answer";
    for (const auto& w : found_words)
    {
        cout << " " << w;
    }
    cout << endl;
}

int main()
{
    int T;
    if (cin >> T)
    {
        while (T--)
        {
            solve();
        }
    }
    return 0;
}

