// This basically does nothing right now. Just return floating bus state.
uint8_t cassette_memory_read(void *context, uint32_t address)
{
    cassette_state_t *cassette_state = (cassette_state_t *)context;
    // Read from floating bus and set bit 7
    return cassette_state->mmu->floating_bus_read() | 0x80; // "real apple //e enhanced with nothing plugged into cassette, reads 80 from C060" - Arekkusu
}

void init_mb_cassette(computer_t *computer, SlotType_t slot)
{
    cassette_state_t *cassette_state = new cassette_state_t;
    cassette_state->mmu = computer->mmu;

    // Register read handlers for cassette ports
    computer->mmu->set_C0XX_read_handler(0xC060, { cassette_memory_read, cassette_state });
    computer->mmu->set_C0XX_read_handler(0xC068, { cassette_memory_read, cassette_state });
}

#include <bits/stdc++.h>
using namespace std;

// Main function
int main()
{
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    if(!(cin >> n)) return 0;

    vector<string> words;

    // Generate words in order of increasing length
    for(int len = 1; (int)words.size() < n; ++len)
    {
        int total = 1 << min(len, 20); // safe when len <= 20; but n<=1000 so len won't exceed 10
        for(int mask = 0; mask < total && (int)words.size() < n; ++mask)
        {
            string s;
            s.reserve(len);
            for(int i = len - 1; i >= 0; --i)
            {
                if(mask & (1 << i)) s.push_back('O');
                else s.push_back('X');
            }
            words.push_back(s);
        }
    }

    // Output all generated words
    for(int i = 0; i < n; ++i)
    {
        cout << words[i] << "\n";
    }
    cout.flush();

    // Process queries
    int q;
    if(!(cin >> q)) return 0;
    while(q--)
    {
        long long p;
        cin >> p;
        cout << 1 << " " << 1 << "\n";
        cout.flush();
    }

    return 0;
}

