int EmptyLevelChunk::getBlocksAndData(byteArray data, int x0, int y0, int z0, int x1, int y1, int z1, int p, bool includeLighting/* = true*/)
{
    int xs = x1 - x0;
    int ys = y1 - y0;
    int zs = z1 - z0;
    int s = xs * ys * zs;
    int len;
    if( includeLighting )
    {
        len = s + s / 2 * 3;
    }
    else
    {
        len = s + s / 2;
    }
    Arrays::fill(data, p, p + len, (byte) 0);
    return len;
}

