    int xs = x1 - x0;
    int ys = y1 - y0;
    int zs = z1 - z0;
    int s = xs * ys * zs;
    if( includeLighting )
    {
        return s + s / 2 * 3;
    }
    else
    {
        return s + s / 2;
    }
}

