using namespace llvm;

// Embeds bitcode into the module
PreservedAnalyses EmbedBitcodePass::run(Module &M, ModuleAnalysisManager &AM)
{
    // Check if bitcode is already embedded
    if (M.getGlobalVariable("llvm.embedded.module", /*AllowInternal=*/true))
        report_fatal_error("Can only embed the module once",
                           /*gen_crash_diag=*/false);

    Triple T(M.getTargetTriple());

    // Verify object format support
    if (T.getObjectFormat() != Triple::ELF)
        report_fatal_error(
            "EmbedBitcode pass currently only supports ELF object format",
            /*gen_crash_diag=*/false);

    std::string Data;
    raw_string_ostream OS(Data);

    // Write bitcode based on LTO type
    if (IsThinLTO)
        ThinLTOBitcodeWriterPass(OS, /*ThinLinkOS=*/nullptr).run(M, AM);
    else
        BitcodeWriterPass(OS, /*ShouldPreserveUseListOrder=*/false, EmitLTOSummary)
            .run(M, AM);

    // Embed the buffer into the module
    embedBufferInModule(M, MemoryBufferRef(Data, "ModuleData"), ".llvm.lto");

    return PreservedAnalyses::all();
}

