#include <iostream>
#include <vector>
#include <unordered_set>

using namespace std;

// Uses Floyd's Cycle Detection Algorithm (Tortoise and Hare)
class Solution {
    public:
        int findDuplicate(vector<int>& nums) {
            int slow = 0;
            int fast = 0;
            int n = nums.size();

            // Find the intersection point of the two runners.
            do {
                slow = nums[slow];
                fast = nums[nums[fast]];
            } while (slow != fast);

            // Find the entrance to the cycle.
            slow = 0;
            while (slow != fast) {
                slow = nums[slow];
                fast = nums[fast];
            }

            return slow; // or fast, both are the same at this point
        }
};

int main() {
    Solution sol;
    vector<int> nums = {1, 3, 4, 2, 2};
    int result = sol.findDuplicate(nums);
    cout << "Duplicate: " << result << endl;
    return 0;
}

