class Solution {
public:
    // Calculates the minimum score triangulation
    int minScoreTriangulation(std::vector<int>& A) {
        int n = A.size();
        int dp[50][50] = {};

        // Iterate over different polygon sizes
        for (int sz = 2; sz < n; sz++) {
            for (int i = 0; i + sz < n; i++) {
                int j = i + sz;
                dp[i][j] = INT_MAX;

                // Try all possible triangulation points
                for (int k = i + 1; k < j; k++) {
                    dp[i][j] = std::min(dp[i][j], A[i] * A[j] * A[k] + dp[i][k] + dp[k][j]);
                }
            }
        }

        return dp[0][n - 1];
    }
};

