    std::string p;
    std::string binary_path = SdbLocateBinaryPath(path);

    // Prepare ICU data
    gIcuData =
        LanguageFeature::prepareIcu(TEST_DIRECTORY, binary_path, p, "basics_suite");

    if (!gIcuData.empty())
    {
        // Set collator language with ICU data
        Utf8Helper::gDefault.setCollatorLanguage("", LanguageType::Default,
                                                 gIcuData.data());
    }
}

