#include <iostream>
#include <vector>
#include <string>
#include <numeric>
#include <algorithm>

using namespace std;

int N, R;
vector<pair<int, int>> adj;
vector<int> parent;

// Global state for recursive forcing
string current_s;

void force_output(int u, int val) {
    if (u >= N) {
        current_s[u] = val + '0';
        return;
    }

    // To get a predictable slot output, we make its inputs equal.
    // Let's force them to 0, which makes slot_output 0 for both AND and OR.
    force_output(adj[u].first, 0);
    force_output(adj[u].second, 0);

    // Now slot_output is 0.
    // output(u) = slot_output ^ s[u] = 0 ^ s[u]
    // We want output(u) = val, so s[u] should be val.
    current_s[u] = val + '0';
}

int do_query(const string& s) {
    cout << "? " << s << endl;
    int result;
    cin >> result;
    return result;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    cin >> N >> R;
    adj.resize(N);
    parent.assign(2 * N + 1, -1);

    for (int i = 0; i < N; ++i) {
        cin >> adj[i].first >> adj[i].second;
        parent[adj[i].first] = i;
        parent[adj[i].second] = i;
    }

    string ans(N, ' ');
    vector<int> path_nodes;
    vector<int> side_nodes;

    for (int i = 0; i < N; ++i) {
        path_nodes.clear();
        side_nodes.clear();

        int curr = i;
        while (parent[curr] != -1) {
            int p = parent[curr];
            if (adj[p].first == curr) {
                side_nodes.push_back(adj[p].second);
            } else {
                side_nodes.push_back(adj[p].first);
            }
            curr = p;
        }

        // --- Test with side branches forced to 0 ---
        // Query A: inputs (0,1), sides 0
        current_s = string(2 * N + 1, '0');
        force_output(adj[i].first, 0);
        force_output(adj[i].second, 1);
        for (int node : side_nodes) {
            force_output(node, 0);
        }
        int out_A = do_query(current_s);

        // Query B: inputs (0,0), sides 0
        current_s = string(2 * N + 1, '0');
        force_output(adj[i].first, 0);
        force_output(adj[i].second, 0);
        for (int node : side_nodes) {
            force_output(node, 0);
        }
        int out_B = do_query(current_s);
        bool diff_side0 = (out_A != out_B);

        // --- Test with side branches forced to 1 ---
        // Query C: inputs (0,1), sides 1
        current_s = string(2 * N + 1, '0');
        force_output(adj[i].first, 0);
        force_output(adj[i].second, 1);
        for (int node : side_nodes) {
            force_output(node, 1);
        }
        int out_C = do_query(current_s);

        // Query D: inputs (0,0), sides 1
        current_s = string(2 * N + 1, '0');
        force_output(adj[i].first, 0);
        force_output(adj[i].second, 0);
        for (int node : side_nodes) {
            force_output(node, 1);
        }
        int out_D = do_query(current_s);
        bool diff_side1 = (out_C != out_D);

        // A difference in output implies the gate is OR, as AND would produce 0 for both (0,1) and (0,0) inputs.
        // This is only detectable if the path to output is sensitive.
        // By trying both side=0 and side=1, we try to create a sensitive path for both OR-heavy and AND-heavy paths.
        if (diff_side0 || diff_side1) {
            ans[i] = '|';
        } else {
            ans[i] = '&';
        }
    }

    cout << "! " << ans << endl;
    return 0;
}

#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

// Structure to store the operations
struct Op {
    int v;
    int i;
};

int main()
{
    // Optimization for faster I/O
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n, m;
    if (!(cin >> n >> m)) return 0;

    // Stacks are 1-indexed to match the problem statement's output format (1 to m)
    // 0 is used for the "carry out" operation destination
    vector<vector<int>> stacks(m + 1);

    // Read the initial configuration of boxes
    // Each stack has exactly n/m boxes initially
    for (int i = 1; i <= m; ++i) {
        for (int j = 0; j < n / m; ++j) {
            int b;
            cin >> b;
            stacks[i].push_back(b);
        }
    }

    vector<Op> ops;
    int current_target = 1;

    // Main loop to process boxes from 1 to n
    while (current_target <= n) {
        int s_idx = -1;
        int b_idx = -1;

        // Locate the current target box
        for (int i = 1; i <= m; ++i) {
            for (int j = 0; j < stacks[i].size(); ++j) {
                if (stacks[i][j] == current_target) {
                    s_idx = i;
                    b_idx = j;
                    break;
                }
            }
            if (s_idx != -1) break;
        }

        // If the target box is at the top of its stack, carry it out
        if (b_idx == (int)stacks[s_idx].size() - 1) {
            ops.push_back({current_target, 0});
            stacks[s_idx].pop_back();
            current_target++;
            continue;
        }

        // If not at the top, we need to move the boxes above it to other stacks.
        // We look for the best "chunk" of boxes to move from the top of the stack.
        // A chunk is defined by the number of boxes from the top (sz).

        int boxes_above = (int)stacks[s_idx].size() - 1 - b_idx;

        int best_sz = -1;
        int best_dst = -1;
        long long best_score = -2e18; // Initialize with a very low score

        // Iterate through all possible chunk sizes we can move
        for (int sz = 1; sz <= boxes_above; ++sz) {
            int start_pos = (int)stacks[s_idx].size() - sz;

            // Find the maximum value in this chunk to determine if it fits nicely
            int chunk_max = -1;
            for (int k = 0; k < sz; ++k) {
                chunk_max = max(chunk_max, stacks[s_idx][start_pos + k]);
            }

            // Evaluate all possible destination stacks
            for (int dst = 1; dst <= m; ++dst) {
                if (dst == s_idx) continue; // Cannot move to the same stack

                // Determine the value at the top of the destination stack
                // If empty, treat it as having a very large value (1000)
                int top_val = (stacks[dst].empty()) ? 1000 : stacks[dst].back();

                long long score;

                // Heuristic Scoring Logic
                if (chunk_max < top_val) {
                    // Valid Move: The max value in chunk is smaller than destination top.
                    // This maintains the sorted property (larger values below smaller values).
                    // We prioritize these moves heavily.

                    // Base score for validity: 200,000
                    // Bonus for moving larger chunks (efficiency): sz * 1000
                    // Penalty for "waste" (gap between top_val and chunk_max): -(top_val - chunk_max)
                    // We prefer tight fits (small gap) and non-empty stacks over empty ones (if fit is good).
                    score = 200000LL + (long long)sz * 1000 - (top_val - chunk_max);
                } else {
                    // Invalid Move: We are placing a larger value on a smaller one.
                    // This blocks the smaller value, which is bad.
                    // If we must do this, we prefer to block larger values (less urgent).
                    // Score is proportional to top_val.
                    // Secondary priority: move larger chunks to save energy.
                    score = (long long)top_val * 1000 + sz;
                }

                if (score > best_score) {
                    best_score = score;
                    best_sz = sz;
                    best_dst = dst;
                }
            }
        }

        // Execute the best move found
        int move_start_idx = (int)stacks[s_idx].size() - best_sz;
        int moved_box_v = stacks[s_idx][move_start_idx]; // This is the box 'v' for the operation

        ops.push_back({moved_box_v, best_dst});

        // Update the stack data structures
        vector<int> moving_chunk;
        moving_chunk.reserve(best_sz);

        // Collect boxes
        for (int k = 0; k < best_sz; ++k) {
            moving_chunk.push_back(stacks[s_idx][move_start_idx + k]);
        }

        // Remove from source stack
        stacks[s_idx].resize(move_start_idx);

        // Add to destination stack
        for (int x : moving_chunk) {
            stacks[best_dst].push_back(x);
        }
    }

    // Output the operations
    for (const auto& op : ops) {
        cout << op.v << " " << op.i << "\n";
    }

    return 0;
}

#define UCLN_TYPE_IS_COMMON
#include "ucln_imp.h"

// Global cleanup function arrays
static cleanupFunc *gCommonCleanupFunctions[UCLN_COMMON_COUNT];
static cleanupFunc *gLibCleanupFunctions[UCLN_COMMON];

/************************************************
 The cleanup order is important in this function.
 Please be sure that you have read ucln.h
 ************************************************/

U_CAPI void U_EXPORT2
u_cleanup()
{
    UTRACE_ENTRY_OC(UTRACE_U_CLEANUP);

    // Force a memory barrier, so that we are sure to see
    //   all state left around by any other threads.
    icu::umtx_lock(nullptr);     
    icu::umtx_unlock(nullptr);   

    ucln_lib_cleanup();

    // Undo any heap functions set by u_setMemoryFunctions().
    cmemory_cleanup();       

    // Must be before utrace_cleanup(), which turns off tracing.
    UTRACE_EXIT();           
/*#if U_ENABLE_TRACING*/
    utrace_cleanup();
/*#endif*/
}

U_CAPI void U_EXPORT2 ucln_cleanupOne(ECleanupLibraryType libType) 
{
    if (gLibCleanupFunctions[libType])
    {
        gLibCleanupFunctions[libType]();
        gLibCleanupFunctions[libType] = nullptr;
    }
}

U_CFUNC void
ucln_common_registerCleanup(ECleanupCommonType type,
                            cleanupFunc *func)
{
    // Thread safety messiness: From ticket 10295, calls to registerCleanup() may occur
    // concurrently. Although such cases should be storing the same value, they raise errors
    // from the thread sanity checker. Doing the store within a mutex avoids those.
    // BUT that can trigger a recursive entry into std::call_once() in umutex.cpp when this code,
    // running from the call_once function, tries to grab the ICU global mutex, which
    // re-enters the mutex init path. So, work-around by special casing UCLN_COMMON_MUTEX, not
    // using the ICU global mutex for it.
    //
    // No other point in ICU uses std::call_once().
    U_ASSERT(UCLN_COMMON_START < type && type < UCLN_COMMON_COUNT);

    if (type == UCLN_COMMON_MUTEX) 
    {
        gCommonCleanupFunctions[type] = func;
    } 
    else if (UCLN_COMMON_START < type && type < UCLN_COMMON_COUNT)  
    {
        // See ticket 10295 for discussion.
        icu::Mutex m;     
        gCommonCleanupFunctions[type] = func;
    }

#if !UCLN_NO_AUTO_CLEANUP && (defined(UCLN_AUTO_ATEXIT) || defined(UCLN_AUTO_LOCAL))
    ucln_registerAutomaticCleanup();
#endif
}

// Note: ucln_registerCleanup() is called with the ICU global mutex locked.
//       Be aware if adding anything to the function.
//       See ticket 10295 for discussion.
U_CAPI void U_EXPORT2
ucln_registerCleanup(ECleanupLibraryType type,
                     cleanupFunc *func)
{
    U_ASSERT(UCLN_START < type && type < UCLN_COMMON);

    if (UCLN_START < type && type < UCLN_COMMON)
    {
        gLibCleanupFunctions[type] = func;
    }
}

U_CFUNC UBool ucln_lib_cleanup() 
{
    int32_t libType = UCLN_START;
    int32_t commonFunc = UCLN_COMMON_START;

    // Clean up library-specific functions
    for (libType++; libType<UCLN_COMMON; libType++) 
    {
        ucln_cleanupOne(static_cast<ECleanupLibraryType>(libType));
    }

    // Clean up common functions
    for (commonFunc++; commonFunc<UCLN_COMMON_COUNT; commonFunc++) 
    {
        if (gCommonCleanupFunctions[commonFunc])
        {
            gCommonCleanupFunctions[commonFunc]();
            gCommonCleanupFunctions[commonFunc] = nullptr;
        }
    }

#if !UCLN_NO_AUTO_CLEANUP && (defined(UCLN_AUTO_ATEXIT) || defined(UCLN_AUTO_LOCAL))
    ucln_unRegisterAutomaticCleanup();
#endif

    return true;
}

