/// @requirements(SEN-1060)
TEST(QuaternionTest, slerp)
{
    Quat from = Quat<f64>(0, 0, toRad(15.0));
    Quat to = Quat<f64>(0, 0, toRad(55.0));
    Quat result = Quat<f64>(0, 0, 0);

