							SNew(SImage)
							.Image(FSlateIconFinder::FindIconBrushForClass(UMoviePipelineConfigBase::StaticClass()))
						]
						+ SHorizontalBox::Slot()
						.Padding(0, 1, 0, 0)
						[
							SNew(STextBlock)
							.Text(LOCTEXT("PresetsToolbarButton", "Presets"))
						]
					]
				]
			]
		]

		// Large Label Telling You What You're Editing
		+SVerticalBox::Slot()
		.AutoHeight()
