// Convert ASCII digit to hex value
unsigned char asciiDigitToHex(char digit) {
    if (0x61 <= digit && digit <= 0x66) {
        return digit - 0x61 + 0xa;
    } else if (0x41 <= digit && digit <= 0x46) {
        return digit - 0x41 + 0xa;
    } else
        return digit - 0x30;
}

// Parse 16-character hex string into 16 bytes
void parseHex16(const char *input, unsigned char *output) {
    const char *src = input;
    unsigned int val;
    int i;
    for (i = 0; i < 0x10; i++, src += 2) {
        val = asciiDigitToHex(src[1]) + (asciiDigitToHex(src[0]) << 4);
        *output++ = val;
    }
}

// Simple LCG random number generator
long random(long l) {
    static long s_seed = 0xEB;
    if (l != 0)
        s_seed = l;
    s_seed = s_seed * 0x19660E + 0x3C6EF35F;
    return s_seed;
}

// Check if byteswap is needed based on endianness
#define NEEDS_BYTESWAP(p, v) (*(((unsigned char *)(p)) + 3) == (v))

// Swap bytes in a 32-bit value
#define BYTESWAP_32BIT(v)                                                                \
    do {                                                                                 \
        unsigned char t0, t1;                                                            \
        t0 = *((unsigned char *)(v) + 0);                                                \
        t1 = *((unsigned char *)(v) + 3);                                                \
        *((unsigned char *)(v) + 0) = t1;                                                \
        *((unsigned char *)(v) + 3) = t0;                                                \
        t0 = *((unsigned char *)(v) + 1);                                                \
        t1 = *((unsigned char *)(v) + 2);                                                \
        *((unsigned char *)(v) + 1) = t1;                                                \
        *((unsigned char *)(v) + 2) = t0;                                                \
    } while (0);

// Generate masher key using random values
void KeyChain::getMasher(unsigned char *uc) {
    unsigned int *masher_p = reinterpret_cast<unsigned int *>(uc);
    unsigned int m = 1;
    int needs_byteswap = NEEDS_BYTESWAP(&m, 1);
    for (int i = 0; i < 8; i++) {
        *masher_p = random((i == 0) ? 0xEB : 0);
        if (needs_byteswap) {
            BYTESWAP_32BIT(masher_p);
        }
        masher_p++;
    }
}

// XOR two byte arrays
void mash(unsigned char *uc1, unsigned char *uc2) {
    unsigned int *ui1 = (unsigned int *)uc1;
    unsigned int *ui2 = (unsigned int *)uc2;
    for (int i = 0; i < 8; i++) {
        ui1[i] = ui1[i] ^ ui2[i];
    }
}

// Circular rotation function
int roll(int i) {
    i += 19;
    i %= 32;
    return i;
}

// Swap two characters
void swap(char &c1, char &c2) {
    char tmp = c1;
    c1 = c2;
    c2 = tmp;
}

// Shuffle operations for obfuscation
void shuffle1(char *c) {
    for (int i = 0; i < 8; i++) {
        swap(c[roll(i * 4)], c[i * 4 + 2]);
        swap(c[roll(i * 4 + 3)], c[i * 4 + 1]);
    }
}

void shuffle2(char *c) {
    for (int i = 0; i < 8; i++) {
        swap(c[(7 - i) * 4 + 1], c[i * 4 + 2]);
        swap(c[(7 - i) * 4], c[i * 4 + 3]);
    }
}

void shuffle3(char *c) {
    for (int i = 0; i < 8; i++) {
        swap(c[roll((7 - i) * 4 + 1)], c[i * 4 + 2]);
        swap(c[(7 - i) * 4], c[i * 4 + 3]);
    }
}

void shuffle4(char *c) {
    for (int i = 0; i < 8; i++) {
        swap(c[(7 - i) * 4 + 1], c[i * 4 + 2]);
        swap(c[roll((7 - i) * 4)], c[i * 4 + 3]);
    }
}

void shuffle5(char *c) {
    for (int i = 0; i < 8; i++) {
        swap(c[(7 - i) * 4 + 1], c[roll(i * 4 + 2)]);
        swap(c[(7 - i) * 4], c[i * 4 + 3]);
    }
}

void shuffle6(char *c) {
    for (int i = 0; i < 8; i++) {
        swap(c[(7 - i) * 4 + 1], c[i * 4 + 2]);
        swap(c[(7 - i) * 4], c[roll(i * 4 + 3)]);
    }
}

// Combined shuffle operation
void supershuffle(char *c) {
    shuffle1(c);
    shuffle2(c);
    shuffle3(c);
    shuffle4(c);
    shuffle5(c);
    shuffle6(c);
}

// Opaque predicate for anti-analysis
void opaquePredicate() {
    static int nTimesCalled = 0;
    nTimesCalled++;
}

// Secure copy with opaque predicate calls
void memcpy_cs(unsigned char *uc, const unsigned char *cuc, unsigned int i) {
    for (int x = 0; x < i; x++) {
        opaquePredicate();
        uc[x] = cuc[x];
    }
}

// Reveal key through shuffling and XOR
void revealKey(long *lp, unsigned char *uc) {
    for (int i = 0; i < 0xE; i++) {
        supershuffle((char *)lp);
    }
    mash((unsigned char *)lp, uc);
}

// Get key implementation
void getKeyImpl(unsigned char *uc1, char *c, unsigned char *uc2) {
    revealKey((long *)uc1, uc2);
    memcpy_cs((unsigned char *)c, uc1, 0x20);
}

// Main key retrieval function
void KeyChain::getKey(unsigned int i, unsigned char *uc1, unsigned char *uc2) {
    unsigned char uchar_arr[32];
    char char_arr[32];
    memcpy_cs(uchar_arr, &hiddenKeys[i * 0x20], 0x20);
    getKeyImpl(uchar_arr, char_arr, uc2);
    parseHex16(char_arr, uc1);
}

// Return number of keys
unsigned int KeyChain::getNumKeys() { return 0xC; }

#include "jemalloc/internal/jemalloc_preamble.h"
#include "jemalloc/internal/jemalloc_internal_includes.h"
#include "jemalloc/internal/assert.h"
#include "jemalloc/internal/ehooks.h"
#include "jemalloc/internal/san.h"
#include "jemalloc/internal/tsd.h"

/* The sanitizer options. */
size_t opt_san_guard_large = SAN_GUARD_LARGE_EVERY_N_EXTENTS_DEFAULT;
size_t opt_san_guard_small = SAN_GUARD_SMALL_EVERY_N_EXTENTS_DEFAULT;

/* Aligned (-1 is off) ptrs will be junked & stashed on dealloc. */
ssize_t opt_lg_san_uaf_align = SAN_LG_UAF_ALIGN_DEFAULT;

/*
 *  Initialized in san_init().  When disabled, the mask is set to (uintptr_t)-1
 *  to always fail the nonfast_align check.
 */
uintptr_t san_cache_bin_nonfast_mask = SAN_CACHE_BIN_NONFAST_MASK_DEFAULT;

static inline void
san_find_guarded_addr(edata_t *edata, uintptr_t *guard1, uintptr_t *guard2,
    uintptr_t *addr, size_t size, bool left, bool right) {
	assert(!edata_guarded_get(edata));
	assert(size % PAGE == 0);
	*addr = (uintptr_t)edata_base_get(edata);
	if (left) {
		*guard1 = *addr;
		*addr += SAN_PAGE_GUARD;
	} else {
		*guard1 = 0;
	}
	if (right) {
		*guard2 = *addr + size;
	} else {
		*guard2 = 0;
	}
}

static inline void
san_find_unguarded_addr(edata_t *edata, uintptr_t *guard1, uintptr_t *guard2,
    uintptr_t *addr, size_t size, bool left, bool right) {
	assert(edata_guarded_get(edata));
	assert(size % PAGE == 0);
	*addr = (uintptr_t)edata_base_get(edata);
	if (right) {
		*guard2 = *addr + size;
	} else {
		*guard2 = 0;
	}
	if (left) {
		*guard1 = *addr - SAN_PAGE_GUARD;
		assert(*guard1 != 0);
		*addr = *guard1;
	} else {
		*guard1 = 0;
	}
}

void
san_guard_pages(tsdn_t *tsdn, ehooks_t *ehooks, edata_t *edata, emap_t *emap,
    bool left, bool right, bool remap) {
	assert(left || right);
	if (remap) {
		emap_deregister_boundary(tsdn, emap, edata);
	}
	size_t size_with_guards = edata_size_get(edata);
	size_t usize = (left && right)
	    ? san_two_side_unguarded_sz(size_with_guards)
	    : san_one_side_unguarded_sz(size_with_guards);
	uintptr_t guard1, guard2, addr;
	san_find_guarded_addr(edata, &guard1, &guard2, &addr, usize, left,
	    right);
	assert(edata_state_get(edata) == extent_state_active);
	ehooks_guard(tsdn, ehooks, (void *)guard1, (void *)guard2);
	/* Update the guarded addr and usable size of the edata. */
	edata_size_set(edata, usize);
	edata_addr_set(edata, (void *)addr);
	edata_guarded_set(edata, true);
	if (remap) {
		emap_register_boundary(tsdn, emap, edata, SC_NSIZES,
		    /* slab */ false);
	}
}

static void
san_unguard_pages_impl(tsdn_t *tsdn, ehooks_t *ehooks, edata_t *edata,
    emap_t *emap, bool left, bool right, bool remap) {
	assert(left || right);
	/* Remove the inner boundary which no longer exists. */
	if (remap) {
		assert(edata_state_get(edata) == extent_state_active);
		emap_deregister_boundary(tsdn, emap, edata);
	} else {
		assert(edata_state_get(edata) == extent_state_retained);
	}
	size_t size = edata_size_get(edata);
	size_t size_with_guards = (left && right)
	    ? san_two_side_guarded_sz(size)
	    : san_one_side_guarded_sz(size);
	uintptr_t guard1, guard2, addr;
	san_find_unguarded_addr(edata, &guard1, &guard2, &addr, size, left,
	    right);
	ehooks_unguard(tsdn, ehooks, (void *)guard1, (void *)guard2);
	/* Update the true addr and usable size of the edata. */
	edata_size_set(edata, size_with_guards);
	edata_addr_set(edata, (void *)addr);
	edata_guarded_set(edata, false);
	/*
	 * Then re-register the outer boundary including the guards, if
	 * requested.
	 */
	if (remap) {
		emap_register_boundary(tsdn, emap, edata, SC_NSIZES,
		    /* slab */ false);
	}
}

void
san_unguard_pages(tsdn_t *tsdn, ehooks_t *ehooks, edata_t *edata,
    emap_t *emap, bool left, bool right) {
	san_unguard_pages_impl(tsdn, ehooks, edata, emap, left, right,
	    /* remap */ true);
}

void
san_unguard_pages_pre_destroy(tsdn_t *tsdn, ehooks_t *ehooks, edata_t *edata,
    emap_t *emap) {
	emap_assert_not_mapped(tsdn, emap, edata);
	/*
	 * We don't want to touch the emap of about to be destroyed extents, as
	 * they have been unmapped upon eviction from the retained ecache. Also,
	 * we unguard the extents to the right, because retained extents only
	 * own their right guard page per san_bump_alloc's logic.
	 */
	 san_unguard_pages_impl(tsdn, ehooks, edata, emap, /* left */ false,
	    /* right */ true, /* remap */ false);
}

static bool
san_stashed_corrupted(void *ptr, size_t size) {
	if (san_junk_ptr_should_slow()) {
		for (size_t i = 0; i < size; i++) {
			if (((char *)ptr)[i] != (char)uaf_detect_junk) {
				return true;
			}
		}
		return false;
	}
	void *first, *mid, *last;
	san_junk_ptr_locations(ptr, size, &first, &mid, &last);
	if (*(uintptr_t *)first != uaf_detect_junk ||
	    *(uintptr_t *)mid != uaf_detect_junk ||
	    *(uintptr_t *)last != uaf_detect_junk) {
		return true;
	}
	return false;
}

void
san_check_stashed_ptrs(void **ptrs, size_t nstashed, size_t usize) {
	/*
	 * Verify that the junked-filled & stashed pointers remain unchanged, to
	 * detect write-after-free.
	 */
	for (size_t n = 0; n < nstashed; n++) {
		void *stashed = ptrs[n];
		assert(stashed != NULL);
		assert(cache_bin_nonfast_aligned(stashed));
		if (unlikely(san_stashed_corrupted(stashed, usize))) {
			safety_check_fail("<jemalloc>: Write-after-free "
			    "detected on deallocated pointer %p (size %zu).\n",
			    stashed, usize);
		}
	}
}

void
tsd_san_init(tsd_t *tsd) {
	*tsd_san_extents_until_guard_smallp_get(tsd) = opt_san_guard_small;
	*tsd_san_extents_until_guard_largep_get(tsd) = opt_san_guard_large;
}

void
san_init(ssize_t lg_san_uaf_align) {
	assert(lg_san_uaf_align == -1 || lg_san_uaf_align >= LG_PAGE);
	if (lg_san_uaf_align == -1) {
		san_cache_bin_nonfast_mask = (uintptr_t)-1;
		return;
	}
	san_cache_bin_nonfast_mask = ((uintptr_t)1 << lg_san_uaf_align) - 1;
}

#include "../src/idiomata/idiom_resolver.hpp"
#include <cassert>
#include <iostream>

using namespace idiomata;

int main()
{
    // 32-bit division by 3: magic = 1431655766 (0x55555556), extra shift = 0.
    std::vector<LocalInsn> seq1 = {
        {0, "imul", {"reg_0", "reg_0", "const_1"}},
        {4, "sar", {"reg_0", "const_2"}}
    };
    std::unordered_map<std::string, std::string> const_map1 = {
        {"0x55555556", "const_1"},
        {"0x0", "const_2"}
    };
    std::unordered_map<std::string, std::string> reg_map1 = { {"eax", "reg_0"} };
    assert(SequenceResolver(seq1, const_map1, reg_map1).resolve_divs() == 3);

    // 32-bit signed division by 5: magic = -1717986919 (0x99999999), extra shift = 1.
    std::vector<LocalInsn> seq2 = {
        {0, "imul", {"reg_0", "reg_0", "const_1"}},
        {4, "sar", {"reg_0", "const_2"}},
        {8, "sar", {"reg_0", "const_3"}}
    };
    std::unordered_map<std::string, std::string> const_map2 = {
        {"0x99999999", "const_1"},
        {"0x20", "const_2"}, // 32
        {"0x1", "const_3"}   // 1 (extra shift)
    };
    std::unordered_map<std::string, std::string> reg_map2 = { {"eax", "reg_0"} };
    assert(SequenceResolver(seq2, const_map2, reg_map2).resolve_divs() == 5);

    // Unsigned division by 5: magic = 3435973837 (0xCCCCCCCD), shift = 2
    std::vector<LocalInsn> seq3 = {
        {0, "mul", {"reg_0", "reg_0", "const_1"}},
        {4, "shr", {"reg_0", "const_2"}}
    };
    std::unordered_map<std::string, std::string> const_map3 = {
        {"0xcccccccd", "const_1"},
        {"0x2", "const_2"} // power=2
    };
    std::unordered_map<std::string, std::string> reg_map3 = { {"eax", "reg_0"} };
    assert(SequenceResolver(seq3, const_map3, reg_map3).resolve_divu() == 5);

    // Unsigned modulo by power-of-two via mask: x & 0xF -> % 16
    std::vector<LocalInsn> seq4 = {
        {0, "and", {"reg_0", "const_0"}}
    };
    std::unordered_map<std::string, std::string> const_map4 = {
        {"0xf", "const_0"}
    };
    std::unordered_map<std::string, std::string> reg_map4 = { {"eax", "reg_0"} };
    assert(SequenceResolver(seq4, const_map4, reg_map4).resolve_modu() == 16);

    // Multiplication by left shift amount.
    std::vector<LocalInsn> seq5 = {
        {0, "shl", {"reg_0", "const_0"}}
    };
    std::unordered_map<std::string, std::string> const_map5 = {
        {"0x3", "const_0"}
    };
    std::unordered_map<std::string, std::string> reg_map5 = { {"eax", "reg_0"} };
    assert(SequenceResolver(seq5, const_map5, reg_map5).resolve_mul() == 8);

    std::cout << "All idiom semantic resolution tests passed!" << std::endl;
    return 0;
}

#include <vector>
#include <queue>
#include <algorithm>
#include <iostream>

// First solution using sorting and max-heap
class Solution {
public:
    double mincostToHireWorkers(std::vector<int>& quality, std::vector<int>& wage, int k) {
        std::vector<std::pair<double, int>> workers;
        int workerCount = quality.size();

        // Calculate wage/quality ratio for each worker
        for(int i = 0; i < workerCount; i++) {
            double ratio = (1.0 * wage[i]) / quality[i];
            workers.push_back({ratio, quality[i]});
        }

        // Sort by ratio
        std::sort(workers.begin(), workers.end());

        int qualitySum = 0;
        std::priority_queue<int> maxHeapQuality;
        double minCostToHire = 1e18;

        // Process each worker as potential captain (highest ratio in group)
        for(auto& worker: workers) {
            double ratio = worker.first;
            int quality = worker.second;

            // Add current worker's quality to heap
            maxHeapQuality.push(quality);
            qualitySum += quality;

            // Maintain only k workers in heap
            if(k < maxHeapQuality.size()) {
                qualitySum -= maxHeapQuality.top();
                maxHeapQuality.pop();
            }

            // If we have exactly k workers, calculate cost
            if(k == maxHeapQuality.size()) {
                minCostToHire = std::min(minCostToHire, 1.0 * qualitySum * ratio);
            }
        }

        return minCostToHire;
    }
};

// Second solution using brute force approach
class Solution {
public:
    double mincostToHireWorkers(std::vector<int>& quality, std::vector<int>& wage, int k) {
        int workerCount = quality.size();
        double minCostToHire = 1e18;

        // Try each worker as the "captain" (determines the ratio)
        for(int i = 0; i < workerCount; i++) {
            double ratio = (1.0 * wage[i]) / quality[i];
            std::vector<double> allowedWorkers;

            // Find all workers who can be hired at this ratio
            for(int j = 0; j < workerCount; j++) {
                int workerQuality = quality[j];
                int workerWage = wage[j];

                // Check if worker j accepts this ratio
                if(ratio * workerQuality >= workerWage) {
                    allowedWorkers.push_back(ratio * workerQuality);
                }
            }

            // Skip if not enough workers
            if(allowedWorkers.size() < k) {
                continue;
            }

            // Sort wages and take k smallest
            std::sort(allowedWorkers.begin(), allowedWorkers.end());
            double min_k_wages = 0;
            for(int j = 0; j < k; j++) {
                min_k_wages += allowedWorkers[j];
            }

            minCostToHire = std::min(minCostToHire, min_k_wages);
        }

        return minCostToHire;
    }
};

class Solution {
public:
    // Finds the duplicate number in the array
    int findDuplicate(vector<int>& nums)
    {
        int dup = 0;
        int n = nums.size();
        // Sort the array to bring duplicates together
        sort(nums.begin(), nums.end());
        // Check adjacent elements for duplicates
        for(int i = 0; i < n - 1; ++i)
        {
            if(nums[i] == nums[i + 1])
            {
                dup = nums[i];
            }
        }
        // Return the found duplicate
        return dup;
    }
};

#include <iostream>
#include <vector>
#include <algorithm>
#include <set>
using namespace std;

const int MAXN = 100005;
vector<int> adj[MAXN];
int L[MAXN], R[MAXN];
bool is_leaf[MAXN];
vector<vector<int>> all_bags;
vector<pair<int, int>> tree_edges;

// Computes L[u] and R[u] for each node u
void dfs_LR(int u) {
    if (adj[u].empty()) {
        is_leaf[u] = true;
        L[u] = R[u] = u;
    } else {
        is_leaf[u] = false;
        L[u] = MAXN;
        R[u] = -1;
        for (int v : adj[u]) {
            dfs_LR(v);
            L[u] = min(L[u], L[v]);
            R[u] = max(R[u], R[v]);
        }
    }
}

// Returns pair {first_bag_id, last_bag_id}
pair<int, int> solve(int u, int p) {
    if (is_leaf[u]) {
        vector<int> content;
        content.push_back(u);
        if (p != 0 && p != u) content.push_back(p);

        sort(content.begin(), content.end());
        content.erase(unique(content.begin(), content.end()), content.end());

        all_bags.push_back(content);
        int id = all_bags.size();
        return {id, id};
    }

    int m = adj[u].size();
    bool is_root = (u == 1);
    int extra_node = is_root ? L[u] : -1;

    // Process children
    vector<pair<int, int>> child_res(m);
    for (int i = 0; i < m; ++i) {
        child_res[i] = solve(adj[u][i], u);
    }

    // Create NodeBag_1
    vector<int> nb1_content;
    nb1_content.push_back(u);
    if (p != 0 && p != u) nb1_content.push_back(p);
    nb1_content.push_back(adj[u][0]);
    nb1_content.push_back(L[adj[u][0]]);
    if (extra_node != -1) nb1_content.push_back(extra_node);

    sort(nb1_content.begin(), nb1_content.end());
    nb1_content.erase(unique(nb1_content.begin(), nb1_content.end()), nb1_content.end());
    all_bags.push_back(nb1_content);
    int node_bag_curr = all_bags.size();
    int first_bag_id = node_bag_curr;

    // Connect to f_1
    tree_edges.push_back({node_bag_curr, child_res[0].first});
    int prev_bag = node_bag_curr;

    for (int i = 0; i < m - 1; ++i) {
        // CycleBag_i
        // Connects R(c_i) and L(c_{i+1})
        int r_curr = R[adj[u][i]];
        int l_next = L[adj[u][i+1]];

        vector<int> cb_content;
        cb_content.push_back(u);
        if (p != 0 && p != u) cb_content.push_back(p);
        cb_content.push_back(r_curr);
        cb_content.push_back(l_next);
        if (extra_node != -1) cb_content.push_back(extra_node);

        sort(cb_content.begin(), cb_content.end());
        cb_content.erase(unique(cb_content.begin(), cb_content.end()), cb_content.end());
        all_bags.push_back(cb_content);
        int cycle_bag = all_bags.size();

        // Connect l_i (which is last of child i) to cycle bag
        tree_edges.push_back({child_res[i].second, cycle_bag});
        // Connect prev_bag to cycle bag
        tree_edges.push_back({prev_bag, cycle_bag});

        // NodeBag_{i+1}
        int c_next = adj[u][i+1];

        vector<int> nb_next_content;
        nb_next_content.push_back(u);
        if (p != 0 && p != u) nb_next_content.push_back(p);
        nb_next_content.push_back(c_next);
        nb_next_content.push_back(l_next);
        if (extra_node != -1) nb_next_content.push_back(extra_node);

        sort(nb_next_content.begin(), nb_next_content.end());
        nb_next_content.erase(unique(nb_next_content.begin(), nb_next_content.end()), nb_next_content.end());
        all_bags.push_back(nb_next_content);
        int node_bag_next = all_bags.size();

        // Connect cycle bag to new node bag
        tree_edges.push_back({cycle_bag, node_bag_next});
        // Connect new node bag to f_{i+1}
        tree_edges.push_back({node_bag_next, child_res[i+1].first});

        prev_bag = node_bag_next;
    }

    // TailBag
    int c_last = adj[u].back();
    int r_last = R[c_last];

    vector<int> tb_content;
    tb_content.push_back(u);
    if (p != 0 && p != u) tb_content.push_back(p);
    tb_content.push_back(c_last);
    tb_content.push_back(r_last);
    if (extra_node != -1) tb_content.push_back(extra_node);

    sort(tb_content.begin(), tb_content.end());
    tb_content.erase(unique(tb_content.begin(), tb_content.end()), tb_content.end());
    all_bags.push_back(tb_content);
    int tail_bag = all_bags.size();

    // Connect l_m to tail bag
    tree_edges.push_back({child_res.back().second, tail_bag});
    // Connect prev_bag to tail bag
    tree_edges.push_back({prev_bag, tail_bag});

    return {first_bag_id, tail_bag};
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int N;
    if (!(cin >> N)) return 0;

    for (int i = 0; i < N - 1; ++i) {
        int p;
        cin >> p;
        adj[p].push_back(i + 2);
    }

    dfs_LR(1);

    solve(1, 0);

    cout << all_bags.size() << "\n";
    for (const auto& bag : all_bags) {
        cout << bag.size();
        for (int x : bag) {
            cout << " " << x;
        }
        cout << "\n";
    }

    for (const auto& edge : tree_edges) {
        cout << edge.first << " " << edge.second << "\n";
    }

    return 0;
}

