// Creates a number input control with increment/decrement buttons
export Ui::Child number(f64 value, Ui::Send<f64> onChange, f64 step)
{
    return Ui::hflow(
               Ui::button(
                   [onChange, value, step](auto& n) {
                       onChange(n, value - step);
                   },
                   Ui::ButtonStyle::subtle(),
                   Mdi::MINUS
               ),
               // Display the current value with two decimal places
               Ui::labelMedium("{:.02}", value) | Ui::insets({0, 4}) | Ui::center(),
               Ui::button(
                   [onChange, value, step](auto& n) {
                       onChange(n, value + step);
                   },
                   Ui::ButtonStyle::subtle(),
                   Mdi::PLUS
               )
           ) |
           // Apply styling to the container
           Ui::box({
               .borderRadii = 4,
               .borderWidth = 1,
               .borderFill = Ui::GRAY800,
           }) |
           // Make the component focusable
           Ui::focusable();
}

