  typename vector<vector<double>>::iterator r;
  typename vector<double>::iterator c;
  for (r = matrix.begin(); r != matrix.end(); r++) {
    cout << endl;
    for (c = r->begin(); c != r->end(); c++) {
      *c = (rand() / (RAND_MAX + 1.0));
      cout << *c << '\t';
    }
  }
  cout << endl;

  // Flatten the 2D vector into a 1D vector
  vector<double> flatArray(rows * cols);
  for (int i = 0; i < rows; ++i) {
    for (int j = 0; j < cols; ++j) {
      flatArray[i * cols + j] = matrix[i][j];
    }
  }

  H5File file("output.h5", H5F_ACC_TRUNC);

  // Define dataset dimensions
  hsize_t dims[2];
  dims[0] = rows;
  dims[1] = cols;
  DataSpace space(2, dims);

  DataType type(H5::PredType::NATIVE_DOUBLE);
  DataSet ds = file.createDataSet("dataset", type, space);

  ds.write(flatArray.data(), H5::PredType::NATIVE_DOUBLE);

  cout << endl << " matrix contents: " << endl;
  for (r = matrix.begin(); r != matrix.end(); r++) {
    cout << endl;
    for (c = r->begin(); c != r->end(); c++) {
      cout << *c << '\t';
    }
  }
  cout << endl;

  ds.close();
  space.close();
  file.close();

  return 0;
}

#include <clang-c/Index.h>
#include <graphviz/graphviz.h>

// Recursive function to traverse the AST and build the graph
void walkAST(CXTranslationUnit unit, CXCursor node, Agraph_t* diagram, Agnode_t* ancestor) {
    CXCursorKind type = clang_getCursorKind(node);
    CXString label = clang_getCursorSpelling(node);
    const char* identifier = clang_getCString(label);

    Agnode_t* current = agnode(diagram, identifier, 1);
    if (ancestor) {
        agedge(diagram, ancestor, current, 0, 1);
    }

    clang_disposeString(label);

    if (type == CXCursor_FunctionDecl || type == CXCursor_CXXMethod) {
        CXCursor definition = clang_getCursorDefinition(node);
        while (definition.kind != CXCursor_InvalidFile) {
            walkAST(unit, definition, diagram, current);
            definition = clang_getCursorLexicalParent(definition);
        }
    } else if (type == CXCursor_CompoundStmt) {
        clang_visitChildren(node, [](CXCursor c, CXCursor parent, CXClientData client_data) {
            Agraph_t* diagram = (Agraph_t*)client_data;
            walkAST(clang_Cursor_getTranslationUnit(parent), c, diagram, (Agnode_t*)client_data);
            return CXChildVisit_Continue;
        }, current);
    } else if (type == CXCursor_IfStmt || type == CXCursor_WhileStmt || type == CXCursor_ForStmt) {
        clang_visitChildren(node, [](CXCursor c, CXCursor parent, CXClientData client_data) {
            Agraph_t* diagram = (Agraph_t*)client_data;
            walkAST(clang_Cursor_getTranslationUnit(parent), c, diagram, (Agnode_t*)client_data);
            return CXChildVisit_Continue;
        }, current);
    }
}

int main() {
    const char* sourceCode = R"code(
        int factorial(int n) {
            if (n == 0) {
                return 1;
            } else {
                return n * factorial(n - 1);
            }
        }

        int main() {
            int value = 5;
            int output = factorial(value);
            std::cout << "Factorial of " << value << " is " << output << std::endl;
            return 0;
        }
    )code";

    CXIndex engine = clang_createIndex(0, 0);
    CXTranslationUnit ast = clang_parseTranslationUnit(engine, 0, 0, 0, 0, 0, CXTranslationUnit_None);

    CXUnsavedFile buffer = { "example.cpp", sourceCode, strlen(sourceCode) };
    clang_reparseTranslationUnit(ast, 1, &buffer, CXReparse_None);

    CXCursor root = clang_getTranslationUnitCursor(ast);
    Agraph_t* diagram = agopen("Control Flow Graph", Agdirected, 0);
    walkAST(ast, root, diagram, 0);

    agwrite(diagram, stdout);
    agclose(diagram);
    clang_disposeTranslationUnit(ast);
    clang_disposeIndex(engine);

    return 0;
}

