struct Lexeme {
    std::string category; // "LABEL", "OPCODE", "REG", "CONSTANT", "REF_LABEL"
    std::string text;
};

std::vector<Lexeme> lex(const std::string& input) {
    std::vector<Lexeme> lexemes;
    std::regex pattern(R"((\w+):|(\w+)|(\$?\w+)|(-?\d+))");
    std::smatch result;

    std::string::const_iterator cursor(input.cbegin());
    while (std::regex_search(cursor, input.cend(), result, pattern)) {
        if (result[1].matched) {
            lexemes.emplace_back("LABEL", result[1]);
        } else if (result[2].matched) {
            lexemes.emplace_back("OPCODE", result[2]);
        } else if (result[3].matched) {
            lexemes.emplace_back("REG", result[3]);
        } else if (result[4].matched) {
            lexemes.emplace_back("CONSTANT", result[4]);
        }
        cursor = result.suffix().first;
    }

    return lexemes;
}

