// Extract words from the input text using regex
std::vector<std::string> extractTokens(const std::string& input) {
    std::regex token_pattern("\\b\\w+\\b");
    auto start_iter = std::sregex_iterator(input.begin(), input.end(), token_pattern);
    auto end_iter = std::sregex_iterator();
    std::vector<std::string> tokens;
    for (std::sregex_iterator iter = start_iter; iter != end_iter; ++iter) {
        tokens.push_back((*iter).str());
    }
    return tokens;
}

// Build adjacency list where an edge exists if last char of word matches first char of another
std::unordered_map<std::string, std::vector<std::string>> constructAdjacencyList(const std::vector<std::string>& tokens) {
    std::unordered_map<std::string, std::vector<std::string>> adj_list;
    for (const auto& current_token : tokens) {
        for (const auto& candidate_token : tokens) {
            if (!current_token.empty() && !candidate_token.empty() &&
                current_token.back() == candidate_token.front()) {
                adj_list[current_token].push_back(candidate_token);
            }
        }
    }
    return adj_list;
}

// Find the longest chain of words where each consecutive pair satisfies the ending-starting character rule
std::vector<std::string> findLongestSequence(const std::string& input_text) {
    std::vector<std::string> tokens = extractTokens(input_text);
    std::unordered_map<std::string, std::vector<std::string>> adjacency = constructAdjacencyList(tokens);
    std::unordered_set<std::string> visited_nodes;
    std::vector<std::string> best_sequence;

    // Depth-first search to explore all possible chains
    std::function<void(const std::string&, std::vector<std::string>&)> traverse = 
        [&](const std::string& node, std::vector<std::string>& current_path) {
            if (visited_nodes.find(node) != visited_nodes.end()) return;

            visited_nodes.insert(node);
            current_path.push_back(node);

            // Explore neighbors
            if (adjacency.find(node) != adjacency.end()) {
                for (const auto& neighbor : adjacency[node]) {
                    traverse(neighbor, current_path);
                }
            }

            // Update best sequence if current is longer
            if (current_path.size() > best_sequence.size()) {
                best_sequence = current_path;
            }

            // Backtrack
            current_path.pop_back();
            visited_nodes.erase(node);
        };

    // Start DFS from each token
    for (const auto& token : tokens) {
        std::vector<std::string> path;
        traverse(token, path);
    }

    return best_sequence;
}

int main() {
    std::string sample_text = "I love Python and Java and Rust and Ruby.";
    std::vector<std::string> chain = findLongestSequence(sample_text);
    for (const auto& word : chain) {
        std::cout << word << " ";
    }
    std::cout << std::endl;
    return 0;
}

