#include <atomic>

using U64 = unsigned long long;

struct SlotData {
    U64 mElements[16] = {};
};

struct SlotManager {
    U64 lock() noexcept {
        while (true) {
            U64 currentMap = mData.load(std::memory_order_relaxed);

            U64 slotIndex = (currentMap & 1) ? 1 : 0;
            auto selectionMask = U64(1) << slotIndex;

            auto priorState =
                mData.fetch_or(selectionMask, std::memory_order_relaxed);
            if ((priorState & selectionMask) == 0) {
                return slotIndex;
            }
        }
    }

    __attribute__((noinline)) SlotData getSlot() noexcept {
        lock();
        return SlotData();
    }

    std::atomic<U64> mData{ 1 };
};

int main() {
    SlotManager manager;
    manager.getSlot();
    return 0;
}

