// Compute quantile values for given percentiles using GK algorithm
std::vector<double> CalculatePercentiles(const std::vector<double>& input_data, const std::vector<double>& percentile_values, double tolerance)
{
    greenwald_khanna<double> gk(tolerance);
    for (double element : input_data)
    {
        gk.insert(element);
    }
    std::vector<double> output;
    for (double p : percentile_values)
    {
        output.push_back(gk.quantile(p));
    }
