// System call wrapper function using software interrupt
template <typename ResultType, typename... Parameters>
ResultType make_syscall(uint32_t sys_id, Parameters... params) {
    uint32_t param0 = (uint32_t)(params)[0];
    uint32_t param1 = (uint32_t)(params)[1];
    uint32_t param2 = (uint32_t)(params)[2];
    uint32_t param3 = (uint32_t)(params)[3];

    ResultType output;
    asm volatile(
        "swi 0"
        : "=r"(output)
        : "r"(sys_id), "r"(param0), "r"(param1), "r"(param2), "r"(param3)
        : "r0", "r1", "r2", "r3", "memory"
    );
    return output;
}

