// Returns special constant for accumulator addressing mode
uint16_t get_ACC_address() { return 0xFFFF; }

// Fetches next byte from instruction stream for immediate addressing
uint16_t get_IMM_address() { return read_next_byte(); }

// Reads next two bytes as word for absolute addressing
uint16_t get_ABS_address() { return read_next_word(); }

// Zero page addressing: only lower 8 bits matter
uint16_t get_ZER_address() { return read_next_byte() & 0xFF; }

// Zero page X-indexed addressing
uint16_t get_ZEX_address() { return (read_next_byte() + reg_X) & 0xFF; }

// Zero page Y-indexed addressing  
uint16_t get_ZEY_address() { return (read_next_byte() + reg_Y) & 0xFF; }

// Absolute X-indexed addressing with 16-bit wrap
uint16_t get_ABX_address() { return (read_next_word() + reg_X) & 0xFFFF; }

// Absolute Y-indexed addressing with 16-bit wrap
uint16_t get_ABY_address() { return (read_next_word() + reg_Y) & 0xFFFF; }

// Implied addressing - no operand required
uint16_t get_IMP_address() { return 0x0000; }

// Relative branching: sign-extended byte added to program counter
uint16_t get_REL_address() { return (int8_t)read_next_byte() + reg_PC; }

// Indirect X addressing: (zero_page + X) points to 16-bit address
uint16_t get_INX_address() { 
    uint8_t base = read_next_byte() + reg_X;
    return (uint16_t)(*(uint8_t*)(0x0000 | base)) & 0xFF; 
}

// Indirect Y addressing: zero_page points to 16-bit address, then add Y
uint16_t get_INY_address() { 
    uint8_t base = read_next_byte();
    return ((uint16_t)(*(uint8_t*)(0x0000 | base))) + reg_Y; 
}

// Absolute indirect addressing: fetch word, use as pointer to another word
uint16_t get_ABI_address() { 
    return (uint16_t)(*(uint16_t*)(0x0000 | read_next_word())); 
}

