class ModifiedCheck : public clang::tidy::ClangTidyCheck {
public:
  ModifiedCheck(StringRef CheckName, ClangTidyContext *Ctx)
      : ClangTidyCheck(CheckName, Ctx) {}

  void registerMatchers(ast_matchers::MatchFinder *Matcher) override {
    Matcher->addMatcher(callExpr(callee(functionDecl(hasName("legacy_func")))).bind("target_call"), this);
  }

  void check(const MatchFinder::MatchResult &MatchResult) override {
    const auto *CallExpr = MatchResult.Nodes.getNodeAs<CallExpr>("target_call");
