// Function to retrieve keyboard scan code using interrupt
int getkeys() {
    union REGS input_regs, output_regs;

    // Wait until a key is pressed
    while (!kbhit());

    // Set AH register to 0 for keyboard input function
    input_regs.h.ah = 0;

    // Call interrupt 22h (keyboard interrupt)
    int86(0x22, &input_regs, &output_regs);

    // Return the scan code from AH register
    return output_regs.h.ah;
}

#include <iostream>
#include <stack>
#include <sstream>
#include <vector>
#include <cctype>

using namespace std;

bool isOperator(char c) {
    return c == '+' || c == '-' || c == '*' || c == '/';
}

int applyOperator(int operand1, int operand2, char operation) {
    switch (operation) {
        case '+': return operand1 + operand2;
        case '-': return operand1 - operand2;
        case '*': return operand1 * operand2;
        case '/': 
            if (operand2 == 0) {
                cout << "Error: Division by zero" << endl;
                exit(1);
            }
            return operand1 / operand2;
        default: 
            cout << "Error: Unknown operator" << endl;
            exit(1);
    }
}

int evaluatePostfixExpression(const string& expr) {
    stack<int> values;
    stringstream ss(expr);
    string currentToken;

    while (ss >> currentToken) {
        if (isOperator(currentToken[0]) && currentToken.length() == 1) {
            if (values.size() < 2) {
                cout << "Error: Invalid expression" << endl;
                exit(1);
            }
            int secondOperand = values.top(); values.pop();
            int firstOperand = values.top(); values.pop();
            int computedValue = applyOperator(firstOperand, secondOperand, currentToken[0]);
            values.push(computedValue);
        } else {
            try {
                int numericValue = stoi(currentToken);
                values.push(numericValue);
            } catch (const invalid_argument& e) {
                cout << "Error: Invalid operand" << endl;
                exit(1);
            }
        }
    }

    if (values.size() != 1) {
        cout << "Error: Invalid expression" << endl;
        exit(1);
    }

    return values.top();
}

int main() {
    string inputExpression;
    cout << "Enter a postfix expression: ";
    getline(cin, inputExpression);

    int finalResult = evaluatePostfixExpression(inputExpression);
    cout << "The result is: " << finalResult << endl;

    return 0;
}

