        "add.u32 base_ptr2, base_ptr2, byte_off;\n"
        "ld.global.f32 %0, [base_ptr];\n"
        "st.global.f32 [base_ptr2], %0;\n"
        : "=f"(dest[row * pitch + col])
        : "r"(row * pitch + col), "r"(4), "r"(src), "r"(dest)
        : "addr_src", "byte_off", "base_ptr", "base_ptr2"
    );
}

#include <condition_variable>
#include <mutex>

class CountdownEvent {
public:
    explicit CountdownEvent(size_t initial_count) : _remaining(initial_count) {}

    void await() {
        std::unique_lock<std::mutex> guard(_lock);
        _cv.wait(guard, [this] { return _remaining == 0; });
    }

    void decrement() {
        std::unique_lock<std::mutex> guard(_lock);
        if (_remaining > 0) {
            --_remaining;
            if (_remaining == 0) {
                _cv.notify_all();
            }
        }
    }

private:
    size_t _remaining;
    std::mutex _lock;
    std::condition_variable _cv;
};

