// Generate a list of prime numbers within the specified range [start, end]
std::vector<int> generate_prime_numbers(int lower_bound, int upper_bound) {
    if (lower_bound > upper_bound) throw std::invalid_argument("Lower bound must be less than or equal to upper bound.");
    std::vector<int> prime_list;
    for (int number = std::max(2, lower_bound); number <= upper_bound; ++number) {
        bool prime_flag = true;
        for (int check_divisor = 2; check_divisor <= static_cast<int>(std::sqrt(number)); ++check_divisor) {
            if (number % check_divisor == 0) {
                prime_flag = false;
                break;
            }
        }
        if (prime_flag) prime_list.push_back(number);
    }
    return prime_list;
}

