// Convert a numpy uint8 array element to unsigned char
unsigned char transform_numpy_uint8(PyObject* input) {
    if (PyArray_Check(input)) {
        PyArrayObject* np_array = reinterpret_cast<PyArrayObject*>(input);
        if (PyArray_TYPE(np_array) == NPY_UINT8) {
            return *reinterpret_cast<unsigned char*>(PyArray_DATA(np_array));
