// Compute the Euclidean norm of a vector
double magnitude(const std::vector<double>& vec) {
    double accumulator = 0.0;
    for (size_t index = 0; index < vec.size(); ++index) {
        accumulator += vec[index] * vec[index];
    }
    // Guard against potential floating-point errors
    if (accumulator < 0.0) {
        // In theory impossible, but included for robustness
        accumulator = 0.0;
    }
    return std::sqrt(accumulator);
}

