// Find the longest common substring between two strings
std::string findLongestCommonSubstr(const std::string& str1, const std::string& str2) {
    int len1 = str1.length();
    int len2 = str2.length();

    // Create DP table initialized with zeros
    std::vector<std::vector<int>> table(len1 + 1, std::vector<int>(len2 + 1, 0));

    // Track maximum length and ending index in first string
    int maxLen = 0;
    int endPos = -1;

    // Fill the DP table
    for (int i = 1; i <= len1; ++i) {
        for (int j = 1; j <= len2; ++j) {
            if (str1[i - 1] == str2[j - 1]) {
                table[i][j] = table[i - 1][j - 1] + 1;
                if (table[i][j] > maxLen) {
                    maxLen = table[i][j];
                    endPos = i - 1;
                }
            } else {
                table[i][j] = 0;
            }
        }
    }

    // Return empty string if no common substring found
    if (maxLen == 0) {
        return "";
    }

    // Extract and return the longest common substring
    return str1.substr(endPos - maxLen + 1, maxLen);
}

int main() {
    std::string input1 = "abcde";
    std::string input2 = "abfcd";

    std::string output = findLongestCommonSubstr(input1, input2);
    std::cout << "Longest Common Substring: " << output << std::endl;

    return 0;
}

