// Template function for conditional vector addition
template<bool Condition>
void vector_add_op()
{
    float output[4] = {2.0, 2.0, 2.0, 2.0};
    float input[4] = {0.5, 1.5, 2.5, 3.5};
    float * out_ptr = output;
    float * in_ptr = input;

    asm volatile (
        "vld1.32    {q2}, [%[input]]  \n"
        "vld1.32    {q3}, [%[output]] \n"
        "vadd.f32   q2, q2, q3        \n"
        "vadd.f32   q2, q2, q3        \n"

        // Branch based on condition flag
        "start_label: \n"
        "cmp %[cond], #1 \n"
        "beq process_extra \n"
        "b end_label \n"
        "process_extra: \n"
        "vadd.f32   q2, q2, q3        \n"
        "end_label: \n"

        "vst1.32    {q2}, [%[output]] \n"
        : [input]"+r"(in_ptr),
          [output]"+r"(out_ptr)
        : [cond]"r"(Condition)
        : "q2", "q3", "q4", "q5", "memory"
    );

    for (int idx = 0; idx < 4; idx++)
    {
        std::cout << output[idx] << ", ";
    }
    std::cout << std::endl;
}

