// Attempt to claim a free slot using atomic bit operations
std::uint64_t acquire() noexcept {
    while (true) {
        std::uint64_t currentMap = dataStore;

        std::uint64_t bitPosition = (currentMap & 1) ? 1 : 0;
        auto bitMask = std::uint64_t(1) << bitPosition;

        auto priorValue =
            __atomic_fetch_or(&dataStore, bitMask, __ATOMIC_SEQ_CST);
        if ((priorValue & bitMask) == 0) {
            return bitPosition;
        }
    }
}

#include <cuda_runtime.h>
#include <iostream>
#include <vector>
#include <chrono>

#define THREADS_PER_BLOCK 256

__global__ void columnSumKernel(const float* __restrict__ d_data, float* __restrict__ d_partialSums, int rows, int cols) {
    __shared__ float temp[THREADS_PER_BLOCK];
    int col = blockIdx.x;
    int idx = threadIdx.x;
    int first = col + idx * cols;
    int step = THREADS_PER_BLOCK;

    float accum = 0.0f;
    for (int i = first; i < rows * cols; i += step) {
        accum += d_data[i];
    }

    temp[idx] = accum;
    __syncthreads();

    for (int half = THREADS_PER_BLOCK / 2; half > 0; half >>= 1) {
        if (idx < half) {
            temp[idx] += temp[idx + half];
        }
        __syncthreads();
    }

    if (idx == 0) {
        d_partialSums[col] = temp[0];
    }
}

void computeColumnSumsCUDA(const float* h_data, float* h_results, int rowCount, int colCount) {
    float* d_deviceData;
    float* d_deviceResults;
    size_t totalSize = rowCount * colCount * sizeof(float);
    size_t partialSize = colCount * sizeof(float);

    cudaMalloc((void**)&d_deviceData, totalSize);
    cudaMalloc((void**)&d_deviceResults, partialSize);

    cudaMemcpy(d_deviceData, h_data, totalSize, cudaMemcpyHostToDevice);

    dim3 threads(THREADS_PER_BLOCK);
    dim3 blocks((colCount + threads.x - 1) / threads.x);

    columnSumKernel<<<blocks, threads>>>(d_deviceData, d_deviceResults, rowCount, colCount);

    cudaMemcpy(h_results, d_deviceResults, partialSize, cudaMemcpyDeviceToHost);

    cudaFree(d_deviceData);
    cudaFree(d_deviceResults);
}

int main() {
    int rows = 90000;
    int cols = 1000;
    std::vector<float> inputMatrix(rows * cols, 1.0f);
    std::vector<float> outputSums(cols, 0.0f);

    auto beginTime = std::chrono::high_resolution_clock::now();
    computeColumnSumsCUDA(inputMatrix.data(), outputSums.data(), rows, cols);
    auto endTime = std::chrono::high_resolution_clock::now();

    std::chrono::duration<double> elapsed = endTime - beginTime;
    std::cout << "CUDA Execution Time: " << elapsed.count() * 1000 << " ms" << std::endl;

    return 0;
}

