class Learner {
public:
    std::string fullName;
    int years;
    std::string program;
    char mark;
    double average;

    Learner(const std::string& fullName, int years, const std::string& program, char mark, double average)
        : fullName(fullName), years(years), program(program), mark(mark), average(average) {
        check();
    }

    void modify(int years, const std::string& program, char mark, double average) {
        this->years = years;
        this->program = program;
        this->mark = mark;
        this->average = average;
        check();
    }

private:
    void check() {
        if (fullName.length() < 2 || fullName.length() > 50) {
            throw std::invalid_argument("Full name length must be between 2 and 50 characters.");
        }
        if (years < 18 || years > 35) {
            throw std::invalid_argument("Years must be between 18 and 35.");
        }
        if (program.length() < 5 || program.length() > 100) {
            throw std::invalid_argument("Program length must be between 5 and 100 characters.");
        }
        if (mark != 'A' && mark != 'B' && mark != 'C' && mark != 'D' && mark != 'F') {
            throw std::invalid_argument("Mark must be one of 'A', 'B', 'C', 'D', or 'F'.");
        }
        if (average < 0.0 || average > 4.0) {
            throw std::invalid_argument("Average must be between 0.0 and 4.0.");
        }
    }
};

class LearnerRegistry {
private:
    std::map<std::string, Learner> registry;

public:
    void registerLearner(const std::string& fullName, int years, const std::string& program, char mark, double average) {
        if (registry.find(fullName) != registry.end()) {
            throw std::runtime_error("Learner with this name already exists.");
        }
        registry[fullName] = Learner(fullName, years, program, mark, average);
    }

    void updateLearner(const std::string& fullName, int years, const std::string& program, char mark, double average) {
        auto it = registry.find(fullName);
        if (it == registry.end()) {
            throw std::runtime_error("Learner not found.");
        }
        it->second.modify(years, program, mark, average);
    }

    Learner getLearner(const std::string& fullName) const {
        auto it = registry.find(fullName);
        if (it == registry.end()) {
            throw std::runtime_error("Learner not found.");
        }
        return it->second;
    }
};

int main() {
    LearnerRegistry system;

    try {
        system.registerLearner("Eve", 22, "Engineering", 'A', 3.7);
        system.registerLearner("Frank", 19, "Literature", 'B', 3.4);
        system.registerLearner("Grace", 20, "History", 'C', 2.9);

        system.updateLearner("Eve", 23, "Engineering", 'A', 3.6);

        Learner eve = system.getLearner("Eve");
        std::cout << "Name: " << eve.fullName << ", Age: " << eve.years << ", Program: " << eve.program
                  << ", Mark: " << eve.mark << ", Average: " << eve.average << std::endl;

    } catch (const std::exception& e) {
        std::cerr << "Issue: " << e.what() << std::endl;
    }

    return 0;
}

