#include <iostream>
using namespace std;

// Tic-Tac-Toe game board representation
char grid[3][3] = { {'1', '2', '3'}, {'4', '5', '6'}, {'7', '8', '9'} };
char currentPlayer;
int selectedRow, selectedCol;

// Function to render the current state of the board
void printBoard() {
    cout << " " << grid[0][0] << " | " << grid[0][1] << " | " << grid[0][2] << endl;
    cout << "-----------" << endl;
    cout << " " << grid[1][0] << " | " << grid[1][1] << " | " << grid[1][2] << endl;
    cout << "-----------" << endl;
    cout << " " << grid[2][0] << " | " << grid[2][1] << " | " << grid[2][2] << endl;
}

// Function to handle a player's turn
void takeTurn() {
    int position;
    cout << "Player " << currentPlayer << ", enter your move (1-9): ";
    cin >> position;
    position--; // Convert to 0-based index

    selectedRow = position / 3;
    selectedCol = position % 3;

    if (grid[selectedRow][selectedCol] != 'X' && grid[selectedRow][selectedCol] != 'O') {
        grid[selectedRow][selectedCol] = currentPlayer;
    } else {
        cout << "Invalid move! Try again." << endl;
        takeTurn();
    }
}

// Function to determine if there is a winning condition
bool hasWinner() {
    // Check rows for win
    for (int idx = 0; idx < 3; idx++) {
        if (grid[idx][0] == grid[idx][1] && grid[idx][1] == grid[idx][2])
            return true;
    }

    // Check columns for win
    for (int idx = 0; idx < 3; idx++) {
        if (grid[0][idx] == grid[1][idx] && grid[1][idx] == grid[2][idx])
            return true;
    }

    // Check diagonals for win
    if (grid[0][0] == grid[1][1] && grid[1][1] == grid[2][2])
        return true;

    if (grid[0][2] == grid[1][1] && grid[1][1] == grid[2][0])
        return true;

    return false;
}

// Function to check if the game ended in a tie
bool isTieGame() {
    for (int i = 0; i < 3; i++) {
        for (int j = 0; j < 3; j++) {
            if (grid[i][j] != 'X' && grid[i][j] != 'O')
                return false;
        }
    }
    return true;
}

// Main entry point for the game
int main() {
    char continuePlaying = 'Y';
    while (continuePlaying == 'Y' || continuePlaying == 'y') {
        for (int turnCount = 0; turnCount < 9; turnCount++) {
            printBoard();

            // Alternate between players
            if (turnCount % 2 == 0) {
                currentPlayer = 'X';
            } else {
                currentPlayer = 'O';
            }

            takeTurn();

            // Check for win or draw after each move
            if (hasWinner()) {
                printBoard();
                cout << "Player " << currentPlayer << " wins!" << endl;
                break;
            } else if (isTieGame()) {
                printBoard();
                cout << "It's a draw!" << endl;
                break;
            }
        }

        cout << "Do you want to play again? (Y/N): ";
        cin >> continuePlaying;

        // Reset the board if playing again
        if (continuePlaying == 'Y' || continuePlaying == 'y') {
            for (int rowIdx = 0; rowIdx < 3; rowIdx++) {
                for (int colIdx = 0; colIdx < 3; colIdx++) {
