#define MAX_BUFFER 128  // Adjust the buffer size as per your requirements

byte dataArray[MAX_BUFFER];
unsigned int writeIndex = 0;
unsigned int readIndex = 0;

void insertIntoQueue(byte value) {
  writeIndex = (writeIndex + 1) % MAX_BUFFER;  // Wrap around if buffer is full
  dataArray[writeIndex] = value;
  if (writeIndex == readIndex) {
    readIndex = (readIndex + 1) % MAX_BUFFER;  // Remove oldest data when buffer is full
  }
}

byte removeFromQueue() {
  if (readIndex != writeIndex) {
    readIndex = (readIndex + 1) % MAX_BUFFER;
    return dataArray[readIndex];
  } else {
    return 0;  // Return a default value if buffer is empty
  }
}

