#include <iostream>
#include <list>

class MinMaxContainer {
private:
    std::list<int> data;
    std::list<int>::iterator minPos, maxPos;

public:
    MinMaxContainer() : minPos(data.end()), maxPos(data.end()) {}

    void addElement(int val) {
        data.push_back(val);
        auto pos = --data.end();
        if (minPos == data.end() || *pos < *minPos) minPos = pos;
        if (maxPos == data.end() || *pos > *maxPos) maxPos = pos;
    }

    void deleteElement(int val) {
        auto pos = std::find(data.begin(), data.end(), val);
        if (pos != data.end()) {
            if (pos == minPos) {
                if (pos != data.begin()) minPos = std::prev(pos);
                else minPos = data.end();
            }
            if (pos == maxPos) {
                if (pos != --data.end()) maxPos = std::next(pos);
                else maxPos = data.end();
            }
            data.erase(pos);
        }
    }

    int findMinimum() const {
        return minPos != data.end() ? *minPos : -1;
    }

    int findMaximum() const {
        return maxPos != data.end() ? *maxPos : -1;
    }
};

int main() {
    MinMaxContainer container;
    container.addElement(5);
    container.addElement(3);
    container.addElement(7);
    std::cout << "Min: " << container.findMinimum() << std::endl; // 3
    std::cout << "Max: " << container.findMaximum() << std::endl; // 7
    container.deleteElement(3);
    std::cout << "Min: " << container.findMinimum() << std::endl; // 5
    return 0;
}

