// Verify that all required validation layers are available
bool AreValidationLayersSupported() {
    uint32_t layerPropertyCount;
    vkEnumerateInstanceLayerProperties(&layerPropertyCount, nullptr);

    std::vector<VkLayerProperties> supportedLayers(layerPropertyCount);
    vkEnumerateInstanceLayerProperties(&layerPropertyCount, supportedLayers.data());

    for (const char* requestedLayer : debugValidationLayers) {
        bool isLayerPresent = false;

        for (const auto& layerInfo : supportedLayers) {
            if (std::strcmp(requestedLayer, layerInfo.layerName) == 0) {
                isLayerPresent = true;
                break;
            }
        }

        if (!isLayerPresent) {
            return false;
        }
    }

    return true;
}

// Update Vulkan instance creation to include validation layers when appropriate
void Renderer::CreateInstance() {
    if (useDebugLayers && !AreValidationLayersSupported()) {
        throw std::runtime_error("Requested validation layers are not supported.");
    }

    // ...
    instanceCreateInfo.enabledLayerCount = useDebugLayers ? static_cast<uint32_t>(debugValidationLayers.size()) : 0u;
    instanceCreateInfo.ppEnabledLayerNames = useDebugLayers ? debugValidationLayers.data() : nullptr;
    // ...
}

