JNIEXPORT jint JNICALL 
Java_com_sfarbac_rtmatching_nativeClass_loadAndDecodeImage
(JNIEnv *env, jobject obj, jlong inputMatPtr, jlong outputMatPtr, jstring assetPath) {

    Mat& srcImage = *(Mat*)inputMatPtr;
    Mat& destImage = *(Mat*)outputMatPtr;

    const jsize pathLength = env->GetStringUTFLength(assetPath);
    const char* cStr = env->GetStringUTFChars(assetPath, (jboolean *)0);
    std::string assetName(cStr, pathLength);

    // Retrieve the AssetManager from the Java context
    jobject appContext = env->GetActivity();
    jobject assetMgrObj = appContext->assetManager;
    AAssetManager* assetMgr = AAssetManager_fromJava(env, assetMgrObj);

    // Attempt to open the specified asset
    AAsset* assetFile = AAssetManager_open(assetMgr, assetName.c_str(), AASSET_MODE_STREAMING);
    if (assetFile == nullptr) {
        __android_log_print(ANDROID_LOG_ERROR, "IMAGE_LOADER", "Failed to open asset: %s", assetName.c_str());
        env->ReleaseStringUTFChars(assetPath, cStr);
        return -1;
    }

    // Determine the size of the asset
    off_t fileSize = AAsset_getLength(assetFile);

    // Allocate memory and read asset contents
    char* dataBuffer = new char[fileSize];
    AAsset_read(assetFile, dataBuffer, fileSize);
    AAsset_close(assetFile);

    // Convert raw bytes into OpenCV matrix
    Mat tempData(1, fileSize, CV_8UC1, dataBuffer);
    Mat decodedImg = imdecode(tempData, IMREAD_GRAYSCALE);

    // Free allocated resources
    delete[] dataBuffer;

    if (decodedImg.empty()) {
        __android_log_print(ANDROID_LOG_ERROR, "IMAGE_LOADER", "Image decoding failed");
        env->ReleaseStringUTFChars(assetPath, cStr);
        return -1;
    }

    destImage = decodedImg;

    env->ReleaseStringUTFChars(assetPath, cStr);

    return 1;
}

