// Compute the product of two quaternions
std::vector<double> quaternionProduct(const std::vector<double>& a, const std::vector<double>& b) {
    double wa = a[0];
    double xa = a[1];
    double ya = a[2];
    double za = a[3];

    double wb = b[0];
    double xb = b[1];
    double yb = b[2];
    double zb = b[3];

    double w = wa * wb - xa * xb - ya * yb - za * zb;
    double x = wa * xb + xa * wb + ya * zb - za * yb;
    double y = wa * yb - xa * zb + ya * wb + za * xb;
    double z = wa * zb + xa * yb - ya * xb + za * wb;

    return {w, x, y, z};
}

int main() {
    std::vector<double> qA = {0.98, 0.08, 0.17, -0.01};
    std::vector<double> qB = {0.70, 0.70, 0.0, 0.0};

    std::vector<double> output = quaternionProduct(qA, qB);

    for (double component : output) {
        std::cout << component << " ";
    }
    std::cout << std::endl;

    return 0;
}

#include <type_traits>

// System call wrapper using ARM SVC instruction
template <int sys_num, typename RETURN_TYPE, typename ARG1, typename ARG2, typename ARG3, typename ARG4>
inline RETURN_TYPE make_syscall(ARG1 arg1, ARG2 arg2, ARG3 arg3, ARG4 arg4)
{
  register ARG1 reg0 asm("r0") = arg1;
  register ARG2 reg1 asm("r1") = arg2;
  register ARG3 reg2 asm("r2") = arg3;
  register ARG4 reg3 asm("r3") = arg4;

  asm volatile("svc %[system_call_number]\n"
    : "=r" (reg0)
    : [system_call_number] "i" (sys_num), "0" (reg0), "r" (reg1), "r" (reg2), "r" (reg3)
    : "memory", "r12", "lr");

  return static_cast<RETURN_TYPE>(reg0);
}

