#include <string>

// Check whether the given integer vector is in ascending order
std::string checkAscendingOrder(const std::vector<int>& data) {
    for (size_t idx = 1; idx < data.size(); ++idx) {
        if (data[idx - 1] > data[idx]) {
            return std::string();
        }
    }
    return "Vector is already in ascending order";
}

// Perform bubble sort on the input vector
std::vector<int> performBubbleSort(std::vector<int>& data) {
    bool hasSwapOccurred;
    int sizeVal = data.size();
    for (int idx = 0; idx < sizeVal - 1; ++idx) {
        hasSwapOccurred = false;
        for (int pos = 0; pos < sizeVal - idx - 1; ++pos) {
            if (data[pos] > data[pos + 1]) {
                std::swap(data[pos], data[pos + 1]);
                hasSwapOccurred = true;
            }
        }
        // Terminate early if no swaps occurred in this pass
        if (!hasSwapOccurred) {
            break;
        }
    }
    return data;
}

int main() {
    std::vector<int> data = {4, 2, 1, 7, 10};
    std::string checkResult = checkAscendingOrder(data);

    if (!checkResult.empty()) {
        std::cout << checkResult << std::endl;
    } else {
        std::vector<int> sortedData = performBubbleSort(data);
        std::cout << "Sorted vector: ";
        for (int value : sortedData) {
            std::cout << value << " ";
        }
        std::cout << std::endl;
    }

    return 0;
}

