namespace tensorflow {

class PrivacyPreservingComputationOp : public OpKernel {
 public:
  explicit PrivacyPreservingComputationOp(OpKernelConstruction* context)
      : OpKernel(context) {
    OP_REQUIRES_OK(context, context->GetAttr("party", &party_));
    OP_REQUIRES_OK(context, context->GetAttr("privacy_budget", &privacy_budget_));
  }

  void Compute(OpKernelContext* context) override {
    // Get the input tensor
    const Tensor& input_tensor = context->input(0);

    // Prepare output tensor with same shape as input
    TensorShape result_shape(input_tensor.shape());
    Tensor* result_tensor = nullptr;
    OP_REQUIRES_OK(context, context->allocate_output(0, result_shape, &result_tensor));

    if (party_ == "participant_a") {
      // For participant_a, simply forward the input
      *result_tensor = input_tensor;
    } else if (party_ == "participant_b") {
      // For participant_b, add calibrated noise for differential privacy
      float scale_param = 1.0 / privacy_budget_;
      InjectNoise(context, input_tensor, result_tensor, scale_param);
    } else {
      OP_REQUIRES(context, false, errors::InvalidArgument("Unknown party identifier: ", party_));
    }
  }

 private:
  void InjectNoise(OpKernelContext* context, const Tensor& input_tensor,
                   Tensor* result_tensor, float scale_param) {
    auto input_flat = input_tensor.flat<float>();
    auto result_flat = result_tensor->flat<float>();

    // Set up random number generation for Gaussian noise
    std::random_device rng;
    std::normal_distribution<float> gaussian(0.0, scale_param);

    for (int idx = 0; idx < input_flat.size(); ++idx) {
      float perturbation = gaussian(rng);
      result_flat(idx) = input_flat(idx) + perturbation;
    }
  }

  string party_;
  float privacy_budget_;
};

REGISTER_KERNEL_BUILDER(Name("PrivacyPreservingComputation").Device(DEVICE_CPU), PrivacyPreservingComputationOp);

