__global__ void customKernel(cudaTextureObject_t textureObj, float* resultBuffer, int imgWidth, int imgHeight, float defaultValue) {
    int pixelX = blockIdx.x * blockDim.x + threadIdx.x;
    int pixelY = blockIdx.y * blockDim.y + threadIdx.y;

    if (pixelX < imgWidth && pixelY < imgHeight) {
        float2 position = make_float2(pixelX, pixelY);
        float sampleValue = tex2D<float>(textureObj, position.x, position.y);

        // Validate texture coordinates are within valid range
