#include <iostream>
#include <vector>
#include <unordered_set>

// Define a literal
using Literal = int;
using Clause = std::vector<Literal>;
using Formula = std::vector<Clause>;

// Define a SAT solver
class SATSolver {
public:
    SATSolver(const Formula& inputFormula) : formula(inputFormula), numVariables(0) {
        for (const auto& clause : formula) {
            for (Literal literal : clause) {
                numVariables = std::max(numVariables, std::abs(literal));
            }
        }
        variableAssignment.resize(numVariables + 1, 0); // 0 means unassigned, 1 means true, -1 means false
    }

    bool solve() {
        return solve_recursive(1);
    }

    void print_solution() const {
        for (int i = 1; i <= numVariables; ++i) {
            if (variableAssignment[i] == 1) {
                std::cout << "x" << i << " = true ";
            } else if (variableAssignment[i] == -1) {
                std::cout << "x" << i << " = false ";
            }
        }
        std::cout << std::endl;
    }

private:
    Formula formula;
    int numVariables;
    std::vector<int> variableAssignment;

    bool solve_recursive(int currentVariable) {
        if (currentVariable > numVariables) {
            return is_satisfied();
        }

        // Try assigning true
        variableAssignment[currentVariable] = 1;
        if (solve_recursive(currentVariable + 1)) {
            return true;
        }

        // Try assigning false
        variableAssignment[currentVariable] = -1;
        if (solve_recursive(currentVariable + 1)) {
            return true;
        }

        // Backtrack
        variableAssignment[currentVariable] = 0;
        return false;
    }

    bool is_satisfied() const {
        for (const auto& clause : formula) {
            bool clause_satisfied = false;
            for (Literal literal : clause) {
                if (literal > 0) {
                    if (variableAssignment[literal] == 1) {
                        clause_satisfied = true;
                        break;
                    }
                } else {
                    if (variableAssignment[-literal] == -1) {
                        clause_satisfied = true;
                        break;
                    }
                }
            }
            if (!clause_satisfied) {
                return false;
            }
        }
        return true;
    }
};

int main() {
    // Example formula: (x1 OR x2) AND (NOT x1 OR x3)
    Formula formula = {
        {1, 2},
        {-1, 3}
    };

    SATSolver solver(formula);
    if (solver.solve()) {
        std::cout << "The formula is satisfiable. Solution: ";
        solver.print_solution();
    } else {
        std::cout << "The formula is unsatisfiable." << std::endl;
    }

    return 0;
}

