typedef unsigned int Dword;

void GetCpuidInfo(Dword leaf, Dword* reg_eax, Dword* reg_ebx, Dword* reg_ecx, Dword* reg_edx) {
    // Assembly implementation of cpuid
    __asm {
        mov eax, leaf
        cpuid
        mov [reg_eax], eax
        mov [reg_ebx], ebx
        mov [reg_ecx], ecx
        mov [reg_edx], edx
    }
}

