// Node structure for binary tree
struct BinaryNode {
    int data;
    BinaryNode* leftChild;
    BinaryNode* rightChild;
    BinaryNode(int value) : data(value), leftChild(nullptr), rightChild(nullptr) {}
};

// Helper function to compute height and check balance
int computeHeight(BinaryNode* currentNode) {
    if (currentNode == nullptr) {
        return 0;
    }

    int leftSubtreeHeight = computeHeight(currentNode->leftChild);
    if (leftSubtreeHeight == -1) {
        return -1; // Left subtree is unbalanced
    }

    int rightSubtreeHeight = computeHeight(currentNode->rightChild);
    if (rightSubtreeHeight == -1) {
        return -1; // Right subtree is unbalanced
    }

    if (std::abs(leftSubtreeHeight - rightSubtreeHeight) > 1) {
        return -1; // Current node violates balance condition
    }

    return std::max(leftSubtreeHeight, rightSubtreeHeight) + 1;
}

// Main function to determine if tree is balanced
bool checkBalance(BinaryNode* rootNode) {
    return computeHeight(rootNode) != -1;
}

// Test driver
int main() {
    // Build a small balanced binary tree
    BinaryNode* root = new BinaryNode(10);
    root->leftChild = new BinaryNode(20);
    root->rightChild = new BinaryNode(30);
    root->leftChild->leftChild = new BinaryNode(40);
    root->leftChild->rightChild = new BinaryNode(50);

    if (checkBalance(root)) {
        std::cout << "The binary tree is height-balanced." << std::endl;
    } else {
        std::cout << "The binary tree is not height-balanced." << std::endl;
    }

    // Deallocate memory
    delete root->leftChild->leftChild;
    delete root->leftChild->rightChild;
    delete root->leftChild;
    delete root->rightChild;
    delete root;

    return 0;
}

#include <jni.h>

// Helper function to safely find and validate a Java class
static inline jclass _safe_class_lookup(JNIEnv* env, const char* className) {
    jclass resultClass = env->FindClass(className);

    if (resultClass == nullptr) {
        // Attempt to locate the NoClassDefFoundError class for proper exception handling
        jclass errorClass = env->FindClass("java/lang/NoClassDefFoundError");
        if (errorClass != nullptr) {
            env->ThrowNew(errorClass, "Requested class could not be located");
        } else {
            // Fallback: throw a generic Exception if even the error class is missing
            jclass genericException = env->FindClass("java/lang/Exception");
            if (genericException != nullptr) {
                env->ThrowNew(genericException, "Critical failure: Unable to resolve NoClassDefFoundError");
            }
        }
        return nullptr; // Signal failure by returning null reference
    }

    return resultClass;
}

jclass retrieve_application_class(JNIEnv* env) {
    auto loadedClass = _safe_class_lookup(env, "com/example/MainApplication");

    if (loadedClass == nullptr) {
        // An exception was already thrown during lookup
        return nullptr; // Propagate error condition
    }

    perform_initialization(env, loadedClass);

    return loadedClass;
}

