/* Define the Iterator object */
typedef struct {
    PyObject_HEAD
    size_t limit;
    size_t index;
} RangeIteratorObject;

static void RangeIterator_dealloc(RangeIteratorObject* self) {
    Py_TYPE(self)->tp_free((PyObject*)self);
}

static PyObject* RangeIterator_iter(RangeIteratorObject* self) {
    Py_INCREF(self);
    return (PyObject*)self;
}

static PyObject* RangeIterator_next(RangeIteratorObject* self) {
    if (self->index >= self->limit) {
        PyErr_SetNone(PyExc_StopIteration);
        return NULL;
    }
    PyObject* value = PyLong_FromSize_t(self->index);
    self->index++;
    return value;
}

