typedef struct {
    PyObject_HEAD
    size_t upper_bound;
} RangeSequenceObject;

static int RangeSequence_Init(RangeSequenceObject *self, PyObject *args, PyObject *kwds) {
    if (!PyArg_ParseTuple(args, "k", &(self->upper_bound))) {
