/* Module initialization function */
PyMODINIT_FUNC PyInit_range_gen(void) {
    PyObject* module;

    RangeIteratorType.tp_new = PyType_GenericNew;
    if (PyType_Ready(&RangeIteratorType) < 0)
        return NULL;

    RangeSequenceType.tp_new = PyType_GenericNew;
    if (PyType_Ready(&RangeSequenceType) < 0)
        return NULL;

    module = PyModule_Create(&range_module);
    if (module == NULL)
        return NULL;

    Py_INCREF(&RangeSequenceType);
    PyModule_AddObject(module, "RangeSequence", (PyObject*)&RangeSequenceType);

    Py_INCREF(&RangeIteratorType);
    PyModule_AddObject(module, "RangeIterator", (PyObject*)&RangeIteratorType);

    return module;
}

