// Function to normalize whitespace in a string
std::string normalizeWhitespace(const std::string& text) {
    if (text.empty()) return text;

    std::string output;
    bool previousWasSpace = false; // Flag to track if the last character was a space

    for (size_t index = 0; index < text.length(); ++index) {
        if (std::isspace(text[index])) {
            if (!previousWasSpace && !output.empty()) {
                output += ' '; // Add a single space only if not already in a space sequence
            }
            previousWasSpace = true;
        } else {
            output += text[index];
            previousWasSpace = false;
        }
    }

    // Remove trailing space if present
    if (!output.empty() && output.back() == ' ') {
        output.pop_back();
    }

    return output;
}

// Function to verify the normalizeWhitespace function
void validateNormalizeWhitespace() {
    std::string case1 = "  Hello   World!  ";
    std::string expected1 = "Hello World!";
    assert(normalizeWhitespace(case1) == expected1);

    std::string case2 = "  This is    a test  ";
    std::string expected2 = "This is a test";
    assert(normalizeWhitespace(case2) == expected2);

    std::string case3 = "NoExtraSpaces";
    std::string expected3 = "NoExtraSpaces";
    assert(normalizeWhitespace(case3) == expected3);

    std::string case4 = " ";
    std::string expected4 = "";
    assert(normalizeWhitespace(case4) == expected4);

    std::string case5 = "   ";
    std::string expected5 = "";
    assert(normalizeWhitespace(case5) == expected5);

    std::cout << "All tests passed!" << std::endl;
}

int main() {
    validateNormalizeWhitespace();
    return 0;
}

