#include <iostream>
#include <vector>
#include <string>

std::vector<std::vector<std::vector<int>>> buildPascalStructure(int rows) {
    std::vector<std::vector<std::vector<int>>> structure(rows);

    for (int depth = 0; depth < rows; ++depth) {
        structure[depth] = std::vector<std::vector<int>>(depth + 1, std::vector<int>(depth + 1, 0));

        for (int row = 0; row <= depth; ++row) {
            for (int col = 0; col <= depth; ++col) {
                if (row == 0 || col == 0 || row == col) {
                    structure[depth][row][col] = 1;
                } else {
                    int result = structure[depth - 1][row - 1][col] + structure[depth - 1][row][col - 1] + structure[depth - 1][row - 1][col - 1];
                    if (result % 2 != 1) {
                        std::cout << "Warning: Even value " << result << " at depth " << depth << " coordinates (" << row << ", " << col << ")" << std::endl;
                        structure[depth][row][col] = -999;  // Indicate anomaly with -999
                    } else {
                        structure[depth][row][col] = result;
                    }
                }
            }
        }
    }

    return structure;
}

int main() {
    int rows = 5;
    auto structure = buildPascalStructure(rows);

    for (int depth = 0; depth < rows; ++depth) {
        for (int row = 0; row <= depth; ++row) {
            for (int col = 0; col <= depth; ++col) {
                std::cout << structure[depth][row][col] << " ";
            }
            std::cout << std::endl;
        }
        std::cout << std::endl;
    }

    return 0;
}

