#include <atomic>
#include <tuple>

typedef struct {
    std::atomic<std::uint64_t> lower;
    std::atomic<std::uint64_t> upper;
} uint128_atomic;

uint128_atomic fetch_relaxed(const uint128_atomic* ptr) {
    return {ptr->lower.load(std::memory_order_relaxed),
            ptr->upper.load(std::memory_order_relaxed)};
}

bool compare_exchange_weak_relaxed(uint128_atomic* target, uint128_atomic* current, uint128_atomic replacement) {
    std::uint64_t prev_low = current->lower.load(std::memory_order_relaxed);
    std::uint64_t prev_high = current->upper.load(std::memory_order_relaxed);
    bool success = target->lower.compare_exchange_weak(prev_low, replacement.lower, std::memory_order_relaxed);
    if (success) {
        success = target->upper.compare_exchange_weak(prev_high, replacement.upper, std::memory_order_relaxed);
    }
    return success;
}

void assign_relaxed(uint128_atomic* atomic, uint128_atomic value) {
    atomic->lower.store(value.lower, std::memory_order_relaxed);
    atomic->upper.store(value.upper, std::memory_order_relaxed);
}

#include <Adafruit_NeoPixel.h>

#define PIN_DATA 6
#define LED_COUNT 22
#define PIN_INPUT 2

Adafruit_NeoPixel strip = Adafruit_NeoPixel(LED_COUNT, PIN_DATA, NEO_GRB + NEO_KHZ800);

enum FireState { Warm, Cool, Electric };
FireState activeMode = Warm;

int inputVal = 0;
int prevInputVal = 0;
unsigned long lastDebounceTime = 0;
unsigned long debouncePeriod = 50;

void initSystem() {
  strip.begin();
  pinMode(PIN_INPUT, INPUT_PULLUP);
}

void runLoop() {
  handleButton();

  switch (activeMode) {
    case Warm:
      renderFire(255, 95, 0);   // orange-red fire
      break;
    case Cool:
      renderFire(0, 255, 0);    // green-yellowish flame
      break;
    case Electric:
      renderFire(0, 0, 255);    // blue-white glow
      break;
  }
}

void renderFire(uint8_t red, uint8_t green, uint8_t blue) {
  for (int index = 0; index < LED_COUNT; index++) {
    int flickerAmount = random(128, 256);  // simulate flickering
    strip.setPixelColor(index, red * flickerAmount / 255, green * flickerAmount / 255, blue * flickerAmount / 255);
  }
  strip.show();
}

void handleButton() {
  int currentReading = digitalRead(PIN_INPUT);

  if (currentReading != prevInputVal) {
    lastDebounceTime = millis();
  }

  if ((millis() - lastDebounceTime) > debouncePeriod) {
    if (currentReading != inputVal) {
      inputVal = currentReading;

      if (inputVal == LOW) {
        advanceFireMode();
      }
    }
  }

