uint64_t rdtscp() {
    uint32_t lo, hi;
    __asm__ __volatile__("rdtscp" : "=a"(lo), "=d"(hi) : : "rcx");
    return ((uint64_t)hi << 32) | lo;
}

int main() {
    unsigned long long start_time, end_time;
    const int count = 500000;

    start_time = rdtscp();
    for (int i = 0; i < count; i++) {
        asm volatile("nop");
    }
    end_time = rdtscp();
    printf("rdtscp measurement for %d NOPs: %llu cycles\n", count, end_time - start_time);

    start_time = rdtscp();
    for (int i = 0; i < count; i++) {
        asm volatile("nop; nop; nop; nop; nop; nop; nop;");
    }
    end_time = rdtscp();
    printf("rdtscp measurement for %d * 7 NOPs: %llu cycles\n", count, end_time - start_time);

    return 0;
}

