using boost::asio::ip::udp;

// Function to send multicast heartbeat messages
void send_multicast_heartbeat(const std::string& group_address, unsigned short listening_port) {
    boost::asio::io_context service_context;
    udp::socket sending_socket(service_context);
    udp::endpoint target_endpoint = udp::endpoint(udp::address::from_string(group_address), listening_port);
    sending_socket.open(udp::v4());

    boost::array<char, 1> message_data = {{ 'B' }};

    while (true) {
        sending_socket.send_to(boost::asio::buffer(message_data), target_endpoint);
        std::this_thread::sleep_for(std::chrono::seconds(5));
    }
}

// Function to receive multicast heartbeat messages
void listen_multicast_heartbeat(const std::string& group_address, unsigned short listening_port) {
    boost::asio::io_context service_context;
    udp::socket receiving_socket(service_context, udp::endpoint(udp::v4(), listening_port));
    receiving_socket.set_option(udp::socket::reuse_address(true));

    udp::endpoint target_endpoint = udp::endpoint(udp::address::from_string(group_address), listening_port);
    receiving_socket.set_option(udp::socket::join_group(target_endpoint.address()));

    boost::array<char, 1> buffer_data;
    while (true) {
        udp::endpoint source_endpoint;
        size_t bytes_received = receiving_socket.receive_from(boost::asio::buffer(buffer_data), source_endpoint);
        if (buffer_data[0] == 'B') {
            std::cout << "Heartbeat received from " << source_endpoint << std::endl;
        }
    }
}

int main() {
    std::string group_address = "239.255.255.250";
    unsigned short listening_port = 12345;

    std::thread sender_thread(send_multicast_heartbeat, group_address, listening_port);
    std::thread receiver_thread(listen_multicast_heartbeat, group_address, listening_port);

    sender_thread.join();
    receiver_thread.join();

    return 0;
}

