long long sum_values(long long x, long long y) {
    try {
        // Verify for overflow conditions
        if (x > 0 && y > std::numeric_limits<long long>::max() - x) {
            throw std::overflow_error("Operands exceed maximum representable value.");
        }
        if (x < 0 && y < std::numeric_limits<long long>::min() - x) {
            throw std::underflow_error("Operands fall below minimum representable value.");
        }

        // Execute addition operation
        long long output = x + y;
        return output;
    } catch (const std::overflow_error& ex) {
        std::cerr << ex.what() << std::endl;
        return 0;
    } catch (const std::underflow_error& ex) {
        std::cerr << ex.what() << std::endl;
        return 0;
    } catch (const std::exception& ex) {
        std::cerr << "An unexpected error occurred: " << ex.what() << std::endl;
        return 0;
    }
}

int main() {
    long long val1 = 1234567890123456789LL;
    long long val2 = 9876543210987654321LL;
    std::cout << "Result: " << sum_values(val1, val2) << std::endl;
    return 0;
}

