class Individual {
private:
    std::string fullName;
    std::set<std::string> aliases;
    std::set<std::string> honorifics;

public:
    Individual(const std::string& name) : fullName(name) {}

    // Append a nickname
    void appendAlias(const std::string& alias) {
        if (alias.empty()) {
            throw std::invalid_argument("Alias cannot be empty.");
        }
        aliases.insert(alias);
    }

    // Remove a nickname
    void removeAlias(const std::string& alias) {
        if (aliases.erase(alias) == 0) {
            throw std::invalid_argument("Alias does not exist.");
        }
    }

    // Modify a nickname
    void modifyAlias(const std::string& previousAlias, const std::string& updatedAlias) {
        if (previousAlias == updatedAlias) {
            return; // No modification required
        }
        if (aliases.find(previousAlias) == aliases.end()) {
            throw std::invalid_argument("Previous alias does not exist.");
        }
        if (!updatedAlias.empty()) {
            aliases.erase(previousAlias);
            aliases.insert(updatedAlias);
        } else {
            throw std::invalid_argument("Updated alias cannot be empty.");
        }
    }

    // Add an honorific
    void addHonorific(const std::string& honorific) {
        if (honorific.empty()) {
            throw std::invalid_argument("Honorific cannot be empty.");
        }
        honorifics.insert(honorific);
    }

    // Remove an honorific
    void removeHonorific(const std::string& honorific) {
        if (honorifics.erase(honorific) == 0) {
            throw std::invalid_argument("Honorific does not exist.");
        }
    }

    // Change an honorific
    void changeHonorific(const std::string& oldHonorific, const std::string& newHonorific) {
        if (oldHonorific == newHonorific) {
            return; // No change needed
        }
        if (honorifics.find(oldHonorific) == honorifics.end()) {
            throw std::invalid_argument("Old honorific does not exist.");
        }
        if (!newHonorific.empty()) {
            honorifics.erase(oldHonorific);
            honorifics.insert(newHonorific);
        } else {
            throw std::invalid_argument("New honorific cannot be empty.");
        }
    }

    // Access aliases
    const std::set<std::string>& getAliases() const {
        return aliases;
    }

    // Access honorifics
    const std::set<std::string>& getHonorifics() const {
        return honorifics;
    }

    // Access the individual's full name
    const std::string& getFullName() const {
        return fullName;
    }
};

#include <windows.h>

LRESULT CALLBACK WindowProcedure(HWND hWnd, UINT uMsg, WPARAM wParam, LPARAM lParam);

int WINAPI WinMain(HINSTANCE hInstance, HINSTANCE hPrevInstance, LPSTR lpCmdLine, int nShowCmd) {
    WNDCLASS wc = {0};
    wc.lpfnWndProc = WindowProcedure;
    wc.hInstance = hInstance;
    wc.hbrBackground = CreateSolidBrush(RGB(255, 255, 255));
    wc.lpszClassName = "DraggableWindowClass";
    RegisterClass(&wc);

    HWND hWnd = CreateWindow(
        "DraggableWindowClass",
        "Transparent Draggable Window",
        WS_OVERLAPPEDWINDOW,
        CW_USEDEFAULT, CW_USEDEFAULT, 640, 480,
        NULL, NULL, hInstance, NULL
    );

    SetWindowLong(hWnd, GWL_EXSTYLE, GetWindowLong(hWnd, GWL_EXSTYLE) | WS_EX_LAYERED);

    ShowWindow(hWnd, nShowCmd);
    UpdateWindow(hWnd);

    MSG message = {0};
    while (GetMessage(&message, NULL, 0, 0)) {
        TranslateMessage(&message);
        DispatchMessage(&message);
    }
    return static_cast<int>(message.wParam);
}

LRESULT CALLBACK WindowProcedure(HWND hWnd, UINT uMsg, WPARAM wParam, LPARAM lParam) {
    static POINT dragOffset;
    static bool isDragging = false;

    switch (uMsg) {
        case WM_DESTROY:
            PostQuitMessage(0);
            break;

        case WM_LBUTTONDOWN: {
            dragOffset.x = GET_X_LPARAM(lParam);
            dragOffset.y = GET_Y_LPARAM(lParam);
            isDragging = true;
            SetLayeredWindowAttributes(hWnd, 0, 180, LWA_ALPHA);
            SetCursor(LoadCursor(NULL, IDC_HAND));
            break;
        }

        case WM_MOUSEMOVE:
            if (isDragging) {
                int xPos = GET_X_LPARAM(lParam) - dragOffset.x;
                int yPos = GET_Y_LPARAM(lParam) - dragOffset.y;
                SetWindowPos(hWnd, NULL, xPos, yPos, 0, 0, SWP_NOSIZE | SWP_NOZORDER | SWP_NOACTIVATE);
            }
            break;

        case WM_LBUTTONUP:
            isDragging = false;
            SetLayeredWindowAttributes(hWnd, 0, 255, LWA_ALPHA);
            SetCursor(LoadCursor(NULL, IDC_ARROW));
            break;

        default:
            return DefWindowProc(hWnd, uMsg, wParam, lParam);
    }
    return 0;
}

