inline unsigned int retrieve_cpu_capabilities()
{
    unsigned int caps;

    // Inline assembly to query CPUID
    asm volatile (
        "push %%eax\n\t"
        "push %%ebx\n\t"
        "push %%ecx\n\t"
        "push %%edx\n\t"
        "mov $1, %%eax\n\t"
        "cpuid\n\t"
        "mov %%edx, %0\n\t"
        "pop %%edx\n\t"
        "pop %%ecx\n\t"
        "pop %%ebx\n\t"
        "pop %%eax\n\t"
        : "=r" (caps)  // Output operand
        :
        : "eax", "ebx", "ecx", "edx"  // Clobbered registers
    );

    return caps;
}

