Eigen::MatrixXd computeMatrix(const LineArray& inputLines);

// Helper function to transform Eigen matrix into nested vector structure
vector<vector<double>> computeMatrix_wrapper(const LineArray& inputLines) {
    Eigen::MatrixXd outputMatrix = computeMatrix(inputLines);
    vector<vector<double>> convertedOutput(outputMatrix.rows(), vector<double>(outputMatrix.cols()));

    for (int row = 0; row < outputMatrix.rows(); ++row) {
        for (int col = 0; col < outputMatrix.cols(); ++col) {
            convertedOutput[row][col] = outputMatrix(row, col);
        }
    }

    return convertedOutput;
}

