#pragma comment(lib, "rasapi32.lib")
#pragma comment(lib, "iphlpapi.lib")

void RetrieveRASIPAddress(HRASCONN hConnection)
{
    // Step 1: Acquire RAS connection status details
    RASCONNSTATUS rasStatus = { sizeof(RASCONNSTATUS) };
    if (RasGetConnectStatus(hConnection, &rasStatus) == ERROR_SUCCESS)
    {
        printf("RAS device identifier: %s\n", rasStatus.szDeviceName);

        // Step 2: Enumerate all network interface configurations
        PIP_ADAPTER_ADDRESSES pAdapters = NULL;
        ULONG bufferSize = 0;
        DWORD result = 0;

        // Initial call to determine required buffer size
        result = GetAdaptersAddresses(AF_UNSPEC, GAA_FLAG_INCLUDE_PREFIX, NULL, pAdapters, &bufferSize);
        if (result == ERROR_BUFFER_OVERFLOW)
        {
            pAdapters = (IP_ADAPTER_ADDRESSES*)malloc(bufferSize);
            if (pAdapters == NULL)
            {
                printf("Failed to allocate memory\n");
                return;
            }
        }

        // Second call to retrieve actual adapter data
        result = GetAdaptersAddresses(AF_UNSPEC, GAA_FLAG_INCLUDE_PREFIX, NULL, pAdapters, &bufferSize);
        if (result == NO_ERROR)
        {
            PIP_ADAPTER_ADDRESSES currentAdapter = pAdapters;
            while (currentAdapter)
            {
                // Step 3: Correlate device name with adapter metadata
                if (wcscmp(currentAdapter->Description, rasStatus.szDeviceName) == 0 || 
                    wcscmp(currentAdapter->FriendlyName, rasStatus.szDeviceName) == 0)
                {
                    PIP_ADAPTER_UNICAST_ADDRESS pUnicastAddr = currentAdapter->FirstUnicastAddress;
                    while (pUnicastAddr)
                    {
                        if (pUnicastAddr->Address.lpSockaddr->sa_family == AF_INET)
                        {
                            char ipBuffer[46];
                            DWORD bufferSize = 46;
                            if (ConvertSocketAddressToString(pUnicastAddr->Address.lpSockaddr, ipBuffer, &bufferSize))
                            {
                                printf("RAS assigned IP address: %s\n", ipBuffer);
                            }
                        }
                        pUnicastAddr = pUnicastAddr->Next;
                    }
                    break;
                }
                currentAdapter = currentAdapter->Next;
            }
        }
        else
        {
            printf("GetAdaptersAddresses encountered error code: %d\n", result);
        }

        if (pAdapters)
        {
            free(pAdapters);
        }
    }
    else
    {
        printf("RasGetConnectStatus operation failed\n");
    }
}

// Utility function to transform socket address into human-readable string format
BOOL ConvertSocketAddressToString(const sockaddr* pSocketAddr, char* pBuffer, DWORD* pBufferSize)
{
    struct sockaddr_in* pIPv4Addr = (struct sockaddr_in*)pSocketAddr;
    return (inet_ntop(AF_INET, &pIPv4Addr->sin_addr, pBuffer, *pBufferSize) != NULL);
}

