}

#include <iostream>

class JammingWeapon : Weapon
{
    float jamProbability;
    int jamCooldown;
    bool isJamActive;

    Default
    {
        jamProbability = 0.03; // 3% chance of jamming
        jamCooldown = 60; // Jamming cooldown in tics
        isJamActive = false;
    }

    States
    {
    Ready:
        WEAP B 1 A_WeaponReady;
        Loop;

    Deselect:
        TNT1 A 0 CheckForJam; // Insert jam detection logic
        WEAP C 1 A_Lower;
        Loop;

    Select:
        TNT1 A 0 CheckForJam; // Insert jam detection logic
        WEAP C 1 A_Raise;
        Loop;

    Fire:
        WEAP A 0 Bright A_PlaySound("weapons/pistol", CHAN_WEAPON);
        TNT1 A 0 CheckForJam; // Insert jam detection logic

        WEAP A 0 A_GunFlash;
        WEAP A 1 Bright;
        WEAP A 0 A_FireBullets(1, 1, 1, 5, "BulletPuff");

        WEAP A 0 A_ReFire;
        Goto Ready;

    Flash:
        TNT1 A 0 CheckForJam; // Insert jam detection logic
        Goto LightDone;

    Jam:
        WEAP A 3 A_PlaySound("weapons/jam", CHAN_WEAPON);
        WEAP A 3;
        WEAP A 3;
        WEAP A 0 ReduceJamTimer;
        Goto Ready;

    LightDone:
        TNT1 A 0 A_Light0;
        Stop;
    }

    override void PostBeginPlay()
    {
        Super.PostBeginPlay();
    }

    private state void CheckForJam()
    {
        if (isJamActive)
            Goto Jam;

        if (random() < jamProbability)
        {
            isJamActive = true;
            Goto Jam;
        }
    }

    private state void ReduceJamTimer()
    {
        jamCooldown--;
        if (jamCooldown <= 0)
        {
            isJamActive = false;
            jamCooldown = 60;
        }
    }
}

