// Check if any keyword from the list is present in the given text
bool hasTerm(const std::string& text, const std::vector<std::string>& terms) {
    for (const auto& term : terms) {
        if (text.find(term) != std::string::npos) {
            return true;
        }
    }
    return false;
}

// Determine the purpose of the input sentence based on keywords
std::string classifyPurpose(const std::string& input) {
    std::unordered_map<std::string, std::vector<std::string>> purpose_terms = {
        {"salutation", {"hello", "hi", "hey", "good morning", "good afternoon", "good evening"}},
        {"departure", {"bye", "goodbye", "see you", "take care"}},
        {"gratitude", {"thank you", "thanks", "appreciate it"}},
        {"inquiry", {"what", "why", "how", "when", "where", "who", "which", "can you", "could you", "would you"}}
    };

    for (const auto& [purpose, terms] : purpose_terms) {
        if (hasTerm(input, terms)) {
            return purpose;
        }
    }

    return "unknown";
}

