using json = nlohmann::json;

// Base class for game objects
class GameObject {
public:
    virtual ~GameObject() = default;
    virtual void setup(const json& config) = 0;
};

// Concrete implementation: spatial location
class LocationComponent : public GameObject {
public:
    float posX, posY, posZ;

    void setup(const json& config) override {
        posX = config.value("x", 0.0f);
        posY = config.value("y", 0.0f);
        posZ = config.value("z", 0.0f);
    }
};

// Concrete implementation: life points
class VitalityComponent : public GameObject {
public:
    int vitality;

    void setup(const json& config) override {
        vitality = config.value("vitality", 100);
    }
};

// Object builder system
class ObjectBuilder {
public:
    using FactoryFn = std::function<std::unique_ptr<GameObject>()>;

    void registerType(const std::string& typeName, FactoryFn factory) {
        factories_[typeName] = factory;
    }

    std::unique_ptr<GameObject> buildObject(const std::string& typeName) const {
        auto iter = factories_.find(typeName);
        if (iter != factories_.end()) {
            return iter->second();
        }
        return nullptr;
    }

private:
    std::unordered_map<std::string, FactoryFn> factories_;
};

// Container class for composite objects
class CompositeObject {
public:
    void attach(std::unique_ptr<GameObject> obj) {
        parts_.push_back(std::move(obj));
    }

    void configure(const json& config) {
        for (auto& part : parts_) {
            part->setup(config);
        }
    }

    // Helper to access internal components
    const std::vector<std::unique_ptr<GameObject>>& getParts() const {
        return parts_;
    }

private:
    std::vector<std::unique_ptr<GameObject>> parts_;
};

// Master object creator
class MasterCreator {
public:
    MasterCreator(ObjectBuilder& builder) : builder_(builder) {}

    std::unique_ptr<CompositeObject> generate(const json& spec) {
        auto composite = std::make_unique<CompositeObject>();
        for (const auto& [typeKey, typeData] : spec.items()) {
            auto instance = builder_.buildObject(typeKey);
            if (instance) {
                composite->attach(std::move(instance));
            }
        }
        composite->configure(spec);
        return composite;
    }

private:
    ObjectBuilder& builder_;
};

int main() {
    ObjectBuilder builder;
    builder.registerType("Location", [] { return std::make_unique<LocationComponent>(); });
    builder.registerType("Vitality", [] { return std::make_unique<VitalityComponent>(); });

    MasterCreator creator(builder);

    std::string jsonString = R"({
        "Location": { "x": 5.0, "y": 10.0, "z": 15.0 },
        "Vitality": { "vitality": 200 }
    })";

    json specification = json::parse(jsonString);
    auto object = creator.generate(specification);

    // Demonstration of component inspection
    for (auto& part : object->getParts()) {
        if (auto loc = dynamic_cast<LocationComponent*>(part.get())) {
            std::cout << "Coordinates: " << loc->posX << ", " << loc->posY << ", " << loc->posZ << std::endl;
        } else if (auto vit = dynamic_cast<VitalityComponent*>(part.get())) {
            std::cout << "Vitality: " << vit->vitality << std::endl;
        }
    }

    return 0;
}

