// Generate the first n Fibonacci numbers
std::vector<int> generateFibonacci(int count) {
    if (count <= 0) return {};
    if (count == 1) return {0};
    if (count == 2) return {0, 1};

    std::vector<int> sequence = {0, 1};
    for (int index = 2; index < count; index++) {
        int newValue = sequence[index - 1] + sequence[index - 2];
        sequence.push_back(newValue);
    }

    return sequence;
}

int main() {
    int n = 10;
    std::vector<int> result = generateFibonacci(n);
    for (int value : result) {
        std::cout << value << " ";
    }
    std::cout << std::endl;
    return 0;
}

