#include <iostream>
#include <vector>
#include <mutex>
#include <cuda_runtime.h>

class DeviceMemoryPool {
public:
    DeviceMemoryPool(size_t unit_size, size_t unit_count) : block_size_(unit_size), num_blocks_(unit_count) {
        // Allocate a contiguous GPU memory region
        cudaMalloc(&memory_pool_, block_size_ * num_blocks_);

        // Set up bookkeeping structures
        block_info_.resize(num_blocks_);
        for (size_t i = 0; i < num_blocks_; ++i) {
            block_info_[i].is_available = true;
            block_info_[i].id = static_cast<int>(i);
        }
        available_list_head_ = 0;
    }

    ~DeviceMemoryPool() {
        cudaFree(memory_pool_);
    }

    void* acquire() {
        std::lock_guard<std::mutex> guard(access_mutex_);

        if (available_list_head_ == -1) {
            throw std::bad_alloc();
        }

        int slot_id = available_list_head_;
        available_list_head_ = block_info_[slot_id].next_available;

        block_info_[slot_id].is_available = false;
        return static_cast<char*>(memory_pool_) + slot_id * block_size_;
    }

    void release(void* address) {
        std::lock_guard<std::mutex> guard(access_mutex_);

        size_t position = (static_cast<char*>(address) - static_cast<char*>(memory_pool_)) / block_size_;

        block_info_[position].is_available = true;
        block_info_[position].next_available = available_list_head_;
        available_list_head_ = static_cast<int>(position);
    }

private:
    size_t block_size_;
    size_t num_blocks_;
    void* memory_pool_;
    std::vector<struct SlotInfo> block_info_;
    int available_list_head_ = 0;
    std::mutex access_mutex_;

    struct SlotInfo {
        bool is_available;
        int id;
        int next_available = -1;
    };
};

int main() {
    DeviceMemoryPool pool(256, 1024);

    void* block_a = pool.acquire();
    void* block_b = pool.acquire();

    pool.release(block_a);
    pool.release(block_b);

    return 0;
}

