#include <iostream>
#include <cmath>
#include <chrono>
#include <vector>

// Constants for computation limits
const unsigned int MAX_ITERATIONS = 40000;
const unsigned int DATA_SIZE = 10000;

int main()
{
    // Initialize data vectors and coefficient arrays
    std::vector<double> input1(DATA_SIZE);
    std::vector<double> input2(DATA_SIZE);
    std::vector<double> coefficients1(MAX_ITERATIONS, 0.0);
    std::vector<double> coefficients2(MAX_ITERATIONS, 0.0);

    // Start timing the execution
    auto begin_time = std::chrono::high_resolution_clock::now();

    // Main computational loop over k values
    for (unsigned int index = 1; index <= MAX_ITERATIONS; ++index) {
        std::vector<double> cosine_vals(DATA_SIZE);
        std::vector<double> sine_vals(DATA_SIZE);

        // Compute trigonometric values for current k
        for (unsigned int position = 0; position < DATA_SIZE; ++position) {
            cosine_vals[position] = std::cos(index * input1[position]);
            sine_vals[position] = std::sin(index * input1[position]);
        }

        // Update coefficients using inner product operations
        coefficients1[index-1] += (input2[DATA_SIZE-1] - input2[0]) + 
            std::inner_product(input2.begin(), input2.end()-1, cosine_vals.begin(), 0.0, 
                             std::plus<double>(), std::minus<double>());
        coefficients2[index-1] += std::inner_product(input2.begin(), input2.end()-1, 
                                                     sine_vals.begin(), 0.0, 
                                                     std::plus<double>(), std::minus<double>());
    }

    // Stop timing and calculate duration
    auto end_time = std::chrono::high_resolution_clock::now();
    auto elapsed = std::chrono::duration_cast<std::chrono::seconds>(end_time - begin_time);

    std::cout << "Execution time: " << elapsed.count() << " seconds" << std::endl;
    return 0;
}

