#include <iostream>
#include <vector>

// Compute the determinant of a square matrix
double calcDeterminant(const std::vector<std::vector<double>>& mat) {
    int size = mat.size();

    // Handle 1x1 case
    if (size == 1) {
        return mat[0][0];
    }

    // Handle 2x2 case
    if (size == 2) {
        return mat[0][0] * mat[1][1] - mat[0][1] * mat[1][0];
    }

    double result = 0.0;

    // Expand along the first row
    for (int column = 0; column < size; ++column) {
        std::vector<std::vector<double>> minor(size - 1, std::vector<double>(size - 1));

        // Build the minor matrix by excluding row 0 and current column
        for (int row = 1; row < size; ++row) {
            for (int col = 0, index = 0; col < size; ++col) {
                if (col != column) {
                    minor[row - 1][index++] = mat[row][col];
                }
            }
        }

        // Accumulate the cofactor contribution
        result += mat[0][column] * std::pow(-1, column) * calcDeterminant(minor);
    }

    return result;
}

int main() {
    // Test matrix
    std::vector<std::vector<double>> testMatrix = {
        {1, 2, 3},
        {4, 5, 6},
        {7, 8, 9}
    };

    double detValue = calcDeterminant(testMatrix);
    std::cout << "The determinant of the matrix is: " << detValue << std::endl;

    return 0;
}

