void histSubtractFromBits(uint64_t* data, uint16_t* histogram) {
    // Process each 64-bit word in the cursor array
    for (int wordIndex = 0; wordIndex < 4; ++wordIndex) {
        uint64_t currentWord = data[wordIndex];
        // Check each bit position in the current word
        for (int bitPosition = 0; bitPosition < 64; ++bitPosition) {
            // If the bit is set, decrement the corresponding histogram entry
            if (currentWord & (1ULL << bitPosition)) {
                histogram[wordIndex * 64 + bitPosition] -= 1;
            }
        }
    }
}

#include <openssl/des.h>
#include <openssl/err.h>
#include <iostream>
#include <fstream>
#include <vector>

void perform3DESEncryption(const std::string& sourcePath, const std::string& destinationPath, const unsigned char* encryptionKey, const unsigned char* initializationVector) {
    std::ifstream sourceFile(sourcePath, std::ios::binary);
    std::ofstream destFile(destinationPath, std::ios::binary);

    if (!sourceFile.is_open() || !destFile.is_open()) {
        std::cerr << "Failed to open file(s)." << std::endl;
        return;
    }

    std::vector<unsigned char> chunk(2048);
    DES_key_schedule scheduleA, scheduleB, scheduleC;
    DES_set_key((DES_cblock*)encryptionKey, &scheduleA);
    DES_set_key((DES_cblock*)(encryptionKey + 8), &scheduleB);
    DES_set_key((DES_cblock*)(encryptionKey + 16), &scheduleC);

    while (sourceFile.read(reinterpret_cast<char*>(chunk.data()), chunk.size())) {
        size_t actualBytes = sourceFile.gcount();
        DES_ede3_cbc_encrypt(chunk.data(), chunk.data(), actualBytes, &scheduleA, &scheduleB, &scheduleC, (DES_cblock*)initializationVector, DES_ENCRYPT);
        destFile.write(reinterpret_cast<char*>(chunk.data()), actualBytes);
    }

    size_t remainingBytes = sourceFile.gcount();
    if (remainingBytes > 0) {
        DES_ede3_cbc_encrypt(chunk.data(), chunk.data(), remainingBytes, &scheduleA, &scheduleB, &scheduleC, (DES_cblock*)initializationVector, DES_ENCRYPT);
        destFile.write(reinterpret_cast<char*>(chunk.data()), remainingBytes);
    }

    sourceFile.close();
    destFile.close();
}

int main() {
    unsigned char desKey[24] = { /* 24-byte key for triple DES */ };
    unsigned char ivData[8] = { /* 8-byte initialization vector */ };

    perform3DESEncryption("plaintext.dat", "encrypted.bin", desKey, ivData);

    return 0;
}

