#include <iostream>
using namespace std;

// Structure representing a node in the binary tree
struct BinaryNode {
    int data;
    BinaryNode *leftChild;
    BinaryNode *rightChild;
    BinaryNode(int x) : data(x), leftChild(nullptr), rightChild(nullptr) {}
};

// Helper function to determine if two subtrees are mirror images of each other
bool checkMirror(BinaryNode* nodeA, BinaryNode* nodeB) {
    if (nodeA == nullptr && nodeB == nullptr) return true;
    if (nodeA == nullptr || nodeB == nullptr) return false;
    return (nodeA->data == nodeB->data) 
           && checkMirror(nodeA->leftChild, nodeB->rightChild) 
           && checkMirror(nodeA->rightChild, nodeB->leftChild);
}

// Main function to verify if the entire tree is symmetric
bool isSymmetricTree(BinaryNode* root) {
    return checkMirror(root, root);
}

// Utility function to allocate and initialize a new tree node
BinaryNode* newNode(int value) {
    return new BinaryNode(value);
}

// Test function to validate symmetry detection logic
void validateSymmetry() {
    // Constructed symmetric tree:
    //       10
    //      /  \
    //    20    20
    //   /  \   /  \
    // 30   40 40   30
    BinaryNode* root = newNode(10);
    root->leftChild = newNode(20);
    root->rightChild = newNode(20);
    root->leftChild->leftChild = newNode(30);
    root->leftChild->rightChild = newNode(40);
    root->rightChild->leftChild = newNode(40);
    root->rightChild->rightChild = newNode(30);

    if (isSymmetricTree(root)) {
        cout << "The binary tree is symmetric." << endl;
    } else {
        cout << "The binary tree is not symmetric." << endl;
    }
}

int main() {
    validateSymmetry();
    return 0;
}

#include <iostream>
#include <optional>

class ListNode {
public:
    int data;
    ListNode* previous;
    ListNode* nextNode;

    ListNode(int val) : data(val), previous(nullptr), nextNode(nullptr) {}
};

class MoveToFrontList {
private:
    ListNode* start;
    ListNode* end;

public:
    MoveToFrontList() : start(nullptr), end(nullptr) {}

    ~MoveToFrontList() {
        while (start != nullptr) {
            ListNode* temp = start;
            start = start->nextNode;
            delete temp;
        }
    }

    void add(int value) {
        ListNode* newNode = new ListNode(value);
        if (start == nullptr) {
            start = end = newNode;
        } else {
            newNode->nextNode = start;
            start->previous = newNode;
            start = newNode;
        }
    }

    bool erase(int value) {
        ListNode* current = start;
        while (current != nullptr) {
            if (current->data == value) {
                if (current->previous) {
                    current->previous->nextNode = current->nextNode;
                } else {
                    start = current->nextNode;
                }
                if (current->nextNode) {
                    current->nextNode->previous = current->previous;
                } else {
                    end = current->previous;
                }
                delete current;
                return true;
            }
            current = current->nextNode;
        }
        return false;
    }

    std::optional<int> find(int value) {
        ListNode* current = start;
        while (current != nullptr) {
            if (current->data == value) {
                bringToFront(current);
                return current->data;
            }
            current = current->nextNode;
        }
        return std::nullopt;
    }

private:
    void bringToFront(ListNode* node) {
        if (node == start) return;

        if (node->previous) {
            node->previous->nextNode = node->nextNode;
        }
        if (node->nextNode) {
            node->nextNode->previous = node->previous;
        }
        if (node == end) {
            end = node->previous;
        }

        node->nextNode = start;
        node->previous = nullptr;
        start->previous = node;
        start = node;
    }
};

int main() {
    MoveToFrontList container;
    container.add(10);
    container.add(20);
    container.add(30);
    container.add(40);

    std::cout << "Find 30: " << container.find(30).value_or(-1) << std::endl;
    std::cout << "Find 10: " << container.find(10).value_or(-1) << std::endl;
    std::cout << "Find 20: " << container.find(20).value_or(-1) << std::endl;

    container.erase(30);
    std::cout << "Find 30 after deletion: " << container.find(30).value_or(-1) << std::endl;

    return 0;
}

