#include <thrust/device_vector.h>
#include <thrust/sort.h>
#include <thrust/execution_policy.h>

struct Vector2D {
    float x, y;
};

struct TreeNode {
    int leftBound, rightBound;  // Interval of points in the array
    int splitAxis;              // Axis used for splitting (0: x-axis, 1: y-axis)
    float threshold;            // Splitting coordinate value
    int childLeft, childRight;  // Indices of left and right subtrees
};

__global__ void constructKdTreeKernel(Vector2D* dataPoints, TreeNode* treeNodes, int* workStack, int* stackTop, int* nextFreeNode) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx >= *stackTop) return;

    int nodePos = workStack[idx];
    TreeNode& current = treeNodes[nodePos];
    int begin = current.leftBound;
    int finish = current.rightBound;
    int dim = current.splitAxis;

    // Sort points along the chosen dimension
    thrust::sort(thrust::device, dataPoints + begin, dataPoints + finish, [dim] __device__ (const Vector2D& p1, const Vector2D& p2) {
        return (dim == 0) ? p1.x < p2.x : p1.y < p2.y;
    });

    // Determine median index and split value
    int mid = (begin + finish) / 2;
    float splitValue = (dim == 0) ? dataPoints[mid].x : dataPoints[mid].y;

    // Allocate new nodes for children using atomic operations
    int leftChild = atomicAdd(nextFreeNode, 1);
    int rightChild = atomicAdd(nextFreeNode, 1);

    // Initialize child nodes
    treeNodes[leftChild] = {begin, mid, 1 - dim, 0, -1, -1};
    treeNodes[rightChild] = {mid + 1, finish, 1 - dim, 0, -1, -1};

    // Update current node with split information
    current.threshold = splitValue;
    current.childLeft = leftChild;
    current.childRight = rightChild;

    // Push children onto the work stack
    workStack[*stackTop] = leftChild;
    workStack[++*stackTop] = rightChild;
}

void buildKdTreeStructure(Vector2D* devicePoints, int pointCount, TreeNode* deviceNodes, int maxCapacity) {
    // Setup initial root node
    TreeNode rootNode = {0, pointCount, 0, 0, -1, -1};
    cudaMemcpy(deviceNodes, &rootNode, sizeof(TreeNode), cudaMemcpyHostToDevice);

    // Allocate GPU memory for stack management
    int* d_workStack;
    cudaMalloc(&d_workStack, maxCapacity * sizeof(int));
    int* d_stackPointer;
    cudaMalloc(&d_stackPointer, sizeof(int));
    int* d_nextAvailableNode;
    cudaMalloc(&d_nextAvailableNode, sizeof(int));

    int initialStackSize = 1;
    int nextNodeCounter = 1;

    cudaMemcpy(d_workStack, &rootNode, sizeof(TreeNode), cudaMemcpyHostToDevice);
    cudaMemcpy(d_stackPointer, &initialStackSize, sizeof(int), cudaMemcpyHostToDevice);
    cudaMemcpy(d_nextAvailableNode, &nextNodeCounter, sizeof(int), cudaMemcpyHostToDevice);

    // Kernel configuration parameters
    int threadsPerBlock = 256;
    int blocksPerGrid = (maxCapacity + threadsPerBlock - 1) / threadsPerBlock;

    // Iterative tree construction loop
    while (initialStackSize > 0) {
        constructKdTreeKernel<<<blocksPerGrid, threadsPerBlock>>>(
            devicePoints, deviceNodes, d_workStack, d_stackPointer, d_nextAvailableNode
        );
        cudaDeviceSynchronize();

        // Retrieve updated stack size and node counter from device
        cudaMemcpy(&initialStackSize, d_stackPointer, sizeof(int), cudaMemcpyDeviceToHost);
        cudaMemcpy(&nextNodeCounter, d_nextAvailableNode, sizeof(int), cudaMemcpyDeviceToHost);
    }

    // Clean up allocated GPU resources
    cudaFree(d_workStack);
    cudaFree(d_stackPointer);
    cudaFree(d_nextAvailableNode);
}

