// Precompute inverse scale factors for efficient arithmetic coding
std::unordered_map<uint32_t, uint32_t> inv_scales;

void init_inverse_scales() {
    for (uint32_t factor = 1; factor <= 256; ++factor) {
        inv_scales[factor] = static_cast<uint32_t>((1U << 16) / factor);
    }
}

void aricoder::encode(symbol* s)
{   
    // Update range boundaries using precomputed reciprocals
    unsigned int range_delta = (chigh - clow + 1);
    cstep = (range_delta * inv_scales[s->scale]) >> 16;
    chigh = clow + (cstep * s->high_count) - 1;
    clow  = clow + (cstep * s->low_count );

    // E3 scaling to prevent underflow and maintain precision
    while ((clow >= CODER_LIMIT050) || (chigh < CODER_LIMIT050)) {
        if (chigh < CODER_LIMIT050) { 
            write_zero();
            write_nrbits_as_one();
        } else { 
            write_one();
            clow  &= CODER_LIMIT050 - 1;
            chigh &= CODER_LIMIT050 - 1;
            write_nrbits_as_zeros();
        }
        clow  <<= 1;
        chigh = (chigh << 1) | 1;
    }

    // Secondary scaling step for maintaining sufficient interval width
    while ((clow >= CODER_LIMIT025) && (chigh < CODER_LIMIT075)) {
        ++nrbits;
        clow  &= CODER_LIMIT025 - 1;
        chigh ^= CODER_LIMIT025 + CODER_LIMIT050;
        clow  <<= 1;
        chigh = (chigh << 1) | 1;
    }
}

