// Kernel to copy data using shared memory tiling
__global__ void copy_tile_data(float *output, const float *input, int cols, int rows) {
    __shared__ float block[BLOCK_SIZE][BLOCK_SIZE];

    int col = blockIdx.y * BLOCK_SIZE + threadIdx.y;
    int row = blockIdx.x * BLOCK_SIZE + threadIdx.x;

    if (col < cols && row < rows) {
        block[threadIdx.y][threadIdx.x] = input[row * cols + col];
    }

    __syncthreads();

    if (col < cols && row < rows) {
        output[row * cols + col] = block[threadIdx.y][threadIdx.x];
    }
}

