struct WeatherReading {
    std::string city;
    double tempC;
    double elevation;
    int timeOfDay;
    std::string period;
};

struct ConvertedResult {
    std::string city;
    double tempF;
};

double correctElevationEffect(double celsius, double elevation) {
    return celsius - 0.0065 * elevation;
}

double adjustHourlyTemperature(double celsius, int hour) {
    if (hour >= 6 && hour < 12) {
        return celsius - 1;
    } else if (hour >= 18 && hour < 24) {
        return celsius - 2;
    }
    return celsius;
}

double seasonalCorrection(double celsius, const std::string& season) {
    if (season == "summer") {
        return celsius + 2;
    } else if (season == "winter") {
        return celsius - 2;
    }
    return celsius;
}

double convertTo Fahrenheit(double celsius) {
    return celsius * 9/5 + 32;
}

std::vector<ConvertedResult> processTemperatures(const std::vector<WeatherReading>& readings) {
    std::vector<ConvertedResult> output;
    for (const auto& item : readings) {
        double tempC = item.tempC;
        double elev = item.elevation;
        int hour = item.timeOfDay;
        std::string season = item.period;

        double correctedTemp = correctElevationEffect(tempC, elev);
        double hourlyAdjusted = adjustHourlyTemperature(correctedTemp, hour);
        double finalTemp = seasonalCorrection(hourlyAdjusted, season);

        double fahrenheit = convertTo Fahrenheit(finalTemp);
        output.push_back({item.city, fahrenheit});
    }
    return output;
}

void writeJsonOutput(const std::vector<ConvertedResult>& data) {
    json j = data;
    std::ofstream outFile("output.json");
    outFile << std::setw(4) << j << std::endl;
}

void writeCsvOutput(const std::vector<ConvertedResult>& data) {
    std::ofstream csvFile("output.csv");
    csvFile << "city,tempF\n";
    for (const auto& entry : data) {
        csvFile << entry.city << "," << entry.tempF << "\n";
    }
}

int main() {
    std::vector<WeatherReading> input = {
        {"Chicago", 22, 15, 14, "summer"},
        {"Miami", 28, 20, 20, "winter"}
    };

    std::vector<ConvertedResult> processed = processTemperatures(input);
    writeJsonOutput(processed);
    writeCsvOutput(processed);

    return 0;
}

