std::string convertJStringToStdString(JNIEnv* env, jstring javaString) {
    char* resultBuffer = NULL;
    jclass stringClass = env->FindClass("java/lang/String");
    jstring encoding = env->NewStringUTF("GB2312");
    jmethodID methodID = env->GetMethodID(stringClass, "getBytes",
            "(Ljava/lang/String;)[B");
    jbyteArray byteArr = (jbyteArray) env->CallObjectMethod(javaString, methodID, encoding);
    jsize arrayLen = env->GetArrayLength(byteArr);
    jbyte* bytes = env->GetByteArrayElements(byteArr, JNI_FALSE);

    if (arrayLen > 0) {
        resultBuffer = (char*) malloc(arrayLen + 1);
        if (resultBuffer == NULL) {
            __android_log_print(ANDROID_LOG_ERROR, "jni", "Memory allocation failed");
            env->ReleaseByteArrayElements(byteArr, bytes, 0);
            return std::string();
        }
        memcpy(resultBuffer, bytes, arrayLen);
        resultBuffer[arrayLen] = '\0';
    }

    env->ReleaseByteArrayElements(byteArr, bytes, 0);
    std::string finalString(resultBuffer);
    free(resultBuffer);
    return finalString;
}

