// Function to read file contents into a tensor
static Status LoadFileIntoTensor(Env* env, const string& filepath, Tensor* result) {
    uint64 file_size = 0;
    TF_RETURN_IF_ERROR(env->GetFileSize(filepath, &file_size));

    string file_content;
    file_content.resize(file_size);

    std::unique_ptr<RandomAccessFile> file_reader;
    TF_RETURN_IF_ERROR(env->NewRandomAccessFile(filepath, &file_reader));

    StringPiece data_piece;
    TF_RETURN_IF_ERROR(file_reader->Read(0, file_size, &data_piece, &file_content[0]));

    result->scalar<string>()() = data_piece.as_string();
    return Status::OK();
}

// Read and preprocess an image from file
Status ProcessImage(const string& filename, const int target_width, const int target_height,
                   const float normalization_mean, const float normalization_scale,
                   std::vector<Tensor>* output_tensors) {
    Tensor input_tensor(DT_STRING, TensorShape());
    TF_RETURN_IF_ERROR(LoadFileIntoTensor(Env::Default(), filename, &input_tensor));

    auto root_scope = Scope::NewRootScope();
    auto input_node = ops::Placeholder(root_scope.WithOpName("image_input"), DT_STRING);
    std::vector<std::pair<string, Tensor>> feed_dict = { {"image_input", input_tensor} };

    // Decode PNG image with 3 color channels
    Output decoded_image = ops::DecodePng(root_scope.WithOpName("decode_png"), input_node,
                                         ops::DecodePng::Channels(3));

    // Convert to float type
    auto float_image = ops::Cast(root_scope.WithOpName("convert_to_float"), decoded_image, DT_FLOAT);

    // Add batch dimension
    auto expanded_image = ops::ExpandDims(root_scope, float_image, 0);

    // Resize to target dimensions
    auto resized_image = ops::ResizeBilinear(root_scope, expanded_image,
                                           ops::Const(root_scope.WithOpName("resize_dims"),
                                                     {target_height, target_width}));

    // Normalize: subtract mean and divide by scale
    auto normalized = ops::Sub(root_scope, resized_image, ops::Const(root_scope, normalization_mean));
    auto final_tensor = ops::Div(root_scope.WithOpName("normalized_output"), normalized,
                                ops::Const(root_scope, normalization_scale));

    GraphDef graph_definition;
    TF_RETURN_IF_ERROR(root_scope.ToGraphDef(&graph_definition));

    Session* session;
    TF_RETURN_IF_ERROR(NewSession(SessionOptions(), &session));
    TF_RETURN_IF_ERROR(session->Create(graph_definition));
    TF_RETURN_IF_ERROR(session->Run({feed_dict}, {"normalized_output"}, {}, output_tensors));
    TF_RETURN_IF_ERROR(session->Close());
    delete session;
    return Status::OK();
}

int main(int argc, char* argv[]) {
    tensorflow::port::InitMain(argv[0], &argc, &argv);

    GraphDef model_graph;
    Status status = ReadBinaryProto(Env::Default(), "models/model.pb", &model_graph);
    if (!status.ok()) {
        std::cout << "Error loading graph: " << status.ToString() << std::endl;
        return -1;
    }
    std::cout << "Model graph loaded successfully\n";

    std::vector<Tensor> preprocessed_images;

    status = ProcessImage("sample.png", 256, 256, 128.0f, 255.0f, &preprocessed_images);
    if (!status.ok()) {
        std::cout << "Error processing image: " << status.ToString() << std::endl;
        return -1;
    }
    std::cout << "Image preprocessing completed\n";

    Session* inference_session;
    status = NewSession(SessionOptions(), &inference_session);
    if (!status.ok()) {
        std::cout << "Failed to create session: " << status.ToString() << std::endl;
        return -1;
    }

    status = inference_session->Create(model_graph);
    if (!status.ok()) {
        std::cout << "Failed to build graph in session: " << status.ToString() << std::endl;
        return -1;
    }

    std::vector<Tensor> results;
    status = inference_session->Run({{"input_layer", preprocessed_images[0]}},
                                   {"output_layer/Relu"}, {}, &results);
    if (!status.ok()) {
        std::cout << "Inference failed: " << status.ToString() << std::endl;
        return -1;
    }

    // Display results
    for (const auto& result_tensor : results) {
        std::cout << "Output tensor shape: " << result_tensor.shape().DebugString() << std::endl;

        // Print first 10 elements of the output
        int limit = std::min(10, static_cast<int>(result_tensor.NumElements()));
        for (int idx = 0; idx < limit; ++idx) {
            std::cout << result_tensor.flat<float>()(idx) << " ";
        }
        std::cout << std::endl;
    }

    TF_RETURN_IF_ERROR(inference_session->Close());
    delete inference_session;
    return 0;
}

