template<std::size_t Bits>
struct big_int;

template <std::size_t Bits, std::size_t S, bool F = S == big_int<Bits>::numblocks>
struct adder {
    static inline void accumulate(big_int<Bits> &x, const big_int<Bits> &y) {
        adder<Bits, big_int<Bits>::numblocks>::accumulate(x, y);
    }
};

template<std::size_t Bits, std::size_t S>
struct adder<Bits, S, 1> {
    static inline void accumulate(big_int<Bits> &x, const big_int<Bits> &y) {
        uint64_t carry = 0;
        for (std::size_t idx = 0; idx < S; ++idx) {
            uint64_t result = x[idx] + y[idx] + carry;
            x[idx] = result;
            carry = (result < x[idx]) ? 1 : 0;
        }
    }
};

template<std::size_t Bits, std::size_t S>
struct adder<Bits, S, 0> {
    static inline void accumulate(big_int<Bits> &x, const big_int<Bits> &y) {
        uint64_t carry = 0;
        for (std::size_t idx = 0; idx < S; ++idx) {
            uint64_t result = x[idx] + y[idx] + carry;
            x[idx] = result;
            carry = (result < x[idx]) ? 1 : 0;
        }
    }
};

template<std::size_t Bits>
struct big_int {
    typedef uint64_t word_type;
    static const std::size_t bitcount = Bits;
    static const std::size_t numblocs = (Bits + std::numeric_limits<word_type>::digits - 1) / std::numeric_limits<word_type>::digits;
    using storage = std::array<uint64_t, numblocs>;

    typedef typename storage::iterator iter;

    iter start() { return storage_.begin(); }
    iter finish() { return storage_.end(); }

    explicit big_int(word_type val = word_type()) {
        assert(-1l >> 1 == -1l);
        std::fill(start(), finish(), word_type());
        storage_[0] = val;
    }

    inline word_type& operator[](std::size_t pos) { return storage_[pos]; }
    inline const word_type& operator[](std::size_t pos) const { return storage_[pos]; }

    big_int& operator+=(const big_int& rhs) {
        adder<bitcount, numblocs>::accumulate(*this, rhs);
        return *this;
    }

    big_int& operator~() {
        std::transform(start(), finish(), start(), std::bit_not<word_type>());
        return *this;
    }

    void dump_raw(std::ostream& stream) const {
        stream << "(";
        for (std::size_t pos = numblocs - 1; pos > 0; --pos)
            stream << storage_[pos] << " ";
        stream << storage_[0];
        stream << ")";
    }

    void display(std::ostream& stream) const {
        assert(false && " IMPLEMENTATION PENDING ! \n");
    }

private:
    storage storage_;
};

template <std::size_t Bits>
std::ostream& operator<< (std::ostream& stream, big_int<Bits> const& num) {
    if (stream.flags() & std::ios_base::hex)
        num.dump_raw(stream);
    else
        num.display(stream);
    return stream;
}

int main(int argc, const char * argv[]) {
    big_int<256> first; // initialized to zero
    big_int<256> second(1);

    ~first; // invert all bits: all zeros become ones

    std::cout << " first: " << std::hex << first << std::endl;
    std::cout << " expected: (ffffffffffffffff ffffffffffffffff ffffffffffffffff ffffffffffffffff) " << std::endl;

    first += second; // should propagate the carry through all words

    std::cout << " first+=second: " << first << std::endl;
    std::cout << " expected: (0 0 0 0) " << std::endl; // it works but ...

    return 0;
}

