// Function to measure performance of sum operation on xtensor
pair<double, double> benchmarkSum(int arraySize, int iterations=30) {
    double total_time = 0;
    double accumulated_result = 0;

    for (int j = 0; j < iterations; j++) {
        xt::xtensor<double, 1> data = xt::random::rand({arraySize}, 0.0, 1.0);
        int begin_time = clock();

        double result = xt::sum(data, xt::evaluation_strategy::immediate, xt::parallelExecution())();

        int finish_time = clock();
        accumulated_result += result;
        total_time += finish_time - begin_time;
    }

    return pair<double, double>(total_time / CLOCKS_PER_SEC / iterations, accumulated_result);
}

int main(int argc, char *argv[]) {
    for (int exp = 5; exp < 8; exp++) {
        int dimension = pow(10, exp);
        pair<double, double> outcome = benchmarkSum(dimension);
        cout << "dimension: " << dimension << " \t " << outcome.first << " sec\t" << outcome.second << endl;
    }
    return 0;
}

