// Definition for singly-linked list.
struct Node {
    int data;
    Node *link;
    Node(int x) : data(x), link(NULL) {}
};

bool detectLoop(Node *start) {
    if (start == NULL || start->link == NULL) {
        return false; // No loop if the list is empty or has only one node
    }

    Node *slow = start;
    Node *fast = start;

    while (fast != NULL && fast->link != NULL) {
        slow = slow->link;         // Move slow pointer by one step
        fast = fast->link->link;   // Move fast pointer by two steps

        if (slow == fast) {
            return true; // Loop detected
        }
    }

    return false; // No loop detected
}

int main() {
    // Example usage:
    Node *first = new Node(10);
    Node *second = new Node(20);
    Node *third = new Node(30);
    Node *fourth = new Node(40);

    first->link = second;
    second->link = third;
    third->link = fourth;
    fourth->link = second; // Creating a loop

    if (detectLoop(first)) {
        std::cout << "Loop found." << std::endl;
    } else {
        std::cout << "No loop found." << std::endl;
    }

    // Clean up memory
    delete first;
    delete second;
    delete third;
    delete fourth;

    return 0;
}

