void analyzeInstructions(uint8_t *dataBuffer, long length, uint64_t baseAddress) {
    csh disasmHandle;
    cs_insn *instructions;
    size_t instructionCount;
    std::string resultString;

    if (cs_open(CS_ARCH_X86, CS_MODE_64, &disasmHandle) == CS_ERR_OK) {
        instructionCount = cs_disasm(disasmHandle, dataBuffer, length, baseAddress, 0, &instructions);
        printf("\nINSTRUCTION_COUNT:%lu", instructionCount);
        if (instructionCount > 0) {
            for (size_t idx = 0; idx < instructionCount; idx++) {
                char tempBuffer[512];
                int written = sprintf(tempBuffer, "0x%" PRIx64 ":\t%s\t\t%s\n", 
                                      instructions[idx].address, 
                                      instructions[idx].mnemonic, 
                                      instructions[idx].op_str);
                resultString += tempBuffer;
            }
            cs_free(instructions, instructionCount);
        } else {
            resultString = "DISASSEMBLY_ERROR: Unable to decode provided bytes!\n";
        }
        cs_close(&disasmHandle);
        std::cout << resultString;
    }
}

bool getTextSection(const char *binaryPath, uint8_t **instructionData, uint64_t *dataLength, uint64_t *entryPoint) {
    std::ifstream inputStream(binaryPath, std::ios::binary);
    if (!inputStream) {
        std::cerr << "Unable to open file: " << binaryPath << std::endl;
        return false;
    }

    inputStream.seekg(0, std::ios::end);
    size_t totalSize = inputStream.tellg();
    inputStream.seekg(0, std::ios::beg);

    uint8_t *memoryMap = new uint8_t[totalSize];
    inputStream.read((char *)memoryMap, totalSize);
    inputStream.close();

    struct mach_header_64 *imageHeader = (struct mach_header_64 *)memoryMap;
    if (imageHeader->magic != MH_MAGIC_64) {
        std::cerr << "Invalid Mach-O header: expected 64-bit format." << std::endl;
        delete[] memoryMap;
        return false;
    }

    struct load_command *cmdPtr = (struct load_command *)(memoryMap + sizeof(struct mach_header_64));
    for (uint32_t cmdIndex = 0; cmdIndex < imageHeader->ncmds; cmdIndex++) {
        if (cmdPtr->cmd == LC_SEGMENT_64) {
            struct segment_command_64 *segCmd = (struct segment_command_64 *)cmdPtr;
            if (strcmp(segCmd->segname, "__TEXT") == 0) {
                for (uint32_t sectIndex = 0; sectIndex < segCmd->nsects; sectIndex++) {
                    struct section_64 *sectDesc = (struct section_64 *)((char *)segCmd + sizeof(struct segment_command_64) + sectIndex * sizeof(struct section_64));
                    if (strcmp(sectDesc->sectname, "__text") == 0) {
                        *instructionData = memoryMap + sectDesc->offset;
                        *dataLength = sectDesc->size;
                        *entryPoint = sectDesc->addr;
                        return true;
                    }
                }
            }
        }
        cmdPtr = (struct load_command *)((char *)cmdPtr + cmdPtr->cmdsize);
    }

    delete[] memoryMap;
    return false;
}

int main() {
    uint8_t *codeSegment;
    uint64_t segmentSize, entryAddress;

    if (getTextSection("path/to/your/dylib", &codeSegment, &segmentSize, &entryAddress)) {
        analyzeInstructions(codeSegment, segmentSize, entryAddress);
    } else {
        std::cerr << "PROCESSING_FAILED: Could not locate code segment in binary." << std::endl;
    }

    return 0;
}

