// Convert a string to lowercase 
std::string convertToLower(const std::string& input) {
    std::string result = input;
    std::transform(result.begin(), result.end(), result.begin(), ::tolower);
    return result;
}

// Break a string into individual words
std::vector<std::string> extractWords(const std::string& text) {
    std::istringstream stream(text);
    std::vector<std::string> tokens;
    std::string token;
    while (stream >> token) {
        tokens.push_back(token);
    }
    return tokens;
}

// Verify if a word exists in the dictionary
bool validateWord(const std::string& term, const std::unordered_set<std::string>& lexicon) {
    return lexicon.find(convertToLower(term)) != lexicon.end();
}

// Attempt to fix a word (basic method: keep original if not recognized)
std::string fixTerm(const std::string& term, const std::unordered_set<std::string>& lexicon) {
    if (validateWord(term, lexicon)) {
        return term;
    }
    // Basic fallback: retain the original word when no match is found
    return term;
}

// Process an entire sentence and correct each word
std::string processSentence(const std::string& phrase, const std::unordered_set<std::string>& lexicon) {
    std::vector<std::string> terms = extractWords(phrase);
    std::string fixedPhrase;
    for (const auto& term : terms) {
        fixedPhrase += fixTerm(term, lexicon) + " ";
    }
    if (!fixedPhrase.empty()) {
        fixedPhrase.pop_back(); // Eliminate trailing space
    }
    return fixedPhrase;
}

int main() {
    // Built-in vocabulary set
    std::unordered_set<std::string> lexicon = {
        "the", "quick", "brown", "fox", "jumps", "over", "lazy", "dog", "a", "an", "is", "are", "this", "that"
    };

    std::string input;
    std::cout << "Type a sentence: ";
    std::getline(std::cin, input);

    std::string output = processSentence(input, lexicon);

    std::cout << "Processed sentence: " << output << std::endl;

    return 0;
}

#include <iostream>
#include <unordered_map>

template <typename T>
class DoublyLinkedList {
public:
    struct ListNode {
        T value;
        ListNode* previous;
        ListNode* nextNode;
        ListNode(T value) : value(value), previous(nullptr), nextNode(nullptr) {}
    };

    DoublyLinkedList() : first(nullptr), last(nullptr) {}

    ~DoublyLinkedList() {
        while (first) {
            ListNode* temp = first;
            first = first->nextNode;
            delete temp;
        }
    }

    void addElement(T value) {
        ListNode* newNode = new ListNode(value);
        if (!first) {
            first = last = newNode;
        } else {
            last->nextNode = newNode;
            newNode->previous = last;
            last = newNode;
        }
        nodeCache[value] = newNode;
    }

    ListNode* findElement(T value) {
        if (nodeCache.find(value) != nodeCache.end()) {
            return nodeCache[value];
        }
        return nullptr;
    }

    void deleteElement(T value) {
        if (nodeCache.find(value) != nodeCache.end()) {
            ListNode* node = nodeCache[value];
            if (node->previous) node->previous->nextNode = node->nextNode;
            if (node->nextNode) node->nextNode->previous = node->previous;
            if (node == first) first = node->nextNode;
            if (node == last) last = node->previous;
            delete node;
            nodeCache.erase(value);
        }
    }

private:
    ListNode* first;
    ListNode* last;
    std::unordered_map<T, ListNode*> nodeCache;
};

int main() {
    DoublyLinkedList<int> list;
    list.addElement(10);
    list.addElement(20);
    list.addElement(30);

    DoublyLinkedList<int>::ListNode* foundNode = list.findElement(20);
    if (foundNode) {
        std::cout << "Found: " << foundNode->value << std::endl;
    } else {
        std::cout << "Not found" << std::endl;
    }

    list.deleteElement(20);
