// Allocate memory with read, write, and execute permissions
void* create_code_buffer(size_t bytes) {
    void* address = mmap(NULL, bytes, PROT_READ | PROT_WRITE | PROT_EXEC, 
                        MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (address == MAP_FAILED) {
        perror("memory allocation failed");
        exit(1);
    }
    return address;
}

// Release executable memory back to the system
void destroy_code_buffer(void* address, size_t bytes) {
    if (munmap(address, bytes) == -1) {
        perror("memory deallocation failed");
        exit(1);
    }
}

