struct Point {
    float x, y, z;
};

struct Triangle {
    int p1, p2, p3;
};

std::vector<Point> loadPoints(const std::string& filepath) {
    std::vector<Point> points;
    std::ifstream stream(filepath);
    if (!stream.is_open()) {
        std::cerr << "Error opening file: " << filepath << std::endl;
        return points;
    }

    std::string row;
    while (std::getline(stream, row)) {
        if (row.substr(0, 2) == "v ") {
            Point point;
            std::sscanf(row.c_str(), "v %f %f %f", &point.x, &point.y, &point.z);
            points.push_back(point);
        }
    }
    return points;
}

std::vector<Triangle> loadTriangles(const std::string& filepath) {
    std::vector<Triangle> triangles;
    std::ifstream stream(filepath);
    if (!stream.is_open()) {
        std::cerr << "Error opening file: " << filepath << std::endl;
        return triangles;
    }

    std::string row;
    while (std::getline(stream, row)) {
        if (row.substr(0, 2) == "f ") {
            Triangle triangle;
            std::sscanf(row.c_str(), "f %d %d %d", &triangle.p1, &triangle.p2, &triangle.p3);
            triangles.push_back(triangle);
        }
    }
    return triangles;
}

