// Helper function to compare substrings starting at positions i and j with length p
bool compareSubstrings(const std::string &input, int pos1, int pos2, int len) {
    if (pos1 + len == input.length()) return false;
    if (pos2 + len == input.length()) return true;
    return input[pos1 + len] < input[pos2 + len];
}

// Constructs suffix array using doubling algorithm
std::vector<int> createSuffixArray(const std::string &sequence) {
    int size = sequence.length();
    std::vector<int> suffixes(size);
    for (int idx = 0; idx < size; ++idx) suffixes[idx] = idx;

    std::vector<int> ranks(size);
    for (int idx = 0; idx < size; ++idx) ranks[idx] = sequence[idx];

    for (int step = 1; step < size; step *= 2) {
        std::sort(suffixes.begin(), suffixes.end(), [&](int a, int b) {
            return ranks[a] < ranks[b] || (ranks[a] == ranks[b] && compareSubstrings(sequence, a, b, step));
        });

        std::vector<int> updatedRanks(size);
        updatedRanks[suffixes[0]] = 0;
        for (int idx = 1; idx < size; ++idx) {
            updatedRanks[suffixes[idx]] = updatedRanks[suffixes[idx - 1]] + 
                (compareSubstrings(sequence, suffixes[idx - 1], suffixes[idx], step) ? 1 : 0);
        }
        ranks = updatedRanks;
    }

    return suffixes;
}

// Builds LCP (Longest Common Prefix) array from suffix array
std::vector<int> constructLCP(const std::string &sequence, const std::vector<int> &suffixes) {
    int n = sequence.length();
    std::vector<int> position(n);
    for (int i = 0; i < n; ++i) position[suffixes[i]] = i;

    std::vector<int> lcp(n, 0);
    for (int i = 0, matchLen = 0; i < n; ++i, matchLen = std::max(matchLen - 1, 0)) {
        if (position[i] == n - 1) {
            matchLen = 0;
            continue;
        }
        int nextPos = suffixes[position[i] + 1];
        while (i + matchLen < n && nextPos + matchLen < n && sequence[i + matchLen] == sequence[nextPos + matchLen]) 
            ++matchLen;
        lcp[position[i]] = matchLen;
    }

    return lcp;
}

// Finds the longest common substring among multiple strings
std::string findLongestCommon(const std::vector<std::string> &words) {
    std::string merged = "";
    for (const auto &word : words) {
        merged += word + "#";
    }

    std::vector<int> suffixOrder = createSuffixArray(merged);
    std::vector<int> lcpValues = constructLCP(merged, suffixOrder);

    int bestLength = 0;
    int bestPosition = 0;
    for (int i = 1; i < lcpValues.size(); ++i) {
        if (lcpValues[i] > bestLength) {
            bestLength = lcpValues[i];
            bestPosition = i;
        }
    }

    if (bestLength == 0) return "";

    return merged.substr(suffixOrder[bestPosition], bestLength);
}

int main() {
    std::vector<std::string> testStrings = {"flower", "flow", "flight"};
    std::string commonPart = findLongestCommon(testStrings);
    if (commonPart.empty()) {
        std::cout << "No common substring detected." << std::endl;
    } else {
        std::cout << "Longest shared substring: " << commonPart << std::endl;
    }
    return 0;
}

