// Convert 64-bit value to network byte order (big-endian)
uint64_t htonll(uint64_t input) {
    static const bool isLittle = (1 == *(uint8_t *)&(uint32_t){1});
    if (isLittle) {
        return ((uint64_t)htonl((uint32_t)(input & 0xFFFFFFFF)) << 32) |
               htonl((uint32_t)(input >> 32));
    }
    return input;
}

// Convert 64-bit value from network byte order (big-endian)
uint64_t ntohll(uint64_t input) {
    static const bool isLittle = (1 == *(uint8_t *)&(uint32_t){1});
    if (isLittle) {
        return ((uint64_t)ntohl((uint32_t)(input & 0xFFFFFFFF)) << 32) |
               ntohl((uint32_t)(input >> 32));
    }
    return input;
}

