// Vector subtraction operation
std::array<double, 3> operator-(const std::array<double, 3>& vec1, const std::array<double, 3>& vec2) {
    return {vec1[0] - vec2[0], vec1[1] - vec2[1], vec1[2] - vec2[2]};
}

// Dot product calculation
double dotProduct(const std::array<double, 3>& first, const std::array<double, 3>& second) {
    return first[0] * second[0] + first[1] * second[1] + first[2] * second[2];
}

// Magnitude (length) of a vector
double magnitude(const std::array<double, 3>& input) {
    return std::sqrt(dotProduct(input, input));
}

// Normalize a vector to unit length
std::array<double, 3> unitVector(const std::array<double, 3>& original) {
    double len = magnitude(original);
    return {original[0] / len, original[1] / len, original[2] / len};
}

// Rectangular box representation
class Box {
public:
    Box(const std::array<double, 3>& centerPos, const double size)
        : _center(centerPos), _size(size) {}

    std::array<double, 3> getCenter() const { return _center; }
    double minimum(const unsigned int axis) const { return _center[axis] - _size / 2.0; }
    double maximum(const unsigned int axis) const { return _center[axis] + _size / 2.0; }
    double getSize() const { return _size; }

private:
    std::array<double, 3> _center;
    double _size;
};

// Conical shape definition
class Funnel {
public:
    Funnel(const std::array<double, 3>& tip, const std::array<double, 3>& bottom, const double angleSize)
        : _tip(tip), _bottom(bottom), _angle(angleSize) {}

    std::array<double, 3> getTip() const { return _tip; }
    std::array<double, 3> getBottom() const { return _bottom; }
    double getAngle() const { return _angle; }
    double getLength() const { return magnitude(_tip - _bottom); }
    double getBaseRadius() const { return std::tan(_angle) * getLength(); }

private:
    std::array<double, 3> _tip;
    std::array<double, 3> _bottom;
    double _angle;
};

// Determine if a point lies within the conical region
bool pointInFunnel(const Funnel& funnel, const std::array<double, 3>& testPoint) {
    std::array<double, 3> v = funnel.getTip();
    std::array<double, 3> b = funnel.getBottom();
    std::array<double, 3> direction = unitVector(b - v);
    double h = funnel.getLength();
    double r = funnel.getBaseRadius();
    double projection = dotProduct(testPoint - v, direction);

    if (projection < 0 || projection > h) return false;

    std::array<double, 3> closestPointOnAxis = v + projection * direction;
    double perpendicularDistance = magnitude(testPoint - closestPointOnAxis);

    return perpendicularDistance <= r * projection / h;
}

// Test for overlap between box and funnel
bool checkIntersection(const Box& box, const Funnel& funnel) {
    // Examine all 8 corner points of the box
    for (int i = 0; i < 2; ++i) {
        for (int j = 0; j < 2; ++j) {
            for (int k = 0; k < 2; ++k) {
                std::array<double, 3> corner = {
                    box.minimum(0) + i * box.getSize(),
                    box.minimum(1) + j * box.getSize(),
                    box.minimum(2) + k * box.getSize()
                };
                if (pointInFunnel(funnel, corner)) return true;
            }
        }
    }

    // Check edges of the box
    for (int i = 0; i < 2; ++i) {
        for (int j = 0; j < 2; ++j) {
            for (int k = 0; k < 2; ++k) {
                std::array<double, 3> p1 = {
                    box.minimum(0) + i * box.getSize(),
                    box.minimum(1) + j * box.getSize(),
                    box.minimum(2) + k * box.getSize()
                };
                for (int dim = 0; dim < 3; ++dim) {
                    int nextDim = (dim + 1) % 3;
                    std::array<double, 3> p2 = p1;
                    p2[dim] += (i == 0 ? box.getSize() : -box.getSize());
                    if (pointInFunnel(funnel, p2)) return true;
                    if (pointInFunnel(funnel, {(p1[0] + p2[0])/2.0, (p1[1] + p2[1])/2.0, (p1[2] + p2[2])/2.0})) return true;
                }
            }
        }
    }

    // Examine faces of the box
    for (int i = 0; i < 2; ++i) {
        for (int j = 0; j < 2; ++j) {
            for (int k = 0; k < 2; ++k) {
                std::array<double, 3> p1 = {
                    box.minimum(0) + i * box.getSize(),
                    box.minimum(1) + j * box.getSize(),
                    box.minimum(2) + k * box.getSize()
                };
                for (int dim = 0; dim < 3; ++dim) {
                    int nextDim = (dim + 1) % 3;
                    std::array<double, 3> p2 = p1;
                    p2[dim] += (i == 0 ? box.getSize() : -box.getSize());
                    std::array<double, 3> p3 = p1;
                    p3[nextDim] += (j == 0 ? box.getSize() : -box.getSize());
                    std::array<double, 3> p4 = p2;
                    p4[nextDim] += (j == 0 ? box.getSize() : -box.getSize());
                    if (pointInFunnel(funnel, {(p1[0]+p2[0]+p3[0]+p4[0])/4.0, (p1[1]+p2[1]+p3[1]+p4[1])/4.0, (p1[2]+p2[2]+p3[2]+p4[2])/4.0})) return true;
                }
            }
        }
    }

    return false;
}

int main() {
    Box box({0.0, 0.0, 0.0}, 2.0);
    Funnel funnel({0.0, 0.0, 5.0}, {0.0, 0.0, 0.0}, M_PI / 4.0);

    if (checkIntersection(box, funnel)) {
        std::cout << "The box and funnel intersect." << std::endl;
    } else {
        std::cout << "The box and funnel do not intersect." << std::endl;
    }

    return 0;
}

