// Compute the average of a list of integers
double average(const std::vector<int>& values) {
    if (values.empty()) {  // Handle empty input case
        return 0.0;
    }
    int accumulator = 0;
    for (int value : values) {
        accumulator += value;
    }
    return static_cast<double>(accumulator) / values.size();
}

