// A priority queue implementation using a linked list
class PriorityQueue {
public:
    PriorityQueue();
    ~PriorityQueue();
    void insert(int data, int priorityLevel);
    int remove();
    bool empty() const;
    void print() const;
private:
    struct Element {
        int data;
        int priorityLevel;
        Element* next;
    };
    Element* head;
};

PriorityQueue::PriorityQueue() {
    head = nullptr;
}

PriorityQueue::~PriorityQueue() {
    while (!empty()) {
        remove();
    }
}

void PriorityQueue::insert(int data, int priorityLevel) {
    Element* newElement = new Element;
    newElement->data = data;
    newElement->priorityLevel = priorityLevel;
    newElement->next = nullptr;

    if (empty() || priorityLevel > head->priorityLevel) {
        newElement->next = head;
        head = newElement;
    } else {
        Element* current = head;
        while (current->next != nullptr && current->next->priorityLevel >= priorityLevel) {
            current = current->next;
        }
        newElement->next = current->next;
        current->next = newElement;
    }
}

int PriorityQueue::remove() {
    if (empty()) {
        throw "The priority queue is empty, cannot remove.";
    }

    Element* temp = head;
    int value = head->data;
    head = head->next;
    delete temp;
    return value;
}

bool PriorityQueue::empty() const {
    return head == nullptr;
}

void PriorityQueue::print() const {
    Element* temp = head;
    while (temp != nullptr) {
        std::cout << temp->data << " (priority: " << temp->priorityLevel << ") -> ";
        temp = temp->next;
    }
    std::cout << "end" << std::endl;
}

int main() {
    PriorityQueue pq;

    pq.insert(10, 3);
    pq.insert(5, 1);
    pq.insert(3, 4);
    pq.insert(20, 2);

    pq.print();

    std::cout << "Removed: " << pq.remove() << std::endl;
    std::cout << "Removed: " << pq.remove() << std::endl;

    pq.print();

    return 0;
}

