#include <vector>
#include <stdexcept>
#include <iostream>

class MultiDimensionalArray {
public:
    MultiDimensionalArray(const std::vector<int>& sizes) : dimensions_(sizes) {
        if (sizes.empty() || sizes.size() > 10) {
            throw std::invalid_argument("Number of dimensions must be between 1 and 10.");
        }
        for (int size : sizes) {
            if (size <= 0) {
                throw std::invalid_argument("Each dimension size must be greater than zero.");
            }
        }
        allocateStorage();
    }

    int& operator[](const std::vector<int>& coords) {
        if (coords.size() != dimensions_.size()) {
            throw std::out_of_range("Coordinate vector length does not match array dimensions.");
        }
        for (int i = 0; i < coords.size(); ++i) {
            if (coords[i] < 0 || coords[i] >= dimensions_[i]) {
                throw std::out_of_range("Coordinate value exceeds array bounds.");
            }
        }
        return storage_[computeOffset(coords)];
    }

    const int& operator[](const std::vector<int>& coords) const {
        if (coords.size() != dimensions_.size()) {
            throw std::out_of_range("Coordinate vector length does not match array dimensions.");
        }
        for (int i = 0; i < coords.size(); ++i) {
            if (coords[i] < 0 || coords[i] >= dimensions_[i]) {
                throw std::out_of_range("Coordinate value exceeds array bounds.");
            }
        }
        return storage_[computeOffset(coords)];
    }

private:
    std::vector<int> dimensions_;
    std::vector<int> storage_;
    std::vector<int> stepSizes_;

    void allocateStorage() {
        int capacity = 1;
        for (int dim : dimensions_) {
            capacity *= dim;
        }
        storage_.assign(capacity, 0);

        stepSizes_.resize(dimensions_.size());
        stepSizes_.back() = 1;
        for (int pos = dimensions_.size() - 2; pos >= 0; --pos) {
            stepSizes_[pos] = stepSizes_[pos + 1] * dimensions_[pos + 1];
        }
    }

    int computeOffset(const std::vector<int>& coords) const {
        int offset = 0;
        for (size_t k = 0; k < coords.size(); ++k) {
            offset += coords[k] * stepSizes_[k];
        }
        return offset;
    }
};

int main() {
    try {
        MultiDimensionalArray matrix({3, 4, 2}); // Create a 3x4x2 array

        // Set and retrieve an element
        matrix[{1, 2, 1}] = 99;
        std::cout << "Value at position (1, 2, 1): " << matrix[{1, 2, 1}] << std::endl;

        // Attempt invalid access to trigger exception
        matrix[{3, 2, 1}];
    } catch (const std::exception& err) {
        std::cerr << "Exception caught: " << err.what() << std::endl;
    }

    return 0;
}

