class BinaryNode {
public:
    int data;
    BinaryNode* leftChild;
    BinaryNode* rightChild;

    BinaryNode(int inputValue) : data(inputValue), leftChild(nullptr), rightChild(nullptr) {}
};

class BinarySearchTree {
public:
    BinaryNode* head;

    BinarySearchTree() : head(nullptr) {}

    void addElement(int inputValue) {
        head = insertIntoTree(head, inputValue);
    }

    BinaryNode* insertIntoTree(BinaryNode* current, int inputValue) {
        if (current == nullptr) {
            return new BinaryNode(inputValue);
        }

        if (inputValue < current->data) {
            current->leftChild = insertIntoTree(current->leftChild, inputValue);
        } else {
            current->rightChild = insertIntoTree(current->rightChild, inputValue);
        }

        return current;
    }

    bool locate(int inputValue) {
        return searchInTree(head, inputValue);
    }

    bool searchInTree(BinaryNode* current, int inputValue) {
        if (current == nullptr) {
            return false;
        }

        if (inputValue == current->data) {
            return true;
        } else if (inputValue < current->data) {
            return searchInTree(current->leftChild, inputValue);
        } else {
            return searchInTree(current->rightChild, inputValue);
        }
    }

    void erase(int inputValue) {
        head = deleteFromTree(head, inputValue);
    }

    BinaryNode* deleteFromTree(BinaryNode* current, int inputValue) {
        if (current == nullptr) {
            return nullptr;
        }

        if (inputValue < current->data) {
            current->leftChild = deleteFromTree(current->leftChild, inputValue);
        } else if (inputValue > current->data) {
            current->rightChild = deleteFromTree(current->rightChild, inputValue);
        } else {
            if (current->leftChild == nullptr && current->rightChild == nullptr) {
                delete current;
                return nullptr;
            } else if (current->leftChild == nullptr) {
                BinaryNode* holder = current->rightChild;
                delete current;
                return holder;
            } else if (current->rightChild == nullptr) {
                BinaryNode* holder = current->leftChild;
                delete current;
                return holder;
            } else {
                BinaryNode* smallestNode = findMinimum(current->rightChild);
                current->data = smallestNode->data;
                current->rightChild = deleteFromTree(current->rightChild, smallestNode->data);
            }
        }

        return current;
    }

    BinaryNode* findMinimum(BinaryNode* current) {
        if (current->leftChild != nullptr) {
            return findMinimum(current->leftChild);
        } else {
            return current;
        }
    }

    void displayInOrder() {
        traverseInorder(head);
    }

    void traverseInorder(BinaryNode* current) {
        if (current != nullptr) {
            traverseInorder(current->leftChild);
            cout << current->data << " ";
            traverseInorder(current->rightChild);
        }
    }
};

int main() {
    BinarySearchTree bst;

    bst.addElement(5);
    bst.addElement(3);
    bst.addElement(8);
    bst.addElement(2);
    bst.addElement(4);
    bst.addElement(7);
    bst.addElement(9);

    cout << "Inorder traversal: ";
    bst.displayInOrder();
    cout << endl;

    cout << "Search 5: " << (bst.locate(5) ? "found" : "not found") << endl;
    cout << "Search 10: " << (bst.locate(10) ? "found" : "not found") << endl;

    bst.erase(3);

    cout << "Inorder traversal after removing 3: ";
    bst.displayInOrder();
    cout << endl;

    return 0;
}

