// Determine if a number is prime using optimized trial division
bool checkPrime(long long value) {
    if (value <= 1) return false;
    if (value <= 3) return true;
    if (value % 2 == 0 || value % 3 == 0) return false;
    for (long long j = 5; j * j <= value; j += 6) {
        if (value % j == 0 || value % (j + 2) == 0) return false;
    }
    return true;
}

// Handle a segment of numbers to identify primes
void handleSegment(long long lower, long long upper, long long limit, std::mutex& outputMutex, std::ofstream& outputFile, std::atomic<long long>& foundCount) {
    for (long long candidate = lower; candidate <= upper; ++candidate) {
        if (checkPrime(candidate)) {
            if (foundCount++ >= limit) {
                std::lock_guard<std::mutex> guard(outputMutex);
                outputFile << candidate << std::endl;
            } else {
                std::cout << candidate << std::endl;
            }
        }
    }
}

int main() {
    long long beginRange, finishRange, fileLimit;
    int threadCount;

    std::cout << "Specify the starting value: ";
    std::cin >> beginRange;
    std::cout << "Specify the ending value: ";
    std::cin >> finishRange;
    std::cout << "Specify the threshold for file output: ";
    std::cin >> fileLimit;
    std::cout << "Specify the number of threads to use: ";
    std::cin >> threadCount;

    std::vector<std::thread> workerThreads;
    std::mutex ioMutex;
    std::ofstream resultFile("prime_results.txt");
    std::atomic<long long> totalFound(0);

    long long segmentSize = (finishRange - beginRange + 1) / threadCount;
    long long extraItems = (finishRange - beginRange + 1) % threadCount;

    long long segmentStart = beginRange;
    for (int idx = 0; idx < threadCount; ++idx) {
        long long segmentEnd = segmentStart + segmentSize - 1;
        if (idx == threadCount - 1) {
            segmentEnd += extraItems;
        }
        workerThreads.emplace_back(handleSegment, segmentStart, segmentEnd, fileLimit, std::ref(ioMutex), std::ref(resultFile), std::ref(totalFound));
        segmentStart = segmentEnd + 1;
    }

    for (auto& worker : workerThreads) {
        worker.join();
    }

    resultFile.close();
    std::cout << "Operation finished. Prime numbers exceeding the limit are saved in prime_results.txt." << std::endl;

    return 0;
}

