class WrapperClass
{
public:
    WrapperClass(ManagedReference^ ref) : _managedRef(ref) {}
    void PerformOperation() { _managedRef->PerformOperation(); }
    ~WrapperClass() { _managedRef->ReleaseResources(); }

private:
    ManagedReference^ _managedRef;
};

class ManagedReference
{
public:
    virtual void PerformOperation() = 0;
    virtual void ReleaseResources() = 0;
};

class DotNetHost
{
public:
    DotNetHost()
    {
        HRESULT hr = CLRCreateInstance(CLSID_CLRMetaHost, IID_ICLRMetaHost, (LPVOID*)&_metaHost);
        if (FAILED(hr)) throw std::runtime_error("Failed to create CLRMetaHost");

        hr = _metaHost->GetRuntime(L"v4.0.30319", IID_ICLRRuntimeInfo, (LPVOID*)&_runtimeInfo);
        if (FAILED(hr)) throw std::runtime_error("Failed to get runtime info");

        BOOL isLoadable = FALSE;
        hr = _runtimeInfo->IsLoadable(&isLoadable);
        if (FAILED(hr) || !isLoadable) throw std::runtime_error("Runtime is not loadable");

        hr = _runtimeInfo->GetInterface(CLSID_CLRRuntimeHost, IID_ICLRRuntimeHost, (LPVOID*)&_runtimeHost);
        if (FAILED(hr)) throw std::runtime_error("Failed to get runtime host");

        hr = _runtimeHost->Start();
        if (FAILED(hr)) throw std::runtime_error("Failed to start runtime");

        hr = _runtimeHost->GetCLRControl(&_clrControl);
        if (FAILED(hr)) throw std::runtime_error("Failed to get CLR control");

        hr = _clrControl->GetHostControl(&_hostControl);
        if (FAILED(hr)) throw std::runtime_error("Failed to get host control");

        hr = _hostControl->QueryInterface(IID_IHostControl, (LPVOID*)&_hostControl);
        if (FAILED(hr)) throw std::runtime_error("Failed to query host control");

        hr = _runtimeHost->ExecuteInDefaultAppDomain(L"ManagedLibrary.dll", L"ManagedLibrary.WrapperClass", L"Initialize", L"", &_managedInstance);
        if (FAILED(hr)) throw std::runtime_error("Failed to execute in default app domain");
    }

    ~DotNetHost()
    {
        _runtimeHost->Stop();
        _runtimeHost->Release();
        _runtimeInfo->Release();
        _metaHost->Release();
    }

    void ExecuteTask()
    {
        HRESULT hr = _runtimeHost->ExecuteInDefaultAppDomain(L"ManagedLibrary.dll", L"ManagedLibrary.WrapperClass", L"PerformOperation", L"", nullptr);
        if (FAILED(hr)) throw std::runtime_error("Failed to execute task");
    }

private:
    ICLRMetaHost* _metaHost;
    ICLRRuntimeInfo* _runtimeInfo;
    ICLRRuntimeHost* _runtimeHost;
    ICLRControl* _clrControl;
    IHostControl* _hostControl;
    _variant_t _managedInstance;
};

int main()
{
    try
    {
        DotNetHost host;
        host.ExecuteTask();
    }
    catch (const std::exception& ex)
    {
        std::cerr << "Error occurred: " << ex.what() << std::endl;
    }

    return 0;
}

