    NewObjectEvent(wxEventType kind = wxEVT_NULL, int identifier = 0)
        : wxEvent(identifier, kind) {}

    // Method to store the newly created object
    void AssignNewObject(Object* freshObject) { m_newlyCreated = freshObject; }

    // Method to retrieve the stored object
    Object* RetrieveNewObject() const { return m_newlyCreated; }

