};

#include <iostream>
#include <cmath>

// Determine whether a given integer is prime
bool checkPrime(int value) {
    if (value <= 1) {
        return false; // Values less than 2 are not prime
    }
    if (value == 2) {
        return true; // Two is the sole even prime
    }
    if (value % 2 == 0) {
        return false; // Eliminate remaining even numbers
    }
    // Test odd divisors up to the square root of the value
    for (int divisor = 3; divisor <= std::sqrt(value); divisor += 2) {
        if (value % divisor == 0) {
            return false;
        }
    }
    return true;
}

int main() {
    std::cout << "List of prime numbers from 1 to 100:" << std::endl;
    for (int number = 1; number <= 100; ++number) {
        if (checkPrime(number)) {
            std::cout << number << " ";
        }
    }
    std::cout << std::endl;
    return 0;
}

#include <rocksdb/db.h>
#include <rocksdb/options.h>
#include <string>
#include <iostream>

class Person {
public:
    std::string userId;
    std::string fullName;
    int years;

    std::string pack() const {
        return userId + "|" + fullName + "|" + std::to_string(years);
    }

    static Person unpack(const std::string& record) {
        Person person;
        size_t first = record.find('|');
        size_t second = record.find('|', first + 1);
        person.userId = record.substr(0, first);
        person.fullName = record.substr(first + 1, second - first - 1);
        person.years = std::stoi(record.substr(second + 1));
        return person;
    }
};

class PersonStore {
private:
    rocksdb::DB* database;
    rocksdb::Options settings;

public:
    PersonStore(const std::string& location) {
        settings.create_if_missing = true;
        rocksdb::Status result = rocksdb::DB::Open(settings, location, &database);
        if (!result.ok()) {
            std::cerr << "Failed to open database: " << result.ToString() << std::endl;
        }
    }

    ~PersonStore() {
        delete database;
    }

    rocksdb::Status add(const Person& individual) {
        return database->Put(rocksdb::WriteOptions(), individual.userId, individual.pack());
    }

    rocksdb::Status modify(const Person& individual) {
        return database->Put(rocksdb::WriteOptions(), individual.userId, individual.pack());
    }

    rocksdb::Status erase(const std::string& identifier) {
        return database->Delete(rocksdb::WriteOptions(), identifier);
    }

    rocksdb::Status fetch(const std::string& identifier, Person& individual) {
        std::string data;
        rocksdb::Status status = database->Get(rocksdb::ReadOptions(), identifier, &data);
        if (status.ok()) {
            individual = Person::unpack(data);
        }
        return status;
    }
};

int main() {
    PersonStore store("path/to/db");

    Person person1;
    person1.userId = "1";
    person1.fullName = "Alice";
    person1.years = 30;

    store.add(person1);

    Person person2;
    store.fetch("1", person2);
    std::cout << "Record retrieved: " << person2.fullName << " (age: " << person2.years << ")" << std::endl;

    person2.fullName = "Alice Smith";
    store.modify(person2);

    store.erase("1");

    return 0;
}

#include <iostream>
#include <string>
#include <tensorflow/c/c_api.h>

// Function to load the TensorFlow model from file
TF_Graph* LoadGraph(const char* model_file) {
    TF_Graph* graph = TF_NewGraph();
    TF_Status* status = TF_NewStatus();
    TF_SessionOptions* session_opts = TF_NewSessionOptions();

    TF_Buffer* graph_buf = TF_NewBuffer();
    TF_ReadFileToBuffer(TF_NewSessionOptions(), model_file, graph_buf, status);
    if (TF_GetCode(status) != TF_OK) {
        std::cerr << "Failed to load model: " << TF_Message(status) << std::endl;
        TF_DeleteStatus(status);
        return nullptr;
    }

    TF_ImportGraphDefOptions* import_opts = TF_NewImportGraphDefOptions();
    TF_GraphImportGraphDef(graph, graph_buf, import_opts, status);
    if (TF_GetCode(status) != TF_OK) {
        std::cerr << "Graph import failed: " << TF_Message(status) << std::endl;
        TF_DeleteStatus(status);
        return nullptr;
    }

    TF_DeleteBuffer(graph_buf);
    TF_DeleteImportGraphDefOptions(import_opts);
    TF_DeleteStatus(status);
    return graph;
}

// Function to perform sentiment analysis using the loaded model
void ExecuteSentimentPrediction(TF_Graph* model_graph, const char* user_text) {
    TF_SessionOptions* session_opts = TF_NewSessionOptions();
    TF_Status* status = TF_NewStatus();
    TF_Session* session = TF_NewSession(model_graph, session_opts, status);

    if (TF_GetCode(status) != TF_OK) {
        std::cerr << "Session creation error: " << TF_Message(status) << std::endl;
        TF_DeleteSession(session, status);
        TF_DeleteSessionOptions(session_opts);
        TF_DeleteStatus(status);
        return;
    }

    // Define input and output operation names
    const char* input_op_name = "input_placeholder:0";
    const char* output_op_name = "output_result:0";

    TF_Output input_operation = {TF_GraphOperationByName(model_graph, input_op_name), 0};
    TF_Output output_operation = {TF_GraphOperationByName(model_graph, output_op_name), 0};

    // Create tensor for input string
    TF_Tensor* input_data = TF_NewTensor(TF_STRING, nullptr, 0, &user_text, sizeof(user_text), nullptr, nullptr);

    // Prepare inputs and outputs for session run
    std::vector<TF_Output> input_ops = {input_operation};
    std::vector<TF_Tensor*> input_values = {input_data};
    std::vector<TF_Output> output_ops = {output_operation};
    std::vector<TF_Tensor*> output_values(1);

    TF_SessionRun(session, nullptr, &input_ops[0], &input_values[0], 1, &output_ops[0], &output_values[0], 1, nullptr, 0, nullptr, status);

    if (TF_GetCode(status) != TF_OK) {
        std::cerr << "Session execution error: " << TF_Message(status) << std::endl;
        TF_DeleteSession(session, status);
        TF_DeleteSessionOptions(session_opts);
        TF_DeleteStatus(status);
        return;
    }

    // Extract and interpret results
    float* result_data = static_cast<float*>(TF_TensorData(output_values[0]));
    int result_length = TF_TensorByteSize(output_values[0]) / sizeof(float);

    std::string classification = (result_data[0] > 0.5f) ? "Positive" : "Negative";
    std::cout << "Analysis Result: " << classification << std::endl;

    // Release resources
    TF_DeleteTensor(input_data);
    TF_DeleteTensor(output_values[0]);
    TF_DeleteSession(session, status);
    TF_DeleteSessionOptions(session_opts);
    TF_DeleteStatus(status);
}

int main() {
    const char* model_location = "path_to_your_model.pb";
    const char* sample_text = "I love this product!";

    TF_Graph* model_graph = LoadGraph(model_location);
    if (model_graph) {
        ExecuteSentimentPrediction(model_graph, sample_text);
        TF_DeleteGraph(model_graph);
    }

    return 0;
}

