#include <vector>

class TicTacToeGame {
public:
    TicTacToeGame() {
        grid = std::vector<std::vector<char>>(3, std::vector<char>(3, ' '));
        activePlayer = 'X';
    }

    void showGrid() const {
        for (int row = 0; row < 3; ++row) {
            for (int col = 0; col < 3; ++col) {
                std::cout << grid[row][col];
                if (col < 2) std::cout << " | ";
            }
            std::cout << std::endl;
            if (row < 2) std::cout << "---------" << std::endl;
        }
    }

    bool placeMark(int r, int c) {
        if (r < 0 || r >= 3 || c < 0 || c >= 3 || grid[r][c] != ' ') {
            return false; // Invalid position
        }
        grid[r][c] = activePlayer;
        switchTurn();
        return true;
    }

    char determineResult() const {
        // Check rows and columns
        for (int k = 0; k < 3; ++k) {
            if (grid[k][0] == grid[k][1] && grid[k][1] == grid[k][2] && grid[k][0] != ' ') {
                return grid[k][0]; // Winner in row
            }
            if (grid[0][k] == grid[1][k] && grid[1][k] == grid[2][k] && grid[0][k] != ' ') {
                return grid[0][k]; // Winner in column
            }
        }

        // Check diagonals
        if (grid[0][0] == grid[1][1] && grid[1][1] == grid[2][2] && grid[0][0] != ' ') {
            return grid[0][0]; // Winner in diagonal
        }
        if (grid[0][2] == grid[1][1] && grid[1][1] == grid[2][0] && grid[0][2] != ' ') {
            return grid[0][2]; // Winner in diagonal
        }

        // Check for draw
        for (int i = 0; i < 3; ++i) {
            for (int j = 0; j < 3; ++j) {
                if (grid[i][j] == ' ') {
                    return ' '; // Game is not over
                }
            }
        }

        return 'T'; // Tie
    }

private:
    std::vector<std::vector<char>> grid;
    char activePlayer;

    void switchTurn() {
        activePlayer = (activePlayer == 'X') ? 'O' : 'X';
    }
};

int main() {
    TicTacToeGame match;
    match.showGrid();

    // Example moves
    match.placeMark(0, 0);
    match.placeMark(1, 1);
    match.placeMark(0, 1);
    match.placeMark(1, 2);
    match.placeMark(0, 2);

    match.showGrid();

    char outcome = match.determineResult();
    if (outcome == 'X' || outcome == 'O') {
        std::cout << "Player " << outcome << " wins!" << std::endl;
    } else if (outcome == 'T') {
        std::cout << "The game is a tie!" << std::endl;
    } else {
        std::cout << "The game is still ongoing!" << std::endl;
    }

    return 0;
}

