#include <iostream>
#include <cmath>

struct Vec3 {
    float a, b, c;

    Vec3(float valA = 0.0f, float valB = 0.0f, float valC = 0.0f)
        : a(valA), b(valB), c(valC) { }

    // Normalize the vector
    Vec3& normalize() {
        float len = std::sqrt(a * a + b * b + c * c);
        a /= len;
        b /= len;
        c /= len;
        return *this;
    }

    // Multiply the vector by a scalar value
    Vec3 operator*(float factor) const {
        return Vec3(a * factor, b * factor, c * factor);
    }

    // Add two vectors together
    Vec3 operator+(const Vec3& rhs) const {
        return Vec3(a + rhs.a, b + rhs.b, c + rhs.c);
    }

    // Subtract a vector from another vector
    Vec3 operator-(const Vec3& rhs) const {
        return Vec3(a - rhs.a, b - rhs.b, c - rhs.c);
    }

    // Dot product of two vectors
    float dot(const Vec3& other) const {
        return a * other.a + b * other.b + c * other.c;
    }
};

// Function to transform a vector using Euler angles (in degrees)
Vec3 applyRotation(const Vec3& inputVec, const Vec3& rotationAngles) {
    float rotX = rotationAngles.a * (3.14159265359f / 180.0f);
    float rotY = rotationAngles.b * (3.14159265359f / 180.0f);
    float rotZ = rotationAngles.c * (3.14159265359f / 180.0f);

    float sinA = std::sin(rotX);
    float cosA = std::cos(rotX);
    float sinB = std::sin(rotY);
    float cosB = std::cos(rotY);
    float sinC = std::sin(rotZ);
    float cosC = std::cos(rotZ);

    Vec3 result;

    result.a = inputVec.a * (cosB * cosC) + inputVec.b * (sinA * sinB * cosC - cosA * sinC) + inputVec.c * (cosA * sinB * cosC + sinA * sinC);
    result.b = inputVec.a * (cosB * sinC) + inputVec.b * (sinA * sinB * sinC + cosA * cosC) + inputVec.c * (cosA * sinB * sinC - sinA * cosC);
    result.c = inputVec.a * (-sinB) + inputVec.b * (sinA * cosB) + inputVec.c * (cosA * cosB);

    return result;
}

int main() {
    Vec3 origin(0, 0, 0);
    Vec3 rotation(-5, -15, 25);

    Vec3 directionVector(0, 0, 1);
    Vec3 rotatedVector = applyRotation(directionVector, rotation);

    std::cout << "'One step forward' vector is (" << rotatedVector.a << ", "
              << rotatedVector.b << ", " << rotatedVector.c << ")\n";

    return 0;
}

#include <iostream>
