// Determine if a given integer is a prime number
bool checkPrime(int value) {
    if (value <= 1) return false;
    if (value <= 3) return true;
    if (value % 2 == 0 || value % 3 == 0) return false;
    for (int j = 5; j * j <= value; j += 6) {
        if (value % j == 0 || value % (j + 2) == 0) return false;
    }
    return true;
}

// Compute the sum of all digits in a positive integer
int digitSum(int value) {
    int result = 0;
    while (value > 0) {
        result += value % 10;
        value /= 10;
    }
    return result;
}

// Identify the greatest prime in the vector and return the sum of its digits
int maxPrimeDigitSum(std::vector<int> &data) {
    int largestPrime = -1;
    for (int element : data) {
        if (checkPrime(element) && element > largestPrime) {
            largestPrime = element;
        }
    }
    return largestPrime != -1 ? digitSum(largestPrime) : 0;
}

