#include <windows.h>
#include <stdio.h>

// Determine if the current process has elevated privileges and UAC settings
BOOL CheckElevationAndUacStatus() {
    HANDLE hAccessToken;
    TOKEN_ELEVATION ElevationInfo;
    DWORD dwBufferSize = sizeof(TOKEN_ELEVATION);

    // Retrieve the access token for the current process
    if (!OpenProcessToken(GetCurrentProcess(), TOKEN_QUERY, &hAccessToken)) {
        printf("Failed to open process token. Error: %u\n", GetLastError());
        return FALSE;
    }

    // Query token elevation details
    if (!GetTokenInformation(hAccessToken, TokenElevation, &ElevationInfo, sizeof(ElevationInfo), &dwBufferSize)) {
        printf("Failed to retrieve token information. Error: %u\n", GetLastError());
        CloseHandle(hAccessToken);
        return FALSE;
    }

    // Report elevation status
    if (ElevationInfo.TokenIsElevated) {
        printf("Process is running with elevated privileges.\n");
    } else {
        printf("Process is not running with elevated privileges.\n");
    }

    // Examine UAC policy configuration
    HKEY hRegistryKey;
    if (RegOpenKeyEx(HKEY_LOCAL_MACHINE, TEXT("SOFTWARE\\Microsoft\\Windows\\CurrentVersion\\Policies\\System"), 0, KEY_READ, &hRegistryKey) == ERROR_SUCCESS) {
        DWORD dwEnableLUAValue;
        DWORD dwValueSize = sizeof(DWORD);
        if (RegQueryValueEx(hRegistryKey, TEXT("EnableLUA"), NULL, NULL, (LPBYTE)&dwEnableLUAValue, &dwValueSize) == ERROR_SUCCESS) {
            if (dwEnableLUAValue == 1) {
                printf("User Account Control (UAC) is active.\n");
            } else {
                printf("User Account Control (UAC) is inactive.\n");
            }
        }
        RegCloseKey(hRegistryKey);
    }

    CloseHandle(hAccessToken);

    // Note: This function assesses elevation and UAC, not code signing enforcement directly.
    return ElevationInfo.TokenIsElevated;
}

int main() {
    if (CheckElevationAndUacStatus()) {
        printf("Code signing enforcement is probably enforced.\n");
    } else {
        printf("Code signing enforcement is probably not enforced.\n");
    }
    return 0;
}

