#include <iostream>
using namespace std;

// Define the Node structure
struct Element {
    int value;
    Element* link;
};

// Function to create a new node
Element* generateNode(int val) {
    Element* newNode = new Element();
    if (!newNode) {
        cout << "Memory allocation failed\n";
        return NULL;
    }
    newNode->value = val;
    newNode->link = NULL;
    return newNode;
}

// Function to insert a new node at the beginning of the list
void prependNode(Element** start, int val) {
    Element* newNode = generateNode(val);
    newNode->link = *start;
    *start = newNode;
}

// Function to insert a new node at the end of the list
void appendNode(Element** start, int val) {
    Element* newNode = generateNode(val);
    if (*start == NULL) {
        *start = newNode;
        return;
    }
    Element* current = *start;
    while (current->link != NULL) {
        current = current->link;
    }
    current->link = newNode;
}

// Function to insert a new node at a specific position in the list
void insertAt(Element** start, int val, int pos) {
    if (pos == 1) {
        prependNode(start, val);
        return;
    }
    Element* newNode = generateNode(val);
    Element* current = *start;
    for (int idx = 1; current != NULL && idx < pos - 1; idx++) {
        current = current->link;
    }
    if (current == NULL) {
        cout << "Invalid position\n";
        return;
    }
    newNode->link = current->link;
    current->link = newNode;
}

// Function to print the list
void displayList(Element* start) {
    Element* current = start;
    while (current != NULL) {
        cout << current->value << " ";
        current = current->link;
    }
    cout << endl;
}

// Function to delete a node from the list
void removeNode(Element** start, int target) {
    Element* current = *start, *previous = NULL;
    if (current != NULL && current->value == target) {
        *start = current->link;
        delete current;
        return;
    }
    while (current != NULL && current->value != target) {
        previous = current;
        current = current->link;
    }
    if (current == NULL) {
        cout << "Value not found\n";
        return;
    }
    previous->link = current->link;
    delete current;
}

// Main function
int main() {
    Element* head = NULL;

    appendNode(&head, 10);
    appendNode(&head, 20);
    prependNode(&head, 5);
    insertAt(&head, 15, 2);

    cout << "Linked list: ";
    displayList(head);

    removeNode(&head, 15);
    cout << "After removing 15: ";
    displayList(head);

    return 0;
}

