#include <iostream>
#include <unordered_set>

struct TreeNode {
    int data;
    TreeNode* link; // XOR of left and right child

    TreeNode(int val) : data(val), link(nullptr) {}
};

struct DualDirectionList {
    TreeNode* start;
    TreeNode* end;

    DualDirectionList() : start(nullptr), end(nullptr) {}

    TreeNode* computeXOR(TreeNode* x, TreeNode* y) {
        return reinterpret_cast<TreeNode*>(reinterpret_cast<uintptr_t>(x) ^ reinterpret_cast<uintptr_t>(y));
    }

    void insert(int value) {
        TreeNode* freshNode = new TreeNode(value);
        if (!start) {
            start = end = freshNode;
            return;
        }
        TreeNode* formerNode = end;
        TreeNode* latterNode = computeXOR(end->link, nullptr);
        end->link = computeXOR(freshNode, latterNode);
        freshNode->link = computeXOR(formerNode, nullptr);
        end = freshNode;
    }

    void invert() {
        TreeNode* current = start;
        TreeNode* previous = nullptr;
        TreeNode* successor = nullptr;

        while (current) {
            successor = computeXOR(previous, current->link);
            current->link = computeXOR(previous, successor);
            previous = current;
            current = successor;
        }

        start = previous; // final node becomes the new start
    }

    void display() {
        TreeNode* current = start;
        TreeNode* previous = nullptr;
        TreeNode* next;

        while (current) {
            std::cout << current->data << " ";
            next = computeXOR(previous, current->link);
            previous = current;
            current = next;
        }
        std::cout << std::endl;
    }
};

int main() {
    DualDirectionList sequence;
    sequence.insert(1);
    sequence.insert(2);
    sequence.insert(3);
    sequence.display(); // 1 2 3

    sequence.invert();
    sequence.display(); // 3 2 1

    return 0;
}

