// Array of descending powers of two for hashing computation
const int POWERS_OF_TWO[] = {
    65536,
    32768,
    16384,
    8192,
    4096,
    2048,
    1024,
    512,
    256,
    128,
    64,
    32,
    16,
    8,
    4,
    2,
    1
};

unsigned long long computeChecksum(const std::string& input) {
    unsigned long long result = 0;
    for (size_t index = 0; index < input.length() && index < sizeof(POWERS_OF_TWO) / sizeof(POWERS_OF_TWO[0]); ++index) {
        result += input[index] * POWERS_OF_TWO[index];
    }
    return result;
}

