#include <immintrin.h> // For AVX2 intrinsics
#include <algorithm>
#include <array>

typedef std::array<uint8_t, 3> Color3B;
typedef std::array<int32_t, 3> Int3Vec;

Color3B adjustColor(Color3B const& input, Color3B base, int32_t amount) {
    // Convert to __m128i (128-bit integer vector)
    __m128i vecInput = _mm_setr_epi32(input[0], input[1], input[2], 0);
    __m128i vecBase = _mm_setr_epi32(base[0], base[1], base[2], 0);
    __m128i vecAmount = _mm_set1_epi32(amount);

    // Evaluate condition: input > base + amount
    __m128i sumBaseAmount = _mm_add_epi32(vecBase, vecAmount);
    __m128i comparison = _mm_cmpgt_epi32(vecInput, sumBaseAmount);
    int mask = _mm_movemask_epi8(comparison);

    if (mask == 0) {
        return base;
    } else {
        // Find maximum component in input vector
        __m128i maxComponent = _mm_max_epi32(vecInput, _mm_shuffle_epi32(vecInput, _MM_SHUFFLE(2, 2, 2, 1)));
        maxComponent = _mm_max_epi32(maxComponent, _mm_shuffle_epi32(maxComponent, _MM_SHUFFLE(2, 2, 2, 0)));

        // Apply adjustment formula: input - (input * amount) / maxComponent
        __m128i product = _mm_mullo_epi32(vecInput, vecAmount);
        __m128i quotient = _mm_div_epi32(product, maxComponent);
        __m128i adjusted = _mm_sub_epi32(vecInput, quotient);

        // Ensure result is at least base value
        adjusted = _mm_max_epi32(adjusted, vecBase);

        // Store and extract results
        int32_t tempResult[4];
        _mm_storeu_si128((__m128i*)tempResult, adjusted);

        return {static_cast<uint8_t>(tempResult[0]), 
                static_cast<uint8_t>(tempResult[1]), 
                static_cast<uint8_t>(tempResult[2])};
    }
}

