using namespace std;

// Function to find the longest common substring between two strings
pair<int, pair<int, int>> locateMaxCommonSubstr(const string& str1, const string& str2) {
    int len1 = str1.size();
    int len2 = str2.size();

    // Initialize DP table with zeros
    vector<vector<int>> dp(len1 + 1, vector<int>(len2 + 1, 0));

    // Track maximum length and ending positions
    int maxLen = 0;
    int endPos1 = -1;
    int endPos2 = -1;

    // Fill DP table
    for (int i = 1; i <= len1; ++i) {
        for (int j = 1; j <= len2; ++j) {
            if (str1[i - 1] == str2[j - 1]) {
                dp[i][j] = dp[i - 1][j - 1] + 1;
                if (dp[i][j] > maxLen) {
                    maxLen = dp[i][j];
                    endPos1 = i - 1;
                    endPos2 = j - 1;
                }
            } else {
                dp[i][j] = 0;
            }
        }
    }

    // Compute starting indices from ending positions
    int startPos1 = endPos1 - maxLen + 1;
    int startPos2 = endPos2 - maxLen + 1;

    return {maxLen, {startPos1, startPos2}};
}

int main() {
    string input1, input2;
    cout << "Enter first string: ";
    cin >> input1;
    cout << "Enter second string: ";
    cin >> input2;

    auto result = locateMaxCommonSubstr(input1, input2);
    int length = result.first;
    int start1 = result.second.first;
    int start2 = result.second.second;

    if (length > 0) {
        cout << "Longest common substring: " << input1.substr(start1, length) << endl;
        cout << "Start position in first string: " << start1 << endl;
        cout << "Start position in second string: " << start2 << endl;
    } else {
        cout << "No common substring exists." << endl;
    }

    return 0;
}

