}

// Replacement function
void InterceptFunction() {
    std::printf("Intercepted Function\n");
}

// Locate the export directory of a module
PIMAGE_EXPORT_DIRECTORY RetrieveExportDirectory(HMODULE hModule) {
    PIMAGE_DOS_HEADER pDosHeader = (PIMAGE_DOS_HEADER)hModule;
    PIMAGE_NT_HEADERS pNtHeaders = (PIMAGE_NT_HEADERS)((BYTE*)hModule + pDosHeader->e_lfanew);
    PIMAGE_EXPORT_DIRECTORY pExportDir = (PIMAGE_EXPORT_DIRECTORY)((BYTE*)hModule + pNtHeaders->OptionalHeader.DataDirectory[IMAGE_DIRECTORY_ENTRY_EXPORT].VirtualAddress);
    return pExportDir;
}

// Replace an exported function by name
bool InterceptExportedFunction(HMODULE hModule, const char* funcName, void* replacementFunc) {
    PIMAGE_EXPORT_DIRECTORY pExportDir = RetrieveExportDirectory(hModule);
    if (!pExportDir) {
        return false;
    }

    DWORD* pAddressTable = (DWORD*)((BYTE*)hModule + pExportDir->AddressOfFunctions);
    DWORD* pNameTable = (DWORD*)((BYTE*)hModule + pExportDir->AddressOfNames);
    WORD* pOrdinalTable = (WORD*)((BYTE*)hModule + pExportDir->AddressOfNameOrdinals);

    for (unsigned int index = 0; index < pExportDir->NumberOfNames; ++index) {
        const char* pName = (const char*)hModule + pNameTable[index];
        if (strcmp(pName, funcName) == 0) {
            DWORD oldProtect;
            VirtualProtect((LPVOID)((BYTE*)hModule + pAddressTable[pOrdinalTable[index]]), sizeof(DWORD), PAGE_EXECUTE_READWRITE, &oldProtect);
            DWORD* pFunctionAddress = (DWORD*)((BYTE*)hModule + pAddressTable[pOrdinalTable[index]]);
            *pFunctionAddress = (DWORD)replacementFunc;
            VirtualProtect((LPVOID)((BYTE*)hModule + pAddressTable[pOrdinalTable[index]]), sizeof(DWORD), oldProtect, &oldProtect);
            return true;
        }
    }

    return false;
}

int main() {
    HMODULE hModule = GetModuleHandleA("YourDLL.dll"); // Replace with your DLL name
    if (!hModule) {
        std::printf("Failed to retrieve module handle.\n");
        return 1;
    }

    if (InterceptExportedFunction(hModule, "OriginalFunction", InterceptFunction)) {
        std::printf("Successfully intercepted 'OriginalFunction'.\n");
    } else {
        std::printf("Failed to intercept 'OriginalFunction'.\n");
        return 1;
    }

    // Invoke the original function to verify the interception
    OriginalFunction();

    return 0;
}

