#include <cstdint>

template<typename T, uint32_t maxCount>
class RingBuffer final {

    __attribute__((aligned(8)))
    T data[maxCount];
    uint32_t head;
    uint32_t tail;

    bool enqueue(const T &value) {
        register uint32_t currentTail asm("r0");
        register uint32_t previousTail asm("r1");

        do {
            // Load current tail value exclusively
            currentTail = __LDREXW(&tail);
            __DMB();

            // Remember previous tail value so that
            // we can store the item at that location
            previousTail = currentTail;

            // Check if ring buffer is full
            if (isFull()) {
                __CLREX();
                __DMB();
                return false;
            }

            // Compute next position
            if (currentTail == (maxCount - 1)) {
                currentTail = 0;
            }
            else {
                currentTail++;
            }

            // Attempt to update tail with new value
        } while (0 != __STREXW(currentTail, &tail));
        __CLREX();
        __DMB();

        // Insert new element
        data[previousTail] = value;
        return true;
    }

    // ... other methods ...

};

