            if (graph.adjMatrix[i][j] != 32767) {
                connections[index].from = i;
                connections[index].to = j;
                connections[index].cost = graph.adjMatrix[i][j];
                index++;
            }
        }
    }
    qsort(connections, graph.nodes * (graph.nodes - 1) / 2, sizeof(Connection), compareByCost);

    while (edgesAdded < graph.nodes - 1) {
        int smallest = 32767;
        int startNode, endNode;
        for (i = 0; i < graph.nodes * (graph.nodes - 1) / 2; i++) {
            if (!included[connections[i].from] || !included[connections[i].to]) {
                if (connections[i].cost < smallest) {
                    smallest = connections[i].cost;
                    startNode = connections[i].from;
                    endNode = connections[i].to;
                }
            }
        }
        printf("(%d,%d):%d\n", startNode, endNode, smallest);
        included[startNode] = 1;
        included[endNode] = 1;
        edgesAdded++;
    }

    free(included);
    free(connections);
}

