// Map locale codes to performance counter paths for different languages
std::map<std::string, std::string> BuildCounterLocaleMap() {
    return {
        {"en", "\\Processor(_Total)\\% Processor Time"},
        {"de", "\\Prozessor(_Total)\\Prozessorzeit (%)"},
        // Additional language mappings can be added here
    };
}

// Determine the system's default UI language and return appropriate counter path
std::string FetchPerformanceCounterPath() {
    LCID lcid = GetSystemDefaultUILanguage();
    char langCode[LOCALE_NAME_MAX_LENGTH];
    GetLocaleInfoA(lcid, LOCALE_SISO639LANGNAME, langCode, LOCALE_NAME_MAX_LENGTH);

    std::map<std::string, std::string> counterMap = BuildCounterLocaleMap();
    auto iter = counterMap.find(langCode);
    if (iter != counterMap.end()) {
        return iter->second;
    }
    return "\\Processor(_Total)\\% Processor Time"; // Fallback to English
}

// Measure current CPU usage using PDH API
double CalculateCpuUsage() {
    PDH_HQUERY queryHandle;
    PDH_HCOUNTER counterHandle;
    PDH_FMT_COUNTERVALUE valueBuffer;

    if (PdhOpenQuery(NULL, 0, &queryHandle) != ERROR_SUCCESS) {
        return -1.0;
    }

    std::string counterPath = FetchPerformanceCounterPath();
    if (PdhAddCounter(queryHandle, counterPath.c_str(), 0, &counterHandle) != ERROR_SUCCESS) {
        PdhCloseQuery(queryHandle);
        return -1.0;
    }

    if (PdhCollectQueryData(queryHandle) != ERROR_SUCCESS) {
        PdhCloseQuery(queryHandle);
        return -1.0;
    }

    Sleep(1000); // Allow time for sampling interval

    if (PdhCollectQueryData(queryHandle) != ERROR_SUCCESS) {
        PdhCloseQuery(queryHandle);
        return -1.0;
    }

    if (PdhGetFormattedCounterValue(counterHandle, PDH_FMT_DOUBLE, NULL, &valueBuffer) != ERROR_SUCCESS) {
        PdhCloseQuery(queryHandle);
        return -1.0;
    }

    PdhCloseQuery(queryHandle);

    return valueBuffer.doubleValue;
}

int main() {
    double cpuLoad = CalculateCpuUsage();
    if (cpuLoad >= 0.0) {
        printf("CPU Usage: %.2f%%\n", cpuLoad);
    } else {
        printf("Unable to retrieve CPU usage information.\n");
    }
    return 0;
}

