std::string convertDoubleToString(double value) {
    std::string result = boost::lexical_cast<std::string>(value);
    return result;
}

std::vector<std::vector<std::string>> doubleVectorToStdStringVector(const std::vector<std::vector<double>>& sourceVector) {
    std::vector<std::vector<std::string>> destinationVector;

    std::transform(sourceVector.begin(), sourceVector.end(), std::back_inserter(destinationVector), [](const std::vector<double>& innerVec) {
        std::vector<std::string> stringVec;
        std::transform(innerVec.begin(), innerVec.end(), std::back_inserter(stringVec), &convertDoubleToString);
        return stringVec;
    });

    return destinationVector;
}

