using namespace std;

const int FIELD_DIM = 5;
const int TOTAL_MINES = 5;

class MineField {
public:
    MineField() {
        srand(time(0));
        setupMines();
        computeAdjacency();
    }

    void runGame() {
        while (true) {
            displayGrid();
            int r, c;
            cout << "Enter row and column to reveal (0-4): ";
            cin >> r >> c;

            if (r < 0 || r >= FIELD_DIM || c < 0 || c >= FIELD_DIM) {
                cout << "Invalid coordinates. Try again." << endl;
                continue;
            }

            if (grid[r][c] == -1) {
                cout << "Boom! You triggered a mine." << endl;
                showFullGrid();
                break;
            }

            if (grid[r][c] == 0) {
                expandEmpty(r, c);
            } else {
                visible[r][c] = true;
            }

            if (victory()) {
                cout << "Well done! You cleared the field." << endl;
                showFullGrid();
                break;
            }
        }
    }

private:
    vector<vector<int>> grid;
    vector<vector<bool>> visible;

    void setupMines() {
        grid.assign(FIELD_DIM, vector<int>(FIELD_DIM, 0));
        visible.assign(FIELD_DIM, vector<bool>(FIELD_DIM, false));

        int placed = 0;
        while (placed < TOTAL_MINES) {
            int x = rand() % FIELD_DIM;
            int y = rand() % FIELD_DIM;
            if (grid[x][y] != -1) {
                grid[x][y] = -1;
                placed++;
            }
        }
    }

    void computeAdjacency() {
        for (int i = 0; i < FIELD_DIM; i++) {
            for (int j = 0; j < FIELD_DIM; j++) {
                if (grid[i][j] == -1) {
                    continue;
                }
                int neighbors = 0;
                for (int di = -1; di <= 1; di++) {
                    for (int dj = -1; dj <= 1; dj++) {
                        int ni = i + di, nj = j + dj;
                        if (ni >= 0 && ni < FIELD_DIM && nj >= 0 && nj < FIELD_DIM && grid[ni][nj] == -1) {
                            neighbors++;
                        }
                    }
                }
                grid[i][j] = neighbors;
            }
        }
    }

    void expandEmpty(int r, int c) {
        if (r < 0 || r >= FIELD_DIM || c < 0 || c >= FIELD_DIM || visible[r][c]) {
            return;
        }

        visible[r][c] = true;
        if (grid[r][c] == 0) {
            for (int di = -1; di <= 1; di++) {
                for (int dj = -1; dj <= 1; dj++) {
                    expandEmpty(r + di, c + dj);
                }
            }
        }
    }

    void displayGrid() {
        for (int i = 0; i < FIELD_DIM; i++) {
            for (int j = 0; j < FIELD_DIM; j++) {
                if (visible[i][j]) {
                    if (grid[i][j] == -1) {
                        cout << "X ";
                    } else {
                        cout << grid[i][j] << " ";
                    }
                } else {
                    cout << ". ";
                }
            }
            cout << endl;
        }
    }

    void showFullGrid() {
        for (int i = 0; i < FIELD_DIM; i++) {
            for (int j = 0; j < FIELD_DIM; j++) {
                if (grid[i][j] == -1) {
                    cout << "X ";
                } else {
                    cout << grid[i][j] << " ";
                }
            }
            cout << endl;
        }
    }

    bool victory() {
        for (int i = 0; i < FIELD_DIM; i++) {
            for (int j = 0; j < FIELD_DIM; j++) {
                if (grid[i][j] != -1 && !visible[i][j]) {
                    return false;
                }
            }
        }
        return true;
    }
};

int main() {
    MineField field;
    field.runGame();
    return 0;
}

