// Split a string by a given delimiter into tokens
std::vector<std::string> tokenize(const std::string &input, char sep) {
    std::vector<std::string> result;
    std::string current;
    std::istringstream stream(input);
    while (std::getline(stream, current, sep)) {
        if (!current.empty()) {
            result.push_back(current);
        }
    }
    return result;
}

