// Load armature data from a JSON file into the 3D scene
void loadArmatureFromJson(const QString &jsonPath, Qt3DCore::QEntity *sceneRoot) {
    QFile jsonFile(jsonPath);
    if (!jsonFile.open(QIODevice::ReadOnly | QIODevice::Text)) {
        qWarning("Unable to open JSON file for reading");
        return;
    }

    QByteArray rawData = jsonFile.readAll();
    QJsonDocument document = QJsonDocument::fromJson(rawData);
    QJsonObject rootObject = document.object();

    // Initialize skeleton loading mechanism
    Qt3DRender::QSkeleton *skeletonInstance = new Qt3DRender::QSkeleton(sceneRoot);
    Qt3DRender::QSkeletonLoader *loader = new Qt3DRender::QSkeletonLoader(sceneRoot);
    loader->setSource(QUrl::fromLocalFile(jsonPath));
    skeletonInstance->setLoader(loader);

    // Process animation definitions
    QJsonArray animationList = rootObject.value("animations").toArray();
    for (const QJsonValue &animEntry : animationList) {
        QJsonObject animData = animEntry.toObject();
        Qt3DAnimation::QAnimationClip *animationClip = new Qt3DAnimation::QAnimationClip(sceneRoot);
        animationClip->setDuration(animData.value("duration").toDouble());
        animationClip->setLoopCount(animData.value("loopCount").toInt());

        // Handle channel mappings for this animation
        QJsonArray channelList = animData.value("channels").toArray();
        for (const QJsonValue &channelEntry : channelList) {
            QJsonObject channelData = channelEntry.toObject();
            Qt3DAnimation::QChannelMapper *mapperInstance = new Qt3DAnimation::QChannelMapper(sceneRoot);
            mapperInstance->setChannelName(channelData.value("channelName").toString());
            mapperInstance->setBoneName(channelData.value("boneName").toString());

            // Add keyframes for this channel
            QJsonArray keyframeList = channelData.value("keys").toArray();
            for (const QJsonValue &keyEntry : keyframeList) {
                QJsonObject keyData = keyEntry.toObject();
                Qt3DAnimation::QKeyframe *keyframe = new Qt3DAnimation::QKeyframe(sceneRoot);
                keyframe->setTime(keyData.value("time").toDouble());
                keyframe->setTranslation(QVector3D(
                    keyData.value("translationX").toDouble(),
                    keyData.value("translationY").toDouble(),
                    keyData.value("translationZ").toDouble()
                ));
                keyframe->setRotation(QQuaternion(
                    keyData.value("rotationW").toDouble(),
                    keyData.value("rotationX").toDouble(),
                    keyData.value("rotationY").toDouble(),
                    keyData.value("rotationZ").toDouble()
                ));
                keyframe->setScale(QVector3D(
                    keyData.value("scaleX").toDouble(),
                    keyData.value("scaleY").toDouble(),
                    keyData.value("scaleZ").toDouble()
                ));
                mapperInstance->addKeyframe(keyframe);
            }

            animationClip->addChannelMapper(mapperInstance);
        }

        // Attach animator to skeleton
        Qt3DAnimation::QClipAnimator *animator = new Qt3DAnimation::QClipAnimator(sceneRoot);
        animator->setClip(animationClip);
        animator->setTarget(skeletonInstance);
        sceneRoot->addComponent(animator);
    }
}

