// Binary tree node definition
struct TreeNode {
    int value;
    TreeNode* leftChild;
    TreeNode* rightChild;
    TreeNode(int v) : value(v), leftChild(nullptr), rightChild(nullptr) {}
};

// Binary Search Tree implementation
class BinarySearchTree {
public:
    TreeNode* head;
    BinarySearchTree() : head(nullptr) {}

    void addValue(int val) {
        head = insertNode(head, val);
    }

    void removeValue(int val) {
        head = removeNode(head, val);
    }

    void inOrderTraversal() {
        traverseInOrder(head);
        cout << endl;
    }

    void preOrderTraversal() {
        traversePreOrder(head);
        cout << endl;
    }

    void postOrderTraversal() {
        traversePostOrder(head);
        cout << endl;
    }

private:
    TreeNode* insertNode(TreeNode* node, int val) {
        if (node == nullptr) {
            return new TreeNode(val);
        }
        if (val < node->value) {
            node->leftChild = insertNode(node->leftChild, val);
        } else if (val > node->value) {
            node->rightChild = insertNode(node->rightChild, val);
        }
        return node;
    }

    TreeNode* findMinNode(TreeNode* node) {
        TreeNode* current = node;
        while (current && current->leftChild != nullptr) {
            current = current->leftChild;
        }
        return current;
    }

    TreeNode* removeNode(TreeNode* node, int val) {
        if (node == nullptr) {
            return node;
        }
        if (val < node->value) {
            node->leftChild = removeNode(node->leftChild, val);
        } else if (val > node->value) {
            node->rightChild = removeNode(node->rightChild, val);
        } else {
            if (node->leftChild == nullptr) {
                TreeNode* temp = node->rightChild;
                delete node;
                return temp;
            } else if (node->rightChild == nullptr) {
                TreeNode* temp = node->leftChild;
                delete node;
                return temp;
            }
            TreeNode* temp = findMinNode(node->rightChild);
            node->value = temp->value;
            node->rightChild = removeNode(node->rightChild, temp->value);
        }
        return node;
    }

    void traverseInOrder(TreeNode* node) {
        if (node != nullptr) {
            traverseInOrder(node->leftChild);
            cout << node->value << " ";
            traverseInOrder(node->rightChild);
        }
    }

    void traversePreOrder(TreeNode* node) {
        if (node != nullptr) {
            cout << node->value << " ";
            traversePreOrder(node->leftChild);
            traversePreOrder(node->rightChild);
        }
    }

    void traversePostOrder(TreeNode* node) {
        if (node != nullptr) {
            traversePostOrder(node->leftChild);
            traversePostOrder(node->rightChild);
            cout << node->value << " ";
        }
    }
};

int main() {
    BinarySearchTree bst;
    bst.addValue(50);
    bst.addValue(30);
    bst.addValue(20);
    bst.addValue(40);
    bst.addValue(70);
    bst.addValue(60);
    bst.addValue(80);

    cout << "Inorder traversal: ";
    bst.inOrderTraversal();

    cout << "Preorder traversal: ";
    bst.preOrderTraversal();

    cout << "Postorder traversal: ";
    bst.postOrderTraversal();

    cout << "Delete 20: ";
    bst.removeValue(20);
    bst.inOrderTraversal();

    cout << "Delete 30: ";
    bst.removeValue(30);
    bst.inOrderTraversal();

    cout << "Delete 50: ";
    bst.removeValue(50);
    bst.inOrderTraversal();

    return 0;
}

