// Find the maximum element in a vector manually
int get_largest(const std::vector<int>& data) {
    if (data.empty()) return INT_MIN; // Handle empty input
    int current_max = data[0];
    for (int value : data) {
        if (value > current_max) {
            current_max = value;
        }
    }
    return current_max;
}

// Using standard library's max_element function
int get_largest_builtin(const std::vector<int>& data) {
    return data.empty() ? INT_MIN : *std::max_element(data.begin(), data.end());
}

