class IRNode {
public:
    virtual std::string generateAssembly() const = 0;
};

class IfNode : public IRNode {
private:
    IRNode* condExpr;
    IRNode* trueBranch;
    IRNode* falseBranch;
    std::string id;

public:
    IfNode(IRNode* cond, IRNode* tBlock, IRNode* fBlock, std::string identifier)
        : condExpr(cond), trueBranch(tBlock), falseBranch(fBlock), id(identifier) {}

    std::string generateAssembly() const override {
        std::string result = "";

        result += condExpr->generateAssembly();
        result += "jmp .false" + id + "\n";
        result += ".true" + id + ":\n";
        result += trueBranch->generateAssembly();
        result += "jmp .end" + id + "\n";
        result += ".false" + id + ":\n";
        result += falseBranch->generateAssembly();
        result += ".end" + id + ":\n";

        return result;
    }
};

class ComparisonNode : public IRNode {
private:
    std::string operatorStr;
    IRNode* lhs;
    IRNode* rhs;
    std::string tag;

public:
    ComparisonNode(std::string op, IRNode* left, IRNode* right, std::string labelTag)
        : operatorStr(op), lhs(left), rhs(right), tag(labelTag) {}

    std::string generateAssembly() const override {
        std::string output = "";

        output += lhs->generateAssembly();
        output += right->generateAssembly(); // Fixed: was missing 'right' variable
        output += "cmp %eax, %ebx\n";
        output += "je .true" + tag + "\n";
        output += "jmp .false" + tag + "\n";

        return output;
    }
};

// Example usage
int main() {
    IRNode* condition = new ComparisonNode("==", new ConstantNode(1), new ConstantNode(1), "cmp1");
    IRNode* trueBranch = new BlockNode({ new InstructionNode("mov $1, %eax") });
    IRNode* falseBranch = new BlockNode({ new InstructionNode("mov $0, %eax") });

    IfNode* ifStatement = new IfNode(condition, trueBranch, falseBranch, "if2");

    std::string assembly = ifStatement->generateAssembly();
    std::cout << assembly << std::endl;

    delete condition;
    delete trueBranch;
    delete falseBranch;
    delete ifStatement;

    return 0;
}

