using namespace std;

// Function to compute the size of the longest increasing subsequence
int getLISLength(vector<int>& arr) {
    if (arr.empty()) return 0;

    vector<int> ends;
    for (int value : arr) {
        // Locate where 'value' should be inserted in 'ends'
        auto pos = lower_bound(ends.begin(), ends.end(), value);
        if (pos == ends.end()) {
            // If 'value' exceeds all current ends, extend the sequence
            ends.push_back(value);
        } else {
            // Otherwise, update the first element >= 'value'
            *pos = value;
        }
    }
    return ends.size();
}

// Function to reconstruct the actual longest increasing subsequence
vector<int> buildLIS(vector<int>& arr) {
    if (arr.empty()) return {};

    vector<int> ends;
    vector<int> positions(arr.size(), -1);
    vector<int> predecessors(arr.size(), -1);

    for (int i = 0; i < arr.size(); ++i) {
        auto pos = lower_bound(ends.begin(), ends.end(), arr[i]);
        int index = pos - ends.begin();
        if (pos == ends.end()) {
            ends.push_back(arr[i]);
        } else {
            *pos = arr[i];
        }
        positions[index] = i;
        if (index > 0) {
            predecessors[i] = positions[index - 1];
        }
    }

    vector<int> result;
    for (int idx = positions.back(); idx >= 0; idx = predecessors[idx]) {
        result.push_back(arr[idx]);
    }
    reverse(result.begin(), result.end());
    return result;
}

int main() {
    vector<int> data = {10, 9, 2, 5, 3, 7, 101, 18};

    int len = getLISLength(data);
    cout << "Length of the longest increasing subsequence: " << len << endl;

    vector<int> seq = buildLIS(data);
    cout << "The longest increasing subsequence: ";
    for (int val : seq) {
        cout << val << " ";
    }
    cout << endl;

    return 0;
}

