using Word = std::uint32_t; // Changed type alias name

// Combine upper bits from first operand with lower bits from second operand
Word rotateMerge(Word a, Word b, Word shiftAmount)
{
    // Create mask for the lower 'shiftAmount' bits
    Word bitMask = (Word(1) << shiftAmount) - 1;

    // Extract upper part from 'a' and combine with lower bits from 'b' shifted up
    return (a >> shiftAmount) | ((b & bitMask) << (std::numeric_limits<Word>::digits - shiftAmount));
}

