// Compute the union of two sorted vectors without duplicates
std::vector<int> computeUnion(const std::vector<int>& input1, const std::vector<int>& input2) {
    std::vector<int> result;
    size_t idx1 = 0, idx2 = 0;

    while (idx1 < input1.size() && idx2 < input2.size()) {
        if (input1[idx1] < input2[idx2]) {
            if (result.empty() || result.back() != input1[idx1]) {
                result.push_back(input1[idx1]);
            }
            ++idx1;
        } else if (input1[idx1] > input2[idx2]) {
            if (result.empty() || result.back() != input2[idx2]) {
                result.push_back(input2[idx2]);
            }
            ++idx2;
        } else {
            if (result.empty() || result.back() != input1[idx1]) {
                result.push_back(input1[idx1]);
            }
            ++idx1;
            ++idx2;
        }
    }

    // Append leftover elements from input1
    while (idx1 < input1.size()) {
        if (result.empty() || result.back() != input1[idx1]) {
            result.push_back(input1[idx1]);
        }
        ++idx1;
    }

    // Append leftover elements from input2
    while (idx2 < input2.size()) {
        if (result.empty() || result.back() != input2[idx2]) {
            result.push_back(input2[idx2]);
        }
        ++idx2;
    }

    return result;
}

int main() {
    std::vector<int> data1 = {1, 2, 4, 5, 6};
    std::vector<int> data2 = {2, 3, 5, 7};

    std::vector<int> output = computeUnion(data1, data2);

    std::cout << "Union of the two arrays is: ";
    for (int value : output) {
        std::cout << value << " ";
    }
    std::cout << std::endl;

    return 0;
}

#include <immintrin.h>

// Compute derived attributes using SIMD operations
void compute_attributes(float* input_data, float* output_sum, float* output_diff, int count) {
    __m256 vector_x, vector_y, vector_z, vector_result1, vector_result2;
    for (int index = 0; index < count; index += 8) {
        vector_x = _mm256_loadu_ps(&input_data[index * 3 + 0]);
        vector_y = _mm256_loadu_ps(&input_data[index * 3 + 1]);
        vector_z = _mm256_loadu_ps(&input_data[index * 3 + 2]);

        // Vector arithmetic operations
        vector_result1 = _mm256_add_ps(vector_x, vector_y);
        vector_result2 = _mm256_sub_ps(vector_x, vector_z);

        _mm256_storeu_ps(&output_sum[index], vector_result1);
        _mm256_storeu_ps(&output_diff[index], vector_result2);
    }
}

