#include <xmmintrin.h>

// Compute the dot product of two 4D vectors using SSE intrinsics
inline __m128 sse_dot_product(__m128 vec_a, __m128 vec_b)
{
    // Multiply corresponding elements
    const __m128 product = _mm_mul_ps(vec_a, vec_b);

    // Accumulate partial sums: add element 0 with element 1
    const __m128 part_sum1 = _mm_add_ss(product, _mm_shuffle_ps(product, product, _MM_SHUFFLE(0, 0, 0, 1)));

    // Accumulate partial sums: add element 0 with element 2
    const __m128 part_sum2 = _mm_add_ss(product, _mm_shuffle_ps(product, product, _MM_SHUFFLE(0, 0, 0, 2)));

    // Combine the two partial sums into final result
    const __m128 final_sum = _mm_add_ss(part_sum1, _mm_shuffle_ps(part_sum2, part_sum2, _MM_SHUFFLE(0, 0, 0, 0)));

    return final_sum;
}

