int main(int argc, char *argv[])
{
    QCoreApplication app(argc, argv);

    // Initialize COM library
    CoInitialize(NULL);
    ISpVoice *speaker = NULL;
    HRESULT result = CoCreateInstance(CLSID_SpVoice, NULL, CLSCTX_ALL, IID_ISpVoice, (void **)&speaker);
    if (FAILED(result)) {
        std::cerr << "Error: Unable to initialize SAPI voice" << std::endl;
        return -1;
    }

    // List all available voices
    ISpObjectToken *voiceToken = NULL;
    IEnumSpObjectTokens *tokenEnum = NULL;
    result = SpEnumTokens(SPCAT_VOICES, NULL, NULL, &tokenEnum);
    if (SUCCEEDED(result)) {
        while (tokenEnum->Next(1, &voiceToken, NULL) == S_OK) {
            SPVOICESTATUS voiceStatus;
            result = speaker->GetStatus(&voiceStatus, NULL);
            if (SUCCEEDED(result)) {
                SPVOICECATEGORY voiceCategory;
                voiceToken->GetCategory(&voiceCategory);
                if (voiceCategory == SPCAT_VOICES) {
                    BSTR tokenID, tokenDesc;
                    voiceToken->GetId(&tokenID);
                    voiceToken->GetDescription(&tokenDesc);
                    std::wcout << L"Voice ID: " << tokenID << L", Description: " << tokenDesc << std::endl;
                    SysFreeString(tokenID);
                    SysFreeString(tokenDesc);
                }
            }
            voiceToken->Release();
        }
        tokenEnum->Release();
    }

    // Attempt to select a specific Acapela voice
    hr = SpFindBestToken(SPCAT_VOICES, L"Name=Acapela Voice Name", NULL, &voiceToken);
    if (SUCCEEDED(result)) {
        result = speaker->SetVoice(voiceToken);
        if (FAILED(result)) {
            std::cerr << "Warning: Could not set the requested Acapela voice" << std::endl;
        }
    } else {
        std::cerr << "Notice: Acapela voice not detected on system" << std::endl;
    }

    // Perform text-to-speech
    result = speaker->Speak(L"Greetings! This is a test using an Acapela voice.", SPF_DEFAULT, NULL);
    if (FAILED(result)) {
        std::cerr << "Error: Speech synthesis failed" << std::endl;
    }

    // Cleanup resources
    if (voiceToken) voiceToken->Release();
    if (speaker) speaker->Release();
    CoUninitialize();

    return app.exec();
}

