// Initialize 3D array using inline assembly
void asm_init(int data_array[5][5][5]) {
    int x = 0, y = 0, z = 0;
    while (x < 5) {
        data_array[x][y][z] = 0;
        __asm inc z;

        if (z > 4) {
            __asm inc y;
            __asm mov z, 0;
        }
        if (y > 4) {
            __asm inc x;
            __asm mov y, 0;
        }
    }
}

// Initialize 3D array using nested loops
void loop_init(int data_array[5][5][5]) {
    for (int i = 0; i < 5; ++i) {
        for (int j = 0; j < 5; ++j) {
            for (int k = 0; k < 5; ++k) {
                data_array[i][j][k] = 0;
            }
        }
    }
}

int main() {
    int arr1[5][5][5];
    int arr2[5][5][5];

    auto begin1 = std::chrono::high_resolution_clock::now();
    asm_init(arr1);
    auto finish1 = std::chrono::high_resolution_clock::now();
    auto time1 = std::chrono::duration_cast<std::chrono::microseconds>(finish1 - begin1);

    auto begin2 = std::chrono::high_resolution_clock::now();
    loop_init(arr2);
    auto finish2 = std::chrono::high_resolution_clock::now();
    auto time2 = std::chrono::duration_cast<std::chrono::microseconds>(finish2 - begin2);

    std::cout << "Assembly implementation: " << time1.count() << " microseconds" << std::endl;
    std::cout << "Standard loop implementation: " << time2.count() << " microseconds" << std::endl;

    return 0;
}

