void transmitFloatData(SOCKET socket, const float* data, int count) {
    char tempBuffer[12 * sizeof(float)];
    for (int index = 0; index < count; ++index) {
        uint32_t rawBits = *reinterpret_cast<uint32_t*>(&data[index]);
        uint32_t networkOrder = htonl(rawBits);
        memcpy(&tempBuffer[index * sizeof(float)], &networkOrder, sizeof(float));
    }
    send(socket, tempBuffer, count * sizeof(float), 0);
}

