// Function to parse a Python-style dictionary string into a C++ map
std::map<std::string, std::string> extractDictEntries(const std::string &inputStr) {
    std::map<std::string, std::string> resultMap;

    std::size_t begin = inputStr.find('{');
    std::size_t finish = inputStr.rfind('}');
    std::string content = inputStr.substr(begin + 1, finish - begin - 1);

    std::stringstream stream(content);
    std::string entry;

    while (std::getline(stream, entry, ',')) {
        std::size_t separatorPos = entry.find(':');
        std::string key = entry.substr(0, separatorPos);
        std::string value = entry.substr(separatorPos + 1);

        // Trim whitespace and quotes from key
        key.erase(0, key.find_first_not_of(" '\"{"));
        key.erase(key.find_last_not_of(" '\"}") + 1);

        // Trim whitespace and quotes from value
        value.erase(0, value.find_first_not_of(" '\""));
        value.erase(value.find_last_not_of(" '\"") + 1);

        resultMap[key] = value;
    }

    return resultMap;
}

int main() {
    std::string pythonStyleDict = "{'item1': 1, 'item2': 2.0, 'item3': 'a string', 'item4': 'another string'}";

    std::map<std::string, std::string> resultMap = extractDictEntries(pythonStyleDict);

    for (const auto &entry : resultMap) {
        std::cout << entry.first << ": " << entry.second << std::endl;
    }

    return 0;
}

