void zeroMemoryStreaming_128B(void* buffer, long numBlocks) {
    __m128i reg0 = _mm_setzero_si128();
    __m128i reg1 = _mm_setzero_si128();
    __m128i reg2 = _mm_setzero_si128();
    __m128i reg3 = _mm_setzero_si128();
    __m128i reg4 = _mm_setzero_si128();
    __m128i reg5 = _mm_setzero_si128();
    __m128i reg6 = _mm_setzero_si128();
    __m128i reg7 = _mm_setzero_si128();

    char* dest = static_cast<char*>(buffer);
    for (long idx = 0; idx < numBlocks; ++idx) {
        _mm_stream_si128(reinterpret_cast<__m128i*>(dest + 0 * 16), reg0);
        _mm_stream_si128(reinterpret_cast<__m128i*>(dest + 1 * 16), reg1);
        _mm_stream_si128(reinterpret_cast<__m128i*>(dest + 2 * 16), reg2);
        _mm_stream_si128(reinterpret_cast<__m128i*>(dest + 3 * 16), reg3);
        _mm_stream_si128(reinterpret_cast<__m128i*>(dest + 4 * 16), reg4);
        _mm_stream_si128(reinterpret_cast<__m128i*>(dest + 5 * 16), reg5);
        _mm_stream_si128(reinterpret_cast<__m128i*>(dest + 6 * 16), reg6);
        _mm_stream_si128(reinterpret_cast<__m128i*>(dest + 7 * 16), reg7);
        dest += 128;
    }
}

int main() {
    unsigned __int64 startTime, endTime;
    const long bufferSize = 64 * KILOBYTE;
    const long blockCount = bufferSize / 128;

    char* dataBuffer = static_cast<char*>(_mm_malloc(bufferSize, 16));

    startTime = readTimestampCounter();
    zeroMemoryStreaming_128B(dataBuffer, blockCount);
    endTime = readTimestampCounter();

    double elapsedSeconds = static_cast<double>(endTime - startTime) / getCpuFrequency();
    std::cout << "Time WRITE_128 [seconds]:" << elapsedSeconds << std::endl;
    std::cout << "Write Speed [MB/s]:" << static_cast<double>(bufferSize) / elapsedSeconds / MEGABYTE << std::endl;

    _mm_free(dataBuffer);
    return 0;
}

