using namespace std;

#define INF 1000000000

typedef long long LL;

///////////////////////////

#define MAX_SIZE 1000000

int weights[MAX_SIZE];
int original[MAX_SIZE];
int permutation[MAX_SIZE];
bool visited[MAX_SIZE]; 

int globalMin = INF;

int main()
{
    int N;
    scanf("%d", &N);
    LOOP(i, 0, N)
    {
        scanf("%d", &weights[i]);
        globalMin = min(globalMin, weights[i]);
    }
    LOOP(i, 0, N)
    {
        scanf("%d", &original[i]);
        --original[i];
    }
    LOOP(i, 0, N)
    {
        int index;
        scanf("%d", &index);
        --index;
        permutation[index] = original[i];
    }
    LL result = 0;
    LOOP(start, N)
        if (!visited[start])
        {
            int localMin = INF;
            LL sum = 0;
            int current = start;
            int length = 0;
            for (;;)
            {
                localMin = min(localMin, weights[current]);
                sum += weights[current];
                current = permutation[current];
                visited[current] = true;
                ++length;
                if (current == start)
                    break;
            }
            result += min(sum + (length - 2) * (LL)localMin, sum + localMin + (length + 1) * (LL)globalMin);
        }
    printf("%Ld\n", result);
}

