class Vector2D {
public:
    // Constructor
    Vector2D(double xCoord = 0.0, double yCoord = 0.0) : x(xCoord), y(yCoord) {}

    // Accessors (getters)
    double getX() const { return x; }
    double getY() const { return y; }

    // Mutators (setters)
    void setX(double newX) { x = newX; }
    void setY(double newY) { y = newY; }

    // Vector addition
    Vector2D operator+(const Vector2D& other) const {
        return Vector2D(x + other.x, y + other.y);
    }

    // Vector subtraction
    Vector2D operator-(const Vector2D& other) const {
        return Vector2D(x - other.x, y - other.y);
    }

    // Scalar multiplication
    Vector2D operator*(double factor) const {
        return Vector2D(x * factor, y * factor);
    }

    // Dot product
    double dot(const Vector2D& other) const {
        return x * other.x + y * other.y;
    }

    // Magnitude (length) of the vector
    double magnitude() const {
        return std::sqrt(x * x + y * y);
    }

    // Normalized vector (unit vector)
    Vector2D normalize() const {
        double len = magnitude();
        if (len > 0) {
            return Vector2D(x / len, y / len);
        }
        return *this; // Return the original vector if it's a zero vector
    }

private:
    double x, y;
};

// Function to print a Vector2D
void displayVector(const Vector2D& v) {
    std::cout << "Vector: (" << v.getX() << ", " << v.getY() << ")" << std::endl;
}

int main() {
    Vector2D vecA(3.0, 4.0);
    Vector2D vecB(1.0, 2.0);

    Vector2D vecC = vecA + vecB;
    Vector2D vecD = vecA - vecB;
    Vector2D vecE = vecA * 2.0;
    double dotResult = vecA.dot(vecB);
    double length = vecA.magnitude();
    Vector2D unitVec = vecA.normalize();

    displayVector(vecA);
    displayVector(vecB);
    displayVector(vecC); // vecA + vecB
    displayVector(vecD); // vecA - vecB
    displayVector(vecE); // vecA * 2.0
    std::cout << "Dot Product: " << dotResult << std::endl;
    std::cout << "Magnitude: " << length << std::endl;
    displayVector(unitVec);

    return 0;
}

