#include <iostream>
#include <string>
#include <vector>
#include <iterator>

class DataStreamGenerator {
public:
    class StreamIterator {
    public:
        using value_type = std::string;
        using reference = std::string&;
        using pointer = std::string*;
        using difference_type = std::ptrdiff_t;
        using iterator_category = std::input_iterator_tag;

        StreamIterator(DataStreamGenerator& generator, bool finish = false) : generator_(generator), finished_(finish) {
            if (!finished_) {
                current_item_ = generator_.produce_next();
            }
        }

        StreamIterator& operator++() {
            if (!finished_) {
                current_item_ = generator_.produce_next();
            }
            return *this;
        }

        StreamIterator operator++(int) {
            StreamIterator temp = *this;
            ++(*this);
            return temp;
        }

        bool operator==(const StreamIterator& rhs) const {
            return finished_ == rhs.finished_;
        }

        bool operator!=(const StreamIterator& rhs) const {
            return !(*this == rhs);
        }

        const std::string& operator*() const {
            return current_item_;
        }

        const std::string* operator->() const {
            return &current_item_;
        }

    private:
        DataStreamGenerator& generator_;
        std::string current_item_;
        bool finished_;
    };

    DataStreamGenerator(const std::string& source_name) : source_name_(source_name), skip_count_(source_name.find("extra") != std::string::npos ? 7 : 8) {
        state_ = 0;
    }

    StreamIterator begin() {
        return StreamIterator(*this);
    }

    StreamIterator end() {
        return StreamIterator(*this, true);
    }

private:
    std::string source_name_;
    int skip_count_;
    int state_;

    std::string produce_next() {
        switch (state_) {
            case 0:
                state_ = 1;
                return "payload";
            case 1:
                for (int j = 0; j < skip_count_; ++j) {
                    state_++;
                    return "skipped";
                }
                state_ = skip_count_ + 1;
                // Continue to next case
            case skip_count_ + 1:
                state_++;
                return "payload";
            default:
                return "payload"; // Infinite loop behavior preserved
        }
    }
};

// Demonstration usage
int main() {
    DataStreamGenerator stream("sample_extra.txt");

    for (const auto& item : stream) {
        std::cout << item << std::endl;
    }

    return 0;
}

