// Definition for singly-linked list.
struct Node {
    int data;
    Node *link;
    Node(int x) : data(x), link(NULL) {}
};

// Function to detect a cycle in a linked list.
bool hasLoop(Node *start) {
    if (start == NULL || start->link == NULL) {
        return false;
    }

    Node *slow = start;
    Node *fast = start;

    while (fast != NULL && fast->link != NULL) {
        slow = slow->link;          // Move slow pointer by one step
        fast = fast->link->link;    // Move fast pointer by two steps

        if (slow == fast) {         // If they meet, there is a cycle
            return true;
        }
    }

    return false;  // If we reach here, there is no cycle
}

// Function to create a linked list with a cycle for testing.
Node* buildListWithLoop() {
    Node *head = new Node(10);
    Node *node2 = new Node(20);
    Node *node3 = new Node(30);
    Node *node4 = new Node(40);

    head->link = node2;
    node2->link = node3;
    node3->link = node4;
    node4->link = node2;  // Creating a cycle

    return head;
}

// Main function to test the cycle detection.
int main() {
    Node *head = buildListWithLoop();

    if (hasLoop(head)) {
        cout << "Loop found in the linked list." << endl;
    } else {
        cout << "No loop found in the linked list." << endl;
    }

    return 0;
}

