// Environment parameters
const int STATES_COUNT = 5;
const int ACTIONS_COUNT = 2;
const double ALPHA = 0.1;
const double GAMMA = 0.9;
const double EPSILON = 0.1;
const int TRAINING_ROUNDS = 1000;

// Q-value table
std::vector<std::vector<double>> Q_TABLE(STATES_COUNT, std::vector<double>(ACTIONS_COUNT, 0.0));

// Simulate environment response to action
std::pair<int, double> simulate_environment(int current_state, int selected_action) {
    // Grid world dynamics: move based on action
    int new_state = current_state + selected_action;
    double obtained_reward = 0.0;

    if (new_state < 0 || new_state >= STATES_COUNT) {
        new_state = current_state;
        obtained_reward = -1.0;
    } else if (new_state == STATES_COUNT - 1) {
        obtained_reward = 10.0;
    }

    return {new_state, obtained_reward};
}

// Select action using epsilon-greedy strategy
int select_policy_action(int observation) {
    std::random_device seed_generator;
    std::mt19937 rng(seed_generator());
    std::uniform_real_distribution<> probability_dist(0.0, 1.0);

    if (probability_dist(rng) < EPSILON) {
        // Exploration phase: random action selection
        std::uniform_int_distribution<> action_sampler(0, ACTIONS_COUNT - 1);
        return action_sampler(rng);
    } else {
        // Exploitation phase: greedy action selection
        double highest_value = -std::numeric_limits<double>::max();
        int optimal_action = 0;
        for (int possible_action = 0; possible_action < ACTIONS_COUNT; ++possible_action) {
            if (Q_TABLE[observation][possible_action] > highest_value) {
                highest_value = Q_TABLE[observation][possible_action];
                optimal_action = possible_action;
            }
        }
        return optimal_action;
    }
}

// Main Q-learning training loop
void train_agent() {
    for (int iteration = 0; iteration < TRAINING_ROUNDS; ++iteration) {
        int state = 0; // Initial state

        while (state != STATES_COUNT - 1) {
            int action = select_policy_action(state);
            auto [next_observation, reward] = simulate_environment(state, action);

            double best_future_value = -std::numeric_limits<double>::max();
            for (int future_action = 0; future_action < ACTIONS_COUNT; ++future_action) {
                if (Q_TABLE[next_observation][future_action] > best_future_value) {
                    best_future_value = Q_TABLE[next_observation][future_action];
                }
            }

            // Update Q-value using Bellman equation
            Q_TABLE[state][action] += ALPHA * (reward + GAMMA * best_future_value - Q_TABLE[state][action]);

            state = next_observation;
        }
    }
}

// Display learned Q-values
void display_q_values() {
    for (int state = 0; state < STATES_COUNT; ++state) {
        for (int action = 0; action < ACTIONS_COUNT; ++action) {
            std::cout << "Q(" << state << ", " << action << ") = " << Q_TABLE[state][action] << std::endl;
        }
    }
}

int main() {
    train_agent();
    display_q_values();
    return 0;
}

