// Function to show the current state of the chess board
void display_board() {
    cout << endl << "   a  b  c  d  e  f  g  h" << endl;
    for (int row = 0; row < 8; row++) {
        cout << row + 1 << "  ";
        for (int col = 0; col < 8; col++) {
            cout << grid[row][col] << "  ";
        }
        cout << row + 1 << endl;
    }
    cout << "   a  b  c  d  e  f  g  h" << endl << endl;
}

// Function to update the board after a valid move
void execute_move(int start_row, int start_col, int end_row, int end_col) {
    if (check_validity(start_row, start_col, end_row, end_col)) {
        swap(grid[start_row][start_col], grid[end_row][end_col]);
    }
}

int main() {
    bool white_turn = true;
    while (!game_ended(white_turn)) {
        display_board();
        cout << "Current player: " << ((white_turn) ? "White" : "Black") << endl;
        bool move_accepted = false;
        while (!move_accepted) {
            string input;
            cout << "Enter your move (e.g., e2e4): ";
            getline(cin, input);
            if (input.length() == 4) {
                int start_row = input[0] - 'a';
                int start_col = input[1] - '1';
                int end_row = input[2] - 'a';
                int end_col = input[3] - '1';

                // Check if piece belongs to current player and move is valid
                if (check_validity(start_row, start_col, end_row, end_col) && 
                    ((isupper(grid[start_row][start_col]) == white_turn))) {
                    execute_move(start_row, start_col, end_row, end_col);
                    move_accepted = true;
                }
            }
            if (!move_accepted) {
                cout << "Invalid move. Please try again." << endl;
            }
        }
        white_turn = !white_turn;
    }

    display_board();

    // Determine game outcome
    if (checkmate_detected(white_turn)) {
        cout << ((white_turn) ? "Black" : "White") << " wins by checkmate!" << endl;
    } else if (stalemate_detected(white_turn)) {
        cout << "Game ends in a draw due to stalemate." << endl;
    }

    return 0;
}

