// Determine whether a given integer is a prime number
bool checkPrime(int num) {
    if (num <= 1) return false;  // Numbers less than or equal to 1 are not prime
    if (num <= 3) return true;   // 2 and 3 are prime numbers

    // Eliminate multiples of 2 and 3 early
    if (num % 2 == 0 || num % 3 == 0) return false;

    // Check for factors up to sqrt(num), skipping even numbers and multiples of 3
    for (int j = 5; j * j <= num; j += 6) {
        if (num % j == 0 || num % (j + 2) == 0)
            return false;
    }
    return true;
}

int main() {
    std::cout << "Prime numbers below 100: " << std::endl;
    for (int value = 2; value < 100; ++value) {
        if (checkPrime(value)) {
            std::cout << value << " ";
        }
    }
    std::cout << std::endl;
    return 0;
}

#include <iostream>
