int main() {
    long long items, windowSize, temp;
    std::cin.sync_with_stdio(false);
    std::cin >> items >> windowSize >> temp;

    long long currentSum = 0, lowestSum = 0;
    long long leftBound = 1, rightBound = windowSize;

    std::queue<long long> slidingWindow;

    for (long long position = 1; position <= items; position++) {
        long long value;
        std::cin >> value;
        currentSum += value;
        slidingWindow.push(value);

        if (position >= windowSize) {
            if (position > windowSize) {
                currentSum -= slidingWindow.front();
                slidingWindow.pop();
            }

            if (currentSum < lowestSum) {
                lowestSum = currentSum;
                leftBound = position - windowSize + 1;
                rightBound = position;
            }
        }
    }

    std::cout << leftBound << " " << rightBound << std::endl;

    return 0;
}

