// Texture reference for 2D float texture data
texture<float, 2, cudaReadModeElementType> texRef;

__global__ void processKernel(float *deviceOutput, int imgWidth, int imgHeight) {
    int posX = blockIdx.x * blockDim.x + threadIdx.x;
    int posY = blockIdx.y * blockDim.y + threadIdx.y;

    if (posX < imgWidth && posY < imgHeight) {
        deviceOutput[posY * imgWidth + posX] = tex2D(texRef, posX, posY);
    }
}

int main() {
    float *deviceBuffer;
    cudaMalloc(&deviceBuffer, imgWidth * imgHeight * sizeof(float));
    cudaMemcpy(deviceBuffer, hostData, imgWidth * imgHeight * sizeof(float), cudaMemcpyHostToDevice);

    cudaChannelFormatDesc channelDescriptor = cudaCreateChannelDesc<float>();
    cudaBindTexture2D(0, &texRef, deviceBuffer, &channelDescriptor, imgWidth, imgHeight, imgWidth * sizeof(float));

    dim3 threadsPerBlock(16, 16);
    dim3 blocksPerGrid((imgWidth + threadsPerBlock.x - 1) / threadsPerBlock.x, 
                       (imgHeight + threadsPerBlock.y - 1) / threadsPerBlock.y);

    processKernel<<<blocksPerGrid, threadsPerBlock>>>(deviceBuffer, imgWidth, imgHeight);

    cudaUnbindTexture(texRef);
    cudaFree(deviceBuffer);

    return 0;
}

