// Evaluate polynomial with coefficients array at given point
float Polynomial(int degree, int coefficients[], float value) 
{   
    float result = 0.0f;
    int index;

    if(degree == 0)
    {
        result = coefficients[0];
    }
    else
    {
        result = coefficients[0];
        for(index = 1; index <= degree; index++)
        {
            result = result + coefficients[index] * value;
            value = value * value;
        }
    }

    return result;  // Return computed polynomial value
}

