}

unsigned int buildShaderProgram(const char* vertexFile, const char* fragmentFile)
{
    // Read shader source files
    std::string vertexSource;
    std::string fragmentSource;
    std::ifstream vShaderStream(vertexFile);
    std::ifstream fShaderStream(fragmentFile);

    if (!vShaderStream.is_open() || !fShaderStream.is_open())
    {
        std::cerr << "Failed to read shader files" << std::endl;
        return 0;
    }

    std::stringstream vShaderBuffer, fShaderBuffer;
    vShaderBuffer << vShaderStream.rdbuf();
    fShaderBuffer << fShaderStream.rdbuf();

    vShaderStream.close();
    fShaderStream.close();

    vertexSource = vShaderBuffer.str();
    fragmentSource = fShaderBuffer.str();

    const char* vShaderCode = vertexSource.c_str();
    const char* fShaderCode = fragmentSource.c_str();

    // Compile vertex shader
    unsigned int vertexShader = glCreateShader(GL_VERTEX_SHADER);
    glShaderSource(vertexShader, 1, &vShaderCode, NULL);
    glCompileShader(vertexShader);

    // Check vertex shader compilation status
    int success;
    char infoLog[512];
    glGetShaderiv(vertexShader, GL_COMPILE_STATUS, &success);
    if (!success)
    {
        glGetShaderInfoLog(vertexShader, 512, NULL, infoLog);
        std::cerr << "ERROR::SHADER::VERTEX::COMPILATION_FAILED\n" << infoLog << std::endl;
    }

    // Compile fragment shader
    unsigned int fragmentShader = glCreateShader(GL_FRAGMENT_SHADER);
    glShaderSource(fragmentShader, 1, &fShaderCode, NULL);
    glCompileShader(fragmentShader);

    // Check fragment shader compilation status
    glGetShaderiv(fragmentShader, GL_COMPILE_STATUS, &success);
    if (!success)
    {
        glGetShaderInfoLog(fragmentShader, 512, NULL, infoLog);
        std::cerr << "ERROR::SHADER::FRAGMENT::COMPILATION_FAILED\n" << infoLog << std::endl;
    }

    // Link shaders into program
    unsigned int shaderProgram = glCreateProgram();
    glAttachShader(shaderProgram, vertexShader);
    glAttachShader(shaderProgram, fragmentShader);
    glLinkProgram(shaderProgram);

    // Check program linking status
    glGetProgramiv(shaderProgram, GL_LINK_STATUS, &success);
    if (!success)
    {
        glGetProgramInfoLog(shaderProgram, 512, NULL, infoLog);
        std::cerr << "ERROR::SHADER::PROGRAM::LINKING_FAILED\n" << infoLog << std::endl;
    }

    // Delete intermediate shaders
    glDeleteShader(vertexShader);
    glDeleteShader(fragmentShader);

    return shaderProgram;
}

void constructCylinderMesh(float baseRadius, float cylHeight, int divisions, std::vector<float>& positionData, std::vector<float>& colorData)
{
    float angularStep = 2.0f * M_PI / divisions;

    for (int index = 0; index <= divisions; ++index)
    {
        float currentAngle = index * angularStep;
        float xPos = baseRadius * cos(currentAngle);
        float yPos = baseRadius * sin(currentAngle);

        // Top cap triangles
        positionData.push_back(xPos);
        positionData.push_back(yPos);
        positionData.push_back(cylHeight / 2.0f);

        positionData.push_back(0.0f);
        positionData.push_back(0.0f);
        positionData.push_back(cylHeight / 2.0f);

        positionData.push_back(xPos);
        positionData.push_back(yPos);
        positionData.push_back(-cylHeight / 2.0f);

        // Bottom cap triangles
        positionData.push_back(xPos);
        positionData.push_back(yPos);
        positionData.push_back(-cylHeight / 2.0f);

        positionData.push_back(0.0f);
        positionData.push_back(0.0f);
        positionData.push_back(-cylHeight / 2.0f);

        positionData.push_back(xPos);
        positionData.push_back(yPos);
        positionData.push_back(cylHeight / 2.0f);

        // Side triangles
        positionData.push_back(xPos);
        positionData.push_back(yPos);
        positionData.push_back(cylHeight / 2.0f);

        positionData.push_back(xPos);
        positionData.push_back(yPos);
        positionData.push_back(-cylHeight / 2.0f);

        positionData.push_back(baseRadius * cos((index + 1) * angularStep));
        positionData.push_back(baseRadius * sin((index + 1) * angularStep));
        positionData.push_back(cylHeight / 2.0f);

        positionData.push_back(baseRadius * cos((index + 1) * angularStep));
        positionData.push_back(baseRadius * sin((index + 1) * angularStep));
        positionData.push_back(cylHeight / 2.0f);

        positionData.push_back(xPos);
        positionData.push_back(yPos);
        positionData.push_back(-cylHeight / 2.0f);

        positionData.push_back(baseRadius * cos((index + 1) * angularStep));
        positionData.push_back(baseRadius * sin((index + 1) * angularStep));
        positionData.push_back(-cylHeight / 2.0f);

        // Assign random colors for each triangle
        colorData.push_back(static_cast<float>(rand()) / RAND_MAX);
        colorData.push_back(static_cast<float>(rand()) / RAND_MAX);
        colorData.push_back(static_cast<float>(rand()) / RAND_MAX);

