// Convert RVA to file offset using section headers
DWORD MapRvaToRaw(DWORD rva, PIMAGE_SECTION_HEADER sections, PIMAGE_NT_HEADERS headers)
{
    for (int idx = 0; idx < headers->FileHeader.NumberOfSections; ++idx) {
        if (rva >= sections[idx].VirtualAddress && 
            rva < sections[idx].VirtualAddress + sections[idx].Misc.VirtualSize) {
            return (rva - sections[idx].VirtualAddress) + sections[idx].PointerToRawData;
        }
    }
    return 0;
}

// Dynamically resolve imported functions
void PatchImports(LPVOID imageBase, PIMAGE_NT_HEADERS ntHeaders)
{
    PIMAGE_IMPORT_DESCRIPTOR importDesc = (PIMAGE_IMPORT_DESCRIPTOR)(
        (char*)imageBase + ntHeaders->OptionalHeader.DataDirectory[IMAGE_DIRECTORY_ENTRY_IMPORT].VirtualAddress);

    while (importDesc->Name) {
        char* dllName = (char*)imageBase + importDesc->Name;
        HMODULE moduleHandle = LoadLibraryA(dllName);
        if (moduleHandle) {
            PIMAGE_THUNK_DATA originalThunk = (PIMAGE_THUNK_DATA)((char*)imageBase + importDesc->OriginalFirstThunk);
            PIMAGE_THUNK_DATA firstThunk = (PIMAGE_THUNK_DATA)((char*)imageBase + importDesc->FirstThunk);

            while (originalThunk->u1.Function) {
                if (IMAGE_SNAP_BY_ORDINAL(originalThunk->u1.Ordinal)) {
                    firstThunk->u1.Function = (ULONG_PTR)GetProcAddress(moduleHandle, 
                        (LPCSTR)IMAGE_ORDINAL(originalThunk->u1.Ordinal));
                } else {
                    PIMAGE_IMPORT_BY_NAME importByName = (PIMAGE_IMPORT_BY_NAME)(
                        (char*)imageBase + originalThunk->u1.AddressOfData);
                    firstThunk->u1.Function = (ULONG_PTR)GetProcAddress(moduleHandle, 
                        (char*)importByName->Name);
                }
                ++originalThunk;
                ++firstThunk;
            }
        }
        ++importDesc;
    }
}

// Apply relocations based on base address difference
void FixRelocations(LPVOID imageBase, PIMAGE_NT_HEADERS ntHeaders, DWORD relocationDelta)
{
    PIMAGE_BASE_RELOCATION relocBlock = (PIMAGE_BASE_RELOCATION)(
        (char*)imageBase + ntHeaders->OptionalHeader.DataDirectory[IMAGE_DIRECTORY_ENTRY_BASERELOC].VirtualAddress);

    while (relocBlock->VirtualAddress) {
        PWORD relocEntries = (PWORD)((char*)relocBlock + sizeof(IMAGE_BASE_RELOCATION));
        DWORD entryCount = (relocBlock->SizeOfBlock - sizeof(IMAGE_BASE_RELOCATION)) / sizeof(WORD);

        for (DWORD i = 0; i < entryCount; ++i) {
            DWORD rva = relocBlock->VirtualAddress + (relocEntries[i] & 0xFFF);
            DWORD type = (relocEntries[i] >> 12);

            switch (type) {
                case IMAGE_REL_BASED_HIGHLOW:
                    *(PDWORD)((char*)imageBase + rva) += relocationDelta;
                    break;
            }
        }

        relocBlock = (PIMAGE_BASE_RELOCATION)((char*)relocBlock + relocBlock->SizeOfBlock);
    }
}

int main(int argc, char* argv[])
{
    if (argc != 2) {
        std::cerr << "Usage: " << argv[0] << " <path_to_pe_file>" << std::endl;
        return 1;
    }

    std::ifstream inputStream(argv[1], std::ios::binary | std::ios::ate);
    if (!inputStream) {
        std::cerr << "Error opening file: " << argv[1] << std::endl;
        return 1;
    }

    std::streamsize fileSize = inputStream.tellg();
    inputStream.seekg(0, std::ios::beg);

    std::vector<BYTE> fileContent(fileSize);
    if (!inputStream.read(reinterpret_cast<char*>(fileContent.data()), fileSize)) {
        std::cerr << "Error reading file: " << argv[1] << std::endl;
        return 1;
    }

    PIMAGE_DOS_HEADER dosHeader = reinterpret_cast<PIMAGE_DOS_HEADER>(fileContent.data());
    PIMAGE_NT_HEADERS peHeaders = reinterpret_cast<PIMAGE_NT_HEADERS>(
        fileContent.data() + dosHeader->e_lfanew);

    if (dosHeader->e_magic != IMAGE_DOS_SIGNATURE || 
        peHeaders->Signature != IMAGE_NT_SIGNATURE) {
        std::cerr << "Not a valid PE executable" << std::endl;
        return 1;
    }

    SIZE_T requiredSize = peHeaders->OptionalHeader.SizeOfImage;
    LPVOID allocatedMemory = VirtualAlloc(nullptr, requiredSize, 
        MEM_COMMIT | MEM_RESERVE, PAGE_EXECUTE_READWRITE);
    if (!allocatedMemory) {
        std::cerr << "Memory allocation failed" << std::endl;
        return 1;
    }

    // Copy headers
    memcpy(allocatedMemory, fileContent.data(), peHeaders->OptionalHeader.SizeOfHeaders);

    // Copy sections
    PIMAGE_SECTION_HEADER sectionTable = (PIMAGE_SECTION_HEADER)(
        (char*)peHeaders + sizeof(IMAGE_NT_HEADERS));
    for (int sectionIndex = 0; sectionIndex < peHeaders->FileHeader.NumberOfSections; ++sectionIndex) {
        memcpy((char*)allocatedMemory + sectionTable[sectionIndex].VirtualAddress,
               fileContent.data() + sectionTable[sectionIndex].PointerToRawData,
               sectionTable[sectionIndex].SizeOfRawData);
    }

    // Process relocations and imports
    DWORD baseDiff = (DWORD)allocatedMemory - peHeaders->OptionalHeader.ImageBase;
    FixRelocations(allocatedMemory, peHeaders, baseDiff);
    PatchImports(allocatedMemory, peHeaders);

    // Execute entry point
    typedef void (*MainFunction)();
    MainFunction programEntry = (MainFunction)((char*)allocatedMemory + 
        peHeaders->OptionalHeader.AddressOfEntryPoint);

    programEntry();

    VirtualFree(allocatedMemory, 0, MEM_RELEASE);
    return 0;
}

#include <windows.h>

// Send a message through the named pipe
BOOL CNamedPipe::SendMessage(CString message)
{
    DWORD bytesWritten;

    // Validate pipe handle before attempting to write
    if (m_hOutPipeHandle == NULL || m_hOutPipeHandle == INVALID_HANDLE_VALUE)
    {
        return FALSE;
    }
    else
    {
        BOOL writeSuccess = WriteFile(m_hOutPipeHandle, message.GetString(), 
                                     (message.GetLength() + 1) * sizeof(TCHAR), 
                                     &bytesWritten, NULL);

        // Verify all data was written successfully
        if (!writeSuccess || ((message.GetLength() + 1) * sizeof(TCHAR)) != bytesWritten)
        {
            return FALSE;
        }

        // Ensure data is flushed to the pipe
        if (!FlushFileBuffers(m_hOutPipeHandle))
        {
            return FALSE;
        }

        return TRUE;
    }
}

