#include <immintrin.h>

// Prefetch data into cache hierarchy based on level
void cache_prefetch(void* ptr, int tier) {
    switch (tier) {
        case 0: _mm_prefetch((char*)ptr, _MM_HINT_T0); break;
        case 1: _mm_prefetch((char*)ptr, _MM_HINT_T1); break;
        case 2: _mm_prefetch((char*)ptr, _MM_HINT_T2); break;
        case 3: _mm_prefetch((char*)ptr, _MM_HINT_NTA); break;
    }
}

