#include <iostream>

// Perform quicksort on the array segment from index 'start' to 'end'
void quickSort(int data[], int start, int end) {
    if (start < end) {
        // Partition the array and get pivot index
        int pivotIndex = partition(data, start, end);

        // Recursively sort subarrays before and after pivot
        quickSort(data, start, pivotIndex - 1);
        quickSort(data, pivotIndex + 1, end);
    }
}

// Partition function that places pivot at correct position
int partition(int data[], int start, int end) {
    int pivotValue = data[end];  // Choose last element as pivot
    int smallerIndex = (start - 1);  // Index of smaller element

    for (int j = start; j <= end - 1; j++) {
        // If current element is less than or equal to pivot
        if (data[j] <= pivotValue) {
            smallerIndex++;    // Move index of smaller element forward
            std::swap(data[smallerIndex], data[j]);
        }
    }
    std::swap(data[smallerIndex + 1], data[end]);
    return (smallerIndex + 1);
}

