// C++ class representing the sequence generator
class SequenceGenerator {
public:
  SequenceGenerator(int begin, int finish) : current(begin), limit(finish) {}

  bool hasMore() const {
    return current < limit;
  }

  int advance() {
    return current++;
  }

private:
  int current;
  int limit;
};

// C++ function to create a new generator instance
void CreateInstance(const FunctionCallbackInfo<Value>& args) {
  Isolate* isolate = args.GetIsolate();
  Local<Context> context = isolate->GetCurrentContext();

  if (args.IsConstructCall()) {
    int startVal = args[0]->IntegerValue(context).ToChecked();
    int endVal = args[1]->IntegerValue(context).ToChecked();

    SequenceGenerator* gen = new SequenceGenerator(startVal, endVal);
    args.This()->SetInternalField(0, External::New(isolate, gen));

    args.GetReturnValue().Set(args.This());
  } else {
    Local<Function> cons = Local<Function>::New(isolate, constructorRef);
    Local<Value> argv[2] = { args[0], args[1] };
    args.GetReturnValue().Set(cons->NewInstance(context, 2, argv).ToLocalChecked());
  }
}

// C++ function to implement the `next` method
void GetNextValue(const FunctionCallbackInfo<Value>& args) {
  Isolate* isolate = args.GetIsolate();
  Local<Context> context = isolate->GetCurrentContext();
  SequenceGenerator* gen = static_cast<SequenceGenerator*>(args.This()->GetInternalField(0).As<External>()->Value());

  if (gen->hasMore()) {
    int value = gen->advance();
    Local<Object> result = Object::New(isolate);
    result->Set(context, String::NewFromUtf8(isolate, "value").ToLocalChecked(), Number::New(isolate, value));
    result->Set(context, String::NewFromUtf8(isolate, "done").ToLocalChecked(), Boolean::New(isolate, false));
    args.GetReturnValue().Set(result);
  } else {
    Local<Object> result = Object::New(isolate);
    result->Set(context, String::NewFromUtf8(isolate, "value").ToLocalChecked(), Undefined(isolate));
    result->Set(context, String::NewFromUtf8(isolate, "done").ToLocalChecked(), Boolean::New(isolate, true));
    args.GetReturnValue().Set(result);
  }
}

// C++ function to implement the `Symbol.iterator` method
void GetIteratorMethod(const PropertyCallbackInfo<Value>& args) {
  Isolate* isolate = args.GetIsolate();
  Local<Context> context = isolate->GetCurrentContext();
  args.GetReturnValue().Set(args.Holder());
}

// Persistent reference to the constructor
Persistent<Function> SequenceGenerator::constructorRef;

void SetupModule(Local<Object> exports) {
  Isolate* isolate = exports->GetIsolate();

  // Prepare constructor template
  Local<FunctionTemplate> tpl = FunctionTemplate::New(isolate, CreateInstance);
  tpl->SetClassName(String::NewFromUtf8(isolate, "SequenceGenerator").ToLocalChecked());
  tpl->InstanceTemplate()->SetInternalFieldCount(1);

  // Prototype methods
  NODE_SET_PROTOTYPE_METHOD(tpl, "next", GetNextValue);
  tpl->InstanceTemplate()->Set(String::NewFromUtf8(isolate, Symbol::GetIterator(isolate)).ToLocalChecked(), FunctionTemplate::New(isolate, GetIteratorMethod)->GetFunction(context).ToLocalChecked());

  constructorRef.Reset(isolate, tpl->GetFunction(context).ToLocalChecked());
  exports->Set(context, String::NewFromUtf8(isolate, "SequenceGenerator").ToLocalChecked(), tpl->GetFunction(context).ToLocalChecked());
}

