#include <cuda_runtime.h>
#include <iostream>
#include <cmath>

#define TILE_DIM 16

__global__ void calculatePairwiseDistances(float *inputX, float *inputY, float *outputD, int rowsX, int colsY) {
    __shared__ float Y_shared[TILE_DIM * 128];

    int rowX = blockIdx.x;
    int colY_start = blockIdx.y * TILE_DIM + threadIdx.x;
    int colY_limit = colY_start + TILE_DIM;

    // Copy Y tiles into shared memory
    for (int idx = colY_start; idx < colY_limit && idx < colsY; idx++) {
        for (int j = 0; j < 128; j++) {
            Y_shared[(idx - colY_start) * 128 + j] = inputY[idx * 128 + j];
        }
    }
    __syncthreads();

    // Compute Euclidean distances
    for (int idx = colY_start; idx < colY_limit && idx < colsY; idx++) {
        float accumulator = 0.0f;
        for (int k = 0; k < 128; k++) {
            float diff = inputX[rowX * 128 + k] - Y_shared[(idx - colY_start) * 128 + k];
            accumulator += diff * diff;
        }
        outputD[rowX * colsY + idx] = sqrtf(accumulator);
    }
}

int main() {
    int n_samples = 1000;
    int m_features = 1000;
    size_t bytesX = n_samples * 128 * sizeof(float);
    size_t bytesY = m_features * 128 * sizeof(float);
    size_t bytesOut = n_samples * m_features * sizeof(float);

    float *hostX = new float[n_samples * 128];
    float *hostY = new float[m_features * 128];
    float *hostResult = new float[n_samples * m_features];

    // Seed and populate host arrays with pseudo-random data
    for (int i = 0; i < n_samples * 128; i++) {
        hostX[i] = static_cast<float>(rand()) / RAND_MAX;
    }
    for (int i = 0; i < m_features * 128; i++) {
        hostY[i] = static_cast<float>(rand()) / RAND_MAX;
    }

    float *devX, *devY, *devOut;
    cudaMalloc(&devX, bytesX);
    cudaMalloc(&devY, bytesY);
    cudaMalloc(&devOut, bytesOut);

    cudaMemcpy(devX, hostX, bytesX, cudaMemcpyHostToDevice);
    cudaMemcpy(devY, hostY, bytesY, cudaMemcpyHostToDevice);

    dim3 blockSize(TILE_DIM, 1);
    dim3 gridSize((m_features + TILE_DIM - 1) / TILE_DIM, n_samples);

    calculatePairwiseDistances<<<gridSize, blockSize>>>(devX, devY, devOut, n_samples, m_features);

    cudaMemcpy(hostResult, devOut, bytesOut, cudaMemcpyDeviceToHost);

    // Release resources
    cudaFree(devX);
    cudaFree(devY);
    cudaFree(devOut);
    delete[] hostX;
    delete[] hostY;
    delete[] hostResult;

    return 0;
}

