#include <boost/python.hpp>
#include <vector>

// Base abstract class A with pure virtual method
struct BaseClassA {
    std::vector<int> data_values;

    virtual void process() = 0;
};

// Interface class B that depends on A
struct InterfaceB {
    virtual void execute(const BaseClassA& input) = 0;
};

namespace py = boost::python;

// Wrapper for BaseClassA to support Python overrides
struct BaseClassA_wrapper : BaseClassA, py::wrapper<BaseClassA> {
    void process() override {
        this->get_override("process")();
    }
};

// Wrapper for InterfaceB to support Python overrides
struct InterfaceB_wrapper : InterfaceB, py::wrapper<InterfaceB> {
    void execute(const BaseClassA& input) override {
        this->get_override("execute")(input);
    }
};

// Converter from C++ A to Python object
struct A_to_python_converter {
    static PyObject* convert(const BaseClassA& obj) {
        py::object py_obj = py::object(py::ptr(new BaseClassA_wrapper(obj)));
        return py_obj.ptr();
    }
};

BOOST_PYTHON_MODULE(module_example) {
    typedef std::vector<int> int_vector_type;

    // Expose vector<int> as IntSequence in Python
    py::class_<int_vector_type>("IntSequence")
        .def(py::vector_indexing_suite<int_vector_type>());

    // Expose BaseClassA with readwrite access and pure virtual method
    py::class_<BaseClassA_wrapper, boost::noncopyable>("BaseClassA")
        .def_readwrite("data_values", &BaseClassA::data_values)
        .def("process", py::pure_virtual(&BaseClassA::process));

