#include <immintrin.h>

struct vector4 {
    float x, y, z, w;
};

void assemblycalc(vector4 &input, vector4 &scale, float factor, vector4 &offset, vector4 &output)
{
    __m128 inputVec = _mm_loadu_ps(&input.x);
    __m128 scaleVec = _mm_loadu_ps(&scale.x);
    __m128 factorVec = _mm_set1_ps(factor);
    __m128 offsetVec = _mm_loadu_ps(&offset.x);

    // Perform rotation-like computation using SIMD operations
    __m128 prod1 = _mm_mul_ps(inputVec, scaleVec); // (input.x * scale.x, etc.)
    __m128 prod1_shuf1 = _mm_shuffle_ps(prod1, prod1, _MM_SHUFFLE(2, 3, 0, 1)); // swap pairs
    __m128 prod1_shuf2 = _mm_shuffle_ps(prod1, prod1, _MM_SHUFFLE(1, 0, 3, 2)); // reverse order
    __m128 prod1_shuf3 = _mm_shuffle_ps(prod1_shuf2, prod1_shuf2, _MM_SHUFFLE(2, 3, 0, 1)); // swap again

    __m128 diff1 = _mm_sub_ps(prod1, prod1_shuf3); // first combination
    __m128 diff2 = _mm_sub_ps(prod1_shuf1, prod1_shuf2); // second combination

    // Apply scaling factor
    __m128 scaledDiff1 = _mm_mul_ps(diff1, factorVec);
    __m128 scaledDiff2 = _mm_mul_ps(diff2, factorVec);

    // Subtract from offset values
    __m128 finalResult1 = _mm_sub_ps(offsetVec, scaledDiff1);
    __m128 finalResult2 = _mm_sub_ps(offsetVec, scaledDiff2);

    // Write results to output structure
    _mm_storeu_ps(&output.x, finalResult1);
    _mm_storeu_ps(&output.y, finalResult2);
}

#include <immintrin.h>
#include <cstdint>
#include <cstdio>

// Reorder 8-bit elements using AVX2 shuffle instruction
void reorder_bytes(const uint8_t* source, uint8_t* destination, const uint8_t* mapping) {
    __m256i data_vec = _mm256_loadu_si256(reinterpret_cast<const __m256i*>(source));
    __m256i index_vec = _mm256_loadu_si256(reinterpret_cast<const __m256i*>(mapping));
    __m256i result_vec = _mm256_shuffle_epi8(data_vec, index_vec);
    _mm256_storeu_si256(reinterpret_cast<__m256i*>(destination), result_vec);
}

int main() {
