#pragma comment(lib, "ws2_32.lib")

class NetworkHandler
{
public:
    class ClientSession
    {
    public:
        ClientSession(SOCKET socket) : clientSocket(socket), isDisconnected(false), transmissionFailure(false)
        {
            notificationEvent = WSACreateEvent();
            if (notificationEvent == WSA_INVALID_EVENT)
            {
                std::cerr << "Event creation failed: " << WSAGetLastError() << std::endl;
                return;
            }

            // Monitor for FD_WRITE events
            if (WSAEventSelect(clientSocket, notificationEvent, FD_WRITE) == SOCKET_ERROR)
            {
                std::cerr << "Failed to set up event selection: " << WSAGetLastError() << std::endl;
                WSACloseEvent(notificationEvent);
                notificationEvent = WSA_INVALID_EVENT;
                return;
            }
        }

        ~ClientSession()
        {
            if (notificationEvent != WSA_INVALID_EVENT)
            {
                WSAEventSelect(clientSocket, notificationEvent, 0); // Disable event monitoring
                WSACloseEvent(notificationEvent);
            }
        }

        void TransmitData(unsigned char buffer[], const int size)
        {
            if (isDisconnected || transmissionFailure)
                return;

            std::lock_guard<std::mutex> guard(mutexLock);

            dataBuffer.buf = (char*)buffer;
            dataBuffer.len = size;

            // Wait until the socket becomes writable
            DWORD outcome = WSAWaitForMultipleEvents(1, &notificationEvent, FALSE, INFINITE, FALSE);
            if (outcome == WSA_WAIT_EVENT_0)
            {
                // Socket ready for writing
                if (WSASend(clientSocket, &dataBuffer, 1, &transmittedBytes, 0, NULL, NULL) == SOCKET_ERROR)
                {
                    int errorCode = WSAGetLastError();
                    if (errorCode != WSA_IO_PENDING)
                    {
                        std::cerr << "Transmission error: " << errorCode << std::endl;
                        transmissionFailure = true;
                    }
                }
            }
            else
            {
                std::cerr << "Event wait failed with code: " << outcome << std::endl;
                transmissionFailure = true;
            }
        }

    private:
        SOCKET clientSocket;
        WSAEvent notificationEvent;
        bool isDisconnected;
        bool transmissionFailure;
        std::mutex mutexLock;
        WSABUF dataBuffer;
        DWORD transmittedBytes;
    };
};

int main()
{
    WSADATA wsaData;
    if (WSAStartup(MAKEWORD(2, 2), &wsaData) != 0)
    {
        std::cerr << "Winsock initialization failed: " << WSAGetLastError() << std::endl;
        return 1;
    }

    // Create a TCP socket
    SOCKET sock = socket(AF_INET, SOCK_STREAM, IPPROTO_TCP);
    if (sock == INVALID_SOCKET)
    {
        std::cerr << "Socket creation failed: " << WSAGetLastError() << std::endl;
        WSACleanup();
        return 1;
    }

    // Configure server address and connect
    sockaddr_in serverAddress;
    serverAddress.sin_family = AF_INET;
    serverAddress.sin_port = htons(8080);
    inet_pton(AF_INET, "192.168.1.100", &serverAddress.sin_addr);
    if (connect(sock, (sockaddr*)&serverAddress, sizeof(serverAddress)) == SOCKET_ERROR)
    {
        std::cerr << "Connection attempt failed: " << WSAGetLastError() << std::endl;
        closesocket(sock);
        WSACleanup();
        return 1;
    }

    // Switch to non-blocking mode
    u_long flags = 1;
    if (ioctlsocket(sock, FIONBIO, &flags) == SOCKET_ERROR)
    {
        std::cerr << "Non-blocking setup failed: " << WSAGetLastError() << std::endl;
        closesocket(sock);
        WSACleanup();
        return 1;
    }

    NetworkHandler::ClientSession session(sock);

    // Sample payload
    unsigned char message[] = "Greetings from client!";
    session.TransmitData(message, sizeof(message) - 1);

    // Cleanup resources
    closesocket(sock);
    WSACleanup();

    return 0;
}

