void* create_executable_region(size_t bytes) {
    void *region = mmap(
        nullptr,
        bytes,
        PROT_READ | PROT_WRITE | PROT_EXEC,
        MAP_PRIVATE | MAP_ANONYMOUS,
        -1,
        0
    );
    if (region == reinterpret_cast<void*>(-1)) {
        std::perror("mmap failed");
        return nullptr;
    }
    return region;
}

void copy_bytes_to_region(size_t len, const uint8_t *src, void *dst) {
    std::memcpy(static_cast<uint8_t*>(dst), src, len);
}

using ExecutableFunction = void (*)();

int main(int argc, char* argv[]) {
    if (argc <= 1) {
        return 1;
    }

    size_t num_bytes = static_cast<size_t>(argc - 1);
    uint8_t instructions[num_bytes];

    for (size_t idx = 0; idx < num_bytes; ++idx) {
        instructions[idx] = static_cast<uint8_t>(
            std::stoul(argv[idx + 1], nullptr, 16)
        );
    }

    void *exec_mem = create_executable_region(num_bytes);
    if (!exec_mem) {
        return 1;
    }

    copy_bytes_to_region(num_bytes, instructions, exec_mem);

    ExecutableFunction run_code = reinterpret_cast<ExecutableFunction>(exec_mem);
    run_code();

    return 0;
}

