// Convert a character array to its binary string representation
std::string convertToBinary(const char* input, int length) {
    std::string result;
    for (int index = 0; index < length; ++index) {
        int value = static_cast<int>(input[index]);
        std::string bits;
        while (value != 0) {
            bits.insert(bits.begin(), (value % 2 == 1) ? '1' : '0');
            value /= 2;
        }
        while (bits.length() < 8) {
            bits.insert(bits.begin(), '0');
        }
        result += bits;
    }
    return result;
}

