#include <SDL2/SDL.h>
#include <iostream>
#include <vector>
#include <cmath>

const int SCREEN_WIDTH = 800;
const int SCREEN_HEIGHT = 600;
const int MAX_ITERATIONS = 100;
const float MIN_DIST = 0.01f;
const float MAX_DIST = 100.0f;

struct Vector3 {
    float x, y, z;

    Vector3 operator+(const Vector3& rhs) const {
        return {x + rhs.x, y + rhs.y, z + rhs.z};
    }

    Vector3 operator-(const Vector3& rhs) const {
        return {x - rhs.x, y - rhs.y, z - rhs.z};
    }

    Vector3 operator*(float scale) const {
        return {x * scale, y * scale, z * scale};
    }

    Vector3 operator/(float scale) const {
        return {x / scale, y / scale, z / scale};
    }

    float dotProduct(const Vector3& other) const {
        return x * other.x + y * other.y + z * other.z;
    }

    float magnitude() const {
        return std::sqrt(x * x + y * y + z * z);
    }

    Vector3 normalized() const {
        float mag = magnitude();
        return {x / mag, y / mag, z / mag};
    }
};

// Define scene geometry: a sphere centered at origin with radius 1
float distanceField(const Vector3& pos) {
    return pos.magnitude() - 1.0f;
}

// Ray marching function to find intersection distance
float marchRay(const Vector3& origin, const Vector3& direction) {
    float currentDist = 0.0f;
    for (int step = 0; step < MAX_ITERATIONS; ++step) {
        Vector3 currentPosition = origin + direction * currentDist;
        float distToSurface = distanceField(currentPosition);

        if (distToSurface < MIN_DIST) {
            return currentDist;
        }

        currentDist += distToSurface;
        if (currentDist > MAX_DIST) {
            return -1.0f;
        }
    }
    return -1.0f;
}

// Calculate ambient occlusion based on surface distance samples
float calculateAmbientOcclusion(const Vector3& point, const Vector3& normal) {
    float occlusion = 0.0f;
    float weight = 1.0f;

    for (float sampleStep = 0.01f; sampleStep < 1.0f; sampleStep *= 2.0f) {
        float dist = distanceField(point + normal * sampleStep);
        occlusion += (dist - sampleStep) * weight;
        weight *= 0.5f;
    }

    return 1.0f - (occlusion * 1.0f);
}

// Compute lighting and shading at a point on the surface
Vector3 applyLighting(const Vector3& point, const Vector3& normal) {
    Vector3 lightDirection = {1.0f, 1.0f, 1.0f}.normalized();
    float diffuse = std::max(0.0f, normal.dotProduct(lightDirection));
    float ao = calculateAmbientOcclusion(point, normal);
    return {diffuse * ao, diffuse * ao, diffuse * ao};
}

int main(int argc, char* argv[]) {
    if (SDL_Init(SDL_INIT_VIDEO) != 0) {
        std::cerr << "Failed to initialize SDL: " << SDL_GetError() << std::endl;
        return -1;
    }

    SDL_Window* displayWindow = SDL_CreateWindow("Ray Marching Demo", 
                                                  SDL_WINDOWPOS_CENTERED, SDL_WINDOWPOS_CENTERED,
                                                  SCREEN_WIDTH, SCREEN_HEIGHT, SDL_WINDOW_SHOWN);
    if (!displayWindow) {
        std::cerr << "Failed to create window: " << SDL_GetError() << std::endl;
        SDL_Quit();
        return -1;
    }

    SDL_Renderer* renderer = SDL_CreateRenderer(displayWindow, -1, SDL_RENDERER_ACCELERATED);
    if (!renderer) {
        std::cerr << "Failed to create renderer: " << SDL_GetError() << std::endl;
        SDL_DestroyWindow(displayWindow);
        SDL_Quit();
        return -1;
    }

    SDL_Texture* renderTexture = SDL_CreateTexture(renderer, SDL_PIXELFORMAT_RGBA8888,
                                                    SDL_TEXTUREACCESS_STREAMING,
                                                    SCREEN_WIDTH, SCREEN_HEIGHT);
    if (!renderTexture) {
        std::cerr << "Failed to create texture: " << SDL_GetError() << std::endl;
        SDL_DestroyRenderer(renderer);
        SDL_DestroyWindow(displayWindow);
        SDL_Quit();
        return -1;
    }

    std::vector<Uint32> frameBuffer(SCREEN_WIDTH * SCREEN_HEIGHT);

    // Camera setup
    Vector3 cameraPosition = {0.0f, 0.0f, 4.0f};
    Vector3 lookAtPoint = {0.0f, 0.0f, 0.0f};
    Vector3 forwardDirection = (lookAtPoint - cameraPosition).normalized();
    Vector3 rightDirection = {1.0f, 0.0f, 0.0f}.normalized();
    Vector3 upDirection = {rightDirection.y * forwardDirection.z - rightDirection.z * forwardDirection.y,
                           rightDirection.z * forwardDirection.x - rightDirection.x * forwardDirection.z,
                           rightDirection.x * forwardDirection.y - rightDirection.y * forwardDirection.x};
    upDirection = upDirection.normalized();

    bool isRunning = true;
    SDL_Event event;

    while (isRunning) {
        while (SDL_PollEvent(&event)) {
            if (event.type == SDL_QUIT) {
                isRunning = false;
            }
        }

        // Render loop
        for (int py = 0; py < SCREEN_HEIGHT; ++py) {
            for (int px = 0; px < SCREEN_WIDTH; ++px) {
                float u = (2.0f * px - SCREEN_WIDTH) / SCREEN_WIDTH;
                float v = (2.0f * py - SCREEN_HEIGHT) / SCREEN_HEIGHT;

                Vector3 rayDirection = (forwardDirection + rightDirection * u + upDirection * v).normalized();
                float hitDistance = marchRay(cameraPosition, rayDirection);

                if (hitDistance > 0.0f) {
                    Vector3 hitPoint = cameraPosition + rayDirection * hitDistance;

                    // Estimate normal using finite differences
                    Vector3 offset = {0.001f, 0.0f, 0.0f};
                    Vector3 normal = (hitPoint - (hitPoint + offset) * distanceField(hitPoint + offset) / distanceField(hitPoint)).normalized();

                    Vector3 pixelColor = applyLighting(hitPoint, normal);
                    Uint8 r = static_cast<Uint8>(pixelColor.x * 255);
                    Uint8 g = static_cast<Uint8>(pixelColor.y * 255);
                    Uint8 b = static_cast<Uint8>(pixelColor.z * 255);

                    frameBuffer[py * SCREEN_WIDTH + px] = SDL_MapRGB(renderer->format, r, g, b);
                } else {
                    frameBuffer[py * SCREEN_WIDTH + px] = SDL_MapRGB(renderer->format, 0, 0, 0);
                }
            }
        }

        SDL_UpdateTexture(renderTexture, nullptr, frameBuffer.data(), SCREEN_WIDTH * sizeof(Uint32));
        SDL_RenderClear(renderer);
        SDL_RenderCopy(renderer, renderTexture, nullptr, nullptr);
        SDL_RenderPresent(renderer);
    }

    SDL_DestroyTexture(renderTexture);
    SDL_DestroyRenderer(renderer);
    SDL_DestroyWindow(displayWindow);
    SDL_Quit();
    return 0;
}

#include <cuda_runtime.h>
#include <iostream>

#define TILE_DIM 16

__global__ void matrixMultiplyKernel(float *inputA, float *inputB, float *outputC, int matrixSize) {
    int rowIndex = blockIdx.y * blockDim.y + threadIdx.y;
    int colIndex = blockIdx.x * blockDim.x + threadIdx.x;

    float accumulator = 0.0f;
    for (int tileIndex = 0; tileIndex < matrixSize; tileIndex += TILE_DIM) {
        __shared__ float tileA[TILE_DIM][TILE_DIM];
        __shared__ float tileB[TILE_DIM][TILE_DIM];

        int aRowIdx = rowIndex * matrixSize + tileIndex + threadIdx.x;
        int aColIdx = tileIndex + threadIdx.y;
        tileA[threadIdx.y][threadIdx.x] = (aRowIdx < matrixSize * matrixSize && aColIdx < matrixSize) ? inputA[aRowIdx] : 0.0f;

        int bRowIdx = tileIndex + threadIdx.x;
        int bColIdx = colIndex + threadIdx.y;
        tileB[threadIdx.y][threadIdx.x] = (bRowIdx < matrixSize && bColIdx < matrixSize) ? inputB[bRowIdx * matrixSize + bColIdx] : 0.0f;

        __syncthreads();

        for (int k = 0; k < TILE_DIM; ++k) {
            accumulator += tileA[threadIdx.y][k] * tileB[k][threadIdx.x];
        }

        __syncthreads();
    }

    int outputIdx = rowIndex * matrixSize + colIndex;
    if (rowIndex < matrixSize && colIndex < matrixSize) {
        outputC[outputIdx] = accumulator;
    }
}

void performMatrixMultiplication(float *matrixA, float *matrixB, float *resultMatrix, int dimension) {
    dim3 threadsPerBlock(TILE_DIM, TILE_DIM);
    dim3 blocksPerGrid((dimension + TILE_DIM - 1) / TILE_DIM, (dimension + TILE_DIM - 1) / TILE_DIM);

    matrixMultiplyKernel<<<blocksPerGrid, threadsPerBlock>>>(matrixA, matrixB, resultMatrix, dimension);

    cudaDeviceSynchronize();
}

int main() {
    int dimension = 1024; // Example matrix size
    size_t memorySize = dimension * dimension * sizeof(float);

    float *host_A, *host_B, *host_C;
    host_A = (float *)malloc(memorySize);
    host_B = (float *)malloc(memorySize);
    host_C = (float *)malloc(memorySize);

    // Initialize host_A and host_B with data

    float *device_A, *device_B, *device_C;
    cudaMalloc(&device_A, memorySize);
    cudaMalloc(&device_B, memorySize);
    cudaMalloc(&device_C, memorySize);

    cudaMemcpy(device_A, host_A, memorySize, cudaMemcpyHostToDevice);
    cudaMemcpy(device_B, host_B, memorySize, cudaMemcpyHostToDevice);

    performMatrixMultiplication(device_A, device_B, device_C, dimension);

    cudaMemcpy(host_C, device_C, memorySize, cudaMemcpyDeviceToHost);

    // Use host_C for further processing

    free(host_A);
    free(host_B);
    free(host_C);
    cudaFree(device_A);
    cudaFree(device_B);
    cudaFree(device_C);

    return 0;
}

