// Function to display Fibonacci sequence up to n terms
void showFibonacci(int count) {
    int first = 0, second = 1, nextValue = 0;

    for (int index = 1; index <= count; ++index) {
        // Outputs the initial two values
        if(index == 1) {
            cout << first << ", ";
            continue;
        }
        if(index == 2) {
            cout << second << ", ";
            continue;
        }
        nextValue = first + second;
        first = second;
        second = nextValue;

        cout << nextValue;
        if(index < count) {
            cout << ", ";
        }
    }
}

int main() {
    int number;
    cout << "Enter the number of terms: ";
    cin >> number;

    cout << "Fibonacci Series: ";
    showFibonacci(number);

    return 0;
}

