int WINAPI customMessageBoxA(HWND hwnd, LPCSTR text, LPCSTR caption, UINT type)
{
    // Custom behavior implementation
    return 42;
}

void applyMessageBoxHook()
{
    DWORD previousProtect;
    VirtualProtect(MessageBoxA, 6, PAGE_EXECUTE_READWRITE, &previousProtect);

    // Prepare the jump instruction to redirect execution
    BYTE redirection[6] = { 0xE9, 0x00, 0x00, 0x00, 0x00, 0xC3 };
    DWORD relativeAddress = (DWORD)customMessageBoxA - ((DWORD)MessageBoxA + 5);
    *(DWORD*)(redirection + 1) = relativeAddress;

    memcpy(MessageBoxA, redirection, 6);

    VirtualProtect(MessageBoxA, 6, previousProtect, &previousProtect);
}

int main()
{
    applyMessageBoxHook();

    int result1 = MessageBoxA(NULL, "Hello World", "Injector", MB_OK);

    printf("Result: %d\n", result1);
    printf("Result: %d\n", MessageBoxA(NULL, "Hello World", "Injector", MB_OK));

    std::cout << "Result: " << result1 << std::endl;
    std::cout << "Result: " << MessageBoxA(NULL, "Hello World", "Injector", MB_OK) << std::endl;

    printf("Execution Complete\n");

    return 0;
}

