int main() {
    DWORD processId = 0;
    std::cout << "Enter PID: ";
    std::cin >> processId;

    HANDLE hProc = OpenProcess(PROCESS_ALL_ACCESS, FALSE, processId);
    if (!hProc) {
        std::cerr << "Failed to open process. Error code: " << GetLastError() << std::endl;
        return 1;
    }

    void* remoteMemory = VirtualAllocEx(hProc, nullptr, 4096, MEM_COMMIT | MEM_RESERVE, PAGE_EXECUTE_READWRITE);
    if (!remoteMemory) {
        std::cerr << "VirtualAllocEx failed. Error code: " << GetLastError() << std::endl;
        CloseHandle(hProc);
        return 1;
    }

    // Define a simple function to inject (beep with fixed parameters)
    auto injectableFunction = []() __attribute__((naked)) {
        __asm {
            push 0x3E8       // duration: 1000 ms
            push 0x2710      // frequency: 10000 Hz
            call Beep
            xor eax, eax
            ret
        }
    };

    SIZE_T bytesWritten = 0;
    BOOL writeResult = WriteProcessMemory(hProc, remoteMemory, 
                                          &injectableFunction, 
                                          sizeof(injectableFunction), 
                                          &bytesWritten);
    if (!writeResult || bytesWritten == 0) {
        std::cerr << "WriteProcessMemory failed. Error code: " << GetLastError() << std::endl;
        VirtualFreeEx(hProc, remoteMemory, 0, MEM_RELEASE);
        CloseHandle(hProc);
        return 1;
    }

    HANDLE hRemoteThread = CreateRemoteThread(hProc, nullptr, 0,
                                              reinterpret_cast<LPTHREAD_START_ROUTINE>(remoteMemory),
                                              nullptr, 0, nullptr);
    if (!hRemoteThread) {
        std::cerr << "CreateRemoteThread failed. Error code: " << GetLastError() << std::endl;
        VirtualFreeEx(hProc, remoteMemory, 0, MEM_RELEASE);
        CloseHandle(hProc);
        return 1;
    }

    WaitForSingleObject(hRemoteThread, INFINITE);

    VirtualFreeEx(hProc, remoteMemory, 0, MEM_RELEASE);
    CloseHandle(hRemoteThread);
    CloseHandle(hProc);

    return 0;
}

#include <openssl/aes.h>
#include <openssl/evp.h>
#include <string>
#include <vector>

std::string decrypt_data(const std::vector<uint8_t>& encrypted, const std::vector<uint8_t>& secret_key, const std::vector<uint8_t>& initialization_vector)
{
    EVP_CIPHER_CTX* context = EVP_CIPHER_CTX_new();
    if (!context) {
        // Handle error
        return "";
    }

    if (EVP_DecryptInit_ex(context, EVP_aes_256_cbc(), nullptr, secret_key.data(), initialization_vector.data()) != 1) {
        EVP_CIPHER_CTX_free(context);
        // Handle error
        return "";
    }

    std::vector<uint8_t> decrypted_buffer(encrypted.size() + AES_BLOCK_SIZE);
    int processed_length;
    if (EVP_DecryptUpdate(context, decrypted_buffer.data(), &processed_length, encrypted.data(), encrypted.size()) != 1) {
        EVP_CIPHER_CTX_free(context);
        // Handle error
        return "";
    }

    int final_block_length;
    if (EVP_DecryptFinal_ex(context, decrypted_buffer.data() + processed_length, &final_block_length) != 1) {
        EVP_CIPHER_CTX_free(context);
        // Handle error
        return "";
    }

    EVP_CIPHER_CTX_free(context);

    decrypted_buffer.resize(processed_length + final_block_length);
    return std::string(decrypted_buffer.begin(), decrypted_buffer.end());
}

