enum class ChessPiece {
    Empty,       // Empty square
    WhitePawn,
    WhiteRook,
    WhiteKnight,
    WhiteBishop,
    WhiteQueen,
    WhiteKing,
    BlackPawn,
    BlackRook,
    BlackKnight,
    BlackBishop,
    BlackQueen,
    BlackKing
};

class GameBoard {
public:
    GameBoard() {
        setupBoard();
    }

    void setupBoard() {
        // Initialize the board with the standard starting position
        grid.fill(ChessPiece::Empty);

        // Place white pieces
        grid[0][0] = grid[0][7] = ChessPiece::WhiteRook;
        grid[0][1] = grid[0][6] = ChessPiece::WhiteKnight;
        grid[0][2] = grid[0][5] = ChessPiece::WhiteBishop;
        grid[0][3] = ChessPiece::WhiteQueen;
        grid[0][4] = ChessPiece::WhiteKing;
        for (int col = 0; col < 8; ++col) {
            grid[1][col] = ChessPiece::WhitePawn;
        }

        // Place black pieces
        grid[7][0] = grid[7][7] = ChessPiece::BlackRook;
        grid[7][1] = grid[7][6] = ChessPiece::BlackKnight;
        grid[7][2] = grid[7][5] = ChessPiece::BlackBishop;
        grid[7][3] = ChessPiece::BlackQueen;
        grid[7][4] = ChessPiece::BlackKing;
        for (int col = 0; col < 8; ++col) {
            grid[6][col] = ChessPiece::BlackPawn;
        }
    }

    void printBoard() const {
        for (int row = 0; row < 8; ++row) {
            for (int col = 0; col < 8; ++col) {
                std::cout << pieceToSymbol(grid[row][col]) << " ";
            }
            std::cout << std::endl;
        }
    }

    bool executeMove(int startRow, int startCol, int endRow, int endCol) {
        if (startRow < 0 || startRow >= 8 || startCol < 0 || startCol >= 8 ||
            endRow < 0 || endRow >= 8 || endCol < 0 || endCol >= 8) {
            std::cerr << "Error: Move out of bounds" << std::endl;
            return false;
        }

        if (grid[startRow][startCol] == ChessPiece::Empty) {
            std::cerr << "Error: No piece at the starting position" << std::endl;
            return false;
        }

        // Simple move without checks for valid moves or captures
        grid[endRow][endCol] = grid[startRow][startCol];
        grid[startRow][startCol] = ChessPiece::Empty;

        return true;
    }

private:
    std::array<std::array<ChessPiece, 8>, 8> grid;

    std::string pieceToSymbol(ChessPiece piece) const {
        switch (piece) {
            case ChessPiece::Empty: return ".";
            case ChessPiece::WhitePawn: return "P";
            case ChessPiece::WhiteRook: return "R";
            case ChessPiece::WhiteKnight: return "N";
            case ChessPiece::WhiteBishop: return "B";
            case ChessPiece::WhiteQueen: return "Q";
            case ChessPiece::WhiteKing: return "K";
            case ChessPiece::BlackPawn: return "p";
            case ChessPiece::BlackRook: return "r";
            case ChessPiece::BlackKnight: return "n";
            case ChessPiece::BlackBishop: return "b";
            case ChessPiece::BlackQueen: return "q";
            case ChessPiece::BlackKing: return "k";
            default: return "?";
        }
    }
};

int main() {
    GameBoard gameBoard;
    gameBoard.printBoard();

    // Example move
    gameBoard.executeMove(1, 0, 2, 0);
    gameBoard.printBoard();

    return 0;
}

