#include <iostream>
#include <vector>

// Locate the initial position of a specified value using binary search
int locateFirstPosition(const std::vector<int>& data, int value) {
    int start = 0;
    int end = data.size() - 1;
    int foundIndex = -1;
    while (start <= end) {
        int middle = start + (end - start) / 2;
        if (data[middle] == value) {
            foundIndex = middle;
            end = middle - 1; // Search left portion for earlier occurrence
        } else if (data[middle] < value) {
            start = middle + 1;
        } else {
            end = middle - 1;
        }
    }
    return foundIndex;
}

// Locate the final position of a specified value using binary search
int locateLastPosition(const std::vector<int>& data, int value) {
    int start = 0;
    int end = data.size() - 1;
    int foundIndex = -1;
    while (start <= end) {
        int middle = start + (end - start) / 2;
        if (data[middle] == value) {
            foundIndex = middle;
            start = middle + 1; // Search right portion for later occurrence
        } else if (data[middle] < value) {
            start = middle + 1;
        } else {
            end = middle - 1;
        }
    }
    return foundIndex;
}

// Calculate how many times a value appears in the sorted array
int calculateFrequency(const std::vector<int>& data, int value) {
    int firstPos = locateFirstPosition(data, value);
    if (firstPos == -1) {
        return 0; // Value not found in the array
    }
    int lastPos = locateLastPosition(data, value);
    return lastPos - firstPos + 1;
}

int main() {
    std::vector<int> data = {1, 2, 2, 2, 3, 4, 5};
    int value = 2;
    int frequency = calculateFrequency(data, value);
    std::cout << "Total appearances of " << value << ": " << frequency << std::endl;
    return 0;
}

#include <iostream>
#include <cmath> // for std::sqrt

class ThreeDPoint {
public:
    // Constructor
    ThreeDPoint(double a = 0.0, double b = 0.0, double c = 0.0) : x_coord(a), y_coord(b), z_coord(c) {}

    // Getters and Setters
    double getX() const { return x_coord; }
    double getY() const { return y_coord; }
    double getZ() const { return z_coord; }

    void setX(double a) { x_coord = a; }
    void setY(double b) { y_coord = b; }
    void setZ(double c) { z_coord = c; }

    // Method to calculate the distance between two points
    double distanceFrom(const ThreeDPoint& other) const {
        double diff_x = x_coord - other.x_coord;
        double diff_y = y_coord - other.y_coord;
        double diff_z = z_coord - other.z_coord;
        return std::sqrt(diff_x * diff_x + diff_y * diff_y + diff_z * diff_z);
    }

private:
    double x_coord, y_coord, z_coord; // Coordinates of the point
};

int main() {
    // Create two points
    ThreeDPoint p1(1.0, 2.0, 3.0);
    ThreeDPoint p2(4.0, 5.0, 6.0);

    // Calculate the distance between the two points
    double dist = p1.distanceFrom(p2);

    // Output the result
    std::cout << "The distance between the points is: " << dist << std::endl;

    return 0;
}

#include <iostream>
#include <thread>
#include <chrono>
#include <cstdio>

extern "C" {
#include <libavformat/avformat.h>
#include <libavutil/opt.h>
#include <libavutil/time.h>
}

int read_frame(AVFormatContext *ctx, AVPacket *pkt)
{
    return av_read_frame(ctx, pkt) >= 0;
}

int main(int argc, char *argv[])
{
    if (argc != 4)
    {
        std::cerr << "Usage: " << argv[0] << " <source.mp4> <destination_ip> <udp_port>" << std::endl;
        return 1;
    }

    const char *sourceFile = argv[1];
    const char *destIP = argv[2];
    int destPort = std::stoi(argv[3]);

    av_register_all();
    avformat_network_init();

    AVFormatContext *inputCtx = nullptr;
    if (avformat_open_input(&inputCtx, sourceFile, nullptr, nullptr) < 0)
    {
        std::cerr << "Failed to open input file: " << sourceFile << std::endl;
        return 2;
    }

    if (avformat_find_stream_info(inputCtx, nullptr) < 0)
    {
        std::cerr << "Unable to retrieve stream information" << std::endl;
        return 3;
    }

    av_dump_format(inputCtx, 0, sourceFile, 0);

    int videoIdx = -1;
    int audioIdx = -1;

    for (unsigned int idx = 0; idx < inputCtx->nb_streams; ++idx)
    {
        if (inputCtx->streams[idx]->codecpar->codec_type == AVMEDIA_TYPE_VIDEO)
        {
            videoIdx = idx;
        }
        else if (inputCtx->streams[idx]->codecpar->codec_type == AVMEDIA_TYPE_AUDIO)
        {
            audioIdx = idx;
        }
    }

    if (videoIdx == -1 || audioIdx == -1)
    {
        std::cerr << "Missing required video or audio stream" << std::endl;
        return 4;
    }

    // Prepare output context
    AVFormatContext *outputCtx = nullptr;
    if (avformat_alloc_output_context2(&outputCtx, nullptr, "rtp", nullptr) < 0)
    {
        std::cerr << "Cannot create output context" << std::endl;
        return 5;
    }

    for (int i = 0; i < inputCtx->nb_streams; i++)
    {
        AVStream *inStream = inputCtx->streams[i];
        AVStream *outStream = avformat_new_stream(outputCtx, nullptr);
        if (!outStream) {
            std::cerr << "Stream allocation failed" << std::endl;
            return 6;
        }

        avcodec_parameters_copy(outStream->codecpar, inStream->codecpar);
        if (i == videoIdx)
        {
            outStream->codecpar->codec_tag = AV_RTP_PAYLOAD_H264;
        }
        else if (i == audioIdx)
        {
            outStream->codecpar->codec_tag = AV_RTP_PAYLOAD_AAC;
        }
    }

    av_dump_format(outputCtx, 0, destIP, 1);

    AVDictionary *opts = nullptr;
    av_dict_set_int(&opts, "ttl", 64, 0);
    av_dict_set_int(&opts, "localport", 8000, 0);

    std::string rtpUrl = "rtp://" + std::string(destIP) + ":" + std::to_string(destPort);
    if (avio_open2(&outputCtx->pb, rtpUrl.c_str(), AVIO_FLAG_WRITE, nullptr, &opts) < 0)
    {
        std::cerr << "Could not open RTP output" << std::endl;
        return 7;
    }

    if (avformat_write_header(outputCtx, nullptr) < 0)
    {
        std::cerr << "Header writing failed" << std::endl;
        return 8;
    }

    // Streaming loop
    AVPacket pkt;
    av_init_packet(&pkt);
    int64_t lastVideoPts = 0;
    int64_t lastAudioPts = 0;

    while (read_frame(inputCtx, &pkt))
    {
        int streamId = pkt.stream_index;
        AVRational tb = inputCtx->streams[streamId]->time_base;

        if (streamId == videoIdx || streamId == audioIdx)
        {
            AVPacket outPkt;
            av_init_packet(&outPkt);
            av_packet_ref(&outPkt, &pkt);

            av_packet_rescale_ts(&pkt, tb, outputCtx->streams[streamId]->time_base);
            av_write_frame(outputCtx, &outPkt);
            av_packet_unref(&outPkt);

            // Timing control
            int64_t diff = pkt.pts - (streamId == videoIdx ? lastVideoPts : lastAudioPts);
            int64_t delayMicros = av_rescale_q(diff, tb, {1, 1000000});
            std::this_thread::sleep_until(std::chrono::system_clock::now() + std::chrono::duration<int64_t, std::micro>(delayMicros));

            if (streamId == videoIdx)
            {
                lastVideoPts = pkt.pts;
            }
            else
            {
                lastAudioPts = pkt.pts;
            }
        }

        av_packet_unref(&pkt);
    }

    av_write_trailer(outputCtx);
    avio_closep(&outputCtx->pb);

    // Cleanup
    avformat_free_context(outputCtx);
    avformat_close_input(&inputCtx);

    return 0;
}

