namespace caffe {

template <typename Dtype>
class WeightedSigmoidCrossEntropyLossLayer : public LossLayer<Dtype> {
 public:
  explicit WeightedSigmoidCrossEntropyLossLayer(const LayerParameter& param)
      : LossLayer<Dtype>(param) {}
  virtual void LayerSetUp(const vector<Blob<Dtype>*>& bottom,
                          const vector<Blob<Dtype>*>& top);
  virtual void Reshape(const vector<Blob<Dtype>*>& bottom,
                       const vector<Blob<Dtype>*>& top);
  virtual void Forward_cpu(const vector<Blob<Dtype>*>& bottom,
                           const vector<Blob<Dtype>*>& top);
  virtual void Backward_cpu(const vector<Blob<Dtype>*>& top,
                            const vector<bool>& propagate_down,
                            const vector<Blob<Dtype>*>& bottom);

 protected:
  Blob<Dtype> sigmoid_output_;
  Blob<Dtype> target_label_;
  Blob<Dtype> class_weight_;
  Blob<Dtype> instance_weight_;
  Dtype pos_weight_;
  Dtype neg_weight_;
};

template <typename Dtype>
void WeightedSigmoidCrossEntropyLossLayer<Dtype>::LayerSetUp(
    const vector<Blob<Dtype>*>& bottom, const vector<Blob<Dtype>*>& top) {
  // Set weights for handling class imbalance: positive samples get higher weight
  pos_weight_ = 1.0 / 0.05;  
  // Negative samples receive lower weight due to their abundance
  neg_weight_ = 1.0 / 0.95;
}

template <typename Dtype>
void WeightedSigmoidCrossEntropyLossLayer<Dtype>::Reshape(
    const vector<Blob<Dtype>*>& bottom, const vector<Blob<Dtype>*>& top) {
  LossLayer<Dtype>::Reshape(bottom, top);
  sigmoid_output_.ReshapeLike(*bottom[0]);
  target_label_.ReshapeLike(*bottom[1]);
  class_weight_.ReshapeLike(*bottom[1]);
  instance_weight_.ReshapeLike(*bottom[1]);
}

template <typename Dtype>
void WeightedSigmoidCrossEntropyLossLayer<Dtype>::Forward_cpu(
    const vector<Blob<Dtype>*>& bottom, const vector<Blob<Dtype>*>& top) {
  const Dtype* input_data = bottom[0]->cpu_data();
  const Dtype* label_data = bottom[1]->cpu_data();
  Dtype* sigmoid_mem = sigmoid_output_.mutable_cpu_data();
  Dtype* weight_mem = class_weight_.mutable_cpu_data();
  Dtype* scale_mem = instance_weight_.mutable_cpu_data();
  int batch_size = bottom[0]->num();
  int elements_per_sample = bottom[0]->count() / batch_size;

  // Calculate sigmoid activation for each element
  for (int n = 0; n < batch_size; ++n) {
    for (int k = 0; k < elements_per_sample; ++k) {
      sigmoid_mem[n * elements_per_sample + k] = 1.0 / (1.0 + exp(-input_data[n * elements_per_sample + k]));
    }
  }

  // Compute sample-specific weights based on class labels
  for (int n = 0; n < batch_size; ++n) {
    for (int k = 0; k < elements_per_sample; ++k) {
      weight_mem[n * elements_per_sample + k] = label_data[n * elements_per_sample + k] * pos_weight_ + 
                                                (1 - label_data[n * elements_per_sample + k]) * neg_weight_;
    }
  }

  // Accumulate weighted loss across all samples
  Dtype total_loss = 0.0;
  for (int n = 0; n < batch_size; ++n) {
    for (int k = 0; k < elements_per_sample; ++k) {
      Dtype label_val = label_data[n * elements_per_sample + k];
      Dtype pred_val = sigmoid_mem[n * elements_per_sample + k];
      Dtype weight_val = weight_mem[n * elements_per_sample + k];
      total_loss += -label_val * log(pred_val) - (1 - label_val) * log(1 - pred_val) * weight_val;
    }
  }
  total_loss /= batch_size;
  top[0]->mutable_cpu_data()[0] = total_loss;
}

template <typename Dtype>
void WeightedSigmoidCrossEntropyLossLayer<Dtype>::Backward_cpu(
    const vector<Blob<Dtype>*>& top, const vector<bool>& propagate_down,
    const vector<Blob<Dtype>*>& bottom) {
  if (!propagate_down[0]) {
    return;
  }
  const Dtype* input_vals = bottom[0]->cpu_data();
  const Dtype* label_vals = bottom[1]->cpu_data();
  const Dtype* sigmoid_vals = sigmoid_output_.cpu_data();
  const Dtype* weight_vals = class_weight_.cpu_data();
  Dtype* gradient_out = bottom[0]->mutable_cpu_diff();
  int batch_size = bottom[0]->num();
  int elements_per_sample = bottom[0]->count() / batch_size;

  // Compute gradients with respect to inputs
  for (int n = 0; n < batch_size; ++n) {
    for (int k = 0; k < elements_per_sample; ++k) {
      Dtype diff_val = sigmoid_vals[n * elements_per_sample + k] - label_vals[n * elements_per_sample + k];
      gradient_out[n * elements_per_sample + k] = diff_val * weight_vals[n * elements_per_sample + k];
    }
  }
  caffe_cpu_scale(bottom[0]->count(), top[0]->cpu_diff()[0] / batch_size, gradient_out, gradient_out);
}

