// Check if a number is prime
bool checkPrime(int num) {
    if (num <= 1) {
        return false;
    }
    for (int j = 2; j <= std::sqrt(num); j++) {
        if (num % j == 0) {
            return false;
        }
    }
    return true;
}

int main() {
    std::vector<int> primeNumbers;
    for (int value = 2; value <= 50; value++) {
        if (checkPrime(value)) {
            primeNumbers.push_back(value);
        }
    }
    for (int p : primeNumbers) {
        std::cout << p << " ";
    }
    std::cout << std::endl;
    return 0;
}

