// Helper function to convert a wrapped Java object to its primitive jvalue representation
jvalue unwrapPrimitive(JNIEnv *env, jobject wrapperObj, const char *typeSig) {
    jvalue result;
    if (typeSig[0] == 'Z') {
        jclass cls = env->GetObjectClass(wrapperObj);
        jmethodID mid = env->GetMethodID(cls, "booleanValue", "()Z");
        result.z = env->CallBooleanMethod(wrapperObj, mid);
    } else if (typeSig[0] == 'B') {
        jclass cls = env->GetObjectClass(wrapperObj);
        jmethodID mid = env->GetMethodID(cls, "byteValue", "()B");
        result.b = env->CallByteMethod(wrapperObj, mid);
    } else if (typeSig[0] == 'C') {
        jclass cls = env->GetObjectClass(wrapperObj);
        jmethodID mid = env->GetMethodID(cls, "charValue", "()C");
        result.c = env->CallCharMethod(wrapperObj, mid);
    } else if (typeSig[0] == 'S') {
        jclass cls = env->GetObjectClass(wrapperObj);
        jmethodID mid = env->GetMethodID(cls, "shortValue", "()S");
        result.s = env->CallShortMethod(wrapperObj, mid);
    } else if (typeSig[0] == 'I') {
        jclass cls = env->GetObjectClass(wrapperObj);
        jmethodID mid = env->GetMethodID(cls, "intValue", "()I");
        result.i = env->CallIntMethod(wrapperObj, mid);
    } else if (typeSig[0] == 'J') {
        jclass cls = env->GetObjectClass(wrapperObj);
        jmethodID mid = env->GetMethodID(cls, "longValue", "()J");
        result.j = env->CallLongMethod(wrapperObj, mid);
    } else if (typeSig[0] == 'F') {
        jclass cls = env->GetObjectClass(wrapperObj);
        jmethodID mid = env->GetMethodID(cls, "floatValue", "()F");
        result.f = env->CallFloatMethod(wrapperObj, mid);
    } else if (typeSig[0] == 'D') {
        jclass cls = env->GetObjectClass(wrapperObj);
        jmethodID mid = env->GetMethodID(cls, "doubleValue", "()D");
        result.d = env->CallDoubleMethod(wrapperObj, mid);
    } else if (typeSig[0] == 'L' || typeSig[0] == '[') {
        result.l = wrapperObj;
    } else {
        std::cerr << "Unsupported parameter type: " << typeSig << std::endl;
    }
    return result;
}

// Generic constructor invoker using variable arguments from a JNI array
jobject invokeConstructor(JNIEnv *env, jobjectArray paramObjects, const char *methodSig) {
    int argCount = env->GetArrayLength(paramObjects);

    // Parse method signature to determine expected parameter count
    const char *cursor = methodSig;
    while (*cursor && *cursor != '(') cursor++;
    if (!*cursor) return nullptr;
    cursor++; // skip '('

    int expectedParams = 0;
    while (*cursor && *cursor != ')') {
        if (*cursor == 'L') {
            while (*cursor && *cursor != ';') cursor++;
        }
        cursor++;
        expectedParams++;
    }

    if (argCount != expectedParams) {
        std::cerr << "Argument count mismatch: expected " << expectedParams 
                  << ", got " << argCount << std::endl;
        return nullptr;
    }

    // Allocate temporary storage for unwrapped values
    jvalue *args = new jvalue[argCount];

    // Unwrap each argument according to the signature
    const char *sigPtr = methodSig + 1; // start after '('
    for (int idx = 0; idx < argCount; ++idx) {
        jobject wrapped = env->GetObjectArrayElement(paramObjects, idx);
        args[idx] = unwrapPrimitive(env, wrapped, sigPtr);

        // Advance signature pointer past current type
        if (*sigPtr == 'L') {
            while (*sigPtr && *sigPtr != ';') sigPtr++;
        }
        sigPtr++;
    }

    // Extract class name and find target class
    const char *className = "com/example/TargetClass"; // Replace with actual class
    jclass targetClass = env->FindClass(className);
    if (!targetClass) {
        std::cerr << "Failed to locate class: " << className << std::endl;
        delete[] args;
        return nullptr;
    }

    // Locate the constructor method ID
    jmethodID ctorId = env->GetMethodID(targetClass, "<init>", methodSig);
    if (!ctorId) {
        std::cerr << "Constructor not found with signature: " << methodSig << std::endl;
        delete[] args;
        return nullptr;
    }

    // Instantiate the object using NewObjectA
    jobject newObj = env->NewObjectA(targetClass, ctorId, args);

    // Cleanup resources
    delete[] args;

    return newObj;
}

// JNI entry point for calling constructor dynamically
extern "C" JNIEXPORT jobject JNICALL Java_com_example_DynamicInvoker_createInstance(JNIEnv *env, jobject thiz, jobjectArray params, jstring sigStr) {
    const char *utfSig = env->GetStringUTFChars(sigStr, nullptr);
    jobject instance = invokeConstructor(env, params, utfSig);
    env->ReleaseStringUTFChars(sigStr, utfSig);
    return instance;
}

