std::string hex_to_bytes(std::string const &hex_input) {
  std::string result;
  for (std::size_t idx = 0; idx < hex_input.size(); idx += 2) {
    auto byte_str = hex_input.substr(idx, 2);
    result.push_back(static_cast<uint8_t>(std::strtol(byte_str.c_str(), nullptr, 16)));
  }
  return result;
}

int main() {
  std::string public_key_data {
R"(
-----BEGIN PUBLIC KEY-----
MFkwEwYHKoZIzj0CAQYIKoZIzj0DAQcDQgAEDd9VXmpHjV4voFO+0ZoFPlRr5icZXquxsr9EkaOUO9B7Wl1DAgGI0EKCm1++Bl2Od32xZFeFuG07OTpTMVOCPA==
-----END PUBLIC KEY-----
)"
  };

  std::string message { hex_to_bytes("562d6ddfb3ceb5abb12d97bc35c4963d249f55b7c75eda618d365492ee98d469") };
  std::string signature { hex_to_bytes("304502204d6d070117d445f4c2fcdbd4df037a1c8cfee2a166353c2e562cd5efd06e914d022100bb06439ded1478bd19022519dc06a84ba18ea4bf30ea9eb9ea90f8b66dad12c7") };

  BIO *memory_bio = BIO_new_mem_buf(public_key_data.data(), public_key_data.length());
  assert(memory_bio);

  EC_KEY *ec_key = PEM_read_bio_EC_PUBKEY(memory_bio, nullptr, nullptr, nullptr);
  assert(ec_key);

  EVP_MD_CTX *digest_context = EVP_MD_CTX_new();
  assert(digest_context);

  EVP_PKEY *evp_key = EVP_PKEY_new();
  assert(evp_key);

  assert(EVP_PKEY_assign_EC_KEY(evp_key, ec_key) == 1);

  assert(EVP_DigestVerifyInit(digest_context, nullptr, EVP_sha256(), nullptr, evp_key) == 1);

  assert(EVP_DigestVerifyUpdate(digest_context, message.data(), message.length()) == 1);

  int verify_result = EVP_DigestVerifyFinal(digest_context, reinterpret_cast<const unsigned char*>(signature.data()), signature.length());

  bool is_valid = (verify_result == 1);

  EVP_MD_CTX_free(digest_context);
  EVP_PKEY_free(evp_key);

  assert(is_valid);
}

