using ObjectId = std::size_t;

class ObjectManager {
public:
    ObjectManager() : nextId_(0) {}

    ObjectId generateObject() {
        return nextId_++;
    }
private:
    ObjectId nextId_;
};

template <typename T>
class DataStore {
public:
    void store(ObjectId obj, const T& data) {
        storage_[obj] = data;
    }

    T* retrieve(ObjectId obj) {
        auto iter = storage_.find(obj);
        return iter != storage_.end() ? &(iter->second) : nullptr;
    }

private:
    std::unordered_map<ObjectId, T> storage_;
};

int main() {
