// Simplify a fraction represented by numerator and denominator
std::pair<int, int> simplify_fraction(int num, int den) {
    int divisor = std::gcd(num, den);
    return {num / divisor, den / divisor};
}

// Count occurrences of unique slopes formed by points relative to origin
std::map<std::pair<int, int>, int> tally_slopes(const std::vector<std::pair<int, int>>& coords) {
    std::map<std::pair<int, int>, int> slope_counts;
    for (const auto& coordinate : coords) {
        int x_val = coordinate.first;
        int y_val = coordinate.second;

        if (y_val == 0) {
            // Vertical line case: represent as (1, 0)
            slope_counts[{1, 0}]++;
        } else {
            auto simplified = simplify_fraction(x_val, y_val);
            slope_counts[simplified]++;
        }
    }
    return slope_counts;
}

int main() {
    std::vector<std::pair<int, int>> test_points = {{2, 3}, {4, 6}, {5, 0}, {3, 9}, {6, 12}};
    auto result = tally_slopes(test_points);

    for (const auto& [key, value] : result) {
        std::cout << "(" << key.first << ", " << key.second << "): " << value << std::endl;
    }

    return 0;
}

