// Macro for CUDA error checking - wraps the validation function
#define validateCudaErrors(err) validateError((err), #err, __FILE__, __LINE__)

// Template function to validate CUDA API calls and handle errors
template <typename U>
void validateError(U errorValue, char const *const functionName, char const *const sourceFile, int const lineNumber) {
    if (errorValue != cudaSuccess) {
        fprintf(stderr, "CUDA failure detected in %s at line %d: error code %d (%s) for call \"%s\"\n", 
