// Kernel to increment each component of a float4 vector by 1.0f
__global__ void vectorIncrementKernel(float4* inputVector) {
    float4 currentVec = *inputVector;

    // Add 1.0f to each component using CUDA's make_float4 helper
    float4 updatedVec = make_float4(currentVec.x + 1.0f, 
