#include <iostream>
using namespace std;

#define EMPTY 0
#define SIZE 9

bool isValidPlacement(int puzzle[SIZE][SIZE], int r, int c, int val) {
    // Check if 'val' exists in current row
    for (int k = 0; k < SIZE; k++) {
        if (puzzle[r][k] == val) {
            return false;
        }
    }

    // Check if 'val' exists in current column
    for (int k = 0; k < SIZE; k++) {
        if (puzzle[k][c] == val) {
            return false;
        }
    }

    // Check if 'val' exists in current 3x3 box
    int boxRow = r - r % 3;
    int boxCol = c - c % 3;
    for (int m = 0; m < 3; m++) {
        for (int n = 0; n < 3; n++) {
            if (puzzle[boxRow + m][boxCol + n] == val) {
                return false;
            }
        }
    }

    return true;
}

bool locateEmptySlot(int puzzle[SIZE][SIZE], int& r, int& c) {
    // Scan grid for first empty position
    for (r = 0; r < SIZE; r++) {
        for (c = 0; c < SIZE; c++) {
            if (puzzle[r][c] == EMPTY) {
                return true;
            }
        }
    }

    // All cells filled means puzzle is complete
    return false;
}

bool solvePuzzle(int puzzle[SIZE][SIZE]) {
    int row, col;

    // Verify if puzzle is already solved
    if (!locateEmptySlot(puzzle, row, col)) {
        return true;
    }

    // Test each digit from 1 to 9
    for (int digit = 1; digit <= 9; digit++) {
        if (isValidPlacement(puzzle, row, col, digit)) {
            // Assign tentative value
            puzzle[row][col] = digit;

            // Continue solving recursively
            if (solvePuzzle(puzzle)) {
                return true;
            }

            // Backtrack if solution not found
            puzzle[row][col] = EMPTY;
        }
    }

    // No valid number works here, need to backtrack
    return false;
}

void printGrid(int puzzle[SIZE][SIZE]) {
    for (int i = 0; i < SIZE; i++) {
        for (int j = 0; j < SIZE; j++) {
            cout << puzzle[i][j] << " ";
        }
        cout << endl;
    }
}

int main() {
    int puzzle[SIZE][SIZE] = {
        {3, 0, 6, 5, 0, 8, 4, 0, 0},
        {5, 2, 0, 0, 0, 0, 0, 0, 0},
        {0, 8, 7, 0, 0, 0, 0, 3, 1},
        {0, 0, 3, 0, 1, 0, 0, 8, 0},
        {9, 0, 0, 8, 6, 3, 0, 0, 5},
        {0, 5, 0, 0, 9, 0, 6, 0, 0},
        {1, 3, 0, 0, 0, 0, 2, 5, 0},
        {0, 0, 0, 0, 0, 0, 0, 7, 4},
        {0, 0, 5, 2, 0, 6, 3, 0, 0}
    };

    if (solvePuzzle(puzzle)) {
        cout << "Sudoku completed successfully.\n";
        printGrid(puzzle);
    }
    else {
        cout << "No valid solution can be found.\n";
    }

    return 0;
}

#include <iostream>
using namespace std;

class TreeNode {
public:
    int value;
    TreeNode* leftChild;
    TreeNode* rightChild;

    TreeNode(int v) : value(v), leftChild(nullptr), rightChild(nullptr) {}
};

class BinarySearchTree {
public:
    TreeNode* head;

    BinarySearchTree() : head(nullptr) {}

    void add(int val) {
        head = addRecursive(head, val);
    }

    void printInorder() {
        printInorderRecursive(head);
        cout << endl;
    }

    void removeValue(int val) {
        head = removeRecursive(head, val);
    }

private:
    TreeNode* addRecursive(TreeNode* node, int val) {
        if (node == nullptr) {
            node = new TreeNode(val);
            return node;
        }
        if (val < node->value) {
            node->leftChild = addRecursive(node->leftChild, val);
        } else if (val > node->value) {
            node->rightChild = addRecursive(node->rightChild, val);
        }
        return node;
    }

    void printInorderRecursive(TreeNode* node) {
        if (node != nullptr) {
            printInorderRecursive(node->leftChild);
            cout << node->value << " ";
            printInorderRecursive(node->rightChild);
        }
    }

    TreeNode* findMinNode(TreeNode* node) {
        TreeNode* current = node;
        while (current && current->leftChild != nullptr) {
            current = current->leftChild;
        }
        return current;
    }

    TreeNode* removeRecursive(TreeNode* node, int val) {
        if (node == nullptr) return node;

        if (val < node->value) {
            node->leftChild = removeRecursive(node->leftChild, val);
        } else if (val > node->value) {
            node->rightChild = removeRecursive(node->rightChild, val);
        } else {
            if (node->leftChild == nullptr) {
                TreeNode* successor = node->rightChild;
                delete node;
                return successor;
            } else if (node->rightChild == nullptr) {
                TreeNode* predecessor = node->leftChild;
                delete node;
                return predecessor;
            }

            TreeNode* temp = findMinNode(node->rightChild);
            node->value = temp->value;
            node->rightChild = removeRecursive(node->rightChild, temp->value);
        }
        return node;
    }
};

int main() {
    BinarySearchTree tree;

    tree.add(50);
    tree.add(30);
    tree.add(20);
    tree.add(40);
    tree.add(70);
    tree.add(60);
    tree.add(80);

    cout << "Inorder traversal of the given tree: ";
    tree.printInorder();

    tree.removeValue(20);
    cout << "Inorder traversal after removing 20: ";
    tree.printInorder();

    tree.removeValue(30);
    cout << "Inorder traversal after removing 30: ";
    tree.printInorder();

    tree.removeValue(50);
    cout << "Inorder traversal after removing 50: ";
    tree.printInorder();

    return 0;
}

