// Perform insertion sort on the given vector
void insertion_sort(vector<int>& data) {
    for (int index = 1; index < data.size(); ++index) {
        int current_value = data[index];
        int position = index - 1;
        while (position >= 0 && current_value < data[position]) {
            data[position + 1] = data[position];
            --position;
        }
        data[position + 1] = current_value;
    }
}

