#include <iostream>
#include <vector>
#include <cmath>
#include <algorithm>
#include <limits>

struct Location {
    int xPos, yPos;
};

double euclideanDist(const Location& point1, const Location& point2) {
    return std::sqrt(std::pow(point1.xPos - point2.xPos, 2) + std::pow(point1.yPos - point2.yPos, 2));
}

double pathLength(const std::vector<int>& route, const std::vector<Location>& locations) {
    double sum = 0.0;
    for (size_t idx = 0; idx < route.size(); ++idx) {
        sum += euclideanDist(locations[route[idx]], locations[route[(idx + 1) % route.size()]]);
    }
    return sum;
}

void improveRoute(std::vector<int>& route, const std::vector<Location>& locations) {
    bool betterFound = true;
    while (betterFound) {
        betterFound = false;
        for (size_t firstIdx = 1; firstIdx < route.size() - 2; ++firstIdx) {
            for (size_t secondIdx = firstIdx + 1; secondIdx < route.size(); ++secondIdx) {
                double oldCost = euclideanDist(locations[route[firstIdx - 1]], locations[route[firstIdx]]) + 
                                euclideanDist(locations[route[secondIdx]], locations[route[(secondIdx + 1) % route.size()]]);
                double newCost = euclideanDist(locations[route[firstIdx - 1]], locations[route[secondIdx]]) + 
                                euclideanDist(locations[route[firstIdx]], locations[route[(secondIdx + 1) % route.size()]]);
                if (newCost < oldCost) {
                    std::reverse(route.begin() + firstIdx, route.begin() + secondIdx + 1);
                    betterFound = true;
                }
            }
        }
    }
}

int main() {
    std::vector<Location> points = {{0, 0}, {2, 8}, {6, 2}, {7, 6}, {2, 2}};
    std::vector<int> path(points.size());
    for (size_t i = 0; i < points.size(); ++i) {
        path[i] = static_cast<int>(i);
    }

    std::cout << "Starting path: ";
    for (int loc : path) {
        std::cout << loc << " ";
    }
    std::cout << "\nStarting length: " << pathLength(path, points) << std::endl;

    improveRoute(path, points);

    std::cout << "Improved path: ";
    for (int loc : path) {
        std::cout << loc << " ";
    }
    std::cout << "\nImproved length: " << pathLength(path, points) << std::endl;

    return 0;
}

#include <iostream>
#include <vector>

using namespace std;

// Locate the initial position of the specified element in sorted array
int locateFirstPosition(const vector<int>& data, int value) {
    int start = 0, end = data.size() - 1;
    int foundIndex = -1;
    while (start <= end) {
        int middle = start + (end - start) / 2;
        if (data[middle] == value) {
            foundIndex = middle;
            end = middle - 1; // Keep searching left portion for earlier occurrence
        } else if (data[middle] < value) {
            start = middle + 1;
        } else {
            end = middle - 1;
        }
    }
    return foundIndex;
}

// Locate the final position of the specified element in sorted array
int locateLastPosition(const vector<int>& data, int value) {
    int start = 0, end = data.size() - 1;
    int foundIndex = -1;
    while (start <= end) {
        int middle = start + (end - start) / 2;
        if (data[middle] == value) {
            foundIndex = middle;
            start = middle + 1; // Keep searching right portion for later occurrence
        } else if (data[middle] < value) {
            start = middle + 1;
        } else {
            end = middle - 1;
        }
    }
    return foundIndex;
}

// Find both boundaries of the specified element in sorted array
pair<int, int> locateBoundaries(const vector<int>& data, int value) {
    int firstPos = locateFirstPosition(data, value);
    if (firstPos == -1) {
        return {-1, -1}; // Element not present in array
    }
    int lastPos = locateLastPosition(data, value);
    return {firstPos, lastPos};
}

int main() {
    vector<int> sequence = {1, 2, 2, 2, 3, 4, 4, 5, 6};
    int searchValue = 2;
    auto [begin, finish] = locateBoundaries(sequence, searchValue);
    if (begin == -1) {
        cout << "Element not found" << endl;
    } else {
        cout << "First appearance at index: " << begin << endl;
        cout << "Final appearance at index: " << finish << endl;
    }
    return 0;
}

#include <iostream>
#include <thread>
#include <deque>
#include <functional>
#include <future>
#include <mutex>
#include <condition_variable>
#include <vector>
#include <memory>
#include <chrono>

class ThreadPoolManager {
public:
    ThreadPoolManager(size_t initialThreads = 20, size_t maxThreads = 200)
        : _initialThreads(initialThreads)
        , _maxThreads(maxThreads)
        , _shutdown(false) {
        active_threads.reserve(_maxThreads);
        for (size_t t = 0; t < _initialThreads; ++t) {
            spawn_thread();
        }
    }

    void spawn_thread() {
        active_threads.emplace_back([this] {
            while (true) {
                std::function<void()> job;
                {
                    std::unique_lock<std::mutex> guard(this->_lock);
                    this->_cv.wait(guard, [this] {
                        return this->_shutdown || !this->_jobs.empty();
                    });
                    if (this->_shutdown && this->_jobs.empty())
                        break;
                    job = std::move(this->_jobs.front());
                    this->_jobs.pop_front();
                }
                job();
            }
        });
    }

    template <typename Func, typename... Params>
    auto enqueue(Func&& func, Params&&... params)
        -> std::future<typename std::result_of<Func(Params...)>::type> {
        using result_type = typename std::result_of<Func(Params...)>::type;

        auto wrapper = std::make_shared<std::packaged_task<result_type()>>(
            std::bind(std::forward<Func>(func), std::forward<Params>(params)...));

        std::future<result_type> future_result = wrapper->get_future();

        {
            std::unique_lock<std::mutex> guard(_lock);
            if (_shutdown) {
                throw std::runtime_error("Enqueue on stopped ThreadPoolManager");
            }
            if (_jobs.size() >= active_threads.size() && active_threads.size() < _maxThreads) {
                spawn_thread();
            }
            _jobs.emplace_back([wrapper] { (*wrapper)(); });
        }
        _cv.notify_one();
        return future_result;
    }

    void shutdown() {
        std::unique_lock<std::mutex> guard(_lock);
        if (!_shutdown) {
            _shutdown = true;
            _cv.notify_all();
        }
        for (std::thread& worker : active_threads)
            worker.join();
    }

    size_t pending_jobs_count() {
        std::unique_lock<std::mutex> guard(_lock);
        return _jobs.size();
    }

    ~ThreadPoolManager() {
        shutdown();
    }

private:
    std::vector<std::thread> active_threads;
    std::deque<std::function<void()>> _jobs;
    size_t _initialThreads;
    size_t _maxThreads;
    std::mutex _lock;
    std::condition_variable _cv;
    bool _shutdown;
};

class WorkerTask {
public:
    WorkerTask(double device_id)
        : _device_id(device_id)
        , _active(true) {
    }

    void launch(ThreadPoolManager& pool) {
        _result = pool.enqueue(&WorkerTask::_execute, this);
    }

    void terminate() {
        {
            _active = false;
            std::unique_lock<std::mutex> guard(_sync_mutex);

            if (_result.valid()) {
                _result.get();
                guard.unlock();
                _finalize();
            }
        }
    }

private:
    std::mutex _sync_mutex;
    double _device_id;
    std::deque<double> _packet_buffer;
    std::future<void> _result;
    bool _active;

    void _finalize() {
        std::unique_lock<std::mutex> guard(_sync_mutex);
        _packet_buffer.clear();
    }

    void _execute() {
        std::unique_lock<std::mutex> guard(_sync_mutex);
        while (_active) {
            if (_packet_buffer.empty()) {
                std::cout << "executing task" << std::endl;
                continue;
            }
            double item = _packet_buffer.front();
            _packet_buffer.pop_front();
            guard.unlock();
            std::cout << "processing item" << std::endl;
            guard.lock();
        }
    }
};

int main() {
    ThreadPoolManager pool(20, 200);
    std::vector<std::shared_ptr<WorkerTask>> tasks;

    for (int idx = 0; idx < 100; ++idx) {
        auto worker = std::make_shared<WorkerTask>(1.0);
        worker->launch(pool);
        tasks.push_back(worker);
    }

    std::this_thread::sleep_for(std::chrono::seconds(3));

    for (auto& worker : tasks) {
        worker->terminate();
    }
    tasks.clear();

    for (int idx = 0; idx < 3; ++idx) {
        auto worker = std::make_shared<WorkerTask>(1.0);
        worker->launch(pool);
        tasks.push_back(worker);
    }

    std::this_thread::sleep_for(std::chrono::seconds(3));

    for (auto& worker : tasks) {
        worker->terminate();
    }

    return 0;
}

#include <cstdio>
