using namespace std;

// Determine whether a given integer is prime
bool checkPrime(int value) {
    if (value <= 1)
        return false;

    if (value == 2)
        return true;

    if (value % 2 == 0)
        return false;

    for (int divisor = 3; divisor <= sqrt(value); divisor += 2) {
        if (value % divisor == 0)
            return false;
    }

    return true;
}

// Find the prime number containing the most digits in the list
int locateLongestPrime(vector<int> numbers) {
    int digitCount = 0;
    int largestPrime = 0;

    for (int index = 0; index < numbers.size(); ++index) {
        if (checkPrime(numbers[index])) {
            int count = 0;
            int temp = numbers[index];
            while (temp != 0) {
                count++;
                temp /= 10;
            }

            if (count > digitCount) {
                digitCount = count;
                largestPrime = numbers[index];
            }
        }
    }

    if (largestPrime == 0)
        return -1; // Indicates no primes were found in the input

    return largestPrime;
}

int main() {
    vector<int> numbers = {1, 3, 131, 323, 5107, 34, 8278, 109, 163, 2323, 321, 3039, 31};
    int answer = locateLongestPrime(numbers);
    printf("The prime number with the maximum number of digits is: %d\n", answer);
    return 0;
}

