bool isSmallConsonant(char ch) {
    return islower(ch) && ch != 'a' && ch != 'e' && ch != 'i' && ch != 'o' && ch != 'u';
}

int calculateConsonantSum(const std::string& text) {
    int totalValue = 0;
    for (size_t index = 1; index < text.length(); index += 2) { // Begin from position 1 and step by 2
        if (isSmallConsonant(text[index])) {
            totalValue += static_cast<int>(text[index]);
        }
    }
    return totalValue;
}

