#include <cuda_runtime.h>
#include <iostream>

#define MATRIX_SIZE 1000

__global__ void matrixMultiply(float *inputA, float *inputB, float *outputC, int size) {
    int rowIndex = blockIdx.y * blockDim.y + threadIdx.y;
    int colIndex = blockIdx.x * blockDim.x + threadIdx.x;

    if (rowIndex < size && colIndex < size) {
        float accumulator = 0.0f;
        for (int k = 0; k < size; k++) {
            accumulator += inputA[rowIndex * size + k] * inputB[k * size + colIndex];
        }
        outputC[rowIndex * size + colIndex] = accumulator;
    }
}

int main() {
    float *host_A, *host_B, *host_C;
    float *device_A, *device_B, *device_C;

    // Allocate memory on the host
    host_A = (float*)malloc(MATRIX_SIZE * MATRIX_SIZE * sizeof(float));
    host_B = (float*)malloc(MATRIX_SIZE * MATRIX_SIZE * sizeof(float));
    host_C = (float*)malloc(MATRIX_SIZE * MATRIX_SIZE * sizeof(float));

    // Initialize matrices
    for (int idx = 0; idx < MATRIX_SIZE * MATRIX_SIZE; idx++) {
        host_A[idx] = 1.0f;
        host_B[idx] = 2.0f;
    }

    // Allocate memory on the device
    cudaMalloc(&device_A, MATRIX_SIZE * MATRIX_SIZE * sizeof(float));
    cudaMalloc(&device_B, MATRIX_SIZE * MATRIX_SIZE * sizeof(float));
    cudaMalloc(&device_C, MATRIX_SIZE * MATRIX_SIZE * sizeof(float));

    // Copy data from host to device
    cudaMemcpy(device_A, host_A, MATRIX_SIZE * MATRIX_SIZE * sizeof(float), cudaMemcpyHostToDevice);
    cudaMemcpy(device_B, host_B, MATRIX_SIZE * MATRIX_SIZE * sizeof(float), cudaMemcpyHostToDevice);

    // Define block and grid dimensions
    dim3 threadsPerBlock(16, 16);
    dim3 blocksPerGrid((MATRIX_SIZE + threadsPerBlock.x - 1) / threadsPerBlock.x, 
                       (MATRIX_SIZE + threadsPerBlock.y - 1) / threadsPerBlock.y);

    // Launch the kernel
    matrixMultiply<<<blocksPerGrid, threadsPerBlock>>>(device_A, device_B, device_C, MATRIX_SIZE);

    // Copy result back to host
    cudaMemcpy(host_C, device_C, MATRIX_SIZE * MATRIX_SIZE * sizeof(float), cudaMemcpyDeviceToHost);

    // Free device memory
    cudaFree(device_A);
    cudaFree(device_B);
    cudaFree(device_C);

    // Free host memory
    free(host_A);
    free(host_B);
    free(host_C);

    return 0;
}

