    lReturnCode = RegCreateKeyEx(HKEY_CLASSES_ROOT, TEXT(".custext"), 0, NULL, 0, KEY_WRITE, NULL, &hKeyHandle, NULL);
    if (lReturnCode == ERROR_SUCCESS)
    {
        RegSetValueEx(hKeyHandle, NULL, 0, REG_SZ, (BYTE*)TEXT("CustomApp.FileType"), (lstrlen(TEXT("CustomApp.FileType")) + 1) * sizeof(TCHAR));
