    lReturnCode = RegCreateKeyEx(HKEY_CLASSES_ROOT, TEXT("CustomApp.FileType\\Shell\\Open\\Command"), 0, NULL, 0, KEY_WRITE, NULL, &hKeyHandle, NULL);
    if (lReturnCode == ERROR_SUCCESS)
    {
        RegSetValueEx(hKeyHandle, NULL, 0, REG_SZ, (BYTE*)TEXT("\"D:\\Tools\\CustomApp.exe\" \"%1\""), (lstrlen(TEXT("\"D:\\Tools\\CustomApp.exe\" \"%1\"")) + 1) * sizeof(TCHAR));
        RegCloseKey(hKeyHandle);
    }

    // Configure the ProgID entry
    lReturnCode = RegCreateKeyEx(HKEY_CLASSES_ROOT, TEXT("CustomApp.FileType"), 0, NULL, 0, KEY_WRITE, NULL, &hKeyHandle, NULL);
