// Compute optimal threshold for weighted error minimization
std::tuple<double, double, int> findOptimalThreshold(
    const std::vector<double>& samples,
    const std::vector<int>& labels,
    const std::vector<double>& weights) {

    // Step 1: Extract feature values from input samples
    std::vector<double> extracted_features = computeFeatureValues(samples);

    // Step 2: Combine features, labels, and weights into sorted tuples
    std::vector<std::tuple<double, int, double>> combined_entries;
    for (size_t idx = 0; idx < extracted_features.size(); ++idx) {
        combined_entries.emplace_back(extracted_features[idx], labels[idx], weights[idx]);
    }
    std::sort(combined_entries.begin(), combined_entries.end());

    // Step 3: Setup initial parameters for optimization
    double optimal_threshold = 0.0;
    double minimal_error = std::numeric_limits<double>::max();
    int optimal_sign = 1; // 1 indicates > threshold, -1 indicates <= threshold

    // Step 4: Evaluate all candidate thresholds
    double cumulative_weight = std::accumulate(weights.begin(), weights.end(), 0.0);
    double loss_positive = 0.0;
    double loss_negative = cumulative_weight;

    for (size_t pos = 0; pos < combined_entries.size(); ++pos) {
        double current_feature = std::get<0>(combined_entries[pos]);
        int current_label = std::get<1>(combined_entries[pos]);
        double current_sample_weight = std::get<2>(combined_entries[pos]);

        // Determine best error at this position
        double candidate_error = std::min(loss_positive, loss_negative);
        if (candidate_error < minimal_error) {
            minimal_error = candidate_error;
            optimal_threshold = current_feature;
            optimal_sign = (loss_positive < loss_negative) ? 1 : -1;
        }

        // Adjust error counters based on label
        if (current_label == 1) {
            loss_positive += current_sample_weight;
            loss_negative -= current_sample_weight;
        } else {
            loss_positive -= current_sample_weight;
            loss_negative += current_sample_weight;
        }
    }

    // Step 5: Output final optimized configuration
    return {optimal_threshold, minimal_error, optimal_sign};
}

