// Initialize EGL and create main and auxiliary contexts for OpenGL ES rendering
void InitializeEGL() {
    ANativeWindow *nativeWindow = (ANativeWindow*)displaySurface;

    EGLint temp, visualFormat;

    EGLDisplay eglDisplay = eglGetDisplay(EGL_DEFAULT_DISPLAY);

    if (!eglInitialize(eglDisplay, 0, 0)) {
        LogError("Failed to initialize EGL: " + GetEglError());
        return;
    }

    EGLint contextAttrs[] = {
        EGL_CONTEXT_CLIENT_VERSION, 2, EGL_NONE
    };

    const EGLint surfaceAttrs[] = {
        EGL_SURFACE_TYPE, EGL_WINDOW_BIT,
        EGL_RENDERABLE_TYPE, EGL_OPENGL_ES2_BIT,
        EGL_BLUE_SIZE, 8,
        EGL_GREEN_SIZE, 8,
        EGL_RED_SIZE, 8,
        EGL_ALPHA_SIZE, 8,
        EGL_BUFFER_SIZE, 32,
        EGL_DEPTH_SIZE, 24,
        EGL_NONE
    };

    EGLint configCount;
    EGLConfig mainConfig;

    if (!eglChooseConfig(eglDisplay, surfaceAttrs, &mainConfig, 1, &configCount)) {
        LogError("Failed to select main EGL config: " + GetEglError());
        return;
    }

    if (!eglGetConfigAttrib(eglDisplay, mainConfig, EGL_NATIVE_VISUAL_ID, &visualFormat)) {
        LogError("Failed to retrieve native visual ID: " + GetEglError());
        return;
    }

    ANativeWindow_setBuffersGeometry(nativeWindow, 0, 0, visualFormat);

    EGLSurface windowSurface = eglCreateWindowSurface(eglDisplay, mainConfig, nativeWindow, NULL);
    if (windowSurface == NULL) {
        LogError("Failed to create window surface: " + GetEglError());
        return;
    }

    EGLContext mainContext = eglCreateContext(eglDisplay, mainConfig, EGL_NO_CONTEXT, contextAttrs);
    if (mainContext == NULL) {
        LogError("Failed to create main OpenGL context: " + GetEglError());
        return;
    }

    // Configuration for off-screen pbuffer surface
    const EGLint pbufferAttrs[] = {
        EGL_SURFACE_TYPE, EGL_PBUFFER_BIT,
        EGL_RENDERABLE_TYPE, EGL_OPENGL_ES2_BIT,
        EGL_BLUE_SIZE, 8,
        EGL_GREEN_SIZE, 8,
        EGL_RED_SIZE, 8,
        EGL_ALPHA_SIZE, 8,
        EGL_DEPTH_SIZE, 0,
        EGL_STENCIL_SIZE, 0,
        EGL_NONE
    };

    EGLint pbSurfaceAttrs[] = {
        EGL_WIDTH, 1,
        EGL_HEIGHT, 1,
        EGL_TEXTURE_TARGET, EGL_NO_TEXTURE,
        EGL_TEXTURE_FORMAT, EGL_NO_TEXTURE,
        EGL_NONE
    };

    EGLint auxConfigCount;
    EGLConfig auxConfig;

    if (!eglChooseConfig(eglDisplay, pbufferAttrs, &auxConfig, 1, &auxConfigCount)) {
        LogError("Failed to select auxiliary EGL config: " + GetEglError());
        return;
    }

    EGLSurface pbufferSurface = eglCreatePbufferSurface(eglDisplay, auxConfig, pbSurfaceAttrs);
    if (pbufferSurface == NULL) {
        LogError("Failed to create pbuffer surface: " + GetEglError());
        return;
    }

    EGLContext auxContext = eglCreateContext(eglDisplay, auxConfig, mainContext, contextAttrs);
    if (auxContext == NULL) {
        LogError("Failed to create auxiliary context: " + GetEglError());
        return;
    }

    if (!eglMakeCurrent(eglDisplay, windowSurface, windowSurface, mainContext)) {
        LogError("Could not activate main EGL context: " + GetEglError());
        return;
    }
}

