// Helper function to convert roster data to Java HashMap
jobject createRosterMap(JNIEnv* env) {
    jclass hashmap_class = env->FindClass("java/util/HashMap");
    jclass boolean_class = env->FindClass("java/lang/Boolean");
    jmethodID hashmap_constructor = env->GetMethodID(hashmap_class, "<init>", "()V");
    jmethodID boolean_constructor = env->GetMethodID(boolean_class, "<init>", "(Z)V");  // Boolean constructor with boolean parameter
    jmethodID hashmap_put = env->GetMethodID(hashmap_class, "put", "(Ljava/lang/Object;Ljava/lang/Object;)Ljava/lang/Object;");
    jobject result_map = env->NewObject(hashmap_class, hashmap_constructor);

    int roster_count;
    std::map<std::string, RosterItem>* roster_data = GetRosterMap();
    std::map<std::string, RosterItem>::iterator item_iterator;

    if (!roster_data || roster_data->size() <= 0)
        return result_map;

    item_iterator = roster_data->begin();
    while (item_iterator != roster_data->end()) {
        jstring entry_key = env->NewStringUTF(item_iterator->second.name.c_str());
        jboolean friend_status = item_iterator->second.isfriend;
        jobject boolean_wrapper = env->NewObject(boolean_class, boolean_constructor, friend_status);  // Wrap boolean in Boolean object
        env->CallObjectMethod(result_map, hashmap_put, entry_key, boolean_wrapper);  // Insert key-value pair into HashMap
        item_iterator++;
    }

    return result_map;
}

#include <string>
#include <vector>
#include <stdexcept>
#include <cassert>

std::vector<unsigned char> base64_decode(const std::string &input) {
    std::string alphabet =
        "ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        "abcdefghijklmnopqrstuvwxyz"
        "0123456789+/";

    size_t input_length = input.size();
    size_t pos = 0;
    size_t idx = 0;
    size_t input_pos = 0;
    unsigned char group_4[4], group_3[3];
    std::vector<unsigned char> result;

    while (input_length-- && (input[input_pos] != '=') && 
           (isalnum(input[input_pos]) || input[input_pos] == '+' || input[input_pos] == '/')) {
        group_4[idx++] = input[input_pos]; 
        input_pos++;

        if (idx == 4) {
            for (idx = 0; idx < 4; idx++)
                group_4[idx] = static_cast<unsigned char>(alphabet.find(group_4[idx]));

            group_3[0] = (group_4[0] << 2) | ((group_4[1] & 0x30) >> 4);
            group_3[1] = ((group_4[1] & 0x0F) << 4) | ((group_4[2] & 0x3C) >> 2);
            group_3[2] = ((group_4[2] & 0x03) << 6) | group_4[3];

            for (idx = 0; idx < 3; idx++)
                result.push_back(group_3[idx]);
            idx = 0;
        }
    }

    if (idx > 0) {
        for (pos = idx; pos < 4; pos++)
            group_4[pos] = 0;

        for (pos = 0; pos < 4; pos++)
            group_4[pos] = static_cast<unsigned char>(alphabet.find(group_4[pos]));

        group_3[0] = (group_4[0] << 2) | ((group_4[1] & 0x30) >> 4);
        group_3[1] = ((group_4[1] & 0x0F) << 4) | ((group_4[2] & 0x3C) >> 2);
        group_3[2] = ((group_4[2] & 0x03) << 6) | group_4[3];

        for (pos = 0; pos < idx - 1; pos++)
            result.push_back(group_3[pos]);
    }

    return result;
}

