bool negative_flag = 0;
bool carry_flag = 0;
bool zero_flag = 0;
bool overflow_flag = 0;

asm volatile (
    "sub %1, %2, %3\n\t"  // Compute difference: %1 = %2 - %3
    "it  eq\n\t"          // Check if result is zero (zero flag)
    "moveq %0, #1\n\t"    // Set zero_flag if subtraction yields equality
    "it  mi\n\t"          // Check if result is negative (negative flag)
    "movmi %0, #1\n\t"    // Set negative_flag if result is negative
    "it  cs\n\t"          // Check if carry occurred (carry flag)
    "movcs %0, #0\n\t"    // Clear carry_flag if carry is set
    "it  vs\n\t"          // Check for overflow condition
    "movvs %0, #1"        // Set overflow_flag if overflow detected
    : "=r" (zero_flag), "=r" (negative_flag), "=r" (carry_flag), "=r" (overflow_flag)
    : "r" (reg[dest].I), "r" (reg[base].I), "r" (value)
    : "cc"  // Condition codes are modified
);

// Normalize flag states according to ARM conventions
negative_flag = (negative_flag != 0);
carry_flag = (carry_flag == 0);
zero_flag = (zero_flag != 0);
overflow_flag = (overflow_flag != 0);

