    }

    return 0;
}

LRESULT CALLBACK MainWndProc(HWND hWnd, UINT message, WPARAM wParam, LPARAM lParam) {
    switch (message) {
    case WM_TRAYNOTIFY:
        if (lParam == WM_LBUTTONDOWN) {
            // Handle tray icon click
            MessageBox(hWnd, "Notification icon activated.", "Info", MB_OK);
        }
        break;
    case WM_DESTROY:
        PostQuitMessage(0);
        break;
    default:
        return DefWindowProc(hWnd, message, wParam, lParam);
    }
    return 0;
}

void PinToNotificationArea(HWND hWnd) {
