// Perform multi-precision addition of two arrays
void big_int_add(uint64_t* result, const uint64_t* operand_a, const uint64_t* operand_b, int length) {
    uint64_t carry_flag = 0;
    for (int index = 0; index < length; index++) {
        uint64_t current_sum;
        __asm__(
            "add %[op_b], %[op_a]\n\t"      // Add operand_b to operand_a
            "adc $0, %[carry]\n\t"          // Add carry bit to result
            : [current_sum] "=r" (current_sum), [carry_flag] "=r" (carry_flag)
            : [op_a] "r" (operand_a[index]), [op_b] "r" (operand_b[index]), [carry_flag] "r" (carry_flag)
            : "cc"
        );
        result[index] = current_sum;
    }
}

