// Define the LED pin
const int ledPin = 9;

// Define the initial pattern and brightness
int blinkPattern[] = {1, 0, 1, 0}; // 1 for on, 0 for off
int timeDelays[] = {500, 1000, 500, 1000}; // delays in milliseconds
int lightLevel[] = {128, 0, 128, 0}; // PWM values (0-255)
int stepCount = sizeof(blinkPattern) / sizeof(blinkPattern[0]);

// Variables to store user input
String userPattern = "";
String userDelays = "";
String userBrightness = "";

void setup() {
  // Initialize the LED pin as an output
  pinMode(ledPin, OUTPUT);

  // Start the serial communication
  Serial.begin(9600);
  Serial.println("LED Blink Pattern Controller");
  Serial.println("Enter new pattern, delays, and brightness values separated by commas.");
  Serial.println("Example: 1,0,1,0,500,1000,500,1000,128,0,128,0");
}

void loop() {
  // Check for user input
  if (Serial.available() > 0) {
    String receivedInput = Serial.readStringUntil('\n');
    processInput(receivedInput);
  }

  // Blink the LED according to the current pattern
  for (int step = 0; step < stepCount; step++) {
    analogWrite(ledPin, lightLevel[step]);
    delay(timeDelays[step]);
  }
}

void processInput(String input) {
  // Split the input string into parts
  String segments[12];
  int segmentCount = 0;
  int pos = 0;

  while (pos < input.length()) {
    int commaPos = input.indexOf(',', pos);
    if (commaPos == -1) {
      segments[segmentCount] = input.substring(pos);
      segmentCount++;
      break;
    }
    segments[segmentCount] = input.substring(pos, commaPos);
    segmentCount++;
    pos = commaPos + 1;
  }

  // Update the pattern, delays, and brightness
  if (segmentCount >= 3 && segmentCount % 3 == 0) {
    stepCount = segmentCount / 3;
    for (int i = 0; i < stepCount; i++) {
      blinkPattern[i] = segments[i * 3].toInt();
      timeDelays[i] = segments[i * 3 + 1].toInt();
      lightLevel[i] = segments[i * 3 + 2].toInt();
    }
    Serial.println("Pattern updated successfully!");
  } else {
    Serial.println("Invalid input. Please enter a valid pattern, delays, and brightness values.");
  }
}

