// Type caster for MPI_Comm to support passing MPI communicators from Python
namespace pybind11 {
namespace detail {

template <>
struct type_caster<MPI_Comm> {
public:
    PYBIND11_TYPE_CASTER(MPI_Comm, _("MPI_Comm"));

    bool load(py::handle src, bool) {
        if (!py::isinstance<py::capsule>(src)) {
            return false;
        }
        MPI_Comm* comm_ptr = static_cast<MPI_Comm*>(PyCapsule_GetPointer(src.ptr(), "MPI_Comm"));
        if (comm_ptr == nullptr) {
            return false;
        }
        value = *comm_ptr;
        return true;
    }

    static py::handle cast(MPI_Comm src, py::return_value_policy, py::handle) {
        py::object capsule = py::capsule(new MPI_Comm(src), "MPI_Comm", [](void* v) {
            MPI_Comm* comm = static_cast<MPI_Comm*>(v);
            MPI_Comm_free(comm);
        });
        return capsule.release();
    }
};

}
}

// Computation class using MPI and C++ features
class ParallelComputation {
    double scale_factor;
    std::vector<int> buffer;
    MPI_Comm communicator_;

public:
    void Initialize() {
        int rank;
        MPI_Comm_rank(communicator_, &rank);
        buffer.clear();
        buffer.resize(8, rank);
    }

    void AssignCommunicator(MPI_Comm comm) {
        communicator_ = comm;
    }

    ParallelComputation(double factor) : scale_factor(factor) {}

    ~ParallelComputation() {
        std::cout << "Object cleanup completed.\n";
    }

    double ProcessValue(double value) {
        std::this_thread::sleep_for(std::chrono::milliseconds(static_cast<int>(value) * 5));
        for (size_t idx = 0; idx < buffer.size(); ++idx) {
            std::cout << buffer[idx] << " ";
        }
        std::cout << std::endl;
        return scale_factor * value;
    }
};

PYBIND11_MODULE(custom_module, m) {
    py::class_<ParallelComputation>(m, "ParallelComputation")
        .def(py::init<double>())
        .def("AssignCommunicator", &ParallelComputation::AssignCommunicator)
        .def("ProcessValue", &ParallelComputation::ProcessValue)
        .def("Initialize", &ParallelComputation::Initialize);
}

