#include <iostream>

// Retrieve JNI environment for current thread
JNIEnv* ObtainJniEnvironment() {
    PrepareThreadContext();
    JNIEnv* jniEnv;
    jint status = javaVM->GetEnv(reinterpret_cast<void**>(&jniEnv), JNI_VERSION_1_6);

    if (status == JNI_OK) {
        // Current thread is attached to JVM, return existing environment
        return jniEnv;
    } else if (status == JNI_EDETACHED) {
        // Thread not attached, attach it first
        status = javaVM->AttachCurrentThread(reinterpret_cast<void**>(&jniEnv), nullptr);
        if (status != JNI_OK) {
            PrintError("Failed to attach thread to Java Virtual Machine");
            return nullptr;
        }
        return jniEnv;
    } else {
        // Unexpected error condition
        PrintError("Unable to acquire JNI environment reference");
        return nullptr;
    }
}

