// Compute the nth Fibonacci number iteratively
int fibonacci(int num) {
    if (num < 2) return num;
    int prev = 0, curr = 1, next_val;
    for (int index = 2; index <= num; ++index) {
        next_val = prev + curr;
        prev = curr;
        curr = next_val;
    }
    return curr;
}

