void initializeJVM() {
#ifdef JNI_VERSION_1_2
    JavaVMInitArgs vmConfiguration;
    JavaVMOption runtimeOptions[1];
    runtimeOptions[0].optionString = const_cast<char*>(("-Djava.class.path=" USER_CLASSPATH));
    vmConfiguration.version = 0x00010002;
    vmConfiguration.options = runtimeOptions;
    vmConfiguration.nOptions = 1;
    vmConfiguration.ignoreUnrecognized = JNI_TRUE;
    // Create the Java VM
    status = JNI_CreateJavaVM(&javaVm, (void**)&jniEnv, &vmConfiguration);
#else
    JDK1_1InitArgs vmConfiguration;
    char classpathBuffer[2048];
    vmConfiguration.version = 0x00010001;
    JNI_GetDefaultJavaVMInitArgs(&vmConfiguration);
    // Append USER_CLASSPATH to the default system class path
    sprintf(classpathBuffer, "%s%c%s", vmConfiguration.classpath, PATH_SEPARATOR, USER_CLASSPATH);
    vmConfiguration.classpath = classpathBuffer;
    // Create the Java VM
    status = JNI_CreateJavaVM(&javaVm, &jniEnv, &vmConfiguration);
#endif /* JNI_VERSION_1_2 */
}

