    javaVm->DestroyJavaVM();
}

jstring createJavaString(const char *text) {
    jstring stringResult;
    jbyteArray byteData = 0;
    jclass stringClass;
    int length;
    length = strlen(text);
    byteData = jniEnv->NewByteArray(length);
    stringClass = jniEnv->FindClass(STRING);
    if (byteData != NULL) {
        jmethodID constructorMethod;
        jniEnv->SetByteArrayRegion(byteData, 0, length, (jbyte *)text);
        constructorMethod = jniEnv->GetMethodID(stringClass, "<init>", "([B)V");
        stringResult = (jstring) jniEnv->NewObject(stringClass, constructorMethod, byteData);
        jniEnv->DeleteLocalRef(byteData);
        return stringResult;
    }
    return NULL;
}

int process_latex_expression(char* inputFormula) {
    jclass engineClass, inputClass, sessionClass;
    jmethodID methodId;
    jstring jstr;
    jclass stringClass;
    jobjectArray arguments;
    jstring latexInput = createJavaString(inputFormula);
    jstring outputResult;

    engineClass = jniEnv->FindClass(SNUGGLE_ENGINE);
    inputClass = jniEnv->FindClass(SNUGGLE_INPUT);
    sessionClass = jniEnv->FindClass(SNUGGLE_SESSION);

    if (engineClass == NULL) return -1;

    // Create SnuggleEngine instance
    methodId = jniEnv->GetMethodID(engineClass, "<init>", "()V");
    jobject engineInstance = jniEnv->NewObject(engineClass, methodId);

    // Create SnuggleSession instance
    methodId = jniEnv->GetMethodID(engineClass, "createSession", "()Luk/ac/ed/ph/snuggletex/SnuggleSession;");
    jobject processingSession = jniEnv->CallObjectMethod(engineInstance, methodId);

    // Create SnuggleInput instance
    methodId = jniEnv->GetMethodID(inputClass, "<init>", "(Ljava/lang/String;)V");
    jobject inputObject = jniEnv->NewObject(inputClass, methodId, latexInput);

    // Parse input
    methodId = jniEnv->GetMethodID(sessionClass, "parseInput", "(Luk/ac/ed/ph/snuggletex/SnuggleInput;)V");
    jniEnv->CallVoidMethod(processingSession, methodId);

    // Build XML string
    methodId = jniEnv->GetMethodID(sessionClass, "buildXMLString", "()Ljava/lang/String;");
    outputResult = (jstring) jniEnv->CallObjectMethod(processingSession, methodId);

    if (jniEnv->ExceptionCheck()) {
        jthrowable exception = jniEnv->ExceptionOccurred();
        jniEnv->ExceptionDescribe();
        jniEnv->ExceptionClear();
        return -1;
    }

    const char *xmlOutput = jniEnv->GetStringUTFChars(outputResult, NULL);
    cout << "Generated XML: " << xmlOutput << endl;
    jniEnv->ReleaseStringUTFChars(outputResult, xmlOutput);

    return 0;
}

