// Card structure to represent a single card
class PlayingCard {
public:
    SuitType suit;
    RankType rank;

    PlayingCard(SuitType s, RankType r) : suit(s), rank(r) {}

    std::string describe() const {
        return rankToName(rank) + " of " + suitToName(suit);
    }
};

// Function to create a standard deck of 52 cards
std::vector<PlayingCard> generateDeck() {
    std::vector<PlayingCard> cards;
    for (int s = 0; s < 4; ++s) {
        for (int r = 0; r < 13; ++r) {
            cards.emplace_back(static_cast<SuitType>(s), static_cast<RankType>(r));
        }
    }
    return cards;
}

