// Template specialization for a 4D vector class
template <>
class Vector {
public:
    // Access elements using template parameters as indices
    double get<1>() const { return elements[0]; }
    double get<2>() const { return elements[1]; }
    double get<4>() const { return elements[2]; }
    double get<8>() const { return elements[3]; }

    // Compute dot product with another vector
    double multiply(const Vector& second) const {
        return get<1>() * second.get<1>() +
