};

#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <iostream>
#include <fstream>

using namespace std;

unsigned int THREAD_COUNT = 10;
unsigned int ARRAY_CAPACITY = 1000000;

struct sortData {
    int* begin;   // pointer to the first array element
    int count;
};

void* sequentialSort(void* data) {
    sortData* param = (sortData*)data;
    int* buffer = param->begin;
    int numItems = param->count;
    for (int i = 0; i < (numItems - 1); i++) {
        for (int j = 0; j < (numItems - 1 - i); j++) {
            if (buffer[j] > buffer[j + 1]) {
                int swap = buffer[j];
                buffer[j] = buffer[j + 1];
                buffer[j + 1] = swap;
            }
        }
    }
    return NULL;
}

void combine(int* first, int* second, int firstSize, int secondSize) {
    int indexA = 0, indexB = 0, indexMerged = 0;
    int* result = new int[firstSize + secondSize];
    while (indexA < firstSize && indexB < secondSize) {
        if (first[indexA] < second[indexB]) {
            result[indexMerged++] = first[indexA++];
        } else {
            result[indexMerged++] = second[indexB++];
        }
    }
    while (indexA < firstSize) {
        result[indexMerged++] = first[indexA++];
    }
    while (indexB < secondSize) {
        result[indexMerged++] = second[indexB++];
    }
    for (int k = 0; k < indexMerged; k++) {
        first[k] = result[k];
    }
    delete[] result;
}

int main(int argc, char* argv[]) {
    ifstream inputFile(argv[1]);
    int itemCount = 0;
    int dataArray[ARRAY_CAPACITY];
    int value; // size of the array = size of the elements
    int temp;

    while (inputFile >> value) {
        dataArray[itemCount] = value;
        itemCount++;
    }

    inputFile.close();

    sortData partition[THREAD_COUNT];
    int blockSize = ARRAY_CAPACITY / THREAD_COUNT;

    for (int i = 0; i < THREAD_COUNT; i++) {
        partition[i].begin = &dataArray[i * blockSize];
        partition[i].count = blockSize;
        pthread_t worker;
        pthread_create(&worker, NULL, sequentialSort, (void*)&partition[i]);
        pthread_join(worker, NULL);
    }

    int leftover = ARRAY_CAPACITY - (THREAD_COUNT * blockSize);

    if (leftover > 0) {
        combine(&dataArray[(THREAD_COUNT - 2) * blockSize], &dataArray[(THREAD_COUNT - 1) * blockSize], blockSize, leftover);
    }

    for (int i = THREAD_COUNT - 2; i >= 0; i--) {
        combine(&dataArray[i * blockSize], &dataArray[(i + 1) * blockSize], blockSize, blockSize);
    }

    ofstream outputFile(argv[2]);

    for (int i = 0; i < ARRAY_CAPACITY; i++) {
        outputFile << dataArray[i] << endl;
    }

    outputFile.close();

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

// Combine two sorted subarrays into one sorted array
void combine(vector<int> &arr, int start, int middle, int end) {
    int sizeLeft = middle - start + 1;
    int sizeRight = end - middle;

    vector<int> leftPart(sizeLeft), rightPart(sizeRight);

    for (int idx = 0; idx < sizeLeft; idx++)
        leftPart[idx] = arr[start + idx];
    for (int idx = 0; idx < sizeRight; idx++)
        rightPart[idx] = arr[middle + 1 + idx];

    int leftIdx = 0, rightIdx = 0, mergeIdx = start;
    while (leftIdx < sizeLeft && rightIdx < sizeRight) {
        if (leftPart[leftIdx] <= rightPart[rightIdx]) {
            arr[mergeIdx++] = leftPart[leftIdx++];
        } else {
            arr[mergeIdx++] = rightPart[rightIdx++];
        }
    }

    while (leftIdx < sizeLeft)
        arr[mergeIdx++] = leftPart[leftIdx++];

    while (rightIdx < sizeRight)
        arr[mergeIdx++] = rightPart[rightIdx++];
}

// Recursively sort array using merge sort algorithm
void divideAndConquerSort(vector<int> &arr, int start, int end) {
    if (start < end) {
        int midPoint = start + (end - start) / 2;
        divideAndConquerSort(arr, start, midPoint);
        divideAndConquerSort(arr, midPoint + 1, end);
        combine(arr, start, midPoint, end);
    }
}

int main() {
    vector<int> data = {12, 11, 13, 5, 6, 7};
    int length = data.size();

    cout << "Initial array: " << endl;
    for(int index = 0; index < length; index++)
        cout << data[index] << " ";
    cout << endl;

    divideAndConquerSort(data, 0, length - 1);

    cout << "Array after sorting: " << endl;
    for(int index = 0; index < length; index++)
        cout << data[index] << " ";
    cout << endl;

    return 0;
}

#include <algorithm>
#include <vector>
#include <iostream>
#include <cmath>

// Perform insertion sort on a subarray from index 'start' to 'end'
void performInsertionSort(std::vector<int>& data, int start, int end) {
    for (int idx = start + 1; idx <= end; ++idx) {
        int current = data[idx];
        int prevIdx = idx - 1;
        while (prevIdx >= start && data[prevIdx] > current) {
            data[prevIdx + 1] = data[prevIdx];
            --prevIdx;
        }
        data[prevIdx + 1] = current;
    }
}

// Maintain the max-heap property for a subtree rooted at index 'root'
void maintainHeap(std::vector<int>& data, int heapSize, int root) {
    int maxIndex = root;
    int leftChild = 2 * root + 1;
    int rightChild = 2 * root + 2;

    if (leftChild < heapSize && data[leftChild] > data[maxIndex])
        maxIndex = leftChild;

    if (rightChild < heapSize && data[rightChild] > data[maxIndex])
        maxIndex = rightChild;

    if (maxIndex != root) {
        std::swap(data[root], data[maxIndex]);
        maintainHeap(data, heapSize, maxIndex);
    }
}

// Sort the array using heap sort algorithm
void heapBasedSort(std::vector<int>& data, int size) {
    // Build max heap
    for (int i = size / 2 - 1; i >= 0; --i)
        maintainHeap(data, size, i);

    // Extract elements one by one
    for (int i = size - 1; i >= 0; --i) {
        std::swap(data[0], data[i]);
        maintainHeap(data, i, 0);
    }
}

// Recursive utility function for introsort
void introsortRecursive(std::vector<int>& data, int low, int high, int maxDepth) {
    if (high - low > 16) {
        if (maxDepth == 0) {
            heapBasedSort(data, high - low + 1);
            return;
        }
        maxDepth = maxDepth - 1;
        auto pivotIt = std::partition(data.begin() + low, data.begin() + high, std::less<int>());
        int pivotPos = pivotIt - data.begin();
        introsortRecursive(data, low, pivotPos - 1, maxDepth);
        introsortRecursive(data, pivotPos, high, maxDepth);
    } else {
        performInsertionSort(data, low, high);
    }
}

// Main introsort function
void introsort(std::vector<int>& data) {
    int maxDepth = 2 * static_cast<int>(std::log(data.size()));
    introsortRecursive(data, 0, data.size() - 1, maxDepth);
}

int main() {
    std::vector<int> dataset = {34, 7, 23, 32, 5, 62, 1, 89, 45, 21, 12, 34, 56, 78, 90, 12, 34, 56, 78, 90};
    introsort(dataset);
    for (int value : dataset) {
        std::cout << value << " ";
    }
    return 0;
}

