using namespace std;

// Retrieve the HTML content from a given URL
string retrievePage(const string& target_url) {
    httplib::Client client(target_url);
    auto response = client.Get("/");
    if (response && response->status == 200) {
        return response->body;
    } else {
        cerr << "Error: Unable to fetch " << target_url << endl;
        return "";
    }
}

// Extract all hyperlinks from HTML content and resolve relative URLs
vector<string> gatherLinks(const string& html_data, const string& origin_url) {
    vector<string> collected_links;
    simple_html_dom_parser parser;
    auto dom = parser.parse(html_data);
    for (auto& anchor : dom->find("a")) {
        string href = anchor->attr("href");
        if (!href.empty() && href[0] == '/') {
            // Transform relative path to absolute URL
            href = origin_url + href;
        }
        collected_links.push_back(href);
    }
    return collected_links;
}

// Perform web crawling on a single URL
void processURL(const string& url, queue<string>& pending_urls, set<string>& seen_urls) {
    if (seen_urls.count(url) > 0) {
        return;
    }

    seen_urls.insert(url);
    string page_content = retrievePage(url);
    if (!page_content.empty()) {
        vector<string> new_links = gatherLinks(page_content, url);
        for (const auto& link : new_links) {
            pending_urls.push(link);
        }
    }
}

// Entry point of the program
int main() {
    string initial_url = "http://example.com";
    queue<string> pending_urls;
    set<string> seen_urls;

    pending_urls.push(initial_url);

    while (!pending_urls.empty()) {
        string current_url = pending_urls.front();
        pending_urls.pop();

        thread worker_thread(processURL, current_url, ref(pending_urls), ref(seen_urls));
        worker_thread.join();
    }

    return 0;
}

