#include <opencv2/opencv.hpp>
#include <iostream>

class VesselEnhancementFilter {
public:
    VesselEnhancementFilter(double scale = 1.5, double paramA = 0.5, double paramB = 1.5) 
        : sigma(scale), alpha(paramA), beta(paramB) {}

    cv::Mat processImage(const cv::Mat& source) {
        cv::Mat grayscale;
        cv::cvtColor(source, grayscale, cv::COLOR_BGR2GRAY);

        cv::Mat hessianComponents;
        calculateHessian(grayscale, hessianComponents);

        cv::Mat eigenVal1, eigenVal2;
        calculateEigenvalues(hessianComponents, eigenVal1, eigenVal2);

        cv::Mat responseMap;
        computeResponse(eigenVal1, eigenVal2, responseMap);

        adjustContrast(responseMap);

        return responseMap;
    }

private:
    double sigma;
    double alpha;
    double beta;

    void calculateHessian(const cv::Mat& src, cv::Mat& dst) {
        cv::Mat gradX, gradY;
        cv::Sobel(src, gradX, CV_64F, 1, 0, 3, 1, 0, cv::BORDER_DEFAULT);
        cv::Sobel(src, gradY, CV_64F, 0, 1, 3, 1, 0, cv::BORDER_DEFAULT);

        cv::Mat dxx, dyy, dxy;
        cv::multiply(gradX, gradX, dxx);
        cv::multiply(gradY, gradY, dyy);
        cv::multiply(gradX, gradY, dxy);

        cv::GaussianBlur(dxx, dxx, cv::Size(0, 0), sigma);
        cv::GaussianBlur(dyy, dyy, cv::Size(0, 0), sigma);
        cv::GaussianBlur(dxy, dxy, cv::Size(0, 0), sigma);

        dst.create(src.size(), CV_64FC3);
        cv::MatIterator_<cv::Vec<double, 3>> outIter = dst.begin<cv::Vec<double, 3>>();
        cv::MatIterator_<double> dxxIt = dxx.begin<double>(), dyyIt = dyy.begin<double>(), dxyIt = dxy.begin<double>();

        while (outIter != dst.end<cv::Vec<double, 3>>()) {
            (*outIter)[0] = *dxxIt;
            (*outIter)[1] = *dyyIt;
            (*outIter)[2] = *dxyIt;

            ++outIter;
            ++dxxIt;
            ++dyyIt;
            ++dxyIt;
        }
    }

    void calculateEigenvalues(const cv::Mat& input, cv::Mat& lambda1, cv::Mat& lambda2) {
        std::vector<cv::Mat> eigenvectors;
        cv::eigen(input, eigenvectors);

        lambda1 = eigenvectors[0];
        lambda2 = eigenvectors[1];
    }

    void computeResponse(const cv::Mat& lambda1, const cv::Mat& lambda2, cv::Mat& output) {
        output.create(lambda1.size(), CV_64F);

        cv::MatIterator_<double> respIt = output.begin<double>();
        cv::MatConstIterator_<double> l1It = lambda1.begin<double>(), l2It = lambda2.begin<double>();

        while (respIt != output.end<double>()) {
            double ratio = std::sqrt(*l2It) / std::sqrt(*l1It);
            double scaleRatio = std::sqrt(*l1It) / std::sqrt(*l2It);

            *respIt = std::exp(-(*l1It * *l1It) / (2.0 * alpha * alpha)) 
                    * (1.0 - std::exp(-ratio * ratio / (2.0 * beta * beta)));

            ++respIt;
            ++l1It;
            ++l2It;
        }
    }

    void adjustContrast(cv::Mat& image) {
        double minVal, maxVal;
        cv::minMaxLoc(image, &minVal, &maxVal);

        image -= minVal;
        image /= (maxVal - minVal);
    }
};

int main() {
    cv::Mat inputImage = cv::imread("source.jpg");
    if (inputImage.empty()) {
        std::cout << "Error loading image!" << std::endl;
        return -1;
    }

    VesselEnhancementFilter filter;
    cv::Mat result = filter.processImage(inputImage);
    cv::imshow("Processed Result", result);
    cv::waitKey(0);

    return 0;
}

