// Define a table as a vector of maps
using Dataset = std::vector<std::map<std::string, std::string>>;

// Function to evaluate a comparison
bool performComparison(const std::string& leftOperand, const std::string& operatorSymbol, const std::string& rightOperand) {
    if (operatorSymbol == "==") return leftOperand == rightOperand;
    if (operatorSymbol == "!=") return leftOperand != rightOperand;
    if (operatorSymbol == "<") return leftOperand < rightOperand;
    if (operatorSymbol == ">") return leftOperand > rightOperand;
    if (operatorSymbol == "<=") return leftOperand <= rightOperand;
    if (operatorSymbol == ">=") return leftOperand >= rightOperand;
    return false;
}

// Function to evaluate a Boolean query on a row
bool evaluateRowCondition(const std::map<std::string, std::string>& record, const std::string& condition) {
    std::istringstream stream(condition);
    std::string word;
    std::vector<std::string> parts;

    // Tokenize the condition
    while (stream >> word) {
        parts.push_back(word);
    }

    bool overallResult = false;
    bool currentEvaluation = false;
    bool shouldNegate = false;
    std::string leftSide, comparisonOp, rightSide;

    for (size_t index = 0; index < parts.size(); ++index) {
        if (parts[index] == "NOT") {
            shouldNegate = true;
            continue;
        }

        if (index + 2 < parts.size() && 
            (parts[index + 1] == "==" || parts[index + 1] == "!=" || parts[index + 1] == "<" || 
             parts[index + 1] == ">" || parts[index + 1] == "<=" || parts[index + 1] == ">=")) {

            leftSide = record.at(parts[index]);
            comparisonOp = parts[index + 1];
            rightSide = record.at(parts[index + 2]);
            currentEvaluation = performComparison(leftSide, comparisonOp, rightSide);
            index += 2;
        } else {
            currentEvaluation = (record.at(parts[index]) == "true");
        }

        if (shouldNegate) {
            currentEvaluation = !currentEvaluation;
            shouldNegate = false;
        }

        if (index == 0) {
            overallResult = currentEvaluation;
        } else {
            if (parts[index - 1] == "AND") {
                overallResult = overallResult && currentEvaluation;
            } else if (parts[index - 1] == "OR") {
                overallResult = overallResult || currentEvaluation;
            }
        }
    }

    return overallResult;
}

// Function to evaluate the Boolean query on two datasets
bool checkDatasetAgainstQuery(const Dataset& primarySet, const Dataset& secondarySet, const std::string& condition) {
    for (const auto& entry : primarySet) {
        if (evaluateRowCondition(entry, condition)) {
            return true;
        }
    }

    for (const auto& entry : secondarySet) {
        if (evaluateRowCondition(entry, condition)) {
            return true;
        }
    }

    return false;
}

int main() {
    // Example datasets
    Dataset primaryData = {
        {{"name", "Alice"}, {"age", "30"}, {"city", "New York"}},
        {{"name", "Bob"}, {"age", "25"}, {"city", "Los Angeles"}}
    };

    Dataset secondaryData = {
        {{"name", "Charlie"}, {"age", "35"}, {"city", "Chicago"}},
        {{"name", "Diana"}, {"age", "28"}, {"city", "New York"}}
    };

    // Example condition
    std::string condition = "city == New York OR age > 30";

    // Evaluate the condition
    bool outcome = checkDatasetAgainstQuery(primaryData, secondaryData, condition);

    // Output the result
    std::cout << "Outcome: " << (outcome ? "true" : "false") << std::endl;

    return 0;
}

