// Memoization cache for Fibonacci sequence calculation
std::unordered_map<int, int> cache;

// Computes the nth Fibonacci number using dynamic programming with memoization
int calculateFibonacci(int position) {
    // Base cases: F(0) = 0, F(1) = 1
    if (position <= 1) return position;

    // Check if result is already computed and stored
    if (cache.count(position) > 0) return cache[position];

    // Compute and store the result for future use
    cache[position] = calculateFibonacci(position - 1) + calculateFibonacci(position - 2);
    return cache[position];
}

