// Perform atomic compare-and-swap on a 128-bit value
template<typename T>
inline bool atomic_cas_128(volatile T* destination, const T& expected, const T& desired) {
    uint64_t* destPtr = reinterpret_cast<uint64_t*>(destination);
    uint64_t* expPtr = reinterpret_cast<uint64_t*>(const_cast<T*>(&expected));
    uint64_t* desPtr = reinterpret_cast<uint64_t*>(const_cast<T*>(&desired));
    unsigned char successFlag = 0;

    __asm__ __volatile__ (
        "lock; cmpxchg16b %0\n\t"
        "setz %1\n\t"
        : "+m"(*destPtr), "=q"(successFlag)
        : "a"(expPtr[0]), 
          "d"(expPtr[1]), 
          "b"(desPtr[0]), 
          "c"(desPtr[1])
        : "memory", "cc"
    );

    return static_cast<bool>(successFlag);
}

