// Custom converter for std::array<std::complex<double>, 4>
void bind_complex_array4(py::module_ &mod) {
    py::class_<ComplexArray4>(mod, "ComplexArray4")
        .def(py::init<>())
        .def(py::init([](const std::vector<std::complex<double>>& input_vec) {
            if (input_vec.size() != 4) {
                throw std::invalid_argument("ComplexArray4 must contain exactly 4 elements");
            }
            return ComplexArray4{input_vec[0], input_vec[1], input_vec[2], input_vec[3]};
        }))
        .def("get", [](const ComplexArray4& self, size_t idx) {
            if (idx >= 4) {
                throw std::out_of_range("Index out of bounds");
            }
            return self[idx];
        })
        .def("__getitem__", [](const ComplexArray4& self, size_t idx) {
            if (idx >= 4) {
                throw std::out_of_range("Index out of bounds");
            }
            return self[idx];
        })
        .def("__setitem__", [](ComplexArray4& self, size_t idx, const std::complex<double>& val) {
            if (idx >= 4) {
                throw std::out_of_range("Index out of bounds");
            }
            self[idx] = val;
        })
        .def("__repr__", [](const ComplexArray4& self) {
            return "ComplexArray4([" + py::str(self[0]) + ", " + py::str(self[1]) + ", " + py::str(self[2]) + ", " + py::str(self[3]) + "])";
        });
