             "mov eax, %1 \n"
             "mov edx, 32 \n"
             "bitloop: \n"
             "shr eax, 1 \n"
             "adc %0, %0 \n"
             "dec edx \n"
             "jnz bitloop \n"
             "mov %0, eax \n"
             : [output] "=r"(output) : [value] "r"(value) : "eax", "edx");

