// Definition for singly-linked list.
struct Node {
    int data;
    Node *link;
    Node(int x) : data(x), link(nullptr) {}
};

class DetectCycle {
public:
    bool detectLoop(Node *start) {
        if (start == nullptr || start->link == nullptr) {
            return false;
        }

        Node *pointer1 = start;
        Node *pointer2 = start;

        while (pointer2 != nullptr && pointer2->link != nullptr) {
            pointer1 = pointer1->link;
            pointer2 = pointer2->link->link;

            if (pointer1 == pointer2) {
                return true; // Loop detected
            }
        }

        return false; // No loop
    }
};

// Function to create a linked list with a loop for testing
Node* buildListWithLoop() {
    Node *first = new Node(10);
    Node *second = new Node(20);
    Node *third = new Node(30);
    Node *fourth = new Node(40);

    first->link = second;
    second->link = third;
    third->link = fourth;
    fourth->link = second; // Creating a loop

    return first;
}

int main() {
    DetectCycle checker;

    // Test with a linked list with a loop
    Node *headWithLoop = buildListWithLoop();
    cout << "List with loop: " << (checker.detectLoop(headWithLoop) ? "Yes" : "No") << endl;

    // Test with a linked list without a loop
    Node *headWithoutLoop = new Node(100);
    headWithoutLoop->link = new Node(200);
    headWithoutLoop->link->link = new Node(300);
    cout << "List without loop: " << (checker.detectLoop(headWithoutLoop) ? "Yes" : "No") << endl;

    return 0;
}

