// Function to check if a character is an operator
bool isOperator(char c) {
    return c == '+' || c == '-' || c == '*' || c == '/';
}

// Function to check if a character is an operand (number)
bool isOperand(char c) {
    return std::isdigit(c) || c == '.';
}

// Function to check the precedence of operators
int precedence(char op) {
    if (op == '+' || op == '-') return 1;
    if (op == '*' || op == '/') return 2;
    return 0;
}

// Function to convert infix to postfix
std::string infixToPostfix(const std::string &infix) {
    std::stack<char> operators;
    std::string postfix;
    std::stringstream ss(infix);
    std::string token;

    while (ss >> token) {
        if (isOperand(token[0])) {
            postfix += token + " ";
        } else if (isOperator(token[0])) {
            while (!operators.empty() && precedence(operators.top()) >= precedence(token[0])) {
                postfix += operators.top();
                operators.pop();
                postfix += " ";
            }
            operators.push(token[0]);
        } else if (token[0] == '(') {
            operators.push(token[0]);
        } else if (token[0] == ')') {
            while (!operators.empty() && operators.top() != '(') {
                postfix += operators.top();
                operators.pop();
                postfix += " ";
            }
            if (!operators.empty() && operators.top() == '(') {
                operators.pop();
            }
        }
    }

    while (!operators.empty()) {
        postfix += operators.top();
        operators.pop();
        postfix += " ";
    }

    return postfix;
}

// Function to evaluate the postfix expression
double evaluatePostfix(const std::string &postfix) {
    std::stack<double> operands;
    std::istringstream iss(postfix);
    std::string token;

    while (iss >> token) {
        if (isOperand(token[0])) {
            operands.push(std::stod(token));
        } else if (isOperator(token[0])) {
            double second = operands.top(); operands.pop();
            double first = operands.top(); operands.pop();
            switch (token[0]) {
                case '+': operands.push(first + second); break;
                case '-': operands.push(first - second); break;
                case '*': operands.push(first * second); break;
                case '/': operands.push(first / second); break;
            }
        }
    }

    return operands.top();
}

int main() {
    std::string expression = "3 + 4 * 2 / ( 1 - 5 )";
    std::string converted = infixToPostfix(expression);
    double finalResult = evaluatePostfix(converted);

    std::cout << "Infix Expression: " << expression << std::endl;
    std::cout << "Postfix Expression: " << converted << std::endl;
    std::cout << "Result: " << finalResult << std::endl;

    return 0;
}

