using namespace std;

// Function to locate the longest repeated substring pattern
string locateMaxRepeatedPattern(const string &text) {
    int length = text.length();
    string foundPattern = "";
    for (int patternLength = length / 2; patternLength > 0; --patternLength) {
        for (int startIndex = 0; startIndex <= length - patternLength; ++startIndex) {
            string candidate = text.substr(startIndex, patternLength);
            if (text.find(candidate, startIndex + patternLength) != string::npos) {
                if (candidate.length() > foundPattern.length()) {
                    foundPattern = candidate;
                }
            }
        }
    }
    return foundPattern;
}

// Function to apply compression to the input string
string applyCompression(const string &input) {
    string workingString = input;
    while (true) {
        string maxPattern = locateMaxRepeatedPattern(workingString);
        if (maxPattern.empty()) break;

        int occurrences = 0;
        size_t searchPosition = 0;
        while ((searchPosition = workingString.find(maxPattern, searchPosition)) != string::npos) {
            ++occurrences;
            searchPosition += maxPattern.size();
        }

        if (occurrences > 1) {
            string encoded = "[" + maxPattern + "]" + to_string(occurrences);
            workingString = input.substr(0, workingString.find(maxPattern)) + encoded;
        } else {
            break;
        }
    }
    return workingString;
}

// Function to handle file processing operations
void handleFileProcessing(const string &sourcePath, const string &destinationPath) {
    ifstream sourceFile(sourcePath);
    ofstream destinationFile(destinationPath);

    if (!sourceFile.is_open() || !destinationFile.is_open()) {
        cerr << "File access failed." << endl;
        return;
    }

    string currentLine;
    while (getline(sourceFile, currentLine)) {
        if (currentLine.find("d+c+d+f+d+c+d+f+d+c+d+f+d+c+d+f+") != string::npos) {
            string compressedVersion = applyCompression(currentLine);
            destinationFile << compressedVersion << endl;
        } else {
            destinationFile << currentLine << endl;
        }
    }

    sourceFile.close();
    destinationFile.close();
}

int main() {
    string inputFilename = "input.txt";
    string outputFilename = "output.txt";
    handleFileProcessing(inputFilename, outputFilename);
    return 0;
}

