{
    static bool isAuthDialogActive = false;

    switch (uMsg)
    {
    case WM_HOTKEY:
        if (wParam == 101)
        {
            DisplayAuthenticationWindow(hWnd);
        }
        break;
    case WM_KEYDOWN:
    case WM_SYSKEYDOWN:
    case WM_LBUTTONDOWN:
    case WM_RBUTTONDOWN:
        if (!isAuthDialogActive)
        {
            DisplayAuthenticationWindow(hWnd);
        }
        break;
    case WM_DESTROY:
        if (isAuthDialogActive)
        {
            return 0;
        }
        // Continue with default handling when dialog not active
    default:
        return DefWindowProc(hWnd, uMsg, wParam, lParam);
    }

    return 0;
}

void DisplayAuthenticationWindow(HWND hWnd)
{
    isAuthDialogActive = true;
    if (DialogBox(GetModuleHandle(NULL), MAKEINTRESOURCE(IDD_AUTH_DIALOG), hWnd, AuthDialogProc) == IDOK)
    {
        PostQuitMessage(0);
    }
    isAuthDialogActive = false;
}

INT_PTR CALLBACK AuthDialogProc(HWND hDlg, UINT message, WPARAM wParam, LPARAM lParam)
{
    switch (message)
    {
    case WM_INITDIALOG:
        return (INT_PTR)TRUE;
    case WM_COMMAND:
        if (LOWORD(wParam) == IDOK || LOWORD(wParam) == IDCANCEL)
        {
            if (LOWORD(wParam) == IDOK)
            {
                char secretKey[256];
                GetDlgItemText(hDlg, IDC_SECRET_INPUT, secretKey, 256);
                if (std::string(secretKey) == "secret123")
                {
                    EndDialog(hDlg, IDOK);
                }
                else
                {
                    MessageBox(hDlg, "Access denied. Please try again.", "Authentication Failed", MB_OK | MB_ICONWARNING);
                }
            }
            else
            {
                EndDialog(hDlg, IDCANCEL);
            }
            return (INT_PTR)TRUE;
        }
        break;
    }
    return (INT_PTR)FALSE;
}

