// Custom typemap for converting Python list to QList<T>
%typemap(in) QList<$1_template_type> (QList<$1_template_type> buffer) {
    if (PyList_Check($input)) {
        int length = PyList_Size($input);
        for (int index = 0; index < length; ++index) {
            PyObject* element = PyList_GetItem($input, index);
            $1_template_type item;
            if (SWIG_ConvertPtr(element, (void**)&item, $1_descriptor, 0) == -1) {
                SWIG_exception_fail(SWIG_TypeError, "Invalid type in input sequence");
            }
            buffer.append(item);
        }
        $1 = buffer;
