    }
}

// Typemap for converting QList<T> back to Python list
%typemap(out) QList<$1_template_type> {
    PyObject* result_list = PyList_New($1.count());
    for (int i = 0; i < $1.count(); ++i) {
        PyObject* obj = SWIG_NewPointerObj(SWIG_as_voidptr($1[i]), $1_descriptor, SWIG_POINTER_OWN);
        PyList_SetItem(result_list, i, obj);
    }
    $result = result_list;
}

