// Function to find the longest contiguous word sequence in a string
std::pair<int, std::string> findLongestSequence(const std::string& input) {
    // Remove all non-word and non-space characters
    std::regex pattern("[^\\w\\s]");
    std::string cleanedText = std::regex_replace(input, pattern, "");

    // Parse words into a vector
    std::istringstream stream(cleanedText);
    std::vector<std::string> tokens{std::istream_iterator<std::string>{stream},
                                    std::istream_iterator<std::string>{}};

    int bestLength = 0;
    std::string bestSequence;

    // Check all possible contiguous subsequences
    for (size_t start = 0; start < tokens.size(); ++start) {
        for (size_t end = start; end < tokens.size(); ++end) {
            int sequenceLength = end - start + 1;
            if (sequenceLength > bestLength) {
                bestLength = sequenceLength;
                bestSequence.clear();
                for (size_t idx = start; idx <= end; ++idx) {
                    bestSequence += tokens[idx] + " ";
                }
            }
        }
    }

    return {bestLength, bestSequence};
}

int main() {
    std::string sampleText = "This is a sample sentence, with commas, and other punctuation!";
    auto [resultLength, resultChain] = findLongestSequence(sampleText);
    std::cout << resultLength << ": " << resultChain << std::endl;
    return 0;
}

