// Structure to hold precomputed division parameters
struct DivisionParams {
    uint64_t multiplier;
    int shiftBits;
};

DivisionParams calculateDivisionConstants(uint64_t divisor) {
    if (divisor == 0) {
        throw std::invalid_argument("Divisor must be non-zero");
    }

    uint64_t threshold = (uint64_t)1 << 32;
    uint64_t currentN = threshold;
    uint64_t currentD = divisor;
    uint64_t prevQ = 0, prevR = currentN;
    uint64_t currQ = 1, currR = 0;
    uint64_t tempQ, tempR;
    int exponent = 0;

    while (prevR >= currentD) {
        tempQ = prevR / currentD;
        tempR = prevR % currentD;
        prevR = currR;
        currR = tempR;
        prevQ = currQ;
        currQ = prevQ + tempQ * currQ;
        exponent++;
    }

    uint64_t magicMultiplier = (prevQ + 1) * threshold;
    int finalShift = 32 - exponent;

    return {magicMultiplier, finalShift};
}

// Perform division using precomputed constants
uint64_t fastDivide(uint64_t dividend, const DivisionParams& params) {
    uint64_t quotient = (dividend * params.multiplier) >> params.shiftBits;
    return quotient;
}

int main() {
    uint64_t divisorValue = 7; // Test divisor
    DivisionParams dp = calculateDivisionConstants(divisorValue);

    uint64_t valueA = 100;
    uint64_t valueB = 200;
    uint64_t valueC = 300;

    uint64_t outputA = fastDivide(valueA, dp);
    uint64_t outputB = fastDivide(valueB, dp);
    uint64_t outputC = fastDivide(valueC, dp);

    std::cout << "Result of " << valueA << " / " << divisorValue << " = " << outputA << std::endl;
    std::cout << "Result of " << valueB << " / " << divisorValue << " = " << outputB << std::endl;
    std::cout << "Result of " << valueC << " / " << divisorValue << " = " << outputC << std::endl;

    return 0;
}

