// Custom thread class for executing Python code in background
class WorkerThread : public QThread {
    Q_OBJECT

public:
    WorkerThread(QObject *parent = nullptr) : QThread(parent) {}

signals:
    void outputReady(const QString &output);

protected:
    void run() override {
        Py_Initialize();
        PyRun_SimpleString("import sys");
        PyRun_SimpleString("sys.path.append('./')");

        PyObject *module = PyImport_ImportModule("your_module");
        if (module != NULL) {
            PyObject *func = PyObject_GetAttrString(module, "your_function");
            if (func && PyCallable_Check(func)) {
                PyObject *args = PyTuple_New(1);
                PyObject *value = PyUnicode_FromString("your_argument");
                PyTuple_SetItem(args, 0, value);

                PyObject *result = PyObject_CallObject(func, args);
                if (result != NULL) {
                    const char *resStr = PyUnicode_AsUTF8(result);
                    QMetaObject::invokeMethod(this, [this, resStr]() {
                        emit outputReady(QString(resStr));
                    }, Qt::QueuedConnection);
                }

                Py_DECREF(args);
                Py_DECREF(func);
            }
            Py_DECREF(module);
        }

        Py_Finalize();
    }
};

// Main application window with UI elements
class ApplicationWindow : public QWidget {
    Q_OBJECT

public:
    ApplicationWindow(QWidget *parent = nullptr) : QWidget(parent) {
        QVBoxLayout *mainLayout = new QVBoxLayout(this);

        outputDisplay = new QTextEdit(this);
        inputField = new QLineEdit(this);
        executeButton = new QPushButton("Execute Script", this);

        mainLayout->addWidget(outputDisplay);
        mainLayout->addWidget(inputField);
        mainLayout->addWidget(executeButton);

        connect(executeButton, &QPushButton::clicked, this, &ApplicationWindow::executeScript);
    }

private slots:
    void executeScript() {
        worker = new WorkerThread(this);
        connect(worker, &WorkerThread::outputReady, this, &ApplicationWindow::handleOutput);

        // Temporarily disable user inputs during execution
        inputField->setEnabled(false);
        executeButton->setEnabled(false);

        worker->start();
    }

    void handleOutput(const QString &output) {
        outputDisplay->append(output);

        // Re-enable controls after completion
        inputField->setEnabled(true);
        executeButton->setEnabled(true);

        // Clean up the worker thread
        worker->deleteLater();
    }

private:
    QTextEdit *outputDisplay;
    QLineEdit *inputField;
    QPushButton *executeButton;
    WorkerThread *worker;
};

int main(int argc, char *argv[]) {
    QApplication app(argc, argv);

    ApplicationWindow window;
    window.show();

    return app.exec();
}

