// Compute the median of a vector of doubles
double computeMedian(vector<double>& values) {
    int length = values.size();
    // Sort the vector in ascending order
    sort(values.begin(), values.end());

    if (length % 2 == 0) {
        return (values[length / 2 - 1] + values[length / 2]) / 2.0;
    } else {
        return values[length / 2];
    }
}

// Compute the mode (most frequent value) of a vector of doubles
double computeMode(vector<double>& values) {
    unordered_map<double, int> countMap;
    for (double val : values) {
        countMap[val]++;
    }

    double result = values[0];
    int highestFrequency = 0;
    for (const auto& entry : countMap) {
        if (entry.second > highestFrequency) {
            highestFrequency = entry.second;
            result = entry.first;
        }
    }

    return result;
}

int main() {
    vector<double> data = {1.5, 3.0, 4.5, 2.5, 5.0};

    double medianValue = computeMedian(data);
    cout << "Median is: " << medianValue << endl;

    double modeValue = computeMode(data);
    cout << "Mode is: " << modeValue << endl;

    return 0;
}

