ICLRRuntimeHost* runtimeHost = nullptr;
ICLRRuntimeInfo* runtimeInfo = nullptr;

HRESULT InitializeManagedRuntime()
{
    HRESULT status = S_OK;

    // Define the CLR version to initialize
    const wchar_t* clrVersion = L"v4.0.30319";

    // Create an instance of the CLR metadata host
    status = CLRCreateInstance(CLSID_CLRMetaHost, IID_ICLRRuntimeInfo, (LPVOID*)&runtimeInfo);
    if (FAILED(status))
    {
        return status;
    }

    // Verify that the requested runtime can be loaded
    BOOL isLoadable = FALSE;
    status = runtimeInfo->IsLoadable(&isLoadable);
    if (FAILED(status) || !isLoadable)
    {
        runtimeInfo->Release();
        return status;
    }

    // Obtain the runtime host interface
    status = runtimeInfo->GetInterface(CLSID_CLRRuntimeHost, IID_ICLRRuntimeHost, (LPVOID*)&runtimeHost);
    if (FAILED(status))
    {
        runtimeInfo->Release();
        return status;
    }

    // Start the Common Language Runtime
    status = runtimeHost->Start();
    if (FAILED(status))
    {
        runtimeHost->Release();
        runtimeInfo->Release();
        return status;
    }

    return S_OK;
}

void CleanupManagedRuntime()
{
    if (runtimeHost)
    {
        runtimeHost->Stop();
        runtimeHost->Release();
    }
    if (runtimeInfo)
    {
        runtimeInfo->Release();
    }
}

