__inline__ __device__ uint32_t per_byte_bit_left_rotate(uint32_t input, uint8_t shift) {
    uint32_t output = 0;
    uint32_t mask = (1 << shift) - 1;

    for (int index = 0; index < 4; ++index) {
        uint8_t byte_val = (input >> (8 * index)) & 0xFF;
