// Vector structure template for fixed-size arrays
template<typename T, int Size> struct array_vector {
  explicit array_vector(const T* input_data) {
    for (int idx = 0; idx < Size; ++idx) { elements[idx] = input_data[idx]; }
  }
  T elements[Size];
};

// Function to create a 2D vector from a scalar
array_vector<double, 2> generate_2d_vector(double value) {
  double temp[] = {value, value};
  return array_vector<double, 2>{temp};
}

// Pybind11 type caster for our custom vector type
namespace pybind11 { namespace detail {
  template <typename T, int Dim> struct type_caster<array_vector<T, Dim>>
  {
  private:
    using _arrayVecTN = array_vector<T, Dim>;

  public:
    PYBIND11_TYPE_CASTER(_arrayVecTN, _("array_vector<T, Dim>"));

    bool load(py::handle source, bool allow_conversion)
    {
      if (!allow_conversion && !py::array_t<T>::check_(source)) { return false; }
      auto buffer = py::array_t<T>::ensure(source);
      if (!buffer || buffer.ndim() != 1 || buffer.size() != Dim) { return false; }
      value = _arrayVecTN{buffer.data()};
      return true;
    }

    static py::handle cast(const _arrayVecTN& source,
        py::return_value_policy policy, py::handle parent)
    {
      py::array_t<T> arr({Dim});
      for (auto index = 0; index < Dim; ++index) { arr.mutable_at(index) = source.elements[index]; }
      return arr.release();
    }
  };
}}

