#include <array>
#include <iostream>

void shift_bits_left(std::array<unsigned long long, 30>& data, unsigned int shift_amount) {
    if (shift_amount == 0) return;

    const unsigned int bits_per_word = 64;
    unsigned int word_shifts = shift_amount / bits_per_word;
    unsigned int bit_shift = shift_amount % bits_per_word;

    if (word_shifts >= data.size()) {
        std::fill(data.begin(), data.end(), 0);
        return;
    }

    // Move words to the left
    for (int idx = data.size() - 1; idx >= static_cast<int>(word_shifts); --idx) {
        data[idx] = data[idx - word_shifts];
    }
    std::fill(data.begin(), data.begin() + word_shifts, 0);

    // Process remaining bit shifts
    if (bit_shift > 0) {
        unsigned long long overflow = 0;
        for (int idx = data.size() - 1; idx >= 0; --idx) {
            unsigned long long shifted = data[idx] << bit_shift;
            data[idx] = shifted | overflow;
            overflow = data[idx - 1] >> (bits_per_word - bit_shift);
        }
    }
}

void shift_bits_right(std::array<unsigned long long, 30>& data, unsigned int shift_amount) {
    if (shift_amount == 0) return;

    const unsigned int bits_per_word = 64;
    unsigned int word_shifts = shift_amount / bits_per_word;
    unsigned int bit_shift = shift_amount % bits_per_word;

    if (word_shifts >= data.size()) {
        std::fill(data.begin(), data.end(), 0);
        return;
    }

    // Move words to the right
    for (int idx = 0; idx < static_cast<int>(data.size()) - static_cast<int>(word_shifts); ++idx) {
        data[idx] = data[idx + word_shifts];
    }
    std::fill(data.begin() + data.size() - word_shifts, data.end(), 0);

    // Process remaining bit shifts
    if (bit_shift > 0) {
        unsigned long long underflow = 0;
        for (int idx = 0; idx < static_cast<int>(data.size()); ++idx) {
            unsigned long long shifted = data[idx] >> bit_shift;
            data[idx] = shifted | underflow;
            underflow = data[idx + 1] << (bits_per_word - bit_shift);
        }
    }
}

int main() {
    std::array<unsigned long long, 30> buffer = { /* Initialize with some values */ };

    // Demonstrate left shifting
    shift_bits_left(buffer, 7);
    // shift_bits_right(buffer, 7);

    for (const auto& element : buffer) {
        std::cout << element << " ";
    }
    std::cout << std::endl;

    return 0;
}

