        if (funcPtr != NULL) {
            dynamicLinkSuccess = TRUE;
            char buffer[] = "test";
            char *ptr = buffer;
            char **addr = &ptr;

            int retValue = funcPtr(addr);
            if (retValue == 0) {
                std::cout << "Success: " << *addr << std::endl;
            } else {
