// Extract words from input text using regex pattern matching
std::vector<std::string> extractTokens(const std::string& input) {
    std::vector<std::string> tokens;
    std::regex token_pattern(R"(\b\w+\b)");
    auto start_iter = std::sregex_iterator(input.begin(), input.end(), token_pattern);
    auto end_iter = std::sregex_iterator();

    for (auto iter = start_iter; iter != end_iter; ++iter) {
        tokens.push_back((*iter).str());
    }
    return tokens;
}

// Construct adjacency list representation of word relationships
std::unordered_map<std::string, std::vector<std::string>> createWordGraph(const std::vector<std::string>& tokenList) {
    std::unordered_map<std::string, std::vector<std::string>> adjacencyMap;

    for (const auto& token : tokenList) {
        for (size_t pos = 1; pos < token.length(); ++pos) {
            std::string prefix = token.substr(0, pos);
            if (std::find(tokenList.begin(), tokenList.end(), prefix) != tokenList.end()) {
                adjacencyMap[prefix].push_back(token);
            }
        }
    }
    return adjacencyMap;
}

// Compute longest chain length using depth-first search with memoization
int computeMaxChainLength(const std::unordered_map<std::string, std::vector<std::string>>& adjMap, 
                         const std::unordered_set<std::string>& tokenSet) {
    std::unordered_map<std::string, int> cache;

    for (const auto& token : tokenSet) {
        explorePath(token, adjMap, cache);
    }

    int maxLen = 0;
    for (const auto& item : cache) {
        maxLen = std::max(maxLen, item.second);
    }
    return maxLen;
}

// Recursive DFS with memoization to find maximum path length from a node
int explorePath(const std::string& node, 
               const std::unordered_map<std::string, std::vector<std::string>>& adjMap,
               std::unordered_map<std::string, int>& cache) {
    if (cache.find(node) == cache.end()) {
        int bestPath = 1;

        for (const auto& adjacentNode : adjMap.at(node)) {
            bestPath = std::max(bestPath, 1 + explorePath(adjacentNode, adjMap, cache));
        }
        cache[node] = bestPath;
    }
    return cache[node];
}

int main() {
    std::string sampleText = "Hello world this is a test of word chains.";
    std::vector<std::string> tokens = extractTokens(sampleText);
    std::unordered_set<std::string> uniqueTokens(tokens.begin(), tokens.end());
    std::unordered_map<std::string, std::vector<std::string>> graphStructure = createWordGraph(tokens);

    std::cout << computeMaxChainLength(graphStructure, uniqueTokens) << std::endl;
    return 0;
}

