extern "C" {
    EMSCRIPTEN_KEEPALIVE
    int word_iterate(const char* input, int length) {
        UErrorCode error = U_ZERO_ERROR;
        UChar* unicodeStr = new UChar[length / 2 + 1];
        u_strFromUTF8(unicodeStr, length / 2 + 1, nullptr, input, length, &error);
        if (U_FAILURE(error)) {
            delete[] unicodeStr;
            return -1;
        }

        BreakIterator* iterator = BreakIterator::createWordInstance(Locale::getDefault(), error);
        if (U_FAILURE(error)) {
            delete[] unicodeStr;
            return -1;
        }

        iterator->setText(unicodeStr, length / 2, error);
        if (U_FAILURE(error)) {
            delete[] unicodeStr;
            delete iterator;
            return -1;
        }

        int32_t begin = iterator->first();
        int32_t finish = iterator->next();

        while (finish != BreakIterator::DONE) {
            // Extract the current word segment
            UChar* segment = new UChar[finish - begin + 1];
            u_strncpy(segment, unicodeStr + begin, finish - begin, &error);
            segment[finish - begin] = 0;

            // Convert to UTF-8 for JavaScript
            int utf8Len = u_strToUTF8(nullptr, 0, nullptr, segment, -1, &error) + 1;
            char* utf8Segment = new char[utf8Len];
            u_strToUTF8(utf8Segment, utf8Len, nullptr, segment, -1, &error);

            EM_ASM({
                console.log(UTF8ToString($0));
            }, utf8Segment);

            delete[] segment;
            delete[] utf8Segment;

            begin = finish;
            finish = iterator->next();
        }

        delete[] unicodeStr;
        delete iterator;
        return 0;
    }
}

