enum class TokenType {
    INT, FLOAT, IDENTIFIER, ASSIGN, PLUS, MINUS, MUL, DIV, LPAREN, RPAREN, SEMICOLON, EOF_TOKEN,
    IF, WHILE, FUNCTION, COMMA, LBRACE, RBRACE, ERROR
};

struct TokenData {
    TokenType kind;
    std::string literal;
    int row;
    int col;
};

class Scanner {
public:
    Scanner(const std::string& source) : text(source), index(0), currentLine(1), currentColumn(1) {}

    TokenData getNextToken();

private:
    std::string text;
    size_t index;
    int currentLine;
    int currentColumn;

    char peekChar();
    void moveNext();
    void ignoreWhitespace();
    TokenData parseNumber();
    TokenData parseName();
    TokenData checkReservedWord(const std::string& tokenText);
};

char Scanner::peekChar() {
    return index < text.length() ? text[index] : '\0';
}

void Scanner::moveNext() {
    if (peekChar() == '\n') {
        currentLine++;
        currentColumn = 1;
    } else {
        currentColumn++;
    }
    index++;
}

void Scanner::ignoreWhitespace() {
    while (std::isspace(peekChar())) {
        moveNext();
    }
}

TokenData Scanner::parseNumber() {
    std::string numStr;
    while (std::isdigit(peekChar()) || peekChar() == '.') {
        numStr += peekChar();
        moveNext();
    }
    if (numStr.find('.') != std::string::npos) {
        return {TokenType::FLOAT, numStr, currentLine, currentColumn};
    } else {
        return {TokenType::INT, numStr, currentLine, currentColumn};
    }
}

TokenData Scanner::parseName() {
    std::string nameStr;
    while (std::isalnum(peekChar()) || peekChar() == '_') {
        nameStr += peekChar();
        moveNext();
    }
    return checkReservedWord(nameStr);
}

TokenData Scanner::checkReservedWord(const std::string& word) {
    static const std::unordered_map<std::string, TokenType> reserved = {
        {"if", TokenType::IF},
        {"while", TokenType::WHILE},
        {"function", TokenType::FUNCTION}
    };

    auto iter = reserved.find(word);
    if (iter != reserved.end()) {
        return {iter->second, word, currentLine, currentColumn};
    }
    return {TokenType::IDENTIFIER, word, currentLine, currentColumn};
}

TokenData Scanner::getNextToken() {
    ignoreWhitespace();

    if (index >= text.length()) {
        return {TokenType::EOF_TOKEN, "", currentLine, currentColumn};
    }

    char ch = peekChar();
    if (std::isdigit(ch)) {
        return parseNumber();
    }

    if (std::isalpha(ch) || ch == '_') {
        return parseName();
    }

    moveNext();
    switch (ch) {
        case '+': return {TokenType::PLUS, "+", currentLine, currentColumn};
        case '-': return {TokenType::MINUS, "-", currentLine, currentColumn};
        case '*': return {TokenType::MUL, "*", currentLine, currentColumn};
        case '/': return {TokenType::DIV, "/", currentLine, currentColumn};
        case '(': return {TokenType::LPAREN, "(", currentLine, currentColumn};
        case ')': return {TokenType::RPAREN, ")", currentLine, currentColumn};
        case ';': return {TokenType::SEMICOLON, ";", currentLine, currentColumn};
        case ',': return {TokenType::COMMA, ",", currentLine, currentColumn};
        case '{': return {TokenType::LBRACE, "{", currentLine, currentColumn};
        case '}': return {TokenType::RBRACE, "}", currentLine, currentColumn};
        default: return {TokenType::ERROR, std::string(1, ch), currentLine, currentColumn};
    }
}

#include <iostream>
#include <stack>
#include <string>
#include <cctype>
