int getPrecedence(char op) {
    if (op == '+' || op == '-') return 1;
    if (op == '*' || op == '/') return 2;
    return 0;
}

bool isOperator(char c) {
    return c == '+' || c == '-' || c == '*' || c == '/';
}

bool isVariableOrNumber(char c) {
    return std::isalpha(c) || std::isdigit(c);
}

std::string convertInfixToPostfix(const std::string& infixExpr) {
    std::stack<char> operatorStack;
    std::string resultPostfix;
    for (char currentChar : infixExpr) {
        if (isVariableOrNumber(currentChar)) {
            resultPostfix += currentChar;
        } else if (currentChar == '(') {
            operatorStack.push(currentChar);
        } else if (currentChar == ')') {
            while (!operatorStack.empty() && operatorStack.top() != '(') {
                resultPostfix += operatorStack.top();
                operatorStack.pop();
            }
            operatorStack.pop();  // Remove '(' from stack
        } else if (isOperator(currentChar)) {
            while (!operatorStack.empty() && getPrecedence(currentChar) <= getPrecedence(operatorStack.top())) {
                resultPostfix += operatorStack.top();
                operatorStack.pop();
            }
            operatorStack.push(currentChar);
        }
    }
    while (!operatorStack.empty()) {
        resultPostfix += operatorStack.top();
        operatorStack.pop();
    }
    return resultPostfix;
}

#include <Python.h>
