// Alternative in-memory module storage using std::map instead of unordered_map
std::map<std::string, std::string> cached_modules;

// Custom module loader with modified function name and variable names
extern "C" PyObject* load_module_from_memory(PyObject* self, PyObject* args) {
    PyObject* module_name;
    if (!PyArg_ParseTuple(args, "O", &module_name)) {
        return nullptr;
    }

    const char* mod_name = PyUnicode_AsUTF8(module_name);
    if (mod_name == nullptr) {
        return nullptr;
    }

    auto search = cached_modules.find(mod_name);
    if (search == cached_modules.end()) {
        PyErr_Format(PyExc_ImportError, "Module '%s' not available in memory", mod_name);
        return nullptr;
    }

    const std::string& source_code = search->second;
    PyObject* new_module = PyModule_New(mod_name);
    if (new_module == nullptr) {
        return nullptr;
    }

    if (PyRun_String(source_code.c_str(), Py_file_input, new_module->ob_dict, new_module->ob_dict) == nullptr) {
        Py_DECREF(new_module);
        return nullptr;
    }

    return new_module;
}

// Function to register the custom loader with different naming
extern "C" void install_custom_importer() {
    PyObject* sys_meta_path = PySys_GetObject("meta_path");
    if (sys_meta_path == nullptr) {
        return;
    }

    PyObject* importer_obj = PyCFunction_NewEx(&PyCFunctionDef{
        (char*)"load_module_from_memory",
        (PyCFunction)load_module_from_memory,
        nullptr,
        nullptr
    }, nullptr);

    if (importer_obj != nullptr) {
        PyList_Insert(sys_meta_path, 0, importer_obj);
        Py_DECREF(importer_obj);
    }
}

// Example usage with modified structure and comments
int main() {
    Py_Initialize();

    // Insert a sample module into memory
    cached_modules["sample_lib"] = R"(
def greet():
    return "Greetings from sample_lib!"
)";

    // Set up our custom import mechanism
    install_custom_importer();

    // Attempt to import our in-memory module
    PyObject* imported_mod = PyImport_ImportModule("sample_lib");
    if (imported_mod == nullptr) {
        PyErr_Print();
        return 1;
    }

    // Retrieve and call a function from the module
    PyObject* greet_func = PyObject_GetAttrString(imported_mod, "greet");
    if (greet_func == nullptr) {
        PyErr_Print();
        return 1;
    }

    PyObject* output = PyObject_CallObject(greet_func, nullptr);
    if (output == nullptr) {
        PyErr_Print();
        return 1;
    }

    const char* msg = PyUnicode_AsUTF8(output);
    if (msg == nullptr) {
        return 1;
    }

    std::cout << "Output: " << msg << std::endl;

    Py_DECREF(imported_mod);
    Py_DECREF(greet_func);
    Py_DECREF(output);

    Py_Finalize();
    return 0;
}

#include <iostream>
#include <vector>
#include <cmath>

// Compute mean squared error for linear hypothesis
double calculate_error(const std::vector<double>& inputs, const std::vector<double>& outputs, double intercept, double slope) {
    int n = inputs.size();
    double error_sum = 0.0;
    for (int idx = 0; idx < n; ++idx) {
        double predicted = intercept + slope * inputs[idx];
        error_sum += std::pow(predicted - outputs[idx], 2);
    }
    return error_sum / (2.0 * n);
}

// Perform gradient descent optimization
void optimize_parameters(const std::vector<double>& inputs, const std::vector<double>& outputs, 
                        double& intercept, double& slope, double learning_rate, int max_epochs) {
    int n = inputs.size();
    for (int epoch = 0; epoch < max_epochs; ++epoch) {
        double delta_intercept = 0.0;
        double delta_slope = 0.0;

        for (int idx = 0; idx < n; ++idx) {
            double prediction = intercept + slope * inputs[idx];
            double error = prediction - outputs[idx];
            delta_intercept += error;
            delta_slope += error * inputs[idx];
        }

        intercept -= learning_rate * delta_intercept / n;
        slope -= learning_rate * delta_slope / n;

        // Track progress by computing current cost
        double current_error = calculate_error(inputs, outputs, intercept, slope);
        std::cout << "Epoch " << epoch << " - Error: " << current_error << std::endl;
    }
}

int main() {
    std::vector<double> feature_values = {1, 2, 3, 4, 5};
    std::vector<double> target_values = {2, 4, 5, 4, 5};

    double intercept_init = 0.0;
    double slope_init = 0.0;
    double learning_rate = 0.01;
    int training_steps = 1000;

    optimize_parameters(feature_values, target_values, intercept_init, slope_init, 
                       learning_rate, training_steps);

    std::cout << "Optimized intercept: " << intercept_init 
              << ", slope: " << slope_init << std::endl;

    return 0;
}

