class CFileDropHandler : public IDropTarget
{
public:
    STDMETHODIMP QueryInterface(REFIID riid, void** ppvObject)
    {
        if (riid == IID_IUnknown || riid == IID_IDropTarget)
        {
            *ppvObject = this;
            AddRef();
            return S_OK;
        }
        *ppvObject = NULL;
        return E_NOINTERFACE;
    }

    STDMETHODIMP_(ULONG) AddRef()
    {
        return InterlockedIncrement(&m_refCount);
    }

    STDMETHODIMP_(ULONG) Release()
    {
        ULONG refCount = InterlockedDecrement(&m_refCount);
        if (refCount == 0)
        {
            delete this;
        }
        return refCount;
    }

    STDMETHODIMP DragEnter(IDataObject* pDataObj, DWORD grfKeyState, POINTL pt, DWORD* pdwEffect)
    {
        FORMATETC format = { CF_HDROP, NULL, DVASPECT_CONTENT, -1, TYMED_HGLOBAL };
        STGMEDIUM medium = { 0 };
        if (SUCCEEDED(pDataObj->GetData(&format, &medium)))
        {
            *pdwEffect = DROPEFFECT_COPY;
        }
        else
        {
            *pdwEffect = DROPEFFECT_NONE;
        }
        return S_OK;
    }

    STDMETHODIMP DragOver(DWORD grfKeyState, POINTL pt, DWORD* pdwEffect)
    {
        // Process drag over event
        return S_OK;
    }

    STDMETHODIMP DragLeave()
    {
        // Process drag leave event
        return S_OK;
    }

    STDMETHODIMP Drop(IDataObject* pDataObj, DWORD grfKeyState, POINTL pt, DWORD* pdwEffect)
    {
        FORMATETC format = { CF_HDROP, NULL, DVASPECT_CONTENT, -1, TYMED_HGLOBAL };
        STGMEDIUM medium = { 0 };
        if (SUCCEEDED(pDataObj->GetData(&format, &medium)))
        {
            HDROP hDropHandle = (HDROP)medium.hGlobal;
            UINT fileCount = DragQueryFile(hDropHandle, 0xFFFFFFFF, NULL, 0);
            for (UINT index = 0; index < fileCount; index++)
            {
                TCHAR filePath[MAX_PATH];
                DragQueryFile(hDropHandle, index, filePath, MAX_PATH);
                MessageBox(NULL, filePath, L"Received File", MB_OK);
            }
            ReleaseStgMedium(&medium);
            *pdwEffect = DROPEFFECT_COPY;
        }
        else
        {
            *pdwEffect = DROPEFFECT_NONE;
        }
        return S_OK;
    }

private:
    ULONG m_refCount;
};

LRESULT CALLBACK WindowProcedure(HWND hwnd, UINT message, WPARAM wParam, LPARAM lParam)
{
    switch (message)
    {
    case WM_DESTROY:
        PostQuitMessage(0);
        return 0;
    }
    return DefWindowProc(hwnd, message, wParam, lParam);
}

int WINAPI WinMain(HINSTANCE hInstance, HINSTANCE hPrevInstance, LPSTR lpCommandLine, int nShowCmd)
{
    WNDCLASS windowClass = { 0 };
    windowClass.lpfnWndProc = WindowProcedure;
    windowClass.hInstance = hInstance;
    windowClass.lpszClassName = L"FileDropApplication";
    RegisterClass(&windowClass);

    HWND mainWnd = CreateWindow(windowClass.lpszClassName, L"Windows Drag and Drop Demo", WS_OVERLAPPEDWINDOW, 
                                CW_USEDEFAULT, CW_USEDEFAULT, 800, 600, NULL, NULL, hInstance, NULL);
    ShowWindow(mainWnd, nShowCmd);

    CFileDropHandler* pDropHandler = new CFileDropHandler();
    RegisterDragDrop(mainWnd, pDropHandler);

    MSG messageLoop = { 0 };
    while (GetMessage(&messageLoop, NULL, 0, 0))
    {
        TranslateMessage(&messageLoop);
        DispatchMessage(&messageLoop);
    }

    RevokeDragDrop(mainWnd);
    delete pDropHandler;

    return 0;
}

