// Display the first n terms of the Fibonacci sequence
void showFibonacci(int count) {
    if (count <= 0) {
        cout << "Please enter a positive integer." << endl;
        return;
    }

    long long prev = 0, curr = 1, nextTerm;

    for (int index = 1; index <= count; ++index) {
        if (index == 1) {
            cout << prev << " ";
            continue;
        }
        if (index == 2) {
            cout << curr << " ";
            continue;
        }
        nextTerm = prev + curr;
        prev = curr;
        curr = nextTerm;
        cout << nextTerm << " ";
    }
    cout << endl;
}

int main() {
    int terms;
    cout << "Enter the number of terms: ";
    cin >> terms;

    showFibonacci(terms);

    return 0;
}

