Java_com_my_package_name_MyNativeClass_processImage(JNIEnv* env, jobject /* obj */, jbyteArray inputBytes) {
    jbyte* inputPtr = env->GetByteArrayElements(inputBytes, nullptr);
    int inputLength = env->GetArrayLength(inputBytes);

    std::vector<unsigned char> buffer(inputPtr, inputPtr + inputLength);
    cv::Mat originalImage = cv::imdecode(buffer, cv::IMREAD_COLOR);

    if (originalImage.empty()) {
        env->ReleaseByteArrayElements(inputBytes, inputPtr, 0);
        return nullptr;
    }

    // Perform edge detection using Canny algorithm
    cv::Mat edgeMap;
    cv::Canny(originalImage, edgeMap, 100, 200);

    std::vector<unsigned char> encodedData;
    cv::imencode(".png", edgeMap, encodedData);

    jbyteArray outputBytes = env->NewByteArray(encodedData.size());
    env->SetByteArrayRegion(outputBytes, 0, encodedData.size(), 
                            reinterpret_cast<const jbyte*>(encodedData.data()));

    env->ReleaseByteArrayElements(inputBytes, inputPtr, 0);

    return outputBytes;
}

