namespace bacc = boost::accumulators;

int main()
{
    bacc::accumulator_set<double, bacc::stats<bacc::tag::count,
                                              bacc::tag::mean,
                                              bacc::tag::variance>> accumulator;

    double last_value = NAN;
    for (double current_value : { 1, 1, 2, 1, 3, 2, 3, 4, 6, 3, 2, 1 })
    {
        const double ratio = (current_value - last_value) / last_value;

        accumulator(std::isnan(ratio) ? 0 : ratio);

        last_value = current_value;
    }

    std::size_t sample_count = bacc::count(accumulator);
    double unbiased_variance = sample_count > 1 ? bacc::variance(accumulator) * sample_count / (sample_count - 1) : 0;

    std::cout << std::setprecision(16)
              << "number of elements: " << sample_count << '\n'
              << "average:            " << bacc::mean(accumulator) << '\n'
              << "corrected variance: " << unbiased_variance << '\n';

    return 0;
}

