// Determine whether array X is contained within array Y
bool containsArray(const int X[], const int Y[], int lenX, int lenY) {
    std::unordered_set<int> container(Y, Y + lenY);
    for (int idx = 0; idx < lenX; ++idx) {
        if (container.find(X[idx]) == container.end()) {
            return false;
        }
    }
    return true;
}

// Identify the longest shared contiguous subsequence between X and Y
std::vector<int> longestSharedSubsequence(const int X[], const int Y[], int lenX, int lenY) {
    std::vector<std::vector<int>> memo(lenX + 1, std::vector<int>(lenY + 1, 0));
    int maxLen = 0;
    int endPos = -1;

    // Populate the DP matrix
    for (int row = 1; row <= lenX; ++row) {
        for (int col = 1; col <= lenY; ++col) {
            if (X[row - 1] == Y[col - 1]) {
                memo[row][col] = memo[row - 1][col - 1] + 1;
                if (memo[row][col] > maxLen) {
                    maxLen = memo[row][col];
                    endPos = row - 1;
                }
            }
        }
    }

    // Reconstruct the longest common subsequence
    std::vector<int> output;
    if (maxLen > 0) {
        for (int pos = endPos - maxLen + 1; pos <= endPos; ++pos) {
            output.push_back(X[pos]);
        }
    }
    return output;
}

int main() {
    int X[] = {1, 4, 3, 7, 9};
    int Y[] = {2, 5, 4, 1, 8, 3};
    int lenX = sizeof(X) / sizeof(X[0]);
    int lenY = sizeof(Y) / sizeof(Y[0]);

    bool containment = containsArray(X, Y, lenX, lenY);
    std::cout << "containsArray: " << (containment ? "True" : "False") << std::endl;

    std::vector<int> longestSeq = longestSharedSubsequence(X, Y, lenX, lenY);
    std::cout << "longestSharedSubsequence: [";
    for (size_t k = 0; k < longestSeq.size(); ++k) {
        std::cout << longestSeq[k];
        if (k < longestSeq.size() - 1) std::cout << ", ";
    }
    std::cout << "]" << std::endl;

    return 0;
}

#include <atomic>
#include <type_traits>

// Define a 128-bit atomic type using a union of two 64-bit atomic types
union Atomic128Value {
    struct {
        std::atomic<uint64_t> lower;
        std::atomic<uint64_t> upper;
    };
    struct {
        uint64_t low_part;
        uint64_t high_part;
    };

    Atomic128Value() : lower(0), upper(0) {}

    Atomic128Value(uint64_t low_val, uint64_t high_val) : low_part(low_val), high_part(high_val) {}

    Atomic128Value(__uint128_t value) : lower(static_cast<uint64_t>(value)), upper(static_cast<uint64_t>(value >> 64)) {}

    operator __uint128_t() const {
        return (static_cast<__uint128_t>(upper.load(std::memory_order_relaxed)) << 64) | 
               static_cast<__uint128_t>(lower.load(std::memory_order_relaxed));
    }

    void store(__uint128_t value, std::memory_order order = std::memory_order_relaxed) {
        upper.store(static_cast<uint64_t>(value >> 64), order);
        lower.store(static_cast<uint64_t>(value), order);
    }

    __uint128_t load(std::memory_order order = std::memory_order_relaxed) const {
        return (static_cast<__uint128_t>(upper.load(order)) << 64) | 
               static_cast<__uint128_t>(lower.load(order));
    }

    bool compare_exchange_weak(__uint128_t& expected, __uint128_t desired, 
                               std::memory_order success_order, std::memory_order failure_order) {
        uint64_t exp_high = static_cast<uint64_t>(expected >> 64);
        uint64_t des_high = static_cast<uint64_t>(desired >> 64);
        bool res = upper.compare_exchange_weak(exp_high, des_high, success_order, failure_order);
        if (res) {
            uint64_t exp_low = static_cast<uint64_t>(expected);
            uint64_t des_low = static_cast<uint64_t>(desired);
            res = lower.compare_exchange_weak(exp_low, des_low, success_order, failure_order);
            if (!res) {
                upper.store(exp_high, failure_order);
            }
        }
        expected = (static_cast<__uint128_t>(exp_high) << 64) | static_cast<uint64_t>(exp_low);
        return res;
    }
};

// Define a 128-bit integer type alias
using uint128_type = __uint128_t;

int main() {
    Atomic128Value atomVal(0x123456789ABCDEF0, 0x0FEDCBA987654321);
    uint128_type current_val = atomVal.load();
    uint128_type new_val = 0x0DEADBEEF0123456789ABCDEF0;
    bool exchanged = atomVal.compare_exchange_weak(current_val, new_val);
    if (exchanged) {
        // The swap operation succeeded
    } else {
        // The swap failed; current_val now holds the actual stored value
    }
    return 0;
}

