class TreeNode {
public:
    virtual ~TreeNode() {}
    virtual double compute() const = 0;
};

class Constant : public TreeNode {
private:
    double data;
public:
    Constant(double num) : data(num) {}
    double compute() const override { return data; }
};

class OperationNode : public TreeNode {
private:
    TreeNode* operand1;
    TreeNode* operand2;
    char symbol;
public:
    OperationNode(TreeNode* op1, char symb, TreeNode* op2) : operand1(op1), symbol(symb), operand2(op2) {}
    ~OperationNode() {
        delete operand1;
        delete operand2;
    }
    double compute() const override {
        double first = operand1->compute();
        double second = operand2->compute();
        switch (symbol) {
            case '+': return first + second;
            case '-': return first - second;
            case '*': return first * second;
            case '/': return first / second;
            default: throw std::runtime_error("Invalid operator encountered");
        }
    }
};

