// Compare two strings using SSE instructions for 16-byte blocks
bool compare_strings_simd(const char* str_a, const char* str_b, size_t len) {
    for (size_t idx = 0; idx < len; idx += 16) {
        __m128i block1 = _mm_loadu_si128(reinterpret_cast<const __m128i*>(str_a + idx));
        __m128i block2 = _mm_loadu_si128(reinterpret_cast<const __m128i*>(str_b + idx));
        if (!_mm_cmpeq_epi8(block1, block2)) {
            return false;
        }
    }
    return true;
}

