#include <vector>
#include <stdexcept>

class MinPriorityQueue {
public:
    MinPriorityQueue() = default;

    // Add a new element to the priority queue
    void add(int val) {
        data.push_back(val);
        bubbleUp(data.size() - 1);
    }

    // Remove and return the smallest element from the priority queue
    int removeMin() {
        if (data.empty()) {
            throw std::runtime_error("Priority queue is empty");
        }

        int minVal = data[0];
        data[0] = data.back();
        data.pop_back();
        bubbleDown(0);

        return minVal;
    }

    // Get the smallest element without removing it
    int peek() const {
        if (data.empty()) {
            throw std::runtime_error("Priority queue is empty");
        }
        return data[0];
    }

    // Check if the priority queue is empty
    bool empty() const {
        return data.empty();
    }

    // Get the number of elements in the priority queue
    size_t count() const {
        return data.size();
    }

private:
    std::vector<int> data;

    // Move the element at index pos upward until heap property is restored
    void bubbleUp(int pos) {
        while (pos > 0) {
            int parentIndex = (pos - 1) / 2;
            if (data[pos] < data[parentIndex]) {
                std::swap(data[pos], data[parentIndex]);
                pos = parentIndex;
            } else {
                break;
            }
        }
    }

    // Move the element at index pos downward until heap property is restored
    void bubbleDown(int pos) {
        int n = data.size();
        while (2 * pos + 1 < n) {
            int leftChild = 2 * pos + 1;
            int rightChild = 2 * pos + 2;
            int minIndex = pos;

            if (leftChild < n && data[leftChild] < data[minIndex]) {
                minIndex = leftChild;
            }

            if (rightChild < n && data[rightChild] < data[minIndex]) {
                minIndex = rightChild;
            }

            if (minIndex != pos) {
                std::swap(data[pos], data[minIndex]);
                pos = minIndex;
            } else {
                break;
            }
        }
    }
};

// Demonstration of the priority queue functionality
int main() {
    MinPriorityQueue pq;
    pq.add(3);
    pq.add(2);
    pq.add(15);
    pq.add(5);
    pq.add(4);
    pq.add(45);

    while (!pq.empty()) {
        std::cout << pq.removeMin() << " ";
    }

    return 0;
}

