#include <vector>
#include <string>

// Helper function to recursively print the LCS using direction table b
void displayCommonSubsequence(const std::string& str1, const std::string& str2, int len1, int len2, std::vector<std::vector<int>>& dir) {
    if (len1 == 0 || len2 == 0) return;

    if (dir[len1][len2] == 1) {  // 1 means characters matched at this position
        displayCommonSubsequence(str1, str2, len1 - 1, len2 - 1, dir);
        std::cout << str1[len1 - 1];
    } else if (dir[len1][len2] == 2) {  // 2 means we came from top cell
        displayCommonSubsequence(str1, str2, len1 - 1, len2, dir);
    } else {  // 3 means we came from left cell
        displayCommonSubsequence(str1, str2, len1, len2 - 1, dir);
    }
}

std::string computeLCS(const std::string& firstStr, const std::string& secondStr) {
    int length1 = firstStr.size();
    int length2 = secondStr.size();

    // DP table for lengths
    std::vector<std::vector<int>> dp(length1 + 1, std::vector<int>(length2 + 1, 0));
    // Direction table: 1=diagonal, 2=up, 3=left
    std::vector<std::vector<int>> direction(length1 + 1, std::vector<int>(length2 + 1, 0));

    // Fill the DP tables
    for (int row = 1; row <= length1; ++row) {
        for (int col = 1; col <= length2; ++col) {
            if (firstStr[row - 1] == secondStr[col - 1]) {
                dp[row][col] = dp[row - 1][col - 1] + 1;
                direction[row][col] = 1;  // Diagonal move (match)
            } else if (dp[row - 1][col] >= dp[row][col - 1]) {
                dp[row][col] = dp[row - 1][col];
                direction[row][col] = 2;  // Up move
            } else {
                dp[row][col] = dp[row][col - 1];
                direction[row][col] = 3;  // Left move
            }
        }
    }

    std::cout << "Longest Common Subsequence: ";
    displayCommonSubsequence(firstStr, secondStr, length1, length2, direction);
    std::cout << std::endl;

    return firstStr;  // Returning first string as placeholder
}

int main() {
    std::string sequence1 = "ABCBDAB";
    std::string sequence2 = "BDCAB";
    computeLCS(sequence1, sequence2);
    return 0;
}

#include <iostream>
#include <stdexcept>

template <typename T>
class DynamicArray {
private:
    T* elements;
    size_t current_size;
    size_t max_capacity;

    // Internal method to expand storage
    void expandStorage(size_t new_capacity) {
        T* fresh_data = new T[new_capacity];
        for (size_t idx = 0; idx < current_size; ++idx) {
            fresh_data[idx] = elements[idx];
        }
        delete[] elements;
        elements = fresh_data;
        max_capacity = new_capacity;
    }

public:
    // Default constructor
    DynamicArray() : elements(nullptr), current_size(0), max_capacity(0) {}

    // Destructor
    ~DynamicArray() {
        delete[] elements;
    }

    // Copy constructor
    DynamicArray(const DynamicArray& source) : current_size(source.current_size), max_capacity(source.max_capacity) {
        elements = new T[max_capacity];
        for (size_t idx = 0; idx < current_size; ++idx) {
            elements[idx] = source.elements[idx];
        }
    }

    // Copy assignment operator
    DynamicArray& operator=(const DynamicArray& source) {
        if (this != &source) {
            delete[] elements;
            current_size = source.current_size;
            max_capacity = source.max_capacity;
            elements = new T[max_capacity];
            for (size_t idx = 0; idx < current_size; ++idx) {
                elements[idx] = source.elements[idx];
            }
        }
        return *this;
    }

    // Move constructor
    DynamicArray(DynamicArray&& source) noexcept : elements(source.elements), current_size(source.current_size), max_capacity(source.max_capacity) {
        source.elements = nullptr;
        source.current_size = 0;
        source.max_capacity = 0;
    }

    // Move assignment operator
    DynamicArray& operator=(DynamicArray&& source) noexcept {
        if (this != &source) {
            delete[] elements;
            elements = source.elements;
            current_size = source.current_size;
            max_capacity = source.max_capacity;
            source.elements = nullptr;
            source.current_size = 0;
            source.max_capacity = 0;
        }
        return *this;
    }

    // Access operators
    T& operator[](size_t position) {
        return elements[position];
    }

    const T& operator[](size_t position) const {
        return elements[position];
    }

    T& getAt(size_t position) {
        if (position >= current_size) {
            throw std::out_of_range("Position out of bounds");
        }
        return elements[position];
    }

    const T& getAt(size_t position) const {
        if (position >= current_size) {
            throw std::out_of_range("Position out of bounds");
        }
        return elements[position];
    }

    T& firstElement() {
        return elements[0];
    }

    const T& firstElement() const {
        return elements[0];
    }

    T& lastElement() {
        return elements[current_size - 1];
    }

    const T& lastElement() const {
        return elements[current_size - 1];
    }

    // Size and capacity information
    size_t length() const {
        return current_size;
    }

    size_t storageSize() const {
        return max_capacity;
    }

    bool isEmpty() const {
        return current_size == 0;
    }

    // Modify array size
    void adjustSize(size_t new_length) {
        if (new_length > max_capacity) {
            expandStorage(new_length);
        }
        current_size = new_length;
    }

    void append(const T& item) {
        if (current_size == max_capacity) {
            if (max_capacity == 0) {
                expandStorage(1);
            } else {
                expandStorage(max_capacity * 2);
            }
        }
        elements[current_size++] = item;
    }

    // Iterator support
    T* start() {
        return elements;
    }

    const T* start() const {
        return elements;
    }

    T* finish() {
        return elements + current_size;
    }

    const T* finish() const {
        return elements + current_size;
    }
};

