#include <iostream>

// Template function to perform vector addition with conditional assembly block
template<bool UseExtraAdd>
void perform_vector_calc()
{
    float result_arr[4] = {2.0f, 2.0f, 2.0f, 2.0f};
    float input_arr[4] = {0.5f, 1.5f, 2.5f, 3.5f};
    float * result_ptr = result_arr;
    float * input_ptr  = input_arr;

    asm volatile (
        "vld1.32    {q2}, [%[inp]]  \n"
        "vld1.32    {q3}, [%[res]]  \n"
        "vadd.f32   q2, q2, q3      \n"
        "vadd.f32   q2, q2, q3      \n"
        : [inp] "+r" (input_ptr),
          [res] "+r" (result_ptr)
        :
        : "q2", "q3", "memory"
    );

    if constexpr (UseExtraAdd) {
        asm volatile (
            "vadd.f32   q2, q2, q3      \n"
            : [inp] "+r" (input_ptr),
              [res] "+r" (result_ptr)
            :
            : "q2", "q3", "memory"
        );
    }

    asm volatile (
        "vst1.32    {q2}, [%[res]]  \n"
        : [inp] "+r" (input_ptr),
          [res] "+r" (result_ptr)
        :
        : "q2", "q3", "memory"
    );

    for (int idx = 0; idx < 4; ++idx)
    {
        std::printf("%.6f, ", result_arr[idx]);
    }
}

// Explicit template instantiations
template void perform_vector_calc<true>();
template void perform_vector_calc<false>();

int main()
{
    perform_vector_calc<true>();
    std::cout << std::endl;
    perform_vector_calc<false>();
    return 0;
}

#include <opencv2/opencv.hpp>
#include <iostream>

int main() {
    // Read the source image in grayscale mode
    cv::Mat sourceImg = cv::imread("source.jpg", cv::IMREAD_GRAYSCALE);

    // Set up source and destination points for affine transformation
    cv::Point2f srcPoints[3];
    cv::Point2f dstPoints[3];

    srcPoints[0] = cv::Point2f(0, 0);
    srcPoints[1] = cv::Point2f(sourceImg.cols - 1, 0);
    srcPoints[2] = cv::Point2f(0, sourceImg.rows - 1);

    dstPoints[0] = cv::Point2f(0, 0);
    dstPoints[1] = cv::Point2f(sourceImg.cols * 2 - 1, 0);
    dstPoints[2] = cv::Point2f(0, sourceImg.rows * 2 - 1);

    // Compute the affine transform matrix
    cv::Mat transformMatrix = cv::getAffineTransform(srcPoints, dstPoints);

    // Prepare the output image with doubled dimensions
    cv::Mat resultImg;
    cv::warpAffine(sourceImg, resultImg, transformMatrix, cv::Size(sourceImg.cols * 2, sourceImg.rows * 2), cv::INTER_CUBIC);

    // Write the transformed image to file
    cv::imwrite("result.png", resultImg);

    return 0;
}

