// Compute the Levenshtein edit distance between two strings
int editDistance(const std::string &source, const std::string &target) {
    int len1 = source.length();
    int len2 = target.length();
    std::vector<std::vector<int>> matrix(len1 + 1, std::vector<int>(len2 + 1, 0));

    // Initialize first column
    for (int i = 0; i <= len1; ++i) {
        matrix[i][0] = i;
    }

    // Initialize first row
    for (int j = 0; j <= len2; ++j) {
        matrix[0][j] = j;
    }

    // Fill the matrix
    for (int i = 1; i <= len1; ++i) {
        for (int j = 1; j <= len2; ++j) {
            int matchCost = (source[i - 1] == target[j - 1]) ? 0 : 1;
            matrix[i][j] = std::min({
                matrix[i - 1][j] + 1,      // deletion
                matrix[i][j - 1] + 1,      // insertion
                matrix[i - 1][j - 1] + matchCost  // substitution
            });
        }
    }
    return matrix[len1][len2];
}

