class Car {
public:
    std::string manufacturer;
    std::string modelName;
    int productionYear;
    std::string paintColor;
    double cost;

    Car(std::string manufacturer, std::string modelName, int productionYear, std::string paintColor, double cost)
        : manufacturer(manufacturer), modelName(modelName), productionYear(productionYear), paintColor(paintColor), cost(cost) {}

    bool operator==(const Car& other) const {
        return manufacturer == other.manufacturer && 
               modelName == other.modelName && 
               productionYear == other.productionYear && 
               paintColor == other.paintColor && 
               cost == other.cost;
    }

    bool operator<(const Car& other) const {
        if (productionYear != other.productionYear) 
            return productionYear < other.productionYear;
        return cost > other.cost; // Note: cost is in descending order
    }
};

