#include <Wire.h>
#include <esp_now.h>
#include <WiFi.h>

#define I2C_ADDR 0x3C
#define MAX_BUFFER 512
#define CHANNEL_NUM 0

typedef struct __attribute__((packed)) {
  uint8_t payload[MAX_BUFFER];
  size_t length;
} FrameData;

QueueHandle_t dataQueue;

void handleIncomingData(const uint8_t* macAddr, const uint8_t* incomingData, int dataLen) {
  FrameData frame;
  memcpy(&frame, incomingData, sizeof(frame));
  xQueueSendFromISR(dataQueue, &frame, NULL);
}

void initSystem() {
  Serial.begin(115200);

  // Configure I2C interface for RP2040 interaction
  Wire.begin();

  // Setup ESP-NOW protocol
  if (esp_now_init() != ESP_OK) {
    Serial.println("ESP-NOW setup error");
    return;
  }

  // Assign callback handler for received packets
  esp_now_register_recv_cb(handleIncomingData);

  // Create queue for screen data management
  dataQueue = xQueueCreate(1, sizeof(FrameData));

  // Configure remote peer device
  esp_now_peer_info_t peerInfo;
  memcpy(peerInfo.peer_addr, (uint8_t[]){0xCA, 0xFE, 0xBA, 0xBE, 0xFA, 0xCE}, 6); // Update with second ESP32's MAC
  peerInfo.channel = CHANNEL_NUM;
  peerInfo.encrypt = false;

  if (esp_now_add_peer(&peerInfo) != ESP_OK) {
    Serial.println("Unable to register ESP-NOW peer");
    return;
  }

  Serial.println("Initialization finished");
}

void runMainLoop() {
  FrameData frameBuffer;

  // Acquire screen content from RP2040 via I2C
  Wire.beginTransmission(I2C_ADDR);
  Wire.write(0x00); // Starting register address
  Wire.endTransmission(false);

  Wire.requestFrom(I2C_ADDR, MAX_BUFFER);
  frameBuffer.length = Wire.readBytes(frameBuffer.payload, MAX_BUFFER);

  // Forward screen data through ESP-NOW to the secondary ESP32
  if (xQueueSend(dataQueue, &frameBuffer, portMAX_DELAY) != pdTRUE) {
    Serial.println("Buffer transmission failed");
  }

  delay(1000); // Control update frequency
}

#include <iostream>

// Structure definition for complex numbers
typedef struct {
    float real;
    float imag;
} dcmplx;

// Function to perform complex convolution operation
dcmplx ComplexConv(int length, dcmplx *source, dcmplx *buffer)
{
    dcmplx result;

    result.real = 0.0f;
    result.imag = 0.0f;

    asm volatile (
        "movs r4, #0\n\t"
        ".calc:\n\t"
        "vldr s16, [%[src], #4]\n\t"
        "vldr s17, [%[src]]\n\t"
        "vneg.f32 s16, s16\n\t"
        "vldr s18, [%[buf], #4]\n\t"
        "vldr s19, [%[buf]]\n\t"
        "vmul.f32 s20, s18, s17\n\t"
        "vmul.f32 s18, s16, s18\n\t"
        "adds %[src], #8\n\t"
        "vmla.f32 s20, s16, s19\n\t"
        "vnmls.f32 s18, s19, s17\n\t"
        "adds %[buf], #8\n\t"
        "vadd.f32 s2, s2, s20\n\t"
        "vadd.f32 s3, s3, s18\n\t"
        "adds r4, r4, #1\n\t"
        "cmp r4, %[len]\n\t"
        "bne .calc\n\t"
        : "=t"(result.real), "=t"(result.imag)
        : [src]"r"(source), [buf]"r"(buffer), [len]"r"(length)
        : "s2", "s3", "s16", "s17", "s18", "s19", "s20", "r4", "cc", "memory"
    );

    return result;
}

