#include "curl_gethostname.h"

/*
 * Curl_gethostname() is a wrapper around gethostname() which allows
 * overriding the host name that the function would normally return.
 * This capability is used by the test suite to verify exact matching
 * of NTLM authentication, which exercises libcurl's MD4 and DES code
 * as well as by the SMTP module when a hostname is not provided.
 *
 * For libcurl debug enabled builds host name overriding takes place
 * when environment variable CURL_GETHOSTNAME is set, using the value
 * held by the variable to override returned host name.
 *
 * Note: The function always returns the un-qualified hostname rather
 * than being provider dependent.
 *
 * For libcurl shared library release builds the test suite preloads
 * another shared library named libhostname using the LD_PRELOAD
 * mechanism which intercepts, and might override, the gethostname()
 * function call. In this case a given platform must support the
 * LD_PRELOAD mechanism and additionally have environment variable
 * CURL_GETHOSTNAME set in order to override the returned host name.
 *
 * For libcurl static library release builds no overriding takes place.
 */
int Curl_gethostname(char *buffer, GETHOSTNAME_TYPE_ARG2 buffer_size) {
#ifndef HAVE_GETHOSTNAME
  /* Allow compilation and return failure when unavailable */
  (void) buffer;
  (void) buffer_size;
  return -1;
#else
  int result;
  char* dot_ptr;
#ifdef DEBUGBUILD
  /* Override host name when environment variable CURL_GETHOSTNAME is set */
  const char *custom_hostname = getenv("CURL_GETHOSTNAME");
  if(custom_hostname) {
    strncpy(buffer, custom_hostname, buffer_size);
    result = 0;
  }
  else {
    buffer[0] = '\0';
    result = gethostname(buffer, buffer_size);
  }
#else /* DEBUGBUILD */
  /* The call to system's gethostname() might get intercepted by the
     libhostname library when libcurl is built as a non-debug shared
     library when running the test suite. */
  buffer[0] = '\0';
  result = gethostname(buffer, buffer_size);
#endif
  buffer[buffer_size - 1] = '\0';
  if(result)
    return result;
  /* Truncate domain, leave only machine name */
  dot_ptr = strchr(buffer, '.');
  if(dot_ptr)
    *dot_ptr = '\0';
  return 0;
#endif
}

#include "autolink/transport/dispatcher/intra_dispatcher.hpp"
#include <memory>
