#include "autolink/transport/common/identity.hpp"
#include "gtest/gtest.h"

namespace autolink {
namespace transport {

TEST(DispatcherTest, on_message) {
  auto dispatcher = IntraDispatcher::Instance();

  std::vector<std::shared_ptr<proto::Chatter>> chatter_messages;
  std::vector<std::shared_ptr<message::RawMessage>> raw_messages;

  // Prepare messages
  auto msg1 = std::make_shared<proto::Chatter>();
  msg1->set_content("hello");

  auto msg2 = std::make_shared<proto::Chatter>();
  msg2->set_content("raw payload");

  std::string serialized_data;
  msg2->SerializeToString(&serialized_data);
  auto raw_msg = std::make_shared<message::RawMessage>(serialized_data);

  // Define callbacks
  auto chatter_handler = [&chatter_messages](const std::shared_ptr<proto::Chatter>& msg, const MessageInfo&) {
    AINFO << "chatter handler invoked";
    chatter_messages.push_back(msg);
  };

  auto raw_handler = [&raw_messages](const std::shared_ptr<message::RawMessage>& msg, const MessageInfo&) {
    AINFO << "raw handler invoked";
    raw_messages.push_back(msg);
  };

  MessageInfo info;
  const std::string topic_name = "sensor_data";
  const uint64_t topic_hash = common::Hash(topic_name);

  // Setup role attributes
  proto::RoleAttributes local_role_a;
  local_role_a.set_channel_name(topic_name);
  local_role_a.set_channel_id(topic_hash);
  local_role_a.set_id(Identity().HashValue());

  proto::RoleAttributes local_role_b = local_role_a;
  local_role_b.set_id(Identity().HashValue());

  proto::RoleAttributes mismatched_role;
  mismatched_role.set_channel_name("other_topic");
  mismatched_role.set_channel_id(common::Hash("other_topic"));

  proto::RoleAttributes remote_role_a = local_role_a;
  Identity id_a;
  remote_role_a.set_id(id_a.HashValue());

  proto::RoleAttributes remote_role_b = local_role_b;
  Identity id_b;
  remote_role_b.set_id(id_b.HashValue());

  // Register listeners
  dispatcher->AddListener<proto::Chatter>(local_role_a, chatter_handler);
  dispatcher->AddListener<message::RawMessage>(local_role_b, raw_handler);
  dispatcher->AddListener<proto::Chatter>(local_role_a, remote_role_a, chatter_handler);
  dispatcher->AddListener<message::RawMessage>(local_role_b, remote_role_a, raw_handler);

  // First dispatch: only self listeners should trigger
  dispatcher->OnMessage<proto::Chatter>(topic_hash, msg1, info);
  EXPECT_EQ(1u, chatter_messages.size());
  EXPECT_EQ(1u, raw_messages.size());

  // Second dispatch: with sender identity matching remote_role_a
  info.set_sender_id(id_a);
  dispatcher->OnMessage<message::RawMessage>(topic_hash, raw_msg, info);
  EXPECT_EQ(3u, chatter_messages.size());
  EXPECT_EQ(3u, raw_messages.size());

  // Third dispatch: new sender identity (no opposite match)
  Identity id_c;
  info.set_sender_id(id_c);
  dispatcher->OnMessage<proto::Chatter>(topic_hash, msg1, info);
  EXPECT_EQ(4u, chatter_messages.size());
  EXPECT_EQ(4u, raw_messages.size());

  // Remove handlers
  dispatcher->RemoveListener<proto::Chatter>(mismatched_role);
  dispatcher->RemoveListener<proto::Chatter>(mismatched_role, remote_role_b);
  dispatcher->RemoveListener<proto::Chatter>(local_role_a);
  dispatcher->RemoveListener<proto::Chatter>(local_role_b);
  dispatcher->RemoveListener<proto::Chatter>(local_role_a, remote_role_a);
  dispatcher->RemoveListener<proto::Chatter>(local_role_b, remote_role_b);

  // Clear and verify no further callbacks
  chatter_messages.clear();
  raw_messages.clear();

  MessageInfo info2;
  dispatcher->OnMessage<proto::Chatter>(topic_hash, msg1, info2);
  EXPECT_EQ(0u, chatter_messages.size());
  EXPECT_EQ(0u, raw_messages.size());

  info.set_sender_id(id_a);
  dispatcher->OnMessage<proto::Chatter>(topic_hash, msg1, info);
  EXPECT_EQ(0u, chatter_messages.size());
  EXPECT_EQ(0u, raw_messages.size());
}

