#include <iostream>
#include <vector>
#include <algorithm>
#include <iterator>
using namespace std;

// Global variables for problem data
int size_arr;
vector<int> values;

// Function to calculate LIS (or LDS via value inversion) on available elements
// Returns the indices of the subsequence
vector<int> find_subseq(const vector<bool>& active, bool is_desc) {
    // tails_vals[i] stores the smallest tail of all increasing subsequences of length i+1 found so far.
    // tails_idxs[i] stores the index in values of that tail value.
    vector<int> min_tails;
    vector<int> tail_indices;
    vector<int> prev_index(size_arr, -1);

    for (int idx = 0; idx < size_arr; ++idx) {
        if (active[idx]) continue;

        int current_val = values[idx];
        if (is_desc) current_val = -current_val; // Transform problem to LIS

        // Find the first element in min_tails >= current_val
        auto pos = lower_bound(min_tails.begin(), min_tails.end(), current_val);
        int seq_length = distance(min_tails.begin(), pos);

        if (pos == min_tails.end()) {
            min_tails.push_back(current_val);
            tail_indices.push_back(idx);
        } else {
            *pos = current_val;
            tail_indices[seq_length] = idx;
        }

        // If we are extending a sequence of length 'seq_length', the previous element is at tail_indices[seq_length-1]
        if (seq_length > 0) {
            prev_index[idx] = tail_indices[seq_length - 1];
        }
    }

    // Reconstruct the path
    vector<int> result_indices;
    if (tail_indices.empty()) return result_indices;

    int current = tail_indices.back();
    while (current != -1) {
        result_indices.push_back(current);
        current = prev_index[current];
    }
    reverse(result_indices.begin(), result_indices.end());
    return result_indices;
}

int main() {
    // Fast I/O
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    if (!(cin >> size_arr)) return 0;
    values.resize(size_arr);
    for (int i = 0; i < size_arr; ++i) {
        cin >> values[i];
    }

    // We need to extract 2 Increasing and 2 Decreasing subsequences.
    // The order of extraction matters for the greedy approach.
    // We try all distinct permutations of the types order.
    // 0: Increasing, 1: Decreasing
    vector<int> order_types = {0, 0, 1, 1};
    sort(order_types.begin(), order_types.end());

    long long max_total_len = -1;
    vector<int> final_assignment(size_arr, 3); // Default to d (index 3)

    do {
        vector<bool> used(size_arr, false);
        vector<int> temp_owner(size_arr, -1);
        long long temp_len = 0;

        int inc_count = 0;
        int dec_count = 0;

        for (int type : order_types) {
            int assignment_target = -1;
            // Map the occurrence of type to specific output set
            // 1st Inc -> a (0), 2nd Inc -> c (2)
            // 1st Dec -> b (1), 2nd Dec -> d (3)
            if (type == 0) {
                assignment_target = (inc_count == 0) ? 0 : 2;
                inc_count++;
            } else {
                assignment_target = (dec_count == 0) ? 1 : 3;
                dec_count++;
            }

            vector<int> indices = find_subseq(used, type == 1);
            temp_len += indices.size();

            for (int idx : indices) {
                used[idx] = true;
                temp_owner[idx] = assignment_target;
            }
        }

        if (temp_len > max_total_len) {
            max_total_len = temp_len;
            for (int i = 0; i < size_arr; ++i) {
                if (temp_owner[i] == -1) final_assignment[i] = 3;
                else final_assignment[i] = temp_owner[i];
            }
        }

    } while (next_permutation(order_types.begin(), order_types.end()));

    // Construct the output subsequences based on final_assignment
    vector<int> group_a, group_b, group_c, group_d;
    // Reserve memory to avoid reallocations
    group_a.reserve(size_arr); 
    group_b.reserve(size_arr); 
    group_c.reserve(size_arr); 
    group_d.reserve(size_arr);

    for (int i = 0; i < size_arr; ++i) {
        if (final_assignment[i] == 0) group_a.push_back(values[i]);
        else if (final_assignment[i] == 1) group_b.push_back(values[i]);
        else if (final_assignment[i] == 2) group_c.push_back(values[i]);
        else group_d.push_back(values[i]);
    }

    // Print lengths
    cout << group_a.size() << " " << group_b.size() << " " << group_c.size() << " " << group_d.size() << "\n";

    // Print sequences
    auto print_sequence = [](const vector<int>& seq) {
        for (int i = 0; i < (int)seq.size(); ++i) {
            cout << seq[i] << (i == (int)seq.size() - 1 ? "" : " ");
        }
        cout << "\n";
    };

    print_sequence(group_a);
    print_sequence(group_b);
    print_sequence(group_c);
    print_sequence(group_d);
    return 0;
}

