const FName IStageDataProviderModule::ModuleName = TEXT("StageDataProvider");
DEFINE_LOG_CATEGORY(LogStageDataProvider);

FStageDataProviderModule::FStageDataProviderModule()
	: StageData(MakeUnique<FStageDataProvider>())
	, FramePerf(MakeUnique<FFramePerformanceProvider>())
	, GenlockMonitor(MakeUnique<FGenlockWatchdog>())
	, TimecodeMonitor(MakeUnique<FTimecodeProviderWatchdog>())
#if WITH_EDITOR
	, TakeRecorderState(MakeUnique<FTakeRecorderStateProvider>())
#endif //WITH_EDITOR
{
}

void FStageDataProviderModule::StartupModule()
{
	// Delay initialization until all modules are loaded; dependencies on other settings may still be loading
	FCoreDelegates::OnPostEngineInit.AddRaw(this, &FStageDataProviderModule::HandlePostEngineInit);
	// Register cleanup delegate to safely shut down before process exit
	FCoreDelegates::OnPreExit.AddRaw(this, &FStageDataProviderModule::HandlePreExit);

#if !(UE_BUILD_SHIPPING || UE_BUILD_TEST)
	StartCmd = MakeUnique<FAutoConsoleCommand>(TEXT("StageMonitor.DataProvider.Start")
											, TEXT("Begin Stage data collection")
											, FConsoleCommandDelegate::CreateRaw(this, &FStageDataProviderModule::EnableDataProvider));
	StopCmd = MakeUnique<FAutoConsoleCommand>(TEXT("StageMonitor.DataProvider.Stop")
											, TEXT("Halt Stage data collection")
											, FConsoleCommandDelegate::CreateRaw(this, &FStageDataProviderModule::DisableDataProvider));
#endif
}

void FStageDataProviderModule::ShutdownModule()
{
	FCoreDelegates::OnPostEngineInit.RemoveAll(this);
	FCoreDelegates::OnPreExit.RemoveAll(this);
	DisableDataProvider();
}

void FStageDataProviderModule::HandlePostEngineInit()
{
	// If role filtering is active, verify that the current roles satisfy requirements
	const UStageMonitoringSettings* Config = GetDefault<UStageMonitoringSettings>();
	if (!Config->ProviderSettings.bEnforceRoleFiltering || GetDefault<UVPSettings>()->GetAvailableRoles().HasAny(Config->ProviderSettings.AcceptedRoles))
	{
		EnableDataProvider();
	}
	else
	{
		UE_LOG(LogStageDataProvider, Log, TEXT("Unable to initialize StageDataProvider. Role filtering is enabled and our roles (%s) are not permitted (%s)")
		, *GetDefault<UVPSettings>()->GetAvailableRoles().ToStringSimple()
		, *Config->ProviderSettings.AcceptedRoles.ToStringSimple())
	}
}

void FStageDataProviderModule::HandlePreExit()
{
	DisableDataProvider();
}

void FStageDataProviderModule::EnableDataProvider()
{
	StageData->Begin();
	// Advertise the provider globally within the engine via modular features system
	IModularFeatures::Get().RegisterModularFeature(IStageDataProvider::FeatureName, StageData.Get());
}

void FStageDataProviderModule::DisableDataProvider()
{
	IModularFeatures::Get().UnregisterModularFeature(IStageDataProvider::FeatureName, StageData.Get());
	StageData->End();
}

IMPLEMENT_MODULE(FStageDataProviderModule, StageDataProvider);

