#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#include <assert.h>
#include "dds/dds.h"

// Compile-time constants for built-in topics used to detect topic and endpoint discovery
static const dds_entity_t monitored_endpoints[] = {
  DDS_BUILTIN_TOPIC_DCPSPUBLICATION,
  DDS_BUILTIN_TOPIC_DCPSSUBSCRIPTION
};

struct key_buffer {
    char buffer[36]; // Format: 8 hex + ':' + 8 hex + ':' + 8 hex + ':' + 8 hex + '\0'
};

// Convert a built-in topic key into a human-readable string representation
static char *format_key(struct key_buffer *kb, const dds_builtintopic_topic_key_t *key)
{
    (void) snprintf(kb->buffer, sizeof(kb->buffer),
                    "%02x%02x%02x%02x:%02x%02x%02x%02x:%02x%02x%02x%02x:%02x%02x%02x%02x",
                    key->d[0], key->d[1], key->d[2], key->d[3],
                    key->d[4], key->d[5], key->d[6], key->d[7],
                    key->d[8], key->d[9], key->d[10], key->d[11],
                    key->d[12], key->d[13], key->d[14], key->d[15]);
    return kb->buffer;
}

// Return a string describing the instance state
static const char *state_to_string(dds_instance_state_t state)
{
    switch (state) {
        case DDS_ALIVE_INSTANCE_STATE: return "alive";
        case DDS_NOT_ALIVE_NO_WRITERS_INSTANCE_STATE: return "no_writers";
        case DDS_NOT_ALIVE_DISPOSED_INSTANCE_STATE: return "disposed";
    }
    assert(0);
    return "";
}

// Process topic samples from the DCPSTopic built-in topic
static bool check_topics(dds_entity_t cond)
{
#define MAX_SAMPLES 10
    void *samples[MAX_SAMPLES] = { NULL };
    dds_sample_info_t infos[MAX_SAMPLES];
    int32_t count = dds_take(cond, samples, infos, MAX_SAMPLES, MAX_SAMPLES);
    bool found_app_topic = false;

    for (int32_t i = 0; i < count; i++) {
        dds_builtintopic_topic_t const * const sample = samples[i];
        struct key_buffer kb;
        printf("%s: %s", state_to_string(infos[i].instance_state), format_key(&kb, &sample->key));
        if (infos[i].valid_data) {
            printf(" %s %s", sample->topic_name, sample->type_name);
            if (strncmp(sample->topic_name, "DCPS", 4) != 0) {
                found_app_topic = true;
            }
        }
        printf("\n");
    }

    (void) dds_return_loan(cond, samples, count);
#undef MAX_SAMPLES
    return found_app_topic;
}

// Check for non-built-in endpoints (writers/readers)
static bool check_endpoints(dds_entity_t ep_conditions[])
{
    bool found_ep = false;
    for (size_t idx = 0; idx < sizeof(monitored_endpoints) / sizeof(monitored_endpoints[0]) && !found_ep; idx++) {
        void *sample_ptr = NULL;
        dds_sample_info_t info;
        int32_t n = dds_take(ep_conditions[idx], &sample_ptr, &info, 1, 1);
        if (n > 0 && info.valid_data) {
            dds_builtintopic_endpoint_t const * const sample = sample_ptr;
            if (strncmp(sample->topic_name, "DCPS", 4) != 0) {
                found_ep = true;
            }
        }
        (void) dds_return_loan(ep_conditions[idx], &sample_ptr, n);
    }
    return found_ep;
}

int main(int argc, char **argv)
{
    (void)argc;
    (void)argv;

    // Create participant
    const dds_entity_t participant = dds_create_participant(DDS_DOMAIN_DEFAULT, NULL, NULL);
    if (participant < 0) {
        fprintf(stderr, "dds_create_participant failed: %s\n", dds_strretcode(participant));
        return 1;
    }

    // Create waitset
    const dds_entity_t waitset = dds_create_waitset(participant);

    // Create reader and condition for DCPSTopic
    const dds_entity_t topic_reader = dds_create_reader(participant, DDS_BUILTIN_TOPIC_DCPSTOPIC, NULL, NULL);
    if (topic_reader < 0) {
        if (topic_reader == DDS_RETCODE_UNSUPPORTED) {
            fprintf(stderr, "Topic discovery is not included in this build. Rebuild with ENABLE_TOPIC_DISCOVERY=ON.\n");
        } else {
            fprintf(stderr, "dds_create_reader(DCPSTopic) failed: %s\n", dds_strretcode(topic_reader));
        }
        dds_delete(participant);
        return 1;
    }

    const dds_entity_t topic_cond = dds_create_readcondition(topic_reader, DDS_ANY_STATE);
    (void) dds_waitset_attach(waitset, topic_cond, 0);

    // Set up readers and conditions for monitoring publication/subscription endpoints
    dds_entity_t ep_readers[sizeof(monitored_endpoints) / sizeof(monitored_endpoints[0])];
    dds_entity_t ep_conditions[sizeof(monitored_endpoints) / sizeof(monitored_endpoints[0])];

    for (size_t idx = 0; idx < sizeof(monitored_endpoints) / sizeof(monitored_endpoints[0]); idx++) {
        ep_readers[idx] = dds_create_reader(participant, monitored_endpoints[idx], NULL, NULL);
        ep_conditions[idx] = dds_create_readcondition(ep_readers[idx], DDS_ANY_STATE);
        (void) dds_waitset_attach(waitset, ep_conditions[idx], 0);
    }

    // Monitoring variables
    bool discovered_topics = false;
    bool discovered_endpoints = false;

    // Run monitoring for 10 seconds
    const dds_time_t deadline = dds_time() + DDS_SECS(10);
    while (dds_waitset_wait_until(waitset, NULL, 0, deadline) > 0) {
        if (check_topics(topic_cond)) {
            discovered_topics = true;
        }
        if (!discovered_endpoints && check_endpoints(ep_conditions)) {
            discovered_endpoints = true;
            // Clean up endpoint monitoring resources once endpoints are found
            for (size_t idx = 0; idx < sizeof(ep_readers) / sizeof(ep_readers[0]); idx++) {
                (void) dds_delete(ep_readers[idx]);
            }
        }
    }

    // Warn if only endpoints were discovered but no topics
    if (!discovered_topics && discovered_endpoints) {
        fprintf(stderr, "No topics discovered, but remote endpoints exist. Is topic discovery enabled?\n");
    }

    dds_delete(participant);
    return 0;
}

