#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int queries;
    if (!(cin >> queries)) return 0;

    vector<unsigned long long> kValues(queries);
    for (int idx = 0; idx < queries; ++idx) {
        cin >> kValues[idx];
    }

    for (int qIdx = 0; qIdx < queries; ++qIdx) {
        unsigned long long k = kValues[qIdx]; // k >= 2

        vector<long long> sequence;
        long long minVal = -1, maxVal = 0;

        // Start with single element (F = 2)
        sequence.push_back(0);

        int highestBit = 63 - __builtin_clzll(k); // floor(log2(k))

        for (int bitPos = highestBit - 1; bitPos >= 0; --bitPos) {
            if ((k >> bitPos) & 1ULL) {
                sequence.push_back(minVal--); // +1 operation: append smallest
            }
            if (bitPos != 0) {
                sequence.push_back(++maxVal); // *2 operation: append largest
            }
        }

        int size = (int)sequence.size();
        vector<pair<long long, int>> indexedValues(size);

        for (int i = 0; i < size; ++i) {
            indexedValues[i] = {sequence[i], i};
        }

        sort(indexedValues.begin(), indexedValues.end());

        vector<int> permutation(size);
        for (int rank = 0; rank < size; ++rank) {
            permutation[indexedValues[rank].second] = rank;
        }

        cout << size << "\n";
        for (int i = 0; i < size; ++i) {
            if (i > 0) cout << ' ';
            cout << permutation[i];
        }
        cout << "\n";
    }

    return 0;
}

