#include <iostream>
#include <vector>
#include <set>
using namespace std;

// Execute a query and return the result
int performQuery(const vector<int>& queryVec) {
    cout << "?";
    for (int val : queryVec) {
        cout << " " << val;
    }
    cout << endl;

    int response;
    cin >> response;
    if (response == -1) exit(0);
    return response;
}

// Main solving function
void process() {
    int size;
    cin >> size;

    // Output fixed position k=1
    cout << "1" << endl;

    vector<int> permutation(size + 1, 0);
    vector<int> inverseMap(size + 1, 0); // inverseMap[value] = position

    // First, determine the value at position 1 using binary search with dummy element 2
    {
        int pos = 1;
        int dummyVal = 2;
        vector<int> options;

        for (int i = 1; i <= size; ++i) {
            if (i != pos) options.push_back(i);
        }

        // Remove dummy from partition candidates
        vector<int> activeOptions;
        for (int opt : options) {
            if (opt != dummyVal) activeOptions.push_back(opt);
        }

        while (!activeOptions.empty()) {
            if (activeOptions.size() == 1) {
                permutation[pos] = activeOptions[0];
                break;
            }

            int splitIndex = activeOptions.size() / 2;
            vector<int> leftPart, rightPart;

            for (int i = 0; i < splitIndex; ++i) {
                leftPart.push_back(activeOptions[i]);
            }
            for (int i = splitIndex; i < activeOptions.size(); ++i) {
                rightPart.push_back(activeOptions[i]);
            }

            // Construct base query: [pos, dummy, left, right]
            vector<int> baseQuery(size);
            int idx = 0;
            baseQuery[idx++] = pos;
            baseQuery[idx++] = dummyVal;
            for (int x : leftPart) baseQuery[idx++] = x;
            for (int x : rightPart) baseQuery[idx++] = x;

            // Construct test query: [dummy, left, pos, right]
            vector<int> testQuery(size);
            idx = 0;
            testQuery[idx++] = dummyVal;
            for (int x : leftPart) testQuery[idx++] = x;
            testQuery[idx++] = pos;
            for (int x : rightPart) testQuery[idx++] = x;

            int baseResult = performQuery(baseQuery);
            int testResult = performQuery(testQuery);
            int diff = testResult - baseResult;

            // Determine which half to keep based on known inverse mapping
            int knownPos = inverseMap[pos]; // known position of value 'pos'
            bool posInLeft = false;
            if (knownPos != 0 && knownPos != dummyVal) {
                for (int x : leftPart) {
                    if (x == knownPos) {
                        posInLeft = true;
                        break;
                    }
                }
            }

            int computedValue = diff + 1;

            if (knownPos != 0) {
                // Deterministic case
                int posTerm = (knownPos == dummyVal) ? 0 : (posInLeft ? 1 : 0);
                int targetInRight = computedValue - posTerm;

                if (targetInRight == 1) {
                    activeOptions = rightPart;
                } else {
                    activeOptions = leftPart;
                }
            } else {
                // Ambiguous case handling
                if (computedValue == 0) {
                    activeOptions = leftPart;
                } else if (computedValue == 2) {
                    activeOptions = rightPart;
                } else { // computedValue == 1
                    if (diff == 2) {
                        activeOptions = rightPart;
                    } else if (diff == -1) {
                        activeOptions = leftPart;
                    } else {
                        if (activeOptions.size() <= 2) {
                            permutation[pos] = -1; // Mark as ambiguous
                            break;
                        }
                        activeOptions = leftPart;
                    }
                }
            }
        }

        if (activeOptions.size() == 1) {
            permutation[pos] = activeOptions[0];
        } else if (permutation[pos] == 0) {
            permutation[pos] = (leftPart.size() > 0) ? leftPart[0] : 
                              (rightPart.size() > 0) ? rightPart[0] : 0;
        }

        if (permutation[pos] != -1 && permutation[pos] != 0) {
            inverseMap[permutation[pos]] = pos;
        }
    }

    // Determine remaining values by elimination
    set<int> occupied;
    for (int i = 2; i <= size; ++i) {
        if (permutation[i] != -1 && permutation[i] != 0) {
            occupied.insert(permutation[i]);
        }
    }

    // Find missing value for position 1
    for (int val = 1; val <= size; ++val) {
        if (occupied.find(val) == occupied.end()) {
            permutation[1] = val;
            break;
        }
    }
    inverseMap[permutation[1]] = 1;

    // Handle any unresolved positions
    vector<int> remainingValues;
    for (int val = 1; val <= size; ++val) {
        if (occupied.find(val) == occupied.end() && val != permutation[1]) {
            remainingValues.push_back(val);
        }
    }

    int remIdx = 0;
    for (int i = 2; i <= size; ++i) {
        if (permutation[i] == -1 || permutation[i] == 0) {
            if (remIdx < remainingValues.size()) {
                permutation[i] = remainingValues[remIdx++];
            }
        }
    }

    // Output final permutation
    cout << "!";
    for (int i = 1; i <= size; ++i) {
        cout << " " << permutation[i];
    }
    cout << endl;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int testCases;
    if (cin >> testCases) {
        while (testCases--) {
            process();
        }
    }

    return 0;
}

#include <nanobind/nanobind.h>
#include <mscclpp/fifo.hpp>

namespace nb = nanobind;
using namespace mscclpp;

// Register FIFO-related classes and methods for Python binding
void register_fifo(nb::module_& mod) {
  // Bind ProxyTrigger class with read-write access to its members
  nb::class_<ProxyTrigger>(mod, "ProxyTrigger")
      .def_rw("first_field", &ProxyTrigger::fst)
      .def_rw("second_field", &ProxyTrigger::snd);

  // Bind FifoDeviceHandle class with read-write access to device-side fields
  nb::class_<FifoDeviceHandle>(mod, "FifoDeviceHandle")
      .def_rw("trigger_array", &FifoDeviceHandle::triggers)
      .def_rw("tail_copy", &FifoDeviceHandle::tailReplica)
      .def_rw("head_index", &FifoDeviceHandle::head)
      .def_rw("capacity", &FifoDeviceHandle::size)
      .def_prop_ro("as_buffer", [](const FifoDeviceHandle& handle) -> nb::bytes {
        return nb::bytes(reinterpret_cast<const char*>(&handle), sizeof(handle));
      });

  // Bind Fifo class with constructor and various operations
  nb::class_<Fifo>(mod, "Fifo")
      .def(nb::init<int>(), nb::arg("buffer_size") = DEFAULT_FIFO_SIZE)
      .def("check_status", &Fifo::poll)
      .def("extract", &Fifo::pop)
      .def("sync_tail", &Fifo::flushTail, nb::arg("synchronize") = false)
      .def("length", &Fifo::size)
      .def("get_device_view", &Fifo::deviceHandle);
}

#include "stdafx.h"
#include "InputOutputStream.h"
#include "NbtIo.h"

// Load a compressed NBT tag from an input stream
CompoundTag *NbtIo::readCompressed(InputStream *inputStream)
{
	MemSect(26);
	// 4J - this was using a try/finally block
	DataInputStream dataIn = DataInputStream(inputStream); // 4J - was new GZIPInputStream as well
	CompoundTag *result = NbtIo::read((DataInput *)&dataIn);
	dataIn.close();
	MemSect(0);
	return result;
}

// Write a compressed NBT tag to an output stream
void NbtIo::writeCompressed(CompoundTag *tag, OutputStream *outputStream)
{
	// 4J - this was using a try/finally block
	// 4J Stu - Buffer output in 1024 byte chunks so that we can allocate properly in the save file
	BufferedOutputStream bufferedOut = BufferedOutputStream(outputStream, 1024);
	DataOutputStream dataOut = DataOutputStream(&bufferedOut); // 4J - was new GZIPOutputStream as well
	NbtIo::write(tag, &dataOut);
	dataOut.close();
}

// Decompress tags from a byte array. Doesn't free the source buffer data.
CompoundTag *NbtIo::decompress(byteArray sourceBuffer)
{
	ByteArrayInputStream bais = ByteArrayInputStream(sourceBuffer);
	// 4J - this was using a try/finally block
	DataInputStream inputStream = DataInputStream(&bais); // 4J - was new GZIPInputStream as well
	CompoundTag *result = NbtIo::read((DataInput *)&inputStream);
	bais.reset();		// This prevents the buffer referenced by the input stream from being freed when it goes out of scope
	inputStream.close();
	return result;
}

// Compress an NBT tag into a byte array
byteArray NbtIo::compress(CompoundTag *tag)
{
	// 4J - this was using a try/finally block
    ByteArrayOutputStream byteOut = ByteArrayOutputStream();
    DataOutputStream dataOut = DataOutputStream(&byteOut); // 4J - was new GZIPOutputStream as well
	NbtIo::write(tag, &dataOut);
	byteArray result(byteOut.buf.length);
	System::arraycopy(byteOut.buf, 0, &result, 0, byteOut.buf.length);
	dataOut.close();
	return result;
}

// Reads a single root tag from the input stream; ensures it's a compound tag
CompoundTag *NbtIo::read(DataInput *dis)
{
	Tag *tag = Tag::readNamedTag(dis);
	if (tag->getId() == Tag::TAG_Compound) return (CompoundTag *)tag;
	if (tag != NULL) delete tag;
	// Root tag must be a named compound tag
	return NULL;
}

// Writes a compound tag to the output stream
void NbtIo::write(CompoundTag *tag, DataOutput *dos)
{
	Tag::writeNamedTag(tag, dos);
}

