    std::vector<SummaryClient> summary_clients;
    int overall_revenue;
    int number_of_clients;
    double mean_transaction_value;
};

AnalysisOutput analyze_client_data(const std::vector<Client>& clients) {
    std::vector<Client> active_clients;
    std::copy_if(clients.begin(), clients.end(), std::back_inserter(active_clients), [](const Client& client) {
        return client.account_status == "active" && client.years_old >= 25;
    });

    std::vector<SummaryClient> client_summaries;
    std::transform(active_clients.begin(), active_clients.end(), std::back_inserter(client_summaries), [](const Client& client) {
        SummaryClient sc;
        sc.name = client.full_name;
        sc.cumulative_spending = std::accumulate(client.transaction_amounts.begin(), client.transaction_amounts.end(), 0);
        sc.years_as_member = 2026 - client.join_year;

        if (sc.cumulative_spending < 500) {
            sc.membership_level = "Bronze";
        } else if (sc.cumulative_spending < 1000) {
            sc.membership_level = "Silver";
        } else {
            sc.membership_level = "Gold";
        }

        return sc;
    });

    int total_revenue = std::accumulate(client_summaries.begin(), client_summaries.end(), 0, [](int sum, const SummaryClient& client) {
        return sum + client.cumulative_spending;
    });

    AnalysisOutput output;
    output.summary_clients = client_summaries;
    output.overall_revenue = total_revenue;
    output.number_of_clients = static_cast<int>(client_summaries.size());
    output.mean_transaction_value = output.number_of_clients > 0 
        ? static_cast<double>(total_revenue) / output.number_of_clients 
        : 0.0;

    return output;
}

int main() {
    std::vector<Client> clients = {
        {1, "Alice", 30, {200, 400, 150}, 2019, "active"},
        {2, "Bob", 22, {100, 50}, 2021, "active"},
        {3, "Charlie", 28, {500, 600}, 2020, "inactive"},
        {4, "Diana", 35, {300, 200, 100}, 2018, "active"}
    };

    auto analysis = analyze_client_data(clients);

    std::cout << "Processed Clients:\n";
    for (const auto& client : analysis.summary_clients) {
        std::cout << client.name << ", total_spent: " << client.cumulative_spending
                  << ", loyalty_years: " << client.years_as_member
                  << ", tier: " << client.membership_level << "\n";
    }

    std::cout << "Total Revenue: " << analysis.overall_revenue << "\n";
    std::cout << "User Count: " << analysis.number_of_clients << "\n";
    std::cout << "Average Spending: " << analysis.mean_transaction_value << "\n";

    return 0;
}

