int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int starting_depth;
    std::cin >> starting_depth;

    if (starting_depth == 0) {
        return 0;
    }

    int current_depth = starting_depth;
    int previous_up_color = -1;
    int exit_reached;

    while (current_depth > 0) {
        int up_color = -1;

        if (previous_up_color == -1) {
            // Initial step: determine upward direction by testing colors
            // Try color 0 first
            std::cout << "move 0" << std::endl;
            std::cin >> exit_reached;
            if (exit_reached) return 0;

            std::cout << "query" << std::endl;
            int new_depth;
            std::cin >> new_depth;

            std::cout << "move 0" << std::endl; // Return to original position
            std::cin >> exit_reached;

            if (new_depth < current_depth) {
                up_color = 0;
            } else {
                // Try color 1
                std::cout << "move 1" << std::endl;
                std::cin >> exit_reached;
                if (exit_reached) return 0;

                std::cout << "query" << std::endl;
                std::cin >> new_depth;

                std::cout << "move 1" << std::endl; // Return to original position
                std::cin >> exit_reached;

                if (new_depth < current_depth) {
                    up_color = 1;
                } else {
                    up_color = 2;
                }
            }
        } else {
            // Subsequent steps: use known down direction to test remaining colors
            int option1 = (previous_up_color + 1) % 3;
            int option2 = (previous_up_color + 2) % 3;

            // Test option1
            std::cout << "move " << option1 << std::endl;
            std::cin >> exit_reached;
            if (exit_reached) return 0;

            std::cout << "query" << std::endl;
            int new_depth;
            std::cin >> new_depth;

            std::cout << "move " << option1 << std::endl; // Return to original position
            std::cin >> exit_reached;

            if (new_depth < current_depth) {
                up_color = option1;
            } else {
                up_color = option2;
            }
        }

        // Final move for this level
        std::cout << "move " << up_color << std::endl;
        std::cin >> exit_reached;
        if (exit_reached) {
            return 0;
        }

        current_depth--;
        previous_up_color = up_color;
    }

    return 0;
}

#include "secp256k1/field_simd.hpp"
#include <cstring>

namespace secp256k1::simd {
using fast::FieldElement;

// ==============================================================================
// Scalar Fallback (always available, any platform)
// ==============================================================================
namespace detail {
void batch_field_add_scalar(FieldElement* result, const FieldElement* lhs,
                            const FieldElement* rhs, std::size_t num_elements) {
    for (std::size_t idx = 0; idx < num_elements; ++idx) {
        result[idx] = lhs[idx] + rhs[idx];
    }
}

void batch_field_sub_scalar(FieldElement* result, const FieldElement* lhs,
                            const FieldElement* rhs, std::size_t num_elements) {
    for (std::size_t idx = 0; idx < num_elements; ++idx) {
        result[idx] = lhs[idx] - rhs[idx];
    }
}

void batch_field_mul_scalar(FieldElement* result, const FieldElement* lhs,
                            const FieldElement* rhs, std::size_t num_elements) {
    for (std::size_t idx = 0; idx < num_elements; ++idx) {
        result[idx] = lhs[idx] * rhs[idx];
    }
}

void batch_field_sqr_scalar(FieldElement* result, const FieldElement* input,
                            std::size_t num_elements) {
    for (std::size_t idx = 0; idx < num_elements; ++idx) {
        result[idx] = input[idx].square();
    }
}
} // namespace detail

// ==============================================================================
// Auto-Dispatching Batch Operations
// ==============================================================================
// Current implementation: scalar-only with architecture detection.
// SIMD kernels (AVX2/AVX-512) operate on the 4xuint64 representation.
//
// For field multiplication, SIMD doesn't help much because secp256k1
// modular reduction is inherently serial (carry propagation).
// The main benefit is for add/sub which are carry-chain operations
// that can be partially parallelized, and for batch inverse
// (Montgomery's trick) which is inherently parallelizable.

void batch_field_add(FieldElement* output,
                     const FieldElement* left,
                     const FieldElement* right,
                     std::size_t length) {
    // Note: For secp256k1 field arithmetic, individual add operations
    // are already very fast (~2ns). The auto-vectorizer with -ftree-vectorize
    // + -march=native typically handles this well. Explicit SIMD intrinsics
    // would add complexity without measurable benefit for add/sub.
    detail::batch_field_add_scalar(output, left, right, length);
}

void batch_field_sub(FieldElement* output,
                     const FieldElement* left,
                     const FieldElement* right,
                     std::size_t length) {
    detail::batch_field_sub_scalar(output, left, right, length);
}

void batch_field_mul(FieldElement* output,
                     const FieldElement* left,
                     const FieldElement* right,
                     std::size_t length) {
    detail::batch_field_mul_scalar(output, left, right, length);
}

void batch_field_sqr(FieldElement* output,
                     const FieldElement* input,
                     std::size_t length) {
    detail::batch_field_sqr_scalar(output, input, length);
}

// ==============================================================================
// Batch Modular Inverse (Montgomery's Trick)
// ==============================================================================
// Computes n inversions with only 1 actual field inversion.
// Algorithm:
//   1. Compute running products: prod[i] = a[0] * a[1] * ... * a[i]
//   2. Invert the final product: inv_all = prod[n-1]^(-1)
//   3. Back-propagate: out[i] = inv_all * prod[i-1], inv_all *= a[i]
//
// Cost: 1 inversion + 3(n-1) multiplications
// vs. n inversions naively (~250x faster for n=256)

void batch_field_inv(FieldElement* output,
                     const FieldElement* input,
                     std::size_t length,
                     FieldElement* temp_buffer) {
    if (length == 0) return;
    if (length == 1) {
        output[0] = input[0].inverse();
        return;
    }

    // Use temp buffer if provided, otherwise reuse output memory
    FieldElement* running_products = temp_buffer ? temp_buffer : output;

    // Step 1: Forward pass -- compute cumulative products
    running_products[0] = input[0];
    for (std::size_t i = 1; i < length; ++i) {
        running_products[i] = running_products[i - 1] * input[i];
    }

    // Step 2: Single inversion of the last product
    auto accumulated_inverse = running_products[length - 1].inverse();

    // Step 3: Backward pass -- distribute inverse values
    for (std::size_t i = length - 1; i > 0; --i) {
        output[i] = accumulated_inverse * running_products[i - 1];
        accumulated_inverse = accumulated_inverse * input[i];
    }
    output[0] = accumulated_inverse;
}
} // namespace secp256k1::simd

