//
// TypeConverter
//
TritonGPUTypeConverter::TritonGPUTypeConverter(MLIRContext *ctx,
                                               int warpCount, int threadsPerWarp,
                                               int ctaCount)
    : context(ctx), numWarps(warpCount), threadsPerWarp(threadsPerWarp),
      numCTAs(ctaCount) {
  addConversion([](Type type) { return type; });

  // Add encoding for tensor types
  addConversion([this](RankedTensorType tensorType) -> RankedTensorType {
    // Skip if already has an encoding
    if (tensorType.getEncoding())
      return tensorType;

    ArrayRef<int64_t> shape = tensorType.getShape();
    triton::gpu::BlockedEncodingAttr layout =
        getDefaultBlockedEncoding(this->context, shape, this->numWarps,
                                  this->threadsPerWarp, this->numCTAs);
    return RankedTensorType::get(shape, tensorType.getElementType(), layout);
  });

  // Add encoding for pointer-to-tensor types
  addConversion([this](triton::PointerType ptrType) -> triton::PointerType {
    auto pointeeTensorType =
        dyn_cast<RankedTensorType>(ptrType.getPointeeType());
    if (!pointeeTensorType)
      return ptrType;

    auto updatedTensorType = convertType(pointeeTensorType);
    return triton::PointerType::get(updatedTensorType,
                                    ptrType.getAddressSpace());
  });

  //
  // Materializations
  //

  // Argument materialization: should not occur in Triton -> TritonGPU
  addArgumentMaterialization([&](OpBuilder &builder,
                                 RankedTensorType tensorType, ValueRange inputs,
                                 Location loc) -> std::optional<Value> {
    llvm_unreachable("Argument rematerialization should not happen in Triton "
                     "-> TritonGPU conversion");
    return std::nullopt;
  });

  // Source materialization: should not occur in Triton -> TritonGPU
  addSourceMaterialization([&](OpBuilder &builder, RankedTensorType tensorType,
                               ValueRange inputs,
                               Location loc) -> std::optional<Value> {
    llvm_unreachable("Source rematerialization should not happen in Triton -> "
                     "TritonGPU Conversion");
    return std::nullopt;
  });

  // Target materialization: insert ConvertLayoutOp when needed
  addTargetMaterialization([&](OpBuilder &builder, RankedTensorType tensorType,
                               ValueRange inputs, Location loc) {
    auto convOp =
        builder.create<triton::gpu::ConvertLayoutOp>(loc, tensorType, inputs);
    return std::optional<Value>(convOp.getResult());
  });
}

//
// TritonGPUConversionTarget
//
TritonGPUConversionTarget::TritonGPUConversionTarget(
    MLIRContext &mlirCtx, TritonGPUTypeConverter &typeConverter)
    : ConversionTarget(mlirCtx) {
  // Legal dialects
  addLegalDialect<triton::gpu::TritonGPUDialect>();

  // Illegal SCF ops
  addIllegalOp<scf::ExecuteRegionOp, scf::ParallelOp, scf::ReduceOp,
               scf::ReduceReturnOp>();

  // Dynamically legal dialects
  addDynamicallyLegalDialect<arith::ArithDialect, math::MathDialect,
                             triton::TritonDialect, cf::ControlFlowDialect,
                             scf::SCFDialect>([&](Operation *op) {
    bool regionsLegal = true;
    for (auto &region : op->getRegions()) {
      regionsLegal = regionsLegal && typeConverter.isLegal(&region);
    }
    return regionsLegal && typeConverter.isLegal(op);
  });

  // Special handling for DotOp layout requirements
  addDynamicallyLegalOp<triton::DotOp>([](triton::DotOp dotOp) -> bool {
    Attribute lhsEncoding =
        cast<RankedTensorType>(dotOp.getA().getType()).getEncoding();
    Attribute rhsEncoding =
        cast<RankedTensorType>(dotOp.getB().getType()).getEncoding();

    if (lhsEncoding && isa<triton::gpu::DotOperandEncodingAttr>(lhsEncoding) &&
        rhsEncoding && isa<triton::gpu::DotOperandEncodingAttr>(rhsEncoding))
      return true;

    return false;
  });
}

#include "pch.h"
#include "ast_stack.h"
#include "ims_operator.h"
#include "oper_block.h"


ast_stack::ast_stack(value v)
{
    push_back(v);
}

void ast_stack::add_branch(value v)
{
    advance(); // artificially simulate moving to the next position
    push_back(v);
    // workaround: shortly after this, an increment will occur, aligning us correctly
    --m_stack.back().v.h;
}

ast_stack& ast_stack::reset3(value v)
{
    m_stack.clear();
    push_back(v);
    return *this;
}

void ast_stack::push_back(value v)
{
    auto& nv = m_stack.emplace_back();
    nv.v = v;
    nv.e = v.h + 1;
    descend(); // immediately proceed deeper
}

void ast_stack::descend()
{
    for (;;) {

        auto el = m_stack.back(); // duplicate current element
        auto* h = el.v.h;

        let na = h->oper_args();

        if (na == 0) {
            break;
        }

        // continue descending along the leftmost branch within the current block
        el.v.h = &el.v.b->m_ops[h->u32].hdr;
        el.e = el.v.h + na;

        m_stack.emplace_back(el);
    }
}

void ast_stack::advance()
{
    auto& s = m_stack;
    auto& b = s.back();

    // immediately proceed to the next item
    if (++b.v.h == b.e) {
        s.pop_back(); // child subtree fully traversed
    } else {
        descend(); // attempt to go deeper into the next child
    }

    // note:
    // assert(m_stack.size() <= m_stack.static_capacity);
}

ast_stack::value::value(const ast_context& p)
{
    b = const_cast<oper_block*>(p.a);
    h = const_cast<ims_operator*>(&p.h);
    call_offset = p.call_offset;
}

