#include "Frustum.h"

Frustum* Frustum::instance = new Frustum();

Frustum::Frustum() {
    projectionMatrix = MemoryTracker::createFloatBuffer(16);
    modelviewMatrix = MemoryTracker::createFloatBuffer(16);
    combinedMatrix = MemoryTracker::createFloatBuffer(16);
}

Frustum::~Frustum() {
    delete projectionMatrix;
    delete modelviewMatrix;
    delete combinedMatrix;
}

FrustumData* Frustum::getInstance() {
    instance->updateFrustum();
    return instance;
}

// Normalize a plane vector to unit length
void Frustum::normalizePlane(float (**planes), int index) {
    float length = (float)sqrt(planes[index][X] * planes[index][X] +
                               planes[index][Y] * planes[index][Y] +
                               planes[index][Z] * planes[index][Z]);

    // Scale the plane coefficients by the inverse length
    planes[index][X] /= length;
    planes[index][Y] /= length;
    planes[index][Z] /= length;
    planes[index][W] /= length;
}

void Frustum::updateFrustum() {
    projectionMatrix->clear();
    modelviewMatrix->clear();
    combinedMatrix->clear();

    glGetFloat(GL_PROJECTION_MATRIX, projectionMatrix);
    glGetFloat(GL_MODELVIEW_MATRIX, modelviewMatrix);

    projectionMatrix->flip()->limit(16);
    projectionMatrix->get(&projData);
    modelviewMatrix->flip()->limit(16);
    modelviewMatrix->get(&modlData);

    // Combine modelview and projection matrices to get clipping planes
    clip[0]  = modlData[0]  * projData[0]  + modlData[1]  * projData[4]  + modlData[2]  * projData[8]  + modlData[3]  * projData[12];
    clip[1]  = modlData[0]  * projData[1]  + modlData[1]  * projData[5]  + modlData[2]  * projData[9]  + modlData[3]  * projData[13];
    clip[2]  = modlData[0]  * projData[2]  + modlData[1]  * projData[6]  + modlData[2]  * projData[10] + modlData[3]  * projData[14];
    clip[3]  = modlData[0]  * projData[3]  + modlData[1]  * projData[7]  + modlData[2]  * projData[11] + modlData[3]  * projData[15];
    clip[4]  = modlData[4]  * projData[0]  + modlData[5]  * projData[4]  + modlData[6]  * projData[8]  + modlData[7]  * projData[12];
    clip[5]  = modlData[4]  * projData[1]  + modlData[5]  * projData[5]  + modlData[6]  * projData[9]  + modlData[7]  * projData[13];
    clip[6]  = modlData[4]  * projData[2]  + modlData[5]  * projData[6]  + modlData[6]  * projData[10] + modlData[7]  * projData[14];
    clip[7]  = modlData[4]  * projData[3]  + modlData[5]  * projData[7]  + modlData[6]  * projData[11] + modlData[7]  * projData[15];
    clip[8]  = modlData[8]  * projData[0]  + modlData[9]  * projData[4]  + modlData[10] * projData[8]  + modlData[11] * projData[12];
    clip[9]  = modlData[8]  * projData[1]  + modlData[9]  * projData[5]  + modlData[10] * projData[9]  + modlData[11] * projData[13];
    clip[10] = modlData[8]  * projData[2]  + modlData[9]  * projData[6]  + modlData[10] * projData[10] + modlData[11] * projData[14];
    clip[11] = modlData[8]  * projData[3]  + modlData[9]  * projData[7]  + modlData[10] * projData[11] + modlData[11] * projData[15];
    clip[12] = modlData[12] * projData[0]  + modlData[13] * projData[4]  + modlData[14] * projData[8]  + modlData[15] * projData[12];
    clip[13] = modlData[12] * projData[1]  + modlData[13] * projData[5]  + modlData[14] * projData[9]  + modlData[15] * projData[13];
    clip[14] = modlData[12] * projData[2]  + modlData[13] * projData[6]  + modlData[14] * projData[10] + modlData[15] * projData[14];
    clip[15] = modlData[12] * projData[3]  + modlData[13] * projData[7]  + modlData[14] * projData[11] + modlData[15] * projData[15];

    // Extract frustum planes from clipping matrix
    // Right plane
    frustum[RIGHT][X] = clip[3] - clip[0];
    frustum[RIGHT][Y] = clip[7] - clip[4];
    frustum[RIGHT][Z] = clip[11] - clip[8];
    frustum[RIGHT][W] = clip[15] - clip[12];
    normalizePlane(frustum, RIGHT);

    // Left plane
    frustum[LEFT][X] = clip[3] + clip[0];
    frustum[LEFT][Y] = clip[7] + clip[4];
    frustum[LEFT][Z] = clip[11] + clip[8];
    frustum[LEFT][W] = clip[15] + clip[12];
    normalizePlane(frustum, LEFT);

    // Bottom plane
    frustum[BOTTOM][X] = clip[3] + clip[1];
    frustum[BOTTOM][Y] = clip[7] + clip[5];
    frustum[BOTTOM][Z] = clip[11] + clip[9];
    frustum[BOTTOM][W] = clip[15] + clip[13];
    normalizePlane(frustum, BOTTOM);

    // Top plane
    frustum[TOP][X] = clip[3] - clip[1];
    frustum[TOP][Y] = clip[7] - clip[5];
    frustum[TOP][Z] = clip[11] - clip[9];
    frustum[TOP][W] = clip[15] - clip[13];
    normalizePlane(frustum, TOP);

    // Back plane
    frustum[BACK][X] = clip[3] - clip[2];
    frustum[BACK][Y] = clip[7] - clip[6];
    frustum[BACK][Z] = clip[11] - clip[10];
    frustum[BACK][W] = clip[15] - clip[14];
    normalizePlane(frustum, BACK);

    // Front plane
    frustum[FRONT][X] = clip[3] + clip[2];
    frustum[FRONT][Y] = clip[7] + clip[6];
    frustum[FRONT][Z] = clip[11] + clip[10];
    frustum[FRONT][W] = clip[15] + clip[14];
    normalizePlane(frustum, FRONT);
}

#include <iostream>
#include <vector>
#include <algorithm>
#include <random>
#include <numeric>
#include <chrono>
using namespace std;

// Function to process each test scenario
void runTest() {
    int size;
    if (!(cin >> size)) return;

    // Create initial list of pen IDs from 0 to size-1
    vector<int> pens(size);
    iota(pens.begin(), pens.end(), 0);

    // Randomize the order using time-based seed
    unsigned rngSeed = chrono::system_clock::now().time_since_epoch().count();
    shuffle(pens.begin(), pens.end(), default_random_engine(rngSeed));

    // Container for confirmed working pens (those that passed at least one test)
    vector<int> confirmed;

    // Lambda function to perform a query on a specific pen ID
    auto checkPen = [&](int id) -> int {
        cout << "0 " << id << endl;
        int result;
        cin >> result;
        return result;
    };

    // Continue until only two pens remain
    while (pens.size() + confirmed.size() > 2) {
        if (pens.empty()) {
            // Only confirmed pens remain - direct comparison needed
            int first = confirmed.back(); confirmed.pop_back();
            int second = confirmed.back(); confirmed.pop_back();

            if (checkPen(first) == 0) {
                // First pen failed, keep second
                confirmed.push_back(second);
            } else {
                // First pen succeeded, test second
                if (checkPen(second) == 0) {
                    // Second failed, keep first
                    confirmed.push_back(first);
                } else {
                    // Both succeeded, keep both
                    confirmed.push_back(first);
                    confirmed.push_back(second);
                }
            }
        } else {
            // Take a candidate pen from the untested pool
            int candidate = pens.back(); pens.pop_back();

            if (confirmed.empty()) {
                // No confirmed pens yet, pair two untested pens
                int opponent = pens.back(); pens.pop_back();

                if (checkPen(candidate) == 0) {
                    // Candidate failed, opponent remains untested
                    pens.push_back(opponent);
                } else {
                    // Candidate succeeded, test opponent
                    if (checkPen(opponent) == 0) {
                        // Opponent failed, promote candidate
                        confirmed.push_back(candidate);
                    } else {
                        // Both succeeded, promote both
                        confirmed.push_back(candidate);
                        confirmed.push_back(opponent);
                    }
                }
            } else {
                // Use a confirmed pen as opponent
                int opponent = confirmed.back(); confirmed.pop_back();

                // Test candidate first (more likely to fail)
                if (checkPen(candidate) == 0) {
                    // Candidate failed, opponent remains confirmed
                    confirmed.push_back(opponent);
                } else {
                    // Candidate succeeded, test opponent
                    if (checkPen(opponent) == 0) {
                        // Opponent failed, replace with candidate
                        confirmed.push_back(candidate);
                    } else {
                        // Both succeeded, keep both
                        confirmed.push_back(candidate);
                        confirmed.push_back(opponent);
                    }
                }
            }
        }
    }

    // Collect final two pens
    vector<int> finalPens;
    finalPens.insert(finalPens.end(), pens.begin(), pens.end());
    finalPens.insert(finalPens.end(), confirmed.begin(), confirmed.end());

    // Output the answer
    cout << "1 " << finalPens[0] << " " << finalPens[1] << endl;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int testCases;
    if (cin >> testCases) {
        while (testCases--) {
            runTest();
        }
    }
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

// Graph representation using adjacency lists
vector<vector<int>> graph;
// Storage for decomposition bags (subsets of vertices)
vector<vector<int>> bags;
// Central node identifiers for each original vertex
vector<int> pivot_nodes;
// Edges in the decomposition tree
vector<pair<int, int>> decomp_connections;
// Current identifier counter for decomposition nodes
int next_id;

// Recursive function to build decomposition for subtree rooted at u
void construct(int u, int parent, int parent_bag) {
    int center = pivot_nodes[u];

    // Connect to parent bag if exists
    if (parent_bag != 0) {
        decomp_connections.push_back({center, parent_bag});
    }

    // Process each child in the tree
    for (int child : graph[u]) {
        if (child == parent) continue;

        int new_bag = next_id++;
        bags[new_bag] = {u, child};
        decomp_connections.push_back({center, new_bag});
        construct(child, u, new_bag);
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int vertex_count;
    cin >> vertex_count;

    // Initialize adjacency list with size vertex_count+1
    graph.resize(vertex_count + 1);

    // Read tree edges (from parent to child for i=2..N)
    for (int idx = 2; idx <= vertex_count; idx++) {
        int parent_vertex;
        cin >> parent_vertex;
        graph[parent_vertex].push_back(idx);
        graph[idx].push_back(parent_vertex);
    }

    // Find all leaf nodes (degree 1)
    vector<int> leaf_vertices;
    for (int node = 1; node <= vertex_count; node++) {
        if (graph[node].size() == 1) {
            leaf_vertices.push_back(node);
        }
    }

    // Sort leaves for consistent ordering
    sort(leaf_vertices.begin(), leaf_vertices.end());

    int leaf_count = leaf_vertices.size();

    // Resize storage for decomposition
    bags.resize(4 * vertex_count + 10);
    pivot_nodes.resize(vertex_count + 1);

    next_id = 1;

    // Create central/bag for each original vertex
    for (int j = 1; j <= vertex_count; j++) {
        pivot_nodes[j] = next_id++;
        bags[pivot_nodes[j]] = {j};
    }

    // Build decomposition starting from root (vertex 1)
    construct(1, -1, 0);

    // Special handling when there are at least 2 leaves
    if (leaf_count >= 2) {
        int first_leaf = leaf_vertices[0];
        int attach_point = pivot_nodes[first_leaf];

        // Create intermediate bags connecting consecutive leaves
        vector<int> intermediate_bags(leaf_count - 1);
        for (int i = 0; i < leaf_count - 1; i++) {
            int left_leaf = leaf_vertices[i];
            int right_leaf = leaf_vertices[i + 1];
            intermediate_bags[i] = next_id++;
            bags[intermediate_bags[i]] = {left_leaf, right_leaf};
        }

        // Create special bag connecting first and last leaves
        int connector_bag = next_id++;
        int start_leaf = leaf_vertices[0];
        int end_leaf = leaf_vertices[leaf_count - 1];
        bags[connector_bag] = {start_leaf, end_leaf};

        // Connect intermediate bags in sequence
        for (int i = 0; i < leaf_count - 2; i++) {
            decomp_connections.push_back({intermediate_bags[i], intermediate_bags[i + 1]});
        }

        // Connect connector bag to first intermediate bag
        decomp_connections.push_back({connector_bag, intermediate_bags[0]});
        // Connect first intermediate bag to attachment point
        decomp_connections.push_back({intermediate_bags[0], attach_point});
    }

    // Total number of decomposition nodes
    int total_bags = next_id - 1;
    cout << total_bags << '\n';

    // Output each bag's contents
    for (int i = 1; i <= total_bags; i++) {
        cout << bags[i].size();
        for (int vertex : bags[i]) {
            cout << " " << vertex;
        }
        cout << '\n';
    }

    // Output decomposition edges
    for (auto& connection : decomp_connections) {
        cout << connection.first << " " << connection.second << '\n';
    }

    return 0;
}

#include <iostream>
#include <vector>
#include <algorithm>
#include <random>
#include <chrono>
#include <cmath>
#include <climits>
using namespace std;

// Problem configuration
int numJobs, numMachines;
struct Operation {
    int machineId;
    int duration;
};

vector<vector<Operation>> jobPaths; // [job][operation_index]

// Helper arrays to avoid repeated allocations during evaluation
vector<int> nextOpIndex;
vector<long long> jobFinishTime;
vector<long long> machineFinishTime;

// Computes makespan for a given operation-based permutation
// perm: vector of size numJobs * numMachines containing job indices (each appears numMachines times)
long long evaluateMakespan(const vector<int>& perm) {
    // Reset helper structures
    fill(nextOpIndex.begin(), nextOpIndex.end(), 0);
    fill(jobFinishTime.begin(), jobFinishTime.end(), 0);
    fill(machineFinishTime.begin(), machineFinishTime.end(), 0);

    long long currentMax = 0;

    for (int job : perm) {
        int opNum = nextOpIndex[job];
        const Operation& op = jobPaths[job][opNum];
        int m = op.machineId;
        int p = op.duration;

        // Determine earliest possible start time
        long long earliestStart = max(jobFinishTime[job], machineFinishTime[m]);
        long long finishTime = earliestStart + p;

        // Update availability information
        jobFinishTime[job] = finishTime;
        machineFinishTime[m] = finishTime;
        nextOpIndex[job]++;

        if (finishTime > currentMax) currentMax = finishTime;
    }

    return currentMax;
}

// Decodes the best permutation into machine-wise operation sequences and prints them
void displaySchedule(const vector<int>& perm) {
    vector<vector<int>> machineOps(numMachines);
    fill(nextOpIndex.begin(), nextOpIndex.end(), 0);

    for (int job : perm) {
        int opNum = nextOpIndex[job];
        int m = jobPaths[job][opNum].machineId;
        machineOps[m].push_back(job);
        nextOpIndex[job]++;
    }

    for (int m = 0; m < numMachines; ++m) {
        for (size_t i = 0; i < machineOps[m].size(); ++i) {
            cout << machineOps[m][i] << (i == machineOps[m].size() - 1 ? "" : " ");
        }
        cout << "\n";
    }
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    if (!(cin >> numJobs >> numMachines)) return 0;

    jobPaths.resize(numJobs);
    for (int i = 0; i < numJobs; ++i) {
        jobPaths[i].reserve(numMachines);
        for (int k = 0; k < numMachines; ++k) {
            int m, t;
            cin >> m >> t;
            jobPaths[i].push_back({m, t});
        }
    }

    // Initialize helper vectors
    nextOpIndex.resize(numJobs);
    jobFinishTime.resize(numJobs);
    machineFinishTime.resize(numMachines);

    // Create initial permutation: each job index appears numMachines times
    vector<int> candidate;
    candidate.reserve(numJobs * numMachines);
    for (int i = 0; i < numJobs; ++i) {
        for (int k = 0; k < numMachines; ++k) {
            candidate.push_back(i);
        }
    }

    // Random number generator initialization
    mt19937 engine(chrono::steady_clock::now().time_since_epoch().count());

    // Generate promising starting solution via multiple random shuffles
    shuffle(candidate.begin(), candidate.end(), engine);
    long long bestScore = evaluateMakespan(candidate);
    vector<int> bestCandidate = candidate;

    for(int attempt = 0; attempt < 100; ++attempt) {
        shuffle(candidate.begin(), candidate.end(), engine);
        long long tempScore = evaluateMakespan(candidate);
        if(tempScore < bestScore) {
            bestScore = tempScore;
            bestCandidate = candidate;
        }
    }

    // Prepare for Simulated Annealing optimization
    vector<int> currentCandidate = bestCandidate;
    long long currentScore = bestScore;

    auto startTime = chrono::steady_clock::now();
    double timeout = 1.95; // Slightly under 2 seconds for safety

    // Estimate initial temperature using random moves
    double totalDelta = 0;
    int deltaCount = 0;
    for(int trial = 0; trial < 200; ++trial) {
        int idx1 = uniform_int_distribution<int>(0, numJobs * numMachines - 1)(engine);
        int idx2 = uniform_int_distribution<int>(0, numJobs * numMachines - 1)(engine);
        if(idx1 == idx2) continue;

        swap(currentCandidate[idx1], currentCandidate[idx2]);
        long long score = evaluateMakespan(currentCandidate);
        long long diff = score - currentScore;
        if(diff > 0) {
            totalDelta += diff;
            deltaCount++;
        }
        // Revert the swap
        swap(currentCandidate[idx1], currentCandidate[idx2]);
    }

    double startTemp = 100.0; // Default fallback value
    if(deltaCount > 0) {
        double avgChange = totalDelta / deltaCount;
        startTemp = -avgChange / log(0.5); // 50% acceptance probability for average worsening
    }

    double temperature = startTemp;
    long long iterations = 0;

    // Main SA loop
    while(true) {
        if ((iterations & 0x3FF) == 0) {
            auto currentTime = chrono::steady_clock::now();
            chrono::duration<double> elapsed = currentTime - startTime;
            if (elapsed.count() > timeout) break;

            double progress = elapsed.count() / timeout;
            temperature = startTemp * (1.0 - progress);
            if(temperature < 1e-6) temperature = 1e-6;
        }
        iterations++;

        // Generate neighbor by swapping two positions
        int pos1 = uniform_int_distribution<int>(0, numJobs * numMachines - 1)(engine);
        int pos2 = uniform_int_distribution<int>(0, numJobs * numMachines - 1)(engine);
        if(pos1 == pos2) continue;

        swap(currentCandidate[pos1], currentCandidate[pos2]);
        long long newScore = evaluateMakespan(currentCandidate);
        bool accepted = false;

        if(newScore <= currentScore) {
            accepted = true;
            if(newScore < bestScore) {
                bestScore = newScore;
                bestCandidate = currentCandidate;
            }
        } else {
            double delta = static_cast<double>(newScore - currentScore);
            if(uniform_real_distribution<double>(0.0, 1.0)(engine) < exp(-delta / temperature)) {
                accepted = true;
            }
        }

        if(!accepted) {
            // Undo the swap
            swap(currentCandidate[pos1], currentCandidate[pos2]);
        } else {
            currentScore = newScore;
        }
    }

    // Output final schedule
    displaySchedule(bestCandidate);
    return 0;
}

