// Cache for previously computed collision results
std::map<long long, long long> cache;

// Computes collisions between two arithmetic progressions:
// A = {base + 1, ..., base + k} and B = {base + shift + 1, ..., base + shift + k}
long long compute_collisions(long long shift, int count) {
    if (cache.find(shift) != cache.end()) {
        return cache[shift];
    }

    const long long BASE = 199999999999999999LL; // Slightly different base
    std::vector<long long> queryList;
    queryList.reserve(2 * count);

    for (int idx = 1; idx <= count; ++idx) {
        queryList.push_back(BASE + idx);
    }
    for (int idx = 1; idx <= count; ++idx) {
        queryList.push_back(BASE + shift + idx);
    }

    return cache[shift] = send_query(queryList);
}

// Determines (d mod n) using binary search and collision queries
long long determine_remainder(long long d, int k) {
    long long left = 0, right = d;
    long long lower_bound_rem = 0;

    if (compute_collisions(d, k) > 0) {
        lower_bound_rem = 0;
    }

    while (left <= right) {
        long long mid = left + (right - left) / 2;
        if (compute_collisions(d - mid, k) > 0) {
            lower_bound_rem = mid;
            left = mid + 1;
        } else {
            right = mid - 1;
        }
    }

    long long currentCollisions = compute_collisions(d - lower_bound_rem, k);
    return lower_bound_rem + k - currentCollisions;
}

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    // First phase: detect small n values
    const int SMALL_K = 450;
    std::vector<long long> smallQuery;
    for (int i = 1; i <= SMALL_K; ++i) {
        smallQuery.push_back(i);
    }

    if (send_query(smallQuery) > 0) {
        int low = 1, high = SMALL_K;
        int foundK = SMALL_K;

        while (low <= high) {
            int mid = low + (high - low) / 2;
            if (mid == 0) {
                low = 1;
                continue;
            }

            std::vector<long long> tempQuery;
            for (int i = 1; i <= mid; ++i) {
                tempQuery.push_back(i);
            }

            if (send_query(tempQuery) > 0) {
                foundK = mid;
                high = mid - 1;
            } else {
                low = mid + 1;
            }
        }

        submit_result(foundK - 1);
        return 0;
    }

    // Second phase: handle large n
    const int LARGE_K = 400;
    std::vector<long long> remainders(34); // indices 0..33

    // Compute (2^i mod n) for i from 0 to 33
    for (int i = 0; i <= 33; ++i) {
        cache.clear();
        remainders[i] = determine_remainder(1LL << i, LARGE_K);
    }

    // Derive n from remainders:
    // Since 2*(2^i mod n) = (2^{i+1} mod n) + c*n, where c ∈ {0,1},
    // then candidate_n = 2*remainders[i] - remainders[i+1] gives either 0 or n.
    // The first positive candidate is our n.
    for (int i = 0; i <= 32; ++i) {
        long long possibleN = 2 * remainders[i] - remainders[i + 1];
        if (possibleN > 0) {
            submit_result(possibleN);
            return 0;
        }
    }

    return 0;
}

