    mUsePostProc = dynamic_cast<Character *>(dir) || dynamic_cast<WorldDir *>(dir);
}

// Main polling loop for hair simulation updates
void CharHair::Poll() {
    Character *currentChar = Character::Current();
    if (currentChar) {
        if (currentChar->Synced()) {
            Hookup();
        }
        if (currentChar->Teleported()) {
            mReset = 1;
        }
        if (currentChar->LODCheck()) {
            DoReset(0);
            return;
        }
    }

    if (mReset > 0) {
        DoReset(mReset);
    }

    float dt = TheTaskMgr.DeltaSeconds();
    if (dt != 0.0f) {
        SimulateLoops(1, GetFPS());
    } else {
        SimulateZeroTime();
    }
}

void CharHair::Enter() {
    mReset = 1;
    RndPollable::Enter();
    Hookup();
}

void CharHair::PollDeps(
    std::list<Hmx::Object *> &changedBy, std::list<Hmx::Object *> &change
) {
    for (int idx = 0; idx < mStrands.size(); ++idx) {
        changedBy.push_back(mStrands[idx].Root());
        change.push_back(mStrands[idx].Root());
    }
}

// Adjust side lengths for cloth-like behavior
void CharHair::SetCloth(bool enableCloth) {
    for (int i = 0; i < mStrands.size(); ++i) {
        Strand &strand = mStrands[i];
        int modIndex = Mod(i + 1, mStrands.size());
        Strand &otherStrand = mStrands[modIndex];

        for (int j = 0; j < strand.NumPoints(); ++j) {
            Point &pt = strand.PointAt(j);
            pt.sideLength = enableCloth && j < otherStrand.NumPoints()
                ? Distance(pt.pos, otherStrand.PointAt(j).pos)
                : -1.0f;
        }
    }
}

void CharHair::Hookup() {
    if (!mManagedHookup) {
        ObjPtrList<CharCollide> colliders(this);
        for (ObjDirItr<CharCollide> it(Dir(), true); it != nullptr; ++it) {
            colliders.push_back(it);
        }
        colliders.sort(SortCollides());
        Hookup(colliders);
    }
}

void CharHair::FreezePose() {
    bool prevSimState = mSimulate;
    Hookup();
    SimulateLoops(200, 60);
    mSimulate = prevSimState;
    FreezePoseRaw();
}

INIT_REVS(12, 1)

void CharHair::Load(BinStream &bs) {
    LOAD_REVS(bs);
    ASSERT_REVS(12, 1);
    LOAD_SUPERCLASS(Hmx::Object)
    bs >> mStiffness >> mTorsion >> mInertia >> mGravity >> mWeight >> mFriction;
    if (d.rev < 9) {
        mMinSlack = 0.0f;
        mMaxSlack = 0.0f;
    } else {
        bs >> mMinSlack >> mMaxSlack;
    }
    // bs >> mStrands;
    bs >> mSimulate;
    if (d.rev > 11)
        bs >> mWind;
}
