using json = nlohmann::json;

class Barometer::Loader {
 public:
  explicit Loader(Barometer::Impl& ref_impl);
  void LoadData(const json& data);
 private:
  void ConfigureBarometerSettings(const json& config);
  Barometer::Impl& ref_impl_;
};

struct BarometerRecord {
  TimeNano timestamp;
  float height;      // meters
  float pressure_val; // pascal
  float qnh_val;     // HectoPascals(hPa)/Millibars(mbar).
};

class Barometer::Impl : public SensorImpl {
 public:
  Impl(const std::string& identifier, bool active, const std::string& parent_link,
       const Logger& log, const TopicManager& topic_mgr,
       const std::string& parent_topic_path,
       const ServiceManager& service_mgr,
       const StateManager& state_mgr);
  void LoadConfig(ConfigJson config_json);
  void Init(const Kinematics&, const Environment&);
  void OnStartUpdate() override;
  void SetupTopics();
  void ApplyNoiseModel(BarometerRecord&, const TimeSec&);
  void Process(const TimeNano, const TimeNano);
  BarometerMessage RetrieveOutput();
  void RegisterServiceEndpoint();
  void OnFinishUpdate() override;
 private:
  friend class Barometer::Loader;
  Barometer::Loader loader_;
  BarometerParams barometer_config_;
  GaussianMarkov pressure_drift_;
  RandomGeneratorGaussianF independent_noise_;
  Topic barometer_pub_;
  std::vector<std::reference_wrapper<Topic>> topic_list_;
  struct TruthData {
    const Environment* env;
  } truth_data_;
  BarometerRecord current_output_;  // Stores latest sensor reading
};

// --- Public Barometer interface ---

Barometer::Barometer() : Sensor(std::shared_ptr<SensorImpl>(nullptr)) {}

Barometer::Barometer(const std::string& id, bool enabled,
                     const std::string& parent_link, const Logger& logger,
                     const TopicManager& topic_manager,
                     const std::string& parent_topic_path,
                     const ServiceManager& service_manager,
                     const StateManager& state_manager)
    : Sensor(std::shared_ptr<SensorImpl>(new Barometer::Impl(
          id, enabled, parent_link, logger, topic_manager, parent_topic_path,
          service_manager, state_manager))) {}

void Barometer::Load(ConfigJson config_json) {
  static_cast<Barometer::Impl*>(pimpl.get())->LoadConfig(config_json);
}

void Barometer::Initialize(const Kinematics& kinematics,
                           const Environment& environment) {
  static_cast<Barometer::Impl*>(pimpl.get())
      ->Init(kinematics, environment);
}

void Barometer::BeginUpdate() {
  static_cast<Barometer::Impl*>(pimpl.get())->OnStartUpdate();
}

void Barometer::Update(const TimeNano sim_time, const TimeNano sim_dt_nanos) {
  static_cast<Barometer::Impl*>(pimpl.get())->Process(sim_time, sim_dt_nanos);
}

BarometerMessage Barometer::getOutput() const {
  return static_cast<Barometer::Impl*>(pimpl.get())->RetrieveOutput();
}

void Barometer::EndUpdate() {
  static_cast<Barometer::Impl*>(pimpl.get())->OnFinishUpdate();
}

// --- Implementation of Barometer::Impl ---

Barometer::Impl::Impl(const std::string& identifier, bool active,
                      const std::string& parent_link, const Logger& log,
                      const TopicManager& topic_mgr,
                      const std::string& parent_topic_path,
                      const ServiceManager& service_mgr,
                      const StateManager& state_mgr)
    : SensorImpl(SensorType::kBarometer, identifier, active, parent_link,
                 Constant::Component::imu, log, topic_mgr,
                 parent_topic_path, service_mgr, state_mgr),
      loader_(*this) {
  SetTopicPath();
  SetupTopics();
}

void Barometer::Impl::LoadConfig(ConfigJson config_json) {
  json cfg = config_json;
  loader_.LoadData(cfg);
}

void Barometer::Impl::Init(const Kinematics& /* kinematics */,
                           const Environment& environment) {
  truth_data_.env = &environment;
  pressure_drift_.Initialize(barometer_config_.pressure_factor_tau,
                             barometer_config_.pressure_factor_sigma, 0.0f);
  independent_noise_ = RandomGeneratorGaussianF(
      0.0f, barometer_config_.uncorrelated_noise_sigma);
}

void Barometer::Impl::SetupTopics() {
  barometer_pub_ = Topic("barometer", topic_path_, TopicType::kPublished, 100,
                         MessageType::kBarometer);
  topic_list_.push_back(barometer_pub_);
}

void Barometer::Impl::OnStartUpdate() {
  for (const auto& topic_ref : topic_list_) {
    topic_manager_.RegisterTopic(topic_ref.get());
  }
  RegisterServiceEndpoint();
}

void Barometer::Impl::Process(const TimeNano sim_time,
                              const TimeNano sim_dt_nanos) {
  std::lock_guard<std::mutex> lock(update_lock_);
  auto now = sim_time;
  TimeSec delta = sim_dt_nanos / 1.0e9;

  current_output_.height = truth_data_.env->env_info.geo_point.altitude;
  current_output_.pressure_val =
      truth_data_.env->env_info.air_pressure;
  current_output_.qnh_val = barometer_config_.qnh;

  ApplyNoiseModel(current_output_, delta);
  current_output_.timestamp = now;

  BarometerMessage msg(current_output_.timestamp, current_output_.height,
                       current_output_.pressure_val, current_output_.qnh_val);
  topic_manager_.PublishTopic(barometer_pub_, (Message&)msg);
}

BarometerMessage Barometer::Impl::RetrieveOutput() {
  return BarometerMessage(current_output_.timestamp, current_output_.height,
                          current_output_.pressure_val, current_output_.qnh_val);
}

void Barometer::Impl::RegisterServiceEndpoint() {
  auto endpoint_name = topic_path_ + "/" + "barometer";
  auto method_desc = ServiceMethod(endpoint_name, {""});
  auto handler = method_desc.CreateMethodHandler(
      &Barometer::Impl::RetrieveOutput, *this);
  service_manager_.RegisterMethod(method_desc, handler);
}

void Barometer::Impl::ApplyNoiseModel(BarometerRecord& data,
                                      const TimeSec& dt) {
  pressure_drift_.Update(dt);
  data.pressure_val += data.pressure_val * pressure_drift_.getOutput();
  data.pressure_val += independent_noise_.next();
  data.pressure_val = data.pressure_val -
                      EarthUtils::kSeaLevelPressure +
                      barometer_config_.qnh * 100.0f;
  data.height = EarthUtils::GetPressureAltitude(data.pressure_val);
  data.qnh_val = barometer_config_.qnh;
}

void Barometer::Impl::OnFinishUpdate() {
  for (const auto& topic : topic_list_) {
    topic_manager_.UnregisterTopic(topic);
  }
}

