Barometer::Loader::Loader(Barometer::Impl& ref_impl) : ref_impl_(ref_impl) {}

void Barometer::Loader::LoadData(const json& config) {
  ref_impl_.logger_.LogVerbose(ref_impl_.name_, "[%s] Loading 'barometer_settings'.",
                               ref_impl_.id_.c_str());
