  ref_impl_.is_loaded_ = true;
  ref_impl_.logger_.LogVerbose(ref_impl_.name_, "[%s] 'barometer_settings' loaded.",
                               ref_impl_.id_.c_str());
}

void Barometer::Loader::ConfigureBarometerSettings(const json& config) {
  ref_impl_.barometer_config_.qnh = JsonUtils::GetNumber<float>(
      config, Constant::Config::qnh, ref_impl_.barometer_config_.qnh);
  ref_impl_.barometer_config_.pressure_factor_sigma =
      JsonUtils::GetNumber<float>(config, Constant::Config::pressure_factor_sigma,
                           ref_impl_.barometer_config_.pressure_factor_sigma);
  ref_impl_.barometer_config_.pressure_factor_tau =
      JsonUtils::GetNumber<float>(config, Constant::Config::pressure_factor_tau,
                           ref_impl_.barometer_config_.pressure_factor_tau);
  ref_impl_.barometer_config_.uncorrelated_noise_sigma =
      JsonUtils::GetNumber<float>(config, Constant::Config::uncorrelated_noise_sigma,
                           ref_impl_.barometer_config_.uncorrelated_noise_sigma);
  ref_impl_.barometer_config_.update_latency =
      JsonUtils::GetNumber<float>(config, Constant::Config::update_latency,
                           ref_impl_.barometer_config_.update_latency);
  ref_impl_.barometer_config_.update_frequency =
      JsonUtils::GetNumber<float>(config, Constant::Config::update_frequency,
                           ref_impl_.barometer_config_.update_frequency);
  ref_impl_.barometer_config_.startup_delay =
      JsonUtils::GetNumber<float>(config, Constant::Config::startup_delay,
                           ref_impl_.barometer_config_.startup_delay);
  ref_impl_.logger_.LogVerbose(ref_impl_.name_, "Loaded Barometer settings");
}

