#include <bits/stdc++.h>
using namespace std;

// Interactive solution using randomized signature matching
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int T;
    if (!(cin >> T)) return 0;

    while (T--) {
        int n;
        if (!(cin >> n)) return 0;

        // Exclude position k=1 from counting in queries
        int fixed_pos = 1;
        cout << fixed_pos << '\n';
        cout.flush();

        // Lambda function to ask a query
        auto query = [&](const vector<int>& perm) -> int {
            cout << "?";
            for (int val : perm) {
                cout << ' ' << val;
            }
            cout << '\n';
            cout.flush();

            int result;
            if (!(cin >> result)) exit(0);
            if (result == -1) exit(0);
            return result;
        };

        // Number of random permutations to use: capped at 200
        int num_queries = min(10 * n, 200);

        // Generate random permutations
        vector<vector<int>> permutations;
        permutations.reserve(num_queries);
        vector<int> base(n);
        iota(base.begin(), base.end(), 1);

        mt19937 rng(456789 + n * 123456);
        for (int t = 0; t < num_queries; ++t) {
            shuffle(base.begin(), base.end(), rng);
            permutations.push_back(base);
        }

        // Precompute positions: pos[t][value] = index of value in permutation t
        vector<vector<int>> positions(num_queries, vector<int>(n + 1));
        for (int t = 0; t < num_queries; ++t) {
            for (int idx = 0; idx < n; ++idx) {
                positions[t][permutations[t][idx]] = idx;
            }
        }

        // Ask all queries and store responses
        vector<int> answers(num_queries);
        for (int t = 0; t < num_queries; ++t) {
            answers[t] = query(permutations[t]);
        }

        // Build cost matrix for assignment problem
        const int INF = 1e9;
        vector<vector<int>> cost_matrix(n, vector<int>(n, INF));

        for (int i = 1; i <= n; ++i) {
            for (int j = 1; j <= n; ++j) {
                if (i == j) continue;

                int penalty = 0;
                for (int t = 0; t < num_queries; ++t) {
                    int pos_i = positions[t][i];
                    int pos_j = positions[t][j];
                    int indicator = (pos_i != (fixed_pos - 1) && pos_i < pos_j) ? 1 : 0;

                    if (indicator) {
                        penalty += (num_queries - answers[t]);
                    } else {
                        penalty += answers[t];
                    }

                    if (penalty > INF / 2) break;
                }
                cost_matrix[i - 1][j - 1] = penalty;
            }
        }

        // Hungarian algorithm for minimum cost assignment
        int N = n;
        vector<int> u(N + 1), v(N + 1), match(N + 1), path(N + 1);

        for (int i = 1; i <= N; ++i) {
            match[0] = i;
            int col = 0;
            vector<int> min_vals(N + 1, INF);
            vector<bool> visited(N + 1, false);

            do {
                visited[col] = true;
                int row = match[col], delta = INF, next_col = 0;

                for (int c = 1; c <= N; ++c) if (!visited[c]) {
                    int current = cost_matrix[row - 1][c - 1] - u[row] - v[c];
                    if (current < min_vals[c]) {
                        min_vals[c] = current;
                        path[c] = col;
                    }
                    if (min_vals[c] < delta) {
                        delta = min_vals[c];
                        next_col = c;
                    }
                }

                for (int c = 0; c <= N; ++c) {
                    if (visited[c]) {
                        u[match[c]] += delta;
                        v[c] -= delta;
                    } else {
                        min_vals[c] -= delta;
                    }
                }
                col = next_col;
            } while (match[col] != 0);

            do {
                int prev_col = path[col];
                match[col] = match[prev_col];
                col = prev_col;
            } while (col);
        }

        // Reconstruct the permutation
        vector<int> perm_result(n + 1);
        for (int j = 1; j <= N; ++j) {
            int i = match[j];
            perm_result[i] = j;
        }

        // Fix any fixed points (should not happen in correct solution)
        vector<int> fixed_points;
        for (int i = 1; i <= n; ++i) {
            if (perm_result[i] == i) {
                fixed_points.push_back(i);
            }
        }

        if (!fixed_points.empty()) {
            int sz = fixed_points.size();
            for (int idx = 0; idx < sz; ++idx) {
                int a = fixed_points[idx];
                int b = fixed_points[(idx + 1) % sz];
                swap(perm_result[a], perm_result[b]);
            }
        }

        // Output final answer
        cout << "!";
        for (int i = 1; i <= n; ++i) {
            cout << ' ' << perm_result[i];
        }
        cout << '\n';
        cout.flush();
    }

    return 0;
}

