const char* BENCHMARK_FILE_EXT = ".benchmark";

BenchmarkRunner::BenchmarkRunner(const std::string& datasetPath,
    std::unique_ptr<BenchmarkConfig> config)
    : config{std::move(config)} {
    database = std::make_unique<Database>(datasetPath,
        SystemConfig(this->config->bufferPoolSize, this->config->numThreads));
    spdlog::set_level(spdlog::level::debug);
}

void BenchmarkRunner::registerBenchmarks(const std::string& path) {
    if (std::filesystem::is_regular_file(path)) {
        registerSingleBenchmark(path);
    } else if (std::filesystem::is_directory(path)) {
        for (auto& entry : std::filesystem::directory_iterator(path)) {
            registerSingleBenchmark(entry.path().string());
        }
    }
}

void BenchmarkRunner::runAllBenchmarks() {
    for (auto& benchmark : benchmarks) {
        try {
            executeBenchmark( // NOLINT(clang-analyzer-optin.cplusplus.UninitializedObject): spdlog has
                              // an uninitialized object.
                benchmark.get());
        } catch (std::exception& e) {
            spdlog::error("Exception occurred while executing benchmark {}: {}.", benchmark->name,
                e.what());
        }
    }
}

void BenchmarkRunner::registerSingleBenchmark(const std::string& path) {
    if (path.ends_with(BENCHMARK_FILE_EXT)) {
        auto benchmark = std::make_unique<Benchmark>(path, database.get(), *config);
        spdlog::info("Registering benchmark {}", benchmark->name);
        benchmarks.push_back(std::move(benchmark));
    }
}

double BenchmarkRunner::computeAverageOfLastRuns(const double* executionTimes, const int& totalLen,
    const int& countToAverage) {
    double accumulated = 0.0;
    for (int idx = totalLen - countToAverage; idx < totalLen; ++idx) {
        accumulated += executionTimes[idx];
    }
    return accumulated / countToAverage;
}

void BenchmarkRunner::executeBenchmark(Benchmark* benchmark) const {
    spdlog::info(
        "Executing benchmark {} with {} thread(s)", // NOLINT(clang-analyzer-optin.cplusplus.UninitializedObject):
                                                    // spdlog has an uninitialized object.
        benchmark->name, config->numThreads);

    if (!benchmark->preRun.empty()) {
        spdlog::info("Pre-execution step: {}", benchmark->preRun);
        benchmark->conn->query(benchmark->preRun);
    }

    for (auto warmupIdx = 0u; warmupIdx < config->numWarmups; ++warmupIdx) {
        spdlog::info("Warm-up iteration {}", warmupIdx + 1);
        benchmark->run();
    }

    profileQueryIfEnabled(benchmark);

    std::vector<double> timingResults(config->numRuns);
    for (auto runIdx = 0u; runIdx < config->numRuns; ++runIdx) {
        auto queryResult = benchmark->run();
        benchmark->log(runIdx + 1, *queryResult);
        timingResults[runIdx] = queryResult->getQuerySummary()->getExecutionTime();
    }

    spdlog::info("Execution time (avg of last {} runs) (ms): {}", config->numRuns,
        computeAverageOfLastRuns(&timingResults[0], config->numRuns,
            config->numRuns /* numRunsToAverage */));

    if (!benchmark->postRun.empty()) {
        spdlog::info("Post-execution step: {}", benchmark->postRun);
        benchmark->conn->query(benchmark->postRun);
    }
}

void BenchmarkRunner::profileQueryIfEnabled(Benchmark* benchmark) const {
    if (config->enableProfile && !config->outputPath.empty()) {
        auto profileData = benchmark->runWithProfile();
        std::ofstream profileStream(config->outputPath + "/" + benchmark->name + "_profile.txt",
            std::ios_base::app);
        profileStream << profileData->getNext()->toString() << '\n';
        profileStream.flush();
        profileStream.close();
    }
}

