#include <vector>
#include <queue>
using namespace std;

class Solution {
public:
    vector<int> maxSlidingWindow(vector<int>& input, int windowSize) {
        vector<int> output;
        priority_queue<pair<int, int>> maxHeap;

        // Initialize heap with the first 'windowSize' elements
        for(int index = 0; index < windowSize; index++) {
            maxHeap.push({input[index], index});
        }

        // Store maximum of first window
        output.push_back(maxHeap.top().first);

        // Slide the window through the rest of the array
        for(int position = windowSize; position < input.size(); position++) {
            // Add current element to heap
            maxHeap.push({input[position], position});

            // Remove elements that are outside the current window
            while(!maxHeap.empty() && maxHeap.top().second <= position - windowSize) {
                maxHeap.pop();
            }

            // Record maximum value of current window
            output.push_back(maxHeap.top().first);
        }

        return output;
    }
};

