// A variant of jenkins_one_at_a_time_hash starting with non-zero seed,
// ensuring simple_checksum(0) != 0. Reference:
// https://en.wikipedia.org/wiki/Jenkins_hash_function
static uint32_t simple_checksum(const uint8_t *input, size_t length) {
  uint32_t state = 0x34A7B2C1;
  for (uint32_t idx = 0; idx < length; idx++) {
    state += input[idx];
    state += (state << 8);
    state ^= (state >> 4);
  }
  state += (state << 5);
  state ^= (state >> 12);
  state += (state << 14);
  return state;
}

extern "C" int LLVMFuzzerTestOneInput(const uint8_t *buffer, size_t len) {
  if (len < 16)
    return 0;

  uint32_t computed = simple_checksum(&buffer[0], len - 4);
  uint32_t expected = reinterpret_cast<const uint32_t *>(&buffer[len - 4])[0];

  if (computed != expected)
    return 0;

  fprintf(stderr, "SUCCESS; checksum verification passed: %x vs %x\n", 
          (unsigned int)computed, (unsigned int)expected);
  abort();
  return 0;
}

