// Function that marks an integer as a sink for analysis
void sink([[clang::annotate("psr.sink")]] int value) {}

// External function returning a random integer
extern int rand();

// Function that conditionally sets input to zero and returns it
int processValue(int input) {
  while (rand()) {
    input = 0;
    break;
  }
  return input;
}

// Main entry point with annotated source parameter
int main([[clang::annotate("psr.source")]] int count, char *arguments[]) {
  int result = processValue(count);
  // Directly pass to sink without sanitizer intervention => potential leak
  sink(result);
}

