HOST_API at::Tensor helloworld(const at::Tensor &input_tensor, const at::Tensor &other_tensor)
{
    // Create output tensor with same shape and type as input
    at::Tensor output_tensor = at::empty_like(input_tensor);

    // Set block size for kernel execution
    uint32_t threads_per_block = 16;

    // Compute total number of elements
    uint32_t element_count = 1;
    for (uint32_t dim_size : input_tensor.sizes()) {
        element_count *= dim_size;
    }

    // Launch the custom kernel
    EXEC_KERNEL_CMD(helloworld, threads_per_block, input_tensor, other_tensor, output_tensor, element_count);

    return output_tensor;
}

