RenderIndexProxy::RenderIndexProxy(const std::string& rendererName, HdDriver* driverRef)
{
    HdRenderSettingsMap configMap;
#ifdef ADSK_OPENUSD_PENDING
    Hgi* hgiInstance = driverRef ? driverRef->driver.GetWithDefault<Hgi*>() : nullptr;
    if (hgiInstance && driverRef->name == HgiTokens->renderDriver)
    {
        HdRendererCreateArgs initArgs;
        initArgs.hgi = hgiInstance;
        initArgs.gpuEnabled = true;
        configMap.emplace(TfToken{"rendererCreateArgs"}, VtValue{initArgs});
    }
#endif

    HdRendererPluginRegistry& pluginRegistry = HdRendererPluginRegistry::GetInstance();
    _renderDelegate = pluginRegistry.CreateRenderDelegate(TfToken(rendererName), configMap);

    if (_renderDelegate)
    {
        _renderIndex = HdRenderIndex::New(_renderDelegate.Get(), { driverRef });
    }
}

RenderIndexProxy::~RenderIndexProxy()
{
    // Perform safe CPU & GPU memory cleanup.
    if (_renderDelegate)
    {
        auto hdStRegistry =
            dynamic_cast<HdStResourceRegistry*>(_renderDelegate->GetResourceRegistry().get());

        if (hdStRegistry)
        {
            hdStRegistry->GarbageCollectDispatchBuffers();
            hdStRegistry->GarbageCollectBufferResources();
        }
        else
        {
            _renderDelegate->GetResourceRegistry()->GarbageCollect();
        }
    }

// #define SHOW_RESOURCE_ALLOCATION
#ifdef SHOW_RESOURCE_ALLOCATION
    if (_renderDelegate)
    {
        auto registryPtr =
            dynamic_cast<HdStResourceRegistry*>(_renderDelegate->GetResourceRegistry().get());
        auto allocationInfo = registryPtr->GetResourceAllocation();
        std::cout << "HdStResourceRegistry:\n";
        for (const auto& item : allocationInfo)
        {
            std::cout << "      " << item.first << " " << item.second << "\n";
        }
    }
#endif

    // Cleanup order matters.
    _renderIndex    = nullptr;
    _renderDelegate = nullptr;
}

