using Real = long double;
const Real PI_VAL = acos(-1.0L);

struct Vector3 {
    Real x, y, z;
};

Vector3 operator+(const Vector3& lhs, const Vector3& rhs) { 
    return {lhs.x + rhs.x, lhs.y + rhs.y, lhs.z + rhs.z}; 
}

Vector3& operator+=(Vector3& lhs, const Vector3& rhs) { 
    lhs.x += rhs.x; 
    lhs.y += rhs.y; 
    lhs.z += rhs.z; 
    return lhs; 
}

Vector3 operator-(const Vector3& lhs, const Vector3& rhs) { 
    return {lhs.x - rhs.x, lhs.y - rhs.y, lhs.z - rhs.z}; 
}

Vector3& operator-=(Vector3& lhs, const Vector3& rhs) { 
    lhs.x -= rhs.x; 
    lhs.y -= rhs.y; 
    lhs.z -= rhs.z; 
    return lhs; 
}

Vector3 operator*(const Vector3& v, Real scalar) { 
    return {v.x * scalar, v.y * scalar, v.z * scalar}; 
}

Real squared_magnitude(const Vector3& v) { 
    return v.x * v.x + v.y * v.y + v.z * v.z; 
}

void normalize_vector(Vector3& v) {
    Real magnitude = sqrt(squared_magnitude(v));
    if (magnitude > 1e-12L) {
        v.x /= magnitude;
        v.y /= magnitude;
        v.z /= magnitude;
    }
}

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int count;
    std::cin >> count;

    if (count == 2) {
        std::cout << std::fixed << std::setprecision(15) << 2.0L << "\n";
        std::cout << "0.0 0.0 1.0\n";
        std::cout << "0.0 0.0 -1.0\n";
        return 0;
    }

    std::vector<Vector3> positions(count);
    const Real GOLDEN_RATIO = (1.0L + sqrt(5.0L)) / 2.0L;

    for (int idx = 0; idx < count; ++idx) {
        Real height = 1.0L - (2.0L * (idx + 0.5L)) / count;
        Real radial_dist = sqrt(1.0L - height * height);
        Real angle = 2.0L * PI_VAL * (idx + 0.5L) / GOLDEN_RATIO;
        positions[idx] = {cos(angle) * radial_dist, sin(angle) * radial_dist, height};
    }

    int max_steps = std::min(15000, static_cast<int>(150000000.0L / (count * count) + 1));

    Real learning_rate_start = 0.2L;
    Real learning_rate_end = 1e-5L;
    Real decay_rate = pow(learning_rate_end / learning_rate_start, 1.0L / max_steps);
    Real current_lr = learning_rate_start;

    for (int step = 0; step < max_steps; ++step) {
        std::vector<Vector3> gradients(count, {0, 0, 0});

        for (int i = 0; i < count; ++i) {
            for (int j = i + 1; j < count; ++j) {
                Vector3 displacement = positions[i] - positions[j];
                Real dist_sq = squared_magnitude(displacement);
                if (dist_sq < 1e-14L) dist_sq = 1e-14L;

                Real inv_dist_fourth = 1.0L / (dist_sq * dist_sq);
                Vector3 repulsion = displacement * inv_dist_fourth;

                gradients[i] += repulsion;
                gradients[j] -= repulsion;
            }
        }

        for (int i = 0; i < count; ++i) {
            positions[i] += gradients[i] * current_lr;
            normalize_vector(positions[i]);
        }

        current_lr *= decay_rate;
    }

    Real min_squared_distance = 100.0L;
    for (int i = 0; i < count; ++i) {
        for (int j = i + 1; j < count; ++j) {
            min_squared_distance = std::min(min_squared_distance, squared_magnitude(positions[i] - positions[j]));
        }
    }

    std::cout << std::fixed << std::setprecision(15);
    std::cout << sqrt(min_squared_distance) << "\n";

    for (int i = 0; i < count; ++i) {
        std::cout << positions[i].x << " " << positions[i].y << " " << positions[i].z << "\n";
    }

    return 0;
}

