#include <iostream>
#include <vector>
#include <cmath>
#include <numeric>
#include <random>

// Use unsigned 64-bit and 128-bit integers for modular arithmetic
using u64 = uint64_t;
using u128 = unsigned __int128;

u64 modulus;
int bit_count(u64 value) {
    if (value == 0) return 0;
    return 64 - __builtin_clzll(value);
}

u64 mod_multiply(u64 x, u64 y) {
    return (u128)x * y % modulus;
}

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    std::cin >> modulus;

    const int sample_count = 24000;
    std::vector<u64> base_values(sample_count);
    std::vector<long long> observed_T(sample_count);

    std::mt19937_64 prng(std::random_device{}());
    std::uniform_int_distribution<u64> range(2, modulus - 1);

    // Generate all queries first
    for (int idx = 0; idx < sample_count; ++idx) {
        base_values[idx] = range(prng);
        std::cout << "? " << base_values[idx] << std::endl;
        std::cin >> observed_T[idx];
    }

    // Precompute powers and bit-length information
    std::vector<std::vector<u64>> power_table(sample_count, std::vector<u64>(60));
    std::vector<std::vector<int>> length_table(sample_count, std::vector<int>(60));
    std::vector<long long> initial_sum(sample_count, 0);

    for (int query_idx = 0; query_idx < sample_count; ++query_idx) {
        u64 current = base_values[query_idx];
        for (int exp = 0; exp < 60; ++exp) {
            power_table[query_idx][exp] = current;
            length_table[query_idx][exp] = bit_count(current) + 1;
            initial_sum[query_idx] += (long long)length_table[query_idx][exp] * length_table[query_idx][exp];
            current = mod_multiply(current, current);
        }
    }

    u64 secret_d = 0;
    std::vector<u64> remainder(sample_count, 1);
    std::vector<long long> correction(sample_count, 0);

    // Recover each bit of the secret exponent
    for (int position = 0; position < 60; ++position) {
        long double sum_product = 0.0L;
        long double sum_squares = 0.0L;

        for (int query_idx = 0; query_idx < sample_count; ++query_idx) {
            long long residual = observed_T[query_idx] - initial_sum[query_idx] - correction[query_idx];
            long long coefficient = (long long)length_table[query_idx][position] * (bit_count(remainder[query_idx]) + 1);

            sum_product += (long double)residual * coefficient;
            sum_squares += (long double)coefficient * coefficient;
        }

        long double estimate = 0.0L;
        if (sum_squares > 1e-12) {
            estimate = sum_product / sum_squares;
        }

        int bit_value = (estimate > 0.5);
        if (bit_value) {
            secret_d |= (1ULL << position);
        }

        if (position < 59) {
            if (bit_value) {
                for (int query_idx = 0; query_idx < sample_count; ++query_idx) {
                    correction[query_idx] += (long long)length_table[query_idx][position] * (bit_count(remainder[query_idx]) + 1);
                    remainder[query_idx] = mod_multiply(remainder[query_idx], power_table[query_idx][position]);
                }
            }
        }
    }

    std::cout << "! " << secret_d << std::endl;
    return 0;
}

