#include "RHIBufferTests.h"

// Copies data from the given vertex buffer to CPU memory and validates it using the provided callback
bool FRHIBufferTests::VerifyBufferContents(const TCHAR* TestName, FRHICommandListImmediate& CmdList, FRHIVertexBuffer* Buffer, TFunctionRef<bool(void* Data, uint32 Size)> CheckCallback)
{
	bool Success;
	{
		uint32 ByteCount = Buffer->GetSize();
		FStagingBufferRHIRef Staging = RHICreateStagingBuffer();
		CmdList.CopyToStagingBuffer(Buffer, Staging, 0, ByteCount);
		// @todo - readback API is inconsistent across RHIs
		CmdList.SubmitCommandsAndFlushGPU();
		CmdList.BlockUntilGPUIdle();
		void* DataPtr = RHILockStagingBuffer(Staging, 0, ByteCount);
		Success = CheckCallback(DataPtr, ByteCount);
		RHIUnlockStagingBuffer(Staging);
	}
	// Immediate flush to clean up the staging buffer / other resources
	CmdList.ImmediateFlush(EImmediateFlushType::FlushRHIThreadFlushResourcesFlushDeferredDeletes);
	if (!Success)
	{
		UE_LOG(LogRHIUnitTestCommandlet, Error, TEXT("Test failed. \"%s\""), TestName);
	}
	else
	{
		UE_LOG(LogRHIUnitTestCommandlet, Display, TEXT("Test passed. \"%s\""), TestName);
	}
	return Success;
}

// Copies data from the given structured buffer to CPU memory and validates it using the provided callback
bool FRHIBufferTests::VerifyBufferContents(const TCHAR* TestName, FRHICommandListImmediate& CmdList, FRHIStructuredBuffer* Buffer, TFunctionRef<bool(void* Data, uint32 Size)> CheckCallback)
{
	bool Success;
	{
		uint32 ByteCount = Buffer->GetSize();
		CmdList.ImmediateFlush(EImmediateFlushType::FlushRHIThreadFlushResourcesFlushDeferredDeletes);
		void* DataPtr = CmdList.LockStructuredBuffer(Buffer, 0, ByteCount, EResourceLockMode::RLM_ReadOnly);
		Success = CheckCallback(DataPtr, ByteCount);
		CmdList.UnlockStructuredBuffer(Buffer);
	}
	// Immediate flush to clean up the staging buffer / other resources
	CmdList.ImmediateFlush(EImmediateFlushType::FlushRHIThreadFlushResourcesFlushDeferredDeletes);
	if (!Success)
	{
		UE_LOG(LogRHIUnitTestCommandlet, Error, TEXT("Test failed. \"%s\""), TestName);
	}
	else
	{
		UE_LOG(LogRHIUnitTestCommandlet, Display, TEXT("Test passed. \"%s\""), TestName);
	}
	return Success;
}

