ConsoleSaveFileInputStream::ConsoleSaveFileInputStream(ConsoleSaveFile *fileStorage, const ConsoleSavePath &path)
{
	m_fileStorage = fileStorage;
	m_fileHandle = m_fileStorage->createFile(path);
	m_fileStorage->setFilePointer(m_fileHandle, 0, NULL, FILE_BEGIN);
}

ConsoleSaveFileInputStream::ConsoleSaveFileInputStream(ConsoleSaveFile *fileStorage, FileEntry *entry)
{
	m_fileStorage = fileStorage;
	m_fileHandle = entry;
	m_fileStorage->setFilePointer(m_fileHandle, 0, NULL, FILE_BEGIN);
}

// Reads a single byte from the stream. Blocks until data is available.
// Returns:
//   the byte read (0-255), or -1 if end-of-file is reached
int ConsoleSaveFileInputStream::read()
{
	byte buffer = 0;
	DWORD bytesRead = 0;
	BOOL success = m_fileStorage->readFile(
		m_fileHandle,
		&buffer,
		1,
		&bytesRead
	);
	if (success == 0)
	{
		// TODO: Add appropriate error handling
		return -1;
	}
	else if (bytesRead == 0)
	{
		// Reached end of file
		return -1;
	}
	return static_cast<int>(buffer);
}

// Reads up to b.length bytes into the provided buffer.
// Blocks until at least one byte is available.
// Returns:
//   number of bytes actually read, or -1 if EOF is reached
int ConsoleSaveFileInputStream::read(byteArray b)
{
	DWORD bytesRead = 0;
	BOOL success = m_fileStorage->readFile(
		m_fileHandle,
		b.data,
		b.length,
		&bytesRead
	);
	if (success == 0)
	{
		// TODO: Add appropriate error handling
		return -1;
	}
	else if (bytesRead == 0)
	{
		// No more data available
		return -1;
	}
	return static_cast<int>(bytesRead);
}

// Reads up to length bytes starting at offset in buffer b.
// If length > 0, blocks until some data is available.
// Parameters:
//   b      - destination buffer
//   offset - starting position within buffer b
//   length - maximum number of bytes to read
// Returns:
//   number of bytes read, or -1 if EOF is reached
int ConsoleSaveFileInputStream::read(byteArray b, unsigned int offset, unsigned int length)
{
	// Ensure we don't overflow the buffer
	assert(length <= (b.length - offset));

	DWORD bytesRead = 0;
	BOOL success = m_fileStorage->readFile(
		m_fileHandle,
		&b[offset],
		length,
		&bytesRead
	);
	if (success == 0)
	{
		// TODO: Add appropriate error handling
		return -1;
	}
	else if (bytesRead == 0)
	{
		// End of file reached
		return -1;
	}
	return static_cast<int>(bytesRead);
}

// Closes the input stream and releases associated resources.
// Also closes the underlying file handle if still open.
void ConsoleSaveFileInputStream::close()
{
	if (m_fileStorage != NULL)
	{
		BOOL success = m_fileStorage->closeHandle(m_fileHandle);
		if (success == 0)
		{
			// TODO: Add appropriate error handling
		}
		// Prevent double-close in destructor
		m_fileStorage = NULL;
	}
}

