#include <iostream>
#include <vector>
#include <string>
#include <cmath>
using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int blackCount, whiteCount, paramX, paramY;
    if (!(cin >> blackCount >> whiteCount >> paramX >> paramY)) return 0;

    // Handle nearly equal counts with alternating pattern
    if (abs(blackCount - whiteCount) <= 1) {
        int height = blackCount + whiteCount;
        cout << height << " " << 1 << "\n";

        char tileChar;
        if (blackCount > whiteCount) tileChar = '#';
        else if (whiteCount > blackCount) tileChar = 'O';
        else tileChar = '#'; 

        for (int idx = 0; idx < height; ++idx) {
            cout << tileChar << "\n";
            tileChar = (tileChar == '#' ? 'O' : '#');
        }
    } else {
        // General case using width-2 grid layout
        vector<string> pattern;

        // Upper section: primarily black tiles
        if (whiteCount == 1) {
            pattern.push_back("##");
        } else {
            for (int k = 0; k < whiteCount - 1; ++k) {
                pattern.push_back("#O");
                pattern.push_back("##");
            }
        }

        // Separator layer between regions
        pattern.push_back("OO");

        // Lower section: primarily white tiles
        if (blackCount > 1) {
            for (int m = 0; m < blackCount - 1; ++m) {
                pattern.push_back("O#");
                pattern.push_back("OO");
            }
        }

        cout << pattern.size() << " " << 2 << "\n";
        for (const string& line : pattern) {
            cout << line << "\n";
        }
    }

    return 0;
}

