namespace {
using namespace mlir;
using namespace mlir::triton;

/// Function conversion pattern that transforms MemRef arguments into pointers
/// to MemRef descriptors (LLVM struct types) containing full type metadata.
struct FunctionOpLowering : public ConvertOpToLLVMPattern<triton::FuncOp> {
  FunctionOpLowering(LLVMTypeConverter &converter, int warpCount,
                     PatternBenefit benefit)
      : ConvertOpToLLVMPattern(converter, benefit), warps(warpCount) {}

  /// Retain only attributes not generated by `LLVMFuncOp::build`. If
  /// `excludeArgAttrs` is true, also omit argument attributes.
  static void extractRelevantAttributes(triton::FuncOp op,
                                        bool excludeArgAttrs,
                                        SmallVectorImpl<NamedAttribute> &out) {
    for (const auto &attribute : op->getAttrs()) {
      if (attribute.getName() == SymbolTable::getSymbolAttrName() ||
          attribute.getName() == op.getFunctionTypeAttrName() ||
          attribute.getName() == "std.varargs" ||
          (excludeArgAttrs && attribute.getName() == op.getArgAttrsAttrName()))
        continue;
      out.push_back(attribute);
    }
  }

  triton::FuncOp extendFunction(triton::FuncOp functionOp,
                                ConversionPatternRewriter &rewriter) const {
    // Append a stack pointer argument for shared memory management.
    auto location = functionOp.getLoc();
    auto context = functionOp->getContext();
    auto memSpace3PtrTy = LLVM::LLVMPointerType::get(rewriter.getContext(), 3);

    // 1. Update the function signature with an extra argument.
    auto originalType = functionOp.getFunctionType();
    auto updatedInputs = llvm::to_vector<4>(originalType.getInputs());
    updatedInputs.push_back(memSpace3PtrTy);
    auto extendedType = FunctionType::get(originalType.getContext(),
                                          updatedInputs, originalType.getResults());

    // 2. Extend argument attributes accordingly.
    SmallVector<NamedAttribute> updatedAttrs;
    extractRelevantAttributes(functionOp, /*excludeArgAttrs=*/true, updatedAttrs);
    auto updatedArgAttrs = llvm::to_vector<4>(functionOp.getAllArgAttrs());
    updatedArgAttrs.emplace_back(DictionaryAttr::get(context));
    updatedAttrs.push_back(rewriter.getNamedAttr(
        functionOp.getArgAttrsAttrName(), rewriter.getArrayAttr(updatedArgAttrs)));

    // 3. Add new argument to the function region and inline body.
    auto extendedFuncOp = rewriter.create<triton::FuncOp>(
        location, functionOp.getName(), extendedType, updatedAttrs);
    auto &bodyRegion = functionOp.getBody();
    bodyRegion.addArgument(memSpace3PtrTy, location);
    rewriter.inlineRegionBefore(bodyRegion, extendedFuncOp.getBody(),
                                extendedFuncOp.end());
    return extendedFuncOp;
  }

  LogicalResult
  matchAndRewrite(triton::FuncOp functionOp, OpAdaptor adaptor,
                  ConversionPatternRewriter &rewriter) const override {
    triton::FuncOp updatedFuncOp = functionOp;
    if (!LLVM::isKernel(functionOp))
      updatedFuncOp = extendFunction(functionOp, rewriter);

    LLVM::LLVMFuncOp loweredFuncOp = *mlir::convertFunctionToLLVMFunction(
        updatedFuncOp, rewriter, *getTypeConverter());
    if (!loweredFuncOp) {
      return failure();
    }

    auto ctx = functionOp->getContext();
    if (LLVM::isKernel(functionOp)) {
      // Mark kernel entry point with nvvm.kernel attribute.
      loweredFuncOp->setAttr("nvvm.kernel",
                             rewriter.getIntegerAttr(type::u1Ty(ctx), 1));
      loweredFuncOp.setLinkage(LLVM::Linkage::External);
    } else {
      // Prevent inlining via noinline passthrough attribute.
      loweredFuncOp.setPassthroughAttr(
          ArrayAttr::get(ctx, rewriter.getStringAttr("noinline")));
      rewriter.eraseOp(updatedFuncOp);
      loweredFuncOp.setLinkage(LLVM::Linkage::Internal);
    }

    // Annotate maxntid for potential use in nvvm.annotation metadata.
    loweredFuncOp->setAttr("nvvm.maxntid",
                           rewriter.getDenseI32ArrayAttr(32 * warps));

    rewriter.eraseOp(functionOp);
    return success();
  }

private:
  int warps{0};
};

} // namespace

void mlir::triton::populateFunctionConversionPatterns(
    LLVMTypeConverter &typeConverter, RewritePatternSet &patterns, int warps,
    PatternBenefit benefit) {
  patterns.add<FunctionOpLowering>(typeConverter, warps, benefit);
}

