void UIScene_SettingsAudioMenu::handleInput(
    int   playerIndex,
    int   keyCode,
    bool  isRepeat,
    bool  isPressed,
    bool  isReleased,
    bool& consumed
) {
    ui.AnimateKeyPress(m_iPad, keyCode, isRepeat, isPressed, isReleased);
    switch (keyCode) {
    case ACTION_MENU_CANCEL:
        if (isPressed) {
            navigateBack();
        }
        break;
    case ACTION_MENU_OK:
#ifdef __ORBIS__
    case ACTION_MENU_TOUCHPAD_PRESS:
#endif
        sendInputToMovie(keyCode, isRepeat, isPressed, isReleased);
        break;
    case ACTION_MENU_UP:
    case ACTION_MENU_DOWN:
    case ACTION_MENU_LEFT:
    case ACTION_MENU_RIGHT:
        sendInputToMovie(keyCode, isRepeat, isPressed, isReleased);
        break;
    }
}

