MenuBackup::MenuBackup(shared_ptr<Inventory> inventory, AbstractContainerMenu *menu)
{
    savePoints = new unordered_map<short, ItemInstanceArray *>();
    this->inventory = inventory;
    this->menu = menu;
}

void MenuBackup::record(short snapshotId)
{
    ItemInstanceArray *snapshot = new ItemInstanceArray( (int)menu->slots->size() + 1 );
    (*snapshot)[0] = ItemInstance::clone(inventory->getCarried());
    for (unsigned int index = 0; index < menu->slots->size(); index++)
    {
        (*snapshot)[index + 1] = ItemInstance::clone(menu->slots->at(index)->getItem());
    }
    // TODO Is unordered_map use correct?
    // Was backups.put(snapshotId, snapshot);
    (*savePoints)[snapshotId] = snapshot;
}

// Cannot use delete as function name as it is a reserved keyword
void MenuBackup::removeRecord(short snapshotId)
{
    // TODO Is the unordered_map use correct?
    // 4J Was backups.remove(snapshotId);
    savePoints->erase(snapshotId);
}

void MenuBackup::restore(short snapshotId)
{
    ItemInstanceArray *snapshot = savePoints->at(snapshotId);
    savePoints->clear();
    inventory->setCarried( (*snapshot)[0] );
    for (unsigned int index = 0; index < menu->slots->size(); index++)
    {
        menu->slots->at(index)->set( (*snapshot)[index + 1] );
    }
}

