// Input handling with refactored control flow
void UIScene_DebugOptionsMenu::handleInput(int playerIndex, int keyCode, bool isRepeat, bool isPressed, bool isReleased, bool &handled)
{
    switch(keyCode)
    {
    case ACTION_MENU_CANCEL:
        if(isPressed)
        {
            unsigned int newDebugMask = 0L;
            int bitPosition = 0;

            // Reconstruct bitmask from checkbox states
            for(int i = 0; i < m_iTotalCheckboxElements; i++)
            {
                if(m_checkboxes[i].IsChecked())
                    newDebugMask |= (1 << bitPosition);
                bitPosition++;
            }

            // Update settings if changed
            if(newDebugMask != app.GetGameSettingsDebugMask(playerIndex))
            {
                app.SetGameSettingsDebugMask(playerIndex, newDebugMask);

                if(app.DebugSettingsOn())
                {
                    app.ActionDebugMask(playerIndex);        
                }
                else
                {
                    // Ensure debug mask is explicitly disabled
                    app.ActionDebugMask(playerIndex, true);
                }
                app.CheckGameSettingsChanged(true, playerIndex);
            }

            navigateBack();
        }
        break;

    case ACTION_MENU_OK:
    case ACTION_MENU_UP:
    case ACTION_MENU_DOWN:
    case ACTION_MENU_PAGEUP:
    case ACTION_MENU_PAGEDOWN:
        sendInputToMovie(keyCode, isRepeat, isPressed, isReleased);
        break;
    }
}

