#include <iostream>
#include <algorithm>
#include <vector>
#include <cstdlib>
#include <ctime>
using namespace std;

typedef long long ll;

ll cycleLength;
// Compute shortest distance between u and v on a simple cycle of length 'cycleLength'
ll minDistOnCycle(ll u, ll v) {
    if (u > v) swap(u, v);
    ll direct = v - u;
    return min(direct, cycleLength - direct);
}

// Send query to judge and get response
ll query(ll u, ll v) {
    cout << "? " << u << " " << v << endl;
    ll result;
    cin >> result;
    return result;
}

// Submit a guess for an edge; exit on wrong answer
bool submitGuess(ll u, ll v) {
    if (u == v) return false;
    cout << "! " << u << " " << v << endl;
    int verdict;
    cin >> verdict;
    if (verdict == -1) exit(0); // Incorrect guess — terminate immediately
    return true;
}

void processTestCase() {
    cin >> cycleLength;

    // Step 1: Search for a pair (start, end) where the chord improves over the cycle path
    ll start = -1, end = -1;
    srand(static_cast<unsigned>(time(nullptr)));

    // Attempt up to 250 random or structured pairs
    for (int attempt = 0; attempt < 250; ++attempt) {
        ll nodeA = (rand() % cycleLength) + 1;
        // Try opposite point (approximate)
        ll nodeB = (nodeA + cycleLength / 2) % cycleLength + 1;

        // Introduce variation every third iteration
        if (attempt % 4 == 0) {
            ll offset = (rand() % (cycleLength / 3)) + cycleLength / 3;
            nodeB = (nodeA + offset - 1) % cycleLength + 1;
        }

        if (nodeA == nodeB) continue;

        ll actualDist = query(nodeA, nodeB);
        ll cycleDist = minDistOnCycle(nodeA, nodeB);

        if (actualDist < cycleDist) {
            start = nodeA;
            end = nodeB;
            break;
        }
    }

    // Fallback case: extremely unlikely in practice
    if (start == -1) {
        submitGuess(2, 5);
        return;
    }

    // Step 2: Determine chord endpoints using binary search along one arc
    auto findChordInArc = [&](bool clockwise) -> pair<ll, ll> {
        ll distClockwise = (end - start + cycleLength) % cycleLength;
        ll distCounterClockwise = (start - end + cycleLength) % cycleLength;

        ll arcLen = clockwise ? distClockwise : distCounterClockwise;

        // Helper: get vertex at offset i from 'start' along chosen direction
        auto getNodeAtOffset = [&](ll offset) -> ll {
            if (clockwise) {
                return (start + offset - 1) % cycleLength + 1;
            } else {
                return (start - offset + cycleLength - 1) % cycleLength + 1;
            }
        };

        ll baseSaving = arcLen - query(start, end);
        if (baseSaving <= 0) return {-1, -1};

        ll span = baseSaving + 1;

        // Binary search for earliest vertex where saving reaches 'baseSaving'
        ll left = 1, right = arcLen;
        ll foundIndex = -1;

        while (left <= right) {
            ll mid = left + (right - left) / 2;
            ll candidateNode = getNodeAtOffset(mid);
            ll measuredDist = query(start, candidateNode);
            ll currentSaving = mid - measuredDist;

            if (currentSaving >= baseSaving) {
                foundIndex = mid;
                right = mid - 1;
            } else {
                left = mid + 1;
            }
        }

        if (foundIndex != -1) {
            ll vPos = foundIndex;
            ll uPos = vPos - span;
            if (uPos >= 0) {
                ll uNode = getNodeAtOffset(uPos);
                return {uNode, getNodeAtOffset(vPos)};
            }
        }
        return {-1, -1};
    };

    // Try clockwise arc first
    pair<ll, ll> candidate = findChordInArc(true);
    if (candidate.first != -1) {
        if (minDistOnCycle(candidate.first, candidate.second) > 1) {
            ll edgeWeight = query(candidate.first, candidate.second);
            if (edgeWeight == 1) {
                submitGuess(candidate.first, candidate.second);
                return;
            }
        }
    }

    // If no luck, try counter-clockwise arc
    candidate = findChordInArc(false);
    if (candidate.first != -1) {
        submitGuess(candidate.first, candidate.second);
        return;
    }

    // Last-resort fallback
    submitGuess(1, 4);
}

int main() {
    int testCount;
    if (cin >> testCount) {
        for (int t = 0; t < testCount; ++t) {
            processTestCase();
        }
    }
    return 0;
}

