#include <iostream>
#include <sstream>
#include <string>
#include <vector>
using namespace std;

int main() {
    int num_test_cases;
    cin >> num_test_cases;

    for (int case_num = 0; case_num < num_test_cases; ++case_num) {
        int nodes, edges, initial_node, initial_steps;
        cin >> nodes >> edges >> initial_node >> initial_steps;

        // Skip edge input
        for (int edge_idx = 0; edge_idx < edges; ++edge_idx) {
            int from_node, to_node;
            cin >> from_node >> to_node;
        }

        // Clear the newline after reading edges
        cin.ignore();

        bool finished = false;
        while (!finished) {
            string input_line;
            getline(cin, input_line);

            if (input_line.empty()) continue;

            if (input_line[0] == 'A' || input_line[0] == 'F') {
                finished = true;
                continue;
            }

            stringstream parser(input_line);
            int neighbor_count;
            parser >> neighbor_count;

            vector<int> neighbors(neighbor_count), visited_status(neighbor_count);
            for (int idx = 0; idx < neighbor_count; ++idx) {
                parser >> neighbors[idx] >> visited_status[idx];
            }

            // Determine next move: prefer unvisited neighbor first
            int selected_move = 1;
            for (int idx = 0; idx < neighbor_count; ++idx) {
                if (visited_status[idx] == 0) {
                    selected_move = idx + 1;
                    break;
                }
            }

            cout << selected_move << endl;
            cout.flush();
        }
    }

    return 0;
}

