using namespace llvm;
using llvm::itanium_demangle::OutputBuffer;
using llvm::itanium_demangle::starts_with;

namespace {
/// Structure holding data needed for demangling.
struct DemanglerContext {
  /// Constructor initializes the context with the mangled string.
  ///
  /// \param Input String to be demangled.
  DemanglerContext(std::string_view Input);

  /// Main entry point to parse and demangle the input symbol.
  ///
  /// \param Result Buffer where the demangled result will be written.
  ///
  /// \return Pointer to the remaining unparsed portion, or nullptr on failure.
  ///
  /// \see https://dlang.org/spec/abi.html#name_mangling .
  const char *processMangle(OutputBuffer *Result);

private:
  /// Internal helper to process the mangled name and populate the result buffer.
  ///
  /// \param Result Output buffer to write the demangled name.
  /// \param Input Reference to the current position in the mangled string.
  void processMangle(OutputBuffer *Result, std::string_view &Input);

  /// Extract numeric value from the beginning of the input string.
  ///
  /// \param Input Current position in the mangled string.
  /// \param Value Output variable to store the parsed number.
  ///
  /// \note Fails if the number exceeds UINT_MAX.
  void extractNumber(std::string_view &Input, unsigned long &Value);

  /// Decode a back-reference position encoded in base-26.
  ///
  /// \param Input Current position in the mangled string.
  /// \param Position Output variable to store the decoded position.
  ///
  /// \return true if decoding succeeded, false otherwise.
  bool extractBackrefPosition(std::string_view &Input, long &Position);

  /// Resolve a back-reference to an earlier part of the mangled string.
  ///
  /// \param Input Current position in the mangled string.
  /// \param Referenced Output variable to store the referenced substring.
  ///
  /// \return true if resolution succeeded, false otherwise.
  bool resolveBackref(std::string_view &Input, std::string_view &Referenced);

  /// Handle identifier-style back references.
  ///
  /// \param Result Output buffer to write the resolved identifier.
  /// \param Input Current position in the mangled string.
  void handleIdentifierBackref(OutputBuffer *Result, std::string_view &Input);

  /// Handle type-style back references.
  ///
  /// \param Input Current position in the mangled string.
  void handleTypeBackref(std::string_view &Input);

  /// Check whether the current position indicates a valid symbol name start.
  ///
  /// \param Input Current position in the mangled string.
  ///
  /// \return true if it's a valid symbol name start, false otherwise.
  bool isValidSymbolStart(std::string_view Input);

  /// Parse and append an identifier to the output buffer.
  ///
  /// \param Result Output buffer to write the identifier.
  /// \param Input Current position in the mangled string.
  void parseIdentifier(OutputBuffer *Result, std::string_view &Input);

  /// Parse a length-prefixed identifier (LName) and append to output.
  ///
  /// \param Result Output buffer to write the identifier.
  /// \param Input Current position in the mangled string.
  /// \param Length Length of the identifier to parse.
  void parseLName(OutputBuffer *Result, std::string_view &Input, unsigned long Length);

  /// Parse a qualified name (e.g., module.Class.function).
  ///
  /// \param Result Output buffer to write the qualified name.
  /// \param Input Current position in the mangled string.
  void parseQualifiedName(OutputBuffer *Result, std::string_view &Input);

  /// Parse a type encoding and advance the input pointer.
  ///
  /// \param Input Current position in the mangled string.
  ///
  /// \return true if parsing succeeded, false otherwise.
  bool parseType(std::string_view &Input);

  /// Immutable view of the original mangled string.
  const std::string_view SourceString;

  /// Track the last back-reference position to prevent infinite recursion.
  int LastBackrefIndex;
};
} // namespace

void DemanglerContext::extractNumber(std::string_view &Input, unsigned long &Value) {
  if (Input.empty() || !std::isdigit(Input.front())) {
    Input = {};
    return;
  }

  unsigned long Temp = 0;
  do {
    unsigned long digit = Input[0] - '0';
    if (Temp > (std::numeric_limits<unsigned int>::max() - digit) / 10) {
      Input = {};
      return;
    }
    Temp = Temp * 10 + digit;
    Input.remove_prefix(1);
  } while (!Input.empty() && std::isdigit(Input.front()));

  if (Input.empty()) {
    Input = {};
    return;
  }

  Value = Temp;
}

bool DemanglerContext::extractBackrefPosition(std::string_view &Input, long &Position) {
  if (Input.empty() || !std::isalpha(Input.front())) {
    Input = {};
    return false;
  }

  unsigned long Val = 0;
  while (!Input.empty() && std::isalpha(Input.front())) {
    if (Val > (std::numeric_limits<unsigned long>::max() - 25) / 26)
      break;

    Val *= 26;
    if (Input[0] >= 'a' && Input[0] <= 'z') {
      Val += Input[0] - 'a';
      if ((long)Val <= 0)
        break;
      Position = Val;
      Input.remove_prefix(1);
      return true;
    }
    Val += Input[0] - 'A';
    Input.remove_prefix(1);
  }

  Input = {};
  return false;
}

bool DemanglerContext::resolveBackref(std::string_view &Input, std::string_view &Referenced) {
  assert(!Input.empty() && Input.front() == 'Q' && "Invalid back reference marker!");
  Referenced = {};

  const char *MarkerPos = Input.data();
  long RefPos;

  Input.remove_prefix(1);
  if (!extractBackrefPosition(Input, RefPos)) {
    Input = {};
    return false;
  }

  if (RefPos > MarkerPos - SourceString.data()) {
    Input = {};
    return false;
  }

  Referenced = MarkerPos - RefPos;
  return true;
}

void DemanglerContext::handleIdentifierBackref(OutputBuffer *Result, std::string_view &Input) {
  unsigned long Len;
  std::string_view Backref;

  if (!resolveBackref(Input, Backref)) {
    Input = {};
    return;
  }

  extractNumber(Backref, Len);
  if (Backref.empty() || Backref.length() < Len) {
    Input = {};
    return;
  }

  parseLName(Result, Backref, Len);
  if (Backref.empty())
    Input = {};
}

void DemanglerContext::handleTypeBackref(std::string_view &Input) {
  if (Input.data() - SourceString.data() >= LastBackrefIndex) {
    Input = {};
    return;
  }

  int SavedRefPos = LastBackrefIndex;
  LastBackrefIndex = Input.data() - SourceString.data();

  std::string_view Backref;
  if (!resolveBackref(Input, Backref)) {
    Input = {};
    return;
  }

  if (Backref.empty()) {
    Input = {};
    return;
  }

  if (!parseType(Backref))
    Input = {};

  LastBackrefIndex = SavedRefPos;
  if (Backref.empty())
    Input = {};
}

bool DemanglerContext::isValidSymbolStart(std::string_view Input) {
  long Pos;
  const char *Marker = Input.data();

  if (std::isdigit(Input.front()))
    return true;

  if (Input.front() != 'Q')
    return false;

  Input.remove_prefix(1);
  bool Success = extractBackrefPosition(Input, Pos);
  if (!Success || Pos > Marker - SourceString.data())
    return false;

  return std::isdigit(Marker[-Pos]);
}

void DemanglerContext::processMangle(OutputBuffer *Result, std::string_view &Input) {
  Input.remove_prefix(2); // Skip "_D"

  parseQualifiedName(Result, Input);
  if (Input.empty()) {
    Input = {};
    return;
  }

  if (Input.front() == 'Z') {
    Input.remove_prefix(1);
  } else if (!parseType(Input)) {
    Input = {};
  }
}

void DemanglerContext::parseQualifiedName(OutputBuffer *Result, std::string_view &Input) {
  size_t FirstPart = false;

  do {
    if (!Input.empty() && Input.front() == '0') {
      do {
        Input.remove_prefix(1);
      } while (!Input.empty() && Input.front() == '0');
      continue;
    }

    if (FirstPart)
      *Result << '.';
    FirstPart = true;

    parseIdentifier(Result, Input);
  } while (!Input.empty() && isValidSymbolStart(Input));
}

void DemanglerContext::parseIdentifier(OutputBuffer *Result, std::string_view &Input) {
  if (Input.empty()) {
    Input = {};
    return;
  }

  if (Input.front() == 'Q')
    return handleIdentifierBackref(Result, Input);

  unsigned long Len;
  extractNumber(Input, Len);
  if (Input.empty()) {
    Input = {};
    return;
  }

  if (!Len || Input.length() < Len) {
    Input = {};
    return;
  }

  if (Len >= 4 && starts_with(Input, "__S")) {
    const size_t SuffixLen = Input.length() - Len;
    std::string_view Tail = Input.substr(3);
    while (Tail.length() > SuffixLen && std::isdigit(Tail.front()))
      Tail.remove_prefix(1);
    if (Tail.length() == SuffixLen) {
      Input.remove_prefix(Len);
      return parseIdentifier(Result, Input);
    }
  }

  parseLName(Result, Input, Len);
}

bool DemanglerContext::parseType(std::string_view &Input) {
  if (Input.empty()) {
    Input = {};
    return false;
  }

  switch (Input.front()) {
  case 'i':
    Input.remove_prefix(1);
    return true;
  case 'Q': {
    handleTypeBackref(Input);
    return true;
  }
  default:
    Input = {};
    return false;
  }
}

void DemanglerContext::parseLName(OutputBuffer *Result, std::string_view &Input,
                                  unsigned long Len) {
  switch (Len) {
  case 6:
    if (starts_with(Input, "__initZ")) {
      Result->prepend("initializer for ");
      Result->setCurrentPosition(Result->getCurrentPosition() - 1);
      Input.remove_prefix(Len);
      return;
    }
    if (starts_with(Input, "__vtblZ")) {
      Result->prepend("vtable for ");
      Result->setCurrentPosition(Result->getCurrentPosition() - 1);
      Input.remove_prefix(Len);
      return;
    }
    break;
  case 7:
    if (starts_with(Input, "__ClassZ")) {
      Result->prepend("ClassInfo for ");
      Result->setCurrentPosition(Result->getCurrentPosition() - 1);
      Input.remove_prefix(Len);
      return;
    }
    break;
  case 11:
    if (starts_with(Input, "__InterfaceZ")) {
      Result->prepend("Interface for ");
      Result->setCurrentPosition(Result->getCurrentPosition() - 1);
      Input.remove_prefix(Len);
      return;
    }
    break;
  case 12:
    if (starts_with(Input, "__ModuleInfoZ")) {
      Result->prepend("ModuleInfo for ");
      Result->setCurrentPosition(Result->getCurrentPosition() - 1);
      Input.remove_prefix(Len);
      return;
    }
    break;
  }

  *Result << Input.substr(0, Len);
  Input.remove_prefix(Len);
}

DemanglerContext::DemanglerContext(std::string_view Input)
    : SourceString(Input), LastBackrefIndex(Input.length()) {}

const char *DemanglerContext::processMangle(OutputBuffer *Result) {
  std::string_view Current(this->SourceString);
  processMangle(Result, Current);
  return Current.data();
}

char *llvm::dlangDemangle(std::string_view MangledName) {
  if (MangledName.empty() || !starts_with(MangledName, "_D"))
    return nullptr;

  OutputBuffer Result;
  if (MangledName == "_Dmain") {
    Result << "D main";
  } else {
    DemanglerContext Context(MangledName);
    const char *Remaining = Context.processMangle(&Result);

    if (Remaining == nullptr || *Remaining != '\0') {
      std::free(Result.getBuffer());
      return nullptr;
    }
  }

  if (Result.getCurrentPosition() > 0) {
    Result << '\0';
    Result.setCurrentPosition(Result.getCurrentPosition() - 1);
    return Result.getBuffer();
  }

  std::free(Result.getBuffer());
  return nullptr;
}

