class Solution {
public:
    int reverseBits(int value) {
        int result = 0;
        for (int position = 0; position < 32; position++) {
            result = (result << 1) | (value & 1);  // extract least significant bit and append to result
            value >>= 1;                           // shift value right to process next bit
        }
        return result;
    }
};

