using namespace std;

struct Connection {
    int from, to;
    int index;
};

int nodes, connectionsCount;
vector<Connection> edgeList;
vector<vector<pair<int, int>>> adjacencyList; // node -> {neighbor, edge_index}

// Global bitsets for the solver
bitset<10000> currentMask;
bitset<10000> candidateSet;
bitset<10000> fullSet;

struct ExperimentResult {
    vector<int> entryTime;
    vector<int> exitTime;
    vector<int> dfsOrder; // maps DFS index -> original node
    int answer;
};

vector<ExperimentResult> experiments;

void performRandomDFS(int startNode, vector<int>& parent, vector<int>& order, vector<int>& inTime, vector<int>& outTime, mt19937& generator) {
    vector<int> stack;
    stack.push_back(startNode);

    vector<bool> visited(nodes, false);
    visited[startNode] = true;

    int timer = 0;

    struct StackFrame {
        int node;
        int nextEdgeIndex;
    };
    vector<StackFrame> callStack;

    // Pre-shuffle adjacency lists
    vector<vector<int>> shuffledAdj(nodes);
    for (int u = 0; u < nodes; ++u) {
        for (auto& neighbor : adjacencyList[u]) {
            shuffledAdj[u].push_back(neighbor.first);
        }
        shuffle(shuffledAdj[u].begin(), shuffledAdj[u].end(), generator);
    }

    callStack.push_back({startNode, 0});
    inTime[startNode] = timer++;
    order[inTime[startNode]] = startNode;

    while (!callStack.empty()) {
        StackFrame& frame = callStack.back();
        int currentNode = frame.node;

        if (frame.nextEdgeIndex < shuffledAdj[currentNode].size()) {
            int nextNode = shuffledAdj[currentNode][frame.nextEdgeIndex];
            frame.nextEdgeIndex++;
            if (!visited[nextNode]) {
                visited[nextNode] = true;
                inTime[nextNode] = timer++;
                order[inTime[nextNode]] = nextNode;
                callStack.push_back({nextNode, 0});
            }
        } else {
            outTime[currentNode] = timer - 1;
            callStack.pop_back();
        }
    }
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    if (!(cin >> nodes >> connectionsCount)) return 0;

    adjacencyList.resize(nodes);
    for (int i = 0; i < connectionsCount; ++i) {
        int u, v;
        cin >> u >> v;
        edgeList.push_back({u, v, i});
        adjacencyList[u].push_back({v, i});
        adjacencyList[v].push_back({u, i});
    }

    mt19937 rng(42);

    // Initialize full bitset
    for (int i = 0; i < nodes; ++i) {
        fullSet[i] = 1;
    }

    const int maxExperiments = 250;
    vector<int> edgeDirection(connectionsCount); // 0: u->v, 1: v->u
    vector<int> inTime(nodes), outTime(nodes), dfsOrder(nodes);

    for (int exp = 0; exp < maxExperiments; ++exp) {
        int root = uniform_int_distribution<int>(0, nodes - 1)(rng);

        fill(inTime.begin(), inTime.end(), 0);
        fill(outTime.begin(), outTime.end(), 0);
        fill(dfsOrder.begin(), dfsOrder.end(), 0);

        performRandomDFS(root, vector<int>(), dfsOrder, inTime, outTime, rng);

        // Determine edge directions based on DFS traversal
        for (const auto& e : edgeList) {
            if (inTime[e.from] < inTime[e.to]) {
                edgeDirection[e.index] = 0; // from -> to
            } else {
                edgeDirection[e.index] = 1; // to -> from
            }
        }

        cout << "0 ";
        for (int i = 0; i < connectionsCount; ++i) {
            cout << edgeDirection[i] << (i == connectionsCount - 1 ? "" : " ");
        }
        cout << endl;

        int response;
        cin >> response;
        if (response == -1) return 0;

        ExperimentResult expData;
        expData.entryTime = inTime;
        expData.exitTime = outTime;
        expData.dfsOrder = dfsOrder;
        expData.answer = response;
        experiments.push_back(expData);
    }

    // Find the two distinct nodes A and B
    int nodeA = -1, nodeB = -1;

    for (int candidateA = 0; candidateA < nodes; ++candidateA) {
        candidateSet = fullSet;
        candidateSet[candidateA] = 0; // Ensure A != B

        bool consistent = true;

        for (const auto& exp : experiments) {
            int aEntry = exp.entryTime[candidateA];
            int aExit = exp.exitTime[candidateA];
            bool mustBeInSubtree = (exp.answer == 1);

            // Iterate over remaining candidates
            for (int candidateB = candidateSet._Find_first(); candidateB < nodes; 
                 candidateB = candidateSet._Find_next(candidateB)) {
                int bEntry = exp.entryTime[candidateB];
                bool isWithinSubtree = (bEntry >= aEntry && bEntry <= aExit);

                if (mustBeInSubtree != isWithinSubtree) {
                    candidateSet[candidateB] = 0;
                }
            }

            if (candidateSet.none()) {
                consistent = false;
                break;
            }
        }

        if (consistent) {
            nodeA = candidateA;
            nodeB = candidateSet._Find_first();
            break;
        }
    }

    cout << "1 " << nodeA << " " << nodeB << endl;

    return 0;
}

