void io_context_run(io_context* ioc)
{
  ioc->run();
}

void strand_test()
{
  io_context ioc;
  io_context::strand s(ioc);
  int count = 0;

  post(ioc, bindns::bind(increment_without_lock, &s, &count));
  ASIO_CHECK(count == 0);
  ioc.run();
  ASIO_CHECK(count == 1);

  count = 0;
  ioc.restart();
  post(s, bindns::bind(increment_with_lock, &s, &count));
  ASIO_CHECK(count == 0);
  ioc.run();
  ASIO_CHECK(count == 1);

  count = 0;
  ioc.restart();
  post(ioc, bindns::bind(start_sleep_increments, &ioc, &s, &count));

  thread thread1(bindns::bind(io_context_run, &ioc));
  thread thread2(bindns::bind(io_context_run, &ioc));

  timer timer1(ioc, chronons::seconds(3));
  timer1.wait();
  ASIO_CHECK(count == 0);

#if defined(ASIO_HAS_BOOST_DATE_TIME)
  timer1.expires_at(timer1.expires_at() + chronons::seconds(2));
#else
  timer1.expires_at(timer1.expiry() + chronons::seconds(2));
#endif
  timer1.wait();
  ASIO_CHECK(count == 1);

#if defined(ASIO_HAS_BOOST_DATE_TIME)
  timer1.expires_at(timer1.expires_at() + chronons::seconds(2));
#else
  timer1.expires_at(timer1.expiry() + chronons::seconds(2));
#endif
  timer1.wait();
  ASIO_CHECK(count == 2);

  thread1.join();
  thread2.join();
  ASIO_CHECK(count == 3);

  count = 0;
  int exception_count = 0;
  ioc.restart();

  post(s, throw_exception);
  post(s, bindns::bind(increment, &count));
  post(s, bindns::bind(increment, &count));
  post(s, throw_exception);
  post(s, bindns::bind(increment, &count));

  ASIO_CHECK(count == 0);
  ASIO_CHECK(exception_count == 0);

  for (;;)
  {
    try
    {
      ioc.run();
      break;
    }
    catch (int)
    {
      ++exception_count;
    }
  }

  ASIO_CHECK(count == 3);
  ASIO_CHECK(exception_count == 2);

  count = 0;
  ioc.restart();

  {
    io_context::strand s2(ioc);
    post(s2, bindns::bind(increment, &count));
    post(s2, bindns::bind(increment, &count));
    post(s2, bindns::bind(increment, &count));
  }

  ASIO_CHECK(count == 0);
}

void strand_wrap_test()
{
#if !defined(ASIO_NO_DEPRECATED)
  io_context ioc;
  io_context::strand s(ioc);
  int count = 0;

  s.wrap(bindns::bind(increment, &count))();
  ASIO_CHECK(count == 0);

  ioc.restart();
  ioc.run();
  ASIO_CHECK(count == 1);

  count = 0;
  s.wrap(increment)(&count);
  ASIO_CHECK(count == 0);

  ioc.restart();
  ioc.run();
  ASIO_CHECK(count == 1);

  count = 0;
  s.wrap(increment_by_a)(&count, 1);
  ASIO_CHECK(count == 0);

  ioc.restart();
  ioc.run();
  ASIO_CHECK(count == 1);

  count = 0;
  s.wrap(increment_by_a_b)(&count, 1, 2);
  ASIO_CHECK(count == 0);

  ioc.restart();
  ioc.run();
  ASIO_CHECK(count == 3);

  count = 0;
  s.wrap(increment_by_a_b_c)(&count, 1, 2, 3);
  ASIO_CHECK(count == 0);

  ioc.restart();
  ioc.run();
  ASIO_CHECK(count == 6);

  count = 0;
  s.wrap(increment_by_a_b_c_d)(&count, 1, 2, 3, 4);
  ASIO_CHECK(count == 0);

  ioc.restart();
  ioc.run();
  ASIO_CHECK(count == 10);
#endif
}

