/// Computes the remainder of two signed integers, returning the result with the sign of the dividend.
/// The builder's insertion point should be at the original srem instruction.
static Value *computeSignedRemainder(Value *Numerator, Value *Denominator,
                                     IRBuilder<> &Builder) {
  unsigned Width = Numerator->getType()->getIntegerBitWidth();
  ConstantInt *ShiftAmount = Builder.getIntN(Width, Width - 1);

  Numerator = Builder.CreateFreeze(Numerator);
  Denominator = Builder.CreateFreeze(Denominator);

  Value *NumSign = Builder.CreateAShr(Numerator, ShiftAmount);
  Value *DenSign = Builder.CreateAShr(Denominator, ShiftAmount);

  Value *NumXor = Builder.CreateXor(Numerator, NumSign);
  Value *DenXor = Builder.CreateXor(Denominator, DenSign);

  Value *UnsignedNum = Builder.CreateSub(NumXor, NumSign);
  Value *UnsignedDen = Builder.CreateSub(DenXor, DenSign);

  Value *URemainder = Builder.CreateURem(UnsignedNum, UnsignedDen);
  Value *XoredResult = Builder.CreateXor(URemainder, NumSign);
  Value *SRemResult = Builder.CreateSub(XoredResult, NumSign);

  if (Instruction *URemInst = dyn_cast<Instruction>(URemainder))
    Builder.SetInsertPoint(URemInst);

  return SRemResult;
}

/// Computes the remainder of two unsigned integers.
/// The builder's insertion point should be at the original urem instruction.
static Value *computeUnsignedRemainder(Value *Numerator, Value *Denominator,
                                       IRBuilder<> &Builder) {
  Numerator = Builder.CreateFreeze(Numerator);
  Denominator = Builder.CreateFreeze(Denominator);

  Value *Quotient = Builder.CreateUDiv(Numerator, Denominator);
  Value *Product = Builder.CreateMul(Denominator, Quotient);
  Value *Remainder = Builder.CreateSub(Numerator, Product);

  if (Instruction *UDiv = dyn_cast<Instruction>(Quotient))
    Builder.SetInsertPoint(UDiv);

  return Remainder;
}

/// Computes the quotient of two signed integers, rounded toward zero.
/// The builder's insertion point should be at the original sdiv instruction.
static Value *computeSignedQuotient(Value *Numerator, Value *Denominator,
                                    IRBuilder<> &Builder) {
  unsigned Width = Numerator->getType()->getIntegerBitWidth();
  ConstantInt *ShiftAmount = Builder.getIntN(Width, Width - 1);

  Numerator = Builder.CreateFreeze(Numerator);
  Denominator = Builder.CreateFreeze(Denominator);

  Value *NumSign = Builder.CreateAShr(Numerator, ShiftAmount);
  Value *DenSign = Builder.CreateAShr(Denominator, ShiftAmount);

  Value *NumXor = Builder.CreateXor(NumSign, Numerator);
  Value *UnsignedNum = Builder.CreateSub(NumXor, NumSign);

  Value *DenXor = Builder.CreateXor(DenSign, Denominator);
  Value *UnsignedDen = Builder.CreateSub(DenXor, DenSign);

  Value *SignMask = Builder.CreateXor(NumSign, DenSign);
  Value *Magnitude = Builder.CreateUDiv(UnsignedNum, UnsignedDen);

  Value *XoredMag = Builder.CreateXor(Magnitude, SignMask);
  Value *Quotient = Builder.CreateSub(XoredMag, SignMask);

  if (Instruction *UDiv = dyn_cast<Instruction>(Magnitude))
    Builder.SetInsertPoint(UDiv);

  return Quotient;
}

/// Computes the quotient of two unsigned integers using a specialized algorithm.
static Value *computeUnsignedQuotient(Value *Numerator, Value *Denominator,
                                      IRBuilder<> &Builder) {
  IntegerType *DivType = cast<IntegerType>(Numerator->getType());
  unsigned BitWidth = DivType->getBitWidth();

  ConstantInt *Zero = ConstantInt::get(DivType, 0);
  ConstantInt *One = ConstantInt::get(DivType, 1);
  ConstantInt *NegOne = ConstantInt::getSigned(DivType, -1);
  ConstantInt *MSB = ConstantInt::get(DivType, BitWidth - 1);
  ConstantInt *TrueVal = Builder.getTrue();

  BasicBlock *OriginalBB = Builder.GetInsertBlock();
  Function *CurrentFunc = OriginalBB->getParent();

  Function *CTLZFunc = Intrinsic::getDeclaration(
      CurrentFunc->getParent(), Intrinsic::ctlz, DivType);

  // Split blocks for control flow
  BasicBlock *SpecialCases = OriginalBB;
  SpecialCases->setName(SpecialCases->getName().str("_udiv-special-cases"));

  BasicBlock *EndBB = SpecialCases->splitBasicBlock(Builder.GetInsertPoint(),
                                                    "udiv-end");
  BasicBlock *LoopExit = BasicBlock::Create(Builder.getContext(),
                                            "udiv-loop-exit", CurrentFunc, EndBB);
  BasicBlock *DoWhileLoop = BasicBlock::Create(Builder.getContext(),
                                               "udiv-do-while", CurrentFunc, EndBB);
  BasicBlock *PreHeader = BasicBlock::Create(Builder.getContext(),
                                             "udiv-preheader", CurrentFunc, EndBB);
  BasicBlock *BB1 = BasicBlock::Create(Builder.getContext(),
                                       "udiv-bb1", CurrentFunc, EndBB);

  // Remove old terminator and set up special case handling
  SpecialCases->getTerminator()->eraseFromParent();

  Builder.SetInsertPoint(SpecialCases);
  Numerator = Builder.CreateFreeze(Numerator);
  Denominator = Builder.CreateFreeze(Denominator);

  Value *IsZeroDivisor = Builder.CreateICmpEQ(Denominator, Zero);
  Value *IsZeroNumerator = Builder.CreateICmpEQ(Numerator, Zero);
  Value *EitherZero = Builder.CreateOr(IsZeroDivisor, IsZeroNumerator);

  Value *LeadingZerosDen = Builder.CreateCall(CTLZFunc, {Denominator, TrueVal});
  Value *LeadingZerosNum = Builder.CreateCall(CTLZFunc, {Numerator, TrueVal});
  Value *ShiftDiff = Builder.CreateSub(LeadingZerosDen, LeadingZerosNum);

  Value *IsLargeShift = Builder.CreateICmpUGT(ShiftDiff, MSB);
  Value *ShouldReturnZero = Builder.CreateLogicalOr(EitherZero, IsLargeShift);
  Value *ShouldReturnNumerator = Builder.CreateICmpEQ(ShiftDiff, MSB);
  Value *DefaultValue = Builder.CreateSelect(ShouldReturnZero, Zero, Numerator);
  Value *EarlyExit = Builder.CreateLogicalOr(ShouldReturnZero, ShouldReturnNumerator);

  Builder.CreateCondBr(EarlyExit, EndBB, BB1);

  // BB1 setup
  Builder.SetInsertPoint(BB1);
  Value *ShiftPlusOne = Builder.CreateAdd(ShiftDiff, One);
  Value *ShiftComplement = Builder.CreateSub(MSB, ShiftDiff);
  Value *InitialQuotient = Builder.CreateShl(Numerator, ShiftComplement);
  Value *SkipLoop = Builder.CreateICmpEQ(ShiftPlusOne, Zero);

  Builder.CreateCondBr(SkipLoop, LoopExit, PreHeader);

  // Preheader setup
  Builder.SetInsertPoint(PreHeader);
  Value *ShiftedNumerator = Builder.CreateLShr(Numerator, ShiftPlusOne);
  Value *DecrementDenom = Builder.CreateAdd(Denominator, NegOne);
  Builder.CreateBr(DoWhileLoop);

  // Do-while loop setup
  Builder.SetInsertPoint(DoWhileLoop);
  PHINode *CarryPhi = Builder.CreatePHI(DivType, 2);
  PHINode *ShiftPhi = Builder.CreatePHI(DivType, 2);
  PHINode *RemainderPhi = Builder.CreatePHI(DivType, 2);
  PHINode *QuotientPhi = Builder.CreatePHI(DivType, 2);

  Value *Temp1 = Builder.CreateShl(RemainderPhi, One);
  Value *Temp2 = Builder.CreateLShr(QuotientPhi, MSB);
  Value *Temp3 = Builder.CreateOr(Temp1, Temp2);
  Value *Temp4 = Builder.CreateShl(QuotientPhi, One);
  Value *NewQuotient = Builder.CreateOr(CarryPhi, Temp4);
  Value *Temp5 = Builder.CreateSub(DecrementDenom, Temp3);
  Value *Temp6 = Builder.CreateAShr(Temp5, MSB);
  Value *NewCarry = Builder.CreateAnd(Temp6, One);
  Value *Temp7 = Builder.CreateAnd(Temp6, Denominator);
  Value *NewRemainder = Builder.CreateSub(Temp3, Temp7);
  Value *NewShift = Builder.CreateAdd(ShiftPhi, NegOne);
  Value *LoopCondition = Builder.CreateICmpEQ(NewShift, Zero);

  Builder.CreateCondBr(LoopCondition, LoopExit, DoWhileLoop);

  // Loop exit setup
  Builder.SetInsertPoint(LoopExit);
  PHINode *FinalCarry = Builder.CreatePHI(DivType, 2);
  PHINode *FinalQuotient = Builder.CreatePHI(DivType, 2);

  Value *ShiftedFinal = Builder.CreateShl(FinalQuotient, One);
  Value *FinalResult = Builder.CreateOr(FinalCarry, ShiftedFinal);
  Builder.CreateBr(EndBB);

  // End block setup
  Builder.SetInsertPoint(EndBB, EndBB->begin());
  PHINode *FinalOutput = Builder.CreatePHI(DivType, 2);

  // Populate PHI nodes
  CarryPhi->addIncoming(Zero, PreHeader);
  CarryPhi->addIncoming(NewCarry, DoWhileLoop);

  ShiftPhi->addIncoming(ShiftPlusOne, PreHeader);
  ShiftPhi->addIncoming(NewShift, DoWhileLoop);

  RemainderPhi->addIncoming(ShiftedNumerator, PreHeader);
  RemainderPhi->addIncoming(NewRemainder, DoWhileLoop);

  QuotientPhi->addIncoming(InitialQuotient, PreHeader);
  QuotientPhi->addIncoming(NewQuotient, DoWhileLoop);

  FinalCarry->addIncoming(Zero, BB1);
  FinalCarry->addIncoming(NewCarry, DoWhileLoop);

  FinalQuotient->addIncoming(InitialQuotient, BB1);
  FinalQuotient->addIncoming(NewQuotient, DoWhileLoop);

  FinalOutput->addIncoming(FinalResult, LoopExit);
  FinalOutput->addIncoming(DefaultValue, SpecialCases);

  return FinalOutput;
}

/// Replace a remainder operation with generated code.
bool llvm::expandRemainder(BinaryOperator *Rem) {
  assert((Rem->getOpcode() == Instruction::SRem ||
          Rem->getOpcode() == Instruction::URem) &&
         "Trying to expand remainder from a non-remainder function");

  IRBuilder<> Builder(Rem);
  assert(!Rem->getType()->isVectorTy() && "Div over vectors not supported");

  if (Rem->getOpcode() == Instruction::SRem) {
    Value *Result = computeSignedRemainder(Rem->getOperand(0),
                                           Rem->getOperand(1), Builder);

    bool WasInsertPoint = Rem->getIterator() == Builder.GetInsertPoint();
    Rem->replaceAllUsesWith(Result);
    Rem->dropAllReferences();
    Rem->eraseFromParent();

    if (WasInsertPoint)
      return true;

    BinaryOperator *BO = dyn_cast<BinaryOperator>(Builder.GetInsertPoint());
    Rem = BO;
  }

  Value *Result = computeUnsignedRemainder(Rem->getOperand(0),
                                           Rem->getOperand(1), Builder);
  Rem->replaceAllUsesWith(Result);
  Rem->dropAllReferences();
  Rem->eraseFromParent();

  if (BinaryOperator *UDiv = dyn_cast<BinaryOperator>(Builder.GetInsertPoint())) {
    assert(UDiv->getOpcode() == Instruction::UDiv && "Non-udiv in expansion?");
    expandDivision(UDiv);
  }

  return true;
}

/// Replace a division operation with generated code.
bool llvm::expandDivision(BinaryOperator *Div) {
  assert((Div->getOpcode() == Instruction::SDiv ||
          Div->getOpcode() == Instruction::UDiv) &&
         "Trying to expand division from a non-division function");

  IRBuilder<> Builder(Div);
  assert(!Div->getType()->isVectorTy() && "Div over vectors not supported");

  if (Div->getOpcode() == Instruction::SDiv) {
    Value *Result = computeSignedQuotient(Div->getOperand(0),
                                          Div->getOperand(1), Builder);

    bool WasInsertPoint = Div->getIterator() == Builder.GetInsertPoint();
    Div->replaceAllUsesWith(Result);
    Div->dropAllReferences();
    Div->eraseFromParent();

    if (WasInsertPoint)
      return true;

    BinaryOperator *BO = dyn_cast<BinaryOperator>(Builder.GetInsertPoint());
    Div = BO;
  }

  Value *Result = computeUnsignedQuotient(Div->getOperand(0),
                                          Div->getOperand(1), Builder);
  Div->replaceAllUsesWith(Result);
  Div->dropAllReferences();
  Div->eraseFromParent();

  return true;
}

/// Handle remainders for types up to 32 bits by extending to 32-bit operations.
bool llvm::expandRemainderUpTo32Bits(BinaryOperator *Rem) {
  assert((Rem->getOpcode() == Instruction::SRem ||
          Rem->getOpcode() == Instruction::URem) &&
         "Trying to expand remainder from a non-remainder function");

  Type *RemType = Rem->getType();
  assert(!RemType->isVectorTy() && "Div over vectors not supported");

  unsigned BitWidth = RemType->getIntegerBitWidth();
  assert(BitWidth <= 32 && "Div of bitwidth greater than 32 not supported");

  if (BitWidth == 32)
    return expandRemainder(Rem);

  IRBuilder<> Builder(Rem);
  Type *Int32Type = Builder.getInt32Ty();

  Value *ExtendedNumerator, *ExtendedDenominator, *ExtendedRem, *Truncated;

  if (Rem->getOpcode() == Instruction::SRem) {
    ExtendedNumerator = Builder.CreateSExt(Rem->getOperand(0), Int32Type);
    ExtendedDenominator = Builder.CreateSExt(Rem->getOperand(1), Int32Type);
    ExtendedRem = Builder.CreateSRem(ExtendedNumerator, ExtendedDenominator);
  } else {
    ExtendedNumerator = Builder.CreateZExt(Rem->getOperand(0), Int32Type);
    ExtendedDenominator = Builder.CreateZExt(Rem->getOperand(1), Int32Type);
    ExtendedRem = Builder.CreateURem(ExtendedNumerator, ExtendedDenominator);
  }

  Truncated = Builder.CreateTrunc(ExtendedRem, RemType);
  Rem->replaceAllUsesWith(Truncated);
  Rem->dropAllReferences();
  Rem->eraseFromParent();

  return expandRemainder(cast<BinaryOperator>(ExtendedRem));
}

