#include "proj_internal.h"
#include <math.h>

// Meridional distance computation for ellipsoid using 6th-order expansion in the third flattening n
// Provides full double precision for |f| <= 1/150
#define MaxOrder 6

// Evaluate polynomial using Horner's scheme: sum(p[i] * x^i, i, 0, N)
// Array p has length N+1
static double evaluate_polynomial(double x, const double coefficients[], int degree) {
    double result = degree < 0 ? 0.0 : coefficients[degree];
    while (degree > 0) {
        result = result * x + coefficients[--degree];
    }
    return result;
}

// Compute sum(c[k] * sin((2*k+2) * zeta), k, 0, K-1) using Clenshaw summation
static double clenshaw_sum(double sin_zeta, double cos_zeta, const double coeffs[], int terms) {
    // Approximate operation count: (terms + 5) multiplications and (2 * terms + 2) additions
    double accumulator0 = 0.0, accumulator1 = 0.0;  // Accumulators for the recurrence
    double X = 2.0 * (cos_zeta - sin_zeta) * (cos_zeta + sin_zeta); // 2 * cos(2*zeta)

    while (terms > 0) {
        double temp = X * accumulator0 - accumulator1 + coeffs[--terms];
        accumulator1 = accumulator0;
        accumulator0 = temp;
    }
    return 2.0 * sin_zeta * cos_zeta * accumulator0; // sin(2*zeta) * accumulator0
}

// Precompute expansion coefficients for meridional distance calculations
double *pj_enfn(double flattening_n) {
    // Coefficients for series expansion of (quarter meridian) / ((a+b)/2 * pi/2) in n^2
    // Coefficient formula: ( (2*k - 3)!! / (2*k)!! )^2 for k = 0..3
    static const double radial_coeff[] = {1.0, 1.0 / 4.0, 1.0 / 64.0, 1.0 / 256.0};

    // Coefficients to convert geographic latitude phi to reduced latitude mu (Eq. A5 in arXiv:2212.05818)
    // Zero terms omitted for efficiency
    static const double phi_to_mu_coeff[] = {
        -3.0 / 2.0,    9.0 / 16.0,     -3.0 / 32.0,     15.0 / 16.0,
        -15.0 / 32.0,  135.0 / 2048.0, -35.0 / 48.0,    105.0 / 256.0,
        315.0 / 512.0, -189.0 / 512.0, -693.0 / 1280.0, 1001.0 / 2048.0
    };

    // Coefficients to convert reduced latitude mu back to geographic latitude phi (Eq. A6 in arXiv:2212.05818)
    // Zero terms omitted for efficiency
    static const double mu_to_phi_coeff[] = {
        3.0 / 2.0,      -27.0 / 32.0,      269.0 / 512.0,   21.0 / 16.0,
        -55.0 / 32.0,   6759.0 / 4096.0,   151.0 / 96.0,    -417.0 / 128.0,
        1097.0 / 512.0, -15543.0 / 2560.0, 8011.0 / 2560.0, 293393.0 / 61440.0
    };

    double n_squared = flattening_n * flattening_n;
    double power_n = flattening_n;
    double *expansion_table;

    // Allocate memory: 2*MaxOrder for Fourier coefficients + 1 for overall scaling factor
    expansion_table = (double *)malloc((2 * MaxOrder + 1) * sizeof(double));
    if (nullptr == expansion_table)
        return nullptr;

    // Compute overall scaling factor
    expansion_table[0] = evaluate_polynomial(n_squared, radial_coeff, MaxOrder / 2) / (1.0 + flattening_n);

    // Fill remaining entries with Fourier coefficients for both directions
    for (int order = 0, offset = 0; order < MaxOrder; ++order) {
        int sub_degree = (MaxOrder - order - 1) / 2;
        expansion_table[order + 1] = power_n * evaluate_polynomial(n_squared, phi_to_mu_coeff + offset, sub_degree);
        expansion_table[order + 1 + MaxOrder] = power_n * evaluate_polynomial(n_squared, mu_to_phi_coeff + offset, sub_degree);
        power_n *= flattening_n;
        offset += sub_degree + 1;
    }

    return expansion_table;
}

// Compute meridional distance function
double pj_mlfn(double lat_phi, double sin_lat, double cos_lat, const double *expansion) {
    return expansion[0] * (lat_phi + clenshaw_sum(sin_lat, cos_lat, expansion + 1, MaxOrder));
}

// Inverse meridional distance function
double pj_inv_mlfn(double reduced_mu, const double *expansion) {
    reduced_mu /= expansion[0];
    return reduced_mu + clenshaw_sum(sin(reduced_mu), cos(reduced_mu), expansion + 1 + MaxOrder, MaxOrder);
}

