#include <math.h>
#include <assert.h>
#include "PeakFinder.h"
using namespace soundtouch;
#define max(a, b) (((a) > (b)) ? (a) : (b))
PeakFinder::PeakFinder()
{
    minPosition = maxPosition = 0;
}
// Locates the 'baseline' of a peak hump by starting from 'peakIndex' and moving
// in the direction specified by 'step' until the next 'hump' after the minimum value 
// starts rising again
int PeakFinder::findGround(const float *signal, int peakIndex, int step) const
{
    float referenceValue;
    int lowestPosition;
    int currentIndex;
    int climbCounter;
    float slope;
    climbCounter = 0;
    referenceValue = signal[peakIndex];
    lowestPosition = peakIndex;
    currentIndex = peakIndex;
    while ((currentIndex > minPosition) && (currentIndex < maxPosition))
    {
        int previousIndex;
        previousIndex = currentIndex;
        currentIndex += step;
        // compute derivative
        slope = signal[currentIndex] - signal[previousIndex];
        if (slope <= 0)
        {
            // descending, acceptable
            if (climbCounter)
            {
                climbCounter --;  // decrement climb counter
            }
            // check for new minimum
            if (signal[currentIndex] < referenceValue)
            {
                // new minimum located
                lowestPosition = currentIndex;
                referenceValue = signal[currentIndex];
            }
        }
        else
        {
            // ascending, increment climbing counter
            climbCounter ++;
            if (climbCounter > 5) break;    // prolonged ascent => next uphill segment => exit
        }
    }
    return lowestPosition;
}
// Determines the index where the signal crosses the specified threshold, starting from 'peakIndex' and
// moving in the direction indicated by 'step'
int PeakFinder::findCrossingLevel(const float *signal, float threshold, int peakIndex, int step) const
{
    float peakMagnitude;
    int currentIndex;
    peakMagnitude = signal[peakIndex];
    assert(peakMagnitude >= threshold);
    currentIndex = peakIndex;
    while ((currentIndex >= minPosition) && (currentIndex < maxPosition))
    {
        if (signal[currentIndex + step] < threshold) return currentIndex;   // crossing detected
        currentIndex += step;
    }
    return -1;  // no crossing found
}
// Computes the center-of-mass position of 'signal' array elements between 'startPos' and 'endPos'
double PeakFinder::calcMassCenter(const float *signal, int startPos, int endPos) const
{
    int idx;
    float totalWeight;
    float weightedSum;
    totalWeight = 0;
    weightedSum = 0;
    for (idx = startPos; idx <= endPos; idx ++)
    {
        weightedSum += (float)idx * signal[idx];
        totalWeight += signal[idx];
    }
    if (totalWeight < 1e-6) return 0;
    return weightedSum / totalWeight;
}
/// Determine precise center of peak near given position by analyzing local mass distribution
double PeakFinder::getPeakCenter(const float *signal, int peakIndex) const
{
    float peakMagnitude;            // magnitude at peak
    int crossPos1, crossPos2;       // indices where the peak 'hump' intersects the cutoff level
    float cutoffLevel;              // threshold value
    float baselineLevel;            // baseline magnitude of the peak
    int gp1, gp2;                   // bottom positions of the peak 'hump'
    // locate baseline positions.
    gp1 = findGround(signal, peakIndex, -1);
    gp2 = findGround(signal, peakIndex, 1);
    baselineLevel = max(signal[gp1], signal[gp2]);
    peakMagnitude = signal[peakIndex];
    if (baselineLevel < 1e-6) return 0;                // baseline too weak => detection failure
    if ((peakMagnitude / baselineLevel) < 1.3) return 0;   // peak less than 30% above baseline => insufficient peak
    // compute 70%-level of the peak
    cutoffLevel = 0.70f * peakMagnitude + 0.30f * baselineLevel;
    // locate mid-level crossings
    crossPos1 = findCrossingLevel(signal, cutoffLevel, peakIndex, -1);
    crossPos2 = findCrossingLevel(signal, cutoffLevel, peakIndex, 1);
    if ((crossPos1 < 0) || (crossPos2 < 0)) return 0;   // no crossing points => not a valid peak
    // compute mass center around the peak region
    return calcMassCenter(signal, crossPos1, crossPos2);
}
double PeakFinder::detectPeak(const float *signal, int aminPos, int amaxPos) 
{
    int idx;
    int peakIndex;                // index of maximum amplitude
    double bestPeak, currentPeak;
    this->minPosition = aminPos;
    this->maxPosition = amaxPos;
    // locate absolute peak
    peakIndex = minPosition;
    currentPeak = signal[minPosition];
    for (idx = minPosition + 1; idx < maxPosition; idx ++)
    {
        if (signal[idx] > currentPeak) 
        {
            currentPeak = signal[idx];
            peakIndex = idx;
        }
    }

    // Compute precise location of the dominant peak using mass center
    bestPeak = getPeakCenter(signal, peakIndex);
    currentPeak = bestPeak;
    // Verify whether the strongest peak might be a harmonic of the actual fundamental beat peak 
    // - occasionally the strongest peak could be the Nth harmonic of the true base peak yet 
    // only marginally higher than the true base
    for (idx = 2; idx < 10; idx ++)
    {
        double candidatePeak, tempResult;
        int i1,i2;
        peakIndex = (int)(bestPeak / (double)idx + 0.5f);
        if (peakIndex < minPosition) break;
        // compute mass-center of potential fundamental peak
        candidatePeak = getPeakCenter(signal, peakIndex);
        // compare with highest detected peak
        i1 = (int)(bestPeak + 0.5);
        i2 = (int)(candidatePeak + 0.5);
        tempResult = 2 * (signal[i2] - signal[i1]) / (signal[i2] + signal[i1]);
        if (fabs(tempResult) < 0.1)
        {
            // The strongest peak is likely a harmonic of a nearly equally strong fundamental,
            // so prefer the fundamental instead
            currentPeak = candidatePeak;
        }
    }
    return currentPeak;
}

