#include "utl/BinStream.h"
#include "math/Rand.h"
#include "math/Rand2.h"
#include "obj/Object.h"
#include "os/Debug.h"
#include "os/Endian.h"
#include "os/Timer.h"
#include <vector>

// Buffer size for encryption operations
#define ENCRYPT_BUFFER_SIZE 1024

// Returns the name of the stream
const char *BinStream::Name() const { 
    return "<unnamed>"; 
}

// Constructor initializes member variables
BinStream::BinStream(bool isLittleEndian) : mLittleEndian(isLittleEndian), mCrypto(nullptr), mRevStack(nullptr) {}

// Swaps data byte order based on size (2, 4, or 8 bytes)
void SwapData(const void *source, void *destination, int sizeInBytes) {
    switch (sizeInBytes) {
    case 2: {
        unsigned short *src = (unsigned short *)source;
        unsigned short *dst = (unsigned short *)destination;
        *dst = EndianSwap(*src);
        break;
    }
    case 4: {
        unsigned int *src = (unsigned int *)source;
        unsigned int *dst = (unsigned int *)destination;
        *dst = EndianSwap(*src);
        break;
    }
    case 8: {
        unsigned long long *src = (unsigned long long *)source;
        unsigned long long *dst = (unsigned long long *)destination;
        *dst = EndianSwap(*src);
        break;
    }
    default:
        MILO_ASSERT(0, 0xAC);
        break;
    }
}

// Disables encryption by releasing the crypto object
void BinStream::DisableEncryption() {
    MILO_ASSERT(mCrypto, 0xDC);
    RELEASE(mCrypto);
}

// Writes data to the stream, optionally encrypting it
void BinStream::Write(const void *inputData, int byteCount) {
    if (Fail()) {
        MILO_PRINT_ONCE("Stream error: Can't write to %s\n", Name());
    } else {
        const unsigned char *buffer = (u8 *)inputData;
        if (!mCrypto) {
            WriteImpl(inputData, byteCount);
        } else {
            char encryptedBuffer[ENCRYPT_BUFFER_SIZE];
            int remaining = byteCount;

            while (remaining > 0) {
                int chunkSize = Min(ENCRYPT_BUFFER_SIZE, remaining);

                for (int index = 0; index < chunkSize; index++) {
                    u8 randomByte = mCrypto->Int();
                    encryptedBuffer[index] = buffer[index] ^ randomByte;
                }

                WriteImpl(encryptedBuffer, chunkSize);
                remaining -= chunkSize;
                buffer += chunkSize;
            }
        }
    }
}

// Seeks to a position in the stream
void BinStream::Seek(int offset, SeekType direction) {
    MILO_ASSERT(!Fail(), 0x11F);
    MILO_ASSERT(!mCrypto, 0x122);
    SeekImpl(offset, direction);
}

// Writes data with endianness conversion
void BinStream::WriteEndian(const void *inputData, int sizeInBytes) {
    if (mLittleEndian) {
        u64 tempBuffer[2]; // 128 bits of temporary storage
        SwapData(inputData, tempBuffer, sizeInBytes);
        Write(tempBuffer, sizeInBytes);
    } else {
        Write(inputData, sizeInBytes);
    }
}

// Adds shared inline - only available in PC dev builds
bool BinStream::AddSharedInlined(const class FilePath &) {
    MILO_FAIL("BinStream::AddSharedInlined is a PC dev tool only !!");
    return false;
}

// Writes a null-terminated string to the stream
BinStream &BinStream::operator<<(const char *text) {
    MILO_ASSERT(text, 0x60);
    int length = strlen(text);
    *this << length;
    Write(text, length);
    return *this;
}

// Writes a Symbol object to the stream
BinStream &BinStream::operator<<(const Symbol &symbol) {
    const char *text = symbol.Str();
    unsigned int len = strlen(text);
    MILO_ASSERT(len < ENCRYPT_BUFFER_SIZE, 0x6C);
    *this << len;
    Write(text, len);
    return *this;
}

// Writes a String object to the stream
BinStream &BinStream::operator<<(const class String &str) {
    int length = str.length();
    *this << length;
    Write(str.c_str(), length);
    return *this;
}

// Enables write encryption using a random seed
void BinStream::EnableWriteEncryption() {
    MILO_ASSERT(!mCrypto, 0xC8);
    int seed = RandomInt();
    *this << seed;
    mCrypto = new Rand2(seed);
}

// Pops an object from the revision stack
int BinStream::PopRev(Hmx::Object *targetObj) {
    MILO_ASSERT(mRevStack, 0x34);
    ObjVersion *currentEntry = &mRevStack->back();

    while (currentEntry->obj == nullptr) {
        MILO_NOTIFY("hey object got deleted!");
        mRevStack->pop_back();
        currentEntry = &mRevStack->back();
    }

    int revisionCount = currentEntry->revs;

    if (targetObj != currentEntry->obj) {
        MILO_LOG("rev stack $this mismatch (%08x != %08x\n", targetObj, currentEntry->obj);
        MILO_LOG("curr obj: %s %s\n", targetObj->ClassName(), PathName(targetObj));
        MILO_LOG("stack obj: %s %s\n", currentEntry->obj->ClassName(), PathName(currentEntry->obj));
        MILO_FAIL(
            "rev stack (%08x %s %s != %08x %s %s)\n",
            targetObj,
            targetObj->ClassName(),
            PathName(targetObj),
            currentEntry->obj,
            currentEntry->obj->ClassName(),
            PathName(currentEntry->obj)
        );
    }

    mRevStack->pop_back();
    return revisionCount;
}

// Reads data from the stream
void BinStream::Read(void *outputData, int byteCount) {
    if (Fail()) {
        MILO_NOTIFY_ONCE("Stream error: Can't read from %s", Name());
        memset(outputData, 0, byteCount);
    } else {
        AutoGlitchReport report(50.0f, __FUNCTION__);
        ReadImpl(outputData, byteCount);

        if (mCrypto) {
            for (unsigned char *ptr = (unsigned char *)outputData;
                 ptr < (unsigned char *)outputData + byteCount;
                 ptr++) {
                unsigned char cryptoValue = mCrypto->Int();
                *ptr ^= cryptoValue;
            }
        }
    }
}

// Asynchronous read operation
int BinStream::ReadAsync(void *buffer, int count) {
    Read(buffer, count);
    return Fail() ? 0 : count;
}

// Reads data with endianness conversion
void BinStream::ReadEndian(void *destination, int sizeInBytes) {
    Read(destination, sizeInBytes);
    if (mLittleEndian) {
        SwapData(destination, destination, sizeInBytes);
    }
}

// Reads a string from the stream
void BinStream::ReadString(char *buffer, int bufferSize) {
    unsigned int stringLength;
    *this >> stringLength;

    if (stringLength >= bufferSize)
        MILO_FAIL("String chars %d > %d", stringLength + 1, bufferSize);

    Read(buffer, stringLength);
    buffer[stringLength] = 0;
}

// Reads a Symbol from the stream
BinStream &BinStream::operator>>(Symbol &symbol) {
    char tempBuffer[ENCRYPT_BUFFER_SIZE];
    ReadString(tempBuffer, ENCRYPT_BUFFER_SIZE);
    symbol = tempBuffer;
    return *this;
}

// Reads a String from the stream
BinStream &BinStream::operator>>(String &str) {
    int size;
    *this >> size;
    str.resize(size);
    Read((void *)str.c_str(), size);
    return *this;
}

// Enables read encryption using a seed from the stream
void BinStream::EnableReadEncryption() {
    MILO_ASSERT(!mCrypto, 0xC0);
    int seed;
    *this >> seed;
    mCrypto = new Rand2(seed);
}

// Destructor cleans up resources
BinStream::~BinStream() {
    delete mCrypto;
    delete mRevStack;
}

// Pushes an object onto the revision stack
void BinStream::PushRev(int revisions, Hmx::Object *object) {
    if (!mRevStack) {
        mRevStack = new std::vector<ObjVersion>();
    }
    mRevStack->push_back(ObjVersion(revisions, object));
}

