#define I2C_ADDRESS 0x3C      // I2C address of the display (some modules use 0x3D)

// Create display object with specified dimensions and I2C interface
Adafruit_SSD1306 oledScreen(DISPLAY_WIDTH, DISPLAY_HEIGHT, &Wire, RESET_PIN);

void setup() {
  Serial.begin(115200);

  // Initialize I2C communication on pins SDA=21 and SCL=22
  Wire.begin(21, 22);

  // Initialize the OLED display
  if (!oledScreen.begin(SSD1306_SWITCHCAPVCC, I2C_ADDRESS)) {
    Serial.println(F("OLED initialization failed"));
    while (true) {
      ; // Halt execution if display fails to initialize
    }
  }

  // Clear the display buffer
  oledScreen.clearDisplay();

  // Set text formatting
  oledScreen.setTextSize(1);
  oledScreen.setTextColor(SSD1306_WHITE);
  oledScreen.setCursor(2, 10);
  oledScreen.println(F("Hello, ESP32!"));

  oledScreen.setCursor(2, 25);

  // Draw a white rectangle as background for second line
  oledScreen.fillRect(0, 24, DISPLAY_WIDTH, 10, SSD1306_WHITE);

  // Switch to black text for overlay
  oledScreen.setTextColor(SSD1306_BLACK);
  oledScreen.println(F("OLED Test"));

  // Update the physical display with buffered content
  oledScreen.display();
}

