#include "average_onto_vertices.h"
template<typename DerivedV,typename DerivedF,typename DerivedS>
IGL_INLINE void igl::average_onto_vertices(const Eigen::MatrixBase<DerivedV> &vertices,
  const Eigen::MatrixBase<DerivedF> &faces,
  const Eigen::MatrixBase<DerivedS> &values,
  Eigen::MatrixBase<DerivedS> &vertex_values)
{
  vertex_values = DerivedS::Zero(vertices.rows(), values.cols());
  Eigen::Matrix<typename DerivedF::Scalar,Eigen::Dynamic,1> counts(vertices.rows());
  counts.setZero();
  for (int face_idx = 0; face_idx < faces.rows(); ++face_idx)
  {
    for (int vert_idx = 0; vert_idx < faces.cols(); ++vert_idx)
    {
      vertex_values.row(faces(face_idx, vert_idx)) += values.row(face_idx);
      counts[faces(face_idx, vert_idx)]++;
    }
  }
  for (int i = 0; i < vertices.rows(); ++i)
    vertex_values.row(i) /= counts[i];
};
