    void unbindContext();

private:
    EGLSurface pbuffer_surface;
    EGLContext gl_context;
    EGLDisplay egl_display_handle;

    static constexpr EGLint configAttribs[] = {
        EGL_SURFACE_TYPE    , EGL_PBUFFER_BIT,
        EGL_RENDERABLE_TYPE , EGL_OPENGL_BIT,
        EGL_RED_SIZE        , 8,
        EGL_GREEN_SIZE      , 8,
        EGL_BLUE_SIZE       , 8,
        EGL_ALPHA_SIZE      , 8,
        EGL_DEPTH_SIZE      , 24,
        EGL_STENCIL_SIZE    , 8,
        EGL_NONE
    };
};

constexpr EGLint EGLBackendHL::configAttribs[];

struct HeadlessGLWindow : public WindowInterface {
    HeadlessGLWindow(const int width, const int height);
    ~HeadlessGLWindow() override;
    void ShowFullscreen(const TrueFalseToggle) override;
    void Move(const int /*x*/, const int /*y*/) override;
    void Resize(const unsigned int /*w*/, const unsigned int /*h*/) override;
    void MakeCurrent() override;
    void RemoveCurrent() override;
    void SwapBuffers() override;
    void ProcessEvents() override;
    EGLBackendHL backend;
};

EGLBackendHL::EGLBackendHL(const int width, const int height) {
    egl_display_handle = eglGetDisplay(EGL_DEFAULT_DISPLAY);
    if (!egl_display_handle) {
        std::cerr << "Failed to initialize EGL display" << std::endl;
    }

    EGLint major_ver, minor_ver;
    if (eglInitialize(egl_display_handle, &major_ver, &minor_ver) == EGL_FALSE) {
        std::cerr << "EGL initialization failed" << std::endl;
    }

    if (eglBindAPI(EGL_OPENGL_API) == EGL_FALSE) {
        std::cerr << "Failed to bind OpenGL API" << std::endl;
    }

    EGLint config_count;
    eglGetConfigs(egl_display_handle, nullptr, 0, &config_count);
    std::vector<EGLConfig> configs(config_count);
    EGLint matched_configs;
    eglChooseConfig(egl_display_handle, configAttribs, configs.data(), config_count, &matched_configs);

    gl_context = eglCreateContext(egl_display_handle, configs[0], EGL_NO_CONTEXT, nullptr);

    const EGLint pbufferAttrs[] = {
        EGL_WIDTH,  width,
        EGL_HEIGHT, height,
        EGL_NONE,
    };

    pbuffer_surface = eglCreatePbufferSurface(egl_display_handle, configs[0], pbufferAttrs);
    if (pbuffer_surface == EGL_NO_SURFACE) {
        std::cerr << "Unable to create EGL pbuffer surface" << std::endl;
    }
}

EGLBackendHL::~EGLBackendHL() {
    if (gl_context)     eglDestroyContext(egl_display_handle, gl_context);
    if (pbuffer_surface) eglDestroySurface(egl_display_handle, pbuffer_surface);
    if (egl_display_handle) eglTerminate(egl_display_handle);
}

void EGLBackendHL::flip() {
    eglSwapBuffers(egl_display_handle, pbuffer_surface);
}

void EGLBackendHL::bindContext() {
    eglMakeCurrent(egl_display_handle, pbuffer_surface, pbuffer_surface, gl_context);
}

void EGLBackendHL::unbindContext() {
    eglMakeCurrent(egl_display_handle, EGL_NO_SURFACE, EGL_NO_SURFACE, EGL_NO_CONTEXT);
}

