  RegisterTarget<Triple::aarch64, /*HasJIT=*/true> A(
      getTheAArch64leTarget(), "aarch64", "AArch64 (little endian)", "AArch64");

  // Register native AArch64 big-endian target with JIT support
  RegisterTarget<Triple::aarch64_be, /*HasJIT=*/true> B(
      getTheAArch64beTarget(), "aarch64_be", "AArch64 (big endian)", "AArch64");

  // Register AArch64 32-bit ILP32 little-endian target with JIT support
  RegisterTarget<Triple::aarch64_32, /*HasJIT=*/true> C(
      getTheAArch64_32Target(), "aarch64_32", "AArch64 (little endian ILP32)", "AArch64");
}

