// Duplicate a file descriptor to a specified target descriptor
int dup2(int src_fd, int dst_fd)
{
	int result;
#ifdef SYS_dup2
	// Use dup2 system call, retrying if busy
	while ((result=__syscall(SYS_dup2, src_fd, dst_fd))==-EBUSY);
#else
	// Fallback implementation using dup3 or fcntl
	if (src_fd == dst_fd) {
		result = __syscall(SYS_fcntl, src_fd, F_GETFD);
		if (result >= 0) return src_fd;
	} else {
		// Use dup3 with flags=0, retrying if busy
		while ((result=__syscall(SYS_dup3, src_fd, dst_fd, 0))==-EBUSY);
	}
#endif
	return __syscall_ret(result);
}

