int main(int argc, const char** argv) {
    const std::unordered_set<std::string_view> validSubcommands = {
        "start",
        "stop",
    };
    const std::unordered_set<std::string_view> specialFlags = {
        "-h",
        "--help",
    };

    std::vector<const char*> cmdArgs(argv, argv + argc);

    // If no explicit subcommand or help flag was provided, default to "start"
    const bool bypassInject = argc >= 2 && specialFlags.contains(argv[1]);
    if (!bypassInject && (argc < 2 || !validSubcommands.contains(argv[1]))) {
        cmdArgs.insert(cmdArgs.begin() + 1, "start");
    }

    argparse::ArgumentParser programParser("turingdb", "1.0", argparse::default_arguments::help);

    std::unique_ptr<StartCmd> startHandler = StartCmd::create();
    std::unique_ptr<StopCmd> stopHandler = StopCmd::create();

    programParser.add_argument("-v", "--version")
        .action([&](const auto& /*unused*/) {
            TuringDBCommitInfo();
            std::exit(0);
        })
        .default_value(false)
        .help("displays version info and terminates")
        .implicit_value(true)
        .nargs(0);

    programParser.add_subparser(startHandler->getArgParser());
    programParser.add_subparser(stopHandler->getArgParser());

    std::stringstream usageInfo;
    usageInfo << "\nBy default 'start' is triggered. Available options:\n" << startHandler->getArgParser();

    programParser.add_description("TuringDB - Graph Database Server");
    programParser.add_epilog(usageInfo.str());

    try {
        programParser.parse_args(cmdArgs.size(), cmdArgs.data());

        if (programParser.is_subcommand_used("start")) {
            return startHandler->execute();
        } else if (programParser.is_subcommand_used("stop")) {
            return stopHandler->execute();
        } else {
            // Should never happen since at least 'start' is always present
            throw FatalException("No subcommand specified.");
        }
    } catch (const std::exception& ex) {
        std::cerr << ex.what() << std::endl;
        std::cerr << programParser;
        return EXIT_FAILURE;
    }

    return EXIT_FAILURE;
}

