#include <string>
#include <algorithm>
using namespace std;

class Solution {
public:
    int countBinarySubstrings(string input) {
        int previousGroupLength = 0;   // length of the prior consecutive character group
        int currentGroupLength = 1;    // length of the ongoing consecutive character group
        int result = 0;

        for (int index = 1; index < input.length(); index++) {
            if (input[index] == input[index - 1]) {
                currentGroupLength++;  // continue same group, increment current count
            } else {
                result += min(previousGroupLength, currentGroupLength); // accumulate valid substrings
                previousGroupLength = currentGroupLength;               // shift current to previous
                currentGroupLength = 1;                                 // reset current group counter
            }
        }
        // account for final adjacent group pair
        result += min(previousGroupLength, currentGroupLength);
        return result;
    }
};

