void spring_mass_dynamics(double dt, int state_dim, int input_dim, int horizon_len, 
                          double *state_matrix, double *input_matrix, double *offset_vec, double *initial_state)
{
    int doubled_states = state_dim * state_dim;
    int mass_count = state_dim / 2;

    // Build continuous-time system matrices
    double *coupling_mat; d_zeros(&coupling_mat, mass_count, mass_count);
    for (int diag_idx = 0; diag_idx < mass_count; diag_idx++) {
        coupling_mat[diag_idx * (mass_count + 1)] = -2.0;
    }
    for (int off_diag = 0; off_diag < mass_count - 1; off_diag++) {
        coupling_mat[off_diag * (mass_count + 1) + 1] = 1.0;
        coupling_mat[(off_diag + 1) * (mass_count + 1) - 1] = 1.0;
    }

    double *zero_block; d_zeros(&zero_block, mass_count, mass_count);
    double *identity_block; d_zeros(&identity_block, mass_count, mass_count);
    for (int id_idx = 0; id_idx < mass_count; id_idx++) {
        identity_block[id_idx * (mass_count + 1)] = 1.0;
    }

    d_zeros(&state_matrix, state_dim, state_dim);
    dmcopy(mass_count, mass_count, zero_block, mass_count, state_matrix, state_dim);
    dmcopy(mass_count, mass_count, coupling_mat, mass_count, state_matrix + mass_count, state_dim);
    dmcopy(mass_count, mass_count, identity_block, mass_count, state_matrix + mass_count * state_dim, state_dim);
    dmcopy(mass_count, mass_count, zero_block, mass_count, state_matrix + mass_count * (state_dim + 1), state_dim);

    free(coupling_mat);
    free(zero_block);
    free(identity_block);

    // Input matrix construction
    d_zeros(&identity_block, input_dim, input_dim);
    for (int u_id = 0; u_id < input_dim; u_id++) {
        identity_block[u_id * (input_dim + 1)] = 1.0;
    }
    double *input_cont; d_zeros(&input_cont, state_dim, input_dim);
    dmcopy(input_dim, input_dim, identity_block, input_dim, input_cont + mass_count, state_dim);
    free(identity_block);

    // Discretization via matrix exponential
    double *temp_vec; d_zeros(&temp_vec, state_dim, 1);
    dmcopy(state_dim, 1, temp_vec, state_dim, offset_vec, state_dim);
    dmcopy(state_dim, state_dim, state_matrix, state_dim, state_matrix, state_dim);
    dscal_3l(doubled_states, dt, state_matrix);
    expm(state_dim, state_matrix);

    double *expm_copy; d_zeros(&expm_copy, state_dim, state_dim);
    d_zeros(&identity_block, state_dim, state_dim);
    for (int eye_idx = 0; eye_idx < state_dim; eye_idx++) {
        identity_block[eye_idx * (state_dim + 1)] = 1.0;
    }
    dmcopy(state_dim, state_dim, state_matrix, state_dim, expm_copy, state_dim);
    daxpy_3l(doubled_states, -1.0, identity_block, expm_copy);
    dgemm_nn_3l(state_dim, input_dim, state_dim, expm_copy, state_dim, input_cont, state_dim, input_matrix, state_dim);

    free(expm_copy);
    free(identity_block);

    int *pivot_list = (int *) malloc(state_dim * sizeof(int));
    int solve_info = 0;
    dgesv_3l(state_dim, input_dim, state_matrix, state_dim, pivot_list, input_matrix, state_dim, &solve_info);
    free(pivot_list);
    free(state_matrix);
    free(input_cont);
    free(temp_vec);

    // Set initial condition
    if (state_dim == 4) {
        initial_state[0] = 5.0;
        initial_state[1] = 10.0;
        initial_state[2] = 15.0;
        initial_state[3] = 20.0;
    } else {
        for (int idx = 0; idx < state_dim; idx++) {
            initial_state[idx] = 1.0;
        }
    }
