#include <iostream>
using namespace std;

// Definition for singly-linked list.
struct ListNode {
    int val;
    ListNode *next;
    ListNode(int x) : val(x), next(NULL) {}
};

class CycleDetector {
public:
    ListNode *findStartOfCycle(ListNode *head) {
        ListNode* runner = head;
        ListNode* walker = head;
        bool hasLoop = false;

        while(runner && runner->next) {
            runner = runner->next->next;
            walker = walker->next;

            if(runner == walker) {
                hasLoop = true;
                break;
            }
        }

        if(!hasLoop) {
            return NULL;
        }

        walker = head;
        while(walker != runner) {
            runner = runner->next;
            walker = walker->next;
        }

        return walker;
    }
};

int main() {
    // Create a linked list with a cycle
    ListNode* node1 = new ListNode(3);
    ListNode* node2 = new ListNode(2);
    ListNode* node3 = new ListNode(0);
    ListNode* node4 = new ListNode(-4);

    node1->next = node2;
    node2->next = node3;
    node3->next = node4;
    node4->next = node2; // Creates a cycle (last node points to the second node)

    CycleDetector detector;
    ListNode* cycleStart = detector.findStartOfCycle(node1);

    if (cycleStart) {
        cout << "The cycle begins at node with value: " << cycleStart->val << endl;
    } else {
        cout << "No cycle detected in the linked list." << endl;
    }

    // Note: In a real-world scenario, you should free the allocated memory.
    // However, since this list has a cycle, freeing memory would require breaking the cycle first.

    return 0;
}

