namespace rocjpeg
{
namespace
{
// Renamed function: get_rocjpeg_api_table_impl → get_api_table_instance
auto&
get_api_table_instance()
{
    static auto _api_table_ptr = std::atomic<rocjpegApiFuncTable*>{ nullptr };
    return _api_table_ptr;
}

void
register_profiler_core()
{
    // Renamed local variable: _const_api_table → base_api_table
    static auto base_api_table = rocjpegApiFuncTable{};
    initialize_rocjpeg_api_table(&base_api_table);

    // Set initial table before any recursive calls
    get_api_table_instance().exchange(&base_api_table);

    // Create modifiable copy for profiler instrumentation
    static auto instrumented_api_table = rocjpegApiFuncTable{};
    copy_rocjpeg_api_table(&instrumented_api_table, &base_api_table);

    void* instrumented_table_ptr = static_cast<void*>(&instrumented_api_table);
    rocprofiler_register_library_indentifier_t lib_id{};

    auto result = rocprofiler_register_library_api_table(
        "rocjpeg",
        &ROCPROFILER_REGISTER_IMPORT_FUNC(rocjpeg),
        ROCP_REG_VERSION,
        &instrumented_table_ptr,
        1,
        &lib_id);

    if(result == 0)
    {
        fprintf(stdout, "[%s] rocjpeg identifier %lu\n", ROCP_REG_FILE_NAME, lib_id.handle);

        auto* expected = &base_api_table;
        if(!get_api_table_instance().compare_exchange_strong(expected, &instrumented_api_table))
        {
            std::cerr << "[ERROR] register_profiler_core: API table mismatch — "
                         "expected internal implementation but got something else.\n";
            std::abort();
        }
    }
    else if(result != ROCP_REG_NO_TOOLS)
    {
        std::cerr << "[ROCJPEG] Registration failed: "
                  << rocprofiler_register_error_string(result) << "\n";
        std::exit(EXIT_FAILURE);
    }
}

// Renamed function: register_profiler → ensure_profiler_registered
void
ensure_profiler_registered()
{
    // Renamed atomic flag: _is_registered → _init_flag
    static auto _init_flag = std::atomic<bool>{ false };

    if(!_init_flag.load(std::memory_order_acquire))
    {
        using mutex_type      = std::recursive_mutex;
        using lock_type       = std::unique_lock<mutex_type>;
        static auto _flag_once = std::once_flag{};
        static auto _reg_mutex = mutex_type{};

        // Defer locking to check ownership first
        auto lk = lock_type{ _reg_mutex, std::defer_lock };

        // Avoid deadlock if same thread re-enters during registration
        if(lk.owns_lock()) return;

        lk.lock();

        // Ensure one-time initialization
        std::call_once(_flag_once, register_profiler_core);

        // Mark as fully initialized after successful registration
        _init_flag.exchange(true, std::memory_order_release);
    }
}
}  // namespace

// Renamed wrapper: get_rocjpeg_api_table → fetch_api_table
rocjpegApiFuncTable*
fetch_api_table()
{
    ensure_profiler_registered();
    return get_api_table_instance().load(std::memory_order_relaxed);
}

// Renamed init function: rocjpeg_init → initialize_jpeg_runtime
void
initialize_jpeg_runtime()
{
    printf("[%s] %s\n", ROCP_REG_FILE_NAME, __FUNCTION__);
}
}  // namespace rocjpeg

extern "C" {

// Wrapper function renamed and slightly reordered logic
void
rocjpeg_init(void)
{
    auto* api_table = rocjpeg::fetch_api_table();
    if(api_table && api_table->rocJpegStreamCreate_fn)
    {
        api_table->rocJpegStreamCreate_fn({});
    }
}

