// System/390 convention: bit numbering starts at the leftmost (high-order) bit of a byte.
// This class helps set specific bit ranges within a byte.
class BitField {
  uint8_t Value;

  constexpr static uint8_t encode(uint8_t StartBit, uint8_t Width, uint8_t Data,
                                  uint8_t Existing) {
    assert(StartBit < 8 && "Start bit out of range!");
    assert(StartBit + Width <= 8 && "Width exceeds available bits!");

    uint8_t Mask = ((1U << Width) - 1U) << (8U - StartBit - Width);
    uint8_t Shifted = Data << (8U - StartBit - Width);
    assert((Shifted & Mask) == Shifted && "Data exceeds field width!");

    return (Existing & ~Mask) | Shifted;
  }

public:
  constexpr BitField() : Value(0) {}
  constexpr BitField(uint8_t Start, uint8_t Len, uint8_t Val)
      : Value(encode(Start, Len, Val, 0)) {}

  void update(uint8_t Start, uint8_t Len, uint8_t Val) {
    Value = encode(Start, Len, Val, Value);
  }

  constexpr operator uint8_t() const { return Value; }
};

// Standard record flags
constexpr uint8_t IsContinued = BitField(7, 1, 1);     // Record continues in next physical record
constexpr uint8_t IsContinuation = BitField(6, 1, 1);  // This is a continuation record

// GOFFOstream manages writing logical records into fixed-size physical records
class GOFFWriterStream : public raw_ostream {
  raw_pwrite_stream &UnderlyingStream;
  size_t BytesRemaining;
#ifndef NDEBUG
  size_t PaddingSize = 0;
#endif
  uint32_t LogicalRecordCount;
  GOFF::RecordType CurrentRecordKind;
  bool NewLogicalRecordFlag;
  char InternalBuffer[GOFF::RecordContentLength];

  size_t bytesLeftInPhysicalRecord() const {
    size_t remainder = BytesRemaining % GOFF::RecordContentLength;
    return remainder ? remainder : GOFF::RecordContentLength;
  }

  static void emitRecordHeader(raw_ostream &OS, GOFF::RecordType Type,
                               size_t RemainingBytes, uint8_t Flags);

  void padCurrentRecord();
  void write_data(const char *Ptr, size_t Size) override;
  uint64_t get_position() const override { return UnderlyingStream.tell(); }

public:
  explicit GOFFWriterStream(raw_pwrite_stream &Stream)
      : UnderlyingStream(Stream), BytesRemaining(0),
        LogicalRecordCount(0), NewLogicalRecordFlag(false) {
    SetBuffer(InternalBuffer, sizeof(InternalBuffer));
  }

  ~GOFFWriterStream() { finish(); }

  raw_pwrite_stream &getStream() { return UnderlyingStream; }

  void beginRecord(GOFF::RecordType Kind, size_t ContentSize);
  void finish() { padCurrentRecord(); }
  uint32_t getLogicalRecordCount() const { return LogicalRecordCount; }

  template <typename T>
  void writeBigEndian(T value) {
    value = support::endian::byte_swap<T>(value, endianness::big);
    write(reinterpret_cast<const char *>(&value), sizeof(value));
  }
};

void GOFFWriterStream::emitRecordHeader(raw_ostream &OS, GOFF::RecordType Type,
                                        size_t RemainingBytes, uint8_t Flags) {
  uint8_t TypeAndFlags = Flags | (static_cast<uint8_t>(Type) << 4);
  if (RemainingBytes > GOFF::RecordLength)
    TypeAndFlags |= IsContinued;

  OS << static_cast<unsigned char>(GOFF::PTVPrefix)   // Prefix type
     << static_cast<unsigned char>(TypeAndFlags)      // Flags and type
     << static_cast<unsigned char>(0);                // Version
}

void GOFFWriterStream::beginRecord(GOFF::RecordType Kind, size_t Size) {
  padCurrentRecord();

  CurrentRecordKind = Kind;
  BytesRemaining = Size;

#ifdef NDEBUG
  size_t tempPadding;
#endif
  tempPadding = BytesRemaining % GOFF::RecordContentLength;
  if (tempPadding) {
    tempPadding = GOFF::RecordContentLength - tempPadding;
    BytesRemaining += tempPadding;
  }

  NewLogicalRecordFlag = true;
  ++LogicalRecordCount;
}

void GOFFWriterStream::padCurrentRecord() {
  assert(GetNumBytesInBuffer() <= BytesRemaining &&
         "Buffer overflow detected");

  size_t neededPadding = BytesRemaining - GetNumBytesInBuffer();
  if (neededPadding) {
    assert(neededPadding == PaddingSize && "Incorrect padding calculation");
    assert(neededPadding < GOFF::RecordLength &&
           "Trying to pad more than one physical record");
    raw_ostream::write_zeros(neededPadding);
  }

  flush();
  assert(BytesRemaining == 0 && "Incomplete record flushed");
  assert(GetNumBytesInBuffer() == 0 && "Buffer not cleared");
}

void GOFFWriterStream::write_data(const char *Ptr, size_t Size) {
  assert(Size <= BytesRemaining && "Too much data for current record");
  assert(BytesRemaining > 0 && "Record overflow");

  if (!(BytesRemaining % GOFF::RecordContentLength)) {
    emitRecordHeader(UnderlyingStream, CurrentRecordKind, BytesRemaining,
                     NewLogicalRecordFlag ? 0 : IsContinuation);
    NewLogicalRecordFlag = false;
  }

  assert(!NewLogicalRecordFlag &&
         "Logical record not aligned with physical record boundary");

  size_t index = 0;
  while (Size > 0) {
    size_t chunkSize = bytesLeftInPhysicalRecord();
    if (chunkSize > Size)
      chunkSize = Size;

    UnderlyingStream.write(Ptr + index, chunkSize);
    index += chunkSize;
    Size -= chunkSize;
    BytesRemaining -= chunkSize;

    if (Size > 0)
      emitRecordHeader(UnderlyingStream, CurrentRecordKind, BytesRemaining);
  }
}

class GOFFObjectEmitter : public MCObjectWriter {
  std::unique_ptr<MCGOFFObjectTargetWriter> TargetWriter;
  GOFFWriterStream Stream;

public:
  GOFFObjectEmitter(std::unique_ptr<MCGOFFObjectTargetWriter> Writer,
                    raw_pwrite_stream &Output)
      : TargetWriter(std::move(Writer)), Stream(Output) {}

  ~GOFFObjectEmitter() override {}

  void emitHeader();
  void emitFooter();

  void applyRelocation(MCAssembler &Asm, const MCAsmLayout &Layout,
                       const MCFragment *Fragment, const MCFixup &Fixup,
                       MCValue Target, uint64_t &FixedValue) override {}

  void performPostLayoutBinding(MCAssembler &Asm,
                                const MCAsmLayout &Layout) override {}

  uint64_t writeBinary(MCAssembler &Asm, const MCAsmLayout &Layout) override;
};

} // end anonymous namespace

void GOFFObjectEmitter::emitHeader() {
  Stream.beginRecord(GOFF::RT_HDR, /*Size=*/57);
  Stream.write_zeros(1);       // Reserved
  Stream.writeBigEndian<uint32_t>(0); // Target Hardware Environment
  Stream.writeBigEndian<uint32_t>(0); // Target Operating System Environment
  Stream.write_zeros(2);       // Reserved
  Stream.writeBigEndian<uint16_t>(0); // CCSID
  Stream.write_zeros(16);      // Character Set Name
  Stream.write_zeros(16);      // Language Product Identifier
  Stream.writeBigEndian<uint32_t>(1); // Architecture Level
  Stream.writeBigEndian<uint16_t>(0); // Module Properties Length
  Stream.write_zeros(6);       // Reserved
}

void GOFFObjectEmitter::emitFooter() {
  uint8_t Flags = GOFF::END_EPR_None;
  uint8_t AddressingMode = 0;
  uint32_t ESDIdentifier = 0;

  // TODO: Populate entry point info properly
  Stream.beginRecord(GOFF::RT_END, /*Size=*/13);
  Stream.writeBigEndian<uint8_t>(BitField(6, 2, Flags)); // Indicator flags
  Stream.writeBigEndian<uint8_t>(AddressingMode);        // AMODE
  Stream.write_zeros(3);                                 // Reserved
  // Record count should be zero per some tool expectations
  Stream.writeBigEndian<uint32_t>(0);     // Record Count
  Stream.writeBigEndian<uint32_t>(ESDIdentifier); // ESDID of entry point
  Stream.finish();
}

uint64_t GOFFObjectEmitter::writeBinary(MCAssembler &Asm,
                                       const MCAsmLayout &Layout) {
  uint64_t InitialPosition = Stream.get_position();
  emitHeader();
  emitFooter();
  LLVM_DEBUG(dbgs() << "Wrote " << Stream.getLogicalRecordCount()
                    << " logical records.\n");
  return Stream.get_position() - InitialPosition;
}

std::unique_ptr<MCObjectWriter>
llvm::createGOFFObjectWriter(std::unique_ptr<MCGOFFObjectTargetWriter> MOTW,
                             raw_pwrite_stream &OS) {
  return std::make_unique<GOFFObjectEmitter>(std::move(MOTW), OS);
}

