//-------------------------------------------------------------------------
/// @details
///		Called to update the monitor
///	@param[in]	force
///		Force an update even if the timer has not expired
//-------------------------------------------------------------------------
void Monitor::updateProcess() noexcept {
    while (!async::cancelled()) {
        // Check if it's time for an update
        async::sleep(100ms);
        // Skip update if insufficient time has passed
        if (time::now() - m_lastUpdate < 2.5s) continue;
        // If active, refresh monitoring data as needed
        if (m_active) performUpdate();
        // Record the latest update timestamp
        m_lastUpdate = time::now();
    }
    // Termination point
    return;
}
//-------------------------------------------------------------------------
/// @details
///		Start the monitoring process
//-------------------------------------------------------------------------
void Monitor::startMonitor() noexcept {
    // Prevent redundant initialization
    ASSERT(!m_active);
    // Initialize monitoring thread
    m_workerThread = async::Thread{_location, "Status",
                                   _bind(&Monitor::updateProcess, this)};
    // Launch the thread
    m_workerThread->start();
    // Mark as running
    m_active = true;
}
