// Fuzzer target: detect sequences of 'A' characters
extern "C" int LLVMFuzzerTestOneInput(const uint8_t *input_data, size_t input_size) {
  assert(input_data);

  // Track current consecutive 'A' count and maximum observed
  size_t current_run = 0, max_run = 0;

  for (size_t index = 0; index < input_size; index++) {
    // Branchless comparison to check if byte equals 'A'
    int is_A = (input_data[index] == 'A');

    // Update current run length only when 'A' is found
    current_run = is_A * (current_run + 1);

    // Update maximum if current run exceeds it
    int exceeds_max = (current_run > max_run);
    max_run = exceeds_max * current_run + (!exceeds_max) * max_run;
  }

  // Trigger special behavior if long enough sequence found
  if (max_run >= 20) {
    std::cout << "BINGO; Found the target (Max: " << max_run << "), exiting\n";
    exit(0);
  }

  return 0;
}

