PyPangoIO::PyPangoIO(std::queue<InterpreterLine>& input_queue, InterpreterLineType line_kind)
    : input_queue(input_queue), line_kind(line_kind)
{
}

void PyPangoIO::write(const std::string& content)
{
    temp_buffer += content;
    size_t pos = temp_buffer.find_first_of('\n');
    while(pos != std::string::npos) {
        const std::string current_line = temp_buffer.substr(0, pos);
        input_queue.push(InterpreterLine(current_line, line_kind));
        temp_buffer = temp_buffer.substr(pos + 1);
        pos = temp_buffer.find_first_of('\n');
    }
}

void PyPangoIO::flush()
{
    // No operation required
}

