void insertArgument(int &argCount, char **argList, char *newArg) {
    argList[argCount] = new char[strlen(newArg) + 1];
    strcpy(argList[argCount], newArg);
    argCount++;
}

int WHTest_legacy(Params &config, PhyloTree &phylo) {
    int argc_local = 0;
    char *argv_local[12];
    char buffer[128];

    insertArgument(argc_local, argv_local, (char*)"WHTestRunner");
    insertArgument(argc_local, argv_local, config.aln_file);
    insertArgument(argc_local, argv_local, (char*)"-s");

    double shape_param = phylo.getModelFactory()->site_rate->getGammaShape();
    snprintf(buffer, sizeof(buffer), "%.6f", shape_param);
    insertArgument(argc_local, argv_local, buffer);

    return WHTest_run(argc_local, argv_local);
}

int WHTest_new(Params &config, IQTree &phylo_tree) {
    int result_code;
    size_t seq_count = phylo_tree.aln->getNSeq();
    size_t site_count = phylo_tree.aln->getNSite(); 

    WHT_setAlignmentSize(seq_count, site_count);
    WHT_allocateMemory();

    for (size_t s = 0; s < seq_count; ++s) {
        for (size_t p = 0; p < site_count; ++p) {
            size_t pattern_idx = phylo_tree.aln->getPatternID(p);
            WHT_setSequenceSite(s, p, (*phylo_tree.aln)[pattern_idx][s]);
        }
    }

    for (size_t s = 0; s < seq_count; ++s) {
        WHT_setSequenceName(s, phylo_tree.aln->getSeqName(s).c_str());
    }

    double gamma_shape_val = phylo_tree.getModelFactory()->site_rate->getGammaShape();
    if (gamma_shape_val == 0.0) {
        gamma_shape_val = 50.0;
    }

    //WHT_setParams(config.whtest_simulations, gamma_shape_val, config.out_prefix, phylo_tree.dist_matrix);
    WHT_setParams(config.whtest_simulations, gamma_shape_val, config.out_prefix, nullptr);

    result_code = WHTest_run(0, nullptr);
    WHT_getResults(&config.whtest_delta, &config.whtest_delta_quantile, &config.whtest_p_value);

    return result_code;
}

