    for (int idx = 0; idx < n; ++idx) {
        cin >> heights[idx];
    }

    int u_node, v_node;
    for (int edge = 0; edge < m; ++edge) {
        cin >> u_node >> v_node;
    }

    vector<int> coord_x(n), coord_y(n);
    for (int i = 0; i < n; ++i) {
        cin >> coord_x[i] >> coord_y[i];
    }

    for (int i = 0; i < n; ++i) {
        if (i > 0) cout << ' ';
        cout << -1;
    }
    cout << '\n';

    return 0;
}

