LoadingSpinner::LoadingSpinner(QWidget* parent)
    : QLabel(parent)
    , m_rotation(0)
{
    setFixedSize(64, 64);
    setScaledContents(true);
    setAlignment(Qt::AlignCenter);

    m_updateTimer = new QTimer(this);
    connect(m_updateTimer, &QTimer::timeout, this, &LoadingSpinner::spin);
}

void LoadingSpinner::begin() {
    m_updateTimer->start(40);
    show();
}

void LoadingSpinner::end() {
    m_updateTimer->stop();
    hide();
}

void LoadingSpinner::spin() {
    m_rotation = (m_rotation + 25) % 360;
    update();
}

void LoadingSpinner::paintEvent(QPaintEvent* event) {
    Q_UNUSED(event);

    QPainter renderer(this);
    renderer.setRenderHint(QPainter::Antialiasing);

    // Material Design 3 circular progress indicator
    QPen stroke(Colors::toQColor(Colors::ACCENT), 4);
    stroke.setCapStyle(Qt::RoundCap);
    renderer.setPen(stroke);

    QRect arcRect(8, 8, 48, 48);
    int initialAngle = -m_rotation * 16;
    int sweepAngle = 270 * 16;
    renderer.drawArc(arcRect, initialAngle, sweepAngle);
}

