#include "rest_server/serened.h"
#include <absl/functional/overload.h>
#include "general_server/server_options_feature.h"
#include "rest_server/serened_includes.h"

using namespace sdb;
using namespace sdb::app;

static_assert(SerenedServer::id<LoggerFeature>() == 0);

constexpr auto kNonServerFeaturesList = std::array{
#ifdef SDB_CLUSTER
  SerenedServer::id<AgencyFeature>(),
  SerenedServer::id<ClusterFeature>(),
#endif
#ifdef SERENEDB_HAVE_FORK
  SerenedServer::id<SupervisorFeature>(),
  SerenedServer::id<DaemonFeature>(),
#endif
  SerenedServer::id<GeneralServerFeature>(),
  SerenedServer::id<HttpEndpointProvider>(),
  SerenedServer::id<LogBufferFeature>(),
  SerenedServer::id<ServerFeature>(),
  SerenedServer::id<SslServerFeature>(),
  SerenedServer::id<StatisticsFeature>(),
};

static const boost::asio::ssl::detail::openssl_init<true> sslLibraryInitializer{};

static int ExecuteServer(int argc, char** argv, GlobalContext& ctx) {
  try {
    std::string programName = ctx.binaryName();
    CrashHandler::installCrashHandler();

    auto opts = std::make_shared<sdb::options::ProgramOptions>(
      argv[0], "Usage: " + programName + " [<options>]",
      "For more information use:", SDB_SBIN_DIR);

    int exitCode{EXIT_FAILURE};
    SerenedServer srv{opts, SDB_SBIN_DIR};
    ServerState currentState;

    srv.addReporter(
      {[&](SerenedServer::State stateVal) {
         CrashHandler::SetState(magic_enum::enum_name(stateVal));
         if (stateVal == SerenedServer::State::InStart) {
           srv.getFeature<PrivilegeFeature>().dropPrivilegesPermanently();
         }
       },
       {}});

    srv.addFeatures(absl::Overload{
      []<typename T>(auto& serverRef, type::Tag<T>) {
        return std::make_unique<T>(serverRef);
      },
      [&exitCode](auto& serverRef, type::Tag<CheckVersionFeature>) {
        return std::make_unique<CheckVersionFeature>(serverRef, &exitCode,
                                                     kNonServerFeaturesList);
      },
      [&programName](auto& serverRef, type::Tag<ConfigFeature>) {
        return std::make_unique<ConfigFeature>(
          serverRef, programName, [] { return GetServerOptions().app_print_version; });
      },
      [](auto& serverRef, type::Tag<InitDatabaseFeature>) {
        return std::make_unique<InitDatabaseFeature>(serverRef,
                                                     kNonServerFeaturesList);
      },
      [](auto& serverRef, type::Tag<LoggerFeature>) {
        return std::make_unique<LoggerFeature>(serverRef, true);
      },
      [](auto& serverRef, type::Tag<NetworkFeature>) {
        auto& metrics = serverRef.template getFeature<metrics::MetricsFeature>();
        return std::make_unique<NetworkFeature>(
          serverRef, metrics, network::ConnectionPool::Config{metrics});
      },
      [&exitCode](auto& serverRef, type::Tag<ServerFeature>) {
        return std::make_unique<ServerFeature>(serverRef, &exitCode);
      },
      [&programName](auto& serverRef, type::Tag<TempPath>) {
        return std::make_unique<TempPath>(serverRef, programName);
      },
      [](auto& serverRef, type::Tag<SslServerFeature>) {
        return std::make_unique<SslServerFeature>(serverRef);
      },
      [&exitCode](auto& serverRef, type::Tag<UpgradeFeature>) {
        return std::make_unique<UpgradeFeature>(serverRef, &exitCode,
                                                kNonServerFeaturesList);
      },
      [](auto& serverRef, type::Tag<HttpEndpointProvider>) {
        return std::make_unique<EndpointFeature>(serverRef);
      },
    });

    try {
      srv.run(argc, argv);
      if (srv.helpShown()) {
        exitCode = EXIT_SUCCESS;
      }
    } catch (const std::exception& ex) {
      SDB_ERROR("fatal_error", Logger::FIXME,
                "serened terminated because of an exception: ", ex.what());
      exitCode = EXIT_FAILURE;
    } catch (...) {
      SDB_ERROR("fatal_error", Logger::FIXME,
                "serened terminated because of an exception of "
                "unknown type");
      exitCode = EXIT_FAILURE;
    }

    log::Flush();
    return ctx.exit(exitCode);
  } catch (const std::exception& ex) {
    SDB_ERROR("fatal_error", Logger::FIXME,
              "serened terminated because of an exception: ", ex.what());
  } catch (...) {
    SDB_ERROR("fatal_error", Logger::FIXME,
              "serened terminated because of an exception of "
              "unknown type");
  }
  exit(EXIT_FAILURE);
}

int main(int argc, char* argv[]) {
  std::string currentWorkingDir(basics::file_utils::CurrentDirectory().result());
  GlobalContext appContext(argc, argv, SDB_SBIN_DIR);
  gRestartAction = nullptr;

  int result = ExecuteServer(argc, argv, appContext);
  if (result != 0) {
    return result;
  }

  if (gRestartAction == nullptr) {
    return 0;
  }

  try {
    result = (*gRestartAction)();
  } catch (...) {
    result = -1;
  }

  delete gRestartAction;
  if (result != 0) {
    std::cerr << "FATAL: RestartAction returned non-zero exit status: " << result
              << ", giving up." << std::endl;
    return result;
  }

#if defined(__linux__)
  result = chdir(currentWorkingDir.c_str());
  if (result != 0) {
    std::cerr << "WARNING: could not change into directory '" << currentWorkingDir << "'"
              << std::endl;
  }
  if (execvp(argv[0], argv) == -1) {
    std::cerr << "WARNING: could not execvp ourselves, restore will not work!"
              << std::endl;
  }
#endif
}

