// Convert fixed-point to double for comparison
static double
fxp_to_double(fxp_t val) {
	double integer_part = (double)(val >> 16);
	double fractional_part = (double)(val & ((1U << 16) - 1)) / (1U << 16);
	return integer_part + fractional_part;
}

// Check if two doubles are approximately equal
static bool
doubles_approx_equal(double x, double y) {
	/*
	 * Tolerance-based comparison: accept values close in either relative or absolute terms.
	 */
	return fabs(x - y) < 0.01 || (x != 0.0 && fabs(x - y) / fabs(x) < 0.01);
}

// Compare two fxp values via conversion to double
static bool
fxp_values_close(fxp_t a, fxp_t b) {
	return doubles_approx_equal(fxp_to_double(a), fxp_to_double(b));
}

// Parse string into fxp_t with error checking
static fxp_t
parse_fxp_string(const char *input_str) {
	fxp_t parsed_value;
	bool parse_error = fxp_parse(&parsed_value, input_str, NULL);
	assert_false(parse_error, "Failed to parse valid fxp string: %s", input_str);
	return parsed_value;
}

// Verify parsing accuracy against expected decimal value
static void
verify_parse_accuracy(const char *decimal_str, const char *fxp_input) {
	double expected_value = strtod(decimal_str, NULL);
	fxp_t parsed_fxp;
	char *parse_end;
	bool parse_error = fxp_parse(&parsed_fxp, fxp_input, &parse_end);
	expect_false(parse_error, "Unexpected parse failure");
	expect_ptr_eq(fxp_input + strlen(decimal_str), parse_end,
	    "Parse did not consume entire string");
	expect_true(doubles_approx_equal(fxp_to_double(parsed_fxp), expected_value),
	    "Incorrect parsing of %s", decimal_str);
}

// Test various valid representations
static void
test_valid_inputs(const char *input_str) {
	// Direct parsing should be accurate
	verify_parse_accuracy(input_str, input_str);

	// Parsing with trailing text should still succeed
	char buffer[100];
	snprintf(buffer, sizeof(buffer), "%s_trailing_content", input_str);
	verify_parse_accuracy(input_str, buffer);

	// Parsing with space-separated suffix
	snprintf(buffer, sizeof(buffer), "%s additional_text", input_str);
	verify_parse_accuracy(input_str, buffer);

	// Parsing within malloc.conf-like context
	snprintf(buffer, sizeof(buffer), "%s:config_value:123", input_str);
	verify_parse_accuracy(input_str, buffer);
}

