// Verify that invalid inputs fail as expected
static void
expect_parse_failure(const char *invalid_str) {
	fxp_t result = FXP_INIT_INT(333);
	char *end_marker = (void *)0x123;
	bool parse_error = fxp_parse(&result, invalid_str, &end_marker);
	expect_true(parse_error, "Expected parse failure for: %s", invalid_str);
	expect_ptr_eq((void *)0x123, end_marker,
	    "Parse error should not modify end pointer");
	expect_u32_eq(result, FXP_INIT_INT(333),
	    "Parse error should not alter result");
}

