#include "Buffer.h"
#include <cassert>

Buffer::Buffer(unsigned int size)
: bufferCapacity(size),
  currPos(0),
  bufLimit(size),
  backingArrayPresent(false) {}

// Resets this buffer. The current position is set to zero, the limit becomes equal to the capacity,
// and any existing mark is invalidated. This operation doesn't physically remove the stored data,
// but the name suggests it does since it's commonly used in contexts where that distinction is irrelevant.
//
// Returns:
// Reference to this buffer for method chaining
Buffer* Buffer::reset() {
    currPos = 0;
    bufLimit = bufferCapacity;
    return this;
}

// Establishes this buffer's upper bound. If the current position exceeds the new limit,
// the position is adjusted downward to match. Any existing mark that exceeds the new limit
// is removed. 
// Parameters: newBound - The desired limit; must be >= 0 and <= bufferCapacity
// Returns: This buffer for chaining operations
Buffer* Buffer::setLimit(unsigned int newBound) {
    assert(newBound <= bufferCapacity);
    bufLimit = newBound;
    if (currPos > newBound) currPos = newBound;
    return this;
}

// Retrieves the current limit value
// Returns: The limit of this buffer
unsigned int Buffer::getLimit() { return bufLimit; }

// Updates this buffer's position indicator. If a mark exists and lies beyond the new position,
// it is cleared. 
// Parameters: newPos - The target position; must be >= 0 and <= current limit
// Returns: This buffer for chaining operations
Buffer* Buffer::setPos(unsigned int newPos) {
    assert(newPos <= bufLimit);
    currPos = newPos;
    return this;
}

// Accesses the current position
// Returns: The current position of this buffer
unsigned int Buffer::getPos() { return currPos; }

// Computes how many elements remain between the current position and the limit
// Returns: The count of remaining accessible elements
unsigned int Buffer::getRemaining() { return bufLimit - currPos; }

