{
	IntCache::releaseAll();
	//if (downfalls == NULL || downfalls->length < w * h)
	if (resultDownfalls.data == NULL || resultDownfalls.length < width * height)
	{
		if(resultDownfalls.data != NULL) delete [] resultDownfalls.data;
		resultDownfalls = floatArray(width * height);
	}
	intArray areaIndices = zoomedLayerData->getArea(xPos, zPos, width, height);
	for (int idx = 0; idx < width * height; idx++)
	{
		float d = (float) Biome::biomes[areaIndices[idx]]->getDownfallInt() / 65536.0f;
		if (d > 1.0f) d = 1.0f;
		resultDownfalls[idx] = d;
	}
}

