/**
* Checks if an area around a block contains only the specified biomes.
* Useful for placing elements like towns.
* 
* This is a bit of a rough check, to make it as fast as possible. To ensure
* NO other biomes, add a margin of at least four blocks to the radius
*/
bool BiomeSource::containsOnly(int xPos, int zPos, int radius, vector<Biome *> allowedList)
{
	int minX = ((xPos - radius) >> 2);
	int minZ = ((zPos - radius) >> 2);
	int maxX = ((xPos + radius) >> 2);
	int maxZ = ((zPos + radius) >> 2);
	int w = maxX - minX + 1;
	int h = maxZ - minZ + 1;
	intArray sampledIndices = layerData->getArea(minX, minZ, w, h);
	for (int idx = 0; idx < w * h; idx++)
	{
		Biome *b = Biome::biomes[sampledIndices[idx]];
		if (find(allowedList.begin(), allowedList.end(), b) == allowedList.end()) return false;
	}
	return true;
}

/**
* Checks if an area around a block contains only the specified biome.
* Useful for placing elements like towns.
* 
* This is a bit of a rough check, to make it as fast as possible. To ensure
* NO other biomes, add a margin of at least four blocks to the radius
*/
bool BiomeSource::containsOnly(int xPos, int zPos, int radius, Biome *requiredBiome)
{
	int minX = ((xPos - radius) >> 2);
	int minZ = ((zPos - radius) >> 2);
	int maxX = ((xPos + radius) >> 2);
	int maxZ = ((zPos + radius) >> 2);

	int w = maxX - minX;
	int h = maxZ - minZ;
	int sampleCount = w*h;
	intArray sampledIndices = layerData->getArea(minX, minZ, w, h);
	for (unsigned int idx = 0; idx < sampleCount; idx++)
	{
		Biome *b = Biome::biomes[sampledIndices[idx]];
		if (requiredBiome != b) return false;
	}
	return true;
}

/**
* Finds the specified biome within the radius. This will return a random
* position if several are found. This test is fairly rough.
* 
* Returns null if the biome wasn't found
*/
TilePos *BiomeSource::findBiome(int xPos, int zPos, int radius, Biome *targetBiome, Random *rng)
{
	int minX = ((xPos - radius) >> 2);
	int minZ = ((zPos - radius) >> 2);
	int maxX = ((xPos + radius) >> 2);
	int maxZ = ((zPos + radius) >> 2);
	int w = maxX - minX + 1;
	int h = maxZ - minZ + 1;
	intArray sampledIndices = layerData->getArea(minX, minZ, w, h);
	TilePos *foundPos = NULL;
	int matchCount = 0;
	int sampleCount = w*h;
	for (unsigned int idx = 0; idx < sampleCount; idx++)
	{
		int xx = minX + idx % w;
		int zz = minZ + idx / w;
		Biome *b = Biome::biomes[sampledIndices[idx]];
		if (b == targetBiome)
		{
			if (foundPos == NULL || rng->nextInt(matchCount + 1) == 0)
			{
				foundPos = new TilePos(xx, 0, zz);
				matchCount++;
			}
		}
	}
	return foundPos;
}

/**
* Finds one of the specified biomes within the radius. This will return a
* random position if several are found. This test is fairly rough.
* 
* Returns null if the biome wasn't found
*/
TilePos *BiomeSource::findBiome(int xPos, int zPos, int radius, vector<Biome *> allowedList, Random *rng)
{
	int minX = ((xPos - radius) >> 2);
	int minZ = ((zPos - radius) >> 2);
	int maxX = ((xPos + radius) >> 2);
	int maxZ = ((zPos + radius) >> 2);
	int w = maxX - minX + 1;
	int h = maxZ - minZ + 1;
	MemSect(50);
	intArray sampledIndices = layerData->getArea(minX, minZ, w, h);
	TilePos *foundPos = NULL;
	int matchCount = 0;
	int sampleCount = w*h;
	for (unsigned int idx = 0; idx < sampleCount; idx++)
	{
		int xx = (minX + idx % w) << 2;
		int zz = (minZ + idx / w) << 2;
		Biome *b = Biome::biomes[sampledIndices[idx]];
		if (find(allowedList.begin(), allowedList.end(), b) != allowedList.end())
		{
			if (foundPos == NULL || rng->nextInt(matchCount + 1) == 0)
			{
				delete foundPos;
				foundPos = new TilePos(xx, 0, zz);
				matchCount++;
			}
		}
	}
	MemSect(0);
	return foundPos;
}

