//#define DEBUG_SEEDS 50
// 4J added - find a seed for this biomesource that matches certain criteria
#ifdef __PSVITA__
__int64 BiomeSource::findSeed(LevelType *worldGenerator, bool* pServerRunning)	// MGH - added pRunning, so we can early out of this on Vita as it can take up to 60 secs
#else
__int64 BiomeSource::findSeed(LevelType *worldGenerator)	
#endif
{
	__int64 optimalSeed = 0;
	ProgressRenderer *mcprogress = Minecraft::GetInstance()->progressRenderer;
	mcprogress->progressStage(IDS_PROGRESS_NEW_WORLD_SEED);
#ifndef _CONTENT_PACKAGE
	if(app.DebugSettingsOn() && app.GetGameSettingsDebugMask(ProfileManager.GetPrimaryPad())&(1L<<eDebugSetting_EnableHeightWaterBiomeOverride))
	{
		// Do nothing
	}
	else
#endif
	{
#ifdef DEBUG_SEEDS
		for( int loopIdx = 0; loopIdx < DEBUG_SEEDS; loopIdx++ )
#endif
		{
			// Try and genuinely random this search up
			Random *rng = new Random(System::nanoTime());
			// Raw biome data has one result per 4x4 group of tiles.
			// Removing a border of 8 from each side since we'll be doing special things at the edge to turn our world into an island, and so don't want to count things
			// in the edge region in case they later get removed
			static const int mapWidth = ( 54 * 4 ) - 16;			// Should be even so we can offset evenly
			static const int mapOffset = -( mapWidth / 2 );
			// Storage for our biome indices
			intArray indices = intArray( mapWidth * mapWidth );
			// Storage for the fractional amounts of each biome that will be calculated
			float comparisonValues[Biome::BIOME_COUNT];
			bool matchFound = false;
			int attemptCount = 0;
			// Just keeping trying to generate seeds until we find one that matches our criteria
			do
			{
				__int64 candidateSeed = rng->nextLong();
				BiomeSource *candidateSource = new BiomeSource(candidateSeed,worldGenerator);
				candidateSource->getRawBiomeIndices(indices, mapOffset, mapOffset, mapWidth, mapWidth);
				extractFractions(indices, comparisonValues);
				matchFound = checkMatch(comparisonValues);
				if( matchFound ) optimalSeed = candidateSeed;
				delete candidateSource;
				attemptCount++;
				mcprogress->progressStagePercentage( attemptCount % 100 );
#ifdef __PSVITA__
			} while (!matchFound && *pServerRunning);
#else
			} while (!matchFound);
#endif
			// Clean up
			delete rng;
			delete indices.data;
#ifdef DEBUG_SEEDS
			app.DebugPrintf("%d: %d tries taken, seed used is %lld\n", loopIdx, attemptCount, optimalSeed);
			BiomeSource *finalSource = new BiomeSource(optimalSeed);
			BiomeArray finalBiomes = finalSource->getBiomeBlock(-27 * 16, -27 * 16, 54 * 16, 54 * 16);
			unsigned int *pixels = new unsigned int[54 * 16 * 54 * 16];
			for(int i = 0; i < 54 * 16 * 54 * 16; i++ )
			{			
				int id = finalBiomes[i]->id;
				// Create following colours:
				// 0	ocean				0000	black
				// 1	plains				0001	pastel cyan
				// 2	desert				0010	green
				// 3	extreme hills		0011	yellow
				// 4	forest				0100	blue
				// 5	taiga				0101	magenta
				// 6	swamps				0110	cyan
				// 7	river				0111	white
				// 8	hell				1000	grey
				// 9	end biome			1001	white
				// 10	frozen ocean		1010	pastel green
				// 11	frozen river		1011	pastel yellow
				// 12	ice flats			1100	pastel blue
				// 13	ice mountains		1101	pastel magenta
				// 14	mushroom island		1110	red
				// 15   mushroom shore		1111	pastel red
				if( id == 1 ) id = 14;
				else if ( id == 14 ) id = 1;
				else if( id == 9 ) id = 15;
				else if( id == 15 ) id = 9;
				pixels[i] = 0xff000000;
				if( id & 1 ) pixels[i] |= 0x00ff0000;
				if( id & 2 ) pixels[i] |= 0x0000ff00;
				if( id & 4 ) pixels[i] |= 0x000000ff;
				if( id & 8 ) pixels[i] |= 0x00808080;
			}
			D3DXIMAGE_INFO srcInfo;
			srcInfo.Format = D3DFMT_LIN_A8R8G8B8;
			srcInfo.ImageFileFormat = D3DXIFF_BMP;
			srcInfo.Width = 54 * 16;
			srcInfo.Height = 54 * 16;
			char buf[256];
			sprintf(buf,"GAME:\\BiomeTest%d.bmp",loopIdx);
			RenderManager.SaveTextureData(buf, &srcInfo, (int *)pixels);
			delete [] pixels;
			delete finalBiomes.data;
			delete finalSource;
#endif
		}
	}
	return optimalSeed;
}

// 4J added - get the fractional amounts of each biome type in the given indices
void BiomeSource::extractFractions(intArray indices, float *fractions)
{
	for( int i = 0; i < Biome::BIOME_COUNT; i++ )
	{
		fractions[i] = 0.0f;
	}
	for( int i = 0; i < indices.length; i++ )
	{
		fractions[indices[i]] += 1.0f;
	}
	for( int i = 0; i < Biome::BIOME_COUNT; i++ )
	{
		fractions[i] /= (float)(indices.length);
	}
}

// 4J added - determine if this particular set of fractional amounts of biome types matches are requirements
bool BiomeSource::checkMatch(float *frac)
{
	// A true for a particular biome type here marks it as one that *has* to be present
	static const bool critical[Biome::BIOME_COUNT] = { 
										true,	// ocean
										true,	// plains
										true,	// desert
										false,	// extreme hills
										true,	// forest
										true,	// taiga
										true,	// swamps
										false,	// river
										false,	// hell
										false,	// end biome
										false,	// frozen ocean
										false,	// frozen river
										false,	// ice flats
										false,	// ice mountains
										true,	// mushroom island / shore
										false,  // mushroom shore (combined with above)
										false,	// beach
										false,	// desert hills (combined with desert)
										false,	// forest hills (combined with forest)
										false,	// taiga hills (combined with taga)
										false,	// small extreme hills
										true,	// jungle
										false,	// jungle hills (combined with jungle)
										};
	// Don't want more than 15% ocean
	if( frac[0] > 0.15f )
	{
		return false;
	}
	// Consider mushroom shore & islands as the same by finding max
	frac[14] = ( ( frac[15] > frac[14] ) ? frac[15] : frac[14] );
	// Merge desert and desert hills
	frac[2] = ( ( frac[17] > frac[2] ) ? frac[17] : frac[2] );
	// Merge forest and forest hills
	frac[4] = ( ( frac[18] > frac[4] ) ? frac[18] : frac[4] );
	// Merge taiga and taiga hills
	frac[5] = ( ( frac[19] > frac[5] ) ? frac[19] : frac[5] );
	// Merge jungle and jungle hills
	frac[21] =  ( ( frac[22] > frac[21] ) ? frac[22] : frac[21] );
	// Loop through all biome types, and:
	// (1) count them
	// (2) give up if one of the critical ones is missing
	int typeCount = 0;
	for( int i = 0; i < Biome::BIOME_COUNT; i++ )
	{
		// We want to skip some where we have merged with another type
		if(i == 15 || i == 17 || i == 18 || i == 19 || i == 22) continue;
		// Consider 0.1% as being "present" - this equates an area of about 3 chunks
		if( frac[i] > 0.001f )
		{
			typeCount++;
		}
		else
		{
			// If a critical biome is missing, just give up
			if( critical[i] )
			{
				return false;
			}
		}
	}
	// Consider as suitable if we've got all the critical ones, and in total 9 or more - currently there's 8 critical so this just forces at least 1 more others
	return ( typeCount >= 9 );
}

#include <iostream>
#include <sm/range>
#include <mplot/graphing.h>

void printUsage(char** programName)
{
    std::cout << "Program Usage\n";
    std::cout << programName[0] << " <min_value> <max_value> <min_ticks> <max_ticks>\n";
}

int main(int argc, char** argv)
{
    float startVal = 0.0f;
    float endVal = 9.0f;

    if (argc > 2) {
        startVal = std::atof(argv[1]);
        endVal = std::atof(argv[2]);
    } else {
        printUsage(argv);
        return -1;
    }

    std::cout << "Input range: " << startVal << " to " << endVal << std::endl;

    sm::range<float> tickRange = {3, 8};

    if (argc > 4) {
        tickRange.min = std::atof(argv[3]);
        tickRange.max = std::atof(argv[4]);
    } else {
        printUsage(argv);
        return -1;
    }

    std::cout << "Tick count range: " << tickRange << std::endl;

    std::deque<float> tickPositions = mplot::graphing::maketicks(startVal, endVal, startVal, endVal, tickRange);

    std::cout << "\n" << startVal << " through " << endVal << ": generated ticks: ";
    for (auto t : tickPositions) { 
        std::cout << t << ", "; 
    }
    std::cout << std::endl;

    return 0;
}

#include <engLib/eng.h>
using namespace engine::net::rpc::v3::keystore;

namespace engine::keystore {

/**
 * @brief Constructor
 *
 * Initializes the service key-store wrapper using the provided `serviceKey` and
 * underlying `keystore`. The `serviceKey` is prepended to partition names in
 * all internal operations.
 *
 * @param svcKey Service identifier used as prefix
 * @param store Underlying key-store instance
 */
ServiceKeyStore::ServiceKeyStore(TextView svcKey,
                                 SharedPtr<KeyStore> store) noexcept
    : m_serviceKey(svcKey), m_keystore(store) {}

/**
 * @brief Retrieve base URL
 *
 * Delegates to the wrapped key-store's `getUrl` method
 *
 * @return The `Url` object representing the underlying store location
 */
Url ServiceKeyStore::getUrl() const noexcept { return m_keystore->getUrl(); }

/**
 * @brief Open operation (unsupported)
 *
 * This implementation always fails with `Ec::NotSupported`
 *
 * @param url Target URL (ignored)
 * @return Error indicating operation not supported
 */
Error ServiceKeyStore::open(const Url &url) noexcept {
    return APERR(Ec::NotSupported, "operation not supported");
}

/**
 * @brief Retrieve value by partition and key
 *
 * Forwards request to the underlying store after augmenting the partition name
 *
 * @param part Partition identifier
 * @param k Key identifier
 * @return Value or error status
 */
ErrorOr<Text> ServiceKeyStore::getValue(TextView part,
                                        TextView k) noexcept {
    return m_keystore->getValue(servicePartition(part), k);
}

/**
 * @brief Store a value under partition/key
 *
 * Forwards request to the underlying store after modifying partition name
 *
 * @param part Partition identifier
 * @param k Key identifier
 * @param val Value to store
 * @return Error status of the underlying operation
 */
Error ServiceKeyStore::setValue(TextView part, TextView k,
                                TextView val) noexcept {
    return m_keystore->setValue(servicePartition(part), k, val);
}

/**
 * @brief Remove a specific key from a partition
 *
 * Forwards deletion request to the underlying store with adjusted partition
 *
 * @param part Partition identifier
 * @param k Key identifier
 * @return Error status of the underlying operation
 */
Error ServiceKeyStore::deleteKey(TextView part, TextView k) noexcept {
    return m_keystore->deleteKey(servicePartition(part), k);
}

/**
 * @brief Clear all entries in a partition
 *
 * Forwards clear request to the underlying store with modified partition name
 *
 * @param part Partition identifier
 * @return Error status of the underlying operation
 */
Error ServiceKeyStore::deleteAll(TextView part) noexcept {
    return m_keystore->deleteAll(servicePartition(part));
}

/**
 * @brief Retrieve all key-value pairs in a partition
 *
 * Forwards request to the underlying store with transformed partition name
 *
 * @param part Partition identifier
 * @return Collection of key-value pairs or error status
 */
ErrorOr<KeyStore::Values> ServiceKeyStore::getAll(TextView part) noexcept {
    return m_keystore->getAll(servicePartition(part));
}

/**
 * @brief Copy all entries between partitions
 *
 * Forwards copy request to the underlying store with adjusted partition names
 *
 * @param src Source partition identifier
 * @param dst Destination partition identifier
 * @return Error status of the underlying operation
 */
Error ServiceKeyStore::copyAll(TextView src, TextView dst) noexcept {
    return m_keystore->copyAll(servicePartition(src),
                               servicePartition(dst));
}

/**
 * @brief Move all entries between partitions with options
 *
 * Forwards move request to the underlying store with modified partition names
 *
 * @param src Source partition identifier
 * @param dst Destination partition identifier
 * @param eraseDst Whether to clear destination before moving
 * @param ignoreIfEmpty Skip operation if source is empty
 * @return Error status of the underlying operation
 */
Error ServiceKeyStore::moveAll(TextView src, TextView dst,
                               bool eraseDst, bool ignoreIfEmpty) noexcept {
    return m_keystore->moveAll(servicePartition(src),
                               servicePartition(dst), eraseDst,
                               ignoreIfEmpty);
}

/**
 * @brief Construct augmented partition name
 *
 * Prepends the service key to the original partition name
 *
 * @param part Original partition name
 * @return Full partition name including service key
 */
Text ServiceKeyStore::servicePartition(TextView part) noexcept {
    return _ts(m_serviceKey, "/", part);
}

}  // namespace engine::keystore

