namespace {
class CleanupOnDestruct;
using container_t = ankerl::unordered_dense::map<counter::obj, std::unique_ptr<CleanupOnDestruct>>;

class CleanupOnDestruct {
    container_t* m_container;
    counter::obj m_obj;
public:
    CleanupOnDestruct(container_t& container, size_t idx, counter& counts)
        : m_container(&container)
        , m_obj(idx, counts) {}

    ~CleanupOnDestruct() {
        (void)m_container;
        // Attempt to remove another element during destruction
        m_container->erase(counter::obj{m_obj.get() + 1, m_obj.counts()});
    }
};
} // namespace

TEST_CASE("reentrant_destruct") {
    auto counts = counter{};
    INFO(counts);
    auto map = container_t();

    /*
    This approach fails due to vector-based storage in unordered_dense.
    The re-entrant erase during destructor leads to undefined behavior.
    Code preserved for reference but not functional.

    for (size_t i = 0; i < 100; ++i) {
        map.try_emplace(counter::obj{i, counts}, std::make_unique<CleanupOnDestruct>(map, i, counts));
    }
    map.erase(counter::obj{0, counts});
    */
}

