Settings loadConfiguration(const std::string& configPath, const std::string& sectionName, bool printInfo) {
  boost::property_tree::ptree tree;
  boost::property_tree::read_info(configPath, tree);
  Settings cfg;

  if (printInfo) {
    std::cerr << "\n #### MPC Configuration:";
    std::cerr << "\n #### =============================================================================\n";
  }

  loadData::loadPtreeValue(tree, cfg.timeHorizon_, sectionName + ".timeHorizon", printInfo);
  loadData::loadPtreeValue(tree, cfg.solutionTimeWindow_, sectionName + ".solutionTimeWindow", printInfo);
  loadData::loadPtreeValue(tree, cfg.recordSolverData_, sectionName + ".recordSolverData", printInfo);
  loadData::loadPtreeValue(tree, cfg.coldStart_, sectionName + ".coldStart", printInfo);
  loadData::loadPtreeValue(tree, cfg.debugPrint_, sectionName + ".debugPrint", printInfo);
  loadData::loadPtreeValue(tree, cfg.mpcDesiredFrequency_, sectionName + ".mpcDesiredFrequency", printInfo);
  loadData::loadPtreeValue(tree, cfg.mrtDesiredFrequency_, sectionName + ".mrtDesiredFrequency", printInfo);

  if (printInfo) {
    std::cerr << " #### =============================================================================" << std::endl;
  }

  return cfg;
}

