#include "jemalloc/internal/jemalloc_preamble.h"
#include "jemalloc/internal/jemalloc_internal_includes.h"
#include "jemalloc/internal/bit_util.h"
#include "jemalloc/internal/cache_bin.h"
#include "jemalloc/internal/safety_check.h"

const uintptr_t disabled_bin = JUNK_ADDR;

void
cache_bin_info_init(cache_bin_info_t *info, cache_bin_sz_t max_cached) {
    assert(max_cached <= CACHE_BIN_NCACHED_MAX);
    size_t stack_bytes = (size_t)max_cached * sizeof(void *);
    assert(stack_bytes < ((size_t)1 << (sizeof(cache_bin_sz_t) * 8)));
    info->ncached_max = (cache_bin_sz_t)max_cached;
}

bool
cache_bin_stack_use_thp(void) {
    /*
     * When metadata_thp is active, we allocate tcache stacks via the base
     * allocator for performance benefits. However, this means the base
     * allocator retains freed memory and may hold onto substantial space
     * after many threads are destroyed without reuse.
     */
    return metadata_thp_enabled();
}

void
cache_bin_info_compute_alloc(const cache_bin_info_t *infos, szind_t ninfos,
    size_t *out_size, size_t *out_alignment) {
    /* Reserve extra slots for the total bin stack region (per tcache):
     * 1) to safely read the empty position on the fast path before
     *    checking "is_empty"; and
     * 2) to allow cur_ptr to advance one slot past the empty position
     *    without overflow.
     */
    *out_size = sizeof(void *) * 2;
    for (szind_t idx = 0; idx < ninfos; idx++) {
        *out_size += infos[idx].ncached_max * sizeof(void *);
    }

    /*
     * When THP is not used, align to at least PAGE size to reduce TLB
     * pressure for smaller sizes; also beneficial if larger sizes remain unused.
     */
    *out_alignment = cache_bin_stack_use_thp() ? QUANTUM : PAGE;
}

void
cache_bin_preincrement(const cache_bin_info_t *infos, szind_t ninfos, void *buffer,
    size_t *offset) {
    if (config_debug) {
        size_t expected_size;
        size_t expected_align;
        cache_bin_info_compute_alloc(infos, ninfos, &expected_size,
            &expected_align);
        assert(((uintptr_t)buffer & (expected_align - 1)) == 0);
    }
    *(uintptr_t *)((byte_t *)buffer + *offset) =
        cache_bin_preceding_junk;
    *offset += sizeof(void *);
}

void
cache_bin_postincrement(void *buffer, size_t *offset) {
    *(uintptr_t *)((byte_t *)buffer + *offset) =
        cache_bin_trailing_junk;
    *offset += sizeof(void *);
}

void
cache_bin_init(cache_bin_t *bin, const cache_bin_info_t *info, void *buffer,
    size_t *offset) {
    /*
     * stack_cur points to the start of available stack space.
     * full_position marks the beginning of the usable region.
     * Allocations proceed toward higher addresses (prefetch-friendly).
     */
    void *stack_pos = (void *)((byte_t *)buffer + *offset);
    void *full_pos = stack_pos;
    uint16_t stack_bytes = (uint16_t)(info->ncached_max * sizeof(void *));
    *offset += stack_bytes;
    void *empty_pos = (void *)((byte_t *)buffer + *offset);

    bin->stack_head = (void **)empty_pos;
    bin->low_bits_low_water = (uint16_t)(uintptr_t)bin->stack_head;
    bin->low_bits_full = (uint16_t)(uintptr_t)full_pos;
    bin->low_bits_empty = (uint16_t)(uintptr_t)empty_pos;

    cache_bin_info_init(&bin->bin_info, info->ncached_max);

    cache_bin_sz_t available_slots = cache_bin_diff(bin,
        bin->low_bits_full, (uint16_t)(uintptr_t)bin->stack_head);
    assert(available_slots == stack_bytes);

    if (!cache_bin_disabled(bin)) {
        assert(cache_bin_ncached_get_local(bin) == 0);
    }

    assert(cache_bin_empty_position_get(bin) == empty_pos);
    assert(stack_bytes > 0 || empty_pos == full_pos);
}

void
cache_bin_init_disabled(cache_bin_t *bin, cache_bin_sz_t max_cached) {
    const void *dummy_stack = cache_bin_disabled_bin_stack();
    size_t dummy_offset = 0;
    cache_bin_info_t dummy_info;
    cache_bin_info_init(&dummy_info, 0);
    cache_bin_init(bin, &dummy_info, (void *)dummy_stack, &dummy_offset);
    cache_bin_info_init(&bin->bin_info, max_cached);
    assert(dummy_offset == 0);
}

#include <asio/bind_executor.hpp>
#include <asio/io_context.hpp>
#include <asio/ip/tcp.hpp>
#include <asio/use_future.hpp>
#include <asio/write.hpp>
#include <cstring>
#include <functional>
#include <iostream>
#include <string>
#include <type_traits>
#include <utility>

using asio::ip::tcp;

//------------------------------------------------------------------------------
// Modified composed operation: wraps an existing async operation with a different completion signature
template <typename CompletionToken>
auto async_send_data(tcp::socket& sock,
    const char* data, CompletionToken&& token)
  // Return type deduction based on CompletionToken and handler signature
  -> typename asio::async_result<
    typename std::decay<CompletionToken>::type,
    void(std::error_code)>::return_type
{
  asio::async_completion<CompletionToken,
    void(std::error_code)> completion(token);

  // Original async_write has signature: void(error, size_t)
  // We adapt by dropping the size_t parameter via std::bind

  auto ex = asio::get_associated_executor(
      completion.completion_handler, sock.get_executor());

  asio::async_write(sock,
      asio::buffer(data, std::strlen(data)),
      asio::bind_executor(ex,
        std::bind(std::move(completion.completion_handler),
          std::placeholders::_1)));

  return completion.result.get();
}

//------------------------------------------------------------------------------
void run_callback_test()
{
  asio::io_context ioc;
  tcp::acceptor acc(ioc, {tcp::v4(), 55555});
  tcp::socket s = acc.accept();

  async_send_data(s, "Callback test message\r\n",
      [](const std::error_code& err)
      {
        if (!err)
        {
          std::cout << "Data transmitted successfully\n";
        }
        else
        {
          std::cout << "Transmission failed: " << err.message() << "\n";
        }
      });

  ioc.run();
}

//------------------------------------------------------------------------------
void run_future_test()
{
  asio::io_context ioc;
  tcp::acceptor acc(ioc, {tcp::v4(), 55555});
  tcp::socket s = acc.accept();

  std::future<void> fut = async_send_data(
      s, "Future-based test\r\n", asio::use_future);

  ioc.run();

  try
  {
    fut.get();
    std::cout << "Data sent (future)\n";
  }
  catch (const std::exception& ex)
  {
    std::cout << "Exception caught: " << ex.what() << "\n";
  }
}

//------------------------------------------------------------------------------
int main()
{
  run_callback_test();
  run_future_test();
}

