#define MAX_CALLS_LIMIT 10
#define TIME_WINDOW_MS 1000
#define BAN_DURATION_MS 10000

static u64 window_start_time = 0;
static u64 ban_end_time = 0;
static int call_counter = 0;

static bool allow_call(void) {
    u64 current_time = osGetTime();
    if (current_time < ban_end_time)
        return false;
    if (current_time - window_start_time > TIME_WINDOW_MS) {
        window_start_time = current_time;
        call_counter = 0;
    }
    call_counter++;
    if (call_counter >= MAX_CALLS_LIMIT) {
        ban_end_time = current_time + BAN_DURATION_MS;
        return false;
    }
    return true;
}

extern "C" void GameDebugLogfHandler(u32 ukn1, u32 ukn2, const char* author, u32 ukn3, const char* fmt, ...) {
    va_list ap;
    va_start(ap, fmt);
    if (allow_call() && strcmp(author, "BuildGeometry") != 0 && strcmp(author, "loadChunk") != 0) {
        char buffer[0x200] = {0};
        int res = vsnprintf(buffer, sizeof(buffer), fmt, ap);
        if (buffer[res-1] == '\n')
            buffer[res-1] = '\0';
        if (ukn2 == 2)
            Core::Debug::LogInfo("[Game.Info] " + std::string(author) + ": " + buffer);
        else if (ukn2 == 8)
            Core::Debug::LogInfo("[Game.Warn] " + std::string(author) + ": " + buffer);
        else
            Core::Debug::LogInfo(' ' + std::string(author) + ": " + buffer);
    }
    va_end(ap);
    return;
}

static __attribute__((naked)) void GameDebugLogfHook(CoreHookContext* ctx) {
    asm volatile (
        "ldmia sp!, {r0-r12, lr}\n"
        "b GameDebugLogfHandler\n"
    );
}

