// This optimization removes immutable local variables by propagating their constant values.
// It relies on the GatherImmutableLocalVars analysis to identify such variables.
// For each immutable local var, its single store value is substituted for all subsequent loads.
class RemoveConstantLocals : public BasicStmtVisitor {
 private:
  using BasicStmtVisitor::visit;
  std::unordered_set<Stmt *> const_vars_;
  std::unordered_map<Stmt *, Stmt *> var_to_const_value_;
  ImmediateIRModifier ir_modifier_;
  DeferredIRModifier deferred_op_;

 public:
  explicit RemoveConstantLocals(
      const std::unordered_set<Stmt *> &const_vars,
      IRNode *node)
      : const_vars_(const_vars), ir_modifier_(node) {
  }

  void visit(AllocaStmt *stmt) override {
    if (const_vars_.find(stmt) != const_vars_.end()) {
      deferred_op_.remove(stmt);
    }
  }

  void visit(LocalLoadStmt *stmt) override {
    if (const_vars_.find(stmt->source) != const_vars_.end()) {
      ir_modifier_.substitute_usage(
          stmt, var_to_const_value_[stmt->source]);
      deferred_op_.remove(stmt);
    }
  }

  void visit(LocalStoreStmt *stmt) override {
    if (const_vars_.find(stmt->dest) != const_vars_.end()) {
      QD_ASSERT(var_to_const_value_.find(stmt->dest) == var_to_const_value_.end());
      var_to_const_value_[stmt->dest] = stmt->value;
      deferred_op_.remove(stmt);
    }
  }

  static void execute(IRNode *node) {
    RemoveConstantLocals pass(
        irpass::analysis::collect_immutable_locals(node), node);
    node->accept(&pass);
    pass.deferred_op_.apply_changes();
  }
};

namespace irpass {
void remove_constant_local_vars(IRNode *root) {
  QD_AUTO_PROF;
  RemoveConstantLocals::execute(root);
}
}  // namespace irpass
}  // namespace quadrants::lang

