#ifndef USE_ALPHA
#define REAL_PART(x, y)  (x)
#define IMAGE_PART(x, y) (y)
#else
#define REAL_PART(x, y)  (alpha_r * (x) - alpha_i * (y))
#define IMAGE_PART(x, y) (alpha_i * (x) + alpha_r * (y))
#endif
#if defined(REAL_ONLY)
#define CMULT(x, y) (REAL_PART(x, y))
#elif defined(IMAGE_ONLY)
#define CMULT(x, y) (IMAGE_PART(x, y))
#else
#define CMULT(x, y) (REAL_PART(x, y) + IMAGE_PART(x, y))
#endif

int CNAME(BLASLONG rows, BLASLONG cols, FLOAT *input_a, BLASLONG stride_a,
#ifdef USE_ALPHA
          FLOAT alpha_r, FLOAT alpha_i, 
#endif
          FLOAT *output_b) {
  BLASLONG index;
  FLOAT *a_ptr, val1, val2;
  stride_a *= 2;

  while (cols > 0) {
    a_ptr = input_a;
    input_a += 2;

    for (index = 0; index < rows; index++) {
      val1 = *(a_ptr + 0);
      val2 = *(a_ptr + 1);

      *(output_b + 0) = CMULT(val1, val2);

      a_ptr += stride_a;
      output_b++;
    }
    cols--;
  }

  return 0;
}

