//************************************************************************
void GetDistanceParser::operator()(Message &request) {
  wchar_t char1, char2;
  request >> char1 >> char2 >> clr;
  TPoint distance = TFontManager::instance()->getDistance(char1, char2);
  request << QString("success") << distance.x << distance.y;
}
//************************************************************************
//    DrawCharVI Parser
//************************************************************************
void DrawCharVIParser::operator()(Message &request) {
  wchar_t charCode, nextCode;
  request >> charCode >> nextCode >> clr;
  TVectorImageP vi(new TVectorImage);
  TPoint p = TFontManager::instance()->drawChar(vi, charCode, nextCode);
  request << QString("success") << p.x << p.y;
  // Serialize vector image strokes
  std::vector<TThickPoint> controlPoints;
  unsigned int i, strokeCount = vi->getStrokeCount();
  for (i = 0; i < strokeCount; ++i) {
    TStroke *stroke = vi->getStroke(i);
    controlPoints.clear();
    stroke->getControlPoints(controlPoints);
    request << controlPoints;
  }
}
//************************************************************************
//    DrawCharGR Parser
//************************************************************************
void DrawCharGRParser::operator()(Message &request) {
  int inkValue;
  QString sharedMemoryId;
  wchar_t charCode, nextCode;
  request >> inkValue >> sharedMemoryId >> charCode >> nextCode >> clr;
  // Generate the character raster
  TRasterGR8P charRaster;
  TPoint offset;
  TPoint origin =
      TFontManager::instance()->drawChar(charRaster, offset, charCode, nextCode);
  // Determine raster dimensions and memory size
  int width = charRaster->getLx(), height = charRaster->getLy();
  int bufferSize = width * height * sizeof(TPixelGR8);
  // Allocate shared memory segment
  {
    tipc::DefaultMessageParser<SHMEM_REQUEST> parser;
    Message shmRequest;
    shmRequest << sharedMemoryId << bufferSize << reset;
    parser(shmRequest);
    QString response;
    shmRequest >> reset >> response;
    if (response != QString("success")) {
      request << QString("failure");
      return;
    }
  }
  // Transfer raster data to shared memory
  QSharedMemory shmem(sharedMemoryId);
  shmem.attach();
  shmem.lock();
  memcpy(shmem.data(), charRaster->getRawData(), bufferSize);
  shmem.unlock();
  shmem.detach();
  request << QString("success") << width << height << origin.x << origin.y;
}
//************************************************************************
//    DrawCharCM Parser
//************************************************************************
void DrawCharCMParser::operator()(Message &request) {
  int inkValue;
  QString sharedMemoryId;
  wchar_t charCode, nextCode;
  request >> inkValue >> sharedMemoryId >> charCode >> nextCode >> clr;
  // Generate the character raster
  TRasterCM32P charRaster;
  TPoint offset;
  TPoint origin = TFontManager::instance()->drawChar(
      charRaster, offset, inkValue, charCode, nextCode);
  // Determine raster dimensions and memory size
  int width = charRaster->getLx(), height = charRaster->getLy();
  int bufferSize = width * height * sizeof(TPixelCM32);
  // Allocate shared memory segment
  {
    tipc::DefaultMessageParser<SHMEM_REQUEST> parser;
    Message shmRequest;
    shmRequest << sharedMemoryId << bufferSize << reset;
    parser(shmRequest);
    QString response;
    shmRequest >> reset >> response;
    if (response != QString("success")) {
      request << QString("failure");
      return;
    }
  }
  // Transfer raster data to shared memory
  QSharedMemory shmem(sharedMemoryId);
  shmem.attach();
  shmem.lock();
  memcpy(shmem.data(), charRaster->getRawData(), bufferSize);
  shmem.unlock();
  shmem.detach();
  request << QString("success") << width << height << origin.x << origin.y;
}
