#include <rclcpp/rclcpp.hpp>
#include <grid_map_ros/grid_map_ros.hpp>
#include <grid_map_msgs/msg/grid_map.hpp>
#include <cmath>
#include <memory>
#include <utility>

int main(int argc, char ** argv)
{
  // Initialize ROS2 and setup publisher
  rclcpp::init(argc, argv);
  rclcpp::Node::SharedPtr ros_node = std::make_shared<rclcpp::Node>("grid_map_demo_publisher");
  auto map_publisher = ros_node->create_publisher<grid_map_msgs::msg::GridMap>(
    "terrain_map", rclcpp::QoS(1).transient_local());

  // Create grid map with elevation layer
  grid_map::GridMap terrain_map({"height"});
  terrain_map.setFrameId("world");
  terrain_map.setGeometry(grid_map::Length(1.5, 2.2), 0.05);

  RCLCPP_INFO(
    ros_node->get_logger(),
    "Initialized map with dimensions %f x %f meters (%i x %i cells).",
    terrain_map.getLength().x(), terrain_map.getLength().y(),
    terrain_map.getSize()(0), terrain_map.getSize()(1));

  // Main loop configuration
  rclcpp::Rate update_rate(20.0);
  rclcpp::SteadyClock clock;

  while (rclcpp::ok()) {
    // Update map data
    rclcpp::Time current_time = ros_node->now();

    for (grid_map::GridMapIterator iter(terrain_map); !iter.isPastEnd(); ++iter) {
      grid_map::Position loc;
      terrain_map.getPosition(*iter, loc);

      terrain_map.at(
        "height",
        *iter) = -0.03 + 0.25 * std::sin(2.5 * current_time.seconds() + 4.0 * loc.y()) * loc.x();
    }

    // Publish updated map
    terrain_map.setTimestamp(current_time.nanoseconds());
    std::unique_ptr<grid_map_msgs::msg::GridMap> msg_ptr;
    msg_ptr = grid_map::GridMapRosConverter::toMessage(terrain_map);
    map_publisher->publish(std::move(msg_ptr));

    RCLCPP_INFO_THROTTLE(ros_node->get_logger(), clock, 2000, "Terrain map updated and published.");

    // Maintain loop rate
    update_rate.sleep();
  }

  return 0;
}

