#if defined (DEBUG_MEMORY)
static void
memFailure (
    enum mcheck_status status
    ) {
    fprintf(stderr, "CRITICAL: Memory integrity error: %s\n",
                (status == MCHECK_DISABLED) ? "Consistency checking is not enabled" :
                (status == MCHECK_OK)       ? "Block is intact" :
                (status == MCHECK_FREE)     ? "Double-free detected" :
                (status == MCHECK_HEAD)     ? "Buffer overflow before allocated block" :
                (status == MCHECK_TAIL)     ? "Buffer overflow after allocated block" :
                "<unknown cause>");
    exit(1);
}
#endif

//------------------------------------------------------------------------------
//  ENTRY POINT
int
main (
    int     numArgs,
    char *  args [],
    char *  envVars []
    ) {
#if defined (DEBUG_MEMORY)
    int rc = mcheck_pedantic (& memFailure);
    printf ("TRACE: mcheck_pedantic returned %d\n", rc);
#endif

    try {
        DeltaresHydro * context = new DeltaresHydro (numArgs, args, envVars);
        if (! context->initialized) return 1;
        context->Execute();
        delete context;
        return 0;
        }
    catch (std::exception& ex) {
        printf ("d_hydro ABORT: C++ Exception: %s\n", ex.what());
        return 1;
        }
    catch (Exception *ex) {
        printf ("d_hydro ABORT: %s\n", ex->message);
        return 1;
        }
    catch (char * str) {
        printf ("ABORT in FLOW2D3D: %s\n", str);
        return 1;
        }
}

//------------------------------------------------------------------------------
//  Constructor.  Initialize the object, read the configuration file and load
//  and invoke the start component's entry function.  All of the work is done
//  by the start component, including loading other components if necessary.
//  ToDo: make load-and-start a generic function available to any component.
DeltaresHydro::DeltaresHydro (
    int     argc,
    char *  argv [],
    char *  envp []
    ) {
    this->programPath = strdup (argv[0]);

#if defined(HAVE_CONFIG_H)
    this->programName = strdup (basename (argv[0]));
#else
    char * suffix = new char[5];
    this->programName = new char[MAXSTRING];
    _splitpath (argv[0], NULL, NULL, this->programName, suffix);
    StringCbCatA (this->programName, MAXSTRING, suffix);
    delete [] suffix;
#endif

    this->remoteArg = NULL;
    this->terminated = false;

    Log::Mask   debugLevel = Log::ALWAYS;  // selector of debugging/trace information
                                           // minDebug: Log::SILENT  maxDebug: Log::TRACE
    FILE *      logStream = stdout;        // log file descriptor

    // Reassemble command-line arguments for later use (to spawn remote slave processes)
    int totalLen = 0;
    for (int idx = 1 ; idx < argc ; idx++)
        totalLen += strlen (argv[idx]) + 1;
    this->fullArgs = new char [totalLen+1];
    memset (this->fullArgs, '\0', totalLen+1);
    char * cursor = this->fullArgs;
    for (int idx = 1 ; idx < argc ; idx++) {
        int len = strlen (argv[idx]);
        memcpy (cursor, argv[idx], len);
        cursor += len;
        *cursor++ = ' ';
        }

    // Process command-line arguments
    int opt;
    while ((opt = getopt (argc, argv, (char *) "d:l:S:v?")) != -1) {
        switch (opt) {
            case 'd': {
                if (sscanf (optarg, "%i", &debugLevel) != 1)
                    throw new Exception("Invalid debug mask (-d option)");
                break;
                }
            case 'l': {
                logStream = fopen (optarg, "w");
                if (logStream == NULL)
                    throw new Exception("Cannot create log file \"%s\"", optarg);
                break;
                }
            case 'S': {
                this->remoteArg = optarg;
                break;
                }
            case 'v': {
                displayInfo (this->programName);
                this->terminated = true;
                return;
                }
            case '?': {
                showHelp (this->programName);
                this->terminated = true;
                return;
                }
            default: {
                throw new Exception("Invalid command-line argument.  Execute \"%s -?\" for usage", this->programName);
                }
            }
        }

    if (argc - optind != 1)
        throw new Exception("Improper usage.  Execute \"%s -?\" for usage", this->programName);

    this->timer = new Clock ();
    this->logger = new Log (logStream, this->timer, debugLevel);

    // Read XML configuration file into tree structure
    this->configFile = argv[optind];
    FILE * fp;
    if (strcmp (this->configFile, "-") == 0)
        fp = stdin;
    else {
        fp = fopen (this->configFile, "r");
        if (fp == NULL)
            throw new Exception("Cannot open configuration file \"%s\"", this->configFile);
        }
    this->xmlRoot = new XmlTree (fp);
    fclose (fp);

    // Get the name and configuration subtree of the start component
    XmlTree * root = this->xmlRoot->Lookup ("/deltaresHydro");
    if (root == NULL)
        throw new Exception("Configuration file \"%s\" does not have a deltaresHydro root element", this->configFile);

    const char * starterName = "flow2D3D";
    this->starter = root->Lookup (starterName);
    if (this->starter == NULL)
        throw new Exception("Configuration element for start component \"%s\" is missing", starterName);

#if defined (MONOLITHIC_FLOW2D3D)
    this->initialized = FLOW2D3D_MonolithicInit (this);
#else
    XmlTree * libElement = this->starter->Lookup ("library");
    if (libElement == NULL)
        throw new Exception("The start component \"%s\" does not contain a library element", starterName);
    const char * libName = libElement->charData;

#if defined (HAVE_CONFIG_H)
#if defined (OSX)
    throw new Exception("ABORT: %s has not be ported to Apple Mac OS/X yet", this->programName);
#else
    char libPath [strlen (libName) + 3+3+1];
    if (strchr (libName, '/') == NULL && strchr (libName, '.') == NULL) {
        sprintf (libPath, "lib%s%s", libName, D3D_PLUGIN_EXT);
        libName = libPath;
        }
    this->logger->Write (Log::DETAIL, "Loading start library \"%s\"", libName);
    void * handle = dlopen (libName, RTLD_LAZY);
    if (handle == NULL)
        throw new Exception("Cannot load component library \"%s\": %s", libName, dlerror ());
    StartComponentEntry entryPoint = (StartComponentEntry) dlsym (handle, this->startEntry);
    if (entryPoint == NULL)
        throw new Exception("Cannot find function \"%s\" in library \"%s\"", this->startEntry, libName);
    this->logger->Write (Log::DETAIL, "Calling entry function in start library");
    this->initialized = entryPoint (this);
#endif
#elif defined (WIN32)
    char * dllName = new char[strlen (libName) + 4+1];
    if (strchr (libName, '/') == NULL && strchr (libName, '\\') == NULL && strchr (libName, '.') == NULL) {
        sprintf (dllName, "%s.dll", libName);
        libName = dllName;
        }
    this->logger->Write (Log::DETAIL, "Loading start library \"%s\"", libName);
    HINSTANCE dllhandle = LoadLibrary (LPCSTR(libName));
    if (dllhandle == NULL)
        throw new Exception("Cannot load component library \"%s\". Return code: %d", libName, GetLastError());
    typedef int (__cdecl *MYPROC)(LPWSTR);
    MYPROC entryPoint = (MYPROC) GetProcAddress (dllhandle, this->startEntry);
    if (entryPoint == NULL)
        throw new Exception("Cannot find function \"%s\" in library \"%s\". Return code: %d", this->startEntry, libName, GetLastError());
    this->logger->Write (Log::DETAIL, "Calling entry function in start library");
    this->initialized = ((entryPoint) ((LPWSTR) this));
    delete [] dllName;
#endif
#endif      // MONOLITHIC_FLOW2D3D
}

//------------------------------------------------------------------------------
//  Destructor
DeltaresHydro::~DeltaresHydro (
    void
    ) {
    if (this->terminated)
        return;

    delete this->starterComponent;

#if defined(HAVE_CONFIG_H)
    free (this->programName);
#else
    delete [] this->programName;
#endif

    this->logger->Write (Log::ALWAYS, "d_hydro shutting down normally");
    delete this->timer;
    delete this->xmlRoot;
    free (this->programPath);
    delete this->logger;
    delete [] this->fullArgs;
}

//------------------------------------------------------------------------------
void
DeltaresHydro::Execute (
    void
    ) {
    try {
        if (this->terminated == true) return;
        this->starterComponent->Run ();
        }
    catch (Exception *ex) {
        printf ("#### d_hydro ABORT: %s\n", ex->message);
        }
}

