#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int size, queries;
    if (!(cin >> size >> queries)) return 0;

    vector<int> arr(size + 1);
    for (int idx = 1; idx <= size; ++idx) cin >> arr[idx];

    vector<pair<int, int>> operations;
    operations.reserve(2200000);

    vector<int> queryResults(queries);
    vector<int> positionMap(size + 1);

    for (int idx = 1; idx <= size; ++idx) 
        positionMap[arr[idx]] = idx;

    long long totalCount = size;

    for (int qIdx = 0; qIdx < queries; ++qIdx) {
        int left, right;
        cin >> left >> right;

        vector<int> segmentValues;
        segmentValues.reserve(right - left + 1);

        for (int j = left; j <= right; ++j) 
            segmentValues.push_back(arr[j]);

        sort(segmentValues.begin(), segmentValues.end());

        long long currentPos;
        if (segmentValues.empty()) {
            queryResults[qIdx] = 1;
        } else {
            currentPos = positionMap[segmentValues[0]];

            for (size_t t = 1; t < segmentValues.size(); ++t) {
                int valueIndex = positionMap[segmentValues[t]];
                operations.emplace_back((int)currentPos, valueIndex);
                ++totalCount;
                currentPos = totalCount;
            }
            queryResults[qIdx] = (int)currentPos;
        }
    }

    cout << totalCount << "\n";

    for (auto &op : operations) {
        cout << op.first << " " << op.second << "\n";
    }

    for (int i = 0; i < queries; ++i) {
        if (i) cout << " ";
        cout << queryResults[i];
    }
    cout << "\n";

    return 0;
}

