int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int size;
    long long targetValue;
    if (!(cin >> size >> targetValue)) return 0;

    vector<long long> values(size);
    for (int index = 0; index < size; ++index) {
        cin >> values[index];
    }

    // Compute LIS length (strictly increasing)
    vector<long long> minTails;
    minTails.reserve(size);

    for (long long current : values) {
        auto pos = lower_bound(minTails.begin(), minTails.end(), current);
        if (pos == minTails.end()) {
            minTails.push_back(current);
        } else {
            *pos = current;
        }
    }

    int lisLength = (int)minTails.size();
    cout << lisLength << "\n";

    for (int repeat = 0; repeat < 10; ++repeat) {
        cout << 1 << " " << 1 << " " << 0 << "\n";
    }

    return 0;
}

