namespace {
class GenericToNVVMConverter {
public:
  bool executeOnModule(Module &module);
private:
  Value *convertConstant(Module *mod, Function *func, Constant *constVal,
                         IRBuilder<> &builder);
  Value *convertConstantVectorOrAggregate(Module *mod, Function *func,
                                          Constant *constVal,
                                          IRBuilder<> &builder);
  Value *convertConstantExpression(Module *mod, Function *func, ConstantExpr *constExpr,
                                   IRBuilder<> &builder);
  typedef ValueMap<GlobalVariable *, GlobalVariable *> GlobalVarMapType;
  typedef ValueMap<Constant *, Value *> ConstantToValueMapType;
  GlobalVarMapType globalVarMap;
  ConstantToValueMapType constantToValueMap;
};
} // end namespace
bool GenericToNVVMConverter::executeOnModule(Module &module) {
  // Create a duplicate of each global variable that uses the default address space.
  // The duplicate is created with the global address space specifier, and the pair
  // (original global variable and its duplicate) is stored in globalVarMap for later use.
  for (GlobalVariable &globalVar : llvm::make_early_inc_range(module.globals())) {
    if (globalVar.getType()->getAddressSpace() == llvm::ADDRESS_SPACE_GENERIC &&
        !llvm::isTexture(globalVar) && !llvm::isSurface(globalVar) && !llvm::isSampler(globalVar) &&
        !globalVar.getName().starts_with("llvm.")) {
      GlobalVariable *newGlobalVar = new GlobalVariable(
          module, globalVar.getValueType(), globalVar.isConstant(), globalVar.getLinkage(),
          globalVar.hasInitializer() ? globalVar.getInitializer() : nullptr, "", &globalVar,
          globalVar.getThreadLocalMode(), llvm::ADDRESS_SPACE_GLOBAL);
      newGlobalVar->copyAttributesFrom(&globalVar);
      newGlobalVar->copyMetadata(&globalVar, /*Offset=*/0);
      globalVarMap[&globalVar] = newGlobalVar;
    }
  }
  // Exit early if all global variables already have explicit address spaces.
  if (globalVarMap.empty()) {
    return false;
  }
  // Traverse instructions in function definitions and replace any usage of original
  // global variables from globalVarMap with their corresponding duplicates.
  // If needed, promote constants to instructions.
  for (Function &func : module) {
    if (func.isDeclaration()) {
      continue;
    }
    IRBuilder<> builder(func.getEntryBlock().getFirstNonPHIOrDbg());
    for (BasicBlock &bb : func) {
      for (Instruction &inst : bb) {
        for (unsigned idx = 0, limit = inst.getNumOperands(); idx < limit; ++idx) {
          Value *operand = inst.getOperand(idx);
          if (isa<Constant>(operand)) {
            inst.setOperand(
                idx, convertConstant(&module, &func, cast<Constant>(operand), builder));
          }
        }
      }
    }
    constantToValueMap.clear();
  }
  // Transfer globalVarMap into a standard value map.
  ValueToValueMapTy valueMap;
  for (auto iter = globalVarMap.begin(), endIter = globalVarMap.end(); iter != endIter; ++iter)
    valueMap[iter->first] = iter->second;
  // Process global variable initializers: replace any usage of original global variables
  // from globalVarMap with their corresponding duplicates. Duplicates must be bitcast to
  // the original types since cvta cannot be used in global initializer contexts.
  for (GlobalVarMapType::iterator iter = globalVarMap.begin(), endIter = globalVarMap.end(); iter != endIter;) {
    GlobalVariable *origGV = iter->first;
    GlobalVariable *newGV = iter->second;
    auto nextIter = std::next(iter);
    globalVarMap.erase(iter);
    iter = nextIter;
    Constant *bitcastNewGV = ConstantExpr::getPointerCast(newGV, origGV->getType());
    // At this point, remaining uses of origGV should only appear in global initializers,
    // as other uses were already replaced during instruction traversal.
    origGV->replaceAllUsesWith(bitcastNewGV);
    std::string name = std::string(origGV->getName());
    origGV->eraseFromParent();
    newGV->setName(name);
  }
  assert(globalVarMap.empty() && "Expected it to be empty by now");
  return true;
}
Value *GenericToNVVMConverter::convertConstant(Module *mod, Function *func, Constant *constVal,
                                               IRBuilder<> &builder) {
  // If the constant constVal has already been transformed in the given function func,
  // return the previously computed result.
  ConstantToValueMapType::iterator foundIt = constantToValueMap.find(constVal);
  if (foundIt != constantToValueMap.end()) {
    return foundIt->second;
  }
  Value *convertedValue = constVal;
  if (isa<GlobalVariable>(constVal)) {
    // If the constant constVal is a global variable present in globalVarMap, substitute
    //
    //   addrspacecast globalVarMap[constVal] to addrspace(0)
    //
    // instead of using constVal directly.
    GlobalVarMapType::iterator iter = globalVarMap.find(cast<GlobalVariable>(constVal));
    if (iter != globalVarMap.end()) {
      GlobalVariable *gv = iter->second;
      convertedValue = builder.CreateAddrSpaceCast(
          gv,
          PointerType::get(gv->getValueType(), llvm::ADDRESS_SPACE_GENERIC));
    }
  } else if (isa<ConstantAggregate>(constVal)) {
    // If any element in the constant vector or aggregate constVal involves a global
    // variable from globalVarMap, reconstruct the constant using a sequence of instructions.
    convertedValue = convertConstantVectorOrAggregate(mod, func, constVal, builder);
  } else if (isa<ConstantExpr>(constVal)) {
    // If any operand in the constant expression constVal involves a global variable
    // from globalVarMap, reconstruct the expression using a sequence of instructions.
    convertedValue = convertConstantExpression(mod, func, cast<ConstantExpr>(constVal), builder);
  }
  constantToValueMap[constVal] = convertedValue;
  return convertedValue;
}
Value *GenericToNVVMConverter::convertConstantVectorOrAggregate(
    Module *mod, Function *func, Constant *constVal, IRBuilder<> &builder) {
  bool operandsModified = false;
  SmallVector<Value *, 4> newOperands;
  unsigned operandCount = constVal->getNumOperands();
  // Determine whether any element uses a global variable from globalVarMap,
  // and thus needs conversion to another value.
  for (unsigned idx = 0; idx < operandCount; ++idx) {
    Value *operand = constVal->getOperand(idx);
    Value *newOperand = convertConstant(mod, func, cast<Constant>(operand), builder);
    operandsModified |= (operand != newOperand);
    newOperands.push_back(newOperand);
  }
  // If no elements were changed, return constVal unchanged.
  if (!operandsModified) {
    return constVal;
  }
  // Otherwise, build an equivalent vector or aggregate using instructions and updated elements.
  Value *resultValue = PoisonValue::get(constVal->getType());
  if (isa<ConstantVector>(constVal)) {
    for (unsigned idx = 0; idx < operandCount; ++idx) {
      Value *index = ConstantInt::get(Type::getInt32Ty(mod->getContext()), idx);
      resultValue = builder.CreateInsertElement(resultValue, newOperands[idx], index);
    }
  } else {
    for (unsigned idx = 0; idx < operandCount; ++idx) {
      resultValue =
          builder.CreateInsertValue(resultValue, newOperands[idx], ArrayRef(idx));
    }
  }
  return resultValue;
}
Value *GenericToNVVMConverter::convertConstantExpression(Module *mod, Function *func, ConstantExpr *constExpr,
                                                         IRBuilder<> &builder) {
  bool operandsModified = false;
  SmallVector<Value *, 4> newOperands;
  unsigned operandCount = constExpr->getNumOperands();
  // Check if any operand involves a global variable from globalVarMap,
  // and thus requires conversion.
  for (unsigned idx = 0; idx < operandCount; ++idx) {
    Value *operand = constExpr->getOperand(idx);
    Value *newOperand = convertConstant(mod, func, cast<Constant>(operand), builder);
    operandsModified |= (operand != newOperand);
    newOperands.push_back(newOperand);
  }
  // If no operands were modified, return constExpr unchanged.
  if (!operandsModified) {
    return constExpr;
  }
  // Otherwise, construct the equivalent instruction using updated operands.
  unsigned opcode = constExpr->getOpcode();
  switch (opcode) {
  case Instruction::ICmp:
    // Integer compare constant expression
    return builder.CreateICmp(CmpInst::Predicate(constExpr->getPredicate()),
                              newOperands[0], newOperands[1]);
  case Instruction::FCmp:
    // Floating-point compare constant expression
    llvm_unreachable("Address space conversion should have no effect "
                     "on floating-point compare constant expressions!");
  case Instruction::ExtractElement:
    // Extract element constant expression
    return builder.CreateExtractElement(newOperands[0], newOperands[1]);
  case Instruction::InsertElement:
    // Insert element constant expression
    return builder.CreateInsertElement(newOperands[0], newOperands[1],
                                       newOperands[2]);
  case Instruction::ShuffleVector:
    // Shuffle vector constant expression
    return builder.CreateShuffleVector(newOperands[0], newOperands[1],
                                       newOperands[2]);
  case Instruction::GetElementPtr:
    // Get element pointer constant expression
    return builder.CreateGEP(cast<GEPOperator>(constExpr)->getSourceElementType(),
                             newOperands[0],
                             ArrayRef(&newOperands[1], operandCount - 1), "",
                             cast<GEPOperator>(constExpr)->isInBounds());
  case Instruction::Select:
    // Select constant expression
    return builder.CreateSelect(newOperands[0], newOperands[1], newOperands[2]);
  default:
    // Binary constant expression
    if (Instruction::isBinaryOp(opcode)) {
      return builder.CreateBinOp(Instruction::BinaryOps(constExpr->getOpcode()),
                                 newOperands[0], newOperands[1]);
    }
    // Unary constant expression
    if (Instruction::isCast(opcode)) {
      return builder.CreateCast(Instruction::CastOps(constExpr->getOpcode()),
                                newOperands[0], constExpr->getType());
    }
    llvm_unreachable("GenericToNVVM encountered an unsupported constant expression");
  }
}
