#include <bits/stdc++.h>
using namespace std;

/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     TreeNode *left;
 *     TreeNode *right;
 *     TreeNode() : val(0), left(nullptr), right(nullptr) {}
 *     TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
 *     TreeNode(int x, TreeNode *left, TreeNode *right) : val(x), left(left), right(right) {}
 * };
 */
struct TreeNode {
      int val;
      TreeNode *left;
      TreeNode *right;
      TreeNode() : val(0), left(nullptr), right(nullptr) {}
      TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
      TreeNode(int x, TreeNode *left, TreeNode *right) : val(x), left(left), right(right) {}
  };

class Solution {
public:
    int sumRange = 0;

    void traverseInOrder(TreeNode* node, int minVal, int maxVal) {
        if (node == NULL) return;

        // Traverse left subtree if current value is greater than minVal
        if (node->val > minVal) {
            traverseInOrder(node->left, minVal, maxVal);
        }

        // Add current node value if it falls within the range
        if (node->val >= minVal && node->val <= maxVal) {
            sumRange += node->val;
        }

        // Traverse right subtree if current value is less than maxVal
        if (node->val < maxVal) {
            traverseInOrder(node->right, minVal, maxVal);
        }
    }

    int rangeSumBST(TreeNode* root, int low, int high) {
        sumRange = 0; // Reset sum for each call
        traverseInOrder(root, low, high);
        return sumRange;
    }
};

int main() {
    // Example usage - construct a sample BST
    TreeNode* root = new TreeNode(10);
    root->left = new TreeNode(5);
    root->right = new TreeNode(15);
    root->left->left = new TreeNode(3);
    root->left->right = new TreeNode(7);
    root->right->right = new TreeNode(18);

    Solution solution;
    int minVal = 7, maxVal = 15;
    int calculatedSum = solution.rangeSumBST(root, minVal, maxVal);

    cout << "Sum of nodes in range [" << minVal << ", " << maxVal << "]: " << calculatedSum << endl;
    return 0;
}

