int main() {
    vector<int> numbers;
    vector<int> numbers1(5, 20);  // 5 elements with value 20
    vector<int> numbers2 = {10, 20, 30, 40, 50};
    vector<int> numbers3(numbers2);    // copy of numbers2

    for(int index = 1; index <= 10; index++) {
        numbers.push_back(index);
    }

    //Method 1: Traditional For Loop
    // for(int i = 0; i < numbers.size(); i++){
    //     cout << numbers[i] << " ";
    // }

    //Method 2: Range-based for loop
    for(int value : numbers) {
        cout << value << " ";
    }
    cout << endl;

    numbers.pop_back();
    numbers.emplace_back(100);    // insert at the end of the vector. Creates inplace object.
    cout << "value at 5th index: " << numbers.at(5) << endl;
    cout << numbers.front() << endl;
    cout << numbers.back() << endl;

    numbers.pop_back();
    cout << numbers.size() << endl;
    cout << numbers.capacity() << endl;
    cout << numbers.max_size() << endl;

    numbers.erase(numbers.begin() + 2);   // erase 3rd element
    numbers.erase(numbers.begin() + 2, numbers.begin() + 4);   // erase 3rd and 4th element(range)
    numbers.clear();  // clear the vector
    cout << numbers.empty() << endl;  // check if vector is empty or not

    numbers.insert(numbers.begin(), 7); // insert 7 at the beginning

    // erase and clear affect the size of the vector but not the capacity.

    //Iterators
    vector<int> numbers4 = {100, 200, 300, 400, 500};
    vector<int>::iterator iter; // we can also use auto
    for(iter = numbers4.begin(); iter != numbers4.end(); iter++) {
        cout << *iter << " ";
    }
    cout << endl;

    //Reverse Iterators
    vector<int>::reverse_iterator riter;  // we can also use auto
    for(riter = numbers4.rbegin(); riter != numbers4.rend(); riter++) {
        cout << *riter << " ";
    }
    cout << endl;

    return 0;
}

