namespace eld {

static bool RISCVEmulateELF(LinkerScript &script, LinkerConfig &config) {
  // RISC-V currently supports little-endian only.
  config.targets().setEndian(TargetOptions::Little);

  if (config.targets().getArch() == "riscv32")
    config.targets().setBitClass(32);

  if (config.targets().getArch() == "riscv64")
    config.targets().setBitClass(64);

  if (!ELDEmulateELF(script, config))
    return false;

  return true;
}

//===----------------------------------------------------------------------===//
// emulateRISCVLD - helper function to perform RISC-V link emulation
//===----------------------------------------------------------------------===//
bool emulateRISCVLD(LinkerScript &script, LinkerConfig &config) {
  return RISCVEmulateELF(script, config);
}

