// Constants for LEGO Power Functions protocol
const uint16_t kLegoPfBitMark = 158;
const uint16_t kLegoPfHdrSpace = 1026;
const uint16_t kLegoPfZeroSpace = 263;
const uint16_t kLegoPfOneSpace = 553;
const uint32_t kLegoPfMinCommandLength = 16000;  // 16ms

#if SEND_LEGOPF
/// Send a LEGO Power Functions message.
/// Status: Beta / Should work.
/// @param[in] data The message to be sent.
/// @param[in] nbits The number of bits of message to be sent.
/// @param[in] repeat The number of times the command is to be repeated.
/// @note Non-zero repeats result in at least 5 messages per specification.
void IRsend::sendLegoPf(const uint64_t data, const uint16_t nbits,
                        const uint16_t repeat) {
  uint8_t channel_id = ((data >> (nbits - 4)) & 0b11) + 1;
  if (repeat != 0) {
    // We are in repeat mode.
    // Specification requires a pause before transmission.
    if (channel_id < 4) space((4 - channel_id) * kLegoPfMinCommandLength);

    // Specification requires at least 5 message repeats.
    for (uint16_t r = 0; r < std::max(repeat, static_cast<uint16_t>(5)); r++) {
      // LEGO uses a special repeat mode with varying start-to-start times.
      sendGeneric(kLegoPfBitMark, kLegoPfHdrSpace,
                  kLegoPfBitMark, kLegoPfOneSpace,
                  kLegoPfBitMark, kLegoPfZeroSpace,
                  kLegoPfBitMark, kLegoPfHdrSpace,
                  ((r < 2) ? 5 : (6 + 2 * channel_id)) * kLegoPfMinCommandLength,
                  data, nbits, 38000, true, 0, kDutyDefault);
    }
  } else {  // No repeat, just a single message.
    sendGeneric(kLegoPfBitMark, kLegoPfHdrSpace,
                kLegoPfBitMark, kLegoPfOneSpace,
                kLegoPfBitMark, kLegoPfZeroSpace,
                kLegoPfBitMark, kLegoPfHdrSpace,
                kLegoPfMinCommandLength * 5,
                data, nbits, 38000, true, 0, kDutyDefault);
  }
}
#endif  // SEND_LEGO

#if DECODE_LEGOPF
/// Decode the supplied LEGO Power Functions message.
/// Status: Stable / Appears to work correctly.
/// @param[in,out] results Pointer to the data buffer and decoded result storage.
/// @param[in] offset Starting index in rawbuf for decoding.
/// @param[in] nbits Expected number of data bits.
/// @param[in] strict Flag indicating whether strict validation is required.
/// @return True if decoding succeeds, false otherwise.
bool IRrecv::decodeLegoPf(decode_results* results, uint16_t offset,
                          const uint16_t nbits, const bool strict) {
  // Check basic feasibility based on bit count if strict mode is enabled.
  if (strict && nbits != kLegoPfBits) return false;

  uint64_t data = 0;

  // Attempt to match header, data, and footer sections.
  if (!matchGeneric(results->rawbuf + offset, &data,
                    results->rawlen - offset, nbits,
                    kLegoPfBitMark, kLegoPfHdrSpace,
                    kLegoPfBitMark, kLegoPfOneSpace,
                    kLegoPfBitMark, kLegoPfZeroSpace,
                    kLegoPfBitMark, kLegoPfMinCommandLength,
                    true)) return false;

  // Perform LRC (Longitudinal Redundancy Check) validation if strict mode is on.
  if (strict) {
    uint16_t lrc_data = data;
    uint8_t lrc = 0xF;
    for (uint8_t i = 0; i < 4; i++) {
      lrc ^= (lrc_data & 0xF);
      lrc_data >>= 4;
    }
    if (lrc != 0) return false;
  }

  // Store decoded information upon success.
  results->decode_type = LEGOPF;
  results->bits = nbits;
  results->value = data;
  results->address = ((data >> (nbits - 4)) & 0b11) + 1;  // Channel ID
  results->command = (data >> 4) & 0xFF;  // Payload between Channel ID and LRC

  return true;
}
#endif  // DECODE_LEGOPF

