#include <iostream>
#include <vector>
using namespace std;

// Maximum size for the answer array
const int MAX_SIZE = 200005;
int result[MAX_SIZE];

// Recursive function using divide and conquer to reconstruct the array
// Based on the observation: if a segment has a mode whose frequency equals 
// the segment length, then all elements in that segment are identical.
// Otherwise, we split the segment. With at most k distinct values, 
// the query complexity is O(k log(n/k)), suitable for k up to 25000.
void reconstruct(int left, int right) {
    if (left > right) return;

    // Ask interactive query about the range [left, right]
    cout << "? " << left << " " << right << endl;

    int mode_value, frequency;
    cin >> mode_value >> frequency;

    // Handle error condition
    if (mode_value == -1) exit(0);

    // If frequency matches segment length, entire segment is filled with mode_value
    if (frequency == right - left + 1) {
        for (int idx = left; idx <= right; ++idx) {
            result[idx] = mode_value;
        }
        return;
    }

    // Segment contains mixed values; split and process recursively
    int center = (left + right) / 2;
    reconstruct(left, center);
    reconstruct(center + 1, right);
}

int main() {
    // Speed up I/O operations
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    if (cin >> n) {
        // Begin reconstruction of the full array
        reconstruct(1, n);

        // Output final reconstructed array
        cout << "! ";
        for (int i = 1; i <= n; ++i) {
            cout << result[i];
            if (i != n) cout << " ";
        }
        cout << endl;
    }

    return 0;
}

