#include <iostream>
#include <vector>
#include <string>
#include <algorithm>
using namespace std;

// Structure representing an operation in our virtual machine
struct Operation {
    string opcode;
    int operand1, operand2, operand3, operand4;
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    unsigned long targetValue;
    cin >> targetValue;

    if (targetValue == 1) {
        cout << 1 << "\n";
        cout << "HALT PUSH 1 GOTO 1" << endl;
        return 0;
    }

    unsigned long stepCount = (targetValue - 1) / 2;
    vector<Operation> sequence;
    int instructionIndex = 0;

    // Initial setup: push marker value 1020 onto stack
    sequence.push_back({"POP", 1023, 2, 1020, 2});
    instructionIndex = 1;

    // Process each bit from highest (30) to lowest (0)
    for (int bitPosition = 30; bitPosition >= 0; --bitPosition) {
        bool currentBitSet = (stepCount >> bitPosition) & 1;

        int blockStart = instructionIndex + 1;
        int nextBlockStart;
        if (bitPosition > 0) {
            nextBlockStart = blockStart + 6;
        } else {
            nextBlockStart = 1 + 31 * 6 + 1;
        }

        // Define unique identifiers for data flow between stages
        int previousStageSymbol = (bitPosition == 30) ? 1020 : (2 * (bitPosition + 1) + 3);
        int currentStageSymbol = (bitPosition == 0) ? 3 : (2 * bitPosition + 3);
        int temporarySymbol = 2 * bitPosition + 4;

        // Doubling phase: duplicate existing items
        sequence.push_back({"POP", previousStageSymbol, blockStart + 1, 1021, blockStart + 3});
        sequence.push_back({"POP", 1023, blockStart + 2, temporarySymbol, blockStart + 2});
        sequence.push_back({"POP", 1023, blockStart, temporarySymbol, blockStart});

        // Conditional addition phase
        int adderEntry = blockStart + 4;
        if (currentBitSet) {
            sequence.push_back({"POP", 1021, adderEntry, currentStageSymbol, adderEntry});
        } else {
            sequence.push_back({"POP", 1021, adderEntry, 1021, adderEntry});
        }

        // Conversion phase: transform temporary items to final form
        sequence.push_back({"POP", temporarySymbol, blockStart + 5, 1021, nextBlockStart});
        sequence.push_back({"POP", 1023, blockStart + 4, currentStageSymbol, blockStart + 4});

        instructionIndex += 6;
    }

    // Main execution loop
    int loopStart = instructionIndex + 1;
    int endInstruction = instructionIndex + 2;

    sequence.push_back({"POP", 3, endInstruction, 2, loopStart});
    sequence.push_back({"HALT", -1, -1, 1, loopStart});
    instructionIndex += 2;

    cout << instructionIndex << "\n";
    for (const auto& op : sequence) {
        if (op.opcode == "POP") {
            cout << "POP " << op.operand1 << " GOTO " << op.operand2 
                 << " PUSH " << op.operand3 << " GOTO " << op.operand4 << "\n";
        } else {
            cout << "HALT PUSH " << op.operand3 << " GOTO " << op.operand4 << "\n";
        }
    }

    return 0;
}

