#include <iostream>
#include <vector>
#include <cmath>
#include <algorithm>
#include <cstdlib>
#include <ctime>
using namespace std;

int size_n;
vector<int> arr;
int index_map[1005]; // Maps value to its current position

struct Operation {
    int left, right, direction; // direction=0 for left rotation, 1 for right rotation
};

vector<Operation> operations;

// Apply an operation to the array 'arr' and update index_map accordingly
void perform_operation(int l, int r, int dir) {
    operations.push_back({l, r, dir});

    if (dir == 0) { // Left rotation: move first element to end
        int first_val = arr[l];
        for (int j = l; j < r; ++j) {
            arr[j] = arr[j + 1];
            index_map[arr[j]] = j;
        }
        arr[r] = first_val;
        index_map[arr[r]] = r;
    } else { // Right rotation: move last element to front
        int last_val = arr[r];
        for (int j = r; j > l; --j) {
            arr[j] = arr[j - 1];
            index_map[arr[j]] = j;
        }
        arr[l] = last_val;
        index_map[arr[l]] = l;
    }
}

// Simulate an operation on a temporary copy of the array (used in search heuristics)
void simulate_operation(vector<int>& temp_arr, int l, int r, int dir) {
    if (dir == 0) {
        int first_val = temp_arr[l];
        for (int j = l; j < r; ++j) temp_arr[j] = temp_arr[j + 1];
        temp_arr[r] = first_val;
    } else {
        int last_val = temp_arr[r];
        for (int j = r; j > l; --j) temp_arr[j] = temp_arr[j - 1];
        temp_arr[l] = last_val;
    }
}

// Compute the score for positions from start_idx to size_n
long long evaluate_score(const vector<int>& temp_arr, int begin_pos) {
    long long score = 0;
    for (int pos = begin_pos; pos <= size_n; ++pos) {
        int diff = pos - temp_arr[pos];
        score += diff * diff;
    }
    return score;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);
    srand(static_cast<unsigned>(time(nullptr)));

    if (!(cin >> size_n)) return 0;

    arr.resize(size_n + 1);
    for (int i = 1; i <= size_n; ++i) {
        cin >> arr[i];
        index_map[arr[i]] = i;
    }

    if (size_n == 1) {
        cout << "1 0\n";
        return 0;
    }

    // Determine window size: approximate sqrt(size_n), prefer even numbers
    int window_size = static_cast<int>(round(sqrt(size_n)));
    if (window_size < 2) window_size = 2;
    if (window_size % 2 != 0) window_size++;
    if (window_size > size_n) window_size = size_n;

    // Define prefix boundary: sort up to (size_n - window_size - 1)
    int prefix_end = size_n - window_size - 1;

    // Sort the prefix using two-phase strategy
    for (int target = 1; target <= prefix_end; ++target) {
        int current_pos = index_map[target];

        // Phase 1: Long-distance moves using window-sized jumps
        while (current_pos >= target + window_size) {
            perform_operation(current_pos - window_size + 1, current_pos, 1);
            current_pos = index_map[target];
        }

        // Phase 2: Fine-tuning within local window
        while (index_map[target] != target) {
            perform_operation(target, target + window_size - 1, 0);
        }
    }

    // Handle the tail section: indices from (prefix_end + 1) to size_n
    int tail_start = prefix_end + 1;
    if (tail_start < 1) tail_start = 1;

    // Generate all valid windows in the tail region
    vector<pair<int, int>> candidate_windows;
    for (int start = tail_start; start <= size_n - window_size + 1; ++start) {
        candidate_windows.emplace_back(start, start + window_size - 1);
    }

    // Local search with randomization to sort the tail
    const int max_iterations = 50000;
    int iterations = 0;

    while (iterations < max_iterations) {
        long long current_cost = evaluate_score(arr, tail_start);
        if (current_cost == 0) break;

        long long best_cost = -1;
        int best_window_index = -1;
        int best_direction = -1;

        // Evaluate all possible single operations
        for (int idx = 0; idx < candidate_windows.size(); ++idx) {
            int l = candidate_windows[idx].first;
            int r = candidate_windows[idx].second;
            for (int d = 0; d < 2; ++d) {
                vector<int> trial_arr = arr;
                simulate_operation(trial_arr, l, r, d);
                long long cost = evaluate_score(trial_arr, tail_start);
                if (best_cost == -1 || cost < best_cost) {
                    best_cost = cost;
                    best_window_index = idx;
                    best_direction = d;
                }
            }
        }

        // Choose next move: greedy improvement or random escape
        if (best_cost < current_cost) {
            perform_operation(candidate_windows[best_window_index].first,
                              candidate_windows[best_window_index].second,
                              best_direction);
        } else {
            int chosen_window = rand() % candidate_windows.size();
            int chosen_dir = rand() % 2;
            perform_operation(candidate_windows[chosen_window].first,
                              candidate_windows[chosen_window].second,
                              chosen_dir);
        }
        ++iterations;
    }

    cout << window_size << " " << operations.size() << "\n";
    for (const auto& op : operations) {
        cout << op.left << " " << op.left + window_size - 1 << " " << op.direction << "\n";
    }

    return 0;
}

#include "expression_evaluator/expression_evaluator_visitor.h"
#include "expression_evaluator/case_evaluator.h"

namespace lbug {
namespace evaluator {

void ExpressionEvaluatorVisitor::handleSwitch(ExpressionEvaluator* evaluator) {
    switch (evaluator->getEvaluatorType()) {
    case EvaluatorType::CASE_ELSE: {
        handleCase(evaluator);
    } break;
    case EvaluatorType::FUNCTION: {
        handleFunction(evaluator);
    } break;
    case EvaluatorType::LAMBDA_PARAM: {
        handleLambdaParam(evaluator);
    } break;
    case EvaluatorType::LIST_LAMBDA: {
        handleListLambda(evaluator);
    } break;
    case EvaluatorType::LITERAL: {
        handleLiteral(evaluator);
    } break;
    case EvaluatorType::PATH: {
        handlePath(evaluator);
    } break;
    case EvaluatorType::NODE_REL: {
        handlePattern(evaluator);
    } break;
    case EvaluatorType::REFERENCE: {
        handleReference(evaluator);
    } break;
    default:
        UNREACHABLE_CODE;
    }
}

void LambdaParamEvaluatorCollector::process(ExpressionEvaluator* evaluator) {
    std::vector<ExpressionEvaluator*> subNodes;
    switch (evaluator->getEvaluatorType()) {
    case EvaluatorType::CASE_ELSE: {
        auto& caseExpr = evaluator->constCast<CaseExpressionEvaluator>();
        subNodes.push_back(caseExpr.getElseEvaluator());
        for (auto& alt : caseExpr.getAlternativeEvaluators()) {
            subNodes.push_back(alt.whenEvaluator.get());
            subNodes.push_back(alt.thenEvaluator.get());
        }
    } break;
    case EvaluatorType::LAMBDA_PARAM: {
        collectedEvaluators.push_back(evaluator);
        return;
    }
    default: {
        for (auto& child : evaluator->getChildren()) {
            subNodes.push_back(child.get());
        }
    }
    }
    for (auto& node : subNodes) {
        process(node);
        handleSwitch(node);
    }
}

} // namespace evaluator
} // namespace lbug

