#include <hip/hip_runtime.h>
#include <hip/hiprtc.h>
#include <cstddef>
#include <cstdlib>
#include <iostream>
#include <string>
#include <vector>

#define VERIFY_RESULT(call, expected)                                                              \
{                                                                                                  \
    if ((call) != (expected))                                                                      \
    {                                                                                              \
        std::cout << "Error in call: " << #call << std::endl;                                      \
        std::exit(EXIT_FAILURE);                                                                   \
    }                                                                                              \
}

#define HIP_VERIFY(call) VERIFY_RESULT(call, hipSuccess)
#define HIPRTC_VERIFY(call) VERIFY_RESULT(call, HIPRTC_SUCCESS)

// CUDA-style kernel source code for hiprtc
static constexpr auto device_kernel{
    R"(
    extern "C"
    __global__ void compute_sum(float* result, float* src1, float* src2, size_t count)
    {
        int idx = threadIdx.x;
        if (idx < count)
        {
            result[idx] = src1[idx] + src2[idx];
        }
    }
)"};

int main()
{
    hiprtcProgram program_handle;
    auto compile_result = hiprtcCreateProgram(&program_handle,
                                              device_kernel,
                                              "compute_sum_kernel.cu",
                                              0,
                                              nullptr,
                                              nullptr);
    if (compile_result != HIPRTC_SUCCESS)
    {
        std::cerr << "Unable to create HIPRTC program" << std::endl;
        std::exit(EXIT_FAILURE);
    }

    hipDeviceProp_t device_properties;
    int selected_device = 0;
    HIP_VERIFY(hipGetDeviceProperties(&device_properties, selected_device));

    std::string arch_flag = "--gpu-architecture=" + std::string(device_properties.gcnArchName);
    const char* compiler_options[] = {arch_flag.c_str()};

    compile_result = hiprtcCompileProgram(program_handle,
                                          1,
                                          compiler_options);
    if (compile_result != HIPRTC_SUCCESS)
    {
        std::cerr << "Compilation failed" << std::endl;
        std::exit(EXIT_FAILURE);
    }

    std::size_t log_buffer_size;
    HIPRTC_VERIFY(hiprtcGetProgramLogSize(program_handle, &log_buffer_size));
    if (log_buffer_size > 1)
    {
        std::string compilation_log(log_buffer_size, '\0');
        HIPRTC_VERIFY(hiprtcGetProgramLog(program_handle, &compilation_log[0]));
        std::cerr << "Compiler warnings/errors: " << compilation_log << std::endl;
        std::exit(EXIT_FAILURE);
    }

    std::size_t binary_size;
    HIPRTC_VERIFY(hiprtcGetCodeSize(program_handle, &binary_size));
    std::vector<char> device_binary(binary_size);
    HIPRTC_VERIFY(hiprtcGetCode(program_handle, device_binary.data()));
    HIPRTC_VERIFY(hiprtcDestroyProgram(&program_handle));

    hipModule_t loaded_module;
    hipFunction_t kernel_function;
    HIP_VERIFY(hipModuleLoadData(&loaded_module, device_binary.data()));
    HIP_VERIFY(hipModuleGetFunction(&kernel_function, loaded_module, "compute_sum"));

    constexpr std::size_t element_count = 256;
    std::vector<float> host_input_a, host_output;
    host_input_a.reserve(element_count);
    host_output.reserve(element_count);

    for (std::size_t index = 0; index < element_count; ++index)
    {
        host_input_a.push_back(static_cast<float>(index + 1));
        host_output.push_back(0.0f);
    }

    float *device_ptr_a, *device_ptr_b, *device_ptr_c;
    HIP_VERIFY(hipMalloc(&device_ptr_a, sizeof(float) * element_count));
    HIP_VERIFY(hipMalloc(&device_ptr_b, sizeof(float) * element_count));
    HIP_VERIFY(hipMalloc(&device_ptr_c, sizeof(float) * element_count));

    HIP_VERIFY(hipMemcpy(device_ptr_a, host_input_a.data(), sizeof(float) * element_count, hipMemcpyHostToDevice));
    HIP_VERIFY(hipMemcpy(device_ptr_b, host_input_a.data(), sizeof(float) * element_count, hipMemcpyHostToDevice));

    struct KernelArgs
    {
        float* output;
        float* input_a;
        float* input_b;
        std::size_t num_elements;
    } arguments{device_ptr_c, device_ptr_a, device_ptr_b, element_count};

    std::size_t arg_block_size = sizeof(arguments);
    void* launch_config[] = {HIP_LAUNCH_PARAM_BUFFER_POINTER, &arguments,
                             HIP_LAUNCH_PARAM_BUFFER_SIZE, &arg_block_size,
                             HIP_LAUNCH_PARAM_END};

    HIP_VERIFY(hipModuleLaunchKernel(kernel_function,
                                     1, 1, 1,
                                     element_count, 1, 1,
                                     0, nullptr,
                                     nullptr, launch_config));

    HIP_VERIFY(hipMemcpy(host_output.data(), device_ptr_c, sizeof(float) * element_count, hipMemcpyDeviceToHost));

    bool passed = true;
    for (std::size_t i = 0; i < element_count; ++i)
    {
        float expected = host_input_a[i] + host_input_a[i];
        if (std::abs(expected - host_output[i]) > 1e-5f)
        {
            std::cout << "Mismatch at index " << i << ": expected " << expected
                      << ", got " << host_output[i] << std::endl;
            passed = false;
            break;
        }
    }

    if (passed)
    {
        std::cout << "Test passed successfully" << std::endl;
    }
    else
    {
        std::abort();
    }

    HIP_VERIFY(hipFree(device_ptr_a));
    HIP_VERIFY(hipFree(device_ptr_b));
    HIP_VERIFY(hipFree(device_ptr_c));

    return EXIT_SUCCESS;
}

