EndermanRenderer::EndermanRenderer() : MobRenderer(new EndermanModel(), 0.5f) {
    model = (EndermanModel*)MobRenderer::model;
    this->setArmor(model);
}

void EndermanRenderer::render(
    std::shared_ptr<Entity> entity,
    double                  posX,
    double                  posY,
    double                  posZ,
    float                   rotation,
    float                   partialTicks
) {
    // 4J - original version used generics and thus had an input parameter of
    // type Boat rather than std::shared_ptr<Entity>  we have here - do some
    // casting around instead
    std::shared_ptr<EnderMan> enderman = std::dynamic_pointer_cast<EnderMan>(entity);
    model->carrying = enderman->getCarryingTile() > 0;
    model->creepy   = enderman->isCreepy();
    if (enderman->isCreepy()) {
        double offset = 0.02;
        posX += random.nextGaussian() * offset;
        posZ += random.nextGaussian() * offset;
    }
    MobRenderer::render(enderman, posX, posY, posZ, rotation, partialTicks);
}

void EndermanRenderer::additionalRendering(std::shared_ptr<Mob> entity, float partialTicks) {
    // 4J - original version used generics and thus had an input parameter of
    // type Boat rather than std::shared_ptr<Entity>  we have here - do some
    // casting around instead
    std::shared_ptr<EnderMan> enderman = std::dynamic_pointer_cast<EnderMan>(entity);
    MobRenderer::additionalRendering(entity, partialTicks);
    if (enderman->getCarryingTile() > 0) {
        glEnable(GL_RESCALE_NORMAL);
        glPushMatrix();
        float scale = 8 / 16.0f;
        glTranslatef(-0 / 16.0f, 11 / 16.0f, -12 / 16.0f);
        scale *= 1.00f;
        glRotatef(20, 1, 0, 0);
        glRotatef(45, 0, 1, 0);
        glScalef(scale, -scale, scale);
        if (SharedConstants::TEXTURE_LIGHTING) {
            int color = enderman->getLightColor(partialTicks);
            int u     = color % 65536;
            int v     = color / 65536;
            glMultiTexCoord2f(GL_TEXTURE1, u / 1.0f, v / 1.0f);
            glColor4f(1, 1, 1, 1);
        }
        glColor4f(1, 1, 1, 1);
        bindTexture(TN_TERRAIN); // 4J was L"/terrain.png"
        tileRenderer->renderTile(
            Tile::tiles[enderman->getCarryingTile()],
            enderman->getCarryingData(),
            1
        );
        glPopMatrix();
        glDisable(GL_RESCALE_NORMAL);
    }
}

int EndermanRenderer::prepareArmor(
    std::shared_ptr<Mob> entity,
    int                  layer,
    float                partialTicks
) {
    // 4J - original version used generics and thus had an input parameter of
    // type Boat rather than std::shared_ptr<Entity>  we have here - do some
    // casting around instead
    std::shared_ptr<EnderMan> enderman = std::dynamic_pointer_cast<EnderMan>(entity);
    if (layer != 0) return -1;
    bindTexture(TN_MOB_ENDERMAN_EYES); // 4J was L"/mob/enderman_eyes.png"
    float brightness = 1;
    glEnable(GL_BLEND);
    // 4J Stu - We probably don't need to do this on 360 either (as we force it
    // back on the renderer) However we do want it off for other platforms that
    // don't force it on in the render lib CBuff handling Several texture packs
    // have fully transparent bits that break if this is off
#ifdef _XBOX
    glDisable(GL_ALPHA_TEST);
#endif
    glBlendFunc(GL_ONE, GL_ONE);
    glDisable(GL_LIGHTING);
    if (enderman->isInvisible()) glDepthMask(false);
    else glDepthMask(true);
    if (SharedConstants::TEXTURE_LIGHTING) {
        int col = 0xf0f0;
        int u   = col % 65536;
        int v   = col / 65536;
        glMultiTexCoord2f(GL_TEXTURE1, u / 1.0f, v / 1.0f);
        glColor4f(1, 1, 1, 1);
    }
    glEnable(GL_LIGHTING);
    glColor4f(1, 1, 1, brightness);
    return 1;
}

