/*-------------------------------------------------------------------------
 * Function:    test_file_creation_mod
 *
 * Purpose:     Modified version of file creation test
 *
 * Return:      None
 *
 * Modifications:
 *-------------------------------------------------------------------------
 */
static void test_file_creation_mod()
{
    SUBTEST("Modified File Creation I/O");

    remove(DATASET_PATH_1.c_str());
    H5File* created_file = nullptr;

    try {
        // Create initial file with exclusive access
        created_file = new H5File(DATASET_PATH_1, H5F_ACC_EXCL);

        // Attempt to recreate same file - should fail
        try {
            H5File duplicate_file(DATASET_PATH_1, H5F_ACC_TRUNC);
            throw InvalidActionException("H5File constructor", "Attempted to overwrite existing file.");
        }
        catch (FileIException&) {}

        delete created_file;
        created_file = NULL;

        // Try creating again with EXCL - should fail since file exists
        try {
            H5File another_file(DATASET_PATH_1, H5F_ACC_EXCL);
            throw InvalidActionException("H5File constructor", "File already present.");
        }
        catch (FileIException&) {}

        // Now truncate the existing file
        created_file = new H5File(DATASET_PATH_1, H5F_ACC_TRUNC);

        // Try truncating while file is open - should fail
        try {
            H5File truncated_file(DATASET_PATH_1, H5F_ACC_TRUNC);
            throw InvalidActionException("H5File constructor", "Truncation attempted on open file.");
        }
        catch (FileIException&) {}

        // Try exclusive access on existing file - should fail
        try {
            H5File exclusive_file(DATASET_PATH_1, H5F_ACC_EXCL);
            throw InvalidActionException("H5File constructor", "EXCL attempt on existing file.");
        }
        catch (FileIException&) {}

        // Verify file creation properties
        FileCreatPropList prop_list = created_file->getCreatePlist();
        hsize_t ublock_size = prop_list.getUserblock();
        verify_val((long)ublock_size, (long)BLOCK_SIZE_1, "FileCreatPropList::getUserblock", __LINE__, __FILE__);

        size_t offset_val, length_val;
        prop_list.getSizes(offset_val, length_val);
        verify_val(offset_val, OFFSET_WIDTH_1, "FileCreatPropList::getSizes", __LINE__, __FILE__);
        verify_val(length_val, LENGTH_WIDTH_1, "FileCreatPropList::getSizes", __LINE__, __FILE__);

        unsigned sym_intern, sym_leaf;
        prop_list.getSymk(sym_intern, sym_leaf);
        verify_val(sym_intern, SYM_NODE_1, "FileCreatPropList::getSymk", __LINE__, __FILE__);
        verify_val(sym_leaf, SYM_TREE_1, "FileCreatPropList::getSymk", __LINE__, __FILE__);

        delete created_file;
        PASSED();
    }
    catch (InvalidActionException& E) {
        cerr << " *FAILED*" << endl;
        cerr << "    <<<  " << E.getDetailMsg() << "  >>>" << endl << endl;
        if (created_file != NULL) delete created_file;
    }
    catch (Exception& E) {
        issue_fail_msg("test_file_creation_mod()", __LINE__, __FILE__, E.getCDetailMsg());
        if (created_file != NULL) delete created_file;
    }

    FileCreatPropList* prop_template = NULL;
    try {
        // Create custom property list
        prop_template = new FileCreatPropList;
        prop_template->setUserblock(BLOCK_SIZE_2);
        prop_template->setSizes(OFFSET_WIDTH_2, LENGTH_WIDTH_2);
        prop_template->setSymk(SYM_NODE_2, SYM_TREE_2);

        // Create file with custom properties
        H5File custom_file(DATASET_PATH_2, H5F_ACC_TRUNC, *prop_template);
        delete prop_template;
        prop_template = NULL;

        // Retrieve and verify properties
        prop_template = new FileCreatPropList(custom_file.getCreatePlist());
        hsize_t block = prop_template->getUserblock();
        verify_val((long)block, (long)BLOCK_SIZE_2, "FileCreatPropList::getUserblock", __LINE__, __FILE__);

        size_t off, len;
        prop_template->getSizes(off, len);
        verify_val(off, OFFSET_WIDTH_2, "FileCreatPropList::getSizes", __LINE__, __FILE__);
        verify_val(len, LENGTH_WIDTH_2, "FileCreatPropList::getSizes", __LINE__, __FILE__);

        unsigned intern, leaf;
        prop_template->getSymk(intern, leaf);
        verify_val(intern, SYM_NODE_2, "FileCreatPropList::getSymk", __LINE__, __FILE__);
        verify_val(leaf, SYM_TREE_2, "FileCreatPropList::getSymk", __LINE__, __FILE__);

        // Clone and modify properties
        FileCreatPropList cloned_prop;
        cloned_prop.copy(*prop_template);
        delete prop_template;
        prop_template = NULL;

        cloned_prop.setUserblock(BLOCK_SIZE_3);
        H5File third_file(DATASET_PATH_3, H5F_ACC_TRUNC, cloned_prop);

        // Verify third file properties
        prop_template = new FileCreatPropList(third_file.getCreatePlist());
        block = prop_template->getUserblock();
        verify_val((long)block, (long)BLOCK_SIZE_3, "FileCreatPropList::getUserblock", __LINE__, __FILE__);

        prop_template->getSizes(off, len);
        verify_val(off, OFFSET_WIDTH_3, "FileCreatPropList::getSizes", __LINE__, __FILE__);
        verify_val(len, LENGTH_WIDTH_3, "FileCreatPropList::getSizes", __LINE__, __FILE__);

        prop_template->getSymk(intern, leaf);
        verify_val(intern, SYM_NODE_3, "FileCreatPropList::getSymk", __LINE__, __FILE__);
        verify_val(leaf, SYM_TREE_3, "FileCreatPropList::getSymk", __LINE__, __FILE__);

        delete prop_template;
        PASSED();
    }
    catch (Exception& E) {
        issue_fail_msg("test_file_creation_mod()", __LINE__, __FILE__, E.getCDetailMsg());
        if (prop_template != NULL) delete prop_template;
    }
}

