    }
    H5Pclose(fapl_id);
}

/*-------------------------------------------------------------------------
 * Function:    test_file_name_mod
 *
 * Purpose:     Modified version of file name test
 *
 * Return:      None
 *-------------------------------------------------------------------------
 */
const int DIM1 = 2;
const int ROWS = 4;
const int COLS = 5;
const H5std_string TEST_GROUP("test_group");
const H5std_string TEST_DATASET("test_dataset");
const H5std_string TEST_ATTR("test_attribute");
const H5std_string TEST_TYPE("compound_type");

typedef struct {
    unsigned int field_a;
    float        field_b;
} test_struct_t;

static void test_file_name_mod()
{
    SUBTEST("Modified File Name Retrieval");
    H5std_string retrieved_name;
    try {
        H5File base_file(DATASET_PATH_4, H5F_ACC_TRUNC);
        retrieved_name = base_file.getFileName();
        verify_val(retrieved_name, DATASET_PATH_4, "H5File::getFileName", __LINE__, __FILE__);

        Group test_group(base_file.createGroup(TEST_GROUP, 0));
        retrieved_name = test_group.getFileName();
        verify_val(retrieved_name, DATASET_PATH_4, "Group::getFileName", __LINE__, __FILE__);

        hsize_t dims[DIM1] = {ROWS, COLS};
        DataSpace space(DIM1, dims);

        DataSet dataset(base_file.createDataSet(TEST_DATASET, PredType::NATIVE_INT, space));
        retrieved_name = dataset.getFileName();
        verify_val(retrieved_name, DATASET_PATH_4, "DataSet::getFileName", __LINE__, __FILE__);

        Attribute attr(dataset.createAttribute(TEST_ATTR, PredType::NATIVE_INT, space));
        retrieved_name = attr.getFileName();
        verify_val(retrieved_name, DATASET_PATH_4, "Attribute::getFileName", __LINE__, __FILE__);

        CompType comp_type(sizeof(test_struct_t));
        comp_type.insertMember("field_a", HOFFSET(test_struct_t, field_a), PredType::NATIVE_INT);
        comp_type.insertMember("field_b", HOFFSET(test_struct_t, field_b), PredType::NATIVE_FLOAT);
        comp_type.commit(base_file, TEST_TYPE);

        retrieved_name = comp_type.getFileName();
        verify_val(retrieved_name, DATASET_PATH_4, "CompType::getFileName", __LINE__, __FILE__);

        PASSED();
    }
    catch (Exception& E) {
        issue_fail_msg("test_file_name_mod()", __LINE__, __FILE__, E.getCDetailMsg());
    }
}

/*-------------------------------------------------------------------------
 * Function:    test_file_attribute_mod
 *
 * Purpose:     Modified version of file attribute test
 *
 * Return:      None
 *-------------------------------------------------------------------------
 */
const int ATTR_DIM = 3;
const H5std_string FILE7("sample_file5.h5");
const H5std_string FILE_ATTR1("file_attr_1");
const H5std_string FILE_ATTR2("file_attr_2");
int file_attr_data[ATTR_DIM] = {1024, -456, 78912};
int ds_attr_data[ATTR_DIM] = {512, -234, 1000};

static void test_file_attribute_mod()
{
    int read_data[ATTR_DIM];
    SUBTEST("Modified File Attribute Operations");
    try {
        H5File attr_file(FILE7, H5F_ACC_TRUNC);
        hsize_t dims[1] = {ATTR_DIM};
        DataSpace space(1, dims);

        Attribute file_attr1(attr_file.createAttribute(FILE_ATTR1, PredType::NATIVE_FLOAT, space));
        Attribute file_attr2(attr_file.createAttribute(FILE_ATTR2, PredType::NATIVE_INT, space));
        file_attr2.write(PredType::NATIVE_INT, file_attr_data);

        // Try creating duplicate attribute - should fail
        try {
            Attribute dup_attr(attr_file.createAttribute(FILE_ATTR2, PredType::NATIVE_INT, space));
            throw InvalidActionException("createAttribute", "Duplicate attribute creation attempted.");
        }
        catch (AttributeIException&) {}

        DataSet dataset(attr_file.createDataSet(TEST_DATASET, PredType::NATIVE_INT, space));
        Attribute ds_attr(dataset.createAttribute(TEST_ATTR, PredType::NATIVE_INT, space));
        ds_attr.write(PredType::NATIVE_INT, ds_attr_data);
        ds_attr.flush(H5F_SCOPE_GLOBAL);

        // Verify object counts
        ssize_t obj_count = attr_file.getObjCount(H5F_OBJ_ALL);
        verify_val(obj_count, 5, "H5File::getObjCount", __LINE__, __FILE__);

        obj_count = attr_file.getObjCount(H5F_OBJ_GROUP);
        verify_val(obj_count, 0, "H5File::getObjCount(H5F_OBJ_GROUP)", __LINE__, __FILE__);

        obj_count = attr_file.getObjCount(H5F_OBJ_DATASET);
        verify_val(obj_count, 1, "H5File::getObjCount(H5F_OBJ_DATASET)", __LINE__, __FILE__);

        obj_count = attr_file.getObjCount(H5F_OBJ_ATTR);
        verify_val(obj_count, 3, "H5File::getObjCount(H5F_OBJ_ATTR)", __LINE__, __FILE__);

        obj_count = attr_file.getObjCount(H5F_OBJ_DATATYPE);
        verify_val(obj_count, 0, "H5File::getObjCount(H5F_OBJ_DATATYPE)", __LINE__, __FILE__);

        obj_count = attr_file.getObjCount(H5F_OBJ_FILE);
        verify_val(obj_count, 1, "H5File::getObjCount(H5F_OBJ_FILE)", __LINE__, __FILE__);

        // Verify file names through attributes
        H5std_string fname = file_attr1.getFileName();
        verify_val(fname, FILE7, "Attribute::getFileName", __LINE__, __FILE__);
        fname.clear();
        fname = ds_attr.getFileName();
        verify_val(fname, FILE7, "Attribute::getFileName", __LINE__, __FILE__);

        // Verify attribute type class
        H5T_class_t atype = file_attr1.getTypeClass();
        verify_val(atype, H5T_FLOAT, "Attribute::getTypeClass", __LINE__, __FILE__);

        // Verify attribute counts
        int num_attrs = attr_file.getNumAttrs();
        verify_val(num_attrs, 2, "H5File::getNumAttrs", __LINE__, __FILE__);

        num_attrs = dataset.getNumAttrs();
        verify_val(num_attrs, 1, "DataSet::getNumAttrs", __LINE__, __FILE__);

        // Read and verify data
        HDmemset(read_data, 0, sizeof(read_data));
        ds_attr.read(PredType::NATIVE_INT, read_data);
        for (int i = 0; i < ATTR_DIM; i++) {
            if (read_data[i] != ds_attr_data[i]) {
                H5_FAILED();
                cerr << "Data mismatch at index " << i << ": got " << read_data[i] 
                     << ", expected " << ds_attr_data[i] << endl;
            }
        }
        PASSED();
    }
    catch (Exception& E) {
        issue_fail_msg("test_file_attribute_mod()", __LINE__, __FILE__, E.getCDetailMsg());
    }
}

/*-------------------------------------------------------------------------
 * Function:    test_libver_bounds_mod
 *
 * Purpose:     Modified version of library version bounds test
 *
 * Return:      None
 *-------------------------------------------------------------------------
 */
static void test_libver_bounds_mod_real(
        H5F_libver_t create_bound, unsigned create_version,
        H5F_libver_t mod_bound, unsigned mod_version)
{
    try {
        FileAccPropList fapl;
        fapl.setLibverBounds(create_bound, H5F_LIBVER_LATEST);
        H5File test_file(FILE7, H5F_ACC_TRUNC, FileCreatPropList::DEFAULT, fapl);

        unsigned obj_version = test_file.childObjVersion("/");
        verify_val(obj_version, create_version, "childObjVersion", __LINE__, __FILE__);

        test_file.close();
        fapl.setLibverBounds(mod_bound, H5F_LIBVER_LATEST);
        test_file.openFile(FILE7, H5F_ACC_RDWR, fapl);
        obj_version = test_file.childObjVersion("/");
        verify_val(obj_version, create_version, "childObjVersion", __LINE__, __FILE__);

        Group g1 = test_file.createGroup("/G1");
        obj_version = test_file.childObjVersion("/G1");
        verify_val(obj_version, mod_version, "childObjVersion", __LINE__, __FILE__);
        g1.close();

        Group g3 = test_file.createGroup("/G1/G3");
        obj_version = g3.childObjVersion("/G1/G3");
        verify_val(obj_version, mod_version, "childObjVersion", __LINE__, __FILE__);
        g3.close();

        obj_version = test_file.childObjVersion("/");
        verify_val(obj_version, create_version, "childObjVersion", __LINE__, __FILE__);
    }
    catch (Exception& E) {
        issue_fail_msg("test_libver_bounds_mod_real()", __LINE__, __FILE__, E.getCDetailMsg());
    }
}

static void test_libver_bounds_mod()
{
    SUBTEST("Modified Library Version Bounds");
    test_libver_bounds_mod_real(H5F_LIBVER_EARLIEST, H5O_VERSION_1, H5F_LIBVER_LATEST, H5O_VERSION_2);
    test_libver_bounds_mod_real(H5F_LIBVER_LATEST, H5O_VERSION_2, H5F_LIBVER_EARLIEST, H5O_VERSION_1);
    PASSED();
}

