#include <iostream>
#include <vector>
#include <limits.h> // For INT_MAX and INT_MIN
using namespace std;

class Solution {
public:
    int reverseNumber(int value) {
        int result = 0;

        while (value != 0) {
            if (result > INT_MAX / 10 || result < INT_MIN / 10) return 0;

            result = result * 10 + value % 10;
            value /= 10;
        }
        return result;
    }

    bool checkPalindrome(int num) {
        if (num < 0) return false;

        int reversedVal = reverseNumber(num);
        return reversedVal == num;
    }
};

int main() {
    Solution solver;
    int inputNum = 12345; // Example number
    cout << "Original number: " << inputNum << endl;
    cout << "Reversed number: " << solver.reverseNumber(inputNum) << endl;

    cout << "Is Palindrome: " << solver.checkPalindrome(inputNum) << endl;

    return 0;
}
