class FMeshPaintEditorModeModule : public IModuleInterface
{
public:
	FMeshPaintEditorModeModule() 
	{
	}

	// FModuleInterface overrides
	virtual void StartupModule() override;
	virtual void ShutdownModule() override;
	virtual bool SupportsDynamicReloading() override
	{
		return true;
	}

protected:
	void Initialize();
	void HandlePostEngineInitialization();
	void Deregister();
	void OnMeshPaintModeButtonClicked();
	bool IsMeshPaintModeButtonActive();
	void AddGeometryAdapterFactory(TSharedRef<IMeshPaintComponentAdapterFactory> AdapterFactory);
	void RemoveGeometryAdapterFactory(TSharedRef<IMeshPaintComponentAdapterFactory> AdapterFactory);
};

void FMeshPaintEditorModeModule::Initialize()
{
	AddGeometryAdapterFactory(MakeShareable(new FMeshPaintSplineMeshComponentAdapterFactory));
	AddGeometryAdapterFactory(MakeShareable(new FMeshPaintStaticMeshComponentAdapterFactory));
	AddGeometryAdapterFactory(MakeShareable(new FMeshPaintSkeletalMeshComponentAdapterFactory));

	FPropertyEditorModule& PropertyModule = FModuleManager::LoadModuleChecked<FPropertyEditorModule>("PropertyEditor");
	PropertyModule.RegisterCustomClassLayout("MeshColorPaintingToolProperties", FOnGetDetailCustomizationInstance::CreateStatic(&FColorPaintingSettingsCustomization::MakeInstance));
	PropertyModule.RegisterCustomClassLayout("MeshWeightPaintingToolProperties", FOnGetDetailCustomizationInstance::CreateStatic(&FWeightPaintingSettingsCustomization::MakeInstance));
	PropertyModule.RegisterCustomClassLayout("MeshTexturePaintingToolProperties", FOnGetDetailCustomizationInstance::CreateStatic(&FTexturePaintingSettingsCustomization::MakeInstance));
}

void FMeshPaintEditorModeModule::HandlePostEngineInitialization()
{
	if (!GetDefault<ULevelEditorMiscSettings>()->bEnableLegacyMeshPaintMode)
	{
		Initialize();
		FMeshPaintingToolActionCommands::RegisterAllToolActions();
		FMeshPaintEditorModeCommands::Register();
	}
}

void FMeshPaintEditorModeModule::StartupModule()
{
	FCoreDelegates::OnPostEngineInit.AddRaw(this, &FMeshPaintEditorModeModule::HandlePostEngineInitialization);
}

void FMeshPaintEditorModeModule::ShutdownModule()
{
	FCoreDelegates::OnPostEngineInit.RemoveAll(this);
	FMeshPaintingToolActionCommands::UnregisterAllToolActions();
	FMeshPaintEditorModeCommands::Unregister();
	Deregister();
}

void FMeshPaintEditorModeModule::Deregister()
{
}

void FMeshPaintEditorModeModule::OnMeshPaintModeButtonClicked()
{
	GLevelEditorModeTools().ActivateMode(GetDefault<UMeshPaintMode>()->GetID());
	GLevelEditorModeTools().DeactivateOtherVisibleModes(GetDefault<UMeshPaintMode>()->GetID());
}

bool FMeshPaintEditorModeModule::IsMeshPaintModeButtonActive()
{
	return true;
}

void FMeshPaintEditorModeModule::AddGeometryAdapterFactory(TSharedRef<IMeshPaintComponentAdapterFactory> AdapterFactory)
{
	FMeshPaintComponentAdapterFactory::FactoryList.Add(AdapterFactory);
}

void FMeshPaintEditorModeModule::RemoveGeometryAdapterFactory(TSharedRef<IMeshPaintComponentAdapterFactory> AdapterFactory)
{
	FMeshPaintComponentAdapterFactory::FactoryList.Remove(AdapterFactory);
}

IMPLEMENT_MODULE(FMeshPaintEditorModeModule, MeshPaintEditorMode)

