namespace lbug {
namespace function {
using namespace lbug::common;

struct UniformRandom {
    static void compute(double& output, void* userData) {
        auto clientCtx = reinterpret_cast<FunctionBindData*>(userData)->clientContext;
        output = static_cast<double>(RandomEngine::Get(*clientCtx)->nextRandomInteger()) /
                 static_cast<double>(UINT32_MAX);
    }
};

function_set UniformRandFunction::getFunctionSet() {
    function_set functions;
    functions.push_back(std::make_unique<ScalarFunction>(
        name, 
        std::vector<LogicalTypeID>{}, 
        LogicalTypeID::DOUBLE, 
        ScalarFunction::NullaryAuxilaryExecFunction<double, UniformRandom>
    ));
    return functions;
}
} // namespace function
} // namespace lbug

#include "test/jemalloc_test.h"
#include "test/arena_util.h"
#include "jemalloc/internal/arena_structs.h"
#include "jemalloc/internal/san_bump.h"

TEST_BEGIN(test_san_bump_alloc_v2) {
    test_skip_if(!maps_coalesce || !opt_retain);
    tsdn_t *tsdn = tsdn_fetch();
    san_bump_alloc_t sba;
    san_bump_alloc_init(&sba);
    unsigned arena_index = do_arena_create(0, 0);
    assert_u_ne(arena_index, UINT_MAX, "Failed to create an arena");
    arena_t *arena = arena_get(tsdn, arena_index, false);
    pac_t *pac = &arena->pa_shard.pac;
    size_t request_size = PAGE * 16;
    size_t element_count = request_size / sizeof(unsigned);
    edata_t* allocated_edata = san_bump_alloc(tsdn, &sba, pac, pac_ehooks_get(pac),
        request_size, /* zero */ false);
    expect_ptr_not_null(allocated_edata, "Failed to allocate edata");
    expect_u_eq(edata_arena_ind_get(allocated_edata), arena_index,
        "Edata was assigned an incorrect arena id");
    expect_zu_eq(edata_size_get(allocated_edata), request_size,
        "Allocated edata of incorrect size");
    expect_false(edata_slab_get(allocated_edata),
        "Bump allocator incorrectly assigned 'slab' to true");
    expect_true(edata_committed_get(allocated_edata), "Edata is not committed");
    void *memory_ptr = edata_addr_get(allocated_edata);
    expect_ptr_not_null(memory_ptr, "Edata was assigned an invalid address");
    /* Test that memory is allocated; no guard pages are misplaced */
    for (unsigned index = 0; index < element_count; ++index) {
        ((unsigned *)memory_ptr)[index] = 1;
    }
    size_t second_request_size = PAGE * 28;
    size_t second_element_count = second_request_size / sizeof(unsigned);
    edata_t *second_edata = san_bump_alloc(tsdn, &sba, pac, pac_ehooks_get(pac),
        second_request_size, /* zero */ true);
    expect_ptr_not_null(second_edata, "Failed to allocate edata");
    expect_u_eq(edata_arena_ind_get(second_edata), arena_index,
        "Edata was assigned an incorrect arena id");
    expect_zu_eq(edata_size_get(second_edata), second_request_size,
        "Allocated edata of incorrect size");
    expect_false(edata_slab_get(second_edata),
        "Bump allocator incorrectly assigned 'slab' to true");
    expect_true(edata_committed_get(second_edata), "Edata is not committed");
    void *second_memory_ptr = edata_addr_get(second_edata);
    expect_ptr_not_null(second_memory_ptr, "Edata was assigned an invalid address");
    uintptr_t distance = second_memory_ptr > memory_ptr 
        ? (uintptr_t)second_memory_ptr - (uintptr_t)memory_ptr
        : (uintptr_t)memory_ptr - (uintptr_t)second_memory_ptr;
    size_t gap_between = (size_t)distance - request_size;
    expect_zu_ge(gap_between, PAGE,
        "Guard page between allocs is missing");
    for (unsigned index = 0; index < second_element_count; ++index) {
        expect_u_eq(((unsigned *)second_memory_ptr)[index], 0, "Memory is not zeroed");
    }
}
TEST_END

TEST_BEGIN(test_large_alloc_size_v2) {
    test_skip_if(!maps_coalesce || !opt_retain);
    tsdn_t *tsdn = tsdn_fetch();
    san_bump_alloc_t sba;
    san_bump_alloc_init(&sba);
    unsigned arena_index = do_arena_create(0, 0);
    assert_u_ne(arena_index, UINT_MAX, "Failed to create an arena");
    arena_t *arena = arena_get(tsdn, arena_index, false);
    pac_t *pac = &arena->pa_shard.pac;
    size_t large_request_size = SBA_RETAINED_ALLOC_SIZE * 2;
    edata_t* allocated_edata = san_bump_alloc(tsdn, &sba, pac, pac_ehooks_get(pac),
        large_request_size, /* zero */ false);
    expect_u_eq(edata_arena_ind_get(allocated_edata), arena_index,
        "Edata was assigned an incorrect arena id");
    expect_zu_eq(edata_size_get(allocated_edata), large_request_size,
        "Allocated edata of incorrect size");
    expect_false(edata_slab_get(allocated_edata),
        "Bump allocator incorrectly assigned 'slab' to true");
    expect_true(edata_committed_get(allocated_edata), "Edata is not committed");
    void *memory_ptr = edata_addr_get(allocated_edata);
    expect_ptr_not_null(memory_ptr, "Edata was assigned an invalid address");
    /* Test that memory is allocated; no guard pages are misplaced */
    for (unsigned index = 0; index < large_request_size / PAGE; ++index) {
        *((char *)memory_ptr + PAGE * index) = 1;
    }
}
TEST_END

int
main(void) {
    return test(
        test_san_bump_alloc_v2,
        test_large_alloc_size_v2);
}

