#include <iostream>
#include <magic_enum/magic_enum.hpp>
#include <magic_enum/magic_enum_iostream.hpp>

enum class Status : int { FAILED = -5, PENDING = 0, SUCCESS = 5 };

template <typename E>
auto convert_to_underlying(magic_enum::Enum<E> value) {
  return static_cast<magic_enum::underlying_type_t<E>>(value);
}

int main() {
  // Enum variable to its string representation
  Status s1 = Status::FAILED;
  auto s1_label = magic_enum::enum_name(s1);
  std::cout << s1_label << std::endl; // FAILED

  // Get all enum names as a sequence
  constexpr auto labels = magic_enum::enum_names<Status>();
  std::cout << "Status names:";
  for (const auto& label : labels) {
    std::cout << " " << label;
  }
  std::cout << std::endl;
  // Status names: FAILED PENDING SUCCESS

  // Convert string to enum value
  auto s2 = magic_enum::enum_cast<Status>("PENDING");
  if (s2.has_value()) {
    std::cout << "PENDING = " << convert_to_underlying(s2.value()) << std::endl; // PENDING = 0
  }

  // Case-insensitive conversion
  s2 = magic_enum::enum_cast<Status>("pending", magic_enum::case_insensitive);
  if (s2.has_value()) {
    std::cout << "PENDING = " << convert_to_underlying(s2.value()) << std::endl; // PENDING = 0
  }

  // Integer to enum
  auto s3 = magic_enum::enum_cast<Status>(5);
  if (s3.has_value()) {
    std::cout << "SUCCESS = " << magic_enum::enum_integer(s3.value()) << std::endl; // SUCCESS = 5
  }

  // Enum to integer
  auto s4_value = magic_enum::enum_integer(Status::FAILED);
  std::cout << "FAILED = " << s4_value << std::endl; // FAILED = -5

  using magic_enum::iostream_operators::operator<<;

  // Output enum values using ostream operator
  std::cout << "Status: " << s1 << " " << s2 << " " << s3 << std::endl; // Status: FAILED PENDING SUCCESS

  // Count of enum values
  std::cout << "Status enum size: " << magic_enum::enum_count<Status>() << std::endl; // Status size: 3

  // Access by index
  std::cout << "Status[1] = " << magic_enum::enum_value<Status>(1) << std::endl; // Status[1] = PENDING

  // All enum values
  constexpr auto all_values = magic_enum::enum_values<Status>();
  std::cout << "Status values:";
  for (const auto val : all_values) {
    std::cout << " " << val;
  }
  std::cout << std::endl;
  // Status values: FAILED PENDING SUCCESS

  enum class Option { X = 2, Y = 4, Z = 8 };
  using namespace magic_enum::bitwise_operators;

  // Bitwise operations
  Option opt = Option::X | Option::Z;
  std::cout << opt << std::endl; // 10

  enum mode { low, medium, high };
  static_assert(magic_enum::is_unscoped_enum_v<mode>);
  static_assert(!magic_enum::is_unscoped_enum_v<Status>);
  static_assert(!magic_enum::is_unscoped_enum_v<Option>);

  static_assert(!magic_enum::is_scoped_enum_v<mode>);
  static_assert(magic_enum::is_scoped_enum_v<Status>);
  static_assert(magic_enum::is_scoped_enum_v<Option>);

  // Enum entries (name-value pairs)
  constexpr auto pairs = magic_enum::enum_entries<Status>();
  std::cout << "Status entries:";
  for (const auto& pair : pairs) {
    std::cout << " " << pair.second << " = " << static_cast<int>(pair.first);
  }
