// Function to discover words using query-based strategy
int main() {
    int T;
    if (cin >> T) {
        while (T--) {
            int totalWords;
            if (!(cin >> totalWords)) break;

            set<string> discovered;

            // Process each letter from 'a' to 'z'
            for (char startChar = 'a'; startChar <= 'z'; ++startChar) {
                if (discovered.size() == totalWords) break;

                string prefix(1, startChar);
                int currentCount = 0;
                int queryBound = 1;

                while (discovered.size() < totalWords) {
                    if (queryBound <= currentCount) {
                        queryBound *= 2;
                        continue;
                    }

                    int otherWords = discovered.size() - currentCount;
                    int maxPossible = totalWords - otherWords;
                    int requested = min(queryBound, maxPossible);

                    if (requested <= currentCount) {
                        queryBound *= 2;
                        continue;
                    }

                    cout << "query " << prefix << " " << requested << endl;
                    int actualCount;
                    cin >> actualCount;

                    for (int idx = 0; idx < actualCount; ++idx) {
                        string word;
                        cin >> word;
                        discovered.insert(word);
                    }

                    currentCount = actualCount;

                    if (actualCount < requested) {
                        break;
                    }

                    if (discovered.size() == totalWords) break;
                    queryBound *= 2;
                }
            }

            cout << "answer";
            for (const string& word : discovered) {
                cout << " " << word;
            }
            cout << endl;
        }
    }
    return 0;
}

