// ===== UNIT TRIANGLE (Modified) =====
UnitTriangle::UnitTriangle() {
    // Initialize internal state variables
    previousSkew = sc_clip(in0(Skew), 0.0f, 1.0f);

    // Determine if the Skew input is audio-rate
    isSkewModulated = isAudioRateIn(Skew);

    mCalcFunc = make_calc_function<UnitTriangle, &UnitTriangle::process>();
    process(1);
}

void UnitTriangle::process(int sampleCount) {

    // Get phase input buffer
    const float* phaseBuffer = in(Phase);

    // Create slope for smooth parameter transitions (control-rate)
    auto skewSlope = makeSlope(sc_clip(in0(Skew), 0.0f, 1.0f), previousSkew);

    // Output buffer
    float* outBuffer = out(Out);

    for (int idx = 0; idx < sampleCount; ++idx) {

        // Normalize phase to [0, 1)
        float currentPhase = sc_frac(phaseBuffer[idx]);

        // Select appropriate skew value based on rate
        float currentSkew = isSkewModulated ? 
            sc_clip(in(Skew)[idx], 0.0f, 1.0f) : 
            skewSlope.consume();

        outBuffer[idx] = UnitShapers::triangle(currentPhase, currentSkew);
    }

    // Update cached parameter value
    previousSkew = isSkewModulated ? 
        sc_clip(in(Skew)[sampleCount - 1], 0.0f, 1.0f) : 
        skewSlope.value;
}

// ===== UNIT KINK (Modified) =====
UnitKink::UnitKink() {
    // Initialize internal state variables
    previousSkew = sc_clip(in0(Skew), 0.0f, 1.0f);

