// ===== UNIT CUBIC (Modified) =====
UnitCubic::UnitCubic() {
    // Initialize internal state variables
    previousIndex = sc_clip(in0(Index), 0.0f, 1.0f);

    // Determine if the Index input is audio-rate
    isIndexModulated = isAudioRateIn(Index);

    mCalcFunc = make_calc_function<UnitCubic, &UnitCubic::process>();
    process(1);
}

void UnitCubic::process(int sampleCount) {

    // Get phase input buffer
    const float* phaseBuffer = in(Phase);

    // Create slope for smooth parameter transitions (control-rate)
    auto indexSlope = makeSlope(sc_clip(in0(Index), 0.0f, 1.0f), previousIndex);

    // Output buffer
    float* outBuffer = out(Out);

    for (int idx = 0; idx < sampleCount; ++idx) {

        // Normalize phase to [0, 1)
        float currentPhase = sc_frac(phaseBuffer[idx]);

        // Select appropriate index value based on rate
        float currentIndex = isIndexModulated ? 
            sc_clip(in(Index)[idx], 0.0f, 1.0f) : 
            indexSlope.consume();

        outBuffer[idx] = UnitShapers::cubic(currentPhase, currentIndex);
    }

    // Update cached parameter value
    previousIndex = isIndexModulated ? 
        sc_clip(in(Index)[sampleCount - 1], 0.0f, 1.0f) : 
        indexSlope.value;
}

