typedef double RealT;

template<typename Real>
class LossEx16Alt : public ROL::StdObjective<Real> {
public:
  Real value( const std::vector<Real> &x, Real &tol ) override {
    std::vector<Real> params = ROL::StdObjective<Real>::getParameter();
    return std::inner_product(x.begin(), x.end(), params.begin(), static_cast<Real>(0));
  }

  void gradient( std::vector<Real> &g, const std::vector<Real> &x, Real &tol ) override {
    std::vector<Real> params = ROL::StdObjective<Real>::getParameter();
    g = params;
  }

  void hessVec( std::vector<Real> &hv, const std::vector<Real> &v, const std::vector<Real> &x, Real &tol ) override {
    std::fill(hv.begin(), hv.end(), static_cast<Real>(0));
  }
};

template<typename Real>
class BudgetEx16Alt : public ROL::StdConstraint<Real> {
public:
  void value( std::vector<Real> &c, const std::vector<Real> &x, Real &tol ) override {
    c[0] = std::accumulate(x.begin(), x.end(), static_cast<Real>(0)) - static_cast<Real>(1);
  }

  void applyJacobian( std::vector<Real> &jv, const std::vector<Real> &v, const std::vector<Real> &x, Real &tol ) override {
    jv[0] = std::accumulate(v.begin(), v.end(), static_cast<Real>(0));
  }

  void applyAdjointJacobian( std::vector<Real> &ajv, const std::vector<Real> &v, const std::vector<Real> &x, Real &tol ) override {
    std::fill(ajv.begin(), ajv.end(), v[0]);
  }

  void applyAdjointHessian( std::vector<Real> &ahuv, const std::vector<Real> &u, const std::vector<Real> &v, const std::vector<Real> &x, Real &tol ) override {
    std::fill(ahuv.begin(), ahuv.end(), static_cast<Real>(0));
  }
};

void displayResult(const std::vector<RealT> &solution,
                   std::ostream & outputStream) {
  size_t dimension = solution.size();
  outputStream << std::endl;
  outputStream << "Solution vector: (";
  for ( size_t idx = 0; idx < dimension-1; idx++ ) {
    outputStream << solution[idx] << ", ";
  }
  outputStream << solution[dimension-1] << ")\n" << std::endl;
}

int main(int argc, char* argv[]) {
  //feenableexcept(FE_DIVBYZERO | FE_INVALID | FE_OVERFLOW);
  ROL::GlobalMPISession mpiSession(&argc, &argv);

  int printFlag     = argc - 1;
  bool verbose      = printFlag > 0;
  ROL::Ptr<std::ostream> outputStream;
  ROL::nullstream dummyStream;

  if (printFlag > 0)
    outputStream = ROL::makePtrFromRef(std::cout);
  else
    outputStream = ROL::makePtrFromRef(dummyStream);

  int statusFlag  = 0;

  try {
    /**********************************************************************************************/
    /************************* CONSTRUCT ROL ALGORITHM ********************************************/
    /**********************************************************************************************/
    std::string inputFilename = "input_16.xml";
    auto paramList = ROL::getParametersFromXmlFile(inputFilename);
    ROL::ParameterList parameters = *paramList;
    parameters.sublist("General").set("Output Level", verbose ? 1 : 0);

    /**********************************************************************************************/
    /************************* CONSTRUCT SOL COMPONENTS *******************************************/
    /**********************************************************************************************/
    size_t numVariables = 10;
    ROL::Ptr<ROL::StdVector<RealT>>
      x_vector = ROL::makePtr<ROL::StdVector<RealT>>(numVariables, 0.0);

    int numSamples = 1000;
    RealT offsetValue(0);
    std::vector<std::vector<RealT>> variableBounds;

    for (size_t i = 0; i < numVariables; ++i) {
      RealT lower = -static_cast<RealT>(rand())/static_cast<RealT>(RAND_MAX);
      RealT upper =  static_cast<RealT>(rand())/static_cast<RealT>(RAND_MAX);
      variableBounds.push_back({lower, upper});
      *outputStream << "  Asset "        << i << ":"
                 << "  Lower Bound: " << lower
                 << "  Upper Bound: " << upper << std::endl;
      offsetValue += upper / static_cast<RealT>(numVariables);
    }

    offsetValue *= static_cast<RealT>(0.35);

    ROL::Ptr<ROL::BatchManager<RealT>>
      batchManager = ROL::makePtr<ROL::BatchManager<RealT>>();

    ROL::Ptr<ROL::SampleGenerator<RealT>>
      sampler = ROL::makePtr<ROL::MonteCarloGenerator<RealT>>(numSamples, variableBounds, batchManager);

    ROL::Ptr<ROL::Objective<RealT>>
      objectiveFunc = ROL::makePtr<LossEx16Alt<RealT>>();
    objectiveFunc->setParameter(sampler->getMyPoint(0));

    ROL::Ptr<ROL::Constraint<RealT>>
      constraintObj = ROL::makePtr<ROL::ConstraintFromObjective<RealT>>(objectiveFunc);

    ROL::Ptr<ROL::SingletonVector<RealT>>
      multiplier_constraint = ROL::makePtr<ROL::SingletonVector<RealT>>(0);

    ROL::Ptr<ROL::SingletonVector<RealT>>
      upper_bound_constraint = ROL::makePtr<ROL::SingletonVector<RealT>>(offsetValue);

    ROL::Ptr<ROL::BoundConstraint<RealT>>
      bound_constraint = ROL::makePtr<ROL::Bounds<RealT>>(*upper_bound_constraint, false);

    ROL::Ptr<ROL::Constraint<RealT>>
      budgetConstraint = ROL::makePtr<BudgetEx16Alt<RealT>>();

    ROL::Ptr<ROL::StdVector<RealT>>
      multiplier_budget = ROL::makePtr<ROL::StdVector<RealT>>(1, 0.0);

    ROL::Ptr<ROL::StochasticProblem<RealT>>
      optimizationProblem = ROL::makePtr<ROL::StochasticProblem<RealT>>(objectiveFunc, x_vector);

    optimizationProblem->addLinearConstraint("Budget", budgetConstraint, multiplier_budget);
    optimizationProblem->addLinearConstraint("Loss", constraintObj, multiplier_constraint, bound_constraint);

    optimizationProblem->finalize(false, true, *outputStream);
    optimizationProblem->check(true, *outputStream);

    std::vector<std::pair<std::string,std::vector<RealT>>> results;

    optimizationProblem->edit();

    ROL::ParameterList objectiveParams;
    objectiveParams.sublist("SOL").sublist("Objective").set("Type","Deviation");
    objectiveParams.sublist("SOL").sublist("Objective").sublist("Deviation Measure").set("Name","Variance");
    optimizationProblem->makeObjectiveStochastic(objectiveParams, sampler);

    ROL::ParameterList constraintParams;
    constraintParams.sublist("SOL").sublist("Loss").set("Type","Risk Neutral");
    optimizationProblem->makeLinearConstraintStochastic("Loss", constraintParams, sampler, batchManager);

    optimizationProblem->finalize(false, true, *outputStream);
    optimizationProblem->check(true, *outputStream);

    ROL::Ptr<ROL::Solver<RealT>>
      solver = ROL::makePtr<ROL::Solver<RealT>>(optimizationProblem, *paramList);

    solver->solve(*outputStream);
    statusFlag += (solver->getAlgorithmState()->statusFlag == ROL::EXITSTATUS_CONVERGED ? 0 : 1);
    displayResult(*x_vector->getVector(), *outputStream);

    ROL::Ptr<ROL::Vector<RealT>> tempVec = x_vector->clone(); 
    tempVec->set(*x_vector);
    results.push_back({"Risk Neutral", *x_vector->getVector()});

    optimizationProblem->edit();
    optimizationProblem->resetStochasticLinearConstraint("Loss");
    constraintParams.sublist("SOL").sublist("Loss").set("Type","Mean Value");
    optimizationProblem->makeLinearConstraintStochastic("Loss", constraintParams, sampler);
    optimizationProblem->finalize(false, true, *outputStream);
    optimizationProblem->check(true, *outputStream);

    solver = ROL::makePtr<ROL::Solver<RealT>>(optimizationProblem, *paramList);
    solver->solve(*outputStream);
    statusFlag += (solver->getAlgorithmState()->statusFlag == ROL::EXITSTATUS_CONVERGED ? 0 : 1);
    displayResult(*x_vector->getVector(), *outputStream);

    tempVec->axpy(-1.0, *x_vector);
    statusFlag += (tempVec->norm() > 100.0*std::sqrt(ROL::ROL_EPSILON<RealT>()) ? 1 : 0);
    results.push_back({"Mean Value", *x_vector->getVector()});

    optimizationProblem->edit();
    constraintParams.sublist("SOL").sublist("Loss").set("Type","Risk Averse");
    constraintParams.sublist("SOL").sublist("Loss").sublist("Risk Measure").set("Name","CVaR");
    constraintParams.sublist("SOL").sublist("Loss").sublist("Risk Measure").sublist("CVaR").set("Confidence Level",0.95);
    constraintParams.sublist("SOL").sublist("Loss").sublist("Risk Measure").sublist("CVaR").set("Convex Combination Parameter",1.0);
    constraintParams.sublist("SOL").sublist("Loss").sublist("Risk Measure").sublist("CVaR").set("Smoothing Parameter",1e-4);
    constraintParams.sublist("SOL").sublist("Loss").sublist("Risk Measure").sublist("CVaR").sublist("Distribution").set("Name","Parabolic");
    constraintParams.sublist("SOL").sublist("Loss").sublist("Risk Measure").sublist("CVaR").sublist("Distribution").sublist("Parabolic").set("Lower Bound",-0.5);
    constraintParams.sublist("SOL").sublist("Loss").sublist("Risk Measure").sublist("CVaR").sublist("Distribution").sublist("Parabolic").set("Upper Bound", 0.5);

    optimizationProblem->removeLinearConstraint("Loss");
    optimizationProblem->addConstraint("Loss", constraintObj, multiplier_constraint, bound_constraint);
    optimizationProblem->makeConstraintStochastic("Loss", constraintParams, sampler);

    optimizationProblem->finalize(false, true, *outputStream);
    optimizationProblem->check(true, *outputStream);

    solver = ROL::makePtr<ROL::Solver<RealT>>(optimizationProblem, *paramList);
    solver->solve(*outputStream);
    statusFlag += (solver->getAlgorithmState()->statusFlag == ROL::EXITSTATUS_CONVERGED ? 0 : 1);
    displayResult(*x_vector->getVector(), *outputStream);

    results.push_back({"bPOE", *x_vector->getVector()});

    *outputStream << std::endl << std::scientific << std::setprecision(6);
    for (const auto& result : results) {
      *outputStream << "  ";
      *outputStream << std::setw(20) << std::left << result.first;
      for (const auto& component : result.second) 
        *outputStream << std::setw(18) << std::left << component;
      *outputStream << std::endl;
    }
    *outputStream << std::endl;
  }
  catch (std::logic_error& err) {
    *outputStream << err.what() << "\n";
    statusFlag = -1000;
  }

  if (statusFlag != 0)
    std::cout << "End Result: TEST FAILED\n";
  else
    std::cout << "End Result: TEST PASSED\n";

  return 0;
}

