int get_current_device_index()
{
    CUcontext cu_context = nullptr;
    SGL_CU_CHECK(cuCtxGetCurrent(&cu_context));
    SGL_CHECK(cu_context, "No active CUDA context found when trying to get current device index.");
    CUdevice cu_device = 0;
    SGL_CU_CHECK(cuCtxGetDevice(&cu_device));
    SGL_CHECK(cu_device >= 0, "Failed to get current CUDA device.");
    return static_cast<int>(cu_device);
}
void* allocate_device_memory(size_t size)
{
    CUdeviceptr ptr;
    SGL_CU_CHECK(cuMemAlloc(&ptr, size));
    return reinterpret_cast<void*>(ptr);
}
void free_device_memory(void* ptr)
{
    if (!ptr)
        return;
    SGL_CU_CHECK(cuMemFree(reinterpret_cast<CUdeviceptr>(ptr)));
}
void copy_device_to_device(void* dst, const void* src, size_t count)
{
    SGL_CU_CHECK(cuMemcpyDtoD(reinterpret_cast<CUdeviceptr>(dst), reinterpret_cast<CUdeviceptr>(src), count));
}
void copy_host_to_device(void* dst, const void* src, size_t count)
{
