int climbWays(int steps) {
    // Base case: if steps are 0, 1, or 2, return the steps value directly
	if(steps <= 2){
		return steps;
	}
	// Recursive case: sum of ways to reach (steps-1) and (steps-2)
	return climbWays(steps - 1) + climbWays(steps - 2);
}

