namespace glk {

TextureRenderer::TextureRenderer() {
  plain_effect = std::make_shared<PlainRendering>();

  // Define vertex positions for a full-screen quad
  std::vector<Eigen::Vector3f> quad_vertices = {
    Eigen::Vector3f(-1.0f, -1.0f, 0.0f),
    Eigen::Vector3f(1.0f, -1.0f, 0.0f),
    Eigen::Vector3f(-1.0f, 1.0f, 0.0f),
    Eigen::Vector3f(1.0f, 1.0f, 0.0f)};

  glGenVertexArrays(1, &vao);
  glBindVertexArray(vao);

  glGenBuffers(1, &vbo);
  glBindBuffer(GL_ARRAY_BUFFER, vbo);

  glBufferData(GL_ARRAY_BUFFER, sizeof(GL_FLOAT) * 3 * quad_vertices.size(), quad_vertices.data(), GL_STATIC_DRAW);

  glBindVertexArray(vao);
  glBindBuffer(GL_ARRAY_BUFFER, vbo);

  glVertexAttribPointer(0, 3, GL_FLOAT, GL_FALSE, 0, 0);

  glBindBuffer(GL_ARRAY_BUFFER, 0);
}

TextureRenderer::~TextureRenderer() {
  glDeleteVertexArrays(1, &vao);
  glDeleteBuffers(1, &vbo);
}

void TextureRenderer::draw(const glk::Texture& texture) {
  plain_effect->draw(*this, texture);
}

void TextureRenderer::draw_plain(glk::GLSLShader& program) const {
  GLint vertex_position_loc = program.attrib("vert_position");

  glBindVertexArray(vao);
  glEnableVertexAttribArray(vertex_position_loc);

  glDrawArrays(GL_TRIANGLE_STRIP, 0, 4);

  glBindBuffer(GL_ARRAY_BUFFER, 0);
}

}  // namespace glk

