#include <iostream>

// Main entry point for hart 0 performance measurement
int main()
{
    register int core_id;
    asm volatile ("csrr %[rd], mhartid" : [rd] "=r" (core_id));
    if (core_id == 0)
    {
        unsigned counter_val;
        int cycles_start, cycles_end, instructions_start, instructions_end;
        volatile unsigned* shared_var = &counter_val;

        // Read time and instruction count registers
        asm volatile ("csrr %0, time" : "=r"(cycles_start));
        asm volatile ("csrr %0, time" : "=r"(cycles_end));
        asm volatile ("csrr %0, instret" : "=r"(instructions_start));
        asm volatile ("csrr %0, instret" : "=r"(instructions_end));

        // Calculate harts ratio from timing measurements
        int cores_ratio = (cycles_end - cycles_start) / (instructions_end - instructions_start);

        int overhead, prev_overhead;
        for (int iteration = 0; iteration < 5; ++iteration)
        {
            // Capture start timestamps
            asm volatile ("csrr %0, time" : "=r"(cycles_start));
            asm volatile ("csrr %0, instret" : "=r"(instructions_start));

            // Modify shared variable conditionally
            if (*shared_var != 4)
            {
                ++(*shared_var);
            }
            else
            {
                --(*shared_var);
            }

            // Capture end timestamps
            asm volatile ("csrr %0, time" : "=r"(cycles_end));
            asm volatile ("csrr %0, instret" : "=r"(instructions_end));

            // Compute bubble count difference
            prev_overhead = overhead;
            overhead = (cycles_end - cycles_start) / cores_ratio - (instructions_end - instructions_start);
        }

        // Write results to fixed memory addresses
        int* penalty_ptr = (int*)0x80200000;
        int* cores_ptr   = (int*)0x80200004;

        *penalty_ptr = overhead - prev_overhead;
        *cores_ptr = cores_ratio;

        // System call to exit
        asm volatile ("ecall");
    }
    else
    {
        // Other harts spin indefinitely
        for(;;);
    }
}

