namespace corosio = boost::corosio;
namespace capy    = boost::capy;

// Minimal coroutine - just increments a counter, designed to expose framework overhead
capy::task<>
lightweight_coro(std::atomic<std::uint64_t>& op_count)
{
    op_count.fetch_add(1, std::memory_order_relaxed);
    co_return;
}

// Execute the performance test for a given time period
void
execute_benchmark(
    perf::context_factory factory,
    int runtime_seconds,
    int batch_size,
    int thread_count)
{
    auto ioc = factory();
    auto ex  = ioc->get_executor();
    std::atomic<std::uint64_t> op_count{0};

    auto start_time   = std::chrono::steady_clock::now();
    auto finish_time  = start_time + std::chrono::seconds(runtime_seconds);
    auto report_time  = start_time + std::chrono::seconds(2);

    std::cout << "Executing benchmark for " << runtime_seconds << " seconds...\n";
    std::cout << "Batch size: " << batch_size << ", Threads: " << thread_count << "\n\n";

    std::uint64_t previous_count = 0;
    int loop_count               = 0;

    while (std::chrono::steady_clock::now() < finish_time)
    {
        // Submit operations in batches
        for (int j = 0; j < batch_size; ++j)
            capy::run_async(ex)(lightweight_coro(op_count));

        // Run with multiple threads if specified
        if (thread_count > 1)
        {
            std::vector<std::thread> worker_threads;
            worker_threads.reserve(thread_count);

            for (int t = 0; t < thread_count; ++t)
                worker_threads.emplace_back([&]() { ioc->run(); });

            for (auto& wt : worker_threads)
                wt.join();
        }
        else
        {
            ioc->run();
        }

        ioc->restart();
        ++loop_count;

        // Output progress every 2 seconds
        auto current_time = std::chrono::steady_clock::now();
        if (current_time >= report_time)
        {
            double elapsed = std::chrono::duration<double>(current_time - start_time).count();
            std::uint64_t current = op_count.load(std::memory_order_relaxed);
            double ops_per_sec = static_cast<double>(current - previous_count) / 2.0;

            std::cout << "  [" << std::fixed << std::setprecision(0) << elapsed
                      << "s] " << perf::format_rate(ops_per_sec) << " (" << loop_count
                      << " loops)\n";

            previous_count = current;
            report_time    = current_time + std::chrono::seconds(2);
        }
    }

    // Final statistics
    auto total_duration =
        std::chrono::duration<double>(std::chrono::steady_clock::now() - start_time).count();
    std::uint64_t total_ops = op_count.load(std::memory_order_relaxed);
    double average_rate     = static_cast<double>(total_ops) / total_duration;

    std::cout << "\n=== Benchmark Results ===\n";
    std::cout << "  Duration:   " << std::fixed << std::setprecision(2)
              << total_duration << " s\n";
    std::cout << "  Operations: " << total_ops << "\n";
    std::cout << "  Loops:      " << loop_count << "\n";
    std::cout << "  Avg rate:   " << perf::format_rate(average_rate) << "\n";
}

void
run_benchmark_suite(
    perf::context_factory factory,
    const char* backend_label,
    int run_length,
    int batch_size,
    int num_workers)
{
    std::cout << "Corosio Benchmark Suite: Batch Size Analysis\n";
    std::cout << "============================================\n";
    std::cout << "Backend: " << backend_label << "\n\n";
    std::cout << "Benchmark objectives:\n";
    std::cout << "  - Queue traversal efficiency\n";
    std::cout << "  - Completed operations processing in do_one()\n";
    std::cout << "  - Cache-friendly memory access patterns\n";
    std::cout << "  - Dispatch overhead at high concurrency\n\n";

    // Warm-up phase
    std::cout << "Warming up (1 second)...\n";
    {
        auto ioc = factory();
        auto ex  = ioc->get_executor();
        std::atomic<std::uint64_t> warmup_counter{0};
        auto warmup_finish =
            std::chrono::steady_clock::now() + std::chrono::seconds(1);

        while (std::chrono::steady_clock::now() < warmup_finish)
        {
            for (int k = 0; k < 1000; ++k)
                capy::run_async(ex)(lightweight_coro(warmup_counter));
            ioc->poll();
            ioc->restart();
        }
    }

    std::cout << "Warm-up finished.\n\n";

    // Main benchmark execution
    execute_benchmark(factory, run_length, batch_size, num_workers);
    std::cout << "\nBenchmark completed.\n";
}

void
show_usage(const char* program_name)
{
    std::cout << "Usage: " << program_name << " [OPTIONS]\n\n";
    std::cout
        << "Benchmark workload for analyzing large pending queue dispatch behavior.\n\n";
    std::cout << "Available options:\n";
    std::cout << "  --backend <name>     Choose I/O backend (default: platform default)\n";
    std::cout
        << "  --runtime <seconds>  Test duration in seconds (default: 10)\n";
    std::cout << "  --batch <size>       Operations per batch (default: 100000)\n";
    std::cout << "  --workers <count>    Number of worker threads (default: 1)\n";
    std::cout << "  --list               Display available backends\n";
    std::cout << "  --help               Show this help text\n";
    std::cout << "\n";
    std::cout << "Example:\n";
    std::cout << "  " << program_name << " --batch 100000 --workers 4\n";
    std::cout << "\n";
    perf::print_available_backends();
}

int
main(int argc, char* argv[])
{
    const char* selected_backend = nullptr;
    int runtime                  = 10;
    int batch_size               = 100000;
    int worker_count             = 1;

    // Parse command-line arguments
    for (int i = 1; i < argc; ++i)
    {
        if (std::strcmp(argv[i], "--backend") == 0)
        {
            if (i + 1 < argc)
                selected_backend = argv[++i];
            else
            {
                std::cerr << "Error: --backend requires an argument\n";
                return 1;
            }
        }
        else if (std::strcmp(argv[i], "--runtime") == 0)
        {
            if (i + 1 < argc)
                runtime = std::atoi(argv[++i]);
            else
            {
                std::cerr << "Error: --runtime requires an argument\n";
                return 1;
            }
        }
        else if (std::strcmp(argv[i], "--batch") == 0)
        {
            if (i + 1 < argc)
                batch_size = std::atoi(argv[++i]);
            else
            {
                std::cerr << "Error: --batch requires an argument\n";
                return 1;
            }
        }
        else if (std::strcmp(argv[i], "--workers") == 0)
        {
            if (i + 1 < argc)
                worker_count = std::atoi(argv[++i]);
            else
            {
                std::cerr << "Error: --workers requires an argument\n";
                return 1;
            }
        }
        else if (std::strcmp(argv[i], "--list") == 0)
        {
            perf::print_available_backends();
            return 0;
        }
        else if (
            std::strcmp(argv[i], "--help") == 0 ||
            std::strcmp(argv[i], "-h") == 0)
        {
            show_usage(argv[0]);
            return 0;
        }
        else
        {
            std::cerr << "Unknown option: " << argv[i] << "\n";
            show_usage(argv[0]);
            return 1;
        }
    }

    // Validate input parameters
    if (batch_size < 1)
    {
        std::cerr << "Error: --batch must be >= 1\n";
        return 1;
    }
    if (worker_count < 1)
    {
        std::cerr << "Error: --workers must be >= 1\n";
        return 1;
    }

    // Use default backend if none specified
    if (!selected_backend)
        selected_backend = perf::default_backend_name();

    // Run the benchmark using the selected backend
    return perf::dispatch_backend(
        selected_backend, [=](perf::context_factory factory, auto, const char* name) {
            run_benchmark_suite(
                factory, name, runtime, batch_size, worker_count);
        });
}

