#include <iostream>
#include <vector>
#include <bitset>
#include <algorithm>
#include <random>
#include <chrono>
#include <numeric>
using namespace std;

// ----------------------
// Constants & Globals
// ----------------------
const int MAX_NODES = 1005;
const double TIME_THRESHOLD = 1.95; // seconds
int nodeCount, edgeCount;
bitset<MAX_NODES> connectionMatrix[MAX_NODES];   // Adjacency matrix (bitset for speed)
vector<int> neighborList[MAX_NODES];             // Adjacency list (stores neighbors for iteration)
bool selectedNode[MAX_NODES];                    // Current solution status (true if vertex is in S)
int neighborCountInSet[MAX_NODES];               // neighborCountInSet[v] = |N(v) ∩ S| (number of neighbors in S)
int optimalConfiguration[MAX_NODES];             // Best solution found so far
int maxSelected = 0;                             // Size of best solution

// Random Number Generator
mt19937 randomGen(1337);

// Time Management
auto startTime = chrono::high_resolution_clock::now();
double elapsed_time() {
    auto currentTime = chrono::high_resolution_clock::now();
    chrono::duration<double> duration = currentTime - startTime;
    return duration.count();
}

// ----------------------
// Core Functions
// ----------------------

// Add vertex u to S, update neighbors' tightness
void include_vertex(int u) {
    if (selectedNode[u]) return;
    selectedNode[u] = true;
    for (int v : neighborList[u]) {
        neighborCountInSet[v]++;
    }
}

// Remove vertex u from S, update neighbors' tightness
void exclude_vertex(int u) {
    if (!selectedNode[u]) return;
    selectedNode[u] = false;
    for (int v : neighborList[u]) {
        neighborCountInSet[v]--;
    }
}

// Update the global best solution if current is better
void update_optimal() {
    int currentSize = 0;
    for (int i = 1; i <= nodeCount; ++i) {
        if (selectedNode[i]) currentSize++;
    }

    if (currentSize > maxSelected) {
        maxSelected = currentSize;
        for (int i = 1; i <= nodeCount; ++i) {
            optimalConfiguration[i] = selectedNode[i] ? 1 : 0;
        }
    }
}

// Helper: Find the unique neighbor in S for a vertex v with tightness 1
// Returns -1 if no neighbor in S (should not happen if tightness==1)
int find_unique_neighbor(int v) {
    for (int u : neighborList[v]) {
        if (selectedNode[u]) return u;
    }
    return -1;
}

// Generate an initial solution using Randomized Greedy
void build_initial_solution() {
    // Clear state
    for (int i = 1; i <= nodeCount; ++i) {
        selectedNode[i] = false;
        neighborCountInSet[i] = 0;
    }

    // Order vertices randomly
    vector<int> order(nodeCount);
    iota(order.begin(), order.end(), 1);
    shuffle(order.begin(), order.end(), randomGen);

    // Greedy construction: pick valid vertices
    for (int u : order) {
        if (neighborCountInSet[u] == 0) {
            include_vertex(u);
        }
    }
    update_optimal();
}

// ----------------------
// Main Solver (Iterated Local Search)
// ----------------------
void optimize() {
    build_initial_solution();

    // Tabu search state: tabu[u] stores the iteration number until which vertex u is locked
    vector<int> tabuList(nodeCount + 1, 0);
    int iteration = 0;
    int stagnantIterations = 0;

    // Parameters for search control
    const int TABU_DURATION_BASE = 7;
    const int MAX_STAGNANT = 2500; // Threshold to trigger perturbation

    // Buffer for (1, 2)-swap candidates
    // candidateList[u] stores vertices v such that v is not in S, neighborCountInSet[v]=1, and neighbor of v is u
    vector<vector<int>> candidateList(nodeCount + 1);
    while (true) {
        // Time Check
        if ((iteration & 127) == 0) { // Check periodically
            if (elapsed_time() > TIME_THRESHOLD) break;
        }
        iteration++;

        bool progressMade = false;

        // ------------------------------------------
        // Phase 1: Immediate Additions (Tightness 0)
        // ------------------------------------------
        // If any vertex has 0 neighbors in S, add it immediately.
        vector<int> zeroNeighbors;
        for (int i = 1; i <= nodeCount; ++i) {
            if (!selectedNode[i] && neighborCountInSet[i] == 0) {
                zeroNeighbors.push_back(i);
            }
        }

        if (!zeroNeighbors.empty()) {
            for (int u : zeroNeighbors) include_vertex(u);
            update_optimal();
            stagnantIterations = 0;
            // If we added vertices, constraints changed, so restart loop to check new opportunities
            continue; 
        }

        // ------------------------------------------
        // Phase 2: (1, 2)-Swaps
        // ------------------------------------------
        // Try to replace 1 vertex u in S with 2 vertices v1, v2 not in S.
        // Requires: neighborCountInSet[v1]=1, neighborCountInSet[v2]=1, N(v1)∩S = {u}, N(v2)∩S = {u}, and v1 not adjacent to v2.

        vector<int> singleNeighborVertices;
        for (int i = 1; i <= nodeCount; ++i) {
            if (!selectedNode[i] && neighborCountInSet[i] == 1) {
                singleNeighborVertices.push_back(i);
            }
        }

        // Group candidates by their single neighbor in S
        vector<int> activeCenters;
        for (int v : singleNeighborVertices) {
            int u = find_unique_neighbor(v);
            if (u != -1) {
                if (candidateList[u].empty()) activeCenters.push_back(u);
                candidateList[u].push_back(v);
            }
        }

        bool swapPerformed = false;
        for (int u : activeCenters) {
            if (candidateList[u].size() >= 2) {
                vector<int>& candidates = candidateList[u];
                // Check all pairs in candidates for independence
                for (size_t i = 0; i < candidates.size(); ++i) {
                    for (size_t j = i + 1; j < candidates.size(); ++j) {
                        int v1 = candidates[i];
                        int v2 = candidates[j];
                        // If v1 and v2 are not connected
                        if (!connectionMatrix[v1][v2]) {
                            // Perform (1, 2)-swap
                            exclude_vertex(u);
                            include_vertex(v1);
                            include_vertex(v2);

                            // Set tabu to avoid immediate reversal
                            tabuList[u] = iteration + TABU_DURATION_BASE + (randomGen() % 5);

                            swapPerformed = true;
                            goto end_swap_search;
                        }
                    }
                }
            }
        }

        end_swap_search:
        // Cleanup used vectors
        for (int u : activeCenters) candidateList[u].clear();

        if (swapPerformed) {
            update_optimal();
            stagnantIterations = 0;
            continue;
        }

        // ------------------------------------------
        // Phase 3: (1, 1)-Swaps (Tabu Search)
        // ------------------------------------------
        // Swap u in S with v not in S (neighborCountInSet[v]=1, neighbor=u) to escape local optima.
        // Size remains constant, but configuration changes.

        vector<int> acceptableMoves;
        for (int v : singleNeighborVertices) {
            int u = find_unique_neighbor(v);
            // Tabu check: allow move only if vertices are not tabu
            if (tabuList[v] <= iteration && tabuList[u] <= iteration) {
                acceptableMoves.push_back(v);
            }
        }

        if (!acceptableMoves.empty()) {
            // Pick a random valid (1,1) move
            int v = acceptableMoves[randomGen() % acceptableMoves.size()];
            int u = find_unique_neighbor(v);

            exclude_vertex(u);
            include_vertex(v);

            int duration = TABU_DURATION_BASE + (randomGen() % 5);
            tabuList[u] = iteration + duration;
            tabuList[v] = iteration + duration;

            stagnantIterations++;
        } else {
            // No moves available (highly constrained state)
            stagnantIterations += 50; 
        }

        // ------------------------------------------
        // Phase 4: Perturbation (Kick / Soft Restart)
        // ------------------------------------------
        if (stagnantIterations > MAX_STAGNANT) {
            // Stop if too close to time limit
            if (elapsed_time() > TIME_THRESHOLD - 0.05) break;
            // Restore best solution found so far
            for (int i = 1; i <= nodeCount; ++i) selectedNode[i] = false;
            for (int i = 1; i <= nodeCount; ++i) if (optimalConfiguration[i]) selectedNode[i] = true;

            // Recompute neighborCountInSet for best solution state
            fill(neighborCountInSet, neighborCountInSet + nodeCount + 1, 0);
            for (int i = 1; i <= nodeCount; ++i) {
                if (selectedNode[i]) {
                    for (int nbr : neighborList[i]) neighborCountInSet[nbr]++;
                }
            }

            // Perform Kick: Remove random K vertices from the best solution
            vector<int> selectedNodes;
            for (int i = 1; i <= nodeCount; ++i) if (selectedNode[i]) selectedNodes.push_back(i);

            if (!selectedNodes.empty()) {
                shuffle(selectedNodes.begin(), selectedNodes.end(), randomGen);
                int removeCount = max(3, (int)selectedNodes.size() / 15); // Remove ~6-7%
                for (int k = 0; k < removeCount && k < (int)selectedNodes.size(); ++k) {
                    exclude_vertex(selectedNodes[k]);
                }
            }

            // Reset tabu memory and counters
            fill(tabuList.begin(), tabuList.end(), 0);
            stagnantIterations = 0;
            // The next loop iteration will fill holes using Phase 1 (Greedy)
        }
    }
}

int main() {
    // Optimize I/O operations
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    if (!(cin >> nodeCount >> edgeCount)) return 0;

    for (int i = 0; i < edgeCount; ++i) {
        int u, v;
        cin >> u >> v;
        if (u == v) continue;
        // Use bitset to handle duplicate edges efficiently
        if (!connectionMatrix[u][v]) {
            connectionMatrix[u][v] = 1;
            connectionMatrix[v][u] = 1;
            neighborList[u].push_back(v);
            neighborList[v].push_back(u);
        }
    }

    optimize();

    // Output result
    for (int i = 1; i <= nodeCount; ++i) {
        cout << optimalConfiguration[i] << "\n";
    }

    return 0;
}

