// Insertion sort implementation 
int main() {
    int n = 5;
    int arr[] = {5, 2, 8, 1, 9};

    for (int index = 0; index < n; index++) {
        int temp = arr[index];
        int j = index - 1;

        // Shift elements greater than temp to the right
        for (; j >= 0 && arr[j] > temp; j--) {
            arr[j + 1] = arr[j];
        }

        arr[j + 1] = temp;
    }

    return 0;
}

