UIScene_SaveMessage::UIScene_SaveMessage(int playerIndex, void *userData, UILayer *layer) : UIScene(playerIndex, layer)
{
	// Initialize required Iggy references for this scene
	initialiseMovie();
	layer->addComponent(playerIndex, eUIComponent_Panorama);
	layer->addComponent(playerIndex, eUIComponent_Logo);
	m_buttonConfirm.init(app.GetString(IDS_CONFIRM_OK), eControl_Confirm);
	m_labelDescription.init(app.GetString(IDS_SAVE_ICON_MESSAGE));
	IggyDataValue status;

	// Adjust UI layout for certain locales (e.g., Russian)
	IggyResult res = IggyPlayerCallMethodRS(getMovie(), &status, IggyPlayerRootPath(getMovie()), m_funcAutoResize, 0, NULL);

	// 4J-PB - Trigger DLC installation if user is signed in and not already processing
	for(unsigned int idx = 0; idx < XUSER_MAX_COUNT; ++idx)
	{
		if( (InputManager.IsPadConnected(idx) || ProfileManager.IsSignedIn(idx)) ) 
		{
			if(!app.DLCInstallProcessCompleted() && !app.DLCInstallPending()) 
			{
				app.StartInstallDLCProcess(idx);
				break;
			}
		}
	}

	m_bIgnoreInput = false;

	// 4J-TomK - Rebuild touch UI after layout adjustment
#ifdef __PSVITA__
	ui.TouchBoxRebuild(this);
#endif
}

UIScene_SaveMessage::~UIScene_SaveMessage()
{
	m_parentLayer->removeComponent(eUIComponent_Panorama);
	m_parentLayer->removeComponent(eUIComponent_Logo);
}

