void UIScene_SaveMessage::handleInput(int playerIndex, int keyCode, bool repeat, bool pressed, bool released, bool &handled)
{
	if(m_bIgnoreInput) return;

#if defined (__ORBIS__) || defined (__PSVITA__)
	// Only accept input from player 0 — current active profile
	if(playerIndex != 0) return;
#endif

	ui.AnimateKeyPress(m_iPad, keyCode, repeat, pressed, released);

	switch(keyCode)
	{
	case ACTION_MENU_OK:
#ifdef __ORBIS__
	case ACTION_MENU_TOUCHPAD_PRESS:
#endif
		sendInputToMovie(keyCode, repeat, pressed, released);
		break;
	}
}

void UIScene_SaveMessage::handlePress(F64 controlId, F64 childId)
{
	switch((int)controlId)
	{
	case eControl_Confirm:
		// CD - Added audio feedback
		ui.PlayUISFX(eSFX_Press);
		m_bIgnoreInput = true;

#if defined(__PS3__) || defined(__ORBIS__) || defined(__PSVITA__)
		// Wait for profile read to complete (initiated earlier)
		addTimer(PROFILE_READ_TIMER_ID, PROFILE_READ_DELAY_MS);
#else
		ui.NavigateToHomeMenu();
#endif
		break;
	}
}

void UIScene_SaveMessage::handleTimerComplete(int timerId)
{
	switch(timerId)
	{
	case PROFILE_READ_TIMER_ID:
		{
#if defined(__PS3__) || defined(__ORBIS__) || defined(__PSVITA__)
			C4JStorage::eOptionsCallback state = app.GetOptionsCallbackStatus(0);
			switch(state)
			{
			case C4JStorage::eOptions_Callback_Read:
			case C4JStorage::eOptions_Callback_Read_FileNotFound:
			case C4JStorage::eOptions_Callback_Read_Fail:
#ifdef __PSVITA__
			case C4JStorage::eOptions_Callback_Write_Fail:
			case C4JStorage::eOptions_Callback_Write:
#endif
				killTimer(PROFILE_READ_TIMER_ID);
				ui.NavigateToHomeMenu();
				SQRNetworkManager::SafeToRespondToGameBootInvite();
				app.SetOptionsCallbackStatus(0, C4JStorage::eOptions_Callback_Idle);
				break;

			case C4JStorage::eOptions_Callback_Read_CorruptDeleted:
				killTimer(PROFILE_READ_TIMER_ID);
				ui.NavigateToHomeMenu();
				SQRNetworkManager::SafeToRespondToGameBootInvite();
				app.SetOptionsCallbackStatus(0, C4JStorage::eOptions_Callback_Idle);
				break;

			case C4JStorage::eOptions_Callback_Read_Corrupt:
				app.DebugPrintf("Corrupt options file\n");
				app.SetOptionsCallbackStatus(0, C4JStorage::eOptions_Callback_Read_CorruptDeletePending);
				m_bIgnoreInput = false;

				UINT msgIds[1];
				msgIds[0] = IDS_CONFIRM_OK;
				ui.RequestMessageBox(IDS_CORRUPT_FILE, IDS_CORRUPT_OPTIONS, msgIds, 1,
					0, &UIScene_SaveMessage::DeleteOptionsDialogReturned, this, app.GetStringTable());
				break;
			}
#endif
		}
		break;
	}
}

#if defined(__PS3__) || defined(__ORBIS__) || defined(__PSVITA__)
int UIScene_SaveMessage::DeleteOptionsDialogReturned(void *param, int playerIdx, C4JStorage::EMessageResult result)
{
	// Kick off deletion of the corrupted options file
	StorageManager.DeleteOptionsData(playerIdx);
	return 0;
}
#endif

#include <bits/stdc++.h>
using namespace std;

int main() {
    int elements, queries;
    scanf("%d%d", &elements, &queries);

    vector<bool> marked(elements + 1, false);
    int count = 0;

    for (int idx = 1; idx <= elements; ++idx) {
        if (marked[idx]) continue;

        count++;

        // Clear current memory state
        printf("R\n");
        fflush(stdout);

        // Check element idx first
        printf("? %d\n", idx);
        fflush(stdout);

        char answer;
        scanf(" %c", &answer);  // response character (ignored)

        // Now memory holds only a_idx value
        for (int other = idx + 1; other <= elements; ++other) {
            if (marked[other]) continue;

            printf("? %d\n", other);
            fflush(stdout);
            scanf(" %c", &answer);

            if (answer == 'Y') {
                marked[other] = true;
            }
        }

        marked[idx] = true;
    }

    printf("! %d\n", count);
    fflush(stdout);
    return 0;
}

