HRESULT CScene_FullscreenProgress::OnInit( XUIMessageInit* pInitData, BOOL& bHandled )
{
	MapChildControls();
	m_buttonConfirm.SetText( app.GetString( IDS_CONFIRM_OK ) );
	LoadingInputParams *data = (LoadingInputParams *)pInitData->pvInitData;
	m_CompletionData = data->completionData;
	m_iPad = data->completionData->iPad;
	m_cancelFunc = data->cancelFunc;
	m_cancelFuncParam = data->m_cancelFuncParam;
	m_completeFunc = data->completeFunc;
	m_completeFuncParam = data->m_completeFuncParam;
	m_bWasCancelled = false;
	thread = new C4JThread(data->func, data->lpParam, "FullscreenProgress");
	thread->SetProcessor(3); // TODO 4J Stu - Verify this thread/core assignment is optimal
	m_threadCompleted = false;
	threadStarted = false;
	//ResumeThread( thread );
	if( CXuiSceneBase::GetPlayerBasePosition(m_iPad) != CXuiSceneBase::e_BaseScene_Fullscreen && CXuiSceneBase::GetPlayerBasePosition(m_iPad) != CXuiSceneBase::e_BaseScene_NotSet)
	{
		app.AdjustSplitscreenScene(m_hObj,&m_OriginalPosition,m_iPad,false);
		CXuiSceneBase::ShowLogo( m_iPad, FALSE );
	}
	else
	{
		CXuiSceneBase::ShowLogo( m_iPad, data->completionData->bShowLogo );
	}
	CXuiSceneBase::ShowBackground( m_iPad, data->completionData->bShowBackground );
	ui.SetTooltips( m_iPad, -1, data->cancelText, -1, -1 );
	// Clear the progress text
	Minecraft *gameInstance = Minecraft::GetInstance();
	gameInstance->progressRenderer->progressStart(-1);
	gameInstance->progressRenderer->progressStage(-1);
	// set the tip
	wstring wsText = app.FormatHTMLString(m_iPad, app.GetString(app.GetNextTip()));
	wchar_t openingTags[64];
	swprintf(openingTags, 64, L"<font color=\"#%08x\" size=14><DIV ALIGN=CENTER>", app.GetHTMLColour(eHTMLColor_White));
	wsText = openingTags + wsText + L"</DIV>";
	XuiControlSetText(m_tip, wsText.c_str());
	m_tip.SetShow( m_CompletionData->bShowTips );
	return S_OK;
}
// The framework calls this handler when the object is to be destroyed. 
HRESULT CScene_FullscreenProgress::OnDestroy()
{
	if( thread != NULL && thread != INVALID_HANDLE_VALUE )
		delete thread;
	if( m_CompletionData != NULL )
		delete m_CompletionData;
	return S_OK;
}
HRESULT CScene_FullscreenProgress::OnKeyDown(XUIMessageInput* pInputData, BOOL& rfHandled)
{
	ui.AnimateKeyPress(pInputData->UserIndex, pInputData->dwKeyCode);
	switch(pInputData->dwKeyCode)
	{
	case VK_PAD_B:
	case VK_ESCAPE:		
		// 4J-JEV: Fix for Xbox360 #162749 - TU17: Save Upload: Content: UI: Player is presented with non-functional Tooltips after the Upload Save For Xbox One is completed.
		if( m_cancelFunc != NULL && !m_threadCompleted ) 
		{
			m_cancelFunc( m_cancelFuncParam );
			m_bWasCancelled = true;
		}
		break;
	}
	return S_OK;
}
