ChestModel::ChestModel()
{
	// Initialize chest components: lid, lock, and base
	ModelPart* topLid = new ModelPart(this, 0, 0);
	topLid->setTexSize(64, 64);
	lid = topLid;
	lid->addBox(0.0f, -5.0f, -14.0f, 14, 5, 14, 0.0f);
	lid->x = 1;
	lid->y = 7;
	lid->z = 15;

	ModelPart* fastener = new ModelPart(this, 0, 0);
	fastener->setTexSize(64, 64);
	lock = fastener;
	lock->addBox(-1.0f, -2.0f, -15.0f, 2, 4, 1, 0.0f);
	lock->x = 8;
	lock->y = 7;
	lock->z = 15;

	ModelPart* base = new ModelPart(this, 0, 19);
	base->setTexSize(64, 64);
	bottom = base;
	bottom->addBox(0.0f, 0.0f, 0.0f, 14, 10, 14, 0.0f);
	bottom->x = 1;
	bottom->y = 6;
	bottom->z = 1;

	// Pre-compile all parts to prevent first-render performance hitch
	lid->compile(1.0f/16.0f);
	lock->compile(1.0f/16.0f);
	bottom->compile(1.0f/16.0f);
}

void ChestModel::render(bool usecompiled)
{
	// Sync lock rotation with lid movement
	lock->xRot = lid->xRot;

	// Render components in order: lock, base, then lid with z-bias adjustment
	lock->render(1 / 16.0f, usecompiled);
	bottom->render(1 / 16.0f, usecompiled);

	// Apply z-bias to lid to avoid z-fighting with overlapping areas
	glPolygonOffset(-0.3f, -0.3f);
	lid->render(1 / 16.0f, usecompiled);
	glPolygonOffset(0.0f, 0.0f);
}

