#include "../performance_counters/event_counter.h"

int main()
{
    std::cout << "RC Lowpass test (Faust)\n";
    static constexpr float sample_rate = 48000.0;
    mydsp filter {};
    filter.init(sample_rate);
    static constexpr int buffer_size = 100'000'000;
    static constexpr int num_runs = 4;
    auto* input_buffer = (float*) malloc(buffer_size * sizeof(float));
    auto* output_buffer = (float*) malloc(buffer_size * sizeof(float));

    std::random_device random_seed{};
    std::mt19937 rng{ random_seed() };
    std::uniform_real_distribution<float> distribution{ -1.0f, 1.0f };

    event_collector collector{};
    {
        event_aggregate stats{};
        float accumulator = 0.0f;

        for (int run = 0; run < num_runs; ++run)
        {
            for (int sample_idx = 0; sample_idx < buffer_size; ++sample_idx)
                input_buffer[sample_idx] = distribution(rng);

            collector.start();
            filter.compute(buffer_size, &input_buffer, &output_buffer);
            stats << collector.end();
            accumulator += output_buffer[buffer_size - 1];
        }

        std::cout << accumulator << '\n';
        pretty_print(stats, buffer_size, "Faust");
    }

    free(input_buffer);
    free(output_buffer);
    return 0;
}

#include <bits/stdc++.h>
using namespace std;
using ll = long long;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int testCases;
    if (!(cin >> testCases)) return 0;

    while (testCases--) {
        int days, queries;
        ll penalty;
        cin >> days >> queries >> penalty;

        vector<ll> A(days + 1, 0), B(queries + 1, 0);
        for (int idx = 1; idx <= days; ++idx) cin >> A[idx];
        for (int idx = 1; idx <= queries; ++idx) cin >> B[idx];

        // Prefix sums for array A
        vector<ll> prefixA(days + 1, 0);
        for (int idx = 1; idx <= days; ++idx) 
            prefixA[idx] = prefixA[idx - 1] + A[idx];

        // Thresholds from array B (prefix sums)
        vector<ll> thresholds(queries + 1, 0);
        for (int idx = 1; idx <= queries; ++idx) 
            thresholds[idx] = thresholds[idx - 1] + B[idx];

        // Helper function: K(x) returns max k such that thresholds[k] <= x
        auto countThresholds = [&](ll value) -> int {
            if (value < 0) return 0;
            int k = upper_bound(thresholds.begin(), thresholds.end(), value) - thresholds.begin() - 1;
            if (k < 0) k = 0;
            if (k > queries) k = queries;
            return k;
        };

        // DP array: dp[i] represents optimal value up to day i
        vector<ll> dp(days + 1, LLONG_MIN / 4);
        dp[0] = 0;  // Base case: no days processed

        // Temporary array for current DP layer
        vector<ll> nextDp(days + 1, LLONG_MIN / 4);
        nextDp[0] = 0;

        // Divide and conquer DP optimization
        function<void(int, int, int, int)> divideAndConquer = [&](int left, int right, int optLeft, int optRight) {
            if (left > right) return;

            int mid = (left + right) >> 1;
            ll bestValue = LLONG_MIN / 4;
            int bestPosition = optLeft;

            int jLimit = min(mid - 1, optRight);
            for (int prev = optLeft; prev <= jLimit; ++prev) {
                ll candidate = dp[prev] + (ll)countThresholds(prefixA[mid] - prefixA[prev]) - penalty;
                if (candidate > bestValue) {
                    bestValue = candidate;
                    bestPosition = prev;
                }
            }

            nextDp[mid] = bestValue;

            // Recurse on left and right halves
            divideAndConquer(left, mid - 1, optLeft, bestPosition);
            divideAndConquer(mid + 1, right, bestPosition, optRight);
        };

        // Compute DP values for positions 1 through days
        divideAndConquer(1, days, 0, days - 1);

        cout << nextDp[days] << "\n";
    }

    return 0;
}

