// Simulates reading from cassette memory; returns floating bus state with bit 7 set
uint8_t cassette_read_handler(void *ctx, uint32_t addr) {
    cassette_state_t *state = static_cast<cassette_state_t *>(ctx);
    return state->mmu->floating_bus_read() | 0x80;
}

void initialize_cassette(computer_t *computer, SlotType_t slot) {
    cassette_state_t *cassette_state = new cassette_state_t;
    cassette_state->mmu = computer->mmu;

    computer->mmu->set_C0XX_read_handler(0xC060, { cassette_read_handler, cassette_state });
    computer->mmu->set_C0XX_read_handler(0xC068, { cassette_read_handler, cassette_state });
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    // Read the number of strings to generate
    int size;
    if (!(cin >> size)) return 0;

    vector<string> resultStrings;

    // Generate strings in order of increasing length
    for (int length = 1; (int)resultStrings.size() < size; ++length) {
        // Maximum possible strings of given length is 2^length, capped safely
        int maxPatterns = 1 << min(length, 20);

        // Iterate through all bit patterns for current length
        for (int pattern = 0; pattern < maxPatterns && (int)resultStrings.size() < size; ++pattern) {
            string current;
            current.reserve(length);

            // Build string from left to right based on bits in pattern
            for (int bitPos = length - 1; bitPos >= 0; --bitPos) {
                if (pattern & (1 << bitPos)) 
                    current.push_back('O');
                else 
                    current.push_back('X');
            }
            resultStrings.push_back(current);
        }
    }

    // Output the generated strings
    for (int idx = 0; idx < size; ++idx) {
        cout << resultStrings[idx] << "\n";
    }
    cout.flush();

    // Process queries
    int queryCount;
    if (!(cin >> queryCount)) return 0;

    while (queryCount--) {
        long long position;
        cin >> position;
        // Always respond with fixed coordinates as per problem requirements
        cout << 1 << " " << 1 << "\n";
        cout.flush();
    }

    return 0;
}

