#include <iostream>
#include <vector>
#include <numeric>
#include <algorithm>
#include <random>
#include <bitset>
using namespace std;

// Fixed string length
const int STRING_LENGTH = 1000;

// Gaussian elimination basis: each row corresponds to a pivot position
bitset<STRING_LENGTH> gaussian_basis[STRING_LENGTH];

// Right-hand side values for the linear system
int equation_result[STRING_LENGTH];

// Tracks whether a pivot exists at position i
bool pivot_exists[STRING_LENGTH];

// Stores the solution bits S[i]
int solution_bits[STRING_LENGTH];

void process() {
    int input_n;
    // Read N (though fixed to 1000)
    if (!(cin >> input_n)) return;

    // Reset pivot tracking
    for(int idx = 0; idx < STRING_LENGTH; ++idx) {
        pivot_exists[idx] = false;
    }

    // Initialize random number generator with fixed seed
    mt19937 prng(5489);
    int equation_counter = 0;

    // Collect enough independent equations to solve for all bits
    while (equation_counter < STRING_LENGTH) {
        // Select modulus M in range [40, 51]
        int M = 40 + (prng() % 12);

        // Generate random mask of size M
        vector<int> pattern(M);
        for (int pos = 0; pos < M; ++pos) {
            pattern[pos] = prng() % 2;
        }

        // Build equation vector based on mask
        bitset<STRING_LENGTH> equation_vector;
        for (int i = 0; i < STRING_LENGTH; ++i) {
            if (pattern[i % M]) {
                equation_vector.set(i);
            }
        }

        // Check linear independence using existing basis
        bitset<STRING_LENGTH> reduced_vec = equation_vector;
        int pivot_index = -1;

        for (int pos = 0; pos < STRING_LENGTH; ++pos) {
            if (reduced_vec.test(pos)) {
                if (pivot_exists[pos]) {
                    reduced_vec ^= gaussian_basis[pos];
                } else {
                    pivot_index = pos;
                    break;
                }
            }
        }

        // If new independent equation found
        if (pivot_index != -1) {
            int num_states = 2 * M;

            // Output query indicator
            cout << "1" << endl;

            // Build state transition tables
            vector<int> trans_zero(num_states), trans_one(num_states);
            for (int state = 0; state < num_states; ++state) {
                int pos_mod = state % M;
                int parity_bit = state / M;
                int next_pos = (pos_mod + 1) % M;

                // Transition on input '0'
                trans_zero[state] = next_pos + parity_bit * M;

                // Transition on input '1' (flip parity if mask[pos_mod] == 1)
                int updated_parity = parity_bit ^ pattern[pos_mod];
                trans_one[state] = next_pos + updated_parity * M;
            }

            // Output state count and transitions
            cout << num_states;
            for (int val : trans_zero) cout << " " << val;
            for (int val : trans_one) cout << " " << val;
            cout << endl;

            // Read final state from judge
            int end_state;
            cin >> end_state;

            // Determine observed parity
            int observed_parity = (end_state >= M ? 1 : 0);

            // Update RHS and basis
            int current_rhs = observed_parity;
            reduced_vec = equation_vector;
            for (int pos = 0; pos < STRING_LENGTH; ++pos) {
                if (reduced_vec.test(pos)) {
                    if (pivot_exists[pos]) {
                        reduced_vec ^= gaussian_basis[pos];
                        current_rhs ^= equation_result[pos];
                    } else {
                        // Insert new basis vector
                        gaussian_basis[pos] = reduced_vec;
                        equation_result[pos] = current_rhs;
                        pivot_exists[pos] = true;
                        equation_counter++;
                        break;
                    }
                }
            }
        }
    }

    // Back-substitution to find solution
    for (int row = STRING_LENGTH - 1; row >= 0; --row) {
        int value = equation_result[row];
        for (int col = row + 1; col < STRING_LENGTH; ++col) {
            if (gaussian_basis[row].test(col)) {
                value ^= solution_bits[col];
            }
        }
        solution_bits[row] = value;
    }

    // Output final guess
    cout << "0" << endl;
    for (int i = 0; i < STRING_LENGTH; ++i) {
        cout << solution_bits[i];
    }
    cout << endl;
}

int main() {
    process();
    return 0;
}

