namespace sdb::fuerte {

EventLoopService::EventLoopService(unsigned int num_threads, const char* thread_name)
  : _next_index(0) {
  _io_contexts.reserve(num_threads);
  _work_guards.reserve(num_threads);
  _worker_threads.reserve(num_threads);

  for (unsigned j = 0; j < num_threads; ++j) {
    _io_contexts.push_back(std::make_shared<asio_ns::io_context>(1));
    _work_guards.push_back(asio_ns::make_work_guard(*_io_contexts.back()));

    asio_ns::io_context* current_ctx = _io_contexts.back().get();

    _worker_threads.emplace_back([=]() {
#ifdef __linux__
      // Assign a descriptive name to each worker thread for debugging purposes
      if (thread_name != nullptr && *thread_name != '\0') {
        prctl(PR_SET_NAME, thread_name, 0, 0, 0);
      }
#endif
      current_ctx->run();
    });
  }
}

EventLoopService::~EventLoopService() { 
  shutdown(); 
}

// nextIOContext returns a shared pointer to the next available io_context
std::shared_ptr<asio_ns::io_context>& EventLoopService::nextIOContext() {
  SDB_ASSERT(!_io_contexts.empty());
  return _io_contexts[_next_index.fetch_add(1, std::memory_order_relaxed) %
                      _io_contexts.size()];
}

asio_ns::ssl::context& EventLoopService::sslContext() {
  std::lock_guard<std::mutex> lock(_ssl_mutex);
  if (!_ssl_context) {
#if (OPENSSL_VERSION_NUMBER >= 0x10100000L)
    _ssl_context =
      std::make_unique<asio_ns::ssl::context>(asio_ns::ssl::context::tls);
#else
    _ssl_context =
      std::make_unique<asio_ns::ssl::context>(asio_ns::ssl::context::sslv23);
#endif
    _ssl_context->set_default_verify_paths();
  }
  return *_ssl_context;
}

void EventLoopService::shutdown() {
  // Signal all work guards to release their hold on the io_contexts
  std::for_each(_work_guards.begin(), _work_guards.end(), [](auto& g) { g.reset(); });

  // Brief pause to allow ongoing operations to complete
  std::this_thread::sleep_for(std::chrono::milliseconds(50));

  // Stop all io_contexts
  std::for_each(_io_contexts.begin(), _io_contexts.end(),
                [](auto& c) { c->stop(); });

  // Another brief pause before joining threads
  std::this_thread::sleep_for(std::chrono::milliseconds(50));

  // Join all worker threads
  std::for_each(_worker_threads.begin(), _worker_threads.end(), [](auto& t) {
    if (t.joinable()) {
      t.join();
    }
  });

  // Clean up resources
  _worker_threads.clear();
  _io_contexts.clear();
  _work_guards.clear();
}

