namespace capy = boost::capy;

// A time-consuming operation that monitors for cancellation requests
capy::task<std::string> lengthy_retrieve(int iterations)
{
    auto token = co_await capy::this_coro::stop_token;  // std::stop_token
    std::string output;

    for (int j = 0; j < iterations; ++j)
    {
        // Examine whether cancellation has been requested before proceeding
        if (token.stop_requested())
        {
            std::cout << "  Stopped at iteration " << j << std::endl;
            throw std::system_error(
                make_error_code(std::errc::operation_canceled));
        }

        output += "stage" + std::to_string(j) + " ";

        // Emulate slow processing (in practice, this would involve I/O operations)
        std::this_thread::sleep_for(std::chrono::milliseconds(12));
        std::cout << "  Finished stage " << j << std::endl;

        // Yield control to let pending stop requests be handled before the next check
        // Additional delay of 18ms ensures logging finishes before main thread continues
        std::this_thread::sleep_for(std::chrono::milliseconds(18));
    }

    co_return output;
}

// Execute with a timeout mechanism (simplified - actual implementation requires timer support)
capy::task<std::optional<std::string>> retrieve_with_deadline()
{
    auto token = co_await capy::this_coro::stop_token;  // std::stop_token

    try
    {
        auto value = co_await lengthy_retrieve(5);  // std::string
        co_return value;
    }
    catch (std::system_error const& ex)
    {
        if (ex.code() == std::errc::operation_canceled)
            co_return std::nullopt;
        throw;
    }
}

void demonstration_successful_execution()
{
    std::cout << "Demonstration: Successful completion\n";

    capy::thread_pool executor;
    std::stop_source canceller;
    std::latch completed(1);  // std::latch - wait for one task to finish
    capy::run_async(executor.get_executor(), canceller.get_token(),
        [&completed](std::optional<std::string> outcome) {
            if (outcome.has_value())
                std::cout << "Output: " << *outcome << "\n";
            else
                std::cout << "Aborted\n";
            completed.count_down();
        },
        [&completed](std::exception_ptr err) { completed.count_down(); }
    )(retrieve_with_deadline());
    completed.wait();  // Suspend until the asynchronous task completes
}

void demonstration_abort_scenario()
{
    std::cout << "\nDemonstration: Abort after 2 stages\n";
    capy::thread_pool executor;
    std::stop_source canceller;
    std::latch completed(1);  // std::latch - wait for one task to finish

    // Initiate the asynchronous operation
    capy::run_async(executor.get_executor(), canceller.get_token(),
        [&completed](std::optional<std::string> outcome) {
            if (outcome.has_value())
                std::cout << "Output: " << *outcome << "\n";
            else
                std::cout << "Aborted (returned nullopt)\n";
            completed.count_down();
        },
        [&completed](std::exception_ptr err) { completed.count_down(); }
    )(retrieve_with_deadline());

    // Simulate timeout: trigger abort after two stages have completed
    // Timing: each stage takes 12ms work + 18ms yield = 30ms total
    // Stage 1 logs at 42ms, stage 2 check at 72ms
    // Cancel at 55ms: after stage 1 log, before stage 2 check
    std::this_thread::sleep_for(std::chrono::milliseconds(55));
    std::cout << "  Initiating abort..." << std::endl;
    canceller.request_stop();

    completed.wait();  // Wait until the task finishes (post-abort handling)
}

// Illustration: Explicit stop token inspection
capy::task<int> handle_elements(std::vector<int> const& data)
{
    auto token = co_await capy::this_coro::stop_token;  // std::stop_token
    int accumulator = 0;

    for (auto element : data)  // int
    {
        if (token.stop_requested())
        {
            std::cout << "Processing halted, current sum: " << accumulator << "\n";
            co_return accumulator;  // Return partial computation result
        }

        accumulator += element;
    }

    co_return accumulator;
}

int main()
{
    demonstration_successful_execution();
    demonstration_abort_scenario();

    return 0;
}

