    sol::state vm;
    vm.open_libraries(sol::lib::base);

    // Define a function that takes at least one argument,
    // followed by variadic arguments, and then another required argument
    vm.set_function(
        "process",
        [](int first, sol::variadic_args args, int last) {
            int accumulator = 0;
            for (const auto& item : args) {
                int num = item; // implicit conversion to int
                accumulator += num;
            }
            // Include 'first' and 'last' in the result
            return accumulator + first + last;
        });

    // Execute Lua scripts to test the function
    vm.script("result1 = process(10, 20)");
    vm.script("result2 = process(5, 10, 15, 20, 25)");
    vm.script("result3 = process(1, 2, 3, 4, 5, 6, 7)");

    // Verify results with assertions
    vm.script("assert(result1 == 30)");
    vm.script("assert(result2 == 100)");
    vm.script("assert(result3 == 28)");

    // Print computed values
    vm.script("print(result1)");  // 30
    vm.script("print(result2)"); // 100
    vm.script("print(result3)"); // 28

    std::cout << std::endl;
