  /**
   * \brief Confirm correct rank assignment per device via ncclCommSplit.
   * ******************************************************************************************/
  TEST(Standalone, SplitComms_RankCheck)
  {
    // Verify multi-GPU setup
    int totalDevices;
    HIPCALL(hipGetDeviceCount(&totalDevices));
    if (totalDevices < 2) {
      GTEST_SKIP() << "This test needs at least two GPUs.";
    }

    std::vector<ncclComm_t> originalComms(totalDevices);
    NCCLCHECK(ncclCommInitAll(originalComms.data(), totalDevices, nullptr));

    std::vector<ncclComm_t> partitionedComms(totalDevices);
    int numPartitions = 2;
    std::map<int, int> partitionCounter;

    NCCLCHECK(ncclGroupStart());
    for (int localIdx = 0; localIdx < totalDevices; ++localIdx) {
      NCCLCHECK(ncclCommSplit(originalComms[localIdx], localIdx % numPartitions, localIdx, &partitionedComms[localIdx], NULL));
      partitionCounter[localIdx % numPartitions]++;
    }
    NCCLCHECK(ncclGroupEnd());

    for (int idx = 0; idx < totalDevices; ++idx) {
      int subRank, subSize;
      NCCLCHECK(ncclCommUserRank(partitionedComms[idx], &subRank));
      NCCLCHECK(ncclCommCount(partitionedComms[idx], &subSize));
      ASSERT_EQ(subRank, idx / numPartitions);
      ASSERT_EQ(subSize, partitionCounter[idx % numPartitions]);
    }

    for (auto& pcomm : partitionedComms)
      NCCLCHECK(ncclCommDestroy(pcomm));
    for (auto& ocomm : originalComms)
      NCCLCHECK(ncclCommDestroy(ocomm));
  }

