  /**
   * \brief Reduce number of ranks by half using ncclCommSplit.
   * ******************************************************************************************/
  TEST(Standalone, SplitComms_Reduce)
  {
    int totalDevices;
    HIPCALL(hipGetDeviceCount(&totalDevices));
    if (totalDevices < 2) {
      GTEST_SKIP() << "This test requires at least two devices.";
    }

    std::vector<ncclComm_t> originalComms(totalDevices);
    NCCLCHECK(ncclCommInitAll(originalComms.data(), totalDevices, nullptr));

    int targetRanks = totalDevices / 2;
    std::vector<ncclComm_t> partitionedComms(totalDevices);
    NCCLCHECK(ncclGroupStart());
    for (int localIdx = 0; localIdx < totalDevices; ++localIdx)
      NCCLCHECK(ncclCommSplit(originalComms[localIdx],
            localIdx < targetRanks ? 0 : NCCL_SPLIT_NOCOLOR,
            localIdx, &partitionedComms[localIdx], NULL));
    NCCLCHECK(ncclGroupEnd());

    for (int idx = 0; idx < totalDevices; ++idx) {
      int origRank, origSize;
      NCCLCHECK(ncclCommUserRank(originalComms[idx], &origRank));
      NCCLCHECK(ncclCommCount(originalComms[idx], &origSize));
      if (idx < targetRanks) {
        int partRank, partSize;
        NCCLCHECK(ncclCommUserRank(partitionedComms[idx], &partRank));
        NCCLCHECK(ncclCommCount(partitionedComms[idx], &partSize));
        ASSERT_EQ(origRank, partRank);
        ASSERT_EQ(partSize, targetRanks);
      } else {
        ASSERT_EQ(partitionedComms[idx], nullptr);
      }
    }

    for (auto& pcomm : partitionedComms)
      NCCLCHECK(ncclCommDestroy(pcomm));
    for (auto& ocomm : originalComms)
      NCCLCHECK(ncclCommDestroy(ocomm));
  }

  /**
   * \brief Ensure no performance regression across protocols: LL, LL128, Simple.
   * ******************************************************************************************/
  TEST(Standalone, RegressionTiming)
  {
    using namespace std::chrono;
    using ClockType = high_resolution_clock;
    int microsecondsTotal, iterations = 20, warmups = 5;

    int gpuCount;
    HIPCALL(hipGetDeviceCount(&gpuCount));
    if (gpuCount < 2) {
      GTEST_SKIP() << "This test requires at least two GPUs.";
    }

    hipDeviceProp_t deviceProps;
    HIPCALL(hipGetDeviceProperties(&deviceProps, 0));

    constexpr int numRanks = 2;
    std::vector<ncclComm_t> comms(numRanks);
    std::vector<int*> devInput(numRanks);
    std::vector<int*> devOutput(numRanks);
    std::vector<hipStream_t> streams(numRanks);

    char* savedProto = getenv("NCCL_PROTO");
    const char* protoList[3] = {"LL", "LL128", "Simple"};

    for (const auto& protoName : protoList)
    {
      microsecondsTotal = 0;
      if(strncmp("gfx12", deviceProps.gcnArchName, 5) == 0) {
        setenv("NCCL_PROTO", "Simple", 1);
      } else {
        setenv("NCCL_PROTO", protoName, 1);
      }

      NCCLCHECK(ncclCommInitAll(comms.data(), numRanks, nullptr));

      int elementCount = 1250;
      std::vector<int> hostInput(elementCount);
      std::vector<int> hostExpected(elementCount);
      for (int i = 0; i < elementCount; ++i) {
        hostInput[i]    = i;
        hostExpected[i] = 2 * i;
      }

      for (int rank = 0; rank < numRanks; ++rank) {
        HIPCALL(hipSetDevice(rank));
        HIPCALL(hipStreamCreate(&streams[rank]));
        HIPCALL(hipMalloc((void**)&devInput[rank], elementCount * sizeof(int)));
        HIPCALL(hipMalloc((void**)&devOutput[rank], elementCount * sizeof(int)));
        HIPCALL(hipMemcpy(devInput[rank], hostInput.data(), elementCount * sizeof(int), hipMemcpyHostToDevice));
        HIPCALL(hipMemset(devOutput[rank], 0, elementCount * sizeof(int)));
        HIPCALL(hipDeviceSynchronize());
      }

      for (int iter = -warmups; iter < iterations; ++iter) {
        for (int rank = 0; rank < numRanks; ++rank) {
          HIPCALL(hipSetDevice(rank));
          HIPCALL(hipMemset(devOutput[rank], 0, elementCount * sizeof(int)));
          HIPCALL(hipDeviceSynchronize());
        }

        NCCLCHECK(ncclGroupStart());
        for (int rank = 0; rank < numRanks; ++rank)
          NCCLCHECK(ncclAllReduce(devInput[rank], devOutput[rank], elementCount, ncclInt, ncclSum, comms[rank], streams[rank]));
        ncclResult_t res = ncclGroupEnd();
        if (res != ncclSuccess) continue;

        const auto startTime = ClockType::now();
        for (int rank = 0; rank < numRanks; ++rank) {
          HIPCALL(hipStreamSynchronize(streams[rank]));
        }

        if (iter >= 0)
          microsecondsTotal += duration_cast<microseconds>(ClockType::now() - startTime).count();

        std::vector<int> hostOutput(elementCount);
        for (int rank = 0; rank < numRanks; ++rank) {
          HIPCALL(hipMemcpy(hostOutput.data(), devOutput[rank], elementCount * sizeof(int), hipMemcpyDeviceToHost));
          HIPCALL(hipDeviceSynchronize());
          for (int i = 0; i < elementCount; ++i)
            ASSERT_EQ(hostOutput[i], hostExpected[i]);
        }
      }

      EXPECT_LT(microsecondsTotal/(double)iterations, 5000);
      printf("[ INFO     ] protocol: %s, avg runtime: %f microseconds\n", protoName, microsecondsTotal/(double)iterations);

      for (int rank = 0; rank < numRanks; ++rank){
        HIPCALL(hipFree(devInput[rank]));
        HIPCALL(hipFree(devOutput[rank]));
        HIPCALL(hipStreamDestroy(streams[rank]));
        NCCLCHECK(ncclCommDestroy(comms[rank]));
      }
    }

    if (savedProto)
      setenv("NCCL_PROTO", savedProto, 1);
    else
      unsetenv("NCCL_PROTO");
  }

  /**
   * \brief Validate kernel stack size for each architecture does not exceed MAX_STACK_SIZE.
   * ******************************************************************************************/
  TEST(Standalone, StackSize) {
    const char* mainKernelName = "ncclDevKernel";
    std::vector<std::string> coFiles = splitString(executeCommand("find ../ -type f -name \"librccl*.co\""), '\n');

    if (coFiles.empty())
      GTEST_SKIP() << "Skipping... Required .co files not found in build directory.";

    for (const auto& filePath : coFiles) {
      std::string cmd = std::string(ROCM_PATH) + "/llvm/bin/llvm-readelf --notes " + filePath;
      std::vector<std::string> notesLines = splitString(executeCommand(cmd.c_str()), '\n');

      if (notesLines.empty())
        GTEST_SKIP() << "Skipping... llvm tools not available.";

      ArchInfo archData = parseMetadata(notesLines);

      for (const auto& kernel : archData.kernels) {
        if (kernel.name.find(mainKernelName) != std::string::npos) {
          int stackSize = kernel.privateSegmentFixedSize;
          int maxAllowed = archData.archName == "gfx90a" ? MAX_STACK_SIZE_gfx90a : MAX_STACK_SIZE;
          printf("[ INFO     ] Arch: %s Kernel: %s Size: %d\n", archData.archName.c_str(), kernel.name.c_str(), stackSize);
          EXPECT_LE(stackSize, maxAllowed);
        }
      }
    }
  }

  /**
   * \brief Check that communicators are correctly bound to their assigned devices.
   * ******************************************************************************************/
  TEST(Standalone, CommCuDevice_Check)
  {
    int deviceCount;
    HIPCALL(hipGetDeviceCount(&deviceCount));
    if (deviceCount < 1) {
      GTEST_SKIP() << "No GPU devices detected.";
    }

    ncclComm_t singleComm;
    ncclUniqueId uniqueId;
    NCCLCHECK(ncclGetUniqueId(&uniqueId));
    HIPCALL(hipSetDevice(0));
    NCCLCHECK(ncclCommInitRank(&singleComm, 1, uniqueId, 0));

    int assignedDevice;
    NCCLCHECK(ncclCommCuDevice(singleComm, &assignedDevice));
    ASSERT_EQ(assignedDevice, 0);
    NCCLCHECK(ncclCommDestroy(singleComm));

    if (deviceCount > 1) {
      std::vector<ncclComm_t> multiComms(deviceCount);
      NCCLCHECK(ncclCommInitAll(multiComms.data(), deviceCount, nullptr));

      for (int idx = 0; idx < deviceCount; ++idx) {
        int deviceForRank;
        NCCLCHECK(ncclCommCuDevice(multiComms[idx], &deviceForRank));
        ASSERT_EQ(deviceForRank, idx);
      }

      for (int idx = 0; idx < deviceCount; ++idx) {
        NCCLCHECK(ncclCommDestroy(multiComms[idx]));
      }
    }
  }

  /**
   * \brief Confirm failure when calling ncclCommUserRank with null communicator.
   * ******************************************************************************************/
  TEST(Standalone, SplitComms_RankCheck_Basic_Failure) {
    int deviceCount;
    HIPCALL(hipGetDeviceCount(&deviceCount));
    if (deviceCount < 2) {
      GTEST_SKIP() << "This test requires at least two devices.";
    }

    std::vector<ncclComm_t> comms(deviceCount);
    NCCLCHECK(ncclCommInitAll(comms.data(), deviceCount, nullptr));

    ncclComm_t nullHandle = nullptr;
    int dummyRank;
    NCCLCHECK(ncclCommUserRank(nullHandle, &dummyRank));

    for (auto& comm : comms)
      NCCLCHECK(ncclCommDestroy(comm));
  }
}

