#define WRITE_SCALAR(traits, ...)                                              \
{                                                                              \
    vector<traits::value_type> buffer;                                         \
    buffer += __VA_ARGS__;                                                     \
    DataType type = traits::dataType();                                        \
    string label = #traits;                                                    \
    MetaData info;                                                             \
    info.set("interpretation", traits::interpretation());                      \
    WriteScalarProp<traits::value_type>(prop,                                  \
                                        label,                                 \
                                        type,                                  \
                                        info,                                  \
                                        buffer);                               \
}

#define WRITE_SMALL_ARRAY(traits, ...)                                         \
{                                                                              \
    vector<traits::value_type> buffer;                                         \
    buffer += __VA_ARGS__;                                                     \
    DataType type = traits::dataType();                                        \
    type.setExtent(buffer.size());                                             \
    string label = #traits;                                                    \
    MetaData info;                                                             \
    WriteSmallArrayProp<traits::value_type>(prop,                              \
                                            label,                             \
                                            type,                              \
                                            info,                              \
                                            buffer);                           \
}

#define WRITE_LARGE_ARRAY(traits, ...)                                         \
{                                                                              \
    vector<traits::value_type> buffer;                                         \
    buffer += __VA_ARGS__;                                                     \
    DataType type = traits::dataType();                                        \
    string label = #traits;                                                    \
    MetaData info;                                                             \
    info.set("interpretation", traits::interpretation());                      \
    WriteArrayProp<traits>(prop,                                               \
                           label,                                              \
                           type,                                               \
                           info,                                               \
                           buffer);                                            \
}

namespace {

template<typename T>
void
WriteScalarProp(OCompoundProperty &compound,
                const string &name,
                const DataType &type,
                const MetaData &info,
                const vector<T> &values)
{
    OScalarProperty writer(compound, name, type, info);
    for (index_t idx = 0; idx < values.size(); ++idx) {
        const T& val = values[idx];
        writer.set(static_cast<const void*>(&val));
    }
}

template<typename T>
void
WriteSmallArrayProp(OCompoundProperty &compound,
                    const string &name,
                    const DataType &type,
                    const MetaData &info,
                    const vector<T> &values)
{
    OScalarProperty writer(compound, name, type, info);
    writer.set(&values.front());
}

template<typename T>
void
WriteArrayProp(OCompoundProperty &compound,
               const string &name,
               const DataType &type,
               const MetaData &info,
               const vector<typename T::value_type> &values)
{
    OArrayProperty writer(compound, name, type, info);
    TypedArraySample<T> sample(values);
    writer.set(sample);
}

