using namespace llvm;

PreservedAnalyses EmbedBitcodePass::run(Module &module, ModuleAnalysisManager &analysisManager) {
  if (module.getGlobalVariable("llvm.embedded.module", /*AllowInternal=*/true))
    report_fatal_error("Can only embed the module once",
                       /*gen_crash_diag=*/false);

  Triple targetTriple(module.getTargetTriple());
  if (targetTriple.getObjectFormat() != Triple::ELF)
    report_fatal_error(
        "EmbedBitcode pass currently only supports ELF object format",
        /*gen_crash_diag=*/false);

  std::string bufferData;
  raw_string_ostream outputStream(bufferData);

  if (IsThinLTO)
    ThinLTOBitcodeWriterPass(outputStream, /*ThinLinkOS=*/nullptr).run(module, analysisManager);
  else
    BitcodeWriterPass(outputStream, /*ShouldPreserveUseListOrder=*/false, EmitLTOSummary)
        .run(module, analysisManager);

  embedBufferInModule(module, MemoryBufferRef(bufferData, "ModuleData"), ".llvm.lto");
  return PreservedAnalyses::all();
}

