// Perform the forward pass for Mamba's output projection layer
void CompiledExecutor::dispatch_mamba_out_proj(const CompiledOp& operation, const modules::ForwardHook* callback) {
    // This operation corresponds to a matrix multiplication: out = gated_out @ out_proj_weight.T
    // Input tensor: gated_out with shape [B*T, intermediate_size]
    // Weight tensor: out_proj_weight with shape [d_model, intermediate_size]
    // Result tensor: out with shape [B*T, d_model]
    // Since this behaves like a regular matmul, we reuse the existing dispatcher
    dispatch_matmul(operation, callback);
}

// Perform the backward pass for Mamba's output projection layer
void CompiledExecutor::dispatch_mamba_out_proj_backward(const CompiledOp& operation, const modules::BackwardHook* callback) {
    // The backward computation follows standard matmul gradient rules
    // Reuse the generic matmul backward implementation
    dispatch_matmul_backward(operation, callback);
}

