static void remap_ioctl_buffer(const struct ioctl_compat_map *entry, char *src_old, char *src_new, int mode)
{
	int new_pos = 0;
	int old_pos = 0;
	int src_size = entry->old_size;

	if (!(mode & entry->direction)) return;

	if (!entry->old_size) {
		/* offsets hard-coded for SNDRV_PCM_IOCTL_SYNC_PTR;
		 * if another exception appears this needs changing. */
		remap_ioctl_buffer(entry+1, src_old, src_new, mode);
		remap_ioctl_buffer(entry+2, src_old+4, src_new+8, mode);

		int adjustment = BYTE_ORDER==BIG_ENDIAN ? 4 : 0;
		remap_ioctl_buffer(entry+3, src_old+68, src_new+72+adjustment, mode);
		remap_ioctl_buffer(entry+3, src_old+72, src_new+76+3*adjustment, mode);
		return;
	}

	for (int idx=0; idx < entry->num_offsets; idx++) {
		int timestamp_offset = entry->offset_list[idx];
		int segment_len = timestamp_offset - old_pos;
		if (mode==W) memcpy(src_old+old_pos, src_new+new_pos, segment_len);
		else memcpy(src_new+new_pos, src_old+old_pos, segment_len);

		new_pos += segment_len;
		old_pos += segment_len;

		long long new_ts_val;
		long old_ts_val;
		int alignment = entry->force_alignment ? sizeof(long long) : alignof(time_t);
		new_pos += (alignment-1) & -new_pos;

		if (mode==W) {
			memcpy(&new_ts_val, src_new+new_pos, sizeof new_ts_val);
			old_ts_val = (long)new_ts_val;
			memcpy(src_old+old_pos, &old_ts_val, sizeof old_ts_val);
		} else {
			memcpy(&old_ts_val, src_old+old_pos, sizeof old_ts_val);
			new_ts_val = (long long)old_ts_val;
			memcpy(src_new+new_pos, &new_ts_val, sizeof new_ts_val);
		}

		new_pos += sizeof new_ts_val;
		old_pos += sizeof old_ts_val;
	}

	if (mode==W) memcpy(src_old+old_pos, src_new+new_pos, src_size-old_pos);
	else memcpy(src_new+new_pos, src_old+old_pos, src_size-old_pos);
}

int ioctl(int fd, int request, ...)
{
	void *argument;
	va_list args;
	va_start(args, request);
	argument = va_arg(args, void *);
	va_end(args);

	int result = __syscall(SYS_ioctl, fd, request, argument);

	if (SIOCGSTAMP != SIOCGSTAMP_OLD && request && result==-ENOTTY) {
		for (int idx=0; idx < (int)(sizeof compat_table / sizeof *compat_table); idx++) {
			if (compat_table[idx].new_req != request) continue;

			union {
				long long align_dummy;
				char buffer[256];
			} temp_buf;

			remap_ioctl_buffer(&compat_table[idx], temp_buf.buffer, argument, W);
			result = __syscall(SYS_ioctl, fd, compat_table[idx].old_req, temp_buf.buffer);
			if (result < 0) break;

			remap_ioctl_buffer(&compat_table[idx], temp_buf.buffer, argument, R);
			break;
		}
	}

	return __syscall_ret(result);
}

