/*
 * Curl_sync_getaddrinfo() when compiled with IPv6 support (synchronous,
 * non-threaded and non-ares variant).
 *
 * Acquires name details for the specified hostname and port. On success,
 * 'addrinfo' is returned and the fourth parameter will reference memory
 * that must be released post-use. This memory *MUST* be deallocated using
 * Curl_freeaddrinfo(), not any other function.
 */
struct Curl_addrinfo *Curl_sync_getaddrinfo(struct Curl_easy *handle,
                                            const char *domain_name,
                                            int service_port,
                                            int address_family)
{
  struct addrinfo preferences;
  struct Curl_addrinfo *result;
  int status;
  char port_string[12];
  char *port_pointer = NULL;
#ifndef USE_RESOLVE_ON_IPS
  char ip_storage[128];
#endif
  int protocol_family = PF_INET;

  if((address_family != CURL_IPRESOLVE_V4) && Curl_ipv6works(handle))
    /* The network stack appears to support IPv6 */
    protocol_family = PF_UNSPEC;

  memset(&preferences, 0, sizeof(preferences));
  preferences.ai_family = protocol_family;
  preferences.ai_socktype = (handle->conn->transport == TRNSPRT_TCP) ?
    SOCK_STREAM : SOCK_DGRAM;

#ifndef USE_RESOLVE_ON_IPS
  /*
   * AI_NUMERICHOST must not be set to enable synthesized IPv6 addresses
   * from IPv4 addresses on iOS and macOS.
   */
  if((1 == curlx_inet_pton(AF_INET, domain_name, ip_storage)) ||
     (1 == curlx_inet_pton(AF_INET6, domain_name, ip_storage))) {
    /* the provided address is numeric-only, avoid reverse lookup */
    preferences.ai_flags = AI_NUMERICHOST;
  }
#endif

  if(service_port) {
    msnprintf(port_string, sizeof(port_string), "%d", service_port);
    port_pointer = port_string;
  }

  status = Curl_getaddrinfo_ex(domain_name, port_pointer, &preferences, &result);
  if(status) {
    infof(handle, "getaddrinfo(3) failed for %s:%d", domain_name, service_port);
    return NULL;
  }

  if(service_port) {
    Curl_addrinfo_set_port(result, service_port);
  }

  print_address_info(result);
  return result;
}
#endif /* CURLRES_SYNCH */
#endif /* CURLRES_IPV6 */

