#include <iostream>
#include <vector>
#include <queue>
#include <algorithm>
#include <string>
using namespace std;

// Global variables for current test case
int node_count;
vector<vector<int>> adjacency_list;
vector<int> node_depths;

// Perform a query with given nodes and return result
pair<int, int> execute_query(const vector<int>& selected_nodes) {
    if (selected_nodes.empty()) return {-1, -1};

    cout << "? " << selected_nodes.size();
    for (int node : selected_nodes) {
        cout << " " << node;
    }
    cout << endl;

    int response_node, distance;
    cin >> response_node >> distance;

    if (response_node == -1 && distance == -1) {
        exit(0); // Terminate on error or query limit exceeded
    }
    return {response_node, distance};
}

// Breadth-first search to compute distances from start node
void compute_distances(int start, vector<int>& distances) {
    fill(distances.begin(), distances.end(), -1);
    distances[start] = 0;
    queue<int> traversal_queue;
    traversal_queue.push(start);

    while (!traversal_queue.empty()) {
        int current = traversal_queue.front();
        traversal_queue.pop();

        for (int neighbor : adjacency_list[current]) {
            if (distances[neighbor] == -1) {
                distances[neighbor] = distances[current] + 1;
                traversal_queue.push(neighbor);
            }
        }
    }
}

void process_test_case() {
    cin >> node_count;
    adjacency_list.assign(node_count + 1, vector<int>());

    for (int edge_index = 0; edge_index < node_count - 1; ++edge_index) {
        int u, v;
        cin >> u >> v;
        adjacency_list[u].push_back(v);
        adjacency_list[v].push_back(u);
    }

    // Phase 1: Query all nodes to get path information
    vector<int> all_nodes(node_count);
    for (int i = 0; i < node_count; ++i) {
        all_nodes[i] = i + 1;
    }

    pair<int, int> path_info = execute_query(all_nodes);
    int intermediate_node = path_info.first;
    int total_distance = path_info.second;

    // Phase 2: Compute depths using BFS from arbitrary root (node 1)
    node_depths.assign(node_count + 1, 0);
    compute_distances(1, node_depths);

    int maximum_depth = 0;
    for (int i = 1; i <= node_count; ++i) {
        maximum_depth = max(maximum_depth, node_depths[i]);
    }

    // Phase 3: Binary search to find deepest node on the hidden path
    int lower_bound = node_depths[intermediate_node];
    int upper_bound = maximum_depth;
    int endpoint_candidate = intermediate_node;

    while (lower_bound < upper_bound) {
        int mid_depth = (lower_bound + upper_bound + 1) / 2;
        vector<int> deep_nodes;

        for (int i = 1; i <= node_count; ++i) {
            if (node_depths[i] >= mid_depth) {
                deep_nodes.push_back(i);
            }
        }

        if (deep_nodes.empty()) {
            upper_bound = mid_depth - 1;
            continue;
        }

        pair<int, int> query_result = execute_query(deep_nodes);
        if (query_result.second == total_distance) {
            endpoint_candidate = query_result.first;
            lower_bound = mid_depth;
        } else {
            upper_bound = mid_depth - 1;
        }
    }

    // Phase 4: Find the second endpoint using distance L from first endpoint
    vector<int> distances_from_endpoint(node_count + 1);
    compute_distances(endpoint_candidate, distances_from_endpoint);

    vector<int> potential_second_endpoints;
    for (int i = 1; i <= node_count; ++i) {
        if (distances_from_endpoint[i] == total_distance) {
            potential_second_endpoints.push_back(i);
        }
    }

    int second_endpoint;
    if (potential_second_endpoints.size() == 1) {
        second_endpoint = potential_second_endpoints[0];
    } else {
        pair<int, int> final_query = execute_query(potential_second_endpoints);
        second_endpoint = final_query.first;
    }

    cout << "! " << endpoint_candidate << " " << second_endpoint << endl;

    string feedback;
    cin >> feedback;
    if (feedback != "Correct") {
        exit(0);
    }
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int test_cases;
    if (cin >> test_cases) {
        while (test_cases--) {
            process_test_case();
        }
    }

    return 0;
}

