        "adc    x14, x14, xzr          \n\t"
        "str    x10, [%[p], #32]        \n\t"   // prod[4]
        // ---- Column 5: prod[5] ----
        // x[2]*y[3] + x[3]*y[2] + carry
        "mul    x8,  %[x2], %[y3]       \n\t"
        "umulh  x10, %[x2], %[y3]       \n\t"
        "mul    x11, %[x3], %[y2]       \n\t"
        "umulh  x12, %[x3], %[y2]       \n\t"
        "adds   x9,  x9,  x8           \n\t"
        "adcs   x10, x10, x14          \n\t"
        "adc    x14, xzr, xzr          \n\t"
        "adds   x9,  x9,  x11          \n\t"
        "adcs   x10, x10, x12          \n\t"
        "adc    x14, x14, xzr          \n\t"
        "str    x9,  [%[p], #40]        \n\t"   // prod[5]
        // ---- Column 6: prod[6] ----
        // x[3]*y[3] + carry
        "mul    x8,  %[x3], %[y3]       \n\t"
        "umulh  x9,  %[x3], %[y3]       \n\t"
        "adds   x10, x10, x8           \n\t"
        "adcs   x9,  x9,  x14          \n\t"
        "str    x10, [%[p], #48]        \n\t"   // prod[6]
        "str    x9,  [%[p], #56]        \n\t"   // prod[7]
