        "umulh  x9,  %[p4], %[c]        \n\t"
        "adds   %[r0], %[r0], x8        \n\t"
        "adcs   %[r1], %[r1], x9        \n\t"
        "adcs   %[r2], %[r2], xzr       \n\t"
        "adcs   %[r3], %[r3], xzr       \n\t"
        "adc    x14, xzr, xzr           \n\t"
        // Reduce prod[5]: res += prod[5] * C << 64
        "mul    x8,  %[p5], %[c]        \n\t"
        "umulh  x9,  %[p5], %[c]        \n\t"
        "adds   %[r1], %[r1], x8        \n\t"
        "adcs   %[r2], %[r2], x9        \n\t"
        "adcs   %[r3], %[r3], xzr       \n\t"
        "adc    x14, x14, xzr           \n\t"
        // Reduce prod[6]: res += prod[6] * C << 128
        "mul    x8,  %[p6], %[c]        \n\t"
        "umulh  x9,  %[p6], %[c]        \n\t"
        "adds   %[r2], %[r2], x8        \n\t"
        "adcs   %[r3], %[r3], x9        \n\t"
        "adc    x14, x14, xzr           \n\t"
        // Reduce prod[7]: res += prod[7] * C << 192
        "mul    x8,  %[p7], %[c]        \n\t"
        "umulh  x9,  %[p7], %[c]        \n\t"
        "adds   %[r3], %[r3], x8        \n\t"
        "adc    x14, x14, x9            \n\t"
