        "umulh  x9,  x14, %[c]          \n\t"
        "adds   %[r0], %[r0], x8        \n\t"
        "adcs   %[r1], %[r1], x9        \n\t"
        "adcs   %[r2], %[r2], xzr       \n\t"
        "adcs   %[r3], %[r3], xzr       \n\t"
        "adc    x14, xzr, xzr           \n\t"
        // Third-round (extremely rare, but mathematically possible)
        "mul    x8,  x14, %[c]          \n\t"
        "adds   %[r0], %[r0], x8        \n\t"
        "adcs   %[r1], %[r1], xzr       \n\t"
        "adcs   %[r2], %[r2], xzr       \n\t"
        "adc    %[r3], %[r3], xzr       \n\t"
        : [r0] "+r"(res0), [r1] "+r"(res1), [r2] "+r"(res2), [r3] "+r"(res3)
        : [p4] "r"(prod[4]), [p5] "r"(prod[5]), [p6] "r"(prod[6]), [p7] "r"(prod[7]),
          [c] "r"(C)
        : "x8", "x9", "x14", "cc"
