        "subs   %[t0], %[r0], %[m0]         \n\t"
        "sbcs   %[t1], %[r1], %[m1]         \n\t"
        "sbcs   %[t2], %[r2], %[m1]         \n\t"
        "sbcs   %[t3], %[r3], %[m1]         \n\t"
