        // CSEL is 1 instruction per limb vs BIC+AND+ORR (3 per limb)
        // cc = carry clear = borrow occurred
        "csel   %[t0], %[r0], %[t0], cc     \n\t"
        "csel   %[t1], %[r1], %[t1], cc     \n\t"
        "csel   %[t2], %[r2], %[t2], cc     \n\t"
        "csel   %[t3], %[r3], %[t3], cc     \n\t"
        : [t0] "=&r"(tmp0), [t1] "=&r"(tmp1), [t2] "=&r"(tmp2), [t3] "=&r"(tmp3)
        : [r0] "r"(res0), [r1] "r"(res1), [r2] "r"(res2), [r3] "r"(res3),
          [m0] "r"(MOD0), [m1] "r"(MOD1)
        : "cc"
    );

    result[0] = tmp0;
    result[1] = tmp1;
    result[2] = tmp2;
    result[3] = tmp3;
