    __asm__ __volatile__(
        // Compute cross products (i<j), each appears 2x
        // We compute them once and will double later

        // x[0]*x[1]
        "mul    x8,  %[x0], %[x1]       \n\t"
        "umulh  x9,  %[x0], %[x1]       \n\t"

        // x[0]*x[2]
        "mul    x10, %[x0], %[x2]       \n\t"
        "umulh  x11, %[x0], %[x2]       \n\t"

        // x[0]*x[3]
        "mul    x12, %[x0], %[x3]       \n\t"
        "umulh  x13, %[x0], %[x3]       \n\t"

        // x[1]*x[2]
        "mul    x14, %[x1], %[x2]       \n\t"
        "umulh  x15, %[x1], %[x2]       \n\t"

        // x[1]*x[3]
        "mul    x16, %[x1], %[x3]       \n\t"
        "umulh  x17, %[x1], %[x3]       \n\t"

        // x[2]*x[3]
        "mul    x19, %[x2], %[x3]       \n\t"
        "umulh  x20, %[x2], %[x3]       \n\t"

        // Accumulate cross products into columns
        // col1 = x01_lo
        // col2 = x01_hi + x02_lo
        // col3 = x02_hi + x03_lo + x12_lo
        // col4 = x03_hi + x12_hi + x13_lo
        // col5 = x13_hi + x23_lo
        // col6 = x23_hi

        // col2 += x02_lo
        "adds   x9,  x9,  x10          \n\t"   // col2
        "adcs   x11, x11, x12          \n\t"   // col3 partial
        "adcs   x13, x13, xzr          \n\t"   // col4 partial
        "adc    x21, xzr, xzr          \n\t"   // overflow

        // col3 += x12_lo
        "adds   x11, x11, x14          \n\t"
        "adcs   x13, x13, x15          \n\t"
        "adc    x21, x21, xzr          \n\t"

        // col4 += x13_lo
        "adds   x13, x13, x16          \n\t"
        "adcs   x17, x17, x21          \n\t"   // col5 partial
        "adc    x21, xzr, xzr          \n\t"

        // col5 += x23_lo
        "adds   x17, x17, x19          \n\t"
        "adc    x20, x20, x21          \n\t"   // col6

