        "mul    x10, %[x1], %[x1]       \n\t"
        "umulh  x12, %[x1], %[x1]       \n\t"
        "adcs   x9,  x9,  x10          \n\t"   // prod[2] += lo(x1^2)
        "adcs   x11, x11, x12          \n\t"   // prod[3] += hi(x1^2)
        "str    x9,  [%[p], #16]        \n\t"   // prod[2]
        "str    x11, [%[p], #24]        \n\t"   // prod[3]

        // x[2]*x[2]
        "mul    x10, %[x2], %[x2]       \n\t"
        "umulh  x12, %[x2], %[x2]       \n\t"
        "adcs   x13, x13, x10          \n\t"   // prod[4] += lo(x2^2)
        "adcs   x17, x17, x12          \n\t"   // prod[5] += hi(x2^2)
        "str    x13, [%[p], #32]        \n\t"   // prod[4]
        "str    x17, [%[p], #40]        \n\t"   // prod[5]

        // x[3]*x[3]
        "mul    x10, %[x3], %[x3]       \n\t"
        "umulh  x12, %[x3], %[x3]       \n\t"
        "adcs   x20, x20, x10          \n\t"   // prod[6] += lo(x3^2)
        "adc    x21, x21, x12          \n\t"   // prod[7] += hi(x3^2)
        "str    x20, [%[p], #48]        \n\t"   // prod[6]
        "str    x21, [%[p], #56]        \n\t"   // prod[7]

        : /* outputs via memory */
        : [x0] "r"(x[0]), [x1] "r"(x[1]), [x2] "r"(x[2]), [x3] "r"(x[3]),
          [p] "r"(prod)
        : "x8", "x9", "x10", "x11", "x12", "x13", "x14", "x15",
