        "umulh  x9,  %[p4], %[c]        \n\t"
        "adds   %[r0], %[r0], x8        \n\t"
        "adcs   %[r1], %[r1], x9        \n\t"
        "adcs   %[r2], %[r2], xzr       \n\t"
        "adcs   %[r3], %[r3], xzr       \n\t"
        "adc    x14, xzr, xzr           \n\t"
        "mul    x8,  %[p5], %[c]        \n\t"
        "umulh  x9,  %[p5], %[c]        \n\t"
        "adds   %[r1], %[r1], x8        \n\t"
        "adcs   %[r2], %[r2], x9        \n\t"
        "adcs   %[r3], %[r3], xzr       \n\t"
        "adc    x14, x14, xzr           \n\t"
        "mul    x8,  %[p6], %[c]        \n\t"
        "umulh  x9,  %[p6], %[c]        \n\t"
        "adds   %[r2], %[r2], x8        \n\t"
        "adcs   %[r3], %[r3], x9        \n\t"
        "adc    x14, x14, xzr           \n\t"
        "mul    x8,  %[p7], %[c]        \n\t"
        "umulh  x9,  %[p7], %[c]        \n\t"
        "adds   %[r3], %[r3], x8        \n\t"
        "adc    x14, x14, x9            \n\t"
        "mul    x8,  x14, %[c]          \n\t"
        "umulh  x9,  x14, %[c]          \n\t"
        "adds   %[r0], %[r0], x8        \n\t"
        "adcs   %[r1], %[r1], x9        \n\t"
        "adcs   %[r2], %[r2], xzr       \n\t"
        "adcs   %[r3], %[r3], xzr       \n\t"
        "adc    x14, xzr, xzr           \n\t"
        "mul    x8,  x14, %[c]          \n\t"
        "adds   %[r0], %[r0], x8        \n\t"
        "adcs   %[r1], %[r1], xzr       \n\t"
        "adcs   %[r2], %[r2], xzr       \n\t"
        "adc    %[r3], %[r3], xzr       \n\t"
        : [r0] "+r"(res0), [r1] "+r"(res1), [r2] "+r"(res2), [r3] "+r"(res3)
        : [p4] "r"(prod[4]), [p5] "r"(prod[5]), [p6] "r"(prod[6]), [p7] "r"(prod[7]),
          [c] "r"(C)
        : "x8", "x9", "x14", "cc"
    );

    // Branchless normalization
    constexpr uint64_t MOD0 = 0xFFFFFFFEFFFFFC2FULL;
    constexpr uint64_t MOD1 = 0xFFFFFFFFFFFFFFFFULL;
    uint64_t tmp0, tmp1, tmp2, tmp3;
    __asm__ __volatile__(
        "subs   %[t0], %[r0], %[m0]         \n\t"
        "sbcs   %[t1], %[r1], %[m1]         \n\t"
        "sbcs   %[t2], %[r2], %[m1]         \n\t"
        "sbcs   %[t3], %[r3], %[m1]         \n\t"
