#include <iostream>
#include <vector>
using namespace std;

// Finds duplicate number using Floyd's cycle detection algorithm (tortoise and hare)
class Solution {
public:
    int findDuplicate(vector<int>& numbers) {
        int slowPointer = 0;
        int fastPointer = 0;
        int size = numbers.size();

        // Phase 1: Detect if there's a cycle in the sequence
        do {
            slowPointer = numbers[slowPointer];
            fastPointer = numbers[numbers[fastPointer]];
        } while (slowPointer != fastPointer);

        // Phase 2: Find the start of the cycle (the duplicate number)
        slowPointer = 0;
        while (slowPointer != fastPointer) {
            slowPointer = numbers[slowPointer];
            fastPointer = numbers[fastPointer];
        }

        return slowPointer; // or fastPointer - both are equal here
    }
};

int main() {
    Solution solver;
    vector<int> input = {1, 3, 4, 2, 2};
    int duplicateValue = solver.findDuplicate(input);
    cout << "Duplicate: " << duplicateValue << endl;
    return 0;
}

