// Convert duration to seconds as a floating-point value
double convertToSeconds(const sen::Duration& timeSpan)
{
  static auto secUnit = sen::UnitRegistry::get().searchUnitByAbbreviation("s").value();
  const auto& sourceUnit = sen::QuantityTraits<sen::Duration>::unit();
  return sen::Unit::convert(sourceUnit, *secUnit, static_cast<double>(timeSpan.get()));
}

