        const auto& report = reader.getSummary();
        std::cout << "  location:        " << arguments->archiveLocation.string() << "\n";
        std::cout << "  length:          " << convertToSeconds(report.lastTime - report.firstTime) << "s\n";
        std::cout << "  begin:           " << report.firstTime.toLocalString() << "\n";
        std::cout << "  finish:          " << report.lastTime.toLocalString() << "\n";
