void configureIndexedCommand(CLI::App& cliApp)
{
  struct CommandArgs
  {
    std::filesystem::path archiveLocation;
  };
  auto arguments = std::make_shared<CommandArgs>();
  auto indexedCmd = cliApp.add_subcommand("indexed", "lists indexed objects with metadata");
  indexedCmd->add_option("archive_path", arguments->archiveLocation, "Path to the archive")->required()->check(CLI::ExistingDirectory);
  indexedCmd->callback(
    [arguments]()
    {
      try
      {
        sen::CustomTypeRegistry nativeTypes;
        sen::db::Input reader(arguments->archiveLocation, nativeTypes);
        const std::string col0Header = "ENTITY NAME";
        const std::string col1Header = "TYPE NAME";
        const std::string col2Header = "CHANNEL";

        std::size_t maxNameWidth = col0Header.size();
        std::size_t maxTypeWidth = col1Header.size();
        for (const auto& entry : reader.getObjectIndexDefinitions())
        {
          maxNameWidth = std::max(maxNameWidth, entry.name.size());
          maxTypeWidth = std::max(maxTypeWidth, entry.type->getQualifiedName().size());
        }

        printf("%s%*s    %s%*s    %s\n",
               col0Header.c_str(),
               static_cast<int>(maxNameWidth - col0Header.size()),
               "",
               col1Header.c_str(),
               static_cast<int>(maxTypeWidth - col1Header.size()),
               "",
               col2Header.c_str());

        for (const auto& entry : reader.getObjectIndexDefinitions())
        {
          const auto& qualifiedName = entry.type->getQualifiedName();
          printf("%s%*s    %s%*s    %s.%s\n",
                 entry.name.c_str(),
                 static_cast<int>(maxNameWidth - entry.name.size()),
                 "",
                 qualifiedName.data(),
                 static_cast<int>(maxTypeWidth - qualifiedName.size()),
                 "",
                 entry.session.c_str(),
                 entry.bus.c_str());
        }
      }
      catch (const std::exception& ex)
      {
        std::cerr << ex.what() << "\n";
        std::exit(1);
      }
    });
}

int executeApplication(int argumentCount, char* arguments[])
{
  CLI::App program {"Data archive inspection tool\n"};
  program.name("sen inspect");
  program.get_formatter()->column_width(14);  // NOLINT
  configureInfoCommand(program);
  configureIndexedCommand(program);
  program.footer("For more information on a command, run 'sen inspect <command> --help'");
  CLI11_PARSE(program, argumentCount, arguments);
  return 0;
}

int main(int argumentCount, char* arguments[])
{
  sen::registerTerminateHandler();
  try
  {
    return executeApplication(argumentCount, arguments);
  }
  catch (const std::exception& ex)
  {
    fprintf(stderr, "Fatal error: %s\n", ex.what());  // NOLINT
    return 1;
  }
  catch (...)
  {
    std::fputs("Unrecognized error occurred\n", stderr);
    return 1;
  }
}

