//-----------------------------------------------------------------
/// @details
///		Initialize the task operation
//-----------------------------------------------------------------
Error Task::beginTask() noexcept {
    // Retrieve configuration context
    json::Value &settings = taskConfig();
    if (auto errCode = settings.lookupAssign("wantsContext", m_wantsContext))
        return errCode;
    // Obtain a null source endpoint (no .serviceConfig provided)
    if (!(m_sourceEndpoint = IServiceEndpoint::getSourceEndpoint(
              {.jobConfig = jobConfig(),
               .taskConfig = settings,
               .openMode = OPEN_MODE::INDEX})))
        return m_sourceEndpoint.ccode();
    // Obtain a null target endpoint (no .serviceConfig provided)
    if (!(m_targetEndpoint = IServiceEndpoint::getTargetEndpoint(
              {.jobConfig = jobConfig(),
               .taskConfig = settings,
               .openMode = OPEN_MODE::CLASSIFY})))
        return m_targetEndpoint.ccode();
    // Execute base class initialization
    return Parent::beginTask();
}
//-----------------------------------------------------------------
///	@details
///		Invokes default line handling to generate an entry
///		and enqueue it for processing
/// @param[in] inputLine
///		The incoming data line - JSON formatted
/// @param[in] ancestor
///		The current parent node in the hierarchy
//-----------------------------------------------------------------
ErrorOr<Entry> Task::processLine(TextView inputLine, const Url &ancestor) noexcept {
    // Handle lines matching C*{...} pattern
    return Parent::processLine("C"_tv, inputLine, ancestor);
}
//-----------------------------------------------------------------
/// @details
///		Handle a single entry object
/// @param[in] item
///		The entry to be processed
//-----------------------------------------------------------------
Error Task::processItem(Entry &item) noexcept {
    // Acquire and release the source communication pipe
    ErrorOr<ServicePipe> sourceChannel;
    util::Guard channelCleanup{[&] { sourceChannel = m_sourceEndpoint->getPipe(); },
                               [&] {
                                   if (sourceChannel)
                                       m_sourceEndpoint->putPipe(*sourceChannel);
                               }};
    // The application provides classificationId field to indicate classification status
    // If classification is required and not yet done:
    //		return classifications[] information
    // If classification is not desired:
    //		return empty classifications[]
    // Secure a source communication pipe
    if (!sourceChannel) return sourceChannel.ccode();
    // Determine if this entry requires classification
    if (item.flags() & Entry::FLAGS::CLASSIFY) {
        // Perform classification if context needed or never classified before
        if (m_wantsContext || !item.classificationId()) {
            // Execute classification logic
            if (auto errCode = Parent::processItem(item, *sourceChannel))
                return errCode;
            // Mark entry as modified
            item.changed(true);
        }
    } else {
        // Classification not requested but currently present
        if (item.classificationId()) {
            // Flag entry as having been altered
            item.changed(true);
        }
    }
    // Clear classification identifier since it's not needed downstream
    item.classificationId.reset();
    // Check processing outcome
    if (item.objectFailed()) {
        // Record failure statistics
        MONITOR(addFailed, 1, item.size());
        // Always log error details
        if (auto errCode = Parent::writeError(item, item.completionCode()))
            return errCode;
    } else {
        // Record success statistics
        MONITOR(addCompleted, 1, item.size());
        // If changes occurred, output the result
        if (item.changed()) {
            // Write successful classification result
            if (auto errCode = Parent::writeResult('C', item)) return errCode;
        }
    }
    // Task completion
    return {};
}
