class Solution {
public:
    // Find minimum score triangulation of convex polygon
    int minScoreTriangulation(std::vector<int>& values) {
        int len = values.size();
        int memo[50][50] = {};

        // Build up solutions for polygons of increasing size
        for (int length = 2; length < len; length++) {
            for (int left = 0; left + length < len; left++) {
                int right = left + length;
                memo[left][right] = INT_MAX;

                // Try all possible triangulation points
                for (int mid = left + 1; mid < right; mid++) {
                    memo[left][right] = std::min(
                        memo[left][right], 
                        values[left] * values[right] * values[mid] + 
                        memo[left][mid] + 
                        memo[mid][right]
                    );
                }
            }
        }

        return memo[0][len - 1];
    }
};

