/* Autocorrelation-based LPC coefficient computation 
   Based on Levinson (1947) and Durbin (1959) algorithms */
/* Input : n samples of time-domain signal
   Output: m prediction coefficients, residual energy */
float vorbis_lpc_from_data(float *input, float *coeff_out, int sample_count, int order){
  double *autocorr = alloca(sizeof(*autocorr) * (order + 1));
  double *lpc_coeffs = alloca(sizeof(*lpc_coeffs) * order);
  double residual_error;
  int lag_index, coeff_idx;

  /* Compute autocorrelation sequence with p+1 lags */
  for (lag_index = 0; lag_index <= order; ++lag_index) {
    double sum = 0.0; /* Use double precision for accumulation */
    for (int sample = lag_index; sample < sample_count; ++sample) {
      sum += (double)input[sample] * input[sample - lag_index];
    }
    autocorr[lag_index] = sum;
  }

  /* Derive LPC coefficients from autocorrelation values */
  residual_error = autocorr[0];

  for (coeff_idx = 0; coeff_idx < order; ++coeff_idx) {
    double reflection = -autocorr[coeff_idx + 1];
    if (residual_error == 0) {
      memset(coeff_out, 0, order * sizeof(*coeff_out));
      return 0.0f;
    }

    /* Calculate reflection coefficient using current LPC coefficients */
    for (int j = 0; j < coeff_idx; ++j) {
      reflection -= lpc_coeffs[j] * autocorr[coeff_idx - j];
    }
    reflection /= residual_error;

    /* Update LPC coefficients and error estimate */
    lpc_coeffs[coeff_idx] = reflection;

    for (int j = 0; j < coeff_idx / 2; ++j) {
      double temp = lpc_coeffs[j];
      lpc_coeffs[j] += reflection * lpc_coeffs[coeff_idx - 1 - j];
      lpc_coeffs[coeff_idx - 1 - j] += reflection * temp;
    }

    if (coeff_idx % 2 != 0) {
      lpc_coeffs[coeff_idx / 2] += lpc_coeffs[coeff_idx / 2] * reflection;
    }

    residual_error *= (1.0 - reflection * reflection);
  }

  for (int j = 0; j < order; ++j) {
    coeff_out[j] = (float)lpc_coeffs[j];
  }

  /* Return residual energy for use in filter excitation */
  return (float)residual_error;
}

void vorbis_lpc_predict(float *predictor, float *init_vals, int order,
                       float *output, long num_samples){
  /* in: predictor[0...order-1] LPC analysis coefficients 
         init_vals[0...order-1] boundary conditions (buffer size n+order-1)
    out: output[0...num_samples-1] synthesized samples */
  long sample_idx, coeff_idx, out_pos, pred_pos;
  float prediction;
  float *buffer = alloca(sizeof(*buffer) * (order + num_samples));

  if (!init_vals) {
    for (int i = 0; i < order; ++i) {
      buffer[i] = 0.0f;
    }
  } else {
    for (int i = 0; i < order; ++i) {
      buffer[i] = init_vals[i];
    }
  }

  for (sample_idx = 0; sample_idx < num_samples; ++sample_idx) {
    prediction = 0.0f;
    out_pos = sample_idx;
    pred_pos = order;

    for (coeff_idx = 0; coeff_idx < order; ++coeff_idx) {
      prediction -= buffer[out_pos++] * predictor[--pred_pos];
    }

    output[sample_idx] = buffer[out_pos] = prediction;
  }
}

