class Solution {
public:
    // Convert a positive integer to its corresponding Excel column title
    std::string convertToTitle(int number) {
        std::string result = "";
        int remainder;

        // Process each digit from right to left (base-26 conversion)
        while (number > 0) {
            remainder = (number - 1) % 26;  // Calculate current character index (0-25)
            number = (number - 1) / 26;     // Move to next higher digit
            result += static_cast<char>(remainder + 'A');
        }

        // Reverse since we built the string from least significant to most significant
        std::reverse(result.begin(), result.end());
        return result;
    }
};

#include "IRrecv.h"
