/// @file
/// @brief Aiwa-based remote control protocol implementation.
/// Derived from the RC-T501 remote control unit specifications.
/// Implementation inspired by IRremoteESP8266 project.
/// @see https://github.com/z3t0/Arduino-IRremote
// Supports:
//   Brand: Aiwa,  Model: RC-T501 RCU
const uint16_t kAiwaRcT501PrefixBits = 26;
const uint16_t kAiwaRcT501SuffixBits = 1;

// Note: These values are the logical inverse (bitwise complement) of lirc's
//       representation since lirc uses '0' for mark and '1' for space.
const uint64_t kAiwaRcT501PrefixValue = 0x1D8113FULL;  // 26-bit prefix
const uint64_t kAiwaRcT501SuffixValue = 1ULL;

#if SEND_AIWA_RC_T501
/// Transmit an Aiwa RC T501 formatted infrared message.
/// Status: BETA / Likely functional.
/// @param[in] payload The data payload to be transmitted.
/// @param[in] bitCount Number of bits in the payload to send.
///   Typically kAiwaRcT501Bits. Maximum is 37 (i.e., 64 - 27).
/// @param[in] repeatCount How many times the command should be repeated.
/// @see http://lirc.sourceforge.net/remotes/aiwa/RC-T501
void IRsend::sendAiwaRCT501(uint64_t payload, uint16_t bitCount, uint16_t repeatCount) {
  // This protocol resembles an extended NEC1 format: 42 bits vs standard 32 bits.
  // We utilize sendNEC internally but prepend a fixed 26-bit header and append
  // a fixed trailing bit.

  uint64_t combinedData = ((kAiwaRcT501PrefixValue << (bitCount + kAiwaRcT501SuffixBits)) |
                           (payload << kAiwaRcT501SuffixBits) | kAiwaRcT501SuffixValue);

  bitCount += kAiwaRcT501PrefixBits + kAiwaRcT501SuffixBits;

  if (bitCount > sizeof(combinedData) * 8)
    return;  // Prevent overflow — abort transmission if data too large.

  sendNEC(combinedData, bitCount, repeatCount);
}
#endif

#if DECODE_AIWA_RC_T501
/// Decode received Aiwa RC T501 infrared messages.
/// Status: BETA / Expected to work reliably.
/// @param[in,out] results Pointer to buffer where decoded data will be stored.
/// @param[in] startIndex Starting position within raw data array for decoding.
///   Defaults to kStartOffset.
/// @param[in] expectedBitCount Expected number of data bits (typically 15).
/// @param[in] enforceStrict Whether to enforce strict protocol compliance.
/// @return True if successful decoding occurs; false otherwise.
/// @note
///  Aiwa RC T501 behaves like a 42-bit variant of NEC1 protocol.
///  Historically (from original Arduino IRremote), it's treated as a 15-bit
///  data protocol. Thus, we anticipate nbits=15 and strip prefix/suffix bits
///  from the captured signal to extract meaningful content.
/// @see http://www.sbprojects.net/knowledge/ir/nec.php
/// @see https://github.com/crankyoldgit/IRremoteESP8266/issues/1069
bool IRrecv::decodeAiwaRCT501(decode_results *results, uint16_t startIndex,
                              const uint16_t expectedBitCount, const bool enforceStrict) {
  // Protocol validation
  if (enforceStrict && expectedBitCount != kAiwaRcT501Bits)
    return false;  // Does not conform to known protocol definition.

  // Account for prefix and suffix when calculating total expected bits.
  uint16_t totalExpectedBits = expectedBitCount + kAiwaRcT501PrefixBits + kAiwaRcT501SuffixBits;
  uint64_t extractedData;

  if (totalExpectedBits > sizeof(extractedData) * 8)
    return false;  // Impossible size — reject early.

  // Perform initial decode using NEC logic with relaxed constraints.
  if (!decodeNEC(results, startIndex, totalExpectedBits, false))
    return false;  // Decoding failure implies this isn't a valid Aiwa RC T501 signal.

  uint16_t actualBits = results->bits;
  extractedData = results->value;

  if (actualBits < totalExpectedBits)
    return false;  // Signal was truncated or incomplete.

  // Verify suffix bit matches expected value.
  if ((extractedData & 0x1ULL) != kAiwaRcT501SuffixValue)
    return false;

  // Remove suffix bit from extracted data.
  extractedData >>= kAiwaRcT501SuffixBits;
  actualBits -= kAiwaRcT501SuffixBits;

  // Extract main payload and store back into results structure.
  actualBits -= kAiwaRcT501PrefixBits;
  results->value = extractedData & ((1ULL << actualBits) - 1);

  // Validate prefix portion.
  extractedData >>= actualBits;
  if (extractedData != kAiwaRcT501PrefixValue)
    return false;

  // Final compliance checks
  if (enforceStrict && results->bits != totalExpectedBits)
    return false;

  // Mark success and populate metadata.
  results->decode_type = AIWA_RC_T501;
  results->bits = actualBits;
  results->address = 0;
  results->command = 0;
  return true;
}
#endif

