namespace infiniop_test::sub {

struct Test::Attributes {
    std::shared_ptr<Tensor> input1;
    std::shared_ptr<Tensor> input2;
    std::shared_ptr<Tensor> output;
    std::shared_ptr<Tensor> expected;
};

std::shared_ptr<Test> Test::build(
    std::unordered_map<std::string, std::vector<uint8_t>> attrs,
    std::unordered_map<std::string, std::shared_ptr<Tensor>> tensors,
    double rel_tol, double abs_tol) {
    auto test = std::shared_ptr<Test>(new Test(rel_tol, abs_tol));
    test->_attributes = new Attributes();

    if (tensors.find("input1") == tensors.end()
        || tensors.find("input2") == tensors.end()
        || tensors.find("output") == tensors.end()
        || tensors.find("expected") == tensors.end()) {
        throw std::runtime_error("Invalid Test configuration");
    }

    test->_attributes->input1 = tensors["input1"];
    test->_attributes->input2 = tensors["input2"];
    test->_attributes->output = tensors["output"];
    test->_attributes->expected = tensors["expected"];

    return test;
}

std::shared_ptr<infiniop_test::Result> Test::run(
    infiniopHandle_t handle, infiniDevice_t device, int dev_id, size_t pre_runs, size_t rep_count) {
    infiniopSubDescriptor_t op_desc;
    auto x = _attributes->input1->to(device, dev_id);
    auto y = _attributes->input2->to(device, dev_id);
    auto z = _attributes->output->to(device, dev_id);

    CHECK_OR(infiniopCreateSubDescriptor(handle, &op_desc,
                                         z->desc(),
                                         x->desc(),
                                         y->desc()),
             return TEST_FAILED(OP_CREATION_FAILED, "Failed to create operator descriptor."));

    size_t scratch_size;
    CHECK_OR(infiniopGetSubWorkspaceSize(op_desc, &scratch_size),
             return TEST_FAILED(OP_CREATION_FAILED, "Failed to query workspace size."));

    void *scratch;
    CHECK_OR(infinirtMalloc(&scratch, scratch_size),
             return TEST_FAILED(OP_CREATION_FAILED, "Failed to allocate scratch memory."));

    CHECK_OR(infiniopSub(op_desc, scratch, scratch_size,
                         z->data(),
                         x->data(),
                         y->data(),
                         nullptr),
             return TEST_FAILED(OP_EXECUTION_FAILED, "Operator execution failed."));

    try {
        allClose(z, _attributes->expected, _rtol, _atol);
    } catch (const std::exception &err) {
        return TEST_FAILED(RESULT_INCORRECT, err.what());
    }

    double duration = 0.0;
    duration = benchmark(
        [=]() {
            infiniopSub(
                op_desc, scratch, scratch_size,
                z->data(),
                x->data(),
                y->data(),
                nullptr);
        },
        pre_runs, rep_count);

    return TEST_PASSED(duration);
}

std::vector<std::string> Test::attribute_names() {
    return {};
}

std::vector<std::string> Test::tensor_names() {
    return {"input1", "input2", "output", "expected"};
}

std::vector<std::string> Test::output_names() {
    return {"output"};
}

std::string Test::toString() const {
    std::ostringstream stream;
    stream << op_name() << std::endl;
    stream << "- input1: " << _attributes->input1->info() << std::endl;
    stream << "- input2: " << _attributes->input2->info() << std::endl;
    stream << "- output: " << _attributes->output->info() << std::endl;
    stream << std::scientific << std::setprecision(2);
    stream << "- rtol=" << _rtol << ", atol=" << _atol << std::endl;
    return stream.str();
}

Test::~Test() {
    delete _attributes;
}

