#include "llama.h"
#include <cstdio>
#include <cstring>
#include <iostream>
#include <string>
#include <vector>

static void show_help(int, char ** argv) {
    printf("\nusage example:\n");
    printf("\n    %s --model model.gguf [--ctx context_size] [--ngl n_gpu_layers]\n", argv[0]);
    printf("\n");
}

int main(int argc, char ** argv) {
    std::string model_file;
    int ngpu = 99;
    int ctx_size = 2048;

    // parse command line arguments
    for (int idx = 1; idx < argc; idx++) {
        try {
            if (strcmp(argv[idx], "-m") == 0 || strcmp(argv[idx], "--model") == 0) {
                if (idx + 1 < argc) {
                    model_file = argv[++idx];
                } else {
                    show_help(argc, argv);
                    return 1;
                }
            } else if (strcmp(argv[idx], "-c") == 0 || strcmp(argv[idx], "--ctx") == 0) {
                if (idx + 1 < argc) {
                    ctx_size = std::stoi(argv[++idx]);
                } else {
                    show_help(argc, argv);
                    return 1;
                }
            } else if (strcmp(argv[idx], "-ngl") == 0 || strcmp(argv[idx], "--ngl") == 0) {
                if (idx + 1 < argc) {
                    ngpu = std::stoi(argv[++idx]);
                } else {
                    show_help(argc, argv);
                    return 1;
                }
            } else {
                show_help(argc, argv);
                return 1;
            }
        } catch (std::exception & e) {
            fprintf(stderr, "error: %s\n", e.what());
            show_help(argc, argv);
            return 1;
        }
    }

    if (model_file.empty()) {
        show_help(argc, argv);
        return 1;
    }

    // suppress non-error logs
    llama_log_set([](enum ggml_log_level level, const char * text, void * /* user_data */) {
        if (level >= GGML_LOG_LEVEL_ERROR) {
            fprintf(stderr, "%s", text);
        }
    }, nullptr);

    // load all available backends
    ggml_backend_load_all();

    // configure model loading
    llama_model_params model_opts = llama_model_default_params();
    model_opts.n_gpu_layers = ngpu;
    llama_model * model = llama_model_load_from_file(model_file.c_str(), model_opts);
    if (!model) {
        fprintf(stderr , "%s: error: unable to load the model\n" , __func__);
        return 1;
    }

    const llama_vocab * vocab = llama_model_get_vocab(model);

    // configure context
    llama_context_params ctx_opts = llama_context_default_params();
    ctx_opts.n_ctx = ctx_size;
    ctx_opts.n_batch = ctx_size;
    llama_context * ctx = llama_init_from_model(model, ctx_opts);
    if (!ctx) {
        fprintf(stderr , "%s: error: failed to initialize the context\n" , __func__);
        return 1;
    }

    // setup sampler chain
    llama_sampler * smpl = llama_sampler_chain_init(llama_sampler_chain_default_params());
    llama_sampler_chain_add(smpl, llama_sampler_init_min_p(0.05f, 1));
    llama_sampler_chain_add(smpl, llama_sampler_init_temp(0.8f));
    llama_sampler_chain_add(smpl, llama_sampler_init_dist(LLAMA_DEFAULT_SEED));

    // function to generate output given a prompt
    auto produce_response = [&](const std::string & input_prompt) {
        std::string result_text;
        const bool is_first_turn = llama_memory_seq_pos_max(llama_get_memory(ctx), 0) == -1;

        // tokenize input
        const int prompt_token_count = -llama_tokenize(vocab, input_prompt.c_str(), input_prompt.size(), NULL, 0, is_first_turn, true);
        std::vector<llama_token> tokenized_input(prompt_token_count);
        if (llama_tokenize(vocab, input_prompt.c_str(), input_prompt.size(), tokenized_input.data(), tokenized_input.size(), is_first_turn, true) < 0) {
            GGML_ABORT("failed to tokenize the input prompt\n");
        }

        // prepare batch
        llama_batch batch = llama_batch_get_one(tokenized_input.data(), tokenized_input.size());
        llama_token next_token;

        while (true) {
            // verify context capacity
            int max_context = llama_n_ctx(ctx);
            int used_context = llama_memory_seq_pos_max(llama_get_memory(ctx), 0) + 1;
            if (used_context + batch.n_tokens > max_context) {
                printf("\033[0m\n");
                fprintf(stderr, "context size exceeded\n");
                exit(0);
            }

            int decode_result = llama_decode(ctx, batch);
            if (decode_result != 0) {
                GGML_ABORT("decoding failed, code = %d\n", decode_result);
            }

            // pick next token
            next_token = llama_sampler_sample(smpl, ctx, -1);

            // stop if end-of-generation token
            if (llama_vocab_is_eog(vocab, next_token)) {
                break;
            }

            // convert and print token
            char piece_buffer[256];
            int bytes_written = llama_token_to_piece(vocab, next_token, piece_buffer, sizeof(piece_buffer), 0, true);
            if (bytes_written < 0) {
                GGML_ABORT("cannot convert token to string\n");
            }

            std::string token_str(piece_buffer, bytes_written);
            printf("%s", token_str.c_str());
            fflush(stdout);
            result_text += token_str;

            // prepare next step
            batch = llama_batch_get_one(&next_token, 1);
        }

        return result_text;
    };

    std::vector<llama_chat_message> chat_history;
    std::vector<char> buffer(llama_n_ctx(ctx));
    int last_position = 0;

    while (true) {
        // prompt for user input
        printf("\033[32m> \033[0m");
        std::string user_input;
        std::getline(std::cin, user_input);
        if (user_input.empty()) {
            break;
        }

        const char * chat_template = llama_model_chat_template(model, /* name */ nullptr);

        // append new message
        chat_history.push_back({"user", strdup(user_input.c_str())});
        int updated_len = llama_chat_apply_template(chat_template, chat_history.data(), chat_history.size(), true, buffer.data(), buffer.size());
        if (updated_len > (int)buffer.size()) {
            buffer.resize(updated_len);
            updated_len = llama_chat_apply_template(chat_template, chat_history.data(), chat_history.size(), true, buffer.data(), buffer.size());
        }
        if (updated_len < 0) {
            fprintf(stderr, "error applying chat template\n");
            return 1;
        }

        // extract only the new part as prompt
        std::string prompt(buffer.begin() + last_position, buffer.begin() + updated_len);

        // generate reply
        printf("\033[33m");
        std::string assistant_reply = produce_response(prompt);
        printf("\n\033[0m");

        // store assistant's response
        chat_history.push_back({"assistant", strdup(assistant_reply.c_str())});
        last_position = llama_chat_apply_template(chat_template, chat_history.data(), chat_history.size(), false, nullptr, 0);
        if (last_position < 0) {
            fprintf(stderr, "error applying chat template\n");
            return 1;
        }
    }

    // cleanup
    for (auto & msg : chat_history) {
        free(const_cast<char *>(msg.content));
    }
    llama_sampler_free(smpl);
    llama_free(ctx);
    llama_model_free(model);
    return 0;
}

#include <nanobind/nanobind.h>
