namespace nb = nanobind;
using namespace mscclpp;

void bind_executor_module(nb::module_& module) {
  // Define enumeration for data types
  nb::enum_<DataType>(module, "DataType")
      .value("int32", DataType::INT32)
      .value("uint32", DataType::UINT32)
      .value("float16", DataType::FLOAT16)
      .value("float32", DataType::FLOAT32)
      .value("bfloat16", DataType::BFLOAT16);

  // Define enumeration for packet types
  nb::enum_<PacketType>(module, "PacketType")
      .value("LL8", PacketType::LL8)
      .value("LL16", PacketType::LL16);

  // Bind ExecutionPlan class
  nb::class_<ExecutionPlan>(module, "ExecutionPlan")
      .def(nb::init<const std::string>(), nb::arg("planPath"))
      .def("name", &ExecutionPlan::name)
      .def("collective", &ExecutionPlan::collective)
      .def("min_message_size", &ExecutionPlan::minMessageSize)
      .def("max_message_size", &ExecutionPlan::maxMessageSize);

  // Bind Executor class with custom lambda for execute method
  nb::class_<Executor>(module, "Executor")
      .def(nb::init<std::shared_ptr<Communicator>>(), nb::arg("comm"))
      .def(
          "execute",
          [](Executor* instance, int localRank, uintptr_t inputBuffer, uintptr_t outputBuffer,
             size_t inputSize, size_t outputSize, DataType type, const ExecutionPlan& plan,
             uintptr_t cudaStream, PacketType pktType) {
            instance->execute(localRank, reinterpret_cast<void*>(inputBuffer),
                              reinterpret_cast<void*>(outputBuffer), inputSize, outputSize,
                              type, plan, (cudaStream_t)cudaStream, pktType);
          },
          nb::arg("rank"), nb::arg("sendbuff"), nb::arg("recvBuff"), nb::arg("sendBuffSize"),
          nb::arg("recvBuffSize"), nb::arg("dataType"), nb::arg("plan"), nb::arg("stream"),
          nb::arg("packetType") = PacketType::LL16);
}

#include <hip/hip_runtime.h>

// GPU kernel to print a greeting message with block and thread indices
__global__ void gpuGreetingKernel() {
  printf("Greetings from GPU! Block %d Thread %d\n", blockIdx.x, threadIdx.x);
}

// Function to launch the GPU kernel with specified grid and block dimensions
void executeGpuKernel(dim3 gridSize, dim3 blockSize) {
  hipLaunchKernelGGL(gpuGreetingKernel, gridSize, blockSize, 0, 0);
}

#include <iostream>
#include <string>
#include <cmath>

// Type II clone: variable names changed, literals adjusted, statement order slightly modified
int main() {
    std::string config_file = "input_04.xml";
    Teuchos::RCP<Teuchos::ParameterList> params
      = Teuchos::rcp( new Teuchos::ParameterList() );
    Teuchos::updateParametersFromXmlFile( config_file, params.ptr() );

    /*** Initialize mesh / degree-of-freedom manager. ***/
    MeshManager_Rectangle<RealT, DeviceT> meshmanager(*params);
    scalar_view node_coords = meshmanager.getNodes();
    int_view elementToNodeMap = meshmanager.getCellToNodeMap();

    *outStream << "Total nodes = " << meshmanager.getNumNodes() << std::endl;
    *outStream << "Total elements = " << meshmanager.getNumCells() << std::endl;
    *outStream << "Total edges = " << meshmanager.getNumEdges() << std::endl;

    ROL::Ptr<MeshManager<RealT, DeviceT>> meshmanagerPtr = ROL::makePtrFromRef(meshmanager);

    // Basis setup.
    basis_ptr shape_basis = ROL::makePtr<Intrepid2::Basis_HGRAD_QUAD_C2_FEM<DeviceT, RealT, RealT>>();

    // Cubature setup.
    ROL::Ptr<Intrepid2::Cubature<DeviceT, RealT, RealT>> quadrature;
    shards::CellTopology cellShape = shape_basis->getBaseCellTopology();                // extract topology from basis
    Intrepid2::DefaultCubatureFactory quadFactory;                                      // instantiate cubature factory
    int quadOrder = 4;                                                                  // set integration order, e.g., 4
    quadrature = quadFactory.create<DeviceT, RealT, RealT>(cellShape, quadOrder);       // generate default cubature

    // Element node coordinates.
    scalar_view elemCoords("elemCoords", meshmanager.getNumCells(), cellShape.getNodeCount(), cellShape.getDimension());
    for (int idx=0; idx<meshmanager.getNumCells(); ++idx) {
      for (unsigned nodeIdx=0; nodeIdx<cellShape.getNodeCount(); ++nodeIdx) {
        for (unsigned dimIdx=0; dimIdx<cellShape.getDimension(); ++dimIdx) {
          elemCoords(idx,nodeIdx,dimIdx) = node_coords(elementToNodeMap(idx,nodeIdx), dimIdx);
        }
      }
    }

    // FE object construction.
    FE<RealT, DeviceT> finiteElem(elemCoords, shape_basis, quadrature);

    // Integration checks.
    scalar_view val1("val1", meshmanager.getNumCells(), quadrature->getNumPoints());
    scalar_view val2("val2", meshmanager.getNumCells(), quadrature->getNumPoints());
    scalar_view grad1("grad1", meshmanager.getNumCells(), quadrature->getNumPoints(), quadrature->getDimension());
    scalar_view grad2("grad2", meshmanager.getNumCells(), quadrature->getNumPoints(), quadrature->getDimension());
    scalar_view coeffs1("coeffs1", meshmanager.getNumCells(), shape_basis->getCardinality());
    scalar_view coeffs2("coeffs2", meshmanager.getNumCells(), shape_basis->getCardinality());
    scalar_view integrals("integrals", meshmanager.getNumCells());

    // Constant value fields.
    Kokkos::deep_copy(coeffs1, static_cast<RealT>(3));
    Kokkos::deep_copy(coeffs2, static_cast<RealT>(5));
    finiteElem.evaluateValue(val1, coeffs1);
    finiteElem.evaluateValue(val2, coeffs2);
    finiteElem.computeIntegral(integrals, val1, val2);

    RealT valueResult(0);
    for (int idx=0; idx<meshmanager.getNumCells(); ++idx) {
      valueResult += integrals(idx);
    }

    if (std::abs(valueResult - static_cast<RealT>(3000)) > std::sqrt(ROL::ROL_EPSILON<RealT>())) {
      errorFlag = -1;
    }

    // Gradient fields.
    scalar_view dofPositions("dofPositions", meshmanager.getNumCells(), shape_basis->getCardinality(), quadrature->getDimension());
    finiteElem.computeDofCoords(dofPositions, elemCoords);

    for (int idx=0; idx<meshmanager.getNumCells(); ++idx) {
      for (int nodeIdx=0; nodeIdx<shape_basis->getCardinality(); ++nodeIdx) {
        RealT x = dofPositions(idx,nodeIdx,0);
        RealT y = dofPositions(idx,nodeIdx,1);
        coeffs1(idx,nodeIdx) = static_cast<RealT>(2)*x + static_cast<RealT>(3)*y;
        coeffs2(idx,nodeIdx) = static_cast<RealT>(4)*x + static_cast<RealT>(5)*y;
      }
    }

    finiteElem.evaluateGradient(grad1, coeffs1);
    finiteElem.evaluateGradient(grad2, coeffs2);
    finiteElem.computeIntegral(integrals, grad1, grad2);

    RealT gradientResult(0);
    for (int idx=0; idx<meshmanager.getNumCells(); ++idx) {
      gradientResult += integrals(idx);
    }

    if (std::abs(gradientResult - static_cast<RealT>(7500)) > std::sqrt(ROL::ROL_EPSILON<RealT>())) {
      errorFlag = -1;
    }

    *outStream << std::setprecision(14) << "\nvalueIntegral=" << valueResult << "  " << "gradientIntegral=" << gradientResult << std::endl;
  }
  catch (std::logic_error& err) {
    *outStream << err.what() << "\n";
    errorFlag = -1000;
  }; // end try
  if (errorFlag != 0)
    std::cout << "Final Status: TEST FAILED\n";
  else
    std::cout << "Final Status: TEST PASSED\n";
  return 0;
}

#include <iostream>
