#define print_no cout << "NO" << endl_line

inline ll gcd(ll a, ll b) { return __gcd(a, b); }
inline ll lcm(ll a, ll b) { return (a / gcd(a, b)) * b; }

inline ll mod_exp(ll base, ll exp, ll mod = MOD) {
    ll result = 1;
    base %= mod;
    while (exp > 0) {
        if (exp & 1) result = (result * base) % mod;
        base = (base * base) % mod;
        exp >>= 1;
    }
    return result;
}

void process_test_case() {
    ll n; 
    cin >> n;

    arr<ll> divisors(n);
    input_array(divisors, n);

    // Sort to identify min and max divisor
    sort(all(divisors));

    // Candidate secret number: product of smallest and largest divisor
    ll candidate_number = divisors[0] * divisors[n - 1];

    // Generate actual divisors of candidate_number (excluding 1 and itself)
    arr<ll> computed_divisors;

    for (ll i = 2; i * i <= candidate_number; ++i) {
        if (candidate_number % i == 0) {
            computed_divisors.push_back(i);
            if (i != candidate_number / i) {
                computed_divisors.push_back(candidate_number / i);
            }
        }
    }

    sort(all(computed_divisors));

    // Compare with provided list
    if (computed_divisors == divisors) {
        cout << candidate_number << endl_line;
    } else {
        cout << -1 << endl_line;
    }
}

