// Main application entry point
int main(int, char**)
{
    // Initialize SDL subsystems
    if (!SDL_Init(SDL_INIT_VIDEO | SDL_INIT_GAMEPAD))
    {
        std::fprintf(stderr, "Error: SDL initialization failed: %s\n", SDL_GetError());
        return 1;
    }

    // Create window with appropriate properties
    float display_scale = SDL_GetDisplayContentScale(SDL_GetPrimaryDisplay());
    SDL_WindowFlags flags = SDL_WINDOW_RESIZABLE | SDL_WINDOW_HIDDEN | SDL_WINDOW_HIGH_PIXEL_DENSITY;
    SDL_Window* app_window = SDL_CreateWindow("Dear ImGui SDL3 + SDL_GPU Demo", 
                                              static_cast<int>(1280 * display_scale), 
                                              static_cast<int>(800 * display_scale), 
                                              flags);
    if (app_window == nullptr)
    {
        std::fprintf(stderr, "Error: Failed to create window: %s\n", SDL_GetError());
        return 1;
    }

    SDL_SetWindowPosition(app_window, SDL_WINDOWPOS_CENTERED, SDL_WINDOWPOS_CENTERED);
    SDL_ShowWindow(app_window);

    // Initialize GPU device
    SDL_GPUDevice* gpu_context = SDL_CreateGPUDevice(
        SDL_GPU_SHADERFORMAT_SPIRV | SDL_GPU_SHADERFORMAT_DXIL | SDL_GPU_SHADERFORMAT_METALLIB,
        true, 
        nullptr
    );
    if (gpu_context == nullptr)
    {
        std::fprintf(stderr, "Error: Failed to create GPU device: %s\n", SDL_GetError());
        return 1;
    }

    // Bind window to GPU device
    if (!SDL_ClaimWindowForGPUDevice(gpu_context, app_window))
    {
        std::fprintf(stderr, "Error: Failed to claim window for GPU: %s\n", SDL_GetError());
        return 1;
    }

    SDL_SetGPUSwapchainParameters(gpu_context, app_window, 
                                  SDL_GPU_SWAPCHAINCOMPOSITION_SDR, 
                                  SDL_GPU_PRESENTMODE_VSYNC);

    // Setup Dear ImGui context
    IMGUI_CHECKVERSION();
    ImGui::CreateContext();
    ImGuiIO& io = ImGui::GetIO(); 
    (void)io;

    // Configure input and UI features
    io.ConfigFlags |= ImGuiConfigFlags_NavEnableKeyboard;
    io.ConfigFlags |= ImGuiConfigFlags_NavEnableGamepad;
    io.ConfigFlags |= ImGuiConfigFlags_DockingEnable;
    io.ConfigFlags |= ImGuiConfigFlags_ViewportsEnable;

    // Apply dark color theme
    ImGui::StyleColorsDark();

    // Adjust UI scaling based on display DPI
    ImGuiStyle& imgui_style = ImGui::GetStyle();
    imgui_style.ScaleAllSizes(display_scale);
    imgui_style.FontScaleDpi = display_scale;
    io.ConfigDpiScaleFonts = true;
    io.ConfigDpiScaleViewports = true;

    // Adjust window styling for multi-viewport support
    if (io.ConfigFlags & ImGuiConfigFlags_ViewportsEnable)
    {
        imgui_style.WindowRounding = 0.0f;
        imgui_style.Colors[ImGuiCol_WindowBg].w = 1.0f;
    }

    // Initialize platform and renderer backends
    ImGui_ImplSDL3_InitForSDLGPU(app_window);

    ImGui_ImplSDLGPU3_InitInfo gpu_init = {};
    gpu_init.Device = gpu_context;
    gpu_init.ColorTargetFormat = SDL_GetGPUSwapchainTextureFormat(gpu_context, app_window);
    gpu_init.MSAASamples = SDL_GPU_SAMPLECOUNT_1;
    gpu_init.SwapchainComposition = SDL_GPU_SWAPCHAINCOMPOSITION_SDR;
    gpu_init.PresentMode = SDL_GPU_PRESENTMODE_VSYNC;

    ImGui_ImplSDLGPU3_Init(&gpu_init);

    // Font loading section (commented out for brevity)
    // style.FontSizeBase = 20.0f;
    // io.Fonts->AddFontDefault();
    // ... additional font loading examples ...

    // Application state variables
    bool show_demo_panel = true;
    bool show_secondary_window = false;
    ImVec4 background_color = ImVec4(0.45f, 0.55f, 0.60f, 1.00f);

    // Main event loop
    bool running = true;
    while (running)
    {
        // Process events
        SDL_Event evt;
        while (SDL_PollEvent(&evt))
        {
            ImGui_ImplSDL3_ProcessEvent(&evt);
            if (evt.type == SDL_EVENT_QUIT)
                running = false;
            if (evt.type == SDL_EVENT_WINDOW_CLOSE_REQUESTED && 
                evt.window.windowID == SDL_GetWindowID(app_window))
                running = false;
        }

        // Skip rendering when window is minimized
        if (SDL_GetWindowFlags(app_window) & SDL_WINDOW_MINIMIZED)
        {
            SDL_Delay(10);
            continue;
        }

        // Begin new frame
        ImGui_ImplSDLGPU3_NewFrame();
        ImGui_ImplSDL3_NewFrame();
        ImGui::NewFrame();

        // Demo window
        if (show_demo_panel)
            ImGui::ShowDemoWindow(&show_demo_panel);

        // Secondary window
        {
            static float slider_value = 0.0f;
            static int button_clicks = 0;

            ImGui::Begin("Hello, world!");
            ImGui::Text("This is some useful text.");
            ImGui::Checkbox("Show Demo Panel", &show_demo_panel);
            ImGui::Checkbox("Show Secondary Window", &show_secondary_window);
            ImGui::SliderFloat("Adjust Value", &slider_value, 0.0f, 1.0f);
            ImGui::ColorEdit3("Background Color", (float*)&background_color);

            if (ImGui::Button("Increment Counter"))
                button_clicks++;

            ImGui::SameLine();
            ImGui::Text("Clicks: %d", button_clicks);
            ImGui::Text("Performance: %.3f ms/frame (%.1f FPS)", 
                        1000.0f / io.Framerate, io.Framerate);
            ImGui::End();
        }

        // Additional window
        if (show_secondary_window)
        {
            ImGui::Begin("Secondary Window", &show_secondary_window);
            ImGui::Text("Hello from the secondary window!");
            if (ImGui::Button("Close This Window"))
                show_secondary_window = false;
            ImGui::End();
        }

        // Render frame
        ImGui::Render();
        ImDrawData* draw_data = ImGui::GetDrawData();
        const bool is_minimized = (draw_data->DisplaySize.x <= 0.0f || 
                                   draw_data->DisplaySize.y <= 0.0f);

        SDL_GPUCommandBuffer* cmd_buffer = SDL_AcquireGPUCommandBuffer(gpu_context);
        SDL_GPUTexture* swapchain_image;
        SDL_WaitAndAcquireGPUSwapchainTexture(cmd_buffer, app_window, &swapchain_image, 
                                              nullptr, nullptr);

        if (swapchain_image != nullptr && !is_minimized)
        {
            ImGui_ImplSDLGPU3_PrepareDrawData(draw_data, cmd_buffer);

            SDL_GPUColorTargetInfo color_target = {};
            color_target.texture = swapchain_image;
            color_target.clear_color = SDL_FColor { 
                background_color.x, background_color.y, 
                background_color.z, background_color.w 
            };
            color_target.load_op = SDL_GPU_LOADOP_CLEAR;
            color_target.store_op = SDL_GPU_STOREOP_STORE;
            color_target.mip_level = 0;
            color_target.layer_or_depth_plane = 0;
            color_target.cycle = false;

            SDL_GPURenderPass* render_pass = SDL_BeginGPURenderPass(
                cmd_buffer, 
                &color_target, 
                1, 
                nullptr
            );

            ImGui_ImplSDLGPU3_RenderDrawData(draw_data, cmd_buffer, render_pass);
            SDL_EndGPURenderPass(render_pass);
        }

        // Handle multi-viewport windows
        if (io.ConfigFlags & ImGuiConfigFlags_ViewportsEnable)
        {
            ImGui::UpdatePlatformWindows();
            ImGui::RenderPlatformWindowsDefault();
        }

        SDL_SubmitGPUCommandBuffer(cmd_buffer);
    }

    // Cleanup resources
    SDL_WaitForGPUIdle(gpu_context);
    ImGui_ImplSDL3_Shutdown();
    ImGui_ImplSDLGPU3_Shutdown();
    ImGui::DestroyContext();
    SDL_ReleaseWindowFromGPUDevice(gpu_context, app_window);
    SDL_DestroyGPUDevice(gpu_context);
    SDL_DestroyWindow(app_window);
    SDL_Quit();

    return 0;
}

