namespace ap::memory {

ErrorOr<Stats> getMemoryStatistics() noexcept {
    Stats result;

    // Retrieve total virtual memory information
    MEMORYSTATUSEX memoryInfo;
    memoryInfo.dwLength = sizeof(MEMORYSTATUSEX);
    GlobalMemoryStatusEx(&memoryInfo);

    result.totalVirtualMemory = memoryInfo.ullTotalPageFile;

    // Calculate virtual memory currently in use by the system
    result.usedVirtualMemory =
        memoryInfo.ullTotalPageFile - memoryInfo.ullAvailPageFile;

    // Get virtual memory used specifically by this process
    PROCESS_MEMORY_COUNTERS_EX processMemoryCounters;
    GetProcessMemoryInfo(GetCurrentProcess(),
                         reinterpret_cast<PPROCESS_MEMORY_COUNTERS>(&processMemoryCounters),
                         sizeof(processMemoryCounters));
    result.processVirtualMemoryUsage = processMemoryCounters.PrivateUsage;

    // Retrieve total physical memory
    result.totalPhysicalMemory = memoryInfo.ullTotalPhys;

    // Calculate physical memory currently in use by the system
    result.usedPhysicalMemory =
        memoryInfo.ullTotalPhys - memoryInfo.ullAvailPhys;

    // Get physical memory (working set) used by this process
    result.processPhysicalMemoryUsage = processMemoryCounters.WorkingSetSize;

    return result;
}

}  // namespace ap::memory

