// Example: Demonstrating how to manually construct a full task list for rendering
HVT_TEST(howTo, buildFullTaskList)
{
    auto testContext = TestHelpers::CreateTestContext();
    TestHelpers::TestStage renderStage(testContext->_backend);
    ASSERT_TRUE(renderStage.open(testContext->_sceneFilepath));

    hvt::RenderIndexProxyPtr rendererProxy;
    hvt::FramePassPtr framePassInstance;

    // Setup phase: initialize rendering infrastructure
    {
        // Initialize renderer
        hvt::RendererDescriptor rendererInfo;
        rendererInfo.hgiDriver    = &testContext->_backend->hgiDriver();
        rendererInfo.rendererName = "HdStormRendererPlugin";
        hvt::ViewportEngine::CreateRenderer(rendererProxy, rendererInfo);

        // Attach USD scene data
        HdSceneIndexBaseRefPtr sceneDataSource = hvt::ViewportEngine::CreateUSDSceneIndex(renderStage.stage());
        rendererProxy->RenderIndex()->InsertSceneIndex(sceneDataSource, SdfPath::AbsoluteRootPath());

        // Frame pass configuration
        hvt::FramePassDescriptor passConfig;
        passConfig.renderIndex = rendererProxy->RenderIndex();
        passConfig.uid         = SdfPath("/renderingFrame");

        // Construct frame pass and populate default tasks
        framePassInstance = std::make_unique<hvt::FramePass>(passConfig.uid.GetText());
        framePassInstance->Initialize(passConfig);
        framePassInstance->CreatePresetTasks(hvt::FramePass::PresetTaskLists::Standard);
    }

    // Render loop: execute multiple frames for stability
    int iterationCount = 20; // previously 10
    auto renderLoop = [&]() {
        auto& layerParams = framePassInstance->params();
        layerParams.renderBufferSize = GfVec2i(testContext->width(), testContext->height());
        layerParams.viewInfo.framing =
            hvt::ViewParams::GetDefaultFraming(testContext->width(), testContext->height());
        layerParams.viewInfo.viewMatrix      = renderStage.viewMatrix();
        layerParams.viewInfo.projectionMatrix = renderStage.projectionMatrix();
        layerParams.viewInfo.lights           = renderStage.defaultLights();
        layerParams.viewInfo.material         = renderStage.defaultMaterial();
        layerParams.viewInfo.ambient          = renderStage.defaultAmbient();
        layerParams.colorspace                = HdxColorCorrectionTokens->sRGB;
        layerParams.backgroundColor           = TestHelpers::ColorDarkGrey;
        layerParams.selectionColor            = TestHelpers::ColorYellow;
        layerParams.enablePresentation        = testContext->presentationEnabled();

        framePassInstance->Render();
        return --iterationCount > 0;
    };

    // Launch rendering using backend-specific mechanism
    testContext->run(renderLoop, framePassInstance.get());

    // Validate output image against baseline
    const std::string referenceImage =
        TestHelpers::gTestNames.suiteName + std::string("/") + std::string("fullTaskListExample");
    ASSERT_TRUE(testContext->validateImages(computedImageName, referenceImage));
}

