    IO &IO, std::shared_ptr<eld::LDYAML::Content> &ContentData) {
  if (ContentData) {
    ContentData->mapping(IO);
    return;
  }
  std::vector<llvm::StringRef> Keys = IO.keys();
  if (llvm::find(Keys, "Contents") != Keys.end()) {
    ContentData = std::make_shared<eld::LDYAML::OutputSection>();
    ContentData->ContentKind = Content::Kind::OutputSection;
  } else if (llvm::find(Keys, "PostLTOFile") != Keys.end()) {
    ContentData = std::make_shared<eld::LDYAML::InputBitcodeSection>();
    ContentData->ContentKind = Content::Kind::InputSection;
  } else if (llvm::find(Keys, "Origin") != Keys.end()) {
    ContentData = std::make_shared<eld::LDYAML::InputSection>();
    ContentData->ContentKind = Content::Kind::InputSection;
  } else if (llvm::find(Keys, "Padding") != Keys.end()) {
    ContentData = std::make_shared<eld::LDYAML::Padding>();
    ContentData->ContentKind = Content::Kind::Padding;
  } else if (llvm::find(Keys, "LinkerScript") != Keys.end()) {
    ContentData = std::make_shared<eld::LDYAML::LinkerScriptRule>();
    ContentData->ContentKind = Content::Kind::LinkerScriptRule;
  } else {
    ContentData = std::make_shared<eld::LDYAML::Assignment>();
    ContentData->ContentKind = Content::Kind::Assignment;
  }
  ContentData->mapping(IO);
}

