void TransConstraint::Enter() {
    RndPollable::Enter();
    SnapToParent();
}

void TransConstraint::SetScaleVectorOnTransform(RndTransformable *xfm, Vector3 &scaleVec) {
    MILO_ASSERT(xfm, 0x80);
    Vector3 eulerOut;
    Hmx::Matrix3 rotMat;
    Transform worldXfm = xfm->WorldXfm();
    MakeEuler(worldXfm.m, eulerOut);
    MakeRotMatrix(eulerOut, rotMat, true);
    Scale(rotMat, scaleVec, rotMat);
    worldXfm.m = rotMat;
    xfm->SetWorldXfm(worldXfm);
}

void TransConstraint::SnapToParent() {
    if (mParent && mChild) {
        Vector3 parentPos = mParent->WorldXfm().v;
        Vector3 childPos = mChild->WorldXfm().v;

        for (int axis = 0; axis < 3; ++axis) {
            if (mTracks[axis]) {
                childPos[axis] = parentPos[axis];
            }
        }

        mChild->SetWorldPos(childPos);

        if (mAffectScale) {
            Vector3 parentScale;
            MakeScale(mParent->WorldXfm().m, parentScale);

            Vector3 childScale;
            MakeScale(mChild->WorldXfm().m, childScale);

            for (int dim = 0; dim < 3; ++dim) {
                if (mTracks[dim]) {
                    childScale[dim] = parentScale[dim];
                }
            }

            SetScaleVectorOnTransform(mChild, childScale);
        }
    }
}

#include <iostream>
#include <vector>
#include <string>
#include <set>
#include <algorithm>

// Process one test scenario
void process_case() {
    int count;
    std::cin >> count;
    std::set<std::string> collected_words;

    // Try each starting character from 'a' to 'z'
    for (char start_char = 'a'; start_char <= 'z'; ++start_char) {
        if (collected_words.size() == count) {
            break;
        }

        std::string base(1, start_char);
        int requested = 1;

        // Exponential search for words with current prefix
        while (true) {
            if (collected_words.size() == count) {
                break;
            }

            std::cout << "query " << base << " " << requested << std::endl;
            int actual_count;
            std::cin >> actual_count;

            for (int idx = 0; idx < actual_count; ++idx) {
                std::string term;
                std::cin >> term;
                collected_words.insert(term);
            }

            // If we received fewer than requested, no more words exist for this prefix
            if (actual_count < requested) {
                break;
            }

            // If we asked for 'count' and got 'count', we have all words
            if (requested == count) {
                break;
            }

            // Increase query size exponentially
            requested *= 2;
            if (requested > count) {
                requested = count;
            }
        }
    }

    // Print the final result
    std::cout << "answer";
    for (const auto& term : collected_words) {
        std::cout << " " << term;
    }
    std::cout << std::endl;
}

int main() {
    // Optimize I/O operations
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int test_cases;
    std::cin >> test_cases;

    while (test_cases--) {
        process_case();
    }

    return 0;
}

