#include <bits/stdc++.h>
using namespace std;
typedef long long ll;

vector<ll> performQuery(int numProbes, const vector<pair<ll, ll>>& probeCoords) {
    cout << "? " << numProbes;
    for (const auto& [xCoord, yCoord] : probeCoords) {
        cout << " " << xCoord << " " << yCoord;
    }
    cout << endl;
    cout.flush();

    string responseLine;
    if (cin.peek() == '\n') cin.ignore();
    getline(cin, responseLine);

    stringstream ss(responseLine);
    vector<ll> distances;
    ll distanceVal;
    while (ss >> distanceVal) {
        distances.push_back(distanceVal);
    }
    return distances;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    ll boardSize, pointCount, waveCount;
    cin >> boardSize >> pointCount >> waveCount;

    // For scenarios with 4 or more waves available
    if (waveCount >= 4) {
        ll boundary = boardSize + 1;
        vector<ll> distA, distB, distC, distD;

        // First wave: single probe at top-right corner
        distA = performQuery(1, {{boundary, boundary}});

        // Second wave: single probe at bottom-right corner
        distB = performQuery(1, {{boundary, -boundary}});

        // Third wave: single probe at top-left corner
        distC = performQuery(1, {{-boundary, boundary}});

        // Fourth wave: single probe at bottom-left corner
        distD = performQuery(1, {{-boundary, -boundary}});

        // Calculate s_i and t_i values from the distances
        vector<ll> S_vals(pointCount), T_vals(pointCount);
        for (int idx = 0; idx < pointCount; idx++) {
            S_vals[idx] = boundary + boundary - distA[idx];
            T_vals[idx] = boundary + boundary - distB[idx];
        }

        // Build adjacency list for bipartite matching
        vector<vector<int>> graph(pointCount);
        for (int i = 0; i < pointCount; i++) {
            for (int j = 0; j < pointCount; j++) {
                ll s_val = S_vals[i];
                ll t_val = T_vals[j];
                ll sum_xy = s_val + t_val;
                ll diff_xy = s_val - t_val;

                if (sum_xy % 2 != 0) continue;

                ll coordX = sum_xy / 2;
                ll coordY = diff_xy / 2;

                if (abs(coordX) <= boardSize && abs(coordY) <= boardSize) {
                    graph[i].push_back(j);
                }
            }
        }

        // Kuhn's algorithm for maximum bipartite matching
        vector<int> rightMatch(pointCount, -1);
        vector<bool> visited(pointCount);

        function<bool(int)> augmentPath = [&](int leftNode) {
            for (int rightNode : graph[leftNode]) {
                if (!visited[rightNode]) {
                    visited[rightNode] = true;
                    if (rightMatch[rightNode] == -1 || augmentPath(rightMatch[rightNode])) {
                        rightMatch[rightNode] = leftNode;
                        return true;
                    }
                }
            }
            return false;
        };

        for (int leftNode = 0; leftNode < pointCount; leftNode++) {
            fill(visited.begin(), visited.end(), false);
            augmentPath(leftNode);
        }

        // Verify we found a perfect matching
        int matchedCount = 0;
        for (int j = 0; j < pointCount; j++) {
            if (rightMatch[j] != -1) matchedCount++;
        }

        if (matchedCount != pointCount) {
            // Output fallback solution
            cout << "!";
            for (int i = 0; i < pointCount; i++) cout << " 0 0";
            cout << endl;
            return 0;
        }

        // Reconstruct coordinates using the matching
        vector<pair<ll, ll>> coordinates(pointCount);
        for (int j = 0; j < pointCount; j++) {
            int i = rightMatch[j];
            ll s_val = S_vals[i];
            ll t_val = T_vals[j];
            ll x_coord = (s_val + t_val) / 2;
            ll y_coord = (s_val - t_val) / 2;
            coordinates[i] = {x_coord, y_coord};
        }

        // Print final answer
        cout << "!";
        for (const auto& [x, y] : coordinates) {
            cout << " " << x << " " << y;
        }
        cout << endl;
    } 
    else {
        // Fallback strategy for fewer than 4 waves
        ll boundary = boardSize + 1;

        // Two-wave approach with two probes each
        auto wave1Results = performQuery(2, {{boundary, boundary}, {-boundary, -boundary}});
        auto wave2Results = performQuery(2, {{boundary, -boundary}, {-boundary, boundary}});

        sort(wave1Results.begin(), wave1Results.end());
        sort(wave2Results.begin(), wave2Results.end());

        vector<ll> S_list, T_list;

        // Pair distances from first wave
        for (int i = 0; i < pointCount; i++) {
            ll d_small = wave1Results[i];
            ll d_large = wave1Results[2 * pointCount - 1 - i];

            if (d_small + d_large != boundary + boundary + boundary + boundary) {
                cout << "!";
                for (int j = 0; j < pointCount; j++) cout << " 0 0";
                cout << endl;
                return 0;
            }
            S_list.push_back(boundary + boundary - d_small);
        }

        // Pair distances from second wave
        for (int i = 0; i < pointCount; i++) {
            ll d_small = wave2Results[i];
            ll d_large = wave2Results[2 * pointCount - 1 - i];

            if (d_small + d_large != boundary + boundary + boundary + boundary) {
                cout << "!";
                for (int j = 0; j < pointCount; j++) cout << " 0 0";
                cout << endl;
                return 0;
            }
            T_list.push_back(boundary + boundary - d_small);
        }

        // Sort and assume pairing by order
        sort(S_list.begin(), S_list.end());
        sort(T_list.begin(), T_list.end());

        vector<pair<ll, ll>> points(pointCount);
        for (int i = 0; i < pointCount; i++) {
            ll s_val = S_list[i];
            ll t_val = T_list[i];
            ll x_coord = (s_val + t_val) / 2;
            ll y_coord = (s_val - t_val) / 2;
            points[i] = {x_coord, y_coord};
        }

        cout << "!";
        for (const auto& [x, y] : points) {
            cout << " " << x << " " << y;
        }
        cout << endl;
    }

    return 0;
}

#include <iostream>
#include <vector>
#include <algorithm>
#include <numeric>

const int MAX_NODES = 1001;
std::vector<int> graph[MAX_NODES];
int nodeColor[MAX_NODES];

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int nodes, edges;
    std::cin >> nodes >> edges;

    for (int i = 0; i < edges; ++i) {
        int from, to;
        std::cin >> from >> to;
        graph[from].push_back(to);
        graph[to].push_back(from);
    }

    // --- Initial coloring: process higher-degree nodes first ---
    std::vector<std::pair<int, int>> degreeList;
    for (int i = 1; i <= nodes; ++i) {
        degreeList.emplace_back(-static_cast<int>(graph[i].size()), i);
    }
    std::sort(degreeList.begin(), degreeList.end());

    // Reset colors to zero (uncolored)
    for (const auto& entry : degreeList) {
        int vertex = entry.second;
        int neighborColors[4] = {0}; // Track usage of colors 1, 2, 3

        for (int neighbor : graph[vertex]) {
            if (nodeColor[neighbor] != 0) {
                neighborColors[nodeColor[neighbor]]++;
            }
        }

        // Choose the least-used color (ties broken by smallest index)
        int chosenColor = 1;
        for (int c = 2; c <= 3; ++c) {
            if (neighborColors[c] < neighborColors[chosenColor]) {
                chosenColor = c;
            }
        }
        nodeColor[vertex] = chosenColor;
    }

    // --- Local search optimization phase ---
    const int MAX_ITERATIONS = 100;
    for (int iteration = 0; iteration < MAX_ITERATIONS; ++iteration) {
        bool updated = false;

        for (int v = 1; v <= nodes; ++v) {
            int conflictCounts[4] = {0};
            for (int neighbor : graph[v]) {
                conflictCounts[nodeColor[neighbor]]++;
            }

            int currentColor = nodeColor[v];
            int optimalColor = currentColor;

            // Find a better color (fewer conflicts, tie-break by smaller index)
            for (int c = 1; c <= 3; ++c) {
                if (conflictCounts[c] < conflictCounts[optimalColor]) {
                    optimalColor = c;
                }
            }

            if (optimalColor != currentColor) {
                nodeColor[v] = optimalColor;
                updated = true;
            }
        }

        if (!updated) {
            break; // Converged to local optimum
        }
    }

    // --- Print final coloring ---
    for (int i = 1; i <= nodes; ++i) {
        std::cout << nodeColor[i] << (i == nodes ? "" : " ");
    }
    std::cout << '\n';

    return 0;
}

