class ModifyOutputSection : public eld::plugin::SectionIteratorPlugin {
public:
  ModifyOutputSection() : eld::plugin::SectionIteratorPlugin("ModifyOutputSection") {}

  // Initialization hook - no setup required for this plugin
  void Init(std::string config) override {}

  // Process each non-garbage collected section
  void processSection(eld::plugin::Section sec) override {
    if (sec.matchPattern("*text")) {
      // Redirect the output section of 'sec' to '.rodata'
      // Note: LinkerWrapper::setOutputSection must only be invoked during BeforeLayout state.
      // Changes made after BeforeLayout may cause undefined behavior.
      //
      // Adding an annotation helps with debugging and diagnostics.
      Linker->setOutputSection(
          sec, ".rodata",
          /*Annotation=*/"Redirecting output section of '.text.*' to '.rodata'");
    }
  }

  // Run hook called once after all processSection calls
  eld::plugin::Plugin::Status Run(bool verbose) override {
    return eld::plugin::Plugin::Status::SUCCESS;
  }

  // Cleanup hook called once per plugin execution
  void Destroy() override {
    // Apply all pending section overrides
    Linker->finishAssignOutputSections();
  }

  uint32_t GetLastError() override { return 0; }
  std::string GetLastErrorAsString() override { return "No error"; }
  std::string GetName() override { return "ModifyOutputSection"; }
};

