namespace debug {
void log_message(const char *msg, ...) {
  char buffer[2048];
  va_list arguments;
  va_start(arguments, msg);
  vsnprintf(buffer, 2048, msg, arguments);
  OutputDebugStringA(buffer);
  va_end(arguments);
}
std::string filename_only(const std::string &path) {
  unsigned int pos = path.find_last_of("\\/");
  if (pos == std::string::npos) {
    return path;
  } else {
    return path.substr(pos + 1);
  }
}
struct CallFrame {
  DWORD64 addr;
  std::string func_name;
  std::string dll_name;
  unsigned int lineno;
  std::string source_file;
};
inline std::vector<CallFrame> capture_stack() {
#if _WIN64
  DWORD arch = IMAGE_FILE_MACHINE_AMD64;
#else
  DWORD arch = IMAGE_FILE_MACHINE_I386;
#endif
  HANDLE current_process = GetCurrentProcess();
  HANDLE current_thread = GetCurrentThread();
  if (SymInitialize(current_process, NULL, TRUE) == FALSE) {
    log_message("Failed to call SymInitialize.");
    return std::vector<CallFrame>();
  }
  SymSetOptions(SYMOPT_LOAD_LINES);
  CONTEXT ctx = {};
  ctx.ContextFlags = CONTEXT_FULL;
  RtlCaptureContext(&ctx);
#if _WIN64
  STACKFRAME frame = {};
  frame.AddrPC.Offset = context.Rip;
  frame.AddrPC.Mode = AddrModeFlat;
  frame.AddrFrame.Offset = context.Rbp;
  frame.AddrFrame.Mode = AddrModeFlat;
  frame.AddrStack.Offset = context.Rsp;
  frame.AddrStack.Mode = AddrModeFlat;
#else
  STACKFRAME frame = {};
  frame.AddrPC.Offset = context.Eip;
  frame.AddrPC.Mode = AddrModeFlat;
  frame.AddrFrame.Offset = context.Ebp;
  frame.AddrFrame.Mode = AddrModeFlat;
  frame.AddrStack.Offset = context.Esp;
  frame.AddrStack.Mode = AddrModeFlat;
#endif
  bool first_entry = true;
  std::vector<CallFrame> results;
  while (StackWalk(arch, current_process, current_thread, &frame, &ctx, NULL,
                   SymFunctionTableAccess, SymGetModuleBase, NULL)) {
    CallFrame entry = {};
    entry.addr = frame.AddrPC.Offset;
#if _WIN64
    DWORD64 base_addr = 0;
#else
    DWORD base_addr = 0;
#endif
    base_addr = SymGetModuleBase(current_process, frame.AddrPC.Offset);
    char module_path[MAX_PATH];
    if (base_addr &&
        GetModuleFileNameA((HINSTANCE)base_addr, module_path, MAX_PATH)) {
      entry.dll_name = filename_only(module_path);
    } else {
      entry.dll_name = "Unknown Module";
    }
#if _WIN64
    DWORD64 displacement = 0;
#else
    DWORD displacement = 0;
#endif
    char symbol_buffer[sizeof(IMAGEHLP_SYMBOL) + 511];
    PIMAGEHLP_SYMBOL sym = (PIMAGEHLP_SYMBOL)symbol_buffer;
    sym->SizeOfStruct = sizeof(IMAGEHLP_SYMBOL) + 511;
    sym->MaxNameLength = 510;
    if (SymGetSymFromAddr(current_process, frame.AddrPC.Offset, &displacement, sym)) {
      entry.func_name = sym->Name;
    } else {
      DWORD err_code = GetLastError();
      log_message("Failed to resolve address 0x%X: %u\n", frame.AddrPC.Offset, err_code);
      entry.func_name = "Unknown Function";
    }
    IMAGEHLP_LINE line_info;
    line_info.SizeOfStruct = sizeof(IMAGEHLP_LINE);
    DWORD line_displacement = 0;
    if (SymGetLineFromAddr(current_process, frame.AddrPC.Offset, &line_displacement, &line_info)) {
      entry.source_file = line_info.FileName;
      entry.lineno = line_info.LineNumber;
    } else {
      DWORD err_code = GetLastError();
      log_message("Failed to resolve line for 0x%X: %u\n", frame.AddrPC.Offset,
            err_code);
      entry.lineno = 0;
    }
    if (!first_entry) {
      results.push_back(entry);
    }
    first_entry = false;
  }
  SymCleanup(current_process);
  return results;
}
