namespace quadrants {
void print_traceback() {
#ifdef __APPLE__
  static std::mutex trace_printer_mutex;
  // Modified based on
  // http://www.nullptr.me/2013/04/14/generating-stack-trace-on-os-x/
  // TODO: print line number instead of offset
  // (https://stackoverflow.com/questions/8278691/how-to-fix-backtrace-line-number-error-in-c)
  // record stack trace up to 64 frames
  void *stack_buffer[64] = {};
  // collect stack frames
  int count = backtrace((void **)stack_buffer, 64);
  // get the human-readable symbols (mangled)
  char **symbols = backtrace_symbols((void **)stack_buffer, count);
  std::vector<std::string> frame_strings;
  for (int idx = 0; idx < count; idx++) {
    char function_symbol[2048] = {};
    char module_name[2048] = {};
    int offset = 0;
    char addr[64] = {};
    // split the string, take out chunks out of stack trace
    // we are primarily interested in module, function and address
    sscanf(symbols[idx], "%*s %s %s %s %*s %d", module_name, addr, function_symbol,
           &offset);
    int valid_cpp_name = 0;
    //  if this is a C++ library, symbol will be demangled
    //  on success function returns 0
    char *function_name =
        abi::__cxa_demangle(function_symbol, NULL, 0, &valid_cpp_name);
    char frame_buffer[8192] = {};
    sprintf(frame_buffer, "* %28s | %7d | %s", module_name, offset,
            function_name);
    if (function_name != nullptr)
      free(function_name);
    std::string frameStr(frame_buffer);
    frame_strings.push_back(frameStr);
  }
  free(symbols);
  // Pretty print the traceback table
  // Exclude this function itself
  frame_strings.erase(frame_strings.begin());
  std::reverse(frame_strings.begin(), frame_strings.end());
  std::lock_guard<std::mutex> guard(trace_printer_mutex);
  printf("\n");
  printf(
      "                            * Quadrants Core - Stack Traceback *        "
      " "
      "  "
      "                  \n");
  printf(
      "========================================================================"
      "==================\n");
  printf(
      "|                       Module |  Offset | Function                     "
      "                 |\n");
  printf(
      "|-----------------------------------------------------------------------"
      "-----------------|\n");
  std::reverse(frame_strings.begin(), frame_strings.end());
  for (auto trace : frame_strings) {
    const int function_start = 39;
    const int line_width = 86;
    const int function_width = line_width - function_start - 2;
    int i;
    for (i = 0; i < (int)trace.size(); i++) {
      std::cout << trace[i];
      if (i > function_start + 3 &&
          (i - 3 - function_start) % function_width == 0) {
        std::cout << " |" << std::endl << " ";
        for (int j = 0; j < function_start; j++) {
          std::cout << " ";
        }
        std::cout << " | ";
      }
    }
    for (int j = 0;
         j < function_width + 2 - (i - 3 - function_start) % function_width;
         j++) {
      std::cout << " ";
    }
    std::cout << "|" << std::endl;
  }
  printf(
      "========================================================================"
      "==================\n");
  printf("\n");
#elif defined(_WIN64)
  // Windows
  fmt::print(fg(fmt::color::cyan), "***********************************\n");
  fmt::print(fg(fmt::color::cyan),
             "* Quadrants Compiler Stack Traceback *\n");
  fmt::print(fg(fmt::color::cyan), "***********************************\n");
  std::vector<debug::CallFrame> stack = debug::capture_stack();
  for (unsigned int i = 0; i < stack.size(); i++) {
    fmt::print(fg(fmt::color::cyan),
               fmt::format("0x{:x}: ", stack[i].addr));
    fmt::print(fg(fmt::color::yellow), stack[i].func_name);
    if (stack[i].source_file != std::string(""))
      fmt::print(fg(fmt::color::cyan),
                 fmt::format("(line {} in {})", stack[i].lineno, stack[i].source_file));
    fmt::print(fg(fmt::color::cyan),
               fmt::format(" in {}\n", stack[i].dll_name));
  }
#else
  // Based on http://man7.org/linux/man-pages/man3/backtrace.3.html
  constexpr int BT_BUF_SIZE = 512;
  int nptrs;
  void *buffer[BT_BUF_SIZE];
  char **strings;
  nptrs = backtrace(buffer, BT_BUF_SIZE);
  strings = backtrace_symbols(buffer, nptrs);
  if (strings == nullptr) {
    perror("backtrace_symbols");
    exit(EXIT_FAILURE);
  }
  fmt::print(fg(fmt::color::cyan), "***********************************\n");
  fmt::print(fg(fmt::color::cyan),
             "* Quadrants Compiler Stack Traceback *\n");
  fmt::print(fg(fmt::color::cyan), "***********************************\n");
  // j = 0: quadrants::print_traceback
  for (int j = 1; j < nptrs; j++) {
    std::string s(strings[j]);
    std::size_t slash = s.find("/");
    std::size_t start = s.find("(");
    std::size_t end = s.rfind("+");
    std::string line;
    if (slash == 0 && start < end && s[start + 1] != '+') {
      std::string name = s.substr(start + 1, end - start - 1);
      char *demangled_name_;
      int status = -1;
      demangled_name_ =
          abi::__cxa_demangle(name.c_str(), nullptr, nullptr, &status);
      if (demangled_name_) {
        name = std::string(demangled_name_);
      }
      std::string prefix = s.substr(0, start);
      line = fmt::format("{}: {}", prefix, name);
      free(demangled_name_);
    } else {
      line = s;
    }
    fmt::print(fg(fmt::color::cyan), "{}\n", line);
  }
  std::free(strings);
#endif
  fmt::print(
      fg(fmt::color::amber),
      "\nInternal error occurred. Check out this page for possible solutions:\n"
      "https://docs.taichi-lang.org/docs/install\n");
}
