#include <iostream>

struct B {
    int value;
    void method1() {
        value++;
        method1();
        method2();
        method3();
        // we can invoke any member function from a non-const method
    }
    void method2() const {
       // value++; // we cannot alter members within a const method
       // method1(); // we cannot call method1() here, since it is not declared const,
       // therefore there's no assurance it won't change state
       method3(); // only const methods may be invoked from a const method
    }
    void method3() const {
       // value++; // this is prohibited inside a const method
       // method1(); // calling method1() is disallowed here as it lacks const qualifier,
            // meaning it might modify the object's state
       method2(); // only const methods are permitted to be called
    }
};

void helper1(B& obj) {
    obj.method1(); // allowed: object reference is non-const
    obj.method2();
    obj.method3();
    // all member functions can be invoked on a non-const object
}

void helper2(const B& obj) {
    // obj.method1(); // not allowed: object is const,
           // so only const-qualified member functions can be called
    obj.method2();
    obj.method3(); // const methods are accessible on const objects
}

