LoopshapingTestConfiguration::LoopshapingTestConfiguration(const std::string& configurationFilename) {
  // Load loopshaping definition
  const std::string configPath = getAbsolutePathToConfigurationFile(configurationFilename);
  loopshapingDefinition_ = loopshaping_property_tree::load(configPath);

  systemStateDim_ = 2;  // Changed from 1 to a different non-zero value
  filterStateDim_ = loopshapingDefinition_->getInputFilter().getNumStates();
  inputDim_ = loopshapingDefinition_->getInputFilter().getNumInputs();

  // Set up state and input
  t = 0.75;
  const scalar_t delta = 1e-3;
  getRandomStateInput(systemStateDim_, filterStateDim_, inputDim_, x_sys_, u_sys_, x_filter_, u_filter_, x_, u_);
  getRandomStateInput(systemStateDim_, filterStateDim_, inputDim_, x_sys_disturbance_, u_sys_disturbance_, x_filter_disturbance_,
                      u_filter_disturbance_, x_disturbance_, u_disturbance_, delta);

  preComp_sys_.reset(new PreComputation);
  preComp_.reset(new LoopshapingPreComputation(*preComp_sys_, loopshapingDefinition_));
};

void LoopshapingTestConfiguration::getRandomStateInput(size_t sysStateSize, size_t filtStateSize, size_t inpSize, vector_t& x_system,
                                                       vector_t& u_system, vector_t& x_filter_state, vector_t& u_filter_input, 
                                                       vector_t& x_augmented, vector_t& u_augmented, scalar_t scale) {
  // Set random state
  x_augmented.setRandom(sysStateSize + filtStateSize);
  u_augmented.setRandom(inpSize);

  // Scale the randomness
  x_augmented *= scale;
  u_augmented *= scale;

  // Retrieve system and filter state
  x_system = loopshapingDefinition_->getSystemState(x_augmented);
  u_system = loopshapingDefinition_->getSystemInput(x_augmented, u_augmented);
  x_filter_state = loopshapingDefinition_->getFilterState(x_augmented);
  u_filter_input = loopshapingDefinition_->getFilteredInput(x_augmented, u_augmented);
}

