TEST(TLSConfigTest, SessionTicketsConfigEquality) {
  TLSConfig::SessionTicketsConfig cfg1;
  cfg1.enabled = true;
  cfg1.lifetime = std::chrono::seconds(3600);
  cfg1.maxKeys = 4;
  TLSConfig config;
  config.withTlsSessionTickets(true);
  config.withTlsSessionTicketLifetime(std::chrono::seconds(3600));
  config.withTlsSessionTicketMaxKeys(4);
  EXPECT_EQ(cfg1, config.sessionTickets);
  config.withTlsSessionTicketMaxKeys(8);
  EXPECT_NE(cfg1, config.sessionTickets);
}

TEST(TLSConfigTest, SniCertificateEquality) {
  TLSConfig::SniCertificate cert1;
  cert1.setPattern("test.example.com");
  cert1.isWildcard = false;
  cert1.setCertPem(kFakeCertPem);
  cert1.setKeyPem(kFakeKeyPem);
  TLSConfig::SniCertificate cert2;
  cert2.setPattern("test.example.com");
  cert2.isWildcard = false;
  cert2.setCertPem(kFakeCertPem);
  cert2.setKeyPem(kFakeKeyPem);
  EXPECT_EQ(cert1, cert2);
  cert2.setKeyPem("-----BEGIN PRIVATE KEY-----\nDIFFERENT_KEY\n-----END PRIVATE KEY-----\n");
  EXPECT_NE(cert1, cert2);
}

