#include <iostream>
#include <vector>
#include <string>
#include <numeric>
#include <algorithm>
using namespace std;

int nodes_count, root_index;
vector<pair<int, int>> tree_edges;
vector<int> node_parent;

// Global state for recursive assignment
string current_assignment;

void assign_value(int u, int val) {
    if (u >= nodes_count) {
        current_assignment[u] = char(val + '0');
        return;
    }

    // Force both children to 0 to ensure predictable behavior
    assign_value(tree_edges[u].first, 0);
    assign_value(tree_edges[u].second, 0);

    // Now slot_output is 0, so output(u) = 0 ^ s[u] = s[u]
    // To get desired output = val, set s[u] = val
    current_assignment[u] = char(val + '0');
}

int perform_query(const string& assignment) {
    cout << "? " << assignment << endl;
    int response;
    cin >> response;
    return response;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);
    cin >> nodes_count >> root_index;
    tree_edges.resize(nodes_count);
    node_parent.assign(2 * nodes_count + 1, -1);

    for (int idx = 0; idx < nodes_count; ++idx) {
        cin >> tree_edges[idx].first >> tree_edges[idx].second;
        node_parent[tree_edges[idx].first] = idx;
        node_parent[tree_edges[idx].second] = idx;
    }

    string result(nodes_count, ' ');
    vector<int> ancestor_chain;
    vector<int> sibling_nodes;

    for (int i = 0; i < nodes_count; ++i) {
        ancestor_chain.clear();
        sibling_nodes.clear();

        int current = i;
        while (node_parent[current] != -1) {
            int parent_idx = node_parent[current];
            if (tree_edges[parent_idx].first == current) {
                sibling_nodes.push_back(tree_edges[parent_idx].second);
            } else {
                sibling_nodes.push_back(tree_edges[parent_idx].first);
            }
            current = parent_idx;
        }

        // --- Scenario: siblings forced to 0 ---
        // Query X: inputs (0,1), siblings 0
        current_assignment = string(2 * nodes_count + 1, '0');
        assign_value(tree_edges[i].first, 0);
        assign_value(tree_edges[i].second, 1);
        for (int node : sibling_nodes) {
            assign_value(node, 0);
        }
        int res_X = perform_query(current_assignment);

        // Query Y: inputs (0,0), siblings 0
        current_assignment = string(2 * nodes_count + 1, '0');
        assign_value(tree_edges[i].first, 0);
        assign_value(tree_edges[i].second, 0);
        for (int node : sibling_nodes) {
            assign_value(node, 0);
        }
        int res_Y = perform_query(current_assignment);
        bool diff_under_0 = (res_X != res_Y);

        // --- Scenario: siblings forced to 1 ---
        // Query Z: inputs (0,1), siblings 1
        current_assignment = string(2 * nodes_count + 1, '0');
        assign_value(tree_edges[i].first, 0);
        assign_value(tree_edges[i].second, 1);
        for (int node : sibling_nodes) {
            assign_value(node, 1);
        }
        int res_Z = perform_query(current_assignment);

        // Query W: inputs (0,0), siblings 1
        current_assignment = string(2 * nodes_count + 1, '0');
        assign_value(tree_edges[i].first, 0);
        assign_value(tree_edges[i].second, 0);
        for (int node : sibling_nodes) {
            assign_value(node, 1);
        }
        int res_W = perform_query(current_assignment);
        bool diff_under_1 = (res_Z != res_W);

        // If any scenario shows sensitivity to input change, gate is OR; otherwise AND
        if (diff_under_0 || diff_under_1) {
            result[i] = '|';
        } else {
            result[i] = '&';
        }
    }

    cout << "! " << result << endl;
    return 0;
}

#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

// Structure representing a搬运 operation
struct Operation {
    int box_value;
    int target_stack;
};

int main() {
    // Speed up input/output operations
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int total_boxes, num_stacks;
    if (!(cin >> total_boxes >> num_stacks)) return 0;

    // Stacks are 1-indexed (stacks[0] unused)
    vector<vector<int>> stacks(num_stacks + 1);

    // Initialize each stack with n/m boxes
    for (int s = 1; s <= num_stacks; ++s) {
        for (int b = 0; b < total_boxes / num_stacks; ++b) {
            int value;
            cin >> value;
            stacks[s].push_back(value);
        }
    }

    vector<Operation> operations;
    int next_target = 1;

    // Process all boxes in order from 1 to n
    while (next_target <= total_boxes) {
        int src_stack = -1;
        int box_position = -1;

        // Find the current target box
        for (int s = 1; s <= num_stacks; ++s) {
            for (int pos = 0; pos < stacks[s].size(); ++pos) {
                if (stacks[s][pos] == next_target) {
                    src_stack = s;
                    box_position = pos;
                    break;
                }
            }
            if (src_stack != -1) break;
        }

        // If box is at top of stack, remove it directly
        if (box_position == (int)stacks[src_stack].size() - 1) {
            operations.push_back({next_target, 0});
            stacks[src_stack].pop_back();
            next_target++;
            continue;
        }

        // Calculate how many boxes are above the target
        int boxes_above = stacks[src_stack].size() - 1 - box_position;

        int best_chunk_size = -1;
        int best_destination = -1;
        long long highest_score = -2e18;

        // Try all possible chunk sizes
        for (int chunk_size = 1; chunk_size <= boxes_above; ++chunk_size) {
            int start_index = stacks[src_stack].size() - chunk_size;

            // Find maximum value in this chunk
            int max_in_chunk = -1;
            for (int k = 0; k < chunk_size; ++k) {
                max_in_chunk = max(max_in_chunk, stacks[src_stack][start_index + k]);
            }

            // Evaluate each possible destination stack
            for (int dest = 1; dest <= num_stacks; ++dest) {
                if (dest == src_stack) continue;

                int top_of_dest = stacks[dest].empty() ? 1000 : stacks[dest].back();

                long long score;

                if (max_in_chunk < top_of_dest) {
                    // Valid move: maintain decreasing order
                    score = 200000LL + (long long)chunk_size * 1000 - (top_of_dest - max_in_chunk);
                } else {
                    // Invalid move: place larger on smaller
                    score = (long long)top_of_dest * 1000 + chunk_size;
                }

                if (score > highest_score) {
                    highest_score = score;
                    best_chunk_size = chunk_size;
                    best_destination = dest;
                }
            }
        }

        // Execute the best move
        int move_start = stacks[src_stack].size() - best_chunk_size;
        int first_moved_box = stacks[src_stack][move_start];

        operations.push_back({first_moved_box, best_destination});

        // Transfer boxes
        vector<int> transferred;
        transferred.reserve(best_chunk_size);
        for (int k = 0; k < best_chunk_size; ++k) {
            transferred.push_back(stacks[src_stack][move_start + k]);
        }

        stacks[src_stack].resize(move_start);
        for (int val : transferred) {
            stacks[best_destination].push_back(val);
        }
    }

    // Print all operations
    for (const auto& op : operations) {
        cout << op.box_value << " " << op.target_stack << "\n";
    }

    return 0;
}

#define UCLN_TYPE_IS_COMMON
#include "ucln_imp.h"
static cleanupFunc *gCommonCleanupRoutines[UCLN_COMMON_COUNT];
static cleanupFunc *gLibraryCleanupRoutines[UCLN_COMMON];
/************************************************
 The cleanup sequence is critical in this function.
 Ensure you have reviewed ucln.h before proceeding.
 ************************************************/
U_CAPI void U_EXPORT2
u_cleanup()
{
    UTRACE_ENTRY_OC(UTRACE_U_CLEANUP);
    icu::umtx_lock(nullptr);     /* Enforce a memory barrier to guarantee visibility of   */
    icu::umtx_unlock(nullptr);   /*   any remaining state from other threads.            */
    ucln_library_cleanup();
    cmemory_cleanup();       /* Revert any heap functions previously set via u_setMemoryFunctions(). */
    UTRACE_EXIT();           /* Must precede utrace_cleanup(), which disables tracing. */
/*#if U_ENABLE_TRACING*/
    utrace_cleanup();
/*#endif*/
}
U_CAPI void U_EXPORT2 ucln_cleanupOne(ECleanupLibraryType libType) 
{
    if (gLibraryCleanupRoutines[libType])
    {
        gLibraryCleanupRoutines[libType]();
        gLibraryCleanupRoutines[libType] = nullptr;
    }
}
U_CFUNC void
ucln_common_registerCleanup(ECleanupCommonType type,
                            cleanupFunc *func)
{
    // Thread safety considerations: As per ticket 10295, registerCleanup() calls might happen
    // concurrently. Although they should assign identical values, the thread sanity checker
    // flags such access. Wrapping the assignment in a mutex avoids these warnings.
    // HOWEVER, this may cause recursive entry into std::call_once() in umutex.cpp when this
    // code—executing within call_once—tries to acquire the ICU global mutex, re-entering the
    // mutex initialization path. Thus, we bypass this by specifically handling UCLN_COMMON_MUTEX,
    // avoiding use of the ICU global mutex for it.
    //
    // No other part of ICU utilizes std::call_once().
    U_ASSERT(UCLN_COMMON_START < type && type < UCLN_COMMON_COUNT);
    if (type == UCLN_COMMON_MUTEX) {
        gCommonCleanupRoutines[type] = func;
    } else if (UCLN_COMMON_START < type && type < UCLN_COMMON_COUNT)  {
        icu::Mutex m;     // Refer to ticket 10295 for further details.
        gCommonCleanupRoutines[type] = func;
    }
#if !UCLN_NO_AUTO_CLEANUP && (defined(UCLN_AUTO_ATEXIT) || defined(UCLN_AUTO_LOCAL))
    ucln_registerAutomaticCleanup();
#endif
}
// Note: ucln_registerCleanup() executes while holding the ICU global mutex.
//       Exercise caution when modifying this function.
//       See ticket 10295 for context.
U_CAPI void U_EXPORT2
ucln_registerCleanup(ECleanupLibraryType type,
                     cleanupFunc *func)
{
    U_ASSERT(UCLN_START < type && type < UCLN_COMMON);
    if (UCLN_START < type && type < UCLN_COMMON)
    {
        gLibraryCleanupRoutines[type] = func;
    }
}
U_CFUNC UBool ucln_library_cleanup() {
    int32_t libType = UCLN_START;
    int32_t commonRoutine = UCLN_COMMON_START;
    for (libType++; libType<UCLN_COMMON; libType++) {
        ucln_cleanupOne(static_cast<ECleanupLibraryType>(libType));
    }
    for (commonRoutine++; commonRoutine<UCLN_COMMON_COUNT; commonRoutine++) {
        if (gCommonCleanupRoutines[commonRoutine])
        {
            gCommonCleanupRoutines[commonRoutine]();
            gCommonCleanupRoutines[commonRoutine] = nullptr;
        }
    }
#if !UCLN_NO_AUTO_CLEANUP && (defined(UCLN_AUTO_ATEXIT) || defined(UCLN_AUTO_LOCAL))
    ucln_unRegisterAutomaticCleanup();
#endif
    return true;
}

