double time_diff(double& start_time) {
  const auto end_time =
    std::chrono::system_clock::now().time_since_epoch().count() / 1e6;
  const double delta = end_time - start_time;
  start_time = end_time;
  return delta;
}

using namespace irs;

TEST(Faiss, VectorIndexingDemo) {
  double start_time = 0.0;
  time_diff(start_time);

  // dimensionality of each vector
  int vec_dim = 128;

  // number of training vectors
  size_t num_train = 100 * 1000;
  std::vector<float> training_data(num_train * vec_dim);

  auto index_type = absl::StrCat("IVF1024,PQ32x4fs");
  auto* raw_index = index_factory(vec_dim, index_type.c_str(), faiss::MetricType::METRIC_L2);
  ASSERT_TRUE(raw_index);

  auto& ivf_index = dynamic_cast<faiss::IndexIVF&>(*raw_index);

  std::mt19937 random_generator;

  {  // Training phase
    printf("[%.3f s] Creating %ld training samples with dimension %d\n", time_diff(start_time),
           num_train, vec_dim);

    std::uniform_real_distribution<> uniform_dist(0.0, 1.0);
    for (size_t idx = 0; idx < num_train * vec_dim; ++idx) {
      training_data[idx] = uniform_dist(random_generator);
    }

    printf("[%.3f s] Initiating index training\n", time_diff(start_time));
    ivf_index.train(num_train, training_data.data());
  }

  size_t num_queries;
  std::vector<float> query_vectors;

  // Reuse training data count as database size
  size_t db_size = std::exchange(num_train, 0);
  std::vector<float> database_vectors = std::move(training_data);

  {  // Database population
    printf("[%.3f s] Constructing dataset of %ld vectors for indexing\n", time_diff(start_time),
           db_size);

    std::uniform_real_distribution<> uniform_dist(0.0, 1.0);
    for (size_t idx = 0; idx < db_size * vec_dim; ++idx) {
      database_vectors[idx] = uniform_dist(random_generator);
    }

    printf("[%.3f s] Inserting vectors into the index\n", time_diff(start_time));
    ivf_index.add(db_size, database_vectors.data());

    printf("[%.3f s] Index imbalance metric: %g\n", time_diff(start_time),
           ivf_index.invlists->imbalance_factor());

    // Extract specific entries as queries
    int first_query_idx = 1234;
    int last_query_idx = 1243;
    num_queries = last_query_idx - first_query_idx;
    query_vectors.resize(num_queries * vec_dim);

    for (int q = first_query_idx; q < last_query_idx; ++q) {
      for (int dim = 0; dim < vec_dim; ++dim) {
        query_vectors[(q - first_query_idx) * vec_dim + dim] = 
          database_vectors[q * vec_dim + dim];
      }
    }
  }

  ivf_index.nprobe = 4;

  {  // Search execution
    int top_k = 5;
    printf(
      "[%.3f s] Executing k-NN search for %d nearest neighbors "
      "of %ld query vectors\n",
      time_diff(start_time), top_k, num_queries);

    std::vector<faiss::idx_t> neighbor_ids(top_k * num_queries);
    std::vector<float> distances(top_k * num_queries);

    ivf_index.search(num_queries, query_vectors.data(), top_k, 
                     distances.data(), neighbor_ids.data());

    printf("[%.3f s] Search outcomes (IDs followed by distances):\n",
           time_diff(start_time));

    for (size_t q = 0; q < num_queries; ++q) {
      printf("query %2zu: ", q);
      for (int k = 0; k < top_k; ++k) {
        printf("%7ld ", neighbor_ids[k + q * top_k]);
      }
      printf("\n   dist: ");
      for (int k = 0; k < top_k; ++k) {
        printf("%7g ", distances[k + q * top_k]);
      }
      printf("\n");
    }

    printf(
      "note: the closest neighbor may not have zero distance due to "
      "approximation introduced by compression\n");
  }

  {  // Save index without posting lists
    const char* filename_no_postings = "/tmp/faiss_index_no_postings";
    printf("[%.3f s] Saving pre-trained index to %s\n", time_diff(start_time),
           filename_no_postings);

    ivf_index.replace_invlists(nullptr, true);
    faiss::write_index(&ivf_index, filename_no_postings);
  }

  {  // Save index with posting lists
    const char* filename_with_postings = "/tmp/faiss_index_with_postings";
    printf("[%.3f s] Preserving full index to %s\n", time_diff(start_time),
           filename_with_postings);

    faiss::write_index(&ivf_index, filename_with_postings);
  }

  delete raw_index;
}

