// Entry point for launching a target application and injecting a DLL
// Usage: rundll32.exe zzz_display_commander.addon64,LaunchAndInject "C:\Path\To\application.exe"
extern "C" __declspec(dllexport) void CALLBACK LaunchAndInject(HWND hwnd, HINSTANCE hInst, LPSTR lpszCmdLine,
                                                               int nCmdShow) {
    UNREFERENCED_PARAMETER(hwnd);
    UNREFERENCED_PARAMETER(hInst);
    UNREFERENCED_PARAMETER(nCmdShow);

    // Initialize logging configuration
    display_commander::config::DisplayCommanderConfigManager::GetInstance().Initialize();
    display_commander::config::DisplayCommanderConfigManager::GetInstance().SetAutoFlushLogs(true);

    // Extract executable path from command line arguments
    std::string target_exe_ansi;
    if (lpszCmdLine != nullptr && strlen(lpszCmdLine) > 0) {
        target_exe_ansi = lpszCmdLine;
        // Strip surrounding quotes if present
        if (target_exe_ansi.length() >= 2 && target_exe_ansi.front() == '"' && target_exe_ansi.back() == '"') {
            target_exe_ansi = target_exe_ansi.substr(1, target_exe_ansi.length() - 2);
        }
    }

    if (target_exe_ansi.empty()) {
        OutputDebugStringA(
            "LaunchAndInject: No executable path specified. Expected format: "
            "rundll32.exe zzz_display_commander.addon64,LaunchAndInject \"C:\\Path\\To\\app.exe\"");
        return;
    }

    // Convert ANSI string to wide character string
    int required_size = MultiByteToWideChar(CP_ACP, 0, target_exe_ansi.c_str(), -1, nullptr, 0);
    if (required_size <= 0) {
        OutputDebugStringA("LaunchAndInject: Unable to convert executable path to wide string");
        return;
    }

    std::vector<wchar_t> exe_path_wide(required_size);
    MultiByteToWideChar(CP_ACP, 0, target_exe_ansi.c_str(), -1, exe_path_wide.data(), required_size);
    std::wstring exe_path(exe_path_wide.data());

    // Validate that the executable exists
    if (!std::filesystem::exists(exe_path)) {
        OutputDebugStringA(std::format("LaunchAndInject: Executable not found: {}", target_exe_ansi).c_str());
        return;
    }

    OutputDebugStringA(std::format("LaunchAndInject: Launching process: {}", target_exe_ansi).c_str());

    // Create the new process
    STARTUPINFOW startup_info = {};
    PROCESS_INFORMATION process_info = {};
    startup_info.cb = sizeof(startup_info);

    std::wstring cmd_line = L"\"" + exe_path + L"\"";
    if (!CreateProcessW(nullptr, cmd_line.data(), nullptr, nullptr, FALSE, 0, nullptr, nullptr, &startup_info, &process_info)) {
        DWORD last_error = GetLastError();
        OutputDebugStringA(std::format("LaunchAndInject: Failed to launch process: Error {} (0x{:X})", last_error, last_error).c_str());
        return;
    }

    // Close thread handle as it's not needed
    CloseHandle(process_info.hThread);
    OutputDebugStringA(std::format("LaunchAndInject: Process launched with PID {}", process_info.dwProcessId).c_str());

    // Allow time for process initialization
    Sleep(500);

    // Determine if process is running under WoW64
    BOOL is_wow64 = FALSE;
    IsWow64Process(process_info.hProcess, &is_wow64);

    // Locate appropriate ReShade DLL
    std::wstring dll_location = GetReShadeDllPath(is_wow64 != FALSE);
    if (dll_location.empty()) {
        OutputDebugStringA("LaunchAndInject: Could not locate ReShade DLL");
        CloseHandle(process_info.hProcess);
        return;
    }

    // Perform injection
    bool injected = InjectIntoProcess(process_info.dwProcessId, dll_location);
    CloseHandle(process_info.hProcess);

    if (injected) {
        OutputDebugStringA(std::format("LaunchAndInject: Successfully launched and injected into process (PID {})",
                                       process_info.dwProcessId)
                               .c_str());
    } else {
        OutputDebugStringA(std::format("LaunchAndInject: Injection failed for process (PID {})", process_info.dwProcessId).c_str());
    }
}

// Entry point for monitoring and injecting into newly created processes
// Usage: rundll32.exe zzz_display_commander.addon64,MonitorAndInject "target_app.exe"
extern "C" __declspec(dllexport) void CALLBACK MonitorAndInject(HWND hwnd, HINSTANCE hInst, LPSTR lpszCmdLine,
                                                                int nCmdShow) {
    UNREFERENCED_PARAMETER(hwnd);
    UNREFERENCED_PARAMETER(hInst);
    UNREFERENCED_PARAMETER(nCmdShow);

    // Setup logging
    display_commander::config::DisplayCommanderConfigManager::GetInstance().Initialize();
    display_commander::config::DisplayCommanderConfigManager::GetInstance().SetAutoFlushLogs(true);

    // Parse target executable name from command line
    std::string target_name_ansi;
    if (lpszCmdLine != nullptr && strlen(lpszCmdLine) > 0) {
        target_name_ansi = lpszCmdLine;
        // Remove surrounding quotes if present
        if (target_name_ansi.length() >= 2 && target_name_ansi.front() == '"' && target_name_ansi.back() == '"') {
            target_name_ansi = target_name_ansi.substr(1, target_name_ansi.length() - 2);
        }
    }

    if (target_name_ansi.empty()) {
        OutputDebugStringA(
            "MonitorAndInject: No executable name provided. Expected format: "
            "rundll32.exe zzz_display_commander.addon64,MonitorAndInject \"target_app.exe\"");
        return;
    }

    // Convert to wide string
    int wide_len = MultiByteToWideChar(CP_ACP, 0, target_name_ansi.c_str(), -1, nullptr, 0);
    if (wide_len <= 0) {
        OutputDebugStringA("MonitorAndInject: Conversion to wide string failed");
        return;
    }

    std::vector<wchar_t> exe_name_wide(wide_len);
    MultiByteToWideChar(CP_ACP, 0, target_name_ansi.c_str(), -1, exe_name_wide.data(), wide_len);
    std::wstring exe_name(exe_name_wide.data());

    // Extract just the filename portion
    std::filesystem::path full_path(exe_name);
    std::wstring base_name = full_path.filename().wstring();

    OutputDebugStringA(std::format("MonitorAndInject: Monitoring for process: {} (normalized: {})", target_name_ansi,
                                   std::string(base_name.begin(), base_name.end()))
                           .c_str());

    std::cout << "MonitorAndInject: Waiting for process: " << target_name_ansi
              << " (matching against: " << std::string(base_name.begin(), base_name.end()) << ")" << std::endl;

    // Begin monitoring and auto-injecting when process starts
    WaitForProcessAndInject(base_name);
}

