typedef std::filesystem::path fspath;

// Compare two entity nodes recursively for equality
void ReserialCompare(EntNode& nodeA, EntNode& nodeB)
{
    assert(nodeA.getFlags() == nodeB.getFlags());
    assert(nodeA.getChildCount() == nodeB.getChildCount());
    assert(nodeA.NameLength() == nodeB.NameLength());
    assert(memcmp(nodeA.NamePtr(), nodeB.NamePtr(), nodeA.NameLength()) == 0);

    // MONITOR: It seems our floating point conversion is round-trip.
    // But if this changes we'll start getting errors here
    assert(nodeA.ValueLength() == nodeB.ValueLength());
    assert(memcmp(nodeA.ValuePtr(), nodeB.ValuePtr(), nodeA.ValueLength()) == 0);

    for (int idx = 0; idx < nodeA.getChildCount(); ++idx) {
        ReserialCompare(*nodeA.ChildAt(idx), *nodeB.ChildAt(idx));
    }
}

// Special comparison for mapentities root nodes due to header chunk differences
void ReserialCompare_MapRoot(EntNode& originalRoot, EntNode& transformedRoot)
{
    // Adjust comparison since meta section isn't serialized anymore
    if (originalRoot.getChildCount() == transformedRoot.getChildCount()) {
        for(int i = 0; i < originalRoot.getChildCount() - 1; ++i) {
            ReserialCompare(originalRoot[i], transformedRoot[i]);
        }
    }
    else {
        assert(originalRoot.getChildCount() - 1 == transformedRoot.getChildCount());
        assert(originalRoot[0].getName() == "metadata");
        assert(transformedRoot[0].getName() != "metadata");

        for (int i = 1; i < originalRoot.getChildCount() - 1; ++i) {
            ReserialCompare(originalRoot[i], transformedRoot[i-1]);
        }
    }

    // Handle final header chunk specially
    EntNode& lastOriginal = originalRoot[originalRoot.getChildCount() - 1];
    EntNode& lastTransformed = transformedRoot[transformedRoot.getChildCount() - 1];

    if (lastOriginal.getName() != "headerchunk") {
        assert(lastTransformed.getName() != "headerchunk");
        ReserialCompare(lastOriginal, lastTransformed);
    }
    else {
        assert(lastOriginal.getChildCount() == lastTransformed.getChildCount());
        // Skip first line as it's modified during serialization
        for (int i = 1; i < lastOriginal.getChildCount(); ++i) {
            ReserialCompare(lastOriginal[i], lastTransformed[i]);
        }
    }
}

// Run test on files in a directory with given extension and resource type
void RunTest(const fspath& dirPath, const fspath& fileExt, ResourceType resType)
{
    using namespace std::filesystem;
    std::vector<fspath> foundFiles;

    for (const directory_entry& entry : recursive_directory_iterator(dirPath)) {
        if(is_directory(entry))
            continue;
        if (entry.path().extension() == fileExt)
            foundFiles.push_back(entry.path());
    }

    std::cout << "Testing " << foundFiles.size() << " files in " << dirPath << "\n";
    int count = 0;

    for (const fspath& filePath : foundFiles) {
        std::cout << filePath << "\n";

        // Read original file into EntityParser
        EntityParser original(filePath.string(), ParsingMode::PERMISSIVE);
        BinaryWriter serializer(static_cast<size_t>(file_size(filePath) * 1.1));

        // Serialize the parsed data
        int warnings = Reserializer::Serialize(*original.getRoot(), serializer, resType, 
                                              original.eofblob, original.eofbloblength);
        if (warnings != 0) {
            std::cout << filePath << "\n";
        }

        // Deserialize again from serialized buffer
        BinaryReader reader(serializer.GetBuffer(), serializer.GetFilledSize());
        std::string outputString;
        outputString.reserve(10000);
        Deserializer::DeserialSingle(reader, outputString, resType);

        // Read deserialized content into new parser
        EntityParser second(ParsingMode::PERMISSIVE, std::string_view(outputString), false);

        // Perform appropriate comparison based on resource type
        if (resType == rt_mapentities) {
            ReserialCompare_MapRoot(*original.getRoot(), *second.getRoot());
        }
        else {
            ReserialCompare(*original.getRoot(), *second.getRoot());
        }

        ++count;
    }
}

