BleKeyboard::BleKeyboard(String keyboardName, String manufacturerName, uint8_t batteryValue)
    : hid(0), deviceName(String(keyboardName).substring(0, 15)),
      deviceManufacturer(String(manufacturerName).substring(0, 15)), batteryLevel(batteryValue) {}

void BleKeyboard::begin(const uint8_t *layout, uint16_t showAs) {
    appearance = showAs;
    _asciimap = layout;
    BLEDevice::init(deviceName.c_str());
    pServer = BLEDevice::createServer();
    pServer->setCallbacks(this);
    hid = new BLEHIDDevice(pServer);
    inputKeyboard = hid->inputReport(KEYBOARD_REPORT_ID); // <-- input REPORTID from report map
    outputKeyboard = hid->outputReport(KEYBOARD_REPORT_ID);
    inputMediaKeys = hid->inputReport(MEDIA_REPORT_ID);
    inputKeyboard->setCallbacks(this);
    outputKeyboard->setCallbacks(this);
    inputMediaKeys->setCallbacks(this);
    hid->manufacturer()->setValue(deviceManufacturer);
    hid->pnp(0x02, vid, pid, version);
    hid->hidInfo(0x00, 0x01);
#if defined(USE_NIMBLE)
    BLEDevice::setSecurityAuth(true, true, true);
#else
    BLESecurity *pSecurity = new BLESecurity();
    pSecurity->setAuthenticationMode(ESP_LE_AUTH_REQ_SC_MITM_BOND);
#endif // USE_NIMBLE
    hid->reportMap((uint8_t *)_hidReportDescriptor, sizeof(_hidReportDescriptor));
    hid->startServices();
    onStarted(pServer);
    advertising = pServer->getAdvertising();
    advertising->setAppearance(appearance);
    if (_randUUID) { // this workaround makes 2 Bruce connect and work on the same Android device
        advertising->addServiceUUID(BLEUUID((uint16_t)(ESP.getEfuseMac() & 0xFFFF)));
    } else {
        advertising->addServiceUUID(hid->hidService()->getUUID());
    }
    advertising->setScanResponse(false);
    advertising->start();
    hid->setBatteryLevel(batteryLevel);
}

void BleKeyboard::end(void) {
    int count = 0;
    count = pServer->getConnectedCount();
    if (count > 0) {
        int index;
        for (index = 0; index < count; index++) pServer->disconnect(pServer->getPeerInfo(count).getConnHandle());
    }
    delete hid;
    BLEDevice::deinit();
    this->connected = false;
}

bool BleKeyboard::isConnected(void) { return this->connected; }

void BleKeyboard::setBatteryLevel(uint8_t level) {
    this->batteryLevel = level;
    if (hid != 0) this->hid->setBatteryLevel(this->batteryLevel);
}

