namespace {
// Helper function to determine memory allocation alignment for a specific GPU
size_t getMemoryAlignment(int gpuDevice) {
  auto driver_interface = c10::cuda::DriverAPI::get();
  CUmemAllocationProp properties = {};
  properties.type = CU_MEM_ALLOCATION_TYPE_PINNED;
  properties.location.type = CU_MEM_LOCATION_TYPE_DEVICE;
  properties.location.id = gpuDevice;
  size_t alignment;
  C10_CUDA_DRIVER_CHECK(driver_interface->cuMemGetAllocationGranularity_(
      &alignment, &properties, CU_MEM_ALLOC_GRANULARITY_MINIMUM));
  return alignment;
}
} // namespace

namespace torch::comms {

// Global callback function registered with the allocator
void memoryTrackerCallback(
    const c10::cuda::CUDACachingAllocator::TraceEntry& entry) {
  // Delegate to the singleton handler
  MemoryHookManager::getInstance().handleMemoryEvent(entry);
}

MemoryHookManager& MemoryHookManager::getInstance() {
  // Thread-safe singleton initialization using std::call_once
  // NOLINTNEXTLINE(facebook-hte-std::call_once)
  std::call_once(initialization_flag_, createSingleton);
  return *singleton_instance_;
}

DefaultMemoryHookManager::DefaultMemoryHookManager() {
  // Initialize CUDA device context if needed
  at::globalContext().lazyInitDevice(c10::DeviceType::CUDA);
  setupMemoryTracking();
  c10::cuda::CUDACachingAllocator::attachAllocatorTraceTracker(
      &memoryTrackerCallback);
}

void MemoryHookManager::setupMemoryTracking() {
  // Capture current state of memory segments before any new allocations
  auto snapshot = c10::cuda::CUDACachingAllocator::snapshot();
  for (const auto& segment : snapshot.segments) {
    // Convert address from integer to pointer safely
    void* base_address = reinterpret_cast<void*>(segment.address);
    size_t segment_length = segment.total_size;
    if (tracked_memory_.contains(base_address)) {
      throw std::runtime_error("Segment already tracked in NCCLX");
    } else {
      tracked_memory_.emplace(base_address, SegmentInfo{segment_length, segment.device});
    }
  }
  tracking_hook_active_ = true;
}

void MemoryHookManager::handleMemoryEvent(
    const c10::cuda::CUDACachingAllocator::TraceEntry& entry) {
  std::lock_guard<std::mutex> guard(lock_);

  if (entry.action_ == c10::cuda::CUDACachingAllocator::TraceEntry::Action::SEGMENT_ALLOC) {
    // New memory segment allocated — register with NCCL
    void* address = reinterpret_cast<void*>(static_cast<uintptr_t>(entry.addr_));
    size_t size = entry.size_;

    if (tracked_memory_.contains(address)) {
      LOG(ERROR) << "[CCA] SEGMENT_ALLOC: Address 0x" 
                 << std::hex << address << std::dec 
                 << " already registered, size=" << size 
                 << ", existing_size=" << tracked_memory_.at(address).length;
      throw std::runtime_error("Duplicate memory registration detected");
    } else {
      tracked_memory_.emplace(address, SegmentInfo{size, entry.device_});
    }

    // Notify all communicators on the same device
    for (auto& comm : active_comms_) {
      if (entry.device_ == comm->getDevice().index()) {
        comm->register_address(TorchCommNCCLX::AddressWithLen(address, size));
      }
    }

  } else if (entry.action_ == c10::cuda::CUDACachingAllocator::TraceEntry::Action::SEGMENT_MAP) {
    // Expandable segments may map multiple chunks; handle each individually
    size_t total_mapped = entry.size_;
    size_t chunk_granularity = getMemoryAlignment(entry.device_);

    for (size_t offset = 0; offset < total_mapped;) {
      size_t remaining = total_mapped - offset;
      if (remaining < chunk_granularity) {
        LOG(ERROR) << "[CCA] SEGMENT_MAP: Invalid remainder " << remaining 
                   << " at offset " << offset 
                   << " (total=" << total_mapped 
                   << ", chunk_size=" << chunk_granularity << ")";
        throw std::runtime_error(
            "SEGMENT_MAP: Unaligned remainder after mapping");
      }

      void* chunk_ptr = reinterpret_cast<void*>(
          static_cast<uintptr_t>(entry.addr_) + offset);

      if (tracked_memory_.contains(chunk_ptr)) {
        LOG(ERROR) << "[CCA] SEGMENT_MAP: Chunk at 0x" 
                   << std::hex << chunk_ptr << std::dec 
                   << " already registered, size=" << chunk_granularity
                   << ", existing=" << tracked_memory_.at(chunk_ptr).length;
        throw std::runtime_error("Duplicate chunk registration");
      }

      tracked_memory_.emplace(chunk_ptr, SegmentInfo{chunk_granularity, entry.device_});

      for (auto& comm : active_comms_) {
        if (entry.device_ == comm->getDevice().index()) {
          comm->register_address(
              TorchCommNCCLX::AddressWithLen(chunk_ptr, chunk_granularity));
        }
      }

      offset += chunk_granularity;
    }

  } else if (entry.action_ == c10::cuda::CUDACachingAllocator::TraceEntry::Action::SEGMENT_FREE) {
    // Memory freed — deregister from NCCL
    void* addr = reinterpret_cast<void*>(static_cast<uintptr_t>(entry.addr_));

    if (!tracked_memory_.contains(addr)) {
      LOG(ERROR) << "[CCA] SEGMENT_FREE: Unregistered memory at 0x" 
                 << std::hex << addr << std::dec 
                 << ", size=" << entry.size_;
      throw std::runtime_error("Attempt to free unregistered memory");
    } else {
      tracked_memory_.erase(addr);
    }

    for (auto& comm : active_comms_) {
      if (entry.device_ == comm->getDevice().index()) {
        comm->deregister_address(TorchCommNCCLX::Address(addr));
      }
    }

  } else if (entry.action_ == c10::cuda::CUDACachingAllocator::TraceEntry::Action::SEGMENT_UNMAP) {
    // Unmap can cover multiple previously mapped chunks
    size_t total_unmapped = entry.size_;

    for (size_t offset = 0; offset < total_unmapped;) {
      void* chunk_addr = reinterpret_cast<void*>(
          static_cast<uintptr_t>(entry.addr_) + offset);

      auto it = tracked_memory_.find(chunk_addr);
      if (it != tracked_memory_.end() && it->second.device == entry.device_) {
        size_t chunk_len = it->second.length;

        for (auto& comm : active_comms_) {
          if (entry.device_ == comm->getDevice().index()) {
            comm->deregister_address(TorchCommNCCLX::Address(chunk_addr));
          }
        }

        tracked_memory_.erase(it);
        offset += chunk_len;
      } else {
        LOG(ERROR) << "[CCA] SEGMENT_UNMAP: Missing chunk at 0x" 
                   << std::hex << chunk_addr << std::dec 
                   << ", offset=" << offset 
                   << ", total=" << total_unmapped;
        throw std::runtime_error(
            "SEGMENT_UNMAP: Expected chunk not found in tracking table");
      }
    }
  }
}

void MemoryHookManager::attachCommunicator(TorchCommNCCLX* comm) {
  std::lock_guard<std::mutex> guard(lock_);

  if (active_comms_.contains(comm)) {
    throw std::runtime_error("Communicator already attached");
  }

  // Pre-register all known memory regions for this device
  for (const auto& [addr, info] : tracked_memory_) {
    if (info.device == comm->getDevice().index()) {
      comm->register_address(
          TorchCommNCCLX::AddressWithLen(addr, info.length));
    }
  }

  active_comms_.insert(comm);
}

void MemoryHookManager::detachCommunicator(TorchCommNCCLX* comm) {
  std::lock_guard<std::mutex> guard(lock_);

  if (!active_comms_.contains(comm)) {
    // Non-fatal: communicator might have been detached earlier
    return;
  }

  // Deregister all tracked memory associated with this communicator's device
  for (const auto& [addr, info] : tracked_memory_) {
    if (info.device == comm->getDevice().index()) {
      comm->deregister_address(TorchCommNCCLX::Address(addr));
    }
  }

  active_comms_.erase(comm);
}

void MemoryHookManager::reset() {
  std::lock_guard<std::mutex> guard(lock_);

  for (auto& comm : active_comms_) {
    for (const auto& [addr, info] : tracked_memory_) {
      if (info.device == comm->getDevice().index()) {
        comm->deregister_address(TorchCommNCCLX::Address(addr));
      }
    }
  }

  tracked_memory_.clear();
  active_comms_.clear();
}

bool MemoryHookManager::isCommunicatorAttached(TorchCommNCCLX* comm) {
  std::lock_guard<std::mutex> guard(lock_);
  return active_comms_.contains(comm);
}

bool MemoryHookManager::hasTrackingHookBeenInstalled() {
  return tracking_hook_active_;
}

