__global__ void
matrix_transpose_kernel(const int* src, int* dst, int height, int width)
{
    __shared__ int tile[cache_tile_size][cache_tile_size];

    int row = blockIdx.y * blockDim.y + threadIdx.y;
    int col = blockIdx.x * blockDim.x + threadIdx.x;
    int idx = row * height + col;

    tile[threadIdx.y][threadIdx.x] = src[idx];
    __syncthreads();

    // Transposed access: (col, row)
    int t_row = blockIdx.x * blockDim.x + threadIdx.y;
    int t_col = blockIdx.y * blockDim.y + threadIdx.x;
    int t_idx = t_row * width + t_col;

    dst[t_idx] = tile[threadIdx.x][threadIdx.y];
}

void
execute_transpose_task(int process_rank, int thread_id, int device_idx, size_t repeat_count, size_t sync_interval)
{
    roctxRangePush("execute_transpose_task");

    constexpr unsigned int ROWS = 5000 * 2;
    constexpr unsigned int COLS = 5000 * 2;

    hipStream_t stream{};
    printf("[transpose] Rank %i, thread %i assigned to device %i\n", process_rank, thread_id, device_idx);

    HIP_CHECK(hipSetDevice(device_idx));
    HIP_CHECK(hipStreamCreate(&stream));

    {
        lock_guard_t lk{device_print_mutex};
        std::cout << "[transpose][" << process_rank << "][" << thread_id << "] Matrix size: "
                  << ROWS << " x " << COLS << std::endl;
    }

    std::default_random_engine engine{std::random_device{}() * (process_rank + 1) * (thread_id + 1)};
    std::uniform_int_distribution<int> dist{0, 1000};

    size_t bytes = sizeof(int) * ROWS * COLS;
    int* host_input  = new int[bytes];
    int* host_output = new int[bytes];

    for(size_t i = 0; i < ROWS * COLS; ++i)
    {
        host_input[i]  = dist(engine);
        host_output[i] = 0;
    }

    int* device_input  = nullptr;
    int* device_output = nullptr;

    HIP_CHECK(hipMalloc(&device_input, bytes));
    HIP_CHECK(hipMalloc(&device_output, bytes));
    HIP_CHECK(hipMemsetAsync(device_input, 0, bytes, stream));
    HIP_CHECK(hipMemsetAsync(device_output, 0, bytes, stream));
    HIP_CHECK(hipMemcpyAsync(device_input, host_input, bytes, hipMemcpyHostToDevice, stream));
    HIP_CHECK(hipStreamSynchronize(stream));

    dim3 grid(COLS / cache_tile_size, ROWS / cache_tile_size, 1);
    dim3 block(cache_tile_size, cache_tile_size, 1);

    auto start_time = std::chrono::high_resolution_clock::now();
    for(size_t iter = 0; iter < repeat_count; ++iter)
    {
        matrix_transpose_kernel<<<grid, block, 0, stream>>>(device_input, device_output, ROWS, COLS);
        hip_error_check();
        if(iter % sync_interval == (sync_interval - 1))
            HIP_CHECK(hipStreamSynchronize(stream));
    }
    auto end_time = std::chrono::high_resolution_clock::now();

    HIP_CHECK(hipStreamSynchronize(stream));
    HIP_CHECK(hipMemcpyAsync(host_output, device_output, bytes, hipMemcpyDeviceToHost, stream));

    double elapsed_sec = std::chrono::duration_cast<std::chrono::duration<double>>(end_time - start_time).count();
    double GB_transferred = static_cast<double>(bytes) * repeat_count * 2.0 / (1ULL << 30);

    {
        lock_guard_t lk{device_print_mutex};
        std::cout << "[transpose][" << process_rank << "][" << thread_id << "] Execution time: "
                  << elapsed_sec << " seconds\n";
        std::cout << "[transpose][" << process_rank << "][" << thread_id << "] Throughput: "
                  << (GB_transferred / elapsed_sec) << " GB/s" << std::endl;
    }

    HIP_CHECK(hipStreamSynchronize(stream));
    HIP_CHECK(hipStreamDestroy(stream));

    validate_results(host_input, host_output, ROWS, COLS);

    HIP_CHECK(hipFree(device_input));
    HIP_CHECK(hipFree(device_output));
    delete[] host_input;
    delete[] host_output;

    roctxRangePop();
}

void
hip_error_check()
{
    hipError_t err = hipGetLastError();
    if(err != hipSuccess)
    {
        lock_guard_t lk{device_print_mutex};
        std::cerr << "HIP runtime error: " << hipGetErrorString(err) << std::endl;
        throw std::runtime_error("hip_runtime_error");
    }
}

void
validate_results(int const* input, int const* output, int rows, int cols)
{
    bool mismatch_found = false;
    for(int trial = 0; trial < 10; ++trial)
    {
        int r = rand() % rows;
        int c = rand() % cols;

        int expected = input[r * cols + c];
        int actual   = output[c * rows + r];

        if(expected != actual)
        {
            if(!mismatch_found)
            {
                lock_guard_t lk{device_print_mutex};
                std::cout << "Mismatch at (" << r << ", " << c << "): input=" << expected
                          << ", output=" << actual << "\n";
                mismatch_found = true;
            }
        }
    }
}

void
run_transpose(size_t num_threads, size_t iterations, size_t sync_every)
{
    auto range_id = roctxRangeStart("run_transpose");

    int world_rank = 0;
    int world_size = 1;

    printf("[transpose] Threads per rank: %zu\n", num_threads);
    printf("[transpose] Total iterations: %zu\n", iterations);
    printf("[transpose] Sync every %zu iterations\n", sync_every);

#if defined(USE_MPI)
    MPI_Comm_rank(MPI_COMM_WORLD, &world_rank);
    MPI_Comm_size(MPI_COMM_WORLD, &world_size);
#else
    (void) world_size;
#endif

    int num_devices = 0;
    HIP_CHECK(hipGetDeviceCount(&num_devices));
    printf("[transpose] Available devices: %i\n", num_devices);

    std::vector<int> device_assignment(world_size * num_threads, 0);
    for(size_t t = 0; t < num_threads; ++t)
    {
        for(int r = 0; r < world_size; ++r)
        {
            size_t idx = r * num_threads + t;
            device_assignment[idx] = (idx % num_devices);
        }
    }

    int base_device_idx = world_rank * num_threads;
    std::vector<std::thread> worker_threads{};

    for(size_t t = 1; t < num_threads; ++t)
    {
        worker_threads.emplace_back(
            execute_transpose_task,
            world_rank,
            static_cast<int>(t),
            device_assignment[base_device_idx + t],
            iterations,
            sync_every);
    }

    execute_transpose_task(world_rank, 0, device_assignment[base_device_idx], iterations, sync_every);

    for(auto& th : worker_threads)
        th.join();

#if defined(USE_MPI)
    MPI_Barrier(MPI_COMM_WORLD);
#endif

    roctxRangeStop(range_id);
}

