#include <bits/stdc++.h>
using namespace std;

int size;
vector<vector<int>> graph;
vector<int> indegree;

bool compare(int a, int b) {
    cout << "? " << a << " " << b << endl;
    char response;
    cin >> response;
    return response == '<';
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);

    cin >> size;
    graph.resize(size + 1);
    indegree.assign(size + 1, 0);

    // Process consecutive pairs: (1,2), (2,3), ..., (n-1,n)
    for (int idx = 1; idx < size; ++idx) {
        if (compare(idx, idx + 1)) {
            graph[idx].push_back(idx + 1);
            ++indegree[idx + 1];
        } else {
            graph[idx + 1].push_back(idx);
            ++indegree[idx];
        }
    }

    // Process pairs with gap of 2: (1,3), (3,5), ...
    for (int idx = 1; idx <= size - 2; idx += 2) {
        if (compare(idx, idx + 2)) {
            graph[idx].push_back(idx + 2);
            ++indegree[idx + 2];
        } else {
            graph[idx + 2].push_back(idx);
            ++indegree[idx];
        }
    }

    // Topological sort using min-heap for lexicographically smallest order
    vector<int> topo_order;
    priority_queue<int, vector<int>, greater<int>> min_heap;

    for (int node = 1; node <= size; ++node) {
        if (indegree[node] == 0) min_heap.push(node);
    }

    while (!min_heap.empty()) {
        int current = min_heap.top();
        min_heap.pop();
        topo_order.push_back(current);

        for (int neighbor : graph[current]) {
            if (--indegree[neighbor] == 0) {
                min_heap.push(neighbor);
            }
        }
    }

    // Assign values according to topological order
    vector<int> result(size + 1);
    int current_value = 1;
    for (int pos : topo_order) {
        result[pos] = current_value++;
    }

    cout << "!";
    for (int i = 1; i <= size; ++i) {
        cout << " " << result[i];
    }
    cout << endl;

    return 0;
}

