#include <iostream>
#include <ruckig/ruckig.hpp>
using namespace ruckig;

int main() {
    // Initialize Ruckig OTG and parameter structures
    Ruckig<3> trajectory_generator(0.01);  // control cycle = 10 ms
    InputParameter<3> input_params;
    OutputParameter<3> output_params;

    // Configure initial state
    input_params.current_position = {0.0, 0.0, 0.5};
    input_params.current_velocity = {0.0, -2.2, -0.5};
    input_params.current_acceleration = {0.0, 2.5, -0.5};

    // Set target state
    input_params.target_position = {5.0, -2.0, -3.5};
    input_params.target_velocity = {0.0, -0.5, -2.0};
    input_params.target_acceleration = {0.0, 0.0, 0.5};

    // Define kinematic limits
    input_params.max_velocity = {3.0, 1.0, 3.0};
    input_params.max_acceleration = {3.0, 2.0, 1.0};
    input_params.max_jerk = {4.0, 3.0, 2.0};

    // Execute trajectory generation in control loop
    std::cout << "Time | Joint positions" << std::endl;
    while (trajectory_generator.update(input_params, output_params) == Result::Working) {
        std::cout << output_params.time << " | " << join(output_params.new_position) << std::endl;
        output_params.pass_to_input(input_params);
    }

    // Report final results
    std::cout << "Total trajectory time: " << output_params.trajectory.get_duration() << " [s]." << std::endl;
    return 0;
}

#include "speye.h"
template <typename T>
IGL_INLINE void igl::speye(const int rows, const int cols, Eigen::SparseMatrix<T> & identity_matrix)
{
  // Determine the length of the main diagonal
  int diag_len = (rows < cols ? rows : cols);
  identity_matrix = Eigen::SparseMatrix<T>(rows, cols);
  identity_matrix.reserve(diag_len);
  for(int index = 0; index < diag_len; ++index)
  {
    identity_matrix.insert(index, index) = 1.0;
  }
  identity_matrix.finalize();
}

template <typename T>
IGL_INLINE void igl::speye(const int size, Eigen::SparseMatrix<T> & identity_matrix)
{
  return igl::speye(size, size, identity_matrix);
}

