#include <faiss/utils/utils.h>
#include <fstream>
#include <iostream>
#include <omp.h>
#include <vector>
#include <faiss/IndexFlat.h>
#include <faiss/IndexIVFFlat.h>
#include "bench_utils.h"

int main() {
    const std::string exp_label = "blog_post_1";
    const std::string method_name = "faiss_ivfflat";

#ifdef SMALLER_TEST
    const std::string data_source = "openai";
    const size_t num_vectors = 999000;
    const size_t num_test_queries = 1000;
    const size_t dim = 1536;
    const size_t n_centroids = 10000;
    const std::string input_path = "./data/data_openai.bin";
    const std::string query_path = "./data/data_openai_test.bin";
#else
    const std::string data_source = "cohere";
    const size_t num_vectors = 10000000;
    const size_t num_test_queries = 1000;
    const size_t dim = 1024;
    const size_t n_centroids = 40000;
    const std::string input_path = "./data/data_cohere.bin";
    const std::string query_path = "./data/data_cohere_test.bin";
#endif

    const float sample_ratio = 1.0f;
    const int max_pts_per_cluster = static_cast<int>((num_vectors * sample_ratio) / n_centroids);
    const size_t num_threads = omp_get_max_threads();
    omp_set_num_threads(num_threads);

    std::cout << "=== FAISS IVFFlat Execution on Cohere Dataset (50M) ===" << std::endl;
    std::cout << "Dataset: " << data_source << " (n=" << num_vectors << ", d=" << dim << ")\n";
    std::cout << "n_clusters=" << n_centroids
              << " max_points_per_centroid=" << max_pts_per_cluster
              << " (equivalent to sampling_fraction=" << sample_ratio << ")\n";
    std::cout << "Compilation flags: " << faiss::get_compile_options() << std::endl;

    std::vector<float> dataset_vec;
    dataset_vec.reserve(num_vectors * dim);
    std::ifstream dataset_file(input_path, std::ios::binary);
    if (!dataset_file) {
        std::cerr << "Unable to open file: " << input_path << std::endl;
        return 1;
    }
    dataset_file.read(reinterpret_cast<char*>(dataset_vec.data()), num_vectors * dim * sizeof(float));
    dataset_file.close();

    std::vector<float> query_vec;
    query_vec.reserve(num_test_queries * dim);
    std::ifstream query_file(query_path, std::ios::binary);
    if (!query_file) {
        std::cerr << "Unable to open file: " << query_path << std::endl;
        return 1;
    }
    query_file.read(reinterpret_cast<char*>(query_vec.data()), num_test_queries * dim * sizeof(float));
    query_file.close();

    // Construct IVFFlat index
    faiss::IndexFlatL2 centroid_index(dim);
    faiss::IndexIVFFlat ivf_index(&centroid_index, dim, n_centroids);
    ivf_index.cp.verbose = true;

    // Training phase
    bench_utils::TicToc timer;
    timer.Tic();
    ivf_index.train(num_vectors, dataset_vec.data());
    timer.Toc();
    double training_duration_ms = timer.GetMilliseconds();
    std::cout << "\nTraining finished in " << training_duration_ms << " ms" << std::endl;

    // Index addition phase
    timer.Reset();
    timer.Tic();
    ivf_index.add(num_vectors, dataset_vec.data());
    timer.Toc();
    double insertion_duration_ms = timer.GetMilliseconds();
    std::cout << "Insertion (assignment) completed in " << insertion_duration_ms << " ms" << std::endl;
    std::cout << "Combined time (train + add): " << (training_duration_ms + insertion_duration_ms) << " ms" << std::endl;

    // Recall evaluation if ground truth available
    std::string gt_file_path = bench_utils::get_ground_truth_path(data_source);
    std::ifstream gt_stream(gt_file_path);
    if (gt_stream.good()) {
        gt_stream.close();
        std::cout << "\n--- Recall Evaluation ---" << std::endl;
        std::cout << "Ground truth path: " << gt_file_path << std::endl;
        auto gt_dict = bench_utils::parse_ground_truth_json(gt_file_path);
        std::cout << "Processing " << num_test_queries << " queries (loaded " << gt_dict.size()
                  << " entries from ground truth)" << std::endl;

        // Assign each vector to nearest centroid
        std::vector<faiss::idx_t> cluster_ids(num_vectors);
        std::vector<float> dist_to_centroids(num_vectors);
        const float* centroids_ptr = centroid_index.get_xb();
        centroid_index.search(num_vectors, dataset_vec.data(), 1,
                              dist_to_centroids.data(), cluster_ids.data());

        auto knn_10_metrics = bench_utils::compute_recall(
            gt_dict, cluster_ids, query_vec.data(), centroids_ptr,
            num_test_queries, n_centroids, dim, 10
        );
        bench_utils::print_recall_results(knn_10_metrics, 10);

        auto knn_100_metrics = bench_utils::compute_recall(
            gt_dict, cluster_ids, query_vec.data(), centroids_ptr,
            num_test_queries, n_centroids, dim, 100
        );
        bench_utils::print_recall_results(knn_100_metrics, 100);

        std::unordered_map<std::string, std::string> hyperparams;
        hyperparams["niter"] = std::to_string(ivf_index.cp.niter);
        hyperparams["nredo"] = std::to_string(ivf_index.cp.nredo);
        hyperparams["max_points_per_centroid"] = std::to_string(ivf_index.cp.max_points_per_centroid);
        hyperparams["sampling_fraction"] = std::to_string(sample_ratio);
        hyperparams["verbose"] = ivf_index.cp.verbose ? "true" : "false";
        hyperparams["training_time"] = std::to_string(training_duration_ms);
        hyperparams["assignment_time"] = std::to_string(insertion_duration_ms);

        bench_utils::write_results_to_csv(
            exp_label,
            method_name,
            data_source,
            ivf_index.cp.niter,
            ivf_index.cp.nredo,
            static_cast<int>(dim),
            num_vectors,
            static_cast<int>(n_centroids),
            training_duration_ms + insertion_duration_ms,
            static_cast<int>(num_threads),
            0.0,
            hyperparams,
            knn_10_metrics,
            knn_100_metrics
        );
    } else {
        std::cout << "\nGround truth not found at: " << gt_file_path << std::endl;
        std::cout << "Recall computation skipped" << std::endl;
    }

    return 0;
}

