FLogWindowManager::~FLogWindowManager()
{
	// Clean up all registered log window hooks
	for (int idx = 0; idx < WindowGridEntries.Num(); ++idx)
	{
		FLogGridEntry* CurrentItem = &WindowGridEntries[idx];
		if (CurrentItem->LogWidget.IsValid())
		{
#if TARGET_UE4_CL >= CL_DEPRECATEDEL
			CurrentItem->LogWidget->MultiOnWindowClosed.Remove(WindowClosedDelegateMap.FindRef(CurrentItem->LogWidget.Get()));
#else
			CurrentItem->LogWidget->MultiOnWindowClosed.RemoveRaw(this, &FLogWindowManager::HandleWindowClosed);
#endif
		}
	}

	for (int overflowIdx = 0; overflowIdx < OverflowWindowsList.Num(); ++overflowIdx)
	{
		if (OverflowWindowsList[overflowIdx].IsValid())
		{
#if TARGET_UE4_CL >= CL_DEPRECATEDEL
			OverflowWindowsList[overflowIdx]->MultiOnWindowClosed.Remove(WindowClosedDelegateMap.FindRef(OverflowWindowsList[overflowIdx].Get()));
#else
			OverflowWindowsList[overflowIdx]->MultiOnWindowClosed.RemoveRaw(this, &FLogWindowManager::HandleWindowClosed);
#endif
		}
	}
}

void FLogWindowManager::Setup(int WindowWidth, int WindowHeight)
{
	if (!bIsSetup)
	{
		bIsSetup = true;
		LogWindowWidth = WindowWidth;
		LogWindowHeight = WindowHeight;

		FDisplayMetrics ScreenMetrics;
		FSlateApplication::Get().GetDisplayMetrics(ScreenMetrics);

		// Use the retrieved display metrics and configured dimensions to initialize grid positions
		FPlatformRect WorkingArea = ScreenMetrics.PrimaryDisplayWorkAreaRect;

		// Determine how many windows fit horizontally and vertically
		float Columns = FMath::FloorToFloat((WorkingArea.Right - WorkingArea.Left) / (float)LogWindowWidth);
		float Rows = FMath::FloorToFloat((WorkingArea.Bottom - WorkingArea.Top) / (float)LogWindowHeight);

		// Populate the grid layout
		for (int RowIndex = 0; RowIndex < Rows; ++RowIndex)
		{
			for (int ColIndex = 0; ColIndex < Columns; ++ColIndex)
			{
				FLogGridEntry NewEntry;
				float VerticalPos = (float)LogWindowHeight * (float)RowIndex;
				float HorizontalPos = (float)LogWindowWidth * (float)ColIndex;

				NewEntry.Top = WorkingArea.Top + VerticalPos;
				NewEntry.Bottom = WorkingArea.Top + VerticalPos + LogWindowHeight;
				NewEntry.Left = WorkingArea.Left + HorizontalPos;
				NewEntry.Right = WorkingArea.Left + HorizontalPos + LogWindowWidth;

				WindowGridEntries.Add(NewEntry);
			}
		}

		// @todo #JohnBDebug: Remove this debug code
#if 0
		for (int k = 0; k < WindowGridEntries.Num(); ++k)
		{
			UE_LOG(LogUnitTest, Log, TEXT("Grid entry '%i': Top: %f, Bottom: %f, Left: %f, Right: %f"), k,
				WindowGridEntries[k].Top, WindowGridEntries[k].Bottom,
				WindowGridEntries[k].Left, WindowGridEntries[k].Right);
		}
#endif
	}
}

TSharedPtr<SLogWindow> FLogWindowManager::SpawnLogWindow(FString WindowTitle, ELogType FilterMask, bool bIsStatusPanel)
{
	TSharedPtr<SLogWindow> Result = nullptr;

	int AvailableSlot = LocateNextAvailableSlot();
	bool bStartMinimized = false;

	if (AvailableSlot != INDEX_NONE)
	{
		LastAssignedPosition = AvailableSlot;
		FLogGridEntry& TargetSlot = WindowGridEntries[AvailableSlot];

		Result =
			SNew(SLogWindow, WindowTitle, TargetSlot.Left, TargetSlot.Top, LogWindowWidth, LogWindowHeight)
			.bStatusWindow(bIsStatusPanel)
			.ExpectedFilters(FilterMask);

		TargetSlot.LogWidget = Result;
	}
	else
	{
		UNIT_ASSERT(WindowGridEntries.Num() > 0);

		FLogGridEntry& OverflowSpot = WindowGridEntries[0];
		Result =
			SNew(SLogWindow, WindowTitle, OverflowSpot.Left, OverflowSpot.Top, LogWindowWidth, LogWindowHeight)
			.bStatusWindow(bIsStatusPanel)
			.ExpectedFilters(FilterMask);

		bStartMinimized = true;
		OverflowWindowsList.Add(Result);
	}

	if (Result.IsValid())
	{
#if TARGET_UE4_CL >= CL_DEPRECATEDEL
		WindowClosedDelegateMap.Add(Result.Get(),
									Result->MultiOnWindowClosed.AddRaw(this, &FLogWindowManager::HandleWindowClosed));
#else
		Result->MultiOnWindowClosed.AddRaw(this, &FLogWindowManager::HandleWindowClosed);
#endif

		FSlateApplication::Get().AddWindow(Result.ToSharedRef());

		if (bStartMinimized)
		{
			Result->Minimize();
		}
		else
		{
			Result->FlashWindow();
		}
	}

	return Result;
}

void FLogWindowManager::HandleWindowClosed(const TSharedRef<SWindow>& ClosedRef)
{
	TSharedPtr<SLogWindow> ClosedPtr = StaticCastSharedRef<SLogWindow>(ClosedRef);
	if (ClosedPtr.IsValid())
	{
		int FreedSlotIndex = INDEX_NONE;

		// Clear the closed window from the grid
		for (int i = 0; i < WindowGridEntries.Num(); ++i)
		{
			if (WindowGridEntries[i].LogWidget == ClosedPtr)
			{
				FreedSlotIndex = i;
				WindowGridEntries[i].LogWidget = nullptr;
				break;
			}
		}

		// Remove from overflow list if applicable
		OverflowWindowsList.Remove(ClosedPtr);

		// If a slot was freed and there are pending overflow windows, promote one
		if (FreedSlotIndex != INDEX_NONE && OverflowWindowsList.Num() > 0)
		{
			int OverflowIndex = INDEX_NONE;
			for (int j = 0; j < OverflowWindowsList.Num(); ++j)
			{
				if (!OverflowWindowsList[j]->bHasMoved)
				{
					OverflowIndex = j;
					break;
				}
			}

			if (OverflowIndex != INDEX_NONE)
			{
				FLogGridEntry& TargetGrid = WindowGridEntries[FreedSlotIndex];
				TargetGrid.LogWidget = OverflowWindowsList[OverflowIndex];
				OverflowWindowsList.RemoveAt(OverflowIndex);

				TargetGrid.LogWidget->BringToFront();
				TargetGrid.LogWidget->MoveWindowTo(FVector2D(TargetGrid.Left, TargetGrid.Top));
				TargetGrid.LogWidget->FlashWindow();
			}
		}

		// Notify unit test manager about the closure
		if (GUnitTestManager != nullptr)
		{
			GUnitTestManager->NotifyLogWindowClosed(ClosedRef);
		}
	}
}

int FLogWindowManager::LocateNextAvailableSlot()
{
	int FoundIndex = INDEX_NONE;

	for (int offset = 0; offset < WindowGridEntries.Num(); ++offset)
	{
		int CheckIndex = LastAssignedPosition + offset + 1;
		if (CheckIndex >= WindowGridEntries.Num())
		{
			CheckIndex -= WindowGridEntries.Num();
		}

		if (!WindowGridEntries[CheckIndex].LogWidget.IsValid())
		{
			FoundIndex = CheckIndex;
			break;
		}
	}

	return FoundIndex;
}

