#include "shader_binding_tables.hpp"
#include "utils.hpp"

//--------------------------------------------------------------------------------------------------
// The Shader Binding Table (SBT)
// - Collects all shader handles and stores them in an SBT buffer
// - In most cases, this implementation can be used as-is
//
Buffer SbtHelper::create_shader_binding_table(const vk::Pipeline &rtPipeline)
{
    uint32_t missCount{2};
    uint32_t hitCount{1};
    uint32_t totalHandles = 1 + missCount + hitCount;
    uint32_t handleSize = rtProperties.shaderGroupHandleSize;

    // Align handle size and compute region strides/sizes for the SBT
    uint32_t alignedHandleSize = utils::align_up(handleSize,
                                                 rtProperties.shaderGroupHandleAlignment);

    rgenRegion.setStride(utils::align_up(alignedHandleSize, rtProperties.shaderGroupBaseAlignment));
    rgenRegion.setSize(rgenRegion.stride); // Required: size == stride for raygen

    missRegion.setStride(alignedHandleSize);
    missRegion.setSize(
        utils::align_up(missCount * alignedHandleSize, rtProperties.shaderGroupBaseAlignment));

    hitRegion.setStride(alignedHandleSize);
    hitRegion.setSize(
        utils::align_up(hitCount * alignedHandleSize, rtProperties.shaderGroupBaseAlignment));

    // Retrieve shader group handles from the pipeline
    uint32_t dataLength = totalHandles * handleSize;
    std::vector<uint8_t> shaderHandles = device.getRayTracingShaderGroupHandlesKHR<uint8_t>(
        rtPipeline, 0, totalHandles, dataLength);

    // Create SBT buffer with appropriate usage flags and memory properties
    vk::DeviceSize sbtTotalSize = rgenRegion.size + missRegion.size + hitRegion.size;
    Buffer rtSBTBuffer = utils::create_buffer(
        device,
        allocator,
        sbtTotalSize,
        vk::BufferUsageFlagBits::eTransferSrc |
            vk::BufferUsageFlagBits::eShaderDeviceAddress |
            vk::BufferUsageFlagBits::eShaderBindingTableKHR,
        VMA_MEMORY_USAGE_AUTO_PREFER_HOST,
        VMA_ALLOCATION_CREATE_HOST_ACCESS_SEQUENTIAL_WRITE_BIT |
            VMA_ALLOCATION_CREATE_MAPPED_BIT);

    // Compute device addresses for each region
    vk::BufferDeviceAddressInfo addrInfo{};
    addrInfo.setBuffer(rtSBTBuffer.buffer);
    vk::DeviceAddress baseAddress = device.getBufferAddress(addrInfo);

    rgenRegion.setDeviceAddress(baseAddress);
    missRegion.setDeviceAddress(baseAddress + rgenRegion.size);
    hitRegion.setDeviceAddress(baseAddress + rgenRegion.size + missRegion.size);

    // Helper lambda to extract handle pointer by index
    auto extractHandle = [&](int idx) { return shaderHandles.data() + idx * handleSize; };

    // Map the buffer and populate with shader handles
    uint8_t *bufferStart = static_cast<uint8_t *>(rtSBTBuffer.allocationInfo.pMappedData);
    uint8_t *writePtr = bufferStart;
    int handleIndex = 0;

    // Copy raygen shader handle
    memcpy(writePtr, extractHandle(handleIndex++), handleSize);

    // Copy miss shader handles
    writePtr = bufferStart + rgenRegion.size;
    for (uint32_t i = 0; i < missCount; ++i) {
        memcpy(writePtr, extractHandle(handleIndex++), handleSize);
        writePtr += missRegion.stride;
    }

    // Copy closest-hit shader handles
    writePtr = bufferStart + rgenRegion.size + missRegion.size;
    for (uint32_t i = 0; i < hitCount; ++i) {
        memcpy(writePtr, extractHandle(handleIndex++), handleSize);
        writePtr += hitRegion.stride;
    }

    return rtSBTBuffer;
}

