#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    if (!(cin >> N)) return 0;
    const int TOTAL_FISH = 2 * N;
    const int GRID_MAX_COORD = 100000;
    const int MAX_PERIMETER = 400000;
    const int HALF_PERIM = MAX_PERIMETER / 2; // 200000

    // Grid configuration
    const int CELL_SIZE = 1000;       // size of each grid cell
    const int NUM_CELLS = 100;        // number of cells along each axis

    // Grid storing difference: #mackerels - #sardines per cell
    vector<vector<int>> diffGrid(NUM_CELLS, vector<int>(NUM_CELLS, 0));

    for (int idx = 0; idx < TOTAL_FISH; idx++) {
        int x, y;
        cin >> x >> y;
        int colIdx = min(x / CELL_SIZE, NUM_CELLS - 1);
        int rowIdx = min(y / CELL_SIZE, NUM_CELLS - 1);

        if (idx < N) 
            diffGrid[rowIdx][colIdx] += 1;
        else 
            diffGrid[rowIdx][colIdx] -= 1;
    }

    // Precompute left and right boundaries for each cell index
    vector<int> leftBoundX(NUM_CELLS), rightBoundX(NUM_CELLS);
    vector<int> leftBoundY(NUM_CELLS), rightBoundY(NUM_CELLS);

    for (int i = 0; i < NUM_CELLS; i++) {
        leftBoundX[i] = i * CELL_SIZE;
        leftBoundY[i] = i * CELL_SIZE;
        rightBoundX[i] = (i == NUM_CELLS - 1) ? GRID_MAX_COORD : (i + 1) * CELL_SIZE - 1;
        rightBoundY[i] = (i == NUM_CELLS - 1) ? GRID_MAX_COORD : (i + 1) * CELL_SIZE - 1;
    }

    long long maxDiff = LLONG_MIN;
    int bestLeft = 0, bestRight = 0, bestTop = 0, bestBottom = 0;

    // Enumerate top and bottom rows of the rectangle
    for (int topRow = 0; topRow < NUM_CELLS; topRow++) {
        vector<int> colSum(NUM_CELLS, 0);

        for (int bottomRow = topRow; bottomRow < NUM_CELLS; bottomRow++) {
            // Add current row to column sums
            for (int c = 0; c < NUM_CELLS; c++) {
                colSum[c] += diffGrid[bottomRow][c];
            }

            // Compute vertical dimensions
            int topY = leftBoundY[topRow];
            int bottomY = rightBoundY[bottomRow];
            int rectHeight = bottomY - topY;
            int remainingWidth = HALF_PERIM - rectHeight;

            if (remainingWidth < 0) break; // height too large, stop expanding downward

            // Prefix sums for column contributions
            vector<long long> prefix(NUM_CELLS + 1, 0);
            for (int j = 0; j < NUM_CELLS; j++) {
                prefix[j + 1] = prefix[j] + colSum[j];
            }

            // Monotonic deque to find minimum prefix in valid range
            deque<pair<int, long long>> minDeque; // (index, prefix_value)

            for (int rightCol = 0; rightCol < NUM_CELLS; rightCol++) {
                // Maintain increasing order in deque
                while (!minDeque.empty() && minDeque.back().second >= prefix[rightCol]) {
                    minDeque.pop_back();
                }
                minDeque.emplace_back(rightCol, prefix[rightCol]);

                // Determine minimum left column index allowed by perimeter constraint
                long long minLeftX = (long long)rightBoundX[rightCol] - remainingWidth;
                int minColIndex;
                if (minLeftX <= 0) {
                    minColIndex = 0;
                } else {
                    minColIndex = (int)((minLeftX + CELL_SIZE - 1) / CELL_SIZE); // ceil division
                }

                // Remove indices outside allowed range from front
                while (!minDeque.empty() && minDeque.front().first < minColIndex) {
                    minDeque.pop_front();
                }

                if (minDeque.empty()) continue;

                long long currentDiff = prefix[rightCol + 1] - minDeque.front().second;
                if (currentDiff > maxDiff) {
                    maxDiff = currentDiff;
                    bestLeft = minDeque.front().first;
                    bestRight = rightCol;
                    bestTop = topRow;
                    bestBottom = bottomRow;
                }
            }
        }
    }

    // If no positive difference found, output bounding box covering all points
    if (maxDiff <= 0) {
        cout << 4 << "\n";
        cout << 0 << " " << 0 << "\n";
        cout << GRID_MAX_COORD << " " << 0 << "\n";
        cout << GRID_MAX_COORD << " " << GRID_MAX_COORD << "\n";
        cout << 0 << " " << GRID_MAX_COORD << "\n";
        return 0;
    }

    // Extract coordinates of best rectangle
    int leftX = leftBoundX[bestLeft];
    int rightX = rightBoundX[bestRight];
    int topY = leftBoundY[bestTop];
    int bottomY = rightBoundY[bestBottom];

    // Verify perimeter constraint (should hold by construction)
    long long width = (long long)rightX - leftX;
    long long height = (long long)bottomY - topY;
    long long perimeter = 2 * (width + height);

    if (perimeter > MAX_PERIMETER) {
        // Fallback in case of unexpected overflow or bug
        cout << 4 << "\n";
        cout << 0 << " " << 0 << "\n";
        cout << GRID_MAX_COORD << " " << 0 << "\n";
        cout << GRID_MAX_COORD << " " << GRID_MAX_COORD << "\n";
        cout << 0 << " " << GRID_MAX_COORD << "\n";
        return 0;
    }

    // Output final rectangle vertices in order
    cout << 4 << "\n";
    cout << leftX << " " << topY << "\n";
    cout << rightX << " " << topY << "\n";
    cout << rightX << " " << bottomY << "\n";
    cout << leftX << " " << bottomY << "\n";

    return 0;
}

