/** Constructor for the LAN beacon object */
FLanBeacon::FLanBeacon(void) 
	: ListenSocket(NULL),
	  SockAddr(ISocketSubsystem::Get(PLATFORM_SOCKETSUBSYSTEM)->CreateInternetAddr())
{
}

/** Destructor - cleans up the broadcast socket */
FLanBeacon::~FLanBeacon(void)
{
	ISocketSubsystem* SocketSubsystem = ISocketSubsystem::Get(PLATFORM_SOCKETSUBSYSTEM);
	SocketSubsystem->DestroySocket(ListenSocket);
}

/** Checks if the listening socket is valid */
bool FLanBeacon::IsListenSocketValid() const
{
	return (ListenSocket != nullptr);
}

/**
 * Initializes the socket for LAN communication
 *
 * @param Port the port number to listen on
 * @return true if initialization succeeded, false otherwise
 */
bool FLanBeacon::Init(int32 Port)
{
	ISocketSubsystem* SocketSubsystem = ISocketSubsystem::Get(PLATFORM_SOCKETSUBSYSTEM);
	bool bSuccess = false;

	// Setup local listening address
	ListenAddr = SocketSubsystem->GetLocalBindAddr(*GWarn);
	ListenAddr->SetPort(Port);

	// Configure broadcast address
	BroadcastAddr = SocketSubsystem->CreateInternetAddr(ListenAddr->GetProtocolType());
	BroadcastAddr->SetBroadcastAddress();
	BroadcastAddr->SetPort(Port);

	// Create temporary socket address for receiving data
	SockAddr = SocketSubsystem->CreateInternetAddr();

	// Create datagram socket
	ListenSocket = SocketSubsystem->CreateSocket(NAME_DGram, TEXT("LAN beacon"), ListenAddr->GetProtocolType());
	if (ListenSocket != nullptr)
	{
		ListenSocket->SetReuseAddr();
		ListenSocket->SetNonBlocking();
		ListenSocket->SetRecvErr();

		// Bind to the specified port
		if (ListenSocket->Bind(*ListenAddr))
		{
			// Enable broadcasting capability
			bSuccess = ListenSocket->SetBroadcast();
		}
		else
		{
			UE_LOG_ONLINE(Error, TEXT("Failed to bind listen socket to addr (%s) for LAN beacon"),
				*ListenAddr->ToString(true));
		}
	}
	else
	{
		UE_LOG_ONLINE(Error, TEXT("Failed to create listen socket for LAN beacon"));
	}

	return bSuccess && (ListenSocket != nullptr);
}

/**
 * Polls the socket for incoming data
 *
 * @param PacketData buffer to store received data
 * @param BufferSize maximum size of the buffer
 * @return number of bytes read, <=0 indicates no data or error
 */
int32 FLanBeacon::ReceivePacket(uint8* PacketData, int32 BufferSize)
{
	check(PacketData && BufferSize);
	int32 BytesRead = 0;

	if (ListenSocket != nullptr)
	{
		ListenSocket->RecvFrom(PacketData, BufferSize, BytesRead, *SockAddr);
		if (BytesRead > 0)
		{
			UE_LOG_ONLINE(Verbose, TEXT("Received %d bytes from %s"), BytesRead, *SockAddr->ToString(true));
		}
	}
	return BytesRead;
}

/**
 * Sends a packet via broadcast
 *
 * @param Packet pointer to packet data
 * @param Length size of the packet in bytes
 * @return true if sending succeeded
 */
bool FLanBeacon::BroadcastPacket(uint8* Packet, int32 Length)
{
	int32 BytesSent = 0;
	UE_LOG_ONLINE(Verbose, TEXT("Sending %d bytes to %s"), Length, *BroadcastAddr->ToString(true));
	return ListenSocket->SendTo(Packet, Length, BytesSent, *BroadcastAddr) && (BytesSent == Length);
}

/**
 * Starts hosting a LAN session
 */
bool FLANSession::Host(FOnValidQueryPacketDelegate& QueryDelegate)
{
	bool bSuccess = false;
	if (LanBeacon != nullptr)
	{
		StopLANSession();
	}
	LanBeaconGuid = FGuid::NewGuid();

	LanBeacon = new FLanBeacon();
	if (LanBeacon->Init(LanAnnouncePort))
	{
		AddOnValidQueryPacketDelegate_Handle(QueryDelegate);
		LanBeaconState = ELanBeaconState::Hosting;
		bSuccess = true;
		UE_LOG_ONLINE(Verbose, TEXT("Listening for LAN beacon requests on %d"), LanAnnouncePort);
	}
	else
	{
		UE_LOG_ONLINE(Warning, TEXT("Failed to init LAN beacon %s"), ISocketSubsystem::Get(PLATFORM_SOCKETSUBSYSTEM)->GetSocketError());
	}

	return bSuccess;
}

/**
 * Initiates a search for LAN servers
 *
 * @param Packet discovery packet to send
 * @param ResponseDelegate callback for valid responses
 * @param TimeoutDelegate callback when search times out
 */
bool FLANSession::Search(FNboSerializeToBuffer& Packet, FOnValidResponsePacketDelegate& ResponseDelegate, FOnSearchingTimeoutDelegate& TimeoutDelegate)
{
	bool bSuccess = true;
	if (LanBeacon != nullptr)
	{
		StopLANSession();
	}

	LanBeaconGuid = FGuid::NewGuid();
	CachedResponseGuids.Empty();

	LanBeacon = new FLanBeacon();
	if (!LanBeacon->Init(LanAnnouncePort))
	{
		UE_LOG_ONLINE(Warning, TEXT("Failed to create socket for lan announce port %s"), ISocketSubsystem::Get(PLATFORM_SOCKETSUBSYSTEM)->GetSocketError());
		bSuccess = false;
	}

	if (LanBeacon && bSuccess)
	{
		if (LanBeacon->BroadcastPacket(Packet, Packet.GetByteCount()))
		{
			UE_LOG_ONLINE(Verbose, TEXT("Sent query packet..."));
			LanBeaconState = ELanBeaconState::Searching;
			LanQueryTimeLeft = LanQueryTimeout;
			RetryData.Reset();
			RetryData.Append(Packet.GetBuffer().GetData(), Packet.GetByteCount());
			LanQueryRetryTimeLeft = LanQueryRetryTime;
			AddOnValidResponsePacketDelegate_Handle(ResponseDelegate);
			AddOnSearchingTimeoutDelegate_Handle(TimeoutDelegate);
		}
		else
		{
			UE_LOG_ONLINE(Warning, TEXT("Failed to send discovery broadcast %s"), ISocketSubsystem::Get(PLATFORM_SOCKETSUBSYSTEM)->GetSocketError());
			bSuccess = false;
		}
	}
	return bSuccess;
}

/** Stops active LAN session operations */
void FLANSession::StopLANSession()
{
	LanBeaconState = ELanBeaconState::NotUsingLanBeacon;
	if (LanBeacon)
	{	
		delete LanBeacon;
		LanBeacon = nullptr;
	}
	OnValidQueryPacketDelegates.Clear();
	OnValidResponsePacketDelegates.Clear();
	OnSearchingTimeoutDelegates.Clear();
	RetryData.Empty();
	CachedResponseGuids.Empty();
}

/** Main update loop for handling LAN beacon operations */
void FLANSession::Tick(float DeltaTime)
{
	if (LanBeaconState == ELanBeaconState::NotUsingLanBeacon)
	{
		return;
	}

	uint8 PacketData[LAN_BEACON_MAX_PACKET_SIZE];
	bool bShouldRead = true;

	while (bShouldRead)
	{
		int32 NumRead = LanBeacon->ReceivePacket(PacketData, LAN_BEACON_MAX_PACKET_SIZE);
		if (NumRead > 0)
		{
			if (LanBeaconState == ELanBeaconState::Hosting)
			{
				uint64 ClientNonce;
				if (IsValidLanQueryPacket(PacketData, NumRead, ClientNonce))
				{
					TriggerOnValidQueryPacketDelegates(&PacketData[LAN_BEACON_PACKET_HEADER_SIZE], NumRead - LAN_BEACON_PACKET_HEADER_SIZE, ClientNonce);
				}
			}
			else if (LanBeaconState == ELanBeaconState::Searching)
			{
				FGuid ResponseGuid;
				if (IsValidLanResponsePacket(PacketData, NumRead, ResponseGuid))
				{
					bool bAlreadySet = false;
					CachedResponseGuids.Add(ResponseGuid, &bAlreadySet);
					if (!bAlreadySet)
					{
						TriggerOnValidResponsePacketDelegates(&PacketData[LAN_BEACON_PACKET_HEADER_SIZE], NumRead - LAN_BEACON_PACKET_HEADER_SIZE);
					}
				}
			}
		}
		else
		{
			if (LanBeaconState == ELanBeaconState::Searching)
			{
				LanQueryRetryTimeLeft -= DeltaTime;

				if (LanBeacon && (LanQueryRetryTimeLeft <= 0.f) && (LanQueryTimeLeft > LanQueryRetryTime))
				{
					if (LanBeacon->BroadcastPacket(RetryData.GetData(), RetryData.Num()))
					{
						UE_LOG_ONLINE(Verbose, TEXT("Sent retry query packet..."));
					}
					else
					{
						UE_LOG_ONLINE(Warning, TEXT("Failed to send retry discovery broadcast %s"), ISocketSubsystem::Get(PLATFORM_SOCKETSUBSYSTEM)->GetSocketError());
					}
					LanQueryRetryTimeLeft = LanQueryRetryTime;
				}

				LanQueryTimeLeft -= DeltaTime;
				if (LanQueryTimeLeft <= 0.f)
				{
					TriggerOnSearchingTimeoutDelegates();
				}
			}
			bShouldRead = false;
		}
	}
}

/** Constructs a server response packet for clients */
void FLANSession::CreateHostResponsePacket(FNboSerializeToBuffer& Packet, uint64 ClientNonce)
{
	Packet << LAN_BEACON_PACKET_VERSION
		<< (uint8)FPlatformProperties::IsLittleEndian()
		<< LanGameUniqueId
		<< LAN_SERVER_RESPONSE1 << LAN_SERVER_RESPONSE2
		<< ClientNonce
		<< LanBeaconGuid;
}

/** Constructs a client query packet for server discovery */
void FLANSession::CreateClientQueryPacket(FNboSerializeToBuffer& Packet, uint64 ClientNonce)
{
	Packet << LAN_BEACON_PACKET_VERSION
		<< (uint8)FPlatformProperties::IsLittleEndian()
		<< LanGameUniqueId
		<< LAN_SERVER_QUERY1 << LAN_SERVER_QUERY2
		<< ClientNonce
		<< LanBeaconGuid;
}

/**
 * Broadcasts a packet using the internal beacon
 *
 * @param Packet pointer to packet data
 * @param Length size of the packet
 * @return true if successful
 */
bool FLANSession::BroadcastPacket(uint8* Packet, int32 Length)
{
	bool bSuccess = false;
	if (LanBeacon)
	{
		bSuccess = LanBeacon->BroadcastPacket(Packet, Length);
		if (!bSuccess)
		{
			UE_LOG_ONLINE(Warning, TEXT("Failed to send broadcast packet %d"), (int32)ISocketSubsystem::Get(PLATFORM_SOCKETSUBSYSTEM)->GetLastErrorCode());
		}
	}
	return bSuccess;
}

/**
 * Validates a LAN query packet header
 *
 * @param Packet raw packet data
 * @param Length size of the packet
 * @param ClientNonce output parameter for nonce value
 * @return true if packet header is valid
 */
bool FLANSession::IsValidLanQueryPacket(const uint8* Packet, uint32 Length, uint64& ClientNonce)
{
	ClientNonce = 0;
	bool bIsValid = false;

	if (Length == LAN_BEACON_PACKET_HEADER_SIZE)
	{
		FNboSerializeFromBuffer PacketReader(Packet, Length);
		uint8 Version = 0;
		PacketReader >> Version;

		if (Version == LAN_BEACON_PACKET_VERSION)
		{
			uint8 Platform = 255;
			PacketReader >> Platform;

			if (Platform & LanPacketPlatformMask)
			{
				int32 GameId = -1;
				PacketReader >> GameId;

				if (GameId == LanGameUniqueId)
				{
					uint8 SQ1 = 0;
					PacketReader >> SQ1;
					uint8 SQ2 = 0;
					PacketReader >> SQ2;

					bIsValid = (SQ1 == LAN_SERVER_QUERY1 && SQ2 == LAN_SERVER_QUERY2);
					PacketReader >> ClientNonce;

					FGuid BeaconGuid;
					PacketReader >> BeaconGuid;
				}
			}
		}
	}
	return bIsValid;
}

/**
 * Validates a LAN response packet header
 *
 * @param Packet raw packet data
 * @param Length size of the packet
 * @param ResponseGuid output parameter for beacon GUID
 * @return true if packet header is valid
 */
bool FLANSession::IsValidLanResponsePacket(const uint8* Packet, uint32 Length, FGuid& ResponseGuid)
{
	bool bIsValid = false;

	if (Length > LAN_BEACON_PACKET_HEADER_SIZE)
	{
		FNboSerializeFromBuffer PacketReader(Packet, Length);
		uint8 Version = 0;
		PacketReader >> Version;

		if (Version == LAN_BEACON_PACKET_VERSION)
		{
			uint8 Platform = 255;
			PacketReader >> Platform;

			if (Platform & LanPacketPlatformMask)
			{
				int32 GameId = -1;
				PacketReader >> GameId;

				if (GameId == LanGameUniqueId)
				{
					uint8 SQ1 = 0;
					PacketReader >> SQ1;
					uint8 SQ2 = 0;
					PacketReader >> SQ2;

					if (SQ1 == LAN_SERVER_RESPONSE1 && SQ2 == LAN_SERVER_RESPONSE2)
					{
						uint64 Nonce = 0;
						PacketReader >> Nonce;

						if (Nonce == LanNonce)
						{
							FGuid BeaconGuid;
							PacketReader >> BeaconGuid;
							bIsValid = !PacketReader.HasOverflow();
							if (bIsValid)
							{
								ResponseGuid = BeaconGuid;
							}
						}
					}
				}
			}
		}
	}
	return bIsValid;
}

