/// @test
/// Verify default quaternion construction yields identity rotation
/// @requirements(SEN-1060)
TEST(QuaternionTest, initDefault)
{
  Quatd q {};
  // Verify components match identity quaternion
  EXPECT_EQ(q.getX(), 0);
  EXPECT_EQ(q.getY(), 0);
  EXPECT_EQ(q.getZ(), 0);
  EXPECT_EQ(q.getW(), 1);
}

/// @test
/// Validate rotation generation using axis-angle representation
/// @requirements(SEN-1060)
TEST(QuaternionTest, axisAngleRotation)
{
  Quatd q {};
  EXPECT_EQ(q.getX(), 0);
  EXPECT_EQ(q.getY(), 0);
  EXPECT_EQ(q.getZ(), 0);
  EXPECT_EQ(q.getW(), 1);

  q.makeRotate(pi, Vec3d {1.0f, 0.0f, 0.0f});
  ASSERT_NEAR(q.getX(), 1, 0.005);
  ASSERT_NEAR(q.getY(), 0, 0.005);
  ASSERT_NEAR(q.getZ(), 0, 0.005);
  ASSERT_NEAR(q.getW(), 0, 0.005);

  q.makeRotate(pi / 2.0f, Vec3d {0.0f, 1.0f, 0.0f});
  ASSERT_NEAR(q.getX(), 0.707, 0.005);
  ASSERT_NEAR(q.getY(), 0, 0.005);
  ASSERT_NEAR(q.getZ(), -0.707, 0.005);
  ASSERT_NEAR(q.getW(), 0, 0.005);
}

/// @test
/// Test Euler angle conversion and rotation construction
/// @requirements(SEN-1060)
TEST(QuaternionTest, eulerAngleOps)
{
  Quat q = Quat<f64>(0, 0, toRad(30.0));
  ASSERT_NEAR(q.getX(), 0.2588, 0.005);
  ASSERT_NEAR(q.getY(), 0, 0.005);
  ASSERT_NEAR(q.getZ(), 0, 0.005);
  ASSERT_NEAR(q.getW(), 0.9659, 0.005);

  auto eul = q.getRotateInEulerYPB();
  ASSERT_NEAR(toDeg(eul.getX()), 0, 0.005);
  ASSERT_NEAR(toDeg(eul.getY()), 0, 0.005);
  ASSERT_NEAR(toDeg(eul.getZ()), 30.0, 0.005);

  q.makeRotate(toRad(60.0), 1, 0, 0);
  eul = q.getRotateInEulerYPB();
  ASSERT_NEAR(toDeg(eul.getX()), 0, 0.005);
  ASSERT_NEAR(toDeg(eul.getY()), 0, 0.005);
  ASSERT_NEAR(toDeg(eul.getZ()), 90.0, 0.005);

  q = Quat<f64>(0, toRad(30.0), 0);
  ASSERT_NEAR(q.getX(), 0, 0.005);
  ASSERT_NEAR(q.getY(), 0.2588, 0.005);
  ASSERT_NEAR(q.getZ(), 0, 0.005);
  ASSERT_NEAR(q.getW(), 0.9659, 0.005);
}

/// @test
/// Check magnitude computation via length() and length2()
/// @requirements(SEN-1060)
TEST(QuaternionTest, normCalculation)
{
  Quat q = Quat<f64>(0, 0, toRad(15.0));
  EXPECT_NEAR(q.length(), 1.0, 0.00001);
  EXPECT_NEAR(q.length2(), 1.0, 0.00001);

  q = Quat<f64>(toRad(60.0), toRad(22.0), toRad(15.0));
  EXPECT_NEAR(q.length(), 1.0, 0.00001);
  EXPECT_NEAR(q.length2(), 1.0, 0.00001);
}

/// @test
/// Validate conjugate operation correctness
/// @requirements(SEN-1060)
TEST(QuaternionTest, conjOperation)
{
  Quat q = Quat<f64>(0, toRad(60.0), toRad(15.0));
  q = q.conj();
  auto eul = q.getRotateInEulerYPB();
  ASSERT_NEAR(toDeg(eul.getX()), 24.146, 0.001);
  ASSERT_NEAR(toDeg(eul.getY()), -56.774, 0.001);
  ASSERT_NEAR(toDeg(eul.getZ()), -28.186, 0.001);
}

/// @test
/// Confirm inverse operation matches expected behavior
/// @requirements(SEN-1060)
TEST(QuaternionTest, invOperation)
{
  Quat q = Quat<f64>(0, toRad(60.0), toRad(15.0));
  q = q.inverse();
  auto eul = q.getRotateInEulerYPB();
  ASSERT_NEAR(toDeg(eul.getX()), 24.146, 0.001);
  ASSERT_NEAR(toDeg(eul.getY()), -56.774, 0.001);
  ASSERT_NEAR(toDeg(eul.getZ()), -28.186, 0.001);
}

/// @test
/// Evaluate spherical linear interpolation (SLERP) accuracy
/// @requirements(SEN-1060)
TEST(QuaternionTest, slerpInterpolation)
{
  Quat from = Quat<f64>(0, 0, toRad(15.0));
  Quat to   = Quat<f64>(0, 0, toRad(55.0));
  Quat res  = Quat<f64>(0, 0, 0);

  res.slerp(0.1, from, to);
  auto eul = res.getRotateInEulerYPB();
  ASSERT_NEAR(toDeg(eul.getX()), 0, 0.001);
  ASSERT_NEAR(toDeg(eul.getY()), 0, 0.001);
  ASSERT_NEAR(toDeg(eul.getZ()), 19, 0.001);

  res.slerp(0.2, from, to);
  eul = res.getRotateInEulerYPB();
  ASSERT_NEAR(toDeg(eul.getX()), 0, 0.001);
  ASSERT_NEAR(toDeg(eul.getY()), 0, 0.001);
  ASSERT_NEAR(toDeg(eul.getZ()), 23, 0.001);
}

