#include <gtest/gtest.h>
#include <iostream>
#include <ocs2_core/misc/LinearInterpolation.h>
#include <Eigen/Dense>

TEST(testLinearInterpolation, testInterpolation) {
  using VectorType = Eigen::Matrix<double, 2, 1>;
  // Prepare test data
  std::vector<double> timestamps = {0.0, 1.0, 2.0, 3.0, 3.0, 4.0};
  std::vector<VectorType, Eigen::aligned_allocator<VectorType>> values;
  for (auto& t_val : timestamps) {
    values.emplace_back(t_val * VectorType::Ones());
  }
  std::cout << "TEST DATA" << std::endl;
  for (int idx = 0; idx < timestamps.size(); ++idx) {
    std::cout << "time: " << timestamps[idx] << " v: " << values[idx].transpose() << std::endl;
  }

  // Helper lambda to verify interpolation results
  auto validate_interpolation = [&](double query_time, int expected_index, double expected_value) {
    const auto segmentInfo = ocs2::LinearInterpolation::timeSegment(query_time, timestamps);
    const auto interpolated_value = ocs2::LinearInterpolation::interpolate(segmentInfo, values);
    const auto foundIndex = segmentInfo.first;
    const auto weight = segmentInfo.second;

    std::cout << "time: " << query_time << " index: " << foundIndex << " v: " 
              << interpolated_value.transpose() << " alpha: " << weight << std::endl;

    EXPECT_EQ(foundIndex, expected_index);
    EXPECT_DOUBLE_EQ(interpolated_value(0), expected_value);
    ASSERT_TRUE(std::isfinite(weight));
    ASSERT_GE(weight, 0.0);
    ASSERT_LE(weight, 1.0);
  };

  // Test cases
  validate_interpolation(-1.0, 0, 0.0);  // Before start
  validate_interpolation(timestamps[0], 0, timestamps[0]);  // At start
  validate_interpolation(0.25 * timestamps[0] + 0.75 * timestamps[1], 0, 0.25 * timestamps[0] + 0.75 * timestamps[1]);  // First interval - off center
  validate_interpolation(0.5 * timestamps[0] + 0.5 * timestamps[1], 0, 0.5 * timestamps[0] + 0.5 * timestamps[1]);  // First interval midpoint
  validate_interpolation(timestamps[1], 0, timestamps[1]);  // Boundary to second interval
  validate_interpolation(timestamps[3], 2, timestamps[3]);  // Event time
  validate_interpolation(0.5 * timestamps[4] + 0.5 * timestamps[5], 4, 0.5 * timestamps[4] + 0.5 * timestamps[5]);  // Last interval
  validate_interpolation(timestamps[5], 4, timestamps[5]);  // At end
  validate_interpolation(timestamps[5] + 1.0, 4, timestamps[5]);  // Beyond end
}

TEST(testLinearInterpolation, testEventTimeInterpolation) {
  {  // Single event point
    std::vector<double> event_times{1.0, 1.0};
    const auto segmentInfo = ocs2::LinearInterpolation::timeSegment(1.0, event_times);
    ASSERT_EQ(segmentInfo.first, 0);
    ASSERT_TRUE(std::isfinite(segmentInfo.second));
    ASSERT_GE(segmentInfo.second, 0.0);
    ASSERT_LE(segmentInfo.second, 1.0);
  }

  {  // Very short interval between samples
    constexpr auto eps = ocs2::numeric_traits::weakEpsilon<ocs2::scalar_t>();
    std::vector<double> event_times{0.0, 1.0, 1.0 + eps, 2.0};

    // Left side of the short interval
    const auto lhs_segment = ocs2::LinearInterpolation::timeSegment(1.0 + 0.1 * eps, event_times);
    ASSERT_EQ(lhs_segment.first, 1);
    ASSERT_EQ(lhs_segment.second, 1.0);

    // Right side of the short interval
    const auto rhs_segment = ocs2::LinearInterpolation::timeSegment(1.0 + 0.9 * eps, event_times);
    ASSERT_EQ(rhs_segment.first, 1);
    ASSERT_EQ(rhs_segment.second, 0.0);
  }
}

TEST(testLinearInterpolation, testSizeOneTime) {
  using VectorType = Eigen::Matrix<double, 2, 1>;

  // Create single-point dataset
  std::vector<double> timestamps = {1.0};
  std::vector<VectorType, Eigen::aligned_allocator<VectorType>> values;
  for (auto& t_val : timestamps) {
    values.emplace_back(t_val * VectorType::Ones());
  }

  std::cout << "TEST DATA" << std::endl;
  for (int idx = 0; idx < timestamps.size(); ++idx) {
