  }

  // Validation function
  auto validate_interpolation = [&](double query_time, int expected_index, double expected_value) {
    const auto segmentInfo = ocs2::LinearInterpolation::timeSegment(query_time, timestamps);
    const auto interpolated_value = ocs2::LinearInterpolation::interpolate(segmentInfo, values);
    const auto foundIndex = segmentInfo.first;
    const auto weight = segmentInfo.second;

    std::cout << "time: " << query_time << " index: " << foundIndex << " v: " 
              << interpolated_value.transpose() << " alpha: " << weight << std::endl;

    EXPECT_EQ(foundIndex, expected_index);
    EXPECT_DOUBLE_EQ(interpolated_value(0), expected_value);
