// Request UGC-related message box with defaults
C4JStorage::EMessageResult ConsoleUIController::RequestUGCMessageBox(UINT title/* = -1 */, UINT message/* = -1 */, int playerIndex/* = -1*/, 
	int(*callback)(LPVOID, int, const C4JStorage::EMessageResult)/* = NULL*/, LPVOID param/* = NULL*/)
{
	if (title == -1)
	{
		title = IDS_CONNECTION_FAILED;
	}
	if (message == -1)
	{
		message = IDS_NO_USER_CREATED_CONTENT_PRIVILEGE_SINGLE_LOCAL;
	}
	if (playerIndex == -1) 
		playerIndex = ProfileManager.GetPrimaryPad();

	UINT uiIDA[1];
	uiIDA[0] = IDS_CONFIRM_OK;
	return ui.RequestMessageBox(title, message, uiIDA, 1, playerIndex, callback, param, app.GetStringTable(), NULL, 0, false);
}

