// Data stored per platform window
struct WGL_WindowData { HDC hDC; };

// Global variables for OpenGL context and window state
static HGLRC            g_OpenGLRenderingContext;
static WGL_WindowData   g_PrimaryWindow;
static int              g_WindowWidth;
static int              g_WindowHeight;

// Function prototypes
bool InitializeWGLContext(HWND hWnd, WGL_WindowData* data);
void ReleaseWGLContext(HWND hWnd, WGL_WindowData* data);
void ResetOpenGLContext();
LRESULT CALLBACK WindowProcedure(HWND hWnd, UINT message, WPARAM wParam, LPARAM lParam);

// Viewport-specific hooks for multi-window support
static void OnViewportCreated(ImGuiViewport* viewport)
{
    assert(viewport->RendererUserData == NULL);
    WGL_WindowData* windowData = IM_NEW(WGL_WindowData);
    InitializeWGLContext((HWND)viewport->PlatformHandle, windowData);
    viewport->RendererUserData = windowData;
}

static void OnViewportDestroyed(ImGuiViewport* viewport)
{
    if (viewport->RendererUserData != NULL)
    {
        WGL_WindowData* windowData = (WGL_WindowData*)viewport->RendererUserData;
        ReleaseWGLContext((HWND)viewport->PlatformHandle, windowData);
        IM_DELETE(windowData);
        viewport->RendererUserData = NULL;
    }
}

static void OnPlatformRenderWindow(ImGuiViewport* viewport, void*)
{
    if (WGL_WindowData* windowData = (WGL_WindowData*)viewport->RendererUserData)
        wglMakeCurrent(windowData->hDC, g_OpenGLRenderingContext);
}

static void OnSwapBuffers(ImGuiViewport* viewport, void*)
{
    if (WGL_WindowData* windowData = (WGL_WindowData*)viewport->RendererUserData)
        ::SwapBuffers(windowData->hDC);
}

// Entry point of the application
int main(int argc, char** argv)
{
    // Enable DPI awareness and get primary monitor scale
    float dpiScale = ImGui_ImplWin32_GetDpiScaleForMonitor(::MonitorFromPoint(POINT{ 0, 0 }, MONITOR_DEFAULTTOPRIMARY));

    // Register window class
    WNDCLASSEXW windowClass = { sizeof(windowClass), CS_OWNDC, WindowProcedure, 0L, 0L, GetModuleHandle(nullptr), nullptr, nullptr, nullptr, nullptr, L"Dear ImGui Win32+OpenGL3 App", nullptr };
    ::RegisterClassExW(&windowClass);

    // Create main application window
    HWND mainHwnd = ::CreateWindowW(windowClass.lpszClassName, L"Dear ImGui Win32+OpenGL3 Example", WS_OVERLAPPEDWINDOW, 
                                    100, 100, (int)(1280 * dpiScale), (int)(800 * dpiScale), 
                                    nullptr, nullptr, windowClass.hInstance, nullptr);

    // Initialize OpenGL context
    if (!InitializeWGLContext(mainHwnd, &g_PrimaryWindow))
    {
        ReleaseWGLContext(mainHwnd, &g_PrimaryWindow);
        ::DestroyWindow(mainHwnd);
        ::UnregisterClassW(windowClass.lpszClassName, windowClass.hInstance);
        return 1;
    }

    wglMakeCurrent(g_PrimaryWindow.hDC, g_OpenGLRenderingContext);

    // Display and update the window
    ::ShowWindow(mainHwnd, SW_SHOWDEFAULT);
    ::UpdateWindow(mainHwnd);

    // Initialize Dear ImGui
    IMGUI_CHECKVERSION();
    ImGui::CreateContext();
    ImGuiIO& io = ImGui::GetIO(); (void)io;

    // Configure input and UI features
    io.ConfigFlags |= ImGuiConfigFlags_NavEnableKeyboard;
    io.ConfigFlags |= ImGuiConfigFlags_NavEnableGamepad;
    io.ConfigFlags |= ImGuiConfigFlags_DockingEnable;
    io.ConfigFlags |= ImGuiConfigFlags_ViewportsEnable;

    // Apply styling
    ImGui::StyleColorsDark();

    // Adjust UI scaling based on DPI
    ImGuiStyle& style = ImGui::GetStyle();
    style.ScaleAllSizes(dpiScale);
    style.FontScaleDpi = dpiScale;
    io.ConfigDpiScaleFonts = true;
    io.ConfigDpiScaleViewports = true;

    // Adjust window rounding for seamless platform windows
    if (io.ConfigFlags & ImGuiConfigFlags_ViewportsEnable)
    {
        style.WindowRounding = 0.0f;
        style.Colors[ImGuiCol_WindowBg].w = 1.0f;
    }

    // Initialize Platform and Renderer backends
    ImGui_ImplWin32_InitForOpenGL(mainHwnd);
    ImGui_ImplOpenGL3_Init();

    // Set up custom viewport hooks for Win32+OpenGL integration
    if (io.ConfigFlags & ImGuiConfigFlags_ViewportsEnable)
    {
        ImGuiPlatformIO& platform_io = ImGui::GetPlatformIO();
        IM_ASSERT(platform_io.Renderer_CreateWindow == NULL);
        IM_ASSERT(platform_io.Renderer_DestroyWindow == NULL);
        IM_ASSERT(platform_io.Renderer_SwapBuffers == NULL);
        IM_ASSERT(platform_io.Platform_RenderWindow == NULL);

        platform_io.Renderer_CreateWindow = OnViewportCreated;
        platform_io.Renderer_DestroyWindow = OnViewportDestroyed;
        platform_io.Renderer_SwapBuffers = OnSwapBuffers;
        platform_io.Platform_RenderWindow = OnPlatformRenderWindow;
    }

    // Load fonts (commented out examples provided)
    // style.FontSizeBase = 20.0f;
    // io.Fonts->AddFontDefault();
    // io.Fonts->AddFontFromFileTTF("c:\\Windows\\Fonts\\segoeui.ttf");

    // Application state
    bool showDemoWindow = true;
    bool showAnotherWindow = false;
    ImVec4 backgroundColor = ImVec4(0.45f, 0.55f, 0.60f, 1.00f);

    // Main event loop
    bool isRunning = true;
    while (isRunning)
    {
        MSG message;
        while (::PeekMessage(&message, nullptr, 0U, 0U, PM_REMOVE))
        {
            ::TranslateMessage(&message);
            ::DispatchMessage(&message);
            if (message.message == WM_QUIT)
                isRunning = false;
        }

        if (!isRunning)
            break;

        if (::IsIconic(mainHwnd))
        {
            ::Sleep(10);
            continue;
        }

        // Begin new frame
        ImGui_ImplOpenGL3_NewFrame();
        ImGui_ImplWin32_NewFrame();
        ImGui::NewFrame();

        // Demo window
        if (showDemoWindow)
            ImGui::ShowDemoWindow(&showDemoWindow);

        // Simple window
        {
            static float sliderValue = 0.0f;
            static int buttonClickCount = 0;
            ImGui::Begin("Hello, world!");
            ImGui::Text("This is some useful text.");
            ImGui::Checkbox("Demo Window", &showDemoWindow);
            ImGui::Checkbox("Another Window", &showAnotherWindow);
            ImGui::SliderFloat("float", &sliderValue, 0.0f, 1.0f);
            ImGui::ColorEdit3("clear color", (float*)&backgroundColor);
            if (ImGui::Button("Button"))
                buttonClickCount++;
            ImGui::SameLine();
            ImGui::Text("counter = %d", buttonClickCount);
            ImGui::Text("Application average %.3f ms/frame (%.1f FPS)", 1000.0f / io.Framerate, io.Framerate);
            ImGui::End();
        }

        // Additional simple window
        if (showAnotherWindow)
        {
            ImGui::Begin("Another Window", &showAnotherWindow);
            ImGui::Text("Hello from another window!");
            if (ImGui::Button("Close Me"))
                showAnotherWindow = false;
            ImGui::End();
        }

        // Render Dear ImGui
        ImGui::Render();
        glViewport(0, 0, g_WindowWidth, g_WindowHeight);
        glClearColor(backgroundColor.x, backgroundColor.y, backgroundColor.z, backgroundColor.w);
        glClear(GL_COLOR_BUFFER_BIT);
        ImGui_ImplOpenGL3_RenderDrawData(ImGui::GetDrawData());

        // Handle additional platform windows
        if (io.ConfigFlags & ImGuiConfigFlags_ViewportsEnable)
        {
            ImGui::UpdatePlatformWindows();
            ImGui::RenderPlatformWindowsDefault();
            wglMakeCurrent(g_PrimaryWindow.hDC, g_OpenGLRenderingContext);
        }

        // Present to screen
        ::SwapBuffers(g_PrimaryWindow.hDC);
    }

    // Cleanup
    ImGui_ImplOpenGL3_Shutdown();
    ImGui_ImplWin32_Shutdown();
    ImGui::DestroyContext();
    ReleaseWGLContext(mainHwnd, &g_PrimaryWindow);
    wglDeleteContext(g_OpenGLRenderingContext);
    ::DestroyWindow(mainHwnd);
    ::UnregisterClassW(windowClass.lpszClassName, windowClass.hInstance);
    return 0;
}

// Helper functions for WGL context management
bool InitializeWGLContext(HWND hWnd, WGL_WindowData* data)
{
    HDC deviceContext = ::GetDC(hWnd);
    PIXELFORMATDESCRIPTOR pfd = { 0 };
    pfd.nSize = sizeof(pfd);
    pfd.nVersion = 1;
    pfd.dwFlags = PFD_DRAW_TO_WINDOW | PFD_SUPPORT_OPENGL | PFD_DOUBLEBUFFER;
    pfd.iPixelType = PFD_TYPE_RGBA;
    pfd.cColorBits = 32;

    int pixelFormat = ::ChoosePixelFormat(deviceContext, &pfd);
    if (pixelFormat == 0)
        return false;

    if (::SetPixelFormat(deviceContext, pixelFormat, &pfd) == FALSE)
        return false;

    ::ReleaseDC(hWnd, deviceContext);
    data->hDC = ::GetDC(hWnd);

    if (!g_OpenGLRenderingContext)
        g_OpenGLRenderingContext = wglCreateContext(data->hDC);

    return true;
}

void ReleaseWGLContext(HWND hWnd, WGL_WindowData* data)
{
    wglMakeCurrent(nullptr, nullptr);
    ::ReleaseDC(hWnd, data->hDC);
}

// Forward declaration from imgui_impl_win32.cpp
extern IMGUI_IMPL_API LRESULT ImGui_ImplWin32_WndProcHandler(HWND hWnd, UINT msg, WPARAM wParam, LPARAM lParam);

// Windows message handler
LRESULT CALLBACK WindowProcedure(HWND hWnd, UINT message, WPARAM wParam, LPARAM lParam)
{
    if (ImGui_ImplWin32_WndProcHandler(hWnd, message, wParam, lParam))
        return true;

    switch (message)
    {
    case WM_SIZE:
        if (wParam != SIZE_MINIMIZED)
        {
            g_WindowWidth = LOWORD(lParam);
            g_WindowHeight = HIWORD(lParam);
        }
        return 0;

    case WM_SYSCOMMAND:
        if ((wParam & 0xfff0) == SC_KEYMENU)
            return 0;
        break;

    case WM_DESTROY:
        ::PostQuitMessage(0);
        return 0;
    }

    return ::DefWindowProcW(hWnd, message, wParam, lParam);
}

