// Convert ASCII digit character to hex value
unsigned char hexCharToValue(char ch) {
    if (0x61 <= ch && ch <= 0x66) {
        return ch - 0x61 + 0xa;
    } else if (0x41 <= ch && ch <= 0x46) {
        return ch - 0x41 + 0xa;
    } else {
        return ch - 0x30;
    }
}

// Parse 16-byte hex string into binary output
void parseHex16(const char *input, unsigned char *output) {
    const char *src = input;
    unsigned int value;
    for (int idx = 0; idx < 0x10; idx++, src += 2) {
        value = hexCharToValue(src[1]) + (hexCharToValue(src[0]) << 4);
        *output++ = value;
    }
}

// Simple LCG random number generator
long pseudoRandom(long seed) {
    static long state = 0xEB;
    if (seed != 0)
        state = seed;
    state = state * 0x19660E + 0x3C6EF35F;
    return state;
}

// Check if system needs byte swapping based on endianness
#define REQUIRES_SWAP(p, val) (*(((unsigned char *)(p)) + 3) == (val))

// Perform 32-bit byte swap in-place
#define PERFORM_BYTESWAP_32BIT(addr)                                                     \
    do {                                                                                 \
        unsigned char temp1, temp2;                                                      \
        temp1 = *((unsigned char *)(addr) + 0);                                          \
        temp2 = *((unsigned char *)(addr) + 3);                                          \
        *((unsigned char *)(addr) + 0) = temp2;                                          \
        *((unsigned char *)(addr) + 3) = temp1;                                          \
        temp1 = *((unsigned char *)(addr) + 1);                                          \
        temp2 = *((unsigned char *)(addr) + 2);                                          \
        *((unsigned char *)(addr) + 1) = temp2;                                          \
        *((unsigned char *)(addr) + 2) = temp1;                                          \
    } while (0);

// Generate masher keys using PRNG
void KeyChain::generateMasher(unsigned char *buffer) {
    unsigned int *masher_ptr = reinterpret_cast<unsigned int *>(buffer);
    unsigned int test_val = 1;
    bool is_big_endian = REQUIRES_SWAP(&test_val, 1);

    for (int i = 0; i < 8; i++) {
        *masher_ptr = pseudoRandom((i == 0) ? 0xEB : 0);
        if (is_big_endian) {
            PERFORM_BYTESWAP_32BIT(masher_ptr);
        }
        masher_ptr++;
    }
}

// XOR two buffers of 8 unsigned ints
void applyXOR(unsigned char *buf1, unsigned char *buf2) {
    unsigned int *ptr1 = (unsigned int *)buf1;
    unsigned int *ptr2 = (unsigned int *)buf2;
    for (int i = 0; i < 8; i++) {
        ptr1[i] ^= ptr2[i];
    }
}

// Circular left shift by 19 bits modulo 32
int rotateBits(int n) {
    n += 19;
    n %= 32;
    return n;
}

// Swap two characters
void exchangeChars(char &a, char &b) {
    char temp = a;
    a = b;
    b = temp;
}

// Shuffle operations on character arrays
void shuffleA(char *arr) {
    for (int i = 0; i < 8; i++) {
        exchangeChars(arr[rotateBits(i * 4)], arr[i * 4 + 2]);
        exchangeChars(arr[rotateBits(i * 4 + 3)], arr[i * 4 + 1]);
    }
}

void shuffleB(char *arr) {
    for (int i = 0; i < 8; i++) {
        exchangeChars(arr[(7 - i) * 4 + 1], arr[i * 4 + 2]);
        exchangeChars(arr[(7 - i) * 4], arr[i * 4 + 3]);
    }
}

void shuffleC(char *arr) {
    for (int i = 0; i < 8; i++) {
        exchangeChars(arr[rotateBits((7 - i) * 4 + 1)], arr[i * 4 + 2]);
        exchangeChars(arr[(7 - i) * 4], arr[i * 4 + 3]);
    }
}

void shuffleD(char *arr) {
    for (int i = 0; i < 8; i++) {
        exchangeChars(arr[(7 - i) * 4 + 1], arr[i * 4 + 2]);
        exchangeChars(arr[rotateBits((7 - i) * 4)], arr[i * 4 + 3]);
    }
}

void shuffleE(char *arr) {
    for (int i = 0; i < 8; i++) {
        exchangeChars(arr[(7 - i) * 4 + 1], arr[rotateBits(i * 4 + 2)]);
        exchangeChars(arr[(7 - i) * 4], arr[i * 4 + 3]);
    }
}

void shuffleF(char *arr) {
    for (int i = 0; i < 8; i++) {
        exchangeChars(arr[(7 - i) * 4 + 1], arr[i * 4 + 2]);
        exchangeChars(arr[(7 - i) * 4], arr[rotateBits(i * 4 + 3)]);
    }
}

// Apply all shuffles sequentially
void fullShuffle(char *data) {
    shuffleA(data);
    shuffleB(data);
    shuffleC(data);
    shuffleD(data);
    shuffleE(data);
    shuffleF(data);
}

// Dummy function for obfuscation
void dummyCounter() {
    static int callCount = 0;
    callCount++;
}

// Safe memory copy with dummy calls inserted
void secureCopy(unsigned char *dest, const unsigned char *src, unsigned int size) {
    for (int i = 0; i < size; i++) {
        dummyCounter();
        dest[i] = src[i];
    }
}

// Reveal key through shuffling and XOR
void decryptKey(long *keyData, unsigned char *mask) {
    for (int step = 0; step < 0xE; step++) {
        fullShuffle((char *)keyData);
    }
    applyXOR((unsigned char *)keyData, mask);
}

// Extract key from hidden storage
void extractKey(unsigned char *source, char *target, unsigned char *mask) {
    decryptKey((long *)source, mask);
    secureCopy((unsigned char *)target, source, 0x20);
}

// Public method to retrieve a specific key
void KeyChain::retrieveKey(unsigned int index, unsigned char *out1, unsigned char *out2) {
    unsigned char buffer1[32];
    char buffer2[32];
    secureCopy(buffer1, &secretData[index * 0x20], 0x20);
    extractKey(buffer1, buffer2, out2);
    parseHex16(buffer2, out1);
}

// Return number of available keys
unsigned int KeyChain::countKeys() { return 0xC; }

#include "jemalloc/internal/jemalloc_preamble.h"
#include "jemalloc/internal/jemalloc_internal_includes.h"
#include "jemalloc/internal/assert.h"
#include "jemalloc/internal/ehooks.h"
#include "jemalloc/internal/san.h"
#include "jemalloc/internal/tsd.h"

/* Configuration parameters for sanitizer behavior */
size_t opt_san_guard_large = SAN_GUARD_LARGE_EVERY_N_EXTENTS_DEFAULT;
size_t opt_san_guard_small = SAN_GUARD_SMALL_EVERY_N_EXTENTS_DEFAULT;

/* Alignment for UAF detection (-1 disables) */
ssize_t opt_lg_san_uaf_align = SAN_LG_UAF_ALIGN_DEFAULT;

/*
 * Initialized during san_init(). When disabled, the mask is set to all 1s
 * to ensure nonfast_align checks always fail.
 */
uintptr_t san_cache_bin_nonfast_mask = SAN_CACHE_BIN_NONFAST_MASK_DEFAULT;

static inline void
san_get_protected_region(edata_t *edata, uintptr_t *left_guard, uintptr_t *right_guard,
    uintptr_t *base_addr, size_t region_size, bool protect_left, bool protect_right) {
	assert(!edata_guarded_get(edata));
	assert(region_size % PAGE == 0);
	*base_addr = (uintptr_t)edata_base_get(edata);

	if (protect_left) {
		*left_guard = *base_addr;
		*base_addr += SAN_PAGE_GUARD;
	} else {
		*left_guard = 0;
	}

	if (protect_right) {
		*right_guard = *base_addr + region_size;
	} else {
		*right_guard = 0;
	}
}

static inline void
san_get_unprotected_region(edata_t *edata, uintptr_t *left_guard, uintptr_t *right_guard,
    uintptr_t *base_addr, size_t region_size, bool protect_left, bool protect_right) {
	assert(edata_guarded_get(edata));
	assert(region_size % PAGE == 0);
	*base_addr = (uintptr_t)edata_base_get(edata);

	if (protect_right) {
		*right_guard = *base_addr + region_size;
	} else {
		*right_guard = 0;
	}

	if (protect_left) {
		*left_guard = *base_addr - SAN_PAGE_GUARD;
		assert(*left_guard != 0);
		*base_addr = *left_guard;
	} else {
		*left_guard = 0;
	}
}

void
san_protect_memory(tsdn_t *tsdn, ehooks_t *ehooks, edata_t *edata, emap_t *emap,
    bool protect_left, bool protect_right, bool update_mapping) {
	assert(protect_left || protect_right);

	if (update_mapping) {
		emap_deregister_boundary(tsdn, emap, edata);
	}

	size_t size_with_protection = edata_size_get(edata);
	size_t raw_size = (protect_left && protect_right)
	    ? san_both_sides_unprotected_size(size_with_protection)
	    : san_one_side_unprotected_size(size_with_protection);

	uintptr_t left_guard, right_guard, current_addr;
	san_get_protected_region(edata, &left_guard, &right_guard, &current_addr, raw_size,
	    protect_left, protect_right);

	assert(edata_state_get(edata) == extent_state_active);
	ehooks_protect(tsdn, ehooks, (void *)left_guard, (void *)right_guard);

	/* Update metadata with protected address and size */
	edata_size_set(edata, raw_size);
	edata_addr_set(edata, (void *)current_addr);
	edata_guarded_set(edata, true);

	if (update_mapping) {
		emap_register_boundary(tsdn, emap, edata, SC_NSIZES,
		    /* slab */ false);
	}
}

static void
san_unprotect_memory_internal(tsdn_t *tsdn, ehooks_t *ehooks, edata_t *edata,
    emap_t *emap, bool protect_left, bool protect_right, bool update_mapping) {
	assert(protect_left || protect_right);

	if (update_mapping) {
		assert(edata_state_get(edata) == extent_state_active);
		emap_deregister_boundary(tsdn, emap, edata);
	} else {
		assert(edata_state_get(edata) == extent_state_retained);
	}

	size_t current_size = edata_size_get(edata);
	size_t full_size = (protect_left && protect_right)
	    ? san_both_sides_protected_size(current_size)
	    : san_one_side_protected_size(current_size);

	uintptr_t left_guard, right_guard, current_addr;
	san_get_unprotected_region(edata, &left_guard, &right_guard, &current_addr,
	    current_size, protect_left, protect_right);

	ehooks_unprotect(tsdn, ehooks, (void *)left_guard, (void *)right_guard);

	/* Restore original size and address */
	edata_size_set(edata, full_size);
	edata_addr_set(edata, (void *)current_addr);
	edata_guarded_set(edata, false);

	if (update_mapping) {
		emap_register_boundary(tsdn, emap, edata, SC_NSIZES,
		    /* slab */ false);
	}
}

void
san_unprotect_memory(tsdn_t *tsdn, ehooks_t *ehooks, edata_t *edata,
    emap_t *emap, bool protect_left, bool protect_right) {
	san_unprotect_memory_internal(tsdn, ehooks, edata, emap,
	    protect_left, protect_right, /* update_mapping */ true);
}

void
san_unprotect_before_destroy(tsdn_t *tsdn, ehooks_t *ehooks, edata_t *edata,
    emap_t *emap) {
	emap_assert_not_mapped(tsdn, emap, edata);

	/*
	 * Skip emap updates for destroyed extents since they've already been
	 * unmapped during eviction from retained ecache. Also, only unprotect
	 * the right side because retained extents only own their right guard
	 * page per san_bump_alloc's logic.
	 */
	san_unprotect_memory_internal(tsdn, ehooks, edata, emap,
	    /* protect_left */ false, /* protect_right */ true,
	    /* update_mapping */ false);
}

static bool
san_check_freed_content(void *memory_block, size_t block_size) {
	if (san_slow_mode_enabled()) {
		for (size_t i = 0; i < block_size; i++) {
			if (((unsigned char *)memory_block)[i] != (unsigned char)uaf_detect_pattern) {
				return true;
			}
		}
		return false;
	}

	void *start_ptr, *middle_ptr, *end_ptr;
	san_get_sample_positions(memory_block, block_size, &start_ptr, &middle_ptr, &end_ptr);

	if (*(uintptr_t *)start_ptr != uaf_detect_pattern ||
	    *(uintptr_t *)middle_ptr != uaf_detect_pattern ||
	    *(uintptr_t *)end_ptr != uaf_detect_pattern) {
		return true;
	}
	return false;
}

void
san_validate_stored_pointers(void **stored_list, size_t count, size_t user_size) {
	/*
	 * Ensure that previously junk-filled and stored pointers haven't been
	 * modified — detecting potential use-after-free bugs.
	 */
	for (size_t index = 0; index < count; index++) {
		void *entry = stored_list[index];
		assert(entry != NULL);
		assert(cache_bin_is_aligned_for_nonfast(entry));

		if (unlikely(san_check_freed_content(entry, user_size))) {
			safety_check_fail("<jemalloc>: Memory corruption detected after free "
			    "for pointer %p (size %zu).\n", entry, user_size);
		}
	}
}

void
tsd_san_initialize(tsd_t *tsd) {
	*tsd_san_remaining_small_extentsp_get(tsd) = opt_san_guard_small;
	*tsd_san_remaining_large_extentsp_get(tsd) = opt_san_guard_large;
}

void
san_setup(ssize_t uaf_alignment_log) {
	assert(uaf_alignment_log == -1 || uaf_alignment_log >= LG_PAGE);

	if (uaf_alignment_log == -1) {
		san_cache_bin_nonfast_mask = (uintptr_t)-1;
		return;
	}

	san_cache_bin_nonfast_mask = ((uintptr_t)1 << uaf_alignment_log) - 1;
}

#include "../src/idiomata/idiom_resolver.hpp"
#include <cassert>
#include <iostream>

// Using the idiomata namespace for resolver functionality
using namespace idiomata;

int main() {
    // Test 32-bit signed division by 7: magic = 613566757 (0x24924925), extra shift = 0.
    std::vector<LocalInsn> test_seq1 = {
        {0, "imul", {"reg_a", "reg_a", "const_val1"}},
        {4, "sar", {"reg_a", "const_shift1"}}
    };
    std::unordered_map<std::string, std::string> const_map_test1 = {
        {"0x24924925", "const_val1"},
        {"0x0", "const_shift1"}
    };
    std::unordered_map<std::string, std::string> reg_map_test1 = { {"edi", "reg_a"} };
    assert(SequenceResolver(test_seq1, const_map_test1, reg_map_test1).resolve_divs() == 7);

    // Test 32-bit signed division by 9: magic = -2031616767 (0x88888889), extra shift = 3.
    std::vector<LocalInsn> test_seq2 = {
        {0, "imul", {"reg_b", "reg_b", "const_val2"}},
        {4, "sar", {"reg_b", "const_shift2"}},
        {8, "sar", {"reg_b", "const_shift3"}}
    };
    std::unordered_map<std::string, std::string> const_map_test2 = {
        {"0x88888889", "const_val2"},
        {"0x10", "const_shift2"}, // 16
        {"0x3", "const_shift3"}   // 3 (extra shift)
    };
    std::unordered_map<std::string, std::string> reg_map_test2 = { {"ebx", "reg_b"} };
    assert(SequenceResolver(test_seq2, const_map_test2, reg_map_test2).resolve_divs() == 9);

    // Unsigned division by 6: magic = 2863311531 (0xAAAAAAAA), shift = 1
    std::vector<LocalInsn> test_seq3 = {
        {0, "mul", {"reg_c", "reg_c", "const_val3"}},
        {4, "shr", {"reg_c", "const_shift4"}}
    };
    std::unordered_map<std::string, std::string> const_map_test3 = {
        {"0xaaaaaaaa", "const_val3"},
        {"0x1", "const_shift4"} // power=1
    };
    std::unordered_map<std::string, std::string> reg_map_test3 = { {"ecx", "reg_c"} };
    assert(SequenceResolver(test_seq3, const_map_test3, reg_map_test3).resolve_divu() == 6);

    // Unsigned modulo by power-of-two via mask: y & 0x7F -> % 128
    std::vector<LocalInsn> test_seq4 = {
        {0, "and", {"reg_d", "const_mask"}}
    };
    std::unordered_map<std::string, std::string> const_map_test4 = {
        {"0x7f", "const_mask"}
    };
    std::unordered_map<std::string, std::string> reg_map_test4 = { {"edx", "reg_d"} };
    assert(SequenceResolver(test_seq4, const_map_test4, reg_map_test4).resolve_modu() == 128);

    // Multiplication by left shift amount: x << 4 -> * 16
    std::vector<LocalInsn> test_seq5 = {
        {0, "shl", {"reg_e", "const_shift5"}}
    };
    std::unordered_map<std::string, std::string> const_map_test5 = {
        {"0x4", "const_shift5"}
    };
    std::unordered_map<std::string, std::string> reg_map_test5 = { {"esi", "reg_e"} };
    assert(SequenceResolver(test_seq5, const_map_test5, reg_map_test5).resolve_mul() == 16);

    std::cout << "All idiom semantic resolution tests passed!" << std::endl;
    return 0;
}

#include <vector>
#include <queue>
#include <algorithm>
#include <iostream>

class Solution {
public:
    double mincostToHireWorkers(std::vector<int>& quality, std::vector<int>& wage, int k) {
        std::vector<std::pair<double, int>> employeeData;
        int totalWorkers = quality.size();

        // Calculate wage-to-quality ratios for each worker
        for(int index = 0; index < totalWorkers; index++) {
            double rate = (1.0 * wage[index]) / quality[index];
            employeeData.push_back({rate, quality[index]});
        }

        // Sort workers by their ratio in ascending order
        std::sort(employeeData.begin(), employeeData.end());

        int currentQualitySum = 0;
        std::priority_queue<int> largestQualities;
        double bestCost = 1e18;

        // Process each worker in sorted order
        for(auto& employee: employeeData) {
            double currentRatio = employee.first;
            int currentQuality = employee.second;

            largestQualities.push(currentQuality);
            currentQualitySum += currentQuality;

            // Maintain only k workers in the heap
            if(k < (int)largestQualities.size()) {
                currentQualitySum -= largestQualities.top();
                largestQualities.pop();
            }

            // When we have exactly k workers, calculate cost
            if(k == (int)largestQualities.size()) {
                bestCost = std::min(bestCost, 1.0 * currentQualitySum * currentRatio);
            }
        }

        return bestCost;
    }
};

#include <vector>
#include <algorithm>

class Solution {
public:
    int findDuplicate(std::vector<int>& numbers) {
        int duplicateValue = 0;
        int size = numbers.size();
        std::sort(numbers.begin(), numbers.end());
        for (int index = 0; index < size - 1; index++) {
            if (numbers[index] == numbers[index + 1]) {
                duplicateValue = numbers[index];
            }
        }
        return duplicateValue;
    }
};

#include <iostream>
#include <vector>
#include <algorithm>
#include <set>
using namespace std;

const int MAX_NODES = 100005;
vector<int> children[MAX_NODES];
int left_bound[MAX_NODES], right_bound[MAX_NODES];
bool leaf_flag[MAX_NODES];
vector<vector<int>> bag_collection;
vector<pair<int, int>> tree_connections;

void compute_bounds(int node) {
    if (children[node].empty()) {
        leaf_flag[node] = true;
        left_bound[node] = right_bound[node] = node;
    } else {
        leaf_flag[node] = false;
        left_bound[node] = MAX_NODES;
        right_bound[node] = -1;
        for (int child : children[node]) {
            compute_bounds(child);
            left_bound[node] = min(left_bound[node], left_bound[child]);
            right_bound[node] = max(right_bound[node], right_bound[child]);
        }
    }
}

// Returns pair {first_bag_index, last_bag_index}
pair<int, int> process_tree(int node, int parent) {
    if (leaf_flag[node]) {
        vector<int> bag_content;
        bag_content.push_back(node);
        if (parent != 0 && parent != node) bag_content.push_back(parent);

        sort(bag_content.begin(), bag_content.end());
        bag_content.erase(unique(bag_content.begin(), bag_content.end()), bag_content.end());

        bag_collection.push_back(bag_content);
        int bag_id = bag_collection.size();
        return {bag_id, bag_id};
    }

    int num_children = children[node].size();
    bool is_root_node = (node == 1);
    int special_node = is_root_node ? left_bound[node] : -1;

    // Process each child recursively
    vector<pair<int, int>> child_results(num_children);
    for (int idx = 0; idx < num_children; ++idx) {
        child_results[idx] = process_tree(children[node][idx], node);
    }

    // Create initial NodeBag
    vector<int> nb1_content;
    nb1_content.push_back(node);
    if (parent != 0 && parent != node) nb1_content.push_back(parent);
    nb1_content.push_back(children[node][0]);
    nb1_content.push_back(left_bound[children[node][0]]);
    if (special_node != -1) nb1_content.push_back(special_node);

    sort(nb1_content.begin(), nb1_content.end());
    nb1_content.erase(unique(nb1_content.begin(), nb1_content.end()), nb1_content.end());
    bag_collection.push_back(nb1_content);
    int current_bag_index = bag_collection.size();
    int first_bag = current_bag_index;

    // Link to first child's bag
    tree_connections.push_back({current_bag_index, child_results[0].first});
    int previous_bag = current_bag_index;

    // Handle remaining children with cycle bags
    for (int i = 0; i < num_children - 1; ++i) {
        int right_val = right_bound[children[node][i]];
        int left_next = left_bound[children[node][i+1]];

        vector<int> cycle_bag_content;
        cycle_bag_content.push_back(node);
        if (parent != 0 && parent != node) cycle_bag_content.push_back(parent);
        cycle_bag_content.push_back(right_val);
        cycle_bag_content.push_back(left_next);
        if (special_node != -1) cycle_bag_content.push_back(special_node);

        sort(cycle_bag_content.begin(), cycle_bag_content.end());
        cycle_bag_content.erase(unique(cycle_bag_content.begin(), cycle_bag_content.end()), cycle_bag_content.end());
        bag_collection.push_back(cycle_bag_content);
        int cycle_bag = bag_collection.size();

        // Connect previous child's last bag to cycle bag
        tree_connections.push_back({child_results[i].second, cycle_bag});
        tree_connections.push_back({previous_bag, cycle_bag});

        // Create next NodeBag
        int next_child = children[node][i+1];
        vector<int> next_nb_content;
        next_nb_content.push_back(node);
        if (parent != 0 && parent != node) next_nb_content.push_back(parent);
        next_nb_content.push_back(next_child);
        next_nb_content.push_back(left_next);
        if (special_node != -1) next_nb_content.push_back(special_node);

        sort(next_nb_content.begin(), next_nb_content.end());
        next_nb_content.erase(unique(next_nb_content.begin(), next_nb_content.end()), next_nb_content.end());
        bag_collection.push_back(next_nb_content);
        int next_bag = bag_collection.size();

        // Link cycle bag to new node bag and then to next child
        tree_connections.push_back({cycle_bag, next_bag});
        tree_connections.push_back({next_bag, child_results[i+1].first});

        previous_bag = next_bag;
    }

    // Final TailBag
    int last_child = children[node].back();
    int last_right = right_bound[last_child];

    vector<int> tail_bag_content;
    tail_bag_content.push_back(node);
    if (parent != 0 && parent != node) tail_bag_content.push_back(parent);
    tail_bag_content.push_back(last_child);
    tail_bag_content.push_back(last_right);
    if (special_node != -1) tail_bag_content.push_back(special_node);

    sort(tail_bag_content.begin(), tail_bag_content.end());
    tail_bag_content.erase(unique(tail_bag_content.begin(), tail_bag_content.end()), tail_bag_content.end());
    bag_collection.push_back(tail_bag_content);
    int final_bag = bag_collection.size();

    // Connect last child's bag and previous bag to tail bag
    tree_connections.push_back({child_results.back().second, final_bag});
    tree_connections.push_back({previous_bag, final_bag});

    return {first_bag, final_bag};
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    if (!(cin >> N)) return 0;

    for (int i = 0; i < N - 1; ++i) {
        int parent;
        cin >> parent;
        children[parent].push_back(i + 2);
    }

    compute_bounds(1);
    process_tree(1, 0);

    cout << bag_collection.size() << "\n";
    for (const auto& bag : bag_collection) {
        cout << bag.size();
        for (int val : bag) {
            cout << " " << val;
        }
        cout << "\n";
    }

    for (const auto& conn : tree_connections) {
        cout << conn.first << " " << conn.second << "\n";
    }

    return 0;
}

