    for (int frame = 0; frame < FILTER_SETTLING_FRAMES; ++frame) val_at_1_4x = engine.calculate_force(&data);

    ASSERT_NEAR(val_at_1x, 1.0, 0.001);
    ASSERT_TRUE(val_at_1x > val_at_1_2x && val_at_1_2x > val_at_1_4x);
}
TEST_CASE(test_grip_floor_clamp, "Understeer") {
    std::cout << "\nTest: Grip Floor Clamp" << std::endl;
    FFBEngine engine;
    InitializeEngine(engine);

    engine.m_optimal_slip_angle = 0.07f; 
    engine.m_understeer_effect = 0.95f; 

    TelemInfoV01 data = CreateBasicTestTelemetry(25.0, 12.0); // Infinite slip
    data.mSteeringShaftTorque = 22.0;

    double result = 0.0;
    for (int frame = 0; frame < FILTER_SETTLING_FRAMES; ++frame) result = engine.calculate_force(&data);

    // GRIP_FLOOR_CLAMP: The grip estimator in FFBEngine.h (line 622) enforces a minimum
    // grip value of 0.2 to prevent total force loss even under extreme slip conditions.
    // This safety floor ensures the wheel never goes completely dead.
    ASSERT_NEAR(result, 0.2, 0.001);
}
