// Constants for sign editing
static const int MAX_SIGN_LINES = 4;
static const int MAX_SIGN_LINE_LENGTH = 15;

// Constructor: Initialize sign entry menu UI scene
UIScene_SignEntryMenu::UIScene_SignEntryMenu(int playerIndex, void* pInitData, UILayer* pParentLayer)
    : UIScene(playerIndex, pParentLayer)
{
    // Initialize required Iggy components
    initialiseMovie();

    SignEntryScreenInput* pInitInfo = static_cast<SignEntryScreenInput*>(pInitData);
    pSign = pInitInfo->sign;
    bIsConfirmed = false;
    bIgnoreInput = false;

    m_buttonConfirm.init(app.GetString(IDS_DONE), eControl_Confirm);
    m_labelMessage.init(app.GetString(IDS_EDIT_SIGN_MESSAGE));

    for (int lineIndex = 0; lineIndex < MAX_SIGN_LINES; ++lineIndex)
    {
#if TO_BE_IMPLEMENTED
        // Use Latin alphabet only due to font limitations in JAP/KOR/CHN locales
        switch (XGetLanguage())
        {
        case XC_LANGUAGE_JAPANESE:
        case XC_LANGUAGE_TCHINESE:
        case XC_LANGUAGE_KOREAN:
        case XC_LANGUAGE_RUSSIAN:
            m_signRows[lineIndex].SetKeyboardType(C_4JInput::EKeyboardMode_Alphabet);
            break;
        default:
            m_signRows[lineIndex].SetKeyboardType(C_4JInput::EKeyboardMode_Full);
            break;
        }
        m_signRows[lineIndex].SetText(pSign->GetMessage(lineIndex).c_str());
        m_signRows[lineIndex].SetTextLimit(MAX_SIGN_LINE_LENGTH);
        m_signRows[lineIndex].SetTitleAndText(IDS_SIGN_TITLE, IDS_SIGN_TITLE_TEXT);
#endif

        // Initialize text input lines with current sign content
        m_textInputLines[lineIndex].init(pSign->GetMessage(lineIndex).c_str(), lineIndex);
    }

    // Add background component
    pParentLayer->addComponent(playerIndex, eUIComponent_MenuBackground);
}

// Destructor: Clean up background component
UIScene_SignEntryMenu::~UIScene_SignEntryMenu()
{
    m_parentLayer->removeComponent(eUIComponent_MenuBackground);
}

// Determine which movie to use based on local player count
std::wstring UIScene_SignEntryMenu::getMoviePath()
{
    if (app.GetLocalPlayerCount() > 1)
    {
        return L"SignEntryMenuSplit";
    }
    else
    {
        return L"SignEntryMenu";
    }
}

// Update tooltip context
void UIScene_SignEntryMenu::updateTooltips()
{
    ui.SetTooltips(m_iPad, IDS_TOOLTIPS_SELECT, IDS_TOOLTIPS_BACK);
}

// Main tick loop: handle confirmation and network update
void UIScene_SignEntryMenu::tick()
{
    UIScene::tick();

    if (bIsConfirmed)
    {
        bIsConfirmed = false;

        // Commit entered text back to sign object
        for (int lineIdx = 0; lineIdx < MAX_SIGN_LINES; ++lineIdx)
        {
            std::wstring temp = m_textInputLines[lineIdx].getLabel();
            pSign->SetMessage(lineIdx, temp);
        }

        pSign->setChanged();

        Minecraft* pGameInstance = Minecraft::GetInstance();
        if (pGameInstance && pGameInstance->level && pGameInstance->level->isClientSide)
        {
            shared_ptr<MultiplayerLocalPlayer> pPlayer = pGameInstance->localplayers[m_iPad];
            if (pPlayer && pPlayer->connection && pPlayer->connection->isStarted())
            {
                pPlayer->connection->send(
                    shared_ptr<SignUpdatePacket>(
                        new SignUpdatePacket(
                            pSign->x,
                            pSign->y,
                            pSign->z,
                            pSign->IsVerified(),
                            pSign->IsCensored(),
                            pSign->GetMessages()
                        )
                    )
                );
            }
        }

        ui.CloseUIScenes(m_iPad);
    }
}

// Handle physical/virtual key input
void UIScene_SignEntryMenu::handleInput(int playerIndex, int key, bool repeat, bool pressed, bool released, bool& handled)
{
    if (bIsConfirmed || bIgnoreInput) return;

    ui.AnimateKeyPress(playerIndex, key, repeat, pressed, released);

    switch (key)
    {
    case ACTION_MENU_CANCEL:
        if (pressed)
        {
            // Cancel: clear all lines and go back
            std::wstring emptyStr;
            for (int i = 0; i < MAX_SIGN_LINES; ++i)
            {
                pSign->SetMessage(i, emptyStr);
            }
            navigateBack();
            ui.PlayUISFX(eSFX_Back);
            handled = true;
        }
        break;

    case ACTION_MENU_OK:
#ifdef __ORBIS__
    case ACTION_MENU_TOUCHPAD_PRESS:
#endif
    case ACTION_MENU_UP:
    case ACTION_MENU_DOWN:
        sendInputToMovie(key, repeat, pressed, released);
        handled = true;
        break;
    }
}

// Callback after keyboard input completes
int UIScene_SignEntryMenu::KeyboardCompleteCallback(LPVOID lpParam, bool bSuccess)
{
    UIScene_SignEntryMenu* pInstance = static_cast<UIScene_SignEntryMenu*>(lpParam);
    pInstance->bIgnoreInput = false;

    if (bSuccess)
    {
        uint16_t buffer[128] = {0};
        InputManager.GetText(buffer);
        pInstance->m_textInputLines[pInstance->m_iEditingLine].setLabel(reinterpret_cast<wchar_t*>(buffer));
    }

    return 0;
}

// Handle UI control press events (e.g., button clicks)
void UIScene_SignEntryMenu::handlePress(F64 controlId, F64 childId)
{
    switch ((int)controlId)
    {
    case eControl_Confirm:
        bIsConfirmed = true;
        break;

    case eControl_Line1:
    case eControl_Line2:
    case eControl_Line3:
    case eControl_Line4:
        m_iEditingLine = static_cast<int>(controlId);
        bIgnoreInput = true;

#ifdef _XBOX_ONE
        // Use emailSmtpAddress keyboard type for Xbox One due to lack of Latin-only mode
        int lang = XGetLanguage();
        switch (lang)
        {
        case XC_LANGUAGE_JAPANESE:
        case XC_LANGUAGE_KOREAN:
        case XC_LANGUAGE_TCHINESE:
            InputManager.RequestKeyboard(
                app.GetString(IDS_SIGN_TITLE),
                m_textInputLines[m_iEditingLine].getLabel(),
                (DWORD)m_iPad,
                MAX_SIGN_LINE_LENGTH,
                &UIScene_SignEntryMenu::KeyboardCompleteCallback,
                this,
                C_4JInput::EKeyboardMode_Email
            );
            break;
        default:
            InputManager.RequestKeyboard(
                app.GetString(IDS_SIGN_TITLE),
                m_textInputLines[m_iEditingLine].getLabel(),
                (DWORD)m_iPad,
                MAX_SIGN_LINE_LENGTH,
                &UIScene_SignEntryMenu::KeyboardCompleteCallback,
                this,
                C_4JInput::EKeyboardMode_Alphabet
            );
            break;
        }
#else
        InputManager.RequestKeyboard(
            app.GetString(IDS_SIGN_TITLE),
            m_textInputLines[m_iEditingLine].getLabel(),
            (DWORD)m_iPad,
            MAX_SIGN_LINE_LENGTH,
            &UIScene_SignEntryMenu::KeyboardCompleteCallback,
            this,
            C_4JInput::EKeyboardMode_Alphabet
        );
#endif
        break;
    }
}

