// Initialize HNSW index entries by loading them if not already loaded
static void setupHNSWIndices(main::ClientContext* ctx) {
    auto& storageMgr = *storage::StorageManager::Get(*ctx);
    auto& catalogRef = *catalog::Catalog::Get(*ctx);

    auto txn = transaction::Transaction::Get(*ctx);
    for (auto& entry : catalogRef.getIndexEntries(txn)) {
        if (entry->getIndexType() == HNSWIndexCatalogEntry::TYPE_NAME &&
            !entry->isLoaded()) {

            // Deserialize and set auxiliary info
            entry->setAuxInfo(HNSWIndexAuxInfo::deserialize(entry->getAuxBufferReader()));

            // Load the corresponding index from storage
            auto& table = storageMgr.getTable(entry->getTableID())->cast<storage::NodeTable>();
            auto idxOpt = table.getIndexHolder(entry->getIndexName());

            ASSERT(idxOpt.has_value() && !idxOpt.value().get().isLoaded());
            auto& indexToLoad = idxOpt.value().get();
            indexToLoad.load(ctx, &storageMgr);
        }
    }
}

void VectorExtension::load(main::ClientContext* context) {
    auto& databaseRef = *context->getDatabase();

    // Register various table functions related to vector indexing
    extension::ExtensionUtils::addTableFunc<QueryVectorIndexFunction>(databaseRef);
    extension::ExtensionUtils::addInternalStandaloneTableFunc<InternalCreateHNSWIndexFunction>(databaseRef);
    extension::ExtensionUtils::addInternalStandaloneTableFunc<InternalFinalizeHNSWIndexFunction>(databaseRef);
    extension::ExtensionUtils::addStandaloneTableFunc<CreateVectorIndexFunction>(databaseRef);
    extension::ExtensionUtils::addInternalStandaloneTableFunc<InternalDropHNSWIndexFunction>(databaseRef);
    extension::ExtensionUtils::addStandaloneTableFunc<DropVectorIndexFunction>(databaseRef);

    // Register the on-disk HNSW index type
    extension::ExtensionUtils::registerIndexType(databaseRef, OnDiskHNSWIndex::getIndexType());

    // Load any pre-existing HNSW indices
    setupHNSWIndices(context);
}

