FName FGitConnectWorker::GetName() const
{
	return "Connect";
}

bool FGitConnectWorker::Execute(FGitSourceControlCommand& InCmd)
{
	check(InCmd.Operation->GetName() == GetName());
	// Check Git Availability
	if (0 < InCmd.PathToGitBinary.Len() && GitSourceControlUtils::CheckGitAvailability(InCmd.PathToGitBinary))
	{
		// Now update the status of assets in Content/ directory and also Config files
		TArray<FString> ProjectDirs;
		ProjectDirs.Add(FPaths::ConvertRelativePathToFull(FPaths::ProjectContentDir()));
		ProjectDirs.Add(FPaths::ConvertRelativePathToFull(FPaths::ProjectConfigDir()));
		InCmd.bCommandSuccessful = GitSourceControlUtils::RunUpdateStatus(InCmd.PathToGitBinary, InCmd.PathToRepositoryRoot, ProjectDirs, InCmd.ErrorMessages, States);
		if(!InCmd.bCommandSuccessful || InCmd.ErrorMessages.Num() > 0)
		{
			StaticCastSharedRef<FConnect>(InCmd.Operation)->SetErrorText(LOCTEXT("NotAGitRepository", "Failed to enable Git source control. You need to initialize the project as a Git repository first."));
			InCmd.bCommandSuccessful = false;
		}
	}
	else
	{
		StaticCastSharedRef<FConnect>(InCmd.Operation)->SetErrorText(LOCTEXT("GitNotFound", "Failed to enable Git source control. You need to install Git and specify a valid path to git executable."));
		InCmd.bCommandSuccessful = false;
	}
	return InCmd.bCommandSuccessful;
}

bool FGitConnectWorker::UpdateStates() const
{
	return GitSourceControlUtils::UpdateCachedStates(States);
}

static FText ParseCommitResults(const TArray<FString>& InResults)
{
	if(InResults.Num() >= 1)
	{
		const FString& FirstLine = InResults[0];
		return FText::Format(LOCTEXT("CommitMessage", "Commited {0}."), FText::FromString(FirstLine));
	}
	return LOCTEXT("CommitMessageUnknown", "Submitted revision.");
}

FName FGitCheckInWorker::GetName() const
{
	return "CheckIn";
}

bool FGitCheckInWorker::Execute(FGitSourceControlCommand& InCmd)
{
	check(InCmd.Operation->GetName() == GetName());
	TSharedRef<FCheckIn, ESPMode::ThreadSafe> Operation = StaticCastSharedRef<FCheckIn>(InCmd.Operation);
	// make a temp file to place our commit message in
	FGitScopedTempFile CommitMsgFile(Operation->GetDescription());
	if(CommitMsgFile.GetFilename().Len() > 0)
	{
		TArray<FString> Parameters;
		FString ParamCommitMsgFilename = TEXT("--file=\"");
		ParamCommitMsgFilename += FPaths::ConvertRelativePathToFull(CommitMsgFile.GetFilename());
		ParamCommitMsgFilename += TEXT("\"");
		Parameters.Add(ParamCommitMsgFilename);
		InCmd.bCommandSuccessful = GitSourceControlUtils::RunCommit(InCmd.PathToGitBinary, InCmd.PathToRepositoryRoot, Parameters, InCmd.Files, InCmd.InfoMessages, InCmd.ErrorMessages);
		if(InCmd.bCommandSuccessful)
		{
			// Remove any deleted files from status cache
			FGitSourceControlModule& GitSourceControl = FModuleManager::GetModuleChecked<FGitSourceControlModule>("GitSourceControl");
			FGitSourceControlProvider& Provider = GitSourceControl.GetProvider();
			TArray<TSharedRef<ISourceControlState, ESPMode::ThreadSafe>> LocalStates;
			Provider.GetState(InCmd.Files, LocalStates, EStateCacheUsage::Use);
			for (const auto& State : LocalStates)
			{
				if (State->IsDeleted())
				{
					Provider.RemoveFileFromCache(State->GetFilename());
				}
			}
			Operation->SetSuccessMessage(ParseCommitResults(InCmd.InfoMessages));
			const FString Message = (InCmd.InfoMessages.Num() > 0) ? InCmd.InfoMessages[0] : TEXT("");
			UE_LOG(LogSourceControl, Log, TEXT("commit successful: %s"), *Message);
		}
	}
	// now update the status of our files
	GitSourceControlUtils::RunUpdateStatus(InCmd.PathToGitBinary, InCmd.PathToRepositoryRoot, InCmd.Files, InCmd.ErrorMessages, States);
	return InCmd.bCommandSuccessful;
}

bool FGitCheckInWorker::UpdateStates() const
{
	return GitSourceControlUtils::UpdateCachedStates(States);
}

