FName FGitDeleteWorker::GetName() const
{
	return "Delete";
}

bool FGitDeleteWorker::Execute(FGitSourceControlCommand& InCmd)
{
	check(InCmd.Operation->GetName() == GetName());
	InCmd.bCommandSuccessful = GitSourceControlUtils::RunCommand(TEXT("rm"), InCmd.PathToGitBinary, InCmd.PathToRepositoryRoot, TArray<FString>(), InCmd.Files, InCmd.InfoMessages, InCmd.ErrorMessages);
	// now update the status of our files
	GitSourceControlUtils::RunUpdateStatus(InCmd.PathToGitBinary, InCmd.PathToRepositoryRoot, InCmd.Files, InCmd.ErrorMessages, States);
	return InCmd.bCommandSuccessful;
}

bool FGitDeleteWorker::UpdateStates() const
{
	return GitSourceControlUtils::UpdateCachedStates(States);
}

// Get lists of Missing files (ie "deleted"), Existing files, and "other than Added" Existing files
void GetMissingVsExistingFiles(const TArray<FString>& InFiles, TArray<FString>& OutMissingFiles, TArray<FString>& OutAllExistingFiles, TArray<FString>& OutOtherThanAddedExistingFiles)
{
	FGitSourceControlModule& GitSourceControl = FModuleManager::GetModuleChecked<FGitSourceControlModule>("GitSourceControl");
	FGitSourceControlProvider& Provider = GitSourceControl.GetProvider();
	TArray<TSharedRef<ISourceControlState, ESPMode::ThreadSafe>> LocalStates;
	Provider.GetState(InFiles, LocalStates, EStateCacheUsage::Use);
	for(const auto& State : LocalStates)
	{
		if(FPaths::FileExists(State->GetFilename()))
		{
			if(State->IsAdded())
			{
				OutAllExistingFiles.Add(State->GetFilename());
			}
			else
			{
				OutOtherThanAddedExistingFiles.Add(State->GetFilename());
				OutAllExistingFiles.Add(State->GetFilename());
			}
		}
		else
		{
			OutMissingFiles.Add(State->GetFilename());
		}
	}
}

FName FGitRevertWorker::GetName() const
{
	return "Revert";
}

bool FGitRevertWorker::Execute(FGitSourceControlCommand& InCmd)
{
	// Filter files by status to use the right "revert" commands on them
	TArray<FString> MissingFiles;
	TArray<FString> AllExistingFiles;
	TArray<FString> OtherThanAddedExistingFiles;
	GetMissingVsExistingFiles(InCmd.Files, MissingFiles, AllExistingFiles, OtherThanAddedExistingFiles);
	if(MissingFiles.Num() > 0)
	{
		// "Added" files that have been deleted needs to be removed from source control
		InCmd.bCommandSuccessful = GitSourceControlUtils::RunCommand(TEXT("rm"), InCmd.PathToGitBinary, InCmd.PathToRepositoryRoot, TArray<FString>(), MissingFiles, InCmd.InfoMessages, InCmd.ErrorMessages);
	}
	if(AllExistingFiles.Num() > 0)
	{
		// reset any changes already added to the index
		InCmd.bCommandSuccessful = GitSourceControlUtils::RunCommand(TEXT("reset"), InCmd.PathToGitBinary, InCmd.PathToRepositoryRoot, TArray<FString>(), AllExistingFiles, InCmd.InfoMessages, InCmd.ErrorMessages);
	}
	if(OtherThanAddedExistingFiles.Num() > 0)
	{
		// revert any changes in working copy (this would fails if the asset was in "Added" state, since after "reset" it is now "untracked")
		InCmd.bCommandSuccessful = GitSourceControlUtils::RunCommand(TEXT("checkout"), InCmd.PathToGitBinary, InCmd.PathToRepositoryRoot, TArray<FString>(), OtherThanAddedExistingFiles, InCmd.InfoMessages, InCmd.ErrorMessages);
	}
	// now update the status of our files
	GitSourceControlUtils::RunUpdateStatus(InCmd.PathToGitBinary, InCmd.PathToRepositoryRoot, InCmd.Files, InCmd.ErrorMessages, States);
	return InCmd.bCommandSuccessful;
}

bool FGitRevertWorker::UpdateStates() const
{
	return GitSourceControlUtils::UpdateCachedStates(States);
}

FName FGitSyncWorker::GetName() const
{
   return "Sync";
