bool FGitSyncWorker::Execute(FGitSourceControlCommand& InCmd)
{
   // pull the branch to get remote changes by rebasing any local commits (not merging them to avoid complex graphs)
   // (this cannot work if any local files are modified but not commited)
   {
      TArray<FString> Parameters;
      Parameters.Add(TEXT("--rebase origin HEAD"));
      InCmd.bCommandSuccessful = GitSourceControlUtils::RunCommand(TEXT("pull"), InCmd.PathToGitBinary, InCmd.PathToRepositoryRoot, Parameters, TArray<FString>(), InCmd.InfoMessages, InCmd.ErrorMessages);
   }
   // now update the status of our files
   GitSourceControlUtils::RunUpdateStatus(InCmd.PathToGitBinary, InCmd.PathToRepositoryRoot, InCmd.Files, InCmd.ErrorMessages, States);
   return InCmd.bCommandSuccessful;
}

bool FGitSyncWorker::UpdateStates() const
{
   return GitSourceControlUtils::UpdateCachedStates(States);
}

FName FGitUpdateStatusWorker::GetName() const
{
	return "UpdateStatus";
}

bool FGitUpdateStatusWorker::Execute(FGitSourceControlCommand& InCmd)
{
	check(InCmd.Operation->GetName() == GetName());
	TSharedRef<FUpdateStatus, ESPMode::ThreadSafe> Operation = StaticCastSharedRef<FUpdateStatus>(InCmd.Operation);
	if(InCmd.Files.Num() > 0)
	{
		InCmd.bCommandSuccessful = GitSourceControlUtils::RunUpdateStatus(InCmd.PathToGitBinary, InCmd.PathToRepositoryRoot, InCmd.Files, InCmd.ErrorMessages, States);
		GitSourceControlUtils::RemoveRedundantErrors(InCmd, TEXT("' is outside repository"));
		if(Operation->ShouldUpdateHistory())
		{
			for(int32 Index = 0; Index < States.Num(); Index++)
			{
				FString& File = InCmd.Files[Index];
				TGitSourceControlHistory History;
				if(States[Index].IsConflicted())
				{
					// In case of a merge conflict, we first need to get the tip of the "remote branch" (MERGE_HEAD)
					GitSourceControlUtils::RunGetHistory(InCmd.PathToGitBinary, InCmd.PathToRepositoryRoot, File, true, InCmd.ErrorMessages, History);
				}
				// Get the history of the file in the current branch
				InCmd.bCommandSuccessful &= GitSourceControlUtils::RunGetHistory(InCmd.PathToGitBinary, InCmd.PathToRepositoryRoot, File, false, InCmd.ErrorMessages, History);
				Histories.Add(*File, History);
			}
		}
	}
	else
	{
		// Perforce "opened files" are those that have been modified (or added/deleted): that is what we get with a simple Git status from the root
		if(Operation->ShouldGetOpenedOnly())
		{
			TArray<FString> Files;
			Files.Add(FPaths::ConvertRelativePathToFull(FPaths::ProjectDir()));
			InCmd.bCommandSuccessful = GitSourceControlUtils::RunUpdateStatus(InCmd.PathToGitBinary, InCmd.PathToRepositoryRoot, Files, InCmd.ErrorMessages, States);
		}
	}
	// don't use the ShouldUpdateModifiedState() hint here as it is specific to Perforce: the above normal Git status has already told us this information (like Git and Mercurial)
	return InCmd.bCommandSuccessful;
}

bool FGitUpdateStatusWorker::UpdateStates() const
{
	bool bUpdated = GitSourceControlUtils::UpdateCachedStates(States);
	FGitSourceControlModule& GitSourceControl = FModuleManager::LoadModuleChecked<FGitSourceControlModule>( "GitSourceControl" );
	FGitSourceControlProvider& Provider = GitSourceControl.GetProvider();
	// add history, if any
	for(const auto& History : Histories)
	{
		TSharedRef<FGitSourceControlState, ESPMode::ThreadSafe> State = Provider.GetStateInternal(History.Key);
		State->History = History.Value;
		State->TimeStamp = FDateTime::Now();
		bUpdated = true;
	}
	return bUpdated;
}

FName FGitCopyWorker::GetName() const
{
	return "Copy";
}

bool FGitCopyWorker::Execute(FGitSourceControlCommand& InCmd)
{
	check(InCmd.Operation->GetName() == GetName());
	// Copy or Move operation on a single file : Git does not need an explicit copy nor move,
	// but after a Move the Editor create a redirector file with the old asset name that points to the new asset.
	// The redirector needs to be commited with the new asset to perform a real rename.
	// => the following is to "MarkForAdd" the redirector, but it still need to be committed by selecting the whole directory and "check-in"
	InCmd.bCommandSuccessful = GitSourceControlUtils::RunCommand(TEXT("add"), InCmd.PathToGitBinary, InCmd.PathToRepositoryRoot, TArray<FString>(), InCmd.Files, InCmd.InfoMessages, InCmd.ErrorMessages);
	return InCmd.bCommandSuccessful;
}

bool FGitCopyWorker::UpdateStates() const
{
	return GitSourceControlUtils::UpdateCachedStates(OutStates);
}

FName FGitResolveWorker::GetName() const
{
	return "Resolve";
}

bool FGitResolveWorker::Execute(FGitSourceControlCommand& InCmd)
{
	check(InCmd.Operation->GetName() == GetName());
	// mark the conflicting files as resolved:
	{
		TArray<FString> Results;
		InCmd.bCommandSuccessful = GitSourceControlUtils::RunCommand(TEXT("add"), InCmd.PathToGitBinary, InCmd.PathToRepositoryRoot, TArray<FString>(), InCmd.Files, Results, InCmd.ErrorMessages);
	}
	// now update the status of our files
	GitSourceControlUtils::RunUpdateStatus(InCmd.PathToGitBinary, InCmd.PathToRepositoryRoot, InCmd.Files, InCmd.ErrorMessages, States);
	return InCmd.bCommandSuccessful;
}

