using namespace std;

// Helper function to perform an OR-query between positions i and j
int ask(int pos1, int pos2) {
    cout << "? " << pos1 << " " << pos2 << endl;
    int answer;
    cin >> answer;
    if (answer == -1) exit(0);
    return answer;
}

int main() {
    // Speed up I/O operations
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int size;
    if (!(cin >> size)) return 0;

    // Initialize list of possible indices for the zero element
    vector<int> possibles(size);
    iota(possibles.begin(), possibles.end(), 1);

    mt19937 gen(2025);  // Seeded RNG with different constant

    // Phase 1: Choose a promising pivot using sampling
    int chosen = -1;
    if (size > 30) {
        int sample_size = 6;
        int witness_count = 5;

        // Create shuffled index list for sampling
        vector<int> shuffled(size);
        iota(shuffled.begin(), shuffled.end(), 1);
        shuffle(shuffled.begin(), shuffled.end(), gen);

        vector<int> trial_pivots;
        for (int idx = 0; idx < sample_size; ++idx)
            trial_pivots.push_back(shuffled[idx]);

        vector<int> test_witnesses;
        for (int idx = sample_size; idx < sample_size + witness_count; ++idx)
            test_witnesses.push_back(shuffled[idx]);

        long long lowest_score = -1;

        for (int candidate : trial_pivots) {
            long long current_score = 0;
            for (int witness : test_witnesses) {
                current_score += ask(candidate, witness);
            }
            if (lowest_score == -1 || current_score < lowest_score) {
                lowest_score = current_score;
                chosen = candidate;
            }
        }
    } else {
        // For smaller inputs, pick a random index as pivot
        uniform_int_distribution<int> dist(0, size - 1);
        chosen = possibles[dist(gen)];
    }

    // Phase 2: Filter candidates based on query results with the pivot
    int min_response = -1;
    vector<pair<int, int>> results;
    results.reserve(size);

    for (int idx : possibles) {
        if (idx == chosen) continue;
        int val = ask(idx, chosen);
        if (min_response == -1 || val < min_response) {
            min_response = val;
        }
        results.emplace_back(idx, val);
    }

    // Update candidate list: include pivot and all minimizers
    vector<int> updated;
    updated.push_back(chosen);
    for (auto& entry : results) {
        if (entry.second == min_response) {
            updated.push_back(entry.first);
        }
    }
    possibles = move(updated);

    // Phase 3: Iteratively narrow down candidates using external pivots
    while (possibles.size() > 1) {
        int external = -1;
        while (true) {
            uniform_int_distribution<int> dist(1, size);
            external = dist(gen);
            bool found_match = false;
            for (int item : possibles) {
                if (item == external) {
                    found_match = true;
                    break;
                }
            }
            if (!found_match) break;
        }

        min_response = -1;
        results.clear();
        for (int idx : possibles) {
            int val = ask(idx, external);
            if (min_response == -1 || val < min_response) {
                min_response = val;
            }
            results.emplace_back(idx, val);
        }

        updated.clear();
        for (auto& pair : results) {
            if (pair.second == min_response) {
                updated.push_back(pair.first);
            }
        }
        possibles = move(updated);
    }

    // Phase 4: Reconstruct full array using identified zero position
    int zero_pos = possibles[0];
    vector<int> solution(size + 1);
    solution[zero_pos] = 0;

    for (int i = 1; i <= size; ++i) {
        if (i == zero_pos) continue;
        solution[i] = ask(i, zero_pos);
    }

    // Output final answer
    cout << "!";
    for (int i = 1; i <= size; ++i) {
        cout << " " << solution[i];
    }
    cout << endl;

    return 0;
}

#include "tempbuf.h"
namespace {
    static inline size_t DoubleSize(size_t current) noexcept {
        return current + current;
    }
} // namespace
void TTempBufOutput::DoWrite(const void* input, size_t length) {
    if (Y_LIKELY(length <= Remaining())) {
        AddData(input, length);
    } else {
        const size_t used = Used();
        TTempBuf buffer(DoubleSize(used + length));
        buffer.AddData(GetData(), used);
        buffer.AddData(input, length);
        static_cast<TTempBuf&>(*this) = buffer;
    }
}

