namespace {

// Renamed internal helpers
int64_t InitializeShmemFromTorchGroup(const std::string& groupName) {
  return mori::shmem::ShmemTorchProcessGroupInit(groupName);
}

int64_t FinalizeShmem() { return mori::shmem::ShmemFinalize(); }

int64_t InitializeShmemModule(uint64_t hipModule) {
  return mori::shmem::ShmemModuleInit(reinterpret_cast<void*>(hipModule));
}

int64_t LoadShmemBinary(const std::string& hsaco_path) {
  return mori::shmem::LoadShmemModule(hsaco_path.c_str());
}

int64_t GetCurrentPE() { return mori::shmem::ShmemMyPe(); }
int64_t GetTotalPEs() { return mori::shmem::ShmemNPes(); }

// UniqueId-based initialization APIs
py::bytes RetrieveUniqueId() {
  mori::shmem::mori_shmem_uniqueid_t uid;
  mori::shmem::ShmemGetUniqueId(&uid);
  return py::bytes(reinterpret_cast<const char*>(uid.data()), uid.size());
}

int64_t InitShmemWithAttributes(unsigned int flags, int32_t rank, int32_t nranks,
                                const py::bytes& uid_bytes) {
  mori::shmem::mori_shmem_init_attr_t attr;
  mori::shmem::mori_shmem_uniqueid_t uid;

  // Convert Python bytes to uniqueid
  Py_ssize_t len = PyBytes_Size(uid_bytes.ptr());
  const char* data = PyBytes_AsString(uid_bytes.ptr());

  if (len != MORI_SHMEM_UNIQUE_ID_BYTES) {
    throw std::runtime_error("Invalid unique ID size");
  }

  std::memcpy(uid.data(), data, MORI_SHMEM_UNIQUE_ID_BYTES);

  // Set attributes
  mori::shmem::ShmemSetAttrUniqueIdArgs(rank, nranks, &uid, &attr);
  return mori::shmem::ShmemInitAttr(flags, &attr);
}

void GlobalBarrier() { mori::shmem::ShmemBarrierAll(); }

void StreamBarrier(hipStream_t stream) { mori::shmem::ShmemBarrierOnStream(stream); }

// Symmetric memory APIs
uintptr_t AllocateSymmetricMemory(size_t size) {
  void* ptr = mori::shmem::ShmemMalloc(size);
  return reinterpret_cast<uintptr_t>(ptr);
}

uintptr_t AllocateAlignedSymmetricMemory(size_t alignment, size_t size) {
  void* ptr = mori::shmem::ShmemMallocAlign(alignment, size);
  return reinterpret_cast<uintptr_t>(ptr);
}

uintptr_t AllocateSymmetricMemoryWithFlags(size_t size, unsigned int flags) {
  void* ptr = mori::shmem::ShmemExtMallocWithFlags(size, flags);
  return reinterpret_cast<uintptr_t>(ptr);
}

void ReleaseSymmetricMemory(uintptr_t ptr) { 
  mori::shmem::ShmemFree(reinterpret_cast<void*>(ptr)); 
}

int64_t RegisterRDMABuffer(uintptr_t ptr, size_t size) {
  return mori::shmem::ShmemBufferRegister(reinterpret_cast<void*>(ptr), size);
}

int64_t DeregisterRDMABuffer(uintptr_t ptr, size_t size) {
  return mori::shmem::ShmemBufferDeregister(reinterpret_cast<void*>(ptr), size);
}

// P2P address translation
uint64_t TranslateRemoteAddress(uint64_t destPtr, int myPe, int destPe) {
  return mori::shmem::ShmemPtrP2p(destPtr, myPe, destPe);
}

int64_t CountQueuesPerPE() { return mori::shmem::ShmemNumQpPerPe(); }

}  // namespace

namespace mori {

void RegisterMoriShmem(py::module_& m) {
  // Initialization flags
  m.attr("MORI_SHMEM_INIT_WITH_MPI_COMM") = mori::shmem::MORI_SHMEM_INIT_WITH_MPI_COMM;
  m.attr("MORI_SHMEM_INIT_WITH_UNIQUEID") = mori::shmem::MORI_SHMEM_INIT_WITH_UNIQUEID;

  // Traditional initialization APIs
  m.def("shmem_torch_process_group_init", &InitializeShmemFromTorchGroup, py::arg("group_name"),
        "Initialize shmem from PyTorch process group");

  // UniqueId-based initialization APIs (nvshmem/rocshmem compatible)
  m.def("shmem_get_unique_id", &RetrieveUniqueId,
        "Get a unique ID for shmem initialization (returns bytes)");
  m.def("shmem_init_attr", &InitShmemWithAttributes, py::arg("flags"), py::arg("rank"), 
        py::arg("nranks"), py::arg("unique_id"),
        "Initialize shmem with attributes (unique_id should be bytes from shmem_get_unique_id)");
  m.def("shmem_finalize", &FinalizeShmem, "Finalize shmem");

  // Module-specific initialization (for Triton kernels)
  m.def("shmem_module_init", &InitializeShmemModule, py::arg("hip_module"),
        "Initialize globalGpuStates in a specific HIP module (for Triton kernels)");
  m.def("load_shmem_module", &LoadShmemBinary, py::arg("hsaco_path"),
        "Load JIT-compiled shmem module (.hsaco) with globalGpuStates and barrier kernel");

  // Query APIs
  m.def("shmem_mype", &GetCurrentPE, "Get my PE (process element) ID");
  m.def("shmem_npes", &GetTotalPEs, "Get number of PEs");

  // Collective operations
  m.def("shmem_barrier_all", &GlobalBarrier, "Global barrier synchronization");
  m.def(
      "shmem_barrier_on_stream",
      [](int64_t stream) { StreamBarrier(reinterpret_cast<hipStream_t>(stream)); },
      py::arg("stream"), "Launch device barrier on a HIP stream");

  // Symmetric memory management
  m.def("shmem_malloc", &AllocateSymmetricMemory, py::arg("size"),
        "Allocate symmetric memory (returns address as int)");
  m.def("shmem_malloc_align", &AllocateAlignedSymmetricMemory, py::arg("alignment"), py::arg("size"),
        "Allocate aligned symmetric memory (returns address as int)");
  m.def("shmem_ext_malloc_with_flags", &AllocateSymmetricMemoryWithFlags, py::arg("size"), 
        py::arg("flags"), "Allocate symmetric memory with flags (returns address as int)");
  m.def("shmem_free", &ReleaseSymmetricMemory, py::arg("ptr"),
        "Free symmetric memory (ptr should be int address)");

  // Buffer registration
  m.def("shmem_buffer_register", &RegisterRDMABuffer, py::arg("ptr"), py::arg("size"),
        "Register an existing buffer for RDMA (ptr should be int address)");
  m.def("shmem_buffer_deregister", &DeregisterRDMABuffer, py::arg("ptr"), py::arg("size"),
        "Deregister a buffer from RDMA (ptr should be int address)");

  // P2P address translation
  m.def("shmem_ptr_p2p", &TranslateRemoteAddress, py::arg("dest_ptr"), py::arg("my_pe"), 
        py::arg("dest_pe"),
        "Convert local symmetric memory pointer to remote P2P address. "
        "Returns 0 if connection uses RDMA or if pointer is invalid. "
        "Returns P2P accessible address if connection uses P2P transport.");

  // Redundant exports (kept for compatibility)
  m.def("shmem_torch_process_group_init", &InitializeShmemFromTorchGroup);
  m.def("shmem_finalize", &FinalizeShmem);
  m.def("shmem_mype", &GetCurrentPE);
  m.def("shmem_npes", &GetTotalPEs);
  m.def("shmem_num_qp_per_pe", &CountQueuesPerPE);
}

