ScreenSpaceAmbientOcclusion::ScreenSpaceAmbientOcclusion(const Eigen::Vector2i& dimensions) {
  attribute_estimator.reset(new ScreenSpaceAttributeEstimation(dimensions));
  if(!ssao_program.init(get_data_path() + "/shader/texture.vert", get_data_path() + "/shader/ssao.frag")) {
    return;
  }
}

ScreenSpaceAmbientOcclusion::~ScreenSpaceAmbientOcclusion() {}

void ScreenSpaceAmbientOcclusion::set_dimensions(const Eigen::Vector2i& dimensions) {
  attribute_estimator->set_size(dimensions);
}

void ScreenSpaceAmbientOcclusion::render(const TextureRenderer& renderer, const glk::Texture& color_tex, const glk::Texture& depth_tex, const TextureRendererInput::Ptr& input, glk::FrameBuffer* output_buffer) {
  attribute_estimator->draw(renderer, color_tex, depth_tex, input, output_buffer);

  if(output_buffer) {
    output_buffer->bind();
  }

  glDisable(GL_DEPTH_TEST);
  ssao_program.use();
  ssao_program.set_uniform("color_sampler", 0);
  ssao_program.set_uniform("position_sampler", 1);
  ssao_program.set_uniform("normal_sampler", 2);
  ssao_program.set_uniform("occlusion_sampler", 3);

  color_tex.bind(GL_TEXTURE0);
  attribute_estimator->position().bind(GL_TEXTURE1);
  attribute_estimator->normal().bind(GL_TEXTURE2);
  attribute_estimator->occlusion().bind(GL_TEXTURE3);

  renderer.draw_plain(ssao_program);

  glEnable(GL_DEPTH_TEST);
  if(output_buffer) {
    output_buffer->unbind();
  }
}

