// Multi-threaded logging test with random log types and timestamp/prefix toggling
int main() {
    const int num_threads = 8;
    std::thread worker_threads[num_threads];

    for (int idx = 0; idx < num_threads; idx++) {
        worker_threads[idx] = std::thread([idx]() {
            const int messages_per_thread = 1000;
            for (int msg_idx = 0; msg_idx < messages_per_thread; msg_idx++) {
                const int log_category = std::rand() % 4;
                switch (log_category) {
                    case 0: LOG_INF("Thread %d: %d\n", idx, msg_idx); break;
                    case 1: LOG_WRN("Thread %d: %d\n", idx, msg_idx); break;
                    case 2: LOG_ERR("Thread %d: %d\n", idx, msg_idx); break;
                    case 3: LOG_DBG("Thread %d: %d\n", idx, msg_idx); break;
                    default:
                        break;
                }

                if (std::rand() % 10 < 5) {
                    common_log_set_timestamps(common_log_main(), std::rand() % 2);
                    common_log_set_prefix(common_log_main(), std::rand() % 2);
                }
            }
        });
    }

    for (int idx = 0; idx < num_threads; idx++) {
        worker_threads[idx].join();
    }

    return 0;
}

