SVNUpdateDialog::SVNUpdateDialog(QWidget *parent, const QString &workDir,
                                 const QStringList &targetFiles, int iconsCount,
                                 bool isDirectoryOnly, bool updateToRev,
                                 bool nonRecurse)
    : Dialog(TApp::instance()->getMainWindow(), true, false)
    , m_updateSceneContentsCheckBox(0)
    , m_workDir(workDir)
    , m_targetFiles(targetFiles)
    , m_updateToRev(updateToRev)
    , m_nonRecurse(nonRecurse)
    , m_iconsCount(iconsCount)
    , m_someSceneIsMissing(false) {
  setModal(false);
  setMinimumSize(300, 180);
  setAttribute(Qt::WA_DeleteOnClose, true);
  setWindowTitle(tr("Version Control: Update"));
  QWidget *mainContainer = new QWidget;
  QVBoxLayout *mainLayout = new QVBoxLayout;
  mainLayout->setAlignment(Qt::AlignHCenter);
  mainLayout->setContentsMargins(0, 0, 0, 0);
  QHBoxLayout *topLayout = new QHBoxLayout;
  m_loadingLabel      = new QLabel;
  QMovie *loadingAnim = new QMovie(":Resources/waiting.gif");
  loadingAnim->setParent(this);
  m_loadingLabel->setMovie(loadingAnim);
  loadingAnim->setCacheMode(QMovie::CacheAll);
  loadingAnim->start();
  m_statusLabel = new QLabel(tr("Getting repository status..."));
  topLayout->addStretch();
  topLayout->addWidget(m_loadingLabel);
  topLayout->addWidget(m_statusLabel);
  topLayout->addStretch();
  mainLayout->addLayout(topLayout);
  m_outputArea = new QTextEdit;
  m_outputArea->setTextInteractionFlags(Qt::NoTextInteraction);
  m_outputArea->setReadOnly(true);
  m_outputArea->hide();
  mainLayout->addWidget(m_outputArea);
  m_conflictPanel = new ConflictWidget;
  m_conflictPanel->hide();
  mainLayout->addWidget(m_conflictPanel);
  m_datePickerWidget = new DateChooserWidget;
  m_datePickerWidget->hide();
  mainLayout->addWidget(m_datePickerWidget);
  if (!isDirectoryOnly) {
    QHBoxLayout *checkBoxLayout = new QHBoxLayout;
    checkBoxLayout->setContentsMargins(0, 0, 0, 0);
    m_updateSceneContentsCheckBox = new QCheckBox(this);
    m_updateSceneContentsCheckBox->setChecked(false);
    m_updateSceneContentsCheckBox->setText(tr("Get Scene Contents"));
    m_updateSceneContentsCheckBox->hide();
    connect(m_updateSceneContentsCheckBox, SIGNAL(toggled(bool)), this,
            SLOT(onUpdateSceneContentsToggled(bool)));
    checkBoxLayout->addStretch();
    checkBoxLayout->addWidget(m_updateSceneContentsCheckBox);
    checkBoxLayout->addStretch();
    mainLayout->addSpacing(10);
    mainLayout->addLayout(checkBoxLayout);
  }
  mainContainer->setLayout(mainLayout);
  beginHLayout();
  addWidget(mainContainer, false);
  endHLayout();
  m_applyButton = new QPushButton(tr("Update"));
  m_applyButton->hide();
  if (m_updateToRev)
    connect(m_applyButton, SIGNAL(clicked()), this,
            SLOT(onUpdateToRevisionButtonClicked()));
  else
    connect(m_applyButton, SIGNAL(clicked()), this,
            SLOT(onUpdateButtonClicked()));
  m_doneButton = new QPushButton(tr("Close"));
  m_doneButton->setEnabled(false);
  connect(m_doneButton, SIGNAL(clicked()), this, SLOT(close()));
  m_abortButton = new QPushButton(tr("Cancel"));
  connect(m_abortButton, SIGNAL(clicked()), this, SLOT(reject()));
  addButtonBarWidget(m_applyButton, m_doneButton, m_abortButton);
  // 0. Connect for svn errors (that may occur every time)
  connect(&m_worker, SIGNAL(error(const QString &)), this,
          SLOT(onError(const QString &)));
  // 1. Getting status
  connect(&m_worker, SIGNAL(statusRetrieved(const QString &)), this,
          SLOT(onStatusRetrieved(const QString &)));
  m_worker.getSVNStatus(m_workDir, m_targetFiles, true, false, true);
}
//-----------------------------------------------------------------------------
void SVNUpdateDialog::onStatusRetrieved(const QString &xmlResponse) {
  m_loadingLabel->hide();
  SVNStatusReader sr(xmlResponse);
  m_statusList = sr.getStatus();
  checkFiles();
  // Check if a scene files is found
  int targetSize = m_filesToUpdate.size();
  for (int i = 0; i < targetSize; i++) {
    if (m_filesToUpdate.at(i).endsWith(".tnz")) {
      if (targetSize == 1)
        m_statusLabel->setText(
            tr("%1 items to update.")
                .arg(m_filesToUpdate.size() + m_sceneResources.size()));
      else
        m_statusLabel->setText(tr("%1 items to update.")
                                 .arg(m_filesToUpdate.size() +
                                      m_sceneResources.size() -
                                      m_iconsCount));
      if (m_updateSceneContentsCheckBox && !m_someSceneIsMissing)
        m_updateSceneContentsCheckBox->show();
      m_applyButton->show();
      m_doneButton->hide();
      return;
    }
  }
  if (m_updateToRev) {
    if (m_conflictFiles.count() > 0) {
      m_statusLabel->setText(
          tr("Some items are currently modified in your working copy.\nPlease "
             "commit or revert changes first."));
      m_statusLabel->show();
      switchToDoneButton();
      return;
    }
    m_statusLabel->setText(tr("Update to:"));
    m_statusLabel->show();
    m_datePickerWidget->show();
    m_applyButton->show();
    m_doneButton->hide();
    adjustSize();
  } else {
    // Resolve first files with conflict
    if (m_conflictFiles.count() > 0) {
      m_statusLabel->setText(tr("Some conflict found. Select.."));
      m_statusLabel->show();
      m_applyButton->setEnabled(false);
      m_applyButton->show();
      m_doneButton->hide();
      QStringList conflictList;
      int conflictCount = m_conflictFiles.size();
      for (int i = 0; i < conflictCount; i++)
        conflictList.append(m_conflictFiles.at(i));
      m_conflictPanel->setFiles(conflictList);
      m_conflictPanel->show();
      adjustSize();
      connect(m_conflictPanel, SIGNAL(allConflictSetted()), this,
              SLOT(onConflictSetted()));
    } else
      updateFiles();
  }
}
//-----------------------------------------------------------------------------
void SVNUpdateDialog::checkFiles() {
  int statusCount = m_statusList.size();
  for (int i = 0; i < statusCount; i++) {
    SVNStatus s = m_statusList.at(i);
    if (s.m_path == "." || s.m_path == "..") continue;
    if ((m_updateToRev && s.m_item == "modified") ||
        (s.m_item == "modified" && s.m_repoStatus == "modified"))
      m_conflictFiles.prepend(s.m_path);
    else if (s.m_item == "none" || s.m_item == "missing" ||
             s.m_repoStatus == "modified" || s.m_repoStatus == "modified") {
      if (s.m_path.endsWith(".tnz") &&
          (s.m_item == "missing" ||
           (s.m_item == "none" && s.m_repoStatus == "added"))) {
        TFilePath scenePath =
            TFilePath(m_workDir.toStdWString()) + s.m_path.toStdWString();
        TFilePath iconPath = ToonzScene::getIconPath(scenePath);
        QDir dir(m_workDir);
#ifdef MACOSX
        m_filesToUpdate.append(dir.relativeFilePath(toQString(iconPath)));
#else
        m_filesToUpdate.append(
            dir.relativeFilePath(toQString(iconPath)).replace("/", "\\"));
#endif
        m_iconsCount++;
        m_someSceneIsMissing = true;
      }
      if (m_targetFiles.count() == 1 || m_targetFiles.contains(s.m_path))
        m_filesToUpdate.prepend(s.m_path);
    }
  }
}
//-----------------------------------------------------------------------------
void SVNUpdateDialog::updateFiles() {
  if (m_filesToUpdate.count() == 0) {
    QString msg = QString(tr("No items to update."));
    m_statusLabel->setText(msg);
    m_statusLabel->show();
    switchToDoneButton();
    return;
  }
  setMinimumSize(300, 200);
  if (m_updateSceneContentsCheckBox) m_updateSceneContentsCheckBox->hide();
  m_applyButton->setEnabled(false);
  m_loadingLabel->hide();
  m_statusLabel->hide();
  m_outputArea->show();
  QStringList args;
  args << "update";
  int fileCount = m_filesToUpdate.count();
  for (int i = 0; i < fileCount; i++) {
    QString file = m_filesToUpdate.at(i);
    if (!file.isEmpty()) args << file;
  }
  int resourceCount = m_sceneResources.size();
  for (int i = 0; i < resourceCount; i++) args << m_sceneResources.at(i);
  if (m_nonRecurse) args << "--non-recursive";
  m_worker.disconnect(SIGNAL(done(const QString &)));
  connect(&m_worker, SIGNAL(outputRetrieved(const QString &)),
          SLOT(addOutputText(const QString &)));
  connect(&m_worker, SIGNAL(done(const QString &)),
          SLOT(onUpdateDone(const QString &)));
  m_worker.executeCommand(m_workDir, "svn", args, false);
}
//-----------------------------------------------------------------------------
void SVNUpdateDialog::switchToDoneButton() {
  if (m_updateSceneContentsCheckBox) m_updateSceneContentsCheckBox->hide();
  m_abortButton->hide();
  m_applyButton->hide();
  m_doneButton->show();
  m_doneButton->setEnabled(true);
}
//-----------------------------------------------------------------------------
void SVNUpdateDialog::addOutputText(const QString &text) {
  QRegExp regExp("Updated to revision (\\d+)\\.");
  QString temp = text;
  temp.remove(regExp);
  QStringList split = temp.split(QRegExp("\\r\\n|\\n"));
  for (int i = 0; i < split.size(); i++) {
    QString s = split.at(i);
    if (!s.isEmpty()) m_outputArea->insertPlainText(s + "\n");
  }
  QScrollBar *scrollBar = m_outputArea->verticalScrollBar();
  scrollBar->setValue(scrollBar->maximum());
}
//-----------------------------------------------------------------------------
void SVNUpdateDialog::onUpdateToRevisionButtonClicked() {
  m_statusLabel->hide();
  m_abortButton->hide();
  m_applyButton->hide();
  m_datePickerWidget->hide();
  m_outputArea->show();
  QStringList args;
  args << "update";
  // Pay attention: I have to perform update of the whole selected files
  // (that could become updatable "looking in the past")
  int fileCount = m_targetFiles.count();
  for (int i = 0; i < fileCount; i++) {
    QString file = m_targetFiles.at(i);
    if (!file.isEmpty()) args << file;
  }
  QString revisionString = m_datePickerWidget->getRevisionString();
  args << "-r" << revisionString;
  connect(&m_worker, SIGNAL(outputRetrieved(const QString &)),
          SLOT(addOutputText(const QString &)));
  connect(&m_worker, SIGNAL(done(const QString &)),
          SLOT(onUpdateDone(const QString &)));
  m_worker.executeCommand(m_workDir, "svn", args, false);
}
//-----------------------------------------------------------------------------
void SVNUpdateDialog::onUpdateButtonClicked() {
  // Update to mine
  QStringList files = m_conflictPanel->getFilesWithOption(0);
  if (files.size() > 0) {
    m_loadingLabel->show();
    m_statusLabel->setText(tr("Updating items..."));
    QStringList args;
    args << "update";
    args.append(files);
    args << "--accept"
         << "mine-full";
    m_worker.disconnect(SIGNAL(done(const QString &)));
    connect(&m_worker, SIGNAL(done(const QString &)),
            SLOT(onUpdateToMineDone()));
    m_worker.executeCommand(m_workDir, "svn", args);
  } else
    onUpdateToMineDone();
}
//-----------------------------------------------------------------------------
void SVNUpdateDialog::onUpdateToMineDone() {
  // Update to theirs
  QStringList files = m_conflictPanel->getFilesWithOption(1);
  if (files.size() > 0) {
    m_loadingLabel->show();
    m_statusLabel->setText(tr("Updating to their items..."));
    QStringList args;
    args << "update";
    args.append(files);
    args << "--accept"
         << "theirs-full";
    m_worker.disconnect(SIGNAL(done(const QString &)));
    connect(&m_worker, SIGNAL(done(const QString &)),
            SLOT(onConflictResolved()));
    m_worker.executeCommand(m_workDir, "svn", args);
  } else
    onConflictResolved();
}
//-----------------------------------------------------------------------------
void SVNUpdateDialog::onConflictResolved() {
  m_conflictPanel->hide();
  updateFiles();
}
//-----------------------------------------------------------------------------
void SVNUpdateDialog::onError(const QString &errorString) {
  m_loadingLabel->hide();
  if (m_outputArea->isVisible())
    addOutputText(errorString);
  else {
    m_statusLabel->setText(errorString);
    m_statusLabel->show();
  }
  switchToDoneButton();
}
//-----------------------------------------------------------------------------
void SVNUpdateDialog::onUpdateDone(const QString &text) {
  addOutputText(text);
  QStringList files;
  for (int i = 0; i < m_filesToUpdate.size(); i++)
    files.append(m_filesToUpdate.at(i));
  emit done(files);
  switchToDoneButton();
}
//-----------------------------------------------------------------------------
void SVNUpdateDialog::onConflictSetted() { m_applyButton->setEnabled(true); }
//-----------------------------------------------------------------------------
void SVNUpdateDialog::onUpdateSceneContentsToggled(bool checked) {
  if (!checked)
    m_sceneResources.clear();
  else {
    VersionControl *vc = VersionControl::instance();
    int targetSize = m_filesToUpdate.count();
    for (int i = 0; i < targetSize; i++) {
      QString fileName = m_filesToUpdate.at(i);
      if (fileName.endsWith(".tnz"))
        m_sceneResources.append(vc->getSceneContents(m_workDir, fileName));
    }
  }
  if (m_filesToUpdate.size() == 1)
    m_statusLabel->setText(
        tr("%1 items to update.")
            .arg(m_filesToUpdate.size() + m_sceneResources.size()));
  else
    m_statusLabel->setText(tr("%1 items to update.")
                             .arg(m_filesToUpdate.size() +
                                  m_sceneResources.size() - m_iconsCount));
}

