namespace {
inline bool supportsRandomAccess(const TFilePath &path) {
  const std::string &format = path.getType();
  if (format == "pli") return false;
  return format == "tlv" ||  // TLVs do support random access
                           // format == "pli" || // PLIs... I thought they would -
                           // but no :( format == "mov" || // MOVs are 'on the
                           // way' to support it... for now, no
         path.getDots() == "..";  // Multi-file levels of course do
}
//-----------------------------------------------------------------------------
void enforceBpp(TPropertyGroup *group, int bits, bool onlyIncrease) {
  // Most properties have a "Bits Per Pixel" property. Enforce the M there in
  // case.
  TEnumProperty *bitsProp = (TEnumProperty *)group->getProperty("Bits Per Pixel");
  if (bitsProp) {
    typedef TEnumProperty::Range Range;
    const Range &range = bitsProp->getRange();
    // Retrieve current index
    int idx = bitsProp->getIndex();
    // Search for a suitable 32-bit or 64-bit value
    int currentBpp = onlyIncrease ? std::stoi(bitsProp->getValueAsString()) : 0;
    int targetBpp = (std::numeric_limits<int>::max)(), targetIdx = -1;
    int i, count = (int)range.size();
    for (i = 0; i < count; ++i) {
      int bppEntry = std::stoi(range[i]);
      if ((bppEntry % bits == 0) && currentBpp <= bppEntry &&
          bppEntry < targetBpp)
        targetBpp = bppEntry, targetIdx = i;
    }
    if (targetIdx >= 0) bitsProp->setIndex(targetIdx);
  }
  // Some properties have an "Alpha Channel" TBoolProperty (PNGs, currently). In
  // case, check that.
  if (bits % 32 == 0) {
    TBoolProperty *alphaProp =
        (TBoolProperty *)group->getProperty("Alpha Channel");
    if (alphaProp) alphaProp->setValue(true);
  }
}
