DEFINE_string(inputDirectory, "", "Directory containing KML files.");
DEFINE_string(outputDirectory, "", "Directory for converted KML files.");
DEFINE_int32(vehicleCategory, 0,
             "Numeric identifier corresponding to routing::VehicleType. "
             "Defaults to pedestrian.");
DEFINE_bool(displayHelp, false, "Display help information for all flags.");

int main(int argc, char ** argv)
{
  gflags::SetProgramUsageMessage(
      "This utility generates smoother tracks from waypoints in KML files. "
      "Input KMLs must include points within a LineString element. "
      "If route construction fails, the original path remains unchanged. "
      "Multiple KML files in the input directory are processed.\n\n"
