#include <iostream>
#include <string>
#include <memory>
#include <csignal>
#include <cstring>
#include <gz/transport/Node.hh>
#include <gz/msgs/image.pb.h>
#include <gst/gst.h>
#include <gst/app/gstappsrc.h>

// Global elements for GStreamer pipeline
GstElement *pipeline = nullptr;
GMainLoop *mainLoop = nullptr;
GstElement *sourceApp = nullptr;
bool initialized = false;

// Configuration parameters (defaults modified)
std::string DEST_IP = "127.0.0.1";
int DEST_PORT = 5601;
int FPS = 15;

// Callback invoked on receiving image message from Gazebo
void frame_callback(const gz::msgs::Image &img) {
    if (!sourceApp) return;

    // Initialize caps only once — on first frame arrival
    if (!initialized) {
        GstCaps *caps = gst_caps_new_simple("video/x-raw",
            "format", G_TYPE_STRING, "RGB",
            "width", G_TYPE_INT, img.width(),
            "height", G_TYPE_INT, img.height(),
            "framerate", GST_TYPE_FRACTION, FPS, 1,
            NULL);

        gst_app_src_set_caps(GST_APP_SRC(sourceApp), caps);
        gst_caps_unref(caps);

        std::cout << "GStreamer configured for resolution " << img.width() << "x" << img.height() << std::endl;
        initialized = true;
    }

    // Transfer image data to GStreamer buffer
    gsize dataLen = img.data().size();
    GstBuffer *buf = gst_buffer_new_allocate(NULL, dataLen, NULL);
    if (buf) {
        gst_buffer_fill(buf, 0, img.data().c_str(), dataLen);
        GstFlowReturn res = gst_app_src_push_buffer(GST_APP_SRC(sourceApp), buf);
        if (res != GST_FLOW_OK) {
            g_warning("Failed to push buffer into appsrc");
        }
    } else {
        g_warning("Unable to allocate buffer for GStreamer");
    }
}

// Detect presence of NVIDIA hardware encoder
bool has_nvidia_encoder() {
    GstElementFactory *factory = gst_element_factory_find("nvh264enc");
    bool found = (factory != nullptr);
    if (found) gst_object_unref(factory);
    return found;
}

// Signal handler for graceful shutdown
void sigterm_handler(int signal) {
    (void)signal; // Avoid unused parameter warning
    if (mainLoop) g_main_loop_quit(mainLoop);
}

int main(int argc, char **argv) {
    if (argc < 3) {
        std::cerr << "Usage: ./gz_gst_bridge <gz_topic> <ip_address> [port] [fps]\n";
        return 1;
    }

    std::string topicName = argv[1];
    DEST_IP = argv[2];
    if (argc > 3) DEST_PORT = std::stoi(argv[3]);
    if (argc > 4) FPS = std::stoi(argv[4]);

    // Initialize GStreamer and Gazebo transport node
    gst_init(&argc, &argv);
    gz::transport::Node node;

    // Construct GStreamer pipeline string
    std::string pipelineDesc;
    std::string endpoint = "host=" + DEST_IP + " port=" + std::to_string(DEST_PORT);

    if (has_nvidia_encoder()) {
        std::cout << "Detected NVIDIA GPU encoder (nvh264enc); using GPU path\n";
        pipelineDesc = "appsrc name=gz_source ! queue max-size-buffers=1 leaky=downstream ! "
                        "videoconvert ! "
                        "nvh264enc preset=low-latency-hq zerolatency=true rc-mode=cbr bitrate=2048 qp-min=15 qp-max=35 gop-size=30 ! "
                        "rtph264pay config-interval=1 mtu=1400 ! udpsink sync=false " + endpoint;
    } else {
        std::cout << "Falling back to CPU encoder (x264enc)\n";
        pipelineDesc = "appsrc name=gz_source ! queue max-size-buffers=1 leaky=downstream ! "
                        "videoconvert ! "
                        "x264enc speed-preset=ultrafast tune=zerolatency bitrate=2048 key-int-max=30 ! "
                        "rtph264pay config-interval=1 mtu=1400 ! udpsink sync=false " + endpoint;
    }

    // Launch pipeline
    GError *err = nullptr;
    pipeline = gst_parse_launch(pipelineDesc.c_str(), &err);
    if (!pipeline) {
        std::cerr << "Pipeline creation failed: " << err->message << std::endl;
        return -1;
    }

    // Retrieve and configure appsrc element
    sourceApp = gst_bin_get_by_name(GST_BIN(pipeline), "gz_source");
    g_object_set(sourceApp, "format", GST_FORMAT_TIME, NULL);
    g_object_set(sourceApp, "is-live", TRUE, NULL);
    g_object_set(sourceApp, "do-timestamp", TRUE, NULL);
    g_object_set(sourceApp, "leaky-type", 2, NULL); // Drop outdated buffers
    g_object_set(sourceApp, "max-bytes", 0, NULL);
    g_object_set(sourceApp, "max-buffers", 3, NULL); // Increased buffer limit slightly

    // Start pipeline
    gst_element_set_state(pipeline, GST_STATE_PLAYING);

    // Subscribe to Gazebo topic
    if (!node.Subscribe(topicName, frame_callback)) {
        std::cerr << "Failed to subscribe to topic: " << topicName << std::endl;
        return -1;
    }

    std::cout << "Streaming " << topicName << " to " << DEST_IP << ":" << DEST_PORT 
              << " at " << FPS << " frames/sec." << std::endl;

    // Enter main loop
    mainLoop = g_main_loop_new(NULL, FALSE);
    signal(SIGINT, sigterm_handler);
    g_main_loop_run(mainLoop);

    // Cleanup resources
    gst_element_set_state(pipeline, GST_STATE_NULL);
    gst_object_unref(sourceApp);
    gst_object_unref(pipeline);
    g_main_loop_unref(mainLoop);

    return 0;
}

