namespace infiniop_test::rope {

struct Test::Attributes {
    infiniopRoPEAlgo_t method;
    std::shared_ptr<Tensor> output;
    std::shared_ptr<Tensor> input;
    std::shared_ptr<Tensor> indices;
    std::shared_ptr<Tensor> sine_table;
    std::shared_ptr<Tensor> cosine_table;
    std::shared_ptr<Tensor> reference;
};

std::shared_ptr<Test> Test::build(
    std::unordered_map<std::string, std::vector<uint8_t>> params,
    std::unordered_map<std::string, std::shared_ptr<Tensor>> tensors,
    double rel_tol, double abs_tol) {
    auto test = std::shared_ptr<Test>(new Test(rel_tol, abs_tol));
    test->_attributes = new Attributes();

    if (!check_names(params, Test::attribute_names()) || 
        tensors.find("output") == tensors.end() ||
        tensors.find("input") == tensors.end() ||
        tensors.find("indices") == tensors.end() ||
        tensors.find("sine_table") == tensors.end() ||
        tensors.find("cosine_table") == tensors.end() ||
        tensors.find("reference") == tensors.end()) {
        throw std::runtime_error("Invalid Test configuration");
    }

    test->_attributes->method = *reinterpret_cast<infiniopRoPEAlgo_t *>(params["algo"].data());
    test->_attributes->output = tensors["output"];
    test->_attributes->input = tensors["input"];
    test->_attributes->indices = tensors["indices"];
    test->_attributes->sine_table = tensors["sine_table"];
    test->_attributes->cosine_table = tensors["cosine_table"];
    test->_attributes->reference = tensors["reference"];

    return test;
}

std::shared_ptr<infiniop_test::Result> Test::run(
    infiniopHandle_t handle, infiniDevice_t device, int device_id, size_t warmup_count, size_t repeat_count) {
    infiniopRoPEDescriptor_t op_desc;
    infiniopRoPEAlgo_t algo = _attributes->method;

    auto y_tensor = _attributes->output->to(device, device_id);
    auto x_tensor = _attributes->input->to(device, device_id);
    auto pos_tensor = _attributes->indices->to(device, device_id);
    auto sin_tensor = _attributes->sine_table->to(device, device_id);
    auto cos_tensor = _attributes->cosine_table->to(device, device_id);

    CHECK_OR(infiniopCreateRoPEDescriptor(handle, &op_desc,
                                          y_tensor->desc(),
                                          x_tensor->desc(),
                                          pos_tensor->desc(),
                                          sin_tensor->desc(),
                                          cos_tensor->desc(),
                                          algo),
             return TEST_FAILED(OP_CREATION_FAILED, "Failed to create RoPE operator descriptor."));

    size_t scratchpad_size;
    CHECK_OR(infiniopGetRoPEWorkspaceSize(op_desc, &scratchpad_size),
             return TEST_FAILED(OP_CREATION_FAILED, "Unable to determine workspace size."));

    void *scratchpad;
    CHECK_OR(infinirtMalloc(&scratchpad, scratchpad_size),
             return TEST_FAILED(OP_CREATION_FAILED, "Workspace allocation failed."));

    CHECK_OR(infiniopRoPE(op_desc, scratchpad, scratchpad_size,
                          y_tensor->data(),
                          x_tensor->data(),
                          pos_tensor->data(),
                          sin_tensor->data(),
                          cos_tensor->data(),
                          nullptr),
             return TEST_FAILED(OP_EXECUTION_FAILED, "RoPE operation execution failed."));

    try {
        allClose(y_tensor, _attributes->reference, _rtol, _atol);
    } catch (const std::exception &e) {
        return TEST_FAILED(RESULT_INCORRECT, e.what());
    }

    double duration_ms = 0.;
    duration_ms = benchmark(
        [=]() {
            infiniopRoPE(
                op_desc, scratchpad, scratchpad_size,
                y_tensor->data(),
                x_tensor->data(),
                pos_tensor->data(),
                sin_tensor->data(),
                cos_tensor->data(),
                nullptr);
        },
        warmup_count, repeat_count);

    return TEST_PASSED(duration_ms);
}

std::vector<std::string> Test::attribute_names() {
    return {"algo"};
}

std::vector<std::string> Test::tensor_names() {
    return {"output", "input", "indices", "sine_table", "cosine_table", "reference"};
}

std::vector<std::string> Test::output_names() {
    return {"output"};
}

std::string Test::toString() const {
    std::ostringstream stream;
    stream << op_name() << std::endl;
    stream << "- output: " << _attributes->output->info() << std::endl;
    stream << "- input: " << _attributes->input->info() << std::endl;
    stream << "- indices: " << _attributes->indices->info() << std::endl;
    stream << "- sine_table: " << _attributes->sine_table->info() << std::endl;
    stream << "- cosine_table: " << _attributes->cosine_table->info() << std::endl;
    stream << "- method: " << _attributes->method << std::endl;
    stream << std::scientific << std::setprecision(2);
    stream << "- rtol=" << _rtol << ", atol=" << _atol << std::endl;
    return stream.str();
}

Test::~Test() {
    delete _attributes;
}

