#include <iostream>
#include <vector>
#include <cmath>
#include <algorithm>
#include <random>
#include <chrono>
using namespace std;

// Upper bound for N based on problem constraints
const int MAX_SIZE = 1000005;

// Global arrays for computation
int min_prime[MAX_SIZE];     // Smallest prime factor for each number
int best_sequence[MAX_SIZE]; // Best sequence found so far
int temp_sequence[MAX_SIZE]; // Sequence used during current evaluation
int input_N;

// Precompute smallest prime factors using modified Sieve of Eratosthenes
void precompute_primes() {
    for (int i = 1; i <= input_N; ++i) {
        min_prime[i] = i;
    }
    for (int p = 2; p * p <= input_N; ++p) {
        if (min_prime[p] == p) { // p is prime
            for (int multiple = p * p; multiple <= input_N; multiple += p) {
                if (min_prime[multiple] == multiple) {
                    min_prime[multiple] = p;
                }
            }
        }
    }
}

int main() {
    // Speed up I/O operations
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    if (!(cin >> input_N)) return 0;

    precompute_primes();

    // First pass: Deterministic greedy approach
    long long running_sum = 0;
    long long worst_prefix = 0;

    temp_sequence[1] = 1;
    running_sum = 1;
    worst_prefix = 1;

    for (int num = 2; num <= input_N; ++num) {
        if (min_prime[num] == num) { // num is prime
            if (running_sum > 0) {
                temp_sequence[num] = -1;
            } else if (running_sum < 0) {
                temp_sequence[num] = 1;
            } else {
                temp_sequence[num] = -1; // Default choice on tie
            }
        } else { // Composite number
            int prime_factor = min_prime[num];
            temp_sequence[num] = temp_sequence[prime_factor] * temp_sequence[num / prime_factor];
        }

        running_sum += temp_sequence[num];
        long long abs_val = llabs(running_sum);
        if (abs_val > worst_prefix) {
            worst_prefix = abs_val;
        }
    }

    // Save deterministic result as initial best
    long long optimal_max = worst_prefix;
    for (int idx = 1; idx <= input_N; ++idx) {
        best_sequence[idx] = temp_sequence[idx];
    }

    // Second pass: Randomized greedy with restarts and early termination
    mt19937_64 engine(chrono::high_resolution_clock::now().time_since_epoch().count());
    auto begin_timing = chrono::high_resolution_clock::now();

    while (true) {
        auto now_timing = chrono::high_resolution_clock::now();
        if (chrono::duration_cast<chrono::milliseconds>(now_timing - begin_timing).count() > 800) break;

        int tolerance = engine() % 3; // 0, 1, or 2

        running_sum = 1;
        long long current_worst = 1;
        bool viable = true;

        temp_sequence[1] = 1;

        for (int val = 2; val <= input_N; ++val) {
            if (min_prime[val] == val) { // Prime case
                if (llabs(running_sum) <= tolerance) {
                    // Random decision within tolerance zone
                    temp_sequence[val] = (engine() & 1) ? 1 : -1;
                } else {
                    // Greedy correction outside tolerance
                    temp_sequence[val] = (running_sum > 0) ? -1 : 1;
                }
            } else { // Composite case
                int base_prime = min_prime[val];
                temp_sequence[val] = temp_sequence[base_prime] * temp_sequence[val / base_prime];
            }

            running_sum += temp_sequence[val];
            long long abs_sum = llabs(running_sum);
            if (abs_sum > current_worst) {
                current_worst = abs_sum;
            }

            // Early exit if current path cannot improve upon best known
            if (current_worst >= optimal_max) {
                viable = false;
                break;
            }
        }

        if (viable) {
            optimal_max = current_worst;
            for (int pos = 1; pos <= input_N; ++pos) {
                best_sequence[pos] = temp_sequence[pos];
            }
            if (optimal_max <= 2) break;
        }
    }

    // Output final sequence
    for (int i = 1; i <= input_N; ++i) {
        cout << best_sequence[i];
        if (i < input_N) cout << " ";
    }
    cout << "\n";

    return 0;
}

