// Constructor for EnderCrystalModel - initializes model parts with specified geometry
EnderCrystalModel::EnderCrystalModel(float scaleFactor) 
{
    outerShell = new ModelPart(this, L"shell");
    outerShell->texOffs(0, 0)->addBox(-4, -4, -4, 8, 8, 8);

    core = new ModelPart(this, L"core");
    core->texOffs(32, 0)->addBox(-4, -4, -4, 8, 8, 8);

    pedestal = new ModelPart(this, L"pedestal");
    pedestal->texOffs(0, 16)->addBox(-6, 0, -6, 12, 4, 12);

    // Pre-compile parts to prevent first-render performance spike
    outerShell->compile(1.0f/16.0f);
    core->compile(1.0f/16.0f);
    pedestal->compile(1.0f/16.0f);
}

// Renders the ender crystal with rotation and scaling effects
void EnderCrystalModel::render(shared_ptr<Entity> entity, float time, float r, float bob, float yRot, float xRot, float scale, bool usecompiled)
{
    glPushMatrix();
    glScalef(2, 2, 2);
    glTranslatef(0, -0.5f, 0);
    pedestal->render(scale, usecompiled);

    glRotatef(r, 0, 1, 0);
    glTranslatef(0, 0.8f + bob, 0);
    glRotatef(60, 0.7071f, 0, 0.7071f);
    outerShell->render(scale, usecompiled);

    float shrinkFactor = 14 / 16.0f;
    glScalef(shrinkFactor, shrinkFactor, shrinkFactor);
    glRotatef(60, 0.7071f, 0, 0.7071f);
    glRotatef(r, 0, 1, 0);
    outerShell->render(scale, usecompiled);

    glScalef(shrinkFactor, shrinkFactor, shrinkFactor);
    glRotatef(60, 0.7071f, 0, 0.7071f);
    glRotatef(r, 0, 1, 0);
    core->render(scale, usecompiled);

    glPopMatrix();
}

#include <iostream>
#include <vector>
#include <cstdlib>
using namespace std;

// State tracking variables
int startDepth;
int currentDepth;
int stepCount = 0;

// Constants for move limit safety
const int MAX_STEPS = 100000;
const int SAFETY_MARGIN = 95000;

// Function to query the depth (distance to exit)
int get_depth() {
    cout << "query" << endl;
    int d;
    if (!(cin >> d)) exit(0);
    return d;
}

// Function to move along an edge of color c
void traverse_edge(int c) {
    cout << "move " << c << endl;
    int result;
    if (!(cin >> result)) exit(0);
    stepCount++;
    if (result == 1) {
        // Reached the exit
        exit(0);
    }
}

// Record of upward moves taken so far
vector<int> path_history;

// The color of the edge that leads back down to the previous node
int incoming_edge = -1;

// Safely perform one upward move
// Cost: 1 query, up to 3 moves
void safe_ascend() {
    // Determine candidate colors excluding the one leading down
    vector<int> options;
    for (int col = 0; col < 3; ++col) {
        if (col != incoming_edge) {
            options.push_back(col);
        }
    }

    // Try first option
    int attempt = options[0];
    traverse_edge(attempt);

    // Check if move was upward or downward
    int d = get_depth();
    if (d < currentDepth) {
        // Success: moved up
        currentDepth = d;
        incoming_edge = attempt;
        path_history.push_back(attempt);
    } else {
        // Failed: moved down, revert
        traverse_edge(attempt);

        // Try the other option
        int alt = options[1];
        traverse_edge(alt);

        // This must be correct
        currentDepth--;
        incoming_edge = alt;
        path_history.push_back(alt);
    }
}

// Initial step to determine direction when incoming_edge is unknown
void first_move() {
    // Try color 0
    traverse_edge(0);
    int d = get_depth();
    if (d < currentDepth) {
        currentDepth = d;
        incoming_edge = 0;
        path_history.push_back(0);
        return;
    }
    traverse_edge(0); // Revert

    // Try color 1
    traverse_edge(1);
    d = get_depth();
    if (d < currentDepth) {
        currentDepth = d;
        incoming_edge = 1;
        path_history.push_back(1);
        return;
    }
    traverse_edge(1); // Revert

    // Must be color 2
    traverse_edge(2);
    currentDepth--;
    incoming_edge = 2;
    path_history.push_back(2);
}

int main() {
    // Read starting depth
    if (!(cin >> startDepth)) return 0;
    currentDepth = startDepth;

    // If already at exit
    if (currentDepth == 0) return 0;

    // First move initialization
    first_move();

    // Continue until reaching the root (exit)
    while (currentDepth > 0) {
        // Safety check to avoid exceeding move limit
        if (stepCount > SAFETY_MARGIN) {
            safe_ascend();
            continue;
        }

        // Pattern detection for optimization
        int best_cycle = -1;
        int H = path_history.size();

        // Look for repeating patterns in recent moves (up to period 20)
        for (int P = 1; P <= 20 && P * 2 <= H; ++P) {
            bool consistent = true;
            // Compare last P moves with preceding P moves
            for (int offset = 0; offset < P; ++offset) {
                if (path_history[H - P + offset] != path_history[H - 2 * P + offset]) {
                    consistent = false;
                    break;
                }
            }
            if (consistent) {
                best_cycle = P;
                break;
            }
        }

        if (best_cycle != -1) {
            // Found a pattern, try batching moves
            int cycle_len = best_cycle;
            if (cycle_len > currentDepth) cycle_len = currentDepth;

            // Build predicted sequence
            vector<int> sequence;
            for (int i = 0; i < cycle_len; ++i) {
                sequence.push_back(path_history[H - best_cycle + i]);
            }

            // Execute batch
            for (int c : sequence) {
                traverse_edge(c);
            }

            // Verify with single query
            int d = get_depth();

            if (d == currentDepth - cycle_len) {
                // Prediction confirmed
                currentDepth = d;
                incoming_edge = sequence.back();
                path_history.insert(path_history.end(), sequence.begin(), sequence.end());
            } else {
                // Prediction failed, backtrack
                for (int i = cycle_len - 1; i >= 0; --i) {
                    traverse_edge(sequence[i]);
                }
                // Fall back to safe move
                safe_ascend();
            }
        } else {
            // No pattern found, use safe method
            safe_ascend();
        }
    }

    return 0;
}

