#include <iostream>
#include <vector>
#include <map>
#include <stack>
using namespace std;

// Memoization map to store results of previous queries for efficiency
map<pair<int, int>, pair<int, int>> memoized_results;

// Function to execute a query and cache its result
pair<int, int> execute_query(int left, int right) {
    if (left > right) {
        return {-1, 0};
    }

    // Check if the result is already cached
    if (memoized_results.find({left, right}) != memoized_results.end()) {
        return memoized_results[{left, right}];
    }

    cout << "? " << left << " " << right << endl;
    int value, frequency;
    cin >> value >> frequency;

    // Handle invalid input or termination condition
    if (value == -1 && frequency == -1) {
        exit(0);
    }

    // Store and return the result
    return memoized_results[{left, right}] = {value, frequency};
}

// Result array, using 1-based indexing
vector<int> solution_array;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;
    solution_array.resize(n + 1, 0);

    // Stack-based iterative approach for divide-and-conquer
    stack<pair<int, int>> segments_to_process;
    segments_to_process.push({1, n});

    while (!segments_to_process.empty()) {
        auto [l, r] = segments_to_process.top();
        segments_to_process.pop();

        if (l > r) continue;

        auto [mode_value, mode_freq] = execute_query(l, r);

        // Binary search to find the rightmost position of the mode segment
        int right_boundary = r;
        int left_search_bound = l + mode_freq - 1;
        int right_search_bound = r;

        while (left_search_bound <= right_search_bound) {
            int mid = left_search_bound + (right_search_bound - left_search_bound) / 2;
            auto [mid_val, mid_freq] = execute_query(l, mid);

            if (mid_val == mode_value && mid_freq >= mode_freq) {
                right_boundary = mid;
                right_search_bound = mid - 1;
            } else {
                left_search_bound = mid + 1;
            }
        }

        int left_boundary = right_boundary - mode_freq + 1;

        // Assign the mode value to the identified segment
        for (int idx = left_boundary; idx <= right_boundary; ++idx) {
            solution_array[idx] = mode_value;
        }

        // Add remaining subsegments to the processing stack
        segments_to_process.push({l, left_boundary - 1});
        segments_to_process.push({right_boundary + 1, r});
    }

    // Output final answer
    cout << "! ";
    for (int i = 1; i <= n; ++i) {
        cout << solution_array[i];
        if (i < n) cout << " ";
    }
    cout << endl;

    return 0;
}

