    for (const auto& str : secondary_data) {
      WriteStr(writer, str.c_str(), str.size());
    }

    ASSERT_EQ(allocator.Counter(), initial_mem_usage);
  }

  // all memory should be freed after scope exit
  ASSERT_EQ(allocator.Counter(), 0);
}

