#include <sol/sol.hpp>
#include <iostream>

int add_twenty(int input) {
    return 20 + input;
}

std::string prepend_text(std::string message) {
    return "received: " + message;
}

sol::variadic_results handler(
    sol::this_state state, sol::variadic_args arguments) {
    sol::variadic_results result;
    if (arguments.size() == 2) {
        result.push_back({ state,
            sol::in_place,
            arguments.get<int>(0) + arguments.get<int>(1) });
    }
    else {
        result.push_back({ state, sol::in_place, 52 });
    }
    return result;
}

int main(int, char*[]) {
    std::cout << "=== overloading with fallback ==="
              << std::endl;
    sol::state lua;
    lua.open_libraries();
    lua.set_function(
        "g", sol::overload(add_twenty, prepend_text, handler));
    lua.script("print(g(1))");      // add_twenty
    lua.script("print(g('hi'))");   // prepend_text
    lua.script("print(g(22, 11))"); // handler
    lua.script("print(g({}))");     // handler
    return 0;
}

