namespace engine::store::pythonBase {

Error IPythonInstanceBase::writeQuestions(
    const pybind11::object &questionObj) noexcept {
    py::object result;
    Error errCode;
    LOGPIPE();

    // If the WriteQuestions method is not registered, delegate to parent
    if (!(m_pyMethods & PythonMethod::WriteQuestions))
        return Parent::writeQuestions(questionObj);

    // Define the Python callback function
    auto pythonCallback = localfcn()->Error {
        // Execute the Python method
        m_pyInstance.attr("writeQuestions")(questionObj);
        return {};
    };

    // Invoke the Python callback
    errCode = callPython(pythonCallback);

    // If parent invocation is required based on error code
    if (checkCallParent(errCode)) 
        return Parent::writeQuestions(questionObj);

    // Return the final status
    return errCode;
}

Error IPythonInstanceBase::writeAnswers(
    const pybind11::object &answersObj) noexcept {
    py::object result;
    Error errCode;
    LOGPIPE();

    // If the WriteAnswers method is not registered, delegate to parent
    if (!(m_pyMethods & PythonMethod::WriteAnswers))
        return Parent::writeAnswers(answersObj);

    // Define the Python callback function
    auto pythonCallback = localfcn()->Error {
        // Execute the Python method
        m_pyInstance.attr("writeAnswers")(answersObj);
        return {};
    };

    // Invoke the Python callback
    errCode = callPython(pythonCallback);

    // If parent invocation is required based on error code
    if (checkCallParent(errCode)) 
        return Parent::writeAnswers(answersObj);

    // Return the final status
    return errCode;
}

