    using T = decltype(factory());
    TVector<T> testValues;
    for (int idx = 0; idx < 1000; ++idx) {
        testValues.emplace_back(factory());
    }
    return absl::VerifyTypeImplementsAbslHashCorrectly(testValues);
}

