#include <clang-c/Index.h>
#include <graphviz/graphviz.h>

void processCursor(CXTranslationUnit unit, CXCursor cursor, Agraph_t* graph, Agnode_t* prevNode) {
    CXCursorKind kind = clang_getCursorKind(cursor);
    CXString nameStr = clang_getCursorSpelling(cursor);
    const char* identifier = clang_getCString(nameStr);

    Agnode_t* currentNode = agnode(graph, identifier, 1);
    if (prevNode) {
        agedge(graph, prevNode, currentNode, 0, 1);
    }

    clang_disposeString(nameStr);

    if (kind == CXCursor_FunctionDecl || kind == CXCursor_CXXMethod) {
        CXCursor defCursor = clang_getCursorDefinition(cursor);
        while (defCursor.kind != CXCursor_InvalidFile) {
            processCursor(unit, defCursor, graph, currentNode);
            defCursor = clang_getCursorLexicalParent(defCursor);
        }
    } else if (kind == CXCursor_CompoundStmt) {
        clang_visitChildren(cursor, [](CXCursor c, CXCursor parent, CXClientData data) {
            Agraph_t* g = (Agraph_t*)data;
            CXTranslationUnit t = clang_Cursor_getTranslationUnit(parent);
            processCursor(t, c, g, (Agnode_t*)data);
            return CXChildVisit_Continue;
        }, currentNode);
    } else if (kind == CXCursor_IfStmt || kind == CXCursor_WhileStmt || kind == CXCursor_ForStmt) {
        clang_visitChildren(cursor, [](CXCursor c, CXCursor parent, CXClientData data) {
            Agraph_t* g = (Agraph_t*)data;
            CXTranslationUnit t = clang_Cursor_getTranslationUnit(parent);
            processCursor(t, c, g, (Agnode_t*)data);
            return CXChildVisit_Continue;
        }, currentNode);
    }
}

int main() {
    const char* sourceCode = R"code(
        int factorial(int n) {
            if (n == 0) {
                return 1;
            } else {
                return n * factorial(n - 1);
            }
        }

        int main() {
            int value = 5;
            int output = factorial(value);
            std::cout << "Factorial of " << value << " is " << output << std::endl;
            return 0;
        }
    )code";

    CXIndex index = clang_createIndex(0, 0);
    CXTranslationUnit unit = clang_parseTranslationUnit(index, nullptr, nullptr, 0, nullptr, 0, CXTranslationUnit_None);

    CXUnsavedFile unsaved = { "example.cpp", sourceCode, strlen(sourceCode) };
    clang_reparseTranslationUnit(unit, 1, &unsaved, CXReparse_None);

    CXCursor rootCursor = clang_getTranslationUnitCursor(unit);
    Agraph_t* astGraph = agopen("Control Flow Graph", Agdirected, 0);
    processCursor(unit, rootCursor, astGraph, nullptr);

    agwrite(astGraph, stdout);
    agclose(astGraph);
    clang_disposeTranslationUnit(unit);
    clang_disposeIndex(index);

    return 0;
}

#include <vector>
