struct Token {
    std::string type; // "LABEL", "INSTRUCTION", "REGISTER", "IMMEDIATE", "LABEL_REF"
    std::string value;
};

std::vector<Token> parseLine(const std::string& input) {
    std::vector<Token> result;
    std::regex pattern(R"((\w+):|(\w+)|(\$?\w+)|(-?\d+))");
    std::smatch matchResult;

    auto pos = input.begin();
    while (std::regex_search(pos, input.end(), matchResult, pattern)) {
        if (matchResult[1].matched) {
            result.emplace_back(Token{"LABEL", matchResult[1].str()});
        } else if (matchResult[2].matched) {
            result.emplace_back(Token{"INSTRUCTION", matchResult[2].str()});
        } else if (matchResult[3].matched) {
            result.emplace_back(Token{"REGISTER", matchResult[3].str()});
        } else if (matchResult[4].matched) {
            result.emplace_back(Token{"IMMEDIATE", matchResult[4].str()});
        }
        pos = matchResult.suffix().first;
    }

    return result;
}

