#include <iostream>
#include <string>
#include <vector>
#include <regex>
#include <unordered_map>
#include <unordered_set>
#include <functional>

// Tokenize text into words using regex
std::vector<std::string> extractWords(const std::string& input) {
    std::regex pattern("\\b[a-zA-Z]+\\b");
    auto start = std::sregex_iterator(input.begin(), input.end(), pattern);
    auto end = std::sregex_iterator();
    std::vector<std::string> tokens;

    for (auto it = start; it != end; ++it) {
        tokens.push_back((*it).str());
    }
    return tokens;
}

// Build adjacency list where edge exists if last char of word matches first char of next word
std::unordered_map<std::string, std::vector<std::string>> constructAdjacencyList(const std::vector<std::string>& wordList) {
    std::unordered_map<std::string, std::vector<std::string>> adjList;

    for (const auto& currentWord : wordList) {
        for (const auto& candidateWord : wordList) {
            if (!currentWord.empty() && !candidateWord.empty() &&
                currentWord.back() == candidateWord.front()) {
                adjList[currentWord].push_back(candidateWord);
            }
        }
    }
    return adjList;
}

// Find the longest chain of words where each consecutive pair ends/starts with same letter
std::vector<std::string> findLongestSequence(const std::string& sourceText) {
    std::vector<std::string> words = extractWords(sourceText);
    std::unordered_map<std::string, std::vector<std::string>> adjacency = constructAdjacencyList(words);
    std::unordered_set<std::string> explored;
    std::vector<std::string> bestPath;

    // Depth-first search to explore all possible chains
    std::function<void(const std::string&, std::vector<std::string>&)> traverse = 
        [&](const std::string& node, std::vector<std::string>& currentPath) {
            if (explored.find(node) != explored.end()) return;

            explored.insert(node);
            currentPath.push_back(node);

            // Explore all neighbors
            if (adjacency.count(node)) {
                for (const auto& neighbor : adjacency[node]) {
                    traverse(neighbor, currentPath);
                }
            }

            // Update best path if current is longer
            if (currentPath.size() > bestPath.size()) {
                bestPath = currentPath;
            }

            // Backtrack
            currentPath.pop_back();
            explored.erase(node);
        };

    // Start DFS from each word
    for (const auto& word : words) {
        std::vector<std::string> path;
        traverse(word, path);
    }

    return bestPath;
}

int main() {
    std::string input = "I love Python and Java and Rust and Ruby.";
    std::vector<std::string> sequence = findLongestSequence(input);

    for (const auto& term : sequence) {
        std::cout << term << " ";
    }
    std::cout << std::endl;

    return 0;
