#include <iostream>
#include <vector>

// Compute the arithmetic mean of a vector of numbers
double computeMean(const std::vector<double>& values) {
    if (values.empty()) return 0.0;
    double total = 0.0;
    size_t count = 0;
    for (size_t i = 0; i < values.size(); ++i) {
        total += values[i];
        ++count;
    }
    return total / static_cast<double>(count);
}

