// Custom frame class demonstrating dynamic combo box item management
class DynamicComboBoxFrame : public wxFrame {
public:
    DynamicComboBoxFrame() 
        : wxFrame(nullptr, wxID_ANY, "Dynamic ComboBox Demo", wxDefaultPosition, wxSize(350, 160)) {

        wxPanel* mainPanel = new wxPanel(this, wxID_ANY);

        // Initialize combo box with predefined options
        wxString initialItems[] = { "First Choice", "Second Choice", "Third Choice" };
        comboBox = new wxComboBox(mainPanel, wxID_ANY, wxEmptyString, wxDefaultPosition, wxDefaultSize, 
                                  3, initialItems, wxCB_SORT | wxCB_DROPDOWN);

        // Bind selection event to handler
        comboBox->Bind(wxEVT_COMBOBOX, &DynamicComboBoxFrame::OnSelectionChanged, this);

        // Layout setup
        wxBoxSizer* layout = new wxBoxSizer(wxVERTICAL);
        layout->Add(comboBox, 0, wxALL, 15);
        mainPanel->SetSizer(layout);

        Center();
    }

    // Event handler for combo box selection changes
    void OnSelectionChanged(wxCommandEvent& evt) {
        wxString currentSelection = comboBox->GetValue();

        // Verify if the current selection already exists in the list
        bool isDuplicate = false;
        wxArrayString availableOptions = comboBox->GetStrings();

        for (size_t i = 0; i < availableOptions.size(); ++i) {
            if (availableOptions[i] == currentSelection) {
                isDuplicate = true;
                break;
            }
        }

        // Add new unique entry only if it's not a duplicate and not empty
        if (!isDuplicate && !currentSelection.IsEmpty()) {
            comboBox->Append(currentSelection);
        }

        evt.Skip(); // Continue normal event processing
    }

private:
    wxComboBox* comboBox;
};

