using u64 = unsigned long long;

struct Bucket {
    u64 mLeaves[16] = {};
};

struct BucketMap {
    u64 acquire() noexcept {
        while (true) {
            u64 map = mData.load(std::memory_order_relaxed);

            // Determine index based on the least significant bit
            u64 index = (map & 1) ? 1 : 0;
            u64 mask = (u64(1) << index);

            // Atomically set the bit to mark as used
            u64 prev = mData.fetch_or(mask, std::memory_order_relaxed);

            // Check if we successfully claimed this bucket
            if ((prev & mask) == 0) {
                return index;
            }
        }
    }

    __attribute__((noinline)) Bucket acquireBucket() noexcept {
        // Acquire a slot and construct a new Bucket
        [[maybe_unused]] auto idx = acquire();
        return Bucket{};
    }

    std::atomic<u64> mData{ 1 };
};

int main() {
    BucketMap map;
    Bucket b = map.acquireBucket();
    return 0;
}

