// Compute quantile estimates for given percentiles using GK algorithm
std::vector<double> CalculatePercentiles(const std::vector<double>& dataset, const std::vector<double>& percentile_values, double error_bound)
{
    greenwald_khanna<double> gk_structure(error_bound);

    // Insert all data points into the summary structure
    for (double element : dataset)
    {
        gk_structure.insert(element);
    }

