#include <cstdint>

// System call wrapper using software interrupt
template <typename ReturnType, typename... ParameterTypes>
ReturnType make_syscall(uint32_t syscall_id, ParameterTypes... parameters) {
    // Extract up to four arguments into an array-like structure
    const uint32_t params[] = {static_cast<uint32_t>(parameters)...};

    ReturnType output;
    asm volatile(
        "svc 0"                    // System call instruction (modern equivalent of swi)
        : "=r"(output)             // Output operand: result stored in register
        : "r"(syscall_id),         // Input: syscall number in r0
          "r"(params[0]),          // First argument in r1
          "r"(params[1]),          // Second argument in r2  
          "r"(params[2]),          // Third argument in r3
          "r"(params[3])           // Fourth argument in r4 (if needed)
        : "r0", "r1", "r2", "r3", "memory"  // Clobbered registers
    );
    return output;
}

