// Find the maximum element in a vector using manual iteration
int findMaximum(const std::vector<int>& values) {
    if (values.empty()) {
        return -1;  // Return -1 for empty vector as sentinel value
    }

    int currentMax = values[0];
    for (size_t index = 1; index < values.size(); ++index) {
        if (values[index] > currentMax) {
            currentMax = values[index];
        }
    }
    return currentMax;
}

