std::atomic<int> flag_a{0};
std::atomic<int> flag_b{0};

// First thread sets flag_a
void writer_1() {
    flag_a.store(1, std::memory_order_release);
}

// Second thread sets flag_b  
void writer_2() {
    flag_b.store(1, std::memory_order_release);
}

// Third thread checks flag_a and flag_b
void reader_1() {
    // May observe flag_a set but flag_b still unset
    assert(flag_a.load(std::memory_order_acquire) == 1 && 
           flag_b.load(std::memory_order_acquire) == 0);
}

// Fourth thread checks flag_b and flag_a
void reader_2() {
    // May observe flag_b set but flag_a still unset
    assert(flag_b.load(std::memory_order_acquire) == 1 && 
           flag_a.load(std::memory_order_acquire) == 0);
}

#include <cstdint>

// Special constant for accumulator operations
constexpr uint16_t ACCUMULATOR_FLAG = 0xFFFF;

// Get next instruction byte
uint8_t read_opcode(); 

// Get next instruction word (two bytes, little-endian)
uint16_t read_opcode_word();

// Current program counter
extern uint16_t PC;

// CPU registers
extern uint8_t X, Y;

// Addressing mode helpers - all return effective addresses
uint16_t Addr_ACC() { 
    // Accumulator addressing uses a special marker value
    return ACCUMULATOR_FLAG; 
}

uint16_t Addr_IMM() { 
    // Immediate mode: get the operand directly from code stream
    return static_cast<uint16_t>(read_opcode()); 
}

uint16_t Addr_ABS() { 
    // Absolute addressing: fetch 16-bit address from code
    return read_opcode_word(); 
}

uint16_t Addr_ZER() { 
    // Zero-page addressing: only lower 8 bits matter
    return static_cast<uint16_t>(read_opcode() & 0xFF); 
}

uint16_t Addr_ZEX() { 
    // Zero-page X-indexed: add X to base, keep in zero-page
    uint8_t base = read_opcode();
    return static_cast<uint16_t>((base + X) & 0xFF); 
}

uint16_t Addr_ZEY() { 
    // Zero-page Y-indexed: add Y to base, keep in zero-page
    uint8_t base = read_opcode();
    return static_cast<uint16_t>((base + Y) & 0xFF); 
}

uint16_t Addr_ABX() { 
    // Absolute X-indexed: add X to full 16-bit address
    uint16_t base_addr = read_opcode_word();
    return static_cast<uint16_t>(base_addr + X); 
}

uint16_t Addr_ABY() { 
    // Absolute Y-indexed: add Y to full 16-bit address
    uint16_t base_addr = read_opcode_word();
    return static_cast<uint16_t>(base_addr + Y); 
}

uint16_t Addr_IMP() { 
    // Implied addressing: no address calculation needed
    return 0x0000; 
}

uint16_t Addr_REL() { 
    // Relative branching: signed offset added to current PC
    int8_t offset = static_cast<int8_t>(read_opcode());
    return static_cast<uint16_t>(PC + offset); 
}

uint16_t Addr_INX() { 
    // Indirect-X: (base+X) points to 16-bit vector in zero-page
    uint8_t base = read_opcode();
    uint8_t effective_base = (base + X) & 0xFF;

    // Read 16-bit address from zero-page (handles page boundary wrap)
    uint8_t low_byte = *(uint8_t*)(0x0000 | effective_base);
    uint8_t high_byte = *(uint8_t*)(0x0000 | ((effective_base + 1) & 0xFF));

    return static_cast<uint16_t>((high_byte << 8) | low_byte); 
}

uint16_t Addr_INY() { 
    // Indirect-Y: base points to vector, then add Y
    uint8_t base = read_opcode();

    // Read 16-bit address from zero-page
    uint8_t low_byte = *(uint8_t*)(0x0000 | base);
    uint8_t high_byte = *(uint8_t*)(0x0000 | ((base + 1) & 0xFF));

    uint16_t addr = static_cast<uint16_t>((high_byte << 8) | low_byte);
    return static_cast<uint16_t>(addr + Y); 
}

uint16_t Addr_ABI() { 
    // Absolute indirect: fetch address, then read 16-bit value from that location
    uint16_t vector_addr = read_opcode_word();

    // Read 16-bit address from memory (handles page boundary)
    uint8_t low_byte = *(uint8_t*)(vector_addr & 0xFFFF);
    uint8_t high_byte = *(uint8_t*)((vector_addr + 1) & 0xFFFF);

    return static_cast<uint16_t>((high_byte << 8) | low_byte); 
}

