// Custom Clang-Tidy check that replaces calls to 'old_function' with 'new_function()'
class ReplacementCheck : public clang::tidy::ClangTidyCheck {
public:
  ReplacementCheck(StringRef CheckName, ClangTidyContext *Ctx)
      : ClangTidyCheck(CheckName, Ctx) {}

  void registerMatchers(ast_matchers::MatchFinder *Matcher) override {
    Matcher->addMatcher(
        callExpr(callee(functionDecl(hasName("old_function")))).bind("target_call"),
        this);
  }

  void check(const MatchFinder::MatchResult &Result) override {
    const auto *CallExpr = Result.Nodes.getNodeAs<CallExpr>("target_call");
    if (!CallExpr)
      return;

    auto &Rewrite = *Result.Rewriter;
    Rewrite.InsertTextBefore(CallExpr->getBeginLoc(), "new_function();\n");
  }
};

static clang::tidy::ClangTidyPluginRegistry::Add<ReplacementCheck> 
    Y("custom-check", "Replaces old_function() calls with new_function()");

