// Read keyboard input and return scan code 
int getkeys() {
    union REGS input, output;
    int scanCode = 0;

    // Wait until a key is pressed
    do {
        // Busy wait until kbhit returns true
    } while (!kbhit());

    // Set up interrupt parameters for keyboard read
    input.h.ah = 0x00;  // Function 0: read keyboard input

