using namespace std;

bool isMathOperator(char c) {
    return c == '+' || c == '-' || c == '*' || c == '/';
}

int performOperation(int operand1, int operand2, char operation) {
    switch (operation) {
        case '+': return operand1 + operand2;
        case '-': return operand1 - operand2;
        case '*': return operand1 * operand2;
        case '/': 
            if (operand2 == 0) {
                cout << "Error: Division by zero" << endl;
                exit(1);
            }
            return operand1 / operand2;
        default: 
            cout << "Error: Unknown operator" << endl;
            exit(1);
    }
}

int computePostfix(const string& expr) {
    stack<int> values;
    stringstream stream(expr);
    string item;

    while (stream >> item) {
        if (isMathOperator(item[0]) && item.size() == 1) {
            if (values.size() < 2) {
                cout << "Error: Invalid expression" << endl;
                exit(1);
            }
            int second = values.top(); values.pop();
            int first = values.top(); values.pop();
            int computed = performOperation(first, second, item[0]);
            values.push(computed);
        } else {
            try {
                int number = stoi(item);
                values.push(number);
            } catch (const invalid_argument&) {
                cout << "Error: Invalid operand" << endl;
                exit(1);
            }
        }
    }

    if (values.size() != 1) {
        cout << "Error: Invalid expression" << endl;
        exit(1);
    }

    return values.top();
}

int main() {
    string inputExpr;
    cout << "Enter a postfix expression: ";
    getline(cin, inputExpr);

    int answer = computePostfix(inputExpr);
    cout << "The result is: " << answer << endl;

    return 0;
}

