#include <condition_variable>
#include <mutex>

class CountdownBarrier {
public:
    explicit CountdownBarrier(size_t initial) : _remaining(initial) {}

    void await() {
        std::unique_lock<std::mutex> guard(_lock);
        _cv.wait(guard, [this] { return _remaining == 0; });
    }

    void release() {
        std::unique_lock<std::mutex> guard(_lock);
        if (_remaining > 0) {
            --_remaining;
            if (_remaining == 0) {
                _cv.notify_all();
            }
        }
    }

private:
    size_t _remaining;
    std::mutex _lock;
    std::condition_variable _cv;
};

