// Generate a list of prime numbers within the given range [start, end]
std::vector<int> find_primes_for(int start, int end) {
    if (start > end) throw std::invalid_argument("Start must be less than or equal to end.");

    std::vector<int> primes;
    int current = std::max(2, start);

    while (current <= end) {
        bool is_prime = true;
        int divisor = 2;

        // Check divisibility up to sqrt(current)
        while (divisor * divisor <= current) {
            if (current % divisor == 0) {
                is_prime = false;
                break;
            }
            divisor++;
        }

        if (is_prime) {
            primes.push_back(current);
        }

        current++;
    }

    return primes;
}

