// Helper function to extract unsigned char from numpy uint8 array
unsigned char extract_uint8_value(PyObject* py_obj) {
    if (!PyArray_Check(py_obj)) {
        throw boost::python::error_already_set();
    }

    PyArrayObject* np_array = static_cast<PyArrayObject*>(py_obj);

    if (PyArray_TYPE(np_array) != NPY_UINT8) {
        throw boost::python::error_already_set();
    }

    void* data_ptr = PyArray_DATA(np_array);
    return *static_cast<unsigned char*>(data_ptr);
}

