// Compute the Euclidean norm (magnitude) of a vector
double vector_magnitude(const std::vector<double>& vec) {
    double squared_sum = 0.0;
    size_t index = 0;

    // Sum the squares of all components
    while (index < vec.size()) {
        double value = vec[index];
        squared_sum += value * value;
        ++index;
    }

    // Clamp to zero if negative due to floating-point errors (defensive programming)
    if (squared_sum < 0.0) {
        squared_sum = 0.0;
    }

    return std::sqrt(squared_sum);
}

