std::string findMaxCommonSequence(const std::string& first, const std::string& second) {
    int len1 = first.length();
    int len2 = second.length();

    // Create a 2D table to store lengths of common suffixes
    std::vector<std::vector<int>> table(len1 + 1, std::vector<int>(len2 + 1, 0));

    // Track the maximum length and ending index in first string
    int maxLen = 0;
    int endPos = -1;

    // Build the table using dynamic programming
    for (int i = 1; i <= len1; ++i) {
        for (int j = 1; j <= len2; ++j) {
            if (first[i - 1] == second[j - 1]) {
                table[i][j] = table[i - 1][j - 1] + 1;

                // Update maximum length and position if needed
                if (table[i][j] > maxLen) {
                    maxLen = table[i][j];
                    endPos = i - 1;
                }
            } else {
                table[i][j] = 0;
            }
        }
    }

    // Return empty string if no common substring found
    if (maxLen == 0) {
        return "";
    }

    // Extract the substring using the recorded position and length
    return first.substr(endPos - maxLen + 1, maxLen);
}

int main() {
    std::string str1 = "abcde";
    std::string str2 = "abfcd";

    std::string commonPart = findMaxCommonSequence(str1, str2);
    std::cout << "Longest Common Substring: " << commonPart << std::endl;

    return 0;
}

