// Generic template: uses runtime branch inside asm block via comparison
template<bool Flag>
void compute_vector() {
    float dest[4] = {1.0f, 1.0f, 1.0f, 1.0f};
    float source[4] = {1.0f, 2.0f, 3.0f, 4.0f};

    float* d_ptr = dest;
    float* s_ptr = source;

    int condition_flag = Flag ? 1 : 0;

    __asm__ volatile (
        "vld1.32   {q2}, [%[src]]      \n"
        "vld1.32   {q3}, [%[dst]]      \n"
        "vadd.f32  q2, q2, q3          \n"
        "vadd.f32  q2, q2, q3          \n"

        // Conditional execution path
        "cmp       %[cond], #1         \n"
        "beq       skip_extra_add      \n"
        "b         end_label           \n"
        "skip_extra_add:               \n"
        "vadd.f32  q2, q2, q3          \n"
        "end_label:                    \n"

        "vst1.32   {q2}, [%[dst]]      \n"
        : [src] "+r" (s_ptr), [dst] "+r" (d_ptr)
        : [cond] "r" (condition_flag)
        : "q2", "q3", "memory"
    );

    display_results(dest);
}

// Specialization when Flag is true: unrolls extra addition at compile time
template<>
void compute_vector<true>() {
    float dest[4] = {1.0f, 1.0f, 1.0f, 1.0f};
    float source[4] = {1.0f, 2.0f, 3.0f, 4.0f};

    float* d_ptr = dest;
    float* s_ptr = source;

    __asm__ volatile (
        "vld1.32   {q4}, [%[src]]      \n"
        "vld1.32   {q5}, [%[dst]]      \n"
        "vadd.f32  q4, q4, q5          \n"
        "vadd.f32  q4, q4, q5          \n"
        "vadd.f32  q4, q4, q5          \n"
        "vst1.32   {q4}, [%[dst]]      \n"
        : [src] "+r" (s_ptr), [dst] "+r" (d_ptr)
        :
        : "q4", "q5", "memory"
    );

    display_results(dest);
}

// Specialization when Flag is false: omits extra addition entirely
template<>
void compute_vector<false>() {
    float dest[4] = {1.0f, 1.0f, 1.0f, 1.0f};
    float source[4] = {1.0f, 2.0f, 3.0f, 4.0f};

    float* d_ptr = dest;
    float* s_ptr = source;

    __asm__ volatile (
        "vld1.32   {q6}, [%[src]]      \n"
        "vld1.32   {q7}, [%[dst]]      \n"
        "vadd.f32  q6, q6, q7          \n"
        "vadd.f32  q6, q6, q7          \n"
        "vst1.32   {q6}, [%[dst]]      \n"
        : [src] "+r" (s_ptr), [dst] "+r" (d_ptr)
        :
        : "q6", "q7", "memory"
    );

    display_results(dest);
}

