#include <atomic>

// Alternative implementation of acquire - finds first available slot using bit scanning
std::uint64_t acquire() noexcept {
    std::uint64_t current_value;
    std::uint64_t selected_bit;
    std::uint64_t bit_mask;

    do {
        current_value = mData.load(std::memory_order_seq_cst);

        // Determine target index: if LSB is 1, choose index 1; otherwise index 0
        selected_bit = (current_value & 0x1ULL) ? 1ULL : 0ULL;
        bit_mask = 1ULL << selected_bit;

        // Attempt to set the bit atomically
        std::uint64_t prior_value = mData.fetch_or(bit_mask, std::memory_order_seq_cst);

        // Check if we succeeded (bit was not already set)
        if ((prior_value & bit_mask) == 0) {
            return selected_bit;
        }

    } while (true);
}

#include <cuda_runtime.h>
#include <iostream>
#include <vector>
#include <chrono>

// Use a different block size for better flexibility
#define THREADS_PER_BLOCK 128

__global__ void columnSumKernel(const float* __restrict__ d_data, float* __restrict__ d_results, int rows, int cols) {
    // Each block processes one row
    int rowIdx = blockIdx.x;
    int threadId = threadIdx.x;

    // Calculate starting position and step size
    int initialPos = rowIdx * cols + threadId;
    int increment = THREADS_PER_BLOCK;

    float localSum = 0.0f;

    // Accumulate partial sums using strided access
    for (int idx = initialPos; idx < (rowIdx + 1) * cols; idx += increment) {
        localSum += d_data[idx];
    }

    // Shared memory for reduction
    __shared__ float temp[THREADS_PER_BLOCK];
    temp[threadId] = localSum;
    __syncthreads();

    // Perform parallel reduction in shared memory
    for (int offset = THREADS_PER_BLOCK / 2; offset > 0; offset >>= 1) {
        if (threadId < offset) {
            temp[threadId] += temp[threadId + offset];
        }
        __syncthreads();
    }

    // Write final result for this row
    if (threadId == 0) {
        d_results[rowIdx] = temp[0];
    }
}

void computeRowSumsOnGPU(const float* hostInput, float* hostOutput, int rowCount, int colCount) {
    float* deviceMatrix = nullptr;
    float* deviceRowSums = nullptr;

    size_t totalElements = static_cast<size_t>(rowCount) * colCount;
    size_t matrixBytes = totalElements * sizeof(float);
    size_t sumsBytes = rowCount * sizeof(float);

    // Allocate memory on device
    cudaMalloc(&deviceMatrix, matrixBytes);
    cudaMalloc(&deviceRowSums, sumsBytes);

    // Copy input data from host to device
    cudaMemcpy(deviceMatrix, hostInput, matrixBytes, cudaMemcpyHostToDevice);

    // Configure kernel launch parameters
    dim3 threadsPerBlock(THREADS_PER_BLOCK);
    dim3 blocksPerGrid((rowCount + threadsPerBlock.x - 1) / threadsPerBlock.x);

    // Launch the kernel
    columnSumKernel<<<blocksPerGrid, threadsPerBlock>>>(deviceMatrix, deviceRowSums, rowCount, colCount);

    // Copy results back to host
    cudaMemcpy(hostOutput, deviceRowSums, sumsBytes, cudaMemcpyDeviceToHost);

    // Clean up device memory
    cudaFree(deviceMatrix);
    cudaFree(deviceRowSums);
}

int main() {
    const int ROW_COUNT = 90000;
    const int COL_COUNT = 1000;

    std::vector<float> inputData(ROW_COUNT * COL_COUNT, 1.0f);
    std::vector<float> outputSums(ROW_COUNT, 0.0f);

    auto startTime = std::chrono::high_resolution_clock::now();
    computeRowSumsOnGPU(inputData.data(), outputSums.data(), ROW_COUNT, COL_COUNT);
    auto endTime = std::chrono::high_resolution_clock::now();

    std::chrono::duration<double> elapsed = endTime - startTime;
    std::cout << "GPU Execution Time: " << elapsed.count() * 1000 << " ms" << std::endl;

    return 0;
}

#include <iostream>
