class StudentRecord {
public:
    std::string fullName;
    int years;
    std::string major;
    char letterGrade;
    double performance;

    StudentRecord(const std::string& name, int age, const std::string& program, char mark, double index)
        : fullName(name), years(age), major(program), letterGrade(mark), performance(index) {
        check();
    }

    void modify(int age, const std::string& program, char mark, double index) {
        years = age;
        major = program;
        letterGrade = mark;
        performance = index;
        check();
    }

private:
    void check() {
        if (fullName.length() < 2 || fullName.length() > 50) {
            throw std::invalid_argument("Name length must be between 2 and 50 characters.");
        }
        if (years < 18 || years > 35) {
            throw std::invalid_argument("Age must be between 18 and 35.");
        }
        if (major.length() < 5 || major.length() > 100) {
            throw std::invalid_argument("Program length must be between 5 and 100 characters.");
        }
        if (letterGrade != 'A' && letterGrade != 'B' && letterGrade != 'C' && 
            letterGrade != 'D' && letterGrade != 'F') {
            throw std::invalid_argument("Mark must be one of 'A', 'B', 'C', 'D', or 'F'.");
        }
        if (performance < 0.0 || performance > 4.0) {
            throw std::invalid_argument("Index must be between 0.0 and 4.0.");
        }
    }
};

class AcademicRegistry {
private:
    std::map<std::string, StudentRecord> registry;

public:
    void enroll(const std::string& name, int age, const std::string& program, char mark, double index) {
        if (registry.find(name) != registry.end()) {
            throw std::runtime_error("Student with this name already exists.");
        }
        registry[name] = StudentRecord(name, age, program, mark, index);
    }

    void revise(const std::string& name, int age, const std::string& program, char mark, double index) {
        auto iter = registry.find(name);
        if (iter == registry.end()) {
            throw std::runtime_error("Student not found.");
        }
        iter->second.modify(age, program, mark, index);
    }

    StudentRecord retrieve(const std::string& name) const {
        auto iter = registry.find(name);
        if (iter == registry.end()) {
            throw std::runtime_error("Student not found.");
        }
        return iter->second;
    }
};

int main() {
    AcademicRegistry system;

    try {
        system.enroll("Alice", 22, "Computer Science", 'A', 3.9);
        system.enroll("Bob", 20, "Mathematics", 'B', 3.5);
        system.enroll("Charlie", 21, "Physics", 'C', 3.0);

        system.revise("Alice", 23, "Computer Science", 'A', 3.8);

        StudentRecord alice = system.retrieve("Alice");
        std::cout << "Name: " << alice.fullName << ", Age: " << alice.years 
                  << ", Program: " << alice.major << ", Mark: " << alice.letterGrade 
                  << ", Index: " << alice.performance << std::endl;

    } catch (const std::exception& e) {
        std::cerr << "Error: " << e.what() << std::endl;
    }

    return 0;
}

