#include <iostream>
using namespace std;

// Tic-Tac-Toe game board representation
char grid[3][3] = { {'1', '2', '3'}, {'4', '5', '6'}, {'7', '8', '9'} };
char currentPlayer;
int selectedRow, selectedCol;

// Displays the current state of the board
void showBoard() {
    cout << " " << grid[0][0] << " | " << grid[0][1] << " | " << grid[0][2] << endl;
    cout << "-----------" << endl;
    cout << " " << grid[1][0] << " | " << grid[1][1] << " | " << grid[1][2] << endl;
    cout << "-----------" << endl;
    cout << " " << grid[2][0] << " | " << grid[2][1] << " | " << grid[2][2] << endl;
}

// Handles player input and updates the board accordingly
void takeTurn() {
    int position;
    cout << "Player " << currentPlayer << ", enter your move (1-9): ";
    cin >> position;
    position--; // Convert to 0-based index

    selectedRow = position / 3;
    selectedCol = position % 3;

    if (grid[selectedRow][selectedCol] != 'X' && grid[selectedRow][selectedCol] != 'O') {
        grid[selectedRow][selectedCol] = currentPlayer;
    } else {
        cout << "Invalid move! Try again." << endl;
        takeTurn();
    }
}

// Checks if there's a winning combination on the board
bool hasWinner() {
    // Check rows
    for (int r = 0; r < 3; r++) {
        if (grid[r][0] == grid[r][1] && grid[r][1] == grid[r][2])
            return true;
    }

    // Check columns
    for (int c = 0; c < 3; c++) {
        if (grid[0][c] == grid[1][c] && grid[1][c] == grid[2][c])
            return true;
    }

    // Check diagonals
    if (grid[0][0] == grid[1][1] && grid[1][1] == grid[2][2])
        return true;

    if (grid[0][2] == grid[1][1] && grid[1][1] == grid[2][0])
        return true;

    return false;
}

// Determines if the game ended in a tie
bool isTieGame() {
    for (int r = 0; r < 3; r++) {
        for (int c = 0; c < 3; c++) {
            if (grid[r][c] != 'X' && grid[r][c] != 'O')
                return false;
        }
    }
    return true;
}

// Main game loop
int main() {
    char continuePlaying = 'Y';
    while (continuePlaying == 'Y' || continuePlaying == 'y') {
        for (int turn = 0; turn < 9; turn++) {
            showBoard();

            // Alternate between players
            if (turn % 2 == 0) {
                currentPlayer = 'X';
            } else {
                currentPlayer = 'O';
            }

            takeTurn();

            // Check for win or draw after each move
            if (hasWinner()) {
                showBoard();
                cout << "Player " << currentPlayer << " wins!" << endl;
                break;
            } else if (isTieGame()) {
                showBoard();
                cout << "It's a draw!" << endl;
                break;
            }
        }

        cout << "Do you want to play again? (Y/N): ";
        cin >> continuePlaying;

        // Reset board if playing again
        if (continuePlaying == 'Y' || continuePlaying == 'y') {
            for (int r = 0; r < 3; r++) {
                for (int c = 0; c < 3; c++) {
                    grid[r][c] = '1' + r * 3 + c;
                }
            }
        }
    }
    return 0;
}

