#include <signal.h>
#include <stdio.h>
#include <time.h>

// Signal handler function
void signal_handler(int sig) { 
    printf("handler\n"); 
}

// Custom restorer function using inline assembly
void signal_restorer() { 
    asm volatile("mov $15,%%rax\nsyscall":::"rax"); 
}

// Signal action structure
struct sigaction sa;
// Time specification for nanosleep
struct timespec sleep_time{10, 0};

int main() {
    // Configure signal handler
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTORER | SA_SIGINFO;
    sa.sa_restorer = &signal_restorer;

    // Perform system calls via inline assembly
    asm volatile(
        "mov $13, %%rax\n"          // SIGPROCMASK syscall number
        "mov %0, %%rdi\n"           // arg1: how (7 = SIG_SETMASK)
        "mov %1, %%rsi\n"           // arg2: newact pointer
        "mov $0, %%rdx\n"           // arg3: oldact (NULL)
        "mov $8, %%r10\n"           // arg4: sigsetsize (8 bytes)
        "syscall\n"                 // invoke system call

        "mov %%rax, %%rdi\n"        // exit status from previous syscall
        "mov $60, %%rax\n"          // exit syscall number
        "syscall\n"                 // terminate process
        :                           // no outputs
        : "i"(7), "p"(&sa)          // inputs: immediate 7, pointer to sa
        : "rax", "rdi", "rsi", "rdx", "r10"  // clobbered registers
    );

    // Sleep for specified duration (should not be reached due to exit syscall above)
    nanosleep(&sleep_time, 0);

    return 0;
}

