// Define buffer size and type alias for byte
#define BUFFER_SIZE 256

using byte = unsigned char;

// Circular buffer implementation with head and tail pointers
byte dataBuffer[BUFFER_SIZE];
unsigned int headIndex = 0;
unsigned int tailIndex = 0;

// Add data to the circular buffer
void insertIntoBuffer(byte inputByte) {
    // Move head forward and wrap around if necessary
    headIndex = (headIndex + 1) % BUFFER_SIZE;

    // Store new data at the updated head position
    dataBuffer[headIndex] = inputByte;

    // If buffer is full, advance tail to discard oldest entry
    if (headIndex == tailIndex) {
        tailIndex = (tailIndex + 1) % BUFFER_SIZE;
    }
}

// Read data from the circular buffer
byte extractFromBuffer() {
    // Check if buffer has data available
    if (tailIndex != headIndex) {
        // Advance tail to get next element
        tailIndex = (tailIndex + 1) % BUFFER_SIZE;
        return dataBuffer[tailIndex];
    } else {
        // Return zero when buffer is empty
        return 0;
    }
}

