#include <iostream>
#include <list>
#include <algorithm>

class OptimizedMinMaxList {
private:
    std::list<int> data;
    std::list<int>::iterator minIter;
    std::list<int>::iterator maxIter;

public:
    OptimizedMinMaxList() : minIter(data.end()), maxIter(data.end()) {}

    void addElement(int val) {
        data.push_back(val);
        auto current = std::prev(data.end());

        if (minIter == data.end() || val < *minIter) {
            minIter = current;
        }
        if (maxIter == data.end() || val > *maxIter) {
            maxIter = current;
        }
    }

    void deleteElement(int val) {
        auto iter = std::find(data.begin(), data.end(), val);
        if (iter != data.end()) {
            if (iter == minIter) {
                if (iter == data.begin()) {
                    minIter = data.end();
                } else {
                    minIter = std::prev(iter);
                }
            }
            if (iter == maxIter) {
                if (std::next(iter) == data.end()) {
                    maxIter = data.end();
                } else {
                    maxIter = std::next(iter);
                }
            }
            data.erase(iter);
        }
    }

    int findMinimum() const {
        return (minIter != data.end()) ? *minIter : -1;
    }

    int findMaximum() const {
        return (maxIter != data.end()) ? *maxIter : -1;
    }
};

int main() {
    OptimizedMinMaxList container;
    container.addElement(5);
    container.addElement(3);
    container.addElement(7);

    std::cout << "Minimum: " << container.findMinimum() << std::endl; // 3
    std::cout << "Maximum: " << container.findMaximum() << std::endl; // 7

    container.deleteElement(3);
    std::cout << "Minimum after deletion: " << container.findMinimum() << std::endl; // 5

    return 0;
}

