// Base interface for handling events of type T
template <typename T>
class EventCallback {
public:
    virtual void onEvent(T data) = 0;
};

// Base interface for processing events of type T
template <typename T>
class EventWorker {
public:
    virtual void execute(T data) = 0;
};

// Configuration structure linking an event handler with a collection of processors
template <typename T>
class ProcessingConfiguration {
public:
    ProcessingConfiguration(EventCallback<T>* callback, std::vector<EventWorker<T>>* workers)
        : handler(callback), processors(workers) {}

    EventCallback<T>* getHandler() const { return handler; }
    std::vector<EventWorker<T>>* getProcessors() const { return processors; }

private:
    EventCallback<T>* handler;
    std::vector<EventWorker<T>>* processors;
};

// Manager class that coordinates event processing components
template <typename T>
class EventDispatcher {
public:
    template <typename U>
    ProcessingConfiguration<U> setupFor(U* callback) {
        return ProcessingConfiguration<U>(callback, &workers);
    }

private:
    std::vector<EventWorker<T>> workers;
};

