// Verify that all required validation layers are present in the system
bool AreValidationLayersAvailable() {
    uint32_t totalLayerCount;
    vkEnumerateInstanceLayerProperties(&totalLayerCount, nullptr);

    std::vector<VkLayerProperties> systemLayerList(totalLayerCount);
    vkEnumerateInstanceLayerProperties(&totalLayerCount, systemLayerList.data());

    for (const char* requestedLayer : debugValidationLayers) {
        bool matchFound = false;

        for (const auto& layerInfo : systemLayerList) {
            if (std::strcmp(requestedLayer, layerInfo.layerName) == 0) {
                matchFound = true;
                break;
            }
        }

        if (!matchFound) {
            return false;
        }
    }

    return true;
}

// Update instance creation logic to conditionally enable validation layers
void Renderer::CreateInstance() {
    if (useDebugValidation && !AreValidationLayersAvailable()) {
        throw std::runtime_error("Debug validation layers were requested but are not supported on this system.");
    }

    // ...
    instanceCreateInfo.enabledLayerCount = useDebugValidation ? static_cast<uint32_t>(debugValidationLayers.size()) : 0u;
    instanceCreateInfo.ppEnabledLayerNames = useDebugValidation ? debugValidationLayers.data() : nullptr;
    // ...
}

#include <android/asset_manager.h>
#include <android/asset_manager_jni.h>

JNIEXPORT jint JNICALL 
Java_com_sfarbac_rtmatching_nativeClass_detectAndMatch
(JNIEnv *env, jobject obj, jlong addrRgba, jlong addrTrick, jstring path) {
    // Reference the input matrices
    cv::Mat& inputImage = *(cv::Mat*)addrRgba;
    cv::Mat& targetImage = *(cv::Mat*)addrTrick;

    // Extract UTF-8 string from Java string
    jsize strLen = env->GetStringUTFLength(path);
    const char* cStr = env->GetStringUTFChars(path, nullptr);
    std::string assetName(cStr, strLen);
    env->ReleaseStringUTFChars(path, cStr);

    // Retrieve and initialize Android asset manager
    jobject activityObj = env->GetObjectField(obj, env->GetFieldID(env->GetObjectClass(obj), "mActivity", "Landroid/app/Activity;"));
    jclass activityClass = env->GetObjectClass(activityObj);
    jfieldID assetManagerFieldID = env->GetFieldID(activityClass, "mAssetManager", "Landroid/content/res/AssetManager;");
    jobject assetManagerObj = env->GetObjectField(activityObj, assetManagerFieldID);
    AAssetManager* mgr = AAssetManager_fromJava(env, assetManagerObj);

    // Open the requested asset file
    AAsset* asset = AAssetManager_open(mgr, assetName.c_str(), AASSET_MODE_STREAMING);
    if (!asset) {
        __android_log_print(ANDROID_LOG_ERROR, "TRACKERS", "Failed to open asset: %s", assetName.c_str());
        return -1;
    }

    // Allocate buffer and read asset contents
    off_t size = AAsset_getLength(asset);
    std::vector<unsigned char> data(size);
    AAsset_read(asset, data.data(), size);
    AAsset_close(asset);

    // Decode image from memory buffer
    cv::Mat decoded = cv::imdecode(cv::Mat(data), cv::IMREAD_GRAYSCALE);
    if (decoded.empty()) {
        __android_log_print(ANDROID_LOG_ERROR, "TRACKERS", "Image decoding failed for asset: %s", assetName.c_str());
        return -1;
    }

    // Assign decoded image to output reference
    targetImage = decoded.clone();

    return 1;
}

