// Determine if a number is a power of two using bit manipulation
template<typename T>
inline bool check_power_of_two(const T value) {
    return (value != 0) && ((value & (value - 1)) == 0);
}

// Specialized version for unsigned int using inline assembly
template<>
inline bool check_power_of_two<unsigned int>(const unsigned int value) {
    bool outcome;
    __asm__ volatile (
        "testl %1, %1\n\t"
        "jz .Lend%=\n\t"
        "andl %1, %1\n\t"
        "jz .Lend%=\n\t"
        "movl $1, %0\n\t"
        "jmp .Ldone%=\n\t"
        ".Lend%=:\n\t"
        "movl $0, %0\n\t"
        ".Ldone%=:"
        : "=r" (outcome)
        : "r" (value & (value - 1))
        : "cc"
    );
    return outcome;
}

int main() {
    unsigned int sample = 16;
    std::cout << "check_power_of_two(" << sample << ") = " << check_power_of_two(sample) << std::endl;
    return 0;
}

