// Compute the product of two quaternions using component-wise operations
std::vector<double> computeQuaternionProduct(const std::vector<double>& a, const std::vector<double>& b) {
    // Extract components for clarity
    double aw = a[0], ax = a[1], ay = a[2], az = a[3];
    double bw = b[0], bx = b[1], by = b[2], bz = b[3];

    // Apply quaternion multiplication rules: (w + xi + yj + zk)
    double res_w = aw * bw - ax * bx - ay * by - az * bz;
    double res_x = aw * bx + ax * bw + ay * bz - az * by;
    double res_y = aw * by - ax * bz + ay * bw + az * bx;
    double res_z = aw * bz + ax * by - ay * bx + az * bw;

    return {res_w, res_x, res_y, res_z};
}

int main() {
    // Define two quaternions to multiply
    std::vector<double> qA = {0.98, 0.08, 0.17, -0.01};
    std::vector<double> qB = {0.70, 0.70, 0.0, 0.0};

    // Perform multiplication
    std::vector<double> output = computeQuaternionProduct(qA, qB);

    // Print each component separated by space
    for (size_t i = 0; i < output.size(); ++i) {
        std::cout << output[i];
        if (i < output.size() - 1) std::cout << " ";
    }
    std::cout << std::endl;

    return 0;
}

#include <type_traits>

// System call wrapper using inline assembly for ARM architecture
template <int syscall_number, typename ReturnT, typename Arg1T, typename Arg2T, typename Arg3T, typename Arg4T>
inline ReturnT system_call(Arg1T arg1, Arg2T arg2, Arg3T arg3, Arg4T arg4)
{
    // Assign arguments to specific CPU registers as per ARM EABI convention
    register Arg1T reg_r0 asm("r0") = arg1;
    register Arg2T reg_r1 asm("r1") = arg2;
    register Arg3T reg_r2 asm("r2") = arg3;
    register Arg4T reg_r3 asm("r3") = arg4;

    // Execute supervisor call instruction with specified syscall number
    asm volatile(
        "svc %c[nr]\n"
        : "+r" (reg_r0)                    // Output: r0 modified in-place
        : [nr] "i" (syscall_number),      // Input: syscall number as immediate
          "0"  (reg_r0),                  // Input: initial value of r0 (same as output)
          "r"  (reg_r1),                  // Input: r1 argument
          "r"  (reg_r2),                  // Input: r2 argument
          "r"  (reg_r3)                   // Input: r3 argument
        : "memory", "r12", "lr"           // Clobbered registers
    );

    return static_cast<ReturnT>(reg_r0);
}

