// Wrapper function that computes the sine of a given value
extern "C" double compute_sine(double input) {
  return std::sin(input);
}

// Node.js API callback handler for the exposed JavaScript function
static napi_value expose_compute_sine(napi_env env, napi_callback_info cbInfo) {
  napi_value jsResult = nullptr;
  napi_get_undefined(env, &jsResult);

  // Prepare to extract arguments
  size_t argCount = 1;
  napi_value jsArgs[1];
  napi_value thisObj = nullptr;

  napi_get_cb_info(env, cbInfo, &argCount, jsArgs, &thisObj, nullptr);

  // Validate argument count
  if (argCount < 1) {
    napi_throw_error(env, nullptr, "Expected exactly one numeric argument");
    return jsResult;
  }

  // Extract the input number
  double inputValue = 0.0;
  napi_status status = napi_get_value_double(env, jsArgs[0], &inputValue);
  if (status != napi_ok) {
    napi_throw_type_error(env, nullptr, "Argument must be a number");
    return jsResult;
  }

  // Compute result using our C++ helper
  double computedValue = compute_sine(inputValue);

  // Create and return the JavaScript number
  napi_create_double(env, computedValue, &jsResult);
  return jsResult;
}

