// Check if the vector is in non-decreasing order
bool isAscending(const std::vector<int>& data) {
    for (size_t idx = 1; idx < data.size(); ++idx) {
        if (data[idx - 1] > data[idx]) {
            return false;
        }
    }
    return true;
}

// Perform bubble sort on the vector in-place
void performBubbleSort(std::vector<int>& input) {
    int length = input.size();
    bool swapped;

    for (int outer = 0; outer < length - 1; ++outer) {
        swapped = false;

        for (int inner = 0; inner < length - outer - 1; ++inner) {
            if (input[inner] > input[inner + 1]) {
                int temp = input[inner];
                input[inner] = input[inner + 1];
                input[inner + 1] = temp;
                swapped = true;
            }
        }

        if (!swapped) {
            break;
        }
    }
}

int main() {
    std::vector<int> numbers = {4, 2, 1, 7, 10};

    if (isAscending(numbers)) {
        std::cout << "Array is already sorted" << std::endl;
    } else {
        performBubbleSort(numbers);
        std::cout << "Sorted array: ";
        for (int value : numbers) {
            std::cout << value << " ";
        }
        std::cout << std::endl;
    }

    return 0;
}

