REGISTER_OP("SecureComputation")
    .Input("input_data: float")
    .Attr("role: string")
    .Attr("privacy_epsilon: float = 1.0")
    .Output("output_data: float")
    .SetShapeFn([](tensorflow::shape_inference::InferenceContext* c) {
      c->set_output(0, c->input(0));
      return tensorflow::Status::OK();
    });

namespace tensorflow {

class SecureComputationOp : public OpKernel {
 public:
  explicit SecureComputationOp(OpKernelConstruction* context)
      : OpKernel(context) {
    OP_REQUIRES_OK(context, context->GetAttr("role", &role_));
    OP_REQUIRES_OK(context, context->GetAttr("privacy_epsilon", &epsilon_));
  }

  void Compute(OpKernelContext* ctx) override {
    // Get input tensor
    const Tensor& input_tensor = ctx->input(0);

    // Prepare output tensor with same shape as input
    TensorShape out_shape(input_tensor.shape());
    Tensor* output_tensor = nullptr;
    OP_REQUIRES_OK(ctx, ctx->allocate_output(0, out_shape, &output_tensor));

    if (role_ == "guest") {
      // Guest simply forwards the data without modification
      *output_tensor = input_tensor;
    } else if (role_ == "host") {
      // Host adds calibrated Laplace noise for differential privacy
      float scale_param = 1.0f / epsilon_;
      ApplyNoise(ctx, input_tensor, output_tensor, scale_param);
    } else {
      OP_REQUIRES(ctx, false, errors::InvalidArgument("Unknown role specified: ", role_));
    }
  }

 private:
  void ApplyNoise(OpKernelContext* ctx, const Tensor& input_tensor,
                  Tensor* output_tensor, float scale) {
    auto in_flat = input_tensor.flat<float>();
    auto out_flat = output_tensor->flat<float>();

    // Use a deterministic seed for reproducibility within a session
    std::mt19937 rng(static_cast<unsigned int>(ctx->random_seed()));
    std::laplacian_distribution<float> noise_dist(0.0f, scale);

    for (int idx = 0; idx < in_flat.size(); ++idx) {
      float perturbation = noise_dist(rng);
      out_flat(idx) = in_flat(idx) + perturbation;
    }
  }

  std::string role_;
  float epsilon_;
};

REGISTER_KERNEL_BUILDER(Name("SecureComputation").Device(DEVICE_CPU), SecureComputationOp);

}  // namespace tensorflow

