// Compute the arithmetic mean of a list of integers
double computeMean(const std::vector<int>& values) {
    if (values.empty()) {  // Handle empty input case
        return 0.0;
    }

    int total = 0;
    size_t index = 0;

    // Iterate through the vector using index-based loop
    while (index < values.size()) {
        total += values[index];
        ++index;
    }

    // Cast to double before division for precise floating-point result
    return static_cast<double>(total) / static_cast<double>(values.size());
}

int main() {
    std::vector<int> data = {10, 20, 30, 40, 50};
    std::cout << "The average is: " << computeMean(data) << std::endl;
    return 0;
}

