// Check if a number is prime using an alternative approach
bool checkPrime(int number) {
    if (number <= 1) {
        return false;
    }
    if (number == 2) {
        return true;
    }
    if (number % 2 == 0) {
        return false;
    }

    int limit = static_cast<int>(std::sqrt(number));
    for (int j = 3; j <= limit; j += 2) {
        if (number % j == 0) {
            return false;
        }
    }
    return true;
}

int main() {
    for (int value = 2; value <= 50; ++value) {
        if (checkPrime(value)) {
            std::cout << value << std::endl;
        }
    }
    return 0;
}

