// Kernel to read texture with boundary check and write to output array
__global__ void yourKernel(cudaTextureObject_t texObj, float* output, int width, int height, float borderValue) {
    int x = blockIdx.x * blockDim.x + threadIdx.x;
    int y = blockIdx.y * blockDim.y + threadIdx.y;

    if (x >= 0 && x < width && y >= 0 && y < height) {
        // Compute texture coordinates
        float u = static_cast<float>(x);
        float v = static_cast<float>(y);

        // Sample the texture
        float pixelValue = tex2D<float>(texObj, u, v);

        // Validate coordinate bounds for texture access
        bool inBounds = (u >= 0.0f && u < static_cast<float>(width) &&
                         v >= 0.0f && v < static_cast<float>(height));

        // Apply border value if out of bounds
        if (!inBounds) {
            pixelValue = borderValue;
        }

        // Write result to output array
        output[y * width + x] = pixelValue;
    }
}

