#include <iostream>
#include <vector>
#include <algorithm>

// Type III clone: Using different variable names and logic structure while preserving functionality
using Var = int;
using ClauseVec = std::vector<Var>;
using CNF = std::vector<ClauseVec>;

class SATSolver {
public:
    SATSolver(const CNF& inputFormula) : clauses(inputFormula), maxVar(0) {
        // Determine number of variables by scanning all literals
        for (const auto& clause : clauses) {
            for (Var literal : clause) {
                maxVar = std::max(maxVar, std::abs(literal));
            }
        }
        varAssignment.assign(maxVar + 1, 0); // 0: unassigned, 1: true, -1: false
    }

    bool findSolution() {
        return tryAssign(1);
    }

    void displayResult() const {
        for (int idx = 1; idx <= maxVar; ++idx) {
            if (varAssignment[idx] == 1) {
                std::cout << "x" << idx << "=T ";
            } else if (varAssignment[idx] == -1) {
                std::cout << "x" << idx << "=F ";
            }
        }
        std::cout << std::endl;
    }

private:
    CNF clauses;
    int maxVar;
    std::vector<int> varAssignment;

    bool tryAssign(int currentVar) {
        if (currentVar > maxVar) {
            return checkAllClauses();
        }

        // Assign TRUE to current variable
        varAssignment[currentVar] = 1;
        if (tryAssign(currentVar + 1)) {
            return true;
        }

        // Assign FALSE to current variable
        varAssignment[currentVar] = -1;
        if (tryAssign(currentVar + 1)) {
            return true;
        }

        // Backtrack
        varAssignment[currentVar] = 0;
        return false;
    }

    bool checkAllClauses() const {
        for (const auto& clause : clauses) {
            bool oneTrue = false;
            for (Var lit : clause) {
                if (lit > 0) {
                    if (varAssignment[lit] == 1) {
                        oneTrue = true;
                        break;
                    }
                } else {
                    if (varAssignment[-lit] == -1) {
                        oneTrue = true;
                        break;
                    }
                }
            }
            if (!oneTrue) {
                return false;
            }
        }
        return true;
    }
};

int main() {
    // Example formula: (x1 ∨ x2) ∧ (¬x1 ∨ x3)
    CNF problem = {
        {1, 2},
        {-1, 3}
    };

    SATSolver checker(problem);
    if (checker.findSolution()) {
        std::cout << "SATISFIABLE. Assignment: ";
        checker.displayResult();
    } else {
        std::cout << "UNSATISFIABLE" << std::endl;
    }

    return 0;
}

