#include <iostream>
#include <cstring>

// Define Dword as an unsigned 32-bit integer type
using Dword = unsigned int;

void ACpuid(Dword leaf, Dword* reg_eax, Dword* reg_ebx, Dword* reg_ecx, Dword* reg_edx) {
    // Inline assembly to execute CPUID instruction
    __asm {
        mov eax, leaf
        cpuid
        mov esi, reg_eax
        mov [esi], eax
        mov esi, reg_ebx
        mov [esi], ebx
        mov esi, reg_ecx
        mov [esi], ecx
        mov esi, reg_edx
        mov [esi], edx
    }
}

int main() {
    char vendor[13] = {0};
    Dword a, b, c, d;

    // Get vendor ID string (leaf 0)
    ACpuid(0, &a, &b, &c, &d);

    // Reorder registers to form vendor string: EBX, EDX, ECX
    std::memcpy(&vendor[0], &b, sizeof(Dword));
    std::memcpy(&vendor[4], &d, sizeof(Dword));
    std::memcpy(&vendor[8], &c, sizeof(Dword));

    std::cout << "CPU vendor name: " << vendor << std::endl;

    char brand[48] = {0};

    // Get processor brand string using extended leaves
    ACpuid(0x80000002, &a, &b, &c, &d);
    std::memcpy(&brand[0], &a, sizeof(Dword));
    std::memcpy(&brand[4], &b, sizeof(Dword));
    std::memcpy(&brand[8], &c, sizeof(Dword));
    std::memcpy(&brand[12], &d, sizeof(Dword));

    ACpuid(0x80000003, &a, &b, &c, &d);
    std::memcpy(&brand[16], &a, sizeof(Dword));
    std::memcpy(&brand[20], &b, sizeof(Dword));
    std::memcpy(&brand[24], &c, sizeof(Dword));
    std::memcpy(&brand[28], &d, sizeof(Dword));

    ACpuid(0x80000004, &a, &b, &c, &d);
    std::memcpy(&brand[32], &a, sizeof(Dword));
    std::memcpy(&brand[36], &b, sizeof(Dword));
    std::memcpy(&brand[40], &c, sizeof(Dword));
    std::memcpy(&brand[44], &d, sizeof(Dword));

    // Ensure null termination
    brand[47] = '\0';

    std::cout << "CPU brand: " << brand << std::endl;

    return 0;
}

