// Function to retrieve status data from shared memory
DLL int getStatus(SYSTEM_OUTPUT* output)
{
    // Handle to the file mapping object
    HANDLE hMapping = nullptr;
    STATUS_DATA* pSharedData = nullptr;
    int result = 0;

    // Attempt to open existing file mapping
    hMapping = OpenFileMapping(
        FILE_MAP_READ,
        FALSE,
        szName);

    if (nullptr == hMapping)
    {
        wprintf(L"Could not open file mapping object (%lu).\n", GetLastError());
        return -2;
    }

    // Map view of the file into process address space
    pSharedData = static_cast<STATUS_DATA*>(MapViewOfFile(hMapping, FILE_MAP_READ, 0, 0, 0));

    if (nullptr == pSharedData)
    {
        wprintf(L"Could not map view of file (%lu).\n", GetLastError());
        CloseHandle(hMapping);
        return -1;
    }

    // Copy data from shared memory to output structure
    output->ReadyForConnect = pSharedData->engine[0].ReadyForConnect;

    // Safely copy string fields using size-based copy
    std::memcpy(output->VizVersionStr, 
                pSharedData->engine[0].VizVersionStr, 
                sizeof(pSharedData->engine[0].VizVersionStr));

    std::memcpy(output->NameOfFile, 
                pSharedData->engine[0].NameOfFile, 
                sizeof(pSharedData->engine[0].NameOfFile));

    // Debug output: confirm values copied correctly
    wprintf(L"Output ReadyForConnect: %hu\n", output->ReadyForConnect);
    wprintf(L"Output VizVersionStr: %s\n", output->VizVersionStr);
    wprintf(L"Output NameOfFile: %s\n", output->NameOfFile);

Cleanup:
    // Cleanup resources in reverse order of acquisition
    if (nullptr != pSharedData)
    {
        UnmapViewOfFile(pSharedData);
        pSharedData = nullptr;
    }

    if (nullptr != hMapping)
    {
        CloseHandle(hMapping);
        hMapping = nullptr;
    }

    return result;
}

#include <iostream>
#include <algorithm>

// Definition for a binary tree node.
struct TreeNode {
    int val;
    TreeNode *left;
    TreeNode *right;
    TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
};

// Helper function that returns -1 if subtree is unbalanced, otherwise returns height
int checkBalance(TreeNode* node) {
    if (node == nullptr) {
        return 0;
    }

    int leftDepth = checkBalance(node->left);
    if (leftDepth == -1) {
        return -1; // Propagate imbalance up
    }

    int rightDepth = checkBalance(node->right);
    if (rightDepth == -1) {
        return -1; // Propagate imbalance up
    }

    // Check if current node violates balance condition
    if (std::abs(leftDepth - rightDepth) > 1) {
        return -1;
    }

    // Return height of current subtree
    return std::max(leftDepth, rightDepth) + 1;
}

// Main function to determine if tree is balanced
bool verifyBalanced(TreeNode* root) {
    return checkBalance(root) != -1;
}

// Example usage
int main() {
    // Build a balanced binary tree structure
    TreeNode* rootNode = new TreeNode(10);
    rootNode->left = new TreeNode(20);
    rootNode->right = new TreeNode(30);
    rootNode->left->left = new TreeNode(40);
    rootNode->left->right = new TreeNode(50);

    if (verifyBalanced(rootNode)) {
        std::cout << "Tree is balanced." << std::endl;
    } else {
        std::cout << "Tree is not balanced." << std::endl;
    }

    // Free allocated memory
    delete rootNode->left->left;
    delete rootNode->left->right;
    delete rootNode->left;
    delete rootNode->right;
    delete rootNode;

    return 0;
}

#include <jni.h>

static inline jclass _safe_find_class(JNIEnv* env, const char* className) {
    jclass result = env->FindClass(className);

    if (result == nullptr) {
        // Attempt to locate the NoClassDefFoundError class for proper exception handling
        jclass errorClass = env->FindClass("java/lang/NoClassDefFoundError");

        if (errorClass != nullptr) {
            env->ThrowNew(errorClass, "Requested class could not be located");
        } else {
            // Fallback: use a more generic Exception if even NoClassDefFoundError is missing
            jclass fallbackClass = env->FindClass("java/lang/Exception");
            if (fallbackClass != nullptr) {
                env->ThrowNew(fallbackClass, "Critical failure: unable to resolve NoClassDefFoundError");
            } else {
                env->ThrowNew(env->FindClass("java/lang/Error"), "Unrecoverable JNI initialization error");
            }
        }
        return nullptr; // Signal failure to caller
    }

    return result;
}

jclass retrieve_main_class(JNIEnv* env) {
    jclass loadedClass = _safe_find_class(env, "com/example/MainClass");

    if (loadedClass == nullptr) {
        // An appropriate Java exception has already been thrown by _safe_find_class
        return nullptr; // Propagate error status
    }

    perform_initialization(env, loadedClass);

    return loadedClass;
}

#include <jni.h>
