extern "C" {
    JNIEXPORT void JNICALL Java_com_example_XGBoostJNI_loadModel(JNIEnv *env, jobject /* this */, jstring modelPath) {
        const char* path = env->GetStringUTFChars(modelPath, nullptr);
        BoosterHandle booster;
        XGBoosterCreate(nullptr, 0, &booster);
        XGBoosterLoadModel(booster, path);
        env->ReleaseStringUTFChars(modelPath, path);
    }

    JNIEXPORT jdouble JNICALL Java_com_example_XGBoostJNI_predict(JNIEnv *env, jobject /* this */, jdoubleArray features) {
        jdouble* featureData = env->GetDoubleArrayElements(features, nullptr);
        jsize length = env->GetArrayLength(features);
        DMatrixHandle matrix;
        XGDMatrixCreateFromMat(featureData, length, 1, -1.0f, &matrix);
        BoosterHandle booster;  // Assume this is initialized elsewhere
        const float* prediction;
        XGBoosterPredict(booster, matrix, 0, 1, &prediction);
        env->ReleaseDoubleArrayElements(features, featureData, JNI_ABORT);
        return static_cast<jdouble>(prediction[0]);
    }
}

