/* Define the RangeSequence object */
typedef struct {
    PyObject_HEAD
    size_t upper_bound;
} RangeSequenceObject;

static int RangeSequence_construct(RangeSequenceObject *self, PyObject *args, PyObject *kwds) {
    if (!PyArg_ParseTuple(args, "k", &(self->upper_bound))) {
        return -1;
    }
    return 0;
}

static PyObject* RangeSequence_produce(RangeSequenceObject *self, PyObject *args) {
    CustomIteratorObject* iter = (CustomIteratorObject*)CustomIteratorType.tp_alloc(&CustomIteratorType, 0);
    if (iter != NULL) {
        iter->limit = self->upper_bound;
        iter->index = 0;
    }
    return (PyObject*)iter;
}

