/* Module definition */
static PyModuleDef sequence_module = {
    PyModuleDef_HEAD_INIT,
    "sequence",                /* name of module */
    NULL,                      /* module documentation, may be NULL */
    -1,                        /* size of per-interpreter state of the module, or -1 if the module keeps state in global variables. */
    NULL
};

/* Module initialization function */
PyMODINIT_FUNC PyInit_sequence(void) {
    PyObject* m;

    CustomIteratorType.tp_new = PyType_GenericNew;
    if (PyType_Ready(&CustomIteratorType) < 0)
        return NULL;

    RangeSequenceType.tp_new = PyType_GenericNew;
    if (PyType_Ready(&RangeSequenceType) < 0)
        return NULL;

    m = PyModule_Create(&sequence_module);
    if (m == NULL)
        return NULL;

    Py_INCREF(&RangeSequenceType);
    PyModule_AddObject(m, "RangeSequence", (PyObject*)&RangeSequenceType);

    Py_INCREF(&CustomIteratorType);
    PyModule_AddObject(m, "CustomIterator", (PyObject*)&CustomIteratorType);

    return m;
}

