// Function to normalize whitespace in a string by collapsing multiple spaces into one
std::string normalizeWhitespace(const std::string& text) {
    if (text.empty()) return text;

    std::string cleaned;
    bool lastWasSpace = false;

    for (size_t pos = 0; pos < text.length(); ++pos) {
        char currentChar = text[pos];

        if (std::isspace(static_cast<unsigned char>(currentChar))) {
            // Only add a space if the previous character wasn't a space and we have content already
            if (!lastWasSpace && !cleaned.empty()) {
                cleaned += ' ';
            }
            lastWasSpace = true;
        } else {
            cleaned += currentChar;
            lastWasSpace = false;
        }
    }

    // Trim trailing space if present
    if (!cleaned.empty() && cleaned.back() == ' ') {
        cleaned.erase(cleaned.size() - 1);
    }

    return cleaned;
}

// Function to verify the normalization works correctly with various inputs
void validateWhitespaceNormalization() {
    std::string input1 = "  Hello   World!  ";
    std::string expected1 = "Hello World!";
    if (normalizeWhitespace(input1) != expected1) {
        std::cerr << "Test failed: input1" << std::endl;
        return;
    }

    std::string input2 = "  This is    a test  ";
    std::string expected2 = "This is a test";
    if (normalizeWhitespace(input2) != expected2) {
        std::cerr << "Test failed: input2" << std::endl;
        return;
    }

    std::string input3 = "NoExtraSpaces";
    std::string expected3 = "NoExtraSpaces";
    if (normalizeWhitespace(input3) != expected3) {
        std::cerr << "Test failed: input3" << std::endl;
        return;
    }

    std::string input4 = " ";
    std::string expected4 = "";
    if (normalizeWhitespace(input4) != expected4) {
        std::cerr << "Test failed: input4" << std::endl;
        return;
    }

    std::string input5 = "   ";
    std::string expected5 = "";
    if (normalizeWhitespace(input5) != expected5) {
        std::cerr << "Test failed: input5" << std::endl;
        return;
    }

    std::cout << "All validation checks passed!" << std::endl;
}

int main() {
    validateWhitespaceNormalization();
    return 0;
}

