#include <iostream>
#include <vector>
#include <string>

// Generate a 3D pyramid structure based on modified Pascal's rules
std::vector<std::vector<std::vector<int>>> buildPyramidStructure(int depth) {
    std::vector<std::vector<std::vector<int>>> result(depth);

    for (int layer = 0; layer < depth; ++layer) {
        result[layer] = std::vector<std::vector<int>>(layer + 1, std::vector<int>(layer + 1, 0));

        for (int row = 0; row <= layer; ++row) {
            for (int col = 0; col <= layer; ++col) {
                if (row == 0 || col == 0 || row == col) {
                    result[layer][row][col] = 1;
                } else {
                    int computed = result[layer - 1][row - 1][col] + 
                                   result[layer - 1][row][col - 1] + 
                                   result[layer - 1][row - 1][col - 1];

                    if (computed % 2 == 0) {
                        std::cout << "Warning: Even value " << computed 
                                  << " detected at layer " << layer 
                                  << " position (" << row << ", " << col << ")" << std::endl;
                        result[layer][row][col] = -1;  // Indicate error condition
                    } else {
                        result[layer][row][col] = computed;
                    }
                }
            }
        }
    }

    return result;
}

int main() {
    int layers = 5;
    auto pyramid = buildPyramidStructure(layers);

    for (int layer = 0; layer < layers; ++layer) {
        for (int i = 0; i <= layer; ++i) {
            for (int j = 0; j <= layer; ++j) {
                std::cout << pyramid[layer][i][j] << " ";
            }
            std::cout << std::endl;
        }
        std::cout << std::endl;
    }

    return 0;
}

