#include <atomic>
#include <cstdint>

struct atomic_uint128 {
    std::atomic<uint64_t> lower;
    std::atomic<uint64_t> upper;
};

// Load the value using relaxed semantics
atomic_uint128 fetch_atomic_value(const atomic_uint128* source) {
    return {source->lower.load(std::memory_order_relaxed),
            source->upper.load(std::memory_order_relaxed)};
}

// Attempt compare-and-swap with relaxed ordering
bool try_update_128bit(atomic_uint128* target, 
                       atomic_uint128* current_val, 
                       atomic_uint128 new_val) {
    uint64_t expected_low = current_val->lower.load(std::memory_order_relaxed);
    uint64_t expected_high = current_val->upper.load(std::memory_order_relaxed);

    // First check and update the lower part
    bool success = target->lower.compare_exchange_weak(expected_low, new_val.lower,
                                                      std::memory_order_relaxed);

    // If lower matched, proceed to update the upper part
    if (success) {
        success = target->upper.compare_exchange_weak(expected_high, new_val.upper,
                                                     std::memory_order_relaxed);
    }

    return success;
}

// Store a new value using relaxed memory ordering
void set_atomic_value(atomic_uint128* destination, atomic_uint128 value) {
    destination->lower.store(value.lower, std::memory_order_relaxed);
    destination->upper.store(value.upper, std::memory_order_relaxed);
}

#include <Adafruit_NeoPixel.h>

#define LED_PIN 6
#define NUM_LEDS 22
#define BUTTON_PIN 2

Adafruit_NeoPixel strip = Adafruit_NeoPixel(NUM_LEDS, LED_PIN, NEO_GRB + NEO_KHZ800);

enum FireState { Warm, Cool, Electric };
FireState activeMode = Warm;

int btnCurrent = 0;
int btnPrevious = 0;
unsigned long lastChange = 0;
unsigned long debouncePeriod = 50;

void initSystem() {
  strip.begin();
  pinMode(BUTTON_PIN, INPUT_PULLUP);
}

void updateLoop() {
  handleInput();

  switch (activeMode) {
    case Warm:
      renderFire(255, 95, 0);   // classic orange-red fire
      break;
    case Cool:
      renderFire(0, 255, 0);    // vibrant green-yellow flame
      break;
    case Electric:
      renderFire(0, 0, 255);    // icy blue-white glow
      break;
  }
}

void renderFire(uint8_t red, uint8_t green, uint8_t blue) {
  for (int pixel = 0; pixel < NUM_LEDS; pixel++) {
    int flickerIntensity = random(128, 256);  // simulate natural flicker
    uint8_t r = red * flickerIntensity / 255;
    uint8_t g = green * flickerIntensity / 255;
    uint8_t b = blue * flickerIntensity / 255;
    strip.setPixelColor(pixel, r, g, b);
  }
  strip.show();
}

void handleInput() {
  int sensorValue = digitalRead(BUTTON_PIN);

  if (sensorValue != btnPrevious) {
    lastChange = millis();
  }

  if ((millis() - lastChange) > debouncePeriod) {
    if (sensorValue != btnCurrent) {
      btnCurrent = sensorValue;

      if (btnCurrent == LOW) {
        advancePattern();
      }
    }
  }

  btnPrevious = sensorValue;
}

void advancePattern() {
  switch (activeMode) {
    case Warm:
