using namespace std;

// Check if a number is prime using optimized trial division
bool checkPrime(int value) {
    if (value <= 1) return false;
    if (value == 2) return true;
    if (value % 2 == 0) return false;

    int limit = static_cast<int>(sqrt(value));
    for (int j = 3; j <= limit; j += 2) {
        if (value % j == 0) return false;
    }
    return true;
}

// Generate a random number with specified digit count
int createRandomNumber(int digits) {
    int lowerBound = 1;
    for (int k = 1; k < digits; ++k) {
        lowerBound *= 10;
    }
    int upperBound = lowerBound * 10 - 1;
    return (rand() % (upperBound - lowerBound + 1)) + lowerBound;
}

// Find a prime number with given number of digits
int searchForPrime(int digits) {
    srand(static_cast<unsigned>(time(nullptr)));
    int candidate = createRandomNumber(digits);
    while (!checkPrime(candidate)) {
        candidate = createRandomNumber(digits);
    }
    return candidate;
}

int main() {
    int digitCount = 3;
    int resultPrime = searchForPrime(digitCount);
    cout << "A prime number with " << digitCount << " digits is: " << resultPrime << endl;
    return 0;
}

