typedef __vector unsigned char uint8x16_p;

uint8x16_p VectorFastLoad8(const void* source)
{
    uint8x16_p result;
    long base_offset = 0;

    __asm__ volatile (
        "lxvd2x %x0, %1, %2"
        : "=wa" (result)
        : "r" (source), "r" (base_offset >> 2)
        : "memory"
    );

    return result;
}

#include <cstdio>
#include <cstdint>

// Read time-stamp counter using rdtscp instruction
uint64_t read_timestamp() {
    uint32_t lo, hi;
    __asm__ __volatile__("rdtscp" : "=a"(lo), "=d"(hi) : : "rcx");
    return (static_cast<uint64_t>(hi) << 32) | lo;
}

int main() {
    uint64_t start_time, end_time;
    const int iteration_count = 1000000;

    // First measurement: single NOP per iteration
    start_time = read_timestamp();
    for (int j = 0; j < iteration_count; ++j) {
        __asm__ volatile("nop");
    }
    end_time = read_timestamp();
    std::printf("Timestamp for %d NOPs: %llu cycles\n", iteration_count, 
                static_cast<unsigned long long>(end_time - start_time));

    // Second measurement: seven NOPs per iteration
    start_time = read_timestamp();
    for (int j = 0; j < iteration_count; ++j) {
        __asm__ volatile("nop; nop; nop; nop; nop; nop; nop;");
    }
    end_time = read_timestamp();
    std::printf("Timestamp for %d * 7 NOPs: %llu cycles\n", iteration_count, 
                static_cast<unsigned long long>(end_time - start_time));

    return 0;
}

