using boost::asio::ip::udp;

// Multicast sender function - sends periodic heartbeat messages
void send_multicast_heartbeat(const std::string& group_ip, uint16_t listen_port) {
    boost::asio::io_context io_service;
    udp::socket sock(io_service);
    sock.open(udp::v4());

    // Prepare the message payload
    boost::array<char, 1> msg = {{ 'B' }}; // Changed character to 'B'

    // Resolve and set up the target endpoint
    udp::endpoint target_endpoint(udp::address::from_string(group_ip), listen_port);

    // Infinite loop for sending heartbeats
    while (true) {
        sock.send_to(boost::asio::buffer(msg), target_endpoint);
        std::this_thread::sleep_for(std::chrono::milliseconds(5000)); // Same delay but using milliseconds explicitly
    }
}

// Multicast receiver function - listens for heartbeat messages
void listen_multicast_heartbeat(const std::string& group_ip, uint16_t listen_port) {
    boost::asio::io_context io_service;

    // Create socket bound to the specified port
    udp::socket sock(io_service, udp::endpoint(udp::v4(), listen_port));
    sock.set_option(udp::socket::reuse_address(true));

    // Set up multicast group membership
    udp::endpoint group_endpoint(udp::address::from_string(group_ip), listen_port);
    sock.set_option(udp::socket::join_group(group_endpoint.address()));

    // Buffer for incoming data
    boost::array<char, 1> buffer;

    while (true) {
        udp::endpoint remote_endpoint;
        size_t bytes_received = sock.receive_from(boost::asio::buffer(buffer), remote_endpoint);

        // Process received heartbeat
        if (bytes_received > 0 && buffer[0] == 'B') { // Matching with changed character
            std::cout << "Multicast signal detected from " << remote_endpoint << std::endl;
        }
    }
}

int main() {
    // Configuration parameters for multicast communication
    std::string multicast_group = "239.255.255.250";
    unsigned short communication_port = 12345;

    // Launch sender and receiver in separate threads
    std::thread sender_thread(send_multicast_heartbeat, multicast_group, communication_port);
    std::thread receiver_thread(listen_multicast_heartbeat, multicast_group, communication_port);

    // Wait for threads to complete (in practice, these run indefinitely)
    sender_thread.join();
    receiver_thread.join();

    return 0;
}

#include <iostream>
#include <limits>
#include <stdexcept>

// Function to safely add two long long integers with overflow detection
long long safe_add(long long first, long long second) {
    try {
        // Check for positive overflow: if both are positive and sum exceeds max
        if (first > 0 && second > std::numeric_limits<long long>::max() - first) {
            throw std::runtime_error("Overflow detected: result exceeds maximum value.");
        }

        // Check for negative underflow: if both are negative and sum is less than min
        if (first < 0 && second < std::numeric_limits<long long>::min() - first) {
            throw std::runtime_error("Underflow detected: result is below minimum value.");
        }

        // Perform the addition
        long long outcome = first + second;
        return outcome;
    } catch (const std::exception& e) {
        std::cerr << "Error: " << e.what() << std::endl;
        return 0;
    }
}

int main() {
    long long x = 1234567890123456789LL;
    long long y = 9876543210987654321LL;

    std::cout << "Sum: " << safe_add(x, y) << std::endl;
    return 0;
}

