class Individual {
private:
    std::string fullName;
    std::set<std::string> aliases;
    std::set<std::string> honors;

public:
    Individual(const std::string& name) : fullName(name) {}

    // Append an alias
    void appendAlias(const std::string& alias) {
        if (alias.empty()) {
            throw std::invalid_argument("Alias cannot be empty.");
        }
        aliases.insert(alias);
    }

    // Remove an alias
    void removeAlias(const std::string& alias) {
        if (aliases.count(alias) == 0) {
            throw std::invalid_argument("Alias does not exist.");
        }
        aliases.erase(alias);
    }

    // Replace an alias with another
    void replaceAlias(const std::string& previousAlias, const std::string& updatedAlias) {
        if (previousAlias == updatedAlias) {
            return; // No modification required
        }
        auto it = aliases.find(previousAlias);
        if (it == aliases.end()) {
            throw std::invalid_argument("Previous alias does not exist.");
        }
        if (!updatedAlias.empty()) {
            aliases.erase(it);
            aliases.insert(updatedAlias);
        } else {
            throw std::invalid_argument("New alias cannot be empty.");
        }
    }

    // Add an honorific title
    void addHonor(const std::string& honor) {
        if (honor.empty()) {
            throw std::invalid_argument("Honorific title cannot be empty.");
        }
        honors.insert(honor);
    }

    // Remove an honorific title
    void removeHonor(const std::string& honor) {
        if (honors.count(honor) == 0) {
            throw std::invalid_argument("Honorific title does not exist.");
        }
        honors.erase(honor);
    }

    // Update an honorific title
    void updateHonor(const std::string& oldHonor, const std::string& newHonor) {
        if (oldHonor == newHonor) {
            return; // No change necessary
        }
        auto it = honors.find(oldHonor);
        if (it == honors.end()) {
            throw std::invalid_argument("Old honorific title does not exist.");
        }
        if (!newHonor.empty()) {
            honors.erase(it);
            honors.insert(newHonor);
        } else {
            throw std::invalid_argument("New honorific title cannot be empty.");
        }
    }

    // Access all aliases
    const std::set<std::string>& getAliases() const {
        return aliases;
    }

    // Access all honorific titles
    const std::set<std::string>& getHonors() const {
        return honors;
    }

    // Access the individual's full name
    const std::string& getFullName() const {
        return fullName;
    }
};

#include <windows.h>

// Window procedure declaration
LRESULT CALLBACK MainWndProc(HWND hwnd, UINT message, WPARAM wParam, LPARAM lParam);

// Entry point for Windows GUI application
int WINAPI WinMain(HINSTANCE hInstance, HINSTANCE hPrevInstance, LPSTR lpCmdLine, int nShowCmd) {
    // Register window class
    WNDCLASS windowClass = {0};
    windowClass.lpfnWndProc = MainWndProc;
    windowClass.hInstance = hInstance;
    windowClass.hbrBackground = CreateSolidBrush(RGB(255, 255, 255));
    windowClass.lpszClassName = "TransparentDraggableWindow";
    RegisterClass(&windowClass);

    // Create the window
    HWND hWnd = CreateWindow(
        "TransparentDraggableWindow",
        "Transparent Draggable Window",
        WS_OVERLAPPEDWINDOW,
        CW_USEDEFAULT, CW_USEDEFAULT, 400, 300,
        NULL, NULL, hInstance, NULL
    );

    // Enable layered window style for transparency support
    SetWindowLong(hWnd, GWL_EXSTYLE, GetWindowLong(hWnd, GWL_EXSTYLE) | WS_EX_LAYERED);

    ShowWindow(hWnd, nShowCmd);
    UpdateWindow(hWnd);

    // Message loop
    MSG messageStruct = {0};
    while (GetMessage(&messageStruct, NULL, 0, 0)) {
        TranslateMessage(&messageStruct);
        DispatchMessage(&messageStruct);
    }

    return static_cast<int>(messageStruct.wParam);
}

// Window procedure implementation
LRESULT CALLBACK MainWndProc(HWND hwnd, UINT msg, WPARAM wp, LPARAM lp) {
    static POINT dragOffset;
    static bool isDragging = false;

    switch (msg) {
        case WM_DESTROY:
            PostQuitMessage(0);
            break;

        case WM_LBUTTONDOWN:
            // Capture mouse and start dragging
            dragOffset.x = GET_X_LPARAM(lp);
            dragOffset.y = GET_Y_LPARAM(lp);
            isDragging = true;

            // Make window semi-transparent during drag
            SetLayeredWindowAttributes(hwnd, 0, 200, LWA_ALPHA);
            SetCursor(LoadCursor(NULL, IDC_SIZEALL));
            SetCapture(hwnd);
            break;

        case WM_MOUSEMOVE:
            if (isDragging) {
                // Calculate new position based on mouse movement
                int newX = GET_X_LPARAM(lp) - dragOffset.x;
                int newY = GET_Y_LPARAM(lp) - dragOffset.y;
                SetWindowPos(hwnd, NULL, newX, newY, 0, 0, SWP_NOSIZE | SWP_NOZORDER | SWP_NOACTIVATE);
            }
            break;

        case WM_LBUTTONUP:
            // Stop dragging and restore opacity
            isDragging = false;
            ReleaseCapture();
            SetLayeredWindowAttributes(hwnd, 0, 255, LWA_ALPHA);
            SetCursor(LoadCursor(NULL, IDC_ARROW));
            break;

        default:
            return DefWindowProc(hwnd, msg, wp, lp);
    }

    return 0;
}

