// Function to retrieve CPU feature flags using inline assembly
inline unsigned int fetch_cpu_capabilities()
{
    unsigned int result;

    // Save and restore registers manually via inline assembly
    asm volatile (
        "pusha\n\t"                    // Push all general-purpose registers
        "mov $1, %%eax\n\t"            // Set CPUID function 1
        "cpuid\n\t"                    // Execute CPUID instruction
        "mov %%edx, %0\n\t"            // Store feature flags (EDX) in output
        "popa\n\t"                     // Restore all general-purpose registers
        : "=r" (result)
        :
        : "eax", "ebx", "ecx", "edx"   // Explicitly list clobbered registers
    );

    return result;
}

int main() {
    // Check bit 26 (0x04000000) which indicates SSE2 support
    const bool has_sse2_support = (fetch_cpu_capabilities() & 0x04000000U) != 0U;

    if (has_sse2_support) {
        std::cout << "Supports SSE2" << std::endl;
    } else {
        std::cout << "Does NOT support SSE2" << std::endl;
    }

    return 0;
}

