// Wrapper class to manage native resources and provide JNI interface
class NativeManager {
private:
    int storedValue;

public:
    NativeManager() : storedValue(0) {}

    void assignValue(int value) {
        storedValue = value;
    }

    int retrieveValue() const {
        return storedValue;
    }
};

extern "C" {
    // Create new native object and return its pointer as handle
    JNIEXPORT jlong JNICALL Java_SimpleClass_createNative(JNIEnv* env, jobject obj) {
        NativeManager* manager = new NativeManager();
        return reinterpret_cast<jlong>(manager);
    }

    // Destroy the native object using provided handle
    JNIEXPORT void JNICALL Java_SimpleClass_destroyNative(JNIEnv* env, jobject obj, jlong handle) {
        if (handle != 0) {
            NativeManager* manager = reinterpret_cast<NativeManager*>(handle);
            delete manager;
        }
    }

    // Set integer variable through native handle
    JNIEXPORT void JNICALL Java_SimpleClass_setIntVar(JNIEnv* env, jobject obj, jint value) {
        // Get field ID for nativeHandle
        jclass cls = env->GetObjectClass(obj);
        jfieldID fid = env->GetFieldID(cls, "nativeHandle", "J");
        jlong handle = env->GetLongField(obj, fid);

        // Cast and use the native object
        NativeManager* manager = reinterpret_cast<NativeManager*>(handle);
        manager->assignValue(static_cast<int>(value));
    }

    // Get integer variable through native handle
    JNIEXPORT jint JNICALL Java_SimpleClass_getIntVar(JNIEnv* env, jobject obj) {
        // Get field ID for nativeHandle
        jclass cls = env->GetObjectClass(obj);
        jfieldID fid = env->GetFieldID(cls, "nativeHandle", "J");
        jlong handle = env->GetLongField(obj, fid);

        // Cast and use the native object
        NativeManager* manager = reinterpret_cast<NativeManager*>(handle);
        return static_cast<jint>(manager->retrieveValue());
    }
}

