using Point = vector<double>;
using Line = vector<Point>;
using LineArray = vector<Line>;

// Forward declaration of the original function f
Eigen::MatrixXd computeMatrix(const LineArray& inputLines);

// Alternative wrapper that transforms Eigen matrix to nested vectors
vector<vector<double>> matrix_to_vector(const LineArray& lines) {
    Eigen::MatrixXd computed = computeMatrix(lines);
    size_t row_count = static_cast<size_t>(computed.rows());
    size_t col_count = static_cast<size_t>(computed.cols());
    vector<vector<double>> output(row_count, vector<double>(col_count));

    for (size_t r = 0; r < row_count; ++r) {
        for (size_t c = 0; c < col_count; ++c) {
            output[r][c] = computed(r, c);
        }
    }

    return output;
}

EMSCRIPTEN_BINDINGS(binding_module) {
    register_vector<double>("Point");
    register_vector<vector<double>>("Line");
    register_vector<vector<vector<double>>>("LineArray");
    register_vector<vector<double>>("Matrix");

    function("matrix_to_vector", &matrix_to_vector);
}

