// Retrieve IP address associated with a RAS connection
void RetrieveRASIPAddress(HRASCONN hConnection)
{
    // Query current RAS connection status
    RASCONNSTATUS connectionStatus = { sizeof(RASCONNSTATUS) };
    if (RasGetConnectStatus(hConnection, &connectionStatus) == ERROR_SUCCESS)
    {
        wprintf(L"RAS device name: %s\n", connectionStatus.szDeviceName);

        // First call to determine required buffer size
        PIP_ADAPTER_ADDRESSES adapterList = NULL;
        ULONG bufferSize = 0;
        DWORD result = GetAdaptersAddresses(AF_UNSPEC, GAA_FLAG_INCLUDE_PREFIX, NULL, adapterList, &bufferSize);

        if (result == ERROR_BUFFER_OVERFLOW)
        {
            adapterList = (IP_ADAPTER_ADDRESSES*)malloc(bufferSize);
            if (!adapterList)
            {
                printf("Failed to allocate memory for adapter list\n");
                return;
            }
        }

        // Second call to retrieve actual adapter data
        result = GetAdaptersAddresses(AF_UNSPEC, GAA_FLAG_INCLUDE_PREFIX, NULL, adapterList, &bufferSize);
        if (result == NO_ERROR)
        {
            PIP_ADAPTER_ADDRESSES currentAdapter = adapterList;
            while (currentAdapter)
            {
                // Compare device name with adapter description or friendly name
                if (wcscmp(currentAdapter->Description, connectionStatus.szDeviceName) == 0 ||
                    wcscmp(currentAdapter->FriendlyName, connectionStatus.szDeviceName) == 0)
                {
                    PIP_ADAPTER_UNICAST_ADDRESS unicastAddr = currentAdapter->FirstUnicastAddress;
                    while (unicastAddr)
                    {
                        if (unicastAddr->Address.lpSockaddr->sa_family == AF_INET)
                        {
                            char ipBuffer[INET_ADDRSTRLEN];
                            struct sockaddr_in* addrIn = (struct sockaddr_in*)unicastAddr->Address.lpSockaddr;

                            if (inet_ntop(AF_INET, &addrIn->sin_addr, ipBuffer, INET_ADDRSTRLEN))
                            {
                                printf("RAS IP Address: %s\n", ipBuffer);
                            }
                        }
                        unicastAddr = unicastAddr->Next;
                    }
                    break;
                }
                currentAdapter = currentAdapter->Next;
            }
        }
        else
        {
            printf("GetAdaptersAddresses failed: %lu\n", result);
        }

        if (adapterList)
        {
            free(adapterList);
        }
    }
    else
    {
        printf("Failed to get RAS connection status\n");
    }
}

