class JammingWeapon : Weapon
{
    float fJamProbability;
    int iJamDuration;
    bool bIsInJamState;

    Default
    {
        fJamProbability = 0.05; // 5% chance of jamming
        iJamDuration = 70; // Jamming period in tics
        bIsInJamState = false;
    }

    States
    {
    Ready:
        WEAP B 1 A_WeaponReady;
        Loop;

    Deselect:
        TNT1 A 0 A_CheckJamStatus; // Check for jam status
        WEAP C 1 A_Lower;
        Loop;

    Select:
        TNT1 A 0 A_CheckJamStatus; // Check for jam status
        WEAP C 1 A_Raise;
        Loop;

    Fire:
        WEAP A 0 Bright A_PlaySound("weapons/pistol", CHAN_WEAPON);
        TNT1 A 0 A_CheckJamStatus; // Check for jam status

        WEAP A 0 A_GunFlash;
        WEAP A 1 Bright;
        WEAP A 0 A_FireBullets(1, 1, 1, 5, "BulletPuff");

        WEAP A 0 A_ReFire;
        Goto Ready;

    Flash:
        TNT1 A 0 A_CheckJamStatus; // Check for jam status
        Goto LightDone;

    JammedSequence:
        WEAP A 3 A_PlaySound("weapons/jam", CHAN_WEAPON);
        WEAP A 3;
        WEAP A 3;
        WEAP A 0 A_ResetJamTimer;
        Goto Ready;

    LightDone:
        TNT1 A 0 A_Light0;
        Stop;
    }

    override void PostBeginPlay()
    {
        Super.PostBeginPlay();
    }

    private state void A_CheckJamStatus()
    {
        if (bIsInJamState)
        {
            Goto JammedSequence;
            return;
        }

        if (random() < fJamProbability)
        {
            bIsInJamState = true;
            Goto JammedSequence;
        }
    }

    private state void A_ResetJamTimer()
    {
        iJamDuration--;
        if (iJamDuration <= 0)
        {
            bIsInJamState = false;
            iJamDuration = 70;
        }
    }
}

