using json = nlohmann::json;

// Base class for game object elements
class GameObjectPart {
public:
    virtual ~GameObjectPart() = default;
    virtual void setup(const json& config) = 0;
};

// Concrete part: spatial location
class LocationPart : public GameObjectPart {
public:
    float posX, posY, posZ;

    void setup(const json& config) override {
        posX = config.value("x", 0.0f);
        posY = config.value("y", 0.0f);
        posZ = config.value("z", 0.0f);
    }
};

// Concrete part: life statistics
class VitalityPart : public GameObjectPart {
public:
    int vitalityPoints;

    void setup(const json& config) override {
        vitalityPoints = config.value("health", 100);
    }
};

// Manager for creating different parts
class PartManager {
public:
    using Builder = std::function<std::unique_ptr<GameObjectPart>()>;

    void addBuilder(const std::string& type, Builder builder) {
        builders_[type] = builder;
    }

    std::unique_ptr<GameObjectPart> produce(const std::string& type) const {
        auto found = builders_.find(type);
        if (found != builders_.end()) {
            return found->second();
        }
        return nullptr;
    }

private:
    std::unordered_map<std::string, Builder> builders_;
};

// Container for assembling game objects
class GameObject {
public:
    void attach(std::unique_ptr<GameObjectPart> part) {
        parts_.push_back(std::move(part));
    }

    void configure(const json& settings) {
        for (auto& part : parts_) {
            part->setup(settings);
        }
    }

    const std::vector<std::unique_ptr<GameObjectPart>>& getParts() const {
        return parts_;
    }

private:
    std::vector<std::unique_ptr<GameObjectPart>> parts_;
};

// Assembler for game entities
class EntityAssembler {
public:
    EntityAssembler(PartManager& manager) : manager_(manager) {}

    std::unique_ptr<GameObject> build(const json& spec) {
        auto obj = std::make_unique<GameObject>();
        for (const auto& [partName, partConfig] : spec.items()) {
            auto part = manager_.produce(partName);
            if (part) {
                obj->attach(std::move(part));
            }
        }
        obj->configure(spec);
        return obj;
    }

private:
    PartManager& manager_;
};

int main() {
    PartManager partManager;
    partManager.addBuilder("Position", [] { return std::make_unique<LocationPart>(); });
    partManager.addBuilder("Health", [] { return std::make_unique<VitalityPart>(); });

    EntityAssembler assembler(partManager);

    std::string jsonString = R"({
        "Position": { "x": 1.0, "y": 2.0, "z": 3.0 },
        "Health": { "health": 100 }
    })";

    json specification = json::parse(jsonString);
    auto gameObj = assembler.build(specification);

    // Demonstrate accessing parts
    for (const auto& part : gameObj->getParts()) {
        if (auto loc = dynamic_cast<LocationPart*>(part.get())) {
            std::cout << "Location: " << loc->posX << ", " << loc->posY << ", " << loc->posZ << std::endl;
        } else if (auto vit = dynamic_cast<VitalityPart*>(part.get())) {
            std::cout << "Vitality: " << vit->vitalityPoints << std::endl;
        }
    }

    return 0;
}

