// Generate the first n Fibonacci numbers
std::vector<int> generateFibonacci(int count) {
    if (count <= 0) return {};
    if (count == 1) return {0};

    std::vector<int> sequence;
    sequence.push_back(0);
    sequence.push_back(1);

    for (int index = 2; index < count; ++index) {
        int previous = sequence[index - 1];
        int beforePrevious = sequence[index - 2];
        int current = previous + beforePrevious;
        sequence.push_back(current);
    }

    return sequence;
}

int main() {
    int n = 10;
    std::vector<int> fibNumbers = generateFibonacci(n);

    for (size_t i = 0; i < fibNumbers.size(); ++i) {
        std::cout << fibNumbers[i] << " ";
    }
    std::cout << std::endl;

    return 0;
}

