// Check if a string is a palindrome by comparing characters from both ends
bool isPalindrome(const std::string& s) {
    int left = 0;
    int right = static_cast<int>(s.length()) - 1;

    while (left < right) {
        if (s[left] != s[right]) {
            return false;
        }
        left++;
        right--;
    }
    return true;
}

int main() {
    std::string inputStrings[] = {"racecar", "hello", "madam", "world"};

    for (int i = 0; i < 4; ++i) {
        if (isPalindrome(inputStrings[i])) {
