        }
    }

    return 0;
}

#include <iostream>
#include <vector>
#include <mutex>
#include <cuda_runtime.h>

// Custom GPU memory allocator using a free-list approach
class GpuMemoryPool {
public:
    GpuMemoryPool(size_t block_size, size_t count) 
        : block_size_(block_size), block_count_(count) {
        // Allocate contiguous GPU memory
        cudaMalloc(&memory_pool_, block_size * count);

        // Setup tracking structures
        block_info_.resize(count);
        for (size_t i = 0; i < count; ++i) {
            block_info_[i].is_available = true;
            block_info_[i].id = static_cast<int>(i);
        }
        available_head_ = 0;
    }

    ~GpuMemoryPool() {
        cudaFree(memory_pool_);
    }

    void* request_block() {
        std::lock_guard<std::mutex> guard(access_mutex_);

        if (available_head_ == -1) {
            throw std::runtime_error("No available memory blocks");
        }

        int block_id = available_head_;
        available_head_ = block_info_[block_id].next_available;

        block_info_[block_id].is_available = false;
        return static_cast<char*>(memory_pool_) + block_id * block_size_;
    }

    void release_block(void* address) {
        std::lock_guard<std::mutex> guard(access_mutex_);

        size_t offset = static_cast<char*>(address) - static_cast<char*>(memory_pool_);
        int block_index = static_cast<int>(offset / block_size_);

        block_info_[block_index].is_available = true;
        block_info_[block_index].next_available = available_head_;
        available_head_ = block_index;
    }

private:
    size_t block_size_;
    size_t block_count_;
    void* memory_pool_;
    std::vector<MemoryBlockInfo> block_info_;
    int available_head_ = 0;
    std::mutex access_mutex_;

    struct MemoryBlockInfo {
        bool is_available;
        int id;
        int next_available = -1;
    };
};

int main() {
    GpuMemoryPool pool(256, 1024);

    void* block_a = pool.request_block();
    void* block_b = pool.request_block();

    pool.release_block(block_a);
    pool.release_block(block_b);

    return 0;
}

