#include <iostream>
#include <cmath>
#include <chrono>
#include <vector>

// Constants for computation limits
const unsigned int MAX_ITERATIONS = 40000;
const unsigned int DATA_SIZE = 10000;

int main()
{
    // Initialize data vectors and coefficient arrays
    std::vector<double> input_values(DATA_SIZE);
    std::vector<double> output_values(DATA_SIZE);
    std::vector<double> cosine_coefficients(MAX_ITERATIONS, 0.0);
    std::vector<double> sine_coefficients(MAX_ITERATIONS, 0.0);

    // Start timing the computation
    auto begin_time = std::chrono::high_resolution_clock::now();

    // Iterate through each harmonic frequency
    for (unsigned int harmonic = 1; harmonic <= MAX_ITERATIONS; ++harmonic) {
        std::vector<double> cos_terms(DATA_SIZE);
        std::vector<double> sin_terms(DATA_SIZE);

        // Precompute trigonometric values for current harmonic
        for (unsigned int idx = 0; idx < DATA_SIZE; ++idx) {
            double angle = harmonic * input_values[idx];
            cos_terms[idx] = std::cos(angle);
            sin_terms[idx] = std::sin(angle);
        }

        // Compute cosine coefficient using inner product with adjusted range
        double diff_term = output_values[DATA_SIZE - 1] - output_values[0];
        double cos_sum = 0.0;
        for (unsigned int i = 0; i < DATA_SIZE - 1; ++i) {
            cos_sum += (output_values[i + 1] - output_values[i]) * cos_terms[i];
        }
        cosine_coefficients[harmonic - 1] += diff_term + cos_sum;

        // Compute sine coefficient similarly
        double sin_sum = 0.0;
        for (unsigned int i = 0; i < DATA_SIZE - 1; ++i) {
            sin_sum += (output_values[i + 1] - output_values[i]) * sin_terms[i];
        }
        sine_coefficients[harmonic - 1] += sin_sum;
    }

    // Stop timing and compute duration
    auto end_time = std::chrono::high_resolution_clock::now();
    auto elapsed = std::chrono::duration_cast<std::chrono::seconds>(end_time - begin_time);

    std::cout << "Time: " << elapsed.count() << " seconds" << std::endl;
    return 0;
}

