struct InlineAsmInjector : public FunctionPass {
  static char ID;
  InlineAsmInjector() : FunctionPass(ID) {}

  bool runOnFunction(Function &func) override {
    // Position builder at the start of the entry block
    BasicBlock &entry = func.getEntryBlock();
    IRBuilder<> builder(&entry, entry.begin());

    // Prepare inline assembly: bswap on a 32-bit register
    StringRef asmCode = "bswap $0";
    StringRef asmConstraints = "=r,r";

    // Define types needed for inline assembly
    Type *int32Ty = Type::getInt32Ty(func.getContext());
    ArrayRef<Type *> argTypes = {int32Ty};
    FunctionType *asmFuncTy = FunctionType::get(int32Ty, argTypes, /*isVarArg=*/false);

    // Construct the inline assembly object
    InlineAsm *bswapAsm = InlineAsm::get(asmFuncTy, asmCode.str(), asmConstraints.str(),
                                          /*hasSideEffects=*/false, /*isAlignStack=*/false);

    // Create a constant argument (e.g., value 0x12345678)
    ConstantInt *inputVal = ConstantInt::get(int32Ty, 0x12345678U);
    Value *result = builder.CreateCall(bswapAsm, inputVal, "bswap_out");

    // Optional: could insert before a specific point, but here we rely on builder position

    return true; // Indicates modification occurred
  }
};

char InlineAsmInjector::ID = 0;
static RegisterPass<InlineAsmInjector> Y("inject-bswap-asm", "Inject BSWAP Inline Assembly");

