#include <iostream>
#include <vector>

// Recursive function to compute matrix determinant using Laplace expansion
double computeDeterminant(const std::vector<std::vector<double>>& mat) {
    int size = mat.size();

    // Handle 1x1 matrix directly
    if (size == 1) {
        return mat[0][0];
    }

    // Handle 2x2 matrix explicitly
    if (size == 2) {
        return mat[0][0] * mat[1][1] - mat[0][1] * mat[1][0];
    }

    double result = 0.0;

    // Iterate through each column of the first row for cofactor expansion
    for (int colIndex = 0; colIndex < size; ++colIndex) {
        // Prepare the minor matrix by excluding row 0 and current column
        std::vector<std::vector<double>> minor(size - 1, std::vector<double>(size - 1));

        // Fill the minor matrix
        for (int row = 1; row < size; ++row) {
            int minorCol = 0;
            for (int col = 0; col < size; ++col) {
                if (col != colIndex) {
                    minor[row - 1][minorCol++] = mat[row][col];
                }
            }
        }

        // Compute sign based on column index parity
        int sign = (colIndex % 2 == 0) ? 1 : -1;

        // Accumulate the cofactor contribution
        result += sign * mat[0][colIndex] * computeDeterminant(minor);
    }

    return result;
}

int main() {
    // Test matrix with known determinant (singular matrix)
    std::vector<std::vector<double>> testMatrix = {
        {1, 2, 3},
        {4, 5, 6},
        {7, 8, 9}
    };

    double detValue = computeDeterminant(testMatrix);
    std::cout << "The determinant of the matrix is: " << detValue << std::endl;

    return 0;
}

