void histSubtractFromBits(uint64_t* cursor, uint16_t* hist) {
    int wordIndex = 0;
    while (wordIndex < 4) {
        uint64_t currentWord = cursor[wordIndex];
        int bitPosition = 0;
        while (bitPosition < 64) {
            if ((currentWord >> bitPosition) & 1ULL) {
                int histIndex = wordIndex * 64 + bitPosition;
                hist[histIndex] -= 1;
            }
            bitPosition++;
        }
        wordIndex++;
    }
}

#include <openssl/des.h>
#include <openssl/err.h>
#include <iostream>
#include <fstream>
#include <vector>

void tripleDESEncrypt(const std::string& sourcePath, const std::string& destPath, 
                     const unsigned char* encryptionKey, const unsigned char* initializationVector) {
    std::ifstream inputStream(sourcePath, std::ios::binary);
    std::ofstream outputStream(destPath, std::ios::binary);

    if (!inputStream.is_open() || !outputStream.is_open()) {
        std::cerr << "Failed to open file(s)." << std::endl;
        return;
    }

    std::vector<unsigned char> dataChunk(1024);
    DES_key_schedule scheduleA, scheduleB, scheduleC;
    DES_set_key((const_DES_cblock*)encryptionKey, &scheduleA);
    DES_set_key((const_DES_cblock*)(encryptionKey + 8), &scheduleB);
    DES_set_key((const_DES_cblock*)(encryptionKey + 16), &scheduleC);

    while (true) {
        inputStream.read(reinterpret_cast<char*>(dataChunk.data()), dataChunk.size());
        std::streamsize bytesRead = inputStream.gcount();

        if (bytesRead == 0) break;

        DES_ede3_cbc_encrypt(dataChunk.data(), dataChunk.data(), bytesRead, 
                            &scheduleA, &scheduleB, &scheduleC, 
                            (DES_cblock*)initializationVector, DES_ENCRYPT);
        outputStream.write(reinterpret_cast<char*>(dataChunk.data()), bytesRead);
    }

    inputStream.close();
    outputStream.close();
}

int main() {
    // 24-byte key for 3-key 3DES algorithm
    unsigned char keyMaterial[24] = { /* 24 bytes for 3-key 3DES */ };
    // 8-byte initialization vector
    unsigned char ivData[8] = { /* 8 bytes for IV */ };

    tripleDESEncrypt("source.txt", "encrypted.bin", keyMaterial, ivData);

    return 0;
}

