    size_t height() const { return storage_.size(); }

    // Get number of columns
    size_t width() const { return storage_.empty() ? 0 : storage_[0].size(); }

    // Convert internal data to NumPy array representation
    PyObject* as_numpy_array() const {
        npy_intp shape[2] = {static_cast<npy_intp>(height()), static_cast<npy_intp>(width())};
        PyArrayObject* result = (PyArrayObject*)PyArray_SimpleNew(2, shape, NPY_DOUBLE);
        std::memcpy(PyArray_DATA(result), storage_.data(), height() * width() * sizeof(double));
        return PyArray_Return(result);
    }

private:
    std::vector<std::vector<double>> storage_;
};

