// Define the structure for the tree node
struct TreeNode {
    int val;
    TreeNode *leftChild;
    TreeNode *rightChild;
    TreeNode(int x) : val(x), leftChild(nullptr), rightChild(nullptr) {}
};

// Helper function to verify if two subtrees are mirror images of each other
bool checkSymmetry(TreeNode* nodeA, TreeNode* nodeB) {
    // Both nodes are null: symmetric
    if (nodeA == nullptr && nodeB == nullptr) return true;
    // One is null but not the other: not symmetric
    if (nodeA == nullptr || nodeB == nullptr) return false;
    // Values must match and children must be mirrors in opposite order
    return (nodeA->val == nodeB->val) 
           && checkSymmetry(nodeA->leftChild, nodeB->rightChild) 
           && checkSymmetry(nodeA->rightChild, nodeB->leftChild);
}

// Main function to determine if the entire tree is symmetric
bool evaluateSymmetry(TreeNode* root) {
    return checkSymmetry(root, root);
}

// Utility function to allocate a new tree node
TreeNode* newNode(int value) {
    return new TreeNode(value);
}

// Test routine to validate symmetry detection
void runSymmetryTest() {
    // Construct test tree:
    //     1
    //    / \
    //   2   2
    //  / \ / \
    // 3  4 4  3
    TreeNode* root = newNode(1);
    root->leftChild = newNode(2);
    root->rightChild = newNode(2);
    root->leftChild->leftChild = newNode(3);
    root->leftChild->rightChild = newNode(4);
    root->rightChild->leftChild = newNode(4);
    root->rightChild->rightChild = newNode(3);

    if (evaluateSymmetry(root)) {
        cout << "The tree is symmetric." << endl;
    } else {
        cout << "The tree is not symmetric." << endl;
    }
}

int main() {
    runSymmetryTest();
    return 0;
}

#include <iostream>
#include <optional>

class ListNode {
public:
    int data;
    ListNode* previous;
    ListNode* nextNode;

    ListNode(int val) : data(val), previous(nullptr), nextNode(nullptr) {}
};

class MoveToFrontList {
private:
    ListNode* start;
    ListNode* end;

public:
    MoveToFrontList() : start(nullptr), end(nullptr) {}

    ~MoveToFrontList() {
        while (start != nullptr) {
            ListNode* temp = start;
            start = start->nextNode;
            delete temp;
        }
    }

    void addElement(int value) {
        ListNode* newNode = new ListNode(value);
        if (start == nullptr) {
            start = end = newNode;
        } else {
            newNode->nextNode = start;
            start->previous = newNode;
            start = newNode;
        }
    }

    bool eraseElement(int value) {
        ListNode* current = start;
        while (current != nullptr) {
            if (current->data == value) {
                if (current->previous) {
                    current->previous->nextNode = current->nextNode;
                } else {
                    start = current->nextNode;
                }
                if (current->nextNode) {
                    current->nextNode->previous = current->previous;
                } else {
                    end = current->previous;
                }
                delete current;
                return true;
            }
            current = current->nextNode;
        }
        return false;
    }

    std::optional<int> find(int value) {
        ListNode* current = start;
        while (current != nullptr) {
            if (current->data == value) {
                bringToFront(current);
                return current->data;
            }
            current = current->nextNode;
        }
        return std::nullopt;
    }

private:
    void bringToFront(ListNode* node) {
        if (node == start) return;

        // Detach node from its current position
        if (node->previous) {
            node->previous->nextNode = node->nextNode;
        }
        if (node->nextNode) {
            node->nextNode->previous = node->previous;
        }
        if (node == end) {
            end = node->previous;
        }

        // Insert at the beginning
        node->nextNode = start;
        node->previous = nullptr;
        start->previous = node;
        start = node;
    }
};

int main() {
    MoveToFrontList list;
    list.addElement(1);
    list.addElement(2);
    list.addElement(3);
    list.addElement(4);

    std::cout << "Find 3: " << list.find(3).value_or(-1) << std::endl;
    std::cout << "Find 1: " << list.find(1).value_or(-1) << std::endl;
    std::cout << "Find 2: " << list.find(2).value_or(-1) << std::endl;

    list.eraseElement(3);
    std::cout << "Find 3 after deletion: " << list.find(3).value_or(-1) << std::endl;

    return 0;
}

