// Perform cross-section of STL model with a horizontal plane
int main() {
    // Create and configure the STL file reader
    vtkSTLReader* modelReader = vtkSTLReader::New();
    modelReader->SetFileName("your_model.stl");
    modelReader->Update();

    // Define a cutting plane at origin with upward normal
    vtkPlane* sectionPlane = vtkPlane::New();
    sectionPlane->SetOrigin(0.0, 0.0, 0.0);
    sectionPlane->SetNormal(0.0, 0.0, 1.0);

    // Generate cut lines using the plane
    vtkCutter* crossSection = vtkCutter::New();
    crossSection->SetCutFunction(sectionPlane);
    crossSection->SetInputConnection(modelReader->GetOutputPort());

    // Prepare data for visualization
    vtkPolyDataMapper* lineMapper = vtkPolyDataMapper::New();
    lineMapper->SetInputConnection(crossSection->GetOutputPort());

    // Create visual representation of the cut
    vtkActor* sectionActor = vtkActor::New();
    sectionActor->SetMapper(lineMapper);

    // Set up rendering environment
    vtkRenderer* viewRenderer = vtkRenderer::New();
    viewRenderer->AddActor(sectionActor);

    vtkRenderWindow* displayWindow = vtkRenderWindow::New();
    displayWindow->AddRenderer(viewRenderer);

    vtkRenderWindowInteractor* userInteraction = vtkRenderWindowInteractor::New();
    userInteraction->SetRenderWindow(displayWindow);

    // Start interactive visualization
    userInteraction->Start();

    // Clean up all VTK objects to prevent memory leaks
    modelReader->Delete();
    sectionPlane->Delete();
    crossSection->Delete();
    lineMapper->Delete();
    sectionActor->Delete();
    viewRenderer->Delete();
    displayWindow->Delete();
    userInteraction->Delete();

    return 0;
}

