#include <cuda_runtime.h>
#include <thrust/device_vector.h>
#include <thrust/sort.h>
#include <thrust/execution_policy.h>

struct Point {
    float x, y;
};

struct TreeNode {
    int beginIdx, endIdx;   // Range of points in the array
    int splitDim;           // Splitting dimension (0 for x, 1 for y)
    float threshold;        // Splitting value
    int leftChild, rightChild; // Indices of left and right children
};

__global__ void constructKdTreeKernel(Point* pointData, TreeNode* treeNodes, 
                                      int* workList, int* workCount, int* nextNodeCounter) {
    int threadId = blockIdx.x * blockDim.x + threadIdx.x;
    if (threadId >= *workCount) return;

    int currentNodeId = workList[threadId];
    TreeNode& node = treeNodes[currentNodeId];
    int leftBound = node.beginIdx;
    int rightBound = node.endIdx;
    int dim = node.splitDim;

    // Sort points along the current dimension using thrust
    thrust::sort(thrust::device, pointData + leftBound, pointData + rightBound, 
                 [dim] __device__ (const Point& p1, const Point& p2) {
                     return (dim == 0) ? p1.x < p2.x : p1.y < p2.y;
                 });

    // Determine median index and splitting value
    int midPoint = (leftBound + rightBound) / 2;
    float splitValue = (dim == 0) ? pointData[midPoint].x : pointData[midPoint].y;

    // Allocate space for child nodes atomically
    int leftNodeId = atomicAdd(nextNodeCounter, 1);
    int rightNodeId = atomicAdd(nextNodeCounter, 1);

    // Initialize child nodes
    treeNodes[leftNodeId] = {leftBound, midPoint, 1 - dim, 0, -1, -1};
    treeNodes[rightNodeId] = {midPoint + 1, rightBound, 1 - dim, 0, -1, -1};

    // Update current node with split information
    node.threshold = splitValue;
    node.leftChild = leftNodeId;
    node.rightChild = rightNodeId;

    // Add children to the work list for further processing
    workList[*workCount] = leftNodeId;
    workList[++(*workCount)] = rightNodeId;
}

void createKdTree(Point* d_points, int totalPoints, TreeNode* d_nodes, int maxCapacity) {
    // Setup initial root node
    TreeNode initialNode = {0, totalPoints, 0, 0, -1, -1};
    cudaMemcpy(d_nodes, &initialNode, sizeof(TreeNode), cudaMemcpyHostToDevice);

    // Allocate device memory for stack management
    int* d_workList;
    cudaMalloc(&d_workList, maxCapacity * sizeof(int));
    int* d_workSize;
    cudaMalloc(&d_workSize, sizeof(int));
    int* d_nodeCounter;
    cudaMalloc(&d_nodeCounter, sizeof(int));

    // Initialize stack and counters
    int workSize = 1;
    int nodeCounter = 1;
    cudaMemcpy(d_workList, &initialNode, sizeof(TreeNode), cudaMemcpyHostToDevice);
    cudaMemcpy(d_workSize, &workSize, sizeof(int), cudaMemcpyHostToDevice);
    cudaMemcpy(d_nodeCounter, &nodeCounter, sizeof(int), cudaMemcpyHostToDevice);

    // Kernel launch parameters
    int threadsPerBlock = 256;
    int blocksPerGrid = (maxCapacity + threadsPerBlock - 1) / threadsPerBlock;

    // Iteratively build the kd-tree until all nodes are processed
    while (workSize > 0) {
        constructKdTreeKernel<<<blocksPerGrid, threadsPerBlock>>>(
            d_points, d_nodes, d_workList, d_workSize, d_nodeCounter);
        cudaDeviceSynchronize();

        // Retrieve updated stack size and counter from device
        cudaMemcpy(&workSize, d_workSize, sizeof(int), cudaMemcpyDeviceToHost);
        cudaMemcpy(&nodeCounter, d_nodeCounter, sizeof(int), cudaMemcpyDeviceToHost);
    }

    // Clean up allocated resources
    cudaFree(d_workList);
    cudaFree(d_workSize);
    cudaFree(d_nodeCounter);
}

