// Precompute scaled reciprocals for efficient division by common scale values
std::unordered_map<uint32_t, uint32_t> inverseFactors;

void setupInverseFactors() {
    for (uint32_t scale = 1; scale <= 256; ++scale) {
        inverseFactors[scale] = static_cast<uint32_t>((1u << 16) / scale);
    }
}

void aricoder::encode(symbol* s)
{   
    // Compute interval width and derive step size using precomputed reciprocal
    uint32_t range = chigh - clow + 1;
    cstep = (range * inverseFactors[s->scale]) >> 16;

    // Update the current code interval
    chigh = clow + cstep * s->high_count - 1;
    clow  = clow + cstep * s->low_count;

    // First scaling phase: handle overflow when interval crosses midpoint
    while ((clow >= CODER_LIMIT050) || (chigh < CODER_LIMIT050)) {
        if (chigh < CODER_LIMIT050) { 
            // Both bounds are in lower half — output '0' and propagate carries
            write_zero();
            flush_pending_ones();
        } else { 
            // Both bounds are in upper half — output '1' and clear carry bits
            write_one();
            clow  &= CODER_LIMIT050 - 1;
            chigh &= CODER_LIMIT050 - 1;
            flush_pending_zeros();
        }
        clow  <<= 1;
        chigh = (chigh << 1) | 1;
    }

    // Second scaling phase: handle middle-range underflow risk
    while ((clow >= CODER_LIMIT025) && (chigh < CODER_LIMIT075)) {
        ++nrbits;
        clow  &= CODER_LIMIT025 - 1;
        chigh ^= (CODER_LIMIT025 ^ CODER_LIMIT075);  // equivalent to XOR with both masks
        clow  <<= 1;
        chigh = (chigh << 1) | 1;
    }
}

