// Generate and print the first n Fibonacci numbers
void printFibonacciSequence(int count) {
    if (count <= 0) {
        cout << "Please enter a positive integer." << endl;
        return;
    }

    int first = 0, second = 1, current = 0;

    for (int position = 1; position <= count; ++position) {
        if (position == 1) {
            cout << first;
            if (count > 1) cout << ", ";
            continue;
        }
        if (position == 2) {
            cout << second;
            if (count > 2) cout << ", ";
            continue;
        }
        current = first + second;
        first = second;
        second = current;
        cout << current;
        if (position < count) {
            cout << ", ";
        }
    }
}

