__global__ void simple_copy(float *outdata, const float *indata, int width, int height) {
    __shared__ float tile[TILE_DIM][TILE_DIM];

    int col = blockIdx.x * TILE_DIM + threadIdx.x;
    int row = blockIdx.y * TILE_DIM + threadIdx.y;

    if (col < width && row < height) {
        tile[threadIdx.y][threadIdx.x] = indata[row * width + col];
    }

    __syncthreads();

    if (col < width && row < height) {
        outdata[row * width + col] = tile[threadIdx.y][threadIdx.x];
    }
}

