using json = nlohmann::json;

struct WeatherDataPoint {
    std::string place;
    double tempC;
    double elevation;
    int timeOfDay;
    std::string period;
};

struct ProcessedTemperature {
    std::string location;
    double tempF;
};

double applyElevationCorrection(double baseTemp, double height) {
    return baseTemp - 0.0065 * height;
}

double applyTimeCorrection(double adjustedTemp, int hour) {
    if (hour >= 6 && hour < 12) {
        return adjustedTemp - 1;
    } else if (hour >= 18 && hour < 24) {
        return adjustedTemp - 2;
    }
    return adjustedTemp;
}

double applySeasonalCorrection(double correctedTemp, const std::string& seasonName) {
    if (seasonName == "summer") {
        return correctedTemp + 2;
    } else if (seasonName == "winter") {
        return correctedTemp - 2;
    }
    return correctedTemp;
}

double convertTo Fahrenheit(double celsiusValue) {
    return celsiusValue * 9.0 / 5.0 + 32.0;
}

std::vector<ProcessedTemperature> processWeatherData(const std::vector<WeatherDataPoint>& input) {
    std::vector<ProcessedTemperature> output;
    for (const auto& item : input) {
        double currentTemp = item.tempC;
        double currentElevation = item.elevation;
        int currentTime = item.timeOfDay;
        std::string currentSeason = item.period;

        double tempAfterElevation = applyElevationCorrection(currentTemp, currentElevation);
        double tempAfterTime = applyTimeCorrection(tempAfterElevation, currentTime);
        double finalTempC = applySeasonalCorrection(tempAfterTime, currentSeason);

        double finalTempF = convertTo Fahrenheit(finalTempC);
        output.push_back({item.place, finalTempF});
    }
    return output;
}

void writeJsonOutput(const std::vector<ProcessedTemperature>& data) {
    json j = data;
    std::ofstream outFile("results.json");
    outFile << std::setw(4) << j << std::endl;
}

void writeCsvOutput(const std::vector<ProcessedTemperature>& data) {
    std::ofstream csvFile("results.csv");
    csvFile << "location,fahrenheit\n";
    for (const auto& entry : data) {
        csvFile << entry.location << "," << entry.tempF << "\n";
    }
}

int main() {
    std::vector<WeatherDataPoint> dataset = {
        {"New York", 20, 10, 10, "summer"},
        {"Los Angeles", 25, 50, 18, "winter"}
    };

    std::vector<ProcessedTemperature> processedData = processWeatherData(dataset);
    writeJsonOutput(processedData);
    writeCsvOutput(processedData);

    return 0;
}

