#include <iostream>
#include <cmath>
#include <Eigen/Dense>
#include <boost/math/quadrature/trapezoidal.hpp>
#include <boost/math/tools/minima.hpp>

// Define the integrand function
double integrand(double t) {
    return t * t; // Example: f(t) = t^2
}

// Numerical integration using trapezoidal rule with high precision
double compute_integral(double lower, double upper) {
    const double tolerance = 1e-8;
    return boost::math::quadrature::trapezoidal(integrand, lower, upper, tolerance);
}

// Objective function to minimize: absolute difference between integral and target distance
double deviation_from_target(double upper_limit, double target_distance) {
    double computed = compute_integral(0.0, upper_limit);
    return std::abs(computed - target_distance);
}

// Find the value of x that minimizes the deviation from target_distance
double locate_optimal_upper_bound(double start_guess, double target_distance) {
    auto objective_func = [target_distance](double x) { return deviation_from_target(x, target_distance); };

    // Use Brent's method for minimization within [0, 10] with max 50 iterations
    auto result = boost::math::tools::brent_find_minima(objective_func, 0.0, 10.0, 50);
    return result.first;
}

int main() {
    // Ellipse parameters
    double semi_minor_axis = 2.23;
    double semi_major_axis = 3.05;

    // Given arc length (or encoded distance)
    double specified_distance = 2.53141952655;

    // Find the optimal upper bound for integration
    double optimal_x = locate_optimal_upper_bound(1.0, specified_distance);
    std::cout << "optimal_x: " << optimal_x << std::endl;

    // Compute angle using geometric relationship for ellipse
    double computed_angle = 90.0 - (180.0 / M_PI) * 
                            std::atan((std::tan(optimal_x) * semi_minor_axis) / semi_major_axis);
    std::cout << "computed_angle: " << computed_angle << std::endl;

    return 0;
}

#include <cstdio>

// Launches the AddOne kernel with appropriate grid and block dimensions
void AddOneKernelLauncher(const int* in, const int N, int* out) {
    int threadsPerBlock = 256;
    int blocksPerGrid = (N + threadsPerBlock - 1) / threadsPerBlock;

    // Launch the CUDA kernel
    AddOneKernel<<<blocksPerGrid, threadsPerBlock>>>(in, N, out);

    // Synchronize and check for errors
    cudaError_t err = cudaDeviceSynchronize();
    if (err != cudaSuccess) {
        std::fprintf(stderr, "kernel launch failed with error \"%s\".\n", cudaGetErrorString(err));
    }
}

