// Convert Java String to C++ std::string using GB2312 encoding
std::string javaStringToCppString(JNIEnv* env, jstring javaStr) {
    char* resultBuffer = nullptr;

    // Get String class reference
    jclass stringClass = env->FindClass("java/lang/String");
    if (stringClass == nullptr) {
        __android_log_print(ANDROID_LOG_ERROR, "jni", "Failed to find String class");
        return std::string();
    }

    // Create encoding string for GB2312
    jstring encodingName = env->NewStringUTF("GB2312");
    if (encodingName == nullptr) {
        __android_log_print(ANDROID_LOG_ERROR, "jni", "Failed to create encoding string");
        return std::string();
    }

    // Get method ID for getBytes(String charsetName)
    jmethodID getBytesMethod = env->GetMethodID(stringClass, "getBytes",
            "(Ljava/lang/String;)[B");
    if (getBytesMethod == nullptr) {
        __android_log_print(ANDROID_LOG_ERROR, "jni", "Failed to get getBytes method");
        env->DeleteLocalRef(encodingName);
        return std::string();
    }

    // Call getBytes to get byte array
    jbyteArray byteArr = (jbyteArray) env->CallObjectMethod(javaStr, getBytesMethod, encodingName);
    if (byteArr == nullptr) {
        __android_log_print(ANDROID_LOG_ERROR, "jni", "Failed to get bytes from string");
        env->DeleteLocalRef(encodingName);
        return std::string();
    }

    // Get length of byte array
    jsize byteCount = env->GetArrayLength(byteArr);
    if (byteCount <= 0) {
        env->DeleteLocalRef(byteArr);
        env->DeleteLocalRef(encodingName);
        return std::string();
    }

    // Get pointer to byte array elements
    jbyte* bytePtr = env->GetByteArrayElements(byteArr, JNI_FALSE);
    if (bytePtr == nullptr) {
        __android_log_print(ANDROID_LOG_ERROR, "jni", "Failed to get byte array elements");
        env->DeleteLocalRef(byteArr);
        env->DeleteLocalRef(encodingName);
        return std::string();
    }

    // Allocate memory for result string (+1 for null terminator)
    resultBuffer = static_cast<char*>(malloc(byteCount + 1));
    if (resultBuffer == nullptr) {
        __android_log_print(ANDROID_LOG_ERROR, "jni", "Memory allocation failed for string conversion");
        env->ReleaseByteArrayElements(byteArr, bytePtr, JNI_ABORT);
        env->DeleteLocalRef(byteArr);
        env->DeleteLocalRef(encodingName);
        return std::string();
    }

    // Copy bytes to buffer and null-terminate
    memcpy(resultBuffer, bytePtr, byteCount);
    resultBuffer[byteCount] = '\0';

    // Clean up JNI references
    env->ReleaseByteArrayElements(byteArr, bytePtr, JNI_ABORT);
    env->DeleteLocalRef(byteArr);
    env->DeleteLocalRef(encodingName);

    // Create and return std::string
    std::string cppString(resultBuffer);
    free(resultBuffer);

    return cppString;
}

