#include <cmath>

struct Vec3 {
    float x, y, z;

    // Vector addition
    Vec3 add(const Vec3& rhs) const {
        return {x + rhs.x, y + rhs.y, z + rhs.z};
    }

    // Vector subtraction
    Vec3 subtract(const Vec3& rhs) const {
        return {x - rhs.x, y - rhs.y, z - rhs.z};
    }

    // Scalar multiplication
    Vec3 scale(float factor) const {
        return {x * factor, y * factor, z * factor};
    }

    // Scalar division
    Vec3 divide(float divisor) const {
        return {x / divisor, y / divisor, z / divisor};
    }

    // Dot product
    float inner(const Vec3& rhs) const {
        return x * rhs.x + y * rhs.y + z * rhs.z;
    }

    // Cross product
    Vec3 perpendicular(const Vec3& rhs) const {
        return {
            y * rhs.z - z * rhs.y,
            z * rhs.x - x * rhs.z,
            x * rhs.y - y * rhs.x
        };
    }

    // Magnitude (length)
    float magnitude() const {
        return std::sqrt(inner(*this));
    }

    // Unit vector
    Vec3 unit() const {
        return divide(magnitude());
    }
};

