// Compute the squared distance from point (2, -3) 
double objectiveFunction(const std::vector<double>& parameters) {
    double x = parameters[0];
    double y = parameters[1];
    double dx = x - 2.0;
    double dy = y + 3.0;
    return dx * dx + dy * dy;  // Equivalent to minimizing (x-2)^2 + (y+3)^2
}

extern "C" {
    #include <cuda_runtime.h>

    // CUDA kernel to perform element-wise addition of two arrays
    __global__ void vectorAddKernel(float *result, const float *inputA, const float *inputB, int size) {
        int index = threadIdx.x;
        if (index < size) {
            result[index] = inputA[index] + inputB[index];
        }
    }

    // Host function to manage memory and launch the CUDA kernel for vector addition
    void vectorAdd(float *hostResult, const float *hostInputA, const float *hostInputB, int count) {
        float *deviceA, *deviceB, *deviceResult;

        // Allocate device memory for input and output arrays
        cudaMalloc(&deviceA, count * sizeof(float));
        cudaMalloc(&deviceB, count * sizeof(float));
        cudaMalloc(&deviceResult, count * sizeof(float));

        // Copy input data from host to device
        cudaMemcpy(deviceA, hostInputA, count * sizeof(float), cudaMemcpyHostToDevice);
        cudaMemcpy(deviceB, hostInputB, count * sizeof(float), cudaMemcpyHostToDevice);

        // Launch the kernel with one block containing 'count' threads
        vectorAddKernel<<<1, count>>>(deviceResult, deviceA, deviceB, count);

        // Copy result back from device to host
        cudaMemcpy(hostResult, deviceResult, count * sizeof(float), cudaMemcpyDeviceToHost);

        // Free allocated device memory
        cudaFree(deviceA);
        cudaFree(deviceB);
        cudaFree(deviceResult);
    }
}

