void WebrtcTransport::onShutdown(RTCError reason) {
    RTC_LOG(LS_INFO) << "WebRTC transport shutdown with reason: "
                     << reason.message();

    // Terminate all connections to the ICE subsystem.
    if (ice_transport_) {
        ice_transport_->Stop();
        ice_transport_->SetIceTransportState(webrtc::IceTransportState::kStopped);
    }
    if (bundle_transport_) {
        bundle_transport_->Stop();
    }
    if (rtp_transport_) {
        rtp_transport_->SetRtpState(webrtc::MediaTransportState::kClosed);
        rtp_transport_->StopSend();
        rtp_transport_->StopReceive();
    }
    if (rtcp_transport_) {
        rtcp_transport_->SetRtcpState(webrtc::MediaTransportState::kClosed);
        rtcp_transport_->StopSend();
        rtcp_transport_->StopReceive();
    }

    // Reset internal counters and metrics
    rtp_packets_count_ = 0u;
    rtcp_packets_count_ = 0u;
    rtp_bytes_count_ = 0u;
    rtcp_bytes_count_ = 0u;

    // Notify listeners about the shutdown.
    event_.Set();
}

