// Helper function to read file contents into a scalar string tensor
static Status LoadFileIntoTensor(Env* pEnv, const string& sPath, Tensor* pOutput) {
    uint64 nSize = 0;
    TF_RETURN_IF_ERROR(pEnv->GetFileSize(sPath, &nSize));

    string sContent;
    sContent.resize(nSize);

    std::unique_ptr<RandomAccessFile> pFile;
    TF_RETURN_IF_ERROR(pEnv->NewRandomAccessFile(sPath, &pFile));

    StringPiece pData;
    TF_RETURN_IF_ERROR(pFile->Read(0, nSize, &pData, &sContent[0]));

    pOutput->scalar<string>()() = sContent;
    return Status::OK();
}

// Process image: decode PNG, resize, normalize
Status LoadAndPreprocessImage(const string& sFilename, int nTargetWidth, int nTargetHeight,
                              float fNormalizationMean, float fNormalizationScale,
                              std::vector<Tensor>* pResult) {
    Tensor tRawInput(DT_STRING, TensorShape());
    TF_RETURN_IF_ERROR(LoadFileIntoTensor(Env::Default(), sFilename, &tRawInput));

    auto rootScope = Scope::NewRootScope();
    auto inputNode = ops::Placeholder(rootScope.WithOpName("image_input"), DT_STRING);
    std::vector<std::pair<string, Tensor>> feedDict = { {"image_input", tRawInput} };

    // Decode PNG with 3 channels
    auto decodedImg = ops::DecodePng(rootScope.WithOpName("png_decoder"), inputNode,
                                     ops::DecodePng::Channels(3));

    // Convert to float
    auto floatImage = ops::Cast(rootScope.WithOpName("to_float"), decodedImg, DT_FLOAT);

    // Add batch dimension
    auto batchedImage = ops::ExpandDims(rootScope, floatImage, 0);

    // Resize to target dimensions
    auto resizedImage = ops::ResizeBilinear(rootScope, batchedImage,
                                            ops::Const(rootScope.WithOpName("size"),
                                                       {nTargetHeight, nTargetWidth}));

    // Normalize: (pixel - mean) / scale
    auto normalized = ops::Div(rootScope.WithOpName("normalize"),
                               ops::Sub(rootScope, resizedImage, ops::Const(rootScope, fNormalizationMean)),
                               ops::Const(rootScope, fNormalizationScale));

    GraphDef graph;
    TF_RETURN_IF_ERROR(rootScope.ToGraphDef(&graph));

    std::unique_ptr<Session> session(NewSession(SessionOptions()));
    TF_RETURN_IF_ERROR(session->Create(graph));
    TF_RETURN_IF_ERROR(session->Run({feedDict}, {"normalize"}, {}, pResult));
    return Status::OK();
}

int main(int argc, char* argv[]) {
    tensorflow::port::InitMain(argv[0], &argc, &argv);

    // Load model graph
    GraphDef graphDef;
    Status status = ReadBinaryProto(Env::Default(), "models/graph.pb", &graphDef);
    if (!status.ok()) {
        std::cerr << "Failed to load graph: " << status.ToString() << std::endl;
        return -1;
    }
    std::cout << "Graph loaded successfully\n";

    // Preprocess input image
    std::vector<Tensor> inputBatch;
    status = LoadAndPreprocessImage("temp.png", 224, 224, 127.5f, 255.0f, &inputBatch);
    if (!status.ok()) {
        std::cerr << "Image preprocessing failed: " << status.ToString() << std::endl;
        return -1;
    }
    std::cout << "Image preprocessed\n";

