    status = inferenceSession->Create(graphDef);
    if (!status.ok()) {
        std::cerr << "Session creation failed: " << status.ToString() << std::endl;
        return -1;
    }

    std::vector<Tensor> predictions;
    status = inferenceSession->Run(
