template<std::size_t NumBits>
struct integer;

// Simplified helper using direct implementation instead of template specialization
template<std::size_t NumBits>
struct adder {
    static inline void perform(integer<NumBits> &a, const integer<NumBits> &b) {
        uint64_t carry_flag = 0;
        std::size_t word_count = integer<NumBits>::numwords;

        for (std::size_t index = 0; index < word_count; ++index) {
            uint64_t operand_a = a[index];
            uint64_t operand_b = b[index];
            uint64_t temp_sum = operand_a + operand_b + carry_flag;

            a[index] = temp_sum;
            // Detect carry: if sum wrapped around (less than either operand after adding)
            carry_flag = (temp_sum < operand_a) || (temp_sum == operand_a && carry_flag != 0);
        }
    }
};

template<std::size_t NumBits>
struct integer {
    typedef uint64_t value_type;
    static const std::size_t numbits = NumBits;
    static const std::size_t numwords = (NumBits + std::numeric_limits<value_type>::digits - 1) / std::numeric_limits<value_type>::digits;
    using container = std::array<uint64_t, numwords>;

    typedef typename container::iterator iterator;

    iterator begin() { return data_.begin(); }
    iterator end() { return data_.end(); }

    explicit integer(value_type num = value_type()) {
        assert(-1l >> 1 == -1l);
        std::fill(begin(), end(), value_type());
        data_[0] = num;
    }

    inline value_type& operator[](std::size_t idx) { return data_[idx]; }
    inline const value_type& operator[](std::size_t idx) const { return data_[idx]; }

    integer& operator+=(const integer& src) {
        adder<numbits>::perform(*this, src);
        return *this;
    }

    integer& operator~() {
        std::transform(begin(), end(), begin(), std::bit_not<value_type>());
        return *this;
    }

    void print_raw(std::ostream& os) const {
        os << "(";
        for (std::size_t pos = numwords - 1; pos > 0; --pos)
            os << data_[pos] << " ";
        os << data_[0];
        os << ")";
    }

    void print(std::ostream& os) const {
        assert(false && " TO DO ! \n");
    }

private:
    container data_;
};

template <std::size_t NumBits>
std::ostream& operator<< (std::ostream& os, integer<NumBits> const& val) {
    if (os.flags() & std::ios_base::hex)
        val.print_raw(os);
    else
        val.print(os);
    return os;
}

int main(int argc, const char * argv[]) {
    integer<256> x; // 0
    integer<256> y(1);

    ~x; // all the 0 become 1

    std::cout << " x: " << std::hex << x << std::endl;
    std::cout << " ref: (ffffffffffffffff ffffffffffffffff ffffffffffffffff ffffffffffffffff) " << std::endl;

    x += y; // should propagate the carry

    std::cout << " x+=y: " << x << std::endl;
    std::cout << " ref: (0 0 0 0) " << std::endl; // it works but ...

    return 0;
}

