using namespace std;

// Function to measure average time and total sum over multiple runs
pair<double, double> benchmark_reduction(int array_size, int iterations = 30) {
    double cumulative_time = 0.0;
    double cumulative_result = 0.0;

    for (int run = 0; run < iterations; ++run) {
        // Generate random 1D tensor with values in [0, 1)
        xt::xtensor<double, 1> data = xt::random::rand({array_size}, 0.0, 1.0);

        // Start timing
        clock_t begin = clock();

        // Perform parallel reduction using immediate evaluation
        double result = xt::sum(data, xt::evaluation_strategy::immediate, xt::parallelExecution())();

        // End timing
        clock_t end = clock();

        // Accumulate results
        cumulative_result += result;
        cumulative_time += static_cast<double>(end - begin);
    }

    // Return average time per run and total sum across all runs
    return make_pair(cumulative_time / CLOCKS_PER_SEC / iterations, cumulative_result);
}

int main(int argc, char *argv[]) {
    // Benchmark for sizes 10^5, 10^6, 10^7
    for (int exp = 5; exp <= 7; ++exp) {
        int n = static_cast<int>(pow(10, exp));
        auto stats = benchmark_reduction(n);
        cout << "size: " << n << "\t" << stats.first << " sec\t" << stats.second << endl;
    }
    return 0;
}

#include <iostream>

// Definition for singly-linked list.
struct ListNode {
    int val;
    ListNode *next;
    ListNode(int x) : val(x), next(nullptr) {}
};

bool hasCycle(ListNode *head) {
    // Handle edge cases: empty list or single node without cycle
    if (!head || !head->next) {
        return false;
    }

    // Use two pointers moving at different speeds
    ListNode *slow = head;
    ListNode *fast = head;

    while (fast && fast->next) {
        slow = slow->next;          // Advance by one node
        fast = fast->next->next;    // Advance by two nodes

        // If they meet, there's a cycle
        if (slow == fast) {
            return true;
        }
    }

    // Fast pointer reached the end, so no cycle exists
    return false;
}

int main() {
    // Create test linked list with a cycle
    ListNode *node1 = new ListNode(1);
    ListNode *node2 = new ListNode(2);
    ListNode *node3 = new ListNode(3);
    ListNode *node4 = new ListNode(4);

    node1->next = node2;
    node2->next = node3;
    node3->next = node4;
    node4->next = node2;  // Cycle back to node2

    // Check for cycle and output result
    if (hasCycle(node1)) {
        std::cout << "Cycle detected." << std::endl;
    } else {
        std::cout << "No cycle detected." << std::endl;
    }

    // Free allocated memory
    delete node1;
    delete node2;
    delete node3;
