// Disassemble binary code using Capstone engine
void analyzeInstructions(uint8_t *data, size_t length, uint64_t baseAddr) {
    csh disassembler;
    cs_insn *instructions;
    size_t instructionCount;
    std::string result;

    if (cs_open(CS_ARCH_X86, CS_MODE_64, &disassembler) == CS_ERR_OK) {
        instructionCount = cs_disasm(disassembler, data, length, baseAddr, 0, &instructions);
        std::cout << "\nINSTRUCTION_COUNT:" << instructionCount << std::endl;

        if (instructionCount > 0) {
            for (size_t k = 0; k < instructionCount; ++k) {
                char line[512];
                snprintf(line, sizeof(line), "0x%" PRIx64 ":\t%s\t\t%s\n", 
                         instructions[k].address, 
                         instructions[k].mnemonic, 
                         instructions[k].op_str);
                result += line;
            }
            cs_free(instructions, instructionCount);
        } else {
            result = "DISASSEMBLY_ERROR: Unable to decode provided bytes.\n";
        }
        cs_close(&disassembler);
        std::cout << result;
    }
}

// Extract __TEXT.__text section from Mach-O binary
bool getExecutableSection(const char *binaryPath, uint8_t **bufferOut, uint64_t *lengthOut, uint64_t *entryPointOut) {
    std::ifstream inputStream(binaryPath, std::ios::binary | std::ios::ate);
    if (!inputStream) {
        std::cerr << "OPEN_FAILED: Cannot access file '" << binaryPath << "'" << std::endl;
        return false;
    }

    std::streamsize fileSize = inputStream.tellg();
    inputStream.seekg(0, std::ios::beg);

    uint8_t *fileContent = new uint8_t[fileSize];
    if (!inputStream.read((char*)fileContent, fileSize)) {
        std::cerr << "READ_FAILED: Could not read entire file" << std::endl;
        delete[] fileContent;
        return false;
    }
    inputStream.close();

    mach_header_64 *header = reinterpret_cast<mach_header_64*>(fileContent);
    if (header->magic != MH_MAGIC_64) {
        std::cerr << "FORMAT_ERROR: File is not a 64-bit Mach-O image" << std::endl;
        delete[] fileContent;
        return false;
    }

    load_command *cmd = reinterpret_cast<load_command*>(fileContent + sizeof(mach_header_64));
    for (uint32_t i = 0; i < header->ncmds; ++i) {
        if (cmd->cmd == LC_SEGMENT_64) {
            segment_command_64 *seg = reinterpret_cast<segment_command_64*>(cmd);
            if (std::strcmp(seg->segname, "__TEXT") == 0) {
                for (uint32_t sectionIndex = 0; sectionIndex < seg->nsects; ++sectionIndex) {
                    section_64 *sect = reinterpret_cast<section_64*>(
                        reinterpret_cast<char*>(seg) + sizeof(segment_command_64) + 
                        sectionIndex * sizeof(section_64)
                    );
                    if (std::strcmp(sect->sectname, "__text") == 0) {
                        *bufferOut = fileContent + sect->offset;
                        *lengthOut = sect->size;
                        *entryPointOut = sect->addr;
                        return true;
                    }
                }
            }
        }
        cmd = reinterpret_cast<load_command*>(reinterpret_cast<char*>(cmd) + cmd->cmdsize);
    }

    delete[] fileContent;
    return false;
}

int main() {
    uint8_t *codeBuffer = nullptr;
    uint64_t codeSize = 0, entryAddress = 0;

    if (getExecutableSection("path/to/your/dylib", &codeBuffer, &codeSize, &entryAddress)) {
        analyzeInstructions(codeBuffer, codeSize, entryAddress);
    } else {
        std::cerr << "EXTRACTION_FAILED: Could not retrieve executable code from binary." << std::endl;
    }

    return 0;
}

