// Convert string to lowercase for case-insensitive comparison
std::string convertToLower(const std::string& inputText) {
    std::string result = inputText;
    for (size_t i = 0; i < result.length(); ++i) {
        result[i] = std::tolower(static_cast<unsigned char>(result[i]));
    }
    return result;
}

// Extract words from a sentence by splitting on whitespace
std::vector<std::string> extractWords(const std::string& text) {
    std::istringstream stream(text);
    std::vector<std::string> tokens;
    std::string token;
    while (stream >> token) {
        tokens.push_back(token);
    }
    return tokens;
}

// Check if a word exists in the dictionary (case-insensitive)
bool validateWord(const std::string& word, const std::unordered_set<std::string>& lexicon) {
    return lexicon.find(convertToLower(word)) != lexicon.end();
}

// Attempt to correct a single word — currently returns original if not found
std::string fixWord(const std::string& word, const std::unordered_set<std::string>& lexicon) {
    if (validateWord(word, lexicon)) {
        return word;
    }
    // Placeholder: no correction applied yet
    return word;
}

// Process entire sentence: tokenize, correct each word, reassemble
std::string fixSentence(const std::string& phrase, const std::unordered_set<std::string>& lexicon) {
    std::vector<std::string> segments = extractWords(phrase);
    std::string fixedPhrase;

    for (size_t i = 0; i < segments.size(); ++i) {
        fixedPhrase += fixWord(segments[i], lexicon);
        if (i < segments.size() - 1) {
            fixedPhrase += " ";
        }
    }

    return fixedPhrase;
}

