#include <iostream>
#include <unordered_map>

template <typename T>
class BidirectionalList {
public:
    struct Element {
        T value;
        Element* backward;
        Element* forward;
        Element(T val) : value(val), backward(nullptr), forward(nullptr) {}
    };

    BidirectionalList() : first(nullptr), last(nullptr) {}

    ~BidirectionalList() {
        while (first) {
            Element* temp = first;
            first = first->forward;
            delete temp;
        }
    }

    void add(T value) {
        Element* newElement = new Element(value);
        if (!first) {
            first = last = newElement;
        } else {
            last->forward = newElement;
            newElement->backward = last;
            last = newElement;
        }
        index[value] = newElement;
    }

    Element* find(T value) {
        auto it = index.find(value);
        if (it != index.end()) {
            return it->second;
        }
        return nullptr;
    }

    void erase(T value) {
        auto it = index.find(value);
        if (it != index.end()) {
            Element* element = it->second;
            if (element->backward) element->backward->forward = element->forward;
            if (element->forward) element->forward->backward = element->backward;
            if (element == first) first = element->forward;
            if (element == last) last = element->backward;
            delete element;
            index.erase(it);
        }
    }

private:
    Element* first;
    Element* last;
    std::unordered_map<T, Element*> index;
};

int main() {
    BidirectionalList<int> sequence;
    sequence.add(10);
    sequence.add(20);
    sequence.add(30);

    BidirectionalList<int>::Element* found = sequence.find(20);
    if (found) {
        std::cout << "Found: " << found->value << std::endl;
    } else {
        std::cout << "Not found" << std::endl;
    }

    sequence.erase(20);
    found = sequence.find(20);
    if (found) {
        std::cout << "Found: " << found->value << std::endl;
    } else {
        std::cout << "Not found" << std::endl;
    }

    return 0;
}

#include <sys/mman.h>
#include <unistd.h>
#include <cstdio>
#include <cerrno>

// Allocate memory with read, write, and execute permissions for dynamic code execution
void* allocate_executable_code_space(size_t bytes) {
    void* address = mmap(nullptr, bytes,
                         PROT_READ | PROT_WRITE | PROT_EXEC,
                         MAP_PRIVATE | MAP_ANONYMOUS,
                         -1, 0);

    if (address == MAP_FAILED) {
        std::fprintf(stderr, "Failed to allocate executable memory: %s\n", strerror(errno));
        std::exit(EXIT_FAILURE);
    }

    return address;
}

// Deallocate previously allocated executable memory region
void release_executable_memory(void* address, size_t bytes) {
    if (munmap(address, bytes) != 0) {
        std::fprintf(stderr, "Failed to release executable memory: %s\n", strerror(errno));
        std::exit(EXIT_FAILURE);
    }
}

