#include <iostream>
#include <vector>
#include <string>
#include <algorithm>

// Helper function to compare substrings starting at positions i and j with length p
bool compareSubstr(const std::string& s, int pos1, int pos2, int len) {
    if (pos1 + len > static_cast<int>(s.size())) return false;
    if (pos2 + len > static_cast<int>(s.size())) return true;
    return s[pos1 + len] < s[pos2 + len];
}

// Construct suffix array using doubling algorithm
std::vector<int> createSuffixArray(const std::string& input) {
    int n = input.length();
    std::vector<int> sa(n);
    for (int idx = 0; idx < n; ++idx) sa[idx] = idx;

    std::vector<int> rnk(n);
    for (int idx = 0; idx < n; ++idx) rnk[idx] = static_cast<int>(input[idx]);

    for (int step = 1; step < n; step *= 2) {
        std::sort(sa.begin(), sa.end(), [&](int a, int b) {
            if (rnk[a] != rnk[b]) return rnk[a] < rnk[b];
            return compareSubstr(input, a, b, step);
        });

        std::vector<int> newRnk(n);
        newRnk[sa[0]] = 0;
        for (int idx = 1; idx < n; ++idx) {
            bool diff = compareSubstr(input, sa[idx - 1], sa[idx], step) || 
                        (rnk[sa[idx - 1]] != rnk[sa[idx]]);
            newRnk[sa[idx]] = newRnk[sa[idx - 1]] + (diff ? 1 : 0);
        }
        rnk = newRnk;
    }

    return sa;
}

// Build LCP array using Kasai's algorithm
std::vector<int> constructLCP(const std::string& text, const std::vector<int>& sa) {
    int n = text.size();
    std::vector<int> rank(n);
    for (int i = 0; i < n; ++i) rank[sa[i]] = i;

    std::vector<int> lcp(n, 0);
    for (int i = 0, height = 0; i < n; ++i) {
        if (rank[i] == n - 1) {
            height = 0;
            continue;
        }
        int j = sa[rank[i] + 1];
        while (i + height < n && j + height < n && text[i + height] == text[j + height]) {
            ++height;
        }
        lcp[rank[i]] = height;
        height = std::max(height - 1, 0);
    }

    return lcp;
}

// Find longest common substring among multiple strings
std::string findLongestSharedSubstring(const std::vector<std::string>& words) {
    std::string combined;
    for (const auto& word : words) {
        combined += word + "#";
    }

    std::vector<int> suffixArray = createSuffixArray(combined);
    std::vector<int> lcp = constructLCP(combined, suffixArray);

    int maxLength = 0;
    int startIndex = 0;
    for (int i = 1; i < static_cast<int>(lcp.size()); ++i) {
        if (lcp[i] > maxLength) {
            maxLength = lcp[i];
            startIndex = i;
        }
    }

    if (maxLength == 0) return "";

    return combined.substr(suffixArray[startIndex], maxLength);
}

int main() {
    std::vector<std::string> inputWords = {"flower", "flow", "flight"};
    std::string commonPart = findLongestSharedSubstring(inputWords);

    if (commonPart.empty()) {
        std::cout << "No shared substring detected." << std::endl;
    } else {
        std::cout << "Longest shared substring: " << commonPart << std::endl;
    }

    return 0;
}

