// Calculate the number of digits in an integer (handles negatives and zero)
int digitCount(int value) {
    if (value == 0) return 1;
    int absValue = (value < 0) ? -value : value;
    return static_cast<int>(log10(absValue)) + 1;
}

// Custom comparison for sorting by digit count, then by numeric value
bool sortByDigitCount(int first, int second) {
    int countFirst = digitCount(first);
    int countSecond = digitCount(second);

    if (countFirst != countSecond) {
        return countFirst < countSecond;
    }
    return first < second;
}

// Sort a vector of integers by their digit lengths
vector<int> orderByLength(vector<int> input) {
    sort(input.begin(), input.end(), sortByDigitCount);
    return input;
}

