#include <cstdint>
#include <cstring>

// Convert 64-bit value to network byte order (big-endian)
uint64_t htonll(uint64_t value) {
    // Determine endianness at runtime using a compile-time constant check
    static const bool isLittleEndian = []() {
        const uint32_t testValue = 1;
        return *(reinterpret_cast<const uint8_t*>(&testValue)) == 1;
    }();

    if (isLittleEndian) {
        // Swap the 32-bit halves and convert each half individually
        uint32_t highPart = static_cast<uint32_t>(value >> 32);
        uint32_t lowPart = static_cast<uint32_t>(value & 0xFFFFFFFF);
        uint32_t swappedHigh = htonl(lowPart);
        uint32_t swappedLow = htonl(highPart);
        return (static_cast<uint64_t>(swappedHigh) << 32) | swappedLow;
    }
    return value;
}

// Convert 64-bit value from network byte order (big-endian)
uint64_t ntohll(uint64_t value) {
    // Reuse the same endianness detection logic
    static const bool isLittleEndian = []() {
        const uint32_t testValue = 1;
        return *(reinterpret_cast<const uint8_t*>(&testValue)) == 1;
    }();

    if (isLittleEndian) {
        // Perform the reverse operation: swap halves and convert each
        uint32_t highPart = static_cast<uint32_t>(value >> 32);
        uint32_t lowPart = static_cast<uint32_t>(value & 0xFFFFFFFF);
        uint32_t swappedHigh = ntohl(lowPart);
        uint32_t swappedLow = ntohl(highPart);
        return (static_cast<uint64_t>(swappedHigh) << 32) | swappedLow;
    }
    return value;
}

#include <iostream>
#include <cmath>
#include <array>
#include <vector>

// Vector subtraction for 3D double arrays
std::array<double, 3> subtract(const std::array<double, 3>& vecA, const std::array<double, 3>& vecB) {
    return {vecA[0] - vecB[0], vecA[1] - vecB[1], vecA[2] - vecB[2]};
}

// Dot product of two 3D vectors
double dotProduct(const std::array<double, 3>& vecA, const std::array<double, 3>& vecB) {
    return vecA[0] * vecB[0] + vecA[1] * vecB[1] + vecA[2] * vecB[2];
}

// Magnitude (length) of a 3D vector
double vectorMagnitude(const std::array<double, 3>& vec) {
    return std::sqrt(dotProduct(vec, vec));
}

// Normalize a 3D vector to unit length
std::array<double, 3> unitVector(const std::array<double, 3>& vec) {
    double mag = vectorMagnitude(vec);
    return {vec[0] / mag, vec[1] / mag, vec[2] / mag};
}

// Cube representation: center position and half-extent
class BoxShape {
public:
    BoxShape(const std::array<double, 3>& pos, const double halfSize)
        : _center(pos), _half(halfSize) {}

    std::array<double, 3> getCenter() const { return _center; }
    double lowerBound(int axis) const { return _center[axis] - _half; }
    double upperBound(int axis) const { return _center[axis] + _half; }
    double getHalfSize() const { return _half; }

private:
    std::array<double, 3> _center;
    double _half;
};

// Right circular cone: apex point, base center point, and half-angle
class ConicalShape {
public:
    ConicalShape(const std::array<double, 3>& apex, const std::array<double, 3>& baseCenter, const double angleRad)
        : _apex(apex), _base(baseCenter), _angle(angleRad) {}

    std::array<double, 3> getApex() const { return _apex; }
    std::array<double, 3> getBaseCenter() const { return _base; }
    double getAngle() const { return _angle; }
    double getLength() const { return vectorMagnitude(subtract(_apex, _base)); }
    double getRadius() const { return std::tan(_angle) * getLength(); }

private:
    std::array<double, 3> _apex;
    std::array<double, 3> _base;
    double _angle;
};

// Determine if a point lies within the conical volume
bool pointInCone(const ConicalShape& cone, const std::array<double, 3>& testPoint) {
    std::array<double, 3> apexPos = cone.getApex();
    std::array<double, 3> basePos = cone.getBaseCenter();
    std::array<double, 3> axisDir = unitVector(subtract(basePos, apexPos));
    double coneLen = cone.getLength();
    double coneRad = cone.getRadius();

    // Project point onto cone axis
    std::array<double, 3> offset = subtract(testPoint, apexPos);
    double projection = dotProduct(offset, axisDir);

    // Check if projection is within cone height bounds
    if (projection < 0.0 || projection > coneLen) return false;

    // Compute closest point on axis to test point
    std::array<double, 3> axisPoint = {apexPos[0] + projection * axisDir[0],
                                       apexPos[1] + projection * axisDir[1],
                                       apexPos[2] + projection * axisDir[2]};

    // Calculate perpendicular distance from point to axis
    double radialDist = vectorMagnitude(subtract(testPoint, axisPoint));

    // Compare with cone radius at that height
    double localRadius = coneRad * projection / coneLen;
    return radialDist <= localRadius;
}

// Test intersection between box and cone using sampling approach
bool shapesIntersect(const BoxShape& box, const ConicalShape& cone) {
    // Sample all 8 corners of the box
    for (int ix = 0; ix < 2; ++ix) {
        for (int iy = 0; iy < 2; ++iy) {
            for (int iz = 0; iz < 2; ++iz) {
                std::array<double, 3> corner = {
                    box.lowerBound(0) + ix * 2 * box.getHalfSize(),
                    box.lowerBound(1) + iy * 2 * box.getHalfSize(),
                    box.lowerBound(2) + iz * 2 * box.getHalfSize()
                };
                if (pointInCone(cone, corner)) return true;
            }
        }
    }

    // Sample edge midpoints
    for (int ix = 0; ix < 2; ++ix) {
        for (int iy = 0; iy < 2; ++iy) {
            for (int iz = 0; iz < 2; ++iz) {
                std::array<double, 3> corner = {
                    box.lowerBound(0) + ix * 2 * box.getHalfSize(),
                    box.lowerBound(1) + iy * 2 * box.getHalfSize(),
                    box.lowerBound(2) + iz * 2 * box.getHalfSize()
                };

                for (int dim = 0; dim < 3; ++dim) {
                    std::array<double, 3> neighbor = corner;
                    neighbor[dim] += (ix == 0 ? 2 * box.getHalfSize() : -2 * box.getHalfSize());

                    // Midpoint of edge
                    std::array<double, 3> midpoint = {
                        (corner[0] + neighbor[0]) / 2.0,
                        (corner[1] + neighbor[1]) / 2.0,
                        (corner[2] + neighbor[2]) / 2.0
                    };

                    if (pointInCone(cone, neighbor) || pointInCone(cone, midpoint)) 
                        return true;
                }
            }
        }
    }

    // Sample face centers
    for (int ix = 0; ix < 2; ++ix) {
        for (int iy = 0; iy < 2; ++iy) {
            for (int iz = 0; iz < 2; ++iz) {
                std::array<double, 3> corner = {
                    box.lowerBound(0) + ix * 2 * box.getHalfSize(),
                    box.lowerBound(1) + iy * 2 * box.getHalfSize(),
                    box.lowerBound(2) + iz * 2 * box.getHalfSize()
                };

                for (int dim = 0; dim < 3; ++dim) {
                    int nextDim = (dim + 1) % 3;
                    std::array<double, 3> edge1 = corner;
                    edge1[dim] += (ix == 0 ? 2 * box.getHalfSize() : -2 * box.getHalfSize());
                    std::array<double, 3> edge2 = corner;
                    edge2[nextDim] += (iy == 0 ? 2 * box.getHalfSize() : -2 * box.getHalfSize());
                    std::array<double, 3> opposite = edge1;
                    opposite[nextDim] += (iy == 0 ? 2 * box.getHalfSize() : -2 * box.getHalfSize());

                    // Center of face
                    std::array<double, 3> faceCenter = {
                        (corner[0] + edge1[0] + edge2[0] + opposite[0]) / 4.0,
                        (corner[1] + edge1[1] + edge2[1] + opposite[1]) / 4.0,
                        (corner[2] + edge1[2] + edge2[2] + opposite[2]) / 4.0
                    };

                    if (pointInCone(cone, faceCenter)) return true;
                }
            }
        }
