// Compute the average of a list of integers
double computeAverage(const std::vector<int>& values) {
    if (values.empty()) {  // Handle empty input case
        return 0.0;
    }
    int total = 0;
    size_t index = 0;
    while (index < values.size()) {
        total += values[index];
        ++index;
    }
    return static_cast<double>(total) / static_cast<double>(values.size());
}

int main() {
    std::vector<int> data = {1, 2, 3, 4, 5};
    std::cout << computeAverage(data) << std::endl;  // Output: 3
    return 0;
}

