#include <iostream>

class PriorityQueue {
public:
    PriorityQueue();
    ~PriorityQueue();
    void insert(int itemValue, int priorityLevel);
    int remove();
    bool empty() const;
    void print() const;
private:
    struct Element {
        int data;
        int priority;
        Element* next;
    };
    Element* head;
};

PriorityQueue::PriorityQueue() {
    head = nullptr;
}

PriorityQueue::~PriorityQueue() {
    while (!empty()) {
        remove();
    }
}

void PriorityQueue::insert(int itemValue, int priorityLevel) {
    Element* newElement = new Element;
    newElement->data = itemValue;
    newElement->priority = priorityLevel;
    newElement->next = nullptr;

    if (empty() || priorityLevel > head->priority) {
        newElement->next = head;
        head = newElement;
    } else {
        Element* current = head;
        while (current->next != nullptr && current->next->priority >= priorityLevel) {
            current = current->next;
        }
        newElement->next = current->next;
        current->next = newElement;
    }
}

int PriorityQueue::remove() {
    if (empty()) {
        throw "Priority queue is empty, cannot remove element.";
    }

    Element* temp = head;
    int value = head->data;
    head = head->next;
    delete temp;
    return value;
}

bool PriorityQueue::empty() const {
    return head == nullptr;
}

void PriorityQueue::print() const {
    Element* current = head;
    while (current != nullptr) {
        std::cout << current->data << " (priority: " << current->priority << ") -> ";
        current = current->next;
    }
    std::cout << "end" << std::endl;
}

int main() {
    PriorityQueue pq;

    pq.insert(10, 3);
    pq.insert(5, 1);
    pq.insert(3, 4);
    pq.insert(20, 2);

    pq.print();

    std::cout << "Removed: " << pq.remove() << std::endl;
    std::cout << "Removed: " << pq.remove() << std::endl;

    pq.print();

    return 0;
}

