class MultiDimensionalStorage {
public:
    explicit MultiDimensionalStorage(const std::vector<int>& sizes) : sizes_(sizes) {
        if (sizes.empty() || sizes.size() > 10) {
            throw std::invalid_argument("Array must have between 1 and 10 dimensions.");
        }
        for (int size : sizes) {
            if (size <= 0) {
                throw std::invalid_argument("All dimension sizes must be positive integers.");
            }
        }
        setupStorage();
    }

    int& at(const std::vector<int>& coords) {
        validateCoordinates(coords);
        return storage_[computeOffset(coords)];
    }

    const int& at(const std::vector<int>& coords) const {
        validateCoordinates(coords);
        return storage_[computeOffset(coords)];
    }

private:
    std::vector<int> sizes_;
    std::vector<int> storage_;
    std::vector<int> stepSizes_;

    void setupStorage() {
        int capacity = 1;
        for (int dimSize : sizes_) {
            capacity *= dimSize;
        }
        storage_.assign(capacity, 0);

        stepSizes_.resize(sizes_.size());
        stepSizes_.back() = 1;
        for (int i = static_cast<int>(sizes_.size()) - 2; i >= 0; --i) {
            stepSizes_[i] = stepSizes_[i + 1] * sizes_[i + 1];
        }
    }

    void validateCoordinates(const std::vector<int>& coords) const {
        if (coords.size() != sizes_.size()) {
            throw std::out_of_range("Coordinate count does not match array dimensions.");
        }
        for (size_t i = 0; i < coords.size(); ++i) {
            if (coords[i] < 0 || coords[i] >= sizes_[i]) {
                throw std::out_of_range("Index " + std::to_string(i) + 
                                        " is out of bounds: value=" + std::to_string(coords[i]) +
                                        ", limit=" + std::to_string(sizes_[i]));
            }
        }
    }

    int computeOffset(const std::vector<int>& coords) const {
        int offset = 0;
        for (size_t i = 0; i < coords.size(); ++i) {
            offset += coords[i] * stepSizes_[i];
        }
        return offset;
    }
};

int main() {
    try {
        MultiDimensionalStorage grid({3, 4, 2}); // Create a 3x4x2 structure

        // Set and get values
        grid.at({1, 2, 1}) = 42;
        std::cout << "Value at position (1, 2, 1): " << grid.at({1, 2, 1}) << std::endl;

        // Attempt invalid access to trigger exception handling
        grid.at({3, 2, 1});
    } catch (const std::exception& err) {
        std::cerr << "Exception caught: " << err.what() << std::endl;
    }

    return 0;
}

