#include <iostream>

// Helper structure for binary search tree node
struct BinaryNode {
    int data;
    BinaryNode* leftChild;
    BinaryNode* rightChild;

    BinaryNode(int value) : data(value), leftChild(nullptr), rightChild(nullptr) {}
};

class BinarySearchTree {
private:
    BinaryNode* head;

public:
    BinarySearchTree() : head(nullptr) {}

    void addValue(int value) {
        head = insertIntoTree(head, value);
    }

    BinaryNode* insertIntoTree(BinaryNode* current, int value) {
        if (current == nullptr) {
            return new BinaryNode(value);
        }

        if (value < current->data) {
            current->leftChild = insertIntoTree(current->leftChild, value);
        } else {
            current->rightChild = insertIntoTree(current->rightChild, value);
        }

        return current;
    }

    bool findValue(int value) {
        return locateInTree(head, value);
    }

    bool locateInTree(BinaryNode* current, int value) {
        if (current == nullptr) {
            return false;
        }

        if (value == current->data) {
            return true;
        } else if (value < current->data) {
            return locateInTree(current->leftChild, value);
        } else {
            return locateInTree(current->rightChild, value);
        }
    }

    void deleteValue(int value) {
        head = removeFromTree(head, value);
    }

    BinaryNode* removeFromTree(BinaryNode* current, int value) {
        if (current == nullptr) {
            return nullptr;
        }

        if (value < current->data) {
            current->leftChild = removeFromTree(current->leftChild, value);
        } else if (value > current->data) {
            current->rightChild = removeFromTree(current->rightChild, value);
        } else {
            // Node to delete found
            if (current->leftChild == nullptr && current->rightChild == nullptr) {
                delete current;
                return nullptr;
            } else if (current->leftChild == nullptr) {
                BinaryNode* successor = current->rightChild;
                delete current;
                return successor;
            } else if (current->rightChild == nullptr) {
                BinaryNode* predecessor = current->leftChild;
                delete current;
                return predecessor;
            } else {
                // Find minimum in right subtree
                BinaryNode* minNode = getMinimum(current->rightChild);
                current->data = minNode->data;
                current->rightChild = removeFromTree(current->rightChild, minNode->data);
            }
        }

        return current;
    }

    BinaryNode* getMinimum(BinaryNode* current) {
        while (current->leftChild != nullptr) {
            current = current->leftChild;
        }
        return current;
    }

    void displayInOrder() {
        traverseInOrder(head);
    }

    void traverseInOrder(BinaryNode* current) {
        if (current != nullptr) {
            traverseInOrder(current->leftChild);
            std::cout << current->data << " ";
            traverseInOrder(current->rightChild);
        }
    }
};

int main() {
    BinarySearchTree bst;

    bst.addValue(5);
    bst.addValue(3);
    bst.addValue(8);
    bst.addValue(2);
    bst.addValue(4);
    bst.addValue(7);
    bst.addValue(9);

    std::cout << "Inorder traversal: ";
    bst.displayInOrder();
    std::cout << std::endl;

    std::cout << "Search 5: " << (bst.findValue(5) ? "found" : "not found") << std::endl;
    std::cout << "Search 10: " << (bst.findValue(10) ? "found" : "not found") << std::endl;

    bst.deleteValue(3);

    std::cout << "Inorder traversal after removing 3: ";
    bst.displayInOrder();
    std::cout << std::endl;

    return 0;
}

