// Optimized prime checking function using 6k ± 1 optimization
bool checkPrime(long long value) {
    if (value <= 1) return false;
    if (value <= 3) return true;
    if (value % 2 == 0 || value % 3 == 0) return false;

    long long limit = static_cast<long long>(std::sqrt(value));
    for (long long divisor = 5; divisor <= limit; divisor += 6) {
        if (value % divisor == 0 || value % (divisor + 2) == 0) {
            return false;
        }
    }
    return true;
}

// Worker function to scan a portion of the range for primes
void scanRange(long long begin, long long finish, long long limit, 
               std::mutex& outputMutex, std::ofstream& outputFile, 
               std::atomic<long long>& foundCounter) {
    for (long long candidate = begin; candidate <= finish; ++candidate) {
        if (checkPrime(candidate)) {
            long long currentCount = ++foundCounter;
            if (currentCount > limit) {
                std::lock_guard<std::mutex> guard(outputMutex);
                outputFile << candidate << '\n';
            } else {
                std::cout << candidate << '\n';
            }
        }
    }
}

int main() {
    long long rangeStart, rangeEnd, fileThreshold;
    int threadCount;

    std::cout << "Enter the starting value: ";
    std::cin >> rangeStart;
    std::cout << "Enter the ending value: ";
    std::cin >> rangeEnd;
    std::cout << "Enter the count threshold for file output: ";
    std::cin >> fileThreshold;
    std::cout << "Enter number of threads to use: ";
    std::cin >> threadCount;

    std::vector<std::thread> workerThreads;
    std::mutex ioMutex;
    std::ofstream resultFile("primes.txt");
    std::atomic<long long> totalFound(0);

    // Calculate work distribution
    long long totalNumbers = rangeEnd - rangeStart + 1;
    long long baseChunk = totalNumbers / threadCount;
    long long extraItems = totalNumbers % threadCount;

    long long nextStart = rangeStart;
    for (int t = 0; t < threadCount; ++t) {
        long long chunkEnd = nextStart + baseChunk - 1;
        if (t == threadCount - 1) {
            chunkEnd += extraItems;
        }

        workerThreads.emplace_back(scanRange, 
                                   nextStart, 
                                   chunkEnd, 
                                   fileThreshold, 
                                   std::ref(ioMutex), 
                                   std::ref(resultFile), 
                                   std::ref(totalFound));
        nextStart = chunkEnd + 1;
    }

    // Wait for all threads to complete
    for (auto& worker : workerThreads) {
        worker.join();
    }

    resultFile.close();
    std::cout << "All calculations finished. Primes exceeding the threshold are saved in primes.txt." << std::endl;

    return 0;
}

