// Wrapper for .NET managed object interaction
class ManagedWrapper
{
public:
    ManagedWrapper(ManagedObject^ instance) : _managedInstance(instance) {}

    void PerformOperation() 
    { 
        _managedInstance->PerformOperation(); 
    }

    ~ManagedWrapper() 
    { 
        if (_managedInstance != nullptr)
            _managedInstance->Cleanup(); 
    }

private:
    ManagedObject^ _managedInstance;
};

// Abstract base for managed objects
class ManagedObject
{
public:
    virtual void PerformOperation() = 0;
    virtual void Cleanup() = 0;
};

class DotNetIntegration
{
public:
    DotNetIntegration()
    {
        HRESULT hr = CLRCreateInstance(CLSID_CLRMetaHost, IID_ICLRMetaHost, (LPVOID*)&_metaHost);
        if (FAILED(hr)) throw std::runtime_error("Failed to initialize CLR meta host");

        hr = _metaHost->GetRuntime(L"v4.0.30319", IID_ICLRRuntimeInfo, (LPVOID*)&_runtimeInfo);
        if (FAILED(hr)) throw std::runtime_error("Unable to retrieve runtime information");

        BOOL loadable = FALSE;
        hr = _runtimeInfo->IsLoadable(&loadable);
        if (FAILED(hr) || !loadable) throw std::runtime_error("CLR runtime is not available for loading");

        hr = _runtimeInfo->GetInterface(CLSID_CLRRuntimeHost, IID_ICLRRuntimeHost, (LPVOID*)&_runtimeHost);
        if (FAILED(hr)) throw std::runtime_error("Could not obtain runtime host interface");

        hr = _runtimeHost->Start();
        if (FAILED(hr)) throw std::runtime_error("Failed to start the CLR runtime");

        hr = _runtimeHost->GetCLRControl(&_clrControl);
        if (FAILED(hr)) throw std::runtime_error("Unable to get CLR control");

        hr = _clrControl->GetHostControl(&_hostControl);
        if (FAILED(hr)) throw std::runtime_error("Failed to acquire host control");

        // Re-query for safety (redundant but defensive)
        hr = _hostControl->QueryInterface(IID_IHostControl, (LPVOID*)&_hostControl);
        if (FAILED(hr)) throw std::runtime_error("Host control query failed");

        // Load and execute managed code in default app domain
        hr = _runtimeHost->ExecuteInDefaultAppDomain(
            L"ManagedLibrary.dll",
            L"ManagedLibrary.ManagedClass", 
            L"Initialize", 
            L"", 
            &_managedReference);

        if (FAILED(hr)) throw std::runtime_error("Execution in default app domain failed");
    }

    ~DotNetIntegration()
    {
        _runtimeHost->Stop();

        if (_runtimeHost) _runtimeHost->Release();
        if (_runtimeInfo) _runtimeInfo->Release();
        if (_metaHost) _metaHost->Release();
    }

    void ExecuteOperation()
    {
        HRESULT hr = _runtimeHost->ExecuteInDefaultAppDomain(
            L"ManagedLibrary.dll",
            L"ManagedLibrary.ManagedClass", 
            L"PerformOperation", 
            L"", 
            nullptr);

        if (FAILED(hr)) throw std::runtime_error("Operation execution failed");
    }

private:
    ICLRMetaHost* _metaHost;
    ICLRRuntimeInfo* _runtimeInfo;
    ICLRRuntimeHost* _runtimeHost;
    ICLRControl* _clrControl;
    IHostControl* _hostControl;
    _variant_t _managedReference;
};

int main()
{
    try
    {
        DotNetIntegration dotnet;
        dotnet.ExecuteOperation();
    }
    catch (const std::exception& ex)
    {
        std::cerr << "Error: " << ex.what() << std::endl;
    }

    return 0;
}

