// Determine if a number is prime using an alternative approach
bool checkPrime(int value) {
    // Handle edge cases: numbers less than 2 are not prime
    if (value < 2) {
        return false;
    }

    // Special case for 2, the only even prime
    if (value == 2) {
        return true;
    }

    // Eliminate all even numbers greater than 2
    if (value % 2 == 0) {
        return false;
    }

    // Check odd divisors up to the square root of the value
    int limit = static_cast<int>(std::sqrt(value));
    int divisor = 3;
    while (divisor <= limit) {
        if (value % divisor == 0) {
            return false;
        }
        divisor += 2; // Only test odd divisors
    }

    return true;
}

int main() {
    std::cout << "Prime numbers between 1 and 100 are:" << std::endl;

    int currentNumber = 1;
    while (currentNumber <= 100) {
        if (checkPrime(currentNumber)) {
            std::cout << currentNumber << " ";
        }
        currentNumber++;
    }

    std::cout << std::endl;
    return 0;
}

#include <rocksdb/db.h>
#include <rocksdb/options.h>
#include <string>
#include <iostream>

struct PersonData {
    std::string identifier;
    std::string fullName;
    int years;

    std::string pack() const {
        return identifier + "|" + fullName + "|" + std::to_string(years);
    }

    static PersonData unpack(const std::string& record) {
        PersonData person;
        size_t first = record.find('|');
        size_t second = record.find('|', first + 1);
        person.identifier = record.substr(0, first);
        person.fullName = record.substr(first + 1, second - first - 1);
        person.years = std::stoi(record.substr(second + 1));
        return person;
    }
};

class PersonStore {
private:
    rocksdb::DB* database;
    rocksdb::Options config;

public:
    PersonStore(const std::string& location) {
        config.create_if_missing = true;
        rocksdb::Status result = rocksdb::DB::Open(config, location, &database);
        if (!result.ok()) {
            std::cerr << "Failed to open database: " << result.ToString() << std::endl;
        }
    }

    ~PersonStore() {
        delete database;
    }

    rocksdb::Status add(const PersonData& person) {
        return database->Put(rocksdb::WriteOptions(), person.identifier, person.pack());
    }

    rocksdb::Status modify(const PersonData& person) {
        return database->Put(rocksdb::WriteOptions(), person.identifier, person.pack());
    }

    rocksdb::Status erase(const std::string& key) {
        return database->Delete(rocksdb::WriteOptions(), key);
    }

    rocksdb::Status fetch(const std::string& key, PersonData& person) {
        std::string buffer;
        rocksdb::Status status = database->Get(rocksdb::ReadOptions(), key, &buffer);
        if (status.ok()) {
            person = PersonData::unpack(buffer);
        }
        return status;
    }
};

int main() {
    PersonStore store("path/to/db");

    PersonData entry;
    entry.identifier = "1";
    entry.fullName = "Alice";
    entry.years = 30;

    store.add(entry);

    PersonData retrieved;
    store.fetch("1", retrieved);
    std::cout << "Record found: " << retrieved.fullName << " (age: " << retrieved.years << ")" << std::endl;

    retrieved.fullName = "Alice Smith";
    store.modify(retrieved);

