#include <iostream>
#include <string>
#include <tensorflow/c/c_api.h>

// Helper function to load and initialize a TensorFlow model graph
TF_Graph* InitializeModel(const char* model_file) {
    TF_Graph* model_graph = TF_NewGraph();
    TF_Status* evaluation_status = TF_NewStatus();
    TF_SessionOptions* session_config = TF_NewSessionOptions();

    TF_Buffer* serialized_model = TF_NewBuffer();
    TF_ReadFileToBuffer(session_config, model_file, serialized_model, evaluation_status);

    if (TF_GetCode(evaluation_status) != TF_OK) {
        std::cerr << "Failed to load model file: " << TF_Message(evaluation_status) << std::endl;
        TF_DeleteStatus(evaluation_status);
        return nullptr;
    }

    TF_ImportGraphDefOptions* graph_options = TF_NewImportGraphDefOptions();
    TF_GraphImportGraphDef(model_graph, serialized_model, graph_options, evaluation_status);

    if (TF_GetCode(evaluation_status) != TF_OK) {
        std::cerr << "Graph import failed: " << TF_Message(evaluation_status) << std::endl;
        TF_DeleteStatus(evaluation_status);
        TF_DeleteImportGraphDefOptions(graph_options);
        return nullptr;
    }

    // Cleanup intermediate resources
    TF_DeleteBuffer(serialized_model);
    TF_DeleteImportGraphDefOptions(graph_options);
    TF_DeleteStatus(evaluation_status);
    return model_graph;
}

// Perform sentiment classification using the loaded model
void EvaluateSentiment(TF_Graph* model_graph, const std::string& text_input) {
    TF_Status* run_status = TF_NewStatus();
    TF_SessionOptions* session_opts = TF_NewSessionOptions();
    TF_Session* inference_session = TF_NewSession(model_graph, session_opts, run_status);

    if (TF_GetCode(run_status) != TF_OK) {
        std::cerr << "Session creation error: " << TF_Message(run_status) << std::endl;
        TF_DeleteSession(inference_session, run_status);
        TF_DeleteSessionOptions(session_opts);
        TF_DeleteStatus(run_status);
        return;
    }

    // Define operation names for input and output
    const char* input_operation = "input_layer:0";
    const char* output_operation = "output_layer:0";

    TF_Output input_port = {TF_GraphOperationByName(model_graph, input_operation), 0};
    TF_Output output_port = {TF_GraphOperationByName(model_graph, output_operation), 0};

    // Prepare string tensor from input text
    TF_Tensor* input_data_tensor = TF_NewTensor(TF_STRING, nullptr, 0, &text_input.data(), text_input.size(), nullptr, nullptr);

    // Execute model inference
    std::vector<TF_Output> input_ops = {input_port};
    std::vector<TF_Tensor*> input_values = {input_data_tensor};
    std::vector<TF_Output> output_ops = {output_port};
    std::vector<TF_Tensor*> result_tensors(1);

    TF_SessionRun(inference_session, nullptr,
                  &input_ops[0], &input_values[0], 1,
                  &output_ops[0], &result_tensors[0], 1,
                  nullptr, 0, nullptr, run_status);

    if (TF_GetCode(run_status) != TF_OK) {
        std::cerr << "Inference execution failed: " << TF_Message(run_status) << std::endl;
        TF_DeleteTensor(input_data_tensor);
        TF_DeleteSession(inference_session, run_status);
        TF_DeleteSessionOptions(session_opts);
        TF_DeleteStatus(run_status);
        return;
    }

    // Interpret results
    float* result_buffer = static_cast<float*>(TF_TensorData(result_tensors[0]));
    double confidence = result_buffer[0];
    std::string sentiment_label = (confidence > 0.5) ? "Positive" : "Negative";

    std::cout << "Detected sentiment: " << sentiment_label << " (confidence: " << confidence << ")" << std::endl;

    // Release allocated memory
    TF_DeleteTensor(input_data_tensor);
    TF_DeleteTensor(result_tensors[0]);
    TF_DeleteSession(inference_session, run_status);
    TF_DeleteSessionOptions(session_opts);
    TF_DeleteStatus(run_status);
}

int main() {
    const char* model_filename = "sentiment_model.pb";
    std::string sample_text = "This is an amazing experience!";

    TF_Graph* loaded_graph = InitializeModel(model_filename);
    if (loaded_graph) {
        EvaluateSentiment(loaded_graph, sample_text);
        TF_DeleteGraph(loaded_graph);
    }

    return 0;
}

