#include <vector>

class TicTacToeGame {
public:
    TicTacToeGame() {
        // Initialize a 3x3 grid with empty spaces
        gameGrid.resize(3, std::vector<char>(3, ' '));
        turn = 'X';
    }

    void showGrid() const {
        for (int row = 0; row < 3; ++row) {
            for (int col = 0; col < 3; ++col) {
                std::cout << gameGrid[row][col];
                if (col != 2) std::cout << " | ";
            }
            std::cout << std::endl;
            if (row != 2) std::cout << "---------" << std::endl;
        }
    }

    bool placeMark(int r, int c) {
        // Validate coordinates and check if cell is empty
        if (r < 0 || r > 2 || c < 0 || c > 2 || gameGrid[r][c] != ' ') {
            return false;
        }
        gameGrid[r][c] = turn;
        switchTurn();
        return true;
    }

    char determineResult() const {
        // Check horizontal lines
        for (int i = 0; i < 3; ++i) {
            if (gameGrid[i][0] == gameGrid[i][1] && 
                gameGrid[i][1] == gameGrid[i][2] && 
                gameGrid[i][0] != ' ') {
                return gameGrid[i][0];
            }
        }

        // Check vertical lines
        for (int j = 0; j < 3; ++j) {
            if (gameGrid[0][j] == gameGrid[1][j] && 
                gameGrid[1][j] == gameGrid[2][j] && 
                gameGrid[0][j] != ' ') {
                return gameGrid[0][j];
            }
        }

        // Check main diagonal
        if (gameGrid[0][0] == gameGrid[1][1] && 
            gameGrid[1][1] == gameGrid[2][2] && 
            gameGrid[0][0] != ' ') {
            return gameGrid[0][0];
        }

        // Check secondary diagonal
        if (gameGrid[0][2] == gameGrid[1][1] && 
            gameGrid[1][1] == gameGrid[2][0] && 
            gameGrid[0][2] != ' ') {
            return gameGrid[0][2];
        }

        // Check for tie
        for (int x = 0; x < 3; ++x) {
            for (int y = 0; y < 3; ++y) {
                if (gameGrid[x][y] == ' ') {
                    return ' '; // Game continues
                }
            }
        }

        return 'T'; // Tie
    }

private:
    std::vector<std::vector<char>> gameGrid;
    char turn;

    void switchTurn() {
        turn = (turn == 'X') ? 'O' : 'X';
    }
};

int main() {
    TicTacToeGame match;
    match.showGrid();

    // Simulate some moves
    match.placeMark(0, 0);
    match.placeMark(1, 1);
    match.placeMark(0, 1);
    match.placeMark(1, 2);
    match.placeMark(0, 2);

    match.showGrid();

    char outcome = match.determineResult();
    if (outcome == 'X' || outcome == 'O') {
        std::cout << "Player " << outcome << " wins!" << std::endl;
    } else if (outcome == 'T') {
        std::cout << "The game ends in a tie!" << std::endl;
    } else {
        std::cout << "The game continues!" << std::endl;
    }

    return 0;
}

