struct TVersionizedPointer {
  std::intptr_t Ver;
  void* Ptr;
};

struct TVersionizedPointerStorage {
  char data[2 * sizeof(TVersionizedPointer)];
};

TVersionizedPointer* GetAlignedVersionizedPointer(TVersionizedPointerStorage& storage) {
  const size_t alignment = alignof(TVersionizedPointer);
  const size_t vp_size = sizeof(TVersionizedPointer);

  // Calculate address with padding to ensure alignment
  std::uintptr_t baseAddr = reinterpret_cast<std::uintptr_t>(&storage);
  std::uintptr_t offset = (vp_size - 1) & ~(alignment - 1);
  std::uintptr_t alignedAddr = (baseAddr + offset) & ~(alignment - 1);

  return reinterpret_cast<TVersionizedPointer*>(alignedAddr);
}

