// 3D vector structure with basic operations
struct Vec3 {
    float x, y, z;

    Vec3(float _x = 0.0f, float _y = 0.0f, float _z = 0.0f)
        : x(_x), y(_y), z(_z) { }

    // Normalize the vector in-place
    Vec3& normalize() {
        float len = std::sqrt(x * x + y * y + z * z);
        if (len > 0.0f) {
            x /= len;
            y /= len;
            z /= len;
        }
        return *this;
    }

    // Scalar multiplication
    Vec3 operator*(float s) const {
        return Vec3(x * s, y * s, z * s);
    }

    // Vector addition
    Vec3 operator+(const Vec3& v) const {
        return Vec3(x + v.x, y + v.y, z + v.z);
    }

    // Vector subtraction
    Vec3 operator-(const Vec3& v) const {
        return Vec3(x - v.x, y - v.y, z - v.z);
    }

    // Dot product
    float dot(const Vec3& v) const {
        return x * v.x + y * v.y + z * v.z;
    }
};

// Apply rotation transformation to a vector using Euler angles (XYZ order)
Vec3 rotateVector(const Vec3& vec, const Vec3& eulerDeg) {
    // Convert degrees to radians
    float rx = eulerDeg.x * 0.017453292519943295f; // π/180
    float ry = eulerDeg.y * 0.017453292519943295f;
    float rz = eulerDeg.z * 0.017453292519943295f;

    float sx = std::sin(rx), cx = std::cos(rx);
    float sy = std::sin(ry), cy = std::cos(ry);
    float sz = std::sin(rz), cz = std::cos(rz);

    Vec3 result;

    // Compute rotated coordinates using rotation matrix for XYZ order
    result.x = vec.x * (cy * cz) + vec.y * (sx * sy * cz - cx * sz) + vec.z * (cx * sy * cz + sx * sz);
    result.y = vec.x * (cy * sz) + vec.y * (sx * sy * sz + cx * cz) + vec.z * (cx * sy * sz - sx * cz);
    result.z = vec.x * (-sy)      + vec.y * (sx * cy)           + vec.z * (cx * cy);

    return result;
}

int main() {
    Vec3 origin(0.0f, 0.0f, 0.0f);
    Vec3 rotation(-5.0f, -15.0f, 25.0f);

    Vec3 forward(0.0f, 0.0f, 1.0f);
    Vec3 rotatedForward = rotateVector(forward, rotation);

    std::cout << "'One step forward' vector is (" << rotatedForward.x << ", "
              << rotatedForward.y << ", " << rotatedForward.z << ")\n";

    return 0;
}

