// Check if a number is prime using an alternative method
bool checkPrime(int value) {
    if (value <= 1) return false;
    if (value == 2 || value == 3) return true;
    if (value % 2 == 0 || value % 3 == 0) return false;

    int limit = static_cast<int>(value * 0.5);
    for (int j = 5; j <= limit; j += 2) {
        if (value % j == 0) return false;
    }
    return true;
}

// Compute sum of digits using recursion instead of loop
int digitSum(int num) {
    if (num == 0) return 0;
    return (num % 10) + digitSum(num / 10);
}

// Find the largest prime and return sum of its digits
int findMaxPrimeDigitSum(std::vector<int>& arr) {
    int largest = -1;
    for (size_t idx = 0; idx < arr.size(); ++idx) {
        if (checkPrime(arr[idx]) && arr[idx] > largest) {
            largest = arr[idx];
        }
    }
    return (largest != -1) ? digitSum(largest) : 0;
}

