// Custom atomic addition for double precision floating point numbers
__device__ double atomicAddDouble(double* addr, double increment) {
    unsigned long long int* addr_as_ull = reinterpret_cast<unsigned long long int*>(addr);
    unsigned long long int current_val = *addr_as_ull;
    unsigned long long int expected_val;

    do {
        expected_val = current_val;
        double current_double = __longlong_as_double(expected_val);
        double new_sum = current_double + increment;
        unsigned long long int new_val = __double_as_longlong(new_sum);
        current_val = atomicCAS(addr_as_ull, expected_val, new_val);
    } while (expected_val != current_val);

    return __longlong_as_double(current_val);
}
