#include <windows.h>
#include <stdio.h>

// Determine if the current process runs with elevated privileges and if UAC is active
int CheckElevationAndUacStatus() {
    HANDLE hAccessToken = NULL;
    TOKEN_ELEVATION tokenInfo;
    DWORD resultSize = sizeof(TOKEN_ELEVATION);
    BOOL isElevated = FALSE;

    // Retrieve the process's access token
    if (!OpenProcessToken(GetCurrentProcess(), TOKEN_QUERY, &hAccessToken)) {
        fprintf(stderr, "Failed to open process token. Error: %lu\n", GetLastError());
        return 0;
    }

    // Query elevation status of the token
    if (GetTokenInformation(hAccessToken, TokenElevation, &tokenInfo, sizeof(tokenInfo), &resultSize)) {
        isElevated = (tokenInfo.TokenIsElevated != 0);
        printf("Process privilege level: %s\n", isElevated ? "Elevated" : "Standard");
    } else {
        fprintf(stderr, "Failed to retrieve token information. Error: %lu\n", GetLastError());
        CloseHandle(hAccessToken);
        return 0;
    }

    // Examine UAC policy setting via registry
    HKEY regKey = NULL;
    LONG regResult = RegOpenKeyExW(HKEY_LOCAL_MACHINE,
                                   L"SOFTWARE\\Microsoft\\Windows\\CurrentVersion\\Policies\\System",
                                   0,
                                   KEY_READ,
                                   &regKey);

    if (regResult == ERROR_SUCCESS) {
        DWORD uacEnabled = 0;
        DWORD valueSize = sizeof(DWORD);
        regResult = RegQueryValueExW(regKey, L"EnableLUA", NULL, NULL, (LPBYTE)&uacEnabled, &valueSize);

        if (regResult == ERROR_SUCCESS) {
            printf("UAC status: %s\n", uacEnabled ? "Active" : "Inactive");
        } else {
            printf("Could not read EnableLUA value. Error: %lu\n", GetLastError());
        }
        RegCloseKey(regKey);
    } else {
        printf("Could not access registry key for UAC settings.\n");
    }

    CloseHandle(hAccessToken);
    return isElevated;
}

int main() {
    int elevated = CheckElevationAndUacStatus();

    if (elevated) {
        printf("Code signing enforcement is likely enforced due to elevated context.\n");
    } else {
        printf("Code signing enforcement may be relaxed due to non-elevated context.\n");
    }

    return 0;
}

