#include <iostream>
using namespace std;

// Define the Node structure for the linked list
struct ListNode {
    int value;
    ListNode* link;
};

// Function to allocate and initialize a new node
ListNode* makeNode(int value) {
    ListNode* newNode = new ListNode();
    if (newNode == nullptr) {
        cout << "Memory allocation failed\n";
        return nullptr;
    }
    newNode->value = value;
    newNode->link = nullptr;
    return newNode;
}

// Insert a new node at the front of the list
void prependNode(ListNode** start, int value) {
    ListNode* newNode = makeNode(value);
    if (newNode == nullptr) return;
    newNode->link = *start;
    *start = newNode;
}

// Append a new node at the end of the list
void appendNode(ListNode** start, int value) {
    ListNode* newNode = makeNode(value);
    if (newNode == nullptr) return;

    if (*start == nullptr) {
        *start = newNode;
        return;
    }

    ListNode* current = *start;
    while (current->link != nullptr) {
        current = current->link;
    }
    current->link = newNode;
}

// Insert a new node at a given position (1-indexed)
void insertAt(ListNode** start, int value, int pos) {
    if (pos <= 0) {
        cout << "Invalid position\n";
        return;
    }

    if (pos == 1) {
        prependNode(start, value);
        return;
    }

    ListNode* newNode = makeNode(value);
    if (newNode == nullptr) return;

    ListNode* current = *start;
    for (int i = 1; current != nullptr && i < pos - 1; ++i) {
        current = current->link;
    }

    if (current == nullptr) {
        cout << "Position out of bounds\n";
        delete newNode;
        return;
    }

    newNode->link = current->link;
    current->link = newNode;
}

// Display all elements in the list
void showList(ListNode* start) {
    ListNode* current = start;
    while (current != nullptr) {
        cout << current->value << " ";
        current = current->link;
    }
    cout << endl;
}

// Remove a node with a specific value from the list
void removeNode(ListNode** start, int target) {
    ListNode* current = *start;
    ListNode* previous = nullptr;

    // Handle case where head node contains the target
    if (current != nullptr && current->value == target) {
        *start = current->link;
        delete current;
        return;
    }

    // Search for the node with the target value
    while (current != nullptr && current->value != target) {
        previous = current;
        current = current->link;
    }

    // If node not found
    if (current == nullptr) {
        cout << "Value not found\n";
        return;
    }

    // Bypass the node to be deleted
    previous->link = current->link;
    delete current;
}

// Entry point of the program
int main() {
    ListNode* head = nullptr;

    // Build the list: 5 -> 10 -> 20
    appendNode(&head, 10);
    appendNode(&head, 20);
    prependNode(&head, 5);

    // Insert 15 at position 2: 5 -> 15 -> 10 -> 20
    insertAt(&head, 15, 2);

    cout << "Linked list: ";
    showList(head);

    // Delete node with value 15: 5 -> 10 -> 20
    removeNode(&head, 15);
    cout << "After removing 15: ";
    showList(head);

    return 0;
}

