#include <iostream>
#include <unordered_set>

// Node structure for XOR linked list
struct Node {
    int data;
    Node* link; // Stores XOR of previous and next node addresses

    Node(int val) : data(val), link(nullptr) {}
};

class XorList {
private:
    Node* start;
    Node* end;

public:
    XorList() : start(nullptr), end(nullptr) {}

    // Helper function to compute XOR of two node pointers
    Node* computeXor(Node* a, Node* b) {
        return reinterpret_cast<Node*>(reinterpret_cast<uintptr_t>(a) ^ reinterpret_cast<uintptr_t>(b));
    }

    // Insert element at the end of the list
    void pushBack(int value) {
        Node* newNode = new Node(value);
        if (!start) {
            start = end = newNode;
            return;
        }

        Node* prevNode = end;
        Node* nextNode = computeXor(end->link, nullptr);
        end->link = computeXor(newNode, nextNode);
        newNode->link = computeXor(prevNode, nullptr);
        end = newNode;
    }

    // Reverse the XOR linked list in-place
    void invert() {
        Node* current = start;
        Node* previous = nullptr;
        Node* future = nullptr;

        while (current != nullptr) {
            future = computeXor(previous, current->link);
            current->link = computeXor(previous, future);
            previous = current;
            current = future;
        }

        // Update head to point to the last node (new start)
        start = previous;
    }

    // Display all elements in order from head to tail
    void show() {
        Node* current = start;
        Node* previous = nullptr;
        Node* nextNode;

        while (current != nullptr) {
            std::cout << current->data << " ";
            nextNode = computeXor(previous, current->link);
            previous = current;
            current = nextNode;
        }
        std::cout << std::endl;
    }
};

int main() {
    XorList list;
    list.pushBack(1);
    list.pushBack(2);
    list.pushBack(3);

    list.show(); // Output: 1 2 3

    list.invert();
    list.show(); // Output: 3 2 1

    return 0;
}

