// Precomputed powers of two in descending order (from 2^16 down to 2^0)
const int MULTIPLICATION[] = {
    65536,
    32768,
    16384,
    8192,
    4096,
    2048,
    1024,
    512,
    256,
    128,
    64,
    32,
    16,
    8,
    4,
    2,
    1
};

// Alternative implementation using index-based iteration instead of range-based loop
unsigned long long customHash(const std::string& str) {
    unsigned long long hash = 0;
    size_t index = 0;
    size_t maxIndex = sizeof(MULTIPLICATION) / sizeof(MULTIPLICATION[0]);

    while (index < str.length() && index < maxIndex) {
        hash += static_cast<unsigned long long>(str[index]) * MULTIPLICATION[index];
        ++index;
    }

    return hash;
}

