// Function to perform HTTP GET request and return response body
std::string fetchUrlContent(const std::string& endpoint)
{
    CURL* curlHandle = nullptr;
    CURLcode operationResult;
    std::string responseBody;

    // Initialize global libcurl environment
    curl_global_init(CURL_GLOBAL_ALL);

    // Create a new easy handle
    curlHandle = curl_easy_init();
    if (curlHandle) {
        // Configure the handle for the target URL
        curl_easy_setopt(curlHandle, CURLOPT_URL, endpoint.c_str());

        // Set up callback to capture response data
        curl_easy_setopt(curlHandle, CURLOPT_WRITEFUNCTION, 
            [](char* buffer, size_t unitSize, size_t unitCount, void* userData) -> size_t {
                auto* output = static_cast<std::string*>(userData);
                output->append(buffer, unitSize * unitCount);
                return unitSize * unitCount;
            });

        // Provide pointer to store the accumulated response
        curl_easy_setopt(curlHandle, CURLOPT_WRITEDATA, &responseBody);

        // Execute the request
        operationResult = curl_easy_perform(curlHandle);

        // Clean up the easy handle
        curl_easy_cleanup(curlHandle);
    }

    // Cleanup global resources
    curl_global_cleanup();

    return responseBody;
}

