#include <immintrin.h>
#include <algorithm>
#include <array>

typedef std::array<uint8_t, 3> Vec3B;
typedef std::array<int32_t, 3> Vec3I;

Vec3B v3bSpread(Vec3B const& source, Vec3B dest, int32_t drop) {
    // Convert input arrays to 128-bit integer vectors
    __m128i srcVec = _mm_setr_epi32(source[0], source[1], source[2], 0);
    __m128i dstVec = _mm_setr_epi32(dest[0], dest[1], dest[2], 0);
    __m128i dropVec = _mm_set1_epi32(drop);

    // Compute condition: source > dest + drop
    __m128i sumDestDrop = _mm_add_epi32(dstVec, dropVec);
    __m128i cmpResult = _mm_cmpgt_epi32(srcVec, sumDestDrop);

    // Check if any element satisfies the condition
    unsigned mask = _mm_movemask_epi8(cmpResult);
    if (mask == 0) {
        return dest;
    }

    // Find maximum component in source vector using shuffling
    __m128i shuffled1 = _mm_shuffle_epi32(srcVec, _MM_SHUFFLE(2, 2, 2, 1));
    __m128i max1 = _mm_max_epi32(srcVec, shuffled1);
    __m128i shuffled2 = _mm_shuffle_epi32(max1, _MM_SHUFFLE(2, 2, 2, 0));
    __m128i maxVal = _mm_max_epi32(max1, shuffled2);

    // Apply formula: result = max(source - (source * drop / maxVal), dest)
    __m128i product = _mm_mullo_epi32(srcVec, dropVec);
    __m128i quotient = _mm_div_epi32(product, maxVal);
    __m128i diff = _mm_sub_epi32(srcVec, quotient);
    __m128i finalResult = _mm_max_epi32(diff, dstVec);

    // Store and extract results
    int32_t tempArray[4];
    _mm_storeu_si128(reinterpret_cast<__m128i*>(tempArray), finalResult);

    return {static_cast<uint8_t>(tempArray[0]),
            static_cast<uint8_t>(tempArray[1]),
            static_cast<uint8_t>(tempArray[2])};
}

