using namespace std;

// Function to find the longest common substring between two strings
pair<int, pair<int, int>> longestCommonSubstr(const string& str1, const string& str2) {
    int len1 = str1.size();
    int len2 = str2.size();

    // Initialize DP table with zeros
    vector<vector<int>> table(len1 + 1, vector<int>(len2 + 1, 0));

    // Track maximum length and ending positions
    int maxLen = 0;
    int pos1 = -1;
    int pos2 = -1;

    // Fill the DP table
    for (int i = 1; i <= len1; ++i) {
        for (int j = 1; j <= len2; ++j) {
            if (str1[i-1] == str2[j-1]) {
                table[i][j] = table[i-1][j-1] + 1;
                if (table[i][j] > maxLen) {
                    maxLen = table[i][j];
                    pos1 = i - 1;
                    pos2 = j - 1;
                }
            } else {
                table[i][j] = 0;
            }
        }
    }

    // Compute starting indices from ending positions
    int start1 = pos1 - maxLen + 1;
    int start2 = pos2 - maxLen + 1;

    return {maxLen, {start1, start2}};
}

int main() {
    string input1, input2;

    cout << "Enter first string: ";
    cin >> input1;
    cout << "Enter second string: ";
    cin >> input2;

    auto result = longestCommonSubstr(input1, input2);
    int length = result.first;
    int begin1 = result.second.first;
    int begin2 = result.second.second;

    if (length > 0) {
        cout << "Longest common substring: " << input1.substr(begin1, length) << endl;
        cout << "Start position in first string: " << begin1 << endl;
        cout << "Start position in second string: " << begin2 << endl;
    } else {
        cout << "No common substring exists." << endl;
    }

    return 0;
}

