// Original function that will be intercepted
void OriginalFunction() {
    std::printf("Original Function\n");
}

// Replacement function to execute instead
void HookFunction() {
    std::printf("Hooked Function\n");
}

// Locate the export directory in a loaded module
PIMAGE_EXPORT_DIRECTORY FindExportTable(HMODULE hModule) {
    PIMAGE_DOS_HEADER pDosHeader = reinterpret_cast<PIMAGE_DOS_HEADER>(hModule);
    PIMAGE_NT_HEADERS pNtHeaders = reinterpret_cast<PIMAGE_NT_HEADERS>(
        reinterpret_cast<BYTE*>(hModule) + pDosHeader->e_lfanew
    );

    DWORD exportRVA = pNtHeaders->OptionalHeader.DataDirectory[IMAGE_DIRECTORY_ENTRY_EXPORT].VirtualAddress;
    return reinterpret_cast<PIMAGE_EXPORT_DIRECTORY>(
        reinterpret_cast<BYTE*>(hModule) + exportRVA
    );
}

// Replace an exported function with our custom implementation
bool InterceptExportedSymbol(HMODULE hModule, const char* symbolName, void* replacementFunc) {
    PIMAGE_EXPORT_DIRECTORY pExportDir = FindExportTable(hModule);
    if (!pExportDir) {
        return false;
    }

    DWORD* funcTable = reinterpret_cast<DWORD*>(
        reinterpret_cast<BYTE*>(hModule) + pExportDir->AddressOfFunctions
    );
    DWORD* nameTable = reinterpret_cast<DWORD*>(
        reinterpret_cast<BYTE*>(hModule) + pExportDir->AddressOfNames
    );
    WORD* ordinalTable = reinterpret_cast<WORD*>(
        reinterpret_cast<BYTE*>(hModule) + pExportDir->AddressOfNameOrdinals
    );

    for (unsigned int idx = 0; idx < pExportDir->NumberOfNames; ++idx) {
        const char* currentName = reinterpret_cast<const char*>(hModule) + nameTable[idx];

        if (std::strcmp(currentName, symbolName) == 0) {
            DWORD originalProtection;
            DWORD funcIndex = pOrdinalTable[idx];

            LPVOID funcAddress = reinterpret_cast<LPVOID>(
                reinterpret_cast<BYTE*>(hModule) + funcTable[funcIndex]
            );

            VirtualProtect(funcAddress, sizeof(DWORD), PAGE_EXECUTE_READWRITE, &originalProtection);

            *reinterpret_cast<DWORD*>(funcAddress) = reinterpret_cast<DWORD>(replacementFunc);

            VirtualProtect(funcAddress, sizeof(DWORD), originalProtection, &originalProtection);
            return true;
        }
    }

    return false;
}

int main() {
    HMODULE hModule = GetModuleHandleA("YourDLL.dll"); // Replace with your DLL name
    if (!hModule) {
        std::printf("Failed to get module handle.\n");
        return 1;
    }

    if (InterceptExportedSymbol(hModule, "OriginalFunction", HookFunction)) {
        std::printf("Hooked 'OriginalFunction' successfully.\n");
    } else {
        std::printf("Failed to hook 'OriginalFunction'.\n");
        return 1;
    }

    // Call the original function to test the hook
    OriginalFunction();

    return 0;
}

