// Helper function to exchange values of two integers using pointers
void exchange(int* x, int* y) {
    int temp = *x;
    *x = *y;
    *y = temp;
}

// Rearrange three integers in descending order
void Descend(int &first, int &second, int &third) {
    // Ensure the largest among first and second is first
    if (first < second) {
        exchange(&first, &second);
    }

    // Ensure the largest among first and third is first
    if (first < third) {
        exchange(&first, &third);
    }

    // Ensure the larger among second and third is second
    if (second < third) {
        exchange(&second, &third);
    }
}

#include <llvm/ExecutionEngine/Orc/LLJIT.h>
#include <llvm/IR/IRBuilder.h>
#include <llvm/IR/Module.h>
#include <llvm/Support/TargetSelect.h>

using namespace llvm;

int main() {
    // Initialize native target components for JIT compilation
    InitializeNativeTarget();
    InitializeNativeTargetAsmPrinter();
    InitializeNativeTargetAsmParser();

    // Create LLJIT instance using builder pattern
    auto JIT = cantFail(LLJITBuilder().create());

    // Get LLVM context from the execution session's target triple
    auto &Context = JIT->getExecutionSession().getTargetTriple().getLLVMContext();

    // Create a new module named "jit_module"
    std::unique_ptr<Module> ModulePtr = std::make_unique<Module>("jit_module", Context);
    IRBuilder<> Builder(Context);

    // Define function type: void(void)
    FunctionType *FuncTy = FunctionType::get(Type::getVoidTy(Context), /*isVarArg=*/false);

    // Create external linkage function named "dynamic_func"
    Function *Func = Function::Create(FuncTy, Function::ExternalLinkage, "dynamic_func", ModulePtr.get());

    // Create entry basic block and set insertion point
    BasicBlock *EntryBB = BasicBlock::Create(Context, "entry_block", Func);
    Builder.SetInsertPoint(EntryBB);

    // Insert x86 xadd instruction via intrinsic call (32-bit atomic exchange-add)
    Value *IntrinDecl = Intrinsic::getDeclaration(ModulePtr.get(), Intrinsic::x86_xadd_32);
    Builder.CreateCall(IntrinDecl, {Builder.getInt32(5), Builder.getInt32(10)});

    // Return from function
    Builder.CreateRetVoid();

    // Add IR module to JIT and ensure success
    cantFail(JIT->addIRModule(std::move(ModulePtr)));

    // Look up the compiled function symbol
    auto SymbolAddr = cantFail(JIT->lookup("dynamic_func"));

    // Cast address to function pointer type and invoke
    using DynamicFuncPtr = void (*)();
    DynamicFuncPtr CompiledFunc = reinterpret_cast<DynamicFuncPtr>(SymbolAddr.getValue());
    CompiledFunc();

    return 0;
}

