// Helper function to parse and print received vector from JSON
void processReceivedData(const std::string& rawData) {
    try {
        auto parsed = json::parse(rawData);
        std::vector<double> values;
        if (parsed.is_array()) {
            values.reserve(parsed.size());
            for (const auto& item : parsed) {
                values.push_back(item.get<double>());
            }
        } else {
            std::cerr << "Received data is not an array." << std::endl;
            return;
        }

        std::cout << "Client says: [";
        for (std::size_t idx = 0; idx < values.size(); ++idx) {
            std::cout << values[idx];
            if (idx + 1 < values.size()) std::cout << " ";
        }
        std::cout << "]" << std::endl;
    } catch (const json::exception& ex) {
        std::cerr << "JSON processing failed: " << ex.what() << std::endl;
    }
}

int main() {
    WSADATA wsaData{};
    SOCKET listeningSocket = INVALID_SOCKET;
    SOCKET connectedSocket = INVALID_SOCKET;
    sockaddr_in localEndpoint{}, remoteEndpoint{};

    // Initialize Winsock
    if (WSAStartup(MAKEWORD(2, 2), &wsaData) != 0) {
        std::cerr << "WSAStartup failed: " << WSAGetLastError() << std::endl;
        return 1;
    }

    // Create listening socket
    listeningSocket = socket(AF_INET, SOCK_STREAM, IPPROTO_TCP);
    if (listeningSocket == INVALID_SOCKET) {
        std::cerr << "Socket creation failed: " << WSAGetLastError() << std::endl;
        WSACleanup();
        return 1;
    }

    // Configure server address structure
    localEndpoint.sin_family = AF_INET;
    localEndpoint.sin_addr.s_addr = INADDR_ANY;
    localEndpoint.sin_port = htons(5555);

    // Bind socket to address
    if (bind(listeningSocket, reinterpret_cast<sockaddr*>(&localEndpoint), sizeof(localEndpoint)) == SOCKET_ERROR) {
        std::cerr << "Bind failed: " << WSAGetLastError() << std::endl;
        closesocket(listeningSocket);
        WSACleanup();
        return 1;
    }

    // Start listening
    if (listen(listeningSocket, SOMAXCONN) == SOCKET_ERROR) {
        std::cerr << "Listen failed: " << WSAGetLastError() << std::endl;
        closesocket(listeningSocket);
        WSACleanup();
        return 1;
    }

    std::cout << "Server started. Awaiting connection on port 5555..." << std::endl;

    // Accept incoming connection
    int remoteSize = sizeof(remoteEndpoint);
    connectedSocket = accept(listeningSocket, reinterpret_cast<sockaddr*>(&remoteEndpoint), &remoteSize);
    if (connectedSocket == INVALID_SOCKET) {
        std::cerr << "Accept failed: " << WSAGetLastError() << std::endl;
        closesocket(listeningSocket);
        WSACleanup();
        return 1;
    }

    std::cout << "Client connected from " << inet_ntoa(remoteEndpoint.sin_addr) << ":" 
              << ntohs(remoteEndpoint.sin_port) << std::endl;

    // Receive up to 5 messages
    constexpr int maxMessages = 5;
    for (int msgCount = 0; msgCount < maxMessages; ++msgCount) {
        std::vector<char> recvBuffer(1024, '\0');
        int bytesReceived = recv(connectedSocket, recvBuffer.data(), static_cast<int>(recvBuffer.size()), 0);

        if (bytesReceived > 0) {
            std::string receivedString(recvBuffer.begin(), recvBuffer.begin() + bytesReceived);
            processReceivedData(receivedString);
        } else if (bytesReceived == 0) {
            std::cout << "Connection closed by client." << std::endl;
            break;
        } else {
            std::cerr << "Receive error: " << WSAGetLastError() << std::endl;
            break;
        }
    }

    // Cleanup
    if (connectedSocket != INVALID_SOCKET) {
        closesocket(connectedSocket);
    }
    closesocket(listeningSocket);
    WSACleanup();

    std::cout << "Press Enter to exit..." << std::endl;
    std::cin.ignore(std::numeric_limits<std::streamsize>::max(), '\n');
    return 0;
}

