template<typename T, uint32_t maxCount>
class RingBuffer final {
    alignas(8) T buffer[maxCount];
    volatile uint32_t start;
    volatile uint32_t end;

    bool enqueue(const T& value) {
        uint32_t currentTail;
        uint32_t nextTail;

        do {
            // Load current end (tail) position atomically
            currentTail = __LDREXW(&end);

            // Check if buffer is full by comparing with start
            if (isFull()) {
                __CLREX();
                return false;
            }

            // Calculate next position with wrap-around
            nextTail = (currentTail == maxCount - 1) ? 0 : currentTail + 1;

            // Try to update the tail pointer atomically
        } while (__STREXW(nextTail, &end));

        // Store the item at the old tail position
        buffer[currentTail] = value;
        return true;
    }

    // ... other methods ...
};

