// Retrieve performance counter path based on system language
std::string FetchCounterPathByLanguage() {
    LCID systemLocale = GetSystemDefaultUILanguage();
    char langCode[LOCALE_NAME_MAX_LENGTH];

    if (GetLocaleInfoA(systemLocale, LOCALE_SISO639LANGNAME, langCode, LOCALE_NAME_MAX_LENGTH) == 0) {
        return "\\Processor(_Total)\\% Processor Time"; // Fallback on error
    }

    std::map<std::string, std::string> languageMap = {
        {"en", "\\Processor(_Total)\\% Processor Time"},
        {"de", "\\Prozessor(_Total)\\Prozessorzeit (%)"},
        // Additional language mappings can be added here
    };

    auto search = languageMap.find(langCode);
    if (search != languageMap.end()) {
        return search->second;
    }
    return "\\Processor(_Total)\\% Processor Time"; // Default fallback
}

// Collect and compute current CPU usage percentage
double AcquireCpuUsage() {
    PDH_HQUERY queryHandle = NULL;
    PDH_HCOUNTER counterHandle = NULL;
    PDH_FMT_COUNTERVALUE valueBuffer;

    // Initialize query for performance data collection
    if (PdhOpenQuery(NULL, 0, &queryHandle) != ERROR_SUCCESS) {
        return -1.0;
    }

    // Add the appropriate performance counter based on locale
    std::string counterPath = FetchCounterPathByLanguage();
    if (PdhAddCounter(queryHandle, counterPath.c_str(), 0, &counterHandle) != ERROR_SUCCESS) {
        PdhCloseQuery(queryHandle);
        return -1.0;
    }

    // Initial data collection to populate counters
    if (PdhCollectQueryData(queryHandle) != ERROR_SUCCESS) {
        PdhCloseQuery(queryHandle);
        return -1.0;
    }

    // Allow time interval for meaningful sample collection
    Sleep(1000);

    // Second data collection after delay
    if (PdhCollectQueryData(queryHandle) != ERROR_SUCCESS) {
        PdhCloseQuery(queryHandle);
        return -1.0;
    }

    // Extract formatted counter value
    if (PdhGetFormattedCounterValue(counterHandle, PDH_FMT_DOUBLE, NULL, &valueBuffer) != ERROR_SUCCESS) {
        PdhCloseQuery(queryHandle);
        return -1.0;
    }

    // Cleanup resources
    PdhCloseQuery(queryHandle);

    return valueBuffer.doubleValue;
}

int main() {
    double cpuLoad = AcquireCpuUsage();

    if (cpuLoad >= 0.0) {
        printf("CPU Usage: %.2f%%\n", cpuLoad);
    } else {
        printf("Error retrieving CPU usage information.\n");
    }

    return 0;
}

