// Read CPU statistics from /proc/stat and return the first line's numeric values
std::vector<long> fetchCPUStats() {
    std::ifstream procStat("/proc/stat");
    std::string firstLine;
    std::getline(procStat, firstLine);

    std::istringstream stream(firstLine);
    std::string token;
    std::vector<long> stats;

    // Discard the initial "cpu" identifier
    stream >> token;

    // Extract all remaining numeric fields
    while (stream >> token) {
        stats.push_back(std::stol(token));
    }

    return stats;
}

// Compute CPU usage percentage based on two snapshots
double computeCPULoad(const std::vector<long>& earlier, const std::vector<long>& later) {
    long sumEarlier = 0;
    long sumLater = 0;

    for (size_t idx = 0; idx < earlier.size(); ++idx) {
        sumEarlier += earlier[idx];
        sumLater += later[idx];
    }

    long totalChange = sumLater - sumEarlier;
    long idleChange = later[3] - earlier[3];

    double ratio = static_cast<double>(idleChange) / static_cast<double>(totalChange);
    return (1.0 - ratio) * 100.0;
}

// Display current CPU utilization by sampling twice with a one-second interval
void showCPUUtilization() {
    auto snapshot1 = fetchCPUStats();
    std::this_thread::sleep_for(std::chrono::seconds(1));
    auto snapshot2 = fetchCPUStats();

    double load = computeCPULoad(snapshot1, snapshot2);
    std::cout << "CPU Usage: " << load << "%" << std::endl;
}

