// Transform a 2D vector of doubles into a 2D vector of strings
std::vector<std::vector<std::string>> convertDoubleMatrixToStrings(const std::vector<std::vector<double>>& inputMatrix) {
    std::vector<std::vector<std::string>> outputMatrix;

    for (const auto& row : inputMatrix) {
        std::vector<std::string> stringRow;
        for (double element : row) {
