std::atomic<int> flag1(0);
std::atomic<int> flag2(0);
int result1, result2;

void workerA() {
    flag1.store(1, std::memory_order_seq_cst);
    result1 = flag2.load(std::memory_order_seq_cst);
}

void workerB() {
    flag2.store(1, std::memory_order_seq_cst);
    result2 = flag1.load(std::memory_order_seq_cst);
}

int main() {
    std::thread tA(workerA);
    std::thread tB(workerB);

    tA.join();
    tB.join();

    // At least one thread must have observed the other's store
    assert(result1 != 0 || result2 != 0);
}

