#include <cstdlib>
#include <ctime>

using namespace std;

const int BOARD_DIM = 5;
const int TOTAL_MINES = 5;

class MinesweeperGame {
public:
    MinesweeperGame() {
        srand(time(0));
        initializeGrid();
        computeAdjacentCounts();
    }

    void runGame() {
        while (true) {
            displayGrid();
            int r, c;
            cout << "Enter coordinates to reveal (row and column from 0 to 4): ";
            cin >> r >> c;

            if (r < 0 || r >= BOARD_DIM || c < 0 || c >= BOARD_DIM) {
                cout << "Invalid position. Please try again." << endl;
                continue;
            }

            if (grid[r][c] == -1) {
                cout << "Boom! You landed on a mine. Game over!" << endl;
                showFullGrid();
                break;
            }

            if (grid[r][c] == 0) {
                uncoverSafeCells(r, c);
            } else {
                visible[r][c] = true;
            }

            if (victoryCondition()) {
                cout << "Well done! You cleared the field successfully." << endl;
                showFullGrid();
                break;
            }
        }
    }

private:
    vector<vector<int>> grid;
    vector<vector<bool>> visible;

    void initializeGrid() {
        grid.assign(BOARD_DIM, vector<int>(BOARD_DIM, 0));
        visible.assign(BOARD_DIM, vector<bool>(BOARD_DIM, false));

        int placed = 0;
        while (placed < TOTAL_MINES) {
            int x = rand() % BOARD_DIM;
            int y = rand() % BOARD_DIM;
            if (grid[x][y] != -1) {
                grid[x][y] = -1;
                placed++;
            }
        }
    }

    void computeAdjacentCounts() {
        for (int i = 0; i < BOARD_DIM; ++i) {
            for (int j = 0; j < BOARD_DIM; ++j) {
                if (grid[i][j] == -1) continue;

                int adjacent = 0;
                for (int di = -1; di <= 1; ++di) {
                    for (int dj = -1; dj <= 1; ++dj) {
                        int ni = i + di;
                        int nj = j + dj;
                        if (ni >= 0 && ni < BOARD_DIM && nj >= 0 && nj < BOARD_DIM && grid[ni][nj] == -1) {
                            adjacent++;
                        }
                    }
                }
                grid[i][j] = adjacent;
            }
        }
    }

    void uncoverSafeCells(int row, int col) {
        if (row < 0 || row >= BOARD_DIM || col < 0 || col >= BOARD_DIM || visible[row][col]) {
            return;
        }

        visible[row][col] = true;
        if (grid[row][col] == 0) {
            for (int dr = -1; dr <= 1; ++dr) {
                for (int dc = -1; dc <= 1; ++dc) {
                    uncoverSafeCells(row + dr, col + dc);
                }
            }
        }
    }

    void displayGrid() {
        for (int i = 0; i < BOARD_DIM; ++i) {
            for (int j = 0; j < BOARD_DIM; ++j) {
                if (visible[i][j]) {
                    if (grid[i][j] == -1) {
                        cout << "X ";
                    } else {
                        cout << grid[i][j] << " ";
                    }
                } else {
                    cout << ". ";
                }
            }
            cout << endl;
        }
    }

    void showFullGrid() {
        for (int i = 0; i < BOARD_DIM; ++i) {
            for (int j = 0; j < BOARD_DIM; ++j) {
                if (grid[i][j] == -1) {
                    cout << "X ";
                } else {
                    cout << grid[i][j] << " ";
                }
            }
            cout << endl;
        }
    }

    bool victoryCondition() {
        for (int i = 0; i < BOARD_DIM; ++i) {
            for (int j = 0; j < BOARD_DIM; ++j) {
                if (grid[i][j] != -1 && !visible[i][j]) {
                    return false;
                }
            }
        }
        return true;
    }
};

int main() {
    MinesweeperGame game;
    game.runGame();
    return 0;
}

