// Alternative implementation: manual parsing approach
std::vector<std::string> parseTokens(const std::string &input, char sep) {
    std::vector<std::string> result;
    std::string current;

    for (size_t pos = 0; pos < input.length(); ++pos) {
        if (input[pos] == sep) {
            if (!current.empty()) {
                result.push_back(current);
                current.clear();
            }
        } else {
            current += input[pos];
        }
    }

    // Handle the last token
    if (!current.empty()) {
        result.push_back(current);
    }

    return result;
}

int main() {
    // Repeat the parsing operation many times
    for (int count = 0; count < 10000; ++count) {
        parseTokens("a b c", ' ');
    }
    return 0;
}

