// Load armature data from a JSON file into the 3D scene
void loadArmatureFromJson(const QString &jsonPath, Qt3DCore::QEntity *sceneRoot) {
    QFile jsonFile(jsonPath);
    if (!jsonFile.open(QIODevice::ReadOnly | QIODevice::Text)) {
        qWarning("Could not open the specified JSON file for reading");
        return;
    }

    QByteArray rawData = jsonFile.readAll();
    QJsonDocument document = QJsonDocument::fromJson(rawData);
    if (document.isNull() || !document.isObject()) {
        qWarning("Invalid JSON content in file");
        return;
    }

    QJsonObject rootObj = document.object();

    // Initialize skeleton loader and setup
    Qt3DRender::QSkeleton *skeleton = new Qt3DRender::QSkeleton(sceneRoot);
    Qt3DRender::QSkeletonLoader *loader = new Qt3DRender::QSkeletonLoader(sceneRoot);
    loader->setSource(QUrl::fromLocalFile(jsonPath));
    skeleton->setLoader(loader);

    // Process animation clips defined in JSON
    QJsonArray animList = rootObj.value("animations").toArray();
    for (const QJsonValue &animEntry : animList) {
        if (!animEntry.isObject()) continue;

        QJsonObject animData = animEntry.toObject();
        Qt3DAnimation::QAnimationClip *clip = new Qt3DAnimation::QAnimationClip(sceneRoot);
        clip->setDuration(animData.value("duration").toDouble());
        clip->setLoopCount(animData.value("loopCount").toInt());

        // Handle channel mappings per animation
        QJsonArray channelList = animData.value("channels").toArray();
        for (const QJsonValue &channelEntry : channelList) {
            if (!channelEntry.isObject()) continue;

            QJsonObject channelData = channelEntry.toObject();
            Qt3DAnimation::QChannelMapper *mapper = new Qt3DAnimation::QChannelMapper(sceneRoot);
            mapper->setChannelName(channelData.value("channelName").toString());
            mapper->setBoneName(channelData.value("boneName").toString());

            // Populate keyframes for this channel
            QJsonArray keyframeList = channelData.value("keys").toArray();
            for (const QJsonValue &keyEntry : keyframeList) {
                if (!keyEntry.isObject()) continue;

                QJsonObject keyData = keyEntry.toObject();
                Qt3DAnimation::QKeyframe *keyframe = new Qt3DAnimation::QKeyframe(sceneRoot);

                double t = keyData.value("time").toDouble();
                double tx = keyData.value("translationX").toDouble();
                double ty = keyData.value("translationY").toDouble();
                double tz = keyData.value("translationZ").toDouble();
                double rw = keyData.value("rotationW").toDouble();
                double rx = keyData.value("rotationX").toDouble();
                double ry = keyData.value("rotationY").toDouble();
                double rz = keyData.value("rotationZ").toDouble();
                double sx = keyData.value("scaleX").toDouble();
                double sy = keyData.value("scaleY").toDouble();
                double sz = keyData.value("scaleZ").toDouble();

                keyframe->setTime(t);
                keyframe->setTranslation(QVector3D(tx, ty, tz));
                keyframe->setRotation(QQuaternion(rw, rx, ry, rz));
                keyframe->setScale(QVector3D(sx, sy, sz));

                mapper->addKeyframe(keyframe);
            }

            clip->addChannelMapper(mapper);
        }

        // Attach animator to skeleton
        Qt3DAnimation::QClipAnimator *animator = new Qt3DAnimation::QClipAnimator(sceneRoot);
        animator->setClip(clip);
        animator->setTarget(skeleton);
        sceneRoot->addComponent(animator);
    }
}

