// Helper function for logging (assuming Log is defined elsewhere)
void Log(const char* msg) {
    __android_log_print(ANDROID_LOG_ERROR, "Framebuffer", "%s", msg);
}

// Helper function to load external class (assuming this exists)
jclass loadExternalClass(const char* className) {
    // Implementation would be in JNI utility code
    return nullptr;
}

jobject createBitmapFromFramebuffer(int w, int h) {
    size_t pixelDataSize = static_cast<size_t>(w) * h * 4; // 4 bytes per pixel for GL_RGBA

    // Use smart pointer for automatic memory management
    std::unique_ptr<uint8_t[]> pixelBuffer(new uint8_t[pixelDataSize]);

    glReadPixels(0, 0, w, h, GL_RGBA, GL_UNSIGNED_BYTE, pixelBuffer.get());

    if (!pixelBuffer) {
        Log("Could not allocate pixel buffer");
        return nullptr;
    }

    jobject resultBitmap = nullptr;

    JNIEnv* env = GetEnv(state_->activity->vm);
    if (!env) {
        Log("Failed to get JNIEnv");
        return nullptr;
    }

    // Transfer pixel data to Java byte array
    jbyteArray javaPixelArray = env->NewByteArray(static_cast<jsize>(pixelDataSize));
    if (!javaPixelArray) {
        Log("Failed to create Java byte array");
        return nullptr;
    }

    env->SetByteArrayRegion(javaPixelArray, 0, static_cast<jsize>(pixelDataSize), 
                           reinterpret_cast<jbyte*>(pixelBuffer.get()));

    // Load required classes and methods
    jclass bitmapCls = loadExternalClass("android/graphics/Bitmap");
    if (!bitmapCls) {
        env->DeleteLocalRef(javaPixelArray);
        return nullptr;
    }

    jclass bitmapConfigCls = loadExternalClass("android/graphics/Bitmap$Config");
    if (!bitmapConfigCls) {
        env->DeleteLocalRef(bitmapCls);
        env->DeleteLocalRef(javaPixelArray);
        return nullptr;
    }

    // Get ARGB_8888 configuration
    jfieldID argbFieldID = env->GetStaticFieldID(bitmapConfigCls, "ARGB_8888", 
                                                  "Landroid/graphics/Bitmap$Config;");
    jobject argbConfig = env->GetStaticObjectField(bitmapConfigCls, argbFieldID);

    // Create bitmap with specified dimensions and config
    jmethodID createMethod = env->GetStaticMethodID(bitmapCls, "createBitmap",
                                                    "(IILandroid/graphics/Bitmap$Config;)Landroid/graphics/Bitmap;");
    resultBitmap = env->CallStaticObjectMethod(bitmapCls, createMethod, w, h, argbConfig);

    if (resultBitmap) {
        // Set pixels using native pointer approach
        jmethodID setPixelsMethod = env->GetMethodID(bitmapCls, "setPixels",
                                                     "([IIII)V");
        env->CallVoidMethod(resultBitmap, setPixelsMethod, javaPixelArray, 0, w, 0, h);
    }

    // Clean up local references
    env->DeleteLocalRef(javaPixelArray);
    env->DeleteLocalRef(bitmapCls);
    env->DeleteLocalRef(bitmapConfigCls);

    if (!resultBitmap) {
        Log("Could not create image from framebuffer to share");
    }

    return resultBitmap;
}

#include <iostream>
using namespace std;

// Binary Search Tree Node definition
struct TreeNode {
    int value;
    TreeNode* leftChild;
    TreeNode* rightChild;

    TreeNode(int v) : value(v), leftChild(nullptr), rightChild(nullptr) {}
};

// Binary Search Tree implementation with traversal and deletion
class BinarySearchTree {
public:
    TreeNode* head;

    BinarySearchTree() : head(nullptr) {}

    // Public insert method
    void addValue(int val) {
        head = insertIntoTree(head, val);
    }

    // Public delete method
    void removeValue(int val) {
        head = removeFromTree(head, val);
    }

    // In-order traversal (Left, Root, Right)
    void printInOrder() {
        traverseInOrder(head);
        cout << endl;
    }

    // Pre-order traversal (Root, Left, Right)
    void printPreOrder() {
        traversePreOrder(head);
        cout << endl;
    }

    // Post-order traversal (Left, Right, Root)
    void printPostOrder() {
        traversePostOrder(head);
        cout << endl;
    }

private:
    // Recursive helper to insert a value
    TreeNode* insertIntoTree(TreeNode* node, int val) {
        if (node == nullptr) {
            return new TreeNode(val);
        }

        if (val < node->value) {
            node->leftChild = insertIntoTree(node->leftChild, val);
        } else if (val > node->value) {
            node->rightChild = insertIntoTree(node->rightChild, val);
        }

        return node;
    }

    // Helper to find the minimum value node in a subtree
    TreeNode* findMinNode(TreeNode* node) {
        TreeNode* current = node;
        while (current && current->leftChild != nullptr) {
            current = current->leftChild;
        }
        return current;
    }

    // Recursive helper to delete a value
    TreeNode* removeFromTree(TreeNode* node, int val) {
        if (node == nullptr) {
            return node;
        }

        if (val < node->value) {
            node->leftChild = removeFromTree(node->leftChild, val);
        } else if (val > node->value) {
            node->rightChild = removeFromTree(node->rightChild, val);
        } else {
            // Node with only one child or no child
            if (node->leftChild == nullptr) {
                TreeNode* temp = node->rightChild;
                delete node;
                return temp;
            } else if (node->rightChild == nullptr) {
                TreeNode* temp = node->leftChild;
                delete node;
                return temp;
            }

            // Node with two children: get inorder successor
            TreeNode* temp = findMinNode(node->rightChild);
            node->value = temp->value;
            node->rightChild = removeFromTree(node->rightChild, temp->value);
        }

        return node;
    }

    // In-order traversal helper
    void traverseInOrder(TreeNode* node) {
        if (node != nullptr) {
            traverseInOrder(node->leftChild);
            cout << node->value << " ";
            traverseInOrder(node->rightChild);
        }
    }

    // Pre-order traversal helper
    void traversePreOrder(TreeNode* node) {
        if (node != nullptr) {
            cout << node->value << " ";
            traversePreOrder(node->leftChild);
            traversePreOrder(node->rightChild);
        }
    }

    // Post-order traversal helper
    void traversePostOrder(TreeNode* node) {
        if (node != nullptr) {
            traversePostOrder(node->leftChild);
            traversePostOrder(node->rightChild);
            cout << node->value << " ";
        }
    }
};

int main() {
    BinarySearchTree bst;

    // Insert values into the BST
    bst.addValue(50);
    bst.addValue(30);
    bst.addValue(20);
    bst.addValue(40);
    bst.addValue(70);
    bst.addValue(60);
    bst.addValue(80);

    // Display traversals before deletion
    cout << "Inorder traversal: ";
    bst.printInOrder();

    cout << "Preorder traversal: ";
    bst.printPreOrder();

    cout << "Postorder traversal: ";
    bst.printPostOrder();

    // Delete nodes and show resulting traversals
    cout << "Delete 20: ";
    bst.removeValue(20);
    bst.printInOrder();

    cout << "Delete 30: ";
    bst.removeValue(30);
    bst.printInOrder();

    cout << "Delete 50: ";
    bst.removeValue(50);
    bst.printInOrder();

    return 0;
}

