// Find maximum element in a vector using manual iteration
int find_max(const std::vector<int>& arr) {
    if (arr.empty()) return INT_MIN; // Handle empty array case

    int current_max = arr[0];
    for (size_t index = 1; index < arr.size(); ++index) {
        if (arr[index] > current_max) {
            current_max = arr[index];
        }
    }
    return current_max;
}

// Alternative implementation using standard library algorithm
int find_max_builtin(const std::vector<int>& arr) {
    if (arr.empty()) return INT_MIN;

    auto max_it = std::max_element(arr.begin(), arr.end());
    return *max_it;
}

