// Base class for IR nodes
class IRNode {
public:
    virtual std::string generateAssembly() const = 0;
    virtual ~IRNode() = default;
};

// Constant value node
class ConstantNode : public IRNode {
private:
    int value;

public:
    ConstantNode(int val) : value(val) {}

    std::string generateAssembly() const override {
        return "mov $" + std::to_string(value) + ", %eax\n";
    }
};

// Simple instruction node
class InstructionNode : public IRNode {
private:
    std::string instr;

public:
    InstructionNode(std::string instruction) : instr(instruction) {}

    std::string generateAssembly() const override {
        return instr + "\n";
    }
};

// Block of instructions
class BlockNode : public IRNode {
private:
    std::vector<IRNode*> instructions;

public:
    BlockNode(std::vector<IRNode*> insts) : instructions(insts) {}

    std::string generateAssembly() const override {
        std::string assembly = "";
        for (IRNode* node : instructions) {
            assembly += node->generateAssembly();
        }
        return assembly;
    }
};

// If statement node with proper label handling
class IfNode : public IRNode {
private:
    IRNode* condition;
    IRNode* trueBlock;
    IRNode* falseBlock;
    std::string uniqueLabel;

public:
    IfNode(IRNode* cond, IRNode* tBlock, IRNode* fBlock, std::string label)
        : condition(cond), trueBlock(tBlock), falseBlock(fBlock), uniqueLabel(label) {}

    std::string generateAssembly() const override {
        std::string assembly = "";

        // Generate condition code
        assembly += condition->generateAssembly();

        // Add jump to false block
        assembly += "cmp %eax, %ebx\n";
        assembly += "je .true_" + uniqueLabel + "\n";
        assembly += "jmp .false_" + uniqueLabel + "\n";

        // True block
        assembly += ".true_" + uniqueLabel + ":\n";
        assembly += trueBlock->generateAssembly();
        assembly += "jmp .end_" + uniqueLabel + "\n";

        // False block
        assembly += ".false_" + uniqueLabel + ":\n";
        assembly += falseBlock->generateAssembly();
        assembly += ".end_" + uniqueLabel + ":\n";

        return assembly;
    }
};

// Comparison node with fixed label handling
class ComparisonNode : public IRNode {
private:
    std::string operatorStr;
    IRNode* leftOperand;
    IRNode* rightOperand;
    std::string labelPrefix;

public:
    ComparisonNode(std::string op, IRNode* lhs, IRNode* rhs, std::string label = "")
        : operatorStr(op), leftOperand(lhs), rightOperand(rhs), labelPrefix(label) {}

    std::string generateAssembly() const override {
        std::string assembly = "";

        // Generate left operand
        assembly += leftOperand->generateAssembly();
        assembly += "push %eax\n";

        // Generate right operand
        assembly += rightOperand->generateAssembly();
        assembly += "pop %ebx\n";

        // Compare values
        assembly += "cmp %ebx, %eax\n";

        // Use conditional jump based on operator
        if (operatorStr == "==") {
            assembly += "je .comp_true_" + labelPrefix + "\n";
        } else if (operatorStr == "!=") {
            assembly += "jne .comp_true_" + labelPrefix + "\n";
        } else if (operatorStr == "<") {
            assembly += "jl .comp_true_" + labelPrefix + "\n";
        } else if (operatorStr == ">") {
            assembly += "jg .comp_true_" + labelPrefix + "\n";
        } else {
            assembly += "je .comp_true_" + labelPrefix + "\n";
        }

        assembly += "jmp .comp_false_" + labelPrefix + "\n";
        assembly += ".comp_true_" + labelPrefix + ":\n";
        assembly += "mov $1, %eax\n";
        assembly += "jmp .comp_end_" + labelPrefix + "\n";
        assembly += ".comp_false_" + labelPrefix + ":\n";
        assembly += "mov $0, %eax\n";
        assembly += ".comp_end_" + labelPrefix + ":\n";

        return assembly;
    }
};

// Example usage demonstrating the fixed implementation
int main() {
    IRNode* condition = new ComparisonNode("==", new ConstantNode(5), new ConstantNode(5), "cmp1");
    IRNode* trueBlock = new BlockNode({ new InstructionNode("mov $100, %eax") });
    IRNode* falseBlock = new BlockNode({ new InstructionNode("mov $200, %eax") });

    IfNode* ifNode = new IfNode(condition, trueBlock, falseBlock, "if1");

    std::string assemblyCode = ifNode->generateAssembly();
    std::cout << assemblyCode << std::endl;

    // Clean up allocated memory
    delete condition;
    delete trueBlock;
    delete falseBlock;
    delete ifNode;

    return 0;
}

