#include <algorithm>

using namespace std;

// Function to compute the length of the longest increasing subsequence
int getLISLength(vector<int>& arr) {
    if (arr.empty()) return 0;

    vector<int> minTails;
    for (int val : arr) {
        auto pos = lower_bound(minTails.begin(), minTails.end(), val);
        if (pos == minTails.end()) {
            minTails.push_back(val);
        } else {
            *pos = val;
        }
    }
    return minTails.size();
}

// Function to reconstruct and return the actual longest increasing subsequence
vector<int> retrieveLIS(vector<int>& arr) {
    if (arr.empty()) return {};

    vector<int> tails;
    vector<int> posIndex(arr.size(), -1);
    vector<int> predecessor(arr.size(), -1);

    for (int i = 0; i < arr.size(); ++i) {
        int current = arr[i];
        auto it = lower_bound(tails.begin(), tails.end(), current);
        int position = it - tails.begin();

        if (it == tails.end()) {
            tails.push_back(current);
        } else {
            *it = current;
        }

        posIndex[position] = i;
        if (position > 0) {
            predecessor[i] = posIndex[position - 1];
        }
    }

    vector<int> result;
    int currentIndex = posIndex.back();
    while (currentIndex != -1) {
        result.push_back(arr[currentIndex]);
        currentIndex = predecessor[currentIndex];
    }

    reverse(result.begin(), result.end());
    return result;
}

int main() {
    vector<int> sequence = {10, 9, 2, 5, 3, 7, 101, 18};

    int lisLen = getLISLength(sequence);
    cout << "Length of the longest increasing subsequence: " << lisLen << endl;

    vector<int> lis = retrieveLIS(sequence);
    cout << "The longest increasing subsequence: ";
    for (int value : lis) {
        cout << value << " ";
    }
    cout << endl;

    return 0;
}

