using T = uint32_t; // or uint64_t

T shift(T x, T y, T n)
{
    // Create a mask with the lower n bits set to 1
    T lowerBitsMask = (n == 0) ? T(0) : (T(1) << n) - 1;

    // Extract the lower n bits from y
    T yLowerBits = y & lowerBitsMask;

    // Shift x right by n positions
    T xShifted = x >> n;

    // Shift the extracted bits to the high end of the word
    T bitsAtHighEnd = yLowerBits << (std::numeric_limits<T>::digits - n);

    // Combine the two parts using bitwise OR
    return xShifted | bitsAtHighEnd;
}

