// Monitor changes in a shared variable using atomic operations and polling
void monitor_changes(std::atomic<int>* variable_to_monitor) {
    int previous_value = variable_to_monitor->load();
    while (true) {
        int current_value = variable_to_monitor->load();
        if (current_value != previous_value) {
            std::cout << "Value has changed!" << std::endl;
            previous_value = current_value;
        }
        // Use compiler barrier to prevent optimization and reduce busy-wait overhead
        #ifdef __GNUC__
            __builtin_ia32_pause();
        #else
            _mm_pause(); // Fallback for other compilers
        #endif
    }
}

