// Computes the union of two sorted arrays without duplicates
std::vector<int> computeUnion(const std::vector<int>& input1, const std::vector<int>& input2) {
    std::vector<int> result;
    size_t idx1 = 0, idx2 = 0;

    // Traverse both arrays using two pointers
    while (idx1 < input1.size() && idx2 < input2.size()) {
        if (input1[idx1] < input2[idx2]) {
            if (result.empty() || result.back() != input1[idx1]) {
                result.push_back(input1[idx1]);
            }
            ++idx1;
        } else if (input1[idx1] > input2[idx2]) {
            if (result.empty() || result.back() != input2[idx2]) {
                result.push_back(input2[idx2]);
            }
            ++idx2;
        } else {
            // Elements are equal - add once if not duplicate
            if (result.empty() || result.back() != input1[idx1]) {
                result.push_back(input1[idx1]);
            }
            ++idx1;
            ++idx2;
        }
    }

    // Process leftover elements in first array
    while (idx1 < input1.size()) {
        if (result.empty() || result.back() != input1[idx1]) {
            result.push_back(input1[idx1]);
        }
        ++idx1;
    }

    // Process leftover elements in second array
    while (idx2 < input2.size()) {
        if (result.empty() || result.back() != input2[idx2]) {
            result.push_back(input2[idx2]);
        }
        ++idx2;
    }

    return result;
}

int main() {
    std::vector<int> arr1 = {1, 2, 4, 5, 6};
    std::vector<int> arr2 = {2, 3, 5, 7};

    std::vector<int> unionResult = computeUnion(arr1, arr2);

    std::cout << "Union of the two arrays is: ";
    for (int value : unionResult) {
        std::cout << value << " ";
    }
    std::cout << std::endl;

    return 0;
}

#include <immintrin.h>

// Compute derived attributes using SIMD vector operations
void compute_attributes(float* input_data, float* output_sum, float* output_diff, int count) {
    __m256 vec_x, vec_y, vec_z, vec_res1, vec_res2;

    for (int idx = 0; idx < count; idx += 8) {
        // Load three consecutive components from the input array
        vec_x = _mm256_loadu_ps(&input_data[idx * 3 + 0]);
        vec_y = _mm256_loadu_ps(&input_data[idx * 3 + 1]);
        vec_z = _mm256_loadu_ps(&input_data[idx * 3 + 2]);

        // Compute sum and difference using AVX instructions
        vec_res1 = _mm256_add_ps(vec_x, vec_y);
        vec_res2 = _mm256_sub_ps(vec_x, vec_z);

        // Store results to respective output arrays
        _mm256_storeu_ps(&output_sum[idx], vec_res1);
        _mm256_storeu_ps(&output_diff[idx], vec_res2);
    }
}

