#include <xmmintrin.h>

// Compute dot product of two 4-element vectors using SSE intrinsics
inline __m128 sse_dot4(__m128 a, __m128 b)
{
    // Multiply corresponding elements
    const __m128 product = _mm_mul_ps(a, b);

    // Extract and sum pairs: (0+1) and (2+3)
    const __m128 shuffled1 = _mm_shuffle_ps(product, product, _MM_SHUFFLE(1, 0, 3, 2));
    const __m128 pair_sums = _mm_add_ps(product, shuffled1);

    // Now combine the two partial sums into the first lane
    const __m128 final_sum = _mm_add_ss(pair_sums, _mm_shuffle_ps(pair_sums, pair_sums, _MM_SHUFFLE(0, 0, 1, 0)));

    return final_sum;
}

#include <QCoreApplication>
#include <QTextToSpeech>
#include <QVoice>
#include <iostream>

#include <sapi.h>

int main(int argc, char *argv[])
{
    QCoreApplication app(argc, argv);

    // Initialize COM library
    CoInitialize(NULL);

    ISpVoice *voice = nullptr;
    HRESULT result = CoCreateInstance(CLSID_SpVoice, nullptr, CLSCTX_ALL, 
                                      IID_ISpVoice, reinterpret_cast<void**>(&voice));
    if (FAILED(result)) {
        std::cerr << "Error: Could not initialize SAPI voice engine" << std::endl;
        return -1;
    }

    // List all available system voices
    IEnumSpObjectTokens *tokenEnum = nullptr;
    result = SpEnumTokens(SPCAT_VOICES, nullptr, nullptr, &tokenEnum);
    if (SUCCEEDED(result)) {
        ISpObjectToken *currentToken = nullptr;
        while (tokenEnum->Next(1, &currentToken, nullptr) == S_OK) {
            SPVOICESTATUS voiceStatus;
            if (SUCCEEDED(voice->GetStatus(&voiceStatus, nullptr))) {
                SPVOICECATEGORY cat;
                currentToken->GetCategory(&cat);

                if (cat == SPCAT_VOICES) {
                    BSTR id, desc;
                    currentToken->GetId(&id);
                    currentToken->GetDescription(&desc);

                    std::wcout << L"[Voice] ID: " << id << L", Description: " << desc << std::endl;

                    SysFreeString(id);
                    SysFreeString(desc);
                }
            }
            currentToken->Release();
            currentToken = nullptr;
        }
        tokenEnum->Release();
    }

    // Attempt to select a specific Acapela voice by name
    ISpObjectToken *selectedToken = nullptr;
    result = SpFindBestToken(SPCAT_VOICES, L"Name=Acapela Voice Name", nullptr, &selectedToken);
    if (SUCCEEDED(result)) {
        result = voice->SetVoice(selectedToken);
        if (FAILED(result)) {
            std::cerr << "Warning: Unable to configure selected Acapela voice" << std::endl;
        }
    } else {
        std::cerr << "Notice: Acapela voice with specified name not found in system" << std::endl;
    }

    // Perform speech synthesis
    const wchar_t *text = L"Hello, this is an Acapela voice.";
    result = voice->Speak(text, SPF_DEFAULT, nullptr);
    if (FAILED(result)) {
        std::cerr << "Error: Speech synthesis failed" << std::endl;
    }

    // Release resources properly
    if (selectedToken) selectedToken->Release();
    if (voice) voice->Release();
    CoUninitialize();

    return app.exec();
}

