// Ensure structure is packed to 1-byte alignment
#pragma pack(push, 1)
struct A {
    unsigned short a;
    unsigned short b;

    // Constructor prints message on creation
    explicit A() {
        std::printf("construct\n");
    }

    // Destructor prints message on destruction
    ~A() {
        std::printf("destruct\n");
    }
};
#pragma pack(pop)

// Compile-time check that size of A is exactly 4 bytes
static_assert(sizeof(A) == 4, "sizeof(A) != 4");

// Function f with __cdecl calling convention
// Takes int, reference to A, and two more ints as parameters
A __cdecl f(int p1, A& p2, int p3, int p4) {
    // Print parameter values in hexadecimal format
    std::printf("%08X %08X %08X %08X\n", p1, p2.a, p3, p4);
    return p2;
}

int main() {
    // Create instance of A (triggers constructor)
    A a;

    // Inline assembly block for x86 architecture
    __asm {
        // Push arguments in reverse order (right-to-left)
        push 4          // p4 = 4
        push 3          // p3 = 3
        lea eax, a      // Load address of 'a' into eax register
        push eax        // Push address of 'a' (p2 parameter)
        push 1          // p1 = 1
        call f          // Call function f
    }

    // Return 0 (program exit normally)
    return 0;
}

