#include <iostream>
#include <functional>

// RAII-style cleanup helper that executes a lambda on scope exit
class ScopeGuard {
    std::function<void()> cleanupAction_;

public:
    explicit ScopeGuard(std::function<void()> action) : cleanupAction_(std::move(action)) {}

    ~ScopeGuard() {
        if (cleanupAction_) {
            cleanupAction_();
        }
    }

    // Disable copy and move operations to prevent double execution
    ScopeGuard(const ScopeGuard&) = delete;
    ScopeGuard& operator=(const ScopeGuard&) = delete;
    ScopeGuard(ScopeGuard&&) = delete;
    ScopeGuard& operator=(ScopeGuard&&) = delete;
};

int main() {
    ScopeGuard first_guard([](){ std::cout << "world!"; });
    ScopeGuard second_guard([](){ std::cout << "Hello, "; });

    // Early return condition - guard destructors still run due to RAII
    if (2 == 2) {
        return -1;
    }

    // This will never execute due to early return above
    ScopeGuard unused_guard([](){ std::cout << "Blam"; });

    return 0;
}

