int main() {
    int decimalNumber = 10;
    std::string binaryString = "";

    // Convert decimal to binary manually
    if (decimalNumber == 0) {
        binaryString = "0";
    } else {
        int temp = decimalNumber;
        while (temp > 0) {
            binaryString = (temp % 2 == 0 ? "0" : "1") + binaryString;
            temp /= 2;
        }
    }

    std::cout << binaryString << std::endl;  // Output: 1010
    return 0;
}

#include <iostream>
#include <chrono>

// Initialize 3D array using manual loop control with inline assembly
void asm_version(int ia_array[5][5][5]) {
    int i = 0, j = 0, k = 0;

    while (i < 5) {
        // Set current element to zero
        ia_array[i][j][k] = 0;

        // Increment k using inline assembly
        __asm {
            inc k
        }

        // Handle k overflow: reset k and increment j
        if (k > 4) {
            __asm {
                inc j
                mov k, 0
            }
        }

        // Handle j overflow: reset j and increment i
        if (j > 4) {
            __asm {
                inc i
                mov j, 0
            }
        }
    }
}

// Initialize 3D array using nested for loops
void optimized_loop_version(int ia_array[5][5][5]) {
    for (int i = 0; i < 5; ++i) {
        for (int j = 0; j < 5; ++j) {
            for (int k = 0; k < 5; ++k) {
                ia_array[i][j][k] = 0;
            }
        }
    }
}

int main() {
    // Declare two identical 3D arrays for testing
    int ia_array1[5][5][5];
    int ia_array2[5][5][5];

    // Measure execution time for the assembly version
    auto start1 = std::chrono::high_resolution_clock::now();
    asm_version(ia_array1);
    auto end1 = std::chrono::high_resolution_clock::now();
    auto duration1 = std::chrono::duration_cast<std::chrono::microseconds>(end1 - start1);

    // Measure execution time for the loop version
    auto start2 = std::chrono::high_resolution_clock::now();
    optimized_loop_version(ia_array2);
    auto end2 = std::chrono::high_resolution_clock::now();
    auto duration2 = std::chrono::duration_cast<std::chrono::microseconds>(end2 - start2);

    // Output timing results
    std::cout << "ASM version took: " << duration1.count() << " microseconds" << std::endl;
    std::cout << "Loop version took: " << duration2.count() << " microseconds" << std::endl;

    return 0;
}

