#include <iostream>
#include <map>
#include <sstream>
#include <string>

std::map<std::string, std::string> extractDictEntries(const std::string &input) {
    std::map<std::string, std::string> result;

    // Locate the dictionary content between braces
    size_t begin = input.find('{');
    size_t finish = input.rfind('}');
    std::string content = input.substr(begin + 1, finish - begin - 1);

    // Process each key-value pair separated by commas
    std::stringstream stream(content);
    std::string segment;

    while (std::getline(stream, segment, ',')) {
        // Find the colon separating key and value
        size_t separator = segment.find(':');
        if (separator == std::string::npos) continue;

        std::string rawKey = segment.substr(0, separator);
        std::string rawValue = segment.substr(separator + 1);

        // Trim whitespace and quotes from key
        size_t keyStart = rawKey.find_first_not_of(" '\"");
        size_t keyEnd = rawKey.find_last_not_of(" '\"");
        if (keyStart != std::string::npos && keyEnd != std::string::npos) {
            rawKey = rawKey.substr(keyStart, keyEnd - keyStart + 1);
        }

        // Trim whitespace and quotes from value
        size_t valStart = rawValue.find_first_not_of(" '\"");
        size_t valEnd = rawValue.find_last_not_of(" '\"");
        if (valStart != std::string::npos && valEnd != std::string::npos) {
            rawValue = rawValue.substr(valStart, valEnd - valStart + 1);
        }

        result[rawKey] = rawValue;
    }

    return result;
}

int main() {
    std::string pythonStyleDict = "{'item1': 1, 'item2': 2.0, 'item3': 'a string', 'item4': 'another string'}";

    std::map<std::string, std::string> extractedData = extractDictEntries(pythonStyleDict);

    for (const auto &entry : extractedData) {
        std::cout << entry.first << ": " << entry.second << std::endl;
    }

    return 0;
}

