template <typename T, typename ValueT>
class Enum {
public:
    static std::vector<T>& getInstances() {
        static std::vector<T> instances;
        return instances;
    }

    static T fromName(const std::string& name) {
        for (const auto& instance : getInstances()) {
            if (instance.getName() == name) {
                return instance;
            }
        }
        throw std::invalid_argument("No enum value with name: " + name);
    }

    static T fromValue(const ValueT& val) {
        for (const auto& enumInstance : getInstances()) {
            if (enumInstance.getValue() == val) {
                return enumInstance;
            }
        }
        throw std::invalid_argument("No enum value with value: " + std::to_string(val));
    }

    std::string getName() const {
        return name;
    }

    ValueT getValue() const {
        return value;
    }

    bool operator==(const T& other) const {
        return name == other.name && value == other.value;
    }

    bool operator!=(const T& other) const {
        return !(*this == other);
    }

protected:
    Enum(const std::string& n, const ValueT& v) : name(n), value(v) {
        getInstances().push_back(static_cast<T>(*this));
    }

private:
    std::string name;
    ValueT value;
};

