// Write data using non-temporal hints to bypass cache
void writeStream_128B(void* buffer, long iterations) {
    __m128i zmm0 = _mm_setzero_si128();
    __m128i zmm1 = _mm_setzero_si128();
    __m128i zmm2 = _mm_setzero_si128();
    __m128i zmm3 = _mm_setzero_si128();
    __m128i zmm4 = _mm_setzero_si128();
    __m128i zmm5 = _mm_setzero_si128();
    __m128i zmm6 = _mm_setzero_si128();
    __m128i zmm7 = _mm_setzero_si128();

    char* dst = static_cast<char*>(buffer);
    for (long idx = 0; idx < iterations; ++idx) {
        _mm_stream_si128(reinterpret_cast<__m128i*>(dst + 0 * 16), zmm0);
        _mm_stream_si128(reinterpret_cast<__m128i*>(dst + 1 * 16), zmm1);
        _mm_stream_si128(reinterpret_cast<__m128i*>(dst + 2 * 16), zmm2);
        _mm_stream_si128(reinterpret_cast<__m128i*>(dst + 3 * 16), zmm3);
        _mm_stream_si128(reinterpret_cast<__m128i*>(dst + 4 * 16), zmm4);
        _mm_stream_si128(reinterpret_cast<__m128i*>(dst + 5 * 16), zmm5);
        _mm_stream_si128(reinterpret_cast<__m128i*>(dst + 6 * 16), zmm6);
        _mm_stream_si128(reinterpret_cast<__m128i*>(dst + 7 * 16), zmm7);
        dst += 128;
    }
}

int main() {
    uint64_t startTick, endTick;
    const long totalBytes = 32 * KByte;
    const long chunkCount = totalBytes / 128;

    // Allocate aligned memory
    char* buffer = static_cast<char*>(_mm_malloc(totalBytes, 16));

    // Start timing
    startTick = getTicks();
    writeStream_128B(buffer, chunkCount);
    endTick = getTicks();

    // Compute metrics
    double elapsedSeconds = static_cast<double>(endTick - startTick) / getCpuFrequency();
    double speedMBps = static_cast<double>(totalBytes) / elapsedSeconds / MByte;

    std::cout << "Time WRITE_128 [seconds]: " << elapsedSeconds << std::endl;
    std::cout << "Write Speed [MB/s]: " << speedMBps << std::endl;

    _mm_free(buffer);
    return 0;
}

