// Helper function to duplicate a C-string safely
static char* DuplicateCString(const char* src)
{
    if (!src) return nullptr;
    size_t len = 0;
    const char* p = src;
    while (*p++) ++len;
    char* dst = new char[len + 1];
    for (size_t i = 0; i <= len; ++i)
        dst[i] = src[i];
    return dst;
}

