// Compute the average of a list of numbers
double computeAverage(const std::vector<double>& values) {
    if (values.empty()) {
        return 0.0;
    }
    double total = 0.0;
    for (size_t index = 0; index < values.size(); ++index) {
        total += values[index];
    }
    return total / static_cast<double>(values.size());
}

