#include <cstdio>
#include <algorithm>

#define FOR(i, a, b) for (int i = (a); i < (b); ++i)

using namespace std;

const int INF = 1000000000;
typedef long long LL;

const int MAXN = 1000000;

int weights[MAXN];
int original[MAXN];
int permutation[MAXN];
bool visited[MAXN];

int globalMinWeight = INF;

int main() {
    int N;
    scanf("%d", &N);

    // Read weights and find the minimum weight across all elements
    FOR(i, 0, N) {
        scanf("%d", &weights[i]);
        globalMinWeight = min(globalMinWeight, weights[i]);
    }

    // Read original sequence and convert to 0-based indexing
    FOR(i, 0, N) {
        scanf("%d", &original[i]);
        --original[i];
    }

    // Build permutation mapping: perm[read_value] = original[i]
    FOR(i, 0, N) {
        int value;
        scanf("%d", &value);
        --value;
        permutation[value] = original[i];
    }

    LL result = 0;

    // Process each cycle in the permutation
    FOR(start, 0, N) {
        if (!visited[start]) {
            int currentMin = INF;
            LL cycleSum = 0;
            int current = start;
            int cycleLength = 0;

            // Traverse the cycle
            do {
                currentMin = min(currentMin, weights[current]);
                cycleSum += weights[current];
                visited[current] = true;
                current = permutation[current];
                ++cycleLength;
            } while (current != start);

            // Calculate two possible strategies:
            // Strategy 1: Use internal minimum for the cycle
            // Strategy 2: Bring in global minimum for potentially better cost
            LL strategy1 = cycleSum + (cycleLength - 2) * (LL)currentMin;
            LL strategy2 = cycleSum + currentMin + (cycleLength + 1) * (LL)globalMinWeight;

            result += min(strategy1, strategy2);
        }
    }

    printf("%lld\n", result);
    return 0;
}

