// Helper to check if a method is virtual and print its name
void inspectVirtualMethod(const CXXMethodDecl *method) {
    if (method && method->isVirtual()) {
        llvm::outs() << "Virtual function: " << method->getNameAsString() << "\n";
    }
}

// Custom visitor that walks through declarations recursively
class VirtualFunctionInspector : public RecursiveASTVisitor<VirtualFunctionInspector> {
public:
    explicit VirtualFunctionInspector(ASTContext &ctx) : ctxRef(ctx) {}

    // Override traversal for CXXMethodDecl nodes
    bool TraverseCXXMethodDecl(CXXMethodDecl *method) {
        if (!method) return true;
        inspectVirtualMethod(method);
        // Continue with default traversal
        return RecursiveASTVisitor<VirtualFunctionInspector>::TraverseCXXMethodDecl(method);
    }

private:
    ASTContext &ctxRef;
};

// AST consumer responsible for initiating the analysis on the translation unit
class VTableAnalysisConsumer : public ASTConsumer {
public:
    explicit VTableAnalysisConsumer(ASTContext &ctx) : inspector(ctx) {}

    void HandleTranslationUnit(ASTContext &context) override {
        Decl *root = context.getTranslationUnitDecl();
        if (root) {
            inspector.TraverseDecl(root);
        }
    }

private:
    VirtualFunctionInspector inspector;
};

// Frontend action factory — creates a new consumer per file
class VTableAnalysisAction : public ASTFrontendAction {
public:
    std::unique_ptr<ASTConsumer> CreateASTConsumer(CompilerInstance &CI, StringRef inputFile) override {
        return std::make_unique<VTableAnalysisAction::WrappedConsumer>(CI.getASTContext());
    }

private:
    class WrappedConsumer : public ASTConsumer {
    public:
        explicit WrappedConsumer(ASTContext &ctx) : consumer(ctx) {}
        void HandleTranslationUnit(ASTContext &ctx) override {
            consumer.HandleTranslationUnit(ctx);
        }
    private:
        VTableAnalysisConsumer consumer;
    };
};

