    CommonOptionsParser parser(argc, argv, "vtable-inspector");
    ClangTool tool(parser.getCompilations(), parser.getSourcePathList());
    auto factory = newFrontendActionFactory<VTableAnalysisAction>();
    return tool.run(factory.get());
}

