// 2D Vector class with basic operations
class Vector2D {
public:
    // Constructor with default values
    Vector2D(double xVal = 0.0, double yVal = 0.0) : xPos(xVal), yPos(yVal) {}

    // Getters for accessing private members
    double getXPos() const { return xPos; }
    double getYPos() const { return yPos; }

    // Setters to modify vector components
    void setXPos(double newX) { xPos = newX; }
    void setYPos(double newY) { yPos = newY; }

    // Overloaded addition operator
    Vector2D operator+(const Vector2D& rhs) const {
        return Vector2D(xPos + rhs.xPos, yPos + rhs.yPos);
    }

    // Overloaded subtraction operator
    Vector2D operator-(const Vector2D& rhs) const {
        return Vector2D(xPos - rhs.xPos, yPos - rhs.yPos);
    }

    // Scalar multiplication
    Vector2D operator*(double factor) const {
        return Vector2D(xPos * factor, yPos * factor);
    }

    // Compute dot product with another vector
    double dotProduct(const Vector2D& other) const {
        return xPos * other.xPos + yPos * other.yPos;
    }

    // Calculate the Euclidean norm (length)
    double length() const {
        return std::sqrt(xPos * xPos + yPos * yPos);
    }

    // Return unit vector in same direction
    Vector2D unitVector() const {
        double len = length();
        if (len > 0.0) {
            return Vector2D(xPos / len, yPos / len);
        }
        return *this; // Preserve zero vector
    }

private:
    double xPos, yPos;
};

// Utility function to display vector contents
void showVector(const Vector2D& vec) {
    std::cout << "Vector: (" << vec.getXPos() << ", " << vec.getYPos() << ")" << std::endl;
}

int main() {
    Vector2D a(3.0, 4.0);
    Vector2D b(1.0, 2.0);

    Vector2D sumVec = a + b;
    Vector2D diffVec = a - b;
    Vector2D scaledVec = a * 2.0;
    double innerProduct = a.dotProduct(b);
    double normA = a.length();
    Vector2D unitA = a.unitVector();

    showVector(a);
    showVector(b);
    showVector(sumVec);   // a + b
    showVector(diffVec);  // a - b
    showVector(scaledVec); // a * 2.0
    std::cout << "Dot Product: " << innerProduct << std::endl;
    std::cout << "Magnitude: " << normA << std::endl;
    showVector(unitA);

    return 0;
}

#include <arm_neon.h>

void my_function(uint32_t *src, uint32_t *dst) {
    // Load the source data as uint32_t vector
    uint32x4_t input = vld1q_u32(src);

    // Extract individual 32-bit elements
    uint32_t a = vgetq_lane_u32(input, 0);
    uint32_t b = vgetq_lane_u32(input, 1);
    uint32_t c = vgetq_lane_u32(input, 2);
    uint32_t d = vgetq_lane_u32(input, 3);

    // Byte-swap each 32-bit value using bit manipulation
    a = ((a & 0x000000FF) << 24) | ((a & 0x0000FF00) << 8) | 
        ((a & 0x00FF0000) >> 8) | ((a & 0xFF000000) >> 24);
    b = ((b & 0x000000FF) << 24) | ((b & 0x0000FF00) << 8) | 
        ((b & 0x00FF0000) >> 8) | ((b & 0xFF000000) >> 24);
    c = ((c & 0x000000FF) << 24) | ((c & 0x0000FF00) << 8) | 
        ((c & 0x00FF0000) >> 8) | ((c & 0xFF000000) >> 24);
    d = ((d & 0x000000FF) << 24) | ((d & 0x0000FF00) << 8) | 
        ((d & 0x00FF0000) >> 8) | ((d & 0xFF000000) >> 24);

    // Store the results back
    dst[0] = a;
    dst[1] = b;
    dst[2] = c;
    dst[3] = d;
}

