#include <iostream>
#include <string>
#include <vector>
#include <iterator>

class FileStructGenerator {
public:
    class Iterator {
    public:
        using value_type = std::string;
        using reference = std::string&;
        using pointer = std::string*;
        using difference_type = std::ptrdiff_t;
        using iterator_category = std::input_iterator_tag;

        Iterator(FileStructGenerator& gen, bool at_end = false) : generator_(gen), is_ended_(at_end) {
            if (!is_ended_) {
                fetch_next();
            }
        }

        Iterator& operator++() {
            if (!is_ended_) {
                fetch_next();
            }
            return *this;
        }

        Iterator operator++(int) {
            Iterator previous = *this;
            ++(*this);
            return previous;
        }

        bool operator==(const Iterator& rhs) const {
            return is_ended_ == rhs.is_ended_;
        }

        bool operator!=(const Iterator& rhs) const {
            return !(*this == rhs);
        }

        const std::string& operator*() const {
            return current_value_;
        }

        const std::string* operator->() const {
            return &current_value_;
        }

    private:
        void fetch_next() {
            current_value_ = generator_.produce_next();
        }

        FileStructGenerator& generator_;
        std::string current_value_;
        bool is_ended_;
    };

    FileStructGenerator(const std::string& path) : file_path_(path), 
        skip_count_(path.find("more") != std::string::npos ? 5 : 6),
        state_counter_(0) {}

    Iterator begin() {
        return Iterator(*this);
    }

    Iterator end() {
        return Iterator(*this, true);
    }

private:
    std::string file_path_;
    int skip_count_;
    int state_counter_;

    std::string produce_next() {
        switch (state_counter_) {
            case 0:
                state_counter_ = 1;
                return "data";
            case 1:
                for (int index = 0; index < skip_count_; ++index) {
                    state_counter_++;
                    return "unused";
                }
                state_counter_ = skip_count_ + 1;
                // Continue to next case
            case skip_count_ + 1:
                state_counter_++;
                return "data";
            default:
                return "data"; // Continues indefinitely like Python's while True loop
        }
    }
};

// Demonstration usage
int main() {
    FileStructGenerator generator("sample_more.txt");

    for (const auto& item : generator) {
        std::cout << item << std::endl;
    }

    return 0;
}

#include <iostream>
using namespace std;

// Definition for singly-linked list node
struct Node {
    int data;
    Node* link;
    Node(int x) : data(x), link(nullptr) {}
};

// Function to check if a cycle exists in the linked list
bool detectLoop(Node* start) {
    // Handle empty list or single node without cycle
    if (start == nullptr || start->link == nullptr) {
        return false;
    }

    Node* runner = start;   // Fast pointer (moves 2 steps)
    Node* walker = start;   // Slow pointer (moves 1 step)

    // Traverse until fast pointer reaches end
    while (runner != nullptr && runner->link != nullptr) {
        walker = walker->link;          // Advance slow pointer by one
        runner = runner->link->link;    // Advance fast pointer by two

        // If pointers meet, loop detected
        if (walker == runner) {
            return true;
        }
    }

    return false;  // No loop found
}

// Helper function to build a test linked list with a cycle
Node* generateTestList() {
    Node* head = new Node(10);
    Node* node2 = new Node(20);
    Node* node3 = new Node(30);
    Node* node4 = new Node(40);

    head->link = node2;
    node2->link = node3;
    node3->link = node4;
    node4->link = node2;  // Create cycle back to second node

    return head;
}

// Entry point for testing cycle detection
int main() {
    Node* listHead = generateTestList();

    if (detectLoop(listHead)) {
        cout << "Cycle found in the linked structure." << endl;
    } else {
        cout << "No cycle present in the linked structure." << endl;
    }

    return 0;
}

