// Continuously monitor a memory location for changes
void watch_for_modifications(int* target_address) {
    int previous = *target_address;
    while (true) {
        int current = *target_address;
        if (current != previous) {
            std::printf("detected change in value!\n");
            previous = current;
        }
        _mm_pause(); // Provide hint to the processor that we are in a spin-wait loop
    }
}

