#include <iostream>
#include <vector>
#include <cmath>
#include <random>
#include <limits>

// Configuration constants for the reinforcement learning setup
const int STATE_COUNT = 5;
const int ACTION_COUNT = 2;
const double ALPHA = 0.1;           // Learning rate
const double GAMMA = 0.9;           // Discount factor
const double EPSILON = 0.1;         // Exploration rate
const int TRAINING_ROUNDS = 1000;

// Q-value table initialized to zeros
std::vector<std::vector<double>> Q_TABLE(STATE_COUNT, std::vector<double>(ACTION_COUNT, 0.0));

// Simulate environment transition and reward
std::pair<int, double> simulate_environment(int current_state, int selected_action) {
    int next_position = current_state + selected_action;
    double obtained_reward = 0.0;

    if (next_position < 0 || next_position >= STATE_COUNT) {
        next_position = current_state;
        obtained_reward = -1.0;
    } else if (next_position == STATE_COUNT - 1) {
        obtained_reward = 10.0;
    }

    return {next_position, obtained_reward};
}

// Select action using epsilon-greedy strategy
int select_policy_action(int observed_state) {
    static std::random_device device;
    static std::mt19937 engine(device());
    static std::uniform_real_distribution<> probability_dist(0.0, 1.0);

    if (probability_dist(engine) < EPSILON) {
        // Random exploration
        std::uniform_int_distribution<> random_action(0, ACTION_COUNT - 1);
        return random_action(engine);
    } else {
        // Greedy exploitation: find best action based on current Q-values
        double optimal_value = -std::numeric_limits<double>::max();
        int optimal_action = 0;

        for (int possible_action = 0; possible_action < ACTION_COUNT; ++possible_action) {
            if (Q_TABLE[observed_state][possible_action] > optimal_value) {
                optimal_value = Q_TABLE[observed_state][possible_action];
                optimal_action = possible_action;
            }
        }
        return optimal_action;
    }
}

// Main Q-learning training loop
void train_agent() {
    for (int iteration = 0; iteration < TRAINING_ROUNDS; ++iteration) {
        int current_state = 0;  // Starting state

        while (current_state != STATE_COUNT - 1) {
            int chosen_action = select_policy_action(current_state);
            auto [new_state, immediate_reward] = simulate_environment(current_state, chosen_action);

            // Find maximum Q-value for the next state
            double future_max_q = -std::numeric_limits<double>::max();
            for (int future_action = 0; future_action < ACTION_COUNT; ++future_action) {
                if (Q_TABLE[new_state][future_action] > future_max_q) {
                    future_max_q = Q_TABLE[new_state][future_action];
                }
            }

            // Update Q-value using Bellman equation
            Q_TABLE[current_state][chosen_action] += ALPHA * 
                (immediate_reward + GAMMA * future_max_q - Q_TABLE[current_state][chosen_action]);

            current_state = new_state;
        }
    }
}

// Display the learned Q-table
void display_q_values() {
    for (int position = 0; position < STATE_COUNT; ++position) {
        for (int move = 0; move < ACTION_COUNT; ++move) {
            std::cout << "Q[" << position << "][" << move << "] = " 
                      << Q_TABLE[position][move] << std::endl;
        }
    }
}

int main() {
    train_agent();
    display_q_values();
    return 0;
}

