    ShowWindow(hWnd, nShowCmd);
    UpdateWindow(hWnd);

    // Add icon to system tray
    RegisterTrayIcon(hWnd);

    // Message loop
    MSG message;
    while (GetMessage(&message, NULL, 0, 0)) {
        TranslateMessage(&message);
        DispatchMessage(&message);
    }

    return static_cast<int>(message.wParam);
}

// Window procedure handling messages
LRESULT CALLBACK MainWndProc(HWND hWnd, UINT uMsg, WPARAM wParam, LPARAM lParam) {
    switch (uMsg) {
        case WM_TRAYICON:
            if (lParam == WM_LBUTTONDBLCLK) {
                // Respond to double-click on tray icon
                MessageBox(hWnd, "Tray icon double-clicked!", "System Tray Demo", MB_OK | MB_ICONINFORMATION);
                ShowWindow(hWnd, SW_SHOW);
            } else if (lParam == WM_RBUTTONDOWN) {
                // Optional: right-click behavior
                POINT pt;
                GetCursorPos(&pt);
                // Could show context menu here
            }
            return 0;

        case WM_DESTROY:
            Shell_NotifyIcon(NIM_DELETE, reinterpret_cast<NOTIFYICONDATA*>(&hWnd)); // Clean up icon
            PostQuitMessage(0);
            return 0;

        default:
            return DefWindowProc(hWnd, uMsg, wParam, lParam);
    }
}

// Adds the application icon to the system tray
void RegisterTrayIcon(HWND hwnd) {
    NOTIFYICONDATA nid = {};
    nid.cbSize = sizeof(NOTIFYICONDATA);
    nid.hWnd = hwnd;
    nid.uID = 1001;
    nid.uFlags = NIF_ICON | NIF_MESSAGE | NIF_TIP;
    nid.uCallbackMessage = WM_TRAYICON;
    nid.hIcon = LoadIcon(NULL, IDI_APPLICATION);
    lstrcpy(nid.szTip, L"System Tray Demo");
