    {'R', 'N', 'B', 'Q', 'K', 'B', 'N', 'R'},
    {'P', 'P', 'P', 'P', 'P', 'P', 'P', 'P'},
    {' ', '.', ' ', '.', ' ', '.', ' ', '.'},
    {'.', ' ', '.', ' ', '.', ' ', '.', ' '},
    {' ', '.', ' ', '.', ' ', '.', ' ', '.'},
    {'.', ' ', '.', ' ', '.', ' ', '.', ' '},
    {'p', 'p', 'p', 'p', 'p', 'p', 'p', 'p'},
    {'r', 'n', 'b', 'q', 'k', 'b', 'n', 'r'}
};

void displayBoard();
bool isValidMove(int startX, int startY, int endX, int endY);
void executeMove(int startX, int startY, int endX, int endY);
bool checkStatus(bool isWhiteTurn);
bool checkmateDetected(bool isWhiteTurn);
bool stalemateDetected(bool isWhiteTurn);
bool gameOverCondition(bool isWhiteTurn);

// Display the current state of the chessboard
void displayBoard() {
    cout << endl << "   a  b  c  d  e  f  g  h" << endl;
    for (int row = 0; row < 8; ++row) {
        cout << row + 1 << "  ";
        for (int col = 0; col < 8; ++col) {
            cout << chessGrid[row][col] << "  ";
        }
        cout << row + 1 << endl;
    }
    cout << "   a  b  c  d  e  f  g  h" << endl << endl;
}

// Execute a move if it's valid
void executeMove(int startX, int startY, int endX, int endY) {
    if (isValidMove(startX, startY, endX, endY)) {
        char temp = chessGrid[startX][startY];
        chessGrid[startX][startY] = chessGrid[endX][endY];
        chessGrid[endX][endY] = temp;
    }
}

int main() {
    bool whiteTurn = true;

    while (!gameOverCondition(whiteTurn)) {
        displayBoard();
        cout << "Current turn: " << ((whiteTurn) ? "White" : "Black") << endl;

        bool moveConfirmed = false;
        while (!moveConfirmed) {
            string input;
            cout << "Enter your move (e.g., e2e4): ";
            getline(cin, input);

            if (input.length() == 4) {
                int startX = input[0] - 'a';
                int startY = input[1] - '1';
                int endX = input[2] - 'a';
                int endY = input[3] - '1';

                // Validate piece ownership and move legality
                bool pieceBelongsToCurrentPlayer = (isupper(input[0]) == whiteTurn);
                if (isValidMove(startX, startY, endX, endY) && pieceBelongsToCurrentPlayer) {
                    executeMove(startX, startY, endX, endY);
                    moveConfirmed = true;
                }
            }

            if (!moveConfirmed) {
                cout << "Invalid move. Please try again." << endl;
            }
        }

        whiteTurn = !whiteTurn;
    }

    displayBoard();

    // Determine game outcome
    if (checkmateDetected(!whiteTurn)) {
        cout << ((whiteTurn) ? "Black" : "White") << " wins by checkmate!" << endl;
    } else if (stalemateDetected(!whiteTurn)) {
        cout << "Game ends in a draw due to stalemate." << endl;
    }

    return 0;
}

