// Determine whether a number is prime using optimized trial division
bool checkPrime(int value) {
    // Handle edge cases: numbers less than 2 are not prime
    if (value < 2) return false;

    // Special handling for small primes 2 and 3
    if (value == 2 || value == 3) return true;

    // Eliminate multiples of 2 and 3 early
    if (value % 2 == 0 || value % 3 == 0) return false;

    // Check divisors of the form 6k ± 1 up to sqrt(value)
    int limit = static_cast<int>(std::sqrt(value));
    for (int divisor = 5; divisor <= limit; divisor += 6) {
        if (value % divisor == 0 || value % (divisor + 2) == 0) {
            return false;
        }
    }
    return true;
}

int main() {
    std::cout << "Prime numbers less than 100 are: " << std::endl;

    int currentNumber = 2;
    while (currentNumber < 100) {
        if (checkPrime(currentNumber)) {
            std::cout << currentNumber << " ";
        }
        currentNumber++;
    }

    std::cout << std::endl;
    return 0;
}

