using namespace std;

int main() {
    long long n, m, k;
    cin.sync_with_stdio(false);
    cin >> n >> m >> k;

    long long currentSum = 0, minWindowSum = 0;
    long long leftIndex = 1, rightIndex = m;

    queue<long long> windowQueue;

    for (long long pos = 1; pos <= n; pos++) {
        long long value;
        cin >> value;
        currentSum += value;
        windowQueue.push(value);

        if (pos >= m) {
            if (pos > m) {
                currentSum -= windowQueue.front();
                windowQueue.pop();
            }

            if (currentSum < minWindowSum || pos == m) {
                minWindowSum = currentSum;
                leftIndex = pos - m + 1;
                rightIndex = pos;
            }
        }
    }

    cout << leftIndex << " " << rightIndex << endl;

    return 0;
}

