#include <cuda_runtime.h>

// Texture reference for 2D float texture data
texture<float, 2, cudaReadModeElementType> tex;

// Kernel function to copy texture data to output array
__global__ void processTexture(float *dest, int cols, int rows) {
    // Calculate global thread coordinates
    int col = blockIdx.x * blockDim.x + threadIdx.x;
    int row = blockIdx.y * blockDim.y + threadIdx.y;

    // Ensure we are within bounds of the image
    if (col < cols && row < rows) {
        // Read from texture at (col, row) and store in output array
        dest[row * cols + col] = tex2D(tex, col, row);
    }
}

int main() {
    float *deviceBuffer;
    int totalElements = width * height;

    // Allocate memory on device
    cudaMalloc(&deviceBuffer, totalElements * sizeof(float));

    // Copy input data from host to device
    cudaMemcpy(deviceBuffer, h_data, totalElements * sizeof(float), cudaMemcpyHostToDevice);

    // Create channel descriptor for float type
    cudaChannelFormatDesc desc = cudaCreateChannelDesc<float>();

    // Bind 2D texture to device memory
    cudaBindTexture2D(0, &tex, deviceBuffer, &desc, width, height, width * sizeof(float));

    // Define block and grid dimensions for kernel launch
    dim3 threadsPerBlock(16, 16);
    dim3 numBlocks((width + threadsPerBlock.x - 1) / threadsPerBlock.x,
                   (height + threadsPerBlock.y - 1) / threadsPerBlock.y);

    // Launch kernel
    processTexture<<<numBlocks, threadsPerBlock>>>(deviceBuffer, width, height);

    // Cleanup: unbind texture and free device memory
    cudaUnbindTexture(tex);
    cudaFree(deviceBuffer);

    return 0;
}

#include <iostream>

// Evaluate polynomial using Horner's method for efficiency
float Polynomial(int degree, const int coefficients[], float value) 
{   
    if (degree < 0) return 0.0f;

    float result = 0.0f;
    float power_of_x = 1.0f;

    // Accumulate terms from lowest to highest degree
    for (int index = 0; index <= degree; index++) {
        result += coefficients[index] * power_of_x;
        power_of_x *= value;  // Update to next power of x
    }

    return result;
}

