unsigned int buildShaderProgram(const char* vsPath, const char* fsPath);
void constructCylinderMesh(float r, float h, int res, std::vector<float>& posData, std::vector<float>& colData);

int main()
{
    // Initialize GLFW context
    if (!glfwInit())
    {
        std::cerr << "Failed to initialize GLFW" << std::endl;
        return -1;
    }

    // Configure OpenGL version and profile
    glfwWindowHint(GLFW_CONTEXT_VERSION_MAJOR, 3);
    glfwWindowHint(GLFW_CONTEXT_VERSION_MINOR, 3);
    glfwWindowHint(GLFW_OPENGL_PROFILE, GLFW_OPENGL_CORE_PROFILE);

    // Create rendering window
    GLFWwindow* win = glfwCreateWindow(800, 600, "3D Cylinder", nullptr, nullptr);
    if (!win)
    {
        std::cerr << "Failed to create GLFW window" << std::endl;
        glfwTerminate();
        return -1;
    }
    glfwMakeContextCurrent(win);

    // Load OpenGL function pointers
    if (!gladLoadGLLoader((GLADloadproc)glfwGetProcAddress))
    {
        std::cerr << "Failed to initialize GLAD" << std::endl;
        return -1;
    }

    // Generate cylinder geometry data
    int segmentCount = 50;
    float cylRadius = 0.5f;
    float cylHeight = 8.0f;
    std::vector<float> positions;
    std::vector<float> colorValues;
    constructCylinderMesh(cylRadius, cylHeight, segmentCount, positions, colorValues);

    // Set up vertex buffer objects
    unsigned int vao, vbo;
    glGenVertexArrays(1, &vao);
    glGenBuffers(1, &vbo);

    glBindVertexArray(vao);

    glBindBuffer(GL_ARRAY_BUFFER, vbo);
    glBufferData(GL_ARRAY_BUFFER, (positions.size() + colorValues.size()) * sizeof(float), nullptr, GL_STATIC_DRAW);

    // Upload position data
    glBufferSubData(GL_ARRAY_BUFFER, 0, positions.size() * sizeof(float), positions.data());
    // Upload color data
    glBufferSubData(GL_ARRAY_BUFFER, positions.size() * sizeof(float), colorValues.size() * sizeof(float), colorValues.data());

    // Define vertex attribute pointers
    glVertexAttribPointer(0, 3, GL_FLOAT, GL_FALSE, 3 * sizeof(float), (void*)0);
    glEnableVertexAttribArray(0);

    glVertexAttribPointer(1, 3, GL_FLOAT, GL_FALSE, 3 * sizeof(float), (void*)(positions.size() * sizeof(float)));
    glEnableVertexAttribArray(1);

    // Compile shader program
    unsigned int shaderProgram = buildShaderProgram("vertex_shader.glsl", "fragment_shader.glsl");

    // Setup transformation matrices
    glm::mat4 modelMatrix = glm::mat4(1.0f);
    glm::mat4 viewMatrix = glm::lookAt(glm::vec3(0.0f, 0.0f, 5.0f), glm::vec3(0.0f, 0.0f, 0.0f), glm::vec3(0.0f, 1.0f, 0.0f));
    glm::mat4 projMatrix = glm::perspective(glm::radians(45.0f), 800.0f / 600.0f, 0.1f, 100.0f);

    // Retrieve uniform locations for shader
    GLint modelUniform = glGetUniformLocation(shaderProgram, "model");
    GLint viewUniform = glGetUniformLocation(shaderProgram, "view");
    GLint projectionUniform = glGetUniformLocation(shaderProgram, "projection");

    // Main application loop
    while (!glfwWindowShouldClose(win))
    {
        // Handle input
        if (glfwGetKey(win, GLFW_KEY_ESCAPE) == GLFW_PRESS)
            glfwSetWindowShouldClose(win, true);

        // Clear buffers
        glClearColor(0.2f, 0.3f, 0.3f, 1.0f);
        glClear(GL_COLOR_BUFFER_BIT | GL_DEPTH_BUFFER_BIT);

        // Activate shader program
        glUseProgram(shaderProgram);

        // Pass transformation matrices to shader
        glUniformMatrix4fv(modelUniform, 1, GL_FALSE, glm::value_ptr(modelMatrix));
        glUniformMatrix4fv(viewUniform, 1, GL_FALSE, glm::value_ptr(viewMatrix));
        glUniformMatrix4fv(projectionUniform, 1, GL_FALSE, glm::value_ptr(projMatrix));

        // Render the cylinder
        glBindVertexArray(vao);
        glDrawArrays(GL_TRIANGLES, 0, static_cast<GLsizei>(positions.size() / 3));

        // Swap framebuffers and process events
        glfwSwapBuffers(win);
        glfwPollEvents();
    }

    // Cleanup resources
    glDeleteVertexArrays(1, &vao);
    glDeleteBuffers(1, &vbo);
    glDeleteProgram(shaderProgram);

    glfwTerminate();
    return 0;
}

unsigned int buildShaderProgram(const char* vsPath, const char* fsPath)
{
    // Read shader source files
    std::string vsSource;
    std::string fsSource;
    std::ifstream vsFile(vsPath);
    std::ifstream fsFile(fsPath);

    if (!vsFile.is_open() || !fsFile.is_open())
    {
        std::cerr << "Failed to read shader files" << std::endl;
        return 0;
    }

    std::stringstream vsStream, fsStream;
    vsStream << vsFile.rdbuf();
    fsStream << fsFile.rdbuf();

    vsFile.close();
    fsFile.close();

    vsSource = vsStream.str();
    fsSource = fsStream.str();

    const char* vsCode = vsSource.c_str();
    const char* fsCode = fsSource.c_str();

    // Compile vertex shader
    unsigned int vs = glCreateShader(GL_VERTEX_SHADER);
    glShaderSource(vs, 1, &vsCode, NULL);
    glCompileShader(vs);

    // Check vertex shader compilation status
    int success;
    char infoLog[512];
    glGetShaderiv(vs, GL_COMPILE_STATUS, &success);
    if (!success)
    {
        glGetShaderInfoLog(vs, 512, NULL, infoLog);
        std::cerr << "ERROR::SHADER::VERTEX::COMPILATION_FAILED\n" << infoLog << std::endl;
    }

    // Compile fragment shader
    unsigned int fs = glCreateShader(GL_FRAGMENT_SHADER);
    glShaderSource(fs, 1, &fsCode, NULL);
    glCompileShader(fs);

    // Check fragment shader compilation status
    glGetShaderiv(fs, GL_COMPILE_STATUS, &success);
    if (!success)
    {
        glGetShaderInfoLog(fs, 512, NULL, infoLog);
        std::cerr << "ERROR::SHADER::FRAGMENT::COMPILATION_FAILED\n" << infoLog << std::endl;
    }

    // Link shaders into program
    unsigned int program = glCreateProgram();
    glAttachShader(program, vs);
    glAttachShader(program, fs);
    glLinkProgram(program);

    // Check program linking status
    glGetProgramiv(program, GL_LINK_STATUS, &success);
    if (!success)
    {
        glGetProgramInfoLog(program, 512, NULL, infoLog);
        std::cerr << "ERROR::SHADER::PROGRAM::LINKING_FAILED\n" << infoLog << std::endl;
    }

    // Delete intermediate shader objects
    glDeleteShader(vs);
    glDeleteShader(fs);

    return program;
}

void constructCylinderMesh(float r, float h, int res, std::vector<float>& posData, std::vector<float>& colData)
{
    float deltaAngle = 2.0f * M_PI / res;

    for (int idx = 0; idx <= res; ++idx)
    {
        float theta = idx * deltaAngle;
        float xPos = r * cos(theta);
        float yPos = r * sin(theta);

        // Top cap triangles
        posData.push_back(xPos);
        posData.push_back(yPos);
        posData.push_back(h / 2.0f);

        posData.push_back(0.0f);
        posData.push_back(0.0f);
        posData.push_back(h / 2.0f);

        posData.push_back(xPos);
        posData.push_back(yPos);
        posData.push_back(-h / 2.0f);

        // Bottom cap triangles
        posData.push_back(xPos);
        posData.push_back(yPos);
        posData.push_back(-h / 2.0f);

        posData.push_back(0.0f);
        posData.push_back(0.0f);
        posData.push_back(-h / 2.0f);

        posData.push_back(xPos);
        posData.push_back(yPos);
        posData.push_back(h / 2.0f);

        // Side triangles
        posData.push_back(xPos);
        posData.push_back(yPos);
        posData.push_back(h / 2.0f);

