// Convert RVA to file offset using section headers
DWORD RvaToFileOffset(DWORD rva, PIMAGE_SECTION_HEADER sections, WORD sectionCount)
{
    for (WORD i = 0; i < sectionCount; ++i) {
        DWORD sectionStart = sections[i].VirtualAddress;
        DWORD sectionEnd = sectionStart + sections[i].Misc.VirtualSize;

        if (rva >= sectionStart && rva < sectionEnd) {
            return (rva - sectionStart) + sections[i].PointerToRawData;
        }
    }
    return 0;
}

// Dynamically resolve imported functions
void PatchImports(LPVOID imageBase, PIMAGE_NT_HEADERS ntHeaders)
{
    PIMAGE_IMPORT_DESCRIPTOR importDesc = (PIMAGE_IMPORT_DESCRIPTOR)(
        (char*)imageBase + 
        ntHeaders->OptionalHeader.DataDirectory[IMAGE_DIRECTORY_ENTRY_IMPORT].VirtualAddress
    );

    while (importDesc->Name != 0) {
        char* dllName = (char*)imageBase + importDesc->Name;
        HMODULE hLib = LoadLibraryA(dllName);

        if (hLib != nullptr) {
            PIMAGE_THUNK_DATA originalThunk = (PIMAGE_THUNK_DATA)(
                (char*)imageBase + importDesc->OriginalFirstThunk
            );
            PIMAGE_THUNK_DATA firstThunk = (PIMAGE_THUNK_DATA)(
                (char*)imageBase + importDesc->FirstThunk
            );

            while (originalThunk->u1.Function != 0) {
                if (IMAGE_SNAP_BY_ORDINAL(originalThunk->u1.Ordinal)) {
                    firstThunk->u1.Function = (ULONG_PTR)GetProcAddress(
                        hLib, 
                        (LPCSTR)IMAGE_ORDINAL(originalThunk->u1.Ordinal)
                    );
                } else {
                    PIMAGE_IMPORT_BY_NAME importByName = (PIMAGE_IMPORT_BY_NAME)(
                        (char*)imageBase + originalThunk->u1.AddressOfData
                    );
                    firstThunk->u1.Function = (ULONG_PTR)GetProcAddress(
                        hLib, 
                        (char*)importByName->Name
                    );
                }
                ++originalThunk;
                ++firstThunk;
            }
        }
        ++importDesc;
    }
}

// Apply relocations based on base address difference
void FixRelocations(LPVOID imageBase, PIMAGE_NT_HEADERS ntHeaders, DWORD baseDiff)
{
    PIMAGE_BASE_RELOCATION relocBlock = (PIMAGE_BASE_RELOCATION)(
        (char*)imageBase + 
        ntHeaders->OptionalHeader.DataDirectory[IMAGE_DIRECTORY_ENTRY_BASERELOC].VirtualAddress
    );

    while (relocBlock->VirtualAddress != 0) {
        PWORD relocEntries = (PWORD)((char*)relocBlock + sizeof(IMAGE_BASE_RELOCATION));
        DWORD entryCount = (relocBlock->SizeOfBlock - sizeof(IMAGE_BASE_RELOCATION)) / sizeof(WORD);

        for (DWORD i = 0; i < entryCount; ++i) {
            DWORD rva = relocBlock->VirtualAddress + (relocEntries[i] & 0x0FFF);
            WORD type = (relocEntries[i] >> 12);

            switch (type) {
                case IMAGE_REL_BASED_HIGHLOW:
                    *(PDWORD)((char*)imageBase + rva) += baseDiff;
                    break;
            }
        }

        relocBlock = (PIMAGE_BASE_RELOCATION)((char*)relocBlock + relocBlock->SizeOfBlock);
    }
}

int main(int argc, char* argv[])
{
    if (argc != 2) {
        std::cerr << "Usage: " << argv[0] << " <pe_file_path>" << std::endl;
        return 1;
    }

    std::ifstream input(argv[1], std::ios::binary | std::ios::ate);
    if (!input) {
        std::cerr << "Error: Cannot open file '" << argv[1] << "'" << std::endl;
        return 1;
    }

    std::streamsize fileSize = input.tellg();
    input.seekg(0, std::ios::beg);

    std::vector<BYTE> fileContent(fileSize);
    if (!input.read(reinterpret_cast<char*>(fileContent.data()), fileSize)) {
        std::cerr << "Error: Failed to read file content" << std::endl;
        return 1;
    }

    // Validate DOS header
    PIMAGE_DOS_HEADER dosHeader = reinterpret_cast<PIMAGE_DOS_HEADER>(fileContent.data());
    if (dosHeader->e_magic != IMAGE_DOS_SIGNATURE) {
        std::cerr << "Error: Invalid DOS header signature" << std::endl;
        return 1;
    }

    // Validate NT headers
    PIMAGE_NT_HEADERS ntHeaders = reinterpret_cast<PIMAGE_NT_HEADERS>(
        fileContent.data() + dosHeader->e_lfanew
    );
    if (ntHeaders->Signature != IMAGE_NT_SIGNATURE) {
        std::cerr << "Error: Invalid PE signature" << std::endl;
        return 1;
    }

    // Allocate memory for the entire image
    SIZE_T requiredSize = ntHeaders->OptionalHeader.SizeOfImage;
    LPVOID allocatedMemory = VirtualAlloc(
        nullptr, 
        requiredSize, 
        MEM_COMMIT | MEM_RESERVE, 
        PAGE_EXECUTE_READWRITE
    );

    if (!allocatedMemory) {
        std::cerr << "Error: Memory allocation failed" << std::endl;
        return 1;
    }

    // Copy headers
    memcpy(
        allocatedMemory, 
        fileContent.data(), 
        ntHeaders->OptionalHeader.SizeOfHeaders
    );

    // Copy section data
    PIMAGE_SECTION_HEADER sectionHeaders = IMAGE_FIRST_SECTION(ntHeaders);
    for (WORD i = 0; i < ntHeaders->FileHeader.NumberOfSections; ++i) {
        memcpy(
            (char*)allocatedMemory + sectionHeaders[i].VirtualAddress,
            fileContent.data() + sectionHeaders[i].PointerToRawData,
            sectionHeaders[i].SizeOfRawData
        );
    }

    // Process relocations and imports
    DWORD loadDelta = (DWORD)allocatedMemory - ntHeaders->OptionalHeader.ImageBase;
    FixRelocations(allocatedMemory, ntHeaders, loadDelta);
    PatchImports(allocatedMemory, ntHeaders);

    // Execute entry point
    typedef void (*EntryPoint)();
    EntryPoint entryPoint = reinterpret_cast<EntryPoint>(
        (char*)allocatedMemory + ntHeaders->OptionalHeader.AddressOfEntryPoint
    );

    entryPoint();

    // Cleanup
    VirtualFree(allocatedMemory, 0, MEM_RELEASE);
    return 0;
}

#include <windows.h>

// Send a message through the named pipe after validating the handle
bool CNamedPipe::SendMessage(CString message)
{
    DWORD bytesWritten = 0;

    // Validate the output pipe handle before proceeding
    if (m_hOutPipeHandle == NULL || m_hOutPipeHandle == INVALID_HANDLE_VALUE)
    {
        return false;
    }

    // Attempt to write the entire message including null terminator
    BOOL writeSuccess = WriteFile(m_hOutPipeHandle, 
                                  message.GetString(), 
                                  (message.GetLength() + 1) * sizeof(TCHAR), 
                                  &bytesWritten, 
                                  NULL);

    // Check if write failed or incomplete
    if (!writeSuccess || 
        ((message.GetLength() + 1) * sizeof(TCHAR)) != bytesWritten)
    {
        return false;
    }

    // Ensure all data is flushed to the pipe
    if (!FlushFileBuffers(m_hOutPipeHandle))
    {
        return false;
    }

    return true;
}

