// Prefetch data into cache hierarchy based on level
void prefetch_line(void* addr, int hint_level) {
    if (hint_level == 0) {
        _mm_prefetch(static_cast<char*>(addr), _MM_HINT_T0);
    } else if (hint_level == 1) {
        _mm_prefetch(static_cast<char*>(addr), _MM_HINT_T1);
    } else if (hint_level == 2) {
        _mm_prefetch(static_cast<char*>(addr), _MM_HINT_T2);
    } else if (hint_level == 3) {
        _mm_prefetch(static_cast<char*>(addr), _MM_HINT_NTA);
    }
}

