// Generator class with modified implementation
class SequenceIterator {
public:
  SequenceIterator(int begin, int limit) : pos(begin), boundary(limit) {}

  bool hasMore() const {
    return pos < boundary;
  }

  int advance() {
    return pos++;
  }

private:
  int pos;
  int boundary;
};

// Constructor handler for the generator object
void CreateSequence(const FunctionCallbackInfo<Value>& args) {
  Isolate* isolate = args.GetIsolate();
  Local<Context> context = isolate->GetCurrentContext();

  if (args.IsConstructCall()) {
    int startVal = args[0]->IntegerValue(context).ToChecked();
    int endVal = args[1]->IntegerValue(context).ToChecked();

    SequenceIterator* iter = new SequenceIterator(startVal, endVal);
    args.This()->SetInternalField(0, External::New(isolate, iter));

    args.GetReturnValue().Set(args.This());
  } else {
    Local<Function> cons = Local<Function>::New(isolate, constructorRef);
    Local<Value> argv[2] = { args[0], args[1] };
    args.GetReturnValue().Set(cons->NewInstance(context, 2, argv).ToLocalChecked());
  }
}

// Implementation of the next() method
void GetNextValue(const FunctionCallbackInfo<Value>& args) {
  Isolate* isolate = args.GetIsolate();
  Local<Context> context = isolate->GetCurrentContext();
  SequenceIterator* iter = static_cast<SequenceIterator*>(args.This()->GetInternalField(0).As<External>()->Value());

  if (iter->hasMore()) {
    int current = iter->advance();
    Local<Object> result = Object::New(isolate);
    result->Set(context, String::NewFromUtf8(isolate, "value").ToLocalChecked(), Number::New(isolate, current));
    result->Set(context, String::NewFromUtf8(isolate, "completed").ToLocalChecked(), Boolean::New(isolate, false));
    args.GetReturnValue().Set(result);
  } else {
    Local<Object> result = Object::New(isolate);
    result->Set(context, String::NewFromUtf8(isolate, "value").ToLocalChecked(), Undefined(isolate));
    result->Set(context, String::NewFromUtf8(isolate, "completed").ToLocalChecked(), Boolean::New(isolate, true));
    args.GetReturnValue().Set(result);
  }
}

// Iterator protocol support - returns self when accessed via Symbol.iterator
void ProvideIterator(const PropertyCallbackInfo<Value>& args) {
  args.GetReturnValue().Set(args.Holder());
}

// Persistent reference to the constructor function
Persistent<Function> SequenceIterator::constructorRef;

// Module initialization function
void SetupModule(Local<Object> exports) {
  Isolate* isolate = exports->GetIsolate();
  Local<Context> context = isolate->GetCurrentContext();

  // Create function template for the generator
  Local<FunctionTemplate> tpl = FunctionTemplate::New(isolate, CreateSequence);
  tpl->SetClassName(String::NewFromUtf8(isolate, "SequenceIterator").ToLocalChecked());
  tpl->InstanceTemplate()->SetInternalFieldCount(1);

  // Add methods and properties
  NODE_SET_PROTOTYPE_METHOD(tpl, "next", GetNextValue);
  tpl->InstanceTemplate()->Set(String::NewFromUtf8(isolate, Symbol::GetIterator(isolate)).ToLocalChecked(), 
                               FunctionTemplate::New(isolate, ProvideIterator)->GetFunction(context).ToLocalChecked());

  constructorRef.Reset(isolate, tpl->GetFunction(context).ToLocalChecked());
  exports->Set(context, String::NewFromUtf8(isolate, "SequenceIterator").ToLocalChecked(), 
               tpl->GetFunction(context).ToLocalChecked());
}

