#include <cuda_runtime.h>
#include <iostream>
#include <cmath>

#define TILE_DIM 16

__global__ void computePairwiseDistances(float *inputA, float *inputB, float *outputDist, int countA, int countB) {
    __shared__ float tileB[TILE_DIM * 128];

    int sampleIdx = blockIdx.x;
    int featureStart = blockIdx.y * TILE_DIM + threadIdx.x;
    int featureEnd = featureStart + TILE_DIM;

    // Load a tile of B into shared memory
    for (int feat = featureStart; feat < featureEnd && feat < countB; ++feat) {
        for (int dim = 0; dim < 128; ++dim) {
            tileB[(feat - featureStart) * 128 + dim] = inputB[feat * 128 + dim];
        }
    }
    __syncthreads();

    // Compute Euclidean distances for the current row of A against loaded tiles of B
    for (int feat = featureStart; feat < featureEnd && feat < countB; ++feat) {
        float accum = 0.0f;
        for (int d = 0; d < 128; ++d) {
            float delta = inputA[sampleIdx * 128 + d] - tileB[(feat - featureStart) * 128 + d];
            accum += delta * delta;
        }
        outputDist[sampleIdx * countB + feat] = sqrtf(accum);
    }
}

int main() {
    const int N = 1000;
    const int M = 1000;
    size_t bytesA = N * 128 * sizeof(float);
    size_t bytesB = M * 128 * sizeof(float);
    size_t bytesC = N * M * sizeof(float);

    float *hostA = new float[N * 128];
    float *hostB = new float[M * 128];
    float *hostC = new float[N * M];

    // Populate input matrices with pseudo-random data
    for (int i = 0; i < N * 128; ++i) {
        hostA[i] = static_cast<float>(rand()) / static_cast<float>(RAND_MAX);
    }
    for (int i = 0; i < M * 128; ++i) {
        hostB[i] = static_cast<float>(rand()) / static_cast<float>(RAND_MAX);
    }

    float *devA, *devB, *devC;
    cudaMalloc(&devA, bytesA);
    cudaMalloc(&devB, bytesB);
    cudaMalloc(&devC, bytesC);

    cudaMemcpy(devA, hostA, bytesA, cudaMemcpyHostToDevice);
    cudaMemcpy(devB, hostB, bytesB, cudaMemcpyHostToDevice);

    dim3 blockSize(TILE_DIM, 1);
    dim3 gridSize((M + TILE_DIM - 1) / TILE_DIM, N);

    computePairwiseDistances<<<gridSize, blockSize>>>(devA, devB, devC, N, M);

    cudaMemcpy(hostC, devC, bytesC, cudaMemcpyDeviceToHost);

    // Release resources
    cudaFree(devA);
    cudaFree(devB);
    cudaFree(devC);
    delete[] hostA;
    delete[] hostB;
    delete[] hostC;

    return 0;
}

