// Base abstract class A with pure virtual method
class AbstractA {
public:
    std::vector<int> data;
    virtual void process() = 0;
    virtual ~AbstractA() = default;
};

// Base abstract class B with pure virtual method taking A reference
class AbstractB {
public:
    virtual void handle(const AbstractA& ref) = 0;
    virtual ~AbstractB() = default;
};

namespace py = boost::python;

// Wrapper for AbstractA to support Python overrides
class PyAbstractA : public AbstractA, public py::wrapper<AbstractA> {
public:
    void process() override {
        this->get_override("process")();
    }
};

// Wrapper for AbstractB to support Python overrides
class PyAbstractB : public AbstractB, public py::wrapper<AbstractB> {
public:
    void handle(const AbstractA& ref) override {
        this->get_override("handle")(ref);
    }
};

// Custom converter from C++ AbstractA to Python object
struct AConverter {
    static PyObject* convert(const AbstractA& obj) {
        py::object pyObj = py::object(py::ptr(new PyAbstractA(obj)));
        return pyObj.ptr();
    }
};

BOOST_PYTHON_MODULE(example_module) {
    using int_vector = std::vector<int>;

    // Expose std::vector<int> as IntSequence in Python
    py::class_<int_vector>("IntSequence")
        .def(py::vector_indexing_suite<int_vector>());

    // Expose AbstractA interface
    py::class_<PyAbstractA, boost::noncopyable>("AbstractA", py::no_init)
        .def_readwrite("data", &AbstractA::data)
        .def("process", py::pure_virtual(&AbstractA::process));

    // Expose AbstractB interface
    py::class_<PyAbstractB, boost::noncopyable>("AbstractB", py::no_init)
        .def("handle", py::pure_virtual(&AbstractB::handle));

    // Register custom converter for AbstractA
    py::to_python_converter<AbstractA, AConverter>();
}

