#pragma comment(lib, "ws2_32.lib")

class NetworkLink
{
public:
    class LinkState
    {
    public:
        LinkState(SOCKET sock) : socketHandle(sock), closed(false), transmissionError(false)
        {
            notificationEvent = WSACreateEvent();
            if (notificationEvent == WSA_INVALID_EVENT)
            {
                std::cerr << "Event creation failed: " << WSAGetLastError() << std::endl;
                return;
            }

            // Monitor write availability
            if (WSAEventSelect(socketHandle, notificationEvent, FD_WRITE) == SOCKET_ERROR)
            {
                std::cerr << "Event registration failed: " << WSAGetLastError() << std::endl;
                WSACloseEvent(notificationEvent);
                notificationEvent = WSA_INVALID_EVENT;
                return;
            }
        }

        ~LinkState()
        {
            if (notificationEvent != WSA_INVALID_EVENT)
            {
                WSAEventSelect(socketHandle, notificationEvent, 0); // Disable event monitoring
                WSACloseEvent(notificationEvent);
            }
        }

        void Transmit(const unsigned char* buffer, int size)
        {
            if (closed || transmissionError)
                return;

            std::lock_guard<std::mutex> guard(mutexLock);

            bufferInfo.buf = reinterpret_cast<char*>(const_cast<unsigned char*>(buffer));
            bufferInfo.len = size;

            // Wait until the socket becomes writable
            DWORD outcome = WSAWaitForMultipleEvents(1, &notificationEvent, FALSE, INFINITE, FALSE);
            if (outcome == WSA_WAIT_EVENT_0)
            {
                // Socket ready for sending
                if (WSASend(socketHandle, &bufferInfo, 1, &transferredBytes, 0, nullptr, nullptr) == SOCKET_ERROR)
                {
                    int errorCode = WSAGetLastError();
                    if (errorCode != WSA_IO_PENDING)
                    {
                        std::cerr << "Transmission error: " << errorCode << std::endl;
                        transmissionError = true;
                    }
                }
            }
            else
            {
                std::cerr << "Event wait failed: " << outcome << std::endl;
                transmissionError = true;
            }
        }

    private:
        SOCKET socketHandle;
        WSAEVENT notificationEvent;
        bool closed;
        bool transmissionError;
        std::mutex mutexLock;
        WSABUF bufferInfo;
        DWORD transferredBytes;
    };
};

int main()
{
    WSADATA wsaData;
    if (WSAStartup(MAKEWORD(2, 2), &wsaData) != 0)
    {
        std::cerr << "Winsock initialization failed: " << WSAGetLastError() << std::endl;
        return 1;
    }

    // Create a TCP socket
    SOCKET clientSocket = socket(AF_INET, SOCK_STREAM, IPPROTO_TCP);
    if (clientSocket == INVALID_SOCKET)
    {
        std::cerr << "Socket creation failed: " << WSAGetLastError() << std::endl;
        WSACleanup();
        return 1;
    }

    // Configure server address
    sockaddr_in serverAddress;
    serverAddress.sin_family = AF_INET;
    serverAddress.sin_port = htons(12345);
    inet_pton(AF_INET, "127.0.0.1", &serverAddress.sin_addr);

    // Establish connection
    if (connect(clientSocket, reinterpret_cast<sockaddr*>(&serverAddress), sizeof(serverAddress)) == SOCKET_ERROR)
    {
        std::cerr << "Connection attempt failed: " << WSAGetLastError() << std::endl;
        closesocket(clientSocket);
        WSACleanup();
        return 1;
    }

    // Switch to non-blocking mode
    u_long flags = 1;
    if (ioctlsocket(clientSocket, FIONBIO, &flags) == SOCKET_ERROR)
    {
        std::cerr << "Non-blocking setup failed: " << WSAGetLastError() << std::endl;
        closesocket(clientSocket);
        WSACleanup();
        return 1;
    }

    NetworkLink::LinkState link(clientSocket);

    // Prepare message
    const char* message = "Greetings from client!";
    link.Transmit(reinterpret_cast<const unsigned char*>(message), static_cast<int>(strlen(message)));

    // Cleanup resources
    closesocket(clientSocket);
    WSACleanup();

    return 0;
}

