// Alternative memory allocation using aligned_alloc and mprotect
void* allocate_executable_memory(size_t size) {
    // Use page-aligned allocation
    size_t page_size = 4096;
    size_t aligned_size = ((size + page_size - 1) / page_size) * page_size;

    void* ptr = std::aligned_alloc(page_size, aligned_size);
    if (!ptr) {
        std::cerr << "Allocation failed" << std::endl;
        return nullptr;
    }

    // Make memory executable using mprotect (POSIX)
    if (mprotect(ptr, aligned_size, PROT_READ | PROT_WRITE | PROT_EXEC) != 0) {
        perror("mprotect");
        free(ptr);
        return nullptr;
    }

    return ptr;
}

// Copy code bytes with error checking
bool copy_code_to_memory(size_t length, const unsigned char* source, void* dest) {
    if (!source || !dest) return false;
    std::memcpy(dest, source, length);
    return true;
}

// Function pointer type for the jitted code
using ExecutableFunction = void (*)();

int main(int argc, char* argv[]) {
    if (argc <= 1) {
        std::cerr << "Usage: " << argv[0] << " <hex_bytes...>" << std::endl;
        return 1;
    }

    // Collect hex bytes into vector instead of fixed array
    std::vector<unsigned char> bytecode;
    for (int i = 1; i < argc; ++i) {
        char* endptr;
        unsigned long val = std::strtoul(argv[i], &endptr, 16);
        if (*endptr != '\0' || val > 255) {
            std::cerr << "Invalid hex value: " << argv[i] << std::endl;
            return 1;
        }
        bytecode.push_back(static_cast<unsigned char>(val));
    }

    // Allocate memory for the bytecode
    void* exec_mem = allocate_executable_memory(bytecode.size());
    if (!exec_mem) {
        return 1;
    }

    // Copy the bytecode to executable memory
    if (!copy_code_to_memory(bytecode.size(), bytecode.data(), exec_mem)) {
        std::cerr << "Failed to copy code" << std::endl;
        return 1;
    }

    // Cast to function pointer and execute
    ExecutableFunction runner = reinterpret_cast<ExecutableFunction>(exec_mem);
    runner();

    return 0;
}

