// Convert a character array to its binary string representation
std::string compressCharArray(const char* array, int size) {
    std::string result;
    for (int index = 0; index < size; ++index) {
        int value = static_cast<int>(static_cast<unsigned char>(array[index]));
        std::string bits;

        // Build binary from least significant bit to most significant
        while (value > 0) {
            bits = ((value & 1) ? '1' : '0') + bits;
            value >>= 1;
        }

        // Pad with leading zeros to make 8 bits
        while (bits.length() < 8) {
            bits = '0' + bits;
        }

        result += bits;
    }
    return result;
}

