#include <SDL2/SDL.h>
#include <iostream>
#include <vector>
#include <cmath>

// Constants for rendering configuration
const int SCREEN_WIDTH = 800;
const int SCREEN_HEIGHT = 600;
const int MAX_ITERATIONS = 100;
const float MAX_RAY_LENGTH = 100.0f;
const float SURFACE_THRESHOLD = 0.01f;

// 3D vector structure with basic operations
struct Vector3 {
    float x, y, z;

    Vector3 operator+(const Vector3& rhs) const {
        return {x + rhs.x, y + rhs.y, z + rhs.z};
    }

    Vector3 operator-(const Vector3& rhs) const {
        return {x - rhs.x, y - rhs.y, z - rhs.z};
    }

    Vector3 operator*(float factor) const {
        return {x * factor, y * factor, z * factor};
    }

    Vector3 operator/(float divisor) const {
        return {x / divisor, y / divisor, z / divisor};
    }

    float dotProduct(const Vector3& other) const {
        return x * other.x + y * other.y + z * other.z;
    }

    float magnitude() const {
        return std::sqrt(x * x + y * y + z * z);
    }

    Vector3 normalized() const {
        float mag = magnitude();
        return {x / mag, y / mag, z / mag};
    }
};

// Distance function for scene geometry (sphere centered at origin)
float sceneDistance(const Vector3& point) {
    return point.magnitude() - 1.0f;
}

// Ray marching algorithm to find intersection distance
float marchRay(const Vector3& origin, const Vector3& direction) {
    float distanceTraveled = 0.0f;
    for (int step = 0; step < MAX_ITERATIONS; ++step) {
        Vector3 currentPos = origin + direction * distanceTraveled;
        float distToSurface = sceneDistance(currentPos);

        if (distToSurface < SURFACE_THRESHOLD) {
            return distanceTraveled;
        }

        distanceTraveled += distToSurface;
        if (distanceTraveled > MAX_RAY_LENGTH) {
            return -1.0f;
        }
    }
    return -1.0f;
}

// Calculate ambient occlusion effect
float calculateAmbientOcclusion(const Vector3& position, const Vector3& normal) {
    float occlusion = 0.0f;
    float weight = 1.0f;

    for (float sampleStep = 0.01f; sampleStep < 1.0f; sampleStep *= 2.0f) {
        float dist = sceneDistance(position + normal * sampleStep);
        occlusion += (dist - sampleStep) * weight;
        weight *= 0.5f;
    }

    return 1.0f - (occlusion * 1.0f);
}

// Compute lighting and shading at a surface point
Vector3 applyLighting(const Vector3& position, const Vector3& normal) {
    Vector3 lightDirection = {1.0f, 1.0f, 1.0f}.normalized();
    float diffuseIntensity = std::max(0.0f, normal.dotProduct(lightDirection));
    float aoFactor = calculateAmbientOcclusion(position, normal);

    return {diffuseIntensity * aoFactor, 
            diffuseIntensity * aoFactor, 
            diffuseIntensity * aoFactor};
}

