    }

    // Prepare pixel buffer
    std::vector<Uint32> frameBuffer(SCREEN_WIDTH * SCREEN_HEIGHT);

    // Camera setup
    Vector3 cameraPosition = {0.0f, 0.0f, 4.0f};
    Vector3 lookAtPoint = {0.0f, 0.0f, 0.0f};
    Vector3 forwardDirection = (lookAtPoint - cameraPosition).normalized();
    Vector3 rightDirection = {1.0f, 0.0f, 0.0f}.normalized();
    Vector3 upDirection = rightDirection.normalized(); // Simplified for this case

    bool applicationRunning = true;
    SDL_Event event;

    // Main rendering loop
    while (applicationRunning) {
        // Handle events
        while (SDL_PollEvent(&event)) {
            if (event.type == SDL_QUIT) {
                applicationRunning = false;
            }
        }

        // Render each pixel
        for (int row = 0; row < SCREEN_HEIGHT; ++row) {
            for (int col = 0; col < SCREEN_WIDTH; ++col) {
                // Calculate UV coordinates
                float u = (2.0f * col - SCREEN_WIDTH) / SCREEN_WIDTH;
                float v = -(2.0f * row - SCREEN_HEIGHT) / SCREEN_HEIGHT;

                // Generate ray direction
                Vector3 rayDirection = (forwardDirection + 
                                       rightDirection * u + 
                                       upDirection * v).normalized();

                // Trace ray through scene
                float hitDistance = marchRay(cameraPosition, rayDirection);

                if (hitDistance > 0.0f) {
                    // Calculate surface point
                    Vector3 surfacePoint = cameraPosition + rayDirection * hitDistance;

                    // Estimate surface normal using finite differences
                    Vector3 offset = {0.001f, 0.0f, 0.0f};
                    Vector3 normal = (surfacePoint - 
                                     (surfacePoint + offset) * 
                                     sceneDistance(surfacePoint + offset) / 
                                     sceneDistance(surfacePoint)).normalized();

                    // Apply lighting
                    Vector3 pixelColor = applyLighting(surfacePoint, normal);

                    // Convert to RGB format
                    Uint8 r = static_cast<Uint8>(pixelColor.x * 255);
                    Uint8 g = static_cast<Uint8>(pixelColor.y * 255);
                    Uint8 b = static_cast<Uint8>(pixelColor.z * 255);

                    frameBuffer[row * SCREEN_WIDTH + col] = SDL_MapRGB(
                        SDL_GetPixelFormat(graphicsRenderer), r, g, b);
                } else {
                    // Background color
                    frameBuffer[row * SCREEN_WIDTH + col] = SDL_MapRGB(
                        SDL_GetPixelFormat(graphicsRenderer), 20, 20, 30);
                }
            }
        }

        // Update texture with rendered pixels
        SDL_UpdateTexture(renderTexture, nullptr, frameBuffer.data(), 
                         SCREEN_WIDTH * sizeof(Uint32));

        // Render to screen
        SDL_RenderClear(graphicsRenderer);
        SDL_RenderCopy(graphicsRenderer, renderTexture, nullptr, nullptr);
        SDL_RenderPresent(graphicsRenderer);
    }

    // Cleanup resources
    SDL_DestroyTexture(renderTexture);
    SDL_DestroyRenderer(graphicsRenderer);
    SDL_DestroyWindow(displayWindow);
    SDL_Quit();

    return 0;
}

#include <cuda_runtime.h>
#include <iostream>

// Define block size for CUDA kernel execution
#define TILE_SIZE 16

__global__ void matrixMultiplyKernel(float *inputA, float *inputB, float *outputC, int matrixDimension) {
    // Compute global row and column indices for the current thread
    int globalRow = blockIdx.y * blockDim.y + threadIdx.y;
    int globalCol = blockIdx.x * blockDim.x + threadIdx.x;

    // Accumulator for the dot product
    float accumulator = 0.0f;

    // Process tiles along the K dimension
    for (int tileStart = 0; tileStart < matrixDimension; tileStart += TILE_SIZE) {
        // Declare shared memory tiles for A and B
        __shared__ float tileA[TILE_SIZE][TILE_SIZE];
        __shared__ float tileB[TILE_SIZE][TILE_SIZE];

        // Load elements of tile A into shared memory
        int aRow = globalRow * matrixDimension + tileStart + threadIdx.x;
        int aCol = tileStart + threadIdx.y;
        tileA[threadIdx.y][threadIdx.x] = 
            (aRow < matrixDimension * matrixDimension && aCol < matrixDimension) ? inputA[aRow] : 0.0f;

        // Load elements of tile B into shared memory
        int bRow = tileStart + threadIdx.x;
        int bCol = globalCol + threadIdx.y;
        tileB[threadIdx.y][threadIdx.x] = 
            (bRow < matrixDimension && bCol < matrixDimension) ? inputB[bRow * matrixDimension + bCol] : 0.0f;

        // Ensure all threads have loaded their data before computation
        __syncthreads();

        // Compute partial dot product for this tile
        for (int k = 0; k < TILE_SIZE; ++k) {
            accumulator += tileA[threadIdx.y][k] * tileB[k][threadIdx.x];
        }

        // Synchronize before loading next tile
        __syncthreads();
    }

    // Write result to global memory if within bounds
    int outputIndex = globalRow * matrixDimension + globalCol;
    if (globalRow < matrixDimension && globalCol < matrixDimension) {
        outputC[outputIndex] = accumulator;
    }
}

// Host function to launch the CUDA kernel
void performMatrixMultiplication(float *deviceA, float *deviceB, float *deviceC, int size) {
    dim3 threadsPerBlock(TILE_SIZE, TILE_SIZE);
    dim3 blocksPerGrid((size + TILE_SIZE - 1) / TILE_SIZE, (size + TILE_SIZE - 1) / TILE_SIZE);

    matrixMultiplyKernel<<<blocksPerGrid, threadsPerBlock>>>(deviceA, deviceB, deviceC, size);

    cudaDeviceSynchronize();
}

int main() {
    int dimension = 1024; // Square matrix dimension
    size_t bytes = dimension * dimension * sizeof(float);

    // Allocate host memory
    float *hostA = (float *)malloc(bytes);
    float *hostB = (float *)malloc(bytes);
    float *hostC = (float *)malloc(bytes);

    // Initialize host matrices (e.g., with test data)
    for (int i = 0; i < dimension * dimension; ++i) {
        hostA[i] = 1.0f;
        hostB[i] = 2.0f;
    }

    // Allocate device memory
    float *deviceA, *deviceB, *deviceC;
    cudaMalloc(&deviceA, bytes);
    cudaMalloc(&deviceB, bytes);
    cudaMalloc(&deviceC, bytes);

    // Copy input data from host to device
    cudaMemcpy(deviceA, hostA, bytes, cudaMemcpyHostToDevice);
    cudaMemcpy(deviceB, hostB, bytes, cudaMemcpyHostToDevice);

    // Execute matrix multiplication on GPU
    performMatrixMultiplication(deviceA, deviceB, deviceC, dimension);

    // Copy result back to host
    cudaMemcpy(hostC, deviceC, bytes, cudaMemcpyDeviceToHost);

    // Optional: Verify or process result (e.g., print first few values)
    // std::cout << "C[0] = " << hostC[0] << std::endl;

    // Cleanup resources
    free(hostA);
    free(hostB);
    free(hostC);
    cudaFree(deviceA);
    cudaFree(deviceB);
    cudaFree(deviceC);

    return 0;
}

