// Function to print Fibonacci sequence up to n terms
void displayFibonacci(int count) {
    int first = 0, second = 1, next = 0;
    int termCount = 0;

    // Handle special cases for first two terms
    if (count >= 1) {
        cout << first;
        termCount++;
    }
    if (count >= 2) {
        cout << ", " << second;
        termCount++;
    }

    // Generate remaining terms
    while (termCount < count) {
        next = first + second;
        first = second;
        second = next;

        cout << ", " << next;
        termCount++;
    }
}

