typedef int (WINAPI *MessageBoxFunc)(HWND, LPCSTR, LPCSTR, UINT);
MessageBoxFunc originalMsgBox = MessageBoxA;

// Replacement function implementation
int WINAPI customMessageBox(HWND hwnd, LPCSTR text, LPCSTR caption, UINT type)
{
    // Custom behavior: always return 1 (IDOK)
    return 1;
}

// Apply inline hook to redirect MessageBoxA calls
void applyHook()
{
    BYTE* targetFunc = reinterpret_cast<BYTE*>(MessageBoxA);
    DWORD previousProtect;

    // Make memory writable
    VirtualProtect(targetFunc, 6, PAGE_EXECUTE_READWRITE, &previousProtect);

    // Prepare jump instruction: JMP rel32
    BYTE patch[5];
    patch[0] = 0xE9; // JMP opcode
    DWORD relativeAddr = reinterpret_cast<DWORD>(customMessageBox) - 
                         (reinterpret_cast<DWORD>(targetFunc) + 5);
    std::memcpy(patch + 1, &relativeAddr, sizeof(relativeAddr));

    // Write the jump instruction
    std::memcpy(targetFunc, patch, 5);

    // Restore original protection
    VirtualProtect(targetFunc, 6, previousProtect, &previousProtect);
}

int main()
{
    // Install the hook
    applyHook();

    // Test calls to the hooked function
    int result1 = MessageBoxA(NULL, "Hello World", "Injector", MB_OK);
    int result2 = MessageBoxA(NULL, "Hello World", "Injector", MB_OK);

    std::printf("Result from first call: %d\n", result1);
    std::printf("Result from second call: %d\n", result2);
    std::cout << "First result: " << result1 << "\n";
    std::cout << "Second result: " << result2 << "\n";

    std::printf("Hello World\n");

    return 0;
}

