#include <Windows.h>
#include <iostream>

int main() {
    DWORD processId = 0;
    std::cout << "Enter PID: ";
    std::cin >> processId;

    HANDLE hProc = OpenProcess(PROCESS_ALL_ACCESS, FALSE, processId);
    if (!hProc) {
        std::cerr << "Failed to open process. Error: " << GetLastError() << std::endl;
        return 1;
    }

    LPVOID remoteMemory = VirtualAllocEx(hProc, nullptr, 4096, MEM_COMMIT | MEM_RESERVE, PAGE_EXECUTE_READWRITE);
    if (!remoteMemory) {
        std::cerr << "VirtualAllocEx failed. Error: " << GetLastError() << std::endl;
        CloseHandle(hProc);
        return 1;
    }

    // Shellcode: push 0x500; push 0x500; call Beep; xor eax, eax; ret
    unsigned char shellcode[] = {
        0x68, 0x00, 0x05, 0x00, 0x00,   // push 0x500
        0x68, 0x00, 0x05, 0x00, 0x00,   // push 0x500
        0xE8, 0x00, 0x00, 0x00, 0x00,   // call Beep (relative offset placeholder)
        0x31, 0xC0,                     // xor eax, eax
        0xC3                            // ret
    };

    // Adjust the relative call offset to point to Beep in kernel32.dll
    HMODULE hKernel32 = GetModuleHandleA("kernel32.dll");
    FARPROC pBeep = GetProcAddress(hKernel32, "Beep");
    LONG relativeOffset = (LONG)((BYTE*)pBeep - ((BYTE*)remoteMemory + 10)); // 10 bytes before call instruction
    *(LONG*)(shellcode + 6) = relativeOffset;

    SIZE_T written = 0;
    if (!WriteProcessMemory(hProc, remoteMemory, shellcode, sizeof(shellcode), &written)) {
        std::cerr << "WriteProcessMemory failed. Error: " << GetLastError() << std::endl;
        VirtualFreeEx(hProc, remoteMemory, 0, MEM_RELEASE);
        CloseHandle(hProc);
        return 1;
    }

    HANDLE hThread = CreateRemoteThread(hProc, nullptr, 0, (LPTHREAD_START_ROUTINE)remoteMemory, nullptr, 0, nullptr);
    if (!hThread) {
        std::cerr << "CreateRemoteThread failed. Error: " << GetLastError() << std::endl;
        VirtualFreeEx(hProc, remoteMemory, 0, MEM_RELEASE);
        CloseHandle(hProc);
        return 1;
    }

    WaitForSingleObject(hThread, INFINITE);

    VirtualFreeEx(hProc, remoteMemory, 0, MEM_RELEASE);
    CloseHandle(hThread);
    CloseHandle(hProc);

    return 0;
}

#include <openssl/aes.h>
#include <openssl/evp.h>
#include <string>
#include <vector>

std::string decrypt(const std::vector<uint8_t>& encryptedData, const std::vector<uint8_t>& secretKey, const std::vector<uint8_t>& initializationVector)
{
    EVP_CIPHER_CTX* context = EVP_CIPHER_CTX_new();
    if (!context) {
        // Error handling for context allocation failure
        return "";
    }

    if (EVP_DecryptInit_ex(context, EVP_aes_256_cbc(), nullptr, secretKey.data(), initializationVector.data()) != 1) {
        EVP_CIPHER_CTX_free(context);
        // Error handling for initialization failure
        return "";
    }

    std::vector<uint8_t> decryptedBuffer(encryptedData.size() + AES_BLOCK_SIZE);
    int processedBytes;
    if (EVP_DecryptUpdate(context, decryptedBuffer.data(), &processedBytes, encryptedData.data(), encryptedData.size()) != 1) {
        EVP_CIPHER_CTX_free(context);
        // Error handling for decryption update failure
        return "";
    }

    int finalProcessedBytes;
    if (EVP_DecryptFinal_ex(context, decryptedBuffer.data() + processedBytes, &finalProcessedBytes) != 1) {
        EVP_CIPHER_CTX_free(context);
        // Error handling for final decryption step failure
        return "";
    }

    EVP_CIPHER_CTX_free(context);

    decryptedBuffer.resize(processedBytes + finalProcessedBytes);
    return std::string(decryptedBuffer.begin(), decryptedBuffer.end());
}

