#include <iostream>
#include <vector>

// Helper function to locate the leftmost index where target could be inserted
int locateLeftBoundary(const std::vector<int>& data, int key) {
    int start = 0;
    int end = static_cast<int>(data.size()) - 1;
    int index = -1;
    while (start <= end) {
        int center = start + (end - start) / 2;
        if (data[center] >= key) {
            if (data[center] == key) {
                index = center;
            }
            end = center - 1;
        } else {
            start = center + 1;
        }
    }
    return index;
}

// Helper function to locate the rightmost index where target could be inserted
int locateRightBoundary(const std::vector<int>& data, int key) {
    int start = 0;
    int end = static_cast<int>(data.size()) - 1;
    int index = -1;
    while (start <= end) {
        int center = start + (end - start) / 2;
        if (data[center] <= key) {
            if (data[center] == key) {
                index = center;
            }
            start = center + 1;
        } else {
            end = center - 1;
        }
    }
    return index;
}

// Compute how many times the target appears in the sorted array
int tallyOccurrences(const std::vector<int>& data, int key) {
    int firstIndex = locateLeftBoundary(data, key);
    if (firstIndex == -1) {
        return 0; // Key not found in the array
    }
    int lastIndex = locateRightBoundary(data, key);
    return lastIndex - firstIndex + 1;
}

int main() {
    std::vector<int> dataset = {1, 2, 2, 2, 3, 4, 5};
    int searchValue = 2;
    int frequency = tallyOccurrences(dataset, searchValue);
    std::cout << "Number of occurrences of " << searchValue << ": " << frequency << std::endl;
    return 0;
}

#include <iostream>
#include <cmath> // for std::sqrt

class ThreeDPoint {
public:
    // Constructor with default values
    ThreeDPoint(double xVal = 0.0, double yVal = 0.0, double zVal = 0.0) 
        : xPos(xVal), yPos(yVal), zPos(zVal) {}

    // Accessor methods
    double getX() const { return xPos; }
    double getY() const { return yPos; }
    double getZ() const { return zPos; }

    // Mutator methods
    void setX(double xVal) { xPos = xVal; }
    void setY(double yVal) { yPos = yVal; }
    void setZ(double zVal) { zPos = zVal; }

    // Compute Euclidean distance to another point
    double computeDistance(const ThreeDPoint& other) const {
        double diffX = xPos - other.xPos;
        double diffY = yPos - other.yPos;
        double diffZ = zPos - other.zPos;
        return std::sqrt(diffX * diffX + diffY * diffY + diffZ * diffZ);
    }

private:
    double xPos, yPos, zPos; // Store the coordinates
};

int main() {
    // Instantiate two points in 3D space
    ThreeDPoint firstPoint(1.0, 2.0, 3.0);
    ThreeDPoint secondPoint(4.0, 5.0, 6.0);

    // Calculate the spatial separation between them
    double separation = firstPoint.computeDistance(secondPoint);

    // Display the computed distance
    std::cout << "The distance between the points is: " << separation << std::endl;

    return 0;
}

