    int destinationPort = std::stoi(argv[3]);

    // Initialize FFmpeg components
    av_register_all();
    avformat_network_init();

    AVFormatContext *inputCtx = nullptr;
    if (avformat_open_input(&inputCtx, sourceFile, nullptr, nullptr) < 0) {
        std::cerr << "Failed to open input file: " << sourceFile << std::endl;
        return 2;
    }

    if (avformat_find_stream_info(inputCtx, nullptr) < 0) {
        std::cerr << "Unable to retrieve stream information" << std::endl;
        return 3;
    }

    av_dump_format(inputCtx, 0, sourceFile, 0);

    int videoIdx = -1;
    int audioIdx = -1;

    for (unsigned int idx = 0; idx < inputCtx->nb_streams; ++idx) {
        AVMediaType type = inputCtx->streams[idx]->codecpar->codec_type;
        if (type == AVMEDIA_TYPE_VIDEO) {
            videoIdx = static_cast<int>(idx);
        } else if (type == AVMEDIA_TYPE_AUDIO) {
            audioIdx = static_cast<int>(idx);
        }
    }

    if (videoIdx == -1 || audioIdx == -1) {
        std::cerr << "Missing required video or audio stream" << std::endl;
        return 4;
    }

    // Prepare output context for RTP streaming
    AVFormatContext *outputCtx = nullptr;
    if (avformat_alloc_output_context2(&outputCtx, nullptr, "rtp", nullptr) < 0) {
        std::cerr << "Could not create output context" << std::endl;
        return 5;
    }

    for (unsigned int i = 0; i < inputCtx->nb_streams; ++i) {
        AVStream *inStream = inputCtx->streams[i];
        AVStream *outStream = avformat_new_stream(outputCtx, nullptr);
        if (!outStream) {
            std::cerr << "Failed to allocate output stream" << std::endl;
            return 6;
        }

        avcodec_parameters_copy(outStream->codecpar, inStream->codecpar);
        if (i == static_cast<unsigned int>(videoIdx)) {
            outStream->codecpar->codec_tag = AV_RTP_PAYLOAD_H264;
        } else if (i == static_cast<unsigned int>(audioIdx)) {
            outStream->codecpar->codec_tag = AV_RTP_PAYLOAD_AAC;
        }
    }

    av_dump_format(outputCtx, 0, destinationIP, 1);

    // Configure RTP options
    AVDictionary *options = nullptr;
    av_dict_set_int(&options, "ttl", 64, 0);
    av_dict_set_int(&options, "localport", 8000, 0);

    std::string rtpUrl = "rtp://" + std::string(destinationIP) + ":" + std::to_string(destinationPort);
    if (avio_open2(&outputCtx->pb, rtpUrl.c_str(), AVIO_FLAG_WRITE, nullptr, &options) < 0) {
        std::cerr << "Cannot open RTP output URL" << std::endl;
        return 7;
    }

    if (avformat_write_header(outputCtx, nullptr) < 0) {
        std::cerr << "Header writing failed" << std::endl;
        return 8;
    }

    // Stream processing loop
    AVPacket pkt;
    av_init_packet(&pkt);
    int64_t lastVideoPTS = 0;
    int64_t lastAudioPTS = 0;

    while (fetch_packet(inputCtx, &pkt) >= 0) {
        int streamId = pkt.stream_index;
        AVRational tb = inputCtx->streams[streamId]->time_base;

        if (streamId == videoIdx || streamId == audioIdx) {
            AVPacket outPkt;
            av_init_packet(&outPkt);
            av_packet_ref(&outPkt, &pkt);

            av_packet_rescale_ts(&pkt, tb, outputCtx->streams[streamId]->time_base);
            av_write_frame(outputCtx, &outPkt);
            av_packet_unref(&outPkt);

            // Timing control for real-time playback
            int64_t currentPTS = pkt.pts;
            int64_t diffPTS = currentPTS - (streamId == videoIdx ? lastVideoPTS : lastAudioPTS);
            int64_t delayMicros = av_rescale_q(diffPTS, tb, {1, 1000000});
            std::this_thread::sleep_until(std::chrono::system_clock::now() + std::chrono::microseconds(delayMicros));

            if (streamId == videoIdx) {
                lastVideoPTS = currentPTS;
            } else {
                lastAudioPTS = currentPTS;
            }
        }

        av_packet_unref(&pkt);
    }

    // Cleanup resources
    av_write_trailer(outputCtx);
    avio_closep(&outputCtx->pb);
    avformat_free_context(outputCtx);
    avformat_close_input(&inputCtx);

    return 0;
}

