template <typename Dtype>
class WeightedSigmoidCrossEntropyLossLayer : public LossLayer<Dtype> {
 public:
  explicit WeightedSigmoidCrossEntropyLossLayer(const LayerParameter& param)
      : LossLayer<Dtype>(param) {}
  virtual void LayerSetUp(const vector<Blob<Dtype>*>& bottom,
                          const vector<Blob<Dtype>*>& top);
  virtual void Reshape(const vector<Blob<Dtype>*>& bottom,
                       const vector<Blob<Dtype>*>& top);
  virtual void Forward_cpu(const vector<Blob<Dtype>*>& bottom,
                           const vector<Blob<Dtype>*>& top);
  virtual void Backward_cpu(const vector<Blob<Dtype>*>& top,
                            const vector<bool>& propagate_down,
                            const vector<Blob<Dtype>*>& bottom);

 protected:
  Blob<Dtype> sigmoid_output_;
  Blob<Dtype> target_labels_;
  Blob<Dtype> sample_weights_;
  Blob<Dtype> temp_weight_tensor_;
  Dtype pos_class_weight_;
  Dtype neg_class_weight_;
};

template <typename Dtype>
void WeightedSigmoidCrossEntropyLossLayer<Dtype>::LayerSetUp(
    const vector<Blob<Dtype>*>& bottom, const vector<Blob<Dtype>*>& top) {
  // Set class weights inversely proportional to class frequencies
  pos_class_weight_ = 20.0;   // 1 / 0.05
  neg_class_weight_ = 1.0526315789473684;  // approximately 1 / 0.95
}

template <typename Dtype>
void WeightedSigmoidCrossEntropyLossLayer<Dtype>::Reshape(
    const vector<Blob<Dtype>*>& bottom, const vector<Blob<Dtype>*>& top) {
  LossLayer<Dtype>::Reshape(bottom, top);
  sigmoid_output_.ReshapeLike(*bottom[0]);
  target_labels_.ReshapeLike(*bottom[1]);
  sample_weights_.ReshapeLike(*bottom[1]);
  temp_weight_tensor_.ReshapeLike(*bottom[1]);
}

template <typename Dtype>
void WeightedSigmoidCrossEntropyLossLayer<Dtype>::Forward_cpu(
    const vector<Blob<Dtype>*>& bottom, const vector<Blob<Dtype>*>& top) {
  const Dtype* input_logits = bottom[0]->cpu_data();
  const Dtype* ground_truth = bottom[1]->cpu_data();
  Dtype* computed_sigmoid = sigmoid_output_.mutable_cpu_data();
  Dtype* weight_map = sample_weights_.mutable_cpu_data();

  int batch_size = bottom[0]->num();
  int elements_per_sample = bottom[0]->count() / batch_size;

  // Compute sigmoid activation for each element
  for (int idx = 0; idx < batch_size * elements_per_sample; ++idx) {
    computed_sigmoid[idx] = static_cast<Dtype>(1.0) / 
        (static_cast<Dtype>(1.0) + exp(-input_logits[idx]));
  }

  // Assign per-sample weights based on label values
  for (int idx = 0; idx < batch_size * elements_per_sample; ++idx) {
    if (ground_truth[idx] > static_cast<Dtype>(0.5)) {
      weight_map[idx] = pos_class_weight_;
    } else {
      weight_map[idx] = neg_class_weight_;
    }
  }

  // Accumulate weighted loss
  Dtype total_loss = Dtype(0);
  for (int idx = 0; idx < batch_size * elements_per_sample; ++idx) {
    Dtype log_prob = log(computed_sigmoid[idx] + Dtype(1e-12));
    Dtype log_one_minus_prob = log(static_cast<Dtype>(1.0) - computed_sigmoid[idx] + Dtype(1e-12));

    if (ground_truth[idx] > static_cast<Dtype>(0.5)) {
      total_loss -= log_prob;
    } else {
      total_loss -= weight_map[idx] * log_one_minus_prob;
    }
  }

  top[0]->mutable_cpu_data()[0] = total_loss / batch_size;
}

template <typename Dtype>
void WeightedSigmoidCrossEntropyLossLayer<Dtype>::Backward_cpu(
    const vector<Blob<Dtype>*>& top, const vector<bool>& propagate_down,
    const vector<Blob<Dtype>*>& bottom) {
  if (!propagate_down[0]) {
    return;
  }

  const Dtype* raw_input = bottom[0]->cpu_data();
  const Dtype* labels = bottom[1]->cpu_data();
  const Dtype* activated_vals = sigmoid_output_.cpu_data();
  const Dtype* weights = sample_weights_.cpu_data();
  Dtype* gradient_out = bottom[0]->mutable_cpu_diff();

  int batch_size = bottom[0]->num();
  int dim = bottom[0]->count() / batch_size;

  // Compute gradients with respect to logits
  for (int i = 0; i < batch_size; ++i) {
    for (int j = 0; j < dim; ++j) {
      int idx = i * dim + j;
      Dtype diff_val = activated_vals[idx] - labels[idx];
      gradient_out[idx] = diff_val * weights[idx];
    }
  }

  // Scale gradients by the loss scaling factor
  caffe_cpu_scale(bottom[0]->count(), 
                  top[0]->cpu_diff()[0] / batch_size, 
                  gradient_out, 
                  gradient_out);
}

