    static bool isLedOn = false;
    isLedOn = !isLedOn; // Invert current state

    digitalWrite(ledControlPin, isLedOn ? HIGH : LOW);
    httpServer.send(200, "text/plain", isLedOn ? "ON" : "OFF");
}

