// Check if a number is prime using an alternative approach
bool checkPrime(int value) {
    if (value <= 1) {
        return false;
    }
    int limit = static_cast<int>(std::sqrt(value));
    int divisor = 2;
    while (divisor <= limit) {
        if (value % divisor == 0) {
            return false;
        }
        divisor++;
    }
    return true;
}

int main() {
    std::vector<int> primeNumbers;
    int currentNumber = 2;
    while (currentNumber <= 50) {
        if (checkPrime(currentNumber)) {
            primeNumbers.push_back(currentNumber);
        }
        currentNumber++;
    }

    for (size_t i = 0; i < primeNumbers.size(); ++i) {
        std::cout << primeNumbers[i] << " ";
    }
    std::cout << std::endl;
    return 0;
}

#include <iostream>

// A 2D vector class supporting basic arithmetic operations
class Vector {
public:
    int x_coord, y_coord;

    // Constructor with default values (0, 0)
    Vector(int x = 0, int y = 0) : x_coord(x), y_coord(y) {}

    // Overloaded addition operator for vector addition
    Vector operator+(const Vector& rhs) const {
        return Vector(x_coord + rhs.x_coord, y_coord + rhs.y_coord);
    }

    // Overloaded subtraction operator for vector difference
    Vector operator-(const Vector& rhs) const {
        return Vector(x_coord - rhs.x_coord, y_coord - rhs.y_coord);
    }

    // Scalar multiplication operator
    Vector operator*(int scale) const {
        return Vector(x_coord * scale, y_coord * scale);
    }

    // Stream insertion operator for easy output formatting
    friend std::ostream& operator<<(std::ostream& out, const Vector& v) {
        out << "(" << v.x_coord << ", " << v.y_coord << ")";
        return out;
    }
};

