// Helper function to convert a jobject to its corresponding primitive jvalue type
jvalue convertToJValue(JNIEnv* env, jobject obj, const char* typeSig) {
    jvalue result;

    // Handle different Java wrapper types based on signature
    switch (typeSig[0]) {
        case 'Z': // boolean
            {
                jmethodID method = env->GetMethodID(env->GetObjectClass(obj), "booleanValue", "()Z");
                result.z = env->CallBooleanMethod(obj, method);
            }
            break;
        case 'B': // byte
            {
                jmethodID method = env->GetMethodID(env->GetObjectClass(obj), "byteValue", "()B");
                result.b = env->CallByteMethod(obj, method);
            }
            break;
        case 'C': // char
            {
                jmethodID method = env->GetMethodID(env->GetObjectClass(obj), "charValue", "()C");
                result.c = env->CallCharMethod(obj, method);
            }
            break;
        case 'S': // short
            {
                jmethodID method = env->GetMethodID(env->GetObjectClass(obj), "shortValue", "()S");
                result.s = env->CallShortMethod(obj, method);
            }
            break;
        case 'I': // int
            {
                jmethodID method = env->GetMethodID(env->GetObjectClass(obj), "intValue", "()I");
                result.i = env->CallIntMethod(obj, method);
            }
            break;
        case 'J': // long
            {
                jmethodID method = env->GetMethodID(env->GetObjectClass(obj), "longValue", "()J");
                result.j = env->CallLongMethod(obj, method);
            }
            break;
        case 'F': // float
            {
                jmethodID method = env->GetMethodID(env->GetObjectClass(obj), "floatValue", "()F");
                result.f = env->CallFloatMethod(obj, method);
            }
            break;
        case 'D': // double
            {
                jmethodID method = env->GetMethodID(env->GetObjectClass(obj), "doubleValue", "()D");
                result.d = env->CallDoubleMethod(obj, method);
            }
            break;
        case 'L':
        case '[':
            result.l = obj;
            break;
        default:
            std::cerr << "Unknown or unsupported type: " << typeSig << std::endl;
            break;
    }

    return result;
}

// Function to instantiate an object using reflection with variable arguments
jobject instantiateObject(JNIEnv* env, jobjectArray argArray, const char* methodSig) {
    // Count number of parameters in the signature
    const char* p = methodSig;
    while (*p && *p != '(') ++p;
    if (!*p) return nullptr;
    ++p; // skip '('

    int paramCount = 0;
    while (*p && *p != ')') {
        if (*p == 'L') {
            while (*p && *p != ';') ++p;
        } else if (*p == '[') {
            // Skip array prefix characters
        }
        ++p;
        ++paramCount;
    }

    // Validate argument count matches signature
    int actualArgs = env->GetArrayLength(argArray);
    if (actualArgs != paramCount) {
        std::cerr << "Argument count mismatch: expected " << paramCount 
                  << ", got " << actualArgs << std::endl;
        return nullptr;
    }

    // Prepare jvalue array for constructor call
    jvalue* values = new jvalue[paramCount];

    // Convert each argument from jobject to appropriate jvalue type
    for (int i = 0; i < paramCount; ++i) {
        jobject argObj = env->GetObjectArrayElement(argArray, i);
        // Extract type info from signature starting after '('
        const char* sigPtr = methodSig + 1;
        for (int j = 0; j < i; ++j) {
            if (*sigPtr == 'L') {
                while (*sigPtr && *sigPtr != ';') ++sigPtr;
            }
            ++sigPtr;
        }
        values[i] = convertToJValue(env, argObj, sigPtr);
        env->DeleteLocalRef(argObj);
    }

    // Locate target class and constructor
    const char* className = "Your/Target/Class"; // Replace with actual class name
    jclass cls = env->FindClass(className);
    if (!cls) {
        std::cerr << "Failed to find class: " << className << std::endl;
        delete[] values;
        return nullptr;
    }

    jmethodID ctor = env->GetMethodID(cls, "<init>", methodSig);
    if (!ctor) {
        std::cerr << "Constructor not found with signature: " << methodSig << std::endl;
        delete[] values;
        return nullptr;
    }

    // Create instance using NewObjectA
    jobject newObj = env->NewObjectA(cls, ctor, values);

    delete[] values;
    return newObj;
}

// JNI exported function to create an object via reflection
extern "C" JNIEXPORT jobject JNICALL Java_com_example_YourClass_createObject(JNIEnv* env, jobject thiz, jobjectArray args, jstring signatureStr) {
    const char* utfSig = env->GetStringUTFChars(signatureStr, nullptr);
    jobject result = instantiateObject(env, args, utfSig);
    env->ReleaseStringUTFChars(signatureStr, utfSig);
    return result;
}

