// Read the time-stamp counter using inline assembly
static inline uint64_t get_cycle_count() {
    uint32_t lo, hi;
    __asm__ __volatile__ ("rdtsc" : "=a"(lo), "=d"(hi));
    return ((uint64_t)hi << 32) | lo;
}

