// Convert hexadecimal string to binary data
std::string hex_to_bytes(std::string const &hex_input) {
  std::string result;
  for (std::size_t idx = 0; idx < hex_input.size(); idx += 2) {
    std::string byte_str = hex_input.substr(idx, 2);
    char byte_val = static_cast<char>(std::strtol(byte_str.c_str(), nullptr, 16));
    result.push_back(byte_val);
  }
  return result;
}

int main() {
  // ECDSA public key in PEM format
  std::string public_key_pem {
R"(
-----BEGIN PUBLIC KEY-----
MFkwEwYHKoZIzj0CAQYIKoZIzj0DAQcDQgAEDd9VXmpHjV4voFO+0ZoFPlRr5icZXquxsr9EkaOUO9B7Wl1DAgGI0EKCm1++Bl2Od32xZFeFuG07OTpTMVOCPA==
-----END PUBLIC KEY-----
)"
  };

  // Message and signature in hexadecimal format
  std::string message_hex { "562d6ddfb3ceb5abb12d97bc35c4963d249f55b7c75eda618d365492ee98d469" };
  std::string signature_hex { "304502204d6d070117d445f4c2fcdbd4df037a1c8cfee2a166353c2e562cd5efd06e914d022100bb06439ded1478bd19022519dc06a84ba18ea4bf30ea9eb9ea90f8b66dad12c7" };

  // Convert hex strings to binary
  std::string message_data = hex_to_bytes(message_hex);
  std::string signature_data = hex_to_bytes(signature_hex);

  // Load the public key from PEM format
  BIO *key_bio = BIO_new_mem_buf(public_key_pem.data(), public_key_pem.length());
  assert(key_bio != nullptr);

  EC_KEY *ec_key = PEM_read_bio_EC_PUBKEY(key_bio, nullptr, nullptr, nullptr);
  assert(ec_key != nullptr);

  // Set up verification context
  EVP_MD_CTX *verify_ctx = EVP_MD_CTX_new();
  assert(verify_ctx != nullptr);

  EVP_PKEY *evp_pubkey = EVP_PKEY_new();
  assert(evp_pubkey != nullptr);

  assert(EVP_PKEY_assign_EC_KEY(evp_pubkey, ec_key) == 1);

  // Initialize verification with SHA-256
  assert(EVP_DigestVerifyInit(verify_ctx, nullptr, EVP_sha256(), nullptr, evp_pubkey) == 1);

  // Feed the message into the verification context
  assert(EVP_DigestVerifyUpdate(verify_ctx, message_data.data(), message_data.length()) == 1);

  // Finalize verification and check result
  int verify_result = EVP_DigestVerifyFinal(verify_ctx,
                                            reinterpret_cast<const unsigned char*>(signature_data.data()),
                                            signature_data.length());

  bool is_valid_signature = (verify_result == 1);

  // Clean up resources
  EVP_MD_CTX_free(verify_ctx);
  EVP_PKEY_free(evp_pubkey);

  // Assert that the signature is valid
  assert(is_valid_signature);
}

