// Base component class using CRTP
template <typename Derived>
class BaseComponent {
public:
    Derived* get() { return static_cast<Derived*>(this); }
};

// Position component representing 2D coordinates
class Position final : public BaseComponent<Position> {
public:
    Position(float x = 0.0f, float y = 0.0f) : x_(x), y_(y) {}

    float getX() const { return x_; }
    void setX(float newX) { x_ = newX; }

    float getY() const { return y_; }
    void setY(float newY) { y_ = newY; }

private:
    float x_, y_;
};

// Velocity component representing 2D velocity vector
class Velocity final : public BaseComponent<Velocity> {
public:
    Velocity(float vx = 0.0f, float vy = 0.0f) : vx_(vx), vy_(vy) {}

    float getX() const { return vx_; }
    void setX(float newVx) { vx_ = newVx; }

    float getY() const { return vy_; }
    void setY(float newVy) { vy_ = newVy; }

private:
    float vx_, vy_;
};

// Type alias for entity identifiers
using EntityID = std::size_t;

// Manages creation of unique entity IDs
class EntityRegistry {
public:
    EntityRegistry() : nextID_(0) {}

    EntityID generateEntity() {
        return nextID_++;
    }

private:
    EntityID nextID_;
};

// Template class to manage components of a specific type
template <typename ComponentType>
class ComponentStorage {
public:
    void assignComponent(EntityID id, const ComponentType& comp) {
        storage_[id] = comp;
    }

    ComponentType* fetchComponent(EntityID id) {
        auto iter = storage_.find(id);
        return (iter != storage_.end()) ? &(iter->second) : nullptr;
    }

private:
    std::unordered_map<EntityID, ComponentType> storage_;
};

int main() {
    EntityRegistry registry;
    ComponentStorage<Position> positionStore;
    ComponentStorage<Velocity> velocityStore;

    EntityID player = registry.generateEntity();
    Position startPos(15.0f, 25.0f);
    positionStore.assignComponent(player, startPos);

    Position* retrievedPos = positionStore.fetchComponent(player);

    if (retrievedPos) {
        std::cout << "Entity(" << player << ") position: (" 
                  << retrievedPos->getX() << "," << retrievedPos->getY() << ")\n";
    } else {
        std::cout << "Entity(" << player << ") has no Position.\n";
    }

    Velocity* retrievedVel = velocityStore.fetchComponent(player);

    if (retrievedVel) {
        std::cout << "Entity(" << player << ") velocity: (" 
                  << retrievedVel->getX() << "," << retrievedVel->getY() << ")\n";
    } else {
        std::cout << "Entity(" << player << ") has no Velocity.\n";
    }

    return 0;
}

