// Helper function to compute greatest common divisor (using Euclidean algorithm)
int compute_gcd(int a, int b) {
    while (b != 0) {
        int temp = b;
        b = a % b;
        a = temp;
    }
    return std::abs(a);
}

// Reduce fraction to simplest form, handling zero denominator specially
std::pair<int, int> simplify_fraction(int num, int den) {
    if (den == 0) {
        return {1, 0}; // Represent vertical line as (1, 0)
    }
    if (num == 0) {
        return {0, 1}; // Horizontal line as (0, 1)
    }

    int gcd_val = compute_gcd(num, den);
    int reduced_num = num / gcd_val;
    int reduced_den = den / gcd_val;

    // Ensure consistent sign representation: keep denominator positive
    if (reduced_den < 0) {
        reduced_num = -reduced_num;
        reduced_den = -reduced_den;
    }

    return {reduced_num, reduced_den};
}

// Count unique slopes formed by points relative to origin
std::map<std::pair<int, int>, int> tally_directions(const std::vector<std::pair<int, int>>& coords) {
    std::map<std::pair<int, int>, int> direction_counts;

    for (const auto& coordinate : coords) {
        int x_coord = coordinate.first;
        int y_coord = coordinate.second;

        if (y_coord == 0) {
            // Handle horizontal case explicitly
            direction_counts[{(x_coord > 0 ? 1 : -1), 0}]++;
        } else {
            auto simplified = simplify_fraction(x_coord, y_coord);
            direction_counts[simplified]++;
        }
    }

    return direction_counts;
}

int main() {
    std::vector<std::pair<int, int>> test_points = {{1, 2}, {2, 4}, {3, 0}, {1, 3}, {2, 6}};
    auto result = tally_directions(test_points);

    for (const auto& entry : result) {
        const auto& slope_pair = entry.first;
        int frequency = entry.second;
        std::cout << "(" << slope_pair.first << ", " << slope_pair.second << "): " << frequency << std::endl;
    }

    return 0;
}

#define checkCudaErrors(val) verifyCudaResult((val), #val, __FILE__, __LINE__)

template <typename T>
void verifyCudaResult(T code, char const *const funcName, char const *const fileName, int const lineNumber) {
    if (code != 0) {
        fprintf(stderr, "CUDA error in %s at line %d: error code %d (%s) for function \"%s\"\n", 
                fileName, lineNumber, static_cast<unsigned int>(code), cudaGetErrorName(code), funcName);
        cudaDeviceReset();
        exit(EXIT_FAILURE);
    }
}

#include <jni.h>
#include <cstdlib>
#include <cstdio>

// Define path separator and classpath for Java integration
#define PATH_SEPARATOR ';' 
#define USER_CLASSPATH "."

int main() {
    JNIEnv* env = nullptr;
    JavaVM* jvm = nullptr;
    jint result = 0;
    jclass testClass = nullptr;
    jmethodID staticMethodId = nullptr;
    jstring message = nullptr;
    jclass stringClass = nullptr;
    jobjectArray arguments = nullptr;

#ifdef JNI_VERSION_1_2
    // Initialize VM arguments using modern JNI interface
    JavaVMInitArgs vmArguments;
    JavaVMOption options[1];

    const char* pathString = "-Djava.class.path=" USER_CLASSPATH;
    options[0].optionString = const_cast<char*>(pathString);

    vmArguments.version = JNI_VERSION_1_2;
    vmArguments.options = options;
    vmArguments.nOptions = 1;
    vmArguments.ignoreUnrecognized = JNI_TRUE;

    // Attempt to create the JVM
    result = JNI_CreateJavaVM(&jvm, reinterpret_cast<void**>(&env), &vmArguments);
#else
    // Fallback for older JNI versions
    JDK1_1InitArgs vmArguments;
    char classPathBuffer[1024];

    vmArguments.version = JNI_VERSION_1_1;
    JNI_GetDefaultJavaVMInitArgs(&vmArguments);

    // Construct full classpath by appending user classpath
    std::snprintf(classPathBuffer, sizeof(classPathBuffer), "%s%c%s",
                  vmArguments.classpath, PATH_SEPARATOR, USER_CLASSPATH);
    vmArguments.classpath = classPathBuffer;

    // Attempt to create the JVM
    result = JNI_CreateJavaVM(&jvm, reinterpret_cast<void**>(&env), &vmArguments);
#endif

    // Handle JVM creation failure
    if (result < 0) {
        std::fprintf(stderr, "Failed to create Java Virtual Machine\n");
        std::exit(EXIT_FAILURE);
    }

    // Load the target Java class
    testClass = env->FindClass("TestJNIInvoke");
    if (testClass == nullptr) {
        goto cleanup;
    }

    // Get the method ID for the static main method
    staticMethodId = env->GetStaticMethodID(testClass, "main", "([Ljava/lang/String;)V");
    if (staticMethodId == nullptr) {
        goto cleanup;
    }

    // Prepare the argument for the Java main method
    message = env->NewStringUTF(" from CPP!");
    if (message == nullptr) {
        goto cleanup;
    }

    stringClass = env->FindClass("java/lang/String");
    if (stringClass == nullptr) {
        goto cleanup;
    }

    arguments = env->NewObjectArray(1, stringClass, message);
    if (arguments == nullptr) {
        goto cleanup;
    }

    // Invoke the static main method with the prepared arguments
    env->CallStaticVoidMethod(testClass, staticMethodId, arguments);

cleanup:
    // Check for and print any pending Java exceptions
    if (env != nullptr && env->ExceptionOccurred()) {
        env->ExceptionDescribe();
    }

    // Clean up the JVM resources
    if (jvm != nullptr) {
        jvm->DestroyJavaVM();
    }

    return 0;
}

