        .def(self != self)
        .def(self < self)
        .def(self <= self)
        .def(self > self)
        .def(self >= self);

    // Expose specific enum values as module-level constants
    def("FlagA", EnumAdapter(FlagEnum::FlagA));
    def("FlagB", EnumAdapter(FlagEnum::FlagB));
    // Additional flag exports can follow similarly
}

