#include <iostream>
using namespace std;

const int GRID_SIZE = 9;
const int EMPTY = 0;

bool isValidPlacement(int board[GRID_SIZE][GRID_SIZE], int r, int c, int value) {
    // Check row for duplicates
    for (int col = 0; col < GRID_SIZE; ++col) {
        if (board[r][col] == value) return false;
    }

    // Check column for duplicates
    for (int row = 0; row < GRID_SIZE; ++row) {
        if (board[row][c] == value) return false;
    }

    // Check 3x3 subgrid for duplicates
    int boxRowStart = (r / 3) * 3;
    int boxColStart = (c / 3) * 3;
    for (int i = 0; i < 3; ++i) {
        for (int j = 0; j < 3; ++j) {
            if (board[boxRowStart + i][boxColStart + j] == value) {
                return false;
            }
        }
    }

    return true;
}

bool locateEmptySlot(int board[GRID_SIZE][GRID_SIZE], int& r, int& c) {
    for (r = 0; r < GRID_SIZE; ++r) {
        for (c = 0; c < GRID_SIZE; ++c) {
            if (board[r][c] == EMPTY) {
                return true;
            }
        }
    }
    return false;
}

bool solveSudokuPuzzle(int board[GRID_SIZE][GRID_SIZE]) {
    int row, col;

    // Base case: no empty cells left means puzzle is solved
    if (!locateEmptySlot(board, row, col)) {
        return true;
    }

    // Try digits 1 through 9
    for (int digit = 1; digit <= 9; ++digit) {
        if (isValidPlacement(board, row, col, digit)) {
            board[row][col] = digit;

            // Recursively attempt to solve the rest of the grid
            if (solveSudokuPuzzle(board)) {
                return true;
            }

            // Backtrack if current digit doesn't lead to solution
            board[row][col] = EMPTY;
        }
    }

    // No valid digit found for this cell, backtrack
    return false;
}

void printBoard(int board[GRID_SIZE][GRID_SIZE]) {
    for (int i = 0; i < GRID_SIZE; ++i) {
        for (int j = 0; j < GRID_SIZE; ++j) {
            cout << board[i][j] << " ";
        }
        cout << "\n";
    }
}

int main() {
    int puzzle[GRID_SIZE][GRID_SIZE] = {
        {3, 0, 6, 5, 0, 8, 4, 0, 0},
        {5, 2, 0, 0, 0, 0, 0, 0, 0},
        {0, 8, 7, 0, 0, 0, 0, 3, 1},
        {0, 0, 3, 0, 1, 0, 0, 8, 0},
        {9, 0, 0, 8, 6, 3, 0, 0, 5},
        {0, 5, 0, 0, 9, 0, 6, 0, 0},
        {1, 3, 0, 0, 0, 0, 2, 5, 0},
        {0, 0, 0, 0, 0, 0, 0, 7, 4},
        {0, 0, 5, 2, 0, 6, 3, 0, 0}
    };

    if (solveSudokuPuzzle(puzzle)) {
        cout << "Sudoku solved.\n";
        printBoard(puzzle);
    } else {
        cout << "No solution exists.\n";
    }

    return 0;
}

#include <iostream>
using namespace std;

// Node structure for Binary Search Tree
struct TreeNode {
    int value;
    TreeNode* leftChild;
    TreeNode* rightChild;

    TreeNode(int v) : value(v), leftChild(nullptr), rightChild(nullptr) {}
};

class BinarySearchTree {
public:
    TreeNode* head;

    BinarySearchTree() : head(nullptr) {}

    void addValue(int val) {
        head = addRecursive(head, val);
    }

    void displayInorder() {
        displayInorderRecursive(head);
        cout << endl;
    }

    void removeValue(int val) {
        head = removeRecursive(head, val);
    }

private:
    TreeNode* addRecursive(TreeNode* node, int val) {
        if (node == nullptr) {
            node = new TreeNode(val);
            return node;
        }
        if (val < node->value) {
            node->leftChild = addRecursive(node->leftChild, val);
        } else if (val > node->value) {
            node->rightChild = addRecursive(node->rightChild, val);
        }
        return node;
    }

    void displayInorderRecursive(TreeNode* node) {
        if (node != nullptr) {
            displayInorderRecursive(node->leftChild);
            cout << node->value << " ";
            displayInorderRecursive(node->rightChild);
        }
    }

    TreeNode* findMinNode(TreeNode* node) {
        TreeNode* current = node;
        while (current && current->leftChild != nullptr) {
            current = current->leftChild;
        }
        return current;
    }

    TreeNode* removeRecursive(TreeNode* node, int val) {
        if (node == nullptr) return node;

        if (val < node->value) {
            node->leftChild = removeRecursive(node->leftChild, val);
        } else if (val > node->value) {
            node->rightChild = removeRecursive(node->rightChild, val);
        } else {
            // Node with only one child or no child
            if (node->leftChild == nullptr) {
                TreeNode* temp = node->rightChild;
                delete node;
                return temp;
            } else if (node->rightChild == nullptr) {
                TreeNode* temp = node->leftChild;
                delete node;
                return temp;
            }

            // Node with two children: get the inorder successor
            TreeNode* temp = findMinNode(node->rightChild);
            node->value = temp->value;
            node->rightChild = removeRecursive(node->rightChild, temp->value);
        }
        return node;
    }
};

int main() {
    BinarySearchTree bst;

    bst.addValue(50);
    bst.addValue(30);
    bst.addValue(20);
    bst.addValue(40);
    bst.addValue(70);
    bst.addValue(60);
    bst.addValue(80);

    cout << "Inorder traversal of the given tree: ";
    bst.displayInorder();

    bst.removeValue(20);
    cout << "Inorder traversal after removing 20: ";
    bst.displayInorder();

    bst.removeValue(30);
    cout << "Inorder traversal after removing 30: ";
    bst.displayInorder();

    bst.removeValue(50);
    cout << "Inorder traversal after removing 50: ";
    bst.displayInorder();

    return 0;
}

