#include <vector>
using namespace std;

// Perform insertion sort on the given vector
void insertion_sort(vector<int>& arr) {
    for (int pos = 1; pos < arr.size(); ++pos) {
        int current_value = arr[pos];
        int index = pos - 1;

        // Shift elements greater than current_value to the right
        while (index >= 0 && current_value < arr[index]) {
            arr[index + 1] = arr[index];
            --index;
        }

        // Place current_value at its correct position
        arr[index + 1] = current_value;
    }
}

