// Calculate Euclidean distance between two cities
double calcDistance(const City& point1, const City& point2) {
    int dx = point1.x - point2.x;
    int dy = point1.y - point2.y;
    return std::sqrt(dx * dx + dy * dy);
}

// Compute total tour length including return to start
double computeTourLength(const std::vector<int>& route, const std::vector<City>& locations) {
    double length = 0.0;
    for (size_t k = 0; k < route.size(); ++k) {
        int current = route[k];
        int next = route[(k + 1) % route.size()];
        length += calcDistance(locations[current], locations[next]);
    }
    return length;
}

// Apply 2-opt improvement heuristic
void improveTour(std::vector<int>& route, const std::vector<City>& places) {
    bool foundBetter = true;
    while (foundBetter) {
        foundBetter = false;
        for (size_t a = 1; a < route.size() - 2; ++a) {
            for (size_t b = a + 1; b < route.size(); ++b) {
                // Calculate current edge costs
                double oldCost = calcDistance(places[route[a-1]], places[route[a]]) + 
                                 calcDistance(places[route[b]], places[route[(b+1) % route.size()]]);

                // Calculate new edge costs after reversal
                double newCost = calcDistance(places[route[a-1]], places[route[b]]) + 
                                 calcDistance(places[route[a]], places[route[(b+1) % route.size()]]);

                if (newCost < oldCost - 1e-9) { // Use small epsilon for floating point comparison
                    std::reverse(route.begin() + a, route.begin() + b + 1);
                    foundBetter = true;
                }
            }
        }
    }
}

int main() {
    std::vector<City> locations = {{0, 0}, {1, 5}, {5, 1}, {5, 5}, {1, 1}};
    std::vector<int> route(locations.size());
    for (size_t i = 0; i < locations.size(); ++i) {
        route[i] = static_cast<int>(i);
    }

    std::cout << "Initial path: ";
    for (int city : route) {
        std::cout << city << " ";
    }
    std::cout << "\nInitial length: " << computeTourLength(route, locations) << std::endl;

    improveTour(route, locations);

    std::cout << "Improved path: ";
    for (int city : route) {
        std::cout << city << " ";
    }
    std::cout << "\nImproved length: " << computeTourLength(route, locations) << std::endl;

    return 0;
}

#include <iostream>
#include <vector>

using namespace std;

// Locate the earliest index where target appears in sorted array
int locateFirst(const vector<int>& data, int key) {
    int start = 0;
    int end = static_cast<int>(data.size()) - 1;
    int index = -1;

    while (start <= end) {
        int middle = start + (end - start) / 2;

        if (data[middle] == key) {
            index = middle;
            end = middle - 1; // Look for earlier occurrence on left side
        } else if (data[middle] < key) {
            start = middle + 1;
        } else {
            end = middle - 1;
        }
    }

    return index;
}

// Locate the latest index where target appears in sorted array
int locateLast(const vector<int>& data, int key) {
    int start = 0;
    int end = static_cast<int>(data.size()) - 1;
    int index = -1;

    while (start <= end) {
        int middle = start + (end - start) / 2;

        if (data[middle] == key) {
            index = middle;
            start = middle + 1; // Look for later occurrence on right side
        } else if (data[middle] < key) {
            start = middle + 1;
        } else {
            end = middle - 1;
        }
    }

    return index;
}

// Get both first and last positions of target in sorted array
pair<int, int> locateRange(const vector<int>& data, int key) {
    int firstPos = locateFirst(data, key);

    if (firstPos == -1) {
        return {-1, -1}; // Key not present
    }

    int lastPos = locateLast(data, key);
    return {firstPos, lastPos};
}

int main() {
    vector<int> sequence = {1, 2, 2, 2, 3, 4, 4, 5, 6};
    int searchValue = 2;

    auto [beginIndex, endIndex] = locateRange(sequence, searchValue);

    if (beginIndex == -1) {
        cout << "Target value not found" << endl;
    } else {
        cout << "First position at index: " << beginIndex << endl;
        cout << "Last position at index: " << endIndex << endl;
    }

    return 0;
}

