class ZYLThreadPool {
public:
    ZYLThreadPool(size_t initialThreads = 20, size_t maxAllowedThreads = 200)
        : _initial(initialThreads)
        , _maximum(maxAllowedThreads)
        , _shutdown(false) {
        threads.reserve(_maximum);
        for (size_t t = 0; t < _initial; ++t) {
            spawn_thread();
        }
    }

    void spawn_thread() {
        threads.emplace_back([this] {
            while (true) {
                std::function<void()> job;
                {
                    std::unique_lock<std::mutex> guard(_mtx);
                    _cv.wait(guard, [this] {
                        return _shutdown || !_jobs.empty();
                    });
                    if (_shutdown && _jobs.empty())
                        break;
                    job = std::move(_jobs.front());
                    _jobs.pop_front();
                }
                job();
            }
        });
    }

    template <typename F, typename... Args>
    auto enqueue(F&& func, Args&&... params)
        -> std::future<typename std::result_of<F(Args...)>::type> {
        using result_t = typename std::result_of<F(Args...)>::type;

        auto packaged = std::make_shared<std::packaged_task<result_t()>>(
            std::bind(std::forward<F>(func), std::forward<Args>(params)...));

        std::future<result_t> outcome = packaged->get_future();

        {
            std::unique_lock<std::mutex> guard(_mtx);
            if (_shutdown) {
                throw std::runtime_error("Enqueue on stopped ZYLThreadPool");
            }
            if (_jobs.size() >= threads.size() && threads.size() < _maximum) {
                spawn_thread();
            }
            _jobs.emplace_back([packaged] { (*packaged)(); });
        }
        _cv.notify_one();
        return outcome;
    }

    void shutdown() {
        std::unique_lock<std::mutex> guard(_mtx);
        if (!_shutdown) {
            _shutdown = true;
            _cv.notify_all();
        }
        for (std::thread& worker : threads)
            worker.join();
    }

    size_t pending_jobs() {
        std::unique_lock<std::mutex> guard(_mtx);
        return _jobs.size();
    }

    ~ZYLThreadPool() {
        shutdown();
    }

private:
    std::vector<std::thread> threads;
    std::deque<std::function<void()>> _jobs;
    size_t _initial;
    size_t _maximum;
    std::mutex _mtx;
    std::condition_variable _cv;
    bool _shutdown;
};

class WorkerTask {
public:
    WorkerTask(double identifier)
        : _id(identifier)
        , _active(true) {
    }

    void launch(ZYLThreadPool& pool) {
        _result = pool.enqueue(&WorkerTask::_run, this);
    }

    void terminate() {
        {
            _active = false;
            std::unique_lock<std::mutex> lock(_mtx);

            if (_result.valid()) {
                _result.get();
                lock.unlock();
                _finalize();
            }
        }
    }

private:
    std::mutex _mtx;
    double _id;
    std::deque<double> _buffer;
    std::future<void> _result;
    bool _active;

    void _finalize() {
        std::unique_lock<std::mutex> lock(_mtx);
        _buffer.clear();
    }

    void _run() {
        std::unique_lock<std::mutex> lock(_mtx);
        while (_active) {
            if (_buffer.empty()) {
                std::cout << "executing task" << std::endl;
                continue;
            }
            double item = _buffer.front();
            _buffer.pop_front();
            lock.unlock();
            std::cout << "processing item" << std::endl;
            lock.lock();
        }
    }
};

int main() {
    ZYLThreadPool pool(20, 200);
    std::vector<std::shared_ptr<WorkerTask>> tasks;

    for (int idx = 0; idx < 100; ++idx) {
        auto worker = std::make_shared<WorkerTask>(1.0);
        worker->launch(pool);
        tasks.push_back(worker);
    }

    std::this_thread::sleep_for(std::chrono::seconds(3));

    for (auto& task : tasks) {
        task->terminate();
    }
    tasks.clear();

    for (int count = 0; count < 3; ++count) {
        auto worker = std::make_shared<WorkerTask>(1.0);
        worker->launch(pool);
        tasks.push_back(worker);
    }

    std::this_thread::sleep_for(std::chrono::seconds(3));

    for (auto& task : tasks) {
        task->terminate();
    }

    return 0;
}

