// Helper function to determine if a number is prime
bool checkPrime(int value) {
    if (value <= 1)
        return false;

    if (value == 2)
        return true;

    if (value % 2 == 0)
        return false;

    int limit = static_cast<int>(std::sqrt(value));
    for (int j = 3; j <= limit; j += 2) {
        if (value % j == 0)
            return false;
    }

    return true;
}

// Function to count the digits in a positive integer
int countDigits(int n) {
    if (n == 0)
        return 1;

    int cnt = 0;
    while (n > 0) {
        cnt++;
        n /= 10;
    }
    return cnt;
}

// Find the largest prime number (by digit count) in the list
int getLongestPrimeByDigitCount(const std::vector<int>& numbers) {
    int longestLength = -1;
    int resultValue = -1;

    for (size_t idx = 0; idx < numbers.size(); ++idx) {
        int current = numbers[idx];

        if (checkPrime(current)) {
            int digitCount = countDigits(current);

            if (digitCount > longestLength) {
                longestLength = digitCount;
                resultValue = current;
            }
        }
    }

    return resultValue;
}

int main() {
    std::vector<int> data = {1, 3, 131, 323, 5107, 34, 8278, 109, 163, 2323, 321, 3039, 31};

    int answer = getLongestPrimeByDigitCount(data);

    std::cout << "The prime number with the maximum number of digits is: " << answer << std::endl;

    return 0;
}

