// Check if character is a lowercase consonant
bool isConsonant(char ch) {
    return std::islower(ch) && 
           ch != 'a' && 
           ch != 'e' && 
           ch != 'i' && 
           ch != 'o' && 
           ch != 'u';
}

// Compute sum of ASCII values for lowercase consonants at odd positions
int calculateOddPositionConsonantSum(const std::string& text) {
    int total = 0;
    size_t index = 1; // Start from first odd index (1)

    while (index < text.length()) {
        if (isConsonant(text[index])) {
            total += static_cast<int>(text[index]);
        }
        index += 2; // Move to next odd index
    }

    return total;
}

int main() {
    std::string sampleText = "aBcDeFgHiJkL";
    int computedValue = calculateOddPositionConsonantSum(sampleText);
    std::cout << "Sum of ASCII values of lowercase consonants at odd indices: " 
              << computedValue << std::endl;
    return 0;
}

