// Macro to check OpenGL errors after each call
#define GL_CHECK(cmd) \
    do { \
        cmd; \
        GLenum err = glGetError(); \
        if (err != GL_NO_ERROR) { \
            std::cerr << "OpenGL error " << err << " at " << __FILE__ << ":" << __LINE__ << std::endl; \
            exit(EXIT_FAILURE); \
        } \
    } while(0)

// Vertex shader source code
const char* vertexShaderSource = R"(
#version 320 es

layout(location = 0) in vec2 a_position;
layout(location = 1) in vec2 a_texCoord;
out vec2 v_texCoord;

void main() {
    gl_Position = vec4(a_position, 0.0, 1.0);
    v_texCoord = a_texCoord;
}
)";

// Fragment shader source code
const char* fragmentShaderSource = R"(
#version 320 es

precision mediump float;
in vec2 v_texCoord;
out vec4 outColor;

uniform sampler2D u_sampler;

void main() {
    outColor = texture(u_sampler, v_texCoord);
}
)";

// Triangle vertex positions (rearranged for different geometry)
float vertices[] = {
    // First triangle: bottom-left corner
    -1.0f, -1.0f,
    -1.0f,  0.5f,
     0.5f, -1.0f,

    // Second triangle: top-right corner
     0.5f, -1.0f,
    -1.0f,  0.5f,
     0.5f,  0.5f
};

// Texture coordinates corresponding to the above vertices
float texCoords[] = {
    // First triangle
    0.0f, 1.0f,
    0.0f, 0.5f,
    0.5f, 1.0f,

    // Second triangle
    0.5f, 1.0f,
    0.0f, 0.5f,
    0.5f, 0.5f
};

// Helper function to compile shaders
GLuint buildShader(GLenum type, const char* src) {
    GLuint shader = glCreateShader(type);
    GL_CHECK(glShaderSource(shader, 1, &src, nullptr));
    GL_CHECK(glCompileShader(shader));

    GLint compiled;
    GL_CHECK(glGetShaderiv(shader, GL_COMPILE_STATUS, &compiled));
    if (!compiled) {
        GLsizei logLen;
        GL_CHECK(glGetShaderiv(shader, GL_INFO_LOG_LENGTH, &logLen));
        std::vector<GLchar> infoLog(logLen + 1);
        GL_CHECK(glGetShaderInfoLog(shader, logLen, &logLen, infoLog.data()));
        std::cerr << "Shader compilation failed:\n" << infoLog.data() << std::endl;
        exit(EXIT_FAILURE);
    }
    return shader;
}

// Build and link program from vertex and fragment shaders
GLuint createRenderingProgram() {
    GLuint vs = buildShader(GL_VERTEX_SHADER, vertexShaderSource);
    GLuint fs = buildShader(GL_FRAGMENT_SHADER, fragmentShaderSource);

    GLuint program = glCreateProgram();
    GL_CHECK(glAttachShader(program, vs));
    GL_CHECK(glAttachShader(program, fs));
    GL_CHECK(glLinkProgram(program));

    GLint linked;
    GL_CHECK(glGetProgramiv(program, GL_LINK_STATUS, &linked));
    if (!linked) {
        GLsizei logLen;
        GL_CHECK(glGetProgramiv(program, GL_INFO_LOG_LENGTH, &logLen));
        std::vector<GLchar> infoLog(logLen + 1);
        GL_CHECK(glGetProgramInfoLog(program, logLen, &logLen, infoLog.data()));
        std::cerr << "Program linking failed:\n" << infoLog.data() << std::endl;
        exit(EXIT_FAILURE);
    }

    GL_CHECK(glDeleteShader(vs));
    GL_CHECK(glDeleteShader(fs));
    return program;
}

int main() {
    EGLDisplay display = eglGetDisplay(EGL_DEFAULT_DISPLAY);
    eglInitialize(display, nullptr, nullptr);

    EGLint configAttribs[] = {
        EGL_RENDERABLE_TYPE, EGL_OPENGL_ES3_BIT,
        EGL_RED_SIZE, 8,
        EGL_GREEN_SIZE, 8,
        EGL_BLUE_SIZE, 8,
        EGL_DEPTH_SIZE, 24,
        EGL_NONE
    };

    EGLConfig config;
    EGLint numConfigs;
    eglChooseConfig(display, configAttribs, &config, 1, &numConfigs);

    EGLint contextAttrs[] = {EGL_CONTEXT_CLIENT_VERSION, 3, EGL_NONE};
    EGLContext context = eglCreateContext(display, config, nullptr, contextAttrs);

    EGLint surfaceAttrs[] = {EGL_WIDTH, 800, EGL_HEIGHT, 600, EGL_NONE};
    EGLSurface surface = eglCreatePbufferSurface(display, config, surfaceAttrs);

    eglMakeCurrent(display, surface, surface, context);

    // Setup rendering pipeline
    GLuint program = createRenderingProgram();
    GL_CHECK(glUseProgram(program));

    // Position buffer setup
    GLuint vboPos;
    GL_CHECK(glGenBuffers(1, &vboPos));
    GL_CHECK(glBindBuffer(GL_ARRAY_BUFFER, vboPos));
    GL_CHECK(glBufferData(GL_ARRAY_BUFFER, sizeof(vertices), vertices, GL_STATIC_DRAW));

    GLuint posLoc = glGetAttribLocation(program, "a_position");
    GL_CHECK(glEnableVertexAttribArray(posLoc));
    GL_CHECK(glVertexAttribPointer(posLoc, 2, GL_FLOAT, GL_FALSE, 0, nullptr));

    // Texture coordinate buffer setup
    GLuint vboTex;
    GL_CHECK(glGenBuffers(1, &vboTex));
    GL_CHECK(glBindBuffer(GL_ARRAY_BUFFER, vboTex));
    GL_CHECK(glBufferData(GL_ARRAY_BUFFER, sizeof(texCoords), texCoords, GL_STATIC_DRAW));

    GLuint texLoc = glGetAttribLocation(program, "a_texCoord");
    GL_CHECK(glEnableVertexAttribArray(texLoc));
    GL_CHECK(glVertexAttribPointer(texLoc, 2, GL_FLOAT, GL_FALSE, 0, nullptr));

    // Texture setup
    GLuint tex;
    GL_CHECK(glGenTextures(1, &tex));
    GL_CHECK(glActiveTexture(GL_TEXTURE0));
    GL_CHECK(glBindTexture(GL_TEXTURE_2D, tex));

    // Load images using OpenCV
    cv::Mat img0 = cv::imread("input0.png");
    cv::Mat img1 = cv::imread("input1.png");
    cv::Mat img2 = cv::imread("input2.png");
    cv::Mat img3 = cv::imread("input3.png");

    // Upload first image as texture data
    GL_CHECK(glTexImage2D(GL_TEXTURE_2D, 0, GL_RGBA, img0.cols, img0.rows, 0,
                          GL_RGBA, GL_UNSIGNED_BYTE, img0.data));

    // Set uniform sampler
    GLint samplerLoc = glGetUniformLocation(program, "u_sampler");
    GL_CHECK(glUniform1i(samplerLoc, 0));

    // Main render loop
    while (true) {
        GLenum err = glGetError();
        if (err != GL_NO_ERROR) {
            std::cerr << "Runtime OpenGL error: " << err << std::endl;
            break;
        }

        GL_CHECK(glClear(GL_COLOR_BUFFER_BIT | GL_DEPTH_BUFFER_BIT));
        GL_CHECK(glDrawArrays(GL_TRIANGLES, 0, 6));
        eglSwapBuffers(display, surface);
    }

    // Cleanup resources
    GL_CHECK(glDeleteTextures(1, &tex));
    GL_CHECK(glDeleteBuffers(1, &vboPos));
    GL_CHECK(glDeleteBuffers(1, &vboTex));
    GL_CHECK(glDeleteProgram(program));

    eglDestroySurface(display, surface);
    eglDestroyContext(display, context);
    eglTerminate(display);

    return 0;
}

#include <cuda_runtime.h>
#include <iostream>

#define MATRIX_SIZE 1000

__global__ void matrixMultiply(float *inputA, float *inputB, float *outputC, int size) {
    int rowIndex = blockIdx.y * blockDim.y + threadIdx.y;
    int colIndex = blockIdx.x * blockDim.x + threadIdx.x;

    if (rowIndex < size && colIndex < size) {
        float accumulator = 0.0f;
        for (int k = 0; k < size; k++) {
            accumulator += inputA[rowIndex * size + k] * inputB[k * size + colIndex];
        }
        outputC[rowIndex * size + colIndex] = accumulator;
    }
}

int main() {
    float *hostA, *hostB, *hostC;
    float *deviceA, *deviceB, *deviceC;

    // Allocate host memory
    hostA = (float*)malloc(MATRIX_SIZE * MATRIX_SIZE * sizeof(float));
    hostB = (float*)malloc(MATRIX_SIZE * MATRIX_SIZE * sizeof(float));
    hostC = (float*)malloc(MATRIX_SIZE * MATRIX_SIZE * sizeof(float));

    // Initialize matrices with constant values
    for (int idx = 0; idx < MATRIX_SIZE * MATRIX_SIZE; idx++) {
        hostA[idx] = 1.0f;
        hostB[idx] = 2.0f;
    }

    // Allocate device memory
    cudaMalloc(&deviceA, MATRIX_SIZE * MATRIX_SIZE * sizeof(float));
    cudaMalloc(&deviceB, MATRIX_SIZE * MATRIX_SIZE * sizeof(float));
    cudaMalloc(&deviceC, MATRIX_SIZE * MATRIX_SIZE * sizeof(float));

    // Transfer data from host to device
    cudaMemcpy(deviceA, hostA, MATRIX_SIZE * MATRIX_SIZE * sizeof(float), cudaMemcpyHostToDevice);
    cudaMemcpy(deviceB, hostB, MATRIX_SIZE * MATRIX_SIZE * sizeof(float), cudaMemcpyHostToDevice);

    // Configure execution configuration
    dim3 blockSize(16, 16);
    dim3 gridSize((MATRIX_SIZE + blockSize.x - 1) / blockSize.x, 
                  (MATRIX_SIZE + blockSize.y - 1) / blockSize.y);

    // Execute the kernel
    matrixMultiply<<<gridSize, blockSize>>>(deviceA, deviceB, deviceC, MATRIX_SIZE);

    // Copy results back to host
    cudaMemcpy(hostC, deviceC, MATRIX_SIZE * MATRIX_SIZE * sizeof(float), cudaMemcpyDeviceToHost);

    // Release device resources
    cudaFree(deviceA);
    cudaFree(deviceB);
    cudaFree(deviceC);

    // Release host resources
    free(hostA);
    free(hostB);
    free(hostC);

    return 0;
}

