// Function to set up file associations for the application
void SetupFileAssociations()
{
    HKEY hKey = nullptr;
    LONG result = ERROR_SUCCESS;

    // Set application identifier under HKCU
    result = RegCreateKeyEx(HKEY_CURRENT_USER, TEXT("Software\\MyApp"), 0, nullptr, 0, KEY_WRITE, nullptr, &hKey, nullptr);
    if (result == ERROR_SUCCESS)
    {
        const TCHAR* appId = TEXT("MyApp");
        RegSetValueEx(hKey, TEXT("AppUserModelID"), 0, REG_SZ, 
                      reinterpret_cast<const BYTE*>(appId), 
                      (_tcslen(appId) + 1) * sizeof(TCHAR));
        RegCloseKey(hKey);
        hKey = nullptr;
    }

    // Associate .myext extension with MyApp.MyFileType
    result = RegCreateKeyEx(HKEY_CLASSES_ROOT, TEXT(".myext"), 0, nullptr, 0, KEY_WRITE, nullptr, &hKey, nullptr);
    if (result == ERROR_SUCCESS)
    {
        const TCHAR* fileType = TEXT("MyApp.MyFileType");
        RegSetValueEx(hKey, nullptr, 0, REG_SZ, 
                      reinterpret_cast<const BYTE*>(fileType), 
                      (_tcslen(fileType) + 1) * sizeof(TCHAR));
        RegCloseKey(hKey);
        hKey = nullptr;
    }

    // Define command for opening files with MyApp
    result = RegCreateKeyEx(HKEY_CLASSES_ROOT, TEXT("MyApp.MyFileType\\Shell\\Open\\Command"), 0, nullptr, 0, KEY_WRITE, nullptr, &hKey, nullptr);
    if (result == ERROR_SUCCESS)
    {
        const TCHAR* command = TEXT("\"C:\\Path\\To\\MyApp.exe\" \"%1\"");
        RegSetValueEx(hKey, nullptr, 0, REG_SZ, 
                      reinterpret_cast<const BYTE*>(command), 
                      (_tcslen(command) + 1) * sizeof(TCHAR));
        RegCloseKey(hKey);
        hKey = nullptr;
    }

    // Register ProgID metadata
    result = RegCreateKeyEx(HKEY_CLASSES_ROOT, TEXT("MyApp.MyFileType"), 0, nullptr, 0, KEY_WRITE, nullptr, &hKey, nullptr);
    if (result == ERROR_SUCCESS)
