// Compute dot products of vector pairs in parallel on GPU
__global__ void gpu_vector_dot_product(Eigen::Vector3d* input_a, 
                                        Eigen::Vector3d* input_b, 
                                        double* result_buffer, 
                                        size_t total_elements)
{
    // Calculate global thread index
    int thread_id = blockIdx.x * blockDim.x + threadIdx.x;

    // Process only valid indices
    if (thread_id < total_elements)
