// Compute the factorial of a non-negative integer using an iterative approach
long long computeFactorial(int value) {
    if (value < 0) {
        throw std::invalid_argument("Factorial is undefined for negative values");
    }

    long long result = 1;
    for (int i = 2; i <= value; ++i) {
        result *= i;
    }
    return result;
}

// Validate the correctness of the factorial implementation
void validateFactorial() {
    if (computeFactorial(0) != 1) throw std::runtime_error("Test failed: factorial(0)");
    if (computeFactorial(1) != 1) throw std::runtime_error("Test failed: factorial(1)");
    if (computeFactorial(5) != 120) throw std::runtime_error("Test failed: factorial(5)");
    if (computeFactorial(10) != 3628800) throw std::runtime_error("Test failed: factorial(10)");

    std::cout << "All tests passed successfully." << std::endl;
}

int main() {
    try {
        validateFactorial();
    } catch (const std::exception& err) {
        std::cerr << "Error: " << err.what() << std::endl;
    }
    return 0;
}

