// Compute optimal decision stump parameters using weighted error minimization
std::tuple<double, double, int> computeStumpParameters(
    const std::vector<double>& samples,
    const std::vector<int>& labels,
    const std::vector<double>& weights) {

    // Step 1: Compute feature representations from input samples
    std::vector<double> feature_values = calculateFeatureValues(samples);

    // Step 2: Combine and sort data by feature values
    std::vector<std::tuple<double, int, double>> combined_data;
    for (size_t idx = 0; idx < feature_values.size(); ++idx) {
        combined_data.emplace_back(feature_values[idx], labels[idx], weights[idx]);
    }
    std::sort(combined_data.begin(), combined_data.end());

    // Step 3: Prepare tracking variables for best configuration
    double optimal_threshold = 0.0;
    double minimal_error = std::numeric_limits<double>::infinity();
    int optimal_polarity = 1;

    // Step 4: Evaluate thresholds derived from sorted feature values
    double cumulative_weight = std::accumulate(weights.begin(), weights.end(), 0.0);
    double false_positive_cost = 0.0;
    double false_negative_cost = cumulative_weight;

    for (size_t pos = 0; pos < combined_data.size(); ++pos) {
        double current_value = std::get<0>(combined_data[pos]);
        int current_label = std::get<1>(combined_data[pos]);
        double sample_weight = std::get<2>(combined_data[pos]);

        // Check if current threshold yields better result
        double candidate_error = std::min(false_positive_cost, false_negative_cost);
        if (candidate_error < minimal_error) {
            minimal_error = candidate_error;
            optimal_threshold = current_value;
            optimal_polarity = (false_positive_cost < false_negative_cost) ? 1 : -1;
        }

        // Adjust error counters based on current sample's label
        if (current_label == 1) {
            false_positive_cost += sample_weight;
            false_negative_cost -= sample_weight;
        } else {
            false_positive_cost -= sample_weight;
            false_negative_cost += sample_weight;
        }
    }

    // Step 5: Finalize and return the optimal configuration
    return {optimal_threshold, minimal_error, optimal_polarity};
}

