#include <android/native_window.h>
#include <EGL/egl.h>

// Initialize EGL and create main + auxiliary contexts for OpenGL ES 2.0 rendering
void InitializeEGL(ANativeWindow* nativeWindow) {
    EGLDisplay display = eglGetDisplay(EGL_DEFAULT_DISPLAY);

    if (display == EGL_NO_DISPLAY) {
        // Handle error: could not get EGL display
        return;
    }

    if (!eglInitialize(display, nullptr, nullptr)) {
        // Error handling for EGL initialization failure
        return;
    }

    // Configure context attributes for OpenGL ES 2.0
    EGLint contextAttrs[] = {
        EGL_CONTEXT_CLIENT_VERSION, 2,
        EGL_NONE
    };

    // Main surface configuration attributes
    const EGLint mainConfigAttrs[] = {
        EGL_SURFACE_TYPE,     EGL_WINDOW_BIT,
        EGL_RENDERABLE_TYPE,  EGL_OPENGL_ES2_BIT,
        EGL_BLUE_SIZE,        8,
        EGL_GREEN_SIZE,       8,
        EGL_RED_SIZE,         8,
        EGL_ALPHA_SIZE,       8,
        EGL_BUFFER_SIZE,      32,
        EGL_DEPTH_SIZE,       24,
        EGL_NONE
    };

    EGLint configCount;
    EGLConfig mainConfig;

    if (!eglChooseConfig(display, mainConfigAttrs, &mainConfig, 1, &configCount) || configCount == 0) {
        // Failed to select appropriate EGL config
        return;
    }

    // Query native visual ID for buffer geometry setup
    EGLint visualFormat;
    if (!eglGetConfigAttrib(display, mainConfig, EGL_NATIVE_VISUAL_ID, &visualFormat)) {
        return;
    }

    // Apply buffer geometry based on native visual format
    ANativeWindow_setBuffersGeometry(nativeWindow, 0, 0, visualFormat);

    // Create window surface
    EGLSurface mainSurface = eglCreateWindowSurface(display, mainConfig, nativeWindow, nullptr);
    if (mainSurface == EGL_NO_SURFACE) {
        return;
    }

    // Create main rendering context
    EGLContext mainContext = eglCreateContext(display, mainConfig, EGL_NO_CONTEXT, contextAttrs);
    if (mainContext == EGL_NO_CONTEXT) {
        eglDestroySurface(display, mainSurface);
        return;
    }

    // Auxiliary pbuffer configuration for offscreen operations
    const EGLint pbufferConfigAttrs[] = {
        EGL_SURFACE_TYPE,     EGL_PBUFFER_BIT,
        EGL_RENDERABLE_TYPE,  EGL_OPENGL_ES2_BIT,
        EGL_BLUE_SIZE,        8,
        EGL_GREEN_SIZE,       8,
        EGL_RED_SIZE,         8,
        EGL_ALPHA_SIZE,       8,
        EGL_DEPTH_SIZE,       0,
        EGL_STENCIL_SIZE,     0,
        EGL_NONE
    };

    EGLint auxConfigCount;
    EGLConfig auxConfig;

    if (!eglChooseConfig(display, pbufferConfigAttrs, &auxConfig, 1, &auxConfigCount) || auxConfigCount == 0) {
        eglDestroyContext(display, mainContext);
        eglDestroySurface(display, mainSurface);
        return;
    }

    // Define pbuffer attributes
    EGLint pbufferAttrs[] = {
        EGL_WIDTH,              1,
        EGL_HEIGHT,             1,
        EGL_TEXTURE_TARGET,     EGL_NO_TEXTURE,
        EGL_TEXTURE_FORMAT,     EGL_NO_TEXTURE,
        EGL_NONE
    };

    // Create pbuffer surface
    EGLSurface auxSurface = eglCreatePbufferSurface(display, auxConfig, pbufferAttrs);
    if (auxSurface == EGL_NO_SURFACE) {
        eglDestroyContext(display, mainContext);
        eglDestroySurface(display, mainSurface);
        return;
    }

    // Create auxiliary context sharing resources with main context
    EGLContext auxContext = eglCreateContext(display, auxConfig, mainContext, contextAttrs);
    if (auxContext == EGL_NO_CONTEXT) {
        eglDestroySurface(display, auxSurface);
        eglDestroyContext(display, mainContext);
        eglDestroySurface(display, mainSurface);
        return;
    }

    // Activate the main rendering context
    if (!eglMakeCurrent(display, mainSurface, mainSurface, mainContext)) {
        eglDestroyContext(display, auxContext);
        eglDestroySurface(display, auxSurface);
        eglDestroyContext(display, mainContext);
        eglDestroySurface(display, mainSurface);
        return;
    }
}

