// Check if two strings are anagrams by comparing character counts
bool areAnagrams(std::string s1, std::string s2) {
    if (s1.length() != s2.length()) {
        return false;
    }

    // Use frequency arrays instead of sorting
    int count[256] = {0};

    // Count characters in first string
    for (char c : s1) {
        count[(unsigned char)c]++;
    }

    // Subtract counts for second string
    for (char c : s2) {
        count[(unsigned char)c]--;
    }

    // If all counts are zero, they are anagrams
    for (int i = 0; i < 256; i++) {
        if (count[i] != 0) {
            return false;
        }
    }

    return true;
}

int main() {
    std::string s1 = "listen";
    std::string s2 = "silent";
    std::cout << std::boolalpha << areAnagrams(s1, s2) << std::endl;  // Output: true
    return 0;
}

