};

JNIEXPORT jobject JNICALL Java_MyClass_getRosterMap(JNIEnv* env, jobject) {
    // Load required Java classes
    jclass hashMapClass = env->FindClass("java/util/HashMap");
    jclass booleanClass = env->FindClass("java/lang/Boolean");

    // Get constructors and method IDs
    jmethodID hashMapConstructor = env->GetMethodID(hashMapClass, "<init>", "()V");
    jmethodID booleanConstructor = env->GetMethodID(booleanClass, "<init>", "(Z)V");
    jmethodID putMethod = env->GetMethodID(hashMapClass, "put", 
        "(Ljava/lang/Object;Ljava/lang/Object;)Ljava/lang/Object;");

    // Instantiate the HashMap
    jobject resultMap = env->NewObject(hashMapClass, hashMapConstructor);

    // Early return if roster map is null or empty
    std::map<std::string, RosterItem>* rosterData = GetRosterMap();
    if (!rosterData || rosterData->empty()) {
        return resultMap;
    }

    // Iterate through the internal roster map and populate the Java HashMap
    for (auto& entry : *rosterData) {
        const std::string& itemName = entry.second.name;
        jstring jName = env->NewStringUTF(itemName.c_str());

        jboolean jIsFriend = static_cast<jboolean>(entry.second.isfriend);
        jobject jBoolValue = env->NewObject(booleanClass, booleanConstructor, jIsFriend);

        env->CallObjectMethod(resultMap, putMethod, jName, jBoolValue);
        env->DeleteLocalRef(jName);   // Optional: avoid local ref overflow
        env->DeleteLocalRef(jBoolValue);
    }

    return resultMap;
}

#include <string>
#include <vector>
#include <cctype>

std::vector<unsigned char> base64_decode(const std::string &input) {
    const std::string base64_table =
        "ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        "abcdefghijklmnopqrstuvwxyz"
        "0123456789+/";

    std::vector<unsigned char> result;
    unsigned char buffer[4];
    int buffer_count = 0;
    size_t pos = 0;

    while (pos < input.size()) {
        char current_char = input[pos];

        // Skip padding and non-base64 characters
        if (current_char == '=' || !isalnum(current_char) && current_char != '+' && current_char != '/') {
            break;
        }

        // Find the index of the character in the base64 table
        size_t char_index = base64_table.find(current_char);
        if (char_index == std::string::npos) {
            break;
        }

        buffer[buffer_count++] = static_cast<unsigned char>(char_index);

        // When we have 4 characters, decode them into 3 bytes
        if (buffer_count == 4) {
            result.push_back((buffer[0] << 2) | (buffer[1] >> 4));
            result.push_back(((buffer[1] & 0x0F) << 4) | (buffer[2] >> 2));
            result.push_back(((buffer[2] & 0x03) << 6) | buffer[3]);
            buffer_count = 0;
        }

        ++pos;
    }

    // Handle remaining characters (partial group)
    if (buffer_count > 1) {
        // Pad with zeros for missing characters
        for (int i = buffer_count; i < 4; ++i) {
            buffer[i] = 0;
        }

        // Decode partial group
        result.push_back((buffer[0] << 2) | (buffer[1] >> 4));
        if (buffer_count > 2) {
            result.push_back(((buffer[1] & 0x0F) << 4) | (buffer[2] >> 2));
        }
    }

    return result;
}

