// Perform subtraction and capture flags using inline assembly
int temp_result;
asm volatile (
    "sub %4, %5, %6\n\t"      // Compute %5 - %6, store in %4
    "ite eq\n\t"              // if-then-else for equal condition
    "movne %0, #0\n\t"        // Z_FLAG = 0 if not equal
    "moveq %0, #1\n\t"        // Z_FLAG = 1 if equal
    "ite lt\n\t"              // if-then-else for less than
    "movge %1, #0\n\t"        // N_FLAG = 0 if not less than
    "movlt %1, #1\n\t"        // N_FLAG = 1 if less than
    "ite cs\n\t"              // if-then-else for carry set
    "movcc %2, #1\n\t"        // C_FLAG = 1 if carry clear
    "movcs %2, #0\n\t"        // C_FLAG = 0 if carry set
    "ite vs\n\t"              // if-then-else for overflow set
    "movvc %3, #0\n\t"        // V_FLAG = 0 if no overflow
    "movvs %3, #1"            // V_FLAG = 1 if overflow
    : "=r" (zero_flag), "=r" (negative_flag), "=r" (carry_flag), "=r" (overflow_flag)
    : "r" (reg[dest].I), "r" (reg[base].I), "r" (value)
    : "cc"
);

