LRESULT CALLBACK MainWndProc(HWND, UINT, WPARAM, LPARAM);
void PinToNotificationArea(HWND);

// Custom message identifier for tray icon events
#define WM_TRAYMSG (WM_USER + 100)

int APIENTRY WinMain(HINSTANCE hInstance, HINSTANCE, LPSTR, int nShowCmd) {
    const char* WINDOW_CLASS = "TrayAppWindow";

    WNDCLASS wc = {};
    wc.lpfnWndProc   = MainWndProc;
    wc.hInstance     = hInstance;
    wc.lpszClassName = WINDOW_CLASS;
    wc.hCursor       = LoadCursor(NULL, IDC_ARROW);
    wc.hbrBackground = (HBRUSH)(COLOR_WINDOW + 1);

    if (!RegisterClass(&wc)) {
        return 1;
    }

    HWND hWnd = CreateWindowEx(
        0,
        WINDOW_CLASS,
        "Notification Area Demo",
        WS_OVERLAPPEDWINDOW,
        CW_USEDEFAULT, CW_USEDEFAULT, 400, 300,
        NULL, NULL, hInstance, NULL
    );

    if (!hWnd) {
        return 1;
    }

    ShowWindow(hWnd, nShowCmd);
    UpdateWindow(hWnd);

    // Add icon to system tray
    PinToNotificationArea(hWnd);

    MSG message;
    while (GetMessage(&message, NULL, 0, 0)) {
        TranslateMessage(&message);
        DispatchMessage(&message);
    }

    return static_cast<int>(message.wParam);
}

LRESULT CALLBACK MainWndProc(HWND hWnd, UINT uMsg, WPARAM wParam, LPARAM lParam) {
    switch (uMsg) {
    case WM_TRAYMSG:
        if (lParam == WM_LBUTTONUP) {
            MessageBox(hWnd, "System tray icon activated!", "Info", MB_ICONINFORMATION | MB_OK);
        }
        break;

    case WM_DESTROY:
        Shell_NotifyIcon(NIM_DELETE, reinterpret_cast<NOTIFYICONDATA*>(&lParam)); // cleanup handled in real scenario
        PostQuitMessage(0);
        break;

    default:
        return DefWindowProc(hWnd, uMsg, wParam, lParam);
    }
    return 0;
}

void PinToNotificationArea(HWND hWnd) {
    NOTIFYICONDATA nid = { sizeof(NOTIFYICONDATA) };
    nid.hWnd         = hWnd;
    nid.uID          = 1001;
    nid.uFlags       = NIF_ICON | NIF_MESSAGE | NIF_TIP;
    nid.uCallbackMessage = WM_TRAYMSG;
    nid.hIcon        = LoadIcon(NULL, IDI_APPLICATION);
    lstrcpy(nid.szTip, "Tray Application v1.0");

    Shell_NotifyIcon(NIM_ADD, &nid);
}

