// LED connected to pin 9
const int ledPin = 9;

// Arrays for pattern control
int blinkState[] = {1, 0, 1, 0}; // 1 = ON, 0 = OFF
int waitTime[] = {500, 1000, 500, 1000}; // delay durations in ms
int lightLevel[] = {128, 0, 128, 0}; // PWM brightness (0-255)
int stepCount = sizeof(blinkState) / sizeof(blinkState[0]);

// Input storage buffers
String userPattern = "";
String userDelays = "";
String userBrightness = "";

void setup() {
  pinMode(ledPin, OUTPUT);
  Serial.begin(9600);
  Serial.println("LED Blink Pattern Controller");
  Serial.println("Enter new pattern, delays, and brightness values separated by commas.");
  Serial.println("Example: 1,0,1,0,500,1000,500,1000,128,0,128,0");
}

void loop() {
  if (Serial.available() > 0) {
    String received = Serial.readStringUntil('\n');
    processInput(received);
  }

  // Execute the current blinking sequence
  for (int idx = 0; idx < stepCount; idx++) {
    analogWrite(ledPin, lightLevel[idx]);
    delay(waitTime[idx]);
  }
}

void processInput(String data) {
  String segments[12];
  int segmentCount = 0;
  int startIdx = 0;

  while (startIdx < data.length()) {
    int commaPos = data.indexOf(',', startIdx);
    if (commaPos == -1) {
      segments[segmentCount] = data.substring(startIdx);
      segmentCount++;
      break;
    }
    segments[segmentCount] = data.substring(startIdx, commaPos);
    segmentCount++;
    startIdx = commaPos + 1;
  }

  // Validate and apply new settings if correct number of parameters provided
  if (segmentCount >= 3 && segmentCount % 3 == 0) {
    stepCount = segmentCount / 3;
    for (int i = 0; i < stepCount; i++) {
      blinkState[i] = segments[i * 3].toInt();
      waitTime[i] = segments[i * 3 + 1].toInt();
      lightLevel[i] = segments[i * 3 + 2].toInt();
    }
    Serial.println("Pattern updated successfully!");
  } else {
    Serial.println("Invalid input. Please enter a valid pattern, delays, and brightness values.");
  }
}

