// Custom type caster for MPI_Comm — rewritten with alternative capsule handling
namespace pybind11 {
namespace detail {

template <>
struct type_caster<MPI_Comm> {
public:
    PYBIND11_TYPE_CASTER(MPI_Comm, _("MPI_Comm"));

    bool load(py::handle src, bool) {
        if (!py::isinstance<py::capsule>(src)) return false;

        void* ptr = PyCapsule_GetPointer(src.ptr(), "MPI_Comm");
        if (!ptr) return false;

        value = *static_cast<MPI_Comm*>(ptr);
        return true;
    }

    static py::handle cast(MPI_Comm src, py::return_value_policy, py::handle) {
        auto* comm_ptr = new MPI_Comm(src);
        py::object capsule = py::capsule(comm_ptr, "MPI_Comm", [](void* v) {
            auto* c = static_cast<MPI_Comm*>(v);
            if (c && *c != MPI_COMM_NULL) {
                MPI_Comm_free(c);
                delete c;
            }
        });
        return capsule.release();
    }
};

}
}

// Renamed class: ComputationEngine replaces SomeComputation
class ComputationEngine {
    float scale_factor;
    int buffer[10]; // Fixed-size array instead of std::vector
    MPI_Comm world_comm;

public:
    void startup() {
        int my_rank;
        MPI_Comm_rank(world_comm, &my_rank);

        // Fill buffer with rank value using pointer traversal
        int* p = buffer;
        int count = 10;
        do {
            *p++ = my_rank;
        } while (--count > 0);
    }

    void assign_comm(MPI_Comm comm) {
        world_comm = comm;
    }

    ComputationEngine(float factor) : scale_factor(factor) {}

    ~ComputationEngine() {
        std::cerr << "[INFO] Engine destroyed.\n";
    }

    float process(float duration_ms) {
        // Sleep using microseconds for finer granularity
        std::this_thread::sleep_for(
            std::chrono::microseconds(static_cast<int>(duration_ms * 1000))
        );

        // Print contents of buffer using pointer iteration
        for (const int* it = buffer; it != buffer + 10; ++it) {
            std::cout << *it << " ";
        }
        std::cout << "\n";

        return scale_factor * duration_ms;
    }
};

PYBIND11_MODULE(module_name, m) {
    py::class_<ComputationEngine>(m, "Cpp_engine")
        .def(py::init<float>())
        .def("assign_comm", &ComputationEngine::assign_comm)
        .def("process", &ComputationEngine::process)
        .def("startup", &ComputationEngine::startup);
}

