// Compute the nth Fibonacci number using an iterative approach
int fibonacci(int limit) {
    if (limit <= 1) return limit;

    int prev = 0;   // F(0)
    int curr = 1;   // F(1)
    int next;

    for (int step = 2; step <= limit; ++step) {
        next = prev + curr;
        prev = curr;
        curr = next;
    }

    return curr;
}

int main() {
    int target = 41;
    int result = fibonacci(target);
    std::cout << result << std::endl;
    return 0;
}

