// Constants for JVM configuration
#define CLASSPATH_SEPARATOR ';' 
#define SNUGGLE_JAR_PATH "snuggletex-1.2.2/snuggletex-core-1.2.2.jar"

// Java class and method identifiers
#define ENGINE_CLASS    "uk/ac/ed/ph/snuggletex/SnuggleEngine"
#define INPUT_CLASS     "uk/ac/ed/ph/snuggletex/SnuggleInput" 
#define SESSION_CLASS   "uk/ac/ed/ph/snuggletex/SnuggleSession"
#define JAVA_STRING     "java/lang/String"

// Global JVM references
JNIEnv* jniEnv = nullptr;
JavaVM* javaVm = nullptr;
jint jvmResult = 0;

// Initialize Java Virtual Machine
void setupJvm() {
#ifdef JNI_VERSION_1_2
    JavaVMInitArgs vmArguments;
    JavaVMOption jvmOptions[1];

    // Set up classpath option
    string classPathOption = "-Djava.class.path=" + string(SNUGGLE_JAR_PATH);
    jvmOptions[0].optionString = const_cast<char*>(classPathOption.c_str());

    vmArguments.version = JNI_VERSION_1_2;
    vmArguments.options = jvmOptions;
    vmArguments.nOptions = 1;
    vmArguments.ignoreUnrecognized = JNI_TRUE;

    // Create JVM instance
    jvmResult = JNI_CreateJavaVM(&javaVm, reinterpret_cast<void**>(&jniEnv), &vmArguments);
#else
    JDK1_1InitArgs vmArgs;
    char combinedClassPath[2048];

    vmArgs.version = JNI_VERSION_1_1;
    JNI_GetDefaultJavaVMInitArgs(&vmArgs);

    // Combine default classpath with our JAR path
    sprintf(combinedClassPath, "%s%c%s", vmArgs.classpath, CLASSPATH_SEPARATOR, SNUGGLE_JAR_PATH);
    vmArgs.classpath = combinedClassPath;

    // Create JVM instance
    jvmResult = JNI_CreateJavaVM(&javaVm, &jniEnv, &vmArgs);
#endif
}

// Shutdown JVM
void teardownJvm() {
    if (javaVm != nullptr) {
        javaVm->DestroyJavaVM();
    }
}

// Convert native C string to Java string object
jstring createJavaString(const char* cString) {
    jstring javaStr = nullptr;
    jbyteArray byteData = nullptr;
    jclass stringClass = nullptr;
    jsize strLength = 0;

    strLength = strlen(cString);
    byteData = jniEnv->NewByteArray(strLength);
    stringClass = jniEnv->FindClass(JAVA_STRING);

    if (byteData != nullptr) {
        jmethodID constructorId;

        // Copy string data to byte array
        jniEnv->SetByteArrayRegion(byteData, 0, strLength, reinterpret_cast<jbyte*>(const_cast<char*>(cString)));

        // Get String constructor and create instance
        constructorId = jniEnv->GetMethodID(stringClass, "<init>", "([B)V");
        javaStr = static_cast<jstring>(jniEnv->NewObject(stringClass, constructorId, byteData));

        // Clean up local references
        jniEnv->DeleteLocalRef(byteData);
        return javaStr;
    }

    return nullptr;
}

// Process LaTeX input and output XML representation
int processLatexExpression(char* latexInput) {
    jclass engineClass, inputClass, sessionClass;
    jmethodID constructorMethod, sessionMethod, inputMethod, parseMethod, xmlMethod;
    jstring jLatexInput;
    jstring jXmlOutput;

    // Find required Java classes
    engineClass = jniEnv->FindClass(ENGINE_CLASS);
    inputClass = jniEnv->FindClass(INPUT_CLASS);
    sessionClass = jniEnv->FindClass(SESSION_CLASS);

    if (engineClass == nullptr) {
        cerr << "Failed to find SnuggleEngine class" << endl;
        return -1;
    }

    // Instantiate SnuggleEngine
    constructorMethod = jniEnv->GetMethodID(engineClass, "<init>", "()V");
    jobject engineInstance = jniEnv->NewObject(engineClass, constructorMethod);

    // Create parsing session
    sessionMethod = jniEnv->GetMethodID(engineClass, "createSession", "()Luk/ac/ed/ph/snuggletex/SnuggleSession;");
    jobject sessionInstance = jniEnv->CallObjectMethod(engineInstance, sessionMethod);

    // Prepare input object
    jLatexInput = createJavaString(latexInput);
    inputMethod = jniEnv->GetMethodID(inputClass, "<init>", "(Ljava/lang/String;)V");
    jobject inputObject = jniEnv->NewObject(inputClass, inputMethod, jLatexInput);

    // Parse the LaTeX content
    parseMethod = jniEnv->GetMethodID(sessionClass, "parseInput", "(Luk/ac/ed/ph/snuggletex/SnuggleInput;)V");
    jniEnv->CallVoidMethod(sessionInstance, parseMethod);

    // Generate XML output
    xmlMethod = jniEnv->GetMethodID(sessionClass, "buildXMLString", "()Ljava/lang/String;");
    jXmlOutput = static_cast<jstring>(jniEnv->CallObjectMethod(sessionInstance, xmlMethod));

    // Handle any exceptions
    if (jniEnv->ExceptionCheck()) {
        jthrowable exception = jniEnv->ExceptionOccurred();
        jniEnv->ExceptionDescribe();
        jniEnv->ExceptionClear();
        return -1;
    }

    // Output result
    const char* xmlContent = jniEnv->GetStringUTFChars(jXmlOutput, nullptr);
    cout << "Generated XML: " << xmlContent << endl;
    jniEnv->ReleaseStringUTFChars(jXmlOutput, xmlContent);

    return 0;
}

int main() {
    int processingResult;

    // Setup JVM environment
    setupJvm();

    // Process test LaTeX expression
    processingResult = processLatexExpression("$$5^2$$");

    // Cleanup resources
    teardownJvm();

    return processingResult;
}

