// A 4-dimensional vector class with specialized accessors and dot product
class Vector {
public:
    // Access elements using template parameters as indices (1-based)
    double get<1>() const { return elements[0]; }
    double get<2>() const { return elements[1]; }
    double get<4>() const { return elements[2]; }
    double get<8>() const { return elements[3]; }

    // Compute the dot product with another vector
    double dot(const Vector& rhs) const {
        return get<1>() * rhs.get<1>() +
               get<2>() * rhs.get<2>() +
               get<4>() * rhs.get<4>() +
               get<8>() * rhs.get<8>();
    }

private:
    double elements[4];
};

#include <iostream>
#include <fstream>

// Parallel sorting implementation using bubble sort on segments and merging
int main(int argc, char* argv[]) {
    std::ifstream inputFile(argv[1]);
    const int MAX_THREADS = 10;
    const int TOTAL_SIZE = 1000000;
    int dataArray[TOTAL_SIZE];
    int count = 0;
    int value;

    // Read input data from file
    while (inputFile >> value) {
        if (count < TOTAL_SIZE) {
            dataArray[count++] = value;
        }
    }
    inputFile.close();

    int segmentSize = TOTAL_SIZE / MAX_THREADS;

    // Sort each segment using bubble sort
    for (int t = 0; t < MAX_THREADS; ++t) {
        int* startPtr = &dataArray[t * segmentSize];
        for (int i = 0; i < segmentSize - 1; ++i) {
            for (int j = 0; j < segmentSize - 1 - i; ++j) {
                if (startPtr[j] > startPtr[j + 1]) {
                    int swapTemp = startPtr[j];
                    startPtr[j] = startPtr[j + 1];
                    startPtr[j + 1] = swapTemp;
                }
            }
        }
    }

    // Handle remaining elements if any
    int leftover = TOTAL_SIZE - (MAX_THREADS * segmentSize);
    if (leftover > 0) {
        // Merge last two segments to include leftover elements
        int leftStart = (MAX_THREADS - 2) * segmentSize;
        int rightStart = (MAX_THREADS - 1) * segmentSize;
        int* mergedBuffer = new int[segmentSize + leftover];
        int i = 0, j = 0, k = 0;

        // Merge the two parts
        while (i < segmentSize && j < leftover) {
            if (dataArray[leftStart + i] < dataArray[rightStart + j]) {
                mergedBuffer[k++] = dataArray[leftStart + i++];
            } else {
                mergedBuffer[k++] = dataArray[rightStart + j++];
            }
        }
        while (i < segmentSize) {
            mergedBuffer[k++] = dataArray[leftStart + i++];
        }
        while (j < leftover) {
            mergedBuffer[k++] = dataArray[rightStart + j++];
        }

        // Copy back to original array
        for (int idx = 0; idx < k; ++idx) {
            dataArray[leftStart + idx] = mergedBuffer[idx];
        }
        delete[] mergedBuffer;
    }

    // Merge all segments pairwise from bottom up
    for (int level = MAX_THREADS - 2; level >= 0; --level) {
        int leftIdx = level * segmentSize;
        int rightIdx = (level + 1) * segmentSize;
        int* tempMerge = new int[2 * segmentSize];
        int p1 = 0, p2 = 0, m = 0;

        while (p1 < segmentSize && p2 < segmentSize) {
            if (dataArray[leftIdx + p1] < dataArray[rightIdx + p2]) {
                tempMerge[m++] = dataArray[leftIdx + p1++];
            } else {
                tempMerge[m++] = dataArray[rightIdx + p2++];
            }
        }
        while (p1 < segmentSize) {
            tempMerge[m++] = dataArray[leftIdx + p1++];
        }
        while (p2 < segmentSize) {
            tempMerge[m++] = dataArray[rightIdx + p2++];
        }

        for (int copy = 0; copy < m; ++copy) {
            dataArray[leftIdx + copy] = tempMerge[copy];
        }
        delete[] tempMerge;
    }

    // Write sorted output to file
    std::ofstream outputFile(argv[2]);
    for (int i = 0; i < TOTAL_SIZE; ++i) {
        outputFile << dataArray[i] << "\n";
    }
    outputFile.close();

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

// Merge two subarrays of array arr
void combine(vector<int> &arr, int start, int center, int end) {
    int sizeLeft = center - start + 1;
    int sizeRight = end - center;

    vector<int> tempLeft(sizeLeft), tempRight(sizeRight);

    // Copy data to temporary arrays
    for (int idx = 0; idx < sizeLeft; ++idx)
        tempLeft[idx] = arr[start + idx];
    for (int idx = 0; idx < sizeRight; ++idx)
        tempRight[idx] = arr[center + 1 + idx];

    // Merge the temporary arrays back into arr[start..end]
    int i = 0, j = 0, k = start;
    while (i < sizeLeft && j < sizeRight) {
        if (tempLeft[i] <= tempRight[j]) {
            arr[k++] = tempLeft[i++];
        } else {
            arr[k++] = tempRight[j++];
        }
    }

    // Copy remaining elements of tempLeft[], if any
    while (i < sizeLeft)
        arr[k++] = tempLeft[i++];

    // Copy remaining elements of tempRight[], if any
    while (j < sizeRight)
        arr[k++] = tempRight[j++];
}

// Main function that sorts arr[start..end] using merge()
void divideAndConquerSort(vector<int> &arr, int leftBound, int rightBound) {
    if (leftBound < rightBound) {
        int midPoint = leftBound + (rightBound - leftBound) / 2;

        // Sort first and second halves
        divideAndConquerSort(arr, leftBound, midPoint);
        divideAndConquerSort(arr, midPoint + 1, rightBound);

        // Merge the sorted halves
        combine(arr, leftBound, midPoint, rightBound);
    }
}

int main() {
    vector<int> data = {12, 11, 13, 5, 6, 7};
    int n = data.size();

    cout << "Original array: " << endl;
    for (int i = 0; i < n; i++)
        cout << data[i] << " ";
    cout << endl;

    divideAndConquerSort(data, 0, n - 1);

    cout << "Sorted array: " << endl;
    for (int i = 0; i < n; i++)
        cout << data[i] << " ";
    cout << endl;

    return 0;
}

#include <algorithm>
