#include <iostream>
#include <cmath>

// Insertion sort for small subarrays
void performInsertionSort(std::vector<int>& data, int startIdx, int endIdx) {
    for (int idx = startIdx + 1; idx <= endIdx; ++idx) {
        int currentValue = data[idx];
        int prevIdx = idx - 1;
        while (prevIdx >= startIdx && data[prevIdx] > currentValue) {
            data[prevIdx + 1] = data[prevIdx];
            --prevIdx;
        }
        data[prevIdx + 1] = currentValue;
    }
}

// Max-heapify procedure for heap-based sorting
void buildMaxHeap(std::vector<int>& data, int heapSize, int rootIdx) {
    int maxNode = rootIdx;
    int leftChild = 2 * rootIdx + 1;
    int rightChild = 2 * rootIdx + 2;

    if (leftChild < heapSize && data[leftChild] > data[maxNode])
        maxNode = leftChild;

    if (rightChild < heapSize && data[rightChild] > data[maxNode])
        maxNode = rightChild;

    if (maxNode != rootIdx) {
        std::swap(data[rootIdx], data[maxNode]);
        buildMaxHeap(data, heapSize, maxNode);
    }
}

// Heap sort implementation using max-heap
void applyHeapSort(std::vector<int>& data, int size) {
    // Build initial max heap
    for (int i = size / 2 - 1; i >= 0; --i)
        buildMaxHeap(data, size, i);

    // Extract elements one by one
    for (int i = size - 1; i > 0; --i) {
        std::swap(data[0], data[i]);
        buildMaxHeap(data, i, 0);
    }
}

// Recursive introsort helper function
void optimizedIntrosort(std::vector<int>& data, int low, int high, int maxDepth) {
    int currentSize = high - low + 1;

    if (currentSize > 16) {
        if (maxDepth <= 0) {
            applyHeapSort(data, currentSize);
            return;
        }

        --maxDepth;
        auto midIt = std::partition(data.begin() + low, data.begin() + high + 1,
                                    [](int val) { return val < data[high]; });
        int partitionIndex = std::distance(data.begin(), midIt);

        optimizedIntrosort(data, low, partitionIndex - 1, maxDepth);
        optimizedIntrosort(data, partitionIndex + 1, high, maxDepth);
    } else {
        performInsertionSort(data, low, high);
    }
}

// Main introsort interface
void runIntrosort(std::vector<int>& data) {
    if (data.empty()) return;
    int depthBound = 2 * static_cast<int>(std::log(data.size()));
    optimizedIntrosort(data, 0, data.size() - 1, depthBound);
}

