    std::vector<int> dataset = {34, 7, 23, 32, 5, 62, 1, 89, 45, 21, 12, 34, 56, 78, 90, 12, 34, 56, 78, 90};
    runIntrosort(dataset);

    for (int value : dataset) {
        std::cout << value << " ";
    }
    std::cout << std::endl;

    return 0;
}

