using namespace std;

// Retrieve the HTML content from a given URL
string retrievePage(const string& url) {
    httplib::Client client(url);
    auto response = client.Get("/");
    if (response && response->status == 200) {
        return response->body;
    } else {
        cerr << "Error fetching: " << url << endl;
        return "";
    }
}

// Parse HTML and gather all hyperlinks, resolving relative paths
vector<string> collectHyperlinks(const string& html, const string& origin) {
    vector<string> collected;
    simple_html_dom_parser parser;
    auto dom = parser.parse(html);

    for (const auto& anchor : dom->find("a")) {
        string target = anchor->attr("href");
        if (!target.empty() && target[0] == '/') {
            // Transform relative link to absolute form
            target = origin + target;
        }
        if (!target.empty()) {
            collected.push_back(target);
        }
    }
    return collected;
}

// Process a single URL: mark as visited, fetch content, and enqueue new links
void processUrl(const string& url, queue<string>& pending, set<string>& seen) {
    if (seen.count(url) > 0) {
        return;
    }

    seen.insert(url);
    string pageContent = retrievePage(url);
    if (!pageContent.empty()) {
        vector<string> newLinks = collectHyperlinks(pageContent, url);
        for (const string& link : newLinks) {
            pending.push(link);
        }
    }
}

// Entry point of the web crawler
int main() {
    string initialUrl = "http://example.com";
    queue<string> frontier;
    set<string> explored;

    frontier.push(initialUrl);

    while (!frontier.empty()) {
        string current = frontier.front();
        frontier.pop();

        thread worker(processUrl, current, ref(frontier), ref(explored));
        worker.join();
    }

    return 0;
}

