// Helper function to invoke a stdcall function using inline assembly
inline uint64_t call_stdcall_function(uint64_t (*stdcall_func)())
{
    unsigned long high_part, low_part;
    asm volatile (
        "call *%3"
        : "=d" (high_part), "=a" (low_part)
        : "c" (0), "r" (stdcall_func)
        : "eax", "edx", "ecx"
    );
    return (static_cast<uint64_t>(high_part) << 32) | static_cast<uint32_t>(low_part);
}

