#include <opencv2/opencv.hpp>
#include <iostream>
#include <cmath>

class VesselEnhancement {
public:
    VesselEnhancement(double scale = 1.0, double param1 = 1.0, double param2 = 2.0) 
        : sigma(scale), alpha(param1), beta(param2) {}

    cv::Mat processImage(const cv::Mat& source) {
        cv::Mat grayscale;
        if (source.channels() == 3) {
            cv::cvtColor(source, grayscale, cv::COLOR_BGR2GRAY);
        } else {
            source.copyTo(grayscale);
        }

        cv::Mat hessianComponents;
        calculateHessian(grayscale, hessianComponents);

        cv::Mat eigen1, eigen2;
        extractEigenvalues(hessianComponents, eigen1, eigen2);

        cv::Mat responseMap;
        constructResponse(eigen1, eigen2, responseMap);

        adjustContrast(responseMap);

        return responseMap;
    }

private:
    double sigma;
    double alpha;
    double beta;

    void calculateHessian(const cv::Mat& input, cv::Mat& output) {
        cv::Mat gradX, gradY;
        cv::Sobel(input, gradX, CV_64F, 1, 0, 3);
        cv::Sobel(input, gradY, CV_64F, 0, 1, 3);

        cv::Mat xx, yy, xy;
        cv::multiply(gradX, gradX, xx);
        cv::multiply(gradY, gradY, yy);
        cv::multiply(gradX, gradY, xy);

        cv::GaussianBlur(xx, xx, cv::Size(), sigma);
        cv::GaussianBlur(yy, yy, cv::Size(), sigma);
        cv::GaussianBlur(xy, xy, cv::Size(), sigma);

        output.create(input.size(), CV_64FC3);
        auto outIter = output.begin<cv::Vec<double,3>>();
        auto xxIter = xx.begin<double>();
        auto yyIter = yy.begin<double>();
        auto xyIter = xy.begin<double>();

        for (; outIter != output.end<cv::Vec<double,3>>(); ++outIter, ++xxIter, ++yyIter, ++xyIter) {
            (*outIter)[0] = *xxIter;
            (*outIter)[1] = *yyIter;
            (*outIter)[2] = *xyIter;
        }
    }

    void extractEigenvalues(const cv::Mat& input, cv::Mat& lambda1, cv::Mat& lambda2) {
        std::vector<cv::Mat> eigenvectors;
        cv::eigen(input, eigenvectors);

        lambda1 = eigenvectors[0].clone();
        lambda2 = eigenvectors[1].clone();
    }

    void constructResponse(const cv::Mat& lambda1, const cv::Mat& lambda2, cv::Mat& result) {
        result.create(lambda1.size(), CV_64F);

        auto resIter = result.begin<double>();
        auto l1Iter = lambda1.begin<double>();
        auto l2Iter = lambda2.begin<double>();

        for (; resIter != result.end<double>(); ++resIter, ++l1Iter, ++l2Iter) {
            double absL1 = std::abs(*l1Iter);
            double absL2 = std::abs(*l2Iter);

            double ratio = (absL1 > 1e-10) ? std::sqrt(absL2 / absL1) : 0.0;
            double coherence = (absL2 > 1e-10) ? std::sqrt(absL1 / absL2) : 0.0;

            double Rb = std::exp(-(absL1 * absL1) / (2.0 * alpha * alpha));
            double So = 1.0 - std::exp(-(ratio * ratio) / (2.0 * beta * beta));

            *resIter = Rb * So;
        }
    }

    void adjustContrast(cv::Mat& image) {
        double minVal, maxVal;
        cv::minMaxLoc(image, &minVal, &maxVal);

        if (maxVal - minVal > 1e-10) {
            image -= minVal;
            image /= (maxVal - minVal);
        }
    }
};

int main() {
    cv::Mat inputImage = cv::imread("input.png");
    if (inputImage.empty()) {
        std::cerr << "Error: Could not load image file." << std::endl;
        return -1;
    }

    VesselEnhancement filter;
    cv::Mat processed = filter.processImage(inputImage);

    cv::imshow("Vessel Enhanced", processed);
    cv::waitKey(0);

    return 0;
}

