// Define a table as a vector of maps
using Table = std::vector<std::map<std::string, std::string>>;

// Function to evaluate a comparison operation
bool performComparison(const std::string& left, const std::string& relation, const std::string& right) {
    if (relation == "==") return left == right;
    if (relation == "!=") return left != right;
    if (relation == "<")  return left < right;
    if (relation == ">")  return left > right;
    if (relation == "<=") return left <= right;
    if (relation == ">=") return left >= right;
    return false;
}

// Function to evaluate a Boolean expression on a single row
bool checkRowCondition(const std::map<std::string, std::string>& entry, const std::string& condition) {
    std::istringstream stream(condition);
    std::string word;
    std::vector<std::string> parts;

    // Split the condition into tokens
    while (stream >> word) {
        parts.push_back(word);
    }

    bool overallResult = false;
    bool tempResult = false;
    bool isNegated = false;
    std::string leftOperand, operatorSymbol, rightOperand;

    for (size_t idx = 0; idx < parts.size(); ++idx) {
        if (parts[idx] == "NOT") {
            isNegated = true;
            continue;
        }

        // Check if this is a comparison expression (e.g., city == New York)
        if (idx + 2 < parts.size() && 
            (parts[idx + 1] == "==" || parts[idx + 1] == "!=" || 
             parts[idx + 1] == "<"  || parts[idx + 1] == ">"  || 
             parts[idx + 1] == "<=" || parts[idx + 1] == ">=")) {

            leftOperand = entry.at(parts[idx]);
            operatorSymbol = parts[idx + 1];
            rightOperand = entry.at(parts[idx + 2]);
            tempResult = performComparison(leftOperand, operatorSymbol, rightOperand);
            idx += 2;
        } else {
            // Handle simple boolean values (e.g., "true")
            tempResult = (entry.at(parts[idx]) == "true");
        }

        // Apply NOT if present
        if (isNegated) {
            tempResult = !tempResult;
            isNegated = false;
        }

        // Combine with previous results using AND/OR
        if (idx == 0) {
            overallResult = tempResult;
        } else {
            std::string prevToken = (idx > 0) ? parts[idx - 1] : "";
            if (prevToken == "AND") {
                overallResult = overallResult && tempResult;
            } else if (prevToken == "OR") {
                overallResult = overallResult || tempResult;
            }
        }
    }

    return overallResult;
}

// Function to evaluate the query across two tables
bool runBooleanSearch(const Table& primary, const Table& secondary, const std::string& filter) {
    // Check rows in first table
    for (const auto& record : primary) {
        if (checkRowCondition(record, filter)) {
            return true;
        }
    }

    // Check rows in second table
    for (const auto& record : secondary) {
        if (checkRowCondition(record, filter)) {
            return true;
        }
    }

    return false;
}

int main() {
    // Sample data sets
    Table dataset1 = {
        {{"name", "Alice"}, {"age", "30"}, {"city", "New York"}},
        {{"name", "Bob"},   {"age", "25"}, {"city", "Los Angeles"}}
    };

    Table dataset2 = {
        {{"name", "Charlie"}, {"age", "35"}, {"city", "Chicago"}},
        {{"name", "Diana"},   {"age", "28"}, {"city", "New York"}}
    };

    // Example search condition
    std::string searchCriteria = "city == New York OR age > 30";

    // Execute the query
    bool matchFound = runBooleanSearch(dataset1, dataset2, searchCriteria);

    // Display result
    std::cout << "Match found: " << (matchFound ? "yes" : "no") << std::endl;

    return 0;
}

