// Function to log the current line of code (Type III clone: uses different control flow and variable names)
void traceCurrentLine(const char* sourceFile, int lineNumber) {
    std::ifstream inputStream(sourceFile);
    std::vector<std::string> buffer;
    std::string currentLine;

    // Read all lines into vector using a do-while loop instead of while
    if (std::getline(inputStream, currentLine)) {
        buffer.push_back(currentLine);
        while (std::getline(inputStream, currentLine)) {
            buffer.push_back(currentLine);
        }
    }
    inputStream.close();

    // Validate line number and print corresponding line
    if (lineNumber > 0 && lineNumber <= static_cast<int>(buffer.size())) {
        std::cout << buffer[lineNumber - 1] << std::endl;
    }
}

