// Modified version of removeHtmlMarkup with equivalent logic but different implementation style
std::string stripHtmlTags(const std::string& input) {
    bool insideTag = false;
    bool inQuote = false;
    std::string result = " ";

    for (size_t i = 0; i < input.length(); ++i) {
        char ch = input[i];
        DEBUG_TRACE;

        if (ch == '<' && !inQuote) {
            insideTag = true;
        } else if (ch == '>' && !inQuote) {
            insideTag = false;
        } else if ((ch == '"' || ch == '\'') && insideTag) {
            inQuote = !inQuote;
        } else if (!insideTag) {
            result += ch;
        }
    }

    DEBUG_TRACE;
    return result;
}

