#include <vector>

int fib(int n) {
    static std::vector<int> memo = {0, 1};

    if (n < static_cast<int>(memo.size())) {
        return memo[n];
    }

    while (static_cast<int>(memo.size()) <= n) {
        int size = memo.size();
        memo.push_back(memo[size - 1] + memo[size - 2]);
    }

    return memo[n];
}

