#include <cstdint>

// Performs a 128-bit compare-and-swap operation using inline assembly
template<typename T>
inline bool atomic_cas_128(volatile T* destination, const T& expected, const T& desired) {
    uint64_t* dst_ptr = reinterpret_cast<uint64_t*>(destination);
    uint64_t* exp_ptr = reinterpret_cast<uint64_t*>(const_cast<T*>(&expected));
    uint64_t* des_ptr = reinterpret_cast<uint64_t*>(const_cast<T*>(&desired));
    unsigned char success_flag = 0;

    __asm__ __volatile__ (
        "lock; cmpxchg16b %1\n\t"
        "setz %0\n\t"
        : "=q"(success_flag)                    // output: zero flag set if swap succeeded
        : "m"(*dst_ptr),                        // input: memory operand
          "a"(exp_ptr[0]),                      // input: low 64 bits of expected value
          "d"(exp_ptr[1]),                      // input: high 64 bits of expected value
          "b"(des_ptr[0]),                      // input: low 64 bits of desired value
          "c"(des_ptr[1])                       // input: high 64 bits of desired value
        : "memory", "cc"                        // clobbered: memory and condition codes
    );

    return static_cast<bool>(success_flag);
}

