#include <pybind11/pybind11.h>
#include <pybind11/stl.h>
#include <pybind11/complex.h>
#include "my_class.h"

// Alias for brevity and clarity
namespace py = pybind11;

// Define custom type alias with alternative naming
using ComplexQuartet = std::array<std::complex<double>, 4>;

// Register opaque type for ComplexQuartet
PYBIND11_MAKE_OPAQUE(ComplexQuartet);

// Helper function to safely construct from vector
ComplexQuartet make_quartet_from_vector(const std::vector<std::complex<double>>& input) {
    if (input.size() != 4) {
        throw std::invalid_argument("Expected exactly 4 complex numbers");
    }
    return ComplexQuartet{input[0], input[1], input[2], input[3]};
}

// Alternative accessor helper: bounds-checked element retrieval
std::complex<double> get_element(const ComplexQuartet& arr, size_t idx) {
    if (idx >= 4) {
        throw std::out_of_range("Index must be between 0 and 3");
    }
    return arr[idx];
}

// Mutator helper: bounds-checked assignment
void set_element(ComplexQuartet& arr, size_t idx, const std::complex<double>& val) {
    if (idx >= 4) {
        throw std::out_of_range("Index must be between 0 and 3");
    }
    arr[idx] = val;
}

// Generate string representation using lambda with loop-based concatenation
std::string repr_quartet(const ComplexQuartet& q) {
    std::string result = "ArrayComplex4([";
    for (int i = 0; i < 4; ++i) {
        if (i > 0) result += ", ";
        result += py::str(q[i]);
    }
    result += "])";
    return result;
}

// Module binding function — renamed and restructured
void register_complex_array_module(py::module_& mod) {
    // Expose std::complex<double> under an alternative name
    py::bind_complex<double>(mod, "ComplexDouble");

    // Bind the quartet type with equivalent semantics
    py::class_<ComplexQuartet>(mod, "ArrayComplex4")
        .def(py::init<>())
        .def(py::init([](const std::vector<std::complex<double>>& vec) {
            return make_quartet_from_vector(vec);
        }))
        .def("at", [](const ComplexQuartet& self, size_t index) {
            return get_element(self, index);
        })
        .def("__getitem__", [](const ComplexQuartet& self, size_t index) {
            return get_element(self, index);
        })
        .def("__setitem__", [](ComplexQuartet& self, size_t index, const std::complex<double>& value) {
            set_element(self, index, value);
        })
        .def("__repr__", [](const ComplexQuartet& self) {
            return repr_quartet(self);
        });

    // Bind MyClass with overloaded methods
    py::class_<MyClass>(mod, "MyClass", py::dynamic_attr())
        .def("my_function",
             static_cast<std::unique_ptr<ComplexQuartet>(MyClass::*)(double)>(&MyClass::my_function))
        .def("my_function",
             static_cast<std::unique_ptr<ComplexQuartet>(MyClass::*)(double, double)>(&MyClass::my_function));
}

// Entry point for Python module creation
PYBIND11_MODULE(my_module, m) {
    register_complex_array_module(m);
}

#include <cstdint>

uint32_t reverseBits(volatile uint32_t value) {
    uint32_t reversed = 0;

    // Process each bit from least significant to most significant
    for (int position = 0; position < 32; ++position) {
        // Extract the current bit and place it in the reversed position
        uint32_t current_bit = (value >> position) & 1;
        reversed |= (current_bit << (31 - position));
    }

    return reversed;
}

uint32_t reverseBits(volatile uint32_t n) {
    uint32_t reversed = 0;

    // Process each bit from least significant to most significant
    for (int i = 0; i < 32; ++i) {
        // Shift result left to make room for next bit
        reversed <<= 1;
        // Add the least significant bit of n to result
        reversed |= (n & 1);
        // Shift n right to process next bit
        n >>= 1;
    }

    return reversed;
}

#include <iostream>
using namespace std;

// Definition for singly-linked list.
struct ListNode {
    int val;
    ListNode *next;
    ListNode(int x) : val(x), next(nullptr) {}
};

class CycleDetector {
public:
    bool detectLoop(ListNode *start) {
        // Handle empty list or single node cases
        if (start == nullptr || start->next == nullptr) {
            return false;
        }

        ListNode *pointer1 = start;  // Slow pointer
        ListNode *pointer2 = start;  // Fast pointer

        // Traverse the list with two pointers at different speeds
        while (pointer2 != nullptr && pointer2->next != nullptr) {
            pointer1 = pointer1->next;          // Move one step
            pointer2 = pointer2->next->next;    // Move two steps

            // If pointers meet, there's a cycle
            if (pointer1 == pointer2) {
                return true;
            }
        }

        // If fast pointer reaches end, no cycle exists
        return false;
    }
};

// Helper function to build a linked list with a cycle for testing
ListNode* buildTestListWithCycle() {
    ListNode *first = new ListNode(10);
    ListNode *second = new ListNode(20);
    ListNode *third = new ListNode(30);
    ListNode *fourth = new ListNode(40);

    first->next = second;
    second->next = third;
    third->next = fourth;
    fourth->next = second;  // Creates a cycle back to second node

    return first;
}

int main() {
    CycleDetector detector;

    // Test case: linked list containing a cycle
    ListNode *headWithLoop = buildTestListWithCycle();
    cout << "List with loop: " << (detector.detectLoop(headWithLoop) ? "Detected" : "None") << endl;

    // Test case: linked list without a cycle
    ListNode *headWithoutLoop = new ListNode(5);
    headWithoutLoop->next = new ListNode(15);
    headWithoutLoop->next->next = new ListNode(25);
    cout << "List without loop: " << (detector.detectLoop(headWithoutLoop) ? "Detected" : "None") << endl;

    return 0;
}

