// Check if a number is prime using an alternative approach
bool checkPrime(int value) {
    if (value <= 1) return false;
    if (value == 2) return true;
    if (value % 2 == 0) return false;

    // Check odd divisors up to sqrt(value)
    for (int j = 3; j * j <= value; j += 2) {
        if (value % j == 0) return false;
    }
    return true;
}

// Calculate sum of digits using recursion instead of loop
int digitSum(int n) {
    if (n == 0) return 0;
    return (n % 10) + digitSum(n / 10);
}

// Find the largest prime and return sum of its digits
int getLargestPrimeDigitSum(const std::vector<int>& numbers) {
    int maxPrime = -1;

    for (size_t idx = 0; idx < numbers.size(); ++idx) {
        int current = numbers[idx];
        if (checkPrime(current) && current > maxPrime) {
            maxPrime = current;
        }
    }

    return (maxPrime != -1) ? digitSum(maxPrime) : 0;
}

