// Determine if a character is an arithmetic operator
bool isArithmeticOperator(char c) {
    return (c == '+' || c == '-' || c == '*' || c == '/');
}

// Determine if a character starts a number (digit or decimal point)
bool isNumberStart(char c) {
    return std::isdigit(c) || c == '.';
}

// Return precedence level for operators
int getPrecedenceLevel(char op) {
    if (op == '+' || op == '-') return 1;
    if (op == '*' || op == '/') return 2;
    return 0;
}

// Transform infix notation to postfix notation
std::string convertToPostfix(const std::string &infixExpr) {
    std::stack<char> opStack;
    std::string result;
    std::istringstream stream(infixExpr);
    std::string word;

    while (stream >> word) {
        // If token starts with a digit or '.', it's a number
        if (isNumberStart(word[0])) {
            result += word + " ";
        }
        // If token is an operator
        else if (isArithmeticOperator(word[0])) {
            while (!opStack.empty() && 
                   getPrecedenceLevel(opStack.top()) >= getPrecedenceLevel(word[0])) {
                result += opStack.top();
                opStack.pop();
                result += " ";
            }
            opStack.push(word[0]);
        }
        // Left parenthesis
        else if (word[0] == '(') {
            opStack.push(word[0]);
        }
        // Right parenthesis
        else if (word[0] == ')') {
            while (!opStack.empty() && opStack.top() != '(') {
                result += opStack.top();
                opStack.pop();
                result += " ";
            }
            if (!opStack.empty() && opStack.top() == '(') {
                opStack.pop(); // Remove the matching '('
            }
        }
    }

    // Pop remaining operators
    while (!opStack.empty()) {
        result += opStack.top();
        opStack.pop();
        result += " ";
    }

    return result;
}

// Compute value of postfix expression
double computePostfix(const std::string &postfixExpr) {
    std::stack<double> values;
    std::istringstream stream(postfixExpr);
    std::string token;

    while (stream >> token) {
        if (isNumberStart(token[0])) {
            values.push(std::stod(token));
        }
        else if (isArithmeticOperator(token[0])) {
            double second = values.top(); values.pop();
            double first = values.top(); values.pop();

            switch (token[0]) {
                case '+': values.push(first + second); break;
                case '-': values.push(first - second); break;
                case '*': values.push(first * second); break;
                case '/': values.push(first / second); break;
            }
        }
    }

    return values.top();
}

int main() {
    std::string expression = "3 + 4 * 2 / ( 1 - 5 )";
    std::string postfixForm = convertToPostfix(expression);
    double computedValue = computePostfix(postfixForm);

    std::cout << "Infix Expression: " << expression << std::endl;
    std::cout << "Postfix Expression: " << postfixForm << std::endl;
    std::cout << "Computed Result: " << computedValue << std::endl;

    return 0;
}

