using namespace std;

// Function to locate the longest repeated substring using a different approach
string locateMaxRepeatedSegment(const string &text) {
    int length = text.length();
    string bestMatch = "";

    // Iterate from half the length down to 1
    for (int segLen = length / 2; segLen >= 1; --segLen) {
        unordered_map<string, int> segmentCount;

        // Count occurrences of each segment of current length
        for (int idx = 0; idx <= length - segLen; ++idx) {
            string segment = text.substr(idx, segLen);
            segmentCount[segment]++;

            // Check if this segment appears again later in the string
            if (segmentCount[segment] > 1 && 
                text.find(segment, idx + 1) != string::npos) {
                if (segment.length() > bestMatch.length()) {
                    bestMatch = segment;
                }
            }
        }
    }

    return bestMatch;
}

// Function to apply compression by replacing repeated segments
string applyCompression(const string &input) {
    string workingCopy = input;

    while (true) {
        string maxRepeated = locateMaxRepeatedSegment(workingCopy);
        if (maxRepeated.empty()) break;

        // Count total occurrences of the repeated segment
        int occurrences = 0;
        size_t searchPos = 0;
        while ((searchPos = workingCopy.find(maxRepeated, searchPos)) != string::npos) {
            occurrences++;
            searchPos += maxRepeated.length();
        }

        // Only compress if there are multiple occurrences
        if (occurrences > 1) {
            string marker = "[" + maxRepeated + "]" + to_string(occurrences);
            size_t firstPos = workingCopy.find(maxRepeated);
            workingCopy = workingCopy.substr(0, firstPos) + marker + 
                         workingCopy.substr(firstPos + maxRepeated.length());
        } else {
            break;
        }
    }

    return workingCopy;
}

// Function to handle file processing with modified logic
void handleFileProcessing(const string &sourcePath, const string &targetPath) {
    ifstream sourceFile(sourcePath);
    ofstream targetFile(targetPath);

    if (!sourceFile || !targetFile) {
        cerr << "Failed to open required files." << endl;
        return;
    }

    string currentLine;
    while (getline(sourceFile, currentLine)) {
        // Check for specific pattern in line
        if (currentLine.find("d+c+d+f+d+c+d+f+d+c+d+f+d+c+d+f+") != string::npos) {
            string processed = applyCompression(currentLine);
            targetFile << processed << "\n";
        } else {
            targetFile << currentLine << "\n";
        }
    }

    sourceFile.close();
    targetFile.close();
}

int main() {
    string sourceFile = "input.txt";
    string destinationFile = "output.txt";
    handleFileProcessing(sourceFile, destinationFile);
    return 0;
}

#include <windows.h>
