// Global flag to track password dialog visibility
static bool g_passwordDialogActive = false;

// Window procedure for the main screen saver window
LRESULT CALLBACK MainWndProc(HWND hwnd, UINT message, WPARAM wParam, LPARAM lParam)
{
    switch (message)
    {
    case WM_HOTKEY:
        // Triggered when user presses registered hotkey (ID = 1)
        if (wParam == 1)
        {
            DisplayPasswordProtection(hwnd);
        }
        break;

    case WM_KEYDOWN:
    case WM_SYSKEYDOWN:
    case WM_LBUTTONDOWN:
    case WM_RBUTTONDOWN:
        // Show password prompt on any user activity if not already visible
        if (!g_passwordDialogActive)
        {
            DisplayPasswordProtection(hwnd);
        }
        break;

    case WM_CLOSE:
        // Prevent closing while password dialog is active
        if (g_passwordDialogActive)
        {
            return 0;
        }
        // Fall through to default handler when dialog is not active

    default:
        return DefWindowProc(hwnd, message, wParam, lParam);
    }

    return 0;
}

// Function to display the password protection dialog
void DisplayPasswordProtection(HWND parentWindow)
{
    g_passwordDialogActive = true;

    // Create and show modal password dialog
    INT_PTR result = DialogBox(
        GetModuleHandle(NULL), 
        MAKEINTRESOURCE(IDD_PASSWORD_DIALOG), 
        parentWindow, 
        PasswordDialogProc
    );

    // If correct password was entered, exit application
    if (result == IDOK)
    {
        PostQuitMessage(0);
    }

    g_passwordDialogActive = false;
}

// Dialog procedure for password input
INT_PTR CALLBACK PasswordDialogProc(HWND dialogWindow, UINT msg, WPARAM wParam, LPARAM lParam)
{
    switch (msg)
    {
    case WM_INITDIALOG:
        // Initialize dialog - return TRUE to set focus to default control
        return (INT_PTR)TRUE;

    case WM_COMMAND:
        // Handle OK and Cancel buttons
        if (LOWORD(wParam) == IDOK || LOWORD(wParam) == IDCANCEL)
        {
            if (LOWORD(wParam) == IDOK)
            {
                char inputBuffer[256];
                GetDlgItemText(dialogWindow, IDC_PASSWORD_FIELD, inputBuffer, sizeof(inputBuffer));

                // Check against hardcoded password
                std::string enteredPassword(inputBuffer);
                if (enteredPassword == "secure_pass")
                {
                    EndDialog(dialogWindow, IDOK);
                }
                else
                {
                    MessageBox(dialogWindow, L"Access denied. Please try again.", L"Authentication Failed", MB_OK | MB_ICONWARNING);
                }
            }
            else
            {
                // User cancelled - close dialog without exiting app
                EndDialog(dialogWindow, IDCANCEL);
            }
            return (INT_PTR)TRUE;
        }
        break;
    }

    return (INT_PTR)FALSE;
}

// Application entry point
int APIENTRY wWinMain(HINSTANCE instanceHandle, HINSTANCE prevInstanceHandle, LPWSTR commandLine, int showCmd)
{
    // Register window class for screen saver
    WNDCLASSEX windowClass = {0};
    windowClass.cbSize        = sizeof(WNDCLASSEX);
    windowClass.style         = CS_HREDRAW | CS_VREDRAW;
    windowClass.lpfnWndProc   = MainWndProc;
    windowClass.hInstance     = instanceHandle;
    windowClass.hCursor       = LoadCursor(NULL, IDC_ARROW);
    windowClass.hbrBackground = (HBRUSH)(COLOR_WINDOW + 1);
    windowClass.lpszClassName = L"SecureScreenSaver";

    RegisterClassEx(&windowClass);

    // Create full-screen window
    HWND mainWnd = CreateWindowEx(
        0,
        L"SecureScreenSaver",
        L"Protected Screen Saver",
        WS_POPUP,
        0, 0,
        GetSystemMetrics(SM_CXSCREEN),
        GetSystemMetrics(SM_CYSCREEN),
        NULL,
        NULL,
        instanceHandle,
        NULL
    );

    if (!mainWnd) return FALSE;

    ShowWindow(mainWnd, showCmd);
    UpdateWindow(mainWnd);

    // Register hotkey (ESC key) to trigger password prompt
    RegisterHotKey(mainWnd, 1, 0, VK_ESCAPE);

    // Message loop
    MSG message;
    while (GetMessage(&message, NULL, 0, 0))
    {
        TranslateMessage(&message);
        DispatchMessage(&message);
    }

    // Cleanup hotkey registration
    UnregisterHotKey(mainWnd, 1);

    return (int)message.wParam;
}

