// Find the maximum value in a vector of integers
int findMaximum(const std::vector<int>& values) {
    if (values.empty()) {
        throw std::invalid_argument("Vector is empty");
    }
    int currentMax = values[0];
    size_t index = 1;
    while (index < values.size()) {
        if (values[index] > currentMax) {
            currentMax = values[index];
        }
        index++;
    }
    return currentMax;
}

