// Custom typemap for converting Python list to QList<T>
%typemap(in) QList<$1_template_type> (QList<$1_template_type> buffer) {
    if (PyList_Check($input)) {
        int count = PyList_Size($input);
        for (int idx = 0; idx < count; ++idx) {
            PyObject* element = PyList_GetItem($input, idx);
            $1_template_type val;
            if (SWIG_ConvertPtr(element, (void**)&val, $1_descriptor, 0) == -1) {
                SWIG_exception_fail(SWIG_TypeError, "Invalid type in input sequence");
            }
            buffer.append(val);
        }
        $1 = buffer;
    } else {
        SWIG_exception_fail(SWIG_TypeError, "Input must be a list");
    }
}

// Typemap for returning QList<T> as Python list
%typemap(out) QList<$1_template_type> {
    PyObject* pylist = PyList_New($1.size());
    for (int i = 0; i < $1.size(); ++i) {
        PyObject* obj = SWIG_NewPointerObj(SWIG_as_voidptr($1[i]), $1_descriptor, SWIG_POINTER_OWN);
        PyList_SetItem(pylist, i, obj);
    }
    $result = pylist;
}

// Extension methods for QList<T> to support iteration and indexing
%extend QList<$1_template_type> {
    PyObject* __iter__() {
        return PySequence_Fast($self, "Object is not iterable");
