class ThreeDimensionalArray {
public:
    ThreeDimensionalArray(int sizeX, int sizeY, int sizeZ) 
        : rows(sizeX), cols(sizeY), depth(sizeZ), 
          storage(sizeX * sizeY * sizeZ, 0.0) {}

    double& at(int x, int y, int z) {
        if (x < 0 || x >= rows || y < 0 || y >= cols || z < 0 || z >= depth) {
            throw std::out_of_range("Access index exceeds array bounds");
        }
        return storage[x * (cols * depth) + y * depth + z];
    }

    int dimensionX() const { return rows; }
    int dimensionY() const { return cols; }
    int dimensionZ() const { return depth; }

