// Custom stream buffer for Python file output
#include <Python.h>
#include <iostream>
#include <streambuf>

class PythonOutputStreamBuffer : public std::streambuf {
public:
    PythonOutputStreamBuffer(PyFileObject* py_file) : py_file(py_file) {
        setp(internal_buffer, internal_buffer + sizeof(internal_buffer) - 1);
    }

protected:
    int overflow(int character) override {
        if (character != EOF) {
            char ch = static_cast<char>(character);
            PyFile_WriteString(&ch, 1, reinterpret_cast<PyObject*>(py_file));
        }
        return 0;
    }

    int sync() override {
        if (pptr() > pbase()) {
            PyFile_WriteString(pbase(), pptr() - pbase(), reinterpret_cast<PyObject*>(py_file));
            pbump(static_cast<int>(pbase() - pptr()));
        }
        return 0;
    }

private:
    PyFileObject* py_file;
    char internal_buffer[2048];
};

class PythonOutputStream : public std::ostream {
public:
    PythonOutputStream(PyFileObject* py_file) 
        : std::ostream(new PythonOutputStreamBuffer(py_file)) {}

    ~PythonOutputStream() {
        delete rdbuf();
    }
};

