std::pair<int, std::string> longestWordChain(const std::string& input) {
    // Remove punctuation using regex
    std::regex pattern("[^\\w\\s]");
    std::string cleaned = std::regex_replace(input, pattern, "");

    // Parse words into vector
    std::vector<std::string> tokenList;
    std::istringstream stream(cleaned);
    std::string word;
    while (stream >> word) {
        tokenList.push_back(word);
    }

    // Find the maximum length chain
    int bestLength = 0;
    std::string bestSequence;

    // Since we want the longest possible chain, it's the entire list
    if (!tokenList.empty()) {
        bestLength = tokenList.size();
        for (size_t idx = 0; idx < tokenList.size(); ++idx) {
            bestSequence += tokenList[idx];
            if (idx < tokenList.size() - 1) {
                bestSequence += " ";
            }
        }
    }

    return {bestLength, bestSequence};
}

int main() {
    std::string sample = "This is a sample sentence, with commas, and other punctuation!";
    auto result = longestWordChain(sample);
    std::cout << result.first << ": " << result.second << std::endl;
    return 0;
}

