// Structure to hold precomputed values for fast division
struct FastDivParams {
    uint64_t multiplier;
    int shiftBits;
};

FastDivParams calculateFastDivisor(uint64_t divisor) {
    if (divisor == 0) {
        throw std::invalid_argument("Division by zero is undefined");
    }

    const uint64_t base = 1ULL << 32;
    uint64_t remainder1 = base;
    uint64_t remainder2 = 0;
    uint64_t quotient1 = 0;
    uint64_t quotient2 = 1;
    uint64_t tempQuotient, tempRemainder;
    int exponent = 0;

    // Extended Euclidean algorithm variant for magic number computation
    while (remainder1 >= divisor) {
        tempQuotient = remainder1 / divisor;
        tempRemainder = remainder1 % divisor;

        remainder1 = remainder2;
        remainder2 = tempRemainder;

        uint64_t oldQ1 = quotient1;
        quotient1 = quotient2;
        quotient2 = oldQ1 + tempQuotient * quotient2;

        ++exponent;
    }

    uint64_t magicMultiplier = (quotient1 + 1) * base;
    int rightShift = 32 - exponent;

    return {magicMultiplier, rightShift};
}

// Perform division using precomputed magic parameters
uint64_t fastDivide(uint64_t dividend, const FastDivParams& params) {
    uint64_t productHigh = (dividend * params.multiplier) >> params.shiftBits;
    return productHigh;
}

int main() {
    uint64_t divisorValue = 7;  // Test divisor
    FastDivParams params = calculateFastDivisor(divisorValue);

    uint64_t testValues[] = {100, 200, 300};

    for (int i = 0; i < 3; ++i) {
        uint64_t result = fastDivide(testValues[i], params);
        std::cout << "Result of " << testValues[i] << " / " 
                  << divisorValue << " = " << result << std::endl;
    }

    return 0;
}

