// Reorder and sort 16 signed bytes using SIMD operations
__m128i sort_bytes_simd(__m128i input) {
    // First pass: compare adjacent pairs (0-1, 2-3, ..., 14-15)
    __m128i pair_lo = _mm_shuffle_epi8(input, _mm_setr_epi8(1,0,3,2,5,4,7,6,9,8,11,10,13,12,15,14));
    __m128i gt_mask = _mm_cmpgt_epi8(input, pair_lo);
    __m128i swapped = _mm_blendv_epi8(pair_lo, input, gt_mask);

    // Second pass: compare pairs with offset 2 (0-2, 1-3, 4-6, ...)
    __m128i offset_lo = _mm_shuffle_epi8(swapped, _mm_setr_epi8(2,3,0,1,6,7,4,5,10,11,8,9,14,15,12,13));
    gt_mask = _mm_cmpgt_epi8(swapped, offset_lo);
    swapped = _mm_blendv_epi8(offset_lo, swapped, gt_mask);

    // Third pass: compare with offset 4 (0-4, 1-5, ..., 8-12, 9-13, ...)
    __m128i step4_lo = _mm_shuffle_epi8(swapped, _mm_setr_epi8(4,5,6,7,0,1,2,3,12,13,14,15,8,9,10,11));
    gt_mask = _mm_cmpgt_epi8(swapped, step4_lo);
    swapped = _mm_blendv_epi8(step4_lo, swapped, gt_mask);

    // Fourth pass: compare with offset 8 (0-8, 1-9, ..., 7-15)
    __m128i final_lo = _mm_shuffle_epi8(swapped, _mm_setr_epi8(8,9,10,11,12,13,14,15,0,1,2,3,4,5,6,7));
    gt_mask = _mm_cmpgt_epi8(swapped, final_lo);
    swapped = _mm_blendv_epi8(final_lo, swapped, gt_mask);

    return swapped;
}

int main() {
    // Initialize with the same values as original
    __m128i input_data = _mm_setr_epi8(10, 2, 5, 1, 9, 3, 8, 4, 15, 6, 14, 7, 13, 11, 12, 0);
    __m128i result = sort_bytes_simd(input_data);

    // Extract results to array for output
    unsigned char output[16];
    _mm_storeu_si128(reinterpret_cast<__m128i*>(output), result);

    // Print sorted bytes
    for (int idx = 0; idx < 16; ++idx) {
        std::cout << static_cast<int>(output[idx]) << " ";
    }
    std::cout << std::endl;

    return 0;
}

#include <iostream>
#include <iomanip>
#include <cmath>
#include <boost/accumulators/accumulators.hpp>
#include <boost/accumulators/statistics/stats.hpp>
#include <boost/accumulators/statistics/count.hpp>
#include <boost/accumulators/statistics/mean.hpp>
#include <boost/accumulators/statistics/variance.hpp>

namespace acc = boost::accumulators;

int main()
{
    // Initialize accumulator set for computing count, mean, and variance
    acc::accumulator_set<double, acc::stats<acc::tag::count,
                                            acc::tag::mean,
                                            acc::tag::variance>> stats;

    double previous_value = NAN;
    bool is_first_iteration = true;

    // Process the sequence of values to compute returns
    double values[] = { 1.0, 1.0, 2.0, 1.0, 3.0, 2.0, 3.0, 4.0, 6.0, 3.0, 2.0, 1.0 };
    size_t array_size = sizeof(values) / sizeof(values[0]);

    for (size_t idx = 0; idx < array_size; ++idx)
    {
        if (is_first_iteration) {
            is_first_iteration = false;
            previous_value = values[idx];
            continue;
        }

        // Calculate return: (current - previous) / previous
        double current_return = (values[idx] - previous_value) / previous_value;
        stats(current_return);

        previous_value = values[idx];
    }

    // Extract statistics
    double count_val = acc::count(stats);
    double mean_val = acc::mean(stats);
    double sample_variance = acc::variance(stats) * count_val / (count_val - 1); // Bessel's correction

    // Output results with high precision
    std::cout << std::setprecision(16)
              << "count:    " << count_val << '\n'
              << "mean:     " << mean_val << '\n'
              << "variance: " << sample_variance << '\n';

    return 0;
}

