// Compute the middle value of a sorted dataset
double calculateMedian(vector<double>& data) {
    int n = data.size();

    // Rearrange elements in ascending order
    sort(data.begin(), data.end());

    if (n % 2 == 0) {
        return (data[n/2 - 1] + data[n/2]) * 0.5;
    } else {
        return data[n/2];
    }
}

// Determine the most frequently occurring value
double calculateMode(vector<double>& data) {
    unordered_map<double, int> counts;
    for (double val : data) {
        counts[val]++;
    }

    double mostFrequent = data[0];
    int highestFrequency = -1;

    for (const auto& entry : counts) {
        if (entry.second > highestFrequency) {
            highestFrequency = entry.second;
            mostFrequent = entry.first;
        }
    }

    return mostFrequent;
}

int main() {
    vector<double> values = {1.5, 3.0, 4.5, 2.5, 5.0};

    double medianResult = calculateMedian(values);
    cout << "Median is: " << medianResult << endl;

    double modeResult = calculateMode(values);
    cout << "Mode is: " << modeResult << endl;

    return 0;
}

