void my_function(uint32_t *src, uint32_t *dst) {
    // Load the input data
    uint32x4_t input = vld1q_u32(src);

    // Extract each byte from each 32-bit element and reconstruct in reversed order
    uint8x16_t bytes = vreinterpretq_u8_u32(input);

    // Manually permute bytes: for each 32-bit lane, reverse the byte order
    // Lane 0: bytes 0,1,2,3 -> 3,2,1,0
    // Lane 1: bytes 4,5,6,7 -> 7,6,5,4
    // etc.
    uint8x16_t permuted = vcombine_u8(
        vrev32_u8(vget_low_u8(bytes)),
        vrev32_u8(vget_high_u8(bytes))
    );

    // Store the result back as uint32_t
    vst1q_u32(dst, vreinterpretq_u32_u8(permuted));
}

