ICLRRuntimeHost* pRuntimeHost = nullptr;
ICLRRuntimeInfo* pRuntimeDetails = nullptr;

HRESULT InitializeManagedEnvironment()
{
    HRESULT result = S_OK;

    // Define the target CLR version
    const wchar_t* runtimeVersion = L"v4.0.30319";

    // Create an instance of the .NET runtime host
    result = CLRCreateInstance(CLSID_CLRMetaHost, IID_ICLRRuntimeInfo, (void**)&pRuntimeDetails);
    if (FAILED(result))
    {
        return result;
    }

    // Verify that the requested runtime can be loaded
    BOOL isCompatible = FALSE;
    result = pRuntimeDetails->IsLoadable(&isCompatible);
    if (FAILED(result) || !isCompatible)
    {
        pRuntimeDetails->Release();
        return result;
    }

    // Obtain the runtime host interface
    result = pRuntimeDetails->GetInterface(CLSID_CLRRuntimeHost, IID_ICLRRuntimeHost, (void**)&pRuntimeHost);
    if (FAILED(result))
    {
        pRuntimeDetails->Release();
        return result;
    }

    // Launch the Common Language Runtime
    result = pRuntimeHost->Start();
    if (FAILED(result))
    {
        pRuntimeHost->Release();
        pRuntimeDetails->Release();
        return result;
    }

    return S_OK;
}

void CleanupManagedEnvironment()
{
    if (pRuntimeHost)
    {
        pRuntimeHost->Stop();
        pRuntimeHost->Release();
        pRuntimeHost = nullptr;
    }
    if (pRuntimeDetails)
    {
        pRuntimeDetails->Release();
        pRuntimeDetails = nullptr;
    }
}

