__inline__ __device__ uint32_t per_byte_bit_left_rotate(uint32_t input, uint8_t amount) {
    uint32_t result = 0;

    // Process each byte individually using a while loop instead of for loop
    int byte_index = 0;
    uint32_t temp_input = input;

    while (byte_index < 4) {
        // Extract current byte
        uint8_t byte = temp_input & 0xFF;

        // Perform rotation on the byte: left shift with wrap-around
        uint8_t rotated = (byte << amount) | (byte >> (8 - amount));
        rotated &= 0xFF;  // Ensure only lower 8 bits remain

        // Place rotated byte back into result at correct position
        result |= (static_cast<uint32_t>(rotated) << (byte_index * 8));

        // Move to next byte
        temp_input >>= 8;
        byte_index++;
    }

    return result;
}

