#include <pybind11/pybind11.h>
#include <pybind11/numpy.h>

namespace py = pybind11;

// Vector structure with N elements of type T
template<typename T, std::size_t SIZE> 
struct array_wrapper {
  explicit array_wrapper(const T* input) {
    for (std::size_t idx = 0; idx < SIZE; ++idx) {
      storage[idx] = input[idx];
    }
  }
  T storage[SIZE];
};

// Create a 2D double vector from a scalar value
array_wrapper<double, 2> make_double_array(double value) {
  double temp[] = {value, value};
  return array_wrapper<double, 2>{temp};
}

// PyBind11 type caster for our custom array wrapper
namespace pybind11 { namespace detail {
  template <typename T, std::size_t SIZE> 
  struct type_caster<array_wrapper<T, SIZE>>
  {
  private:
    using _wrapper_type = array_wrapper<T, SIZE>;

  public:
    PYBIND11_TYPE_CASTER(_wrapper_type, _("array_wrapper<T, SIZE>"));

    bool load(py::handle source, bool allow_conversion) {
      if (!allow_conversion && !py::array_t<T>::check_(source)) {
        return false;
      }

      auto buffer = py::array_t<T>::ensure(source);
      if (!buffer || buffer.ndim() != 1 || buffer.size() != SIZE) {
        return false;
      }

      value = _wrapper_type{buffer.data()};
      return true;
    }

    static py::handle cast(const _wrapper_type& src,
                          py::return_value_policy policy,
                          py::handle parent) {
      py::array_t<T> result({SIZE});
      for (std::size_t i = 0; i < SIZE; ++i) {
        result.mutable_at(i) = src.storage[i];
      }
      return result.release();
    }
  };
}}

// Explicit instantiation for double array of size 2
template struct pybind11::detail::type_caster<array_wrapper<double, 2>>;

// Alternative function with input validation
array_wrapper<double, 2> make_array_with_validation(const py::array_t<double>& input_array) {
  if (input_array.ndim() != 1 || input_array.size() != 1) {
    throw std::runtime_error("Expected a one-dimensional array containing exactly one element.");
  }

  double scalar_value = input_array.at(0);
  return make_double_array(scalar_value);
}

// Module definition
PYBIND11_MODULE(vector_module, mod) {
  mod.def("make_vector", py::vectorize(&make_double_array));
  mod.def("make_vector_safe", &make_array_with_validation);
}

