// Perform a left bitwise shift on a 1280-bit number represented as 20 64-bit chunks
void left_shift_array(std::array<unsigned long long, 20>& data, unsigned int shift_bits) {
    if (shift_bits == 0) return;

    const unsigned int bits_per_word = 64;
    unsigned int word_shifts = shift_bits / bits_per_word;
    unsigned int bit_offset = shift_bits % bits_per_word;

    // If shift exceeds array capacity, clear all elements
    if (word_shifts >= data.size()) {
        data.fill(0);
        return;
    }

    // Move words to higher positions
    for (int idx = data.size() - 1; idx >= static_cast<int>(word_shifts); --idx) {
        data[idx] = data[idx - word_shifts];
    }

    // Zero out the vacated lower positions
    for (unsigned int idx = 0; idx < word_shifts; ++idx) {
        data[idx] = 0;
    }

    // Apply bit-level shifting within words if needed
    if (bit_offset > 0) {
        unsigned long long carry_over = 0;
        for (int idx = data.size() - 1; idx >= 0; --idx) {
            unsigned long long current_value = data[idx];
            unsigned long long shifted = current_value << bit_offset;
            data[idx] = shifted | carry_over;
            carry_over = current_value >> (bits_per_word - bit_offset);
        }
    }
}

// Perform a right bitwise shift on a 1280-bit number represented as 20 64-bit chunks
void right_shift_array(std::array<unsigned long long, 20>& data, unsigned int shift_bits) {
    if (shift_bits == 0) return;

    const unsigned int bits_per_word = 64;
    unsigned int word_shifts = shift_bits / bits_per_word;
    unsigned int bit_offset = shift_bits % bits_per_word;

    // If shift exceeds array capacity, clear all elements
    if (word_shifts >= data.size()) {
        data.fill(0);
        return;
    }

    // Move words to lower positions
    for (unsigned int idx = 0; idx < data.size() - word_shifts; ++idx) {
        data[idx] = data[idx + word_shifts];
    }

    // Zero out the vacated upper positions
    for (unsigned int idx = data.size() - word_shifts; idx < data.size(); ++idx) {
        data[idx] = 0;
    }

    // Apply bit-level shifting within words if needed
    if (bit_offset > 0) {
        unsigned long long carry_over = 0;
        for (unsigned int idx = 0; idx < data.size(); ++idx) {
            unsigned long long current_value = data[idx];
            unsigned long long shifted = current_value >> bit_offset;
            data[idx] = shifted | carry_over;
            carry_over = current_value << (bits_per_word - bit_offset);
        }
    }
}

int main() {
    std::array<unsigned long long, 20> big_number = { /* Initialize with some values */ };

    // Demonstrate left shift operation
    left_shift_array(big_number, 5);

    // Output the result
    for (const auto& chunk : big_number) {
        std::cout << chunk << " ";
    }
    std::cout << std::endl;

    return 0;
}

#include <iostream>
