const int MATRIX_SIZE = 1024;  // Dimension of the square matrices

// Perform matrix multiplication using standard triple-nested loop
void computeMatrixProduct(const std::vector<std::vector<int>>& firstMatrix, 
                          const std::vector<std::vector<int>>& secondMatrix, 
                          std::vector<std::vector<int>>& resultMatrix) {
    for (int row = 0; row < MATRIX_SIZE; ++row) {
        for (int col = 0; col < MATRIX_SIZE; ++col) {
            int accumulator = 0;
            for (int k = 0; k < MATRIX_SIZE; ++k) {
                accumulator += firstMatrix[row][k] * secondMatrix[k][col];
            }
            resultMatrix[row][col] = accumulator;
        }
    }
}

int main() {
    // Initialize matrices with ones and zeros
    std::vector<std::vector<int>> matrixA(MATRIX_SIZE, std::vector<int>(MATRIX_SIZE, 1));
    std::vector<std::vector<int>> matrixB(MATRIX_SIZE, std::vector<int>(MATRIX_SIZE, 1));
    std::vector<std::vector<int>> matrixC(MATRIX_SIZE, std::vector<int>(MATRIX_SIZE, 0));

    // Measure execution time
    auto startTime = std::chrono::high_resolution_clock::now();
    computeMatrixProduct(matrixA, matrixB, matrixC);
    auto endTime = std::chrono::high_resolution_clock::now();

    // Output timing results
    std::chrono::duration<double> elapsed = endTime - startTime;
    std::cout << "CPU Execution Time: " << elapsed.count() << " seconds" << std::endl;

    return 0;
}

