struct I420Buffer {
    int w;
    int h;
    uint8_t* buf;
    uint8_t* yPlane;
    uint8_t* uPlane;
    uint8_t* vPlane;
};

static I420Buffer input_buffer;
static I420Buffer output_buffer;

extern "C" {

JNIEXPORT jbyteArray JNICALL
Java_com_android_camera3_camera_hardware_session_output_photo_yuv_YuvJniInterface_scale420YuvByteArray(
        JNIEnv* env, jclass /*clazz*/, jbyteArray yuvByteArray_, jint src_w, jint src_h,
        jint dst_w, jint dst_h) {

    jbyte* raw_data = env->GetByteArrayElements(yuvByteArray_, nullptr);

    // Compute sizes
    int src_len = env->GetArrayLength(yuvByteArray_);
    int dst_len = dst_w * dst_h * 3 / 2;

    // Setup input buffer
    input_buffer.w = src_w;
    input_buffer.h = src_h;
    input_buffer.buf = reinterpret_cast<uint8_t*>(raw_data);
    input_buffer.yPlane = input_buffer.buf;
    input_buffer.uPlane = input_buffer.yPlane + src_w * src_h;
    input_buffer.vPlane = input_buffer.uPlane + (src_w * src_h) / 4;

    // Release previous output buffer if exists
    if (output_buffer.buf != nullptr) {
        delete[] output_buffer.buf;
        output_buffer.buf = nullptr;
    }

    // Allocate and configure output buffer
    output_buffer.w = dst_w;
    output_buffer.h = dst_h;
    output_buffer.buf = new unsigned char[dst_len];
    output_buffer.yPlane = output_buffer.buf;
    output_buffer.uPlane = output_buffer.yPlane + dst_w * dst_h;
    output_buffer.vPlane = output_buffer.uPlane + (dst_w * dst_h) / 4;

    libyuv::FilterMode scaling_mode = libyuv::FilterModeEnum::kFilterBilinear;

    int status = libyuv::I420Scale(
        input_buffer.yPlane, input_buffer.w,
        input_buffer.uPlane, input_buffer.w / 2,
        input_buffer.vPlane, input_buffer.w / 2,
        input_buffer.w, input_buffer.h,
        output_buffer.yPlane, output_buffer.w,
        output_buffer.uPlane, output_buffer.w / 2,
        output_buffer.vPlane, output_buffer.w / 2,
        output_buffer.w, output_buffer.h,
        scaling_mode
    );

    LOGD("Scaling completed with status: %d", status);

    // Transfer result back to Java
    jbyteArray result_array = env->NewByteArray(dst_len);
    env->SetByteArrayRegion(result_array, 0, dst_len, reinterpret_cast<jbyte*>(output_buffer.buf));

    env->ReleaseByteArrayElements(yuvByteArray_, raw_data, JNI_ABORT);

    return result_array;
}
}

