// Extract words from text using regex
std::vector<std::string> extractWords(const std::string& input) {
    std::vector<std::string> result;
    std::regex token_pattern(R"(\b\w+\b)");
    auto start = std::sregex_iterator(input.begin(), input.end(), token_pattern);
    auto end = std::sregex_iterator();

    for (auto it = start; it != end; ++it) {
        result.push_back((*it).str());
    }
    return result;
}

// Build adjacency list where each word points to longer words that start with it
std::unordered_map<std::string, std::vector<std::string>> constructWordGraph(const std::vector<std::string>& wordList) {
    std::unordered_map<std::string, std::vector<std::string>> adjList;
    for (const auto& currentWord : wordList) {
        // Check all possible prefixes of the current word
        for (size_t len = 1; len < currentWord.length(); ++len) {
            std::string prefix = currentWord.substr(0, len);
            // If prefix exists in our word list, add edge
            if (std::find(wordList.begin(), wordList.end(), prefix) != wordList.end()) {
                adjList[prefix].push_back(currentWord);
            }
        }
    }
    return adjList;
}

// Depth-first search with memoization to find longest chain starting at a word
int computeChainLength(const std::string& startWord,
                      const std::unordered_map<std::string, std::vector<std::string>>& graph,
                      std::unordered_map<std::string, int>& cache) {
    // Return cached result if available
    if (cache.find(startWord) != cache.end()) {
        return cache[startWord];
    }

    int best = 1;  // At minimum, chain contains the word itself

    // Explore all neighbors (words that can follow)
    auto iter = graph.find(startWord);
    if (iter != graph.end()) {
        for (const auto& nextWord : iter->second) {
            int pathLength = 1 + computeChainLength(nextWord, graph, cache);
            if (pathLength > best) {
                best = pathLength;
            }
        }
    }

    cache[startWord] = best;
    return best;
}

// Find the maximum chain length across all words
int determineMaxChain(const std::unordered_map<std::string, std::vector<std::string>>& graph,
                     const std::unordered_set<std::string>& vocabulary) {
    std::unordered_map<std::string, int> memoTable;

    // Compute chain lengths for all words
    for (const auto& word : vocabulary) {
        computeChainLength(word, graph, memoTable);
    }

    // Find maximum value in memo table
    int maxChain = 0;
    for (const auto& entry : memoTable) {
        if (entry.second > maxChain) {
            maxChain = entry.second;
        }
    }
    return maxChain;
}

int main() {
    std::string sampleText = "I am a software engineer and I love programming.";
    std::vector<std::string> tokens = extractWords(sampleText);
    std::unordered_set<std::string> uniqueWords(tokens.begin(), tokens.end());
    std::unordered_map<std::string, std::vector<std::string>> wordConnections = constructWordGraph(tokens);

    std::cout << determineMaxChain(wordConnections, uniqueWords) << std::endl;
    return 0;
}

