#include <unicode/brkiter.h>
#include <emscripten.h>

extern "C" {
    EMSCRIPTEN_KEEPALIVE
    int word_iterate(const char* str, int len) {
        UErrorCode status = U_ZERO_ERROR;

        // Allocate buffer for UTF-16 string (maximum possible length)
        int maxUChars = len + 1;
        UChar* ustr = new UChar[maxUChars];

        // Convert from UTF-8 to UTF-16
        u_strFromUTF8(ustr, maxUChars, nullptr, str, len, &status);
        if (U_FAILURE(status)) {
            delete[] ustr;
            return -1;
        }

        // Create word boundary iterator
        BreakIterator* bi = BreakIterator::createWordInstance(Locale::getDefault(), status);
        if (U_FAILURE(status)) {
            delete[] ustr;
            return -1;
        }

        // Set the text to analyze
        bi->setText(ustr, u_strlen(ustr), status);
        if (U_FAILURE(status)) {
            delete[] ustr;
            delete bi;
            return -1;
        }

        // Iterate through all word boundaries
        int32_t start = bi->first();
        int32_t end = bi->next();

        while (end != BreakIterator::DONE) {
            // Extract current word segment
            int wordLen = end - start;
            UChar* wordBuffer = new UChar[wordLen + 1];
            u_strncpy(wordBuffer, ustr + start, wordLen, &status);
            wordBuffer[wordLen] = 0;

            // Convert UTF-16 word to UTF-8 for JavaScript
            int utf8Len = u_strToUTF8(nullptr, 0, nullptr, wordBuffer, -1, &status);
            char* utf8Buffer = new char[utf8Len + 1];
            u_strToUTF8(utf8Buffer, utf8Len + 1, nullptr, wordBuffer, -1, &status);

            // Pass to JavaScript console
            EM_ASM({
                console.log(UTF8ToString($0));
            }, utf8Buffer);

            // Cleanup temporary buffers
            delete[] wordBuffer;
            delete[] utf8Buffer;

            // Move to next word boundary
            start = end;
            end = bi->next();
        }

        // Final cleanup
        delete[] ustr;
        delete bi;
        return 0;
    }
}

