#include <iostream>
#include <string>
#include <vector>
#include <cctype>
#include <unordered_map>

enum class TokenType {
    INT, FLOAT, IDENTIFIER, ASSIGN, PLUS, MINUS, MUL, DIV, LPAREN, RPAREN, SEMICOLON, EOF_TOKEN,
    IF, WHILE, FUNCTION, COMMA, LBRACE, RBRACE, ERROR
};

struct Token {
    TokenType type;
    std::string value;
    int line;
    int column;
};

class Lexer {
public:
    Lexer(const std::string& source) : text(source), index(0), currentLine(1), currentColumn(1) {}

    Token getNextToken();

private:
    std::string text;
    size_t index;
    int currentLine;
    int currentColumn;

    char peekChar();
    void moveNext();
    void skipSpaces();
    Token parseNumber();
    Token parseName();
    Token checkKeyword(const std::string& word);
};

char Lexer::peekChar() {
    return index < text.length() ? text[index] : '\0';
}

void Lexer::moveNext() {
    if (peekChar() == '\n') {
        currentLine++;
        currentColumn = 1;
    } else {
        currentColumn++;
    }
    index++;
}

void Lexer::skipSpaces() {
    while (std::isspace(peekChar())) {
        moveNext();
    }
}

Token Lexer::parseNumber() {
    std::string digits;
    while (std::isdigit(peekChar()) || peekChar() == '.') {
        digits += peekChar();
        moveNext();
    }
    if (digits.find('.') != std::string::npos) {
        return {TokenType::FLOAT, digits, currentLine, currentColumn};
    } else {
        return {TokenType::INT, digits, currentLine, currentColumn};
    }
}

Token Lexer::parseName() {
    std::string name;
    while (std::isalnum(peekChar()) || peekChar() == '_') {
        name += peekChar();
        moveNext();
    }
    return checkKeyword(name);
}

Token Lexer::checkKeyword(const std::string& word) {
    static const std::unordered_map<std::string, TokenType> reservedWords = {
        {"if", TokenType::IF},
        {"while", TokenType::WHILE},
        {"function", TokenType::FUNCTION}
    };

    auto found = reservedWords.find(word);
    if (found != reservedWords.end()) {
        return {found->second, word, currentLine, currentColumn};
    }
    return {TokenType::IDENTIFIER, word, currentLine, currentColumn};
}

Token Lexer::getNextToken() {
    skipSpaces();

    if (index >= text.length()) {
        return {TokenType::EOF_TOKEN, "", currentLine, currentColumn};
    }

    char c = peekChar();
    if (std::isdigit(c)) {
        return parseNumber();
    }

    if (std::isalpha(c) || c == '_') {
        return parseName();
    }

    moveNext();
    switch (c) {
        case '+': return {TokenType::PLUS, "+", currentLine, currentColumn};
        case '-': return {TokenType::MINUS, "-", currentLine, currentColumn};
        case '*': return {TokenType::MUL, "*", currentLine, currentColumn};
        case '/': return {TokenType::DIV, "/", currentLine, currentColumn};
        case '(': return {TokenType::LPAREN, "(", currentLine, currentColumn};
        case ')': return {TokenType::RPAREN, ")", currentLine, currentColumn};
        case ';': return {TokenType::SEMICOLON, ";", currentLine, currentColumn};
        case ',': return {TokenType::COMMA, ",", currentLine, currentColumn};
        case '{': return {TokenType::LBRACE, "{", currentLine, currentColumn};
        case '}': return {TokenType::RBRACE, "}", currentLine, currentColumn};
        default: return {TokenType::ERROR, std::string(1, c), currentLine, currentColumn};
    }
}

#include <iostream>
