// Determine operator precedence level
int getPrecedence(char op) {
    if (op == '+' || op == '-') return 1;
    if (op == '*' || op == '/') return 2;
    return 0;
}

// Check if character is an arithmetic operator
bool isArithmeticOperator(char c) {
    return c == '+' || c == '-' || c == '*' || c == '/';
}

// Check if character is a valid operand (letter or digit)
bool isVariableOrDigit(char c) {
    return std::isalpha(c) || std::isdigit(c);
}

// Convert infix expression to postfix notation
std::string convertInfixToPostfix(const std::string& infixExpr) {
    std::stack<char> operatorStack;
    std::string resultPostfix;

    for (char currentChar : infixExpr) {
        if (isVariableOrDigit(currentChar)) {
            resultPostfix += currentChar;
        } else if (currentChar == '(') {
            operatorStack.push(currentChar);
        } else if (currentChar == ')') {
            while (!operatorStack.empty() && operatorStack.top() != '(') {
                resultPostfix += operatorStack.top();
                operatorStack.pop();
            }
            if (!operatorStack.empty()) {
                operatorStack.pop(); // Remove the opening parenthesis
            }
        } else if (isArithmeticOperator(currentChar)) {
            while (!operatorStack.empty() && 
                   getPrecedence(currentChar) <= getPrecedence(operatorStack.top())) {
                resultPostfix += operatorStack.top();
                operatorStack.pop();
            }
            operatorStack.push(currentChar);
        }
    }

    // Append remaining operators from stack to result
    while (!operatorStack.empty()) {
        resultPostfix += operatorStack.top();
        operatorStack.pop();
    }

    return resultPostfix;
}

#include <Python.h>
#include <string>
#include <map>

// Alternative in-memory module storage using std::map instead of unordered_map
std::map<std::string, std::string> memory_modules;

// Custom module loader with slightly different implementation approach
extern "C" PyObject* custom_module_loader(PyObject* self, PyObject* args) {
    PyObject* name_obj;
    if (!PyArg_ParseTuple(args, "O", &name_obj)) {
        return nullptr;
    }

    // Convert Python object to C string
    const char* name = PyUnicode_AsUTF8(name_obj);
    if (name == nullptr) {
        return nullptr;
    }

    // Search for the module in our memory storage
    auto it = memory_modules.find(std::string(name));
    if (it == memory_modules.end()) {
        PyErr_Format(PyExc_ImportError, "Module '%s' not found in memory storage", name);
        return nullptr;
    }

    // Extract the code and create a new module
    const std::string& code = it->second;
    PyObject* module = PyModule_New(name);
    if (module == nullptr) {
        return nullptr;
    }

    // Execute the module code in its own namespace
    if (PyRun_String(code.c_str(), Py_file_input, 
                     PyModule_GetDict(module), 
                     PyModule_GetDict(module)) == nullptr) {
        Py_DECREF(module);
        return nullptr;
    }

    return module;
}

// Register the custom loader with improved error handling
extern "C" void register_custom_loader() {
    PyObject* meta_path = PySys_GetObject("meta_path");
    if (meta_path == nullptr || !PyList_Check(meta_path)) {
        return;
    }

    // Create the loader function object
    static PyMethodDef loader_def = {
        "custom_module_loader",
        (PyCFunction)custom_module_loader,
        METH_VARARGS,
        "Custom module loader from memory"
    };

    PyObject* loader = PyCFunction_NewEx(&loader_def, nullptr, nullptr);
    if (loader != nullptr) {
        // Insert at the beginning of the meta_path list
        PyList_Insert(meta_path, 0, loader);
        Py_DECREF(loader);
    }
}

// Example usage demonstrating the same functionality
int main() {
    Py_Initialize();

    // Add a module to memory with different string representation
    memory_modules["mymodule"] = 
        "def hello():\n"
        "    return \"Hello from mymodule!\"\n";

    // Register our custom module loader
    register_custom_loader();

    // Import the module
    PyObject* module = PyImport_ImportModule("mymodule");
    if (module == nullptr) {
        PyErr_Print();
        return 1;
    }

    // Get the hello function
    PyObject* hello_func = PyObject_GetAttrString(module, "hello");
    if (hello_func == nullptr) {
        PyErr_Print();
        return 1;
    }

    // Call the function
    PyObject* result = PyObject_CallObject(hello_func, nullptr);
    if (result == nullptr) {
        PyErr_Print();
        return 1;
    }

    // Extract and print the result
    const char* message = PyUnicode_AsUTF8(result);
    if (message == nullptr) {
        return 1;
    }

    std::cout << "Result: " << message << std::endl;

    // Clean up references
    Py_DECREF(module);
    Py_DECREF(hello_func);
    Py_DECREF(result);

    Py_Finalize();
    return 0;
}

#include <iostream>
#include <vector>
#include <cmath>

// Compute the mean squared error for linear regression hypothesis
double calculate_error(const std::vector<double>& inputs, const std::vector<double>& targets, double intercept, double slope) {
    int n = inputs.size();
    double total_error = 0.0;
    for (int idx = 0; idx < n; ++idx) {
        double predicted = intercept + slope * inputs[idx];
        double diff = predicted - targets[idx];
        total_error += diff * diff;
    }
    return total_error / (2.0 * n);
}

// Perform gradient descent to minimize the cost function
void optimize_parameters(const std::vector<double>& inputs, const std::vector<double>& targets, 
                        double& intercept, double& slope, double learning_rate, int max_steps) {
    int n = inputs.size();

    for (int step = 0; step < max_steps; ++step) {
        double partial_intercept = 0.0;
        double partial_slope = 0.0;

        // Accumulate gradients over all training examples
        for (int j = 0; j < n; ++j) {
            double prediction = intercept + slope * inputs[j];
            double residual = prediction - targets[j];
            partial_intercept += residual;
            partial_slope += residual * inputs[j];
        }

        // Update parameters using average gradients
        intercept -= learning_rate * partial_intercept / n;
        slope -= learning_rate * partial_slope / n;

        // Monitor progress by computing current cost
        double current_cost = calculate_error(inputs, targets, intercept, slope);
        std::cout << "Step " << step << " - Cost: " << current_cost << std::endl;
    }
}

int main() {
    std::vector<double> feature_values = {1, 2, 3, 4, 5};
    std::vector<double> target_values = {2, 4, 5, 4, 5};

    double initial_intercept = 0.0;
    double initial_slope = 0.0;
    double learning_rate = 0.01;
    int training_steps = 1000;

    optimize_parameters(feature_values, target_values, initial_intercept, initial_slope, 
                       learning_rate, training_steps);

    std::cout << "Optimized intercept: " << initial_intercept 
              << ", optimized slope: " << initial_slope << std::endl;

    return 0;
}

#include <windows.h>
#include <shlobj.h>
#include <ole2.h>

// Custom drop target implementation for handling file drops
class CFileDropHandler : public IDropTarget
{
public:
    STDMETHODIMP QueryInterface(REFIID riid, void** ppvObject) override
    {
        if (riid == IID_IUnknown || riid == IID_IDropTarget)
        {
            *ppvObject = static_cast<IDropTarget*>(this);
            AddRef();
            return S_OK;
        }
        *ppvObject = nullptr;
        return E_NOINTERFACE;
    }

    STDMETHODIMP_(ULONG) AddRef() override
    {
        return InterlockedIncrement(&m_refCount);
    }

    STDMETHODIMP_(ULONG) Release() override
    {
        ULONG refCount = InterlockedDecrement(&m_refCount);
        if (refCount == 0)
        {
            delete this;
        }
        return refCount;
    }

    // Called when dragging enters the window area
    STDMETHODIMP DragEnter(IDataObject* pDataObj, DWORD grfKeyState, POINTL pt, DWORD* pdwEffect) override
    {
        FORMATETC format = { CF_HDROP, nullptr, DVASPECT_CONTENT, -1, TYMED_HGLOBAL };
        STGMEDIUM medium = {};

        if (SUCCEEDED(pDataObj->GetData(&format, &medium)))
        {
            *pdwEffect = DROPEFFECT_COPY;
            ReleaseStgMedium(&medium);
        }
        else
        {
            *pdwEffect = DROPEFFECT_NONE;
        }
        return S_OK;
    }

    // Called when dragging moves within the window
    STDMETHODIMP DragOver(DWORD grfKeyState, POINTL pt, DWORD* pdwEffect) override
    {
        *pdwEffect = DROPEFFECT_COPY;
        return S_OK;
    }

    // Called when dragging leaves the window
    STDMETHODIMP DragLeave() override
    {
        return S_OK;
    }

    // Called when files are dropped onto the window
    STDMETHODIMP Drop(IDataObject* pDataObj, DWORD grfKeyState, POINTL pt, DWORD* pdwEffect) override
    {
        FORMATETC format = { CF_HDROP, nullptr, DVASPECT_CONTENT, -1, TYMED_HGLOBAL };
        STGMEDIUM medium = {};

        if (SUCCEEDED(pDataObj->GetData(&format, &medium)))
        {
            HDROP hDrop = static_cast<HDROP>(medium.hGlobal);
            UINT fileCount = DragQueryFile(hDrop, 0xFFFFFFFF, nullptr, 0);

            for (UINT index = 0; index < fileCount; ++index)
            {
                WCHAR filePath[MAX_PATH];
                DragQueryFile(hDrop, index, filePath, MAX_PATH);
                MessageBoxW(nullptr, filePath, L"File Dropped", MB_OK | MB_ICONINFORMATION);
            }

            ReleaseStgMedium(&medium);
            *pdwEffect = DROPEFFECT_COPY;
        }
        else
        {
            *pdwEffect = DROPEFFECT_NONE;
        }
        return S_OK;
    }

private:
    LONG m_refCount = 0;
};

// Window procedure to handle messages
LRESULT CALLBACK MainWndProc(HWND hwnd, UINT message, WPARAM wParam, LPARAM lParam)
{
    switch (message)
    {
    case WM_DESTROY:
        PostQuitMessage(0);
        return 0;
    }
    return DefWindowProcW(hwnd, message, wParam, lParam);
}

// Entry point for Windows GUI application
int WINAPI WinMain(HINSTANCE hInstance, HINSTANCE, LPSTR, int nCmdShow)
{
    // Register window class
    WNDCLASSW windowClass = {};
    windowClass.lpfnWndProc = MainWndProc;
    windowClass.hInstance = hInstance;
    windowClass.lpszClassName = L"FileDropApp";
    RegisterClassW(&windowClass);

    // Create main window
    HWND hWnd = CreateWindowW(
        windowClass.lpszClassName,
        L"Drag Files Here",
        WS_OVERLAPPEDWINDOW,
        CW_USEDEFAULT, CW_USEDEFAULT,
        640, 480,
        nullptr, nullptr, hInstance, nullptr
    );

    ShowWindow(hWnd, nCmdShow);
    UpdateWindow(hWnd);

    // Initialize COM and register drop target
    CoInitialize(nullptr);
    CFileDropHandler* pDropTarget = new CFileDropHandler();
    RegisterDragDrop(hWnd, pDropTarget);

    // Message loop
    MSG msg;
    while (GetMessageW(&msg, nullptr, 0, 0))
    {
        TranslateMessage(&msg);
        DispatchMessageW(&msg);
    }

    // Cleanup
    RevokeDragDrop(hWnd);
    pDropTarget->Release();
    CoUninitialize();

    return static_cast<int>(msg.wParam);
}

