namespace google {
namespace protobuf {

void StringAppendF(std::string* result, const char* pattern, ...) {
    va_list parameters;
    va_start(parameters, pattern);

    // Allocate buffer dynamically to handle longer strings
    std::vector<char> temp_buffer(2048);
    int written = vsnprintf(temp_buffer.data(), temp_buffer.size(), pattern, parameters);

    if (written > 0 && static_cast<size_t>(written) < temp_buffer.size()) {
        *result += std::string(temp_buffer.data(), written);
    } else if (written >= 0) {
        // Retry with properly sized buffer
        temp_buffer.resize(written + 1);
        va_end(parameters);
        va_start(parameters, pattern);
        vsnprintf(temp_buffer.data(), temp_buffer.size(), pattern, parameters);
        *result += std::string(temp_buffer.data(), written);
    }

    va_end(parameters);
}

