extern "C" JNIEXPORT jbyteArray JNICALL
Java_com_my_package_name_MyNativeClass_processImage(JNIEnv* env, jobject /* obj */, jbyteArray inputBytes) {
    // Extract raw data from Java byte array
    jbyte* rawData = env->GetByteArrayElements(inputBytes, nullptr);
    jsize inputSize = env->GetArrayLength(inputBytes);

    // Convert to OpenCV-compatible format
    std::vector<unsigned char> buffer(rawData, rawData + inputSize);
    cv::Mat originalImage = cv::imdecode(buffer, cv::IMREAD_COLOR);

    // Handle decoding failure
    if (originalImage.empty()) {
        env->ReleaseByteArrayElements(inputBytes, rawData, 0);
        return nullptr;
    }

    // Perform edge detection using different parameters and method variant
    cv::Mat processedEdges;
    cv::Canny(originalImage, processedEdges, 100, 200, 3);

    // Encode result as JPEG byte array
    std::vector<unsigned char> encodedBuffer;
    cv::imencode(".jpg", processedEdges, encodedBuffer);

    // Create and populate Java byte array with the result
    jbyteArray outputArray = env->NewByteArray(encodedBuffer.size());
    env->SetByteArrayRegion(outputArray, 0, encodedBuffer.size(), 
                            reinterpret_cast<const jbyte*>(encodedBuffer.data()));

    // Clean up resources
    env->ReleaseByteArrayElements(inputBytes, rawData, 0);

    return outputArray;
}

