JNIEXPORT jboolean JNICALL Java_com_entrust_adminservices_urs_examples_authn_LdapAuthenticator2_takeInfo(
    JNIEnv *env, jobject obj, jstring domain, jstring id, jstring idca, jstring password, jstring* errorMessage) 
{
    // Extract UTF-8 strings from JNI jstrings
    const char* user = env->GetStringUTFChars(id, nullptr);
    const char* realm = env->GetStringUTFChars(domain, nullptr);
    const char* cred = env->GetStringUTFChars(password, nullptr);

    HANDLE tokenHandle = nullptr;
    BOOL success = FALSE;

    // Attempt logon using provided credentials
    success = LogonUserA(user, realm, cred,
                         LOGON32_LOGON_NETWORK,
                         LOGON32_PROVIDER_DEFAULT,
                         &tokenHandle);

    // Release native string buffers early
    env->ReleaseStringUTFChars(id, user);
    env->ReleaseStringUTFChars(domain, realm);
    env->ReleaseStringUTFChars(password, cred);

    if (success)
    {
        CloseHandle(tokenHandle);
        return JNI_TRUE;
    }

    // Handle failure: retrieve system error message
    DWORD errCode = GetLastError();
    void* msgBuffer = nullptr;

    FormatMessageA(FORMAT_MESSAGE_ALLOCATE_BUFFER | FORMAT_MESSAGE_FROM_SYSTEM | FORMAT_MESSAGE_IGNORE_INSERTS,
                   nullptr, errCode, MAKELANGID(LANG_NEUTRAL, SUBLANG_DEFAULT),
                   reinterpret_cast<LPSTR>(&msgBuffer), 0, nullptr);

    *errorMessage = env->NewStringUTF(static_cast<const char*>(msgBuffer));
    LocalFree(msgBuffer);

    return JNI_FALSE;
}

#include <iostream>
#include <vector>
#include <algorithm>
