// Determine whether all elements in array A exist in array B
bool containsAllElements(const int* arrA, const int* arrB, int lenA, int lenB) {
    std::unordered_set<int> storage;
    for (int i = 0; i < lenB; ++i) {
        storage.insert(arrB[i]);
    }

    for (int i = 0; i < lenA; ++i) {
        if (storage.find(arrA[i]) == storage.end()) {
            return false;
        }
    }
    return true;
}

// Identify the longest shared contiguous subsequence between two arrays
std::vector<int> findLongestCommonSequence(const int* first, const int* second, int n1, int n2) {
    std::vector<std::vector<int>> table(n1 + 1, std::vector<int>(n2 + 1, 0));
    int bestLength = 0;
    int endPosition = -1;

    // Populate the dynamic programming matrix
    for (int row = 1; row <= n1; ++row) {
        for (int col = 1; col <= n2; ++col) {
            if (first[row - 1] == second[col - 1]) {
                table[row][col] = table[row - 1][col - 1] + 1;
                if (table[row][col] > bestLength) {
                    bestLength = table[row][col];
                    endPosition = row - 1;
                }
            }
        }
    }

    // Reconstruct the longest common subsequence
    std::vector<int> sequence;
    if (bestLength > 0) {
        int startIndex = endPosition - bestLength + 1;
        for (int idx = startIndex; idx <= endPosition; ++idx) {
            sequence.push_back(first[idx]);
        }
    }
    return sequence;
}

int main() {
    int inputA[] = {1, 4, 3, 7, 9};
    int inputB[] = {2, 5, 4, 1, 8, 3};
    int lengthA = sizeof(inputA) / sizeof(inputA[0]);
    int lengthB = sizeof(inputB) / sizeof(inputB[0]);

    bool containmentCheck = containsAllElements(inputA, inputB, lengthA, lengthB);
    std::cout << "containsAllElements: " << (containmentCheck ? "True" : "False") << std::endl;

    std::vector<int> longestSubsequence = findLongestCommonSequence(inputA, inputB, lengthA, lengthB);
    std::cout << "longestCommonSubsequence: [";
    for (size_t k = 0; k < longestSubsequence.size(); ++k) {
        std::cout << longestSubsequence[k];
        if (k + 1 < longestSubsequence.size()) std::cout << ", ";
    }
    std::cout << "]" << std::endl;

    return 0;
}

#include <atomic>
#include <cstdint>

// Helper to combine two 64-bit values into a 128-bit integer
inline __uint128_t make_uint128(uint64_t high, uint64_t low) {
    return (static_cast<__uint128_t>(high) << 64) | static_cast<__uint128_t>(low);
}

// Union-based 128-bit atomic wrapper
union Atomic128Wrapper {
    struct {
        std::atomic<uint64_t> lower;
        std::atomic<uint64_t> upper;
    };

    // Constructor for initializing with two 64-bit parts
    Atomic128Wrapper(uint64_t l = 0, uint64_t u = 0) : lower(l), upper(u) {}

    // Constructor for initializing with full 128-bit value
    Atomic128Wrapper(__uint128_t val) 
        : lower(static_cast<uint64_t>(val)), 
          upper(static_cast<uint64_t>(val >> 64)) {}

    // Conversion operator to 128-bit integer
    explicit operator __uint128_t() const {
        return make_uint128(upper.load(std::memory_order_relaxed),
                           lower.load(std::memory_order_relaxed));
    }

    // Store operation
    void set(__uint128_t value, std::memory_order order = std::memory_order_relaxed) {
        upper.store(static_cast<uint64_t>(value >> 64), order);
        lower.store(static_cast<uint64_t>(value), order);
    }

    // Load operation
    __uint128_t get(std::memory_order order = std::memory_order_relaxed) const {
        return make_uint128(upper.load(order), lower.load(order));
    }

    // Weak compare-and-swap implementation
    bool cas(__uint128_t& expected, __uint128_t desired, 
             std::memory_order success, std::memory_order failure) {
        uint64_t exp_high = static_cast<uint64_t>(expected >> 64);
        uint64_t exp_low  = static_cast<uint64_t>(expected);
        uint64_t des_high = static_cast<uint64_t>(desired >> 64);
        uint64_t des_low  = static_cast<uint64_t>(desired);

        // First update the high part
        if (!upper.compare_exchange_weak(exp_high, des_high, success, failure)) {
            expected = make_uint128(exp_high, exp_low);
            return false;
        }

        // Then update the low part
        if (!lower.compare_exchange_weak(exp_low, des_low, success, failure)) {
            // Restore high part on failure
            upper.store(exp_high, failure);
            expected = make_uint128(exp_high, exp_low);
            return false;
        }

        expected = make_uint128(exp_high, exp_low);
        return true;
    }
};

int main() {
    // Initialize with sample values
    Atomic128Wrapper atom(0x123456789ABCDEF0ULL, 0x0FEDCBA987654321ULL);

    __uint128_t current_val = atom.get();
    __uint128_t new_val = make_uint128(0x0DEADBEEF01234567ULL, 0x89ABCDEF01234567ULL);

    bool result = atom.cas(current_val, new_val, 
                          std::memory_order_seq_cst, 
                          std::memory_order_seq_cst);

    if (result) {
        // CAS succeeded - value was updated
    } else {
        // CAS failed - current_val now holds actual value
    }

    return 0;
}

