// Abstract base class for all expression types
class MathExpr {
public:
    virtual ~MathExpr() {}
    virtual double compute() const = 0;
};

// Represents a constant numeric value
class NumericValue : public MathExpr {
private:
    double data;
public:
    NumericValue(double val) : data(val) {}
    double compute() const override { return data; }
};

// Handles binary mathematical operations between two expressions
class OperationExpression : public MathExpr {
private:
    MathExpr* operand1;
    MathExpr* operand2;
    char operation;
public:
    OperationExpression(MathExpr* op1, char op, MathExpr* op2) 
        : operand1(op1), operation(op), operand2(op2) {}

    ~OperationExpression() {
        delete operand1;
        delete operand2;
    }

    double compute() const override {
        double first = operand1->compute();
        double second = operand2->compute();

        switch (operation) {
            case '+': return first + second;
            case '-': return first - second;
            case '*': return first * second;
            case '/': return first / second;
            default: throw std::runtime_error("Unsupported operator encountered");
        }
    }
};

#include <immintrin.h>

// Compare two strings of given length using SSE intrinsics (Type III clone)
bool compare_strings_sse(const char* s1, const char* s2, size_t length) {
    size_t i = 0;
    // Process 16 bytes at a time using SIMD
    while (i < length) {
        __m128i chunk1 = _mm_loadu_si128(reinterpret_cast<const __m128i*>(s1 + i));
        __m128i chunk2 = _mm_loadu_si128(reinterpret_cast<const __m128i*>(s2 + i));

        // Check for any byte differences
        __m128i cmp_result = _mm_cmpeq_epi8(chunk1, chunk2);
        if (_mm_movemask_epi8(_mm_cmpneq_epi8(chunk1, chunk2)) != 0xFFFF) {
            return false;
        }

        i += 16;
    }
    return true;
}

