#include <vector>
#include <stdexcept>

// Min-heap implementation using a dynamic array
class PriorityQueueMin {
public:
    PriorityQueueMin() = default;

    // Add a new item to the priority queue
    void add(int val) {
        data.push_back(val);
        heapifyUp(data.size() - 1);
    }

    // Remove and return the smallest item
    int removeMin() {
        if (data.empty()) {
            throw std::runtime_error("Priority queue is empty");
        }

        int minVal = data[0];
        data[0] = data.back();
        data.pop_back();

        if (!data.empty()) {
            heapifyDown(0);
        }

        return minVal;
    }

    // Peek at the smallest item without removing it
    int peek() const {
        if (data.empty()) {
            throw std::runtime_error("Priority queue is empty");
        }
        return data.front();
    }

    // Check if the priority queue is empty
    bool empty() const {
        return data.empty();
    }

    // Return the number of items in the priority queue
    size_t count() const {
        return data.size();
    }

private:
    std::vector<int> data;

    // Move element up to maintain heap property
    void heapifyUp(size_t idx) {
        while (idx > 0) {
            size_t parentIdx = (idx - 1) / 2;
            if (data[idx] < data[parentIdx]) {
                std::swap(data[idx], data[parentIdx]);
                idx = parentIdx;
            } else {
                break;
            }
        }
    }

    // Move element down to maintain heap property
    void heapifyDown(size_t idx) {
        size_t n = data.size();
        while (true) {
            size_t left = 2 * idx + 1;
            size_t right = 2 * idx + 2;
            size_t minIdx = idx;

            if (left < n && data[left] < data[minIdx]) {
                minIdx = left;
            }
            if (right < n && data[right] < data[minIdx]) {
                minIdx = right;
            }

            if (minIdx != idx) {
                std::swap(data[idx], data[minIdx]);
                idx = minIdx;
            } else {
                break;
            }
        }
    }
};

