std::vector<int> pairs_difference_to_zero(const std::vector<int>& nums) {
    std::unordered_set<int> observed;
    for (size_t i = 0; i < nums.size(); ++i) {
        int current_value = nums[i];
        if (observed.count(current_value) > 0) {
