// Recursive function to reconstruct and print the LCS
void displaySubsequence(const std::string& seq1, const std::string& seq2, 
                        int len1, int len2, std::vector<std::vector<int>>& dir) {
    if (len1 == 0 || len2 == 0) return;

    if (dir[len1][len2] == 1) {  // Characters match
        displaySubsequence(seq1, seq2, len1 - 1, len2 - 1, dir);
        std::cout << seq1[len1 - 1];
    } else if (dir[len1][len2] == 2) {  // Move up in seq1
        displaySubsequence(seq1, seq2, len1 - 1, len2, dir);
    } else {  // Move left in seq2
        displaySubsequence(seq1, seq2, len1, len2 - 1, dir);
    }
}

std::string computeLCS(const std::string& first, const std::string& second) {
    int m = first.size();
    int n = second.size();

    // DP table for lengths of LCS
    std::vector<std::vector<int>> dp(m + 1, std::vector<int>(n + 1, 0));
    // Direction table: 1=diagonal (match), 2=up, 3=left
    std::vector<std::vector<int>> direction(m + 1, std::vector<int>(n + 1, 0));

    // Fill the DP tables
    for (int i = 1; i <= m; ++i) {
        for (int j = 1; j <= n; ++j) {
            if (first[i - 1] == second[j - 1]) {
                dp[i][j] = dp[i - 1][j - 1] + 1;
                direction[i][j] = 1;
            } else if (dp[i - 1][j] > dp[i][j - 1]) {
                dp[i][j] = dp[i - 1][j];
                direction[i][j] = 2;
            } else {
                dp[i][j] = dp[i][j - 1];
                direction[i][j] = 3;
            }
        }
    }

    std::cout << "The longest common subsequence is: ";
    displaySubsequence(first, second, m, n, direction);
    std::cout << std::endl;

    return first;
}

int main() {
    std::string str1 = "ABCBDAB";
    std::string str2 = "BDCAB";
    computeLCS(str1, str2);
    return 0;
}

#include <iostream>
#include <stdexcept>

template <typename T>
class MyArray {
private:
    T* elements;
    size_t current_size;
    size_t max_capacity;

    // Internal method to expand storage when needed
    void expandStorage(size_t new_capacity) {
        T* fresh_buffer = new T[new_capacity];
        for (size_t idx = 0; idx < current_size; ++idx) {
            fresh_buffer[idx] = elements[idx];
        }
        delete[] elements;
        elements = fresh_buffer;
        max_capacity = new_capacity;
    }

public:
    // Default constructor
    MyArray() : elements(nullptr), current_size(0), max_capacity(0) {}

    // Destructor
    ~MyArray() {
        delete[] elements;
    }

    // Copy constructor
    MyArray(const MyArray& source) : current_size(source.current_size), max_capacity(source.max_capacity) {
        elements = new T[max_capacity];
        for (size_t idx = 0; idx < current_size; ++idx) {
            elements[idx] = source.elements[idx];
        }
    }

    // Copy assignment operator
    MyArray& operator=(const MyArray& source) {
        if (this != &source) {
            delete[] elements;
            current_size = source.current_size;
            max_capacity = source.max_capacity;
            elements = new T[max_capacity];
            for (size_t idx = 0; idx < current_size; ++idx) {
                elements[idx] = source.elements[idx];
            }
        }
        return *this;
    }

    // Move constructor
    MyArray(MyArray&& source) noexcept 
        : elements(source.elements), current_size(source.current_size), max_capacity(source.max_capacity) {
        source.elements = nullptr;
        source.current_size = 0;
        source.max_capacity = 0;
    }

    // Move assignment operator
    MyArray& operator=(MyArray&& source) noexcept {
        if (this != &source) {
            delete[] elements;
            elements = source.elements;
            current_size = source.current_size;
            max_capacity = source.max_capacity;
            source.elements = nullptr;
            source.current_size = 0;
            source.max_capacity = 0;
        }
        return *this;
    }

    // Access operators
    T& operator[](size_t position) {
        return elements[position];
    }

    const T& operator[](size_t position) const {
        return elements[position];
    }

    T& getAt(size_t position) {
        if (position >= current_size) {
            throw std::out_of_range("Position out of bounds");
        }
        return elements[position];
    }

    const T& getAt(size_t position) const {
        if (position >= current_size) {
            throw std::out_of_range("Position out of bounds");
        }
        return elements[position];
    }

    T& firstElement() {
        return elements[0];
    }

    const T& firstElement() const {
        return elements[0];
    }

    T& lastElement() {
        return elements[current_size - 1];
    }

    const T& lastElement() const {
        return elements[current_size - 1];
    }

    // Capacity functions
    size_t length() const {
        return current_size;
    }

    size_t storageSize() const {
        return max_capacity;
    }

    bool isEmpty() const {
        return current_size == 0;
    }

    // Modify array size
    void adjustSize(size_t new_length) {
        if (new_length > max_capacity) {
            expandStorage(new_length);
        }
        current_size = new_length;
    }

    // Add element at the end
    void append(const T& item) {
        if (current_size == max_capacity) {
            if (max_capacity == 0) {
                expandStorage(1);
            } else {
                expandStorage(max_capacity * 2);
            }
        }
        elements[current_size++] = item;
    }

    // Iterator support
    T* start() {
        return elements;
    }

    const T* start() const {
        return elements;
    }

    T* finish() {
        return elements + current_size;
    }

    const T* finish() const {
        return elements + current_size;
    }
};

// Demonstration program
int main() {
