}

#include <emmintrin.h>   // For SSE2 intrinsics (no SSSE3 needed)
#include <cstring>       // For memcpy if needed

// Simulate source data pointer retrieval
unsigned char* GetSourceDataPointer();

int main() {
    unsigned char* srcPtr = GetSourceDataPointer();

    // Aligned buffer for result floats
    alignas(16) float resultVec[4];

    // Load 16 bytes from unaligned source
    __m128i loadData = _mm_loadu_si128(reinterpret_cast<const __m128i*>(srcPtr));

    // Extract only even-indexed bytes: positions 0, 2, 4, 6
    // Use masks and unpacks to avoid _mm_shuffle_epi8 (SSSE3)
    const __m128i maskEven = _mm_set1_epi8(0x0F); // low nibble mask
    __m128i lo = _mm_and_si128(loadData, maskEven);
    __m128i hi = _mm_and_si128(_mm_srli_epi64(loadData, 4), maskEven);
    __m128i evens = _mm_unpacklo_epi8(lo, hi); // interleaves low bytes: [b0,b2,b4,b6,...]

    // Zero-extend 8-bit integers to 32-bit integers (first 4 elements used)
    __m128i int32Data = _mm_cvtepi8_epi32(evens);

    // Convert to single-precision floats
    __m128 floatData = _mm_cvtepi32_ps(int32Data);

    // Store into aligned float array
    _mm_store_ps(resultVec, floatData);

    // Perform some SIMD floating-point ops (e.g., scale and add)
    __m128 scale = _mm_set1_ps(2.5f);
    __m128 bias  = _mm_set1_ps(1.0f);
    __m128 processed = _mm_add_ps(_mm_mul_ps(floatData, scale), bias);

    // Optional: store or use result
    _mm_store_ps(resultVec, processed);

    return 0;
}

#include <altivec.h>
#undef vector

typedef __vector unsigned char uint8x16_p;

// Load 8 bytes into a vector register using alternative addressing approach
uint8x16_p VectorFastLoad8(const void* p)
{
    long offset = 0;
    uint8x16_p res;

    // Use inline assembly with adjusted constraint and operand ordering
    __asm__ volatile (
        "lxvd2x %x0, %1, %2"
        : "=wa" (res)
        : "r" (p), "r" (offset >> 2), "m" (*(const char (*)[16])p)
    );

    return res;
}

