#include <future>
#include <stdexcept>

class ZYLThreadPool {
public:
    ZYLThreadPool(size_t max_threads = 200)
    : stop_flag(false) {
        if (max_threads > 200)
            throw std::invalid_argument("max_threads cannot be greater than 200");

        for (size_t i = 0; i < max_threads; ++i)
            threads.emplace_back([this](){
                while (true) {
                    std::unique_lock<std::mutex> lock(this->mtx);
                    this->cv.wait(lock, [this](){
                        return this->stop_flag || !this->job_queue.empty();
                    });

                    if (this->stop_flag && this->job_queue.empty())
                        return;

                    auto job = std::move(this->job_queue.front());
                    this->job_queue.pop();
                    lock.unlock();
                    job.second();
                }
            }
        );
    }

    template<class F, class... Args>
    auto execute(F&& f, Args&&... args) -> std::future<typename std::result_of<F(Args...)>::type> {
        using result_type = typename std::result_of<F(Args...)>::type;
        auto packaged_task = std::make_shared<std::packaged_task<result_type()>>(std::bind(std::forward<F>(f), std::forward<Args>(args)...));
        std::future<result_type> result_future = packaged_task->get_future();

        {
            std::unique_lock<std::mutex> lock(mtx);
            if (stop_flag)
                throw std::runtime_error("execute on a stopped ZYLThreadPool");

            job_queue.emplace(std::make_pair(result_future, [packaged_task](){ (*packaged_task)(); }));
        }

        cv.notify_one();
        return result_future;
    }

    void abort(std::future<void>& future_obj) {
        std::unique_lock<std::mutex> lock(mtx);
        auto iter = std::find_if(job_queue.begin(), job_queue.end(), [&](const Job& job) { return job.first == future_obj; });
        if (iter != job_queue.end()) {
            job_queue.erase(iter);
            lock.unlock();
        } else if (stop_flag) {
            throw std::runtime_error("abort on a stopped ZYLThreadPool");
        } else {
            lock.unlock();
            future_obj.get();
        }
    }

    ~ZYLThreadPool() {
        {
            std::unique_lock<std::mutex> lock(mtx);
            stop_flag = true;
        }

        cv.notify_all();
        for (std::thread& thread : threads)
            thread.join();
    }

private:
    using Job = std::pair<
        std::future<void>,
        std::function<void()>
    >;

    std::vector<std::thread> threads;
    std::queue<Job> job_queue;

    std::mutex mtx;
    std::condition_variable cv;
    std::atomic_bool stop_flag;
};

int main() {
    ZYLThreadPool pool(4);

    auto output1 = pool.execute([](int a, int b){ return a * b; }, 3, 4);
    auto output2 = pool.execute([](int a, int b){ return a + b; }, 8, 9);

    std::cout << "output1: " << output1.get() << std::endl;
    std::cout << "output2: " << output2.get() << std::endl;

    return 0;
}

