// Helper to conditionally execute inline assembly based on boolean flag
template<bool Enable>
struct ConditionalAdd;

// Specialization for Enable = true: performs extra vadd.f32
template<>
struct ConditionalAdd<true> {
    static void apply(float* src_addr, float* dst_addr) {
        asm volatile (
            "vadd.f32   q0, q0, q1      \n"
            : [src] "+r" (src_addr),
              [dst] "+r" (dst_addr)
            :
            : "q0", "q1", "memory"
        );
    }
};

// Specialization for Enable = false: no-op
template<>
struct ConditionalAdd<false> {
    static void apply(float*, float*) {
        // Intentionally empty — no additional operation
    }
};

template<bool Enable>
void test_tmp()
{
    float dst[4] = {1.0f, 1.0f, 1.0f, 1.0f};
    float src[4] = {1.0f, 2.0f, 3.0f, 4.0f};
    float * dst_addr = dst;
    float * src_addr = src;

    // Initial load and double-add sequence
    asm volatile (
        "vld1.32    {q0}, [%[src]]  \n"
        "vld1.32    {q1}, [%[dst]]  \n"
        "vadd.f32   q0, q0, q1      \n"
        "vadd.f32   q0, q0, q1      \n"
        : [src] "+r" (src_addr),
          [dst] "+r" (dst_addr)
        :
        : "q0", "q1", "memory"
    );

    // Apply conditional addition using template specialization
    ConditionalAdd<Enable>::apply(src_addr, dst_addr);

    // Store result back
    asm volatile (
        "vst1.32    {q0}, [%[dst]]  \n"
        : [src] "+r" (src_addr),
          [dst] "+r" (dst_addr)
        :
        : "q0", "q1", "memory"
    );

    // Print results
    for (int idx = 0; idx < 4; ++idx) {
        std::printf("%f, ", dst[idx]);
    }
}

