{
    test_tmp<true>();
    std::cout << std::endl;
    test_tmp<false>();
    return 0;
}

#include <opencv2/opencv.hpp>
#include <iostream>

int main() {
    // Read the grayscale input image
    cv::Mat sourceImage = cv::imread("input.png", cv::IMREAD_GRAYSCALE);

    if (sourceImage.empty()) {
        std::cerr << "Error: Could not load input image." << std::endl;
        return -1;
    }

    // Define source and destination points for affine transformation
    cv::Point2f srcPoints[3];
    cv::Point2f dstPoints[3];

    // Source triangle vertices: top-left, top-right, bottom-left
    srcPoints[0] = cv::Point2f(0.0f, 0.0f);
    srcPoints[1] = cv::Point2f(static_cast<float>(sourceImage.cols - 1), 0.0f);
    srcPoints[2] = cv::Point2f(0.0f, static_cast<float>(sourceImage.rows - 1));

    // Destination triangle vertices: scaled coordinates (2x size)
    dstPoints[0] = cv::Point2f(0.0f, 0.0f);
    dstPoints[1] = cv::Point2f(static_cast<float>((sourceImage.cols * 2) - 1), 0.0f);
    dstPoints[2] = cv::Point2f(0.0f, static_cast<float>((sourceImage.rows * 2) - 1));

    // Compute the affine transformation matrix
    cv::Mat transformMatrix = cv::getAffineTransform(srcPoints, dstPoints);

    // Prepare output image with doubled dimensions
    cv::Mat resultImage;
    cv::Size newSize(sourceImage.cols * 2, sourceImage.rows * 2);

    // Apply affine warp using cubic interpolation
    cv::warpAffine(sourceImage, resultImage, transformMatrix, newSize, cv::INTER_CUBIC);

    // Write the transformed image to file
    cv::imwrite("output.png", resultImage);

    return 0;
}

