// Compute the Levenshtein edit distance between two strings
int levenshteinDistance(const std::string &source, const std::string &target) {
    int lenSrc = source.length();
    int lenTar = target.length();

    // Create a 2D matrix to store distances
    std::vector<std::vector<int>> dp(lenSrc + 1, std::vector<int>(lenTar + 1, 0));

    // Initialize base cases: transforming empty string to target/prefixes
    for (int i = 0; i <= lenSrc; ++i) {
        dp[i][0] = i;
    }
    for (int j = 0; j <= lenTar; ++j) {
        dp[0][j] = j;
    }

    // Fill the DP table
    for (int i = 1; i <= lenSrc; ++i) {
        for (int j = 1; j <= lenTar; ++j) {
            int matchCost = (source[i - 1] == target[j - 1]) ? 0 : 1;

            // Minimum of deletion, insertion, or substitution
            int del = dp[i - 1][j] + 1;
            int ins = dp[i][j - 1] + 1;
            int sub = dp[i - 1][j - 1] + matchCost;

            dp[i][j] = std::min({del, ins, sub});
        }
    }

    return dp[lenSrc][lenTar];
}

