#include <Wire.h>
#include <esp_now.h>
#include <WiFi.h>

#define I2C_SLAVE_ADDR 0x3C
#define MAX_BUFFER_LEN 512
#define ESP_NOW_CHANNEL_NUM 0

struct __attribute__((packed)) FramePacket {
  uint8_t frame[MAX_BUFFER_LEN];
  size_t length;
};

QueueHandle_t dataQueue;

void handleIncomingData(const uint8_t* srcAddr, const uint8_t* payload, int len) {
  FramePacket packet;
  memcpy(&packet, payload, sizeof(packet));
  xQueueSendFromISR(dataQueue, &packet, nullptr);
}

void setup() {
  Serial.begin(115200);

  // Configure I2C interface for RP2040 connection
  Wire.begin();

  // Setup ESP-NOW protocol
  if (esp_now_init() != ESP_OK) {
    Serial.println("ESP-NOW init error");
    return;
  }

  // Attach receive handler
  esp_now_register_recv_cb(handleIncomingData);

  // Create message queue for screen data
  dataQueue = xQueueCreate(1, sizeof(FramePacket));

  // Add remote peer device
  esp_now_peer_info_t peerInfo{};
  uint8_t peerMac[6] = {0xCA, 0xFE, 0xBA, 0xBE, 0xFA, 0xCE}; // Target ESP32 MAC
  memcpy(peerInfo.peer_addr, peerMac, 6);
  peerInfo.channel = ESP_NOW_CHANNEL_NUM;
  peerInfo.encrypt = false;

  if (esp_now_add_peer(&peerInfo) != ESP_OK) {
    Serial.println("Peer registration failed");
    return;
  }

  Serial.println("Initialization finished");
}

void loop() {
  FramePacket frameData{};

  // Acquire screen content via I2C from RP2040
  Wire.beginTransmission(I2C_SLAVE_ADDR);
  Wire.write(0x00); // Starting register address
  Wire.endTransmission(false);

  size_t bytesRead = Wire.requestFrom(I2C_SLAVE_ADDR, MAX_BUFFER_LEN);
  frameData.length = bytesRead;
  Wire.readBytes(frameData.frame, std::min(bytesRead, (size_t)MAX_BUFFER_LEN));

  // Queue the frame for transmission
  if (xQueueSend(dataQueue, &frameData, portMAX_DELAY) != pdPASS) {
    Serial.println("Buffer queueing failure");
  }

  vTaskDelay(pdMS_TO_TICKS(1000)); // Wait one second before next update
}

#include <iostream>

typedef struct {
    float re;
    float im;
} dcmplx;

dcmplx ComplexConv(int len, dcmplx *hat, dcmplx *buf)
{
    dcmplx result = {0.0f, 0.0f};

    for (int i = 0; i < len; ++i) {
        // Load current complex values from hat and buf arrays
        dcmplx h_val = hat[i];
        dcmplx b_val = buf[i];

        // Perform complex multiplication: (h.re + h.im*i) * (b.re + b.im*i)
        // But with a sign change on h.im (as seen in the assembly: vneg.f32 s11)
        float h_re = h_val.re;
        float h_im_negated = -h_val.im;  // This matches "vneg.f32 s11, s11"

        // Compute real part: h_im_negated * b_im + h_re * b_re
        // (equivalent to vmul.f32 + vmla.f32 for real part)
        float real_part = h_im_negated * b_val.im + h_re * b_val.re;

        // Compute imaginary part: h_im_negated * b_re - h_re * b_im  
        // (equivalent to vmul.f32 + vnmls.f32 for imag part)
        float imag_part = h_im_negated * b_val.re - h_re * b_val.im;

        // Accumulate results
        result.re += real_part;
        result.im += imag_part;
    }

    return result;
}

