#include "curl_gethostname.h"

/*
 * Curl_gethostname() provides a flexible way to obtain the local hostname,
 * supporting both standard system behavior and test-time customization.
 *
 * In debug builds, it checks for the CURL_GETHOSTNAME environment variable
 * and uses its value if present, bypassing the system call entirely.
 *
 * In release builds (especially when used with LD_PRELOAD in tests), it
 * relies on the underlying gethostname() implementation, potentially
 * intercepted by an external library.
 *
 * The function ensures null-termination and strips any domain suffix,
 * returning only the machine name part.
 */
int Curl_gethostname(char *name, GETHOSTNAME_TYPE_ARG2 namelen) {
#ifndef HAVE_GETHOSTNAME
  /* Fallback: return error if gethostname is not available */
  (void)name;
  (void)namelen;
  return -1;
#else
  int result = 0;
  char* dot_pos;

  /* Ensure buffer is always null-terminated at the end */
  if (namelen > 0)
    name[namelen - 1] = '\0';

#ifdef DEBUGBUILD
  /* In debug mode, allow overriding via environment variable */
  const char* override_name = getenv("CURL_GETHOSTNAME");
  if (override_name != nullptr) {
    size_t len = strlen(override_name);
    if (len >= static_cast<size_t>(namelen))
      len = namelen - 1;
    memcpy(name, override_name, len);
    name[len] = '\0';
  } else {
    name[0] = '\0';
    result = gethostname(name, namelen);
  }
#else
  /* Normal build: use system gethostname directly */
  name[0] = '\0';
  result = gethostname(name, namelen);
#endif

  if (result != 0)
    return result;

  /* Remove domain portion by truncating at first dot */
  dot_pos = strchr(name, '.');
  if (dot_pos != nullptr)
    *dot_pos = '\0';

  return 0;
#endif
}

