namespace autolink {
namespace transport {

TEST(DispatcherTest, on_message) {
  auto dispatcher = IntraDispatcher::Instance();

  std::vector<std::shared_ptr<proto::Chatter>> chatter_records;
  std::vector<std::shared_ptr<message::RawMessage>> raw_records;

  // Prepare test messages
  auto msg1 = std::make_shared<proto::Chatter>();
  msg1->set_content("chatter");

  proto::Chatter temp_chatter;
  temp_chatter.set_content("raw message");
  std::string serialized_data;
  temp_chatter.SerializeToString(&serialized_data);
  auto raw_msg = std::make_shared<message::RawMessage>(serialized_data);

  // Define callbacks
  auto chatter_handler = [&chatter_records](const std::shared_ptr<proto::Chatter>& msg, const MessageInfo&) {
    AINFO << "chatter handler invoked";
    chatter_records.push_back(msg);
  };

  auto raw_handler = [&raw_records](const std::shared_ptr<message::RawMessage>& msg, const MessageInfo&) {
    AINFO << "raw handler invoked";
    raw_records.push_back(msg);
  };

  MessageInfo info;

  // Setup role attributes
  const std::string topic_name = "channel";
  const uint64_t topic_hash = common::Hash(topic_name);

  proto::RoleAttributes local_role_a;
  local_role_a.set_channel_name(topic_name);
  local_role_a.set_channel_id(topic_hash);
  local_role_a.set_id(Identity().HashValue());

  proto::RoleAttributes local_role_b = local_role_a;
  local_role_b.set_id(Identity().HashValue());

  proto::RoleAttributes mismatched_role;
  mismatched_role.set_channel_name("channel1");
  mismatched_role.set_channel_id(common::Hash("channel1"));

  Identity id_a;
  proto::RoleAttributes remote_role_a = local_role_a;
  remote_role_a.set_id(id_a.HashValue());

  Identity id_b;
  proto::RoleAttributes remote_role_b = local_role_a;
  remote_role_b.set_id(id_b.HashValue());

  // Register listeners
  dispatcher->AddListener<proto::Chatter>(local_role_a, chatter_handler);
  dispatcher->AddListener<message::RawMessage>(local_role_b, raw_handler);
  dispatcher->AddListener<proto::Chatter>(local_role_a, remote_role_a, chatter_handler);
  dispatcher->AddListener<message::RawMessage>(local_role_b, remote_role_a, raw_handler);

  // First dispatch: only self handlers (2 total)
  dispatcher->OnMessage<proto::Chatter>(topic_hash, msg1, info);
  EXPECT_EQ(1u, chatter_records.size());
  EXPECT_EQ(1u, raw_records.size());

  // Second dispatch: with sender set → triggers both self & opposite handlers
  info.set_sender_id(id_a);
  dispatcher->OnMessage<message::RawMessage>(topic_hash, raw_msg, info);
  EXPECT_EQ(3u, chatter_records.size());
  EXPECT_EQ(3u, raw_records.size());

  // Third dispatch: new sender, no opposite handlers exist for this type
  Identity id_c;
  info.set_sender_id(id_c);
  dispatcher->OnMessage<proto::Chatter>(topic_hash, msg1, info);
  EXPECT_EQ(4u, chatter_records.size());
  EXPECT_EQ(4u, raw_records.size());

  // Cleanup: remove listeners
  dispatcher->RemoveListener<proto::Chatter>(mismatched_role);  // no match
  dispatcher->RemoveListener<proto::Chatter>(mismatched_role, remote_role_b);  // no match

  dispatcher->RemoveListener<proto::Chatter>(local_role_a);
  dispatcher->RemoveListener<proto::Chatter>(local_role_b);
  dispatcher->RemoveListener<proto::Chatter>(local_role_a, remote_role_a);
  dispatcher->RemoveListener<proto::Chatter>(local_role_b, remote_role_b);

  // Verify removal: no handlers left
  chatter_records.clear();
  raw_records.clear();

  MessageInfo info2;
  dispatcher->OnMessage<proto::Chatter>(topic_hash, msg1, info2);
  EXPECT_EQ(0u, chatter_records.size());
  EXPECT_EQ(0u, raw_records.size());

  info.set_sender_id(id_a);
  dispatcher->OnMessage<proto::Chatter>(topic_hash, msg1, info);
  EXPECT_EQ(0u, chatter_records.size());
  EXPECT_EQ(0u, raw_records.size());
}

