// Yield the current thread's time slice to another thread
void SchedYield() noexcept {
#if defined(_unix_) || defined(__linux__) || defined(__APPLE__)
    sched_yield();
#else
    Sleep(0);
#endif
}

// Platform-independent thread yield function
void ThreadYield() noexcept {
#if defined(_freebsd_) || defined(__FreeBSD__)
    pthread_yield();
#elif defined(_unix_) || defined(__linux__) || defined(__APPLE__)
    sched_yield();
#else
    SchedYield();
#endif
}

#include <iostream>
#include <vector>
#include <algorithm>
#include <functional>
using namespace std;

int n;
vector<int> p;

// Custom binary search: returns first index where min_tails[idx] >= target
int find_insert_pos(const vector<int>& min_tails, int target) {
    int left = 0, right = min_tails.size();
    while (left < right) {
        int mid = left + (right - left) / 2;
        if (min_tails[mid] < target)
            left = mid + 1;
        else
            right = mid;
    }
    return left;
}

// Returns indices of subsequence (increasing or decreasing)
vector<int> extract_subseq_indices(const vector<bool>& used, bool is_decreasing) {
    vector<int> min_tails;       // smallest tail value for each length
    vector<int> min_tail_indices; // corresponding index in p
    vector<int> prev_idx(n, -1);  // predecessor index for reconstruction

    for (int i = 0; i < n; ++i) {
        if (used[i]) continue;

        int val = p[i];
        if (is_decreasing) val = -val;

        int pos = find_insert_pos(min_tails, val);

        if (pos == (int)min_tails.size()) {
            min_tails.push_back(val);
            min_tail_indices.push_back(i);
        } else {
            min_tails[pos] = val;
            min_tail_indices[pos] = i;
        }

        if (pos > 0) {
            prev_idx[i] = min_tail_indices[pos - 1];
        }
    }

    // Reconstruct path backwards then reverse
    vector<int> result;
    if (min_tail_indices.empty()) return result;

    int curr = min_tail_indices.back();
    while (curr != -1) {
        result.push_back(curr);
        curr = prev_idx[curr];
    }
    reverse(result.begin(), result.end());
    return result;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    if (!(cin >> n)) return 0;
    p.resize(n);
    for (int i = 0; i < n; ++i) cin >> p[i];

    // Try all distinct orderings of [Inc, Inc, Dec, Dec]
    vector<int> types = {0, 0, 1, 1};
    sort(types.begin(), types.end());

    long long max_total_len = -1;
    vector<int> best_assignment(n, 3); // default assignment: 'd' (index 3)

    do {
        vector<bool> used(n, false);
        vector<int> owner(n, -1);
        long long current_len = 0;

        int inc_used = 0, dec_used = 0;

        for (int t : types) {
            int assign_to;
            if (t == 0) {
                assign_to = (inc_used == 0) ? 0 : 2; // 0→a, 2→c
                inc_used++;
            } else {
                assign_to = (dec_used == 0) ? 1 : 3; // 1→b, 3→d
                dec_used++;
            }

            vector<int> idxs = extract_subseq_indices(used, (t == 1));
            current_len += idxs.size();

            for (int idx : idxs) {
                used[idx] = true;
                owner[idx] = assign_to;
            }
        }

        if (current_len > max_total_len) {
            max_total_len = current_len;
            for (int i = 0; i < n; ++i) {
                best_assignment[i] = (owner[i] == -1) ? 3 : owner[i];
            }
        }
    } while (next_permutation(types.begin(), types.end()));

    // Build final output vectors
    vector<int> a, b, c, d;
    a.reserve(n); b.reserve(n); c.reserve(n); d.reserve(n);

    for (int i = 0; i < n; ++i) {
        switch (best_assignment[i]) {
            case 0: a.push_back(p[i]); break;
            case 1: b.push_back(p[i]); break;
            case 2: c.push_back(p[i]); break;
            default: d.push_back(p[i]); break;
        }
    }

    // Output lengths
    cout << a.size() << " " << b.size() << " " << c.size() << " " << d.size() << "\n";

    // Helper lambda to print vector elements space-separated
    auto print_sequence = [](const vector<int>& seq) {
        for (size_t i = 0; i < seq.size(); ++i) {
            if (i > 0) cout << " ";
            cout << seq[i];
        }
        cout << "\n";
    };

    print_sequence(a);
    print_sequence(b);
    print_sequence(c);
    print_sequence(d);

    return 0;
}

