const FName IStageDataProviderModule::ModuleName = TEXT("StageDataProvider");
DEFINE_LOG_CATEGORY(LogStageDataProvider);

FStageDataProviderModule::FStageDataProviderModule()
	: DataProvider(MakeUnique<FStageDataProvider>())
	, FramePerformanceProvider(MakeUnique<FFramePerformanceProvider>())
	, GenlockWatchdog(MakeUnique<FGenlockWatchdog>())
	, TimecodeWatchdog(MakeUnique<FTimecodeProviderWatchdog>())
#if WITH_EDITOR
	, TakeRecorderStateProvider(MakeUnique<FTakeRecorderStateProvider>())
#endif // WITH_EDITOR
{
}

void FStageDataProviderModule::StartupModule()
{
	// Delay initialization until after engine is fully initialized
	FCoreDelegates::OnPostEngineInit.AddRaw(this, &FStageDataProviderModule::InitializeAfterEngineStart);

	// Ensure cleanup before shutdown
	FCoreDelegates::OnPreExit.AddRaw(this, &FStageDataProviderModule::CleanupBeforeExit);

#if !(UE_BUILD_SHIPPING || UE_BUILD_TEST)
	// Register debug console commands only in non-shipping builds
	ConsoleCommandStart = MakeUnique<FAutoConsoleCommand>(
		TEXT("StageMonitor.DataProvider.Start"),
		TEXT("Start Stage data provider"),
		FConsoleCommandDelegate::CreateRaw(this, &FStageDataProviderModule::BeginRecording));

	ConsoleCommandStop = MakeUnique<FAutoConsoleCommand>(
		TEXT("StageMonitor.DataProvider.Stop"),
		TEXT("Stop Stage data provider"),
		FConsoleCommandDelegate::CreateRaw(this, &FStageDataProviderModule::EndRecording));
#endif
}

void FStageDataProviderModule::ShutdownModule()
{
	// Clean up delegates
	FCoreDelegates::OnPostEngineInit.RemoveAll(this);
	FCoreDelegates::OnPreExit.RemoveAll(this);

	// Ensure provider is stopped cleanly
	EndRecording();
}

void FStageDataProviderModule::InitializeAfterEngineStart()
{
	const UStageMonitoringSettings* Config = GetDefault<UStageMonitoringSettings>();
	const UVPSettings* VPConfig = GetDefault<UVPSettings>();

	// Determine if we can start based on role filtering rules
	const bool bCanStartWithoutFiltering = !Config->ProviderSettings.bUseRoleFiltering;
	const bool bHasMatchingRole = VPConfig->GetRoles().HasAny(Config->ProviderSettings.SupportedRoles);

	if (bCanStartWithoutFiltering || bHasMatchingRole)
	{
		BeginRecording();
	}
	else
	{
		UE_LOG(LogStageDataProvider, Log,
			TEXT("Cannot initialize StageDataProvider. Role filtering is active, and our roles (%s) are not among the accepted ones (%s).")
			, *VPConfig->GetRoles().ToStringSimple()
			, *Config->ProviderSettings.SupportedRoles.ToStringSimple());
	}
}

void FStageDataProviderModule::CleanupBeforeExit()
{
	EndRecording();
}

void FStageDataProviderModule::BeginRecording()
{
	DataProvider->Start();
	// Register globally accessible modular feature
	IModularFeatures::Get().RegisterModularFeature(IStageDataProvider::ModularFeatureName, DataProvider.Get());
}

void FStageDataProviderModule::EndRecording()
{
	// Unregister before stopping to avoid race conditions
	IModularFeatures::Get().UnregisterModularFeature(IStageDataProvider::ModularFeatureName, DataProvider.Get());
	DataProvider->Stop();
}

