#include <iostream>
#include <nlohmann/json.hpp>
using json = nlohmann::json;

int main() {
    // Prepare a byte vector representing a tagged CBOR byte string
    std::vector<std::uint8_t> data_bytes = {0xd8, 0x42, 0x44, 0xcA, 0xfe, 0xba, 0xbe};

    // Attempt to parse with tag error handling enabled (throws on encountering tags)
    try {
        auto parsed_with_error = json::from_cbor(data_bytes, true, true, json::cbor_tag_handler_t::error);
    }
    catch (const json::parse_error& ex) {
        std::cout << ex.what() << std::endl;
    }

    // Parse while ignoring any CBOR tags present
    auto parsed_ignored = json::from_cbor(data_bytes, true, true, json::cbor_tag_handler_t::ignore);
    std::cout << parsed_ignored << std::endl;

    // Parse and store the tag as a binary subtype in the resulting JSON value
    auto parsed_stored = json::from_cbor(data_bytes, true, true, json::cbor_tag_handler_t::store);
    std::cout << parsed_stored << std::endl;

    return 0;
}

