// Helper structure to format a key as a human-readable string
typedef struct {
    char buffer[36]; // Format: 8x2 hex + 3 colons + null terminator
} KeyString;

// Convert a topic key into a formatted string like "aabbccdd:11223344:..."
static char* format_key(KeyString *ks, const dds_builtintopic_topic_key_t *key) {
    (void) snprintf(ks->buffer, sizeof(ks->buffer),
                    "%02x%02x%02x%02x:%02x%02x%02x%02x:"
                    "%02x%02x%02x%02x:%02x%02x%02x%02x",
                    key->d[0], key->d[1], key->d[2], key->d[3],
                    key->d[4], key->d[5], key->d[6], key->d[7],
                    key->d[8], key->d[9], key->d[10], key->d[11],
                    key->d[12], key->d[13], key->d[14], key->d[15]);
    return ks->buffer;
}

// Return a descriptive string for an instance state
static const char* describe_instance_state(dds_instance_state_t state) {
    switch (state) {
        case DDS_ALIVE_INSTANCE_STATE:           return "alive";
        case DDS_NOT_ALIVE_NO_WRITERS_INSTANCE_STATE: return "nowriters";
        case DDS_NOT_ALIVE_DISPOSED_INSTANCE_STATE:   return "disposed";
    }
    assert(0 && "Unexpected instance state");
    return "";
}

// Process DCPSTopic samples; returns true if any non-builtin topic was seen
static bool inspect_topics(dds_entity_t cond) {
#define MAX_SAMPLES 10
    void* sample_ptrs[MAX_SAMPLES] = { NULL };
    dds_sample_info_t infos[MAX_SAMPLES];

    int32_t count = dds_take(cond, sample_ptrs, infos, MAX_SAMPLES, MAX_SAMPLES);
    bool found_app_topic = false;

    for (int32_t idx = 0; idx < count; ++idx) {
        const dds_builtintopic_topic_t* topic = (const dds_builtintopic_topic_t*)sample_ptrs[idx];
        KeyString ks;
        printf("%s: %s", describe_instance_state(infos[idx].instance_state), format_key(&ks, &topic->key));

        if (infos[idx].valid_data) {
            printf(" %s %s", topic->topic_name, topic->type_name);
            if (strncmp(topic->topic_name, "DCPS", 4) != 0) {
                found_app_topic = true;
            }
        }
        putchar('\n');
    }

    (void) dds_return_loan(cond, sample_ptrs, count);
#undef MAX_SAMPLES
    return found_app_topic;
}

// Check if any non-built-in endpoints exist across publication/subscription topics
static bool check_endpoints_exist(const dds_entity_t read_conds[]) {
    bool ep_found = false;

    for (size_t i = 0; i < sizeof(monitored_builtin_endpoints)/sizeof(monitored_builtin_endpoints[0]) && !ep_found; ++i) {
        void* ptr = NULL;
        dds_sample_info_t info;
        int32_t taken = dds_take(read_conds[i], &ptr, &info, 1, 1);

        if (taken > 0 && info.valid_data) {
            const dds_builtintopic_endpoint_t* ep = (const dds_builtintopic_endpoint_t*)ptr;
            if (strncmp(ep->topic_name, "DCPS", 4) != 0) {
                ep_found = true;
            }
        }
        (void) dds_return_loan(read_conds[i], &ptr, taken);
    }

    return ep_found;
}

int main(int argc, char** argv) {
    (void)argc;
    (void)argv;

    // Create participant
    dds_entity_t part = dds_create_participant(DDS_DOMAIN_DEFAULT, NULL, NULL);
    if (part < 0) {
        fprintf(stderr, "dds_create_participant failed: %s\n", dds_strretcode(part));
        return 1;
    }

    // Set up waitset
    dds_entity_t wset = dds_create_waitset(part);
    if (wset < 0) {
        fprintf(stderr, "dds_create_waitset failed: %s\n", dds_strretcode(wset));
        dds_delete(part);
        return 1;
    }

    // Reader for DCPSTopic
    dds_entity_t topic_reader = dds_create_reader(part, DDS_BUILTIN_TOPIC_DCPSTOPIC, NULL, NULL);
    if (topic_reader < 0) {
        if (topic_reader == DDS_RETCODE_UNSUPPORTED) {
            fprintf(stderr, "Topic discovery not compiled in. Rebuild with ENABLE_TOPIC_DISCOVERY=ON\n");
        } else {
            fprintf(stderr, "Failed to create DCPSTopic reader: %s\n", dds_strretcode(topic_reader));
        }
        dds_delete(part);
        return 1;
    }

    // Attach read condition for topic changes
    dds_entity_t topic_cond = dds_create_readcondition(topic_reader, DDS_ANY_STATE);
    if (topic_cond < 0) {
        fprintf(stderr, "Failed to create topic read condition: %s\n", dds_strretcode(topic_cond));
        dds_delete(part);
        return 1;
    }
    (void) dds_waitset_attach(wset, topic_cond, 0);

    // Readers and conditions for DCPSPublication/Subscription
    dds_entity_t ep_readers[sizeof(monitored_builtin_endpoints)/sizeof(monitored_builtin_endpoints[0])];
    dds_entity_t ep_conditions[sizeof(monitored_builtin_endpoints)/sizeof(monitored_builtin_endpoints[0])];

    for (size_t i = 0; i < sizeof(monitored_builtin_endpoints)/sizeof(monitored_builtin_endpoints[0]); ++i) {
        ep_readers[i] = dds_create_reader(part, monitored_builtin_endpoints[i], NULL, NULL);
        if (ep_readers[i] < 0) {
            fprintf(stderr, "Failed to create endpoint reader %zu: %s\n", i, dds_strretcode(ep_readers[i]));
            dds_delete(part);
            return 1;
        }
        ep_conditions[i] = dds_create_readcondition(ep_readers[i], DDS_ANY_STATE);
        if (ep_conditions[i] < 0) {
            fprintf(stderr, "Failed to create endpoint read condition %zu: %s\n", i, dds_strretcode(ep_conditions[i]));
            dds_delete(part);
            return 1;
        }
        (void) dds_waitset_attach(wset, ep_conditions[i], 0);
    }

    // Monitoring flags
    bool app_topic_discovered = false;
    bool app_endpoint_discovered = false;

    // Run monitoring for up to 10 seconds
    const dds_time_t deadline = dds_time() + DDS_SECS(10);

    while (dds_waitset_wait_until(wset, NULL, 0, deadline) > 0) {
        if (inspect_topics(topic_cond)) {
            app_topic_discovered = true;
        }

        if (!app_endpoint_discovered && check_endpoints_exist(ep_conditions)) {
            app_endpoint_discovered = true;

            // Clean up endpoint readers once we know they exist
            for (size_t i = 0; i < sizeof(ep_readers)/sizeof(ep_readers[0]); ++i) {
                (void) dds_delete(ep_readers[i]);
            }
        }
    }

    // Final warning if only endpoints were found (likely topic discovery disabled)
    if (!app_topic_discovered && app_endpoint_discovered) {
        fprintf(stderr, "Warning: No topics discovered, but remote endpoints detected.\n"
                        "       Is topic discovery enabled in your configuration?\n");
    }

    dds_delete(part);
    return 0;
}

