std::string
demangle_cpp_symbol(std::string_view mangled, int* result_code)
{
    constexpr size_t max_buf_size = 4096;
    if (mangled.empty()) {
        *result_code = -2;
        return {};
    }

    std::string input{mangled};
    size_t out_len = 0;
    char* demangled_ptr = abi::__cxa_demangle(input.c_str(), nullptr, &out_len, result_code);

    switch (*result_code) {
        case 0:
            if (demangled_ptr) input = std::string{demangled_ptr};
            break;
        case -1: {
            char msg[max_buf_size]{};
            ::snprintf(msg, max_buf_size, "Memory allocation failed while demangling %s", input.c_str());
            ::perror(msg);
            break;
        }
        case -2:
        case -3: {
            char msg[max_buf_size]{};
            ::snprintf(msg, max_buf_size,
                       "Invalid argument in demangle call for '%s', status=%d",
                       input.c_str(), *result_code);
            ::perror(msg);
            break;
        }
        default:
            break;
    }

    if (out_len == 0 && *result_code == 0) *result_code = -2;
    ::free(demangled_ptr);
    return input;
}

void
dump_traces_to_file(const call_trace_list& traces)
{
    std::string output_path = "code_object_trace.log";
    if (const char* env = std::getenv("ROCPROFILER_SAMPLE_OUTPUT_FILE"))
        output_path = env;

    std::ostream* out_stream = nullptr;
    std::function<void(std::ostream*&)> cleanup_fn = {};

    if (output_path == "stdout") {
        out_stream = &std::cout;
    } else if (output_path == "stderr") {
        out_stream = &std::cerr;
    } else {
        auto* file = new std::ofstream{output_path};
        if (file && *file) {
            out_stream = file;
            cleanup_fn = [](std::ostream*& os) { delete static_cast<std::ofstream*>(os); };
        } else {
            std::cerr << "Failed to open '" << output_path << "', falling back to stderr.\n";
            output_path = "stderr";
            out_stream = &std::cerr;
            delete file;
        }
    }

    std::cout << "Writing trace data to: " << output_path << "\n" << std::flush;

    size_t idx = 1;
    for (const auto& entry : traces) {
        *out_stream << std::left << std::setw(2) << idx++ << "/" << std::setw(2) << traces.size()
                    << " [" << common::fs::path{entry.src_file}.filename() << ":" << entry.line_no << "] "
                    << std::setw(20) << entry.func_name;
        if (!entry.details.empty())
            *out_stream << " :: " << entry.details;
        *out_stream << "\n";
    }

    out_stream->flush();
    if (cleanup_fn) cleanup_fn(out_stream);
}

template <typename T>
std::string
to_hex_string(T value, size_t width = 16)
{
    std::ostringstream oss;
    oss << "0x" << std::hex << std::setfill('0') << std::setw(width) << value;
    return oss.str();
}

void
on_tracing_event(rocprofiler_callback_tracing_record_t rec,
                 rocprofiler_user_data_t* /*user*/,
                 void* user_payload)
{
    if (rec.kind == ROCPROFILER_CALLBACK_TRACING_CODE_OBJECT &&
        rec.operation == ROCPROFILER_CODE_OBJECT_LOAD) {
        auto* obj_data = static_cast<rocprofiler_callback_tracing_code_object_load_data_t*>(rec.payload);
        auto* trace_vec = static_cast<call_trace_list*>(user_payload);
        std::ostringstream info;

        if (rec.phase == ROCPROFILER_CALLBACK_PHASE_LOAD)
            info << "code object loaded :: ";
        else if (rec.phase == ROCPROFILER_CALLBACK_PHASE_UNLOAD)
            info << "code object unloaded :: ";

        info << "code_object_id=" << obj_data->code_object_id
             << ", rocp_agent=" << obj_data->rocp_agent.handle
             << ", uri=" << obj_data->uri
             << ", load_base=" << to_hex_string(obj_data->load_base)
             << ", load_size=" << obj_data->load_size
             << ", load_delta=" << to_hex_string(obj_data->load_delta);

        if (obj_data->storage_type == ROCPROFILER_CODE_OBJECT_STORAGE_TYPE_FILE)
            info << ", storage_file_descr=" << obj_data->storage_file;
        else if (obj_data->storage_type == ROCPROFILER_CODE_OBJECT_STORAGE_TYPE_MEMORY)
            info << ", storage_memory_base=" << to_hex_string(obj_data->memory_base)
                 << ", storage_memory_size=" << obj_data->memory_size;

        trace_vec->push_back({__FUNCTION__, __FILE__, __LINE__, info.str()});
    }

    if (rec.kind == ROCPROFILER_CALLBACK_TRACING_CODE_OBJECT &&
        rec.operation == ROCPROFILER_CODE_OBJECT_DEVICE_KERNEL_SYMBOL_REGISTER) {
        auto* kern_data = static_cast<rocprofiler_callback_tracing_code_object_kernel_symbol_register_data_t*>(rec.payload);
        auto* trace_vec = static_cast<call_trace_list*>(user_payload);
        std::ostringstream info;

        if (rec.phase == ROCPROFILER_CALLBACK_PHASE_LOAD) {
            info << "kernel symbol registered :: ";
            tracked_kernels->insert({kern_data->kernel_id, *kern_data});
        } else if (rec.phase == ROCPROFILER_CALLBACK_PHASE_UNLOAD) {
            info << "kernel symbol unregistered :: ";
            tracked_kernels->erase(kern_data->kernel_id);
        }

        std::string kernel_name{kern_data->kernel_name};
        kernel_name = std::regex_replace(kernel_name, std::regex{"(\\.kd)$"}, "");
        int demangle_status = 0;
        kernel_name = demangle_cpp_symbol(kernel_name, &demangle_status);

        info << "code_object_id=" << kern_data->code_object_id
             << ", kernel_id=" << kern_data->kernel_id
             << ", kernel_object=" << to_hex_string(kern_data->kernel_object)
             << ", kernarg_segment_size=" << kern_data->kernarg_segment_size
             << ", kernarg_segment_alignment=" << kern_data->kernarg_segment_alignment
             << ", group_segment_size=" << kern_data->group_segment_size
             << ", private_segment_size=" << kern_data->private_segment_size
             << ", kernel_name=" << kernel_name;

        trace_vec->emplace_back(__FUNCTION__, __FILE__, __LINE__, info.str());
    }
}

int
initialize_tool(rocprofiler_client_finalize_t fini_cb, void* client_data)
{
    tracked_kernels = new kernel_info_map{};
    assert(client_data != nullptr);

    auto* trace_buffer = static_cast<call_trace_list*>(client_data);
    trace_buffer->emplace_back(__FUNCTION__, __FILE__, __LINE__, "");

    finalize_handler = fini_cb;

    ROCPROFILER_CALL(rocprofiler_create_context(&active_context), "context creation");
    ROCPROFILER_CALL(
        rocprofiler_configure_callback_tracing_service(active_context,
                                                       ROCPROFILER_CALLBACK_TRACING_CODE_OBJECT,
                                                       nullptr,
                                                       0,
                                                       on_tracing_event,
                                                       client_data),
        "configure tracing service");

    int is_valid = 0;
    ROCPROFILER_CALL(rocprofiler_context_is_valid(active_context, &is_valid),
                     "context validation");
    if (is_valid == 0) return -1;

    ROCPROFILER_CALL(rocprofiler_start_context(active_context), "start context");
    return 0;
}

void
finalize_tool(void* client_data)
{
    assert(client_data != nullptr);
    auto* trace_log = static_cast<call_trace_list*>(client_data);
    trace_log->emplace_back(__FUNCTION__, __FILE__, __LINE__, "");
    dump_traces_to_file(*trace_log);
    delete trace_log;
    delete tracked_kernels;
}

void
ensure_setup()
{
    int init_status = 0;
    if (rocprofiler_is_initialized(&init_status) == ROCPROFILER_STATUS_SUCCESS &&
        init_status == 0) {
        ROCPROFILER_CALL(rocprofiler_force_configure(&rocprofiler_configure),
                         "force config");
    }
}
