extern "C" rocprofiler_tool_configure_result_t*
rocprofiler_configure(uint32_t version,
                      const char* runtime_version,
                      uint32_t priority,
                      rocprofiler_client_id_t* client_id)
{
    client_id->name = "ExampleTool";
    client::detail::registered_client = client_id;

    uint32_t major = version / 10000;
    uint32_t minor = (version % 10000) / 100;
    uint32_t patch = version % 100;

    std::ostringstream info;
    info << client_id->name << " (priority=" << priority << ") using rocprofiler-sdk v"
         << major << "." << minor << "." << patch << " (" << runtime_version << ")";
    std::clog << info.str() << '\n';

    auto* tool_storage = new std::vector<client::detail::trace_entry>{};
    tool_storage->emplace_back(client::detail::trace_entry{__FUNCTION__, __FILE__, __LINE__, info.str()});

    static rocprofiler_tool_configure_result_t config{
        sizeof(rocprofiler_tool_configure_result_t),
        &client::detail::initialize_tool,
        &client::detail::finalize_tool,
        static_cast<void*>(tool_storage)
    };

    return &config;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int q;
    if (!(cin >> q)) return 0;

    vector<unsigned long long> queries(q);
    for (int i = 0; i < q; ++i) {
        cin >> queries[i];
    }

    for (int idx = 0; idx < q; ++idx) {
        unsigned long long target = queries[idx];

        // Find highest set bit position
        int highest_bit = 0;
        unsigned long long temp = target;
        while (temp > 1) {
            temp >>= 1;
            highest_bit++;
        }

        vector<long long> sequence;
        long long min_val = -1;
        long long max_val = 0;

        // Process bits from second highest to lowest
        sequence.push_back(0);

        for (int bit_pos = highest_bit - 1; bit_pos >= 0; --bit_pos) {
            if ((target >> bit_pos) & 1ULL) {
                sequence.push_back(min_val--);
            }
            if (bit_pos != 0) {
                sequence.push_back(++max_val);
            }
        }

        int size = sequence.size();
        vector<pair<long long, int>> indexed_values(size);

        for (int i = 0; i < size; ++i) {
            indexed_values[i] = make_pair(sequence[i], i);
        }

        sort(indexed_values.begin(), indexed_values.end());

        vector<int> result_permutation(size);
        for (int rank = 0; rank < size; ++rank) {
            result_permutation[indexed_values[rank].second] = rank;
        }

        cout << size << "\n";
        for (int i = 0; i < size; ++i) {
            if (i > 0) cout << " ";
            cout << result_permutation[i];
        }
        cout << "\n";
    }

    return 0;
}

