// Main solving function with modified logic
void determinePermutation() {
    int n;
    cin >> n;

    // Output k value
    cout << "1" << endl;

    // Initialize arrays for permutation tracking
    vector<int> permutation(n + 1, 0);
    vector<int> inverseMapping(n + 1, 0); // inverseMapping[value] = position

    // Determine p[1] last by elimination
    for (int position = 2; position <= n; position++) {
        vector<int> candidates;
        for (int value = 1; value <= n; value++) {
            if (value != position) {
                candidates.push_back(value);
            }
        }

        // Use dummy value 1 for comparisons
        int dummyValue = 1;
        vector<int> remainingCandidates;

        // Separate dummy from other candidates
        for (int val : candidates) {
            if (val != dummyValue) {
                remainingCandidates.push_back(val);
            }
        }

        // Binary search process
        while (!remainingCandidates.empty()) {
            if (remainingCandidates.size() == 1) {
                permutation[position] = remainingCandidates[0];
                break;
            }

            // Split candidates into two groups
            int splitPoint = remainingCandidates.size() / 2;
            vector<int> groupA, groupB;

            for (int i = 0; i < splitPoint; i++) {
                groupA.push_back(remainingCandidates[i]);
            }
            for (int i = splitPoint; i < remainingCandidates.size(); i++) {
                groupB.push_back(remainingCandidates[i]);
            }

            // Construct first query: position first, then dummy, groupA, groupB
            vector<int> query1(n);
            int idx = 0;
            query1[idx++] = position;
            query1[idx++] = dummyValue;
            for (int val : groupA) query1[idx++] = val;
            for (int val : groupB) query1[idx++] = val;

            // Construct second query: dummy first, groupA, position, groupB
            vector<int> query2(n);
            idx = 0;
            query2[idx++] = dummyValue;
            for (int val : groupA) query2[idx++] = val;
            query2[idx++] = position;
            for (int val : groupB) query2[idx++] = val;

            int response1 = executeQuery(query1);
            int response2 = executeQuery(query2);
            int difference = response2 - response1;

            // Determine next candidate set based on response
            int knownPos = inverseMapping[position]; // known predecessor

            if (knownPos != 0) {
                // Deterministic case when predecessor is known
                bool posInGroupA = false;
                for (int val : groupA) {
                    if (val == knownPos) {
                        posInGroupA = true;
                        break;
                    }
                }

                int calculatedValue = difference + 1;
                if (posInGroupA) {
                    if (calculatedValue == 1) {
                        remainingCandidates = groupB;
                    } else {
                        remainingCandidates = groupA;
                    }
                } else {
                    if (calculatedValue == 1) {
                        remainingCandidates = groupA;
                    } else {
                        remainingCandidates = groupB;
                    }
                }
            } else {
                // Ambiguous case handling
                int adjustedValue = difference + 1;

                if (adjustedValue == 0) {
                    remainingCandidates = groupA;
                } else if (adjustedValue == 2) {
                    remainingCandidates = groupB;
                } else { // adjustedValue == 1
                    if (difference == 2) {
                        remainingCandidates = groupB;
                    } else if (difference == -1) {
                        remainingCandidates = groupA;
                    } else {
                        // Handle tie-breaker scenario
                        if (remainingCandidates.size() <= 2) {
                            permutation[position] = -1; // Mark as ambiguous
                            break;
                        }
                        remainingCandidates = groupA;
                    }
                }
            }
        }

        // Set final value if not already determined
        if (permutation[position] == 0 && !remainingCandidates.empty()) {
            permutation[position] = remainingCandidates[0];
        }

        // Update inverse mapping if valid
        if (permutation[position] != -1 && permutation[position] != 0) {
            inverseMapping[permutation[position]] = position;
        }
    }

    // Determine p[1] by finding missing value
    set<int> usedValues;
    for (int i = 2; i <= n; i++) {
        if (permutation[i] != -1 && permutation[i] != 0) {
            usedValues.insert(permutation[i]);
        }
    }

    for (int value = 1; value <= n; value++) {
        if (usedValues.find(value) == usedValues.end()) {
            permutation[1] = value;
            break;
        }
    }
    inverseMapping[permutation[1]] = 1;

    // Handle any remaining ambiguous cases
    vector<int> unusedValues;
    for (int value = 1; value <= n; value++) {
        if (usedValues.find(value) == usedValues.end() && value != permutation[1]) {
            unusedValues.push_back(value);
        }
    }

    int unusedIndex = 0;
    for (int i = 2; i <= n; i++) {
        if (permutation[i] == -1 || permutation[i] == 0) {
            if (unusedIndex < unusedValues.size()) {
                permutation[i] = unusedValues[unusedIndex++];
            }
        }
    }

    // Output final permutation
    cout << "!";
    for (int i = 1; i <= n; i++) {
        cout << " " << permutation[i];
    }
    cout << endl;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int testCases;
    if (cin >> testCases) {
        while (testCases--) {
            determinePermutation();
        }
    }

    return 0;
}

#include <nanobind/nanobind.h>
