namespace nb = nanobind;
using namespace mscclpp;

// Register bindings for Fifo-related classes
void register_fifo(nb::module_& m) {
  // Bind ProxyTrigger class with read-write access to its members
  nb::class_<ProxyTrigger>(m, "ProxyTrigger")
      .def_rw("fst", &ProxyTrigger::fst)
      .def_rw("snd", &ProxyTrigger::snd);

  // Bind FifoDeviceHandle class with read-write access to its fields
  nb::class_<FifoDeviceHandle>(m, "FifoDeviceHandle")
      .def_rw("triggers", &FifoDeviceHandle::triggers)
      .def_rw("tail_replica", &FifoDeviceHandle::tailReplica)
      .def_rw("head", &FifoDeviceHandle::head)
      .def_rw("size", &FifoDeviceHandle::size)
      .def_prop_ro("raw", [](const FifoDeviceHandle& self) -> nb::bytes {
        return nb::bytes(reinterpret_cast<const char*>(&self), sizeof(self));
      });

  // Bind Fifo class with constructor and methods
  nb::class_<Fifo>(m, "Fifo")
      .def(nb::init<int>(), nb::arg("size") = DEFAULT_FIFO_SIZE)
      .def("poll", &Fifo::poll)
      .def("pop", &Fifo::pop)
      .def("flush_tail", &Fifo::flushTail, nb::arg("synchronize") = false)
      .def("length", &Fifo::size)  // Renamed method alias (same underlying function)
      .def("device_handle", &Fifo::deviceHandle);
}

#include "stdafx.h"
#include "InputOutputStream.h"
#include "NbtIo.h"

CompoundTag* NbtIo::readCompressed(InputStream* stream)
{
    MemSect(26);

    // Wrap input in DataInputStream for reading
    DataInputStream reader(stream);

    // Parse the NBT compound tag
    CompoundTag* result = NbtIo::read(static_cast<DataInput*>(&reader));

    // Ensure resources are released before returning
    reader.close();
    MemSect(0);

    return result;
}

void NbtIo::writeCompressed(CompoundTag* sourceTag, OutputStream* output)
{
    // Use buffered output to improve I/O efficiency
    BufferedOutputStream bufferWriter(output, 1024);
    DataOutputStream dataWriter(&bufferWriter);

    // Perform actual write operation
    NbtIo::write(sourceTag, &dataWriter);

    // Clean up streams properly
    dataWriter.close();
}

// Decompress from a byte array into a CompoundTag
CompoundTag* NbtIo::decompress(byteArray const& srcData)
{
    ByteArrayInputStream inputStream(srcData);
    DataInputStream reader(&inputStream);

    // Read top-level tag; must be a compound
    Tag* rawTag = Tag::readNamedTag(&reader);
    CompoundTag* result = nullptr;

    if (rawTag != nullptr && rawTag->getId() == Tag::TAG_Compound) {
        result = static_cast<CompoundTag*>(rawTag);
    } else {
        delete rawTag;
        result = nullptr;
    }

    // Prevent buffer deallocation on scope exit
    inputStream.reset();
    reader.close();

    return result;
}

byteArray NbtIo::compress(CompoundTag* sourceTag)
{
    ByteArrayOutputStream memStream;
    DataOutputStream writer(&memStream);

    // Write the tag to memory stream
    NbtIo::write(sourceTag, &writer);
    writer.close();

    // Copy internal buffer contents to new byteArray
    int size = memStream.buf.length;
    byteArray output(size);
    System::arraycopy(memStream.buf, 0, &output, 0, size);

    return output;
}

// Top-level read function: expects root tag to be a named compound
CompoundTag* NbtIo::read(DataInput* input)
{
    Tag* root = Tag::readNamedTag(input);

    if (root == nullptr || root->getId() != Tag::TAG_Compound) {
        delete root;
        return nullptr;
    }

    return static_cast<CompoundTag*>(root);
}

// Helper to write a compound tag as the root element
void NbtIo::write(CompoundTag* tag, DataOutput* output)
{
    Tag::writeNamedTag(tag, output);
}

