Joint::Id constexpr Joint::kInvalidId;

std::string JointDebugString(Joint const & joint)
{
    std::ostringstream stream;
    stream << "Joint [";

    size_t count = joint.GetSize();
    for (size_t index = 0; index < count; ++index)
    {
        if (index > 0)
            stream << ", ";
        stream << DebugPrint(joint.GetEntry(index));
    }

    stream << "]";
    return stream.str();
}
