#include <iostream>
#include <vector>
#include <string>
#include <numeric>
#include <algorithm>

struct Client {
    int client_id;
    std::string full_name;
    int years_old;
    std::vector<int> transaction_amounts;
    int join_year;
    std::string account_status;
};

struct SummaryClient {
    std::string name;
    int expenditure;
    int years_as_member;
    std::string membership_level;
};

struct AnalysisOutput {
    std::vector<SummaryClient> analyzed_clients;
    int overall_sales;
    int number_of_clients;
    double mean_purchase;
};

AnalysisOutput analyze_client_data(const std::vector<Client>& clients) {
    std::vector<Client> active_clients;
    for (const auto& client : clients) {
        if (client.account_status == "active" && client.years_old >= 25) {
            active_clients.push_back(client);
        }
    }

    std::vector<SummaryClient> client_summaries;
    for (const auto& client : active_clients) {
        SummaryClient summary;
        summary.name = client.full_name;

        int total = 0;
        for (int amount : client.transaction_amounts) {
            total += amount;
        }
        summary.expenditure = total;

        summary.years_as_member = 2026 - client.join_year;

        if (summary.expenditure < 500) {
            summary.membership_level = "Bronze";
        } else if (summary.expenditure < 1000) {
            summary.membership_level = "Silver";
        } else {
            summary.membership_level = "Gold";
        }

        client_summaries.push_back(summary);
    }

    int total_revenue = 0;
    for (const auto& summary : client_summaries) {
        total_revenue += summary.expenditure;
    }

    AnalysisOutput output;
    output.analyzed_clients = client_summaries;
    output.overall_sales = total_revenue;
    output.number_of_clients = static_cast<int>(client_summaries.size());

    if (output.number_of_clients > 0) {
        output.mean_purchase = static_cast<double>(total_revenue) / output.number_of_clients;
    } else {
        output.mean_purchase = 0.0;
    }

    return output;
}

