int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int depth;
    std::cin >> depth;

    if (depth == 0) {
        return 0;
    }

    int current_depth = depth;
    int previous_direction = -1;
    bool exit_reached;

    while (current_depth > 0) {
        int chosen_direction = -1;

        if (previous_direction == -1) {
            // First move: need to determine which direction leads upward
            // Try color 0 first
            std::cout << "move 0" << std::endl;
            std::cin >> exit_reached;
            if (exit_reached) return 0;

            std::cout << "query" << std::endl;
            int new_depth;
            std::cin >> new_depth;

            std::cout << "move 0" << std::endl; // Return to original position
            std::cin >> exit_reached;

            if (new_depth < current_depth) {
                chosen_direction = 0;
            } else {
                // Try color 1 as alternative
                std::cout << "move 1" << std::endl;
                std::cin >> exit_reached;
                if (exit_reached) return 0;

                std::cout << "query" << std::endl;
                std::cin >> new_depth;

                std::cout << "move 1" << std::endl; // Return to original position
                std::cin >> exit_reached;

                if (new_depth < current_depth) {
                    chosen_direction = 1;
                } else {
                    chosen_direction = 2;
                }
            }
        } else {
            // Determine the other two possible directions
            int alt1 = (previous_direction + 1) % 3;
            int alt2 = (previous_direction + 2) % 3;

            // Test alt1 first
            std::cout << "move " << alt1 << std::endl;
            std::cin >> exit_reached;
            if (exit_reached) return 0;

            std::cout << "query" << std::endl;
            int new_depth;
            std::cin >> new_depth;

            std::cout << "move " << alt1 << std::endl; // Return to original position
            std::cin >> exit_reached;

            if (new_depth < current_depth) {
                chosen_direction = alt1;
            } else {
                chosen_direction = alt2;
            }
        }

        // Final move in this level using determined direction
        std::cout << "move " << chosen_direction << std::endl;
        std::cin >> exit_reached;
        if (exit_reached) {
            return 0;
        }

        current_depth--;
        previous_direction = chosen_direction;
    }

    return 0;
}

