namespace secp256k1::simd {
using fast::FieldElement;

// ==============================================================================
// Scalar Fallback (always available, any platform)
// ==============================================================================
namespace detail {

// Helper lambda to perform element-wise binary operation on field arrays
template<typename Op>
void apply_op(FieldElement* out, const FieldElement* a, const FieldElement* b, std::size_t n, Op&& op) {
    std::size_t idx = 0;
    while (idx < n) {
        out[idx] = op(a[idx], b[idx]);
        ++idx;
    }
}

// Helper lambda for unary operations (e.g., square)
template<typename Op>
void apply_unary_op(FieldElement* out, const FieldElement* a, std::size_t n, Op&& op) {
    std::size_t idx = 0;
    while (idx < n) {
        out[idx] = op(a[idx]);
        ++idx;
    }
}

void batch_field_add_scalar(FieldElement* result, const FieldElement* lhs,
                            const FieldElement* rhs, std::size_t elements) {
    apply_op(result, lhs, rhs, elements, [](auto&& x, auto&& y) { return x + y; });
}

void batch_field_sub_scalar(FieldElement* result, const FieldElement* lhs,
                            const FieldElement* rhs, std::size_t elements) {
    apply_op(result, lhs, rhs, elements, [](auto&& x, auto&& y) { return x - y; });
}

void batch_field_mul_scalar(FieldElement* result, const FieldElement* lhs,
                            const FieldElement* rhs, std::size_t elements) {
    apply_op(result, lhs, rhs, elements, [](auto&& x, auto&& y) { return x * y; });
}

void batch_field_sqr_scalar(FieldElement* result, const FieldElement* input,
                            std::size_t count) {
    apply_unary_op(result, input, count, [](auto&& x) { return x.square(); });
}

} // namespace detail

// ==============================================================================
// Auto-Dispatching Batch Operations
// ==============================================================================
// Current implementation: scalar-only with architecture detection.
// SIMD kernels (AVX2/AVX-512) operate on the 4xuint64 representation.
//
// For field multiplication, SIMD doesn't help much because secp256k1
// modular reduction is inherently serial (carry propagation).
// The main benefit is for add/sub which are carry-chain operations
// that can be partially parallelized, and for batch inverse
// (Montgomery's trick) which is inherently parallelizable.

void batch_field_add(FieldElement* dest,
                     const FieldElement* src_a,
                     const FieldElement* src_b,
                     std::size_t len) {
    // As noted in original: vectorization via compiler flags suffices.
    detail::batch_field_add_scalar(dest, src_a, src_b, len);
}

void batch_field_sub(FieldElement* dest,
                     const FieldElement* src_a,
                     const FieldElement* src_b,
                     std::size_t len) {
    detail::batch_field_sub_scalar(dest, src_a, src_b, len);
}

void batch_field_mul(FieldElement* dest,
                     const FieldElement* src_a,
                     const FieldElement* src_b,
                     std::size_t len) {
    detail::batch_field_mul_scalar(dest, src_a, src_b, len);
}

void batch_field_sqr(FieldElement* dest,
                     const FieldElement* src,
                     std::size_t len) {
    detail::batch_field_sqr_scalar(dest, src, len);
}

// ==============================================================================
// Batch Modular Inverse (Montgomery's Trick)
// ==============================================================================
// Computes n inversions with only 1 actual field inversion.
// Algorithm:
//   1. Compute running products: prod[i] = a[0] * a[1] * ... * a[i]
//   2. Invert the final product: inv_all = prod[n-1]^(-1)
//   3. Back-propagate: out[i] = inv_all * prod[i-1], inv_all *= a[i]
//
// Cost: 1 inversion + 3(n-1) multiplications
// vs. n inversions naively (~250x faster for n=256)

void batch_field_inv(FieldElement* output,
                     const FieldElement* inputs,
                     std::size_t size,
                     FieldElement* temp_buffer) {
    if (size == 0u) {
        return;
    }
    if (size == 1u) {
        output[0] = inputs[0].inverse();
        return;
    }

    // Reuse 'output' as scratch if no external buffer given
    FieldElement* accumulators = temp_buffer ? temp_buffer : output;

    // Phase 1: Forward accumulation of products
    accumulators[0] = inputs[0];
    std::size_t i = 1;
    while (i < size) {
        accumulators[i] = accumulators[i - 1] * inputs[i];
        ++i;
    }

    // Phase 2: Invert last accumulated product
    FieldElement current_inverse = accumulators[size - 1].inverse();

    // Phase 3: Backward pass to compute inverses
    std::size_t j = size;
    while (j > 1u) {
        --j;
        output[j] = current_inverse * accumulators[j - 1];
        current_inverse = current_inverse * inputs[j];
    }
    output[0] = current_inverse;
}

} // namespace secp256k1::simd

