// TypeConverter implementation — rewritten with minor structural changes
TritonGPUTypeConverter::TritonGPUTypeConverter(MLIRContext *ctx,
                                               int warpCount,
                                               int threadsPerWarp,
                                               int ctaCount)
    : context(ctx), numWarps(warpCount), threadsPerWarp(threadsPerWarp),
      numCTAs(ctaCount) {

  // Identity conversion for non-tensor types
  addConversion([](Type t) { return t; });

  // Tensor type conversion with layout inference
  addConversion([this](RankedTensorType tensorTy) -> RankedTensorType {
    if (tensorTy.getEncoding())
      return tensorTy;

    auto shape = tensorTy.getShape();
    auto encoding = getDefaultBlockedEncoding(
        this->context, shape, this->numWarps, this->threadsPerWarp, this->numCTAs);
    return RankedTensorType::get(shape, tensorTy.getElementType(), encoding);
  });

  // Pointer type conversion — handles tt.ptr<tensor<>> specifically
  addConversion([this](triton::PointerType ptrTy) -> triton::PointerType {
    auto pointeeTy = dyn_cast<RankedTensorType>(ptrTy.getPointeeType());
    if (!pointeeTy)
      return ptrTy;

    auto newTensorTy = convertType(pointeeTy);
    return triton::PointerType::get(newTensorTy, ptrTy.getAddressSpace());
  });

  //
  // Materialization handlers
  //

  // Argument materialization — should never be invoked in this pass
  addArgumentMaterialization([&](OpBuilder &, RankedTensorType, ValueRange, Location) -> std::optional<Value> {
    llvm_unreachable("Argument rematerialization must not occur during Triton→TritonGPU lowering");
    return std::nullopt;
  });

  // Source materialization — also unreachable here
  addSourceMaterialization([&](OpBuilder &, RankedTensorType, ValueRange, Location) -> std::optional<Value> {
    llvm_unreachable("Source rematerialization is not expected in Triton→TritonGPU conversion");
    return std::nullopt;
  });

  // Target materialization — inserts ConvertLayoutOp when needed
  addTargetMaterialization([&](OpBuilder &builder, RankedTensorType dstTy,
                               ValueRange inputs, Location loc) {
    auto convOp = builder.create<triton::gpu::ConvertLayoutOp>(loc, dstTy, inputs);
    return std::optional<Value>(convOp.getResult());
  });
}

//
// Conversion target setup
//

TritonGPUConversionTarget::TritonGPUConversionTarget(
    MLIRContext &ctx, TritonGPUTypeConverter &typeConv)
    : ConversionTarget(ctx) {

  // Legal dialects
  addLegalDialect<triton::gpu::TritonGPUDialect>();

  // Explicitly illegal SCF ops
  addIllegalOp<scf::ExecuteRegionOp, scf::ParallelOp, scf::ReduceOp,
               scf::ReduceReturnOp>();

  // Dynamically legal check for core dialects
  addDynamicallyLegalDialect<arith::ArithDialect, math::MathDialect,
                             triton::TritonDialect, cf::ControlFlowDialect,
                             scf::SCFDialect>([&](Operation *op) {
    bool allRegionsLegal = true;
    for (auto &region : op->getRegions()) {
      allRegionsLegal &= typeConv.isLegal(&region);
    }
    return allRegionsLegal && typeConv.isLegal(op);
  });

  // Special handling for DotOp layout requirements
  addDynamicallyLegalOp<triton::DotOp>([](triton::DotOp dotOp) -> bool {
    auto AType = cast<RankedTensorType>(dotOp.getA().getType());
    auto BType = cast<RankedTensorType>(dotOp.getB().getType());

    auto AEnc = AType.getEncoding();
    auto BEnc = BType.getEncoding();

    bool validA = AEnc && isa<triton::gpu::DotOperandEncodingAttr>(AEnc);
    bool validB = BEnc && isa<triton::gpu::DotOperandEncodingAttr>(BEnc);

    return validA && validB;
  });
}

