// Reimplementation of ast_stack with modified traversal logic
ast_stack::ast_stack(value v)
{
    push_to_stack(v);
}

void ast_stack::add_branch(value v)
{
    advance_position(); // simulate moving to next position before adding
    push_to_stack(v);
    // Adjust: decrement header pointer to compensate for upcoming increment
    --m_nodes.back().current_header;
}

ast_stack& ast_stack::reset3(value v)
{
    m_nodes.clear();
    push_to_stack(v);
    return *this;
}

void ast_stack::push_to_stack(value v)
{
    auto& new_node = m_nodes.emplace_back();
    new_node.current_header = v.h;
    new_node.end_marker = v.h + 1;
    descend_into_subtree();
}

void ast_stack::descend_into_subtree()
{
    while (true) {
        auto node = m_nodes.back(); // snapshot current state
        auto* header_ptr = node.current_header;

        auto arg_count = header_ptr->oper_args();

        if (arg_count == 0) {
            break; // leaf node reached
        }

        // Navigate to first child operator in the block
        node.current_header = &node.header_block->m_ops[header_ptr->u32].hdr;
        node.end_marker = node.current_header + arg_count;

        m_nodes.emplace_back(node); // add child node to stack
    }
}

void ast_stack::advance_position()
{
    auto& stack_ref = m_nodes;
    auto& current_node = stack_ref.back();

    // Move to next operator
    if (++current_node.current_header == current_node.end_marker) {
        stack_ref.pop_back(); // finished processing this level
    } else {
        descend_into_subtree(); // try descending from new position
    }
}

ast_stack::value::value(const ast_context& p)
{
    header_block = const_cast<oper_block*>(p.a);
    current_header = const_cast<ims_operator*>(&p.h);
    call_offset = p.call_offset;
}

