#include "Frustum.h"

// Singleton instance for the Frustum class
Frustum* Frustum::frustum = new Frustum();

// Constructor: allocate memory for matrices
Frustum::Frustum() {
    _proj = MemoryTracker::createFloatBuffer(16);
    _modl = MemoryTracker::createFloatBuffer(16);
    _clip = MemoryTracker::createFloatBuffer(16);
}

// Destructor: release allocated memory
Frustum::~Frustum() {
    delete _proj;
    delete _modl;
    delete _clip;
}

// Public method to retrieve the current frustum state
FrustumData* Frustum::getFrustum() {
    calculateFrustum();  // Ensure frustum is up-to-date before returning
    return frustum;
}

// Helper: Normalize a plane vector (A, B, C, D) by its magnitude
void Frustum::normalizePlane(float (**planes), int index) {
    float length = sqrtf(planes[index][A] * planes[index][A] +
                         planes[index][B] * planes[index][B] +
                         planes[index][C] * planes[index][C]);

    if (length != 0.0f) {
        planes[index][A] /= length;
        planes[index][B] /= length;
        planes[index][C] /= length;
        planes[index][D] /= length;
    }
}

// Main logic to compute view frustum from OpenGL matrices
void Frustum::calculateFrustum() {
    // Clear buffers before use
    _proj->clear();
    _modl->clear();
    _clip->clear();

    // Retrieve projection and modelview matrices from OpenGL
    glGetFloat(GL_PROJECTION_MATRIX, _proj);
    glGetFloat(GL_MODELVIEW_MATRIX, _modl);

    // Prepare data access
    _proj->flip()->limit(16);
    _modl->flip()->limit(16);
    _proj->get(&proj);
    _modl->get(&modl);

    // Compute combined clip matrix (modelview × projection)
    // Row-major multiplication: each row of result is linear combination of columns of proj weighted by modl row
    for (int row = 0; row < 4; ++row) {
        for (int col = 0; col < 4; ++col) {
            clip[row * 4 + col] = 0.0f;
            for (int k = 0; k < 4; ++k) {
                clip[row * 4 + col] += modl[row * 4 + k] * proj[k * 4 + col];
            }
        }
    }

    // Extract frustum planes from clip matrix
    // Right plane: clip[3] - clip[0], etc.
    m_Frustum[RIGHT][A] = clip[3] - clip[0];
    m_Frustum[RIGHT][B] = clip[7] - clip[4];
    m_Frustum[RIGHT][C] = clip[11] - clip[8];
    m_Frustum[RIGHT][D] = clip[15] - clip[12];

    // Left plane
    m_Frustum[LEFT][A] = clip[3] + clip[0];
    m_Frustum[LEFT][B] = clip[7] + clip[4];
    m_Frustum[LEFT][C] = clip[11] + clip[8];
    m_Frustum[LEFT][D] = clip[15] + clip[12];

    // Bottom plane
    m_Frustum[BOTTOM][A] = clip[3] + clip[1];
    m_Frustum[BOTTOM][B] = clip[7] + clip[5];
    m_Frustum[BOTTOM][C] = clip[11] + clip[9];
    m_Frustum[BOTTOM][D] = clip[15] + clip[13];

    // Top plane
    m_Frustum[TOP][A] = clip[3] - clip[1];
    m_Frustum[TOP][B] = clip[7] - clip[5];
    m_Frustum[TOP][C] = clip[11] - clip[9];
    m_Frustum[TOP][D] = clip[15] - clip[13];

    // Back plane
    m_Frustum[BACK][A] = clip[3] - clip[2];
    m_Frustum[BACK][B] = clip[7] - clip[6];
    m_Frustum[BACK][C] = clip[11] - clip[10];
    m_Frustum[BACK][D] = clip[15] - clip[14];

    // Front plane
    m_Frustum[FRONT][A] = clip[3] + clip[2];
    m_Frustum[FRONT][B] = clip[7] + clip[6];
    m_Frustum[FRONT][C] = clip[11] + clip[10];
    m_Frustum[FRONT][D] = clip[15] + clip[14];

    // Normalize all extracted planes
    normalizePlane(m_Frustum, RIGHT);
    normalizePlane(m_Frustum, LEFT);
    normalizePlane(m_Frustum, BOTTOM);
    normalizePlane(m_Frustum, TOP);
    normalizePlane(m_Frustum, BACK);
    normalizePlane(m_Frustum, FRONT);
}

