using namespace std;

// Function to process each test case
void runTest() {
    int n;
    if (!(cin >> n)) return;

    // Create initial list of pen IDs from 0 to n-1
    vector<int> pens(n);
    iota(pens.begin(), pens.end(), 0);

    // Randomize the order using time-based seed
    unsigned seed = chrono::system_clock::now().time_since_epoch().count();
    shuffle(pens.begin(), pens.end(), default_random_engine(seed));

    // Vector to hold pens that have passed at least one test
    vector<int> verified;

    // Lambda function to perform a query on a pen
    auto checkPen = [&](int id) -> int {
        cout << "0 " << id << endl;
        int result;
        cin >> result;
        return result;
    };

    // Continue until only two pens remain
    while (pens.size() + verified.size() > 2) {
        if (pens.empty()) {
            // Only verified pens remain; pit them directly against each other
            int first = verified.back(); verified.pop_back();
            int second = verified.back(); verified.pop_back();

            if (checkPen(first) == 0) {
                // First pen failed; keep second
                verified.push_back(second);
            } else {
                if (checkPen(second) == 0) {
                    // Second pen failed; keep first
                    verified.push_back(first);
                } else {
                    // Both succeeded; keep both
                    verified.push_back(first);
                    verified.push_back(second);
                }
            }
        } else {
            // Take a candidate pen from the unverified list
            int candidate = pens.back(); pens.pop_back();

            if (verified.empty()) {
                // No verified pens yet; pair two unverified pens
                int opponent = pens.back(); pens.pop_back();

                if (checkPen(candidate) == 0) {
                    // Candidate failed; opponent remains unverified
                    pens.push_back(opponent);
                } else {
                    if (checkPen(opponent) == 0) {
                        // Opponent failed; promote candidate to verified
                        verified.push_back(candidate);
                    } else {
                        // Both succeeded; promote both
                        verified.push_back(candidate);
                        verified.push_back(opponent);
                    }
                }
            } else {
                // Use a verified pen as gatekeeper
                int gatekeeper = verified.back(); verified.pop_back();

                if (checkPen(candidate) == 0) {
                    // Candidate failed; gatekeeper remains verified
                    verified.push_back(gatekeeper);
                } else {
                    if (checkPen(gatekeeper) == 0) {
                        // Gatekeeper failed; replace with candidate
                        verified.push_back(candidate);
                    } else {
                        // Both survived; keep both verified
                        verified.push_back(candidate);
                        verified.push_back(gatekeeper);
                    }
                }
            }
        }
    }

    // Collect remaining pens
    vector<int> finalPens;
    finalPens.insert(finalPens.end(), pens.begin(), pens.end());
    finalPens.insert(finalPens.end(), verified.begin(), verified.end());

    // Output the final pair
    cout << "1 " << finalPens[0] << " " << finalPens[1] << endl;
}

