    cin.tie(nullptr);

    int testCaseCount;
    if (cin >> testCaseCount) {
        for (int i = 0; i < testCaseCount; ++i) {
            runTest();
        }
    }

    return 0;
}

#include <iostream>
#include <vector>
#include <algorithm>
#include <utility>

int main() {
    std::ios::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int n;
    std::cin >> n;

    // Build adjacency list
    std::vector<std::vector<int>> graph(n + 1);
    for (int i = 2; i <= n; ++i) {
        int parent;
        std::cin >> parent;
        graph[parent].push_back(i);
        graph[i].push_back(parent);
    }

    // Identify leaf nodes
    std::vector<int> leaf_nodes;
    for (int i = 1; i <= n; ++i) {
        if (graph[i].size() == 1) {
            leaf_nodes.push_back(i);
        }
    }

    std::sort(leaf_nodes.begin(), leaf_nodes.end());

    // Prepare storage for decomposition components
    std::vector<std::vector<int>> component_bags;
    std::vector<std::pair<int, int>> connection_edges;

    // Create individual node bags first
    std::vector<int> node_to_bag_id(n + 1);
    int bag_counter = 0;
    for (int i = 1; i <= n; ++i) {
        node_to_bag_id[i] = bag_counter++;
        component_bags.push_back({i});
    }

    // Process tree structure - connect parent to child bags
    for (int u = 1; u <= n; ++u) {
        for (int v : graph[u]) {
            if (v > u) {  // Only process each edge once
                connection_edges.emplace_back(node_to_bag_id[u], bag_counter);
                component_bags.push_back({u, v});
                bag_counter++;
            }
        }
    }

    // Handle leaf connections specially when there are multiple leaves
    if (leaf_nodes.size() >= 2) {
        int first_leaf_bag = node_to_bag_id[leaf_nodes[0]];

        // Create intermediate bags connecting consecutive leaves
        std::vector<int> leaf_chain_bags;
        for (size_t i = 0; i + 1 < leaf_nodes.size(); ++i) {
            leaf_chain_bags.push_back(bag_counter);
            component_bags.push_back({leaf_nodes[i], leaf_nodes[i+1]});
            bag_counter++;
        }

        // Create a special bag connecting first and last leaves
        int connector_bag = bag_counter++;
        component_bags.push_back({leaf_nodes.front(), leaf_nodes.back()});

        // Connect the chain
        for (size_t i = 0; i + 1 < leaf_chain_bags.size(); ++i) {
            connection_edges.emplace_back(leaf_chain_bags[i], leaf_chain_bags[i+1]);
        }

        // Connect to the connector bag and first leaf's bag
        if (!leaf_chain_bags.empty()) {
            connection_edges.emplace_back(connector_bag, leaf_chain_bags.front());
            connection_edges.emplace_back(leaf_chain_bags.front(), first_leaf_bag);
        }
    }

    // Output results
    std::cout << bag_counter << '\n';
    for (const auto& bag : component_bags) {
        std::cout << bag.size();
        for (int node : bag) {
            std::cout << " " << node;
        }
        std::cout << '\n';
    }

    for (const auto& edge : connection_edges) {
        std::cout << edge.first << " " << edge.second << '\n';
    }

    return 0;
}

#include <iostream>
#include <vector>
#include <algorithm>
#include <random>
#include <chrono>
#include <cmath>
#include <climits>
using namespace std;

// Problem Data
int J, M;
struct Task {
    int machine;
    int time;
};
vector<vector<Task>> job_routes; // [job][op_index]

// Helper arrays for evaluation (avoid reallocation)
vector<int> op_counter;
vector<long long> job_end_time;
vector<long long> machine_end_time;

// Evaluate makespan given operation-based permutation
long long evaluate_makespan(const vector<int>& order) {
    fill(op_counter.begin(), op_counter.end(), 0);
    fill(job_end_time.begin(), job_end_time.end(), 0);
    fill(machine_end_time.begin(), machine_end_time.end(), 0);

    long long max_completion = 0;

    for (int job : order) {
        int step = op_counter[job]++;
        const Task& t = job_routes[job][step];
        int m = t.machine;
        int dur = t.time;

        long long earliest = max(job_end_time[job], machine_end_time[m]);
        long long finish = earliest + dur;

        job_end_time[job] = finish;
        machine_end_time[m] = finish;

        if (finish > max_completion) max_completion = finish;
    }

    return max_completion;
}

// Print the schedule per machine based on best permutation
void display_schedule(const vector<int>& order) {
    vector<vector<int>> machine_jobs(M);
    fill(op_counter.begin(), op_counter.end(), 0);

    for (int job : order) {
        int step = op_counter[job]++;
        int m = job_routes[job][step].machine;
        machine_jobs[m].push_back(job);
    }

    for (int m = 0; m < M; ++m) {
        for (size_t i = 0; i < machine_jobs[m].size(); ++i) {
            cout << machine_jobs[m][i];
            if (i + 1 < machine_jobs[m].size()) cout << " ";
        }
        cout << "\n";
    }
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    if (!(cin >> J >> M)) return 0;

    job_routes.resize(J);
    for (int i = 0; i < J; ++i) {
        job_routes[i].reserve(M);
        for (int k = 0; k < M; ++k) {
            int m, p;
            cin >> m >> p;
            job_routes[i].emplace_back(Task{m, p});
        }
    }

    // Initialize helper structures
    op_counter.resize(J);
    job_end_time.resize(J);
    machine_end_time.resize(M);

    // Build initial permutation: each job repeated M times
    vector<int> base_order;
    base_order.reserve(J * M);
    for (int j = 0; j < J; ++j) {
        for (int k = 0; k < M; ++k) {
            base_order.push_back(j);
        }
    }

    // Random seed and initial random shuffle
    mt19937_64 rng(chrono::high_resolution_clock::now().time_since_epoch().count());
    shuffle(base_order.begin(), base_order.end(), rng);

    long long best_val = evaluate_makespan(base_order);
    vector<int> best_order = base_order;

    // Try multiple random permutations to find a good starting point
    for (int attempt = 0; attempt < 150; ++attempt) {
        shuffle(base_order.begin(), base_order.end(), rng);
        long long val = evaluate_makespan(base_order);
        if (val < best_val) {
            best_val = val;
            best_order = base_order;
        }
    }

    // Simulated Annealing setup
    vector<int> current_order = best_order;
    long long current_val = best_val;

    auto start_point = chrono::steady_clock::now();
    double limit_seconds = 1.95;

    // Estimate temperature using random moves
    double avg_delta = 0.0;
    int delta_count = 0;
    for (int trial = 0; trial < 200; ++trial) {
        int idx1 = uniform_int_distribution<int>(0, J*M - 1)(rng);
        int idx2 = uniform_int_distribution<int>(0, J*M - 1)(rng);
        if (idx1 == idx2) continue;

        swap(current_order[idx1], current_order[idx2]);
        long long new_val = evaluate_makespan(current_order);
        long long diff = new_val - current_val;

        if (diff > 0) {
            avg_delta += diff;
            delta_count++;
        }

        swap(current_order[idx1], current_order[idx2]); // revert
    }

    double temp = 100.0;
    if (delta_count > 0) {
        double mean_delta = avg_delta / delta_count;
        temp = -mean_delta / log(0.5); // 50% acceptance at mean delta
    }

    long long iterations = 0;

    while (true) {
        // Check time every 1024 iterations
        if ((iterations & 0x3FF) == 0) {
            auto now = chrono::steady_clock::now();
            double elapsed = chrono::duration<double>(now - start_point).count();
            if (elapsed >= limit_seconds) break;

            double progress = elapsed / limit_seconds;
            temp = 100.0 * (1.0 - progress);
            if (temp < 1e-8) temp = 1e-8;
        }
        iterations++;

        // Generate neighbor by swapping two positions
        int pos1 = uniform_int_distribution<int>(0, J*M - 1)(rng);
        int pos2 = uniform_int_distribution<int>(0, J*M - 1)(rng);
        if (pos1 == pos2) continue;

        swap(current_order[pos1], current_order[pos2]);
        long long candidate_val = evaluate_makespan(current_order);

        bool accepted = false;

        if (candidate_val <= current_val) {
            accepted = true;
            if (candidate_val < best_val) {
                best_val = candidate_val;
                best_order = current_order;
            }
        } else {
            double delta = static_cast<double>(candidate_val - current_val);
            double prob = exp(-delta / temp);
            if (uniform_real_distribution<double>(0.0, 1.0)(rng) < prob) {
                accepted = true;
            }
        }

        if (!accepted) {
            swap(current_order[pos1], current_order[pos2]); // undo
        } else {
            current_val = candidate_val;
        }
    }

    display_schedule(best_order);
    return 0;
}

#include "stdafx.h"
#include "IntBuffer.h"
