// Helper macro for byte extraction
#define EXTRACT_BYTE(val, shift) static_cast<unsigned char>((val) >> (shift))

ByteBuffer::ByteBuffer(unsigned int capacity)
	: Buffer(capacity), hasBackingArray(false), buffer(nullptr), byteOrder(BIGENDIAN)
{
	buffer = new byte[capacity];
	std::fill(buffer, buffer + capacity, 0);
}

ByteBuffer* ByteBuffer::allocateDirect(int capacity)
{
	return new ByteBuffer(static_cast<unsigned int>(capacity));
}

ByteBuffer::ByteBuffer(unsigned int capacity, byte* backingArray)
	: Buffer(capacity), hasBackingArray(true), buffer(backingArray), byteOrder(BIGENDIAN)
{
}

ByteBuffer::~ByteBuffer()
{
	if (!hasBackingArray && buffer != nullptr)
	{
		delete[] buffer;
		buffer = nullptr;
	}
}

ByteBuffer* ByteBuffer::wrap(byteArray& b)
{
	return new ByteBuffer(b.length, b.data);
}

ByteBuffer* ByteBuffer::allocate(unsigned int capacity)
{
	return new ByteBuffer(capacity);
}

void ByteBuffer::order(ByteOrder bo)
{
	byteOrder = bo;
}

ByteBuffer* ByteBuffer::flip()
{
	m_limit = m_position;
	m_position = 0;
	return this;
}

byte* ByteBuffer::getBuffer() const
{
	return buffer;
}

int ByteBuffer::getSize() const
{
	return m_limit;
}

BYTE ByteBuffer::get(int index) const
{
	assert(index >= 0 && index < m_limit);
	return buffer[index];
}

int ByteBuffer::getInt()
{
	assert(m_position + 3 < m_limit);

	int result = 0;
	if (byteOrder == BIGENDIAN)
	{
		result |= (static_cast<int>(buffer[m_position]) << 24);
		result |= (static_cast<int>(buffer[m_position + 1]) << 16);
		result |= (static_cast<int>(buffer[m_position + 2]) << 8);
		result |= static_cast<int>(buffer[m_position + 3]);
	}
	else // LITTLEENDIAN
	{
		result |= static_cast<int>(buffer[m_position]);
		result |= (static_cast<int>(buffer[m_position + 1]) << 8);
		result |= (static_cast<int>(buffer[m_position + 2]) << 16);
		result |= (static_cast<int>(buffer[m_position + 3]) << 24);
	}

	m_position += 4;
	return result;
}

int ByteBuffer::getInt(unsigned int index) const
{
	assert(index + 3 < m_limit);

	int result = 0;
	if (byteOrder == BIGENDIAN)
	{
		result |= (static_cast<int>(buffer[index]) << 24);
		result |= (static_cast<int>(buffer[index + 1]) << 16);
		result |= (static_cast<int>(buffer[index + 2]) << 8);
		result |= static_cast<int>(buffer[index + 3]);
	}
	else // LITTLEENDIAN
	{
		result |= static_cast<int>(buffer[index]);
		result |= (static_cast<int>(buffer[index + 1]) << 8);
		result |= (static_cast<int>(buffer[index + 2]) << 16);
		result |= (static_cast<int>(buffer[index + 3]) << 24);
	}

	return result;
}

__int64 ByteBuffer::getLong()
{
	assert(m_position + 7 < m_limit);

	__int64 value = 0;
	if (byteOrder == BIGENDIAN)
	{
		for (int i = 0; i < 8; ++i)
			value |= (__int64)(static_cast<__int64>(buffer[m_position + i]) << (56 - i * 8));
	}
	else // LITTLEENDIAN
	{
		for (int i = 0; i < 8; ++i)
			value |= (__int64)(static_cast<__int64>(buffer[m_position + i]) << (i * 8));
	}

	m_position += 8;
	return value;
}

short ByteBuffer::getShort()
{
	assert(m_position + 1 < m_limit);

	short val = 0;
	if (byteOrder == BIGENDIAN)
	{
		val = static_cast<short>((static_cast<unsigned char>(buffer[m_position]) << 8) |
			static_cast<unsigned char>(buffer[m_position + 1]));
	}
	else // LITTLEENDIAN
	{
		val = static_cast<short>(static_cast<unsigned char>(buffer[m_position]) |
			(static_cast<unsigned char>(buffer[m_position + 1]) << 8));
	}

	m_position += 2;
	return val;
}

void ByteBuffer::getShortArray(shortArray& s)
{
	assert(s.length >= (m_limit - m_position) / 2);
	std::memcpy(s.data, buffer + m_position, (m_limit - m_position));
}

ByteBuffer* ByteBuffer::put(int index, byte b)
{
	assert(index >= 0 && index < m_limit);
	buffer[index] = b;
	return this;
}

ByteBuffer* ByteBuffer::putInt(int value)
{
	assert(m_position + 3 < m_limit);

	if (byteOrder == BIGENDIAN)
	{
		buffer[m_position]     = EXTRACT_BYTE(value, 24);
		buffer[m_position + 1] = EXTRACT_BYTE(value, 16);
		buffer[m_position + 2] = EXTRACT_BYTE(value, 8);
		buffer[m_position + 3] = EXTRACT_BYTE(value, 0);
	}
	else // LITTLEENDIAN
	{
		buffer[m_position]     = EXTRACT_BYTE(value, 0);
		buffer[m_position + 1] = EXTRACT_BYTE(value, 8);
		buffer[m_position + 2] = EXTRACT_BYTE(value, 16);
		buffer[m_position + 3] = EXTRACT_BYTE(value, 24);
	}

	m_position += 4;
	return this;
}

ByteBuffer* ByteBuffer::putInt(unsigned int index, int value)
{
	assert(index + 3 < m_limit);

	if (byteOrder == BIGENDIAN)
	{
		buffer[index]     = EXTRACT_BYTE(value, 24);
		buffer[index + 1] = EXTRACT_BYTE(value, 16);
		buffer[index + 2] = EXTRACT_BYTE(value, 8);
		buffer[index + 3] = EXTRACT_BYTE(value, 0);
	}
	else // LITTLEENDIAN
	{
		buffer[index]     = EXTRACT_BYTE(value, 0);
		buffer[index + 1] = EXTRACT_BYTE(value, 8);
		buffer[index + 2] = EXTRACT_BYTE(value, 16);
		buffer[index + 3] = EXTRACT_BYTE(value, 24);
	}

	return this;
}

ByteBuffer* ByteBuffer::putShort(short value)
{
	assert(m_position + 1 < m_limit);

	if (byteOrder == BIGENDIAN)
	{
		buffer[m_position]     = EXTRACT_BYTE(value, 8);
		buffer[m_position + 1] = EXTRACT_BYTE(value, 0);
	}
	else // LITTLEENDIAN
	{
		buffer[m_position]     = EXTRACT_BYTE(value, 0);
		buffer[m_position + 1] = EXTRACT_BYTE(value, 8);
	}

	m_position += 2;
	return this;
}

ByteBuffer* ByteBuffer::putShortArray(shortArray& s)
{
	assert(s.length * 2 <= m_limit);
	std::memcpy(buffer, s.data, s.length * 2);
	return this;
}

ByteBuffer* ByteBuffer::putLong(__int64 value)
{
	assert(m_position + 7 < m_limit);

	if (byteOrder == BIGENDIAN)
	{
		for (int i = 0; i < 8; ++i)
			buffer[m_position + i] = EXTRACT_BYTE(value, 56 - i * 8);
	}
	else // LITTLEENDIAN
	{
		for (int i = 0; i < 8; ++i)
			buffer[m_position + i] = EXTRACT_BYTE(value, i * 8);
	}

	return this;
}

ByteBuffer* ByteBuffer::put(byteArray inputArray)
{
	if (inputArray.length > remaining())
		assert(false); // TODO: proper exception handling

	std::copy(inputArray.data, inputArray.data + inputArray.length, buffer + m_position);
	m_position += inputArray.length;
	return this;
}

byteArray ByteBuffer::array() const
{
	return byteArray(buffer, m_capacity);
}

IntBuffer* ByteBuffer::asIntBuffer()
{
	return new IntBuffer((m_limit - m_position) / 4,
		reinterpret_cast<int*>(buffer + m_position));
}

FloatBuffer* ByteBuffer::asFloatBuffer()
{
	return new FloatBuffer((m_limit - m_position) / 4,
		reinterpret_cast<float*>(buffer + m_position));
}

