#include <iostream>
#include <vector>
#include <map>

// Interact with the judge: send query and receive collision count
long long communicate(const std::vector<long long>& elements) {
    if (elements.empty()) {
        return 0;
    }

    std::cout << "0 " << elements.size();
    for (long long val : elements) {
        std::cout << " " << val;
    }
    std::cout << std::endl;

    long long result;
    std::cin >> result;

    if (result == -1) {
        exit(0);
    }
    return result;
}

// Report final answer to the judge
void report(long long value) {
    std::cout << "1 " << value << std::endl;
}

// Cache results of expensive queries
std::map<long long, long long> cache;

// Compute collisions between two segments: [base+1, base+k] and [base+d+1, base+d+k]
long long compute_collisions(long long offset, int segment_length) {
    if (cache.find(offset) != cache.end()) {
        return cache[offset];
    }

    const long long BASE = 200000000000000000LL;
    std::vector<long long> query_elements;
    query_elements.reserve(2 * segment_length);

    // First segment: BASE + 1 to BASE + k
    for (int idx = 1; idx <= segment_length; ++idx) {
        query_elements.push_back(BASE + idx);
    }

    // Second segment: BASE + offset + 1 to BASE + offset + k
    for (int idx = 1; idx <= segment_length; ++idx) {
        query_elements.push_back(BASE + offset + idx);
    }

    return cache[offset] = communicate(query_elements);
}

// Determine remainder using binary search on possible values
long long determine_remainder(long long divisor, int segment_size) {
    long long left = 0, right = divisor;
    long long lower_bound = 0;

    // Check if there are collisions at offset=divisor
    if (compute_collisions(divisor, segment_size) > 0) {
        lower_bound = 0;
    }

    // Binary search for maximum m where d-m yields collisions
    while (left <= right) {
        long long mid = left + (right - left) / 2;
        if (compute_collisions(divisor - mid, segment_size) > 0) {
            lower_bound = mid;
            left = mid + 1;
        } else {
            right = mid - 1;
        }
    }

    long long current_collisions = compute_collisions(divisor - lower_bound, segment_size);
    return lower_bound + segment_size - current_collisions;
}

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    // Handle small n case first
    const int SMALL_THRESHOLD = 450;
    std::vector<long long> initial_query;
    for (int i = 1; i <= SMALL_THRESHOLD; ++i) {
        initial_query.push_back(i);
    }

    if (communicate(initial_query) > 0) {
        int low = 1, high = SMALL_THRESHOLD;
        int found_k = SMALL_THRESHOLD;

        while (low <= high) {
            int mid = low + (high - low) / 2;
            if (mid == 0) {
                low = 1;
                continue;
            }

            std::vector<long long> test_query;
            for (int i = 1; i <= mid; ++i) {
                test_query.push_back(i);
            }

            if (communicate(test_query) > 0) {
                found_k = mid;
                high = mid - 1;
            } else {
                low = mid + 1;
            }
        }

        report(found_k - 1);
        return 0;
    }

    // Handle large n case
    const int LARGE_THRESHOLD = 400;
    std::vector<long long> remainders(34);

    // Calculate 2^i mod n for i from 0 to 33
    for (int i = 0; i <= 33; ++i) {
        cache.clear();
        remainders[i] = determine_remainder(1LL << i, LARGE_THRESHOLD);
    }

    // Derive n from consecutive remainders
    for (int i = 0; i <= 32; ++i) {
        long long potential_n = 2 * remainders[i] - remainders[i+1];
        if (potential_n > 0) {
            report(potential_n);
            return 0;
        }
    }

    return 0;
}

