void CharHair::SetName(const char* name, ObjectDir* dir) {
    Hmx::Object::SetName(name, dir);
    // Enable post-processing only if parent is Character or WorldDir
    mPostProcEnabled = dynamic_cast<Character*>(dir) || dynamic_cast<WorldDir*>(dir);
}

void CharHair::Poll() {
    Character* currentChar = Character::Current();
    if (currentChar) {
        if (currentChar->Synced()) {
            Hookup();
        }
        if (currentChar->Teleported()) {
            mResetFlag = 1;
        }
        if (currentChar->LODCheck()) {
            DoReset(0);
            return;
        }
    }

    if (mResetFlag > 0) {
        DoReset(mResetFlag);
    }

    float dt = TheTaskMgr.DeltaSeconds();
    if (dt != 0.0f) {
        SimulateLoops(1, GetFPS());
    } else {
        SimulateZeroTime();
    }
}

void CharHair::Enter() {
    mResetFlag = 1;
    RndPollable::Enter();
    Hookup();
}

void CharHair::PollDeps(
    std::list<Hmx::Object*>& changedBy, std::list<Hmx::Object*>& changeList
) {
    size_t count = mStrands.size();
    for (size_t idx = 0; idx < count; ++idx) {
        Hmx::Object* rootObj = mStrands[idx].Root();
        changedBy.push_back(rootObj);
        changeList.push_back(rootObj);
    }
}

void CharHair::SetCloth(bool enable) {
    size_t totalStrands = mStrands.size();
    for (size_t i = 0; i < totalStrands; ++i) {
        Strand& currentStrand = mStrands[i];
        int modIndex = Mod(static_cast<int>(i + 1), static_cast<int>(totalStrands));
        Strand& otherStrand = mStrands[modIndex];

        int pointCount = currentStrand.NumPoints();
        for (int j = 0; j < pointCount; ++j) {
            Point& pt = currentStrand.PointAt(j);
            float sideLen = -1.0f;
            if (enable && j < otherStrand.NumPoints()) {
                sideLen = Distance(pt.pos, otherStrand.PointAt(j).pos);
            }
            pt.sideLength = sideLen;
        }
    }
}

void CharHair::Hookup() {
    if (!mIsManagedHookup) {
        ObjPtrList<CharCollide> colliderList(this);
        for (ObjDirItr<CharCollide> it(Dir(), true); it != nullptr; ++it) {
            colliderList.push_back(*it);
        }
        colliderList.sort(SortCollides());
        Hookup(colliderList);
    }
}

void CharHair::FreezePose() {
    bool prevSimState = mSimEnabled;
    Hookup();
    SimulateLoops(200, 60);
    mSimEnabled = prevSimState;
    FreezePoseRaw();
}

INIT_REVS(11, 0)

void CharHair::Load(BinStream& bs) {
    LOAD_REVS(bs);
    ASSERT_REVS(11, 0);
    LOAD_SUPERCLASS(Hmx::Object)
    bs >> mStiffness >> mTorsion >> mInertia >> mGravity >> mWeight >> mFriction;

    if (d.rev < 8) {
        mMinSlack = 0.0f;
        mMaxSlack = 0.0f;
    } else {
        bs >> mMinSlack >> mMaxSlack;
    }

    bs >> mSimEnabled;
    if (d.rev > 10) {
        bs >> mWindFactor;
    }
}

