};

struct BarometerReading {
  TimeNano timestamp;
  float altitude_m;   // meters
  float pressure_pa;  // pascals
  float qnh_hpa;      // hectopascals (hPa)
};

class Barometer::Impl : public SensorImpl {
 public:
  Impl(const std::string& identifier, bool active,
       const std::string& parent_link_name,
       const Logger& logger_ref,
       const TopicManager& topic_mgr,
       const std::string& base_topic_path,
       const ServiceManager& service_mgr,
       const StateManager& state_mgr);

  void Configure(ConfigJson cfg);
  void Setup(const Kinematics&, const Environment&);
  void StartUpdate() override;
  void GenerateTopics();
  void InjectNoise(BarometerReading&, const TimeSec&);
  void Tick(const TimeNano sim_time, const TimeNano delta_nanos);
  BarometerMessage FetchOutput();
  void SetupServiceEndpoint();
  void FinishUpdate() override;

 private:
  friend class Barometer::Loader;
  Barometer::Loader loader_;
  BarometerParams sensor_config_;
  GaussianMarkov pressure_drift_process_;
  RandomGeneratorGaussianF independent_noise_;
  Topic barometer_pub_topic_;
  std::vector<std::reference_wrapper<Topic>> active_topics_;

  struct TruthReference {
    const Environment* env_ptr;
  } truth_context_;

  BarometerReading current_reading_;  // Stores most recent measurement
};

// --- Public Barometer interface ---

Barometer::Barometer() : Sensor(std::shared_ptr<SensorImpl>(nullptr)) {}

Barometer::Barometer(const std::string& id, bool enabled,
                     const std::string& parent_link,
                     const Logger& logger,
                     const TopicManager& topic_manager,
                     const std::string& topic_prefix,
                     const ServiceManager& service_manager,
                     const StateManager& state_manager)
    : Sensor(std::shared_ptr<SensorImpl>(new Barometer::Impl(
          id, enabled, parent_link, logger, topic_manager, topic_prefix,
          service_manager, state_manager))) {}

void Barometer::Configure(ConfigJson cfg) {
  static_cast<Barometer::Impl*>(pimpl.get())->Configure(cfg);
}

void Barometer::Setup(const Kinematics& kin, const Environment& env) {
  static_cast<Barometer::Impl*>(pimpl.get())->Setup(kin, env);
}

void Barometer::StartUpdate() {
  static_cast<Barometer::Impl*>(pimpl.get())->StartUpdate();
}

void Barometer::Tick(const TimeNano sim_time, const TimeNano dt_nanos) {
  static_cast<Barometer::Impl*>(pimpl.get())->Tick(sim_time, dt_nanos);
}

BarometerMessage Barometer::FetchOutput() const {
  return static_cast<Barometer::Impl*>(pimpl.get())->FetchOutput();
}

void Barometer::FinishUpdate() {
