}

// --- Implementation details ---

Barometer::Impl::Impl(const std::string& identifier, bool enabled,
                      const std::string& parent_link,
                      const Logger& logger_ref,
                      const TopicManager& topic_mgr,
                      const std::string& topic_prefix,
                      const ServiceManager& service_mgr,
                      const StateManager& state_mgr)
    : SensorImpl(SensorType::kBarometer, identifier, enabled, parent_link,
                 Constant::Component::imu, logger_ref, topic_mgr, topic_prefix,
                 service_mgr, state_mgr),
      loader_(*this) {
  InitializeTopicPath();
  GenerateTopics();
}

void Barometer::Impl::Configure(ConfigJson cfg) {
  json config = cfg;
  loader_.Parse(config);
}

void Barometer::Impl::Setup(const Kinematics&, const Environment& environment) {
  truth_context_.env_ptr = &environment;

  pressure_drift_process_.Initialize(sensor_config_.pressure_drift_tau,
                                     sensor_config_.pressure_drift_sigma, 0.0f);

  independent_noise_ = RandomGeneratorGaussianF(
      0.0f, sensor_config_.white_noise_sigma);
}

void Barometer::Impl::GenerateTopics() {
  barometer_pub_topic_ = Topic("barometer", topic_path_, TopicType::kPublished,
                               100, MessageType::kBarometer);
  active_topics_.push_back(barometer_pub_topic_);
}

void Barometer::Impl::StartUpdate() {
  for (const auto& topic_ref : active_topics_) {
    topic_manager_.RegisterTopic(topic_ref.get());
  }
  SetupServiceEndpoint();
}

void Barometer::Impl::Tick(const TimeNano sim_time, const TimeNano delta_nanos) {
  std::lock_guard<std::mutex> guard(update_lock_);

  TimeSec elapsed = delta_nanos / 1.0e9;

  // Read ground truth values
  current_reading_.altitude_m = truth_context_.env_ptr->env_info.geo_point.altitude;
  current_reading_.pressure_pa =
      truth_context_.env_ptr->env_info.air_pressure;
  current_reading_.qnh_hpa = sensor_config_.qnh_reference;

  // Apply noise and drift
  InjectNoise(current_reading_, elapsed);
  current_reading_.timestamp = sim_time;

  // Construct message and publish
  BarometerMessage msg(current_reading_.timestamp,
                       current_reading_.altitude_m,
                       current_reading_.pressure_pa,
                       current_reading_.qnh_hpa);

  topic_manager_.PublishTopic(barometer_pub_topic_, static_cast<Message&>(msg));
}

BarometerMessage Barometer::Impl::FetchOutput() {
  return BarometerMessage(current_reading_.timestamp,
                          current_reading_.altitude_m,
                          current_reading_.pressure_pa,
                          current_reading_.qnh_hpa);
}

void Barometer::Impl::SetupServiceEndpoint() {
  std::string endpoint = topic_path_ + "/" + "barometer";
  ServiceMethod method(endpoint, {""});

  auto handler = method.CreateMethodHandler(
      &Barometer::Impl::FetchOutput, *this);

  service_manager_.RegisterMethod(method, handler);
}

void Barometer::Impl::InjectNoise(BarometerReading& reading, const TimeSec& dt) {
  // Update correlated drift component
  pressure_drift_process_.Update(dt);
  reading.pressure_pa += reading.pressure_pa * pressure_drift_process_.GetValue();

  // Add uncorrelated Gaussian noise
  reading.pressure_pa += independent_noise_.Next();

  // Convert to sea-level adjusted pressure
  reading.pressure_pa = reading.pressure_pa -
                        EarthUtils::kSeaLevelPressure +
                        reading.qnh_hpa * 100.0f;

  // Recompute altitude from corrected pressure
  reading.altitude_m = EarthUtils::GetPressureAltitude(reading.pressure_pa);
  reading.qnh_hpa = sensor_config_.qnh_reference;
}

void Barometer::Impl::FinishUpdate() {
  for (const auto& topic_ref : active_topics_) {
    topic_manager_.UnregisterTopic(topic_ref.get());
  }
}

// --- Loader implementation ---

Barometer::Loader::Loader(Barometer::Impl& ref_impl) : ref_impl_(ref_impl) {}

void Barometer::Loader::Parse(const json& config) {
  ref_impl_.logger_.LogVerbose(ref_impl_.name_, "[%s] Parsing 'barometer_settings'.",
                               ref_impl_.id_.c_str());
  ExtractBarometerParameters(config);
  ref_impl_.is_loaded_ = true;
  ref_impl_.logger_.LogVerbose(ref_impl_.name_, "[%s] 'barometer_settings' parsed.",
                               ref_impl_.id_.c_str());
}

void Barometer::Loader::ExtractBarometerParameters(const json& config) {
  // Load barometer configuration parameters
  ref_impl_.sensor_config_.qnh_reference =
      JsonUtils::GetNumber<float>(config, Constant::Config::qnh,
                                  ref_impl_.sensor_config_.qnh_reference);

  ref_impl_.sensor_config_.pressure_drift_sigma =
      JsonUtils::GetNumber<float>(config, Constant::Config::pressure_factor_sigma,
                                  ref_impl_.sensor_config_.pressure_drift_sigma);

  ref_impl_.sensor_config_.pressure_drift_tau =
      JsonUtils::GetNumber<float>(config, Constant::Config::pressure_factor_tau,
                                  ref_impl_.sensor_config_.pressure_drift_tau);

  ref_impl_.sensor_config_.white_noise_sigma =
      JsonUtils::GetNumber<float>(config, Constant::Config::uncorrelated_noise_sigma,
                                  ref_impl_.sensor_config_.white_noise_sigma);

  ref_impl_.sensor_config_.latency =
      JsonUtils::GetNumber<float>(config, Constant::Config::update_latency,
                                  ref_impl_.sensor_config_.latency);

  ref_impl_.sensor_config_.update_rate =
      JsonUtils::GetNumber<float>(config, Constant::Config::update_frequency,
                                  ref_impl_.sensor_config_.update_rate);

  ref_impl_.sensor_config_.startup_delay_sec =
      JsonUtils::GetNumber<float>(config, Constant::Config::startup_delay,
                                  ref_impl_.sensor_config_.startup_delay_sec);

  ref_impl_.logger_.LogVerbose(ref_impl_.name_, "Parsed Barometer settings");
}

