#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int T;
    if (!(cin >> T)) return 0;

    while (T--) {
        int n;
        if (!(cin >> n)) return 0;

        // Fixed excluded position (1-indexed)
        const int k = 1;
        cout << k << '\n';
        cout.flush();

        // Lambda to ask a query
        auto ask = [&](const vector<int>& q) -> int {
            cout << "?";
            for (int x : q) cout << ' ' << x;
            cout << '\n';
            cout.flush();

            int res;
            if (!(cin >> res)) exit(0);
            if (res == -1) exit(0);
            return res;
        };

        // Number of queries: capped at min(10*n, 200)
        int m = min(10 * n, 200);

        // Prepare base array [1..n]
        vector<int> base(n);
        iota(base.begin(), base.end(), 1);

        // Deterministic RNG seed based on n for reproducibility
        mt19937 rng(712367 + n * 239017);

        // Generate random permutations
        vector<vector<int>> perms(m, vector<int>(n));
        for (int t = 0; t < m; ++t) {
            perms[t] = base;
            shuffle(perms[t].begin(), perms[t].end(), rng);
        }

        // Precompute positions: pos[t][val] = index of val in perms[t]
        vector<vector<int>> pos(m, vector<int>(n + 1, 0));
        for (int t = 0; t < m; ++t) {
            for (int i = 0; i < n; ++i) {
                pos[t][perms[t][i]] = i;
            }
        }

        // Ask all queries and collect answers
        vector<int> answers(m);
        for (int t = 0; t < m; ++t) {
            answers[t] = ask(perms[t]);
        }

        // Build cost matrix: cost[i][j] = penalty if p[i+1] = j+1
        const int INF = 1e9;
        vector<vector<int>> cost(n, vector<int>(n, INF));

        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < n; ++j) {
                if (i == j) continue; // no fixed points

                int penalty = 0;
                for (int t = 0; t < m; ++t) {
                    int pi = pos[t][i + 1];
                    int pj = pos[t][j + 1];

                    // M_t(i+1, j+1) = 1 iff pi != (k-1) and pi < pj
                    int contribution = (pi != (k - 1) && pi < pj) ? 1 : 0;

                    // Penalize mismatch with observed answer
                    if (contribution == 1) {
                        penalty += (m - answers[t]);
                    } else {
                        penalty += answers[t];
                    }

                    if (penalty >= INF / 2) break;
                }
                cost[i][j] = penalty;
            }
        }

        // Solve assignment problem using Hungarian method (min-cost perfect matching)
        vector<int> u(n + 1), v(n + 1), p(n + 1), way(n + 1, 0);

        for (int i = 1; i <= n; ++i) {
            p[0] = i;
            int j0 = 0;
            vector<int> minv(n + 1, INF);
            vector<bool> used(n + 1, false);

            do {
                used[j0] = true;
                int i0 = p[j0], delta = INF, j1 = 0;

                for (int j = 1; j <= n; ++j) {
                    if (!used[j]) {
                        int cur = cost[i0 - 1][j - 1] - u[i0] - v[j];
                        if (cur < minv[j]) {
                            minv[j] = cur;
                            way[j] = j0;
                        }
                        if (minv[j] < delta) {
                            delta = minv[j];
                            j1 = j;
                        }
                    }
                }

                for (int j = 0; j <= n; ++j) {
                    if (used[j]) {
                        u[p[j]] += delta;
                        v[j] -= delta;
                    } else {
                        minv[j] -= delta;
                    }
                }

                j0 = j1;
            } while (p[j0] != 0);

            do {
                int j1 = way[j0];
                p[j0] = p[j1];
                j0 = j1;
            } while (j0);
        }

        // Reconstruct mapping: result[i] = value assigned to position i
        vector<int> result(n + 1);
        for (int j = 1; j <= n; ++j) {
            result[p[j]] = j;
        }

        // Fix any remaining fixed points by swapping
        vector<int> fixed_points;
        for (int i = 1; i <= n; ++i) {
            if (result[i] == i) fixed_points.push_back(i);
        }

        if (!fixed_points.empty()) {
            for (size_t idx = 0; idx < fixed_points.size(); ++idx) {
                int a = fixed_points[idx];
                int b = fixed_points[(idx + 1) % fixed_points.size()];
                swap(result[a], result[b]);
            }
        }

        // Output final permutation
        cout << "!";
        for (int i = 1; i <= n; ++i) {
            cout << ' ' << result[i];
        }
        cout << '\n';
        cout.flush();
    }

    return 0;
}

