using asio::local::stream_protocol;

// Define buffer size for communication
const int BUFFER_SIZE = 1024;

int main(int argc, char* argv[])
{
  try
  {
    // Validate command line arguments
    if (argc != 2)
    {
      std::cerr << "Usage: stream_client <socket_path>\n";
      return 1;
    }

    // Create I/O context and socket
    asio::io_context io_context;
    stream_protocol::socket socket(io_context);

    // Connect to the server using provided path
    socket.connect(stream_protocol::endpoint(argv[1]));

    // Prompt user for input message
    std::cout << "Enter message: ";
    char message_buffer[BUFFER_SIZE];
    std::cin.getline(message_buffer, BUFFER_SIZE);

    // Calculate actual message length
    size_t message_len = std::strlen(message_buffer);

    // Send the message to the server
    asio::write(socket, asio::buffer(message_buffer, message_len));

    // Prepare buffer for reply
    char reply_buffer[BUFFER_SIZE];

    // Read exactly message_len bytes from server
    size_t received_bytes = asio::read(socket,
        asio::buffer(reply_buffer, message_len));

    // Output the received reply
    std::cout << "Reply is: ";
    std::cout.write(reply_buffer, received_bytes);
    std::cout << "\n";
  }
  catch (const std::exception& exception)
  {
    std::cerr << "Error occurred: " << exception.what() << "\n";
    return 1;
  }

  return 0;
}
