const char* BENCHMARK_SUFFIX = ".benchmark";

BenchmarkRunner::BenchmarkRunner(const std::string& datasetPath,
    std::unique_ptr<BenchmarkConfig> config)
    : config{std::move(config)} {
    database = std::make_unique<Database>(
        datasetPath, 
        SystemConfig(this->config->bufferPoolSize, this->config->numThreads));
    spdlog::set_level(spdlog::level::debug);
}

void BenchmarkRunner::registerBenchmarks(const std::string& path) {
    if (std::filesystem::is_regular_file(path)) {
        registerSingleBenchmark(path);
    } else if (std::filesystem::is_directory(path)) {
        for (const auto& entry : std::filesystem::directory_iterator(path)) {
            registerSingleBenchmark(entry.path().string());
        }
    }
}

void BenchmarkRunner::runAllBenchmarks() {
    for (auto& benchPtr : benchmarks) {
        try {
            executeBenchmark(benchPtr.get()); // NOLINT(clang-analyzer-optin.cplusplus.UninitializedObject)
        } catch (const std::exception& e) {
            spdlog::error("Exception occurred during benchmark '{}': {}", benchPtr->name, e.what());
        }
    }
}

void BenchmarkRunner::registerSingleBenchmark(const std::string& filePath) {
    if (filePath.ends_with(BENCHMARK_SUFFIX)) {
        auto benchmark = std::make_unique<Benchmark>(filePath, database.get(), *config);
        spdlog::info("Loaded benchmark: {}", benchmark->name);
        benchmarks.emplace_back(std::move(benchmark));
    }
}

double BenchmarkRunner::computeAverageOfLastRuns(const double* timeArray, const int& totalLen,
    const int& countLastEntries) {
    double runningSum = 0.0;
    int startIndex = totalLen - countLastEntries;
    for (int idx = startIndex; idx < totalLen; ++idx) {
        runningSum += timeArray[idx];
    }
    return runningSum / static_cast<double>(countLastEntries);
}

void BenchmarkRunner::executeBenchmark(Benchmark* benchmark) const {
    spdlog::info(
        "Executing benchmark '{}' using {} thread(s)", // NOLINT(clang-analyzer-optin.cplusplus.UninitializedObject)
        benchmark->name, config->numThreads);

    if (!benchmark->preRun.empty()) {
        spdlog::info("Pre-execution step: {}", benchmark->preRun);
        benchmark->conn->query(benchmark->preRun);
    }

    for (size_t warmupIdx = 0; warmupIdx < config->numWarmups; ++warmupIdx) {
        spdlog::info("Warm-up iteration {}", warmupIdx + 1);
        benchmark->run();
    }

    if (config->enableProfile && !config->outputPath.empty()) {
        collectAndSaveProfilingData(benchmark);
    }

    std::vector<double> executionTimes(config->numRuns);
    for (size_t runIdx = 0; runIdx < config->numRuns; ++runIdx) {
        auto result = benchmark->run();
        benchmark->log(runIdx + 1, *result);
        executionTimes[runIdx] = result->getQuerySummary()->getExecutionTime();
    }

    spdlog::info("Average execution time (last {} runs): {:.3f} ms", config->numRuns,
        computeAverageOfLastRuns(executionTimes.data(), config->numRuns, config->numRuns));

    if (!benchmark->postRun.empty()) {
        spdlog::info("Post-execution step: {}", benchmark->postRun);
        benchmark->conn->query(benchmark->postRun);
    }
}

void BenchmarkRunner::collectAndSaveProfilingData(Benchmark* benchmark) const {
    auto profileResult = benchmark->runWithProfile();
    std::ofstream profileStream(config->outputPath + "/" + benchmark->name + "_profile.txt",
        std::ios_base::app);
    if (profileStream.is_open()) {
        profileStream << profileResult->getNext()->toString() << '\n';
        profileStream.flush();
    }
    profileStream.close();
}

