#include <vector>
#include <queue>
using namespace std;

class Solution {
public:
    vector<int> maxSlidingWindow(vector<int>& nums, int windowSize) {
        vector<int> output;
        priority_queue<pair<int, int>> pq; // max-heap storing {value, index}

        // Initialize with the first window
        for (int idx = 0; idx < windowSize; ++idx) {
            pq.push({nums[idx], idx});
        }

        // Record maximum of first window
        output.push_back(pq.top().first);

        // Process remaining elements
        for (int right = windowSize; right < nums.size(); ++right) {
            // Add new element to heap
            pq.push({nums[right], right});

            // Remove outdated elements (outside current window)
            while (!pq.empty() && pq.top().second <= right - windowSize) {
                pq.pop();
            }

            // Current maximum is at top of heap
            output.push_back(pq.top().first);
        }

        return output;
    }
};

