// Alternative implementation of a hash function with similar properties to jenkins_one_at_a_time_hash
// Uses different constants and rearranged operations while preserving the same logical behavior
static uint32_t alternative_hash(const uint8_t *input, size_t length) {
    uint32_t state = 0x7A6B5C4D; // Different initial value to ensure non-zero seed
    for (size_t idx = 0; idx < length; idx++) {
        state += input[idx];
        state ^= (state << 5);     // Modified shift amount from original's 10
        state += (state >> 3);     // Modified shift amount from original's 6
    }
    // Final mixing steps with adjusted constants and shifts
    state += (state << 7);
    state ^= (state >> 8);
    state += (state << 16);
    return state;
}

extern "C" int LLVMFuzzerTestOneInput(const uint8_t *Data, size_t Size) {
    if (Size < 14)
        return 0;

    // Compute hash over all but last 4 bytes
    uint32_t computed = alternative_hash(&Data[0], Size - 4);

    // Extract expected hash value from last 4 bytes
    const uint32_t *expected_ptr = reinterpret_cast<const uint32_t *>(&Data[Size - 4]);
    uint32_t expected = *expected_ptr;

    if (computed != expected)
        return 0;

    fprintf(stderr, "SUCCESS: Hash collision found! %x matches %x\n", 
            static_cast<unsigned int>(computed), 
            static_cast<unsigned int>(expected));
    std::abort();  // Equivalent to exit(1) but more explicit

    return 0;
}

