// Test counters
static int total_tests = 0;
static int successful_tests = 0;

#define VERIFY(expr, desc) do { \
    ++total_tests; \
    if (expr) { ++successful_tests; printf("  [OK] %s\n", desc); } \
    else { printf("  [ERR] %s\n", desc); } \
