// Convert hex string to byte array
static void parse_hex(const char* hex_input, uint8_t* output, size_t bytes_count) {
    for (size_t idx = 0; idx < bytes_count; ++idx) {
        unsigned int val = 0;
#ifdef __clang__
#pragma clang diagnostic push
#pragma clang diagnostic ignored "-Wdeprecated-declarations"
#endif
        // NOLINTNEXTLINE(cert-err34-c)
        if (sscanf(hex_input + idx * 2, "%02x", &val) != 1) val = 0;
#ifdef __clang__
#pragma clang diagnostic pop
#endif
        output[idx] = static_cast<uint8_t>(val);
    }
}

// -- HMAC-SHA512 Validation --------------------------------------------------
static void validate_hmac_sha512() {
    printf("\n--- HMAC-SHA512 Verification ---\n");
    const char* key_text = "Jefe";
    const char* message_text = "what do ya want for nothing?";

    auto hmac_result = hmac_sha512(
        reinterpret_cast<const uint8_t*>(key_text), 4,
        reinterpret_cast<const uint8_t*>(message_text), 28);

    uint8_t reference[64];
    parse_hex("164b7a7bfcf819e2e395fbe73b56e0a387bd64222e831fd610270cd7ea250554"
              "9758bf75c05a994a6d034f65f8f0e6fdcaeab1a34d4a6b4b636e070a38bce737",
              reference, 64);

    VERIFY(std::memcmp(hmac_result.data(), reference, 64) == 0,
           "RFC 4231 Test Case 2: HMAC-SHA512 matches expected value");
}

// -- BIP-32 Master Key Generation -------------------------------------------
static void validate_master_key_generation() {
    printf("\n--- BIP-32 Master Key Generation ---\n");
    uint8_t entropy[16];
    parse_hex("000102030405060708090a0b0c0d0e0f", entropy, 16);

    auto [root_key, success] = bip32_master_key(entropy, 16);
    VERIFY(success, "Master key creation succeeded");
    VERIFY(root_key.is_private, "Root key is private");
    VERIFY(root_key.depth == 0, "Root key depth is zero");

    uint8_t expected_chain[32];
    parse_hex("873dff81c02f525623fd1fe5167eac3a55a049de3d314bb42ee227ffed37d508",
              expected_chain, 32);
    VERIFY(std::memcmp(root_key.chain_code.data(), expected_chain, 32) == 0,
           "Master chain code matches BIP-32 test vector 1");

    uint8_t expected_privkey[32];
    parse_hex("e8f32e723decf4051aefac8e2c93c9c5b214313817cdb01a1494b917c8436b35",
              expected_privkey, 32);
    VERIFY(std::memcmp(root_key.key.data(), expected_privkey, 32) == 0,
           "Master private key matches BIP-32 test vector 1");
}

// -- BIP-32 Child Key Derivation --------------------------------------------
static void validate_child_derivation() {
    printf("\n--- BIP-32 Child Key Derivation ---\n");
    uint8_t seed_data[16];
    parse_hex("000102030405060708090a0b0c0d0e0f", seed_data, 16);

    auto [master, ok_init] = bip32_master_key(seed_data, 16);
    VERIFY(ok_init, "Initial master key valid for derivation tests");

    auto [hardened_child, ok_hard] = master.derive_hardened(0);
    VERIFY(ok_hard, "Hardened derivation m/0' succeeded");
    VERIFY(hardened_child.depth == 1, "m/0' has depth 1");
    VERIFY(hardened_child.is_private, "m/0' remains private");

    uint8_t expected_cc_child[32];
    parse_hex("47fdacbd0f1097043b78c63c20c34ef4ed9a111d980047ad16282c7ae6236141",
              expected_cc_child, 32);
    VERIFY(std::memcmp(hardened_child.chain_code.data(), expected_cc_child, 32) == 0,
           "m/0' chain code matches BIP-32 test vector");

    auto public_key = hardened_child.to_public();
    VERIFY(!public_key.is_private, "to_public() yields public key");

    auto [normal_child, ok_norm] = hardened_child.derive_normal(1);
    VERIFY(ok_norm, "Normal derivation m/0'/1 succeeded");
    VERIFY(normal_child.depth == 2, "m/0'/1 has depth 2");
}

// -- BIP-32 Path-based Derivation -------------------------------------------
static void validate_path_derivation() {
    printf("\n--- BIP-32 Path Derivation ---\n");
    uint8_t seed_bytes[16];
    parse_hex("000102030405060708090a0b0c0d0e0f", seed_bytes, 16);

    auto [root, ok_root] = bip32_master_key(seed_bytes, 16);
    VERIFY(ok_root, "Root key ready for path derivation");

    auto [path_key, ok_path] = bip32_derive_path(root, "m/0'/1");
    VERIFY(ok_path, "Path 'm/0'/1' derived successfully");
    VERIFY(path_key.depth == 2, "Path 'm/0'/1' depth equals 2");

    auto [deep_key, ok_deep] = bip32_derive_path(root, "m/0'/1/2'");
    VERIFY(ok_deep, "Deep path 'm/0'/1/2'' derived successfully");
    VERIFY(deep_key.depth == 3, "Path 'm/0'/1/2'' depth equals 3");

    auto [empty_res, ok_empty] = bip32_derive_path(root, "");
    (void)empty_res;
    VERIFY(!ok_empty, "Empty path correctly rejected");

    auto [invalid_res, ok_invalid] = bip32_derive_path(root, "x/0");
    (void)invalid_res;
    VERIFY(!ok_invalid, "Invalid path prefix 'x/' correctly rejected");
}

// -- Serialization Checks ----------------------------------------------------
static void validate_serialization() {
    printf("\n--- BIP-32 Serialization ---\n");
    uint8_t init_seed[16];
    parse_hex("000102030405060708090a0b0c0d0e0f", init_seed, 16);

    auto [root, _] = bip32_master_key(init_seed, 16);
    (void)_;

    auto serialized = root.serialize();
    VERIFY(serialized.size() == 78, "Serialized format length is 78 bytes");

    // xprv version bytes: 0x0488ADE4
    VERIFY(serialized[0] == 0x04 && serialized[1] == 0x88 &&
           serialized[2] == 0xAD && serialized[3] == 0xE4,
           "Version bytes indicate xprv");

    VERIFY(serialized[4] == 0, "Serialized depth field is zero");

    auto fp = root.fingerprint();
    (void)fp;
    VERIFY(fp.size() == 4, "Fingerprint length is 4 bytes");
}

// -- Seed Length Validation --------------------------------------------------
static void validate_seed_requirements() {
    printf("\n--- BIP-32 Seed Validation ---\n");
    uint8_t short_entropy[8] = {1,2,3,4,5,6,7,8};
    auto [_, ok_short] = bip32_master_key(short_entropy, 8);
    (void)_;
    VERIFY(!ok_short, "Short seed (<16 bytes) correctly rejected");

    uint8_t valid_16[16];
    for (int i = 0; i < 16; ++i) valid_16[i] = static_cast<uint8_t>(i + 1);
    auto [key16, ok16] = bip32_master_key(valid_16, 16);
    (void)key16;
    VERIFY(ok16, "Valid 16-byte seed accepted");

    uint8_t long_64[64];
    for (int i = 0; i < 64; ++i) long_64[i] = static_cast<uint8_t>(i + 1);
    auto [key64, ok64] = bip32_master_key(long_64, 64);
    (void)key64;
    VERIFY(ok64, "Valid 64-byte seed accepted");
}

// -- Main Entry Point --------------------------------------------------------
int test_bip32_run() {
    printf("=== HD Wallet (BIP-32) Compliance Tests ===\n");
    validate_hmac_sha512();
    validate_master_key_generation();
    validate_child_derivation();
    validate_path_derivation();
    validate_serialization();
    validate_seed_requirements();

    printf("\n=== Summary: %d/%d tests passed ===\n", successful_tests, total_tests);
    return (successful_tests == total_tests) ? 0 : 1;
}

