#include <iostream>
#include <vector>
#include <string>

int main() {
    // Grid dimensions
    int rows = 20;
    int cols = 20;

    // Output grid size
    std::cout << rows << " " << cols << std::endl;

    // Initialize the grid with walls ('0')
    std::vector<std::string> maze(rows, std::string(cols, '0'));

    // Create horizontal corridors on even-numbered rows (0, 2, ..., 18)
    for (int r = 0; r < rows - 1; r += 2) {
        for (int c = 0; c < cols; ++c) {
            maze[r][c] = '1';
        }
    }

    // Add vertical connectors between consecutive corridors
    // Alternate connection points: right side for even corridor pairs, left side for odd ones
    for (int r = 0; r < rows - 2; r += 2) {
        if ((r / 2) % 2 == 0) {
            // Connect to the rightmost column
            maze[r + 1][cols - 1] = '1';
        } else {
            // Connect to the leftmost column
            maze[r + 1][0] = '1';
        }
    }

    // Add terminal nodes (dead ends) in the last row (row 19)
    // Attach them only at even column indices to avoid creating cycles
    for (int c = 0; c < cols; c += 2) {
        maze[rows - 1][c] = '1';
    }

    // Display the resulting maze/grid
    for (int i = 0; i < rows; ++i) {
        std::cout << maze[i] << std::endl;
    }

    return 0;
}

