RenderIndexProxy::RenderIndexProxy(const std::string& rendererName, HdDriver* hgiDriver)
{
    // Initialize settings map for renderer configuration
    HdRenderSettingsMap configMap;

#ifdef ADSK_OPENUSD_PENDING
    // Attempt to extract HGI instance from driver if available
    Hgi* gpuBackend = nullptr;
    if (hgiDriver != nullptr)
    {
        gpuBackend = hgiDriver->driver.GetWithDefault<Hgi*>();
    }

    // Special handling for Hgi-based render driver
    if (gpuBackend && (hgiDriver->name == HgiTokens->renderDriver))
    {
        HdRendererCreateArgs initArgs;
        initArgs.hgi = gpuBackend;
        initArgs.gpuEnabled = true;
        configMap.emplace(TfToken{"rendererCreateArgs"}, VtValue{initArgs});
    }
#endif

    // Acquire renderer plugin registry and instantiate delegate
    HdRendererPluginRegistry& pluginRegistry = HdRendererPluginRegistry::GetInstance();
    _renderDelegate = pluginRegistry.CreateRenderDelegate(TfToken(rendererName), configMap);

    // Construct render index using the created delegate and driver
    if (_renderDelegate)
    {
        _renderIndex = HdRenderIndex::New(_renderDelegate.Get(), { hgiDriver });
    }
}

RenderIndexProxy::~RenderIndexProxy()
{
    // Ensure proper cleanup of GPU/CPU resources before destruction
    if (_renderDelegate)
    {
        // Try casting to Storm-specific resource registry
        auto stormRegistry =
            dynamic_cast<HdStResourceRegistry*>(_renderDelegate->GetResourceRegistry().get());

        if (stormRegistry)
        {
            // Perform targeted cleanup for Storm's internal buffer management
            stormRegistry->GarbageCollectDispatchBuffers();
            stormRegistry->GarbageCollectBufferResources();
        }
        else
        {
            // Fallback generic garbage collection for other render delegates
            _renderDelegate->GetResourceRegistry()->GarbageCollect();
        }
    }

    // Optional debug output: print current registry state
    // #define DUMP_RESOURCE_STATS
#ifdef DUMP_RESOURCE_STATS
    if (_renderDelegate)
    {
        auto regPtr =
            dynamic_cast<HdStResourceRegistry*>(_renderDelegate->GetResourceRegistry().get());
        if (regPtr)
        {
            auto allocInfo = regPtr->GetResourceAllocation();
            std::cerr << "Current HdStResourceRegistry allocation:\n";
            for (const auto& [key, val] : allocInfo)
            {
                std::cerr << "  [" << key.GetString() << "] => " << val << "\n";
            }
        }
    }
#endif

    // Explicitly nullify members in correct order to avoid dangling references
    _renderIndex.reset();
    _renderDelegate.reset();
}

