UGeometryCollectionCache* FTargetCacheProviderEditor::GetCacheForCollection(const UGeometryCollection* InCollection)
{
	// Locate the package containing the input geometry collection
	UPackage* CollectionPackage = InCollection->GetOutermost();
	check(CollectionPackage);

	// Load the AssetTools module for asset creation operations
	FAssetToolsModule& AssetToolsModule = FModuleManager::LoadModuleChecked<FAssetToolsModule>("AssetTools");

	// Prepare variables for generating a unique asset name
	FString PackagePath;
	FString AssetShortName;

	// Generate a unique name by appending "_Cache" to the collection's package path
	AssetToolsModule.Get().CreateUniqueAssetName(CollectionPackage->GetName(), TEXT("_Cache"), PackagePath, AssetShortName);

	// Create the new cache asset in the same directory as the collection
	UObject* CreatedCacheObject = AssetToolsModule.Get().CreateAsset(
		AssetShortName, 
		FPackageName::GetLongPackagePath(PackagePath), 
		UGeometryCollectionCache::StaticClass(), 
		nullptr
	);

	// Cast and return the newly created object as a GeometryCollectionCache
	return CastChecked<UGeometryCollectionCache>(CreatedCacheObject);
}

