// Base abstract interface A
struct InterfaceA {
  virtual void performActionA() = 0;
};

// Base abstract interface B
struct InterfaceB {
  virtual void performActionB() = 0;
};

// Concrete implementation combining both interfaces
struct CombinedImpl : InterfaceA, InterfaceB {
  void performActionA() override {}
  void performActionB() override {}
};

// Base class with default behavior
struct BaseC {
  virtual void executeActionC() {}
};

// Final concrete class inheriting from BaseC and CombinedImpl
struct FullImpl : BaseC, CombinedImpl {
  void performActionA() override {}
  void performActionB() override {}
  void executeActionC() override {}
};

// Function accepting InterfaceA reference
void invokeA(InterfaceA &a) {
  a.performActionA();
}

// Function accepting InterfaceB reference
void invokeB(InterfaceB &b) {
  b.performActionB();
}

// Function accepting BaseC reference
void invokeC(BaseC &c) {
  c.executeActionC();
}

int main() {
  FullImpl full;
  invokeA(full);
  invokeB(full);
  invokeC(full);
}

