using LD = long double;
const LD PI = acosl(-1.0L);

struct Point {
    LD x, y, z;
};

Point operator+(const Point& a, const Point& b) { 
    return {a.x + b.x, a.y + b.y, a.z + b.z}; 
}

Point& operator+=(Point& a, const Point& b) { 
    a.x += b.x; 
    a.y += b.y; 
    a.z += b.z; 
    return a; 
}

Point operator-(const Point& a, const Point& b) { 
    return {a.x - b.x, a.y - b.y, a.z - b.z}; 
}

Point& operator-=(Point& a, const Point& b) { 
    a.x -= b.x; 
    a.y -= b.y; 
    a.z -= b.z; 
    return a; 
}

Point operator*(const Point& a, LD s) { 
    return {a.x * s, a.y * s, a.z * s}; 
}

LD norm_sq(const Point& a) { 
    return a.x * a.x + a.y * a.y + a.z * a.z; 
}

void normalize(Point& a) {
    LD mag = sqrt(norm_sq(a));
    if (mag > 1e-12L) {
        a.x /= mag;
        a.y /= mag;
        a.z /= mag;
    }
}

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int n;
    std::cin >> n;

    // Special case for n=2
    if (n == 2) {
        std::cout << std::fixed << std::setprecision(15) << 2.0L << "\n";
        std::cout << "0.0 0.0 1.0\n";
        std::cout << "0.0 0.0 -1.0\n";
        return 0;
    }

    std::vector<Point> points(n);
    const LD GOLDEN_RATIO = (1.0L + sqrtl(5.0L)) / 2.0L;

    // Initialize points using Fibonacci lattice
    for (int i = 0; i < n; ++i) {
        LD z = 1.0L - (2.0L * (i + 0.5L)) / n;
        LD radius = sqrtl(1.0L - z * z);
        LD theta = 2.0L * PI * (i + 0.5L) / GOLDEN_RATIO;
        points[i] = {cosl(theta) * radius, sinl(theta) * radius, z};
    }

    // Calculate number of iterations based on problem size
    int max_iter = static_cast<int>(150000000.0L / (n * n) + 1);
    int iterations = std::min(15000, max_iter);

    // Gradient descent parameters with exponential decay
    LD alpha_start = 0.2L;
    LD alpha_end = 1e-5L;
    LD decay_rate = powl(alpha_end / alpha_start, 1.0L / iterations);
    LD alpha = alpha_start;

    // Optimization loop
    for (int step = 0; step < iterations; ++step) {
        std::vector<Point> gradients(n, {0, 0, 0});

        // Compute pairwise forces
        for (int idx1 = 0; idx1 < n; ++idx1) {
            for (int idx2 = idx1 + 1; idx2 < n; ++idx2) {
                Point diff_vec = points[idx1] - points[idx2];
                LD dist_sq = norm_sq(diff_vec);
                if (dist_sq < 1e-14L) dist_sq = 1e-14L;

                LD inv_dist_sq = 1.0L / dist_sq;
                LD inv_dist_fourth = inv_dist_sq * inv_dist_sq;

                Point repulsion = diff_vec * inv_dist_fourth;
                gradients[idx1] += repulsion;
                gradients[idx2] -= repulsion;
            }
        }

        // Update positions and re-normalize to unit sphere
        for (int idx = 0; idx < n; ++idx) {
            points[idx] += gradients[idx] * alpha;
            normalize(points[idx]);
        }

        // Apply learning rate decay
        alpha *= decay_rate;
    }

    // Find minimum squared distance between any pair
    LD min_dist_sq = 100.0L;
    for (int i = 0; i < n; ++i) {
        for (int j = i + 1; j < n; ++j) {
            LD current_dist_sq = norm_sq(points[i] - points[j]);
            min_dist_sq = std::min(min_dist_sq, current_dist_sq);
        }
    }

    // Output results
    std::cout << std::fixed << std::setprecision(15);
    std::cout << sqrtl(min_dist_sq) << "\n";

    for (int i = 0; i < n; ++i) {
        std::cout << points[i].x << " " << points[i].y << " " << points[i].z << "\n";
    }

    return 0;
}

