// State disabling/enabling via helper function to reduce duplication
namespace {
    struct StateSwitch {
        int flag;
        bool enable;
        void (*action)(bool);
    };

    void setBlend(bool v) { RenderManager.StateSetBlendEnable(v); }
    void setCull(bool v) { RenderManager.StateSetFaceCull(v); }
    void setDepthTest(bool v) { RenderManager.StateSetDepthTestEnable(v); }
    void setAlphaTest(bool v) { RenderManager.StateSetAlphaTestEnable(v); }
    void setFog(bool v) { RenderManager.StateSetFogEnable(v); }
    void setLighting(bool v) { RenderManager.StateSetLightingEnable(v); }

    void setLight(int idx, bool v) { RenderManager.StateSetLightEnable(idx, v); }

    const StateSwitch disableMap[] = {
        {GL_TEXTURE_2D, false, nullptr},
        {GL_BLEND, false, setBlend},
        {GL_CULL_FACE, false, setCull},
        {GL_DEPTH_TEST, false, setDepthTest},
        {GL_ALPHA_TEST, false, setAlphaTest},
        {GL_FOG, false, setFog},
        {GL_LIGHTING, false, setLighting},
        {GL_LIGHT0, false, [] (bool) { setLight(0, false); }},
        {GL_LIGHT1, false, [] (bool) { setLight(1, false); }}
    };

    const StateSwitch enableMap[] = {
        {GL_BLEND, true, setBlend},
        {GL_CULL_FACE, true, setCull},
        {GL_DEPTH_TEST, true, setDepthTest},
        {GL_ALPHA_TEST, true, setAlphaTest},
        {GL_FOG, true, setFog},
        {GL_LIGHTING, true, setLighting},
        {GL_LIGHT0, true, [] (bool) { setLight(0, true); }},
        {GL_LIGHT1, true, [] (bool) { setLight(1, true); }}
    };

    void applyStateChange(const StateSwitch* table, size_t size, int state, bool enabled) {
        for (size_t i = 0; i < size; ++i) {
            if (table[i].flag == state) {
                if (table[i].action) {
                    table[i].action(enabled);
                } else if (state == GL_TEXTURE_2D) {
                    RenderManager.TextureBind(-1);
                }
                break;
            }
        }
    }
}

void glDisable(int state) {
    applyStateChange(disableMap, std::size(disableMap), state, false);
}

void glEnable(int state) {
    applyStateChange(enableMap, std::size(enableMap), state, true);
}

