// Lighting
void glLight(int lightIdx, int mode, FloatBuffer* values) {
    int realIdx = -1;
    if (lightIdx == GL_LIGHT0) realIdx = 0;
    else if (lightIdx == GL_LIGHT1) realIdx = 1;
    else return;

    float* data = values->_getDataPointer();
    switch (mode) {
        case GL_POSITION:
            RenderManager.StateSetLightDirection(realIdx, data[0], data[1], data[2]);
            break;
        case GL_DIFFUSE:
            RenderManager.StateSetLightColour(realIdx, data[0], data[1], data[2]);
            break;
        case GL_AMBIENT:
        case GL_SPECULAR:
        default:
            break;
    }
}

