#include <iostream>
#include <vector>
#include <cmath>
#include <random>

// Type III clone: Modified logic using different approach to compute same result
using u64 = unsigned long long;

u64 n_val; // Renamed global variable

// Function to compute bit-length of (x+1), equivalent to ceil(log2(x+1))
int get_bit_length(u64 x) {
    if (x == 0) return 0;
    // Use built-in function for leading zeros, but handle edge case for zero
    return 64 - __builtin_clzll(x);
}

// Modular multiplication avoiding overflow via 128-bit intermediate
u64 mod_mul(u64 a, u64 b) {
    unsigned __int128 res = static_cast<unsigned __int128>(a) * b;
    return static_cast<u64>(res % n_val);
}

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    std::cin >> n_val;

    const int NUM_SAMPLES = 24000;
    std::vector<u64> base_vals(NUM_SAMPLES);
    std::vector<long long> observed_vals(NUM_SAMPLES);

    // Seeded RNG for reproducibility
    std::mt19937_64 rng_engine(std::random_device{}());
    std::uniform_int_distribution<u64> dist(2, n_val - 1);

    // Pre-query phase: collect all inputs first
    for (int idx = 0; idx < NUM_SAMPLES; ++idx) {
        base_vals[idx] = dist(rng_engine);
        std::cout << "? " << base_vals[idx] << "\n";
        std::cin >> observed_vals[idx];
    }

    // Precompute powers and bit contributions per sample
    std::vector<std::vector<u64>> power_table(NUM_SAMPLES, std::vector<u64>(60));
    std::vector<std::vector<int>> bit_contribs(NUM_SAMPLES, std::vector<int>(60));
    std::vector<long long> initial_sum(NUM_SAMPLES, 0);

    for (int s = 0; s < NUM_SAMPLES; ++s) {
        u64 cur = base_vals[s];
        for (int p = 0; p < 60; ++p) {
            power_table[s][p] = cur;
            int blen = get_bit_length(cur);
            bit_contribs[s][p] = blen + 1;
            initial_sum[s] += static_cast<long long>(bit_contribs[s][p]) * bit_contribs[s][p];
            cur = mod_mul(cur, cur);
        }
    }

    u64 secret_d = 0;
    std::vector<u64> running_r(NUM_SAMPLES, 1ULL);
    std::vector<long long> accumulated_c(NUM_SAMPLES, 0LL);

    // Reconstruct d bit-by-bit from LSB to MSB
    for (int bit_pos = 0; bit_pos < 60; ++bit_pos) {
        long double sum_y_times_v = 0.0L;
        long double sum_v_squared = 0.0L;

        for (int s = 0; s < NUM_SAMPLES; ++s) {
            long long residual = observed_vals[s] - initial_sum[s] - accumulated_c[s];
            int v_val = bit_contribs[s][bit_pos] * (get_bit_length(running_r[s]) + 1);
            sum_y_times_v += static_cast<long double>(residual) * v_val;
            sum_v_squared += static_cast<long double>(v_val) * v_val;
        }

        long double beta_estimate = 0.0L;
        if (sum_v_squared > 1e-12) {
            beta_estimate = sum_y_times_v / sum_v_squared;
        }

        int current_bit = (beta_estimate > 0.5L) ? 1 : 0;

        if (current_bit) {
            secret_d |= (1ULL << bit_pos);
        }

        if (bit_pos < 59) {
            if (current_bit) {
                for (int s = 0; s < NUM_SAMPLES; ++s) {
                    accumulated_c[s] += static_cast<long long>(bit_contribs[s][bit_pos]) *
                                        (get_bit_length(running_r[s]) + 1);
                    running_r[s] = mod_mul(running_r[s], power_table[s][bit_pos]);
                }
            }
        }
    }

    std::cout << "! " << secret_d << "\n";
    return 0;
}

