#include "RHIBufferTests.h"

// Reads buffer data from GPU to CPU using staging resources and validates via callback for vertex buffers
bool FRHIBufferTests::VerifyBufferContents(const TCHAR* TestName, FRHICommandListImmediate& RHICmdList, FRHIVertexBuffer* Buffer, TFunctionRef<bool(void* Ptr, uint32 NumBytes)> VerifyCallback)
{
	bool bSuccess = false;
	{
		const uint32 DataSize = Buffer->GetSize();
		FStagingBufferRHIRef StagingResource = RHICreateStagingBuffer();

		RHICmdList.CopyBufferToStaging(Buffer, StagingResource, 0u, DataSize);
		RHICmdList.SubmitCommandsAndFlushGPU();
		RHICmdList.WaitOnGPUIdle();

		void* CpuAccessPtr = RHILockStagingBuffer(StagingResource, 0u, DataSize);
		bSuccess = VerifyCallback(CpuAccessPtr, DataSize);
		RHIUnlockStagingBuffer(StagingResource);
	}

	RHICmdList.ImmediateFlush(EImmediateFlushType::FlushRHIThreadFlushResourcesFlushDeferredDeletes);

	if (!bSuccess)
	{
		UE_LOG(LogRHIUnitTestCommandlet, Error, TEXT("Verification failed: \"%s\""), TestName);
	}
	else
	{
		UE_LOG(LogRHIUnitTestCommandlet, Display, TEXT("Verification succeeded: \"%s\""), TestName);
	}
	return bSuccess;
}

// Reads structured buffer data directly and validates via callback (no staging buffer needed)
bool FRHIBufferTests::VerifyBufferContents(const TCHAR* TestName, FRHICommandListImmediate& RHICmdList, FRHIStructuredBuffer* Buffer, TFunctionRef<bool(void* Ptr, uint32 NumBytes)> VerifyCallback)
{
	bool bSuccess = false;
	{
		const uint32 TotalBytes = Buffer->GetSize();

		RHICmdList.ImmediateFlush(EImmediateFlushType::FlushRHIThreadFlushResourcesFlushDeferredDeletes);

		void* LockedData = RHICmdList.LockStructuredBuffer(Buffer, 0u, TotalBytes, EResourceLockMode::RLM_ReadOnly);
		bSuccess = VerifyCallback(LockedData, TotalBytes);
		RHICmdList.UnlockStructuredBuffer(Buffer);
	}

	RHICmdList.ImmediateFlush(EImmediateFlushType::FlushRHIThreadFlushResourcesFlushDeferredDeletes);

	if (!bSuccess)
	{
		UE_LOG(LogRHIUnitTestCommandlet, Error, TEXT("Structured buffer test failed: \"%s\""), TestName);
	}
	else
	{
		UE_LOG(LogRHIUnitTestCommandlet, Display, TEXT("Structured buffer test passed: \"%s\""), TestName);
	}
	return bSuccess;
}

#include "llvm/Transforms/Coroutines/CoroConditionalWrapper.h"
