/*----------------------------------------------------------------------------------------------------------------------
|	Initializes member variables: sets taxon count to zero and block identifier to "TAXA".
*/
NxsTaxaBlock::NxsTaxaBlock()
  : NxsBlock()
{
	m_numTaxa = 0;
	blockName = "TAXA";
}

/*----------------------------------------------------------------------------------------------------------------------
|	Destructor cleans up stored taxon labels.
*/
NxsTaxaBlock::~NxsTaxaBlock()
{
	taxonNames.clear();
}

/*----------------------------------------------------------------------------------------------------------------------
|	Parses the TAXA block content from input stream via tokenization. Handles DIMENSIONS, TAXLABELS, END/ENDBLOCK,
|	and unknown commands.
*/
void NxsTaxaBlock::Read(
  NxsToken &token)	// token used for lexical analysis
{
	m_numTaxa = 0;
	int expectedNumTaxa = 0;
	isEmptyFlag = false;
	userProvidedData = true;

	// Expect semicolon after block name
	token.GetNextToken();
	if (!token.Equals(";")) 
	{
		errormsg = "Expected ';' after TAXA block name, but found ";
		errormsg += token.GetToken();
		errormsg += " instead";
		throw NxsException(errormsg, token.GetFilePosition(), token.GetFileLine(), token.GetFileColumn());
	}

	for (;;)
	{
		token.GetNextToken();

		if (token.Equals("DIMENSIONS"))
		{
			token.GetNextToken(); // skip 'NTAX'
			if (!token.Equals("NTAX"))
			{
				errormsg = "Expected NTAX keyword, but found ";
				errormsg += token.GetToken();
				errormsg += " instead";
				throw NxsException(errormsg, token.GetFilePosition(), token.GetFileLine(), token.GetFileColumn());
			}

			token.GetNextToken(); // skip '='
			if (!token.Equals("=")) 
			{
				errormsg = "Expected '=', but found ";
				errormsg += token.GetToken();
				errormsg += " instead";
				throw NxsException(errormsg, token.GetFilePosition(), token.GetFileLine(), token.GetFileColumn());
			}

			token.GetNextToken(); // read number
			expectedNumTaxa = std::stoi(token.GetToken());
			if (expectedNumTaxa <= 0)
			{
				errormsg = "NTAX must be positive (";
				errormsg += token.GetToken();
				errormsg += " was given)";
				throw NxsException(errormsg, token.GetFilePosition(), token.GetFileLine(), token.GetFileColumn());
			}

			token.GetNextToken(); // expect ';'
			if (!token.Equals(";"))
			{
				errormsg = "Expected ';' to end DIMENSIONS command, but found ";
				errormsg += token.GetToken();
				errormsg += " instead";
				throw NxsException(errormsg, token.GetFilePosition(), token.GetFileLine(), token.GetFileColumn());
			}
		}
		else if (token.Equals("TAXLABELS"))
		{
			if (expectedNumTaxa <= 0)
			{
				errormsg = "NTAX must be defined before TAXLABELS";
				throw NxsException(errormsg, token.GetFilePosition(), token.GetFileLine(), token.GetFileColumn());
			}

			int count = 0;
			while (count < expectedNumTaxa)
			{
				token.SetLabileFlagBit(NxsToken::hyphenNotPunctuation + NxsToken::preserveUnderscores);
				token.GetNextToken();
				AddTaxonLabel(token.GetToken());
				count++;
			}

			token.GetNextToken(); // consume trailing ';'
			if (!token.Equals(";"))
			{
				errormsg = "Expected ';' after TAXLABELS list, but found ";
				errormsg += token.GetToken();
				errormsg += " instead";
				throw NxsException(errormsg, token.GetFilePosition(), token.GetFileLine(), token.GetFileColumn());
			}
		}
		else if (token.Equals("END") || token.Equals("ENDBLOCK"))
		{
			token.GetNextToken(); // get ';'
			if (!token.Equals(";"))
			{
				errormsg = "Expected ';' after ENDBLOCK, but found ";
				errormsg += token.GetToken();
				errormsg += " instead";
				throw NxsException(errormsg, token.GetFilePosition(), token.GetFileLine(), token.GetFileColumn());
			}
			break;
		}
		else
		{
			SkippingCommand(token.GetToken());
			do
			{
				token.GetNextToken();
			} while (!token.AtEOF() && !token.Equals(";"));

			if (token.AtEOF())
			{
				errormsg = "Unexpected end of file encountered";
				throw NxsException(errormsg, token.GetFilePosition(), token.GetFileLine(), token.GetFileColumn());
			}
		}
	}
}

/*----------------------------------------------------------------------------------------------------------------------
|	Writes summary of taxa block contents to output stream.
*/
void NxsTaxaBlock::Report(
  std::ostream &out) const
{
	out << "\n" << blockName << " block contains ";
	if (m_numTaxa == 0)
	{
		out << "no taxa\n";
		return;
	}
	else if (m_numTaxa == 1)
		out << "one taxon\n";
	else
		out << m_numTaxa << " taxa\n";

	for (unsigned idx = 0; idx < m_numTaxa; ++idx)
	{
		out << "\t" << (idx + 1) << "\t" << taxonNames[idx] << "\n";
	}
}

/*----------------------------------------------------------------------------------------------------------------------
|	Resets internal state for reuse or new parsing.
*/
void NxsTaxaBlock::Reset()
{
	errormsg.clear();
	isEmptyFlag = true;
	isEnabled = true;
	userProvidedData = false;
	m_numTaxa = 0;
	taxonNames.clear();
	needsQuoting.clear();
}

/*----------------------------------------------------------------------------------------------------------------------
|	Appends a new taxon label and returns its index.
*/
unsigned NxsTaxaBlock::AddTaxonLabel(
  NxsString label)
{
	isEmptyFlag = false;

	bool quoteRequired = label.QuotesNeeded();
	needsQuoting.push_back(quoteRequired);

	taxonNames.push_back(label);
	m_numTaxa++;

	return m_numTaxa - 1;
}

/*----------------------------------------------------------------------------------------------------------------------
|	Replaces existing taxon label at position i with new string s.
*/
void NxsTaxaBlock::ChangeTaxonLabel(
  unsigned pos,
  NxsString label)
{
	assert(pos < taxonNames.size());

	needsQuoting[pos] = label.QuotesNeeded();
	taxonNames[pos] = label;
}

/*----------------------------------------------------------------------------------------------------------------------
|	Finds maximum length among all stored taxon labels.
*/
unsigned NxsTaxaBlock::GetMaxTaxonLabelLength() const
{
	assert(m_numTaxa == taxonNames.size());
	unsigned maxLen = 0;

	for (unsigned i = 0; i < m_numTaxa; ++i)
	{
		unsigned currLen = taxonNames[i].length();
		if (currLen > maxLen)
			maxLen = currLen;
	}
	return maxLen;
}

/*----------------------------------------------------------------------------------------------------------------------
|	Retrieves taxon label by index.
*/
NxsString NxsTaxaBlock::GetTaxonLabel(unsigned idx) const
{
	assert(idx < taxonNames.size());
	return taxonNames[idx];
}

/*----------------------------------------------------------------------------------------------------------------------
|	Checks whether taxon label at index needs quoting in NEXUS format.
*/
bool NxsTaxaBlock::NeedsQuotes(unsigned idx) const
{
	assert(idx < taxonNames.size());
	return needsQuoting[idx];
}

/*----------------------------------------------------------------------------------------------------------------------
|	Tests if a given label already exists in the list.
*/
bool NxsTaxaBlock::IsAlreadyDefined(const NxsString &label) const
{
	auto iter = std::find(taxonNames.begin(), taxonNames.end(), label);
	return iter != taxonNames.end();
}

/*----------------------------------------------------------------------------------------------------------------------
|	Searches for taxon named 'label' and returns its index.
|	Throws exception if not found.
*/
unsigned NxsTaxaBlock::FindTaxon(const NxsString &label)
{
	unsigned index = 0;
	for (auto iter = taxonNames.begin(); iter != taxonNames.end(); ++iter, ++index)
	{
		if (*iter == label)
			return index;
	}
	throw NxsTaxaBlock::NxsX_NoSuchTaxon();
}

/*----------------------------------------------------------------------------------------------------------------------
|	Returns current number of stored taxa.
*/
unsigned NxsTaxaBlock::GetNumTaxonLabels() const
{
	return static_cast<unsigned>(taxonNames.size());
}

/*----------------------------------------------------------------------------------------------------------------------
|	Sets the explicit taxon count (does not modify actual storage).
*/
void NxsTaxaBlock::SetNtax(unsigned n)
{
	m_numTaxa = n;
}

