	m_file = file;
	m_saveFile->setFilePointer(m_file, 0, nullptr, FILE_BEGIN);
}

int ConsoleSaveFileInputStream::read()
{
	byte buffer = 0;
	DWORD bytesRead = 0;
	BOOL operationSuccess = m_saveFile->readFile(
		m_file,
		&buffer,
		1,
		&bytesRead
	);

	if (!operationSuccess) {
		// TODO 4J Stu - Some kind of error handling
		return -1;
	}

	if (bytesRead == 0) {
		// Reached end of file
		return -1;
	}

	return static_cast<int>(buffer);
}

int ConsoleSaveFileInputStream::read(byteArray b)
{
	DWORD bytesRead = 0;
	BOOL operationSuccess = m_saveFile->readFile(
		m_file,
		b.data,
		b.length,
		&bytesRead
	);

	if (!operationSuccess) {
		// TODO 4J Stu - Some kind of error handling
		return -1;
	}

	if (bytesRead == 0) {
		// No more data available
		return -1;
	}

	return static_cast<int>(bytesRead);
}

int ConsoleSaveFileInputStream::read(byteArray b, unsigned int offset, unsigned int length)
{
	// Ensure we don't overflow the buffer bounds
	assert(length <= (b.length - offset));

	DWORD bytesRead = 0;
	BOOL operationSuccess = m_saveFile->readFile(
		m_file,
		&b[offset],
		length,
		&bytesRead
	);

	if (!operationSuccess) {
		// TODO 4J Stu - Some kind of error handling
		return -1;
	}

	if (bytesRead == 0) {
		// End-of-file reached
		return -1;
	}

	return static_cast<int>(bytesRead);
}

void ConsoleSaveFileInputStream::close()
{
	if (m_saveFile != nullptr) {
		BOOL closeResult = m_saveFile->closeHandle(m_file);
		if (!closeResult) {
			// TODO 4J Stu - Some kind of error handling
		}
		// Prevent double-close in destructor
		m_saveFile = nullptr;
	}
}

