#include <iostream>
#include <vector>
#include <string>
#include <cmath>
using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int blackCount, whiteCount, tempX, tempY;
    if (!(cin >> blackCount >> whiteCount >> tempX >> tempY)) return 0;

    // Handle nearly equal counts with alternating pattern
    if (abs(blackCount - whiteCount) <= 1) {
        int totalHeight = blackCount + whiteCount;
        cout << totalHeight << " " << 1 << "\n";

        char tileChar = '@';
        if (whiteCount > blackCount) {
            tileChar = '.';
        }

        for (int row = 0; row < totalHeight; ++row) {
            cout << tileChar << "\n";
            tileChar = (tileChar == '@' ? '.' : '@');
        }
    } else {
        // General case: construct grid using two-row blocks
        vector<string> pattern;

        // Top section: primarily black tiles with isolated white dots
        if (whiteCount == 1) {
            pattern.push_back("@@");
        } else {
            for (int i = 0; i < whiteCount - 1; ++i) {
                pattern.push_back("@.");
                pattern.push_back("@@");
            }
        }

        // Middle separator layer
        pattern.push_back("..");

        // Bottom section: primarily white tiles with isolated black dots
        if (blackCount > 1) {
            for (int i = 0; i < blackCount - 1; ++i) {
                pattern.push_back(".@");
                pattern.push_back("..");
            }
        }

        cout << pattern.size() << " " << 2 << "\n";
        for (const string& line : pattern) {
            cout << line << "\n";
        }
    }

    return 0;
}

