namespace {
using namespace mlir;
using namespace mlir::triton;

// Custom pattern for converting triton::FuncOp to LLVM IR
// This handles kernel and non-kernel functions differently:
// - Kernel functions get marked with nvvm.kernel and external linkage
// - Non-kernel functions get noinline attribute and internal linkage
struct FuncToLLVMConversion : public ConvertOpToLLVMPattern<triton::FuncOp> {
  FuncToLLVMConversion(LLVMTypeConverter &converter, int warpCount,
                       PatternBenefit benefit)
      : ConvertOpToLLVMPattern(converter, benefit), warps(warpCount) {}

  // Remove specific attributes that are handled automatically during conversion
  static void stripUnneededAttributes(triton::FuncOp op, bool skipArgAttrs,
                                      SmallVectorImpl<NamedAttribute> &out) {
    for (const auto &attr : op->getAttrs()) {
      StringRef name = attr.getName().getValue();
      if (name == SymbolTable::getSymbolAttrName() ||
          name == op.getFunctionTypeAttrName() ||
          name == "std.varargs" ||
          (skipArgAttrs && name == op.getArgAttrsAttrName()))
        continue;
      out.push_back(attr);
    }
  }

  // Extend the function signature with a shared memory pointer argument
  triton::FuncOp extendFunctionSignature(triton::FuncOp originalFunc,
                                         ConversionPatternRewriter &rewriter) const {
    auto loc = originalFunc.getLoc();
    auto ctx = originalFunc->getContext();
    auto memPtrTy = LLVM::LLVMPointerType::get(rewriter.getContext(), 3);

    // Update function type
    auto oldType = originalFunc.getFunctionType();
    SmallVector<Type> updatedInputs(oldType.getInputs());
    updatedInputs.push_back(memPtrTy);
    auto newFuncType = FunctionType::get(ctx, updatedInputs, oldType.getResults());

    // Update argument attributes
    SmallVector<NamedAttribute> updatedAttrs;
    stripUnneededAttributes(originalFunc, /*skipArgAttrs=*/true, updatedAttrs);
    auto argAttrs = llvm::to_vector<4>(originalFunc.getAllArgAttrs());
    argAttrs.emplace_back(DictionaryAttr::get(ctx));
    updatedAttrs.push_back(
        rewriter.getNamedAttr(originalFunc.getArgAttrsAttrName(),
                              rewriter.getArrayAttr(argAttrs)));

    // Create new function with extended signature
    auto newFunc = rewriter.create<triton::FuncOp>(
        loc, originalFunc.getName(), newFuncType, updatedAttrs);

    // Move body and add new argument
    auto &body = originalFunc.getBody();
    body.addArgument(memPtrTy, loc);
    rewriter.inlineRegionBefore(body, newFunc.getBody(), newFunc.end());

    return newFunc;
  }

  LogicalResult
  matchAndRewrite(triton::FuncOp funcOp, OpAdaptor adaptor,
                  ConversionPatternRewriter &rewriter) const override {
    triton::FuncOp workingFunc = funcOp;

    // For non-kernel functions, we need to extend the signature
    if (!LLVM::isKernel(funcOp)) {
      workingFunc = extendFunctionSignature(funcOp, rewriter);
    }

    // Perform actual conversion to LLVMFuncOp
    auto convertedFunc = mlir::convertFunctionToLLVM(
        workingFunc, rewriter, *getTypeConverter());
    if (!convertedFunc) {
      return failure();
    }

    auto ctx = funcOp->getContext();

    if (LLVM::isKernel(funcOp)) {
      // Mark as CUDA kernel
      convertedFunc->setAttr("nvvm.kernel",
                             rewriter.getIntegerAttr(IntegerType::get(ctx, 1), 1));
      convertedFunc.setLinkage(LLVM::Linkage::External);
    } else {
      // Prevent inlining by adding noinline attribute
      convertedFunc.setPassthroughAttr(
          ArrayAttr::get(ctx, rewriter.getStringAttr("noinline")));
      rewriter.eraseOp(workingFunc);
      convertedFunc.setLinkage(LLVM::Linkage::Internal);
    }

    // Set thread count annotation for NVVM backend
    convertedFunc->setAttr("nvvm.maxntid",
                           rewriter.getDenseI32ArrayAttr(32 * warps));

    rewriter.eraseOp(funcOp);
    return success();
  }

private:
  int warps{0};
};

} // namespace

void mlir::triton::populateFuncOpConversionPattern(
    LLVMTypeConverter &typeConverter, RewritePatternSet &patterns, int numWarps,
    PatternBenefit benefit) {
  patterns.add<FuncToLLVMConversion>(typeConverter, numWarps, benefit);
}

