)
: UIScene(playerIndex, uiLayerParent) {
    // Initialize required Iggy resources for this scene
    loadMovie();

    WCHAR buffer[256];

    // Initialize music slider with current volume setting
    int musicVol = app.GetGameSettings(playerIndex, eGameSetting_MusicVolume);
    swprintf(buffer, 256, L"%ls: %d%%", app.GetString(IDS_SLIDER_MUSIC), musicVol);
    m_sliderMusic.init(
        buffer,
        eControl_Music,
        0,
        100,
