    );

    // Initialize sound FX slider with current volume setting
    int soundVol = app.GetGameSettings(playerIndex, eGameSetting_SoundFXVolume);
    swprintf(buffer, 256, L"%ls: %d%%", app.GetString(IDS_SLIDER_SOUND), soundVol);
    m_sliderSound.init(
        buffer,
        eControl_Sound,
        0,
        100,
        soundVol
    );

    performLayoutAdjustment();

    // Handle splitscreen-specific layout if multiple players are active
    if (app.GetLocalPlayerCount() > 1) {
