    return (app.GetLocalPlayerCount() > 1) ? L"SettingsAudioMenuSplit" : L"SettingsAudioMenu";
}

void UIScene_SettingsAudioMenu::updateTooltips() {
    ui.SetTooltips(m_iPad, IDS_TOOLTIPS_SELECT, IDS_TOOLTIPS_BACK);
}

void UIScene_SettingsAudioMenu::updateComponents() {
    bool isNotInLevel = (Minecraft::GetInstance()->level == nullptr);

    if (isNotInLevel) {
        m_parentLayer->showComponent(m_iPad, eUIComponent_Panorama, true);
        m_parentLayer->showComponent(m_iPad, eUIComponent_Logo, true);
    } else {
        m_parentLayer->showComponent(m_iPad, eUIComponent_Panorama, false);

        if (app.GetLocalPlayerCount() == 1) {
            m_parentLayer->showComponent(m_iPad, eUIComponent_Logo, true);
        } else {
            m_parentLayer->showComponent(m_iPad, eUIComponent_Logo, false);
        }
    }
}

void UIScene_SettingsAudioMenu::handleInput(
    int   playerIdx,
    int   inputKey,
    bool  isRepeat,
    bool  isDown,
    bool  isUp,
    bool& consumed
) {
    ui.AnimateKeyPress(m_iPad, inputKey, isRepeat, isDown, isUp);

    switch (inputKey) {
    case ACTION_MENU_CANCEL:
        if (isDown) {
            navigateBack();
        }
        break;

    case ACTION_MENU_OK:
#ifdef __ORBIS__
    case ACTION_MENU_TOUCHPAD_PRESS:
#endif
        sendInputToMovie(inputKey, isRepeat, isDown, isUp);
        break;

    case ACTION_MENU_UP:
    case ACTION_MENU_DOWN:
    case ACTION_MENU_LEFT:
    case ACTION_MENU_RIGHT:
        sendInputToMovie(inputKey, isRepeat, isDown, isUp);
        break;
    }
}

void UIScene_SettingsAudioMenu::handleSliderMove(
    F64 sliderIdentifier,
    F64 newValue
) {
    WCHAR tempBuffer[256];
    int adjustedValue = static_cast<int>(newValue);

    switch (static_cast<int>(sliderIdentifier)) {
    case eControl_Music:
        m_sliderMusic.handleSliderMove(adjustedValue);
        app.SetGameSettings(m_iPad, eGameSetting_MusicVolume, adjustedValue);
        swprintf(tempBuffer, 256, L"%ls: %d%%", app.GetString(IDS_SLIDER_MUSIC), adjustedValue);
        m_sliderMusic.setLabel(tempBuffer);
        break;

    case eControl_Sound:
        m_sliderSound.handleSliderMove(adjustedValue);
        app.SetGameSettings(m_iPad, eGameSetting_SoundFXVolume, adjustedValue);
        swprintf(tempBuffer, 256, L"%ls: %d%%", app.GetString(IDS_SLIDER_SOUND), adjustedValue);
        m_sliderSound.setLabel(tempBuffer);
        break;
    }
}

