#include "SparseDataStorage.h"

// Static initialization for thread-safe deletion queue management
int SparseDataStorage::deleteQueueIndex = 0;
XLockFreeStack<unsigned char> SparseDataStorage::deleteQueue[3];

void SparseDataStorage::staticCtor()
{
    for (int idx = 0; idx < 3; ++idx)
    {
        deleteQueue[idx].Initialize();
    }
}

// Constructor: initializes storage with minimal compression — first plane marked as all-zero, others uncompressed.
// Allocation strategy uses XPhysicalAlloc on Xbox to ensure proper page alignment (4KB), simplifying cleanup later.
SparseDataStorage::SparseDataStorage()
{
#ifdef _XBOX
    unsigned char* rawIndices = static_cast<unsigned char*>(XPhysicalAlloc(128 * 128, MAXULONG_PTR, 4096, PAGE_READWRITE));
#else
    unsigned char* rawIndices = static_cast<unsigned char*>(malloc(128 * 128));
#endif

    unsigned char* dataRegion = rawIndices + 128;

    // First entry indicates "all zero", subsequent entries form an index chain
    rawIndices[0] = ALL_0_INDEX;
    for (int i = 1; i < 128; ++i)
    {
        rawIndices[i] = static_cast<unsigned char>(i - 1);
    }

    // Zero-fill the actual data region
    XMemSet(dataRegion, 0, 128 * 127);

    // Pack pointer and count into 64-bit value
#pragma warning(disable : 4826)
    dataAndCount = (static_cast<__int64>(rawIndices) & 0x0000ffffffffffffLL) | 0x007F000000000000LL;
#pragma warning(default : 4826)

#ifdef DATA_COMPRESSION_STATS
    count = 128;
#endif
}

// Alternate constructor for upper-layer initialization (e.g., empty planes only)
SparseDataStorage::SparseDataStorage(bool /*unused*/)
{
    unsigned char* rawIndices = static_cast<unsigned char*>(malloc(128));

    // Initialize all indices to indicate zero-filled planes
    for (int i = 0; i < 128; ++i)
    {
        rawIndices[i] = ALL_0_INDEX;
    }

#pragma warning(disable : 4826)
    dataAndCount = static_cast<__int64>(rawIndices) & 0x0000ffffffffffffLL;
#pragma warning(default : 4826)

#ifdef DATA_COMPRESSION_STATS
    count = 128;
#endif
}

// Destructor: safely frees memory depending on allocation method (XPhysicalFree vs malloc)
SparseDataStorage::~SparseDataStorage()
{
    unsigned char* basePtr = reinterpret_cast<unsigned char*>(dataAndCount & 0x0000ffffffffffffLL);

#ifdef _XBOX
    if (reinterpret_cast<unsigned int>(basePtr) >= MM_PHYSICAL_4KB_BASE)
    {
        XPhysicalFree(basePtr);
    }
    else
#endif
    {
        free(basePtr);
    }
}

// Copy constructor: duplicates current state into newly allocated memory
SparseDataStorage::SparseDataStorage(SparseDataStorage* source)
{
    __int64 srcPacked = source->dataAndCount;
    unsigned char* srcBase = reinterpret_cast<unsigned char*>(srcPacked & 0x0000ffffffffffffLL);
    int srcPlaneCount = static_cast<int>((srcPacked >> 48) & 0xFFFF);

    size_t totalSize = srcPlaneCount * 128 + 128;
    unsigned char* destBase = static_cast<unsigned char*>(malloc(totalSize));

#pragma warning(disable : 4826)
    dataAndCount = (srcPacked & 0xFFFF000000000000LL) | (static_cast<__int64>(destBase) & 0x0000ffffffffffffLL);
#pragma warning(default : 4826)

    XMemCpy(destBase, srcBase, totalSize);

#ifdef DATA_COMPRESSION_STATS
    count = srcPlaneCount;
#endif
}

// Populate storage from external byte array (Java-compatible layout)
void SparseDataStorage::setData(byteArray dataIn, unsigned int inOffset)
{
    int usedPlanes = 0;
    unsigned char tempIndices[128];

    // First pass: determine which Y-planes contain non-zero data
    for (int y = 0; y < 128; ++y)
    {
        bool isEmpty = true;
        for (int xz = 0; xz < 256; ++xz)
        {
            int pos = (xz << 7) | y;
            int slot = pos >> 1;
            int part = pos & 1;
            unsigned char val = (dataIn[slot + inOffset] >> (part * 4)) & 0x0F;
            if (val != 0)
            {
                isEmpty = false;
                break;
            }
        }
        tempIndices[y] = isEmpty ? ALL_0_INDEX : static_cast<unsigned char>(usedPlanes++);
    }

    // Allocate new storage based on required planes
    unsigned char* newBase = static_cast<unsigned char*>(malloc(usedPlanes * 128 + 128));
    unsigned char* newData = newBase + 128;

    XMemCpy(newBase, tempIndices, 128);

    // Second pass: copy actual data into allocated planes
    unsigned char* outPtr = newData;
    for (int y = 0; y < 128; ++y)
    {
        if (tempIndices[y] < ALL_0_INDEX)
        {
            int part = y & 1;
            unsigned char* inPtr = &dataIn[(y >> 1) + inOffset];
            for (int xz = 0; xz < 128; ++xz)
            {
                *outPtr = (static_cast<unsigned char>(*inPtr) >> (part * 4)) & 0x0F;
                inPtr += 64;
                *outPtr |= ((static_cast<unsigned char>(*inPtr) >> (part * 4)) & 0x0F) << 4;
                inPtr += 64;
                ++outPtr;
            }
        }
    }

    // Update internal packed descriptor
    __int64 newDesc = (static_cast<__int64>(newBase) & 0x0000ffffffffffffLL) | (static_cast<__int64>(usedPlanes) << 48);
    updateDataAndCount(newDesc);
}

// Extract full data set into caller-provided buffer
void SparseDataStorage::getData(byteArray retArray, unsigned int retOffset)
{
    XMemSet(retArray.data + retOffset, 0, 16384);

    unsigned char* indices, * data;
    getPlaneIndicesAndData(&indices, &data);

    for (int y = 0; y < 128; ++y)
    {
        if (indices[y] == ALL_0_INDEX)
            continue;

        int part = y & 1;
        int shift = part * 4;
        unsigned char* dst = &retArray.data[(y >> 1) + retOffset];
        unsigned char* src = &data[indices[y] * 128];

        for (int xz = 0; xz < 128; ++xz)
        {
            unsigned char low = *src & 0x0F;
            *dst |= low << shift;
            dst += 64;

            unsigned char high = (*src >> 4) & 0x0F;
            *dst |= high << shift;
            dst += 64;

            ++src;
        }
    }
}

// Retrieve single voxel value
int SparseDataStorage::get(int x, int y, int z)
{
    unsigned char* indices, * data;
    getPlaneIndicesAndData(&indices, &data);

    if (indices[y] == ALL_0_INDEX)
        return 0;

    int planeIdx = x * 16 + z;
    int byteIdx = planeIdx / 2;
    int bitShift = (planeIdx % 2) * 4;

    unsigned char byteVal = data[indices[y] * 128 + byteIdx];
    return (byteVal >> bitShift) & 0x0F;
}

// Set single voxel value
void SparseDataStorage::set(int x, int y, int z, int val)
{
    unsigned char* indices, * data;
    getPlaneIndicesAndData(&indices, &data);

    if (indices[y] >= ALL_0_INDEX)
    {
        if (val == 0 && indices[y] == ALL_0_INDEX)
            return;
        addNewPlane(y);
        getPlaneIndicesAndData(&indices, &data);
    }

    int planeIdx = x * 16 + z;
    int byteIdx = planeIdx / 2;
    int bitShift = (planeIdx % 2) * 4;
    int mask = 0xF0 >> bitShift;

    unsigned char* target = &data[indices[y] * 128 + byteIdx];
    *target = (*target & static_cast<unsigned char>(mask)) | (static_cast<unsigned char>(val) << bitShift);
}

// Bulk write operation from external buffer
int SparseDataStorage::setDataRegion(byteArray dataIn, int x0, int y0, int z0, int x1, int y1, int z1,
                                     int offset, tileUpdatedCallback callback, void* param, int yparam)
{
    unsigned char* src = &dataIn.data[offset];

    if (callback)
    {
        for (int x = x0; x < x1; ++x)
        {
            for (int z = z0; z < z1; ++z)
            {
                int startY = y0 & ~1;
                int len = (y1 - y0) / 2;
                for (int i = 0; i < len; ++i)
                {
                    int y = startY + (i << 1);
                    int v1 = *src & 0x0F;
                    if (get(x, y, z) != v1)
                    {
                        set(x, y, z, v1);
                        callback(x, y, z, param, yparam);
                    }

                    int v2 = (*src >> 4) & 0x0F;
                    if (get(x, y + 1, z) != v2)
                    {
                        set(x, y + 1, z, v2);
                        callback(x, y + 1, z, param, yparam);
                    }
                    ++src;
                }
            }
        }
    }
    else
    {
        for (int x = x0; x < x1; ++x)
        {
            for (int z = z0; z < z1; ++z)
            {
                int startY = y0 & ~1;
                int len = (y1 - y0) / 2;
                for (int i = 0; i < len; ++i)
                {
                    int y = startY + (i << 1);
                    set(x, y, z, *src & 0x0F);
                    set(x, y + 1, z, (*src >> 4) & 0x0F);
                    ++src;
                }
            }
        }
    }

    return static_cast<int>(src - &dataIn.data[offset]);
}

// Bulk read operation into external buffer
int SparseDataStorage::getDataRegion(byteArray dataOut, int x0, int y0, int z0, int x1, int y1, int z1, int offset)
{
    unsigned char* dst = &dataOut.data[offset];

    for (int x = x0; x < x1; ++x)
    {
        for (int z = z0; z < z1; ++z)
        {
            int startY = y0 & ~1;
            int len = (y1 - y0) / 2;
            for (int i = 0; i < len; ++i)
            {
                int y = startY + (i << 1);
                unsigned char val1 = static_cast<unsigned char>(get(x, y, z));
                unsigned char val2 = static_cast<unsigned char>(get(x, y + 1, z));
                *dst = val1 | (val2 << 4);
                ++dst;
            }
        }
    }

    return static_cast<int>(dst - &dataOut.data[offset]);
}

// Dynamically expand plane storage when needed (thread-safe via CAS loop)
void SparseDataStorage::addNewPlane(int y)
{
    bool done = false;
    do
    {
        __int64 oldDesc = dataAndCount;
        int usedLines = static_cast<int>((oldDesc >> 48) & 0xFFFF);
        unsigned char* oldBase = reinterpret_cast<unsigned char*>(oldDesc & 0x0000ffffffffffffLL);

        unsigned char curIndex = oldBase[y];
        if (curIndex < ALL_0_INDEX)
            return; // Already allocated

        int newCount = usedLines + 1;
        unsigned char* newBase = static_cast<unsigned char*>(malloc(newCount * 128 + 128));
        XMemCpy(newBase, oldBase, usedLines * 128 + 128);
        XMemSet(newBase + usedLines * 128 + 128, 0, 128);
        newBase[y] = static_cast<unsigned char>(usedLines);

        __int64 newDesc = (static_cast<__int64>(newBase) & 0x0000ffffffffffffLL) | (static_cast<__int64>(newCount) << 48);

        __int64 prev = InterlockedCompareExchangeRelease64(&dataAndCount, newDesc, oldDesc);
        if (prev == oldDesc)
        {
            done = true;
            queueForDelete(oldBase);
#ifdef DATA_COMPRESSION_STATS
            count = newCount;
#endif
        }
        else
        {
            queueForDelete(newBase);
        }
    } while (!done);
}

// Helper to extract current plane indices and data pointers
void SparseDataStorage::getPlaneIndicesAndData(unsigned char** indices, unsigned char** data)
{
    unsigned char* base = reinterpret_cast<unsigned char*>(dataAndCount & 0x0000ffffffffffffLL);
    *indices = base;
    *data = base + 128;
}

// Queue memory for deferred deletion
void SparseDataStorage::queueForDelete(unsigned char* ptr)
{
    deleteQueue[deleteQueueIndex].Push(ptr);
}

// Periodic cleanup of queued memory (rotates through 3 queues for safety)
void SparseDataStorage::tick()
{
    int freeIdx = (deleteQueueIndex + 1) % 3;
    unsigned char* item = nullptr;

    do
    {
        item = deleteQueue[freeIdx].Pop();
        if (item)
        {
#ifdef _XBOX
            if (reinterpret_cast<unsigned int>(item) >= MM_PHYSICAL_4KB_BASE)
                XPhysicalFree(item);
            else
#endif
                free(item);
        }
    } while (item);

    deleteQueueIndex = (deleteQueueIndex + 1) % 3;
}

// Atomic update of descriptor (with safe reclamation of old memory)
void SparseDataStorage::updateDataAndCount(__int64 newDesc)
{
    bool success = false;
    do
    {
        __int64 oldDesc = dataAndCount;
        unsigned char* oldBase = reinterpret_cast<unsigned char*>(oldDesc & 0x0000ffffffffffffLL);

        __int64 result = InterlockedCompareExchangeRelease64(&dataAndCount, newDesc, oldDesc);
        if (result == oldDesc)
        {
            success = true;
            queueForDelete(oldBase);
        }
    } while (!success);

#ifdef DATA_COMPRESSION_STATS
    count = static_cast<int>((newDesc >> 48) & 0xFFFF);
#endif
}

// Attempt to compress storage by removing all-zero planes
int SparseDataStorage::compress()
{
    __int64 oldDesc = dataAndCount;
    unsigned char* oldBase = reinterpret_cast<unsigned char*>(oldDesc & 0x0000ffffffffffffLL);
    unsigned char* oldData = oldBase + 128;

    unsigned char newIndices[128];
    bool changed = false;
    int activePlanes = 0;

    for (int i = 0; i < 128; ++i)
    {
        if (oldBase[i] == ALL_0_INDEX)
        {
            newIndices[i] = ALL_0_INDEX;
        }
        else
        {
            unsigned char* planeData = &oldData[128 * oldBase[i]];
            bool isEmpty = true;
            for (int j = 0; j < 128; ++j)
            {
                if (planeData[j] != 0)
                {
                    isEmpty = false;
                    break;
                }
            }

            if (isEmpty)
            {
                newIndices[i] = ALL_0_INDEX;
                changed = true;
            }
            else
            {
                newIndices[i] = static_cast<unsigned char>(activePlanes++);
            }
        }
    }

    if (changed)
    {
        size_t newSize = 128 + 128 * activePlanes;
        unsigned char* newBase = static_cast<unsigned char*>(malloc(newSize));
        XMemCpy(newBase, newIndices, 128);

        unsigned char* newData = newBase + 128;
        for (int i = 0; i < 128; ++i)
        {
            if (newIndices[i] < ALL_0_INDEX)
            {
                XMemCpy(newData, &oldData[128 * oldBase[i]], 128);
                newData += 128;
            }
        }

        __int64 newDesc = (static_cast<__int64>(newBase) & 0x0000ffffffffffffLL) | (static_cast<__int64>(activePlanes) << 48);
        __int64 result = InterlockedCompareExchangeRelease64(&dataAndCount, newDesc, oldDesc);

        if (result != oldDesc)
        {
            queueForDelete(newBase);
        }
        else
        {
            queueForDelete(oldBase);
#ifdef DATA_COMPRESSION_STATS
            count = activePlanes;
#endif
        }
        return activePlanes;
    }

    return static_cast<int>((oldDesc >> 48) & 0xFFFF);
}

// Check if currently compressed (fewer than full planes)
bool SparseDataStorage::isCompressed()
{
    int planes = static_cast<int>((dataAndCount >> 48) & 0xFFFF);
    return planes < 127;
}

// Serialization support
void SparseDataStorage::write(DataOutputStream* dos)
{
    int planes = static_cast<int>((dataAndCount >> 48) & 0xFFFF);
    dos->writeInt(planes);

    unsigned char* base = reinterpret_cast<unsigned char*>(dataAndCount & 0x0000ffffffffffffLL);
    byteArray wrapper(base, planes * 128 + 128);
    dos->write(wrapper);
}

// Deserialization support
void SparseDataStorage::read(DataInputStream* dis)
{
    int planes = dis->readInt();
    unsigned char* base = static_cast<unsigned char*>(malloc(planes * 128 + 128));
    byteArray wrapper(base, planes * 128 + 128);
    dis->readFully(wrapper);

    __int64 newDesc = (static_cast<__int64>(base) & 0x0000ffffffffffffLL) | (static_cast<__int64>(planes) << 48);
    updateDataAndCount(newDesc);
}

#include <iostream>
#include <asio.hpp>
#include <functional>

class DualTimerPrinter
{
public:
    DualTimerPrinter(asio::io_context& context)
        : work_guard_(asio::make_work_guard(context)),
          timer_a_(context),
          timer_b_(context),
          shared_counter_(0)
    {
        // Initialize both timers with 1-second delay
        start_timer_a();
        start_timer_b();
    }

    ~DualTimerPrinter()
    {
        std::cout << "Final count is " << shared_counter_ << std::endl;
    }

private:
    void start_timer_a()
    {
        timer_a_.expires_after(std::chrono::seconds(1));
        timer_a_.async_wait([this](const asio::error_code&) {
            if (shared_counter_ < 10) {
                std::cout << "Timer 1: " << shared_counter_ << std::endl;
                ++shared_counter_;
                start_timer_a();
            }
        });
    }

    void start_timer_b()
    {
        timer_b_.expires_after(std::chrono::seconds(1));
        timer_b_.async_wait([this](const asio::error_code&) {
            if (shared_counter_ < 10) {
                std::cout << "Timer 2: " << shared_counter_ << std::endl;
                ++shared_counter_;
                start_timer_b();
            }
        });
    }

    asio::executor_work_guard<asio::io_context::executor_type> work_guard_;
    asio::steady_timer timer_a_;
    asio::steady_timer timer_b_;
    int shared_counter_;
};

int main()
{
    asio::io_context io_context;

    // Create printer object which starts the timers
    DualTimerPrinter printer(io_context);

    // Run the io_context in multiple threads for concurrency
    asio::thread_pool pool(2);
    asio::post(pool, [&io_context]() { io_context.run(); });
    asio::post(pool, [&io_context]() { io_context.run(); });

    pool.join();

    return 0;
}

