// Custom implementation to release addrinfo chain and manage reference counting
void freeaddrinfo(struct addrinfo *p)
{
    // Count the number of elements in the linked list
    size_t count = 0;
    struct addrinfo *current = p;

    while (current != NULL) {
        count++;
        current = current->ai_next;
    }

    // Calculate base address of the allocation block
    struct aibuf *base = (struct aibuf *)((char *)p - offsetof(struct aibuf, ai));

    // Adjust base pointer using slot information
    struct aibuf *adjusted_base = base - base->slot;

    // Acquire lock for thread-safe reference counting
    LOCK(adjusted_base->lock);

    // Decrement reference count by the number of nodes being freed
    adjusted_base->ref -= count;

    // If no references remain, deallocate memory; otherwise release lock
    if (adjusted_base->ref == 0) {
        free(adjusted_base);
    } else {
        UNLOCK(adjusted_base->lock);
    }
}

