#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

// Constants and global state
int totalPairs;
vector<int> connections[1005];      // adjacency list: stores neighbors for each chameleon
int romanticPartner[1005];          // L(u): who is u's love partner (if degree == 3)
bool matchedInOutput[1005];         // marks whether a chameleon has already been output

// Perform a query on the given subset of chameleons
int ask(const vector<int>& participants) {
    if (participants.empty()) return 0;

    cout << "Query " << participants.size();
    for (int id : participants) cout << " " << id;
    cout << '\n';

    int result;
    cin >> result;
    return result;
}

// Determine if node 'u' shares an edge with any node in set 'candidates'
bool hasConnection(int u, const vector<int>& candidates) {
    if (candidates.empty()) return false;

    vector<int> testSet = candidates;
    testSet.push_back(u);
    int count = ask(testSet);

    // If no edges exist among testSet, answer should be |testSet| = |candidates| + 1
    return count != (int)candidates.size() + 1;
}

// Recursively discover all neighbors of 'u' within 'candidates', respecting max-degree-3 constraint
void exploreNeighbors(int u, const vector<int>& candidates) {
    if (candidates.empty()) return;

    // Early exit: already found 3 neighbors (max possible)
    if ((int)connections[u].size() >= 3) return;

    // No edges between u and this group → prune recursion
    if (!hasConnection(u, candidates)) return;

    // Base case: only one candidate left → must be neighbor
    if (candidates.size() == 1) {
        int v = candidates[0];
        connections[u].push_back(v);
        connections[v].push_back(u);
        return;
    }

    // Divide-and-conquer search
    int half = candidates.size() / 2;
    vector<int> left(candidates.begin(), candidates.begin() + half);
    vector<int> right(candidates.begin() + half, candidates.end());

    exploreNeighbors(u, left);
    exploreNeighbors(u, right);
}

int main() {
    ios_base::sync_with_stdio(false);

    if (!(cin >> totalPairs)) return 0;

    vector<vector<int>> independentGroups;   // groups where no two nodes are adjacent

    // Build graph incrementally
    for (int node = 1; node <= 2 * totalPairs; ++node) {
        // Try to find neighbors among previously placed nodes (independent sets)
        for (const auto& group : independentGroups) {
            exploreNeighbors(node, group);
        }

        // Place 'node' into first compatible independent group
        bool assigned = false;
        for (auto& group : independentGroups) {
            bool incompatible = false;

            // Check if 'node' is adjacent to any member of this group
            for (int neighbor : connections[node]) {
                for (int member : group) {
                    if (neighbor == member) {
                        incompatible = true;
                        break;
                    }
                }
                if (incompatible) break;
            }

            if (!incompatible) {
                group.push_back(node);
                assigned = true;
                break;
            }
        }

        if (!assigned) {
            independentGroups.emplace_back(initializer_list<int>{node});
        }
    }

    // Identify love edges using degree-3 property
    for (int i = 1; i <= 2 * totalPairs; ++i) {
        if (connections[i].size() == 3) {
            int a = connections[i][0];
            int b = connections[i][1];
            int c = connections[i][2];

            // Among {a,b,c}, exactly one is the love partner.
            // Query({i, x, y}) == 1 means z is love partner.
            if (ask({i, a, b}) == 1) {
                romanticPartner[i] = c;
            } else if (ask({i, a, c}) == 1) {
                romanticPartner[i] = b;
            } else {
                romanticPartner[i] = a;
            }
        }
    }

    // Output color-matching pairs
    for (int i = 1; i <= 2 * totalPairs; ++i) {
        if (matchedInOutput[i]) continue;

        for (int neighbor : connections[i]) {
            // Color edge iff neither direction is a love edge
            if (romanticPartner[i] != neighbor && romanticPartner[neighbor] != i) {
                cout << "Answer " << i << " " << neighbor << '\n';
                matchedInOutput[i] = true;
                matchedInOutput[neighbor] = true;
                break;
            }
        }
    }

    return 0;
}

