MenuBackup::MenuBackup(shared_ptr<Inventory> inventory, AbstractContainerMenu* menu)
{
    backupStore = new std::unordered_map<short, ItemInstanceArray*>();
    playerInventory = inventory;
    containerMenu = menu;
}

void MenuBackup::record(short changeId)
{
    ItemInstanceArray* snapshot = new ItemInstanceArray(static_cast<int>(containerMenu->slots->size()) + 1);

    // Save carried item at index 0
    snapshot[0] = ItemInstance::clone(playerInventory->getCarried());

    // Save each slot's item starting from index 1
    size_t slotCount = containerMenu->slots->size();
    for (size_t idx = 0; idx < slotCount; ++idx) {
        Slot* currentSlot = containerMenu->slots->at(idx);
        snapshot[idx + 1] = ItemInstance::clone(currentSlot->getItem());
    }

    // Store the snapshot under the given identifier
    backupStore->operator[](changeId) = snapshot;
}

void MenuBackup::removeRecord(short changeId)
{
    auto it = backupStore->find(changeId);
    if (it != backupStore->end()) {
        delete it->second;
        backupStore->erase(it);
    }
}

void MenuBackup::revert(short changeId)
{
    auto it = backupStore->find(changeId);
    if (it == backupStore->end()) return;

    ItemInstanceArray* restoredState = it->second;

    // Restore carried item
    playerInventory->setCarried(restoredState[0]);

    // Restore all slot contents
    size_t totalSlots = containerMenu->slots->size();
    for (size_t i = 0; i < totalSlots; ++i) {
        Slot* targetSlot = containerMenu->slots->at(i);
        targetSlot->set(restoredState[i + 1]);
    }

    // Clean up memory after rollback
    delete restoredState;
    backupStore->clear();
}

