ManagedStatic<CmdLineConfigRegistrar> cmdlineRegistry;

namespace option_handler {

// Helper function template dispatch — rewritten using if constexpr instead of multiple overloads
template <typename T, bool ExternalStorage>
std::string extractValue(const cl::opt<T, ExternalStorage> &opt) {
  if constexpr (std::is_same_v<T, bool>) {
    return opt.getValue() ? "true" : "false";
  } else if constexpr (std::is_same_v<T, std::string>) {
    return opt.getValue();
  } else if constexpr (std::is_arithmetic_v<T>) {
    return std::to_string(opt.getValue());
  } else if constexpr (std::is_same_v<T, MultiBufferStrategy>) {
    static const std::map<MultiBufferStrategy, std::string> strategyMap = {
        {MultiBufferStrategy::NO_LIMIT, "no-limit"},
        {MultiBufferStrategy::ONLY_CUBE, "only-cube"},
        {MultiBufferStrategy::ONLY_VECTOR, "only-vector"},
        {MultiBufferStrategy::CUBE_NO_L0C, "no-l0c"},
    };
    return strategyMap.at(opt.getValue());
  } else {
    llvm_unreachable("Unsupported option type in extraction");
  }
}

} // namespace option_handler

void BiShengIRCompileMainConfig::collectHIVMCArgs() {
  std::vector<std::string> collected;
  auto &registeredOpts = cl::getRegisteredOptions();

  // Manual index-based traversal instead of range-for
  size_t idx = 0;
  while (idx < registeredOpts.size()) {
    auto iter = registeredOpts.begin();
    std::advance(iter, idx);
    const auto &[nameStr, optPtr] = *iter;

    std::string val = "";
#define GEN_OPTION_COLLECTION
#include "bishengir/Tools/bishengir-compile/CompileOptions.cpp.inc"

    if (!val.empty()) {
      collected.emplace_back(nameStr.str() + "=" + val);
    }

    ++idx;
  }

  // Append additional args from config
  for (const auto &rawArgStr : cmdlineRegistry->getHIVMCArgs()) {
    if (rawArgStr.empty()) continue;
    for (const auto &arg : llvm::split(rawArgStr, " "))
      collected.push_back(arg.str());
  }

  cmdlineRegistry->setHIVMCArgs(collected);
}

void BiShengIRCompileMainConfig::registerCLOptions() {
  // Force initialization via dereference
  *cmdlineRegistry;
}

BiShengIRCompileMainConfig BiShengIRCompileMainConfig::createFromCLOptions() {
  BiShengIRCompileMainConfig::collectHIVMCArgs();
  return *cmdlineRegistry;
}

