// Constructor: restructured initialization logic using std::for_each-like pattern via loop
UIScene_DebugOptionsMenu::UIScene_DebugOptionsMenu(int controllerIndex, void *initData, UILayer *parentLayer)
	: UIScene(controllerIndex, parentLayer)
{
	initialiseMovie();

	// Retrieve current debug bitmask from app settings
	unsigned int currentDebugMask = app.GetGameSettingsDebugMask(controllerIndex);

	// Prepare root path for Iggy binding
	IggyValuePath *root = IggyPlayerRootPath(getMovie());

	// Initialize checkboxes dynamically based on bitmask
	int checkboxCount = 0;
	for (int idx = 0; idx < eDebugSetting_Max && idx < 21; ++idx)
	{
		std::wstring label(m_DebugOptionLabels[idx]);
		bool isChecked = (currentDebugMask & (1U << idx)) != 0;

		m_checkboxes[checkboxCount].init(label, checkboxCount, isChecked);
		++checkboxCount;
	}
