// Input handler: refactored bitmask accumulation using accumulator variable instead of inline OR
void UIScene_DebugOptionsMenu::handleInput(int controllerIndex, int keyCode, bool isRepeat, bool isPressed, bool isReleased, bool &handled)
{
	switch (keyCode)
	{
	case ACTION_MENU_CANCEL:
		if (isPressed)
		{
			unsigned int newDebugMask = 0U;
			int bitPosition = 0;

			// Accumulate all checkbox states into bitmask
			for (int i = 0; i < m_iTotalCheckboxElements; ++i)
			{
				if (m_checkboxes[i].IsChecked())
				{
					newDebugMask |= (1U << bitPosition);
				}
				++bitPosition;
			}

			// Only update if changed
			unsigned int oldMask = app.GetGameSettingsDebugMask(controllerIndex);
			if (newDebugMask != oldMask)
			{
				app.SetGameSettingsDebugMask(controllerIndex, newDebugMask);

				if (app.DebugSettingsOn())
				{
					app.ActionDebugMask(controllerIndex);
				}
				else
				{
					// Explicitly disable debug features if mask was cleared
					app.ActionDebugMask(controllerIndex, true); // force off
				}

				app.CheckGameSettingsChanged(true, controllerIndex);
			}

			navigateBack();
		}
		break;

	case ACTION_MENU_OK:
	case ACTION_MENU_UP:
	case ACTION_MENU_DOWN:
	case ACTION_MENU_PAGEUP:
	case ACTION_MENU_PAGEDOWN:
		sendInputToMovie(keyCode, isRepeat, isPressed, isReleased);
		break;
	}
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    if (!(cin >> n)) return 0;

    // Compute k as the ceiling of square root of n
    long long k = static_cast<long long>(ceil(sqrt(static_cast<long double>(n))));

    // Prepare output with fixed precision
    cout.setf(std::ios::fixed);
    cout << setprecision(9);

    // Output k (stored as double)
    cout << static_cast<double>(k) << "\n";

    // Generate n points in a grid layout
    for (long long idx = 0; idx < n; ++idx) {
        long long row = idx / k;
        long long col = idx % k;

        // Offset coordinates by 0.5 to center points in grid cells
        double x_coord = 0.5 + static_cast<double>(col);
        double y_coord = 0.5 + static_cast<double>(row);

        cout << x_coord << " " << y_coord << " " << 0.0 << "\n";
    }

    return 0;
}

#include "common.h"
#include "block_decoder.h"
#include "stream_decoder.h"
#include "index.h"
#include "outqueue.h"

typedef enum {
    THR_WAITING,
    THR_ACTIVE,
    THR_TERMINATE,
} worker_state;

struct worker_thread {
    worker_state status;
    uint8_t *input_buffer;
    size_t input_capacity;
    size_t input_bytes_written;
    size_t input_bytes_consumed;
    size_t output_position;
    struct lzma_stream_coder *main_coder;
    const lzma_allocator *mem_allocator;
    lzma_outbuf *output_buffer;
    size_t bytes_in_processed;
    size_t bytes_out_processed;
    bool partial_update_active;
    bool partial_update_done;
    lzma_next_coder block_coder;
    lzma_block block_config;
    uint64_t filter_memory;
    struct worker_thread *next_free;
    mythread_mutex lock;
    mythread_cond signal;
    mythread thread_id;
};

struct lzma_stream_coder {
    enum {
        HDR_STREAM,
        HDR_BLOCK,
        INIT_BLOCK,
        INIT_THREAD_BLOCK,
        RUN_THREAD_BLOCK,
        INIT_DIRECT_BLOCK,
        RUN_DIRECT_BLOCK,
        WAIT_INDEX_OUTPUT,
        DECODE_INDEX,
        FOOTER_STREAM,
        PADDING_STREAM,
        ERROR_STATE,
    } current_state;

    lzma_next_coder block_decoder;
    lzma_block block_options;
    lzma_filter filters[LZMA_FILTERS_MAX + 1];
    lzma_stream_flags stream_props;
    lzma_index_hash *index_checksum;
    uint32_t wait_timeout_ms;
    lzma_ret worker_error_code;
    lzma_ret deferred_error;
    uint32_t max_threads;
    uint32_t threads_created;
    struct worker_thread *thread_pool;
    struct worker_thread *available_threads;
    struct worker_thread *current_worker;
    lzma_outq output_queue;
    mythread_mutex main_lock;
    mythread_cond main_cond;
    uint64_t mem_limit_parallel;
    uint64_t mem_hard_limit;
    uint64_t direct_mode_memory;
    uint64_t active_memory;
    uint64_t cached_memory;
    uint64_t next_filters_memory;
    uint64_t next_input_memory;
    uint64_t next_block_memory;
    uint64_t total_compressed;
    uint64_t total_uncompressed;
    bool check_none_warning;
    bool check_unsupported_warning;
    bool any_check_warning;
    bool skip_integrity_check;
    bool allow_concatenated;
    bool quick_fail;
    bool first_stream_data;
    bool buffer_was_full;
    size_t buffer_pos;
    uint8_t temp_buffer[LZMA_BLOCK_HEADER_SIZE_MAX];
};

static void
enable_partial_output_callback(void *worker_ptr)
{
    struct worker_thread *w = (struct worker_thread *)worker_ptr;
    mythread_sync(w->lock) {
        w->partial_update_active = true;
        mythread_cond_signal(&w->signal);
    }
}

static MYTHREAD_RET_TYPE
worker_function(void *worker_ptr)
{
    struct worker_thread *w = (struct worker_thread *)worker_ptr;
    size_t input_end;
    bool partial_enabled;
    lzma_ret result;

    while (true) {
        mythread_mutex_lock(&w->lock);

        if (w->status == THR_WAITING) {
            mythread_cond_wait(&w->signal, &w->lock);
            continue;
        }

        if (w->status == THR_TERMINATE) {
            mythread_mutex_unlock(&w->lock);
            lzma_free(w->input_buffer, w->mem_allocator);
            lzma_next_end(&w->block_coder, w->mem_allocator);
            mythread_mutex_destroy(&w->lock);
            mythread_cond_destroy(&w->signal);
            return MYTHREAD_RET_VALUE;
        }

        assert(w->status == THR_ACTIVE);

        w->bytes_in_processed = w->input_bytes_consumed;
        w->bytes_out_processed = w->output_position;

        input_end = w->input_bytes_written;
        partial_enabled = w->partial_update_active;

        if (input_end == w->input_bytes_consumed && 
            !(partial_enabled && !w->partial_update_done)) {
            mythread_cond_wait(&w->signal, &w->lock);
            continue;
        }

        mythread_mutex_unlock(&w->lock);

        const size_t chunk_size = 16384;
        size_t chunk_end = w->input_bytes_consumed + chunk_size;
        if (chunk_end > input_end)
            chunk_end = input_end;

        result = w->block_coder.code(
            w->block_coder.coder, w->mem_allocator,
            w->input_buffer, &w->input_bytes_consumed, chunk_end,
            w->output_buffer->data, &w->output_position,
            w->output_buffer->allocated, LZMA_RUN);

        if (result == LZMA_OK) {
            if (partial_enabled) {
                w->partial_update_done = true;
                mythread_sync(w->main_coder->main_lock) {
                    w->output_buffer->write_pos = w->output_position;
                    w->output_buffer->decoder_input_pos = w->input_bytes_consumed;
                    mythread_cond_signal(&w->main_coder->main_cond);
                }
            }
            continue;
        }

        assert(result != LZMA_STREAM_END || 
               w->input_bytes_consumed == w->input_capacity);
        assert(result != LZMA_STREAM_END ||
               w->output_position == w->block_config.uncompressed_size);

        mythread_sync(w->lock) {
            if (result == LZMA_STREAM_END && 
                w->input_bytes_written != w->input_capacity) {
                result = LZMA_PROG_ERROR;
            }
            if (w->status != THR_TERMINATE)
                w->status = THR_WAITING;
        }

        if (result == LZMA_STREAM_END) {
            lzma_free(w->input_buffer, w->mem_allocator);
            w->input_buffer = NULL;
        }

        mythread_sync(w->main_coder->main_lock) {
            w->main_coder->total_compressed += w->input_bytes_consumed;
            w->main_coder->total_uncompressed += w->output_position;
            w->bytes_in_processed = 0;
            w->bytes_out_processed = 0;

            w->output_buffer->write_pos = w->output_position;
            w->output_buffer->decoder_input_pos = w->input_bytes_consumed;
            w->output_buffer->completed = true;
            w->output_buffer->completion_result = result;
            w->output_buffer = NULL;

            if (result != LZMA_STREAM_END &&
                w->main_coder->worker_error_code == LZMA_OK)
                w->main_coder->worker_error_code = result;

            if (result == LZMA_STREAM_END) {
                w->main_coder->active_memory -= w->input_capacity;
                w->main_coder->active_memory -= w->filter_memory;
                w->main_coder->cached_memory += w->filter_memory;

                w->next_free = w->main_coder->available_threads;
                w->main_coder->available_threads = w;
            }
            mythread_cond_signal(&w->main_coder->main_cond);
        }
    }
}

static void
cleanup_threads(struct lzma_stream_coder *coder, const lzma_allocator *allocator)
{
    for (uint32_t i = 0; i < coder->threads_created; ++i) {
        mythread_sync(coder->thread_pool[i].lock) {
            coder->thread_pool[i].status = THR_TERMINATE;
            mythread_cond_signal(&coder->thread_pool[i].signal);
        }
    }

    for (uint32_t i = 0; i < coder->threads_created; ++i)
        mythread_join(coder->thread_pool[i].thread_id);

    lzma_free(coder->thread_pool, allocator);
    coder->threads_created = 0;
    coder->thread_pool = NULL;
    coder->available_threads = NULL;
    coder->active_memory = 0;
    coder->cached_memory = 0;
}

static void
stop_threads(struct lzma_stream_coder *coder)
{
    for (uint32_t i = 0; i < coder->threads_created; ++i) {
        mythread_sync(coder->thread_pool[i].lock) {
            coder->thread_pool[i].status = THR_WAITING;
        }
    }
}

static lzma_ret
create_new_worker(struct lzma_stream_coder *coder, const lzma_allocator *allocator)
{
    if (coder->thread_pool == NULL) {
        coder->thread_pool = lzma_alloc(
            coder->max_threads * sizeof(struct worker_thread),
            allocator);
        if (coder->thread_pool == NULL)
            return LZMA_MEM_ERROR;
    }

    assert(coder->threads_created < coder->max_threads);
    struct worker_thread *w = &coder->thread_pool[coder->threads_created];

    if (mythread_mutex_init(&w->lock))
        goto mutex_error;
    if (mythread_cond_init(&w->signal))
        goto cond_error;

    w->status = THR_WAITING;
    w->input_buffer = NULL;
    w->input_capacity = 0;
    w->mem_allocator = allocator;
    w->main_coder = coder;
    w->output_buffer = NULL;
    w->block_coder = LZMA_NEXT_CODER_INIT;
    w->filter_memory = 0;

    if (mythread_create(&w->thread_id, worker_function, w))
        goto thread_error;

    ++coder->threads_created;
    coder->current_worker = w;
    return LZMA_OK;

thread_error:
    mythread_cond_destroy(&w->signal);
cond_error:
    mythread_mutex_destroy(&w->lock);
mutex_error:
    return LZMA_MEM_ERROR;
}

static lzma_ret
acquire_worker(struct lzma_stream_coder *coder, const lzma_allocator *allocator)
{
    mythread_sync(coder->main_lock) {
        if (coder->available_threads != NULL) {
            coder->current_worker = coder->available_threads;
            coder->available_threads = coder->available_threads->next_free;
            coder->cached_memory -= coder->current_worker->filter_memory;
        }
    }

    if (coder->current_worker == NULL) {
        assert(coder->threads_created < coder->max_threads);
        return_if_error(create_new_worker(coder, allocator));
    }

    coder->current_worker->input_bytes_written = 0;
    coder->current_worker->input_bytes_consumed = 0;
    coder->current_worker->output_position = 0;
    coder->current_worker->bytes_in_processed = 0;
    coder->current_worker->bytes_out_processed = 0;
    coder->current_worker->partial_update_active = false;
    coder->current_worker->partial_update_done = false;

    return LZMA_OK;
}

static lzma_ret
process_output_and_wait(struct lzma_stream_coder *coder,
                       const lzma_allocator *allocator,
                       uint8_t *restrict out, size_t *restrict out_pos,
                       size_t out_size,
                       bool *input_possible,
                       bool allow_blocking,
                       mythread_condtime *wait_time, bool *has_blocked)
{
    lzma_ret ret = LZMA_OK;

    mythread_sync(coder->main_lock) {
        do {
            size_t start_pos = *out_pos;
            do {
                ret = lzma_outq_read(&coder->output_queue, allocator,
                                   out, out_pos, out_size,
                                   NULL, NULL);
                if (ret == LZMA_STREAM_END)
                    lzma_outq_enable_partial_output(&coder->output_queue,
                                                  &enable_partial_output_callback);
            } while (ret == LZMA_STREAM_END);

            if (ret != LZMA_OK)
                break;

            if (*out_pos == out_size && *out_pos != start_pos)
                coder->buffer_was_full = true;

            if (coder->worker_error_code != LZMA_OK) {
                if (coder->quick_fail) {
                    ret = coder->worker_error_code;
                    break;
                }
                coder->deferred_error = LZMA_PROG_ERROR;
            }

            if (input_possible != NULL &&
                coder->mem_limit_parallel - coder->active_memory -
                coder->output_queue.active_mem >= coder->next_block_memory &&
                lzma_outq_has_buf(&coder->output_queue) &&
                (coder->threads_created < coder->max_threads ||
                 coder->available_threads != NULL)) {
                *input_possible = true;
                break;
            }

            if (!allow_blocking)
                break;

            if (lzma_outq_is_empty(&coder->output_queue)) {
                assert(input_possible == NULL);
                break;
            }

            if (lzma_outq_is_readable(&coder->output_queue)) {
                assert(*out_pos == out_size);
                break;
            }

            if (coder->current_worker != NULL &&
                coder->current_worker->partial_update_active) {
                if (coder->current_worker->output_buffer->decoder_input_pos ==
                    coder->current_worker->input_bytes_written)
                    break;
            }

            if (coder->wait_timeout_ms != 0) {
                if (!*has_blocked) {
                    *has_blocked = true;
                    mythread_condtime_set(wait_time, &coder->main_cond,
                                        coder->wait_timeout_ms);
                }
                if (mythread_cond_timedwait(&coder->main_cond,
                                          &coder->main_lock,
                                          wait_time) != 0) {
                    ret = LZMA_TIMED_OUT;
                    break;
                }
            } else {
                mythread_cond_wait(&coder->main_cond, &coder->main_lock);
            }
        } while (ret == LZMA_OK);
    }

    if (ret != LZMA_OK && ret != LZMA_TIMED_OUT)
        stop_threads(coder);

    return ret;
}

static lzma_ret
decode_block_header(struct lzma_stream_coder *coder,
                   const lzma_allocator *allocator, const uint8_t *restrict in,
                   size_t *restrict in_pos, size_t in_size)
{
    if (*in_pos >= in_size)
        return LZMA_OK;

    if (coder->buffer_pos == 0) {
        if (in[*in_pos] == INDEX_INDICATOR)
            return LZMA_INDEX_DETECTED;

        coder->block_options.header_size =
            lzma_block_header_size_decode(in[*in_pos]);
    }

    lzma_bufcpy(in, in_pos, in_size, coder->temp_buffer, &coder->buffer_pos,
               coder->block_options.header_size);

    if (coder->buffer_pos < coder->block_options.header_size)
        return LZMA_OK;

    coder->buffer_pos = 0;
    coder->block_options.version = 1;
    coder->block_options.filters = coder->filters;

    return_if_error(lzma_block_header_decode(&coder->block_options,
                                           allocator, coder->temp_buffer));

    coder->block_options.ignore_check = coder->skip_integrity_check;

    return LZMA_STREAM_END;
}

static size_t
get_compressed_block_size(const struct lzma_stream_coder *coder)
{
    return vli_ceil4(coder->block_options.compressed_size)
         + lzma_check_size(coder->stream_props.check);
}

static bool
needs_single_threaded_mode(lzma_vli size)
{
    return size == LZMA_VLI_UNKNOWN || size > SIZE_MAX / 3;
}

static lzma_ret
reset_stream_decoder(struct lzma_stream_coder *coder,
                    const lzma_allocator *allocator)
{
    coder->index_checksum = lzma_index_hash_init(coder->index_checksum, allocator);
    if (coder->index_checksum == NULL)
        return LZMA_MEM_ERROR;

    coder->current_state = HDR_STREAM;
    coder->buffer_pos = 0;
    return LZMA_OK;
}

static lzma_ret
multi_threaded_decode(void *coder_ptr, const lzma_allocator *allocator,
                     const uint8_t *restrict in, size_t *restrict in_pos,
                     size_t in_size,
                     uint8_t *restrict out, size_t *restrict out_pos,
                     size_t out_size, lzma_action action)
{
    struct lzma_stream_coder *coder = (struct lzma_stream_coder *)coder_ptr;
    mythread_condtime wait_time;
    bool has_blocked = false;

    const bool blocking_allowed = action == LZMA_FINISH ||
        (*in_pos == in_size && !coder->buffer_was_full);
    coder->buffer_was_full = false;

    while (true) {
        switch (coder->current_state) {
            case HDR_STREAM: {
                size_t in_start = *in_pos;
                lzma_bufcpy(in, in_pos, in_size, coder->temp_buffer,
                           &coder->buffer_pos, LZMA_STREAM_HEADER_SIZE);
                coder->total_compressed += *in_pos - in_start;

                if (coder->buffer_pos < LZMA_STREAM_HEADER_SIZE)
                    return LZMA_OK;

                coder->buffer_pos = 0;

                const lzma_ret ret = lzma_stream_header_decode(
                    &coder->stream_props, coder->temp_buffer);
                if (ret != LZMA_OK)
                    return ret == LZMA_FORMAT_ERROR && !coder->first_stream_data
                        ? LZMA_DATA_ERROR : ret;

                coder->first_stream_data = false;
                coder->block_options.check = coder->stream_props.check;
                coder->current_state = HDR_BLOCK;

                if (coder->check_none_warning && 
                    coder->stream_props.check == LZMA_CHECK_NONE)
                    return LZMA_NO_CHECK;
                if (coder->check_unsupported_warning &&
                    !lzma_check_is_supported(coder->stream_props.check))
                    return LZMA_UNSUPPORTED_CHECK;
                if (coder->any_check_warning)
                    return LZMA_GET_CHECK;

                FALLTHROUGH;
            }

            case HDR_BLOCK: {
                size_t in_start = *in_pos;
                const lzma_ret ret = decode_block_header(coder, allocator,
                    in, in_pos, in_size);
                coder->total_compressed += *in_pos - in_start;

                if (ret == LZMA_OK) {
                    assert(*in_pos == in_size);

                    if (action == LZMA_FINISH && coder->quick_fail) {
                        stop_threads(coder);
                        return LZMA_DATA_ERROR;
                    }

                    return_if_error(process_output_and_wait(coder, allocator,
                        out, out_pos, out_size, NULL, blocking_allowed,
                        &wait_time, &has_blocked));
                    if (coder->deferred_error != LZMA_OK) {
                        coder->current_state = ERROR_STATE;
                        break;
                    }
                    return LZMA_OK;
                }

                if (ret == LZMA_INDEX_DETECTED) {
                    coder->current_state = WAIT_INDEX_OUTPUT;
                    break;
                }

                if (ret != LZMA_STREAM_END) {
                    coder->deferred_error = ret;
                    coder->current_state = ERROR_STATE;
                    break;
                }

                coder->next_filters_memory = lzma_raw_decoder_memusage(
                    coder->filters);
                if (coder->next_filters_memory == UINT64_MAX) {
                    coder->deferred_error = LZMA_OPTIONS_ERROR;
                    coder->current_state = ERROR_STATE;
                    break;
                }

                coder->current_state = INIT_BLOCK;
                FALLTHROUGH;
            }

            case INIT_BLOCK: {
                if (coder->next_filters_memory > coder->mem_hard_limit) {
                    return_if_error(process_output_and_wait(coder, allocator,
                        out, out_pos, out_size, NULL, true,
                        &wait_time, &has_blocked));
                    if (!lzma_outq_is_empty(&coder->output_queue))
                        return LZMA_OK;
                    return LZMA_MEMLIMIT_ERROR;
                }

                if (needs_single_threaded_mode(coder->block_options.compressed_size) ||
                    needs_single_threaded_mode(coder->block_options.uncompressed_size)) {
                    coder->current_state = INIT_DIRECT_BLOCK;
                    break;
                }

                coder->next_input_memory = get_compressed_block_size(coder);
                const uint64_t buffer_memory = coder->next_input_memory +
                    lzma_outq_outbuf_memusage(
                        coder->block_options.uncompressed_size);

                if (UINT64_MAX - buffer_memory < coder->next_filters_memory) {
                    coder->current_state = INIT_DIRECT_BLOCK;
                    break;
                }

                coder->next_block_memory = coder->next_filters_memory + buffer_memory;

                if (coder->next_block_memory > coder->mem_limit_parallel) {
                    coder->current_state = INIT_DIRECT_BLOCK;
                    break;
                }

                lzma_next_end(&coder->block_decoder, allocator);
                coder->direct_mode_memory = 0;

                const lzma_ret ret = lzma_index_hash_append(coder->index_checksum,
                    lzma_block_unpadded_size(&coder->block_options),
                    coder->block_options.uncompressed_size);
                if (ret != LZMA_OK) {
                    coder->deferred_error = ret;
                    coder->current_state = ERROR_STATE;
                    break;
                }

                coder->current_state = INIT_THREAD_BLOCK;
                FALLTHROUGH;
            }

            case INIT_THREAD_BLOCK: {
                bool block_can_start = false;
                return_if_error(process_output_and_wait(coder, allocator,
                    out, out_pos, out_size, &block_can_start, true,
                    &wait_time, &has_blocked));
                if (coder->deferred_error != LZMA_OK) {
                    coder->current_state = ERROR_STATE;
                    break;
                }

                if (!block_can_start) {
                    assert(*out_pos == out_size);
                    assert(!lzma_outq_is_empty(&coder->output_queue));
                    return LZMA_OK;
                }

                uint64_t active_mem = 0;
                uint64_t cached_mem = 0;
                struct worker_thread *w = NULL;

                mythread_sync(coder->main_lock) {
                    active_mem = coder->active_memory;
                    cached_mem = coder->cached_memory;
                    w = coder->available_threads;
                }

                const uint64_t max_mem = coder->mem_limit_parallel -
                    coder->next_block_memory;

                if (active_mem + cached_mem + coder->output_queue.allocated_mem >
                    max_mem) {
                    lzma_outq_clear_cache2(&coder->output_queue, allocator,
                        coder->block_options.uncompressed_size);
                }

                uint64_t freed_mem = 0;
                if (w != NULL && active_mem + cached_mem +
                    coder->output_queue.active_mem > max_mem) {
                    if (w->filter_memory <= coder->next_filters_memory)
                        w = w->next_free;
                    while (w != NULL) {
                        lzma_next_end(&w->block_coder, allocator);
                        freed_mem += w->filter_memory;
                        w->filter_memory = 0;
                        w = w->next_free;
                    }
                }

                mythread_sync(coder->main_lock) {
                    coder->cached_memory -= freed_mem;
                    coder->active_memory += coder->next_input_memory +
                        coder->next_filters_memory;
                }

                lzma_ret ret = lzma_outq_prealloc_buf(&coder->output_queue,
                    allocator, coder->block_options.uncompressed_size);
                if (ret != LZMA_OK) {
                    stop_threads(coder);
                    return ret;
                }

                ret = acquire_worker(coder, allocator);
                if (ret != LZMA_OK) {
                    stop_threads(coder);
                    return ret;
                }

                coder->current_worker->filter_memory = coder->next_filters_memory;
                coder->current_worker->block_config = coder->block_options;

                ret = lzma_block_decoder_init(&coder->current_worker->block_coder,
                    allocator, &coder->current_worker->block_config);

                lzma_filters_free(coder->filters, allocator);
                coder->current_worker->block_config.filters = NULL;

                if (ret != LZMA_OK) {
                    coder->deferred_error = ret;
                    coder->current_state = ERROR_STATE;
                    break;
                }

                coder->current_worker->input_capacity = coder->next_input_memory;
                coder->current_worker->input_buffer = lzma_alloc(
                    coder->current_worker->input_capacity, allocator);
                if (coder->current_worker->input_buffer == NULL) {
                    stop_threads(coder);
                    return LZMA_MEM_ERROR;
                }

                coder->current_worker->output_buffer = lzma_outq_get_buf(
                    &coder->output_queue, coder->current_worker);

                mythread_sync(coder->current_worker->lock) {
                    assert(coder->current_worker->status == THR_WAITING);
                    coder->current_worker->status = THR_ACTIVE;
                    mythread_cond_signal(&coder->current_worker->signal);
                }

                mythread_sync(coder->main_lock) {
                    lzma_outq_enable_partial_output(&coder->output_queue,
                        &enable_partial_output_callback);
                }

                coder->current_state = RUN_THREAD_BLOCK;
                FALLTHROUGH;
            }

            case RUN_THREAD_BLOCK: {
                if (action == LZMA_FINISH && coder->quick_fail) {
                    size_t available = in_size - *in_pos;
                    size_t needed = coder->current_worker->input_capacity -
                        coder->current_worker->input_bytes_written;
                    if (available < needed) {
                        stop_threads(coder);
                        return LZMA_DATA_ERROR;
                    }
                }

                size_t current_write = coder->current_worker->input_bytes_written;
                lzma_bufcpy(in, in_pos, in_size, coder->current_worker->input_buffer,
                           &current_write, coder->current_worker->input_capacity);

                mythread_sync(coder->current_worker->lock) {
                    coder->current_worker->input_bytes_written = current_write;
                    mythread_cond_signal(&coder->current_worker->signal);
                }

                return_if_error(process_output_and_wait(coder, allocator,
                    out, out_pos, out_size, NULL,
                    blocking_allowed && *in_pos == in_size,
                    &wait_time, &has_blocked));

                if (coder->deferred_error != LZMA_OK) {
                    coder->current_state = ERROR_STATE;
                    break;
                }

                if (coder->current_worker->input_bytes_written <
                    coder->current_worker->input_capacity) {
                    assert(*in_pos == in_size);
                    return LZMA_OK;
                }

                coder->current_worker = NULL;
                coder->current_state = HDR_BLOCK;
                break;
            }

            case INIT_DIRECT_BLOCK: {
                return_if_error(process_output_and_wait(coder, allocator,
                    out, out_pos, out_size, NULL, true,
                    &wait_time, &has_blocked));
                if (!lzma_outq_is_empty(&coder->output_queue))
                    return LZMA_OK;

                lzma_outq_clear_cache(&coder->output_queue, allocator);
                cleanup_threads(coder, allocator);

                const lzma_ret ret = lzma_block_decoder_init(&coder->block_decoder,
                    allocator, &coder->block_options);
                lzma_filters_free(coder->filters, allocator);
                coder->block_options.filters = NULL;

                if (ret != LZMA_OK)
                    return ret;

                coder->direct_mode_memory = coder->next_filters_memory;
                coder->current_state = RUN_DIRECT_BLOCK;
                FALLTHROUGH;
            }

            case RUN_DIRECT_BLOCK: {
                size_t in_start = *in_pos;
                size_t out_start = *out_pos;
                const lzma_ret ret = coder->block_decoder.code(
                    coder->block_decoder.coder, allocator,
                    in, in_pos, in_size, out, out_pos, out_size, action);

                coder->total_compressed += *in_pos - in_start;
                coder->total_uncompressed += *out_pos - out_start;

                if (ret != LZMA_STREAM_END)
                    return ret;

                return_if_error(lzma_index_hash_append(coder->index_checksum,
                    lzma_block_unpadded_size(&coder->block_options),
                    coder->block_options.uncompressed_size));

                coder->current_state = HDR_BLOCK;
                break;
            }

            case WAIT_INDEX_OUTPUT:
                return_if_error(process_output_and_wait(coder, allocator,
                    out, out_pos, out_size, NULL, true,
                    &wait_time, &has_blocked));
                if (!lzma_outq_is_empty(&coder->output_queue))
                    return LZMA_OK;
                coder->current_state = DECODE_INDEX;
                FALLTHROUGH;

            case DECODE_INDEX: {
                if (*in_pos >= in_size)
                    return LZMA_OK;

                size_t in_start = *in_pos;
                const lzma_ret ret = lzma_index_hash_decode(coder->index_checksum,
                    in, in_pos, in_size);
                coder->total_compressed += *in_pos - in_start;

                if (ret != LZMA_STREAM_END)
                    return ret;

                coder->current_state = FOOTER_STREAM;
                FALLTHROUGH;
            }

            case FOOTER_STREAM: {
                size_t in_start = *in_pos;
                lzma_bufcpy(in, in_pos, in_size, coder->temp_buffer,
                           &coder->buffer_pos, LZMA_STREAM_HEADER_SIZE);
                coder->total_compressed += *in_pos - in_start;

                if (coder->buffer_pos < LZMA_STREAM_HEADER_SIZE)
                    return LZMA_OK;

                coder->buffer_pos = 0;

                lzma_stream_flags footer_flags;
                const lzma_ret ret = lzma_stream_footer_decode(&footer_flags,
                    coder->temp_buffer);
                if (ret != LZMA_OK)
                    return ret == LZMA_FORMAT_ERROR ? LZMA_DATA_ERROR : ret;

                if (lzma_index_hash_size(coder->index_checksum) !=
                    footer_flags.backward_size)
                    return LZMA_DATA_ERROR;

                return_if_error(lzma_stream_flags_compare(
                    &coder->stream_props, &footer_flags));

                if (!coder->allow_concatenated)
                    return LZMA_STREAM_END;

                coder->current_state = PADDING_STREAM;
                FALLTHROUGH;
            }

            case PADDING_STREAM: {
                assert(coder->allow_concatenated);
                while (true) {
                    if (*in_pos >= in_size) {
                        if (action != LZMA_FINISH)
                            return LZMA_OK;
                        return coder->buffer_pos == 0
                            ? LZMA_STREAM_END
                            : LZMA_DATA_ERROR;
                    }

                    if (in[*in_pos] != 0x00)
                        break;

                    ++*in_pos;
                    ++coder->total_compressed;
                    coder->buffer_pos = (coder->buffer_pos + 1) & 3;
                }

                if (coder->buffer_pos != 0) {
                    ++*in_pos;
                    ++coder->total_compressed;
                    return LZMA_DATA_ERROR;
                }

                return_if_error(reset_stream_decoder(coder, allocator));
                break;
            }

            case ERROR_STATE: {
                if (!coder->quick_fail) {
                    return_if_error(process_output_and_wait(coder, allocator,
                        out, out_pos, out_size, NULL, true,
                        &wait_time, &has_blocked));
                    if (!lzma_outq_is_empty(&coder->output_queue))
                        return LZMA_OK;
                }
                return coder->deferred_error;
            }
        }
    }
}

static void
cleanup_multi_thread_decoder(void *coder_ptr, const lzma_allocator *allocator)
{
    struct lzma_stream_coder *coder = (struct lzma_stream_coder *)coder_ptr;
    cleanup_threads(coder, allocator);
    lzma_outq_end(&coder->output_queue, allocator);
    lzma_next_end(&coder->block_decoder, allocator);
    lzma_filters_free(coder->filters, allocator);
    lzma_index_hash_end(coder->index_checksum, allocator);
    lzma_free(coder, allocator);
}

static lzma_check
get_checksum_type(const void *coder_ptr)
{
    const struct lzma_stream_coder *coder = (const struct lzma_stream_coder *)coder_ptr;
    return coder->stream_props.check;
}

static lzma_ret
configure_memory_usage(void *coder_ptr, uint64_t *memusage,
                      uint64_t *old_memlimit, uint64_t new_memlimit)
{
    struct lzma_stream_coder *coder = (struct lzma_stream_coder *)coder_ptr;

    mythread_sync(coder->main_lock) {
        *memusage = coder->direct_mode_memory +
                   coder->active_memory +
                   coder->cached_memory +
                   coder->output_queue.allocated_mem;
    }

    if (*memusage < LZMA_MEMUSAGE_BASE)
        *memusage = LZMA_MEMUSAGE_BASE;

    *old_memlimit = coder->mem_hard_limit;

    if (new_memlimit != 0) {
        if (new_memlimit < *memusage)
            return LZMA_MEMLIMIT_ERROR;
        coder->mem_hard_limit = new_memlimit;
    }

    return LZMA_OK;
}

static void
get_progress_info(void *coder_ptr, uint64_t *progress_in, uint64_t *progress_out)
{
    struct lzma_stream_coder *coder = (struct lzma_stream_coder *)coder_ptr;

    mythread_sync(coder->main_lock) {
        *progress_in = coder->total_compressed;
        *progress_out = coder->total_uncompressed;

        for (size_t i = 0; i < coder->threads_created; ++i) {
            mythread_sync(coder->thread_pool[i].lock) {
                *progress_in += coder->thread_pool[i].bytes_in_processed;
                *progress_out += coder->thread_pool[i].bytes_out_processed;
            }
        }
    }
}

static lzma_ret
initialize_multi_thread_decoder(lzma_next_coder *next, const lzma_allocator *allocator,
                               const lzma_mt *options)
{
    struct lzma_stream_coder *coder;

    if (options->threads == 0 || options->threads > LZMA_THREADS_MAX)
        return LZMA_OPTIONS_ERROR;
    if (options->flags & ~LZMA_SUPPORTED_FLAGS)
        return LZMA_OPTIONS_ERROR;

    lzma_next_coder_init(&initialize_multi_thread_decoder, next, allocator);

    coder = next->coder;
    if (!coder) {
        coder = lzma_alloc(sizeof(struct lzma_stream_coder), allocator);
        if (coder == NULL)
            return LZMA_MEM_ERROR;
        next->coder = coder;

        if (mythread_mutex_init(&coder->main_lock)) {
            lzma_free(coder, allocator);
            return LZMA_MEM_ERROR;
        }
        if (mythread_cond_init(&coder->main_cond)) {
            mythread_mutex_destroy(&coder->main_lock);
            lzma_free(coder, allocator);
            return LZMA_MEM_ERROR;
        }

        next->code = &multi_threaded_decode;
        next->end = &cleanup_multi_thread_decoder;
        next->get_check = &get_checksum_type;
        next->memconfig = &configure_memory_usage;
        next->get_progress = &get_progress_info;

        coder->filters[0].id = LZMA_VLI_UNKNOWN;
        memzero(&coder->output_queue, sizeof(coder->output_queue));
        coder->block_decoder = LZMA_NEXT_CODER_INIT;
        coder->direct_mode_memory = 0;
        coder->index_checksum = NULL;
        coder->thread_pool = NULL;
        coder->available_threads = NULL;
        coder->threads_created = 0;
    }

    lzma_filters_free(coder->filters, allocator);

    cleanup_threads(coder, allocator);

    coder->active_memory = 0;
    coder->cached_memory = 0;
    coder->next_block_memory = 0;
    coder->total_compressed = 0;
    coder->total_uncompressed = 0;
    coder->current_state = HDR_STREAM;
    coder->worker_error_code = LZMA_OK;
    coder->deferred_error = LZMA_OK;
    coder->current_worker = NULL;
    coder->wait_timeout_ms = options->timeout;
    coder->mem_limit_parallel = my_max(1, options->memlimit_threading);
    coder->mem_hard_limit = my_max(1, options->memlimit_stop);

    if (coder->mem_limit_parallel > coder->mem_hard_limit)
        coder->mem_limit_parallel = coder->mem_hard_limit;

    coder->check_none_warning = (options->flags & LZMA_TELL_NO_CHECK) != 0;
    coder->check_unsupported_warning = (options->flags & LZMA_TELL_UNSUPPORTED_CHECK) != 0;
    coder->any_check_warning = (options->flags & LZMA_TELL_ANY_CHECK) != 0;
    coder->skip_integrity_check = (options->flags & LZMA_IGNORE_CHECK) != 0;
    coder->allow_concatenated = (options->flags & LZMA_CONCATENATED) != 0;
    coder->quick_fail = (options->flags & LZMA_FAIL_FAST) != 0;
    coder->first_stream_data = true;
    coder->buffer_was_full = false;
    coder->buffer_pos = 0;
    coder->max_threads = options->threads;

    return_if_error(lzma_outq_init(&coder->output_queue, allocator,
                                  coder->max_threads));
    return reset_stream_decoder(coder, allocator);
}

extern LZMA_API(lzma_ret)
lzma_stream_decoder_mt(lzma_stream *strm, const lzma_mt *options)
{
    lzma_next_strm_init(initialize_multi_thread_decoder, strm, options);
    strm->internal->supported_actions[LZMA_RUN] = true;
    strm->internal->supported_actions[LZMA_FINISH] = true;
    return LZMA_OK;
}

#include "core/orchestrator_openai.h"
#include "absl/strings/match.h"
#include "core/database.h"
#include "core/http_client.h"
#include <gtest/gtest.h>

namespace slop {

class OpenAiOrchestratorTest : public ::testing::Test {
 protected:
  Database db;
  HttpClient http;
  void SetUp() override { ASSERT_TRUE(db.Init(":memory:").ok()); }
};

TEST_F(OpenAiOrchestratorTest, PayloadStructureBasic) {
  OpenAiOrchestrator orchestrator(&db, &http, "gpt-4-turbo", "https://api.openai.com/v1");
  auto result = orchestrator.AssemblePayload("session1", "You are helpful.", {});
  ASSERT_TRUE(result.ok());
  nlohmann::json payload = *result;

  // Confirm essential structure
  EXPECT_STREQ(payload["model"].get<std::string>().c_str(), "gpt-4-turbo");
  ASSERT_TRUE(payload.contains("messages"));
  ASSERT_TRUE(payload["messages"].is_array());
}

TEST_F(OpenAiOrchestratorTest, OpenAiProactiveFiltering) {
  OpenAiOrchestrator orchestrator(&db, &http, "gpt-4", "https://api.openai.com/v1");

  // Register only tool1 as allowed (top-level exposed)
  ASSERT_TRUE(db.RegisterTool({"tool1", "desc1", "{}", true}).ok());

  // Simulate two tool calls: tool1 (allowed) and tool2 (not registered → suppressed)
  nlohmann::json assistant_msg1 = {
      {"role", "assistant"},
      {"tool_calls", {{{"id", "call_1"}, {"type", "function"}, 
                       {"function", {{"name", "tool1"}, {"arguments", "{}"}}}}}}};
  nlohmann::json tool_resp1 = {
      {"role", "tool"},
      {"tool_call_id", "call_1"},
      {"content", "res1"}};

  nlohmann::json assistant_msg2 = {
      {"role", "assistant"},
      {"tool_calls", {{{"id", "call_2"}, {"type", "function"}, 
                       {"function", {{"name", "tool2"}, {"arguments", "{}"}}}}}}};
  nlohmann::json user_msg2 = {
      {"role", "user"},
      {"content", "Suppressed tool call for unregistered tool: tool2"}};

  // Record messages in the database
  ASSERT_TRUE(db.AppendMessage("s1", "assistant", assistant_msg1.dump(), "call_1|tool1", "tool_call").ok());
  ASSERT_TRUE(db.AppendMessage("s1", "tool", tool_resp1.dump(), "call_1|tool1", "completed").ok());
  ASSERT_TRUE(db.AppendMessage("s1", "assistant", assistant_msg2.dump(), "call_2|tool2", "tool_call").ok());
  ASSERT_TRUE(db.AppendMessage("s1", "user", user_msg2.dump(), "call_2|tool2", "suppressed").ok());

  // Retrieve conversation history and assemble payload
  auto history_or = db.GetConversationHistory("s1", false);
  ASSERT_TRUE(history_or.ok());

  auto payload_or = orchestrator.AssemblePayload("s1", "System prompt", *history_or);
  ASSERT_TRUE(payload_or.ok());
  nlohmann::json payload = *payload_or;

  nlohmann::json messages = payload["messages"];

  // Validate message order and content
  // Index 0: system
  EXPECT_EQ(messages[0]["role"], "system");

  // Index 1: assistant with tool1 call (preserved)
  EXPECT_EQ(messages[1]["role"], "assistant");
  EXPECT_TRUE(messages[1].contains("tool_calls"));
  EXPECT_EQ(messages[1]["tool_calls"][0]["function"]["name"], "tool1");

  // Index 2: tool response for tool1 (preserved)
  EXPECT_EQ(messages[2]["role"], "tool");
  EXPECT_EQ(messages[2]["tool_call_id"], "call_1");

  // Index 3: assistant with suppressed tool2 call (no tool_calls, replaced by content note)
  EXPECT_EQ(messages[3]["role"], "assistant");
  EXPECT_FALSE(messages[3].contains("tool_calls"));
  std::string content3 = messages[3]["content"].get<std::string>();
  EXPECT_TRUE(absl::StrContains(content3, "suppressed"));

  // Index 4: user message indicating suppression of tool2
  EXPECT_EQ(messages[4]["role"], "user");
  std::string content4 = messages[4]["content"].get<std::string>();
  EXPECT_TRUE(absl::StrContains(content4, "suppressed"));
}

