#include <iostream>
#include <vector>
#include <string>

int main() {
    // Optimize I/O for competitive programming scenarios
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    // Grid dimensions as specified
    const int rows = 20;
    const int cols = 20;

    // Output grid size information
    std::cout << rows << " " << cols << '\n';

    // Initialize grid with walls ('0')
    std::vector<std::string> map(rows, std::string(cols, '0'));

    // Select a central point for the cross (slightly off-center is acceptable)
    const int mid_row = 10;
    const int mid_col = 10;

    // Draw vertical line of the cross
    for (int r = 0; r < rows; ++r) {
        map[r][mid_col] = '1';
    }

    // Draw horizontal line of the cross
    for (int c = 0; c < cols; ++c) {
        map[mid_row][c] = '1';
    }

    // Display the resulting pattern
    for (int r = 0; r < rows; ++r) {
        std::cout << map[r] << '\n';
    }

    return 0;
}

#include <iostream>
#include <nlohmann/json.hpp>

using json = nlohmann::json;

int main() {
    // Valid JSON pointer constructions
    json::json_pointer ptr1;
    json::json_pointer ptr2("");
    json::json_pointer ptr3("/");
    json::json_pointer ptr4("//");
    json::json_pointer ptr5("/foo/bar");
    json::json_pointer ptr6("/foo/bar/-");
    json::json_pointer ptr7("/foo/~0");
    json::json_pointer ptr8("/foo/~1");

    // Invalid: missing leading slash
    try {
        json::json_pointer invalidPtr1("invalid");
    } catch (const json::parse_error& error) {
        std::cout << error.what() << '\n';
    }

    // Invalid: tilde not followed by 0 or 1
    try {
        json::json_pointer invalidPtr2("/path/~");
    } catch (const json::parse_error& error) {
        std::cout << error.what() << '\n';
    }

    // Invalid: tilde followed by invalid digit
    try {
        json::json_pointer invalidPtr3("/path/~2");
    } catch (const json::parse_error& error) {
        std::cout << error.what() << '\n';
    }

    return 0;
}

#include <iostream>
#include <algorithm>
#include <vector>
#include <cstdlib>
#include <ctime>
using namespace std;

typedef long long ll;

ll n;

// Compute the shortest distance between u and v on a cycle of length n
ll compute_cycle_distance(ll u, ll v) {
    if (u > v) swap(u, v);
    ll direct = v - u;
    ll wrap = n - direct;
    return min(direct, wrap);
}

// Ask the judge about the shortest path between two nodes
ll query_distance(ll u, ll v) {
    cout << "? " << u << " " << v << endl;
    ll result;
    cin >> result;
    return result;
}

// Submit a guess for an edge and check correctness
bool submit_guess(ll u, ll v) {
    if (u == v) return false;

    cout << "! " << u << " " << v << endl;
    int verdict;
    cin >> verdict;

    if (verdict == -1) {
        exit(0); // Incorrect guess, terminate immediately
    }
    return true;
}

void process_test_case() {
    cin >> n;

    ll candidate_u = -1, candidate_v = -1;

    // Seed random number generator with current time
    srand(static_cast<unsigned>(time(nullptr)));

    // Attempt to find a chord by testing random pairs
    for (int attempt = 0; attempt < 200; ++attempt) {
        ll node_a = (rand() % n) + 1;
        ll node_b;

        // Try to pick a point roughly opposite to maximize chance of chord usage
        if (attempt % 3 == 0) {
            ll offset = (rand() % (n / 4)) + (n / 4);
            node_b = ((node_a + offset - 1) % n) + 1;
        } else {
            node_b = ((node_a + n / 2 - 1) % n) + 1;
        }

        if (node_a == node_b) continue;

        ll actual_dist = query_distance(node_a, node_b);
        ll cycle_dist = compute_cycle_distance(node_a, node_b);

        if (actual_dist < cycle_dist) {
            candidate_u = node_a;
            candidate_v = node_b;
            break;
        }
    }

    // Fallback case: no chord found in search — try arbitrary pair
    if (candidate_u == -1) {
        submit_guess(1, 2);
        return;
    }

    // Helper lambda to find chord along a specific direction
    auto find_chord_along_direction = [&](bool clockwise) -> pair<ll, ll> {
        ll arc_length_cw = (candidate_v - candidate_u + n) % n;
        ll arc_length_ccw = (candidate_u - candidate_v + n) % n;
        ll arc_len = clockwise ? arc_length_cw : arc_length_ccw;

        // Function to get vertex at offset i from candidate_u along chosen direction
        auto get_vertex_at_offset = [&](ll offset) -> ll {
            if (clockwise) {
                return ((candidate_u + offset - 1) % n) + 1;
            } else {
                return ((candidate_u - offset + n - 1) % n) + 1;
            }
        };

        // Compute expected saving using known distances
        ll base_saving = arc_len - query_distance(candidate_u, candidate_v);
        if (base_saving <= 0) return {-1, -1};

        ll required_gap = base_saving + 1;

        // Binary search for first position where saving reaches required level
        ll left = 1, right = arc_len;
        ll found_index = -1;

        while (left <= right) {
            ll mid = left + (right - left) / 2;
            ll mid_vertex = get_vertex_at_offset(mid);
            ll measured_dist = query_distance(candidate_u, mid_vertex);
            ll current_saving = mid - measured_dist;

            if (current_saving >= base_saving) {
                found_index = mid;
                right = mid - 1;
            } else {
                left = mid + 1;
            }
        }

        if (found_index != -1) {
            ll end_idx = found_index - required_gap;
            if (end_idx >= 0) {
                ll start_vertex = get_vertex_at_offset(end_idx);
                ll end_vertex = get_vertex_at_offset(found_index);
                return {start_vertex, end_vertex};
            }
        }
        return {-1, -1};
    };

    // Try clockwise direction first
    pair<ll, ll> possible_edge = find_chord_along_direction(true);
    if (possible_edge.first != -1) {
        if (compute_cycle_distance(possible_edge.first, possible_edge.second) > 1) {
            ll dist_check = query_distance(possible_edge.first, possible_edge.second);
            if (dist_check == 1) {
                submit_guess(possible_edge.first, possible_edge.second);
                return;
            }
        }
    }

    // If not found CW, try CCW
    possible_edge = find_chord_along_direction(false);
    if (possible_edge.first != -1) {
        submit_guess(possible_edge.first, possible_edge.second);
        return;
    }

    // Ultimate fallback (should never happen)
    submit_guess(1, 3);
}

int main() {
    int test_count;
    if (cin >> test_count) {
        while (test_count--) {
            process_test_case();
        }
    }
    return 0;
}

