#include <iostream>
#include <sstream>
#include <string>
#include <vector>
using namespace std;

int main() {
    int test_cases;
    cin >> test_cases;

    for (int case_num = 0; case_num < test_cases; ++case_num) {
        int nodes, edges, initial_node, moves_so_far;
        cin >> nodes >> edges >> initial_node >> moves_so_far;

        // Skip edge input
        for (int i = 0; i < edges; ++i) {
            int u, v;
            cin >> u >> v;
        }

        // Clear any leftover newline
        cin.ignore();

        bool finished = false;
        while (!finished) {
            string input_line;
            getline(cin, input_line);

            if (input_line.empty()) {
                continue;
            }

            // Check for termination commands
            if (input_line[0] == 'A' || input_line[0] == 'F') {
                finished = true;
                continue;
            }

            // Parse the line to get degree and neighbor info
            istringstream parser(input_line);
            int degree;
            parser >> degree;

            vector<int> neighbors(degree), visited_flags(degree);
            for (int idx = 0; idx < degree; ++idx) {
                parser >> neighbors[idx] >> visited_flags[idx];
            }

            // Determine next move: prefer unvisited neighbor first
            int selected_move = 1;  // Default to first option

            for (int j = 0; j < degree; ++j) {
                if (visited_flags[j] == 0) {
                    selected_move = j + 1;
                    break;
                }
            }

            cout << selected_move << endl;
            cout.flush();
        }
    }

    return 0;
}

