// Forward declarations for the demangler structure
namespace dlang_demangle {
    class OutputBuffer;
    bool starts_with(std::string_view, const char*);

    class Demangler {
    public:
        Demangler(std::string_view input);
        const char* processMangledName(OutputBuffer& output);

    private:
        std::string_view source;
        int lastReferencePos;

        void decodeInteger(std::string_view&, unsigned long&);
        bool extractBackrefPosition(std::string_view&, long&);
        bool resolveBackref(std::string_view&, std::string_view&);
        void handleSymbolReference(OutputBuffer&, std::string_view&);
        void handleTypeReference(std::string_view&);
        bool isValidIdentifierStart(std::string_view) const;
        void processIdentifier(OutputBuffer&, std::string_view&);
        void processLongIdentifier(OutputBuffer&, std::string_view&, unsigned long);
        void processQualified(OutputBuffer&, std::string_view&);
        bool processType(std::string_view&);
        void processSpecialSymbols(OutputBuffer&, std::string_view&, unsigned long);
    };
}

// Simplified OutputBuffer implementation for demonstration
