bool dlang_demangle::starts_with(std::string_view sv, const char* prefix) {
    size_t len = strlen(prefix);
    return sv.substr(0, len) == std::string_view(prefix, len);
}

dlang_demangle::Demangler::Demangler(std::string_view input)
    : source(input), lastReferencePos(static_cast<int>(input.length())) {}

void dlang_demangle::Demangler::decodeInteger(std::string_view& input, unsigned long& result) {
    if (input.empty() || !std::isdigit(input.front())) {
        input = {};
        result = 0;
        return;
    }

    unsigned long value = 0;
    do {
        unsigned long digit = input[0] - '0';
        // Overflow check
        if (value > (std::numeric_limits<unsigned int>::max() - digit) / 10) {
            input = {};
            result = 0;
            return;
        }
        value = value * 10 + digit;
        input.remove_prefix(1);
    } while (!input.empty() && std::isdigit(input.front()));

    if (input.empty()) {
        input = {};
        result = 0;
        return;
    }
    result = value;
}

bool dlang_demangle::Demangler::extractBackrefPosition(std::string_view& input, long& result) {
    if (input.empty()) {
        input = {};
        return false;
    }

    unsigned long value = 0;
    while (!input.empty() && std::isalpha(input.front())) {
        // Overflow protection
        if (value > (std::numeric_limits<unsigned long>::max() - 25) / 26)
            break;

        value *= 26;
        if (input[0] >= 'a' && input[0] <= 'z') {
            value += input[0] - 'a';
            if (static_cast<long>(value) <= 0)
                break;
            result = static_cast<long>(value);
            input.remove_prefix(1);
            return true;
        }
        value += input[0] - 'A';
        input.remove_prefix(1);
    }

    input = {};
    return false;
}

bool dlang_demangle::Demangler::resolveBackref(std::string_view& input, std::string_view& result) {
    if (input.empty() || input.front() != 'Q') {
        result = {};
        return false;
    }

    const char* qPosition = input.data();
    long refPosition;
    input.remove_prefix(1);

    if (!extractBackrefPosition(input, refPosition)) {
        input = {};
        return false;
    }

    if (refPosition > (qPosition - source.data())) {
        input = {};
        return false;
    }

    result = std::string_view(qPosition - refPosition, refPosition);
    return true;
}

void dlang_demangle::Demangler::handleSymbolReference(dlang_demangle::OutputBuffer& output, std::string_view& input) {
    unsigned long length;
    std::string_view backref;

    if (!resolveBackref(input, backref)) {
        input = {};
        return;
    }

    decodeInteger(backref, length);
    if (backref.empty() || backref.length() < length) {
        input = {};
        return;
    }

    processLongIdentifier(output, backref, length);
    if (backref.empty())
        input = {};
}

void dlang_demangle::Demangler::handleTypeReference(std::string_view& input) {
    if (input.data() - source.data() >= lastReferencePos) {
        input = {};
        return;
    }

    int savedRefPos = lastReferencePos;
    lastReferencePos = input.data() - source.data();

    std::string_view backref;
    if (!resolveBackref(input, backref) || backref.empty()) {
        input = {};
        return;
    }

    if (!processType(backref))
        input = {};

    lastReferencePos = savedRefPos;
    if (backref.empty())
        input = {};
}

bool dlang_demangle::Demangler::isValidIdentifierStart(std::string_view input) const {
    if (input.empty()) return false;

    if (std::isdigit(input.front()))
        return true;

    if (input.front() != 'Q')
        return false;

    std::string_view temp = input.substr(1);
    long pos;
    bool valid = extractBackrefPosition(temp, pos);
    if (!valid || pos > (input.data() - source.data()))
        return false;

    return std::isdigit(input.data()[-pos]);
}

void dlang_demangle::Demangler::processIdentifier(dlang_demangle::OutputBuffer& output, std::string_view& input) {
    if (input.empty()) {
        input = {};
        return;
    }

    if (input.front() == 'Q') {
        handleSymbolReference(output, input);
        return;
    }

    unsigned long length;
    decodeInteger(input, length);

    if (input.empty() || !length || input.length() < length) {
        input = {};
        return;
    }

    // Handle fake parent symbols (__S...)
    if (length >= 4 && starts_with(input, "__S")) {
        size_t suffixLen = input.length() - length;
        std::string_view remaining = input.substr(3);
        while (remaining.length() > suffixLen && std::isdigit(remaining.front()))
            remaining.remove_prefix(1);

        if (remaining.length() == suffixLen) {
            input.remove_prefix(length);
            processIdentifier(output, input);
            return;
        }
    }

    processLongIdentifier(output, input, length);
}

void dlang_demangle::Demangler::processLongIdentifier(dlang_demangle::OutputBuffer& output, std::string_view& input, unsigned long length) {
    // Special handling for compiler-generated symbols
    switch (length) {
        case 6:
            if (starts_with(input, "__initZ")) {
                output << "initializer for ";
                input.remove_prefix(length);
                return;
            }
            if (starts_with(input, "__vtblZ")) {
                output << "vtable for ";
                input.remove_prefix(length);
                return;
            }
            break;
        case 7:
            if (starts_with(input, "__ClassZ")) {
                output << "ClassInfo for ";
                input.remove_prefix(length);
                return;
            }
            break;
        case 11:
            if (starts_with(input, "__InterfaceZ")) {
                output << "Interface for ";
                input.remove_prefix(length);
                return;
            }
            break;
        case 12:
            if (starts_with(input, "__ModuleInfoZ")) {
                output << "ModuleInfo for ";
                input.remove_prefix(length);
                return;
            }
            break;
    }

    output << input.substr(0, length);
    input.remove_prefix(length);
}

bool dlang_demangle::Demangler::processType(std::string_view& input) {
    if (input.empty()) {
        input = {};
        return false;
    }

    switch (input.front()) {
        case 'i':
            input.remove_prefix(1);
            return true;
        case 'Q':
            handleTypeReference(input);
            return true;
        default:
            input = {};
            return false;
    }
}

void dlang_demangle::Demangler::processQualified(dlang_demangle::OutputBuffer& output, std::string_view& input) {
    bool first = true;
    while (!input.empty()) {
        if (!input.empty() && input.front() == '0') {
            while (!input.empty() && input.front() == '0')
                input.remove_prefix(1);
            continue;
        }

        if (!first)
            output << '.';
        first = false;

        processIdentifier(output, input);

        if (input.empty() || !isValidIdentifierStart(input))
            break;
    }
}

void dlang_demangle::Demangler::processMangledName(dlang_demangle::OutputBuffer& output, std::string_view& input) {
    // Skip "_D" prefix
    input.remove_prefix(2);

    processQualified(output, input);

    if (input.empty()) {
        input = {};
        return;
    }

    if (input.front() == 'Z') {
        input.remove_prefix(1);
    } else if (!processType(input)) {
        input = {};
    }
}

const char* dlang_demangle::Demangler::processMangledName(dlang_demangle::OutputBuffer& output) {
    std::string_view current(source);
    processMangledName(output, current);
    return current.data();
}

// Main demangling function
char* dlangDemangle(std::string_view mangled) {
    if (mangled.empty() || !starts_with(mangled, "_D"))
        return nullptr;

    dlang_demangle::OutputBuffer demangled;

    if (mangled == "_Dmain") {
        demangled << "D main";
    } else {
        dlang_demangle::Demangler processor(mangled);
        const char* remaining = processor.processMangledName(demangled);

        if (remaining == nullptr || *remaining != '\0') {
            return nullptr;
        }
    }

    // Add null terminator
    if (demangled.getCurrentPosition() > 0) {
        demangled << '\0';
        return demangled.getBuffer();
    }

    return nullptr;
}

