// Helper macro to create test config files
void generate_test_file(const char* path, const char* data) {
    FILE* fp = fopen(path, "w");
    if (fp) {
        fprintf(fp, "%s", data);
        fclose(fp);
    }
}

// Test framework macros (Type III: renamed and slightly restructured)
#define VERIFY_TEST(cond, msg) \
    do { \
        if (!(cond)) { \
            printf("FAIL: %s - %s\n", __FUNCTION__, msg); \
            return 0; \
        } \
    } while(0)

#define TEST_SUCCESS() \
    do { \
        printf("PASS: %s\n", __FUNCTION__); \
        return 1; \
    } while(0)

// Global state for logging tests
static int global_log_counter = 0;

// Mock logger implementation (Type III: slightly different control flow)
void mock_logger(ncclDebugLogLevel lvl, unsigned long flg,
                 const char* srcFile, int srcLine, const char* fmt, ...) {
    (void)flg;
    global_log_counter++;

    // Determine verbosity based on environment
    const char* envLevel = getenv("NCCL_DEBUG");
    bool shouldDisplay = false;

    if (envLevel != nullptr) {
        if (strcmp(envLevel, "TRACE") == 0) {
            shouldDisplay = true;
        } else if (strcmp(envLevel, "INFO") == 0 && lvl <= NCCL_LOG_INFO) {
            shouldDisplay = true;
        } else if (strcmp(envLevel, "WARN") == 0 && lvl <= NCCL_LOG_WARN) {
            shouldDisplay = true;
        }
    }

    if (!shouldDisplay) return;

    const char* lvlStr = "UNKNOWN";
    switch(lvl) {
        case NCCL_LOG_NONE: lvlStr = "NONE"; break;
        case NCCL_LOG_VERSION: lvlStr = "VERSION"; break;
        case NCCL_LOG_WARN: lvlStr = "WARN"; break;
        case NCCL_LOG_INFO: lvlStr = "INFO"; break;
        case NCCL_LOG_ABORT: lvlStr = "ABORT"; break;
        case NCCL_LOG_TRACE: lvlStr = "TRACE"; break;
    }

    printf("[TUNER:%s:%s:%d] ", lvlStr, srcFile, srcLine);
    va_list args;
    va_start(args, fmt);
    vprintf(fmt, args);
    va_end(args);
    printf("\n");
}

