// Test 4: Collective type matching
int test_collective_matching() {
    const char* matchCfg =
        "allreduce,0,65536,tree,simple,8,1,-1,-1,-1\n"
        "broadcast,0,32768,ring,ll128,4,-1,-1,-1,-1\n";
    generate_test_file("match_cfg.conf", matchCfg);
    setenv("NCCL_TUNER_CONFIG_FILE", "match_cfg.conf", 1);

    void* ctx = nullptr;
    pluginInit(&ctx, 0, 8, 1, mock_logger, nullptr, nullptr);

    float costTable[NCCL_NUM_ALGORITHMS][NCCL_NUM_PROTOCOLS];
    float* costPtr[NCCL_NUM_ALGORITHMS];
    for (int i = 0; i < NCCL_NUM_ALGORITHMS; i++) {
        costPtr[i] = costTable[i];
        for (int j = 0; j < NCCL_NUM_PROTOCOLS; j++) {
            costTable[i][j] = 1.0f;
        }
    }

    int nChans;
    ncclResult_t res = pluginGetCollInfo(ctx, ncclFuncAllReduce, 32768, 1,
                                         costPtr, NCCL_NUM_ALGORITHMS, NCCL_NUM_PROTOCOLS,
                                         0, &nChans);
    VERIFY_TEST(res == ncclSuccess, "GetCollInfo should work");
    mock_logger(NCCL_LOG_INFO, NCCL_ALL, __FILE__, __LINE__,
                "DEBUG: Tree/Simple cost = %.1f (expecting 0.0)",
                costTable[NCCL_ALGO_TREE][NCCL_PROTO_SIMPLE]);
    VERIFY_TEST(costTable[NCCL_ALGO_TREE][NCCL_PROTO_SIMPLE] == 0.0f, "Tree/Simple should be low cost");
    VERIFY_TEST(nChans == 8, "Should use 8 channels");

    // Reset and test broadcast
    for (int i = 0; i < NCCL_NUM_ALGORITHMS; i++)
        for (int j = 0; j < NCCL_NUM_PROTOCOLS; j++)
            costTable[i][j] = 1.0f;

    res = pluginGetCollInfo(ctx, ncclFuncBroadcast, 16384, 1,
                            costPtr, NCCL_NUM_ALGORITHMS, NCCL_NUM_PROTOCOLS,
                            0, &nChans);
    VERIFY_TEST(res == ncclSuccess, "GetCollInfo for broadcast should work");
    mock_logger(NCCL_LOG_INFO, NCCL_ALL, __FILE__, __LINE__,
                "DEBUG: Ring/LL128 cost = %.1f (expecting 0.0)",
                costTable[NCCL_ALGO_RING][NCCL_PROTO_LL128]);
    VERIFY_TEST(costTable[NCCL_ALGO_RING][NCCL_PROTO_LL128] == 0.0f, "Ring/LL128 should be low cost");
    VERIFY_TEST(nChans == 4, "Should use 4 channels");

    pluginFinalize(ctx);
    unlink("match_cfg.conf");
    unsetenv("NCCL_TUNER_CONFIG_FILE");
    TEST_SUCCESS();
}

