// Test 11: Large configuration files
int test_large_config() {
    const char* largeFile = "large_cfg.conf";
    FILE* f = fopen(largeFile, "w");
    VERIFY_TEST(f != nullptr, "Could not create large config file");
    fprintf(f, "# Large config for dynamic allocation test\n");

    const int numConfigs = 500;
    const char* colls[] = {"allreduce", "broadcast", "reduce", "allgather", "reducescatter"};
    const char* algos[] = {"tree", "ring", "collnet_direct", "nvls"};
    const char* protos[] = {"simple", "ll", "ll128"};

    for (int i = 0; i < numConfigs; i++) {
        const char* coll = colls[i % 5];
        const char* algo = algos[i % 4];
        const char* proto = protos[i % 3];
        size_t minB = (i * 1024) % 1048576;
        size_t maxB = minB + 65536;
        int chans = (i % 8) + 1;
        int nodes = (i % 4) == 0 ? -1 : (i % 4);
        int ranks = (i % 8) == 0 ? -1 : (i % 32) + 1;
        int pipeOps = (i % 3) == 0 ? -1 : (i % 4) + 1;
        int regBuff = (i % 3) == 0 ? -1 : (i % 2);
        fprintf(f, "%s,%zu,%zu,%s,%s,%d,%d,%d,%d,%d\n",
                coll, minB, maxB, algo, proto, chans, nodes, ranks, pipeOps, regBuff);
    }
    fclose(f);

    setenv("NCCL_TUNER_CONFIG_FILE", largeFile, 1);
    void* ctx = nullptr;
    ncclResult_t res = pluginInit(&ctx, 0, 16, 4, mock_logger, nullptr, nullptr);
    VERIFY_TEST(res == ncclSuccess, "Large config init should succeed");

    TunerContext* tCtx = (TunerContext*)ctx;
    VERIFY_TEST(tCtx->numConfigs == numConfigs, "Should load all configs");
    VERIFY_TEST(tCtx->maxConfigs == numConfigs, "maxConfigs should match");
    VERIFY_TEST(tCtx->configs != nullptr, "Configs array should exist");

    // Verify access throughout array
    for (int i = 0; i < tCtx->numConfigs; i++) {
        TuningConfig* cfg = &tCtx->configs[i];
        VERIFY_TEST(cfg->collType >= ncclFuncBroadcast && cfg->collType <= ncclFuncAllReduce, "Invalid collective type");
        VERIFY_TEST(cfg->maxBytes >= cfg->minBytes, "maxBytes should be >= minBytes");
        VERIFY_TEST(cfg->nChannels > 0, "nChannels should be positive");
    }

    // Access specific indices
    TuningConfig* first = &tCtx->configs[0];
    TuningConfig* mid = &tCtx->configs[numConfigs / 2];
    TuningConfig* last = &tCtx->configs[numConfigs - 1];
