class Solution {
public:
    int reverseBits(int n) {
        int result = 0;
        int position = 0;
        while (position < 32) {
            // Extract the least significant bit of n and shift it to the correct position in result
            int bit = n & 1;
            result = (result << 1) | bit;
            // Move to the next bit in n
            n >>= 1;
            position++;
        }
        return result;
    }
};

#include <iostream>
#include <vector>
#include <algorithm>
#include <random>
#include <bitset>
using namespace std;

struct Edge {
    int u, v;
    int id;
};

int N, M;
vector<Edge> edges;
vector<vector<pair<int, int>>> adj; // u -> {v, edge_index}

// Global bitsets for solver
bitset<10000> current_mask;
bitset<10000> possible_v;
bitset<10000> all_ones;

struct QueryData {
    vector<int> in_time;
    vector<int> out_time;
    vector<int> dfs_order; // map dfs_index -> original_node
    int answer;
};

vector<QueryData> queries;

void perform_random_dfs(int root, vector<int>& parent, vector<int>& order,
                        vector<int>& in, vector<int>& out, mt19937& rng) {
    vector<int> stack;
    stack.push_back(root);

    vector<bool> visited(N, false);
    visited[root] = true;

    int timer = 0;

    struct StackFrame {
        int node;
        int next_edge;
    };
    vector<StackFrame> call_stack;

    // Pre-shuffle adjacency lists
    vector<vector<int>> shuffled_adj(N);
    for (int u = 0; u < N; ++u) {
        for (auto& p : adj[u]) {
            shuffled_adj[u].push_back(p.first);
        }
        shuffle(shuffled_adj[u].begin(), shuffled_adj[u].end(), rng);
    }

    call_stack.push_back({root, 0});
    in[root] = timer++;
    order[in[root]] = root;

    while (!call_stack.empty()) {
        StackFrame& frame = call_stack.back();
        int u = frame.node;

        if (frame.next_edge < shuffled_adj[u].size()) {
            int v = shuffled_adj[u][frame.next_edge];
            frame.next_edge++;
            if (!visited[v]) {
                visited[v] = true;
                in[v] = timer++;
                order[in[v]] = v;
                call_stack.push_back({v, 0});
            }
        } else {
            out[u] = timer - 1;
            call_stack.pop_back();
        }
    }
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    if (!(cin >> N >> M)) return 0;

    adj.resize(N);
    for (int i = 0; i < M; ++i) {
        int u, v;
        cin >> u >> v;
        edges.push_back({u, v, i});
        adj[u].emplace_back(v, i);
        adj[v].emplace_back(u, i);
    }

    mt19937 rng(1337);

    // Initialize bitset
    for (int i = 0; i < N; ++i) {
        all_ones[i] = 1;
    }

    const int num_queries = 250;
    vector<int> edge_directions(M); // 0: u->v, 1: v->u
    vector<int> in(N), out(N), order(N);

    for (int q = 0; q < num_queries; ++q) {
        int root = uniform_int_distribution<int>(0, N - 1)(rng);

        fill(in.begin(), in.end(), 0);
        fill(out.begin(), out.end(), 0);
        fill(order.begin(), order.end(), 0);

        perform_random_dfs(root, vector<int>(), order, in, out, rng);

        // Determine edge directions based on DFS discovery times
        for (const auto& e : edges) {
            if (in[e.u] < in[e.v]) {
                edge_directions[e.id] = 0; // u -> v
            } else {
                edge_directions[e.id] = 1; // v -> u
            }
        }

        cout << "0 ";
        for (int i = 0; i < M; ++i) {
            cout << edge_directions[i];
            if (i != M - 1) cout << " ";
        }
        cout << "\n";

        int res;
        cin >> res;
        if (res == -1) return 0;

        QueryData qd;
        qd.in_time = in;
        qd.out_time = out;
        qd.dfs_order = order;
        qd.answer = res;
        queries.push_back(qd);
    }

    // Find A and B
    int candidate_A = -1, candidate_B = -1;

    for (int u = 0; u < N; ++u) {
        possible_v = all_ones;
        possible_v[u] = 0; // Ensure A != B

        bool valid_candidate = true;

        for (const auto& qd : queries) {
            int u_in = qd.in_time[u];
            int u_out = qd.out_time[u];
            bool must_be_in_subtree = (qd.answer == 1);

            // Iterate through remaining candidates
            for (int v = possible_v._Find_first(); 
                 v < N && possible_v.any(); 
                 v = possible_v._Find_next(v)) {

                int v_in = qd.in_time[v];
                bool is_in_subtree = (v_in >= u_in && v_in <= u_out);

                if (must_be_in_subtree != is_in_subtree) {
                    possible_v[v] = 0;
                }
            }

            if (possible_v.none()) {
                valid_candidate = false;
                break;
            }
        }

        if (valid_candidate) {
            candidate_A = u;
            candidate_B = possible_v._Find_first();
            break;
        }
    }

    cout << "1 " << candidate_A << " " << candidate_B << "\n";

    return 0;
}

