// Wrapper to retrieve string with custom overrides applied
const char* __fastcall GetString(int table_id, int /*unused*/, int entry_id, bool* out_valid) {
    GameStr* instance = ZealService::get_instance()->gamestr_hook.get();

    // Check if user-defined replacement exists for this ID
    auto it = instance->custom_strings.find(entry_id);
    if (it != instance->custom_strings.end()) {
        if (out_valid) *out_valid = true;
        return it->second.c_str();
    }

    // If marked as non-printable, return empty string
    auto noprint_it = instance->suppress_strings.find(entry_id);
    if (noprint_it != instance->suppress_strings.end() && noprint_it->second) {
        return "";
    }

    // Fall back to original implementation
    using OriginalFunc = const char*(__fastcall*)(int, int, int, bool*);
    OriginalFunc orig_func = reinterpret_cast<OriginalFunc>(
        ZealService::get_instance()->hooks->hook_map["GetString"]->original(GetString)
    );

    return orig_func(table_id, 0, entry_id, out_valid);
}

