    int stride_x = 1;
    int stride_y = 1;
    int length = 1;

    double result_optimized = 0.0;
    double result_reference = 0.0;

    result_optimized = BLASFUNC(dsdot)(&length, &x_val, &stride_x, &y_val, &stride_y);
    result_reference = BLASFUNC_REF(dsdot)(&length, &x_val, &stride_x, &y_val, &stride_y);

    CU_ASSERT_DOUBLE_EQUAL(result_optimized, result_reference, CHECK_EPS);
}

