#include <iostream>
#include <sstream>

// Reimplementation of strand-like behavior using a custom mutex-based dispatcher
// This simulates the core logic of asio::strand without relying on Boost.Asio

class custom_dispatcher {
private:
    bool locked = false;
    std::mutex mtx;

public:
    bool running_in_this_thread() const {
        // Simplified: assume main thread context for demonstration
        return true;
    }

    template<typename Func>
    void execute(Func&& func) {
        std::lock_guard<std::mutex> lock(mtx);
        func();
    }

    template<typename Func>
    void dispatch(Func&& func) {
        if (locked) {
            // Already in locked context - execute directly
            func();
        } else {
            // Not locked - acquire lock and execute
            execute(std::forward<Func>(func));
        }
    }

    void set_locked(bool state) {
        locked = state;
    }
};

void increment(int* count) {
    ++(*count);
}

void increment_without_lock(custom_dispatcher* d, int* count) {
    int original_count = *count;
    d->dispatch([count]() { increment(count); });
    // Since no other functions are executing through the dispatcher,
    // the previous dispatch should have successfully nested.
    // In our implementation, this will always be true due to mutex protection.
    if (*count != original_count + 1) {
        std::cerr << "Error: Expected count to be " << original_count + 1 
                  << " but got " << *count << std::endl;
    }
}

void increment_with_lock(custom_dispatcher* d, int* count) {
    d->set_locked(true);
    int original_count = *count;
    d->dispatch([count]() { increment(count); });
    // The current function already holds the dispatcher's lock,
    // so the previous call to dispatch should have successfully nested.
    if (*count != original_count + 1) {
        std::cerr << "Error: Expected count to be " << original_count + 1 
                  << " but got " << *count << std::endl;
    }
    d->set_locked(false);
}

void sleep_increment(custom_dispatcher* d, int* count) {
    // Simulate delay with a simple loop (not precise timing)
    for (volatile int i = 0; i < 100000000; ++i);
    increment(count);
}

void start_sleep_increments(custom_dispatcher* d, int* count) {
    // Give threads time to start
    for (volatile int i = 0; i < 100000000; ++i);

    // Start three increments
    d->dispatch([d, count]() { sleep_increment(d, count); });
    d->dispatch([d, count]() { sleep_increment(d, count); });
    d->dispatch([d, count]() { sleep_increment(d, count); });
}

void throw_exception() {
    throw 1;
}

void increment_by_a(int* count, int a) {
    (*count) += a;
}

void increment_by_a_b(int* count, int a, int b) {
    (*count) += a + b;
}

void increment_by_a_b_c(int* count, int a, int b, int c) {
    (*count) += a + b + c;
}

void increment_by_a_b_c_d(int* count, int a, int b, int c, int d) {
    (*count) += a + b + c + d;
}

void run_test(custom_dispatcher& d, int& count) {
    count = 0;
    d.dispatch([&d, &count]() { increment_without_lock(&d, &count); });
    // No handlers can be called until we explicitly run them
    // In our simplified model, dispatch executes immediately
    if (count != 1) {
        std::cerr << "Error: Expected count to be 1 but got " << count << std::endl;
    }
}

void run_test_with_lock(custom_dispatcher& d, int& count) {
    count = 0;
    d.dispatch([&d, &count]() { increment_with_lock(&d, &count); });
    if (count != 1) {
        std::cerr << "Error: Expected count to be 1 but got " << count << std::endl;
    }
}

void run_concurrent_test(custom_dispatcher& d, int& count) {
    count = 0;

    // Simulate concurrent execution with multiple threads
    // We'll simulate this by manually calling the functions

    // First batch
    d.dispatch([&d, &count]() { start_sleep_increments(&d, &count); });

    // Wait for first batch to complete
    for (volatile int i = 0; i < 200000000; ++i);

    if (count != 3) {
        std::cerr << "Error: Expected count to be 3 but got " << count << std::endl;
    }
}

void run_exception_test(custom_dispatcher& d, int& count) {
    count = 0;
    int exception_count = 0;

    try {
        d.dispatch([]() { throw_exception(); });
    } catch (...) {
        ++exception_count;
    }

    d.dispatch([&count]() { increment(&count); });
    d.dispatch([&count]() { increment(&count); });

    try {
        d.dispatch([]() { throw_exception(); });
    } catch (...) {
        ++exception_count;
    }

    d.dispatch([&count]() { increment(&count); });

    if (count != 3 || exception_count != 2) {
        std::cerr << "Error: Expected count=3, exceptions=2 but got count=" 
                  << count << ", exceptions=" << exception_count << std::endl;
    }
}

void wrap_function_test(custom_dispatcher& d, int& count) {
    count = 0;

    // Simulate wrapping functions
    auto wrapped1 = [&d, &count]() { increment(&count); };
    wrapped1();

    if (count != 1) {
        std::cerr << "Error: Expected count to be 1 but got " << count << std::endl;
    }

    count = 0;
    auto wrapped2 = [&d, &count]() { increment_by_a(&count, 1); };
    wrapped2();
    if (count != 1) {
        std::cerr << "Error: Expected count to be 1 but got " << count << std::endl;
    }

    count = 0;
    auto wrapped3 = [&d, &count]() { increment_by_a_b(&count, 1, 2); };
    wrapped3();
    if (count != 3) {
        std::cerr << "Error: Expected count to be 3 but got " << count << std::endl;
    }

    count = 0;
    auto wrapped4 = [&d, &count]() { increment_by_a_b_c(&count, 1, 2, 3); };
    wrapped4();
    if (count != 6) {
        std::cerr << "Error: Expected count to be 6 but got " << count << std::endl;
    }

    count = 0;
    auto wrapped5 = [&d, &count]() { increment_by_a_b_c_d(&count, 1, 2, 3, 4); };
    wrapped5();
    if (count != 10) {
        std::cerr << "Error: Expected count to be 10 but got " << count << std::endl;
    }
}

int main() {
    // Test basic strand functionality
    custom_dispatcher dispatcher;
    int count = 0;

    run_test(dispatcher, count);

    count = 0;
    run_test_with_lock(dispatcher, count);

    count = 0;
    run_concurrent_test(dispatcher, count);

    count = 0;
    run_exception_test(dispatcher, count);

    count = 0;
    wrap_function_test(dispatcher, count);

    std::cout << "All tests passed!" << std::endl;
    return 0;
}

