#include "llvm/Transforms/Utils/IntegerDivision.h"
#include "llvm/IR/Function.h"
#include "llvm/IR/IRBuilder.h"
#include "llvm/IR/Instructions.h"
#include "llvm/IR/Intrinsics.h"
#include "llvm/IR/Constants.h"
using namespace llvm;

#define DEBUG_TYPE "integer-division"

// Helper function to create a constant of specified bit width
static ConstantInt* makeConstantInt(Type* Ty, int64_t Value) {
  return ConstantInt::get(Ty, Value);
}

// Generate code for signed remainder using absolute value transformation
static Value *generateSignedRemainderCode(Value *Dividend, Value *Divisor,
                                          IRBuilder<> &Builder) {
  Type *Ty = Dividend->getType();
  unsigned BitWidth = Ty->getIntegerBitWidth();
  ConstantInt *ShiftAmount = makeConstantInt(Ty, BitWidth - 1);

  // Apply sign handling similar to compiler-rt implementation
  Dividend = Builder.CreateFreeze(Dividend);
  Divisor  = Builder.CreateFreeze(Divisor);

  Value *DivSign = Builder.CreateAShr(Dividend, ShiftAmount);
  Value *DivrSign = Builder.CreateAShr(Divisor, ShiftAmount);

  // Convert to unsigned values by XORing with sign and subtracting sign
  Value *XorDiv = Builder.CreateXor(Dividend, DivSign);
  Value *XorDivr = Builder.CreateXor(Divisor, DivrSign);
  Value *UDividend = Builder.CreateSub(XorDiv, DivSign);
  Value *UDivisor = Builder.CreateSub(XorDivr, DivrSign);

  // Compute unsigned remainder
  Value *URemainder = Builder.CreateURem(UDividend, UDivisor);

  // Restore sign: (urem ^ dividend_sign) - dividend_sign
  Value *XoredResult = Builder.CreateXor(URemainder, DivSign);
  Value *SRem = Builder.CreateSub(XoredResult, DivSign);

  if (Instruction *URemInst = dyn_cast<Instruction>(URemainder))
    Builder.SetInsertPoint(URemInst);

  return SRem;
}

// Generate code for unsigned remainder using standard algorithm
static Value *generatedUnsignedRemainderCode(Value *Dividend, Value *Divisor,
                                             IRBuilder<> &Builder) {
  Dividend = Builder.CreateFreeze(Dividend);
  Divisor  = Builder.CreateFreeze(Divisor);

  // Remainder = Dividend - Quotient * Divisor
  Value *Quotient = Builder.CreateUDiv(Dividend, Divisor);
  Value *Product = Builder.CreateMul(Divisor, Quotient);
  Value *Remainder = Builder.CreateSub(Dividend, Product);

  if (Instruction *UDivInst = dyn_cast<Instruction>(Quotient))
    Builder.SetInsertPoint(UDivInst);

  return Remainder;
}

// Generate code for signed division using absolute value method
static Value *generateSignedDivisionCode(Value *Dividend, Value *Divisor,
                                         IRBuilder<> &Builder) {
  Type *Ty = Dividend->getType();
  unsigned BitWidth = Ty->getIntegerBitWidth();
  ConstantInt *ShiftAmount = makeConstantInt(Ty, BitWidth - 1);

  Dividend = Builder.CreateFreeze(Dividend);
  Divisor  = Builder.CreateFreeze(Divisor);

  Value *DivSign = Builder.CreateAShr(Dividend, ShiftAmount);
  Value *DivrSign = Builder.CreateAShr(Divisor, ShiftAmount);

  // Convert to positive values
  Value *XorDiv = Builder.CreateXor(Dividend, DivSign);
  Value *XorDivr = Builder.CreateXor(Divisor, DivrSign);
  Value *U_Dividend = Builder.CreateSub(XorDiv, DivSign);
  Value *U_Divisor = Builder.CreateSub(XorDivr, DivrSign);

  // Calculate quotient magnitude
  Value *Q_Magnitude = Builder.CreateUDiv(U_Dividend, U_Divisor);

  // Determine sign of result
  Value *Q_Sign = Builder.CreateXor(DivSign, DivrSign);

  // Apply sign to quotient: (q_mag ^ q_sign) - q_sign
  Value *XoredQ = Builder.CreateXor(Q_Magnitude, Q_Sign);
  Value *Quotient = Builder.CreateSub(XoredQ, Q_Sign);

  if (Instruction *UDivInst = dyn_cast<Instruction>(Q_Magnitude))
    Builder.SetInsertPoint(UDivInst);

  return Quotient;
}

// Generate code for unsigned division using LLVM's ctlz intrinsic
static Value *generateUnsignedDivisionCode(Value *Dividend, Value *Divisor,
                                           IRBuilder<> &Builder) {
  Type *Ty = Dividend->getType();
  IntegerType *IntTy = cast<IntegerType>(Ty);
  unsigned BitWidth = IntTy->getBitWidth();

  ConstantInt *Zero = makeConstantInt(Ty, 0);
  ConstantInt *One = makeConstantInt(Ty, 1);
  ConstantInt *NegOne = ConstantInt::getSigned(Ty, -1);
  ConstantInt *MSB = makeConstantInt(Ty, BitWidth - 1);
  ConstantInt *TrueVal = Builder.getTrue();

  BasicBlock *OrigBB = Builder.GetInsertBlock();
  Function *F = OrigBB->getParent();

  // Declare ctlz intrinsic
  Function *CTLZ = Intrinsic::getDeclaration(F->getParent(), Intrinsic::ctlz, Ty);

  // Split basic blocks for control flow
  BasicBlock *SpecialCases = OrigBB;
  SpecialCases->setName(SpecialCases->getName().str("_udiv-special-cases"));

  BasicBlock *EndBB = SpecialCases->splitBasicBlock(Builder.GetInsertPoint(),
                                                    "udiv-end");
  BasicBlock *LoopExit = BasicBlock::Create(Builder.getContext(),
                                            "udiv-loop-exit", F, EndBB);
  BasicBlock *DoWhileLoop = BasicBlock::Create(Builder.getContext(),
                                               "udiv-do-while", F, EndBB);
  BasicBlock *PreHeader = BasicBlock::Create(Builder.getContext(),
                                             "udiv-preheader", F, EndBB);
  BasicBlock *BB1 = BasicBlock::Create(Builder.getContext(),
                                       "udiv-bb1", F, EndBB);

  // Remove original terminator
  SpecialCases->getTerminator()->eraseFromParent();

  // Handle special cases
  Builder.SetInsertPoint(SpecialCases);
  Dividend = Builder.CreateFreeze(Dividend);
  Divisor = Builder.CreateFreeze(Divisor);

  Value *IsDivZero = Builder.CreateICmpEQ(Divisor, Zero);
  Value *IsDivZero2 = Builder.CreateICmpEQ(Dividend, Zero);
  Value *EitherZero = Builder.CreateOr(IsDivZero, IsDivZero2);

  Value *CtlzDivisor = Builder.CreateCall(CTLZ, {Divisor, TrueVal});
  Value *CtlzDividend = Builder.CreateCall(CTLZ, {Dividend, TrueVal});
  Value *ShiftDiff = Builder.CreateSub(CtlzDivisor, CtlzDividend);

  Value *IsShiftLarge = Builder.CreateICmpUGT(ShiftDiff, MSB);
  Value *ShouldReturnZero = Builder.CreateLogicalOr(EitherZero, IsShiftLarge);
  Value *ShouldReturnDividend = Builder.CreateICmpEQ(ShiftDiff, MSB);
  Value *RetVal = Builder.CreateSelect(ShouldReturnZero, Zero, Dividend);
  Value *EarlyRet = Builder.CreateLogicalOr(ShouldReturnZero, ShouldReturnDividend);

  Builder.CreateCondBr(EarlyRet, EndBB, BB1);

  // BB1: Setup for loop
  Builder.SetInsertPoint(BB1);
  Value *SRPlus1 = Builder.CreateAdd(ShiftDiff, One);
  Value *TmpVal = Builder.CreateSub(MSB, ShiftDiff);
  Value *InitQ = Builder.CreateShl(Dividend, TmpVal);
  Value *SkipLoop = Builder.CreateICmpEQ(SRPlus1, Zero);
  Builder.CreateCondBr(SkipLoop, LoopExit, PreHeader);

  // Preheader: Initialize loop variables
  Builder.SetInsertPoint(PreHeader);
  Value *InitR = Builder.CreateLShr(Dividend, SRPlus1);
  Value *DivisorMinusOne = Builder.CreateAdd(Divisor, NegOne);
  Builder.CreateBr(DoWhileLoop);

  // Do-while loop
  Builder.SetInsertPoint(DoWhileLoop);
  PHINode *CarryPhi = Builder.CreatePHI(Ty, 2);
  PHINode *SRPhi = Builder.CreatePHI(Ty, 2);
  PHINode *RPhi = Builder.CreatePHI(Ty, 2);
  PHINode *QPhi = Builder.CreatePHI(Ty, 2);

  Value *ShiftedR = Builder.CreateShl(RPhi, One);
  Value *HighBitQ = Builder.CreateLShr(QPhi, MSB);
  Value *Combined = Builder.CreateOr(ShiftedR, HighBitQ);
  Value *ShiftedQ = Builder.CreateShl(QPhi, One);
  Value *NewQ = Builder.CreateOr(CarryPhi, ShiftedQ);
  Value *Subtracted = Builder.CreateSub(DivisorMinusOne, Combined);
  Value *SignExt = Builder.CreateAShr(Subtracted, MSB);
  Value *NewCarry = Builder.CreateAnd(SignExt, One);
  Value *AdjustedDivisor = Builder.CreateAnd(SignExt, Divisor);
  Value *NewR = Builder.CreateSub(Combined, AdjustedDivisor);
  Value *NewSR = Builder.CreateAdd(SRPhi, NegOne);
  Value *LoopContinue = Builder.CreateICmpNE(NewSR, Zero);

  Builder.CreateCondBr(LoopContinue, DoWhileLoop, LoopExit);

  // Loop exit block
  Builder.SetInsertPoint(LoopExit);
  PHINode *FinalCarry = Builder.CreatePHI(Ty, 2);
  PHINode *FinalQ = Builder.CreatePHI(Ty, 2);

  Value *ShiftedFinalQ = Builder.CreateShl(FinalQ, One);
  Value *FinalResult = Builder.CreateOr(FinalCarry, ShiftedFinalQ);
  Builder.CreateBr(EndBB);

  // End block with phi node
  Builder.SetInsertPoint(EndBB, EndBB->begin());
  PHINode *ResultPhi = Builder.CreatePHI(Ty, 2);

  // Populate PHI nodes
  CarryPhi->addIncoming(Zero, PreHeader);
  CarryPhi->addIncoming(NewCarry, DoWhileLoop);

  SRPhi->addIncoming(SRPlus1, PreHeader);
  SRPhi->addIncoming(NewSR, DoWhileLoop);

  RPhi->addIncoming(InitR, PreHeader);
  RPhi->addIncoming(NewR, DoWhileLoop);

  QPhi->addIncoming(InitQ, PreHeader);
  QPhi->addIncoming(NewQ, DoWhileLoop);

  FinalCarry->addIncoming(Zero, BB1);
  FinalCarry->addIncoming(NewCarry, DoWhileLoop);

  FinalQ->addIncoming(InitQ, BB1);
  FinalQ->addIncoming(NewQ, DoWhileLoop);

  ResultPhi->addIncoming(FinalResult, LoopExit);
  ResultPhi->addIncoming(RetVal, SpecialCases);

  return ResultPhi;
}

// Expand remainder operation
bool llvm::expandRemainder(BinaryOperator *Rem) {
  assert((Rem->getOpcode() == Instruction::SRem ||
          Rem->getOpcode() == Instruction::URem) &&
         "Trying to expand remainder from a non-remainder function");

  IRBuilder<> Builder(Rem);
  assert(!Rem->getType()->isVectorTy() && "Div over vectors not supported");

  if (Rem->getOpcode() == Instruction::SRem) {
    Value *Remainder = generateSignedRemainderCode(Rem->getOperand(0),
                                                   Rem->getOperand(1), Builder);
    bool IsInsertPoint = Rem->getIterator() == Builder.GetInsertPoint();
    Rem->replaceAllUsesWith(Remainder);
    Rem->dropAllReferences();
    Rem->eraseFromParent();

    if (IsInsertPoint)
      return true;

    BinaryOperator *BO = dyn_cast<BinaryOperator>(Builder.GetInsertPoint());
    Rem = BO;
  }

  Value *Remainder = generatedUnsignedRemainderCode(Rem->getOperand(0),
                                                    Rem->getOperand(1),
                                                    Builder);
  Rem->replaceAllUsesWith(Remainder);
  Rem->dropAllReferences();
  Rem->eraseFromParent();

  if (BinaryOperator *UDiv = dyn_cast<BinaryOperator>(Builder.GetInsertPoint())) {
    assert(UDiv->getOpcode() == Instruction::UDiv && "Non-udiv in expansion?");
    expandDivision(UDiv);
  }

  return true;
}

// Expand division operation
bool llvm::expandDivision(BinaryOperator *Div) {
  assert((Div->getOpcode() == Instruction::SDiv ||
          Div->getOpcode() == Instruction::UDiv) &&
         "Trying to expand division from a non-division function");

  IRBuilder<> Builder(Div);
  assert(!Div->getType()->isVectorTy() && "Div over vectors not supported");

  if (Div->getOpcode() == Instruction::SDiv) {
    Value *Quotient = generateSignedDivisionCode(Div->getOperand(0),
                                                 Div->getOperand(1), Builder);
    bool IsInsertPoint = Div->getIterator() == Builder.GetInsertPoint();
    Div->replaceAllUsesWith(Quotient);
    Div->dropAllReferences();
    Div->eraseFromParent();

    if (IsInsertPoint)
      return true;

    BinaryOperator *BO = dyn_cast<BinaryOperator>(Builder.GetInsertPoint());
    Div = BO;
  }

  Value *Quotient = generateUnsignedDivisionCode(Div->getOperand(0),
                                                 Div->getOperand(1),
                                                 Builder);
  Div->replaceAllUsesWith(Quotient);
  Div->dropAllReferences();
  Div->eraseFromParent();

  return true;
}

// Expand remainder for types up to 32 bits
bool llvm::expandRemainderUpTo32Bits(BinaryOperator *Rem) {
  assert((Rem->getOpcode() == Instruction::SRem ||
          Rem->getOpcode() == Instruction::URem) &&
         "Trying to expand remainder from a non-remainder function");

  Type *RemTy = Rem->getType();
  assert(!RemTy->isVectorTy() && "Div over vectors not supported");

  unsigned RemTyBitWidth = RemTy->getIntegerBitWidth();
  if (RemTyBitWidth > 32)
    return false;

  if (RemTyBitWidth == 32)
    return expandRemainder(Rem);

  IRBuilder<> Builder(Rem);
  Type *Int32Ty = Builder.getInt32Ty();

  Value *ExtDividend, *ExtDivisor, *ExtRem, *Trunc;

  if (Rem->getOpcode() == Instruction::SRem) {
    ExtDividend = Builder.CreateSExt(Rem->getOperand(0), Int32Ty);
    ExtDivisor = Builder.CreateSExt(Rem->getOperand(1), Int32Ty);
    ExtRem = Builder.CreateSRem(ExtDividend, ExtDivisor);
  } else {
    ExtDividend = Builder.CreateZExt(Rem->getOperand(0), Int32Ty);
    ExtDivisor = Builder.CreateZExt(Rem->getOperand(1), Int32Ty);
    ExtRem = Builder.CreateURem(ExtDividend, ExtDivisor);
  }

  Trunc = Builder.CreateTrunc(ExtRem, RemTy);
  Rem->replaceAllUsesWith(Trunc);
  Rem->dropAllReferences();
  Rem->eraseFromParent();

  return expandRemainder(cast<BinaryOperator>(ExtRem));
}

