#include "proj_internal.h"
#include <cmath>

// Maximum order for series expansion (same as original Lmax = 6)
constexpr int SeriesOrder = 6;

// Evaluate polynomial using Horner’s method: p[0] + p[1]*x + ... + p[N]*x^N
static double evaluate_polynomial(double x, const double coefficients[], int degree) {
    double result = 0.0;
    if (degree >= 0) {
        result = coefficients[degree];
        for (int i = degree; i > 0; --i) {
            result = result * x + coefficients[i - 1];
        }
    }
    return result;
}

// Clenshaw summation for Fourier-type series: sum_{k=0}^{K-1} c[k] * sin((2k+2)*zeta)
static double fourier_clenshaw(double s_zeta, double c_zeta, const double coeffs[], int terms) {
    // Recurrence: u_{k} = X * u_{k+1} - u_{k+2} + c_k, starting from u_{terms}=u_{terms+1}=0
    double u_next = 0.0;   // corresponds to u_{k+1}
    double u_next2 = 0.0;  // corresponds to u_{k+2}
    double cos_2zeta = 2.0 * (c_zeta * c_zeta - s_zeta * s_zeta); // cos(2*zeta)

    for (int k = terms - 1; k >= 0; --k) {
        double temp = cos_2zeta * u_next - u_next2 + coeffs[k];
        u_next2 = u_next;
        u_next = temp;
    }

    return s_zeta * c_zeta * u_next; // sin(zeta)*cos(zeta)*u_0 = (1/2)sin(2zeta)*u_0, but original uses 2*sin*cos*u0
}

// Precompute expansion coefficients for meridional distance and its inverse
double* pj_enfn(double n) {
    // Coefficients for radial scaling factor: ((2k-3)!!/(2k)!!)^2 for k=0..2 (Lmax/2 = 3 terms)
    static const double rad_coeffs[] = {1.0, 0.25, 1.0/64.0, 1.0/256.0};

    // Coefficient arrays for phi <-> mu conversion (see arXiv:2212.05818, Appendix A)
    static const double mu_from_phi[] = {
        -1.5,          0.5625,       -0.09375,      0.9375,
        -0.46875,      0.06591796875,-0.7291666667, 0.41015625,
        0.615234375,   -0.369140625, -0.5409375,    0.48828125
    };

    static const double phi_from_mu[] = {
        1.5,          -0.84375,       0.525390625,    1.3125,
        -1.71875,      1.64990234375, 1.5729166667,   -3.2578125,
        2.142578125,  -6.07109375,     3.129296875,    4.77509765625
    };

    double n_squared = n * n;
    double factor = n;
    double* expanded = new double[2 * SeriesOrder + 1];

    if (!expanded)
        return nullptr;

    // First coefficient: overall scale factor
    expanded[0] = evaluate_polynomial(n_squared, rad_coeffs, SeriesOrder / 2) / (1.0 + n);

    // Fill remaining coefficients for forward and inverse conversions
    int offset = 0;
    for (int idx = 0; idx < SeriesOrder; ++idx) {
        int poly_degree = (SeriesOrder - idx - 1) / 2;

        expanded[idx + 1] = factor * evaluate_polynomial(n_squared, mu_from_phi + offset, poly_degree);
        expanded[idx + 1 + SeriesOrder] = factor * evaluate_polynomial(n_squared, phi_from_mu + offset, poly_degree);

        factor *= n;
        offset += poly_degree + 1;
    }

    return expanded;
}

// Meridional distance function: M(phi) = en[0] * (phi + clenshaw(...))
double pj_mlfn(double phi, double sin_phi, double cos_phi, const double* coeffs) {
    double correction = fourier_clenshaw(sin_phi, cos_phi, coeffs + 1, SeriesOrder);
    return coeffs[0] * (phi + correction);
}

// Inverse meridional distance: phi(M) = en[0]^{-1} * M + clenshaw(...)
double pj_inv_mlfn(double mu, const double* coeffs) {
    double normalized_mu = mu / coeffs[0];
    double sin_mu = std::sin(normalized_mu);
    double cos_mu = std::cos(normalized_mu);
    double correction = fourier_clenshaw(sin_mu, cos_mu, coeffs + 1 + SeriesOrder, SeriesOrder);
    return normalized_mu + correction;
}

