// to maintain functionality without external dependencies

struct Vector3 {
    float x, y, z;
    Vector3(float x = 0, float y = 0, float z = 0) : x(x), y(y), z(z) {}
};

struct Particle {
    Vector3 position;
    Vector3 velocity;
    Vector3 color;
    float life;
    bool active;

    Particle() : position(), velocity(), color(), life(0.0f), active(false) {}
};

class ParticleSystem {
private:
    static const int MAX_PARTICLES = 3000;
    Particle particles[MAX_PARTICLES];
    float min_age;
    float birth_interval;
    float life_span;

public:
    ParticleSystem() : min_age(0.0f), birth_interval(0.002667f), life_span(8.0f) {}

    void initializeParticle(int index, double time) {
        if (index < 0 || index >= MAX_PARTICLES) return;

        Particle& p = particles[index];
        p.position = Vector3(0.0f, 0.0f, 3.0f); // Fountain height

        float angle = (2.0f * 3.14159f / 4096.0f) * (rand() & 4095);
        float speed = 8.0f * (0.8f + 0.1f * (std::sin(0.5f * time) + std::sin(1.31f * time)));

        p.velocity = Vector3(
            0.4f * std::cos(angle) * speed,
            0.4f * std::sin(angle) * speed,
            (0.7f + 0.3f / 4096.0f * (rand() & 4095)) * speed
        );

        p.color = Vector3(
            0.7f + 0.3f * std::sin(0.34f * time + 0.1f),
            0.6f + 0.4f * std::sin(0.63f * time + 1.1f),
            0.6f + 0.4f * std::sin(0.91f * time + 2.1f)
        );

        p.life = 1.0f;
        p.active = true;
    }

    void updateParticle(int index, float dt) {
        if (index < 0 || index >= MAX_PARTICLES || !particles[index].active) return;

        Particle& p = particles[index];
        p.life -= dt / life_span;

        if (p.life <= 0.0f) {
            p.active = false;
            return;
        }

        // Apply gravity
        p.velocity.z -= 9.8f * dt;

        // Update position
        p.position.x += p.velocity.x * dt;
        p.position.y += p.velocity.y * dt;
        p.position.z += p.velocity.z * dt;

        // Simple collision detection
        if (p.velocity.z < 0.0f) {
            float dist_sq = p.position.x * p.position.x + p.position.y * p.position.y;
            if (dist_sq < (1.6f + 0.35f) * (1.6f + 0.35f) && p.position.z < 3.35f) {
                p.velocity.z = -0.75f * p.velocity.z;
                p.position.z = 3.35f + 0.75f * (3.35f - p.position.z);
            } else if (p.position.z < 0.35f) {
                p.velocity.z = -0.75f * p.velocity.z;
                p.position.z = 0.35f + 0.75f * (0.35f - p.position.z);
            }
        }
    }

    void processParticles(double time, float delta_time) {
        float remaining_time = delta_time;
        const float min_step = birth_interval * 0.5f;

        while (remaining_time > 0.0f) {
            float step = std::min(remaining_time, min_step);

            for (int i = 0; i < MAX_PARTICLES; ++i) {
                updateParticle(i, step);
            }

            min_age += step;
            remaining_time -= step;

            while (min_age >= birth_interval) {
                min_age -= birth_interval;

                for (int i = 0; i < MAX_PARTICLES; ++i) {
                    if (!particles[i].active) {
                        initializeParticle(i, time + min_age);
                        updateParticle(i, min_age);
                        break;
                    }
                }
            }
        }
    }

    Particle* getParticles() { return particles; }
    int getMaxParticles() const { return MAX_PARTICLES; }
};

