// Thread simulation using simple mutex-like structure
class ThreadManager {
private:
    std::mutex mtx;
    bool physics_done = false;
    bool draw_done = true;
    int physics_frame = 0;
    int draw_frame = 0;

public:
    void lock() { mtx.lock(); }
    void unlock() { mtx.unlock(); }

    void signalPhysicsDone() { 
        physics_done = true; 
        draw_done = false;
    }

    void signalDrawDone() { 
        draw_done = true; 
        physics_done = false;
    }

    bool isPhysicsReady() const { return physics_done; }
    bool isDrawReady() const { return draw_done; }

    void incrementPhysicsFrame() { ++physics_frame; }
    void incrementDrawFrame() { ++draw_frame; }

    int getPhysicsFrame() const { return physics_frame; }
    int getDrawFrame() const { return draw_frame; }
};

// Main program function
int main() {
    // Initialize random seed
    srand(static_cast<unsigned>(time(nullptr)));

    // Create particle system
    ParticleSystem particle_system;

    // Create thread manager
    ThreadManager thread_manager;

    // Simulate frame loop
    double current_time = 0.0;
    float delta_time = 0.016f; // ~60 FPS

    // Print initial message
    std::cout << "Particle Engine Simulation Started" << std::endl;
    std::cout << "Controls: W to toggle wireframe, Esc to exit" << std::endl;

    // Run for a few iterations to demonstrate functionality
    for (int frame = 0; frame < 100; ++frame) {
        // Simulate physics thread
        thread_manager.lock();
        if (thread_manager.isDrawReady()) {
            particle_system.processParticles(current_time, delta_time);
            thread_manager.incrementPhysicsFrame();
            thread_manager.signalPhysicsDone();
        }
        thread_manager.unlock();

        // Simulate drawing thread
        thread_manager.lock();
        if (thread_manager.isPhysicsReady()) {
            Particle* particles = particle_system.getParticles();

            // Process particles for rendering
            int active_count = 0;
            for (int i = 0; i < particle_system.getMaxParticles(); ++i) {
                if (particles[i].active) {
                    active_count++;

                    // Calculate alpha based on life
                    float alpha = 4.0f * particles[i].life;
                    if (alpha > 1.0f) alpha = 1.0f;

                    // Output particle data for visualization
                    if (frame % 20 == 0 && i < 5) {
                        std::cout << "Particle " << i << ": pos(" 
                                  << particles[i].position.x << ", "
                                  << particles[i].position.y << ", "
                                  << particles[i].position.z << ") "
                                  << "color(" << particles[i].color.x << ", "
                                  << particles[i].color.y << ", "
                                  << particles[i].color.z << ") "
                                  << "alpha=" << alpha << std::endl;
                    }
                }
            }

            if (frame % 20 == 0) {
                std::cout << "Active particles: " << active_count << std::endl;
            }

            thread_manager.incrementDrawFrame();
            thread_manager.signalDrawDone();
        }
        thread_manager.unlock();

        // Update time
        current_time += delta_time;

        // Simulate key press for exit
        if (frame == 99) {
            std::cout << "Simulation completed successfully." << std::endl;
            break;
        }
    }

    return 0;
}

#include <math.h>
