#include "PeakFinder.h"
using namespace soundtouch;

// Macro to compute maximum of two values
#define MAX_VAL(x, y) ((x) > (y) ? (x) : (y))

PeakFinder::PeakFinder()
{
    minPos = maxPos = 0;
}

// Locate the base level (ground) of a peak by moving from 'peakpos' in the given 'direction'
// until the signal starts rising again after a minimum
int PeakFinder::findGround(const float *data, int peakpos, int direction) const
{
    float referenceValue;
    int lowestIndex;
    int currentIndex;
    int ascentCounter;
    float slope;

    ascentCounter = 0;
    referenceValue = data[peakpos];
    lowestIndex = peakpos;
    currentIndex = peakpos;

    while ((currentIndex > minPos) && (currentIndex < maxPos))
    {
        int previousIndex = currentIndex;
        currentIndex += direction;

        slope = data[currentIndex] - data[previousIndex];

        if (slope <= 0.0f)
        {
            // Descending segment
            if (ascentCounter > 0)
                ascentCounter--;

            if (data[currentIndex] < referenceValue)
            {
                lowestIndex = currentIndex;
                referenceValue = data[currentIndex];
            }
        }
        else
        {
            // Ascending segment
            ascentCounter++;
            if (ascentCounter >= 6)
                break;  // Sustained ascent indicates next peak region
        }
    }

    return lowestIndex;
}

// Determine where the waveform crosses a specified 'level', starting from 'peakpos' and 
// moving in the given 'direction'
int PeakFinder::findCrossingLevel(const float *data, float level, int peakpos, int direction) const
{
    float currentValue;
    int index;

    currentValue = data[peakpos];
    assert(currentValue >= level);

    index = peakpos;
    while ((index >= minPos) && (index < maxPos))
    {
        if (data[index + direction] < level)
            return index;  // Found crossing point

        index += direction;
    }

    return -1;  // No crossing found
}

// Compute weighted average position (center of mass) of data points between indices 'firstPos' and 'lastPos'
double PeakFinder::calcMassCenter(const float *data, int firstPos, int lastPos) const
{
    int i;
    double weightedSum;
    double amplitudeSum;

    weightedSum = 0.0;
    amplitudeSum = 0.0;

    for (i = firstPos; i <= lastPos; ++i)
    {
        weightedSum += static_cast<double>(i) * data[i];
        amplitudeSum += data[i];
    }

    if (amplitudeSum < 1e-6)
        return 0.0;

    return weightedSum / amplitudeSum;
}

// Estimate precise center of a peak using local mass distribution around it
double PeakFinder::getPeakCenter(const float *data, int peakpos) const
{
    float peakMagnitude;
    int leftCrossing, rightCrossing;
    float thresholdLevel;
    float baselineMagnitude;
    int groundLeft, groundRight;

    // Find valley points on both sides
    groundLeft = findGround(data, peakpos, -1);
    groundRight = findGround(data, peakpos, 1);

    baselineMagnitude = MAX_VAL(data[groundLeft], data[groundRight]);
    peakMagnitude = data[peakpos];

    // Validate peak prominence
    if (baselineMagnitude < 1e-6)
        return 0.0;
    if ((peakMagnitude / baselineMagnitude) < 1.3)
        return 0.0;

    // Define detection threshold at 70% of peak + 30% of baseline
    thresholdLevel = 0.70f * peakMagnitude + 0.30f * baselineMagnitude;

    // Locate threshold crossings
    leftCrossing = findCrossingLevel(data, thresholdLevel, peakpos, -1);
    rightCrossing = findCrossingLevel(data, thresholdLevel, peakpos, 1);

    if ((leftCrossing < 0) || (rightCrossing < 0))
        return 0.0;

    // Return center of mass within detected bounds
    return calcMassCenter(data, leftCrossing, rightCrossing);
}

// Detect dominant peak position using local mass-center refinement and harmonic analysis
double PeakFinder::detectPeak(const float *data, int aminPos, int amaxPos)
{
    int i;
    int candidateIndex;
    double refinedPosition, currentScore;

    this->minPos = aminPos;
    this->maxPos = amaxPos;

    // Locate global maximum
    candidateIndex = minPos;
    currentScore = data[minPos];
    for (i = minPos + 1; i < maxPos; ++i)
    {
        if (data[i] > currentScore)
        {
            currentScore = data[i];
            candidateIndex = i;
        }
    }

    // Refine position using mass-center method
    refinedPosition = getPeakCenter(data, candidateIndex);
    currentScore = refinedPosition;

    // Harmonic check: consider whether the strongest peak might be an overtone
    for (i = 2; i < 10; ++i)
    {
        double alternatePosition, comparisonValue;
        int integerPos1, integerPos2;

        candidateIndex = static_cast<int>(refinedPosition / static_cast<double>(i) + 0.5);
        if (candidateIndex < minPos)
            break;

        alternatePosition = getPeakCenter(data, candidateIndex);

        integerPos1 = static_cast<int>(refinedPosition + 0.5);
        integerPos2 = static_cast<int>(alternatePosition + 0.5);

        comparisonValue = 2.0 * (data[integerPos2] - data[integerPos1]) / 
                          (data[integerPos2] + data[integerPos1]);

        if (fabs(comparisonValue) < 0.1)
        {
            refinedPosition = alternatePosition;
        }
    }

    return refinedPosition;
}

