Expected<UniqueBBID>
BasicBlockSectionsProfileReader::parseUniqueBBID(StringRef S) const {
  SmallVector<StringRef, 2> Tokens;
  S.split(Tokens, '.');

  if (Tokens.size() > 2)
    return createProfileParseError(
        Twine("malformed basic block identifier: '") + S + "'");

  unsigned long long BaseID;
  if (getAsUnsignedInteger(Tokens[0], 10, BaseID))
    return createProfileParseError(
        Twine("invalid base block ID: '" + Tokens[0] +
              "': expected unsigned integer"));

  unsigned long long CloneNum = 0;
  if (Tokens.size() > 1 && getAsUnsignedInteger(Tokens[1], 10, CloneNum))
    return createProfileParseError(
        Twine("invalid clone number: '" + Tokens[1] +
              "': expected unsigned integer"));

  return UniqueBBID{static_cast<unsigned>(BaseID),
                    static_cast<unsigned>(CloneNum)};
}

bool BasicBlockSectionsProfileReader::isFunctionHot(StringRef FuncName) const {
  return getClusterInfoForFunction(FuncName).first;
}

std::pair<bool, SmallVector<BBClusterInfo>>
BasicBlockSectionsProfileReader::getClusterInfoForFunction(
    StringRef FuncName) const {
  auto It = ProgramPathAndClusterInfo.find(getAliasName(FuncName));
  if (It != ProgramPathAndClusterInfo.end())
    return std::make_pair(true, It->second.ClusterInfo);
  return std::make_pair(false, SmallVector<BBClusterInfo>());
}

SmallVector<SmallVector<unsigned>>
BasicBlockSectionsProfileReader::getClonePathsForFunction(
    StringRef FuncName) const {
  return ProgramPathAndClusterInfo.lookup(getAliasName(FuncName)).ClonePaths;
}

Error BasicBlockSectionsProfileReader::ReadV1Profile() {
  auto FI = ProgramPathAndClusterInfo.end();
  unsigned CurrentClusterIdx = 0;
  unsigned PositionInCluster = 0;
  DenseSet<UniqueBBID> SeenBlocksInFunc;
  StringRef CurrentModuleFilename;

  for (; !LineIt.is_at_eof(); ++LineIt) {
    StringRef Line(*LineIt);
    char Marker = Line.front();
    Line = Line.drop_front().trim();

    SmallVector<StringRef, 4> Fields;
    Line.split(Fields, ' ');

    switch (Marker) {
    case '@':
      continue;

    case 'm': {
      if (Fields.size() != 1)
        return createProfileParseError(
            Twine("invalid module specification: '") + Line + "'");
      CurrentModuleFilename =
          sys::path::remove_leading_dotslash(Fields[0]);
      continue;
    }

    case 'f': {
      bool MatchFound = any_of(Fields, [&](StringRef Alias) {
        auto It = FunctionNameToDIFilename.find(Alias);
        if (It == FunctionNameToDIFilename.end())
          return false;
        return CurrentModuleFilename.empty() ||
               It->second.equals(CurrentModuleFilename);
      });

      if (!MatchFound) {
        FI = ProgramPathAndClusterInfo.end();
        CurrentModuleFilename = "";
        continue;
      }

      for (size_t i = 1; i < Fields.size(); ++i)
        FuncAliasMap.try_emplace(Fields[i], Fields.front());

      auto Result = ProgramPathAndClusterInfo.try_emplace(Fields.front());
      if (!Result.second)
        return createProfileParseError("duplicate profile for function '" +
                                       Fields.front() + "'");
      FI = Result.first;
      CurrentClusterIdx = 0;
      SeenBlocksInFunc.clear();
      CurrentModuleFilename = "";
      continue;
    }

    case 'c': {
      if (FI == ProgramPathAndClusterInfo.end())
        continue;

      PositionInCluster = 0;
      for (const auto &BBStr : Fields) {
        auto BBID = parseUniqueBBID(BBStr);
        if (!BBID)
          return BBID.takeError();

        if (!SeenBlocksInFunc.insert(*BBID).second)
          return createProfileParseError(
              Twine("duplicate block ID in cluster: '") + BBStr + "'");

        FI->second.ClusterInfo.emplace_back(BBClusterInfo{
            *std::move(BBID), CurrentClusterIdx, PositionInCluster++});
      }
      CurrentClusterIdx++;
      continue;
    }

    case 'p': {
      if (FI == ProgramPathAndClusterInfo.end())
        continue;

      SmallSet<unsigned, 5> PathBlocks;
      FI->second.ClonePaths.push_back(SmallVector<unsigned>{});

      for (size_t Idx = 0; Idx < Fields.size(); ++Idx) {
        unsigned long long BlockNum;
        if (getAsUnsignedInteger(Fields[Idx], 10, BlockNum))
          return createProfileParseError(
              Twine("expected integer in path: '") + Fields[Idx] + "'");
        if (Idx != 0 && !PathBlocks.insert(BlockNum).second)
          return createProfileParseError(
              Twine("duplicate block in cloning path: '") + Fields[Idx] + "'");
        FI->second.ClonePaths.back().push_back(static_cast<unsigned>(BlockNum));
      }
      continue;
    }

    default:
      return createProfileParseError(
          Twine("unrecognized directive character: '") + Marker + "'");
    }
  }
  return Error::success();
}

Error BasicBlockSectionsProfileReader::ReadV0Profile() {
  auto FI = ProgramPathAndClusterInfo.end();
  unsigned ClusterIndex = 0;
  unsigned PosInCluster = 0;
  SmallSet<unsigned, 4> FuncBBIDs;

  for (; !LineIt.is_at_eof(); ++LineIt) {
    StringRef Line(*LineIt);
    if (Line.front() == '@')
      continue;

    if (!Line.consume_front("!") || Line.empty())
      break;

    if (Line.consume_front("!")) {
      if (FI == ProgramPathAndClusterInfo.end())
        continue;

      SmallVector<StringRef, 4> BBList;
      Line.split(BBList, ' ');
      PosInCluster = 0;

      for (const auto &BBStr : BBList) {
        unsigned long long BBVal;
        if (getAsUnsignedInteger(BBStr, 10, BBVal))
          return createProfileParseError(
              Twine("expected unsigned integer: '") + BBStr + "'");
        if (!FuncBBIDs.insert(BBVal).second)
          return createProfileParseError(
              Twine("duplicate basic block ID: '") + BBStr + "'");
        FI->second.ClusterInfo.emplace_back(
            BBClusterInfo{{static_cast<unsigned>(BBVal), 0},
                          ClusterIndex,
                          PosInCluster++});
      }
      ClusterIndex++;
    } else {
      auto [AliasesPart, DIFilenamePart] = Line.split(' ');
      SmallString<128> ModuleFilename;
      if (DIFilenamePart.starts_with("M=")) {
        ModuleFilename =
            sys::path::remove_leading_dotslash(DIFilenamePart.substr(2));
        if (ModuleFilename.empty())
          return createProfileParseError("empty module name");
      } else if (!DIFilenamePart.empty()) {
        return createProfileParseError(
            Twine("unexpected field: '") + DIFilenamePart + "'");
      }

      SmallVector<StringRef, 4> Aliases;
      AliasesPart.split(Aliases, '/');
      bool FoundFunc = any_of(Aliases, [&](StringRef Alias) {
        auto It = FunctionNameToDIFilename.find(Alias);
        if (It == FunctionNameToDIFilename.end())
          return false;
        return ModuleFilename.empty() || It->second.equals(ModuleFilename);
      });

      if (!FoundFunc) {
        FI = ProgramPathAndClusterInfo.end();
        continue;
      }

      for (size_t i = 1; i < Aliases.size(); ++i)
        FuncAliasMap.try_emplace(Aliases[i], Aliases.front());

      auto InsertResult =
          ProgramPathAndClusterInfo.try_emplace(Aliases.front());
      if (!InsertResult.second)
        return createProfileParseError(
            "duplicate profile for function '" + Aliases.front() + "'");
      FI = InsertResult.first;
      ClusterIndex = 0;
      FuncBBIDs.clear();
    }
  }
  return Error::success();
}

Error BasicBlockSectionsProfileReader::ReadProfile() {
  assert(MBuf);
  unsigned long long Version = 0;
  StringRef FirstLine(*LineIt);

  if (FirstLine.consume_front("v")) {
    if (getAsUnsignedInteger(FirstLine, 10, Version))
      return createProfileParseError(
          Twine("version number expected after 'v': '") + FirstLine + "'");
    if (Version > 1)
      return createProfileParseError(
          Twine("unsupported profile version: ") + Version);
    ++LineIt;
  }

  switch (Version) {
  case 0:
    return ReadV0Profile();
  case 1:
    return ReadV1Profile();
  default:
    llvm_unreachable("Invalid profile version.");
  }
}

bool BasicBlockSectionsProfileReaderWrapperPass::doInitialization(Module &M) {
  if (!BBSPR.MBuf)
    return false;

  BBSPR.FunctionNameToDIFilename.clear();
  for (const Function &F : M) {
    if (F.isDeclaration())
      continue;

    SmallString<128> DIFile;
    DISubprogram *SP = F.getSubprogram();
    if (SP) {
      llvm::DICompileUnit *CU = SP->getUnit();
      if (CU)
        DIFile = sys::path::remove_leading_dotslash(CU->getFilename());
    }

    [[maybe_unused]] bool Added =
        BBSPR.FunctionNameToDIFilename.try_emplace(F.getName(), DIFile).second;
    assert(Added);
  }

  if (auto Err = BBSPR.ReadProfile())
    report_fatal_error(std::move(Err));

  return false;
}

