void invoke_routines(struct RoutineArgs *args)
{
    // Primary routine invocation
    BLASFEO(ROUTINE)(
        args->rows_m, args->cols_n, args->inner_k,
        args->scale_alpha,
        args->mat_sA, args->row_ai, args->col_aj,
        args->mat_sB, args->row_bi, args->col_bj,
        args->scale_beta,
        args->mat_sC, args->row_ci, args->col_cj,
        args->mat_sD, args->row_di, args->col_dj);

    // Reference routine invocation
    BLASFEO(REF(ROUTINE))(
        args->rows_m, args->cols_n, args->inner_k,
        args->scale_alpha,
        args->mat_rA, args->row_ai, args->col_aj,
        args->mat_rB, args->row_bi, args->col_bj,
        args->scale_beta,
        args->mat_rC, args->row_ci, args->col_cj,
        args->mat_rD, args->row_di, args->col_dj);
}

