#include "utl/BinStream.h"
#include "math/Rand.h"
#include "math/Rand2.h"
#include "obj/Object.h"
#include "os/Debug.h"
#include "os/Endian.h"
#include "os/Timer.h"
#include <vector>

#define BUF_SIZE 512

const char *BinStream::Name() const { return "<unnamed>"; }

BinStream::BinStream(bool b)
    : mLittleEndian(b), mCrypto(nullptr), mRevStack(nullptr) {}

void SwapData(const void *src, void *dst, int sz) {
    switch (sz) {
        case 2: {
            unsigned short *s_in = static_cast<unsigned short *>(const_cast<void *>(src));
            unsigned short *s_out = static_cast<unsigned short *>(dst);
            *s_out = EndianSwap(*s_in);
            break;
        }
        case 4: {
            unsigned int *i_in = static_cast<unsigned int *>(const_cast<void *>(src));
            unsigned int *i_out = static_cast<unsigned int *>(dst);
            *i_out = EndianSwap(*i_in);
            break;
        }
        case 8: {
            unsigned long long *l_in = static_cast<unsigned long long *>(const_cast<void *>(src));
            unsigned long long *l_out = static_cast<unsigned long long *>(dst);
            *l_out = EndianSwap(*l_in);
            break;
        }
        default:
            MILO_ASSERT(false, 0xAC);
            break;
    }
}

void BinStream::DisableEncryption() {
    MILO_ASSERT(mCrypto != nullptr, 0xDC);
    delete mCrypto;
    mCrypto = nullptr;
}

void BinStream::Write(const void *raw_data, int byte_count) {
    if (Fail()) {
        MILO_PRINT_ONCE("Stream error: Can't write to %s\n", Name());
        return;
    }

    const unsigned char *data_ptr = static_cast<const unsigned char *>(raw_data);

    if (!mCrypto) {
        WriteImpl(raw_data, byte_count);
    } else {
        char temp_buffer[BUF_SIZE];
        int remaining = byte_count;

        for (int offset = 0; offset < byte_count; offset += BUF_SIZE) {
            int chunk_size = (remaining >= BUF_SIZE) ? BUF_SIZE : remaining;
            for (int idx = 0; idx < chunk_size; ++idx) {
                u8 key_byte = mCrypto->Int();
                temp_buffer[idx] = data_ptr[offset + idx] ^ key_byte;
            }
            WriteImpl(temp_buffer, chunk_size);
            remaining -= chunk_size;
        }
    }
}

void BinStream::Seek(int offset, SeekType mode) {
    MILO_ASSERT(!Fail(), 0x11F);
    MILO_ASSERT(mCrypto == nullptr, 0x122);
    SeekImpl(offset, mode);
}

void BinStream::WriteEndian(const void *input, int size_in_bytes) {
    if (mLittleEndian) {
        u64 buffer[2]; // enough space for up to 128 bits
        SwapData(input, buffer, size_in_bytes);
        Write(buffer, size_in_bytes);
    } else {
        Write(input, size_in_bytes);
    }
}

bool BinStream::AddSharedInlined(const class FilePath &) {
    MILO_FAIL("BinStream::AddSharedInlined is a PC dev tool only !!");
    return false;
}

BinStream &BinStream::operator<<(const char *text) {
    MILO_ASSERT(text != nullptr, 0x60);
    int len = static_cast<int>(strlen(text));
    *this << len;
    Write(text, len);
    return *this;
}

BinStream &BinStream::operator<<(const Symbol &symbol) {
    const char *str_val = symbol.Str();
    unsigned int str_len = static_cast<unsigned int>(strlen(str_val));
    MILO_ASSERT(str_len < static_cast<unsigned int>(BUF_SIZE), 0x6C);
    *this << str_len;
    Write(str_val, str_len);
    return *this;
}

BinStream &BinStream::operator<<(const class String &text_str) {
    int length = static_cast<int>(text_str.length());
    *this << length;
    Write(text_str.c_str(), length);
    return *this;
}

void BinStream::EnableWriteEncryption() {
    MILO_ASSERT(mCrypto == nullptr, 0xC8);
    int seed = RandomInt();
    *this << seed;
    mCrypto = new Rand2(seed);
}

int BinStream::PopRev(Hmx::Object *target_obj) {
    MILO_ASSERT(mRevStack != nullptr, 0x34);

    ObjVersion &back_entry = mRevStack->back();

    while (back_entry.obj == nullptr) {
        MILO_NOTIFY("hey object got deleted!");
        mRevStack->pop_back();
        back_entry = mRevStack->back();
    }

    int revision_count = back_entry.revs;

    if (target_obj != back_entry.obj) {
        MILO_LOG("rev stack $this mismatch (%08x != %08x\n", target_obj, back_entry.obj);
        MILO_LOG("curr obj: %s %s\n", target_obj->ClassName(), PathName(target_obj));
        MILO_LOG("stack obj: %s %s\n", back_entry.obj->ClassName(), PathName(back_entry.obj));
        MILO_FAIL(
            "rev stack (%08x %s %s != %08x %s %s)\n",
            target_obj,
            target_obj->ClassName(),
            PathName(target_obj),
            back_entry.obj,
            back_entry.obj->ClassName(),
            PathName(back_entry.obj)
        );
    }

    mRevStack->pop_back();
    return revision_count;
}

void BinStream::Read(void *buffer, int byte_count) {
    if (Fail()) {
        MILO_NOTIFY_ONCE("Stream error: Can't read from %s", Name());
        memset(buffer, 0, byte_count);
        return;
    }

    AutoGlitchReport report(50.0f, __FUNCTION__);
    ReadImpl(buffer, byte_count);

    if (mCrypto) {
        unsigned char *byte_ptr = static_cast<unsigned char *>(buffer);
        for (int i = 0; i < byte_count; ++i) {
            unsigned char crypto_val = mCrypto->Int();
            byte_ptr[i] ^= crypto_val;
        }
    }
}

int BinStream::ReadAsync(void *dest, int count) {
    Read(dest, count);
    return Fail() ? 0 : count;
}

void BinStream::ReadEndian(void *out_buf, int size_in_bytes) {
    Read(out_buf, size_in_bytes);
    if (mLittleEndian) {
        SwapData(out_buf, out_buf, size_in_bytes);
    }
}

void BinStream::ReadString(char *out_chars, int max_capacity) {
    unsigned int string_length;
    *this >> string_length;

    if (string_length >= static_cast<unsigned int>(max_capacity)) {
        MILO_FAIL("String chars %d > %d", string_length + 1, max_capacity);
    }

    Read(out_chars, string_length);
    out_chars[string_length] = '\0';
}

BinStream &BinStream::operator>>(Symbol &symbol_out) {
    char local_buffer[BUF_SIZE];
    ReadString(local_buffer, BUF_SIZE);
    symbol_out = local_buffer;
    return *this;
}

BinStream &BinStream::operator>>(String &string_out) {
    int required_size;
    *this >> required_size;
    string_out.resize(required_size);
    Read(static_cast<void *>(const_cast<char *>(string_out.c_str())), required_size);
    return *this;
}

void BinStream::EnableReadEncryption() {
    MILO_ASSERT(mCrypto == nullptr, 0xC0);
    int seed_value;
    *this >> seed_value;
    mCrypto = new Rand2(seed_value);
}

BinStream::~BinStream() {
    delete mCrypto;
    delete mRevStack;
}

