#include "average_onto_vertices.h"
template<typename DerivedV,typename DerivedF,typename DerivedS>
IGL_INLINE void igl::average_onto_vertices(const Eigen::MatrixBase<DerivedV> &V,
  const Eigen::MatrixBase<DerivedF> &F,
  const Eigen::MatrixBase<DerivedS> &S,
  Eigen::MatrixBase<DerivedS> &SV)
{
  // Initialize output matrix and count vector
  SV.setZero(V.rows(), S.cols());
  Eigen::Matrix<typename DerivedF::Scalar, Eigen::Dynamic, 1> vertex_counts(V.rows());
  vertex_counts.setZero();

  // Accumulate values from faces to vertices
  for (int face_idx = 0; face_idx < F.rows(); ++face_idx)
  {
    for (int corner_idx = 0; corner_idx < F.cols(); ++corner_idx)
    {
      int vertex_id = F(face_idx, corner_idx);
      SV.row(vertex_id) += S.row(face_idx);
      vertex_counts[vertex_id] += static_cast<typename DerivedF::Scalar>(1);
    }
  }

  // Compute average by dividing accumulated values by vertex counts
  for (int i = 0; i < V.rows(); ++i)
  {
    if (vertex_counts[i] > 0)
    {
      SV.row(i) /= vertex_counts[i];
    }
  }
};
