int main() {
    int n;
    cin >> n;

    // Calculate k as the ceiling of square root of n using sqrt function
    double sqrt_n = sqrt(n);
    int k = (int)ceil(sqrt_n);

    cout << fixed << setprecision(6) << (double)k << endl;

    // Generate points in grid pattern
    for (int i = 0; i < n; ++i) {
        // Compute row and column using division and modulo
        int row = i / k;
        int col = i % k;

        // Output coordinates with offset of 0.5
        cout << (col + 0.5) << " " << (row + 0.5) << " " << 0.0 << endl;
    }

    return 0;
}

