class EGLBackend {
public:
    EGLBackend(unsigned int w, unsigned int h);
    ~EGLBackend();
    void present();
    void activate();
    void deactivate();
private:
    EGLSurface surface;
    EGLContext context;
    EGLDisplay display;
    static constexpr EGLint configAttribs[] = {
        EGL_SURFACE_TYPE    , EGL_PBUFFER_BIT,
        EGL_RENDERABLE_TYPE , EGL_OPENGL_BIT,
        EGL_RED_SIZE        , 8,
        EGL_GREEN_SIZE      , 8,
        EGL_BLUE_SIZE       , 8,
        EGL_ALPHA_SIZE      , 8,
        EGL_DEPTH_SIZE      , 24,
        EGL_STENCIL_SIZE    , 8,
        EGL_NONE
    };
};

constexpr EGLint EGLBackend::configAttribs[];

struct HeadlessGLWindow : public WindowInterface {
    HeadlessGLWindow(unsigned int width, unsigned int height);
    ~HeadlessGLWindow() override;
    void ShowFullscreen(const TrueFalseToggle) override;
    void Move(int /*x*/, int /*y*/) override;
    void Resize(unsigned int /*w*/, unsigned int /*h*/) override;
    void MakeCurrent() override;
    void RemoveCurrent() override;
    void SwapBuffers() override;
    void ProcessEvents() override;
    EGLBackend backend;
};

EGLBackend::EGLBackend(unsigned int width, unsigned int height) {
    display = eglGetDisplay(EGL_DEFAULT_DISPLAY);
    if (!display) {
        std::cerr << "Failed to initialize EGL display" << std::endl;
    }

    EGLint verMajor, verMinor;
    if (eglInitialize(display, &verMajor, &verMinor) != EGL_TRUE) {
        std::cerr << "EGL initialization failed" << std::endl;
    }

    if (eglBindAPI(EGL_OPENGL_API) != EGL_TRUE) {
        std::cerr << "Failed to bind OpenGL API" << std::endl;
    }

    EGLint configCount;
    eglGetConfigs(display, nullptr, 0, &configCount);
    std::vector<EGLConfig> configs(configCount);
    EGLint actualConfigs;
    eglChooseConfig(display, configAttribs, configs.data(), configCount, &actualConfigs);

    context = eglCreateContext(display, configs[0], EGL_NO_CONTEXT, nullptr);

    const EGLint pbufferAttrs[] = {
        EGL_WIDTH, static_cast<EGLint>(width),
        EGL_HEIGHT, static_cast<EGLint>(height),
        EGL_NONE
    };

    surface = eglCreatePbufferSurface(display, configs[0], pbufferAttrs);
    if (surface == EGL_NO_SURFACE) {
        std::cerr << "Unable to create EGL offscreen surface" << std::endl;
    }
}

EGLBackend::~EGLBackend() {
    if (context) {
        eglDestroyContext(display, context);
    }
    if (surface) {
        eglDestroySurface(display, surface);
    }
    if (display) {
        eglTerminate(display);
    }
}

void EGLBackend::present() {
    eglSwapBuffers(display, surface);
}

void EGLBackend::activate() {
    eglMakeCurrent(display, surface, surface, context);
}

void EGLBackend::deactivate() {
    eglMakeCurrent(display, EGL_NO_SURFACE, EGL_NO_SURFACE, EGL_NO_CONTEXT);
}

