// Redefine file descriptor duplication logic with alternative implementation
int dup2(int oldfd, int newfd) {
    int result;

#ifdef SYS_dup2
    // Use SYS_dup2 system call in a retry loop for EBUSY cases
    do {
        result = __syscall(SYS_dup2, oldfd, newfd);
    } while (result == -EBUSY);
#else
    // Fallback implementation when SYS_dup2 is not available
    if (oldfd == newfd) {
        // When both descriptors are the same, just verify validity
        result = __syscall(SYS_fcntl, oldfd, F_GETFD);
        if (result >= 0) return oldfd;
    } else {
        // Use SYS_dup3 as alternative with flags set to 0
        do {
            result = __syscall(SYS_dup3, oldfd, newfd, 0);
        } while (result == -EBUSY);
    }
#endif

    return __syscall_ret(result);
}

