int main(int argc, const char* const* argv) {
    // Define supported subcommands and special flags
    const std::unordered_set<std::string_view> validSubcommands = {"start", "stop"};
    const std::unordered_set<std::string_view> helpFlags = {"-h", "--help"};

    // Convert raw args to vector for easier manipulation
    std::vector<const char*> processedArgs(argv, argv + argc);

    // Determine if we should auto-inject 'start' as default subcommand
    bool needsDefaultSubcommand = true;
    if (argc >= 2) {
        std::string_view firstArg = argv[1];
        if (helpFlags.count(firstArg) > 0 || validSubcommands.count(firstArg) > 0) {
            needsDefaultSubcommand = false;
        }
    }

    if (needsDefaultSubcommand) {
        processedArgs.insert(processedArgs.begin() + 1, "start");
    }

    // Setup argument parser
    argparse::ArgumentParser cli("turingdb", "1.0", argparse::default_arguments::help);

    // Instantiate command handlers
    std::unique_ptr<StartCmd> startHandler = StartCmd::create();
    std::unique_ptr<StopCmd> stopHandler = StopCmd::create();

    // Add --version flag
    cli.add_argument("-v", "--version")
        .action([](const auto&) {
            printVersionInfo();
            std::exit(EXIT_SUCCESS);
        })
        .default_value(false)
        .implicit_value(true)
        .nargs(0)
        .help("Show version and build info");

    // Attach subparsers
    cli.add_subparser(startHandler->getArgParser());
    cli.add_subparser(stopHandler->getArgParser());

    // Custom description and epilog
    std::ostringstream descStream;
    descStream << "\nUsage: turingdb [OPTIONS] [SUBCOMMAND]\n"
               << "By default, 'start' is assumed if no subcommand is given.\n\n"
               << "Available subcommands:\n"
               << startHandler->getArgParser();
    cli.add_description("TuringDB — High-performance Graph Database Server");
    cli.add_epilog(descStream.str());

    try {
        cli.parse_args(static_cast<int>(processedArgs.size()), processedArgs.data());

        // Dispatch based on active subcommand
        if (cli.is_subcommand_used("start")) {
            return startHandler->execute();
        } else if (cli.is_subcommand_used("stop")) {
            return stopHandler->execute();
        } else {
            throw FatalException("Internal error: no subcommand selected after parsing.");
        }
    } catch (const std::exception& ex) {
        std::cerr << "Error: " << ex.what() << "\n\n";
        std::cerr << cli;
        return EXIT_FAILURE;
    }

    return EXIT_FAILURE; // fallback
}

