using namespace std;

class Solution {
public:
    int countBinarySubstrings(string s) {
        int countPrev = 0;   // size of the last different group
        int countCurr = 1;   // size of the current consecutive group
        int total = 0;

        for (int idx = 1; idx < s.length(); idx++) {
            if (s[idx] == s[idx - 1]) {
                countCurr++;  // continue current group
            } else {
                total += min(countPrev, countCurr);  // add valid substrings between groups
                countPrev = countCurr;               // shift current to previous
                countCurr = 1;                       // start new group
            }
        }

        // account for final pair of groups
        total += min(countPrev, countCurr);
        return total;
    }
};

