void mass_spring_system(double Ts, int state_count, int control_count, int horizon_length, double *state_matrix, double *input_matrix, double *state_offset, double *initial_state)
{
    int state_squared = state_count * state_count;
    int error_code = 0;
    int mass_count = state_count / 2;

    // Allocate temporary matrices
    double **temp_matrices = (double**)malloc(3 * sizeof(double*));
    for (int i = 0; i < 3; ++i) {
        temp_matrices[i] = NULL;
    }

    // Initialize T matrix (tridiagonal system matrix)
    d_zeros(&temp_matrices[0], mass_count, mass_count);
    int idx;
    for (idx = 0; idx < mass_count; idx++) {
        temp_matrices[0][idx * (mass_count + 1)] = -2.0;
    }
    for (idx = 0; idx < mass_count - 1; idx++) {
        temp_matrices[0][idx * (mass_count + 1) + 1] = 1.0;
    }
    for (idx = 1; idx < mass_count; idx++) {
        temp_matrices[0][idx * (mass_count + 1) - 1] = 1.0;
    }

    // Initialize zero and identity matrices
    double *zero_matrix; d_zeros(&zero_matrix, mass_count, mass_count);
    double *identity_matrix; d_zeros(&identity_matrix, mass_count, mass_count);
    for (idx = 0; idx < mass_count; idx++) {
        identity_matrix[idx * (mass_count + 1)] = 1.0;
    }

    // Build continuous-time system matrix Ac
    double *continuous_A; d_zeros(&continuous_A, state_count, state_count);
    dmcopy(mass_count, mass_count, zero_matrix, mass_count, continuous_A, state_count);
    dmcopy(mass_count, mass_count, temp_matrices[0], mass_count, continuous_A + mass_count, state_count);
    dmcopy(mass_count, mass_count, identity_matrix, mass_count, continuous_A + mass_count * state_count, state_count);
    dmcopy(mass_count, mass_count, zero_matrix, mass_count, continuous_A + mass_count * (state_count + 1), state_count);

    free(temp_matrices[0]);
    free(zero_matrix);
    free(identity_matrix);

    // Input matrix Bc
    d_zeros(&identity_matrix, control_count, control_count);
    for (idx = 0; idx < control_count; idx++) {
        identity_matrix[idx * (control_count + 1)] = 1.0;
    }
    double *continuous_B; d_zeros(&continuous_B, state_count, control_count);
    dmcopy(control_count, control_count, identity_matrix, control_count, continuous_B + mass_count, state_count);
    free(identity_matrix);

    // Discretization: compute exp(Ts * Ac)
    double *discrete_state_offset; d_zeros(&discrete_state_offset, state_count, 1);
    dmcopy(state_count, 1, discrete_state_offset, state_count, state_offset, state_count);
    dmcopy(state_count, state_count, continuous_A, state_count, state_matrix, state_count);
    dscal_3l(state_squared, Ts, state_matrix);
    expm(state_count, state_matrix);

    double *temp_discrete; d_zeros(&temp_discrete, state_count, state_count);
    d_zeros(&identity_matrix, state_count, state_count);
    for (idx = 0; idx < state_count; idx++) {
        identity_matrix[idx * (state_count + 1)] = 1.0;
    }
    dmcopy(state_count, state_count, state_matrix, state_count, temp_discrete, state_count);
    daxpy_3l(state_squared, -1.0, identity_matrix, temp_discrete);
    dgemm_nn_3l(state_count, control_count, state_count, temp_discrete, state_count, continuous_B, state_count, input_matrix, state_count);

    free(temp_discrete);
    free(identity_matrix);

    int *pivot_indices = (int*)malloc(state_count * sizeof(int));
    dgesv_3l(state_count, control_count, continuous_A, state_count, pivot_indices, input_matrix, state_count, &error_code);
