        write_buf = (hobj_ref_t*)HDmalloc(buf_unit * DIM1_SIZE);
        read_buf  = (hobj_ref_t*)HDmalloc(buf_unit * DIM1_SIZE);
        tmp_buf   = (hobj_ref_t*)HDmalloc(buf_unit * DIM1_SIZE);

