}

static void obj_ref_test()
{
    const H5std_string grp_comment = "Foo!";
    LOG_TEST("Object Reference Functions");

    H5File* fptr = nullptr;
    try {
        hobj_ref_t *write_buf,
                   *read_buf,
                   *tmp_buf;

        size_t unit_size = MAX(sizeof(unsigned), sizeof(hobj_ref_t));
        write_buf = (hobj_ref_t*)HDmalloc(unit_size * DIM1_SIZE);
        read_buf  = (hobj_ref_t*)HDmalloc(unit_size * DIM1_SIZE);
        tmp_buf   = (hobj_ref_t*)HDmalloc(unit_size * DIM1_SIZE);

        fptr = new H5File(FILE_A, H5F_ACC_TRUNC);

        hsize_t dims1[] = {DIM1_SIZE};
        DataSpace dspace1(DIM1_RANK, dims1);

        Group rootGrp = fptr->createGroup("Group1");
        rootGrp.setComment(".", grp_comment);

        DataSet ds1 = rootGrp.createDataSet(DATASET_ALPHA, PredType::NATIVE_UINT, dspace1);
        unsigned* u32_ptr;
        for (int i = 0; i < DIM1_SIZE; ++i)
            *(u32_ptr = (unsigned*)write_buf + i) = i * 3;

        ds1.write(write_buf, PredType::NATIVE_UINT);
        ds1.close();

        DataSet ds2 = rootGrp.createDataSet(DATASET_BETA, PredType::NATIVE_UCHAR, dspace1);
        ds2.close();

        CompType dtype1(sizeof(s1_t));
        dtype1.insertMember(FIELD_A, HOFFSET(s1_t, a), PredType::NATIVE_INT);
        dtype1.insertMember(FIELD_B, HOFFSET(s1_t, b), PredType::NATIVE_INT);
        dtype1.insertMember(FIELD_C, HOFFSET(s1_t, c), PredType::NATIVE_FLOAT);
        dtype1.commit(rootGrp, TYPE_NAME);
        dtype1.close();
        rootGrp.close();

        DataSet ref_ds = fptr->createDataSet(DATASET_GAMMA, PredType::STD_REF_OBJ, dspace1);

        // Object reference creation and verification
        fptr->reference(&write_buf[0], "/Group1/Dataset1");
        H5O_type_t obj_type = ref_ds.getRefObjType(&write_buf[0], H5R_OBJECT);
