static void region_ref_1D_test()
{
    hsize_t start[DIM3_RANK],
            stride[DIM3_RANK],
            count[DIM3_RANK],
            block[DIM3_RANK];
    hsize_t coords[POINT_COUNT][DIM3_RANK];
    hsize_t low[DIM3_RANK], high[DIM3_RANK];

    LOG_TEST("1-D Dataset Region Reference Functions");

    try {
        hdset_reg_ref_t *write_buf,
                        *read_buf;
        uint8_t *data_write,
                *data_read;

        write_buf = (hdset_reg_ref_t*)HDcalloc(sizeof(hdset_reg_ref_t), DIM1_SIZE);
        read_buf  = (hdset_reg_ref_t*)HDmalloc(sizeof(hdset_reg_ref_t) * DIM1_SIZE);
        data_write = (uint8_t*)HDmalloc(sizeof(uint8_t) * DIM3_SIZE);
        data_read  = (uint8_t*)HDcalloc(sizeof(uint8_t), DIM3_SIZE);

        H5File file(FILE_B, H5F_ACC_TRUNC);

        hsize_t dims3[] = {DIM3_SIZE};
        DataSpace dspace3(DIM3_RANK, dims3);

        DataSet ds3 = file.createDataSet(DATASET_BETA, PredType::STD_U8LE, dspace3);
        for (int i = 0; i < DIM3_SIZE; ++i)
            data_write[i] = static_cast<uint8_t>(i * 3);

        ds3.write(data_write, PredType::STD_U8LE);
        ds3.close();

        hsize_t dims1[] = {DIM1_SIZE};
        DataSpace dspace1(DIM1_RANK, dims1);
        DataSet ds1 = file.createDataSet(DATASET_ALPHA, PredType::STD_REF_DSETREG, dspace1);

        // Hyperslab setup
        start[0] = 2; stride[0] = 5; count[0] = 15; block[0] = 2;
        dspace3.selectHyperslab(H5S_SELECT_SET, count, start, stride, block);
        hssize_t nelms = dspace3.getSelectNpoints();
        verify_val(nelms, 30, "getSelectNpoints", __LINE__, __FILE__);
        file.reference(&write_buf[0], "/Dataset2", dspace3);

        H5O_type_t obj_type = ds1.getRefObjType(&write_buf[0], H5R_DATASET_REGION);
        verify_val(obj_type, H5O_TYPE_DATASET, "getRefObjType", __LINE__, __FILE__);

        // Point selection
        coords[0][0] = 16; coords[1][0] = 22; coords[2][0] = 38; coords[3][0] = 41;
        coords[4][0] = 52; coords[5][0] = 63; coords[6][0] = 70; coords[7][0] = 89;
        coords[8][0] = 97; coords[9][0] = 3;
        dspace3.selectElements(H5S_SELECT_SET, POINT_COUNT, (const hsize_t*)coords);
        nelms = dspace3.getSelectNpoints();
        verify_val(nelms, 10, "getSelectNpoints", __LINE__, __FILE__);
        file.reference(&write_buf[1], "/Dataset2", dspace3);

        ds1.write(write_buf, PredType::STD_REF_DSETREG);
        dspace1.close(); ds1.close(); dspace3.close();
        file.close();

        // Reopen and test dereference
        file.openFile(FILE_B, H5F_ACC_RDWR);
        ds1 = file.openDataSet("/Dataset1");
        ds1.read(read_buf, PredType::STD_REF_DSETREG);

        // Test dereference method
        ds3.dereference(ds1, &read_buf[0], H5R_DATASET_REGION);
        obj_type = ds1.getRefObjType(&read_buf[0], H5R_DATASET_REGION);
        verify_val(obj_type, H5O_TYPE_DATASET, "getRefObjType", __LINE__, __FILE__);

        DataSpace ds_space = ds3.getSpace();
        nelms = ds_space.getSimpleExtentNpoints();
        verify_val((long)nelms, 100, "getSimpleExtentNpoints", __LINE__, __FILE__);

        // Constructor-based dereference
        DataSet ds_copy(ds1, &read_buf[0], H5R_DATASET_REGION);
        ds_space = ds_copy.getSpace();
        nelms = ds_space.getSimpleExtentNpoints();
        verify_val((long)nelms, 100, "getSimpleExtentNpoints", __LINE__, __FILE__);
        ds_copy.close(); ds_space.close();

        ds3.read(data_read, PredType::STD_U8LE);
        for (int i = 0; i < DIM3_SIZE; ++i)
            verify_val(data_read[i], static_cast<uint8_t>(i*3), "read data", __LINE__, __FILE__);

        // Get region and validate hyperslab blocks
        DataSpace reg_sp = ds1.getRegion(&read_buf[0]);
        nelms = reg_sp.getSelectNpoints();
        verify_val((long)nelms, 30, "getSelectNpoints", __LINE__, __FILE__);

        nelms = reg_sp.getSelectHyperNblocks();
        verify_val((long)nelms, 15, "getSelectHyperNblocks", __LINE__, __FILE__);

        hsize_t* block_list = (hsize_t*)HDmalloc(nelms * DIM3_RANK * 2 * sizeof(hsize_t));
        reg_sp.getSelectHyperBlocklist(0, nelms, block_list);

        // Verify block coordinates
        for (int i = 0; i < 30; ++i)
            verify_val(block_list[i], (hsize_t)(2 + 5*(i/2) + (i%2)), "block coordinate", __LINE__, __FILE__);

        reg_sp.getSelectBounds(low, high);
        verify_val(low[0], (hsize_t)2, "getSelectBounds", __LINE__, __FILE__);
        verify_val(high[0], (hsize_t)73, "getSelectBounds", __LINE__, __FILE__);
        reg_sp.close();

        // Point region test
        DataSpace pt_sp = ds1.getRegion(&read_buf[1]);
        hssize_t pt_count = pt_sp.getSelectElemNpoints();
        verify_val((long)pt_count, 10, "getSelectElemNpoints", __LINE__, __FILE__);

        hsize_t* point_list = (hsize_t*)HDmalloc(pt_count * DIM3_RANK * sizeof(hsize_t));
        pt_sp.getSelectElemPointlist(0, pt_count, point_list);
        for (int i = 0; i < POINT_COUNT; ++i)
            verify_val(point_list[i], coords[i][0], "point coordinate", __LINE__, __FILE__);

        pt_sp.getSelectBounds(low, high);
        verify_val(low[0], (hsize_t)3, "getSelectBounds", __LINE__, __FILE__);
        verify_val(high[0], (hsize_t)97, "getSelectBounds", __LINE__, __FILE__);
        pt_sp.close();

        HDfree(block_list);
        HDfree(point_list);
        ds3.close(); ds1.close(); file.close();
        HDfree(write_buf);
        HDfree(read_buf);
        HDfree(data_write);
        HDfree(data_read);
        TEST_PASS();
    }
    catch (Exception& ex) {
        TEST_FAIL("region_ref_1D_test()", __LINE__, __FILE__, ex.getCFuncName(), ex.getCDetailMsg());
    }
}

