#include "melody.h"
#include <algorithm>
#include "callbacks.h"
#include "commands.h"
#include "game_functions.h"
#include "hook_wrapper.h"
#include "string_util.h"
#include "zeal.h"

// Requirements for Melody per Secrets in discord zeal-discussions ~ 2024/03/25
// - Bards only
// - 5 song limit
// - Retries allowed on missed notes
// - Character stuns must end melody
// Test cases:
// - Command line behavior and messages:
//   - Bard class only
//   - # of songs limit <= 5
//   - Only ints as parameters
//   - Zero parameter melody ends melody
//   - Start is prevented when not standing
//   - New /melody without a /stopsong transitions cleanly after current song
//   - /stopsong immediately stops (aborts) active song
// - Check basic song looping functionality (single song, multiple songs)
// - Retry logic for missed notes (correct rewind of song index, retry timeout)\
//   - Should advance song after 8 retries (try Selo's indoors)
//   - Should terminate melody after 15 failures without a success
// - Graceful handling of spells without single target
//   - Skipping of song with single line complaint
//   - Termination of melody after retry limit if all songs are failing
// - Terminated when sitting
// - Paused when zoning, trading, looting, or ducking and then resumed

const int MAX_REWIND_ATTEMPTS = 8;          // Rewind up to this many times before advancing.
const int MAX_FAILURES_BEFORE_QUIT = 15;    // End melody if too many retries without success.
const unsigned long ZONE_ENTER_DELAY_MS = 2000;  // Wait after zoning before resuming.
const unsigned long CAST_RETRY_DELAY_MS = 1500;  // Max wait after cast timer before retry.
const unsigned long ITEM_CAST_DELAY_MS = 500;    // Wait after casting item clicky.
const unsigned long ITEM_QUEUE_EXPIRY_MS = 3650; // Timeout for queued item use.

enum ItemState { IdleState = 0, CastRequestedState, CastStartedState };

bool Melody::start(const std::vector<int>& input_songs, bool continue_session) {
  if (!Zeal::Game::is_in_game()) return false;

  Zeal::GameStructures::GAMECHARINFO* player_data = Zeal::Game::get_char_info();
  if (!player_data || player_data->StunnedState) {
    Zeal::Game::print_chat(USERCOLOR_SPELL_FAILURE, "Can not start melody while stunned.");
    return false;
  }

  Zeal::GameStructures::Entity* self = Zeal::Game::get_self();
  if (!self || (self->StandingState != Stance::Stand)) {
    Zeal::Game::print_chat(USERCOLOR_SPELL_FAILURE, "Can only start melody when standing.");
    return false;
  }

  std::vector<int> acceptable_songs;
  for (const int& slot : input_songs) {
    if (slot < 0 || slot >= GAME_NUM_SPELL_GEMS) {
      Zeal::Game::print_chat(USERCOLOR_SPELL_FAILURE, "Error: Invalid spell gem %i", slot + 1);
      return false;
    }
    if (player_data->MemorizedSpell[slot] == -1) {
      Zeal::Game::print_chat(USERCOLOR_SPELL_FAILURE, "Error: skipping empty spell gem %i", slot + 1);
    } else {
      acceptable_songs.push_back(slot);
    }
  }

  if (acceptable_songs.empty() && !input_songs.empty()) {
    Zeal::Game::print_chat(USERCOLOR_SPELL_FAILURE, "Error: no valid songs");
    return false;
  }

  if (!zone_entry_time) {
    zone_entry_time = GetTickCount64() - ZONE_ENTER_DELAY_MS;
  }

  if (!continue_session || 
      (input_songs.size() != acceptable_songs.size()) || 
      (current_song_index < 0) ||
      (current_song_index >= acceptable_songs.size())) {
    current_song_index = -1;
  }

  playlist = acceptable_songs;
  is_running = !playlist.empty();
  attempt_counter = 0;
  active_cast_id = kInvalidSpellId;
  retry_cast_id = kInvalidSpellId;
  pending_cast_id = kInvalidSpellId;
  item_slot = -1;
  item_state = IdleState;

  if (is_running) {
    Zeal::Game::print_chat(USERCOLOR_SPELLS, "You begin playing a melody.");
  }
  return true;
}

void Melody::resume() {
  if (is_running) return;
  start(playlist, true);
}

void Melody::end(bool announce) {
  if (is_running) {
    if (active_cast_id != kInvalidSpellId) {
      current_song_index--;
      if (current_song_index < 0) {
        current_song_index = playlist.size() - 1;
      }
    }
    is_running = false;
    attempt_counter = 0;
    active_cast_id = kInvalidSpellId;
    retry_cast_id = kInvalidSpellId;
    pending_cast_id = kInvalidSpellId;
    item_slot = -1;
    item_state = IdleState;
    if (announce) {
      Zeal::Game::print_chat(USERCOLOR_SPELL_FAILURE, "Your melody has ended.");
    }
  }
}

bool Melody::use_item(int slot) {
  if (!is_running) return false;
  item_slot = slot;
  item_timeout = GetTickCount64() + ITEM_QUEUE_EXPIRY_MS;
  return true;
}

void Melody::handle_stop_cast_callback(BYTE reason, WORD spell_id) {
  if (reason != 3 || !is_running) {
    end(true);
    return;
  }

  if (active_cast_id == spell_id && (++attempt_counter % MAX_REWIND_ATTEMPTS)) {
    retry_cast_id = active_cast_id;
  }
  active_cast_id = kInvalidSpellId;
}

void __fastcall StopCast(int t, int u, BYTE reason, WORD spell_id) {
  ZealService::get_instance()->melody->handle_stop_cast_callback(reason, spell_id);
  ZealService::get_instance()->hooks->hook_map["StopCast"]->original(StopCast)(t, u, reason, spell_id);
}

void Melody::stop_active_cast() {
  Zeal::GameStructures::GAMECHARINFO* player_data = Zeal::Game::get_char_info();
  Zeal::GameStructures::Entity* self = Zeal::Game::get_self();
  if (player_data && self && self->ActorInfo && self->ActorInfo->CastingSpellId != kInvalidSpellId) {
    ZealService::get_instance()->hooks->hook_map["StopCast"]->original(StopCast)(
        (int)player_data, 0, 0, self->ActorInfo->CastingSpellId);
  }
  active_cast_id = kInvalidSpellId;
}

static void quietly_end_bard_song() {
  Zeal::GameStructures::Entity* self = Zeal::Game::get_self();
  Zeal::GameStructures::GAMECHARINFO* player_data = Zeal::Game::get_char_info();

  *(int16_t*)(0x007ce45a) = -1;
  self->ActorInfo->CastingSpellId = kInvalidSpellId;
  self->ActorInfo->CastingSpellGemNumber = 0;
  self->ActorInfo->CastingTimeout = 0;
  self->ActorInfo->FizzleTimeout = 0;

  auto* spell_mgr = Zeal::Game::get_spell_mgr();
  for (int i = 0; i < GAME_NUM_SPELL_GEMS; ++i) {
    int spell_id = player_data->MemorizedSpell[i];
    if (spell_mgr && spell_id > 0 && spell_id < 4000) {
      auto* info = spell_mgr->Spells[spell_id];
      if (info && info->RecastTime) continue;
    }
    self->ActorInfo->RecastTimeout[i] = 0;
  }

  const int OP_ManaChange = 0x417f;
  Zeal::Game::send_message(OP_ManaChange, nullptr, 0, 1);
}

void Melody::tick() {
  if (!is_running) return;

  Zeal::GameStructures::Entity* self = Zeal::Game::get_self();
  Zeal::GameStructures::GAMECHARINFO* player_data = Zeal::Game::get_char_info();

  if (!Zeal::Game::is_in_game() || !self || !self->ActorInfo || !player_data ||
      (self->StandingState == Stance::Sit) || (player_data->StunnedState) || 
      (attempt_counter > MAX_FAILURES_BEFORE_QUIT)) {
    end(true);
    return;
  }

  static ULONGLONG last_cast_time = GetTickCount64();
  static ULONGLONG cast_start_time = last_cast_time;
  ULONGLONG now = GetTickCount64();

  if (!zone_entry_time || now < zone_entry_time + ZONE_ENTER_DELAY_MS) return;

  if (Zeal::Game::GetSpellCastingTime() != -1) {
    last_cast_time = now;
    if ((last_cast_time - cast_start_time) > 1000) {
      attempt_counter = 0;
    }
    return;
  } else if (item_state == CastRequestedState) {
    if ((now - cast_start_time) < 1000) return;
    Zeal::Game::print_chat("Melody use item start sync ack failure");
  }

  if (active_cast_id == pending_cast_id) {
    pending_cast_id = kInvalidSpellId;
  }
  active_cast_id = kInvalidSpellId;

  bool casting_in_progress = self->ActorInfo->CastingSpellId != kInvalidSpellId;
  bool server_confirmed = (self->ActorInfo->CastingSpellGemNumber == 0xff);

  if (casting_in_progress && !server_confirmed) {
    bool using_item = (item_state != IdleState);
    unsigned long timeout = using_item ? ITEM_CAST_DELAY_MS : CAST_RETRY_DELAY_MS;
    bool expired = ((now - last_cast_time) > timeout);
    if (!expired) return;

    if (!using_item) {
      Zeal::Game::print_chat("Melody: ack time out error, trying to restart");
      stop_active_cast();
    }
  }

  if (!Zeal::Game::get_game() || !Zeal::Game::get_game()->IsOkToTransact() || 
      self->StandingState != Stance::Stand) {
    return;
  }

  item_state = IdleState;
  if (item_slot >= 0) {
    stop_active_cast();
    Zeal::GameStructures::GAMEITEMINFO* used_item = nullptr;
    bool success = (item_timeout >= now) && Zeal::Game::use_item(item_slot, false, &used_item);
    item_slot = -1;

    if (success) {
      item_state = CastRequestedState;
      if (used_item && used_item->Common.CastTime == 0 && Zeal::Game::get_game()->IsOkToTransact()) {
        item_state = IdleState;
      }
      cast_start_time = now;
      last_cast_time = now;
      return;
    }
  }

  int next_slot = find_next_song();
  if (next_slot < 0) return;

  WORD spell_id = player_data->MemorizedSpell[next_slot];
  if (spell_id == kInvalidSpellId) return;

  if (Zeal::Game::get_spell_mgr()) {
    auto* spell_info = Zeal::Game::get_spell_mgr()->Spells[spell_id];
    if ((spell_info->TargetType == Zeal::GameEnums::SpellTargetType::Target ||
         spell_info->TargetType == Zeal::GameEnums::SpellTargetType::TargetedAE) &&
        !Zeal::Game::get_target()) {
      Zeal::Game::print_chat(USERCOLOR_SPELL_FAILURE, "You must first select a target for spell %i", next_slot + 1);
      attempt_counter++;
      return;
    }
  }

  if (Zeal::Game::GameInternal::IsPlayerABardAndSingingASong()) {
    quietly_end_bard_song();
  } else {
    stop_active_cast();
  }

  if (player_data->cast(next_slot, spell_id, 0, -1)) {
    active_cast_id = spell_id;
  } else {
    attempt_counter++;
  }
  cast_start_time = now;
}

bool Melody::is_slot_ready(int slot) {
  bool invalid = (slot < 0 || slot >= GAME_NUM_SPELL_GEMS);
  auto self = Zeal::Game::get_self();
  auto actor = self ? self->ActorInfo : nullptr;
  auto char_info = Zeal::Game::get_char_info();
  auto display = Zeal::Game::get_display();

  if (invalid || !self || !actor || !char_info || !display) return true;

  int game_time = display->GameTimeMs;
  int spell_id = char_info->MemorizedSpell[slot];

  if (spell_id != kInvalidSpellId && actor->RecastTimeout[slot] > game_time) {
    return false;
  }
  return true;
}

int Melody::find_next_song() {
  auto char_info = Zeal::Game::get_char_info();

  if (char_info && retry_cast_id != kInvalidSpellId) {
    int id = retry_cast_id;
    retry_cast_id = kInvalidSpellId;
    for (auto slot : playlist) {
      if (char_info->MemorizedSpell[slot] == id) return slot;
    }
  }

  if (char_info && pending_cast_id != kInvalidSpellId) {
    for (auto slot : playlist) {
      if (char_info->MemorizedSpell[slot] == pending_cast_id && is_slot_ready(slot)) {
        return slot;
      }
    }
  }

  current_song_index++;
  if (current_song_index >= (int)playlist.size() || current_song_index < 0) {
    current_song_index = 0;
  }

  int slot = playlist[current_song_index];
  if (is_slot_ready(slot)) return slot;

  if (pending_cast_id == kInvalidSpellId) {
    pending_cast_id = char_info ? char_info->MemorizedSpell[slot] : kInvalidSpellId;
  }
  return -1;
}

void Melody::handle_deactivate_ui() {
  zone_entry_time = 0;
  if (!is_running || !Zeal::Game::GameInternal::IsPlayerABardAndSingingASong()) return;

  handle_stop_cast_callback(3, Zeal::Game::get_self()->ActorInfo->CastingSpellId);
}

bool Melody::handle_opcode(int opcode) {
  if (item_state == IdleState) return false;

  const int OP_BeginCast = 0x40a9;
  const int OP_ManaChange = 0x417f;
  const int OP_MemorizeSpell = 0x4182;

  if (opcode == OP_ManaChange || opcode == OP_MemorizeSpell) {
    item_state = IdleState;
  } else if (opcode == OP_BeginCast && item_state == CastRequestedState) {
    item_state = CastStartedState;
  }
  return false;
}

Melody::Melody(ZealService* zeal) {
  if (!Zeal::Game::is_new_ui()) return;

  zeal->callbacks->AddGeneric([this]() { tick(); });
  zeal->callbacks->AddGeneric([this]() { end(); }, callback_type::CharacterSelect);
  zeal->callbacks->AddGeneric([this]() { handle_deactivate_ui(); }, callback_type::DeactivateUI);
  zeal->callbacks->AddGeneric([this]() { zone_entry_time = GetTickCount64(); }, callback_type::EnterZone);
  zeal->callbacks->AddPacket([this](UINT opcode, char* buffer, UINT len) { return handle_opcode(opcode); },
                             callback_type::WorldMessage);
  zeal->hooks->Add("StopCast", 0x4cb510, StopCast, hook_type_detour);

  zeal->commands_hook->Add(
      "/melody", {"/mel"}, "Bard only, auto cycles 5 songs of your choice.", [this](std::vector<std::string>& args) {
        if (args.size() > 1 && args[1] == "resume") {
          resume();
          return true;
        }
        end(true);
        if (!Zeal::Game::get_char_info() || 
            Zeal::Game::get_char_info()->Class != Zeal::GameEnums::ClassTypes::Bard) {
          Zeal::Game::print_chat(USERCOLOR_SPELL_FAILURE, "Only bards can keep a melody.");
          return true;
        }
        if (args.size() > 6) {
          Zeal::Game::print_chat(USERCOLOR_SPELL_FAILURE, "A melody can only consist of up to 5 songs.");
          return true;
        }
        std::vector<int> new_songs;
        for (size_t i = 1; i < args.size(); i++) {
          int slot = -1;
          if (Zeal::String::tryParse(args[i], &slot)) {
            new_songs.push_back(slot - 1);
          } else {
            Zeal::Game::print_chat(USERCOLOR_SPELL_FAILURE, "Melody parsing error: Usage example: /melody 1 2 3 4");
            return true;
          }
        }
        start(new_songs);
        return true;
      });

  zeal->commands_hook->Add(
      "/stopsong", {}, "Stops the current bard song from casting", [this](std::vector<std::string>& args) {
        if (Zeal::Game::GameInternal::IsPlayerABardAndSingingASong())
          return false;
        return true;
      });
}

