// Initialize LLaMA backend and context within a separate thread, then clean up resources properly
int main(int argc, char ** argv) {
    auto * model_path = get_model_or_exit(argc, argv);

    std::thread worker_thread([&model_path]() {
        // Initialize the backend for this thread
        llama_backend_init();

        // Load the model from file
        auto * model = llama_model_load_from_file(model_path, llama_model_default_params());

        // Create a new context based on the loaded model
        auto * ctx = llama_init_from_model(model, llama_context_default_params());

        // Clean up resources in reverse order of creation
        llama_free(ctx);
        llama_model_free(model);
        llama_backend_free();
    });

    // Wait for the worker thread to complete before exiting
    worker_thread.join();

    return 0;
}

