#include <iostream>
using namespace std;

// Definition for singly-linked list node
struct Node {
    int data;
    Node* link;
    Node(int x) : data(x), link(nullptr) {}
};

class DetectCycle {
public:
    Node* findStartOfLoop(Node* start) {
        Node* runner = start;      // moves two steps at a time
        Node* walker = start;      // moves one step at a time
        bool loopDetected = false;

        // Phase 1: Detect if there's a cycle using Floyd's algorithm
        while (runner != nullptr && runner->link != nullptr) {
            runner = runner->link->link;
            walker = walker->link;

            if (runner == walker) {
                loopDetected = true;
                break;
            }
        }

        // If no cycle found, return null
        if (!loopDetected) {
            return nullptr;
        }

        // Phase 2: Find the starting node of the cycle
        walker = start;
        while (walker != runner) {
            runner = runner->link;
            walker = walker->link;
        }

        return walker;  // or runner, since they're equal here
    }
};

int main() {
    // Build a linked list with a cycle: 3 -> 2 -> 0 -> -4 -> 2 (cycle back to second node)
    Node* head = new Node(3);
    Node* node2 = new Node(2);
    Node* node3 = new Node(0);
    Node* node4 = new Node(-4);

    head->link = node2;
    node2->link = node3;
    node3->link = node4;
    node4->link = node2;  // creates the cycle

    DetectCycle dc;
    Node* cycleStart = dc.findStartOfLoop(head);

    if (cycleStart != nullptr) {
        cout << "The cycle begins at node with value: " << cycleStart->data << endl;
    } else {
        cout << "No cycle detected in the linked list." << endl;
    }

    // Note: Memory cleanup is omitted due to the cyclic structure.
    // In production code, you'd need special handling to avoid infinite loops during deletion.

    return 0;
}

