namespace rocjpeg {

namespace detail {

// Internal API table accessor
auto&
get_api_table_ptr()
{
    static std::atomic<rocjpegApiFuncTable*> s_table{ nullptr };
    return s_table;
}

// Helper: copy and initialize API tables safely
void
setup_profiling_tables(rocjpegApiFuncTable& out_const,
                       rocjpegApiFuncTable& out_mutable)
{
    initialize_rocjpeg_api_table(&out_const);
    copy_rocjpeg_api_table(&out_mutable, &out_const);
}

// Registration implementation — performs actual registration with profiler
void
perform_registration()
{
    static rocjpegApiFuncTable const_api{};
    static rocjpegApiFuncTable mutable_api{};

    setup_profiling_tables(const_api, mutable_api);

    // Atomically publish const table first
    auto* expected = nullptr;
    if (!get_api_table_ptr().compare_exchange_strong(expected, &const_api)) {
        // Should never happen in correct usage
        std::cerr << "[rocjpeg] Unexpected concurrent access during init.\n";
        abort();
    }

    void* mutable_ptr = &mutable_api;
    rocprofiler_register_library_indentifier_t lib_id{};

    auto status = rocprofiler_register_library_api_table(
        "rocjpeg",
        &ROCPROFILER_REGISTER_IMPORT_FUNC(rocjpeg),
        ROCP_REG_VERSION,
        &mutable_ptr,
        1,
        &lib_id
    );

    if (status == 0) {
        printf("[%s] rocjpeg registered as library %lu\n", ROCP_REG_FILE_NAME, lib_id.handle);

        // Attempt to atomically swap in mutable table
        if (!get_api_table_ptr().compare_exchange_strong(expected, &mutable_api)) {
            std::cerr << "[rocjpeg] Failed to install mutable API table.\n";
            abort();
        }
    } else if (status != ROCP_REG_NO_TOOLS) {
        std::cerr << "[rocjpeg] Registration failed: "
                  << rocprofiler_register_error_string(status) << "\n";
        std::exit(EXIT_FAILURE);
    }
}

// Thread-safe lazy registration guard
void
ensure_registered()
{
    static bool s_flag = false;
    static std::mutex s_mutex{};
    static std::once_flag s_once{};

    if (!s_flag) {
        std::lock_guard<std::mutex> lock{s_mutex};
        if (!s_flag) {
            std::call_once(s_once, perform_registration);
            s_flag = true;
        }
    }
}

} // namespace detail

// Public API: retrieve current API table after ensuring registration
rocjpegApiFuncTable*
get_rocjpeg_api_table()
{
    detail::ensure_registered();
    return detail::get_api_table_ptr().load(std::memory_order_relaxed);
}

