#include <iostream>
#include <vector>
#include <algorithm>
#include <cstdlib>

// Simulated structure for BDD manager
struct DdManager {
    int size;
    int keys;
    int isolated;
    std::vector<int> perm;
    std::vector<std::vector<int>> subtables;
    std::vector<int> invperm;

    DdManager(int n) : size(n), keys(0), isolated(0), 
                       perm(n), invperm(n), 
                       subtables(n) {
        for (int i = 0; i < n; ++i) {
            perm[i] = i;
            invperm[i] = i;
            subtables[i].resize(1, i); // Simplified representation
        }
    }
};

// Move structure for tracking swaps
struct Move {
    int x;
    int y;
    int size;
    Move* next;

    Move(int x_val, int y_val, int sz) 
        : x(x_val), y(y_val), size(sz), next(nullptr) {}
};

// Global counters
int ddTotalNumberSwapping = 0;

// Helper function to check symmetry between two variables
bool checkVariableSymmetry(DdManager& table, int varX, int varY) {
    // Check if variables have identical structure in their subtables
    const auto& subX = table.subtables[varX];
    const auto& subY = table.subtables[varY];

    // If either variable has only one node, it's likely a projection function
    if (subX.size() <= 1 || subY.size() <= 1) {
        return false;
    }

    // Simple symmetry check: compare subtable patterns
    bool symmetric = true;
    for (size_t i = 0; i < std::min(subX.size(), subY.size()); ++i) {
        if (subX[i] != subY[i]) {
            symmetric = false;
            break;
        }
    }

    return symmetric;
}

// Find the bottom of a symmetry group
int findGroupBottom(DdManager& table, int varIndex) {
    int current = varIndex;
    while (current < static_cast<int>(table.subtables.size()) && 
           table.subtables[current][0] != current) {
        current = table.subtables[current][0];
    }
    return current;
}

// Find the top of a symmetry group
int findGroupTop(DdManager& table, int varIndex) {
    int current = varIndex;
    while (current > 0 && table.subtables[current][0] < current) {
        current = table.subtables[current][0];
    }
    return current;
}

// Merge two symmetry groups
void mergeSymmetryGroups(DdManager& table, int top1, int bottom2) {
    if (bottom2 >= 0 && bottom2 < static_cast<int>(table.subtables.size())) {
        table.subtables[bottom2][0] = top1;
    }
}

// Move variable upward through the BDD
std::vector<Move*> moveVariableUp(DdManager& table, int startVar, int limitVar) {
    std::vector<Move*> moves;
    int currentPos = startVar;

    while (currentPos > limitVar) {
        int prevPos = currentPos - 1;

        // Check for symmetry before swapping
        if (checkVariableSymmetry(table, prevPos, currentPos)) {
            // Merge symmetry groups
            int topPrev = findGroupTop(table, prevPos);
            int bottomCurrent = findGroupBottom(table, currentPos);
            mergeSymmetryGroups(table, topPrev, bottomCurrent);

            // Record the move
            Move* newMove = new Move(prevPos, currentPos, table.keys);
            moves.push_back(newMove);

            currentPos = prevPos;
        } else {
            // Perform standard swap
            // Simulate swap operation
            std::swap(table.perm[currentPos], table.perm[prevPos]);
            std::swap(table.invperm[table.perm[currentPos]], 
                     table.invperm[table.perm[prevPos]]);

            // Update subtables
            for (int i = 0; i < static_cast<int>(table.subtables.size()); ++i) {
                if (!table.subtables[i].empty()) {
                    table.subtables[i][0] = i; // Reset self-reference
                }
            }

            // Record the move
            Move* newMove = new Move(prevPos, currentPos, table.keys);
            moves.push_back(newMove);

            currentPos = prevPos;
        }
    }

    return moves;
}

// Move variable downward through the BDD
std::vector<Move*> moveVariableDown(DdManager& table, int startVar, int limitVar) {
    std::vector<Move*> moves;
    int currentPos = startVar;

    while (currentPos < limitVar) {
        int nextPos = currentPos + 1;

        // Check for symmetry before swapping
        if (checkVariableSymmetry(table, currentPos, nextPos)) {
            // Merge symmetry groups
            int topCurrent = findGroupTop(table, currentPos);
            int bottomNext = findGroupBottom(table, nextPos);
            mergeSymmetryGroups(table, topCurrent, bottomNext);

            // Record the move
            Move* newMove = new Move(currentPos, nextPos, table.keys);
            moves.push_back(newMove);

            currentPos = nextPos;
        } else {
            // Perform standard swap
            std::swap(table.perm[currentPos], table.perm[nextPos]);
            std::swap(table.invperm[table.perm[currentPos]], 
                     table.invperm[table.perm[nextPos]]);

            // Update subtables
            for (int i = 0; i < static_cast<int>(table.subtables.size()); ++i) {
                if (!table.subtables[i].empty()) {
                    table.subtables[i][0] = i; // Reset self-reference
                }
            }

            // Record the move
            Move* newMove = new Move(currentPos, nextPos, table.keys);
            moves.push_back(newMove);

            currentPos = nextPos;
        }
    }

    return moves;
}

// Main symmetric sifting algorithm
int performSymmetricSifting(DdManager& table, int lowerBound, int upperBound) {
    int totalVariables = table.size;
    std::vector<int> variableOrder(totalVariables);

    // Initialize variable order based on subtable sizes
    for (int i = 0; i < totalVariables; ++i) {
        variableOrder[i] = i;
    }

    // Sort variables by subtable size (descending)
    std::sort(variableOrder.begin(), variableOrder.end(),
              [&](int a, int b) {
                  return table.subtables[a].size() > table.subtables[b].size();
              });

    // Initialize symmetry groups
    for (int i = lowerBound; i <= upperBound; ++i) {
        if (!table.subtables[i].empty()) {
            table.subtables[i][0] = i; // Each variable starts as its own group
        }
    }

    int bestSize = table.keys;

    // Process each variable according to sorted order
    for (int varIndex : variableOrder) {
        if (varIndex < lowerBound || varIndex > upperBound) continue;

        // Skip if already part of a symmetry group
        if (!table.subtables[varIndex].empty() && 
            table.subtables[varIndex][0] != varIndex) {
            continue;
        }

        // Try moving the variable up
        auto upMoves = moveVariableUp(table, varIndex, lowerBound);

        // Try moving the variable down
        auto downMoves = moveVariableDown(table, varIndex, upperBound);

        // Calculate final size after movements
        int finalSize = table.keys;

        // If we found a better configuration, keep it
        if (finalSize < bestSize) {
            bestSize = finalSize;
        }

        // Clean up move records
        for (auto move : upMoves) delete move;
        for (auto move : downMoves) delete move;
    }

    return bestSize;
}

// Symmetric sifting to convergence
int performConvergentSymmetricSifting(DdManager& table, int lowerBound, int upperBound) {
    int initialSize = table.keys;
    int currentSize = initialSize;
    int iterationCount = 0;
    const int maxIterations = 10; // Prevent infinite loops

    while (iterationCount < maxIterations) {
        int previousSize = currentSize;

        // Perform one round of symmetric sifting
        currentSize = performSymmetricSifting(table, lowerBound, upperBound);

        // Check for convergence
        if (currentSize >= previousSize) {
            break;
        }

        iterationCount++;
    }

    return currentSize;
}

// Print symmetry profile
void printSymmetryProfile(DdManager& table, int lowerBound, int upperBound) {
    std::cout << "Symmetry Profile:" << std::endl;

    int totalSymmetricVars = 0;
    int totalSymmetricGroups = 0;

    for (int i = lowerBound; i <= upperBound; ++i) {
        if (!table.subtables[i].empty() && table.subtables[i][0] != i) {
            std::cout << "Group starting at " << i << ": ";

            int current = i;
            do {
                std::cout << current << " ";
                totalSymmetricVars++;

                if (!table.subtables[current].empty()) {
                    current = table.subtables[current][0];
                }
            } while (current != i);

            totalSymmetricGroups++;
            std::cout << std::endl;
        }
    }

    std::cout << "Total symmetric variables: " << totalSymmetricVars << std::endl;
    std::cout << "Total symmetric groups: " << totalSymmetricGroups << std::endl;
}

