// Bit-field management utility for GOFF record flags
class BitField {
  uint8_t Storage;

  static constexpr uint8_t computeMask(uint8_t startBit, uint8_t width) {
    return ((1U << width) - 1U) << (8U - startBit - width);
  }

  static constexpr uint8_t applyBits(uint8_t startBit, uint8_t width,
                                     uint8_t newValue, uint8_t oldValue) {
    assert(startBit < 8 && "Start bit must be less than 8");
    assert(startBit + width <= 8 && "Bit field exceeds byte boundary");

    const uint8_t mask = computeMask(startBit, width);
    const uint8_t shiftedValue = (newValue & ((1U << width) - 1U)) 
                                 << (8U - startBit - width);
    return (oldValue & ~mask) | shiftedValue;
  }

public:
  constexpr BitField() : Storage(0) {}

  constexpr BitField(uint8_t start, uint8_t len, uint8_t val)
      : Storage(applyBits(start, len, val, 0)) {}

  void update(uint8_t start, uint8_t len, uint8_t val) {
    Storage = applyBits(start, len, val, Storage);
  }

  constexpr operator uint8_t() const { return Storage; }
};

// Predefined flag constants
constexpr uint8_t RecordContinued = BitField(7, 1, 1);
constexpr uint8_t IsContinuation = BitField(6, 1, 1);

// Stream class to manage writing of GOFF physical records
class GOFFOutputHandler : public raw_ostream {
  raw_pwrite_stream &UnderlyingStream;
  size_t BytesRemainingInRecord;
#ifndef NDEBUG
  size_t PaddingSize = 0;
#endif
  uint32_t TotalLogicalRecords;
  GOFF::RecordType ActiveRecordType;
  bool NewRecordStarted;
  char InternalBuffer[GOFF::RecordContentLength];

  size_t bytesLeftInCurrentPhysicalRecord() const {
    size_t remainder = BytesRemainingInRecord % GOFF::RecordContentLength;
    return remainder ? remainder : GOFF::RecordContentLength;
  }

  static void emitRecordHeader(raw_ostream &OS, GOFF::RecordType type,
                               size_t remainingBytes, uint8_t flags) {
    uint8_t combined = flags | (static_cast<uint8_t>(type) << 4);
    if (remainingBytes > GOFF::RecordLength)
      combined |= RecordContinued;
    OS << static_cast<unsigned char>(GOFF::PTVPrefix)
       << static_cast<unsigned char>(combined)
       << static_cast<unsigned char>(0); // Version
  }

  void padCurrentRecord() {
    size_t needed = BytesRemainingInRecord - GetNumBytesInBuffer();
    if (needed > 0) {
      assert(needed == PaddingSize && "Incorrect padding calculation");
      assert(needed < GOFF::RecordLength && "Too much padding requested");
      write_zeros(needed);
    }
    flush();
    assert(BytesRemainingInRecord == 0 && "Incomplete record flush");
    assert(GetNumBytesInBuffer() == 0 && "Buffer not cleared after flush");
  }

  void write_data(const char *data, size_t length) override {
    assert(length <= BytesRemainingInRecord && "Write exceeds record capacity");
    assert(BytesRemainingInRecord > 0 && "No space left in logical record");

    if (BytesRemainingInRecord % GOFF::RecordContentLength == 0) {
      emitRecordHeader(UnderlyingStream, ActiveRecordType,
                       BytesRemainingInRecord,
                       NewRecordStarted ? 0 : IsContinuation);
      NewRecordStarted = false;
    }

    size_t index = 0;
    while (length > 0) {
      size_t chunkSize = bytesLeftInCurrentPhysicalRecord();
      if (chunkSize > length)
        chunkSize = length;

      UnderlyingStream.write(data + index, chunkSize);
      index += chunkSize;
      length -= chunkSize;
      BytesRemainingInRecord -= chunkSize;

      if (length > 0)
        emitRecordHeader(UnderlyingStream, ActiveRecordType,
                         BytesRemainingInRecord);
    }
  }

  uint64_t get_position() const override { return UnderlyingStream.tell(); }

public:
  explicit GOFFOutputHandler(raw_pwrite_stream &stream)
      : UnderlyingStream(stream), BytesRemainingInRecord(0),
        TotalLogicalRecords(0), NewRecordStarted(false) {
    SetBuffer(InternalBuffer, sizeof(InternalBuffer));
  }

  ~GOFFOutputHandler() { finalize(); }

  raw_pwrite_stream &get_underlying_stream() { return UnderlyingStream; }

  void begin_new_record(GOFF::RecordType type, size_t contentSize) {
    padCurrentRecord();
    ActiveRecordType = type;
    BytesRemainingInRecord = contentSize;

#ifdef NDEBUG
    size_t tempPadding;
#else
    size_t &tempPadding = PaddingSize;
#endif

    tempPadding = contentSize % GOFF::RecordContentLength;
    if (tempPadding != 0) {
      tempPadding = GOFF::RecordContentLength - tempPadding;
      BytesRemainingInRecord += tempPadding;
    }

    NewRecordStarted = true;
    ++TotalLogicalRecords;
  }

  void finalize() { padCurrentRecord(); }

  uint32_t get_logical_record_count() const { return TotalLogicalRecords; }

  template<typename T>
  void write_big_endian(T value) {
    value = support::endian::byte_swap<T>(value, endianness::big);
    write(reinterpret_cast<const char *>(&value), sizeof(T));
  }
};

// Main writer class implementing MCObjectWriter interface
class GOFFObjectWriterImpl : public MCObjectWriter {
  std::unique_ptr<MCGOFFObjectTargetWriter> TargetWriter;
  GOFFOutputHandler Output;

public:
  GOFFObjectWriterImpl(std::unique_ptr<MCGOFFObjectTargetWriter> targetWriter,
                       raw_pwrite_stream &stream)
      : TargetWriter(std::move(targetWriter)), Output(stream) {}

  ~GOFFObjectWriterImpl() override {}

  void write_header() {
    Output.begin_new_record(GOFF::RT_HDR, /*Size=*/57);
    Output.write_zeros(1);       // Reserved
    Output.write_big_endian<uint32_t>(0); // Target Hardware Environment
    Output.write_big_endian<uint32_t>(0); // Target Operating System Environment
    Output.write_zeros(2);       // Reserved
    Output.write_big_endian<uint16_t>(0); // CCSID
    Output.write_zeros(16);      // Character Set name
    Output.write_zeros(16);      // Language Product Identifier
    Output.write_big_endian<uint32_t>(1); // Architecture Level
    Output.write_big_endian<uint16_t>(0); // Module Properties Length
    Output.write_zeros(6);       // Reserved
  }

  void write_terminator() {
    uint8_t flags = GOFF::END_EPR_None;
    uint8_t addressMode = 0;
    uint32_t esdId = 0;
    // TODO: Populate entry point information

    Output.begin_new_record(GOFF::RT_END, /*Size=*/13);
    Output.write_big_endian<uint8_t>(BitField(6, 2, flags)); // Indicator flags
    Output.write_big_endian<uint8_t>(addressMode);           // AMODE
    Output.write_zeros(3);                                   // Reserved
    Output.write_big_endian<uint32_t>(0);                    // Record Count
    Output.write_big_endian<uint32_t>(esdId);                // ESDID
    Output.finalize();
  }

  void recordRelocation(MCAssembler &, const MCAsmLayout &,
                        const MCFragment *, const MCFixup &, MCValue,
                        uint64_t &) override {}

  void executePostLayoutBinding(MCAssembler &, const MCAsmLayout &) override {}

  uint64_t write_object(MCAssembler &assembler, const MCAsmLayout &layout) override {
    uint64_t initialPosition = Output.tell();
    write_header();
    write_terminator();
    LLVM_DEBUG(dbgs() << "Wrote " << Output.get_logical_record_count()
                      << " logical records.\n");
    return Output.tell() - initialPosition;
  }
};

} // end anonymous namespace

std::unique_ptr<MCObjectWriter>
llvm::createGOFFObjectWriter(std::unique_ptr<MCGOFFObjectTargetWriter> motw,
                             raw_pwrite_stream &os) {
  return std::make_unique<GOFFObjectWriterImpl>(std::move(motw), os);
}

