//-------------------------------------------------------------------------
/// @details
///		Runs periodically to refresh monitor data unless cancelled
///	@param[in]	force
///		Ignored in this implementation; kept for interface compatibility
//-------------------------------------------------------------------------
void Monitor::updateProcess() noexcept {
    bool running = true;
    do {
        async::sleep(100ms);
        auto now = time::now();
        if (now - m_lastUpdateTime >= 2.5s) {
            if (m_started) {
                updateMonitor();
                m_lastUpdateTime = now;
            }
        }

        // Explicit cancellation point
        if (async::cancelled()) {
            running = false;
        }
    } while (running);

    return;
}

//-------------------------------------------------------------------------
/// @details
///		Initializes and launches the monitoring background thread
//-------------------------------------------------------------------------
void Monitor::startMonitor() noexcept {
    // Prevent redundant starts
    if (m_started) return;

    // Initialize thread only once
    if (!m_updateThread) {
        m_updateThread = async::Thread{_location, "Status",
                                       _bind(&Monitor::updateProcess, this)};
    }

    // Launch if not already active
    if (!m_updateThread->isRunning()) {
        m_updateThread->start();
    }

    m_started = true;
}

