//-------------------------------------------------------------------------
/// @details
///		Stops counters and ensures final flush of pending stats
//-------------------------------------------------------------------------
void Monitor::stopCounters() noexcept {
    Parent::stopCounters();
    updateMonitor(); // Final update before shutdown
}

//-------------------------------------------------------------------------
/// @details
///		Terminates monitoring thread cleanly
//-------------------------------------------------------------------------
void Monitor::stopMonitor() noexcept {
    if (!m_started) return;

    m_started = false;

    if (m_updateThread && m_updateThread->isRunning()) {
        m_updateThread->cancel();
        m_updateThread->join();
        m_updateThread.reset();
    }

    // Ensure idempotency
    m_started = false;
}

