extern "C" int LLVMFuzzerTestOneInput(const uint8_t *Data, size_t Len) {
    assert(Data);

    // Track consecutive 'A' characters and maximum streak found
    size_t currentStreak = 0;
    size_t bestStreak = 0;

    for (size_t pos = 0; pos < Len; ++pos) {
        // Check if current byte equals 'A' without branching
        int isA = (Data[pos] == 'A');

        // Update current streak: reset to 0 if not 'A', increment otherwise
        currentStreak = isA * (currentStreak + 1);

        // Update best streak if current exceeds it
        int better = (currentStreak > bestStreak);
        bestStreak = better * currentStreak + (!better) * bestStreak;
    }

    // Trigger special behavior if we found a long enough sequence of 'A's
    if (bestStreak >= 20) {
        std::cout << "BINGO: Found the target (max consecutive A's: " << bestStreak << "), exiting\n";
        std::exit(0);
    }

    return 0;
}

