PyPangoIO::PyPangoIO(std::queue<InterpreterLine>& input_queue, InterpreterLineType line_kind)
    : input_queue(input_queue), line_kind(line_kind)
{
}
void PyPangoIO::write(const std::string& content)
{
    pending += content;
    size_t pos = pending.find('\n');
    while(pos != std::string::npos) {
        const std::string segment = pending.substr(0, pos);
        input_queue.push(InterpreterLine(segment, line_kind));
        pending = pending.substr(pos + 1);
        pos = pending.find('\n');
    }
}
void PyPangoIO::flush()
{
    // Intentionally left empty
}
void register_pango_writer(pybind11::module& module)
{
    pybind11::class_<PyPangoIO>(module, "PyPangoIO")
      .def("write", &PyPangoIO::write)
      .def("flush", &PyPangoIO::flush);
}
