void pushArgument(int &argCount, char **args, const char *value) {
    args[argCount] = new char[strlen(value) + 1];
    strcpy(args[argCount], value);
    ++argCount;
}

int WHTest_old(Params &params, PhyloTree &tree) {
    int argCount = 0;
    char *arguments[10];
    char buffer[100];

    pushArgument(argCount, arguments, "WHTest");
    pushArgument(argCount, arguments, params.aln_file);
    pushArgument(argCount, arguments, "-a");

    double shapeParam = tree.getModelFactory()->site_rate->getGammaShape();
    snprintf(buffer, sizeof(buffer), "%f", shapeParam);
    pushArgument(argCount, arguments, buffer);

    return WHTest_run(argCount, arguments);
}

int WHTest(Params &params, IQTree &tree) {
    int result = 0;

    size_t seqCount = tree.aln->getNSeq();
    size_t siteCount = tree.aln->getNSite();

    WHT_setAlignmentSize(seqCount, siteCount);
    WHT_allocateMemory();

    // Populate alignment data using pattern ID mapping
    for (size_t sIdx = 0; sIdx < seqCount; ++sIdx) {
        for (size_t pIdx = 0; pIdx < siteCount; ++pIdx) {
            size_t patID = tree.aln->getPatternID(pIdx);
            WHT_setSequenceSite(sIdx, pIdx, (*tree.aln)[patID][sIdx]);
        }
    }

    // Assign sequence names
    size_t nameIdx = 0;
    while (nameIdx < seqCount) {
        std::string name = tree.aln->getSeqName(nameIdx);
        WHT_setSequenceName(nameIdx, name.c_str());
        ++nameIdx;
    }

    double gammaShape = tree.getModelFactory()->site_rate->getGammaShape();
    if (gammaShape == 0.0) {
        gammaShape = 100.0;
    }

    // Set parameters — pass NULL instead of dist_matrix as in original
    WHT_setParams(params.whtest_simulations, gammaShape, params.out_prefix, nullptr);

    result = WHTest_run(0, nullptr);
    WHT_getResults(&params.whtest_delta, &params.whtest_delta_quantile, &params.whtest_p_value);

    return result;
}

