LoadingSpinner::LoadingSpinner(QWidget* parent)
    : QLabel(parent)
    , m_rotation(0)
{
    setFixedSize(60, 60);
    setScaledContents(true);
    setAlignment(Qt::AlignCenter);

    m_animationTimer = new QTimer(this);
    connect(m_animationTimer, &QTimer::timeout, this, &LoadingSpinner::spin);
}

void LoadingSpinner::begin() {
    m_animationTimer->start(50);
    show();
}

void LoadingSpinner::end() {
    m_animationTimer->stop();
    hide();
}

void LoadingSpinner::spin() {
    m_rotation = (m_rotation + 30) % 360;
    update();
}

void LoadingSpinner::paintEvent(QPaintEvent* event) {
    Q_UNUSED(event);

    QPainter painter(this);
    painter.setRenderHint(QPainter::Antialiasing);

    // Material Design 3 circular progress indicator
    QPen pen(Colors::toQColor(Colors::PRIMARY), 3);
    pen.setCapStyle(Qt::RoundCap);
    painter.setPen(pen);

    QRect arcRect(10, 10, 40, 40);
    int initialAngle = -m_rotation * 16;
    int sweepAngle = 270 * 16;
    painter.drawArc(arcRect, initialAngle, sweepAngle);
}

