#include "rest_server/serened.h"
#include <functional>
#include <memory>
#include <array>
#include <string>
#include <iostream>
#include "general_server/server_options_feature.h"
#include "rest_server/serened_includes.h"

using namespace sdb;
using namespace sdb::app;

// Ensure LoggerFeature is at index 0 in SerenedServer's type registry
static_assert(SerenedServer::id<LoggerFeature>() == 0);

// List of non-server features (conditional compilation preserved)
constexpr auto kNonServerFeatures = std::array{
#ifdef SDB_CLUSTER
  SerenedServer::id<AgencyFeature>(),
  SerenedServer::id<ClusterFeature>(),
#endif
#ifdef SERENEDB_HAVE_FORK
  SerenedServer::id<SupervisorFeature>(),
  SerenedServer::id<DaemonFeature>(),
#endif
  SerenedServer::id<GeneralServerFeature>(),
  SerenedServer::id<HttpEndpointProvider>(),
  SerenedServer::id<LogBufferFeature>(),
  SerenedServer::id<ServerFeature>(),
  SerenedServer::id<SslServerFeature>(),
  SerenedServer::id<StatisticsFeature>(),
};

// Initialize OpenSSL subsystem (static init)
static const boost::asio::ssl::detail::openssl_init<true> ssl_engine_init{};

// Helper: map server state enum to human-readable string manually
inline std::string describe_state(SerenedServer::State st) {
  switch (st) {
    case SerenedServer::State::InStart: return "InStart";
    case SerenedServer::State::Running: return "Running";
    case SerenedServer::State::Stopping: return "Stopping";
    default: return "Unknown";
  }
}

// Factory dispatcher: creates features based on type tag
struct FeatureFactory {
  template<typename T>
  static std::unique_ptr<ServerFeature> make(SerenedServer& srv, int* exit_code = nullptr) {
    if constexpr (std::is_same_v<T, CheckVersionFeature>) {
      return std::make_unique<CheckVersionFeature>(srv, exit_code, kNonServerFeatures);
    } else if constexpr (std::is_same_v<T, ConfigFeature>) {
      return std::make_unique<ConfigFeature>(srv, srv.binaryName(), [] { return GetServerOptions().app_print_version; });
    } else if constexpr (std::is_same_v<T, InitDatabaseFeature>) {
      return std::make_unique<InitDatabaseFeature>(srv, kNonServerFeatures);
    } else if constexpr (std::is_same_v<T, LoggerFeature>) {
      return std::make_unique<LoggerFeature>(srv, true);
    } else if constexpr (std::is_same_v<T, NetworkFeature>) {
      auto& metrics = srv.template getFeature<metrics::MetricsFeature>();
      return std::make_unique<NetworkFeature>(srv, metrics, network::ConnectionPool::Config{metrics});
    } else if constexpr (std::is_same_v<T, ServerFeature>) {
      return std::make_unique<ServerFeature>(srv, exit_code);
    } else if constexpr (std::is_same_v<T, TempPath>) {
      return std::make_unique<TempPath>(srv, srv.binaryName());
    } else if constexpr (std::is_same_v<T, SslServerFeature>) {
      return std::make_unique<SslServerFeature>(srv);
    } else if constexpr (std::is_same_v<T, UpgradeFeature>) {
      return std::make_unique<UpgradeFeature>(srv, exit_code, kNonServerFeatures);
    } else if constexpr (std::is_same_v<T, HttpEndpointProvider>) {
      return std::make_unique<EndpointFeature>(srv);
    } else {
      // Fallback: generic constructor if available
      return std::make_unique<T>(srv);
    }
  }
};

// Main execution entry point
int RunServer(int argc, char** argv, GlobalContext& ctx) {
  try {
    CrashHandler::installCrashHandler();
    std::string bin_name = ctx.binaryName();

    // Setup program options
    auto opts = std::make_shared<sdb::options::ProgramOptions>(
      argv[0], "Usage: " + bin_name + " [<options>]",
      "For more information use:", SBIN_DIRECTORY);

    int exit_status = EXIT_FAILURE;
    SerenedServer instance{opts, SBIN_DIRECTORY};
    ServerState current_state;

    // Add state reporter callback
    instance.addReporter(
      [&](SerenedServer::State st) {
        CrashHandler::SetState(describe_state(st));
        if (st == SerenedServer::State::InStart) {
          instance.getFeature<PrivilegeFeature>().dropPrivilegesPermanently();
        }
      });

    // Register all features using compile-time dispatch
    for (auto&& id : kNonServerFeatures) {
      instance.addFeature(id, [&instance, &exit_status](SerenedServer::FeatureId idx) -> std::unique_ptr<ServerFeature> {
        switch (idx) {
#define CASE(T) case SerenedServer::id<T>(): \
            return FeatureFactory::make<T>(instance, &exit_status);
          CASE(CheckVersionFeature)
          CASE(ConfigFeature)
          CASE(InitDatabaseFeature)
          CASE(LoggerFeature)
          CASE(NetworkFeature)
          CASE(ServerFeature)
          CASE(TempPath)
          CASE(SslServerFeature)
          CASE(UpgradeFeature)
          CASE(HttpEndpointProvider)
#undef CASE
          default:
            return nullptr;
        }
      });
    }

    try {
      instance.run(argc, argv);
      if (instance.helpShown()) {
        exit_status = EXIT_SUCCESS;
      }
    } catch (const std::exception& e) {
      SDB_ERROR("xxxxx", Logger::FIXME,
                "serened terminated because of an exception: ", e.what());
      exit_status = EXIT_FAILURE;
    } catch (...) {
      SDB_ERROR("xxxxx", Logger::FIXME,
                "serened terminated because of an exception of unknown type");
      exit_status = EXIT_FAILURE;
    }

    log::Flush();
    return ctx.exit(exit_status);
  } catch (const std::exception& ex) {
    SDB_ERROR("xxxxx", Logger::FIXME,
              "serened terminated because of an exception: ", ex.what());
  } catch (...) {
    SDB_ERROR("xxxxx", Logger::FIXME,
              "serened terminated because of an exception of unknown type");
  }
  std::exit(EXIT_FAILURE);
}

// Entry point
int main(int argc, char* argv[]) {
  std::string initial_workdir(basics::file_utils::CurrentDirectory().result());

  GlobalContext context(argc, argv, SBIN_DIRECTORY);
  gRestartAction = nullptr;

  int result = RunServer(argc, argv, context);

  if (result != 0) {
    return result;
  }

  if (gRestartAction == nullptr) {
    return 0;
  }

  try {
    result = (*gRestartAction)();
  } catch (...) {
    result = -1;
  }

  delete gRestartAction;

  if (result != 0) {
    std::cerr << "FATAL: RestartAction returned non-zero exit status: " << result
              << ", giving up." << std::endl;
    return result;
  }

#if defined(__linux__)
  // Attempt restart via execvp after restoring working directory
  if (chdir(initial_workdir.c_str()) != 0) {
    std::cerr << "WARNING: could not change into directory '" << initial_workdir << "'"
              << std::endl;
  }
  if (execvp(argv[0], argv) == -1) {
    std::cerr << "WARNING: could not execvp ourselves, restore will not work!"
              << std::endl;
  }
#endif

  return 0;
}

