// Helper to convert fixed-point to double for comparison
static double
fxp_to_double(fxp_t val) {
	double integer_part = static_cast<double>(val >> 16);
	unsigned int fractional_part = val & 0xFFFF;
	double fractional_component = static_cast<double>(fractional_part) / 65536.0;
	return integer_part + fractional_component;
}

// Check if two doubles are approximately equal within tolerance
static bool
approx_equal(double x, double y) {
	// Accept values close in either absolute or relative terms
	return fabs(x - y) < 0.01 || (x != 0.0 && fabs(x - y) / fabs(x) < 0.01);
}

// Compare two fxp values via their double representations
static bool
fxp_approx_equal(fxp_t a, fxp_t b) {
	return approx_equal(fxp_to_double(a), fxp_to_double(b));
}

// Safely parse a string into an fxp value
static fxp_t
safe_parse(const char *input) {
	fxp_t parsed_value;
	bool parse_error = fxp_parse(&parsed_value, input, nullptr);
	assert_false(parse_error, "Failed to parse valid FXP string: %s", input);
	return parsed_value;
}

// Verify parsing accuracy against expected double value
static void
verify_parse_accuracy(const char *original_str, const char *parse_str) {
	double expected_val = strtod(original_str, nullptr);
	fxp_t parsed_fxp;
	char *end_ptr = nullptr;
	bool parse_err = fxp_parse(&parsed_fxp, parse_str, &end_ptr);
	expect_false(parse_err, "Unexpected parse failure");
	expect_ptr_eq(parse_str + strlen(original_str), end_ptr,
	    "Did not consume entire input string");
	expect_true(approx_equal(fxp_to_double(parsed_fxp), expected_val),
	    "Incorrect parsing of %s", original_str);
}

// Run multiple parsing scenarios for a given numeric string
static void
run_valid_parsing_tests(const char *number_str) {
	// Direct parsing test
	verify_parse_accuracy(number_str, number_str);

	// With trailing text
	char buffer[200];
	snprintf(buffer, sizeof(buffer), "%s_extra_suffix", number_str);
	verify_parse_accuracy(number_str, buffer);

	// With space after number
	snprintf(buffer, sizeof(buffer), "%s followed_by_text", number_str);
	verify_parse_accuracy(number_str, buffer);

	// Inside malloc.conf-like syntax
	snprintf(buffer, sizeof(buffer), "%s:config_key:123", number_str);
	verify_parse_accuracy(number_str, buffer);
}

