// Ensure invalid inputs fail as expected
static void
expect_parse_failure(const char *bad_input) {
	fxp_t initial_result = FXP_INIT_INT(333);
	char *position_marker = reinterpret_cast<char*>(0x123);
	bool error_flag = fxp_parse(&initial_result, bad_input, &position_marker);
	expect_true(error_flag, "Expected parse failure for '%s'", bad_input);
	expect_ptr_eq(reinterpret_cast<char*>(0x123), position_marker,
	    "Parse error should leave output unchanged");
	expect_u32_eq(initial_result, FXP_INIT_INT(333),
	    "Parse error should not modify result");
}

