#include "Buffer.h"
#include <cassert>

Buffer::Buffer(unsigned int capacity)
: m_capacity(capacity),
  m_pos(0),
  m_upperBound(capacity),
  hasBackingArray(false) {}

// Resets the buffer state by setting position to zero and limit to capacity
// This method preserves existing data but prepares the buffer for new operations
//
// Returns:
// This buffer instance for method chaining
Buffer* Buffer::clear() {
    m_pos = 0;
    m_upperBound = m_capacity;
    return this;
}

// Establishes a new boundary for this buffer. When the position exceeds the 
// specified limit, it gets adjusted downward to match. Any existing mark 
// beyond the new limit will be invalidated.
//
// Parameters: newLimit - The desired upper bound; must be within [0, capacity]
// Returns: This buffer object for fluent interface support
Buffer* Buffer::limit(unsigned int newLimit) {
    assert(newLimit <= m_capacity);
    m_upperBound = newLimit;
    if (m_pos > newLimit) m_pos = newLimit;
    return this;
}

// Retrieves the current boundary value of this buffer
// Returns: The maximum allowable position value
unsigned int Buffer::limit() { return m_upperBound; }

// Adjusts the current index within the buffer boundaries
// If a mark exists beyond the new position, it will be removed
//
// Parameters: newPos - The target index; must satisfy 0 <= newPos <= current_limit
// Returns: This buffer instance for chaining operations
Buffer* Buffer::position(unsigned int newPos) {
    assert(newPos <= m_upperBound);
    m_pos = newPos;
    return this;
}

// Provides the current index within the buffer
// Returns: The current position marker
unsigned int Buffer::position() { return m_pos; }

// Calculates how many elements can still be processed before reaching the limit
// Returns: The count of available elements from current position to limit
unsigned int Buffer::remaining() { return m_upperBound - m_pos; }

