// 4J - removal of separate temperature & downfall layers brought forward from 1.2.3
void BiomeSource::_init()
{	
    layer = nullptr;
	zoomedLayer = nullptr;

	cache = new BiomeCache(this);
	// Initialize spawnable biomes list
	playerSpawnBiomes.clear();
	playerSpawnBiomes.emplace_back(Biome::forest);
	playerSpawnBiomes.emplace_back(Biome::taiga);
	// 4J-PB - Moving forward plains as a spawnable biome (mainly for the Superflat world)
	playerSpawnBiomes.emplace_back(Biome::plains);
	playerSpawnBiomes.emplace_back(Biome::taigaHills);
	playerSpawnBiomes.emplace_back(Biome::forestHills);
	playerSpawnBiomes.emplace_back(Biome::jungle);
	playerSpawnBiomes.emplace_back(Biome::jungleHills);
}

void BiomeSource::_init(__int64 seed, LevelType *generator)
{
	_init();
	LayerArray layers = Layer::getDefaultLayers(seed, generator);
