//#define DEBUG_SEEDS 50
// 4J added - find a seed for this biomesource that matches certain criteria
#ifdef __PSVITA__
__int64 BiomeSource::findSeed(LevelType *generator, bool* pServerRunning)	// MGH - added pRunning, so we can early out of this on Vita as it can take up to 60 secs
#else
__int64 BiomeSource::findSeed(LevelType *generator)	
#endif
{
	__int64 bestSeed = 0;
	ProgressRenderer *mcprogress = Minecraft::GetInstance()->progressRenderer;
	mcprogress->progressStage(IDS_PROGRESS_NEW_WORLD_SEED);
#ifndef _CONTENT_PACKAGE
	if(app.DebugSettingsOn() && app.GetGameSettingsDebugMask(ProfileManager.GetPrimaryPad())&(1L<<eDebugSetting_EnableHeightWaterBiomeOverride))
	{
		// Do nothing
	}
	else
#endif
	{
#ifdef DEBUG_SEEDS
		for( int k = 0; k < DEBUG_SEEDS; k++ )
#endif
		{
			// Try and genuinely random this search up
			Random *pr = new Random(System::nanoTime());
			// Raw biome data has one result per 4x4 group of tiles.
			// Removing a border of 8 from each side since we'll be doing special things at the edge to turn our world into an island, and so don't want to count things
			// in the edge region in case they later get removed
			static const int biomeWidth = ( 54 * 4 ) - 16;			// Should be even so we can offset evenly
			static const int biomeOffset = -( biomeWidth / 2 );
			// Storage for our biome indices
			intArray indices = intArray( biomeWidth * biomeWidth );
			// Storage for the fractional amounts of each biome that will be calculated
			float toCompare[Biome::BIOME_COUNT];
			bool matchFound = false;
			int tryCount = 0;
			// Just keeping trying to generate seeds until we find one that matches our criteria
			do
			{
				__int64 seed = pr->nextLong();
				BiomeSource *biomeSource = new BiomeSource(seed,generator);
				biomeSource->getRawBiomeIndices(indices, biomeOffset, biomeOffset, biomeWidth, biomeWidth);
				getFracs(indices, toCompare);
				matchFound = getIsMatch( toCompare );
				if( matchFound ) bestSeed = seed;
				delete biomeSource;
				tryCount++;
				mcprogress->progressStagePercentage( tryCount % 100 );
#ifdef __PSVITA__
			} while (!matchFound && *pServerRunning);
#else
			} while (!matchFound);
#endif
			// Clean up
			delete pr;
			delete[] indices.data;
#ifdef DEBUG_SEEDS
			app.DebugPrintf("%d: %d tries taken, seed used is %lld\n", k, tryCount, bestSeed);
			BiomeSource *biomeSource = new BiomeSource(bestSeed);
			BiomeArray biomes = biomeSource->getBiomeBlock(-27 * 16, -27 * 16, 54 * 16, 54 * 16);
			unsigned int *pixels = new unsigned int[54 * 16 * 54 * 16];
			for(int i = 0; i < 54 * 16 * 54 * 16; ++i )
			{			
				int id = biomes[i]->id;
				// Create following colours:
				// 0	ocean				0000	black
				// 1	plains				0001	pastel cyan
				// 2	desert				0010	green
				// 3	extreme hills		0011	yellow
				// 4	forest				0100	blue
				// 5	taiga				0101	magenta
				// 6	swamps				0110	cyan
				// 7	river				0111	white
				// 8	hell				1000	grey
				// 9	end biome			1001	white
				// 10	frozen ocean		1010	pastel green
				// 11	frozen river		1011	pastel yellow
				// 12	ice flats			1100	pastel blue
				// 13	ice mountains		1101	pastel magenta
				// 14	mushroom island		1110	red
				// 15   mushroom shore		1111	pastel red
				if( id == 1 ) id = 14;
				else if ( id == 14 ) id = 1;
				else if( id == 9 ) id = 15;
				else if( id == 15 ) id = 9;
				pixels[i] = 0xff000000;
				if( id & 1 ) pixels[i] |= 0x00ff0000;
				if( id & 2 ) pixels[i] |= 0x0000ff00;
				if( id & 4 ) pixels[i] |= 0x000000ff;
				if( id & 8 ) pixels[i] |= 0x00808080;
			}
			D3DXIMAGE_INFO srcInfo;
			srcInfo.Format = D3DFMT_LIN_A8R8G8B8;
			srcInfo.ImageFileFormat = D3DXIFF_BMP;
			srcInfo.Width = 54 * 16;
			srcInfo.Height = 54 * 16;
			char buf[256];
			sprintf(buf,"GAME:\\BiomeTest%d.bmp",k);
			RenderManager.SaveTextureData(buf, &srcInfo, (int *)pixels);
			delete [] pixels;
			delete[] biomes.data;
			delete biomeSource;
#endif
		}
	}
	return bestSeed;
}

// 4J added - get the fractional amounts of each biome type in the given indices
void BiomeSource::getFracs(intArray indices, float *fracs)
{
	for( int i = 0; i < Biome::BIOME_COUNT; ++i )
	{
		fracs[i] = 0.0f;
	}
	for( int i = 0; i < indices.length; ++i )
	{
		fracs[indices[i]] += 1.0f;
	}
	for( int i = 0; i < Biome::BIOME_COUNT; ++i )
	{
		fracs[i] /= static_cast<float>(indices.length);
	}
}

// 4J added - determine if this particular set of fractional amounts of biome types matches are requirements
bool BiomeSource::getIsMatch(float *frac)
{
	// A true for a particular biome type here marks it as one that *has* to be present
	static const bool critical[Biome::BIOME_COUNT] = { 
										true,	// ocean
										true,	// plains
										true,	// desert
										false,	// extreme hills
										true,	// forest
										true,	// taiga
										true,	// swamps
										false,	// river
										false,	// hell
										false,	// end biome
										false,	// frozen ocean
										false,	// frozen river
										false,	// ice flats
										false,	// ice mountains
										true,	// mushroom island / shore
										false,  // mushroom shore (combined with above)
										false,	// beach
										false,	// desert hills (combined with desert)
										false,	// forest hills (combined with forest)
										false,	// taiga hills (combined with taga)
										false,	// small extreme hills
										true,	// jungle
										false,	// jungle hills (combined with jungle)
										};
	// Don't want more than 15% ocean
	if( frac[0] > 0.15f )
	{
		return false;
	}
	// Consider mushroom shore & islands as the same by finding max
	frac[14] = ( ( frac[15] > frac[14] ) ? frac[15] : frac[14] );
	// Merge desert and desert hills
	frac[2] = ( ( frac[17] > frac[2] ) ? frac[17] : frac[2] );
	// Merge forest and forest hills
	frac[4] = ( ( frac[18] > frac[4] ) ? frac[18] : frac[4] );
	// Merge taiga and taiga hills
	frac[5] = ( ( frac[19] > frac[5] ) ? frac[19] : frac[5] );
	// Merge jungle and jungle hills
	frac[21] =  ( ( frac[22] > frac[21] ) ? frac[22] : frac[21] );
	// Loop through all biome types, and:
	// (1) count them
	// (2) give up if one of the critical ones is missing
	int typeCount = 0;
	for( int i = 0; i < Biome::BIOME_COUNT; ++i )
	{
		// We want to skip some where we have merged with another type
		if(i == 15 || i == 17 || i == 18 || i == 19 || i == 22) continue;
		// Consider 0.1% as being "present" - this equates an area of about 3 chunks
		if( frac[i] > 0.001f )
		{
			typeCount++;
		}
		else
		{
			// If a critical biome is missing, just give up
			if( critical[i] )
			{
				return false;
			}
		}
	}
	// Consider as suitable if we've got all the critical ones, and in total 9 or more - currently there's 8 critical so this just forces at least 1 more others
	return ( typeCount >= 9 );
}

#include <iostream>
#include <sm/range>
#include <mplot/graphing.h>

void printUsage(char** programName) {
    std::cout << "Program Usage:\n";
    std::cout << *programName << " <min_value> <max_value> <min_ticks> <max_ticks>\n";
}

int main(int argc, char** argv) {
    float lowerBound = 0.0f;
    float upperBound = 9.0f;

    if (argc > 2) {
        lowerBound = static_cast<float>(std::atof(argv[1]));
        upperBound = static_cast<float>(std::atof(argv[2]));
    } else {
        printUsage(argv);
        return -1;
    }

    std::cout << "Input range: " << lowerBound << " to " << upperBound << std::endl;

    sm::range<float> tickRange{3, 8};
    if (argc > 4) {
        tickRange.min = static_cast<float>(std::atof(argv[3]));
        tickRange.max = static_cast<float>(std::atof(argv[4]));
    } else {
        printUsage(argv);
        return -1;
    }

    std::cout << "Tick count interval: " << tickRange << std::endl;

    std::deque<float> tickPositions = mplot::graphing::maketicks(
        lowerBound, upperBound, lowerBound, upperBound, tickRange);

    std::cout << "\nGenerated ticks for [" << lowerBound << ", " << upperBound << "]: ";
    for (const auto& pos : tickPositions) {
        std::cout << pos << ", ";
    }
    std::cout << std::endl;

    return 0;
}

#include <engLib/eng.h>
using namespace engine::net::rpc::v3::keystore;

namespace engine::keystore {

/**
 * @brief Constructor
 *
 * Initializes the service key-store wrapper with a given service key and
 * underlying key-store instance. The service key is prepended to partition
 * names during all wrapped operations.
 *
 * @param svcKey Service identifier used as prefix for partitions
 * @param store  Underlying key-store implementation to delegate calls to
 */
ServiceKeyStore::ServiceKeyStore(TextView svcKey,
                                 SharedPtr<KeyStore> store) noexcept
    : m_serviceKey(svcKey), m_keystore(store) {}

/**
 * @brief Retrieve base URL
 *
 * Delegates to the underlying key-store's `getUrl` method.
 *
 * @return The configured URL of the underlying store
 */
Url ServiceKeyStore::getUrl() const noexcept { return m_keystore->getUrl(); }

/**
 * @brief Attempt to open the store
 *
 * This operation is intentionally unsupported.
 *
 * @param url Unused parameter
 * @return Always returns Ec::NotSupported error
 */
Error ServiceKeyStore::open(const Url &url) noexcept {
    return APERR(Ec::NotSupported, "operation not supported");
}

/**
 * @brief Fetch value by key within a logical partition
 *
 * Prepends the service key to the provided partition name before delegating
 * to the wrapped store.
 *
 * @param part Partition identifier (will be prefixed)
 * @param key  Key to look up
 * @return Value or error if lookup fails
 */
ErrorOr<Text> ServiceKeyStore::getValue(TextView part, TextView key) noexcept {
    return m_keystore->getValue(servicePartition(part), key);
}

/**
 * @brief Store a value under a key in a partition
 *
 * Wraps the partition name with the service key and forwards to the underlying
 * key-store.
 *
 * @param part Partition identifier (will be prefixed)
 * @param key  Key to store under
 * @param val  Value to store
 * @return Error code on failure
 */
Error ServiceKeyStore::setValue(TextView part, TextView key,
                                TextView val) noexcept {
    return m_keystore->setValue(servicePartition(part), key, val);
}

/**
 * @brief Remove a specific key from a partition
 *
 * Applies service-key prefixing to the partition and delegates deletion.
 *
 * @param part Partition identifier (will be prefixed)
 * @param key  Key to delete
 * @return Error code on failure
 */
Error ServiceKeyStore::deleteKey(TextView part, TextView key) noexcept {
    return m_keystore->deleteKey(servicePartition(part), key);
}

/**
 * @brief Erase all entries in a partition
 *
 * Prefixes the partition name and forwards to the underlying store.
 *
 * @param part Partition identifier (will be prefixed)
 * @return Error code on failure
 */
Error ServiceKeyStore::deleteAll(TextView part) noexcept {
    return m_keystore->deleteAll(servicePartition(part));
}

/**
 * @brief Retrieve all key-value pairs in a partition
 *
 * Uses service-key augmented partition name when calling the wrapped store.
 *
 * @param part Partition identifier (will be prefixed)
 * @return Collection of key-value pairs or error
 */
ErrorOr<KeyStore::Values> ServiceKeyStore::getAll(TextView part) noexcept {
    return m_keystore->getAll(servicePartition(part));
}

/**
 * @brief Copy all entries between partitions
 *
 * Applies service-key prefixing to both source and destination partitions.
 *
 * @param src Source partition name
 * @param dst Destination partition name
 * @return Error code on failure
 */
Error ServiceKeyStore::copyAll(TextView src, TextView dst) noexcept {
    return m_keystore->copyAll(servicePartition(src), servicePartition(dst));
}

/**
 * @brief Move all entries between partitions with optional cleanup
 *
 * Extends copyAll semantics with options to clear destination and skip empty
 * sources.
 *
 * @param src       Source partition (prefixed internally)
 * @param dst       Destination partition (prefixed internally)
 * @param clearDst  Whether to erase destination contents first
 * @param skipIfEmpty Avoid action if source has no entries
 * @return Error code on failure
 */
Error ServiceKeyStore::moveAll(TextView src, TextView dst, bool clearDst,
                               bool skipIfEmpty) noexcept {
    return m_keystore->moveAll(servicePartition(src), servicePartition(dst),
                               clearDst, skipIfEmpty);
}

/**
 * @brief Build a prefixed partition name
 *
 * Combines the stored service key and the input partition into a single
 * hierarchical identifier.
 *
 * @param part Base partition name
 * @return Combined string: "<serviceKey>/<part>"
 */
Text ServiceKeyStore::servicePartition(TextView part) noexcept {
    return _ts(m_serviceKey, "/", part);
}

}  // namespace engine::keystore

