#include <ankerl/unordered_dense.h>
#include <app/counter.h>
#include <app/doctest.h>

namespace {
    class CleanupOnDestruction;
    using storage_map = ankerl::unordered_dense::map<counter::obj, std::unique_ptr<CleanupOnDestruction>>;

    class CleanupOnDestruction {
        storage_map* m_container;
        counter::obj m_id;
    public:
        CleanupOnDestruction(storage_map& container, size_t index, counter& counts)
            : m_container(&container)
            , m_id(index, counts) {}

        ~CleanupOnDestruction() {
            if (m_container != nullptr) {
                // Compute next key as (current_index + 1) mod (index + 2) to avoid overflow or invalid keys
                auto next_idx = static_cast<size_t>((m_id.index() + 1) % (m_id.index() + 2));
                m_container->erase(counter::obj{next_idx, m_id.counts()});
            }
        }

        counter::obj const& id() const { return m_id; }
    };
} // namespace

TEST_CASE("reentrant_destruct") {
    auto counts = counter{};
    INFO(counts);
    auto container = storage_map{};

    // Insert elements using insert instead of try_emplace
    for (size_t i = 0; i < 5; ++i) {
        auto obj = counter::obj{i, counts};
        container.insert(std::make_pair(obj, std::make_unique<CleanupOnDestruction>(container, i, counts)));
    }

    // Optional: remove one explicitly to simulate partial cleanup
    container.erase(counter::obj{0, counts});
}

#include <cmath>

// Round float to long integer using inline assembly with ARM NEON instructions
long roundFloatToInt(float value) {
    long result;
    __asm__ volatile (
        "frintx s0, %s1\n\t"
        "fcvtzs %x0, s0"
        : "=r"(result), "+w"(value)
    );
    return result;
}

