Settings loadSettings(const std::string& configPath, const std::string& sectionName, bool printDetails) {
  boost::property_tree::ptree tree;
  boost::property_tree::read_info(configPath, tree);
  Settings cfg;

  if (printDetails) {
    std::cerr << "\n #### MPC Settings:";
    std::cerr << "\n #### =============================================================================\n";
  }

  // Load configuration values using the property tree
  loadData::loadPtreeValue(tree, cfg.timeHorizon_, sectionName + ".timeHorizon", printDetails);
  loadData::loadPtreeValue(tree, cfg.solutionTimeWindow_, sectionName + ".solutionTimeWindow", printDetails);
  loadData::loadPtreeValue(tree, cfg.recordSolverData_, sectionName + ".recordSolverData", printDetails);
  loadData::loadPtreeValue(tree, cfg.coldStart_, sectionName + ".coldStart", printDetails);
  loadData::loadPtreeValue(tree, cfg.debugPrint_, sectionName + ".debugPrint", printDetails);
  loadData::loadPtreeValue(tree, cfg.mpcDesiredFrequency_, sectionName + ".mpcDesiredFrequency", printDetails);
  loadData::loadPtreeValue(tree, cfg.mrtDesiredFrequency_, sectionName + ".mrtDesiredFrequency", printDetails);

  if (printDetails) {
    std::cerr << " #### =============================================================================" << std::endl;
  }

  return cfg;
}

