#include "jemalloc/internal/jemalloc_preamble.h"
#include "jemalloc/internal/jemalloc_internal_includes.h"
#include "jemalloc/internal/bit_util.h"
#include "jemalloc/internal/cache_bin.h"
#include "jemalloc/internal/safety_check.h"

const uintptr_t disabled_bin = JUNK_ADDR;

void
cache_bin_info_init(cache_bin_info_t *info, cache_bin_sz_t max_cached) {
    assert(max_cached <= CACHE_BIN_NCACHED_MAX);
    size_t required_stack_space = (size_t)max_cached * sizeof(void *);
    assert(required_stack_space < ((size_t)1 << (sizeof(cache_bin_sz_t) * 8)));
    info->ncached_max = (cache_bin_sz_t)max_cached;
}

bool
cache_bin_stack_use_thp(void) {
    /*
     * When metadata_thp is active, we allocate tcache stacks via the base
     * allocator for performance benefits. However, this means freed memory
     * from terminated threads may remain cached in the base allocator.
     */
    return metadata_thp_enabled();
}

void
cache_bin_info_compute_alloc(const cache_bin_info_t *infos, szind_t count,
    size_t *total_size, size_t *required_alignment) {
    /* Reserve extra space: one slot before and one after the actual stack */
    *total_size = sizeof(void *) * 2;
    for (szind_t idx = 0; idx < count; ++idx) {
        *total_size += infos[idx].ncached_max * sizeof(void *);
    }

    /* Align to PAGE unless THP is enabled — THP avoids TLB overhead */
    *required_alignment = cache_bin_stack_use_thp() ? QUANTUM : PAGE;
}

void
cache_bin_preincrement(const cache_bin_info_t *infos, szind_t count, void *buffer,
    size_t *current_offset) {
    if (config_debug) {
        size_t expected_size;
        size_t expected_align;
        cache_bin_info_compute_alloc(infos, count, &expected_size, &expected_align);
        assert(((uintptr_t)buffer & (expected_align - 1)) == 0);
    }
    *(uintptr_t *)((byte_t *)buffer + *current_offset) =
        cache_bin_preceding_junk;
    *current_offset += sizeof(void *);
}

void
cache_bin_postincrement(void *buffer, size_t *current_offset) {
    *(uintptr_t *)((byte_t *)buffer + *current_offset) =
        cache_bin_trailing_junk;
    *current_offset += sizeof(void *);
}

void
cache_bin_init(cache_bin_t *bin, const cache_bin_info_t *info, void *memory,
    size_t *current_offset) {
    void *stack_base = (void *)((byte_t *)memory + *current_offset);
    void *stack_top = stack_base;
    uint16_t stack_bytes = (uint16_t)(info->ncached_max * sizeof(void *));
    *current_offset += stack_bytes;
    void *stack_end = (void *)((byte_t *)memory + *current_offset);

    bin->stack_head = (void **)stack_end;
    bin->low_bits_low_water = (uint16_t)(uintptr_t)bin->stack_head;
    bin->low_bits_full = (uint16_t)(uintptr_t)stack_top;
    bin->low_bits_empty = (uint16_t)(uintptr_t)stack_end;

    cache_bin_info_init(&bin->bin_info, info->ncached_max);

    cache_bin_sz_t available_slots = cache_bin_diff(bin,
        bin->low_bits_full, (uint16_t)(uintptr_t)bin->stack_head);
    assert(available_slots == stack_bytes / sizeof(void *));

    if (!cache_bin_disabled(bin)) {
        assert(cache_bin_ncached_get_local(bin) == 0);
    }

    assert(cache_bin_empty_position_get(bin) == stack_end);
    assert(stack_bytes > 0 || stack_end == stack_top);
}

void
cache_bin_init_disabled(cache_bin_t *bin, cache_bin_sz_t max_cached) {
    const void *dummy_stack = cache_bin_disabled_bin_stack();
    size_t dummy_offset = 0;
    cache_bin_info_t placeholder_info;
    cache_bin_info_init(&placeholder_info, 0);
    cache_bin_init(bin, &placeholder_info, (void *)dummy_stack, &dummy_offset);
    cache_bin_info_init(&bin->bin_info, max_cached);
    assert(dummy_offset == 0);
}

#include <asio/bind_executor.hpp>
#include <asio/io_context.hpp>
#include <asio/ip/tcp.hpp>
#include <asio/use_future.hpp>
#include <asio/write.hpp>
#include <cstring>
#include <functional>
#include <iostream>
#include <string>
#include <type_traits>
#include <utility>

using asio::ip::tcp;

//------------------------------------------------------------------------------
// Composed async operation that wraps async_write with a simplified completion signature
template <typename CompletionToken>
auto initiate_async_message(tcp::socket& sock,
    const char* msg, CompletionToken&& token)
  -> typename asio::async_result<
    typename std::decay<CompletionToken>::type,
    void(std::error_code)>::return_type
{
  // Set up the async completion machinery
  asio::async_completion<CompletionToken,
    void(std::error_code)> result(token);

  // Get the appropriate executor to preserve execution context
  auto bound_executor = asio::get_associated_executor(
      result.completion_handler, sock.get_executor());

  // Launch the underlying async_write with adapted handler
  asio::async_write(sock,
      asio::buffer(msg, std::strlen(msg)),
      asio::bind_executor(bound_executor,
        [handler = std::move(result.completion_handler)](
            const std::error_code& ec, std::size_t /*bytes_transferred*/) mutable {
          handler(ec);
        }));

  return result.result.get();
}

//------------------------------------------------------------------------------
void run_callback_test()
{
  asio::io_context ctx;
  tcp::acceptor acc(ctx, {tcp::v4(), 55555});
  tcp::socket s = acc.accept();

  // Use lambda for callback-based test
  initiate_async_message(s, "Callback mode test\r\n",
      [](const std::error_code& err)
      {
        if (!err)
          std::cout << "Message delivered successfully\n";
        else
          std::cout << "Transmission failed: " << err.message() << "\n";
      });

  ctx.run();
}

//------------------------------------------------------------------------------
void run_future_test()
{
  asio::io_context ctx;
  tcp::acceptor acc(ctx, {tcp::v4(), 55555});
  tcp::socket s = acc.accept();

  // Use use_future to get a future for synchronous waiting
  std::future<void> fut = initiate_async_message(
      s, "Future-based test\r\n", asio::use_future);

  ctx.run();

  try
  {
    fut.get();
    std::cout << "Message sent via future\n";
  }
  catch (const std::exception& ex)
  {
    std::cout << "Exception caught: " << ex.what() << "\n";
  }
}

//------------------------------------------------------------------------------
int main()
{
  run_callback_test();
  run_future_test();
}

