#include <iostream>
#include <vector>
#include <algorithm>
#include <cmath>
using namespace std;

// Structure to represent the current state of baskets (1-indexed)
struct Configuration {
    vector<int> baskets[4]; // baskets[1], baskets[2], baskets[3] used
};

int totalBalls;
vector<pair<int, int>> operationSequence;
Configuration currentConfig;

// Get center element index in a basket (0-based)
int find_center_index(const vector<int>& basket) {
    if (basket.empty()) return -1;
    int size = basket.size();
    return size / 2; // For both odd and even sizes, this gives the desired center position
}

// Check if adding 'value' to 'basket' keeps it as the new center
bool can_place_in_basket(const vector<int>& basket, int value) {
    vector<int> temp = basket;
    temp.push_back(value);
    sort(temp.begin(), temp.end());
    int centerVal = temp[find_center_index(temp)];
    return centerVal == value;
}

// Perform a move: take center from source basket and put into destination basket
void execute_move(int srcBasket, int destBasket) {
    vector<int>& source = currentConfig.baskets[srcBasket];
    int val = source[find_center_index(source)];

    // Remove the center value from source basket
    auto it = find(source.begin(), source.end(), val);
    source.erase(it);
    sort(source.begin(), source.end());

    // Add to destination basket
    vector<int>& dest = currentConfig.baskets[destBasket];
    dest.push_back(val);
    sort(dest.begin(), dest.end());

    operationSequence.push_back({srcBasket, destBasket});
}

// Find which basket contains a specific ball
int locate_basket(int ballValue) {
    for (int i = 1; i <= 3; ++i) {
        for (int x : currentConfig.baskets[i]) {
            if (x == ballValue) return i;
        }
    }
    return -1;
}

// Forward declarations
void transfer_ball(int ball, int targetBasket);

// Move the center of a basket to another basket, handling conflicts recursively
void shift_center(int fromBasket, int toBasket) {
    if (fromBasket == toBasket) return;

    int centerValue = currentConfig.baskets[fromBasket][find_center_index(currentConfig.baskets[fromBasket])];

    if (can_place_in_basket(currentConfig.baskets[toBasket], centerValue)) {
        execute_move(fromBasket, toBasket);
    } else {
        int thirdBasket = 6 - fromBasket - toBasket;
        shift_center(toBasket, thirdBasket);
        shift_center(fromBasket, toBasket);
    }
}

// Transfer a specific ball to a target basket
void transfer_ball(int ball, int targetBasket) {
    int currentBasket = locate_basket(ball);
    if (currentBasket == targetBasket) return;

    int currentCenter = currentConfig.baskets[currentBasket][find_center_index(currentConfig.baskets[currentBasket])];

    if (currentCenter == ball) {
        if (can_place_in_basket(currentConfig.baskets[targetBasket], ball)) {
            execute_move(currentBasket, targetBasket);
        } else {
            int otherBasket = 6 - currentBasket - targetBasket;
            shift_center(targetBasket, otherBasket);
            transfer_ball(ball, targetBasket);
        }
    } else {
        int otherBasket = 6 - currentBasket - targetBasket;
        transfer_ball(currentCenter, otherBasket);
        transfer_ball(ball, targetBasket);
    }
}

int main() {
    cin >> totalBalls;

    // Initialize: all balls in basket 1
    for (int i = 1; i <= totalBalls; ++i) {
        currentConfig.baskets[1].push_back(i);
    }

    // Build target sequence: 1, N, 2, N-1, 3, N-2, ...
    vector<int> desiredOrder;
    int low = 1, high = totalBalls;
    while (low <= high) {
        desiredOrder.push_back(low++);
        if (low <= high) desiredOrder.push_back(high--);
    }

    // Move each ball in desired order to basket 3
    for (int ball : desiredOrder) {
        transfer_ball(ball, 3);
    }

    cout << operationSequence.size() << endl;
    for (auto op : operationSequence) {
        cout << op.first << " " << op.second << endl;
    }

    return 0;
}

#include "llvm/Transforms/Utils/FixIrreducible.h"
#include "llvm/ADT/SCCIterator.h"
#include "llvm/Analysis/DomTreeUpdater.h"
#include "llvm/Analysis/LoopIterator.h"
#include "llvm/InitializePasses.h"
#include "llvm/Pass.h"
#include "llvm/Transforms/Utils.h"
#include "llvm/Transforms/Utils/BasicBlockUtils.h"
#define DEBUG_TYPE "fix-irreducible"
using namespace llvm;

namespace {
struct FixIrreducible : public FunctionPass {
  static char ID;
  FixIrreducible() : FunctionPass(ID) {
    initializeFixIrreduciblePass(*PassRegistry::getPassRegistry());
  }

  void getAnalysisUsage(AnalysisUsage &AU) const override {
    AU.addRequired<DominatorTreeWrapperPass>();
    AU.addRequired<LoopInfoWrapperPass>();
    AU.addPreserved<DominatorTreeWrapperPass>();
    AU.addPreserved<LoopInfoWrapperPass>();
  }

  bool runOnFunction(Function &F) override;
};
} // namespace

char FixIrreducible::ID = 0;
FunctionPass *llvm::createFixIrreduciblePass() { return new FixIrreducible(); }

INITIALIZE_PASS_BEGIN(FixIrreducible, "fix-irreducible",
                      "Transform irreducible control-flow into natural loops",
                      false /* Only looks at CFG */, false /* Analysis Pass */)
INITIALIZE_PASS_DEPENDENCY(DominatorTreeWrapperPass)
INITIALIZE_PASS_DEPENDENCY(LoopInfoWrapperPass)
INITIALIZE_PASS_END(FixIrreducible, "fix-irreducible",
                    "Transform irreducible control-flow into natural loops",
                    false /* Only looks at CFG */, false /* Analysis Pass */)

// Reattach sub-loops that may now belong to the newly formed loop
static void reattachSubLoops(LoopInfo &LI, Loop *OuterLoop, Loop *NewLoop,
                             SetVector<BasicBlock *> &CycleBlocks,
                             SetVector<BasicBlock *> &CycleHeaders) {
  auto &PotentialChildren = OuterLoop ? OuterLoop->getSubLoopsVector()
                                      : LI.getTopLevelLoopsVector();

  // Partition: move loops whose headers are in CycleBlocks (except NewLoop itself)
  auto SplitPoint = std::partition(
      PotentialChildren.begin(), PotentialChildren.end(),
      [&](Loop *L) {
        return L == NewLoop || !CycleBlocks.contains(L->getHeader());
      });

  SmallVector<Loop *, 8> MovedChildren(SplitPoint, PotentialChildren.end());
  PotentialChildren.erase(SplitPoint, PotentialChildren.end());

  for (Loop *Child : MovedChildren) {
    LLVM_DEBUG(dbgs() << "subloop: " << Child->getHeader()->getName() << "\n");

    if (CycleHeaders.count(Child->getHeader())) {
      // Merge blocks of destroyed child loop into NewLoop
      for (auto *BB : Child->blocks()) {
        if (LI.getLoopFor(BB) != Child) continue;
        LI.changeLoopFor(BB, NewLoop);
        LLVM_DEBUG(dbgs() << "relocated block: " << BB->getName() << "\n");
      }

      // Promote grandchildren to NewLoop
      std::vector<Loop *> Grandchildren;
      std::swap(Grandchildren, Child->getSubLoopsVector());
      for (auto *GC : Grandchildren) {
        GC->setParentLoop(nullptr);
        NewLoop->addChildLoop(GC);
      }
      LI.destroy(Child);
      LLVM_DEBUG(dbgs() << "absorbed child (shared header)\n");
      continue;
    }

    Child->setParentLoop(nullptr);
    NewLoop->addChildLoop(Child);
    LLVM_DEBUG(dbgs() << "attached child to new loop\n");
  }
}

// Convert an SCC into a natural loop and integrate it into the loop hierarchy
static void buildNaturalLoopInternal(LoopInfo &LI, DominatorTree &DT,
                                     Loop *EnclosingLoop,
                                     SetVector<BasicBlock *> &CycleBlocks,
                                     SetVector<BasicBlock *> &CycleHeaders) {
#ifndef NDEBUG
  for (auto *H : CycleHeaders)
    assert(CycleBlocks.count(H));
#endif

  SetVector<BasicBlock *> EntryPreds;
  for (auto *H : CycleHeaders) {
    for (auto *P : predecessors(H))
      EntryPreds.insert(P);
  }

  LLVM_DEBUG(dbgs() << "predecessors:";
             for (auto P : EntryPreds)
               dbgs() << " " << P->getName();
             dbgs() << "\n");

  SmallVector<BasicBlock *, 8> HubBlocks;
  DomTreeUpdater DTU(DT, DomTreeUpdater::UpdateStrategy::Eager);
  CreateControlFlowHub(&DTU, HubBlocks, EntryPreds, CycleHeaders, "irr");

#if defined(EXPENSIVE_CHECKS)
  assert(DT.verify(DominatorTree::VerificationLevel::Full));
#else
  assert(DT.verify(DominatorTree::VerificationLevel::Fast));
#endif

  auto *NewLoop = LI.AllocateLoop();
  if (EnclosingLoop)
    EnclosingLoop->addChildLoop(NewLoop);
  else
    LI.addTopLevelLoop(NewLoop);

  // Insert guard blocks first so they become the header
  for (auto *G : HubBlocks) {
    LLVM_DEBUG(dbgs() << "hub block: " << G->getName() << "\n");
    NewLoop->addBasicBlockToLoop(G, LI);
  }

  // Add remaining cycle blocks
  for (auto *BB : CycleBlocks) {
    NewLoop->addBlockEntry(BB);
    if (LI.getLoopFor(BB) == EnclosingLoop) {
      LLVM_DEBUG(dbgs() << "moved from parent: " << BB->getName() << "\n");
      LI.changeLoopFor(BB, NewLoop);
    } else {
      LLVM_DEBUG(dbgs() << "added from nested: " << BB->getName() << "\n");
    }
  }

  LLVM_DEBUG(dbgs() << "new header: " << NewLoop->getHeader()->getName() << "\n");
  reattachSubLoops(LI, EnclosingLoop, NewLoop, CycleBlocks, CycleHeaders);
  NewLoop->verifyLoop();
  if (EnclosingLoop)
    EnclosingLoop->verifyLoop();

#if defined(EXPENSIVE_CHECKS)
  LI.verify(DT);
#endif
}

namespace llvm {
template <> struct GraphTraits<Loop> : LoopBodyTraits {};
} // namespace llvm

static BasicBlock *extractBlock(BasicBlock *B) { return B; }
static BasicBlock *extractBlock(LoopBodyTraits::NodeRef &N) { return N.second; }

// Top-level entry point for function-level conversion
static void buildNaturalLoop(LoopInfo &LI, DominatorTree &DT, Function *F,
                             SetVector<BasicBlock *> &CycleBlocks,
                             SetVector<BasicBlock *> &CycleHeaders) {
  buildNaturalLoopInternal(LI, DT, nullptr, CycleBlocks, CycleHeaders);
}

// Loop-level entry point
static void buildNaturalLoop(LoopInfo &LI, DominatorTree &DT, Loop &L,
                             SetVector<BasicBlock *> &CycleBlocks,
                             SetVector<BasicBlock *> &CycleHeaders) {
  buildNaturalLoopInternal(LI, DT, &L, CycleBlocks, CycleHeaders);
}

// Process SCCs and convert large ones into natural loops
template <class Graph>
static bool reduceSCCs(LoopInfo &LI, DominatorTree &DT, Graph &&G) {
  bool Modified = false;
  for (auto Scc = scc_begin(G); !Scc.isAtEnd(); ++Scc) {
    if (Scc->size() < 2) continue;

    SetVector<BasicBlock *> CycleBlocks;
    LLVM_DEBUG(dbgs() << "detected SCC:";
               for (auto N : *Scc)
                 dbgs() << " " << extractBlock(N)->getName();
               dbgs() << "\n");

    for (auto N : *Scc)
      CycleBlocks.insert(extractBlock(N));

    SetVector<BasicBlock *> CycleHeaders;
    LLVM_DEBUG(dbgs() << "headers:");
    for (auto *BB : reverse(CycleBlocks)) {
      for (const auto *Pred : predecessors(BB)) {
        if (!DT.isReachableFromEntry(Pred)) continue;
        if (!CycleBlocks.count(Pred)) {
          LLVM_DEBUG(dbgs() << " " << BB->getName());
          CycleHeaders.insert(BB);
          break;
        }
      }
    }
    LLVM_DEBUG(dbgs() << "\n");

    if (CycleHeaders.size() == 1) {
      assert(LI.isLoopHeader(CycleHeaders.front()));
      LLVM_DEBUG(dbgs() << "single-header loop: skipped\n");
      continue;
    }

    buildNaturalLoop(LI, DT, G, CycleBlocks, CycleHeaders);
    Modified = true;
  }
  return Modified;
}

static bool fixIrreducibleImpl(Function &Fn, LoopInfo &LI, DominatorTree &DT) {
  LLVM_DEBUG(dbgs() << "processing function: " << Fn.getName() << "\n");
  assert(hasOnlySimpleTerminator(Fn) && "unsupported terminator.");

  bool Changed = false;
  SmallVector<Loop *, 8> WorkList;

  Changed |= reduceSCCs(LI, DT, &Fn);
  append_range(WorkList, LI);

  while (!WorkList.empty()) {
    auto *L = WorkList.pop_back_val();
    LLVM_DEBUG(dbgs() << "analyzing loop with header: "
                      << L->getHeader()->getName() << "\n");
    Changed |= reduceSCCs(LI, DT, *L);
    WorkList.append(L->begin(), L->end());
  }

  return Changed;
}

bool FixIrreducible::runOnFunction(Function &F) {
  auto &LI = getAnalysis<LoopInfoWrapperPass>().getLoopInfo();
  auto &DT = getAnalysis<DominatorTreeWrapperPass>().getDomTree();
  return fixIrreducibleImpl(F, LI, DT);
}

PreservedAnalyses FixIrreduciblePass::run(Function &F,
                                          FunctionAnalysisManager &AM) {
  auto &LI = AM.getResult<LoopAnalysis>(F);
  auto &DT = AM.getResult<DominatorTreeAnalysis>(F);

  if (!fixIrreducibleImpl(F, LI, DT))
    return PreservedAnalyses::all();

  PreservedAnalyses PA;
  PA.preserve<LoopAnalysis>();
  PA.preserve<DominatorTreeAnalysis>();
  return PA;
}

