#define MAX_CALLS 10
#define WINDOW_MS 1000
#define BAN_MS 10000

static u64 window_start = 0;
static u64 ban_until = 0;
static int call_count = 0;

static bool allow_call(void) {
    u64 now = osGetTime();
    if (now < ban_until)
        return false;
    if (now - window_start > WINDOW_MS) {
        window_start = now;
        call_count = 0;
    }
    call_count++;
    if (call_count >= MAX_CALLS) {
        ban_until = now + BAN_MS;
        return false;
    }
    return true;
}

extern "C" void GameDebugLogfHandler(u32 ukn1, u32 ukn2, const char* author, u32 ukn3, const char* fmt, ...) {
    va_list ap;
    va_start(ap, fmt);
    if (allow_call() && strcmp(author, "BuildGeometry") != 0 && strcmp(author, "loadChunk") != 0) {
        char buffer[0x200] = {0};
        int res = vsnprintf(buffer, sizeof(buffer), fmt, ap);
        if (buffer[res-1] == '\n')
            buffer[res-1] = '\0';
        if (ukn2 == 2)
            Core::Debug::LogInfo("[Game.Info] " + std::string(author) + ": " + buffer);
        else if (ukn2 == 8)
            Core::Debug::LogInfo("[Game.Warn] " + std::string(author) + ": " + buffer);
        else
            Core::Debug::LogInfo(' ' + std::string(author) + ": " + buffer);
    }
    va_end(ap);
    return;
}

static __attribute__((naked)) void GameDebugLogfHook(CoreHookContext* ctx) {
    asm volatile (
        "ldmia sp!, {r0-r12, lr}\n"
        "b GameDebugLogfHandler\n"
    );
}

void hookSomeFunctions() {
    Core::CrashHandler::core_state = Core::CrashHandler::CORE_HOOKING;
    installFunctionHook(0x0056c2a0, (u32)RegisterItemsHook);
    installFunctionHook(0x0056de70, (u32)RegisterItemsTexturesHook);
    installFunctionHook(0x00578358, (u32)RegisterCreativeItemsHook);
    installFunctionHook(0x001b4898, (u32)RegisterRecipes);
    installFunctionHook(0x00114f50, (u32)GameDebugLogfHook);
    // Disabled due to memory leak concerns
    // installFunctionHook(0x004df688, (u32)EntitySpawnStartHook);
    // installFunctionHook(0x004df7e0, (u32)EntitySpawnFinishedHook);
}

