int                           SparseLightStorage::deleteQueueIndex;
XLockFreeStack<unsigned char> SparseLightStorage::deleteQueue[3];

void SparseLightStorage::staticCtor() {
    // Initialize the delete queues using a different approach
    // Instead of a traditional for-loop, use pointer arithmetic with a sentinel
    XLockFreeStack<unsigned char>* pQueue = deleteQueue;
    XLockFreeStack<unsigned char>* pEnd   = deleteQueue + 3;

    while (pQueue != pEnd) {
        pQueue->Initialize();
        ++pQueue;
    }
}

