namespace quadrants::lang {

// This optimization removes immutable local variables by propagating their
// constant values to all subsequent uses. It assumes that each such variable
// is assigned exactly once (enforced by the GatherImmutableLocalVars pass).
class ImmutableVarPropagator : public BasicStmtVisitor {
 private:
  using BasicStmtVisitor::visit;

  // Set of statements representing immutable local variables
  std::unordered_set<Stmt *> immutable_vars_;

  // Maps each immutable var to its single defining value
  std::unordered_map<Stmt *, Stmt *> var_to_value_map_;

  ImmediateIRModifier ir_modifier_;
  DelayedIRModifier cleanup_modifier_;

 public:
  ImmutableVarPropagator(
      const std::unordered_set<Stmt *> &immutable_vars,
      IRNode *root)
      : immutable_vars_(immutable_vars), 
        ir_modifier_(root) {
  }

  void visit(AllocaStmt *stmt) override {
    if (immutable_vars_.count(stmt)) {
      cleanup_modifier_.remove(stmt);
    }
  }

  void visit(LocalLoadStmt *stmt) override {
    auto src = stmt->src;
    if (immutable_vars_.find(src) != immutable_vars_.end()) {
      auto replacement = var_to_value_map_[src];
      ir_modifier_.substitute_usage(stmt, replacement);
      cleanup_modifier_.remove(stmt);
    }
  }

  void visit(LocalStoreStmt *stmt) override {
    auto dest = stmt->dest;
    if (immutable_vars_.find(dest) != immutable_vars_.end()) {
      QD_ASSERT(var_to_value_map_.find(dest) == var_to_value_map_.end());
      var_to_value_map_[dest] = stmt->val;
      cleanup_modifier_.remove(stmt);
    }
  }

  static void execute(IRNode *node) {
    auto immutable_set = irpass::analysis::collect_immutable_locals(node);
    ImmutableVarPropagator optimizer(immutable_set, node);
    node->accept(&optimizer);
    optimizer.cleanup_modifier_.apply_changes();
  }
};

namespace irpass {

void eliminate_immutable_local_vars(IRNode *root) {
  QD_AUTO_PROF;
  ImmutableVarPropagator::execute(root);
}

}  // namespace irpass
}  // namespace quadrants::lang

