  IO.mapRequired("LowerBound", Res.LowerBound);
  IO.mapRequired("UpperBound", Res.UpperBound);

  const uint32_t *PSVVersionPtr = static_cast<uint32_t *>(IO.getContext());
  if (*PSVVersionPtr < 2)
