// Helper to extract secure parameters from service JSON
inline bool hasSecureParameters(const json::Value& params) noexcept {
    return params.isMember("secureParameters");
}

// Helper to check if parameter is of type SECURE
inline bool isSecureParam(const PARAM_TYPE type) noexcept {
    return type == PARAM_TYPE::SECURE;
}

//---------------------------------------------------------------------
/// @details
///		Decrypts the secrets within the service parameters and
///     populates the parameters with the hidden token values
///	@param[inout] service
///		Service to decrypt
//---------------------------------------------------------------------
Error decryptParameters(json::Value &service) noexcept {
    // Retrieve service definition
    auto serviceInfo = IServices::getServiceDefinitionFromService(service);
    if (!serviceInfo) return serviceInfo.ccode();

    // Ensure 'parameters' section exists
    if (!service.isMember("parameters")) return {};

    auto &params = service["parameters"];

    // Skip if no secure parameters present
    if (!hasSecureParameters(params)) return {};

    auto &secureSection = params["secureParameters"];

    // Extract and decode token
    Text token;
    if (auto ccode = secureSection.lookupAssign("token", token)) return ccode;
    if (!token) return {};

    auto decoded = crypto::base64Decode(token);
    if (!decoded) return decoded.ccode();

    auto plaintext = crypto::engineDecrypt(*decoded);
    if (!plaintext) return plaintext.ccode();

    auto parsedJson = json::parse(plaintext->toTextView());
    if (!parsedJson) return parsedJson.ccode();

    auto secureValues = *parsedJson;

    // Apply decrypted values to parameters
    const auto &defs = (*serviceInfo)->secureParameters;
    for (const auto &[keyName, paramType] : defs) {
        if (!isSecureParam(paramType)) continue;
        if (params.isMember(keyName)) continue;  // Already set
        if (!secureValues.isMember(keyName)) continue;

        params[keyName] = secureValues[keyName];
    }

    // Clean up secure section after use
    params.removeMember("secureParameters");
    return {};
}

//---------------------------------------------------------------------
/// @details
///		Encrypts the secrets within the service parameters. For secure
///		parameters, it places the values int the secure section with the
///		name and removes it from the parameters list. For readonly parameters
///		it leaves the value in the parameters, but copies it into secure
///		so we can ensure it is not overwritten
///	@param[in]	configParam
///		Parameter configuration info
///	@param[inout] target
///		Parameters set to encrypt
//---------------------------------------------------------------------
Error encryptParameters(IServiceConfig &config, json::Value &target) noexcept {
    json::Value secureNames(json::arrayValue);
    json::Value secretValues(json::objectValue);

    // Load service definition
    auto serviceInfo =
        IServices::getServiceDefinitionFromService(config.serviceConfig);
    if (!serviceInfo) return serviceInfo.ccode();

    // Ensure input has parameters
    if (!config.serviceConfig.isMember("parameters")) return {};

    // Copy current parameters to output
    target["parameters"] = config.serviceConfig["parameters"];
    auto &params = target["parameters"];

    // Process each secure parameter
    for (const auto &[keyName, paramType] : (*serviceInfo)->secureParameters) {
        if (!params.isMember(keyName)) continue;

        auto value = params[keyName];

        if (isSecureParam(paramType)) {
            params.removeMember(keyName);
            secureNames.append(keyName);
        }

        secretValues[keyName] = value;
    }

    // Encrypt and encode
    auto ciphertext = crypto::engineEncrypt(secretValues.stringify());
    if (!ciphertext) return ciphertext.ccode();

    auto token = crypto::base64Encode(*ciphertext);

    // Build secure section
    json::Value secureSection;
    secureSection["readonly"] = json::Value(json::arrayValue); // placeholder
    secureSection["secure"] = secureNames;
    secureSection["token"] = token;

    params["secureParameters"] = secureSection;
    return {};
}

