#ifndef USE_ALPHA
#define REAL_PART(a, b)  (a)
#define IMAGE_PART(a, b) (b)
#else
#define REAL_PART(a, b)  (alpha_r * (a) - alpha_i * (b))
#define IMAGE_PART(a, b) (alpha_i * (a) + alpha_r * (b))
#endif

#if defined(REAL_ONLY)
#define CMULT(a, b) (REAL_PART(a, b))
#elif defined(IMAGE_ONLY)
#define CMULT(a, b) (IMAGE_PART(a, b))
#else
#define CMULT(a, b) (REAL_PART(a, b) + IMAGE_PART(a, b))
#endif

int CNAME(BLASLONG m, BLASLONG n, FLOAT *a, BLASLONG lda,
#ifdef USE_ALPHA
          FLOAT alpha_r, FLOAT alpha_i, 
#endif
          FLOAT *b) {
    // Process each column
    while (n > 0) {
        FLOAT *current_a = a;
        a += 2;  // Move to next column's data

        BLASLONG row_idx = 0;
        while (row_idx < m) {
            // Load real and imaginary parts
            FLOAT real_val = current_a[0];
            FLOAT imag_val = current_a[1];

            // Compute complex multiplication result based on mode
            *(b + 0) = CMULT(real_val, imag_val);

            // Advance pointers for next iteration
            current_a += lda;
            b++;
            row_idx++;
        }

        n--;
    }

    return 0;
}

