#include <rclcpp/rclcpp.hpp>
#include <grid_map_ros/grid_map_ros.hpp>
#include <grid_map_msgs/msg/grid_map.hpp>
#include <cmath>
#include <memory>

int main(int argc, char ** argv)
{
  // Initialize ROS2 and create node with publisher
  rclcpp::init(argc, argv);
  auto node = std::make_shared<rclcpp::Node>("grid_map_simple_demo");
  auto map_pub = node->create_publisher<grid_map_msgs::msg::GridMap>(
    "grid_map", rclcpp::QoS(1).transient_local());

  // Setup grid map with single layer
  grid_map::GridMap layers({"elevation"});
  layers.setFrameId("map");
  layers.setGeometry(grid_map::Length(1.2, 2.0), 0.03);

  RCLCPP_INFO(
    node->get_logger(),
    "Map initialized: %.2f x %.2f m (%d x %d cells)",
    layers.getLength().x(), layers.getLength().y(),
    layers.getSize()(0), layers.getSize()(1));

  // Timing and loop control
  rclcpp::Rate loop_rate(30.0);
  rclcpp::Clock steady_clock;

  while (rclcpp::ok()) {
    // Update elevation data for each cell
    rclcpp::Time current_time = node->now();

    for (grid_map::GridMapIterator iter(layers); !iter.isPastEnd(); ++iter) {
      grid_map::Position loc;
      layers.getPosition(*iter, loc);

      double t = current_time.seconds();
      double y = loc.y();
      double x = loc.x();

      layers.at("elevation", *iter) = 
        -0.04 + 0.2 * std::sin(3.0 * t + 5.0 * y) * x;
    }

    // Publish updated map
    layers.setTimestamp(current_time.nanoseconds());
    auto msg_ptr = grid_map::GridMapRosConverter::toMessage(layers);
    map_pub->publish(std::move(msg_ptr));

    RCLCPP_INFO_THROTTLE(node->get_logger(), steady_clock, 1000, "Grid map sent.");
    loop_rate.sleep();
  }

  return 0;
}

