//------------------------------------------------------------------------------
#if defined (MEMCHECK)
static void
handleMemError (
    enum mcheck_status errCode
    ) {
    const char* msg =
        (errCode == MCHECK_DISABLED) ? "Consistency checking is not turned on" :
        (errCode == MCHECK_OK)       ? "Block is fine" :
        (errCode == MCHECK_FREE)     ? "Block freed twice" :
        (errCode == MCHECK_HEAD)     ? "Memory before the block was clobbered" :
        (errCode == MCHECK_TAIL)     ? "Memory after the block was clobbered" :
        "<undefined reason>";
    fprintf(stderr, "ABORT: Malloc check error: %s\n", msg);
    exit(EXIT_FAILURE);
}
#endif

//------------------------------------------------------------------------------
// Entry point
int
main (
    int     argCount,
    char *  argVec [],
    char *  envVec []
    ) {
#if defined (MEMCHECK)
    int rc = mcheck_pedantic (& handleMemError);
    printf ("DEBUG: mcheck_pedantic returns %d\n", rc);
#endif

    try {
        DeltaresHydro * engine = new DeltaresHydro (argCount, argVec, envVec);
        if (!engine->isReady()) {
            delete engine;
            return EXIT_FAILURE;
        }
        engine->Execute();
        delete engine;
        return EXIT_SUCCESS;
    }
    catch (std::exception& ex) {
        std::cerr << "d_hydro ABORT: C++ Exception: " << ex.what() << '\n';
        return EXIT_FAILURE;
    }
    catch (Exception *ex) {
        std::cerr << "d_hydro ABORT: " << ex->message << '\n';
        return EXIT_FAILURE;
    }
    catch (char const* str) {
        std::cerr << "ABORT in FLOW2D3D: " << str << '\n';
        return EXIT_FAILURE;
    }
}

//------------------------------------------------------------------------------
// Constructor: initialize object, parse config, load & invoke start component
DeltaresHydro::DeltaresHydro (
    int     argCount,
    char *  argVec [],
    char *  envVec []
    ) : done(false), ready(false), clock(nullptr), log(nullptr),
        config(nullptr), start(nullptr), startComponent(nullptr),
        mainArgs(nullptr), slaveArg(nullptr), exePath(nullptr), exeName(nullptr) {

    this->exePath = strdup(argVec[0]);

#if defined(HAVE_CONFIG_H)
    this->exeName = strdup(basename(argVec[0]));
#else
    char * extPart = new char[5];
    this->exeName = new char[MAXSTRING];
    _splitpath(argVec[0], nullptr, nullptr, this->exeName, extPart);
    StringCbCatA(this->exeName, MAXSTRING, extPart);
    delete [] extPart;
#endif

    // Reconstruct original command line for spawning slaves
    size_t totalLen = 0;
    for (int idx = 1; idx < argCount; ++idx) {
        totalLen += strlen(argVec[idx]) + 1;
    }
    this->mainArgs = new char[totalLen + 1];
    memset(this->mainArgs, '\0', totalLen + 1);
    char * writePtr = this->mainArgs;
    for (int idx = 1; idx < argCount; ++idx) {
        size_t len = strlen(argVec[idx]);
        memcpy(writePtr, argVec[idx], len);
        writePtr += len;
        *writePtr++ = ' ';
    }

    // Parse options
    int optChar;
    Log::Mask debugLevel = Log::ALWAYS; // default verbosity
    FILE * logStream = stdout;

    while ((optChar = getopt(argCount, argVec, (char *) "d:l:S:v?")) != -1) {
        switch (optChar) {
            case 'd': {
                if (sscanf(optarg, "%i", &debugLevel) != 1)
                    throw new Exception("Invalid log mask (-d option)");
                break;
            }
            case 'l': {
                logStream = fopen(optarg, "w");
                if (!logStream)
                    throw new Exception("Cannot create log file \"%s\"", optarg);
                break;
            }
            case 'S': {
                this->slaveArg = optarg;
                break;
            }
            case 'v': {
                displayInfo(this->exeName);
                this->done = true;
                return;
            }
            case '?': {
                showHelp(this->exeName);
                this->done = true;
                return;
            }
            default: {
                throw new Exception("Invalid command-line argument. Run \"%s -?\" for usage.", this->exeName);
            }
        }
    }

    if (argCount - optind != 1)
        throw new Exception("Improper usage. Run \"%s -?\" for usage.", this->exeName);

    this->clock = new Clock();
    this->log = new Log(logStream, this->clock, debugLevel);

    // Load configuration
    this->configfile = argVec[optind];
    FILE * cfgFile;
    if (strcmp(this->configfile, "-") == 0) {
        cfgFile = stdin;
    } else {
        cfgFile = fopen(this->configfile, "r");
        if (!cfgFile)
            throw new Exception("Cannot open configuration file \"%s\"", this->configfile);
    }
    this->config = new XmlTree(cfgFile);
    fclose(cfgFile);

    // Validate root element
    XmlTree * root = this->config->Lookup("/deltaresHydro");
    if (!root)
        throw new Exception("Configuration file \"%s\" lacks deltaresHydro root element", this->configfile);

    // Default start component
    const char * starterName = "flow2D3D";
    this->start = root->Lookup(starterName);
    if (!this->start)
        throw new Exception("Missing configuration for start component \"%s\"", starterName);

#if defined (MONOLITHIC_FLOW2D3D)
    this->ready = FLOW2D3D_MonolithicInit(this);
#else
    XmlTree * libElem = this->start->Lookup("library");
    if (!libElem)
        throw new Exception("Start component \"%s\" missing library element", starterName);
    const char * libName = libElem->charData;

#if defined (HAVE_CONFIG_H)
#if defined (OSX)
    throw new Exception("ABORT: %s has not been ported to Apple Mac OS/X yet", this->exeName);
#else
    char libPath[PATH_MAX];
    if (strchr(libName, '/') == NULL && strchr(libName, '.') == NULL) {
        snprintf(libPath, sizeof(libPath), "lib%s%s", libName, D3D_PLUGIN_EXT);
        libName = libPath;
    }
    this->log->Write(Log::DETAIL, "Loading start library \"%s\"", libName);
    void * handle = dlopen(libName, RTLD_LAZY);
    if (!handle)
        throw new Exception("Cannot load component library \"%s\": %s", libName, dlerror());
    StartComponentEntry entryPoint = (StartComponentEntry) dlsym(handle, this->startEntry);
    if (!entryPoint)
        throw new Exception("Cannot find function \"%s\" in library \"%s\"", this->startEntry, libName);
    this->log->Write(Log::DETAIL, "Calling entry function in start library");
    this->ready = entryPoint(this);
#endif
#elif defined (WIN32)
    char * dllPath = new char[strlen(libName) + 5];
    if (strchr(libName, '/') == NULL && strchr(libName, '\\') == NULL && strchr(libName, '.') == NULL) {
        sprintf(dllPath, "%s.dll", libName);
        libName = dllPath;
    }
    this->log->Write(Log::DETAIL, "Loading start library \"%s\"", libName);
    HINSTANCE dllHandle = LoadLibraryA(libName);
    if (!dllHandle)
        throw new Exception("Cannot load component library \"%s\". Return code: %lu", libName, GetLastError());
    typedef int (__cdecl *ProcAddr)(LPWSTR);
    ProcAddr entryPoint = (ProcAddr) GetProcAddress(dllHandle, this->startEntry);
    if (!entryPoint)
        throw new Exception("Cannot find function \"%s\" in library \"%s\". Return code: %lu", this->startEntry, libName, GetLastError());
    this->log->Write(Log::DETAIL, "Calling entry function in start library");
    this->ready = entryPoint((LPWSTR) this);
    delete [] dllPath;
#endif
#endif // MONOLITHIC_FLOW2D3D
}

//------------------------------------------------------------------------------
// Destructor
DeltaresHydro::~DeltaresHydro (
    void
    ) {
    if (this->done) return;

    delete this->startComponent;

#if defined(HAVE_CONFIG_H)
    free(this->exeName);
#else
    delete [] this->exeName;
#endif

    this->log->Write(Log::ALWAYS, "d_hydro shutting down normally");
    delete this->clock;
    delete this->config;
    free(this->exePath);
    delete this->log;
    delete [] this->mainArgs;
}

//------------------------------------------------------------------------------
void
DeltaresHydro::Execute (
    void
    ) {
    if (this->done) return;

    try {
        this->startComponent->Run();
    }
    catch (Exception *ex) {
        std::fprintf(stderr, "#### d_hydro ABORT: %s\n", ex->message);
    }
}

