#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, q;
    if (!(cin >> n >> q)) return 0;

    vector<int> arr(n + 1);
    for (int idx = 1; idx <= n; ++idx) {
        cin >> arr[idx];
    }

    // Store queries and process them
    vector<pair<int, int>> operations;
    operations.reserve(2200000);

    vector<int> answer_list(q);
    vector<int> position_map(n + 1);

    // Build position map: value -> index in array
    for (int idx = 1; idx <= n; ++idx) {
        position_map[arr[idx]] = idx;
    }

    long long total_ops = n;

    for (int query_idx = 0; query_idx < q; ++query_idx) {
        int left, right;
        cin >> left >> right;

        // Extract and sort the segment
        vector<int> segment_values;
        segment_values.reserve(right - left + 1);
        for (int j = left; j <= right; ++j) {
            segment_values.push_back(arr[j]);
        }
        sort(segment_values.begin(), segment_values.end());

        if (segment_values.empty()) {
            answer_list[query_idx] = 1;
        } else {
            long long current_pos = position_map[segment_values[0]];

            // Generate operations between consecutive elements
            for (size_t k = 1; k < segment_values.size(); ++k) {
                int next_val = segment_values[k];
                int next_pos = position_map[next_val];

                operations.emplace_back((int)current_pos, next_pos);
                ++total_ops;
                current_pos = total_ops;
            }

            answer_list[query_idx] = (int)current_pos;
        }
    }

    cout << total_ops << "\n";
    for (const auto& op : operations) {
        cout << op.first << " " << op.second << "\n";
    }

    for (int i = 0; i < q; ++i) {
        if (i > 0) cout << " ";
        cout << answer_list[i];
    }
    cout << "\n";

    return 0;
}

