namespace Slic3r
{
// By Florens Waserfall aka @platch:
// This constant essentially describes the volumetric error at the surface which is induced
// by stacking "elliptic" extrusion threads. It is empirically determined by
// 1. measuring the surface profile of printed parts to find
// the ratio between layer height and profile height and then
// 2. computing the geometric difference between the model-surface and the elliptic profile.
//
// The definition of the roughness formula is in
// https://tams.informatik.uni-hamburg.de/publications/2017/Adaptive%20Slicing%20for%20the%20FDM%20Process%20Revisited.pdf
// (page 51, formula (8))
// Currenty @platch's error metric formula is not used.
//static constexpr const double SURFACE_CONST = 0.18403;

// Compute maximum layer height based on surface slope while respecting roughness constraints
static inline float compute_layer_height_from_slope(const SlicingAdaptive::FaceZ &face, float max_deviation)
{
    // Original @platch's formula (not currently used)
    // return float(max_deviation / (SURFACE_CONST + 0.5 * std::abs(normal_z)));

    // Constant stepping in horizontal direction (Cura-style)
    // return (face.n_cos > 1e-5) ? float(max_deviation * face.n_sin / face.n_cos) : FLT_MAX;

    // Triangle area error metric (Vojtech's approach)
    // return (face.n_cos > 1e-5) ? float(1.44 * max_deviation * sqrt(face.n_sin / face.n_cos)) : FLT_MAX;

    // Modified version with clamping for near-vertical surfaces
    if (face.n_cos <= 1e-5)
        return FLT_MAX;

    float adaptive_height = 1.44f * max_deviation * std::sqrt(face.n_sin / face.n_cos);
    float vertical_limit = max_deviation / 0.184f;

    return std::min(adaptive_height, vertical_limit);

    // Alternative: constant stepping along surface (Perez/Pandey et al.)
    // return float(max_deviation * face.n_sin);
}

void SlicingAdaptive::clear()
{
    m_faces.clear();
}

void SlicingAdaptive::prepare(const ModelObject &object)
{
    this->clear();
    TriangleMesh mesh = object.raw_mesh();
    const ModelInstance &first_instance = *object.instances.front();
    mesh.transform(first_instance.get_matrix(), first_instance.is_left_handed());

    // Collect faces from mesh
    m_faces.reserve(mesh.facets_count());
    for (stl_triangle_vertex_indices face : mesh.its.indices)
    {
        stl_vertex vertex[3] = {mesh.its.vertices[face[0]], mesh.its.vertices[face[1]], mesh.its.vertices[face[2]]};
        stl_vertex n = face_normal_normalized(vertex);

        // Calculate Z span of the triangle
        float min_z = std::min(std::min(vertex[0].z(), vertex[1].z()), vertex[2].z());
        float max_z = std::max(std::max(vertex[0].z(), vertex[1].z()), vertex[2].z());

        // Store face data including normal components
        m_faces.emplace_back(FaceZ({{min_z, max_z}, std::abs(n.z()), std::sqrt(n.x() * n.x() + n.y() * n.y())}));
    }

    // Sort faces lexicographically by their Z span
    std::sort(m_faces.begin(), m_faces.end(), 
              [](const FaceZ &f1, const FaceZ &f2) { return f1.z_span < f2.z_span; });
}

// current_facet is in/out parameter, remembers the index of the last face visited
// print_z - the top print surface of the previous layer
// returns height of the next layer
float SlicingAdaptive::next_layer_height(const float print_z, float quality_factor, size_t &current_facet)
{
    float layer_height = static_cast<float>(m_slicing_params.max_layer_height);
    float max_surface_deviation;

    // Determine deviation threshold based on quality factor
#if 0
    // @platch's formula for quality
    double delta_min = SURFACE_CONST * m_slicing_params.min_layer_height;
    double delta_mid = (SURFACE_CONST + 0.5) * m_slicing_params.layer_height;
    double delta_max = (SURFACE_CONST + 0.5) * m_slicing_params.max_layer_height;
#else
    // Vojtech's triangle area error metric
    double delta_min = m_slicing_params.min_layer_height;
    double delta_mid = m_slicing_params.layer_height;
    double delta_max = m_slicing_params.max_layer_height;
#endif

    // Interpolate deviation based on quality factor
    if (quality_factor < 0.5f)
        max_surface_deviation = static_cast<float>(lerp(delta_min, delta_mid, 2.0 * quality_factor));
    else
        max_surface_deviation = static_cast<float>(lerp(delta_max, delta_mid, 2.0 * (1.0 - quality_factor)));

    // Find all facets intersecting the slice-layer
    size_t ordered_id = current_facet;
    {
        bool first_hit = false;
        for (; ordered_id < m_faces.size(); ++ordered_id)
        {
            const std::pair<float, float> &zspan = m_faces[ordered_id].z_span;

            // If facet minimum is above current slice plane, stop searching
            if (zspan.first >= print_z)
                break;

            // If facet maximum is above current slice plane, consider it
            if (zspan.second > print_z)
            {
                if (!first_hit)
                {
                    first_hit = true;
                    current_facet = ordered_id;
                }

                // Skip nearly touching facets to avoid numerical issues
                if (zspan.second < print_z + EPSILON)
                    continue;

                // Update minimum layer height based on this facet
                layer_height = std::min(layer_height, compute_layer_height_from_slope(m_faces[ordered_id], max_surface_deviation));
            }
        }
    }

    // Enforce minimum layer height constraint
    layer_height = std::max(layer_height, static_cast<float>(m_slicing_params.min_layer_height));

    // Check for additional constraints from sloped facets within the proposed layer
    if (layer_height > static_cast<float>(m_slicing_params.min_layer_height))
    {
        for (; ordered_id < m_faces.size(); ++ordered_id)
        {
            const std::pair<float, float> &zspan = m_faces[ordered_id].z_span;

            // Stop if facet minimum is above proposed layer top
            if (zspan.first >= print_z + layer_height)
                break;

            // Skip nearly touching facets
            if (zspan.second < print_z + EPSILON)
                continue;

            // Calculate adjusted height for this facet
            float reduced_height = compute_layer_height_from_slope(m_faces[ordered_id], max_surface_deviation);
            float z_diff = zspan.first - print_z;

            if (reduced_height < z_diff)
            {
                assert(z_diff < layer_height + EPSILON);
#ifdef ADAPTIVE_LAYER_HEIGHT_DEBUG
                BOOST_LOG_TRIVIAL(trace) << "cusp computation, height is reduced from " << layer_height 
                                         << " to " << z_diff << " due to z-diff";
#endif
                layer_height = z_diff;
            }
            else if (reduced_height < layer_height)
            {
#ifdef ADAPTIVE_LAYER_HEIGHT_DEBUG
                BOOST_LOG_TRIVIAL(trace) << "adaptive layer computation: height is reduced from " 
                                         << layer_height << " to " << reduced_height << " due to higher facet";
#endif
                layer_height = reduced_height;
            }
        }

        // Re-enforce minimum layer height constraint
        layer_height = std::max(layer_height, static_cast<float>(m_slicing_params.min_layer_height));
    }

#ifdef ADAPTIVE_LAYER_HEIGHT_DEBUG
    BOOST_LOG_TRIVIAL(trace) << "adaptive layer computation, layer-bottom at z:" << print_z
                             << ", quality_factor:" << quality_factor 
                             << ", resulting layer height:" << layer_height;
#endif

    return layer_height;
}

// Returns distance to next horizontal facet in Z-direction
float SlicingAdaptive::horizontal_facet_distance(float z)
{
    for (size_t i = 0; i < m_faces.size(); ++i)
    {
        std::pair<float, float> zspan = m_faces[i].z_span;

        // Stop if we've passed maximum search range
        if (zspan.first > z + m_slicing_params.max_layer_height)
            break;

        // Found horizontal facet above current Z
        if (zspan.first > z && zspan.first == zspan.second)
            return zspan.first - z;
    }

    // No horizontal facet found within range
    float max_height = m_slicing_params.max_layer_height;
    float object_top = m_slicing_params.object_print_z_height();

    return (z + max_height > object_top) 
           ? std::max(object_top - z, 0.0f) 
           : max_height;
}
