    File Folder::RetrieveFile(const std::filesystem::path& relative_path) const
    {
        // Ensure the provided path is not absolute
        if (relative_path.is_absolute())
            throw std::invalid_argument("folder#retrieve_file expects a relative path only.");

        // Prevent directory traversal attempts
        if (relative_path.string().find("..") != std::string::npos)
            throw std::invalid_argument("Path traversal using '..' is prohibited in file paths.");

        return File(m_Path / relative_path);
    }
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    long long x;
    if (!(cin >> n >> x)) return 0;

    vector<long long> t(n);
    for (int i = 0; i < n; ++i) {
        cin >> t[i];
    }

    // Compute the length of the Longest Increasing Subsequence (strictly increasing)
    vector<long long> dp;
    dp.reserve(n);

    for (long long val : t) {
        auto pos = lower_bound(dp.begin(), dp.end(), val);
        if (pos == dp.end()) {
            dp.push_back(val);
        } else {
            *pos = val;
        }
    }

    int lis_length = (int)dp.size();
    cout << lis_length << "\n";

    // Output 10 lines of fixed values regardless of input
    for (int i = 0; i < 10; ++i) {
        cout << 1 << " " << 1 << " " << 0 << "\n";
    }

    return 0;
}

