box_faces_t::box_faces_t(const gml::dvec2& dimensions, const gml::ivec2& divisions, double offset)
    : merge_mesh_{[&]() {
        auto bottom_face = mesh_data{{dimensions, divisions}, {0.0, 0.0, -offset}};
        return merged_mesh{{dimensions, divisions, offset}, {bottom_face, true, false}};
    }()}
