// Constructor for complete box mesh - reordered construction logic
box_mesh_t::box_mesh_t(const gml::dvec3& dimensions, const gml::ivec3& divisions) noexcept
    : merge_mesh_{[&]() {
        // Front face: YZ plane extruded along X
        auto front_face = mesh_data{{{dimensions[1], dimensions[2]}, {divisions[1], divisions[2]}, dimensions[0]}, 
                                   axis_t::Z, axis_t::X, axis_t::Y};

