        // Top face: XY plane extruded along Z
        auto top_face = mesh_data{{{dimensions[0], dimensions[1]}, {divisions[0], divisions[1]}, dimensions[2]}};

        return merged_mesh{front_face, {side_face, true, false}, top_face};
