namespace {

// Helper structure to track mapping between original and transformed globals
struct GlobalAliasRecord {
  GlobalVariable *original;
  GlobalVariable *replacement;
};

// Internal utility class for handling constant expression rewriting
struct ConstantRewriter {
  Module *mod;
  Function *func;
  IRBuilder<> &builder;
  ValueMap<GlobalVariable *, GlobalVariable *> &gvMap;
  ValueMap<Constant *, Value *> &constCache;

  ConstantRewriter(Module *M, Function *F, IRBuilder<> &B,
                   ValueMap<GlobalVariable *, GlobalVariable *> &GVM,
                   ValueMap<Constant *, Value *> &CC)
      : mod(M), func(F), builder(B), gvMap(GVM), constCache(CC) {}

  Value *process(Constant *C);
  Value *handleAggregateOrVector(Constant *C);
  Value *handleExpr(ConstantExpr *CE);
};

class GenericToNVVMTransformer {
public:
  bool processModule(Module &M);

private:
  ValueMap<GlobalVariable *, GlobalVariable *> globalVarMap;
  ValueMap<Constant *, Value *> constantRemap;
};

} // end anonymous namespace

bool GenericToNVVMTransformer::processModule(Module &M) {
  // Phase 1: Clone global variables in generic address space into global space
  SmallVector<GlobalAliasRecord, 8> clonedGlobals;
  for (GlobalVariable &GV : M.globals()) {
    if (GV.getType()->getAddressSpace() == ADDRESS_SPACE_GENERIC &&
        !isTexture(GV) && !isSurface(GV) && !isSampler(GV) &&
        !GV.getName().starts_with("llvm.")) {
      GlobalVariable *newGV = new GlobalVariable(
          M, GV.getValueType(), GV.isConstant(), GV.getLinkage(),
          GV.hasInitializer() ? GV.getInitializer() : nullptr, "", &GV,
          GV.getThreadLocalMode(), ADDRESS_SPACE_GLOBAL);
      newGV->copyAttributesFrom(&GV);
      newGV->copyMetadata(&GV, /*Offset=*/0);
      globalVarMap[&GV] = newGV;
      clonedGlobals.push_back({&GV, newGV});
    }
  }

  if (clonedGlobals.empty())
    return false;

  // Phase 2: Replace uses inside function bodies
  for (Function &F : M) {
    if (F.isDeclaration())
      continue;

    BasicBlock &entryBB = F.getEntryBlock();
    Instruction *firstInst = entryBB.getFirstNonPHIOrDbg();
    IRBuilder<> builder(firstInst);

    for (BasicBlock &BB : F) {
      for (Instruction &II : BB) {
        unsigned numOps = II.getNumOperands();
        for (unsigned idx = 0; idx < numOps; ++idx) {
          Value *op = II.getOperand(idx);
          if (Constant *c = dyn_cast<Constant>(op)) {
            ConstantRewriter rewriter(&M, &F, builder, globalVarMap,
                                      constantRemap);
            II.setOperand(idx, rewriter.process(c));
          }
        }
      }
    }
    constantRemap.clear();
  }

  // Phase 3: Update global initializers and replace old globals
  ValueToValueMapTy valueMap;
  for (auto &pair : globalVarMap)
    valueMap[pair.first] = pair.second;

  for (size_t i = 0; i < clonedGlobals.size(); ++i) {
    GlobalVariable *orig = clonedGlobals[i].original;
    GlobalVariable *clone = clonedGlobals[i].replacement;

    Constant *castedClone =
        ConstantExpr::getPointerCast(clone, orig->getType());
    orig->replaceAllUsesWith(castedClone);

    std::string name = orig->getName().str();
    orig->eraseFromParent();
    clone->setName(name);
  }

  assert(globalVarMap.empty() && "All entries should have been processed");
  return true;
}

Value *GenericToNVVMTransformer::processConstant(Constant *C, Module *M,
                                                 Function *F,
                                                 IRBuilder<> &Builder) {
  auto it = constantRemap.find(C);
  if (it != constantRemap.end())
    return it->second;

  Value *result = C;

  if (GlobalVariable *GV = dyn_cast<GlobalVariable>(C)) {
    auto mapIt = globalVarMap.find(GV);
    if (mapIt != globalVarMap.end()) {
      GlobalVariable *newGV = mapIt->second;
      Type *genericPtrTy = PointerType::get(newGV->getValueType(),
                                            ADDRESS_SPACE_GENERIC);
      result = Builder.CreateAddrSpaceCast(newGV, genericPtrTy);
    }
  } else if (isa<ConstantAggregate>(C)) {
    ConstantRewriter rewriter(M, F, Builder, globalVarMap, constantRemap);
    result = rewriter.handleAggregateOrVector(C);
  } else if (ConstantExpr *CE = dyn_cast<ConstantExpr>(C)) {
    ConstantRewriter rewriter(M, F, Builder, globalVarMap, constantRemap);
    result = rewriter.handleExpr(CE);
  }

  constantRemap[C] = result;
  return result;
}

Value *ConstantRewriter::process(Constant *C) {
  return parent.processConstant(C, mod, func, builder);
}

Value *ConstantRewriter::handleAggregateOrVector(Constant *C) {
  bool changed = false;
  SmallVector<Value *, 4> newOps;
  unsigned count = C->getNumOperands();

  for (unsigned i = 0; i < count; ++i) {
    Constant *op = cast<Constant>(C->getOperand(i));
    Value *newOp = process(op);
    changed |= (newOp != op);
    newOps.push_back(newOp);
  }

  if (!changed)
    return C;

  Value *res = PoisonValue::get(C->getType());
  if (isa<ConstantVector>(C)) {
    for (unsigned i = 0; i < count; ++i) {
      Value *idx = ConstantInt::get(Type::getInt32Ty(mod->getContext()), i);
      res = builder.CreateInsertElement(res, newOps[i], idx);
    }
  } else {
    for (unsigned i = 0; i < count; ++i) {
      res = builder.CreateInsertValue(res, newOps[i], {i});
    }
  }
  return res;
}

Value *ConstantRewriter::handleExpr(ConstantExpr *CE) {
  bool changed = false;
  SmallVector<Value *, 4> newOps;
  unsigned count = CE->getNumOperands();

  for (unsigned i = 0; i < count; ++i) {
    Constant *op = cast<Constant>(CE->getOperand(i));
    Value *newOp = process(op);
    changed |= (newOp != op);
    newOps.push_back(newOp);
  }

  if (!changed)
    return CE;

  unsigned opcode = CE->getOpcode();
  switch (opcode) {
  case Instruction::ICmp:
    return builder.CreateICmp(CE->getPredicate(), newOps[0], newOps[1]);
  case Instruction::ExtractElement:
    return builder.CreateExtractElement(newOps[0], newOps[1]);
  case Instruction::InsertElement:
    return builder.CreateInsertElement(newOps[0], newOps[1], newOps[2]);
  case Instruction::ShuffleVector:
    return builder.CreateShuffleVector(newOps[0], newOps[1], newOps[2]);
  case Instruction::GetElementPtr: {
    GEPOperator *GEP = cast<GEPOperator>(CE);
    ArrayRef<Value *> indices(&newOps[1], count - 1);
    return builder.CreateGEP(GEP->getSourceElementType(), newOps[0], indices,
                             "", GEP->isInBounds());
  }
  case Instruction::Select:
    return builder.CreateSelect(newOps[0], newOps[1], newOps[2]);
  default:
    if (Instruction::isBinaryOp(opcode)) {
      return builder.CreateBinOp(static_cast<Instruction::BinaryOps>(opcode),
                                 newOps[0], newOps[1]);
    }
    if (Instruction::isCast(opcode)) {
      return builder.CreateCast(static_cast<Instruction::CastOps>(opcode),
                                newOps[0], CE->getType());
    }
    llvm_unreachable("Unsupported constant expression in transformation");
  }
}

