using namespace std;

// Definition for a binary tree node.
struct TreeNode {
    int val;
    TreeNode *left;
    TreeNode *right;
    TreeNode() : val(0), left(nullptr), right(nullptr) {}
    TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
    TreeNode(int x, TreeNode *l, TreeNode *r) : val(x), left(l), right(r) {}
};

class Solution {
public:
    int accumulatedSum = 0;

    void traverseInOrder(TreeNode* node, int minBound, int maxBound) {
        if (node == nullptr) return;

        // Traverse left subtree only if current value is greater than lower bound
        if (node->val > minBound) {
            traverseInOrder(node->left, minBound, maxBound);
        }

        // Add current node's value if it lies within the specified range
        if (node->val >= minBound && node->val <= maxBound) {
            accumulatedSum += node->val;
        }

        // Traverse right subtree only if current value is less than upper bound
        if (node->val < maxBound) {
            traverseInOrder(node->right, minBound, maxBound);
        }
    }

    int calculateRangeSum(TreeNode* root, int low, int high) {
        accumulatedSum = 0; // Reset the accumulator before traversal
        traverseInOrder(root, low, high);
        return accumulatedSum;
    }
};

int main() {
    // Constructing the example BST:
    //       10
    //      /  \
    //     5    15
    //    / \     \
    //   3   7     18

    TreeNode* root = new TreeNode(10);
    root->left = new TreeNode(5);
    root->right = new TreeNode(15);
    root->left->left = new TreeNode(3);
    root->left->right = new TreeNode(7);
    root->right->right = new TreeNode(18);

    Solution solver;
    int lowerLimit = 7;
    int upperLimit = 15;
    int sumResult = solver.calculateRangeSum(root, lowerLimit, upperLimit);

    cout << "Range Sum BST: " << sumResult << endl; // Expected output: 32 (7 + 10 + 15)
    return 0;
}

