using namespace std;

int main() {
    // Initialize vectors in various ways
    vector<int> original;
    vector<int> filled(5, 10);        // 5 elements, each set to 10
    vector<int> initialized = {1, 2, 3, 4, 5};
    vector<int> copied(initialized);  // copy constructor

    // Fill 'original' with numbers 1 through 10
    for (int i = 1; i <= 10; ++i) {
        original.push_back(i);
    }

    // Print using range-based for loop
    for (int val : original) {
        cout << val << " ";
    }
    cout << endl;

    // Modify the vector: remove last element, add new one at end
    original.pop_back();
    original.emplace_back(10);

    // Access specific elements
    cout << "value at 5th index: " << original.at(5) << endl;
    cout << "first element: " << original.front() << endl;
    cout << "last element: " << original.back() << endl;

    // Remove last element again and check size/capacity
    original.pop_back();
    cout << "size: " << original.size() << endl;
    cout << "capacity: " << original.capacity() << endl;
    cout << "max possible size: " << original.max_size() << endl;

    // Erase elements by position
    original.erase(original.begin() + 2);           // erase 3rd element
    original.erase(original.begin() + 2, original.begin() + 4); // erase 3rd-4th elements

    // Clear all elements
    original.clear();
    cout << "is empty? " << (original.empty() ? "yes" : "no") << endl;

    // Insert element at front
    original.insert(original.begin(), 5);

    // Demonstrate iterators
    vector<int> testVec = {1, 2, 3, 4, 5};
    vector<int>::iterator iter;
    for (iter = testVec.begin(); iter != testVec.end(); ++iter) {
        cout << *iter << " ";
    }
    cout << endl;

    // Demonstrate reverse iterators
    vector<int>::reverse_iterator rIter;
    for (rIter = testVec.rbegin(); rIter != testVec.rend(); ++rIter) {
        cout << *rIter << " ";
    }
    cout << endl;

    return 0;
}

