namespace eld {

// Helper function to configure and emulate RISC-V ELF settings
static bool ConfigureAndEmulateRISCV(LinkerScript& script, LinkerConfig& config) {
  // Set endianness: RISC-V currently supports little-endian only
  config.targets().setEndian(TargetOptions::Little);

  // Determine bit class based on architecture string
  const std::string arch = config.targets().getArch();
  if (arch == "riscv32")
    config.targets().setBitClass(32);
  else if (arch == "riscv64")
    config.targets().setBitClass(64);

  // Delegate to generic ELF emulation; return false on failure
  if (!ELDEmulateELF(script, config))
    return false;

  return true;
}

//===----------------------------------------------------------------------===//
// emulateRISCVLD - public entry point for RISC-V linker emulation
//===----------------------------------------------------------------------===//
bool emulateRISCVLD(LinkerScript& script, LinkerConfig& config) {
  return ConfigureAndEmulateRISCV(script, config);
}

} // namespace eld

//===----------------------------------------------------------------------===//
// ELDInitializeRISCVEmulation - registration of RISC-V emulations
//===----------------------------------------------------------------------===//
extern "C" void ELDInitializeRISCVEmulation() {
  using namespace eld;

  // Register emulation handlers for both 32-bit and 64-bit RISC-V targets
  TargetRegistry::RegisterEmulation(TheRISCV32Target, emulateRISCVLD);
  TargetRegistry::RegisterEmulation(TheRISCV64Target, emulateRISCVLD);
}

