    void AddToLiveIns(MCRegister Reg, MachineLoop *CurLoop);

    // Hoistability checks
    bool CanBeHoisted(MachineInstr &I, MachineLoop *CurLoop);
    bool IsLoopInvariant(MachineInstr &I, MachineLoop *CurLoop);
    bool HasPHIUser(const MachineInstr *MI, MachineLoop *CurLoop);

    // Latency and cost analysis
    bool HasHighLatencyUse(MachineInstr &MI, unsigned DefIdx, Register Reg,
                               MachineLoop *CurLoop) const;
    bool IsTrivialCost(MachineInstr &MI) const;

    // Register pressure evaluation
    bool WouldIncreasePressure(const DenseMap<unsigned, int> &Cost,
                                 bool IsCheap);
    void UpdatePathPressure(const MachineInstr *MI);

    // Profitability determination
    bool ShouldHoist(MachineInstr &MI, MachineLoop *CurLoop);

    // Execution guarantees
    bool BlockAlwaysExecutes(MachineBasicBlock *BB, MachineLoop *CurLoop);

    // Rematerialization check
    bool CanRemat(const MachineInstr &MI) const;

    // Scope management for dominator tree traversal
    void EnterScope(MachineBasicBlock *MBB);
    void ExitScope(MachineBasicBlock *MBB);
    void CompleteScope(
        MachineDomTreeNode *Node,
        DenseMap<MachineDomTreeNode *, unsigned> &OpenChildren,
        const DenseMap<MachineDomTreeNode *, MachineDomTreeNode *> &ParentMap);

    // Main hoisting logic
    void ProcessLoopBody(MachineDomTreeNode *HeaderN, MachineLoop *CurLoop,
                        MachineBasicBlock *CurPreheader);

    // Pressure initialization
    void InitializePressure(MachineBasicBlock *BB);

    // Cost calculation
    DenseMap<unsigned, int> CalculateRegCost(const MachineInstr *MI,
                                             bool TrackSeen,
                                             bool TreatUnseenAsDef);

    // Update pressure after instruction
    void AdjustPressure(const MachineInstr *MI,
                           bool TreatUnseenAsDef = false);

    // Load extraction and CSE
    MachineInstr *ExtractLoadForHoisting(MachineInstr *MI, MachineLoop *CurLoop);
    MachineInstr *FindDuplicate(const MachineInstr *MI,
                                   std::vector<MachineInstr *> &PrevMIs);

    bool PerformCSE(MachineInstr *MI,
                 DenseMap<unsigned, std::vector<MachineInstr *>>::iterator &CI);

    bool CanShareComputation(MachineInstr *MI);

    // Actual hoisting operation
    unsigned PerformHoist(MachineInstr *MI, MachineBasicBlock *Preheader,
                   MachineLoop *CurLoop);

    // CSE table setup
    void SetupCSETable(MachineBasicBlock *BB);

    // Load hoisting initialization
    void PrepareLoadHoistingLoops();

    // Hotness comparison
    bool IsTargetHotter(MachineBasicBlock *SrcBlock,
                            MachineBasicBlock *TgtBlock);

    // Preheader retrieval
    MachineBasicBlock *GetLoopPreheader(MachineLoop *CurLoop,
                                       MachineBasicBlock *CurPreheader);

    // Helper methods
    bool IsExitBlock(MachineLoop *CurLoop, const MachineBasicBlock *MBB) {
      if (ExitBlockCache.contains(CurLoop))
        return is_contained(ExitBlockCache[CurLoop], MBB);

      SmallVector<MachineBasicBlock *, 8> Exits;
      CurLoop->getExitBlocks(Exits);
      ExitBlockCache[CurLoop] = Exits;
      return is_contained(Exits, MBB);
    }
  };

