// Implementation of helper function for frame index checking
static bool StoresToFrameIndex(const MachineInstr *MI, int FI) {
  if (!MI->mayStore())
     return false;

  if (MI->memoperands_empty())
    return true;

  for (const MachineMemOperand *MemOp : MI->memoperands()) {
    if (!MemOp->isStore() || !MemOp->getPseudoValue())
      continue;
    if (const FixedStackPseudoSourceValue *Value =
        dyn_cast<FixedStackPseudoSourceValue>(MemOp->getPseudoValue())) {
      if (Value->getFrameIndex() == FI)
        return true;
    }
  }
  return false;
}

bool MachineLICMBase::runOnMachineFunction(MachineFunction &MF) {
  if (skipFunction(MF.getFunction()))
    return false;

  TransformDone = FirstOperation = false;

  const TargetSubtargetInfo &ST = MF.getSubtarget();
  TII = ST.getInstrInfo();
  TLI = ST.getTargetLowering();
  TRI = ST.getRegisterInfo();
  MFI = &MF.getFrameInfo();
  MRI = &MF.getRegInfo();
  SchedModel.init(&ST);

  PreRegAllocPhase = MRI->isSSA();
  HasProfileData = MF.getFunction().hasProfileData();

  if (PreRegAllocPhase)
    LLVM_DEBUG(dbgs() << "******** Pre-regalloc Machine LICM: ");
  else
    LLVM_DEBUG(dbgs() << "******** Post-regalloc Machine LICM: ");

  LLVM_DEBUG(dbgs() << MF.getName() << " ********\n");

  if (PreRegAllocPhase) {
    unsigned NumPSets = TRI->getNumRegPressureSets();
    CurrentPressure.resize(NumPSets);
    std::fill(CurrentPressure.begin(), CurrentPressure.end(), 0);
    PressureLimits.resize(NumPSets);
    for (unsigned i = 0, e = NumPSets; i != e; ++i)
      PressureLimits[i] = TRI->getRegPressureSetLimit(MF, i);
  }

  if (DisableHoistingToHotterBlocks != HotnessPolicy::None)
    MBFI = &getAnalysis<MachineBlockFrequencyInfo>();

  MLI = &getAnalysis<MachineLoopInfo>();
  DT  = &getAnalysis<MachineDominatorTree>();
  AA = &getAnalysis<AAResultsWrapperPass>().getAAResults();

  if (HoistConstLoads)
    PrepareLoadHoistingLoops();

  SmallVector<MachineLoop *, 8> Worklist(MLI->begin(), MLI->end());
  while (!Worklist.empty()) {
    MachineLoop *CurLoop = Worklist.pop_back_val();
    MachineBasicBlock *CurPreheader = nullptr;

    if (!PreRegAllocPhase)
      HoistRegionPostRA(CurLoop, CurPreheader);
    else {
      MachineDomTreeNode *N = DT->getNode(CurLoop->getHeader());
      FirstOperation = true;
      ProcessLoopBody(N, CurLoop, CurPreheader);
      CSETable.clear();
    }
  }

  return TransformDone;
}

void MachineLICMBase::ProcessInstruction(MachineInstr *MI, BitVector &PhysRegDefs,
                                BitVector &PhysRegClobbers,
                                SmallSet<int, 32> &StoredFIs,
                                SmallVectorImpl<HoistCandidate> &Candidates,
                                MachineLoop *CurLoop) {
  bool RuledOut = false;
  bool HasNonInvariantUse = false;
  unsigned Def = 0;

  for (const MachineOperand &MO : MI->operands()) {
    if (MO.isFI()) {
      int FI = MO.getIndex();
      if (!StoredFIs.count(FI) &&
          MFI->isSpillSlotObjectIndex(FI) &&
          StoresToFrameIndex(MI, FI))
        StoredFIs.insert(FI);
      HasNonInvariantUse = true;
      continue;
    }

    if (MO.isRegMask()) {
      PhysRegClobbers.setBitsNotInMask(MO.getRegMask());
      continue;
    }

    if (!MO.isReg())
      continue;

    Register Reg = MO.getReg();
    if (!Reg)
      continue;

    assert(Reg.isPhysical() && "Not expecting virtual register!");

    if (!MO.isDef()) {
      if (Reg && (PhysRegDefs.test(Reg) || PhysRegClobbers.test(Reg)))
        HasNonInvariantUse = true;
      continue;
    }

    if (MO.isImplicit()) {
      for (MCRegAliasIterator AI(Reg, TRI, true); AI.isValid(); ++AI)
        PhysRegClobbers.set(*AI);

      if (!MO.isDead())
        RuledOut = true;
      continue;
    }

    if (Def)
      RuledOut = true;
    else
      Def = Reg;

    for (MCRegAliasIterator AS(Reg, TRI, true); AS.isValid(); ++AS) {
      if (PhysRegDefs.test(*AS))
        PhysRegClobbers.set(*AS);
    }

    for (MCRegAliasIterator AS(Reg, TRI, true); AS.isValid(); ++AS)
      PhysRegDefs.set(*AS);

    if (PhysRegClobbers.test(Reg))
      RuledOut = true;
  }

  if (Def && !RuledOut) {
    int FI = std::numeric_limits<int>::min();
    if ((!HasNonInvariantUse && CanBeHoisted(*MI, CurLoop)) ||
        (TII->isLoadFromStackSlot(*MI, FI) && MFI->isSpillSlotObjectIndex(FI)))
      Candidates.push_back(HoistCandidate(MI, Def, FI));
  }
}

void MachineLICMBase::HoistRegionPostRA(MachineLoop *CurLoop,
                                        MachineBasicBlock *CurPreheader) {
  MachineBasicBlock *Preheader = GetLoopPreheader(CurLoop, CurPreheader);
  if (!Preheader)
    return;

  unsigned NumRegs = TRI->getNumRegs();
  BitVector PhysRegDefs(NumRegs);
  BitVector PhysRegClobbers(NumRegs);
  SmallVector<HoistCandidate, 32> Candidates;
  SmallSet<int, 32> StoredFIs;

  for (MachineBasicBlock *BB : CurLoop->getBlocks()) {
    const MachineLoop *ML = MLI->getLoopFor(BB);
    if (ML && ML->getHeader()->isEHPad()) continue;

    for (const auto &LI : BB->liveins()) {
      for (MCRegAliasIterator AI(LI.PhysReg, TRI, true); AI.isValid(); ++AI)
        PhysRegDefs.set(*AI);
    }

    if (const uint32_t *Mask = BB->getBeginClobberMask(TRI))
      PhysRegClobbers.setBitsNotInMask(Mask);

    CurrentSpeculationState = SpeculationState::Unknown;

    for (MachineInstr &MI : *BB)
      ProcessInstruction(&MI, PhysRegDefs, PhysRegClobbers, StoredFIs, Candidates,
                CurLoop);
  }

  BitVector TermRegs(NumRegs);
  MachineBasicBlock::iterator TI = Preheader->getFirstTerminator();
  if (TI != Preheader->end()) {
    for (const MachineOperand &MO : TI->operands()) {
      if (!MO.isReg())
        continue;
      Register Reg = MO.getReg();
      if (!Reg)
        continue;
      for (MCRegAliasIterator AI(Reg, TRI, true); AI.isValid(); ++AI)
        TermRegs.set(*AI);
    }
  }

  for (HoistCandidate &Candidate : Candidates) {
    if (Candidate.FrameIdx != std::numeric_limits<int>::min() &&
        StoredFIs.count(Candidate.FrameIdx))
      continue;

    unsigned Def = Candidate.DestinationReg;
    if (!PhysRegClobbers.test(Def) && !TermRegs.test(Def)) {
      bool Safe = true;
      MachineInstr *MI = Candidate.Instruction;
      for (const MachineOperand &MO : MI->all_uses()) {
        if (!MO.getReg())
          continue;
        Register Reg = MO.getReg();
        if (PhysRegDefs.test(Reg) ||
            PhysRegClobbers.test(Reg)) {
          Safe = false;
          break;
        }
      }
      if (Safe)
        HoistPostRA(MI, Candidate.DestinationReg, CurLoop, CurPreheader);
    }
  }
}

void MachineLICMBase::AddToLiveIns(MCRegister Reg, MachineLoop *CurLoop) {
  for (MachineBasicBlock *BB : CurLoop->getBlocks()) {
    if (!BB->isLiveIn(Reg))
      BB->addLiveIn(Reg);

    for (MachineInstr &MI : *BB) {
      for (MachineOperand &MO : MI.all_uses()) {
        if (!MO.getReg())
          continue;
        if (TRI->regsOverlap(Reg, MO.getReg()))
          MO.setIsKill(false);
      }
    }
  }
}

void MachineLICMBase::HoistPostRA(MachineInstr *MI, unsigned Def,
                                  MachineLoop *CurLoop,
                                  MachineBasicBlock *CurPreheader) {
  MachineBasicBlock *Preheader = GetLoopPreheader(CurLoop, CurPreheader);

  LLVM_DEBUG(dbgs() << "Hoisting to " << printMBBReference(*Preheader)
                    << " from " << printMBBReference(*MI->getParent()) << ": "
                    << *MI);

  MachineBasicBlock *MBB = MI->getParent();
  Preheader->splice(Preheader->getFirstTerminator(), MBB, MI);

  assert(!MI->isDebugInstr() && "Should not hoist debug inst");
  MI->setDebugLoc(DebugLoc());

  AddToLiveIns(Def, CurLoop);
  ++NumPostRAHoisted;
  TransformDone = true;
}

bool MachineLICMBase::BlockAlwaysExecutes(MachineBasicBlock *BB,
                                            MachineLoop *CurLoop) {
  if (CurrentSpeculationState != SpeculationState::Unknown)
    return CurrentSpeculationState == SpeculationState::Unsafe;

  if (BB != CurLoop->getHeader()) {
    SmallVector<MachineBasicBlock*, 8> ExitingBlocks;
    CurLoop->getExitingBlocks(ExitingBlocks);
    for (MachineBasicBlock *ExitingBlock : ExitingBlocks)
      if (!DT->dominates(BB, ExitingBlock)) {
        CurrentSpeculationState = SpeculationState::Safe;
        return false;
      }
  }

  CurrentSpeculationState = SpeculationState::Unsafe;
  return true;
}

bool MachineLICMBase::CanRemat(const MachineInstr &MI) const {
  if (!TII->isTriviallyReMaterializable(MI))
    return false;

  for (const MachineOperand &MO : MI.all_uses()) {
    if (MO.getReg().isVirtual())
      return false;
  }
  return true;
}

void MachineLICMBase::EnterScope(MachineBasicBlock *MBB) {
  LLVM_DEBUG(dbgs() << "Entering " << printMBBReference(*MBB) << '\n');
  PathPressure.push_back(CurrentPressure);
}

void MachineLICMBase::ExitScope(MachineBasicBlock *MBB) {
  LLVM_DEBUG(dbgs() << "Exiting " << printMBBReference(*MBB) << '\n');
  PathPressure.pop_back();
}

void MachineLICMBase::CompleteScope(MachineDomTreeNode *Node,
    DenseMap<MachineDomTreeNode*, unsigned> &OpenChildren,
    const DenseMap<MachineDomTreeNode*, MachineDomTreeNode*> &ParentMap) {
  if (OpenChildren[Node])
    return;

  for(;;) {
    ExitScope(Node->getBlock());
    MachineDomTreeNode *Parent = ParentMap.lookup(Node);
    if (!Parent || --OpenChildren[Parent] != 0)
      break;
    Node = Parent;
  }
}

void MachineLICMBase::ProcessLoopBody(MachineDomTreeNode *HeaderN,
                                     MachineLoop *CurLoop,
                                     MachineBasicBlock *CurPreheader) {
  MachineBasicBlock *Preheader = GetLoopPreheader(CurLoop, CurPreheader);
  if (!Preheader)
    return;

  SmallVector<MachineDomTreeNode*, 32> ScopeNodes;
  SmallVector<MachineDomTreeNode*, 8> WorkList;
  DenseMap<MachineDomTreeNode*, MachineDomTreeNode*> ParentMap;
  DenseMap<MachineDomTreeNode*, unsigned> OpenChildren;

  WorkList.push_back(HeaderN);
  while (!WorkList.empty()) {
    MachineDomTreeNode *Node = WorkList.pop_back_val();
    assert(Node && "Null dominator tree node?");
    MachineBasicBlock *BB = Node->getBlock();

    const MachineLoop *ML = MLI->getLoopFor(BB);
    if (ML && ML->getHeader()->isEHPad())
      continue;

    if (!CurLoop->contains(BB))
      continue;

    ScopeNodes.push_back(Node);
    unsigned NumChildren = Node->getNumChildren();

    if (BB->succ_size() >= 25)
      NumChildren = 0;

    OpenChildren[Node] = NumChildren;
    if (NumChildren) {
      for (MachineDomTreeNode *Child : reverse(Node->children())) {
        ParentMap[Child] = Node;
        WorkList.push_back(Child);
      }
    }
  }

  if (ScopeNodes.size() == 0)
    return;

  SeenRegisters.clear();
  PathPressure.clear();
  InitializePressure(Preheader);

  for (MachineDomTreeNode *Node : ScopeNodes) {
    MachineBasicBlock *MBB = Node->getBlock();
    EnterScope(MBB);

    CurrentSpeculationState = SpeculationState::Unknown;

    for (MachineInstr &MI : llvm::make_early_inc_range(*MBB)) {
      unsigned Result = MoveStatus::Failed;
      Result = PerformHoist(&MI, Preheader, CurLoop);

      if (Result == MoveStatus::Failed) {
        SmallVector<MachineLoop *> InnerLoops;
        for (MachineLoop *L = MLI->getLoopFor(MI.getParent()); L != CurLoop;
             L = L->getParentLoop())
          InnerLoops.push_back(L);

        while (!InnerLoops.empty()) {
          MachineLoop *InnerLoop = InnerLoops.pop_back_val();
          MachineBasicBlock *InnerPreheader = InnerLoop->getLoopPreheader();
          if (InnerPreheader) {
            Result = PerformHoist(&MI, InnerPreheader, InnerLoop);
            if (Result & MoveStatus::Success)
              break;
          }
        }
      }

      if (Result & MoveStatus::Removed)
        continue;

      AdjustPressure(&MI);
    }

    CompleteScope(Node, OpenChildren, ParentMap);
  }
}

static bool IsOperandKilled(const MachineOperand &MO, MachineRegisterInfo *MRI) {
  return MO.isKill() || MRI->hasOneNonDBGUse(MO.getReg());
}

void MachineLICMBase::InitializePressure(MachineBasicBlock *BB) {
  std::fill(CurrentPressure.begin(), CurrentPressure.end(), 0);

  if (BB->pred_size() == 1) {
    MachineBasicBlock *TBB = nullptr, *FBB = nullptr;
    SmallVector<MachineOperand, 4> Cond;
    if (!TII->analyzeBranch(*BB, TBB, FBB, Cond, false) && Cond.empty())
      InitializePressure(*BB->pred_begin());
  }

  for (const MachineInstr &MI : *BB)
    AdjustPressure(&MI, /*ConsiderUnseenAsDef=*/true);
}

void MachineLICMBase::AdjustPressure(const MachineInstr *MI,
                                        bool ConsiderUnseenAsDef) {
  auto Cost = CalculateRegCost(MI, /*ConsiderSeen=*/true, ConsiderUnseenAsDef);
  for (const auto &RPIdAndCost : Cost) {
    unsigned Class = RPIdAndCost.first;
    if (static_cast<int>(CurrentPressure[Class]) < -RPIdAndCost.second)
      CurrentPressure[Class] = 0;
    else
      CurrentPressure[Class] += RPIdAndCost.second;
  }
}

DenseMap<unsigned, int>
MachineLICMBase::CalculateRegCost(const MachineInstr *MI, bool ConsiderSeen,
                                  bool ConsiderUnseenAsDef) {
  DenseMap<unsigned, int> Cost;
  if (MI->isImplicitDef())
    return Cost;

  for (unsigned i = 0, e = MI->getDesc().getNumOperands(); i != e; ++i) {
    const MachineOperand &MO = MI->getOperand(i);
    if (!MO.isReg() || MO.isImplicit())
      continue;

    Register Reg = MO.getReg();
    if (!Reg.isVirtual())
      continue;

    bool isNew = ConsiderSeen ? SeenRegisters.insert(Reg).second : false;
    const TargetRegisterClass *RC = MRI->getRegClass(Reg);
    RegClassWeight W = TRI->getRegClassWeight(RC);
    int RCCost = 0;

    if (MO.isDef())
      RCCost = W.RegWeight;
    else {
      bool isKill = IsOperandKilled(MO, MRI);
      if (isNew && !isKill && ConsiderUnseenAsDef)
        RCCost = W.RegWeight;
      else if (!isNew && isKill)
        RCCost = -W.RegWeight;
    }

    if (RCCost == 0)
      continue;

    const int *PS = TRI->getRegClassPressureSets(RC);
    for (; *PS != -1; ++PS) {
      if (!Cost.contains(*PS))
        Cost[*PS] = RCCost;
      else
        Cost[*PS] += RCCost;
    }
  }
  return Cost;
}

static bool LoadsFromGOTOrConstantPool(MachineInstr &MI) {
  assert(MI.mayLoad() && "Expected MI that loads!");

  if (MI.memoperands_empty())
    return true;

  for (MachineMemOperand *MemOp : MI.memoperands())
    if (const PseudoSourceValue *PSV = MemOp->getPseudoValue())
      if (PSV->isGOT() || PSV->isConstantPool())
        return true;

  return false;
}

static bool IsConstantStore(const MachineInstr &MI,
                             const TargetRegisterInfo *TRI,
                             const MachineRegisterInfo *MRI) {
  bool FoundCallerPresReg = false;
  if (!MI.mayStore() || MI.hasUnmodeledSideEffects() ||
      (MI.getNumOperands() == 0))
    return false;

  for (const MachineOperand &MO : MI.operands()) {
    if (MO.isReg()) {
      Register Reg = MO.getReg();
      if (Reg.isVirtual())
        Reg = TRI->lookThruCopyLike(MO.getReg(), MRI);
      if (Reg.isVirtual())
        return false;
      if (!TRI->isCallerPreservedPhysReg(Reg.asMCReg(), *MI.getMF()))
        return false;
      else
        FoundCallerPresReg = true;
    } else if (!MO.isImm()) {
        return false;
    }
  }
  return FoundCallerPresReg;
}

static bool IsCopyFeedingConstantStore(const MachineInstr &MI,
                                        const MachineRegisterInfo *MRI,
                                        const TargetRegisterInfo *TRI) {
  if (!MI.isCopy())
    return false;

  const MachineFunction *MF = MI.getMF();
  Register CopySrcReg = MI.getOperand(1).getReg();
  if (CopySrcReg.isVirtual())
    return false;
  if (!TRI->isCallerPreservedPhysReg(CopySrcReg.asMCReg(), *MF))
    return false;

  Register CopyDstReg = MI.getOperand(0).getReg();
  assert(CopyDstReg.isVirtual() && "copy dst is not a virtual reg");

  for (MachineInstr &UseMI : MRI->use_instructions(CopyDstReg)) {
    if (UseMI.mayStore() && IsConstantStore(UseMI, TRI, MRI))
      return true;
  }
  return false;
}

bool MachineLICMBase::CanBeHoisted(MachineInstr &I, MachineLoop *CurLoop) {
  bool DontMoveAcrossStore = !HoistConstLoads || !LoadHoistPermission[CurLoop];

  if ((!I.isSafeToMove(AA, DontMoveAcrossStore)) &&
      !(HoistConstStores && IsConstantStore(I, TRI, MRI))) {
    LLVM_DEBUG(dbgs() << "LICM: Instruction not safe to move.\n");
    return false;
  }

  if (I.mayLoad() && !LoadsFromGOTOrConstantPool(I) &&
      !BlockAlwaysExecutes(I.getParent(), CurLoop)) {
    LLVM_DEBUG(dbgs() << "LICM: Load not guaranteed to execute.\n");
    return false;
  }

  if (I.isConvergent())
    return false;

  if (!TII->shouldHoist(I, CurLoop))
    return false;

  return true;
}

bool MachineLICMBase::IsLoopInvariant(MachineInstr &I,
                                          MachineLoop *CurLoop) {
  if (!CanBeHoisted(I, CurLoop)) {
    LLVM_DEBUG(dbgs() << "LICM: Instruction not a LICM candidate\n");
    return false;
  }
  return CurLoop->isLoopInvariant(I);
}

bool MachineLICMBase::HasPHIUser(const MachineInstr *MI,
                                    MachineLoop *CurLoop) {
  SmallVector<const MachineInstr *, 8> Work(1, MI);
  do {
    MI = Work.pop_back_val();
    for (const MachineOperand &MO : MI->all_defs()) {
      Register Reg = MO.getReg();
      if (!Reg.isVirtual())
        continue;

      for (MachineInstr &UseMI : MRI->use_instructions(Reg)) {
        if (UseMI.isPHI()) {
          if (CurLoop->contains(&UseMI))
            return true;
          if (IsExitBlock(CurLoop, UseMI.getParent()))
            return true;
          continue;
        }

        if (UseMI.isCopy() && CurLoop->contains(&UseMI))
          Work.push_back(&UseMI);
      }
    }
  } while (!Work.empty());
  return false;
}

bool MachineLICMBase::HasHighLatencyUse(MachineInstr &MI, unsigned DefIdx,
                                            Register Reg,
                                            MachineLoop *CurLoop) const {
  if (MRI->use_nodbg_empty(Reg))
    return false;

  for (MachineInstr &UseMI : MRI->use_nodbg_instructions(Reg)) {
    if (UseMI.isCopyLike())
      continue;
    if (!CurLoop->contains(UseMI.getParent()))
      continue;

    for (unsigned i = 0, e = UseMI.getNumOperands(); i != e; ++i) {
      const MachineOperand &MO = UseMI.getOperand(i);
      if (!MO.isReg() || !MO.isUse())
        continue;
      Register MOReg = MO.getReg();
      if (MOReg != Reg)
        continue;
      if (TII->hasHighOperandLatency(SchedModel, MRI, MI, DefIdx, UseMI, i))
        return true;
    }
    break;
  }
  return false;
}

