// Constants for LEGO Power Functions timing parameters
const uint16_t kLegoPfBitMark = 158;
const uint16_t kLegoPfHdrSpace = 1026;
const uint16_t kLegoPfZeroSpace = 263;
const uint16_t kLegoPfOneSpace = 553;
const uint32_t kLegoPfMinCommandLength = 16000;  // 16ms

#if SEND_LEGOPF
/// Send a LEGO Power Functions message using alternative implementation.
/// Status: Beta / Should work.
/// @param[in] payload The message data to be transmitted.
/// @param[in] bitCount Number of bits in the message.
/// @param[in] repetitions How many times to repeat transmission.
void IRsend::sendLegoPf(const uint64_t payload, const uint16_t bitCount,
                        const uint16_t repetitions) {
  // Extract channel identifier from most significant bits
  uint8_t channelIdentifier = ((payload >> (bitCount - 4)) & 0b11) + 1;

  if (repetitions > 0) {
    // Handle repeated transmission mode
    if (channelIdentifier < 4) {
      // Insert delay based on channel before transmission
      uint32_t initialDelay = (4 - channelIdentifier) * kLegoPfMinCommandLength;
      space(initialDelay);
    }

    // Ensure minimum 5 transmissions as per specification
    uint16_t totalTransmissions = std::max(repetitions, 5u);

    for (uint16_t transmissionIndex = 0; 
         transmissionIndex < totalTransmissions; 
         transmissionIndex++) {
      // Calculate inter-message gap based on transmission sequence
      uint16_t gapMultiplier = (transmissionIndex < 2) ? 5 : (6 + 2 * channelIdentifier);
      uint32_t interMessageGap = gapMultiplier * kLegoPfMinCommandLength;

      sendGeneric(kLegoPfBitMark, kLegoPfHdrSpace,
                  kLegoPfBitMark, kLegoPfOneSpace,
                  kLegoPfBitMark, kLegoPfZeroSpace,
                  kLegoPfBitMark, kLegoPfHdrSpace,
                  interMessageGap,
                  payload, bitCount, 38000, true, 0, kDutyDefault);
    }
  } else {
    // Single transmission without repetition
    sendGeneric(kLegoPfBitMark, kLegoPfHdrSpace,
                kLegoPfBitMark, kLegoPfOneSpace,
                kLegoPfBitMark, kLegoPfZeroSpace,
                kLegoPfBitMark, kLegoPfHdrSpace,
                kLegoPfMinCommandLength * 5,
                payload, bitCount, 38000, true, 0, kDutyDefault);
  }
}
#endif  // SEND_LEGO

#if DECODE_LEGOPF
/// Decode received LEGO Power Functions signal with modified algorithm.
/// Status: STABLE / Appears to work.
/// @param[in,out] resultPtr Pointer to decode results storage structure.
/// @param[in] startIndex Starting position in raw buffer for decoding.
/// @param[in] expectedBits Expected number of data bits.
/// @param[in] enforceStrict Whether to perform strict validation.
/// @return True if decoding successful, false otherwise.
bool IRrecv::decodeLegoPf(decode_results* resultPtr, uint16_t startIndex,
                          const uint16_t expectedBits, const bool enforceStrict) {
  // Validate expected bit count if strict mode enabled
  if (enforceStrict && expectedBits != kLegoPfBits) return false;

  uint64_t decodedData = 0;

  // Attempt generic matching of the signal pattern
  if (!matchGeneric(resultPtr->rawbuf + startIndex, &decodedData,
                    resultPtr->rawlen - startIndex, expectedBits,
                    kLegoPfBitMark, kLegoPfHdrSpace,
                    kLegoPfBitMark, kLegoPfOneSpace,
                    kLegoPfBitMark, kLegoPfZeroSpace,
                    kLegoPfBitMark, kLegoPfMinCommandLength,
                    true)) return false;

  // Perform LRC validation when strict mode is active
  if (enforceStrict) {
    uint16_t lrcCheckValue = decodedData;
    uint8_t lrcResult = 0xF;

    // XOR all nibbles together for LRC verification
    for (uint8_t nibbleCounter = 0; nibbleCounter < 4; nibbleCounter++) {
      lrcResult ^= (lrcCheckValue & 0xF);
      lrcCheckValue >>= 4;
    }

    if (lrcResult != 0) return false;
  }

  // Populate decode results structure
  resultPtr->decode_type = LEGOPF;
  resultPtr->bits = expectedBits;
  resultPtr->value = decodedData;
  resultPtr->address = ((decodedData >> (expectedBits - 4)) & 0b11) + 1;
  resultPtr->command = (decodedData >> 4) & 0xFF;

  return true;
}
#endif  // DECODE_LEGOPF

