class FTakesCoreModule : public IModuleInterface
{
public:
	virtual void StartupModule() override
	{
		// Load required LevelSequence module to ensure availability
		FModuleManager::Get().LoadModuleChecked("LevelSequence");

		// Retrieve or create take metadata for the ULevelSequence CDO
		ULevelSequence* SequenceCDO = GetMutableDefault<ULevelSequence>();
		if (!ensure(SequenceCDO)) return;

		UTakeMetaData* FoundMetaData = SequenceCDO->FindOrAddMetaData<UTakeMetaData>();
		if (FoundMetaData)
		{
			FoundMetaData->SetFlags(RF_Transient);
		}

		// Store weak reference to CDO for safe cleanup later
		StoredLevelSequenceCDO = SequenceCDO;

		// Initialize and register take data with Movie Scene Tools
		TakeDataHandle = MakeShareable(new FTakesCoreTakeData);
		FMovieSceneToolsModule& ToolsModule = FModuleManager::Get().GetModuleChecked<FMovieSceneToolsModule>("MovieSceneTools");
		ToolsModule.RegisterTakeData(TakeDataHandle.Get());
	}

	virtual void ShutdownModule() override
	{
		// Safely remove take metadata if CDO still exists
		if (ULevelSequence* ActiveCDO = StoredLevelSequenceCDO.Get())
		{
			ActiveCDO->RemoveMetaData<UTakeMetaData>();
		}

		// Unregister take data only if registered
		if (TakeDataHandle.IsValid())
		{
			FMovieSceneToolsModule& ToolsModule = FModuleManager::Get().GetModuleChecked<FMovieSceneToolsModule>("MovieSceneTools");
			ToolsModule.UnregisterTakeData(TakeDataHandle.Get());
			TakeDataHandle.Reset();
		}
	}

private:
	// Weak pointer to preserve safety during shutdown after CDO destruction
	TWeakObjectPtr<ULevelSequence> StoredLevelSequenceCDO;
	TSharedPtr<IMovieSceneToolsTakeData> TakeDataHandle;
};

