// Maximum size for the answer array
const int MAX_SIZE = 200005;
int result[MAX_SIZE];

// Recursive function to determine array elements using divide-and-conquer approach
// Uses interactive queries to find mode and frequency in subarrays
void reconstruct(int left, int right) {
    if (left > right) return;

    // Ask query about current segment [left, right]
    cout << "? " << left << " " << right << endl;

    int mode_value, freq;
    cin >> mode_value >> freq;

    // Handle error case
    if (mode_value == -1) {
        exit(1);
    }

    // If all elements in this range are the same
    if (freq == right - left + 1) {
        for (int idx = left; idx <= right; ++idx) {
            result[idx] = mode_value;
        }
        return;
    }

    // Split the range and process each half recursively
    int center = (left + right) / 2;
    reconstruct(left, center);
    reconstruct(center + 1, right);
}

int main() {
    // Speed up I/O operations
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    if (cin >> n) {
        // Begin reconstruction of entire array
        reconstruct(1, n);

        // Output final answer
        cout << "! ";
        for (int i = 1; i <= n; ++i) {
            cout << result[i];
            if (i < n) cout << " ";
        }
        cout << endl;
    }

    return 0;
}

