#include <iostream>
#include <vector>
#include <string>
using namespace std;

// Structure to represent an instruction in the generated program
struct Instr {
    string op;
    int p1, p2, p3, p4;
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    unsigned long k;
    cin >> k;

    // Special case: k == 1
    if (k == 1) {
        cout << "1\n";
        cout << "HALT PUSH 1 GOTO 1\n";
        return 0;
    }

    // Compute m = (k - 1) / 2
    unsigned long m = (k - 1) >> 1;
    vector<Instr> prog;

    int instrCount = 0;

    // Initial setup: push marker 1023 to indicate start of computation
    prog.push_back({"POP", 1023, 2, 1020, 2});
    instrCount = 1;

    // Process bits from 30 down to 0
    for (int bitPos = 30; bitPos >= 0; --bitPos) {
        bool currentBit = (m >> bitPos) & 1UL;

        int blockBase = instrCount + 1;
        int nextBlockStart;
        if (bitPos > 0) {
            nextBlockStart = blockBase + 6;
        } else {
            // Final bit: jump to main loop
            nextBlockStart = 1 + 31 * 6 + 1;
        }

        // Symbol definitions based on position
        int prevSymbol = (bitPos == 30) ? 1020 : (2 * (bitPos + 1) + 3);
        int outSymbol = (bitPos == 0) ? 3 : (2 * bitPos + 3);
        int tempSymbol = 2 * bitPos + 4;

        // Doubling section: expand each previous symbol into two temp symbols
        // POP prevSymbol -> [continue] or [skip]; then push two temps
        prog.push_back({"POP", prevSymbol, blockBase + 1, 1021, blockBase + 3});
        prog.push_back({"POP", 1023, blockBase + 2, tempSymbol, blockBase + 2});
        prog.push_back({"POP", 1023, blockBase, tempSymbol, blockBase});

        // Adder section: optionally add one more if current bit is set
        int adderPos = blockBase + 4;
        if (currentBit) {
            prog.push_back({"POP", 1021, adderPos, outSymbol, adderPos});
        } else {
            prog.push_back({"POP", 1021, adderPos, 1021, adderPos});
        }

        // Conversion section: convert all temp symbols to output symbols
        prog.push_back({"POP", tempSymbol, blockBase + 5, 1021, nextBlockStart});
        prog.push_back({"POP", 1023, blockBase + 4, outSymbol, blockBase + 4});

        instrCount += 6;
    }

    // Main execution loop
    int loopStart = instrCount + 1;
    int haltPos = instrCount + 2;

    // Loop control: pop counter items until none remain
    prog.push_back({"POP", 3, haltPos, 2, loopStart});
    prog.push_back({"HALT", -1, -1, 1, loopStart});

    instrCount += 2;

    // Output result
    cout << instrCount << "\n";
    for (const auto& inst : prog) {
        if (inst.op == "POP") {
            cout << "POP " << inst.p1 << " GOTO " << inst.p2 
                 << " PUSH " << inst.p3 << " GOTO " << inst.p4 << "\n";
        } else { // HALT
            cout << "HALT PUSH " << inst.p3 << " GOTO " << inst.p4 << "\n";
        }
    }

    return 0;
}

