using namespace std;

int n;
vector<int> arr;
int index_map[1005]; // Maps value to its current position

struct Operation {
    int left, right, direction; // direction=0 for left rotation, 1 for right rotation
};

vector<Operation> operations;

// Apply an operation to the actual array and update index_map
void execute_operation(int l, int r, int dir) {
    operations.push_back({l, r, dir});

    if (dir == 0) { // Left rotation: move first element to end
        int temp = arr[l];
        for (int i = l; i < r; ++i) {
            arr[i] = arr[i + 1];
            index_map[arr[i]] = i;
        }
        arr[r] = temp;
        index_map[temp] = r;
    } else { // Right rotation: move last element to front
        int temp = arr[r];
        for (int i = r; i > l; --i) {
            arr[i] = arr[i - 1];
            index_map[arr[i]] = i;
        }
        arr[l] = temp;
        index_map[temp] = l;
    }
}

// Simulate operation on a copy of the array (for evaluation)
void simulate(vector<int>& temp_arr, int l, int r, int dir) {
    if (dir == 0) {
        int temp = temp_arr[l];
        for (int i = l; i < r; ++i) {
            temp_arr[i] = temp_arr[i + 1];
        }
        temp_arr[r] = temp;
    } else {
        int temp = temp_arr[r];
        for (int i = r; i > l; --i) {
            temp_arr[i] = temp_arr[i - 1];
        }
        temp_arr[l] = temp;
    }
}

// Compute score for elements from start_idx to n
long long evaluate(const vector<int>& temp_arr, int start_pos) {
    long long score = 0;
    for (int i = start_pos; i <= n; ++i) {
        int diff = i - temp_arr[i];
        score += diff * diff;
    }
    return score;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);
    srand(static_cast<unsigned>(time(nullptr)));

    if (!(cin >> n)) return 0;

    arr.resize(n + 1);
    for (int i = 1; i <= n; ++i) {
        cin >> arr[i];
        index_map[arr[i]] = i;
    }

    if (n == 1) {
        cout << "1 0\n";
        return 0;
    }

    // Determine window size x (prefer even, at least 2)
    int window_size = static_cast<int>(round(sqrt(n)));
    if (window_size < 2) window_size = 2;
    if (window_size % 2 != 0) window_size++;
    if (window_size > n) window_size = n;

    int prefix_end = n - window_size - 1;

    // Sort prefix [1 .. prefix_end]
    for (int target = 1; target <= prefix_end; ++target) {
        int current_pos = index_map[target];

        // Move element using large jumps when possible
        while (current_pos >= target + window_size) {
            execute_operation(current_pos - window_size + 1, current_pos, 1);
            current_pos = index_map[target];
        }

        // Fine-tune positioning within small window
        while (index_map[target] != target) {
            execute_operation(target, target + window_size - 1, 0);
        }
    }

    // Handle tail portion: [prefix_end + 1, n]
    int tail_start = prefix_end + 1;
    if (tail_start < 1) tail_start = 1;

    // Build list of valid windows in tail region
    vector<pair<int, int>> candidate_windows;
    for (int start = tail_start; start <= n - window_size + 1; ++start) {
        candidate_windows.emplace_back(start, start + window_size - 1);
    }

    // Optimization loop for tail sorting
    const int max_attempts = 50000;
    int attempts = 0;

    while (attempts < max_attempts) {
        long long current_val = evaluate(arr, tail_start);
        if (current_val == 0) break;

        long long best_val = -1;
        int best_window_idx = -1;
        int best_dir = -1;

        // Evaluate all possible moves
        for (size_t i = 0; i < candidate_windows.size(); ++i) {
            int l = candidate_windows[i].first;
            int r = candidate_windows[i].second;
            for (int d = 0; d < 2; ++d) {
                vector<int> trial = arr;
                simulate(trial, l, r, d);
                long long val = evaluate(trial, tail_start);
                if (best_val == -1 || val < best_val) {
                    best_val = val;
                    best_window_idx = i;
                    best_dir = d;
                }
            }
        }

        // Choose next move: greedy improvement or random escape
        if (best_val < current_val) {
            execute_operation(candidate_windows[best_window_idx].first,
                              candidate_windows[best_window_idx].second,
                              best_dir);
        } else {
            int rand_window = rand() % candidate_windows.size();
            int rand_dir = rand() % 2;
            execute_operation(candidate_windows[rand_window].first,
                              candidate_windows[rand_window].second,
                              rand_dir);
        }
        attempts++;
    }

    cout << window_size << " " << operations.size() << "\n";
    for (const auto& op : operations) {
        cout << op.left << " " << op.right << " " << op.direction << "\n";
    }

    return 0;
}

#include "expression_evaluator/expression_evaluator_visitor.h"
#include "expression_evaluator/case_evaluator.h"

namespace lbug {
namespace evaluator {

void ExpressionEvaluatorVisitor::handleSwitchDispatch(ExpressionEvaluator* exprEval) {
    auto type = exprEval->getEvaluatorType();
    switch (type) {
        case EvaluatorType::CASE_ELSE:
            handleCaseDispatch(exprEval);
            break;
        case EvaluatorType::FUNCTION:
            handleFunctionDispatch(exprEval);
            break;
        case EvaluatorType::LAMBDA_PARAM:
            handleLambdaParamDispatch(exprEval);
            break;
        case EvaluatorType::LIST_LAMBDA:
            handleListLambdaDispatch(exprEval);
            break;
        case EvaluatorType::LITERAL:
            handleLiteralDispatch(exprEval);
            break;
        case EvaluatorType::PATH:
            handlePathDispatch(exprEval);
            break;
        case EvaluatorType::NODE_REL:
            handlePatternDispatch(exprEval);
            break;
        case EvaluatorType::REFERENCE:
            handleReferenceDispatch(exprEval);
            break;
        default:
            reportUnreachableBranch();
    }
}

void LambdaParamCollector::traverseAndCollect(ExpressionEvaluator* node) {
    std::vector<ExpressionEvaluator*> nextNodes;

    switch (node->getEvaluatorType()) {
        case EvaluatorType::CASE_ELSE: {
            const auto& caseNode = node->constCast<CaseExpressionEvaluator>();
            if (auto elseExpr = caseNode.getElseEvaluator()) {
                nextNodes.push_back(elseExpr);
            }
            for (const auto& alt : caseNode.getAlternativeEvaluators()) {
                nextNodes.push_back(alt.whenEvaluator.get());
                nextNodes.push_back(alt.thenEvaluator.get());
            }
        } break;

        case EvaluatorType::LAMBDA_PARAM: {
            collected.insert(collected.end(), node);
            return;
        }

        default: {
            const auto& children = node->getChildren();
            std::copy_if(children.begin(), children.end(), std::back_inserter(nextNodes),
                         [](const std::unique_ptr<ExpressionEvaluator>& ptr) { return ptr != nullptr; });
        }
    }

    for (auto* child : nextNodes) {
        traverseAndCollect(child);
        handleSwitchDispatch(child);
    }
}

} // namespace evaluator
