GhastModel::GhastModel() : Model()
{
    int yOffset = -16;
    body = new ModelPart(this, 0, 0);
    body->addBox(-8, -8, -8, 16, 16, 16);
    body->y += (8 + 16) + yOffset;

    Random* rng = new Random(1660);
    int idx = 0;
    while (idx < TENTACLESLENGTH)
    {
        tentacles[idx] = new ModelPart(this, 0, 0);

        float xOffset = ((static_cast<float>(idx % 3) - static_cast<float>((idx / 3) % 2) * 0.5f + 0.25f) / 2.0f * 2.0f - 1.0f) * 5.0f;
        float yOffsetTentacle = (static_cast<float>(idx / 3) / 2.0f * 2.0f - 1.0f) * 5.0f;

        int length = rng->nextInt(7) + 8;
        tentacles[idx]->addBox(-1, 0, -1, 2, length, 2);
        tentacles[idx]->x = xOffset;
        tentacles[idx]->z = yOffsetTentacle;
        tentacles[idx]->y = static_cast<float>(31 + yOffset);

        ++idx;
    }

    // Precompile for consistent performance
    body->compile(1.0f / 16.0f);
    int partIdx = 0;
    while (partIdx < TENTACLESLENGTH)
    {
        tentacles[partIdx]->compile(1.0f / 16.0f);
        ++partIdx;
    }
}

void GhastModel::setupAnim(float time, float r, float bob, float yRot, float xRot, float scale, unsigned int uiBitmaskOverrideAnim)
{
    int idx = 0;
    while (idx < TENTACLESLENGTH)
    {
        tentacles[idx]->xRot = 0.2f * Mth::sin(bob * 0.3f + static_cast<float>(idx)) + 0.4f;
        ++idx;
    }
}

void GhastModel::render(shared_ptr<Entity> entity, float time, float r, float bob, float yRot, float xRot, float scale, bool usecompiled)
{
    setupAnim(time, r, bob, yRot, xRot, scale);

    glPushMatrix();
    glTranslatef(0, 0.6f, 0);
    body->render(scale, usecompiled);

    int idx = 0;
    while (idx < TENTACLESLENGTH)
    {
        tentacles[idx]->render(scale, usecompiled);
        ++idx;
    }

    glPopMatrix();
}

