#include <sol/sol.hpp>
#include <string>
#include <tuple>

int main(int, char*[]) {
    sol::state lua;
    lua.open_libraries(sol::lib::base);

    // Define a function 'g' that accepts three arguments and returns them as a tuple
    lua["g"] = [](int x, int y, sol::object z) {
        return std::make_tuple(x, y, z);
    };

    // Test with integer third argument
    std::tuple<int, int, int> test_result1 = lua["g"](100, 200, 300);
    const std::tuple<int, int, int> expected1(100, 200, 300);
    SOL_ASSERT(test_result1 == expected1);

    // Test with string third argument
    std::tuple<int, int, std::string> test_result2 = lua["g"](100, 200, "BARK BARK BARK!");
    const std::tuple<int, int, std::string> expected2(100, 200, "BARK BARK BARK!");
    SOL_ASSERT(test_result2 == expected2);

    // Test using sol::tie for unpacking
    int val_a, val_b;
    std::string val_c;
    sol::tie(val_a, val_b, val_c) = lua["g"](100, 200, "bark");
    SOL_ASSERT(val_a == 100);
    SOL_ASSERT(val_b == 200);
    SOL_ASSERT(val_c == "bark");

    // Test from within Lua script
    lua.script(R"(
        x, y, z = g(150, 250, "woofbark")
        assert(x == 150)
        assert(y == 250)
        assert(z == "woofbark")
    )");

    return 0;
}

#include <hip/hip_runtime.h>
#include <hip/hiprtc.h>
#include <cstddef>
#include <cstdlib>
#include <iostream>
#include <string>
#include <memory>

// Helper macro to check return codes
#define VERIFY(call, expected) \
    do { \
        auto res = (call); \
        if (res != expected) { \
            std::cerr << "Error: " << #call << " failed with code " << res << std::endl; \
            std::exit(EXIT_FAILURE); \
        } \
    } while (0)

// Convenience macros for HIP and hipRTC
#define HIP_VERIFY(call) VERIFY(call, hipSuccess)
#define HIPRTC_VERIFY(call) VERIFY(call, HIPRTC_SUCCESS)

// Kernel source — unchanged semantically, but reformatted slightly
static constexpr const char* device_kernel_code{
R"(
extern "C"
__global__ void compute_sum(float* dst, const float* src1, const float* src2, size_t len)
{
    int idx = threadIdx.x;
    if (idx < len)
    {
        dst[idx] = src1[idx] + src2[idx];
    }
}
)"};

int main()
{
    // Step 1: Compile kernel using hipRTC
    hiprtcProgram prog;
    HIPRTC_VERIFY(hiprtcCreateProgram(&prog,
                                      device_kernel_code,
                                      "vector_add_kernel.cu",
                                      0, nullptr, nullptr));

    // Get device info to construct compilation flags
    hipDeviceProp_t dev_props{};
    int dev_id = 0;
    HIP_VERIFY(hipGetDeviceProperties(&dev_props, dev_id));
    std::string arch_flag = "--gpu-architecture=" + std::string{dev_props.gcnArchName};
    const char* compile_opts[] = {arch_flag.c_str()};

    // Compile program
    HIPRTC_VERIFY(hiprtcCompileProgram(prog, 1, compile_opts));

    // Check compilation log for warnings/errors
    size_t log_bytes = 0;
    HIPRTC_VERIFY(hiprtcGetProgramLogSize(prog, &log_bytes));
    if (log_bytes > 1)
    {
        std::string build_log(log_bytes, '\0');
        HIPRTC_VERIFY(hiprtcGetProgramLog(prog, &build_log[0]));
        std::cerr << "Compilation warning/error:\n" << build_log << std::endl;
        std::exit(EXIT_FAILURE);
    }

    // Extract compiled binary
    size_t bin_bytes = 0;
    HIPRTC_VERIFY(hiprtcGetCodeSize(prog, &bin_bytes));
    std::unique_ptr<char[]> bin_data{new char[bin_bytes]};
    HIPRTC_VERIFY(hiprtcGetCode(prog, bin_data.get()));
    HIPRTC_VERIFY(hiprtcDestroyProgram(&prog));

    // Load module and get kernel function
    hipModule_t mod;
    hipFunction_t func;
    HIP_VERIFY(hipModuleLoadData(&mod, bin_data.get()));
    HIP_VERIFY(hipModuleGetFunction(&func, mod, "compute_sum"));

    // Setup host data
    constexpr size_t N = 256;
    std::unique_ptr<float[]> h_src1{new float[N]};
    std::unique_ptr<float[]> h_src2{new float[N]};
    std::unique_ptr<float[]> h_res{new float[N]{}};

    for (size_t i = 0; i < N; ++i)
    {
        h_src1[i] = static_cast<float>(i + 1);
        h_src2[i] = h_src1[i]; // same input for both vectors
    }

    // Allocate device memory
    float *d_s1, *d_s2, *d_r;
    HIP_VERIFY(hipMalloc(&d_s1, N * sizeof(float)));
    HIP_VERIFY(hipMalloc(&d_s2, N * sizeof(float)));
    HIP_VERIFY(hipMalloc(&d_r,  N * sizeof(float)));

    // Copy inputs to device
    HIP_VERIFY(hipMemcpy(d_s1, h_src1.get(), N * sizeof(float), hipMemcpyHostToDevice));
    HIP_VERIFY(hipMemcpy(d_s2, h_src2.get(), N * sizeof(float), hipMemcpyHostToDevice));

    // Launch configuration
    struct KernelArgs {
        float* out;
        const float* in1;
        const float* in2;
        size_t count;
    } args{d_r, d_s1, d_s2, N};

    size_t arg_size = sizeof(args);
    void* launch_config[] = {
        HIP_LAUNCH_PARAM_BUFFER_POINTER, &args,
        HIP_LAUNCH_PARAM_BUFFER_SIZE,    &arg_size,
        HIP_LAUNCH_PARAM_END
    };

    HIP_VERIFY(hipModuleLaunchKernel(func,
                                     1, 1, 1,   // grid dims
                                     N, 1, 1,   // block dims
                                     0, nullptr, // shared mem, stream
                                     nullptr, launch_config));

    // Copy result back
    HIP_VERIFY(hipMemcpy(h_res.get(), d_r, N * sizeof(float), hipMemcpyDeviceToHost));

    // Validate results
    bool passed = true;
    size_t idx = 0;
    do {
        float expected = h_src1[idx] + h_src2[idx];
        if (h_res[idx] != expected) {
            std::cerr << "Mismatch at index " << idx << ": "
                      << "expected " << expected << ", got " << h_res[idx] << std::endl;
            passed = false;
            break;
        }
        ++idx;
    } while (idx < N);

    if (!passed) {
        std::exit(EXIT_FAILURE);
    }

    std::cout << "Validation successful!" << std::endl;

    // Cleanup
    HIP_VERIFY(hipFree(d_s1));
    HIP_VERIFY(hipFree(d_s2));
    HIP_VERIFY(hipFree(d_r));

    return EXIT_SUCCESS;
}

