EndermanRenderer::EndermanRenderer() : MobRenderer(new EndermanModel(), 0.5f) {
    model = static_cast<EndermanModel*>(MobRenderer::model);
    setupArmor(model);
}

void EndermanRenderer::render(
    std::shared_ptr<Entity> entity,
    double                  posX,
    double                  posY,
    double                  posZ,
    float                   rotation,
    float                   partialTicks
) {
    std::shared_ptr<EnderMan> enderman = std::dynamic_pointer_cast<EnderMan>(entity);

    // Update model state based on entity properties
    model->carrying = enderman->getCarryingTile() != 0;
    model->creepy   = enderman->isCreepy();

    if (enderman->isCreepy()) {
        const double jitterFactor = 0.02;
        posX += random.nextGaussian() * jitterFactor;
        posZ += random.nextGaussian() * jitterFactor;
    }

    MobRenderer::render(enderman, posX, posY, posZ, rotation, partialTicks);
}

void EndermanRenderer::additionalRendering(std::shared_ptr<Mob> mobPtr, float tickDelta) {
    std::shared_ptr<EnderMan> enderman = std::dynamic_pointer_cast<EnderMan>(mobPtr);

    MobRenderer::additionalRendering(mobPtr, tickDelta);

    int carriedBlockId = enderman->getCarryingTile();
    if (carriedBlockId > 0) {
        glEnable(GL_RESCALE_NORMAL);
        glPushMatrix();

        float scale = 8.0f / 16.0f;
        glTranslatef(0.0f, 11.0f / 16.0f, -12.0f / 16.0f);
        scale *= 1.00f;
        glRotatef(20.0f, 1.0f, 0.0f, 0.0f);
        glRotatef(45.0f, 0.0f, 1.0f, 0.0f);
        glScalef(scale, -scale, scale);

        if (SharedConstants::TEXTURE_LIGHTING) {
            int lightColor = enderman->getLightColor(tickDelta);
            int uComponent = lightColor % 65536;
            int vComponent = lightColor / 65536;
            glMultiTexCoord2f(GL_TEXTURE1, static_cast<float>(uComponent), static_cast<float>(vComponent));
            glColor4f(1.0f, 1.0f, 1.0f, 1.0f);
        }

        glColor4f(1.0f, 1.0f, 1.0f, 1.0f);
        bindTexture(TN_TERRAIN);
        tileRenderer->renderTile(
            Tile::tiles[carriedBlockId],
            enderman->getCarryingData(),
            1
        );

        glPopMatrix();
        glDisable(GL_RESCALE_NORMAL);
    }
}

int EndermanRenderer::prepareArmor(std::shared_ptr<Mob> mobRef, int layerIndex, float timeFraction) {
    std::shared_ptr<EnderMan> enderman = std::dynamic_pointer_cast<EnderMan>(mobRef);

    if (layerIndex != 0) return -1;

    bindTexture(TN_MOB_ENDERMAN_EYES);
    float brightness = 1.0f;
    glEnable(GL_BLEND);

#ifdef _XBOX
    glDisable(GL_ALPHA_TEST);
#endif

    glBlendFunc(GL_ONE, GL_ONE);
    glDisable(GL_LIGHTING);

    if (enderman->isInvisible()) {
        glDepthMask(false);
    } else {
        glDepthMask(true);
    }

    if (SharedConstants::TEXTURE_LIGHTING) {
        int fixedColor = 0xf0f0;
        int uCoord = fixedColor % 65536;
        int vCoord = fixedColor / 65536;
        glMultiTexCoord2f(GL_TEXTURE1, static_cast<float>(uCoord), static_cast<float>(vCoord));
        glColor4f(1.0f, 1.0f, 1.0f, 1.0f);
    }

    glEnable(GL_LIGHTING);
    glColor4f(1.0f, 1.0f, 1.0f, brightness);

    return 1;
}

