  }

  // Helper function to check if two strings are equal (exact match)
  bool is_exact_match(const std::string& lhs, const std::string& rhs) const {
    return lhs.size() == rhs.size() && lhs.compare(0, lhs.size(), rhs) == 0;
  }

  // Helper: determine whether a pattern contains any wildcard characters
  bool has_wildcard(const std::string& pattern) const {
    return pattern.find('*') != std::string::npos;
  }

  // Helper: split string by delimiter (used for manual parsing)
  std::vector<std::string> split_by_char(const std::string& s, char delim) const {
    std::vector<std::string> parts;
    std::string current;
    for (char c : s) {
      if (c == delim) {
        if (!current.empty() || !parts.empty()) {
          parts.push_back(current);
          current.clear();
        }
      } else {
        current += c;
      }
    }
    if (!current.empty() || !parts.empty()) {
      parts.push_back(current);
    }
    return parts;
  }

  // Core wildcard matching logic — rewritten using iterative prefix/suffix checks
  bool wildcard_match_impl(const std::string& text, const std::string& pattern) const {
    size_t t_idx = 0, p_idx = 0;
    size_t star_idx = std::string::npos;
    size_t match_idx = 0;

    while (t_idx < text.size()) {
      if (p_idx < pattern.size() && (pattern[p_idx] == '*' || text[t_idx] == pattern[p_idx])) {
        if (pattern[p_idx] == '*') {
          star_idx = p_idx;
          match_idx = t_idx;
          ++p_idx;
        } else {
          ++t_idx;
          ++p_idx;
        }
      } else if (star_idx != std::string::npos) {
        p_idx = star_idx + 1;
        ++match_idx;
        t_idx = match_idx;
      } else {
        return false;
      }
    }

    while (p_idx < pattern.size() && pattern[p_idx] == '*') {
      ++p_idx;
    }

    return p_idx == pattern.size();
  }
};

