// Helper function to safely delete objects
template<typename T>
void safe_delete(T*& ptr) {
    if (ptr != nullptr) {
        delete ptr;
        ptr = nullptr;
    }
}

/*-------------------------------------------------------------------------
 * Modified version of test_file_create with adjusted logic flow
 *-------------------------------------------------------------------------
 */
static void modified_file_creation_test()
{
    SUBTEST("Modified File Creation I/O");

    H5File* created_file = nullptr;

    try {
        // Ensure clean state
        remove(TEST_FILE_1.c_str());

        // Create initial file with exclusive access
        created_file = new H5File(TEST_FILE_1, H5F_ACC_EXCL);

        // Attempt duplicate creation - should fail
        try {
            H5File duplicate(TEST_FILE_1, H5F_ACC_TRUNC);
            throw InvalidActionException("Duplicate creation", "Should not succeed");
        } catch (FileIException&) {
            // Expected failure
        }

        // Close first file
        safe_delete(created_file);

        // Try creating existing file again - should fail
        try {
            H5File another_attempt(TEST_FILE_1, H5F_ACC_EXCL);
            throw InvalidActionException("Existing file", "Should not succeed");
        } catch (FileIException&) {
            // Expected failure
        }

        // Truncate existing file successfully
        created_file = new H5File(TEST_FILE_1, H5F_ACC_TRUNC);

        // Verify file creation properties
        FileCreatPropList prop_list = created_file->getCreatePlist();

        hsize_t ublock_size = prop_list.getUserblock();
        verify_val(static_cast<long>(ublock_size), 
                   static_cast<long>(DEFAULT_USERBLOCK),
                   "getUserblock", __LINE__, __FILE__);

        size_t offset_size, length_size;
        prop_list.getSizes(offset_size, length_size);
        verify_val(offset_size, DEFAULT_OFFSET_SZ, "getSizes offset", __LINE__, __FILE__);
        verify_val(length_size, DEFAULT_LENGTH_SZ, "getSizes length", __LINE__, __FILE__);

        unsigned sym_int_k, sym_leaf_k;
        prop_list.getSymk(sym_int_k, sym_leaf_k);
        verify_val(sym_int_k, SYM_INT_DEFAULT, "getSymk internal", __LINE__, __FILE__);
        verify_val(sym_leaf_k, SYM_LEAF_DEFAULT, "getSymk leaf", __LINE__, __FILE__);

        // Cleanup
        safe_delete(created_file);
        PASSED();

    } catch (InvalidActionException& e) {
        issue_fail_msg("modified_file_creation_test", __LINE__, __FILE__, e.getDetailMsg());
        safe_delete(created_file);
    } catch (Exception& e) {
        issue_fail_msg("modified_file_creation_test", __LINE__, __FILE__, e.getCDetailMsg());
        safe_delete(created_file);
    }
}

