#include <iostream>
#include <vector>
#include <limits.h> // For INT_MAX and INT_MIN
using namespace std;

class Solution {
public:
    int reverseNumber(int input) {
        int result = 0;

        while (input != 0) {
            // Check for overflow before performing multiplication and addition
            if (result > INT_MAX / 10 || result < INT_MIN / 10) {
                return 0;
            }

            result = result * 10 + input % 10;
            input /= 10;
        }

        return result;
    }

    bool checkPalindrome(int value) {
        // Negative numbers are not palindromes
        if (value < 0) {
            return false;
        }

        int reversedValue = reverseNumber(value);
        return reversedValue == value;
    }
};

int main() {
    Solution solver;
    int number = 12345; // Example number

    cout << "Original number: " << number << endl;
    cout << "Reversed number: " << solver.reverseNumber(number) << endl;

    cout << "Is Palindrome: " << solver.checkPalindrome(number) << endl;

    return 0;
}
// Output: Original number: 12345

