// Generate a random double in [0, 1) using the client context's RNG
struct RandomDoubleGenerator {
    static void compute(double& output, void* bindData) {
        auto* ctx = reinterpret_cast<FunctionBindData*>(bindData)->clientContext;
        uint32_t rawRandom = RandomEngine::Get(*ctx)->nextRandomInteger();
        output = static_cast<double>(rawRandom) / static_cast<double>(UINT32_MAX);
    }
};

function_set RandomScalarFunction::getFunctionSet() {
