        std::make_unique<ScalarFunction>(
            name,
            std::vector<LogicalTypeID>{},
            LogicalTypeID::DOUBLE,
            ScalarFunction::NullaryAuxilaryExecFunction<double, RandomDoubleGenerator>
        )
    );
    return functions;
}

