#include "test/jemalloc_test.h"
#include "test/arena_util.h"
#include "jemalloc/internal/arena_structs.h"
#include "jemalloc/internal/san_bump.h"

static void
verify_edata_properties(tsdn_t *tsdn, edata_t *edata, unsigned expected_arena_ind,
    size_t expected_size, bool expect_zeroed) {
	expect_u_eq(edata_arena_ind_get(edata), expected_arena_ind,
	    "Edata was assigned an incorrect arena id");
	expect_zu_eq(edata_size_get(edata), expected_size,
	    "Allocated edata of incorrect size");
	expect_false(edata_slab_get(edata),
	    "Bump allocator incorrectly assigned 'slab' to true");
	expect_true(edata_committed_get(edata), "Edata is not committed");

	void *addr = edata_addr_get(edata);
	expect_ptr_not_null(addr, "Edata was assigned an invalid address");

	if (expect_zeroed) {
		size_t nwords = expected_size / sizeof(unsigned);
		for (size_t idx = 0; idx < nwords; ++idx) {
			expect_u_eq(((unsigned *)addr)[idx], 0,
			    "Memory should be zeroed on allocation");
		}
	} else {
		// Just touch memory to ensure it's writable
		for (size_t idx = 0; idx < expected_size / sizeof(unsigned); ++idx) {
			((unsigned *)addr)[idx] = 1;
		}
	}
}

TEST_BEGIN(test_san_bump_alloc) {
	test_skip_if(!maps_coalesce || !opt_retain);

	tsdn_t *tsdn = tsdn_fetch();
	san_bump_alloc_t sba;
	san_bump_alloc_init(&sba);

	unsigned arena_idx = do_arena_create(0, 0);
	assert_u_ne(arena_idx, UINT_MAX, "Failed to create an arena");

	arena_t *arena = arena_get(tsdn, arena_idx, false);
	pac_t *pac = &arena->pa_shard.pac;

	size_t sz1 = PAGE * 16;
	edata_t *e1 = san_bump_alloc(tsdn, &sba, pac, pac_ehooks_get(pac), sz1, /* zero */ false);
	verify_edata_properties(tsdn, e1, arena_idx, sz1, /* expect_zeroed */ false);

	void *mem1 = edata_addr_get(e1);
	expect_ptr_not_null(mem1, "First allocation returned null pointer");

	size_t sz2 = PAGE * 28;
	edata_t *e2 = san_bump_alloc(tsdn, &sba, pac, pac_ehooks_get(pac), sz2, /* zero */ true);
	verify_edata_properties(tsdn, e2, arena_idx, sz2, /* expect_zeroed */ true);

	void *mem2 = edata_addr_get(e2);
	expect_ptr_not_null(mem2, "Second allocation returned null pointer");

	uintptr_t diff = (uintptr_t)mem2 > (uintptr_t)mem1
	    ? (uintptr_t)mem2 - (uintptr_t)mem1
	    : (uintptr_t)mem1 - (uintptr_t)mem2;
	size_t gap = (size_t)diff - sz1;
	expect_zu_ge(gap, PAGE,
	    "Expected at least one guard page between allocations");

	// Ensure second region is zeroed explicitly again (redundant but safe)
	for (size_t i = 0; i < sz2 / sizeof(unsigned); ++i) {
		expect_u_eq(((unsigned *)mem2)[i], 0,
		    "Second allocation memory not zeroed as expected");
	}
}
TEST_END

TEST_BEGIN(test_large_alloc_size) {
	test_skip_if(!maps_coalesce || !opt_retain);

	tsdn_t *tsdn = tsdn_fetch();
	san_bump_alloc_t sba;
	san_bump_alloc_init(&sba);

	unsigned arena_idx = do_arena_create(0, 0);
	assert_u_ne(arena_idx, UINT_MAX, "Failed to create an arena");

	arena_t *arena = arena_get(tsdn, arena_idx, false);
	pac_t *pac = &arena->pa_shard.pac;

	size_t big_size = SBA_RETAINED_ALLOC_SIZE * 2;
	edata_t *big_edata = san_bump_alloc(tsdn, &sba, pac, pac_ehooks_get(pac),
	    big_size, /* zero */ false);

	expect_u_eq(edata_arena_ind_get(big_edata), arena_idx,
	    "Large edata assigned wrong arena index");
	expect_zu_eq(edata_size_get(big_edata), big_size,
	    "Large edata has incorrect size");
	expect_false(edata_slab_get(big_edata),
	    "Large bump alloc incorrectly marked as slab");
	expect_true(edata_committed_get(big_edata),
	    "Large allocation not committed");

	void *big_ptr = edata_addr_get(big_edata);
	expect_ptr_not_null(big_ptr, "Large allocation returned null");

	// Touch every page to verify mapping
	for (size_t pg = 0; pg < big_size / PAGE; ++pg) {
		*((char *)big_ptr + pg * PAGE) = (char)(pg & 0xFF);
	}
}
TEST_END

int
main(void) {
	return test(
	    test_san_bump_alloc,
	    test_large_alloc_size);
}

