#include <iostream>
#include <magic_enum/magic_enum.hpp>
#include <magic_enum/magic_enum_iostream.hpp>

// Custom helper to convert enum to its underlying integer type
template <typename E>
auto to_underlying(magic_enum::Enum<E> value) {
  return static_cast<magic_enum::underlying_type_t<E>>(value);
}

int main() {
  // Declare and initialize an enum variable
  Color c1 = Color::RED;

  // Convert enum to its string representation
  auto c1_name = magic_enum::enum_name(c1);
  std::cout << c1_name << std::endl; // RED

  // Get all enum names as a compile-time array
  constexpr auto names_list = magic_enum::enum_names<Color>();
  std::cout << "Color names:";
  for (const auto& name : names_list) {
    std::cout << " " << name;
  }
  std::cout << std::endl;

  // Parse string to enum value
  auto parsed_blue = magic_enum::enum_cast<Color>("BLUE");
  if (parsed_blue.has_value()) {
    std::cout << "BLUE = " << to_underlying(parsed_blue.value()) << std::endl; // BLUE = 0
  }

  // Case-insensitive parsing
  parsed_blue = magic_enum::enum_cast<Color>("blue", magic_enum::case_insensitive);
  if (parsed_blue.has_value()) {
    std::cout << "BLUE = " << to_underlying(parsed_blue.value()) << std::endl; // BLUE = 0
  }

  // Convert integer to enum
  auto green_val = magic_enum::enum_cast<Color>(10);
  if (green_val.has_value()) {
    std::cout << "GREEN = " << magic_enum::enum_integer(green_val.value()) << std::endl; // GREEN = 10
  }

  // Convert enum to integer
  int red_int = magic_enum::enum_integer(Color::RED);
  std::cout << "RED = " << red_int << std::endl; // RED = -10

  // Enable ostream operator overloads for enums
  using magic_enum::iostream_operators::operator<<;

  // Output multiple enum values using the overloaded operator
  std::cout << "Color: " << c1 << " " << parsed_blue.value() << " " << green_val.value() << std::endl;

  // Count number of enum values
  std::cout << "Color enum size: " << magic_enum::enum_count<Color>() << std::endl; // 3

  // Access enum by index
  std::cout << "Color[0] = " << magic_enum::enum_value<Color>(0) << std::endl; // RED

  // Get all enum values as a compile-time array
  constexpr auto all_values = magic_enum::enum_values<Color>();
  std::cout << "Colors values:";
  for (const auto val : all_values) {
    std::cout << " " << val;
  }
  std::cout << std::endl;

  // Bitwise operations on scoped enums
  enum class Flags { A = 1, B = 2, C = 4, D = 8 };
  using namespace magic_enum::bitwise_operators;
  Flags combined_flags = Flags::A | Flags::C;
  std::cout << combined_flags << std::endl; // 5

  // Unscoped enum example
  enum color { red, green, blue };
  static_assert(magic_enum::is_unscoped_enum_v<color>);
  static_assert(!magic_enum::is_unscoped_enum_v<Color>);
  static_assert(!magic_enum::is_unscoped_enum_v<Flags>);

  // Scoped enum checks
  static_assert(!magic_enum::is_scoped_enum_v<color>);
  static_assert(magic_enum::is_scoped_enum_v<Color>);
  static_assert(magic_enum::is_scoped_enum_v<Flags>);

  // Enum entries: pairs of (value, name)
  constexpr auto entries = magic_enum::enum_entries<Color>();
  std::cout << "Colors entries:";
  for (const auto& entry : entries) {
    std::cout << " " << entry.second << " = " << to_underlying(entry.first);
  }
  std::cout << std::endl;

  return 0;
}

