// Constants for Argo protocol (same as original)
const uint16_t kArgoHdrMark = 6400;
const uint16_t kArgoHdrSpace = 3300;
const uint16_t kArgoBitMark = 400;
const uint16_t kArgoOneSpace = 2200;
const uint16_t kArgoZeroSpace = 900;
const uint32_t kArgoGap = 7500;  // Made up value. Complete guess.
const uint8_t kArgoSensorCheck = 52;
const uint8_t kArgoSensorFixed = 0b011;
const uint8_t kArgoWrem3Preamble = 0b1011;
const uint8_t kArgoWrem3Postfix_Timer = 0b1;
const uint8_t kArgoWrem3Postfix_ACControl = 0b110000;

// Enumerations (simplified)
enum class ArgoMode { AUTO, COOL, HEAT, DRY, FAN };
enum class ArgoFan { FAN_AUTO, FAN_LOWEST, FAN_LOWER, FAN_LOW, FAN_MEDIUM, FAN_HIGH, FAN_HIGHEST };
enum class ArgoFlap { FLAP_AUTO, FLAP_1, FLAP_2, FLAP_3, FLAP_4, FLAP_5, FLAP_6, FLAP_FULL };
enum class ArgoMessageType { AC_CONTROL, IFEEL_TEMP_REPORT, TIMER_COMMAND, CONFIG_PARAM_SET };

// Simplified state structure
struct ArgoState {
    std::vector<uint8_t> data;
    ArgoMessageType msgType;

    ArgoState() : msgType(ArgoMessageType::AC_CONTROL) {
        data.resize(12, 0);  // Default size
    }
};

// Base class for Argo AC control
class ArgoACController {
protected:
    ArgoState currentState;
    uint8_t temperature;
    uint8_t sensorTemp;
    ArgoMode currentMode;
    ArgoFan currentFan;
    bool powerOn;
    bool maxMode;
    bool nightMode;
    bool iFeelMode;

public:
    ArgoACController() : 
        temperature(20), sensorTemp(25), currentMode(ArgoMode::AUTO),
        currentFan(ArgoFan::FAN_AUTO), powerOn(false), maxMode(false),
        nightMode(false), iFeelMode(false) {}

    // Core functionality methods
    void initialize() {
        resetState();
    }

    void resetState() {
        currentState = ArgoState();
        temperature = 20;
        sensorTemp = 25;
        currentMode = ArgoMode::AUTO;
        currentFan = ArgoFan::FAN_AUTO;
        powerOn = false;
        maxMode = false;
        nightMode = false;
        iFeelMode = false;
    }

    // Power control
    void turnOn() { powerOn = true; }
    void turnOff() { powerOn = false; }
    bool isPowered() const { return powerOn; }

    // Temperature settings
    void setTemperature(uint8_t temp) {
        temperature = std::max(12u, std::min(32u, temp));
    }

    uint8_t getTemperature() const { return temperature; }

    void setSensorTemperature(uint8_t temp) {
        sensorTemp = std::max(10u, std::min(35u, temp));
    }

    uint8_t getSensorTemperature() const { return sensorTemp; }

    // Mode control
    void setMode(ArgoMode mode) { currentMode = mode; }
    ArgoMode getMode() const { return currentMode; }

    // Fan control
    void setFan(ArgoFan fan) { currentFan = fan; }
    ArgoFan getFan() const { return currentFan; }

    // Feature toggles
    void setMaxMode(bool enable) { maxMode = enable; }
    bool isMaxMode() const { return maxMode; }

    void setNightMode(bool enable) { nightMode = enable; }
    bool isNightMode() const { return nightMode; }

    void setIFeel(bool enable) { iFeelMode = enable; }
    bool isIFeel() const { return iFeelMode; }

    // Checksum calculation (simplified version)
    uint8_t calculateChecksum(const std::vector<uint8_t>& bytes) const {
        uint16_t sum = 0;
        for (size_t i = 0; i < bytes.size() - 1; ++i) {
            sum += bytes[i];
        }
        return static_cast<uint8_t>(sum & 0xFF);
    }

    // Message generation
    virtual std::vector<uint8_t> generateCommand() const = 0;

    // String representation
    virtual std::string toString() const {
        std::string result = "Argo AC Controller State:\n";
        result += "Power: " + std::string(powerOn ? "ON" : "OFF") + "\n";
        result += "Mode: " + modeToString(currentMode) + "\n";
        result += "Temperature: " + std::to_string(temperature) + "C\n";
        result += "Sensor Temp: " + std::to_string(sensorTemp) + "C\n";
        result += "Fan: " + fanToString(currentFan) + "\n";
        result += "Max Mode: " + std::string(maxMode ? "ON" : "OFF") + "\n";
        result += "Night Mode: " + std::string(nightMode ? "ON" : "OFF") + "\n";
        result += "iFeel: " + std::string(iFeelMode ? "ON" : "OFF") + "\n";
        return result;
    }

protected:
    std::string modeToString(ArgoMode mode) const {
        switch (mode) {
            case ArgoMode::AUTO: return "AUTO";
            case ArgoMode::COOL: return "COOL";
            case ArgoMode::HEAT: return "HEAT";
            case ArgoMode::DRY: return "DRY";
            case ArgoMode::FAN: return "FAN";
            default: return "UNKNOWN";
        }
    }

    std::string fanToString(ArgoFan fan) const {
        switch (fan) {
            case ArgoFan::FAN_AUTO: return "AUTO";
            case ArgoFan::FAN_LOWEST: return "LOWEST";
            case ArgoFan::FAN_LOWER: return "LOWER";
            case ArgoFan::FAN_LOW: return "LOW";
            case ArgoFan::FAN_MEDIUM: return "MEDIUM";
            case ArgoFan::FAN_HIGH: return "HIGH";
            case ArgoFan::FAN_HIGHEST: return "HIGHEST";
            default: return "UNKNOWN";
        }
    }
};

// WREM2 specific implementation
class ArgoAC_WREM2 : public ArgoACController {
public:
    std::vector<uint8_t> generateCommand() const override {
        std::vector<uint8_t> command(12, 0);

        // Set preamble bytes
        command[0] = 0b00110101;  // Pre1
        command[1] = 0b10101111;  // Pre2

        // Set power bit
        command[2] = (powerOn ? 0x80 : 0x00);

        // Set mode (bits 4-6 of byte 3)
        uint8_t modeValue = static_cast<uint8_t>(currentMode);
        command[3] = (command[3] & 0x1F) | ((modeValue & 0x07) << 5);

        // Set temperature (bits 0-3 of byte 4)
        uint8_t tempValue = std::max(0, static_cast<int>(temperature) - 4);
        command[4] = (command[4] & 0xF0) | (tempValue & 0x0F);

        // Set fan (bits 4-5 of byte 5)
        uint8_t fanValue = static_cast<uint8_t>(currentFan);
        command[5] = (command[5] & 0xCF) | ((fanValue & 0x03) << 4);

        // Set features
        if (maxMode) command[6] |= 0x01;
        if (nightMode) command[7] |= 0x01;
        if (iFeelMode) command[8] |= 0x01;

        // Sensor temperature in byte 9
        uint8_t sensorValue = std::max(0, static_cast<int>(sensorTemp) - 10);
        command[9] = sensorValue;

        // Calculate and set checksum
        uint8_t checksum = calculateChecksum(command);
        command[10] = (checksum >> 2) | 0x04;  // Constant part
        command[11] = (checksum << 6) | 0x01;  // Constant part

        return command;
    }

    std::string toString() const override {
        return ArgoACController::toString();
    }
};

// WREM3 specific implementation
class ArgoAC_WREM3 : public ArgoACController {
private:
    uint8_t channel;
    bool ecoMode;
    bool lightMode;
    bool filterMode;

public:
    ArgoAC_WREM3() : channel(0), ecoMode(false), lightMode(false), filterMode(false) {}

    void setChannel(uint8_t ch) { channel = std::min(ch, 3u); }
    uint8_t getChannel() const { return channel; }

    void setEcoMode(bool enable) { ecoMode = enable; }
    bool isEcoMode() const { return ecoMode; }

    void setLightMode(bool enable) { lightMode = enable; }
    bool isLightMode() const { return lightMode; }

    void setFilterMode(bool enable) { filterMode = enable; }
    bool isFilterMode() const { return filterMode; }

    std::vector<uint8_t> generateCommand() const override {
        std::vector<uint8_t> command(13, 0);

        // Set preamble (first nibble of first byte)
        command[0] = (kArgoWrem3Preamble << 4) | (channel & 0x0F);

        // Set message type (bits 6-7 of first byte)
        command[0] = (command[0] & 0x3F) | (static_cast<uint8_t>(ArgoMessageType::AC_CONTROL) << 6);

        // Set power bit
        command[1] = (powerOn ? 0x80 : 0x00);

        // Set mode
        uint8_t modeValue = static_cast<uint8_t>(currentMode);
        command[2] = (command[2] & 0x1F) | ((modeValue & 0x07) << 5);

        // Set temperature
        uint8_t tempValue = std::max(0, static_cast<int>(temperature) - 4);
        command[3] = (command[3] & 0xF0) | (tempValue & 0x0F);

        // Set fan
        uint8_t fanValue = static_cast<uint8_t>(currentFan);
        command[4] = (command[4] & 0xC0) | (fanValue & 0x3F);

        // Set flap/swing
        command[5] = 0x07;  // Default auto position

        // Set features
        if (maxMode) command[6] |= 0x01;
        if (nightMode) command[7] |= 0x01;
        if (ecoMode) command[8] |= 0x01;
        if (filterMode) command[9] |= 0x01;
        if (lightMode) command[10] |= 0x01;
        if (iFeelMode) command[11] |= 0x01;

        // Sensor temperature
        uint8_t sensorValue = std::max(0, static_cast<int>(sensorTemp) - 10);
        command[12] = sensorValue;

        // Calculate and set checksum
        uint8_t checksum = calculateChecksum(command);
        command.back() = checksum;

        return command;
    }

    std::string toString() const override {
        std::string result = "Argo AC WREM3 State:\n";
        result += ArgoACController::toString();
        result += "Channel: " + std::to_string(channel) + "\n";
        result += "Eco Mode: " + std::string(ecoMode ? "ON" : "OFF") + "\n";
        result += "Light Mode: " + std::string(lightMode ? "ON" : "OFF") + "\n";
        result += "Filter Mode: " + std::string(filterMode ? "ON" : "OFF") + "\n";
        return result;
    }
};

