#include <iostream>
#include <vector>
#include <string>
#include <set>
#include <algorithm>
using namespace std;

// Function to find and output all words according to the problem protocol
void processWords() {
    int totalWords;
    if (!(cin >> totalWords)) return;

    set<string> collectedWords;

    // Process each letter from 'a' to 'z'
    for (char startChar = 'a'; startChar <= 'z'; ++startChar) {
        // Early exit if we've collected all required words
        if (collectedWords.size() == totalWords) break;

        string prefix(1, startChar);
        int currentCount = 0;     // Words found for this prefix so far
        int querySize = 1;        // Initial query size

        while (collectedWords.size() < totalWords) {
            // Double the query size if current limit is insufficient
            if (querySize <= currentCount) {
                querySize *= 2;
                continue;
            }

            // Calculate how many words with this prefix could still exist
            int otherPrefixCount = collectedWords.size() - currentCount;
            int maxPossibleForCurrentPrefix = totalWords - otherPrefixCount;

            // Determine actual query size: min of our target and theoretical maximum
            int effectiveQuerySize = min(querySize, maxPossibleForCurrentPrefix);

            // Ensure we're actually querying for more than we already have
            if (effectiveQuerySize <= currentCount) {
                querySize *= 2;
                continue;
            }

            cout << "query " << prefix << " " << effectiveQuerySize << endl;

            int responseCount;
            cin >> responseCount;

            // Read the returned words
            for (int i = 0; i < responseCount; ++i) {
                string word;
                cin >> word;
                collectedWords.insert(word);
            }

            currentCount = responseCount;

            // If fewer words returned than requested, no more words with this prefix
            if (responseCount < effectiveQuerySize) {
                break;
            }

            // Check global termination condition
            if (collectedWords.size() == totalWords) break;

            // Continue with larger query size for this prefix
            querySize *= 2;
        }
    }

    cout << "answer";
    for (const string& word : collectedWords) {
        cout << " " << word;
    }
    cout << endl;
}

int main() {
    int testCases;
    if (cin >> testCases) {
        while (testCases--) {
            processWords();
        }
    }
    return 0;
}

