// ===== UNIT TRIANGLE =====
UnitTriangle::UnitTriangle() {
    // Initialize cached parameter value
    cachedSkew = sc_clip(in0(Skew), 0.0f, 1.0f);

    // Determine if Skew input is audio-rate
    skewIsAudio = isAudioRateIn(Skew);

    // Assign calculation function and run one sample initially
    mCalcFunc = make_calc_function<UnitTriangle, &UnitTriangle::processNext>();
    processNext(1);
}

void UnitTriangle::processNext(int numSamples) {
    const float* phaseInput = in(Phase);
    float* outBuffer = out(Out);

    // Prepare slope for smooth interpolation of control-rate parameter
    SlopeGenerator skewSlope;
    if (!skewIsAudio) {
        float initialSkew = sc_clip(in0(Skew), 0.0f, 1.0f);
        skewSlope = SlopeGenerator(initialSkew, cachedSkew);
    }

    for (int idx = 0; idx < numSamples; ++idx) {
        // Normalize phase to [0,1)
        float currentPhase = sc_frac(phaseInput[idx]);

        float currentSkew;
        if (skewIsAudio) {
            currentSkew = sc_clip(in(Skew)[idx], 0.0f, 1.0f);
        } else {
            currentSkew = skewSlope.next();
        }

        outBuffer[idx] = UnitShapers::triangle(currentPhase, currentSkew);
    }

    // Update cached value based on input type
    if (skewIsAudio) {
        cachedSkew = sc_clip(in(Skew)[numSamples - 1], 0.0f, 1.0f);
    } else {
        cachedSkew = skewSlope.current();
    }
}

// ===== UNIT KINK =====
UnitKink::UnitKink() {
    cachedSkew = sc_clip(in0(Skew), 0.0f, 1.0f);
    skewIsAudio = isAudioRateIn(Skew);
    mCalcFunc = make_calc_function<UnitKink, &UnitKink::processNext>();
    processNext(1);
}

void UnitKink::processNext(int numSamples) {
    const float* phaseInput = in(Phase);
    float* outBuffer = out(Out);

    SlopeGenerator skewSlope;
    if (!skewIsAudio) {
        float initialSkew = sc_clip(in0(Skew), 0.0f, 1.0f);
        skewSlope = SlopeGenerator(initialSkew, cachedSkew);
    }

    for (int idx = 0; idx < numSamples; ++idx) {
        float currentPhase = sc_frac(phaseInput[idx]);

        float currentSkew;
        if (skewIsAudio) {
            currentSkew = sc_clip(in(Skew)[idx], 0.0f, 1.0f);
        } else {
            currentSkew = skewSlope.next();
        }

        outBuffer[idx] = UnitShapers::kink(currentPhase, currentSkew);
    }

    if (skewIsAudio) {
        cachedSkew = sc_clip(in(Skew)[numSamples - 1], 0.0f, 1.0f);
    } else {
        cachedSkew = skewSlope.current();
    }
}

// ===== UNIT CUBIC =====
UnitCubic::UnitCubic() {
    cachedIndex = sc_clip(in0(Index), 0.0f, 1.0f);
    indexIsAudio = isAudioRateIn(Index);
    mCalcFunc = make_calc_function<UnitCubic, &UnitCubic::processNext>();
    processNext(1);
}

void UnitCubic::processNext(int numSamples) {
    const float* phaseInput = in(Phase);
    float* outBuffer = out(Out);

    SlopeGenerator indexSlope;
    if (!indexIsAudio) {
        float initialIndex = sc_clip(in0(Index), 0.0f, 1.0f);
        indexSlope = SlopeGenerator(initialIndex, cachedIndex);
    }

    for (int idx = 0; idx < numSamples; ++idx) {
        float currentPhase = sc_frac(phaseInput[idx]);

        float currentIndex;
        if (indexIsAudio) {
            currentIndex = sc_clip(in(Index)[idx], 0.0f, 1.0f);
        } else {
            currentIndex = indexSlope.next();
        }

        outBuffer[idx] = UnitShapers::cubic(currentPhase, currentIndex);
    }

    if (indexIsAudio) {
        cachedIndex = sc_clip(in(Index)[numSamples - 1], 0.0f, 1.0f);
    } else {
        cachedIndex = indexSlope.current();
    }
}

