using RealVal = double;

// Loss function: linear objective with parameter vector p
template<typename T>
class ObjectiveFunc16 : public ROL::StdObjective<T> {
public:
  T value(const std::vector<T>& x, T& /*tol*/) override {
    auto param = getParameter();
    return std::inner_product(x.begin(), x.end(), param.begin(), static_cast<T>(0));
  }

  void gradient(std::vector<T>& grad, const std::vector<T>& x, T& /*tol*/) override {
    auto param = getParameter();
    grad.assign(param.begin(), param.end());
  }

  void hessVec(std::vector<T>& hv, const std::vector<T>& /*v*/, const std::vector<T>& /*x*/, T& /*tol*/) override {
    std::fill(hv.begin(), hv.end(), static_cast<T>(0));
  }
};

// Budget constraint: sum(x_i) == 1
template<typename T>
class ResourceConstraint16 : public ROL::StdConstraint<T> {
public:
  void value(std::vector<T>& c, const std::vector<T>& x, T& /*tol*/) override {
    T total = std::accumulate(x.begin(), x.end(), static_cast<T>(0));
    c[0] = total - static_cast<T>(1);
  }

  void applyJacobian(std::vector<T>& jv, const std::vector<T>& v, const T& /*x*/, T& /*tol*/) override {
    jv[0] = std::accumulate(v.begin(), v.end(), static_cast<T>(0));
  }

  void applyAdjointJacobian(std::vector<T>& ajv, const std::vector<T>& v, const T& /*x*/, T& /*tol*/) override {
    std::fill(ajv.begin(), ajv.end(), v[0]);
  }

  void applyAdjointHessian(std::vector<T>& ahuv, const std::vector<T>& /*u*/, const std::vector<T>& /*v*/,
                           const T& /*x*/, T& /*tol*/) override {
    std::fill(ahuv.begin(), ahuv.end(), static_cast<T>(0));
  }
};

void displayResult(const std::vector<RealVal>& solution, std::ostream& os) {
  size_t n = solution.size();
  os << "\nSolution vector:\n";
  os << "x = (";
  for (size_t idx = 0; idx < n - 1; ++idx) {
    os << solution[idx] << ", ";
  }
  os << solution[n - 1] << ")\n\n";
}

