  // feenableexcept(FE_DIVBYZERO | FE_INVALID | FE_OVERFLOW);
  ROL::GlobalMPISession commSession(&argc, &argv);

  int verboseFlag = argc - 1;
  bool verbose = verboseFlag > 0;
  ROL::Ptr<std::ostream> output;
  ROL::nullstream dummyStream;
  if (verbose)
    output = ROL::makePtrFromRef(std::cout);
  else
    output = ROL::makePtrFromRef(dummyStream);

  int status = 0;

  try {
    /**********************************************************************************************/
    /************************* SETUP SOLVER CONFIGURATION *****************************************/
    /**********************************************************************************************/
    std::string configPath = "input_16.xml";
    auto params = ROL::getParametersFromXmlFile(configPath);
    ROL::ParameterList globalParams = *params;
    globalParams.sublist("General").set("Output Level", verbose ? 1 : 0);

    /**********************************************************************************************/
    /************************* BUILD PROBLEM COMPONENTS *******************************************/
    /**********************************************************************************************/
    const size_t numAssets = 10;
    ROL::Ptr<ROL::StdVector<RealVal>> decisionVar =
        ROL::makePtr<ROL::StdVector<RealVal>>(numAssets, static_cast<RealVal>(0));

    int sampleCount = 1000;
    RealVal offsetVal = static_cast<RealVal>(0);
    std::vector<std::vector<RealVal>> varBounds;

    for (size_t i = 0; i < numAssets; ++i) {
      RealVal lower = -static_cast<RealVal>(std::rand()) / static_cast<RealVal>(RAND_MAX);
      RealVal upper =  static_cast<RealVal>(std::rand()) / static_cast<RealVal>(RAND_MAX);
      varBounds.emplace_back(std::initializer_list<RealVal>{lower, upper});
      *output << "Asset " << i << ": Lower=" << lower << ", Upper=" << upper << "\n";
      offsetVal += upper / static_cast<RealVal>(numAssets);
    }
    offsetVal *= static_cast<RealVal>(0.35);

    ROL::Ptr<ROL::BatchManager<RealVal>> batchMgr = ROL::makePtr<ROL::BatchManager<RealVal>>();
    ROL::Ptr<ROL::SampleGenerator<RealVal>> sampler =
        ROL::makePtr<ROL::MonteCarloGenerator<RealVal>>(sampleCount, varBounds, batchMgr);

    // Define loss objective
    ROL::Ptr<ROL::Objective<RealVal>> objFunc =
        ROL::makePtr<ObjectiveFunc16<RealVal>>();
    objFunc->setParameter(sampler->getMyPoint(0));

    // Wrap as constraint
    ROL::Ptr<ROL::Constraint<RealVal>> objAsConstr =
        ROL::makePtr<ROL::ConstraintFromObjective<RealVal>>(objFunc);
    ROL::Ptr<ROL::SingletonVector<RealVal>> multiplierObj =
        ROL::makePtr<ROL::SingletonVector<RealVal>>(0);
    ROL::Ptr<ROL::SingletonVector<RealVal>> upperBoundObj =
        ROL::makePtr<ROL::SingletonVector<RealVal>>(offsetVal);
    ROL::Ptr<ROL::BoundConstraint<RealVal>> boundObj =
        ROL::makePtr<ROL::Bounds<RealVal>>(*upperBoundObj, false);

    // Budget constraint
    ROL::Ptr<ROL::Constraint<RealVal>> budgetConstr =
        ROL::makePtr<ResourceConstraint16<RealVal>>();
    ROL::Ptr<ROL::StdVector<RealVal>> budgetMultiplier =
        ROL::makePtr<ROL::StdVector<RealVal>>(1, static_cast<RealVal>(0));

    // Construct stochastic problem
    ROL::Ptr<ROL::StochasticProblem<RealVal>> optProblem =
        ROL::makePtr<ROL::StochasticProblem<RealVal>>(objFunc, decisionVar);
    optProblem->addLinearConstraint("Budget", budgetConstr, budgetMultiplier);
    optProblem->addLinearConstraint("Loss", objAsConstr, multiplierObj, boundObj);

    // Validate deterministic setup
    optProblem->finalize(false, true, *output);
    optProblem->check(true, *output);

    std::vector<std::pair<std::string, std::vector<RealVal>>> results;

    // --- Case 1: Risk-neutral (Variance-based) ---
    optProblem->edit();
    ROL::ParameterList objSettings;
    objSettings.sublist("SOL").sublist("Objective").set("Type", "Deviation");
    objSettings.sublist("SOL").sublist("Objective").sublist("Deviation Measure").set("Name", "Variance");
    optProblem->makeObjectiveStochastic(objSettings, sampler);

    ROL::ParameterList conSettings1;
    conSettings1.sublist("SOL").sublist("Loss").set("Type", "Risk Neutral");
    optProblem->makeLinearConstraintStochastic("Loss", conSettings1, sampler, batchMgr);

    optProblem->finalize(false, true, *output);
    optProblem->check(true, *output);

    ROL::Ptr<ROL::Solver<RealVal>> solver1 =
        ROL::makePtr<ROL::Solver<RealVal>>(optProblem, params);
    solver1->solve(*output);
    status += (solver1->getAlgorithmState()->statusFlag == ROL::EXITSTATUS_CONVERGED ? 0 : 1);
    displayResult(*decisionVar->getVector(), *output);
    ROL::Ptr<ROL::Vector<RealVal>> tempVec = decisionVar->clone(); tempVec->set(*decisionVar);
    results.emplace_back("Risk Neutral", *decisionVar->getVector());

    // --- Case 2: Mean Value (re-solve same problem) ---
    optProblem->edit();
    optProblem->resetStochasticLinearConstraint("Loss");
    conSettings1.sublist("SOL").sublist("Loss").set("Type", "Mean Value");
    optProblem->makeLinearConstraintStochastic("Loss", conSettings1, sampler);

    optProblem->finalize(false, true, *output);
    optProblem->check(true, *output);

    ROL::Ptr<ROL::Solver<RealVal>> solver2 =
        ROL::makePtr<ROL::Solver<RealVal>>(optProblem, params);
    solver2->solve(*output);
    status += (solver2->getAlgorithmState()->statusFlag == ROL::EXITSTATUS_CONVERGED ? 0 : 1);
    displayResult(*decisionVar->getVector(), *output);
    tempVec->axpy(-1.0, *decisionVar);
    status += (tempVec->norm() > 100.0 * std::sqrt(ROL::ROL_EPSILON<RealVal>()) ? 1 : 0);
    results.emplace_back("Mean Value", *decisionVar->getVector());

    // --- Case 3: bPOE with CVaR ---
    optProblem->edit();
    ROL::ParameterList conSettings2;
    conSettings2.sublist("SOL").sublist("Loss").set("Type", "Risk Averse");
    conSettings2.sublist("SOL").sublist("Loss").sublist("Risk Measure").set("Name", "CVaR");
    conSettings2.sublist("SOL").sublist("Loss").sublist("Risk Measure").sublist("CVaR").set("Confidence Level", 0.95);
    conSettings2.sublist("SOL").sublist("Loss").sublist("Risk Measure").sublist("CVaR").set("Convex Combination Parameter", 1.0);
    conSettings2.sublist("SOL").sublist("Loss").sublist("Risk Measure").sublist("CVaR").set("Smoothing Parameter", 1e-4);
    conSettings2.sublist("SOL").sublist("Loss").sublist("Risk Measure").sublist("CVaR").sublist("Distribution").set("Name", "Parabolic");
    conSettings2.sublist("SOL").sublist("Loss").sublist("Risk Measure").sublist("CVaR").sublist("Distribution").sublist("Parabolic").set("Lower Bound", -0.5);
    conSettings2.sublist("SOL").sublist("Loss").sublist("Risk Measure").sublist("CVaR").sublist("Distribution").sublist("Parabolic").set("Upper Bound", 0.5);

    optProblem->removeLinearConstraint("Loss");
    optProblem->addConstraint("Loss", objAsConstr, multiplierObj, boundObj);
    optProblem->makeConstraintStochastic("Loss", conSettings2, sampler);

    optProblem->finalize(false, true, *output);
    optProblem->check(true, *output);

    ROL::Ptr<ROL::Solver<RealVal>> solver3 =
        ROL::makePtr<ROL::Solver<RealVal>>(optProblem, params);
    solver3->solve(*output);
    status += (solver3->getAlgorithmState()->statusFlag == ROL::EXITSTATUS_CONVERGED ? 0 : 1);
    displayResult(*decisionVar->getVector(), *output);
    results.emplace_back("bPOE", *decisionVar->getVector());

    // Output summary
    *output << "\n" << std::scientific << std::setprecision(6);
    for (const auto& entry : results) {
      *output << "  " << std::setw(20) << std::left << std::get<0>(entry);
      for (const auto& val : std::get<1>(entry)) {
        *output << std::setw(18) << std::left << val;
      }
      *output << "\n";
    }
    *output << "\n";
  }
  catch (const std::logic_error& e) {
    *output << "Exception caught: " << e.what() << "\n";
    status = -1000;
  }

  if (status != 0)
    std::cout << "End Result: TEST FAILED\n";
  else
    std::cout << "End Result: TEST PASSED\n";

  return 0;
}

