// Retrieve index of currently active CUDA device
int get_active_device_index()
{
    CUcontext ctx = nullptr;
    SGL_CU_CHECK(cuCtxGetCurrent(&ctx));
    SGL_REQUIRE(ctx, "No active CUDA context found when querying current device.");

    CUdevice dev = 0;
    SGL_CU_CHECK(cuCtxGetDevice(&dev));
    SGL_REQUIRE(dev >= 0, "Failed to retrieve current CUDA device ID.");
    return static_cast<int>(dev);
}

// Allocate memory on the GPU device
void* allocate_on_device(size_t bytes)
{
    CUdeviceptr addr;
    SGL_CU_CHECK(cuMemAlloc(&addr, bytes));
    return reinterpret_cast<void*>(addr);
}

// Free previously allocated device memory
void release_device_memory(void* ptr)
{
    if (!ptr) return;
    SGL_CU_CHECK(cuMemFree(reinterpret_cast<CUdeviceptr>(ptr)));
}

// Copy data between two device pointers
void copy_device_to_device(void* dest, const void* src, size_t num_bytes)
{
    SGL_CU_CHECK(cuMemcpyDtoD(reinterpret_cast<CUdeviceptr>(dest),
                              reinterpret_cast<CUdeviceptr>(src), num_bytes));
}

// Copy data from host to device
void copy_host_to_device(void* dest, const void* src, size_t num_bytes)
{
    SGL_CU_CHECK(cuMemcpyHtoD(reinterpret_cast<CUdeviceptr>(dest), src, num_bytes));
}

// Copy data from device to host
void copy_device_to_host(void* dest, const void* src, size_t num_bytes)
{
    SGL_CU_CHECK(cuMemcpyDtoH(dest, reinterpret_cast<CUdeviceptr>(src), num_bytes));
}

// Fill device memory with a byte pattern
void fill_device_memory(void* dst, uint8_t val, size_t count)
{
    SGL_CU_CHECK(cuMemsetD8(reinterpret_cast<CUdeviceptr>(dst), val, count));
}

// Asynchronous fill of device memory
void fill_device_memory_async(void* dst, uint8_t val, size_t count, CUstream stream)
{
    SGL_CU_CHECK(cuMemsetD8Async(reinterpret_cast<CUdeviceptr>(dst), val, count, stream));
}

// Import external shared memory resource into CUDA
CUexternalMemory import_shared_external_memory(const Buffer* buf)
{
    SGL_CU_SCOPE(buf->device());
    SGL_REQUIRE(buf, "Buffer pointer must not be null.");
    SGL_REQUIRE(is_set(buf->desc().usage, BufferUsage::shared), "Buffer lacks shared usage flag.");

    NativeHandle sh_handle = buf->shared_handle();
    SGL_REQUIRE(sh_handle, "Shared handle could not be created for buffer.");

    CUDA_EXTERNAL_MEMORY_HANDLE_DESC desc = {};
    switch (buf->device()->type()) {
#if SGL_WINDOWS
    case DeviceType::d3d12:
        desc.type = CU_EXTERNAL_MEMORY_HANDLE_TYPE_D3D12_RESOURCE;
        desc.handle.win32.handle = reinterpret_cast<void*>(sh_handle.value());
        break;
    case DeviceType::vulkan:
        desc.type = CU_EXTERNAL_MEMORY_HANDLE_TYPE_OPAQUE_WIN32;
        desc.handle.win32.handle = reinterpret_cast<void*>(sh_handle.value());
        break;
#elif SGL_LINUX
    case DeviceType::vulkan:
        desc.type = CU_EXTERNAL_MEMORY_HANDLE_TYPE_OPAQUE_FD;
        desc.handle.fd = static_cast<int>(sh_handle.value());
        break;
#endif
    default:
        SGL_THROW("Unsupported interop device type: {}.", buf->device()->type());
    }

    desc.size = buf->size();
    desc.flags = CUDA_EXTERNAL_MEMORY_DEDICATED;

    CUexternalMemory ext_mem;
    SGL_CU_CHECK(cuImportExternalMemory(&ext_mem, &desc));
    return ext_mem;
}

// Destroy imported external memory object
void release_external_memory(CUexternalMemory ext_mem)
{
    SGL_CU_CHECK(cuDestroyExternalMemory(ext_mem));
}

// Map external memory buffer to device address space
void* map_external_buffer(CUexternalMemory ext_mem, size_t offset, size_t size)
{
    CUDA_EXTERNAL_MEMORY_BUFFER_DESC mapping_desc = {};
    mapping_desc.offset = offset;
    mapping_desc.size = size;
    CUdeviceptr mapped_ptr = 0;
    SGL_CU_CHECK(cuExternalMemoryGetMappedBuffer(&mapped_ptr, ext_mem, &mapping_desc));
    return reinterpret_cast<void*>(mapped_ptr);
}

// Import external semaphore for cross-API synchronization
CUexternalSemaphore import_shared_semaphore(const Fence* fence)
{
    SGL_REQUIRE(fence, "Fence pointer must not be null.");
    SGL_REQUIRE(fence->desc().shared, "Fence was not created with shared flag.");

    NativeHandle sh_handle = fence->shared_handle();
    SGL_REQUIRE(sh_handle, "Shared handle creation failed for fence.");

    CUDA_EXTERNAL_SEMAPHORE_HANDLE_DESC desc = {};
    switch (fence->device()->type()) {
#if SGL_WINDOWS
    case DeviceType::d3d12:
        desc.type = CU_EXTERNAL_SEMAPHORE_HANDLE_TYPE_D3D12_FENCE;
        desc.handle.win32.handle = reinterpret_cast<void*>(sh_handle.value());
        break;
    case DeviceType::vulkan:
        desc.type = CU_EXTERNAL_SEMAPHORE_HANDLE_TYPE_TIMELINE_SEMAPHORE_WIN32;
        desc.handle.win32.handle = reinterpret_cast<void*>(sh_handle.value());
        break;
#elif SGL_LINUX
    case DeviceType::vulkan:
        desc.type = CU_EXTERNAL_SEMAPHORE_HANDLE_TYPE_TIMELINE_SEMAPHORE_FD;
        desc.handle.fd = static_cast<int>(sh_handle.value());
        break;
#endif
    default:
        SGL_THROW("Unsupported device type {} for semaphore import.", fence->device()->type());
    }

    CUexternalSemaphore ext_sem;
    SGL_CU_CHECK(cuImportExternalSemaphore(&ext_sem, &desc));
    return ext_sem;
}

// Release external semaphore
void release_external_semaphore(CUexternalSemaphore ext_sem)
{
    SGL_CU_CHECK(cuDestroyExternalSemaphore(ext_sem));
}

// Signal external semaphore asynchronously
void signal_semaphore_async(CUexternalSemaphore ext_sem, uint64_t val, CUstream stream)
{
    CUDA_EXTERNAL_SEMAPHORE_SIGNAL_PARAMS params = {};
    params.params.fence.value = val;
    SGL_CU_CHECK(cuSignalExternalSemaphoresAsync(&ext_sem, &params, 1, stream));
}

// Wait on external semaphore asynchronously
void wait_on_semaphore_async(CUexternalSemaphore ext_sem, uint64_t val, CUstream stream)
{
    CUDA_EXTERNAL_SEMAPHORE_WAIT_PARAMS params = {};
    params.params.fence.value = val;
    SGL_CU_CHECK(cuWaitExternalSemaphoresAsync(&ext_sem, &params, 1, stream));
}

// Find device index by matching LUID or UUID depending on platform
inline int locate_device_by_identifier(int total_devices, const AdapterLUID& id)
{
    for (int idx = 0; idx < total_devices; ++idx) {
        CUdevice dev;
        SGL_CU_CHECK(cuDeviceGet(&dev, idx));

#if SGL_WINDOWS
        std::array<char, 8> luid_storage;
        unsigned int node_mask;
        SGL_CU_CHECK(cuDeviceGetLuid(luid_storage.data(), &node_mask, dev));
        static_assert(sizeof(AdapterLUID) >= luid_storage.size());
        if (std::memcmp(luid_storage.data(), id.data(), luid_storage.size()) == 0)
            return idx;
#else
        CUuuid uuid;
        SGL_CU_CHECK(cuDeviceGetUuid(&uuid, dev));
        static_assert(sizeof(CUuuid) <= sizeof(AdapterLUID));
        if (std::memcmp(&uuid, id.data(), sizeof(CUuuid)) == 0)
            return idx;
#endif
    }
    return -1;
}

// Locate device by name match
inline int locate_device_by_name(int total_devices, std::string_view target_name)
{
    for (int idx = 0; idx < total_devices; ++idx) {
        char dev_name[256];
        SGL_CU_CHECK(cuDeviceGetName(dev_name, sizeof(dev_name), idx));
        if (target_name == dev_name)
            return idx;
    }
    return -1;
}

// Query integer-valued device attribute
inline int query_device_property(CUdevice dev, CUdevice_attribute attr)
{
    int result;
    SGL_CU_CHECK(cuDeviceGetAttribute(&result, attr, dev));
    return result;
}

// Constructor: wrap an existing RHI device as a CUDA device
Device::Device(const sgl::Device* rhi_dev)
{
    SGL_REQUIRE(rhi_dev, "RHI device pointer cannot be null.");
    SGL_REQUIRE(rhiCudaDriverApiInit(), "CUDA driver API initialization failed.");

    SGL_CU_CHECK(cuInit(0));

    int num_devices;
    SGL_CU_CHECK(cuDeviceGetCount(&num_devices));

    // Try matching via LUID first
    int chosen_idx = locate_device_by_identifier(num_devices, rhi_dev->info().adapter_luid);

    if (chosen_idx < 0) {
        log_warn("LUID-based device matching failed. Attempting name-based fallback.");
        chosen_idx = locate_device_by_name(num_devices, rhi_dev->info().adapter_name);
    }

    if (chosen_idx < 0) {
        log_warn("Name-based matching also failed. Falling back to compute capability heuristic.");
        for (int i = 0; i < num_devices; ++i) {
            if (query_device_property(i, CU_DEVICE_ATTRIBUTE_COMPUTE_CAPABILITY_MAJOR) >= 7) {
                chosen_idx = i;
                break;
            }
        }
    }

    if (chosen_idx < 0)
        SGL_THROW("No suitable CUDA-capable device found.");

    SGL_CU_CHECK(cuDeviceGet(&m_device, chosen_idx));
    SGL_CU_CHECK(cuDevicePrimaryCtxRetain(&m_context, m_device));
    m_owns_context = true;

    char name[256];
    SGL_CU_CHECK(cuDeviceGetName(name, sizeof(name), m_device));
    int major = query_device_property(m_device, CU_DEVICE_ATTRIBUTE_COMPUTE_CAPABILITY_MAJOR);
    int minor = query_device_property(m_device, CU_DEVICE_ATTRIBUTE_COMPUTE_CAPABILITY_MINOR);
    log_debug("Initialized CUDA context on \"{}\" (sm {}.{}).", name, major, minor);
}

// Constructor: share existing CUDA context
Device::Device(CUcontext ctx)
{
    m_context = ctx;
    SGL_CU_SCOPE(this);
    SGL_CU_CHECK(cuCtxGetDevice(&m_device));
    m_owns_context = false;

    char name[256];
    SGL_CU_CHECK(cuDeviceGetName(name, sizeof(name), m_device));
    int major = query_device_property(m_device, CU_DEVICE_ATTRIBUTE_COMPUTE_CAPABILITY_MAJOR);
    int minor = query_device_property(m_device, CU_DEVICE_ATTRIBUTE_COMPUTE_CAPABILITY_MINOR);
    log_debug("Sharing CUDA context on \"{}\" (sm {}.{}).", name, major, minor);
}

// Constructor: bind directly to a CUDA device
Device::Device(CUdevice dev)
{
    m_device = dev;
    SGL_CU_CHECK(cuDevicePrimaryCtxRetain(&m_context, m_device));
    m_owns_context = true;

    char name[256];
    SGL_CU_CHECK(cuDeviceGetName(name, sizeof(name), m_device));
    int major = query_device_property(m_device, CU_DEVICE_ATTRIBUTE_COMPUTE_CAPABILITY_MAJOR);
    int minor = query_device_property(m_device, CU_DEVICE_ATTRIBUTE_COMPUTE_CAPABILITY_MINOR);
    log_debug("Bound CUDA context to \"{}\" (sm {}.{}).", name, major, minor);
}

// Destructor: clean up context ownership
Device::~Device()
{
    if (m_owns_context) {
        SGL_CU_CHECK(cuDevicePrimaryCtxRelease(m_device));
    }
}

// Get adapter LUID for interoperability
AdapterLUID Device::adapter_luid() const
{
    AdapterLUID luid{};
    memset(luid.data(), 0, luid.size());

#if SGL_WINDOWS
    std::array<char, 8> luid_buf;
    unsigned int node_mask;
    SGL_CU_CHECK(cuDeviceGetLuid(luid_buf.data(), &node_mask, m_device));
    static_assert(luid_buf.size() <= sizeof(AdapterLUID));
    memcpy(luid.data(), luid_buf.data(), luid_buf.size());
#else
    CUuuid uuid;
    SGL_CU_CHECK(cuDeviceGetUuid(&uuid, m_device));
    static_assert(sizeof(uuid) <= sizeof(AdapterLUID));
    memcpy(luid.data(), &uuid, sizeof(CUuuid));
#endif

    return luid;
}

// Get human-readable adapter name
std::string Device::adapter_name() const
{
    char name[256];
    SGL_CU_CHECK(cuDeviceGetName(name, sizeof(name), m_device));
    return std::string{name};
}

// ExternalMemory wrapper implementation
ExternalMemory::ExternalMemory(const Buffer* buf)
    : m_resource(buf)
    , m_external_memory(import_shared_external_memory(buf))
    , m_size(buf->size())
{
}

ExternalMemory::~ExternalMemory()
{
    if (m_mapped_data) {
        SGL_CU_SCOPE(m_resource->device());
        SGL_CU_CHECK(cuMemFree(reinterpret_cast<CUdeviceptr>(m_mapped_data)));
        m_mapped_data = nullptr;
    }
    release_external_memory(m_external_memory);
}

void* ExternalMemory::mapped_data() const
{
    if (!m_mapped_data)
        m_mapped_data = map_external_buffer(m_external_memory, 0, m_size);
    return m_mapped_data;
}

// ExternalSemaphore wrapper implementation
ExternalSemaphore::ExternalSemaphore(Fence* f)
    : m_fence(f)
    , m_external_semaphore(import_shared_semaphore(f))
{
}

ExternalSemaphore::~ExternalSemaphore()
{
    release_external_semaphore(m_external_semaphore);
}

void ExternalSemaphore::signal(uint64_t val, CUstream stream)
{
    signal_semaphore_async(m_external_semaphore, val, stream);
}

void ExternalSemaphore::wait(uint64_t val, CUstream stream)
{
    wait_on_semaphore_async(m_external_semaphore, val, stream);
}

// Context scoping RAII helper
ContextScope::ContextScope(const Device* dev)
{
    SGL_CU_CHECK(cuCtxPushCurrent(dev->context()));
}

ContextScope::ContextScope(const sgl::Device* rhi_dev)
{
    if (rhi_dev->type() == DeviceType::cuda) {
        rhi::DeviceNativeHandles handles{};
        SLANG_RHI_CALL(rhi_dev->rhi_device()->getNativeDeviceHandles(&handles));
        SGL_ASSERT(handles.handles[2].type == rhi::NativeHandleType::CUcontext);
        SGL_CU_CHECK(cuCtxPushCurrent(reinterpret_cast<CUcontext>(handles.handles[2].value)));
    } else {
        SGL_ASSERT(rhi_dev->cuda_device());
        SGL_CU_CHECK(cuCtxPushCurrent(rhi_dev->cuda_device()->context()));
    }
}

ContextScope::~ContextScope()
{
    CUcontext dummy;
    SGL_CU_CHECK(cuCtxPopCurrent(&dummy));
}

