int main(int, char**)
{
    // Initialize Allegro subsystems
    al_init();
    al_install_keyboard();
    al_install_mouse();
    al_init_primitives_addon();

    // Configure display with resizing capability
    al_set_new_display_flags(ALLEGRO_RESIZABLE);
    ALLEGRO_DISPLAY* window = al_create_display(1280, 800);
    al_set_window_title(window, "Dear ImGui Allegro 5 example");

    // Create event handling infrastructure
    ALLEGRO_EVENT_QUEUE* eventQueue = al_create_event_queue();
    al_register_event_source(eventQueue, al_get_display_event_source(window));
    al_register_event_source(eventQueue, al_get_keyboard_event_source());
    al_register_event_source(eventQueue, al_get_mouse_event_source());

    // Initialize Dear ImGui context and configuration
    IMGUI_CHECKVERSION();
    ImGui::CreateContext();
    ImGuiIO& io = ImGui::GetIO(); (void)io;
    io.ConfigFlags |= ImGuiConfigFlags_NavEnableKeyboard;

    // Apply dark color scheme to the UI
    ImGui::StyleColorsDark();

    // Initialize Allegro 5 backend for Dear ImGui
    ImGui_ImplAllegro5_Init(window);

    // Font loading section (commented out as in original)
    // - Can be enabled by uncommenting specific AddFont calls
    // - Supports FreeType via IMGUI_ENABLE_FREETYPE definition
    // - Multiple fonts can be loaded and switched using PushFont/PopFont

    // Application state variables
    bool isDemoWindowVisible = true;
    bool isSecondaryWindowVisible = false;
    ImVec4 backgroundColor = ImVec4(0.45f, 0.55f, 0.60f, 1.00f);

    // Main application loop
    bool applicationRunning = true;
    while (applicationRunning)
    {
        // Process all pending events
        ALLEGRO_EVENT currentEvent;
        while (al_get_next_event(eventQueue, &currentEvent))
        {
            ImGui_ImplAllegro5_ProcessEvent(&currentEvent);

            if (currentEvent.type == ALLEGRO_EVENT_DISPLAY_CLOSE)
                applicationRunning = false;

            if (currentEvent.type == ALLEGRO_EVENT_DISPLAY_RESIZE)
            {
                ImGui_ImplAllegro5_InvalidateDeviceObjects();
                al_acknowledge_resize(window);
                ImGui_ImplAllegro5_CreateDeviceObjects();
            }
        }

        // Begin new frame for Dear ImGui
        ImGui_ImplAllegro5_NewFrame();
        ImGui::NewFrame();

        // Render main demo window if active
        if (isDemoWindowVisible)
            ImGui::ShowDemoWindow(&isDemoWindowVisible);

        // Render custom primary window
        {
            static float animationValue = 0.0f;
            static int clickCounter = 0;

            ImGui::Begin("Hello, world!");
            ImGui::Text("This is some useful text.");
            ImGui::Checkbox("Demo Window", &isDemoWindowVisible);
            ImGui::Checkbox("Another Window", &isSecondaryWindowVisible);
            ImGui::SliderFloat("float", &animationValue, 0.0f, 1.0f);
            ImGui::ColorEdit3("clear color", (float*)&backgroundColor);

            if (ImGui::Button("Button"))
                clickCounter++;

            ImGui::SameLine();
            ImGui::Text("counter = %d", clickCounter);
            ImGui::Text("Application average %.3f ms/frame (%.1f FPS)", 
                       1000.0f / io.Framerate, io.Framerate);
            ImGui::End();
        }

        // Render secondary window if active
        if (isSecondaryWindowVisible)
        {
            ImGui::Begin("Another Window", &isSecondaryWindowVisible);
            ImGui::Text("Hello from another window!");
            if (ImGui::Button("Close Me"))
                isSecondaryWindowVisible = false;
            ImGui::End();
        }

        // Finalize and render Dear ImGui content
        ImGui::Render();

        // Clear screen with background color (pre-multiplied alpha)
        al_clear_to_color(al_map_rgba_f(
            backgroundColor.x * backgroundColor.w,
            backgroundColor.y * backgroundColor.w,
            backgroundColor.z * backgroundColor.w,
            backgroundColor.w
        ));

        // Render Dear ImGui draw data
        ImGui_ImplAllegro5_RenderDrawData(ImGui::GetDrawData());
        al_flip_display();
    }

    // Cleanup resources
    ImGui_ImplAllegro5_Shutdown();
    ImGui::DestroyContext();
    al_destroy_event_queue(eventQueue);
    al_destroy_display(window);

    return 0;
}

int climbStairs(int n) {
    // Calculate number of distinct ways to climb to the top
    if (n <= 2) {
        return n;
    }

    int prev2 = 1;  // ways to climb 1 step
    int prev1 = 2;  // ways to climb 2 steps
    int current = 0;

    for (int i = 3; i <= n; ++i) {
        current = prev1 + prev2;
        prev2 = prev1;
        prev1 = current;
    }

    return current;
}

