#include <cstddef>

int main() {
    register unsigned long mhartid_reg;
    asm volatile ("csrr %0, mhartid" : "=r"(mhartid_reg));

    if (mhartid_reg == 0) {
        // Initialize variables for measurement
        unsigned dummy_var = 0u;
        volatile unsigned* target_ptr = &dummy_var;

        // Precompute harts ratio using initial time/instret samples
        unsigned long t0, t1, i0, i1;
        asm volatile ("csrr %0, time" : "=r"(t0));
        asm volatile ("csrr %0, instret" : "=r"(i0));
        asm volatile ("csrr %0, time" : "=r"(t1));
        asm volatile ("csrr %0, instret" : "=r"(i1));

        long delta_time = static_cast<long>(t1 - t0);
        long delta_inst = static_cast<long>(i1 - i0);
        int harts_ratio = (delta_inst != 0) ? static_cast<int>(delta_time / delta_inst) : 0;

        // Loop to compute bubble metrics over 5 iterations
        int bubble_count = 0;
        int prev_bubble = 0;
        int iteration = 0;

        while (iteration < 5) {
            unsigned long start_time, start_inst;
            asm volatile ("csrr %0, time" : "=r"(start_time));
            asm volatile ("csrr %0, instret" : "=r"(start_inst));

            // Toggle value between 0 and 4
            if (*target_ptr != 4u) {
                ++(*target_ptr);
            } else {
                --(*target_ptr);
            }

            unsigned long end_time, end_inst;
            asm volatile ("csrr %0, time" : "=r"(end_time));
            asm volatile ("csrr %0, instret" : "=r"(end_inst));

            long elapsed_time = static_cast<long>(end_time - start_time);
            long elapsed_inst = static_cast<long>(end_inst - start_inst);

            prev_bubble = bubble_count;
            bubble_count = (elapsed_time / harts_ratio) - elapsed_inst;

            ++iteration;
        }

        // Write final values to fixed physical addresses
        int* const pPenalty = reinterpret_cast<int*>(0x80200000UL);
        int* const pHarts   = reinterpret_cast<int*>(0x80200004UL);

        *pPenalty = bubble_count - prev_bubble;
        *pHarts   = harts_ratio;

        // Trigger system call
        asm volatile ("ecall");
    } else {
        // Spin forever on non-zero harts
        for (;;) {
            // Empty loop body
        }
    }

    return 0;
}

