namespace corosio = boost::corosio;
namespace capy    = boost::capy;

// Minimal coroutine that increments a counter atomically
capy::task<>
lightweight_task(std::atomic<std::uint64_t>& tally)
{
    tally.fetch_add(1u, std::memory_order_relaxed);
    co_return;
}

// Execute benchmark workload over specified time interval
void
execute_benchmark(
    perf::context_factory make_context,
    int runtime_seconds,
    int batch_size,
    int worker_count)
{
    auto ioc = make_context();
    auto ex  = ioc->get_executor();

    std::atomic<std::uint64_t> total_ops{0};
    auto const begin_time = std::chrono::steady_clock::now();
    auto const finish_time = begin_time + std::chrono::seconds(runtime_seconds);
    auto next_checkpoint = begin_time + std::chrono::seconds(2);

    std::cout << "Benchmark running for " << runtime_seconds << " seconds...\n";
    std::cout << "Batch size per cycle: " << batch_size << ", Worker threads: " << worker_count << "\n\n";

    std::uint64_t previous_total = 0;
    std::size_t cycles_completed = 0;

    while (std::chrono::steady_clock::now() < finish_time)
    {
        // Enqueue tasks in batches
        for (int idx = 0; idx < batch_size; ++idx)
            capy::run_async(ex)(lightweight_task(total_ops));

        // Run workers depending on thread count
        if (worker_count > 1)
        {
            std::vector<std::thread> pool;
            pool.reserve(static_cast<std::size_t>(worker_count));
            for (int t = 0; t < worker_count; ++t)
                pool.emplace_back([&ioc_ref = *ioc]() { ioc_ref.run(); });
            for (auto& th : pool)
                th.join();
        }
        else
        {
            ioc->run();
        }

        ioc->restart();
        ++cycles_completed;

        // Report progress every 2 seconds
        auto current_time = std::chrono::steady_clock::now();
        if (current_time >= next_checkpoint)
        {
            double elapsed_sec =
                std::chrono::duration<double>(current_time - begin_time).count();
            std::uint64_t now_total = total_ops.load(std::memory_order_relaxed);
            double ops_per_sec = static_cast<double>(now_total - previous_total) / 2.0;
            std::cout << "  [" << std::fixed << std::setprecision(0) << elapsed_sec
                      << "s] " << perf::format_rate(ops_per_sec) << " (" 
                      << cycles_completed << " cycles)\n";
            previous_total = now_total;
            next_checkpoint = current_time + std::chrono::seconds(2);
        }
    }

    // Final summary
    auto final_time = std::chrono::steady_clock::now();
    double total_duration =
        std::chrono::duration<double>(final_time - begin_time).count();
    std::uint64_t grand_total = total_ops.load(std::memory_order_relaxed);
    double average_throughput = static_cast<double>(grand_total) / total_duration;

    std::cout << "\n=== Summary ===\n";
    std::cout << "  Duration:   " << std::fixed << std::setprecision(2)
              << total_duration << " s\n";
    std::cout << "  Total ops:  " << grand_total << "\n";
    std::cout << "  Cycles:     " << cycles_completed << "\n";
    std::cout << "  Avg rate:   " << perf::format_rate(average_throughput) << "\n";
}

// Entry point for running the profiler test
void
launch_profiler_test(
    perf::context_factory factory,
    const char* backend_label,
    int run_length,
    int items_per_batch,
    int num_workers)
{
    std::cout << "Corosio Profiler Test: Batch Size Impact\n";
    std::cout << "=========================================\n";
    std::cout << "Backend: " << backend_label << "\n\n";
    std::cout << "Focus areas:\n";
    std::cout << "  - Queue traversal overhead\n";
    std::cout << "  - Completion handling efficiency\n";
    std::cout << "  - Cache-friendly access patterns\n";
    std::cout << "  - Per-operation dispatch cost at scale\n\n";

    // Warm-up phase
    std::cout << "Warming up (1 second)...\n";
    {
        auto warmup_ioc = factory();
        auto warmup_ex  = warmup_ioc->get_executor();
        std::atomic<std::uint64_t> warmup_counter{0};
        auto const warmup_deadline =
            std::chrono::steady_clock::now() + std::chrono::seconds(1);

        while (std::chrono::steady_clock::now() < warmup_deadline)
        {
            for (int k = 0; k < 1000; ++k)
                capy::run_async(warmup_ex)(lightweight_task(warmup_counter));
            warmup_ioc->poll();
            warmup_ioc->restart();
        }
    }
    std::cout << "Warm-up finished.\n\n";

    // Main test
    execute_benchmark(factory, run_length, items_per_batch, num_workers);
    std::cout << "\nBenchmark completed.\n";
}

// Print usage information
void
show_usage(const char* program_invocation)
{
    std::cout << "Usage: " << program_invocation << " [OPTIONS]\n\n";
    std::cout
        << "Profiling tool to measure dispatch performance under heavy queue load.\n\n";
    std::cout << "Options:\n";
    std::cout << "  --backend <name>     Choose I/O backend (default: platform default)\n";
    std::cout << "  --time <seconds>     Run duration (default: 10)\n";
    std::cout << "  --batch <count>      Tasks per dispatch cycle (default: 100000)\n";
    std::cout << "  --workers <count>    Number of worker threads (default: 1)\n";
    std::cout << "  --list               Show supported backends\n";
    std::cout << "  --help               Display this help text\n";
    std::cout << "\n";
    std::cout << "Example:\n";
    std::cout << "  " << program_invocation << " --batch 50000 --workers 4\n";
    std::cout << "\n";
    perf::print_available_backends();
}

// Program entry point
int
main(int argc, char* argv[])
{
    const char* selected_backend = nullptr;
    int run_duration             = 10;
    int items_per_cycle          = 100000;
    int worker_threads           = 1;

    // Parse CLI arguments
    for (int pos = 1; pos < argc; ++pos)
    {
        if (std::strcmp(argv[pos], "--backend") == 0)
        {
            if (++pos >= argc || !argv[pos][0])
            {
                std::cerr << "Error: --backend requires an argument\n";
                return 1;
            }
            selected_backend = argv[pos];
        }
        else if (std::strcmp(argv[pos], "--time") == 0)
        {
            if (++pos >= argc || !argv[pos][0])
            {
                std::cerr << "Error: --time requires an argument\n";
                return 1;
            }
            run_duration = std::atoi(argv[pos]);
        }
        else if (std::strcmp(argv[pos], "--batch") == 0)
        {
            if (++pos >= argc || !argv[pos][0])
            {
                std::cerr << "Error: --batch requires an argument\n";
                return 1;
            }
            items_per_cycle = std::atoi(argv[pos]);
        }
        else if (std::strcmp(argv[pos], "--workers") == 0)
        {
            if (++pos >= argc || !argv[pos][0])
            {
                std::cerr << "Error: --workers requires an argument\n";
                return 1;
            }
            worker_threads = std::atoi(argv[pos]);
        }
        else if (std::strcmp(argv[pos], "--list") == 0)
        {
            perf::print_available_backends();
            return 0;
        }
        else if (std::strcmp(argv[pos], "--help") == 0 ||
                 std::strcmp(argv[pos], "-h") == 0)
        {
            show_usage(argv[0]);
            return 0;
        }
        else
        {
            std::cerr << "Unknown option: " << argv[pos] << "\n";
            show_usage(argv[0]);
            return 1;
        }
    }

    // Argument validation
    if (items_per_cycle < 1)
    {
        std::cerr << "Error: --batch must be ≥ 1\n";
        return 1;
    }
    if (worker_threads < 1)
    {
        std::cerr << "Error: --workers must be ≥ 1\n";
        return 1;
    }

    // Use default backend if none specified
    if (!selected_backend)
        selected_backend = perf::default_backend_name();

    // Dispatch based on selected backend
    return perf::dispatch_backend(
        selected_backend,
        [=](perf::context_factory factory, auto, const char* name) {
            launch_profiler_test(factory, name, run_duration, items_per_cycle, worker_threads);
        });
}

