#include <iostream>
#include <vector>
#include <bitset>
#include <algorithm>
#include <random>
#include <chrono>
#include <numeric>
using namespace std;

// ----------------------
// Configuration & State
// ----------------------
constexpr int MAX_VERTEX = 1005;
constexpr double TIMEOUT_SEC = 1.95;

int numVertices, numEdges;
bitset<MAX_VERTEX> adjacencyMatrix[MAX_VERTEX];
vector<int> adjacencyList[MAX_VERTEX];
bool vertexInSet[MAX_VERTEX];
int neighborCountInSet[MAX_VERTEX];
int bestConfiguration[MAX_VERTEX];
int largestIndependentSetSize = 0;

mt19937 randomEngine(1337);

auto startTime = chrono::high_resolution_clock::now();

double elapsedSeconds() {
    auto currentTime = chrono::high_resolution_clock::now();
    return chrono::duration<double>(currentTime - startTime).count();
}

// ----------------------
// Core Operations
// ----------------------

void includeVertex(int v) {
    if (vertexInSet[v]) return;
    vertexInSet[v] = true;
    for (int w : adjacencyList[v]) {
        neighborCountInSet[w]++;
    }
}

void excludeVertex(int v) {
    if (!vertexInSet[v]) return;
    vertexInSet[v] = false;
    for (int w : adjacencyList[v]) {
        neighborCountInSet[w]--;
    }
}

void recordBestSolution() {
    int currentSize = 0;
    for (int i = 1; i <= numVertices; ++i)
        if (vertexInSet[i]) ++currentSize;

    if (currentSize > largestIndependentSetSize) {
        largestIndependentSetSize = currentSize;
        copy(begin(vertexInSet), end(vertexInSet), begin(bestConfiguration));
    }
}

int findUniqueNeighbor(int v) {
    for (int u : adjacencyList[v])
        if (vertexInSet[u]) return u;
    return -1;
}

void buildInitialGreedySolution() {
    fill_n(vertexInSet, MAX_VERTEX, false);
    fill_n(neighborCountInSet, MAX_VERTEX, 0);

    vector<int> order(numVertices);
    iota(order.begin(), order.end(), 1);
    shuffle(order.begin(), order.end(), randomEngine);

    for (int candidate : order) {
        if (neighborCountInSet[candidate] == 0)
            includeVertex(candidate);
    }

    recordBestSolution();
}

// ----------------------
// Main Optimization Loop (ILS Framework)
// ----------------------
void optimize() {
    buildInitialGreedySolution();

    vector<int> tabuUntil(MAX_VERTEX + 1, 0);
    int iteration = 0;
    int stagnantIterations = 0;

    const int TABU_DURATION_MIN = 7;
    const int MAX_STAGNANT = 2500;

    vector<vector<int>> candidatesPerVertex(MAX_VERTEX + 1);

    while (true) {
        // Periodic timeout check
        if ((iteration & 127) == 0 && elapsedSeconds() > TIMEOUT_SEC)
            break;
        ++iteration;

        bool progressMade = false;

        // --- Phase A: Immediate Inclusions ---
        vector<int> zeroNeighbors;
        for (int v = 1; v <= numVertices; ++v) {
            if (!vertexInSet[v] && neighborCountInSet[v] == 0)
                zeroNeighbors.push_back(v);
        }

        if (!zeroNeighbors.empty()) {
            for (int v : zeroNeighbors) includeVertex(v);
            recordBestSolution();
            stagnantIterations = 0;
            progressMade = true;
        }

        if (progressMade) continue;

        // --- Phase B: (1,2)-Swaps ---
        vector<int> exactlyOneNeighbor;
        for (int v = 1; v <= numVertices; ++v) {
            if (!vertexInSet[v] && neighborCountInSet[v] == 1)
                exactlyOneNeighbor.push_back(v);
        }

        vector<int> activeCenters;
        for (int v : exactlyOneNeighbor) {
            int center = findUniqueNeighbor(v);
            if (center != -1) {
                if (candidatesPerVertex[center].empty())
                    activeCenters.push_back(center);
                candidatesPerVertex[center].push_back(v);
            }
        }

        bool swapPerformed = false;
        for (int center : activeCenters) {
            auto& pool = candidatesPerVertex[center];
            if (pool.size() >= 2) {
                for (size_t i = 0; i < pool.size(); ++i) {
                    for (size_t j = i + 1; j < pool.size(); ++j) {
                        int v1 = pool[i], v2 = pool[j];
                        if (!adjacencyMatrix[v1][v2]) {
                            excludeVertex(center);
                            includeVertex(v1);
                            includeVertex(v2);

                            tabuUntil[center] = iteration + TABU_DURATION_MIN + (randomEngine() % 5);
                            swapPerformed = true;
                            goto finish_swap_search;
                        }
                    }
                }
            }
        }
        finish_swap_search:

        for (int c : activeCenters) candidatesPerVertex[c].clear();

        if (swapPerformed) {
            recordBestSolution();
            stagnantIterations = 0;
            continue;
        }

        // --- Phase C: (1,1)-Swaps via Tabu Search ---
        vector<int> eligibleMoves;
        for (int v : exactlyOneNeighbor) {
            int partner = findUniqueNeighbor(v);
            if (tabuUntil[v] <= iteration && tabuUntil[partner] <= iteration)
                eligibleMoves.push_back(v);
        }

        if (!eligibleMoves.empty()) {
            int chosenV = eligibleMoves[randomEngine() % eligibleMoves.size()];
            int removed = findUniqueNeighbor(chosenV);

            excludeVertex(removed);
            includeVertex(chosenV);

            int tenure = TABU_DURATION_MIN + (randomEngine() % 5);
            tabuUntil[removed] = tabuUntil[chosenV] = iteration + tenure;

            ++stagnantIterations;
        } else {
            stagnantIterations += 50;
        }

        // --- Phase D: Perturbation / Restart ---
        if (stagnantIterations > MAX_STAGNANT) {
            if (elapsedSeconds() > TIMEOUT_SEC - 0.05) break;

            // Restore best known state
            fill_n(vertexInSet, MAX_VERTEX, false);
            copy_n(bestConfiguration, MAX_VERTEX, vertexInSet);

            // Recompute tightness values
            fill_n(neighborCountInSet, MAX_VERTEX, 0);
            for (int v = 1; v <= numVertices; ++v) {
                if (vertexInSet[v]) {
                    for (int w : adjacencyList[v]) {
                        neighborCountInSet[w]++;
                    }
                }
            }

            // Kick: Remove ~6% of vertices randomly
            vector<int> currentMembers;
            for (int v = 1; v <= numVertices; ++v)
                if (vertexInSet[v]) currentMembers.push_back(v);

            if (!currentMembers.empty()) {
                shuffle(currentMembers.begin(), currentMembers.end(), randomEngine);
                int removals = max(3, static_cast<int>(currentMembers.size() / 15));
                for (int k = 0; k < removals && k < static_cast<int>(currentMembers.size()); ++k)
                    excludeVertex(currentMembers[k]);
            }

            fill(tabuUntil.begin(), tabuUntil.end(), 0);
            stagnantIterations = 0;
        }
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    if (!(cin >> numVertices >> numEdges)) return 0;

    for (int i = 0; i < numEdges; ++i) {
        int a, b;
        cin >> a >> b;
        if (a == b) continue;
        if (!adjacencyMatrix[a][b]) {
            adjacencyMatrix[a][b] = adjacencyMatrix[b][a] = true;
            adjacencyList[a].push_back(b);
            adjacencyList[b].push_back(a);
        }
    }

    optimize();

    for (int i = 1; i <= numVertices; ++i)
        cout << bestConfiguration[i] << '\n';

    return 0;
}

#include <iostream>

void performInsertionSort(int data[], int size) {
    for (int position = 1; position < size; ++position) {
        int currentValue = data[position];
        int comparisonIndex = position - 1;

        // Shift elements greater than currentValue to the right
        while (comparisonIndex >= 0 && data[comparisonIndex] > currentValue) {
            data[comparisonIndex + 1] = data[comparisonIndex];
            --comparisonIndex;
        }

        // Place currentValue at its correct position
        data[comparisonIndex + 1] = currentValue;
    }
}

int main() {
    int arr[] = {5, 2, 8, 1, 9};
    int n = sizeof(arr) / sizeof(arr[0]);

    performInsertionSort(arr, n);

    // Print sorted array
    for (int i = 0; i < n; ++i) {
        std::cout << arr[i] << " ";
    }
    std::cout << std::endl;

    return 0;
}

