// Constructor: Initialize UI components and start DLC installation if applicable
UIScene_SaveMessage::UIScene_SaveMessage(int playerIndex, void* userData, UILayer* layerParent)
    : UIScene(playerIndex, layerParent)
{
    // Load and initialize UI assets
    prepareMovie();

    // Add static UI elements
    layerParent->addComponent(playerIndex, eUIComponent_Panorama);
    layerParent->addComponent(playerIndex, eUIComponent_Logo);

    // Initialize interactive controls
    m_buttonConfirm.init(app.GetString(IDS_CONFIRM_OK), eControl_Confirm);
    m_labelDescription.init(app.GetString(IDS_SAVE_ICON_MESSAGE));

    // Auto-resize layout (especially important for certain locales like Russian)
    IggyDataValue resizeResult;
    IggyResult res = IggyPlayerCallMethodRS(
        getMovie(),
        &resizeResult,
        IggyPlayerRootPath(getMovie()),
        m_funcAutoResize,
        0,
        nullptr
    );

    // Attempt DLC install if signed-in user is active and not already installing
    for (unsigned int pid = 0; pid < XUSER_MAX_COUNT; ++pid) {
        if (InputManager.IsPadConnected(pid) || ProfileManager.IsSignedIn(pid)) {
            if (!app.DLCInstallProcessCompleted() && !app.DLCInstallPending()) {
                app.StartInstallDLCProcess(pid);
                break;
