#include <bits/stdc++.h>
using namespace std;

int main() {
    int n, k;
    scanf("%d%d", &n, &k);

    vector<int> parent(n + 1);
    for (int i = 1; i <= n; ++i) {
        parent[i] = i;
    }

    function<int(int)> find = [&](int x) {
        return parent[x] == x ? x : parent[x] = find(parent[x]);
    };

    auto unite = [&](int x, int y) {
        int px = find(x), py = find(y);
        if (px != py) {
            parent[px] = py;
        }
    };

    for (int i = 1; i <= n; ++i) {
        // Reset memory
        printf("R\n");
        fflush(stdout);

        // Query current element
        printf("? %d\n", i);
        fflush(stdout);

        char resp;
        scanf(" %c", &resp);

        // Check all remaining elements for equivalence
        for (int j = i + 1; j <= n; ++j) {
            printf("? %d\n", j);
            fflush(stdout);
            scanf(" %c", &resp);

            if (resp == 'Y') {
                unite(i, j);
            }
        }
    }

    // Count distinct roots
    int distinct = 0;
    for (int i = 1; i <= n; ++i) {
        if (find(i) == i) {
            distinct++;
        }
    }

    printf("! %d\n", distinct);
    fflush(stdout);

    return 0;
}

