HRESULT CScene_FullscreenProgress::OnInit( XUIMessageInit* pInitData, BOOL& bHandled )
{
    MapChildControls();

    // Set confirm button label
    m_buttonConfirm.SetText( app.GetString( IDS_CONFIRM_OK ) );

    // Extract parameters from init data
    LoadingInputParams *initParams = static_cast<LoadingInputParams*>(pInitData->pvInitData);
    m_CompletionData = initParams->completionData;
    m_iPad = m_CompletionData->iPad;
    m_cancelFunc = initParams->cancelFunc;
    m_cancelFuncParam = initParams->m_cancelFuncParam;
    m_completeFunc = initParams->completeFunc;
    m_completeFuncParam = initParams->m_completeFuncParam;
    m_bWasCancelled = false;

    // Launch worker thread
    thread = new C4JThread(initParams->func, initParams->lpParam, "FullscreenProgress");
    thread->SetProcessor(3); // TODO 4J Stu - Verify optimal core usage

    m_threadCompleted = false;
    threadStarted = false;

    // Adjust UI layout based on current scene context
    int currentBasePos = CXuiSceneBase::GetPlayerBasePosition(m_iPad);
    if (currentBasePos != CXuiSceneBase::e_BaseScene_Fullscreen &&
        currentBasePos != CXuiSceneBase::e_BaseScene_NotSet)
    {
        app.AdjustSplitscreenScene(m_hObj, &m_OriginalPosition, m_iPad, false);
        CXuiSceneBase::ShowLogo(m_iPad, FALSE);
    }
    else
    {
        CXuiSceneBase::ShowLogo(m_iPad, m_CompletionData->bShowLogo);
    }

    // Configure background and tooltips
    CXuiSceneBase::ShowBackground(m_iPad, m_CompletionData->bShowBackground);
    ui.SetTooltips(m_iPad, -1, initParams->cancelText, -1, -1);

    // Reset progress renderer state
    Minecraft *pGame = Minecraft::GetInstance();
    pGame->progressRenderer->progressStart(-1);
    pGame->progressRenderer->progressStage(-1);

    // Update tip text
    wstring tipContent = app.FormatHTMLString(m_iPad, app.GetString(app.GetNextTip()));
    wchar_t htmlHeader[64];
    swprintf(htmlHeader, 64, L"<font color=\"#%08x\" size=14><DIV ALIGN=CENTER>", app.GetHTMLColour(eHTMLColor_White));
    tipContent = wstring(htmlHeader) + tipContent + L"</DIV>";
    XuiControlSetText(m_tip, tipContent.c_str());
    m_tip.SetShow(m_CompletionData->bShowTips);

    return S_OK;
}

