// Timer-driven logic: monitor thread status and update UI accordingly
HRESULT CScene_FullscreenProgress::OnTimer(XUIMessageTimer *pTimer, BOOL& bHandled)
{
    int rawExitCode = thread->GetExitCode();
    DWORD actualExitCode = static_cast<DWORD>(rawExitCode);

    if (actualExitCode != STILL_ACTIVE)
    {
        // Stop timers and clear tip display
        XuiKillTimer(m_hObj, TIMER_FULLSCREEN_PROGRESS);
        XuiKillTimer(m_hObj, TIMER_FULLSCREEN_TIPS);
        XuiControlSetText(m_tip, L"");
        m_tip.SetShow(FALSE);

        // Handle non-successful exit codes
        if (actualExitCode != S_OK)
        {
            if (actualExitCode == ERROR_CANCELLED)
            {
                // Thread was cancelled externally; ignore silently
            }
            else
            {
                // Show error dialog and navigate to home menu
                UINT msgArgs[1] = { IDS_CONFIRM_OK };
                StorageManager.RequestMessageBox(
                    IDS_CONNECTION_FAILED,
                    IDS_CONNECTION_LOST_SERVER,
                    msgArgs, 1,
                    ProfileManager.GetPrimaryPad(),
                    nullptr, nullptr,
                    app.GetStringTable()
                );
                app.NavigateToHomeMenu();
                ui.UpdatePlayerBasePositions();
            }
        }
        else
        {
            // Thread succeeded
            if (m_CompletionData->bRequiresUserAction && !m_bWasCancelled)
            {
                m_threadCompleted = true;
                m_buttonConfirm.SetShow(TRUE);
                m_buttonConfirm.SetFocus(ProfileManager.GetPrimaryPad());
                ui.SetTooltips(m_iPad, IDS_TOOLTIPS_SELECT, -1, -1, -1);
            }
            else
            {
                if (m_bWasCancelled)
                    m_threadCompleted = true;

                // Perform post-completion actions
                eProgressCompletionType finalAction = m_CompletionData->type;

                if (finalAction == e_ProgressCompletion_AutosaveNavigateBack)
                {
                    int iPad = m_CompletionData->iPad;
                    CXuiSceneBase::ShowBackground(iPad, FALSE);
                    CXuiSceneBase::ShowLogo(iPad, FALSE);
                    app.NavigateBack(iPad);
                    app.SetIgnoreAutosaveMenuDisplayed(iPad, false);
                    CXuiSceneBase::ShowOtherPlayersBaseScene(iPad, true);

                    Minecraft *pGame = Minecraft::GetInstance();
                    if (pGame->localgameModes[ProfileManager.GetPrimaryPad()] != nullptr)
                        pGame->localgameModes[ProfileManager.GetPrimaryPad()]->getTutorial()->showTutorialPopup(true);

                    ui.UpdatePlayerBasePositions();
                }
                else if (finalAction == e_ProgressCompletion_NavigateBack)
                {
                    int iPad = m_CompletionData->iPad;
                    CXuiSceneBase::ShowBackground(iPad, FALSE);
                    CXuiSceneBase::ShowBackground(iPad, TRUE);
                    app.NavigateBack(iPad);
                    CXuiSceneBase::ShowOtherPlayersBaseScene(iPad, true);
                    ui.UpdatePlayerBasePositions();
                }
                else if (finalAction == e_ProgressCompletion_NavigateBackToScene)
                {
                    CXuiSceneBase::ShowBackground(m_CompletionData->iPad, FALSE);
                    CXuiSceneBase::ShowBackground(m_CompletionData->iPad, TRUE);
                    CXuiSceneBase::ShowOtherPlayersBaseScene(m_CompletionData->iPad, true);

                    if (app.IsSceneInStack(m_CompletionData->iPad, m_CompletionData->scene))
                        app.NavigateBack(m_CompletionData->iPad, false, m_CompletionData->scene);
                    else
                        app.CloseXuiScenesAndNavigateToScene(m_CompletionData->iPad, m_CompletionData->scene);

                    ui.UpdatePlayerBasePositions();
                }
                else if (finalAction == e_ProgressCompletion_CloseUIScenes)
                {
                    app.CloseXuiScenes(m_CompletionData->iPad);
                    ui.UpdatePlayerBasePositions();
                }
                else if (finalAction == e_ProgressCompletion_CloseAllPlayersUIScenes)
                {
                    app.CloseAllPlayersXuiScenes();
                    ui.UpdatePlayerBasePositions();
                }
                else if (finalAction == e_ProgressCompletion_NavigateToHomeMenu)
                {
                    app.NavigateToHomeMenu();
                    // ui.UpdatePlayerBasePositions(); intentionally commented out
                }
            }
        }
    }
    else
    {
        // Thread still running — handle periodic updates
        switch (pTimer->nId)
        {
        case TIMER_FULLSCREEN_TIPS:
            {
                wstring nextTip = app.FormatHTMLString(m_iPad, app.GetString(app.GetNextTip()));
                wchar_t header[64];
                swprintf(header, 64, L"<font color=\"#%08x\" size=14><DIV ALIGN=CENTER>",
                         app.GetHTMLColour(eHTMLColor_White));
                nextTip = wstring(header) + nextTip + L"</DIV>";
                XuiControlSetText(m_tip, nextTip.c_str());
            }
            break;
        case TIMER_FULLSCREEN_PROGRESS:
        default:
            break;
        }
    }

    bHandled = TRUE;
    return S_OK;
}

