ChestModel::ChestModel()
{
    // Initialize chest components: lid, lock, and base
    ModelPart* tempLid = new ModelPart(this, 0, 0);
    lid = tempLid->setTexSize(64, 64);
    lid->addBox(0.0f, -5.0f, -14.0f, 14, 5, 14, 0.0f);
    lid->offsetX = 1;
    lid->offsetY = 7;
    lid->offsetZ = 15;

    ModelPart* tempLock = new ModelPart(this, 0, 0);
    lock = tempLock->setTexSize(64, 64);
    lock->addBox(-1.0f, -2.0f, -15.0f, 2, 4, 1, 0.0f);
    lock->offsetX = 8;
    lock->offsetY = 7;
    lock->offsetZ = 15;

    ModelPart* tempBase = new ModelPart(this, 0, 19);
    bottom = tempBase->setTexSize(64, 64);
    bottom->addBox(0.0f, 0.0f, 0.0f, 14, 10, 14, 0.0f);
    bottom->offsetX = 1;
    bottom->offsetY = 6;
    bottom->offsetZ = 1;

    // Precompile geometry to prevent first-render stutter
    lid->buildDisplayList(1.0f / 16.0f);
    lock->buildDisplayList(1.0f / 16.0f);
    bottom->buildDisplayList(1.0f / 16.0f);
}

void ChestModel::render(bool useCompiledList)
{
    // Sync lock rotation with lid movement
    lock->rotateX = lid->rotateX;

    // Render order: lock & base first, then lid with z-bias to avoid visual artifacts
    lock->draw(1.0f / 16.0f, useCompiledList);
    bottom->draw(1.0f / 16.0f, useCompiledList);

    // Apply negative polygon offset to lift lid slightly in depth buffer
    glPolygonOffset(-0.3f, -0.3f);
    lid->draw(1.0f / 16.0f, useCompiledList);
    glPolygonOffset(0.0f, 0.0f);  // Reset offset for subsequent rendering
}

