#include <iostream>
#include <fstream>
#include <random>
#include "../performance_counters/event_counter.h"

int main()
{
    std::cout << "RC Lowpass test (Faust)\n";
    static constexpr float sample_rate = 48000.0f;

    mydsp processor {};
    processor.init(sample_rate);

    static constexpr size_t buffer_size = 100'000'000;
    static constexpr int repeat_count = 4;

    float* input_buffer = static_cast<float*>(std::malloc(buffer_size * sizeof(float)));
    float* output_buffer = static_cast<float*>(std::malloc(buffer_size * sizeof(float)));

    std::random_device random_seed {};
    std::mt19937 rng_engine(random_seed());
    std::uniform_real_distribution<float> uniform_dist(-1.0f, 1.0f);

    event_collector measurement_collector {};

    {
        event_aggregate timing_stats {};
        float final_output_value = 0.0f;

        for (int run = 0; run < repeat_count; ++run)
        {
            // Fill input buffer with random samples
            for (size_t idx = 0; idx < buffer_size; ++idx)
                input_buffer[idx] = uniform_dist(rng_engine);

            measurement_collector.start();
            processor.compute(static_cast<int>(buffer_size), &input_buffer, &output_buffer);
            timing_stats << measurement_collector.end();

            final_output_value += output_buffer[buffer_size - 1];
        }

        std::cout << final_output_value << '\n';
        pretty_print(timing_stats, static_cast<int>(buffer_size), "Faust");
    }

    std::free(input_buffer);
    std::free(output_buffer);

    return 0;
}

#include <bits/stdc++.h>
using namespace std;
using i64 = long long;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int testCases;
    if (!(cin >> testCases)) return 0;

    while (testCases--) {
        int n, m;
        i64 penalty;
        cin >> n >> m >> penalty;

        vector<i64> A(n + 1), B(m + 1);
        for (int idx = 1; idx <= n; ++idx) cin >> A[idx];
        for (int idx = 1; idx <= m; ++idx) cin >> B[idx];

        // Prefix sums for array A
        vector<i64> prefixA(n + 1, 0);
        for (int i = 1; i <= n; ++i) {
            prefixA[i] = prefixA[i - 1] + A[i];
        }

        // Prefix sums for array B (thresholds)
        vector<i64> prefixB(m + 1, 0);
        for (int i = 1; i <= m; ++i) {
            prefixB[i] = prefixB[i - 1] + B[i];
        }

        // Function: find max k such that prefixB[k] <= x
        auto findMaxSegments = [&](i64 x) -> int {
            if (x < 0) return 0;
            auto it = upper_bound(prefixB.begin(), prefixB.end(), x);
            int k = distance(prefixB.begin(), it) - 1;
            return max(0, min(k, m));
        };

        // DP arrays: dpPrev holds previous state, dpNext will hold current
        vector<i64> dpPrev(n + 1, numeric_limits<i64>::min() / 4);
        vector<i64> dpNext(n + 1, numeric_limits<i64>::min() / 4);

        dpPrev[0] = 0;

        // Divide-and-conquer DP optimization
        function<void(int, int, int, int)> solveRange = [&](int left, int right, int optLeft, int optRight) {
            if (left > right) return;

            int mid = (left + right) >> 1;
            i64 bestVal = numeric_limits<i64>::min() / 4;
            int bestPos = optLeft;

            int jUpper = min(mid - 1, optRight);
            for (int j = optLeft; j <= jUpper; ++j) {
                i64 candidate = dpPrev[j] + findMaxSegments(prefixA[mid] - prefixA[j]) - penalty;
                if (candidate > bestVal) {
                    bestVal = candidate;
                    bestPos = j;
                }
            }

            dpNext[mid] = bestVal;

            // Recurse left and right
            solveRange(left, mid - 1, optLeft, bestPos);
            solveRange(mid + 1, right, bestPos, optRight);
        };

        // Compute dp for positions 1..n
        solveRange(1, n, 0, n - 1);

        cout << dpNext[n] << '\n';
    }

    return 0;
}

