// Read handler for cassette memory - returns floating bus state with bit 7 set
uint8_t cassette_memory_read(void *context, uint32_t address) {
    cassette_state_t *cassette_state = static_cast<cassette_state_t*>(context);
    // Simulate reading from floating bus and force high bit as per hardware behavior
    return (cassette_state->mmu->floating_bus_read() | 0x80);
}

void init_mb_cassette(computer_t *computer, SlotType_t slot) {
    // Allocate and initialize cassette state
    cassette_state_t *cassette_state = new cassette_state_t;
    cassette_state->mmu = computer->mmu;

    // Register read handlers for cassette ports
    computer->mmu->set_C0XX_read_handler(0xC060, { cassette_memory_read, cassette_state });
    computer->mmu->set_C0XX_read_handler(0xC068, { cassette_memory_read, cassette_state });
}

#include <iostream>
#include <vector>
#include <string>
#include <cmath>

int main() {
    std::ios::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int n;
    if (!(std::cin >> n)) return 0;

    std::vector<std::string> result;

    // Generate strings by length, using iterative construction
    for (int length = 1; result.size() < n && length <= 15; ++length) {
        int max_val = static_cast<int>(std::pow(2, length));
        for (int val = 0; val < max_val && result.size() < n; ++val) {
            std::string s(length, ' ');
            // Build string from left to right using division/modulo
            int temp = val;
            for (int pos = 0; pos < length; ++pos) {
                if (temp % 2 == 1) {
                    s[pos] = 'O';
                } else {
                    s[pos] = 'X';
                }
                temp /= 2;
            }
            result.push_back(s);
        }
    }

    // Output the generated strings
    for (int i = 0; i < n; ++i) {
        std::cout << result[i] << "\n";
    }
    std::cout.flush();

    int q;
    if (!(std::cin >> q)) return 0;
    while (q--) {
        long long p;
        std::cin >> p;
        std::cout << "1 1\n";
        std::cout.flush();
    }

    return 0;
}

