int EmptyLevelChunk::getBlocksAndData(byteArray buffer, int minX, int minY, int minZ,
                                      int maxX, int maxY, int maxZ, int offset, bool includeLighting)
{
    int dx = maxX - minX;
    int dy = maxY - minY;
    int dz = maxZ - minZ;
    int volume = dx * dy * dz;

    int totalSize;
    if (includeLighting)
        totalSize = volume + (volume / 2) * 3;
    else
        totalSize = volume + (volume / 2);

    Arrays::fill(buffer, offset, offset + totalSize, static_cast<byte>(0));
    return totalSize;
}

