#include <iostream>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int testCases;
    if (!(cin >> testCases)) return 0;

    while (testCases--) {
        int n;
        if (!(cin >> n)) break;

        // Calculate the maximum number using formula: n² - n + 1
        int maxNum = n * n - n + 1;

        cout << "!";

        // Use do-while loop instead of for loop
        int current = 1;
        do {
            cout << " " << current;
            current++;
        } while (current <= maxNum);

        cout << "\n";
        cout.flush();
    }

    return 0;
}

#include <iostream>
#include <vector>
#include <bitset>
#include <random>
using namespace std;

// Fixed string length
const int STRING_LENGTH = 1000;

// Gaussian elimination structures
bitset<STRING_LENGTH> pivot_vectors[STRING_LENGTH];
int equation_results[STRING_LENGTH];
bool has_pivot[STRING_LENGTH];
int solution_bits[STRING_LENGTH];

void process() {
    int input_n;
    if (!(cin >> input_n)) return;

    // Reset pivot tracking
    for (int i = 0; i < STRING_LENGTH; ++i) {
        has_pivot[i] = false;
    }

    // Initialize random number generator with fixed seed
    mt19937 rng(5489);
    int equations_collected = 0;

    // Collect enough independent equations
    while (equations_collected < STRING_LENGTH) {
        // Random modulus in range [40, 51]
        int modulus = 40 + (rng() % 12);

        // Generate random mask of size 'modulus'
        vector<int> mask(modulus);
        for (int idx = 0; idx < modulus; ++idx) {
            mask[idx] = rng() & 1;
        }

        // Build the coefficient vector based on mask
        bitset<STRING_LENGTH> coeff_vector;
        for (int pos = 0; pos < STRING_LENGTH; ++pos) {
            if (mask[pos % modulus]) {
                coeff_vector.set(pos);
            }
        }

        // Attempt to find pivot and reduce
        bitset<STRING_LENGTH> reduced = coeff_vector;
        int pivot_index = -1;

        for (int bit = 0; bit < STRING_LENGTH; ++bit) {
            if (reduced.test(bit)) {
                if (has_pivot[bit]) {
                    reduced ^= pivot_vectors[bit];
                } else {
                    pivot_index = bit;
                    break;
                }
            }
        }

        // If we found a new pivot, proceed with query
        if (pivot_index != -1) {
            int num_states = 2 * modulus;

            // Send query command
            cout << "1" << endl;

            // Build transition tables
            vector<int> state_trans_0(num_states), state_trans_1(num_states);
            for (int s = 0; s < num_states; ++s) {
                int pos = s % modulus;
                int parity = s / modulus;
                int next_pos = (pos + 1) % modulus;

                // Input '0' does not change parity
                state_trans_0[s] = next_pos + parity * modulus;

                // Input '1' flips parity if mask[pos] is set
                int new_parity = parity ^ mask[pos];
                state_trans_1[s] = next_pos + new_parity * modulus;
            }

            // Output state count and transitions
            cout << num_states;
            for (int t : state_trans_0) cout << " " << t;
            for (int t : state_trans_1) cout << " " << t;
            cout << endl;

            // Read final state from judge
            int final_state;
            cin >> final_state;
            int observed_parity = (final_state >= modulus) ? 1 : 0;

            // Update system with new equation
            int rhs = observed_parity;
            reduced = coeff_vector;
            for (int bit = 0; bit < STRING_LENGTH; ++bit) {
                if (reduced.test(bit)) {
                    if (has_pivot[bit]) {
                        reduced ^= pivot_vectors[bit];
                        rhs ^= equation_results[bit];
                    } else {
                        pivot_vectors[bit] = reduced;
                        equation_results[bit] = rhs;
                        has_pivot[bit] = true;
                        equations_collected++;
                        break;
                    }
                }
            }
        }
    }

    // Back-substitution to determine solution bits
    for (int i = STRING_LENGTH - 1; i >= 0; --i) {
        int value = equation_results[i];
        for (int j = i + 1; j < STRING_LENGTH; ++j) {
            if (pivot_vectors[i].test(j)) {
                value ^= solution_bits[j];
            }
        }
        solution_bits[i] = value;
    }

    // Output final guess
    cout << "0" << endl;
    for (int i = 0; i < STRING_LENGTH; ++i) {
        cout << solution_bits[i];
    }
    cout << endl;
}

int main() {
    process();
    return 0;
}

