extern "C" int LLVMFuzzerTestOneInput(const uint8_t *Data, size_t Size) {
    // Skip if input is too small to contain a 32-bit value
    if (Size < sizeof(uint32_t)) {
        return 0;
    }

    uint32_t X, Y;

    // Determine offset based on input size
    size_t Offset = (Size < 8) ? 0 : (Size / 2);

    // Copy 4 bytes from Data at calculated offset into X
    std::memcpy(&X, Data + Offset, sizeof(uint32_t));

    // Load the constant "FUZZ" as a 32-bit value into Y
    const char magic[] = {'F', 'U', 'Z', 'Z'};
    std::memcpy(&Y, magic, sizeof(uint32_t));

    // Store comparison result (1 if equal, 0 otherwise) into Sink
    Sink = (X == Y) ? 1 : 0;

    return 0;
}

