namespace sdb::fuerte {

EventLoopService::EventLoopService(unsigned int thread_count, const char* name)
  : _last_used(0) {
  // Pre-allocate storage for efficiency
  _io_contexts.reserve(thread_count);
  _guards.reserve(thread_count);
  _threads.reserve(thread_count);

  // Initialize each io_context with a work guard and spawn a worker thread
  for (unsigned i = 0; i < thread_count; ++i) {
    auto ctx_ptr = std::make_shared<asio_ns::io_context>(1);
    _io_contexts.push_back(ctx_ptr);
    _guards.push_back(asio_ns::make_work_guard(*ctx_ptr));

    asio_ns::io_context* raw_ctx = ctx_ptr.get();
    _threads.emplace_back([=]() {
#ifdef __linux__
      if (name != nullptr && *name != '\0') {
        prctl(PR_SET_NAME, reinterpret_cast<unsigned long>(name), 0, 0, 0);
      }
#endif
      raw_ctx->run();
    });
  }
}

EventLoopService::~EventLoopService() {
  stop();
}

// Round-robin selection of next available io_context
std::shared_ptr<asio_ns::io_context>& EventLoopService::nextIOContext() {
  SDB_ASSERT(!_io_contexts.empty());
  size_t index = _last_used.fetch_add(1, std::memory_order_relaxed) % _io_contexts.size();
  return _io_contexts[index];
}

asio_ns::ssl::context& EventLoopService::sslContext() {
  std::lock_guard<std::mutex> lock(_ssl_context_mutex);
  if (!_ssl_context) {
#if (OPENSSL_VERSION_NUMBER >= 0x10100000L)
    _ssl_context = std::make_unique<asio_ns::ssl::context>(
        asio_ns::ssl::context::tls_client);
#else
    _ssl_context = std::make_unique<asio_ns::ssl::context>(
        asio_ns::ssl::context::sslv23_client);
#endif
    _ssl_context->set_default_verify_paths();
  }
  return *_ssl_context;
}

void EventLoopService::stop() {
  // Signal all work guards to release their associated contexts
  for (auto& guard : _guards) {
    guard.reset();
  }

  // Brief pause to allow pending operations to complete
  std::this_thread::sleep_for(std::chrono::milliseconds(50));

  // Stop all io_contexts
  for (auto& ctx : _io_contexts) {
    ctx->stop();
  }

  // Another brief pause before joining threads
  std::this_thread::sleep_for(std::chrono::milliseconds(50));

  // Join all threads safely
  for (auto& thread : _threads) {
    if (thread.joinable()) {
      thread.join();
    }
  }

  // Clear containers after threads have been joined
  _threads.clear();
  _io_contexts.clear();
  _guards.clear();
}

