namespace capy = boost::capy;

// Helper: simulate work with optional early exit on cancellation
capy::task<std::string> perform_delayed_work(int total_units)
{
    auto stop_token = co_await capy::this_coro::stop_token;
    std::string accumulated_output;

    for (int unit_index = 0; unit_index < total_units; ++unit_index)
    {
        if (stop_token.stop_requested())
        {
            std::cout << "  Work halted at unit " << unit_index << std::endl;
            throw std::system_error(
                make_error_code(std::errc::operation_canceled));
        }

        accumulated_output += "chunk_" + std::to_string(unit_index) + " ";

        // Simulate processing delay
        std::this_thread::sleep_for(std::chrono::milliseconds(10));
        std::cout << "  Finished unit " << unit_index << std::endl;

        // Yield opportunity for cancellation before next iteration
        std::this_thread::sleep_for(std::chrono::milliseconds(15));
    }

    co_return accumulated_output;
}

// Wrapper that enforces graceful handling of cancellation via optional return
capy::task<std::optional<std::string>> execute_with_safe_cancellation()
{
    auto token = co_await capy::this_coro::stop_token;

    try
    {
        auto fetched = co_await perform_delayed_work(5);
        co_return fetched;
    }
    catch (std::system_error const& ex)
    {
        if (ex.code() == std::errc::operation_canceled)
            co_return std::nullopt;
        throw;
    }
}

// Run task to completion without interruption
void run_success_scenario()
{
    std::cout << "Scenario: Successful execution\n";

    capy::thread_pool executor;
    std::stop_source cancel_source;
    std::latch completion_barrier(1);

    capy::run_async(executor.get_executor(), cancel_source.get_token(),
        [&completion_barrier](std::optional<std::string> outcome) {
            if (outcome.has_value())
                std::cout << "Output: " << *outcome << "\n";
            else
                std::cout << "Operation was cancelled\n";
            completion_barrier.count_down();
        },
        [&completion_barrier](std::exception_ptr err) {
            std::rethrow_exception(err);
            completion_barrier.count_down();
        }
    )(execute_with_safe_cancellation());

    completion_barrier.wait();
}

// Simulate cancellation mid-execution
void run_interrupted_scenario()
{
    std::cout << "\nScenario: Early termination after ~2 units\n";

    capy::thread_pool executor;
    std::stop_source cancel_source;
    std::latch completion_barrier(1);

    capy::run_async(executor.get_executor(), cancel_source.get_token(),
        [&completion_barrier](std::optional<std::string> outcome) {
            if (outcome.has_value())
                std::cout << "Output: " << *outcome << "\n";
            else
                std::cout << "Cancelled (returned empty)\n";
            completion_barrier.count_down();
        },
        [&completion_barrier](std::exception_ptr err) {
            std::rethrow_exception(err);
            completion_barrier.count_down();
        }
    )(execute_with_safe_cancellation());

    // Wait until just after second unit completes (approx. 42ms)
    std::this_thread::sleep_for(std::chrono::milliseconds(42));
    std::cout << "  Initiating cancellation...\n";
    cancel_source.request_stop();

    completion_barrier.wait();
}

// Alternative coroutine: sum items with cancellation awareness
capy::task<int> accumulate_with_check(std::vector<int> const& data)
{
    auto token = co_await capy::this_coro::stop_token;
    int running_total = 0;

    for (auto value : data)
    {
        if (token.stop_requested())
        {
            std::cout << "Accumulation stopped early; current total: " << running_total << "\n";
            co_return running_total;
        }

        running_total += value;
    }

    co_return running_total;
}

int main()
{
    run_success_scenario();
    run_interrupted_scenario();

    return 0;
}

