// Helper function to compute sum of variadic arguments plus first argument
int compute_variadic_sum(int first_arg, sol::variadic_args va) {
    std::vector<int> values;
    // Manually extract each element from variadic_args
    for (size_t i = 0; i < va.size(); ++i) {
        values.push_back(va[i]); // implicit conversion to int
    }

    int total = first_arg;
    for (int val : values) {
        total += val;
    }
    return total;
}

int main() {
