      groupSizeMap[groupId]++;
    }
    NCCLCHECK(ncclGroupEnd());

    // Validate ranks and sizes in each split communicator
    for (int idx = 0; idx < totalGpus; ++idx) {
      int currentRank, totalRanksInGroup;
      NCCLCHECK(ncclCommUserRank(splitComms[idx], &currentRank));
      NCCLCHECK(ncclCommCount(splitComms[idx], &totalRanksInGroup));

      int expectedRank = idx / numGroups;
      int expectedSize = groupSizeMap[idx % numGroups];
      ASSERT_EQ(currentRank, expectedRank);
      ASSERT_EQ(totalRanksInGroup, expectedSize);
    }

    // Cleanup
    for (auto& comm : splitComms)
      NCCLCHECK(ncclCommDestroy(comm));
    for (auto& comm : originalComms)
      NCCLCHECK(ncclCommDestroy(comm));
  }

  /**
   * \brief All devices join one common group using ncclCommSplit.
   * ******************************************************************************************/
  TEST(Standalone, SplitComms_OneColor)
  {
    int totalGpus;
    HIPCALL(hipGetDeviceCount(&totalGpus));
    if (totalGpus < 2) {
      GTEST_SKIP() << "Need at least two GPUs.";
    }

    std::vector<ncclComm_t> baseComms(totalGpus);
    NCCLCHECK(ncclCommInitAll(baseComms.data(), totalGpus, nullptr));

    std::vector<ncclComm_t> newComms(totalGpus);
    NCCLCHECK(ncclGroupStart());
    for (int rank = 0; rank < totalGpus; ++rank)
      NCCLCHECK(ncclCommSplit(baseComms[rank], 0, rank, &newComms[rank], nullptr));
    NCCLCHECK(ncclGroupEnd());

    // Ensure no change in rank or size after splitting with same color
    for (int i = 0; i < totalGpus; ++i) {
      int origRank, origSize;
      NCCLCHECK(ncclCommUserRank(baseComms[i], &origRank));
      NCCLCHECK(ncclCommCount(baseComms[i], &origSize));

      int splitRank, splitSize;
      NCCLCHECK(ncclCommUserRank(newComms[i], &splitRank));
      NCCLCHECK(ncclCommCount(newComms[i], &splitSize));

      ASSERT_EQ(origRank, splitRank);
      ASSERT_EQ(origSize, splitSize);
    }

    // Release resources
    for (auto& c : newComms)
      NCCLCHECK(ncclCommDestroy(c));
    for (auto& c : baseComms)
      NCCLCHECK(ncclCommDestroy(c));
  }

  /**
   * \brief Reduce number of communicators by half using ncclCommSplit.
   * ******************************************************************************************/
  TEST(Standalone, SplitComms_Reduce)
  {
    int totalGpus;
    HIPCALL(hipGetDeviceCount(&totalGpus));
    if (totalGpus < 2) {
      GTEST_SKIP() << "Requires ≥2 GPUs.";
    }

    std::vector<ncclComm_t> initComms(totalGpus);
    NCCLCHECK(ncclCommInitAll(initComms.data(), totalGpus, nullptr));

    int targetRanks = totalGpus / 2;
    std::vector<ncclComm_t> reducedComms(totalGpus);

    NCCLCHECK(ncclGroupStart());
    for (int r = 0; r < totalGpus; ++r) {
      int color = (r < targetRanks) ? 0 : NCCL_SPLIT_NOCOLOR;
      NCCLCHECK(ncclCommSplit(initComms[r], color, r, &reducedComms[r], nullptr));
    }
    NCCLCHECK(ncclGroupEnd());

    for (int i = 0; i < totalGpus; ++i) {
      int origRank, origSize;
      NCCLCHECK(ncclCommUserRank(initComms[i], &origRank));
      NCCLCHECK(ncclCommCount(initComms[i], &origSize));

      if (i < targetRanks) {
        int newRank, newSize;
        NCCLCHECK(ncclCommUserRank(reducedComms[i], &newRank));
        NCCLCHECK(ncclCommCount(reducedComms[i], &newSize));
        ASSERT_EQ(origRank, newRank);
        ASSERT_EQ(newSize, targetRanks);
      } else {
        ASSERT_EQ(reducedComms[i], nullptr);
      }
    }

    // Destroy comms safely
    for (auto& c : reducedComms)
      if (c != nullptr) NCCLCHECK(ncclCommDestroy(c));
    for (auto& c : initComms)
      NCCLCHECK(ncclCommDestroy(c));
  }

  /**
   * \brief Ensure performance consistency across protocols: LL, LL128, Simple.
   * ******************************************************************************************/
  TEST(Standalone, RegressionTiming)
  {
    using Clock = std::chrono::high_resolution_clock;
    int elapsedMicros = 0;
    const int warmups = 5, trials = 20;

    int gpuCount;
    HIPCALL(hipGetDeviceCount(&gpuCount));
    if (gpuCount < 2) {
      GTEST_SKIP() << "Two GPUs needed.";
    }

    hipDeviceProp_t props;
    HIPCALL(hipGetDeviceProperties(&props, 0));

    constexpr int numRanks = 2;
    std::vector<ncclComm_t> comms(numRanks);
    std::vector<int*> dInputs(numRanks), dOutputs(numRanks);
    std::vector<hipStream_t> streams(numRanks);

    char* savedProto = getenv("NCCL_PROTO");
    const char* protoNames[] = {"LL", "LL128", "Simple"};

    for (const char* p : protoNames) {
      elapsedMicros = 0;

      if (strncmp(props.gcnArchName, "gfx12", 5) == 0) {
        setenv("NCCL_PROTO", "Simple", 1);
      } else {
        setenv("NCCL_PROTO", p, 1);
      }

      NCCLCHECK(ncclCommInitAll(comms.data(), numRanks, nullptr));

      int N = 1250;
      std::vector<int> hInput(N), hExpected(N);
      for (int k = 0; k < N; ++k) {
        hInput[k] = k;
        hExpected[k] = 2 * k;
      }

      for (int r = 0; r < numRanks; ++r) {
        HIPCALL(hipSetDevice(r));
        HIPCALL(hipStreamCreate(&streams[r]));
        HIPCALL(hipMalloc((void**)&dInputs[r], N * sizeof(int)));
        HIPCALL(hipMalloc((void**)&dOutputs[r], N * sizeof(int)));
        HIPCALL(hipMemcpy(dInputs[r], hInput.data(), N * sizeof(int), hipMemcpyHostToDevice));
        HIPCALL(hipMemset(dOutputs[r], 0, N * sizeof(int)));
        HIPCALL(hipDeviceSynchronize());
      }

      for (int iter = -warmups; iter < trials; ++iter) {
        for (int r = 0; r < numRanks; ++r) {
          HIPCALL(hipSetDevice(r));
          HIPCALL(hipMemset(dOutputs[r], 0, N * sizeof(int)));
          HIPCALL(hipDeviceSynchronize());
        }

        NCCLCHECK(ncclGroupStart());
        for (int r = 0; r < numRanks; ++r)
          NCCLCHECK(ncclAllReduce(dInputs[r], dOutputs[r], N, ncclInt, ncclSum, comms[r], streams[r]));
        ncclResult_t res = ncclGroupEnd();
        if (res != ncclSuccess) continue;

        auto startTime = Clock::now();
        for (int r = 0; r < numRanks; ++r)
          HIPCALL(hipStreamSynchronize(streams[r]));

        if (iter >= 0)
          elapsedMicros += duration_cast<microseconds>(Clock::now() - startTime).count();

        std::vector<int> hOutput(N);
        for (int r = 0; r < numRanks; ++r) {
          HIPCALL(hipMemcpy(hOutput.data(), dOutputs[r], N * sizeof(int), hipMemcpyDeviceToHost));
          HIPCALL(hipDeviceSynchronize());
          for (int j = 0; j < N; ++j)
            ASSERT_EQ(hOutput[j], hExpected[j]);
        }
      }

      double avgTime = static_cast<double>(elapsedMicros) / trials;
      EXPECT_LT(avgTime, 5000.0);
      printf("[ INFO     ] protocol: %s, avg runtime: %.2f µs\n", p, avgTime);

      for (int r = 0; r < numRanks; ++r) {
        HIPCALL(hipFree(dInputs[r]));
        HIPCALL(hipFree(dOutputs[r]));
        HIPCALL(hipStreamDestroy(streams[r]));
        NCCLCHECK(ncclCommDestroy(comms[r]));
      }
    }

    if (savedProto)
      setenv("NCCL_PROTO", savedProto, 1);
    else
      unsetenv("NCCL_PROTO");
  }

  /**
   * \brief Check kernel stack usage against architecture-specific limits.
   * ******************************************************************************************/
  TEST(Standalone, StackSize)
  {
    const std::string mainKernelName = "ncclDevKernel";
    std::vector<std::string> coFiles = splitString(executeCommand("find ../ -type f -name \"librccl*.co\""), '\n');

    if (coFiles.empty())
      GTEST_SKIP() << "No .co files found — skipping.";

    for (const auto& file : coFiles) {
      std::string cmd = std::string(ROCM_PATH) + "/llvm/bin/llvm-readelf --notes " + file;
      std::vector<std::string> notesLines = splitString(executeCommand(cmd.c_str()), '\n');
      if (notesLines.empty())
        GTEST_SKIP() << "llvm not installed — skipping.";

      ArchInfo archData = parseMetadata(notesLines);

      for (const auto& kern : archData.kernels) {
        if (kern.name.find(mainKernelName) != std::string::npos) {
          int stackSize = kern.privateSegmentFixedSize;
          int maxAllowed = (archData.archName == "gfx90a") ? MAX_STACK_SIZE_gfx90a : MAX_STACK_SIZE;
          printf("[ INFO     ] Arch: %s | Kernel: %s | Stack Size: %d\n",
                 archData.archName.c_str(), kern.name.c_str(), stackSize);
          EXPECT_LE(stackSize, maxAllowed);
        }
      }
    }
  }

  /**
   * \brief Validate device binding to communicators in single/multi-GPU contexts.
   * ******************************************************************************************/
  TEST(Standalone, CommCuDevice_Check)
  {
    int devCount;
    HIPCALL(hipGetDeviceCount(&devCount));
    if (devCount < 1) {
      GTEST_SKIP() << "No GPU devices available.";
    }

    ncclComm_t singleComm;
    ncclUniqueId uid;
    NCCLCHECK(ncclGetUniqueId(&uid));
    HIPCALL(hipSetDevice(0));
    NCCLCHECK(ncclCommInitRank(&singleComm, 1, uid, 0));

    int boundDevice;
    NCCLCHECK(ncclCommCuDevice(singleComm, &boundDevice));
    ASSERT_EQ(boundDevice, 0);
    NCCLCHECK(ncclCommDestroy(singleComm));

    if (devCount > 1) {
      std::vector<ncclComm_t> multiComms(devCount);
      NCCLCHECK(ncclCommInitAll(multiComms.data(), devCount, nullptr));

      for (int i = 0; i < devCount; ++i) {
        int assignedDev;
        NCCLCHECK(ncclCommCuDevice(multiComms[i], &assignedDev));
        ASSERT_EQ(assignedDev, i);
      }

      for (int i = 0; i < devCount; ++i)
        NCCLCHECK(ncclCommDestroy(multiComms[i]));
    }
  }

