// Helper macros for writing scalar, small array, and regular array properties
#define WRITE_SCALAR(traits, ...)                                              \
{                                                                              \
    vector<traits::value_type> data;                                           \
    data += __VA_ARGS__;                                                       \
    DataType dtype = traits::dataType();                                       \
    string pname = #traits;                                                    \
    MetaData md;                                                               \
    md.set("interpretation", traits::interpretation());                        \
    write_scalar_property(prop, pname, dtype, md, data);                       \
}

#define WRITE_SMALL_ARRAY(traits, ...)                                         \
{                                                                              \
    vector<traits::value_type> data;                                           \
    data += __VA_ARGS__;                                                       \
    DataType dtype = traits::dataType();                                       \
    dtype.setExtent(data.size());                                              \
    string pname = #traits;                                                    \
    MetaData md;                                                               \
    write_small_array_property(prop, pname, dtype, md, data);                  \
}

#define WRITE_REGULAR_ARRAY(traits, ...)                                       \
{                                                                              \
    vector<traits::value_type> data;                                           \
    data += __VA_ARGS__;                                                       \
    DataType dtype = traits::dataType();                                       \
    string pname = #traits;                                                    \
    MetaData md;                                                               \
    md.set("interpretation", traits::interpretation());                        \
    write_array_property<traits>(prop, pname, dtype, md, data);                \
}

namespace {

// Write scalar property using OScalarProperty
template<typename T>
void write_scalar_property(
    OCompoundProperty& compoundProp,
    const string& propertyName,
    const DataType& dataType,
    const MetaData& metaData,
    const vector<T>& values)
{
    OScalarProperty writer(compoundProp, propertyName, dataType, metaData);
    for (size_t idx = 0; idx < values.size(); ++idx) {
        writer.set(static_cast<const void*>(&values[idx]));
    }
}

// Write small array property using OScalarProperty with bulk set
template<typename T>
void write_small_array_property(
    OCompoundProperty& compoundProp,
    const string& propertyName,
    const DataType& dataType,
    const MetaData& metaData,
    const vector<T>& values)
{
    OScalarProperty writer(compoundProp, propertyName, dataType, metaData);
    if (!values.empty()) {
        writer.set(&values.front());
    }
}

// Write regular array property using OArrayProperty
template<typename T>
void write_array_property(
    OCompoundProperty& compoundProp,
    const string& propertyName,
    const DataType& dataType,
    const MetaData& metaData,
    const vector<typename T::value_type>& values)
{
    OArrayProperty writer(compoundProp, propertyName, dataType, metaData);
    TypedArraySample<T> sample(values);
    writer.set(sample);
}

