using namespace llvm;

PreservedAnalyses EmbedBitcodePass::run(Module &M, ModuleAnalysisManager &AM) {
  // Check if bitcode has already been embedded
  if (M.getGlobalVariable("llvm.embedded.module", /*AllowInternal=*/true))
    report_fatal_error("Bitcode embedding can only be performed once",
                       /*gen_crash_diag=*/false);

  Triple targetTriple(M.getTargetTriple());

  // Verify that the target object format is ELF
  if (targetTriple.getObjectFormat() != Triple::ELF)
    report_fatal_error(
        "This bitcode embedding functionality is restricted to ELF format",
        /*gen_crash_diag=*/false);

  // Prepare buffer for bitcode output
  std::string bitcodeData;
  raw_string_ostream bitcodeStream(bitcodeData);

  // Generate appropriate bitcode based on LTO mode
  if (IsThinLTO) {
    ThinLTOBitcodeWriterPass(bitcodeStream, /*ThinLinkOS=*/nullptr)
        .run(M, AM);
  } else {
    BitcodeWriterPass(bitcodeStream,
                      /*ShouldPreserveUseListOrder=*/false,
                      EmitLTOSummary)
        .run(M, AM);
  }

  // Embed the generated bitcode into the module
  embedBufferInModule(M, MemoryBufferRef(bitcodeStream.str(), "ModuleData"),
                      ".llvm.lto");

  return PreservedAnalyses::all();
}

