void CompiledExecutor::dispatch_mamba_out_proj(const CompiledOp& op, const modules::ForwardHook* hook) {
    // Mamba output projection is equivalent to a matrix multiplication: out = gated_out @ out_proj_weight^T
    // Input tensor: gated_out with shape [B*T, intermediate_size]
    // Weight tensor: out_proj_weight with shape [d_model, intermediate_size]
    // Result tensor: out with shape [B*T, d_model]
    // Since this operation matches the standard matmul pattern, we reuse the existing dispatcher
    execute_matmul(op, hook);
}

void CompiledExecutor::dispatch_mamba_out_proj_backward(const CompiledOp& op, const modules::BackwardHook* hook) {
    // Backward pass for the output projection corresponds to standard matmul gradient computation
    // Reuse the generic backward implementation for matrix multiplication
    execute_matmul_backward(op, hook);
}

