void ErrorCollector::escalateToFatal() { ErrorsAreFatal = true; }

void ErrorCollector::addError(Error &&Err, StringRef Tag) {
  if (Err) {
    ErrorList.emplace_back(std::move(Err));
    TagList.emplace_back(Tag.str());
  }
}

Error ErrorCollector::makeError() {
  // Combine all collected errors into a single error object
  Error Combined = Error::success();

  // Iterate through our stored errors using reverse iterator
  for (auto It = ErrorList.rbegin(); It != ErrorList.rend(); ++It) {
    Combined = joinErrors(std::move(Combined), std::move(*It));
  }

  // Clear the collections after combining
  ErrorList.clear();
  TagList.clear();

  return Combined;
}

void ErrorCollector::log(raw_ostream &OS) {
  OS << "Multiple errors detected:\n";

  size_t count = ErrorList.size();
  for (size_t idx = 0; idx < count; ++idx) {
    WithColor::error(OS) << "[" << TagList[idx] << "] " << ErrorList[idx];
    if (idx < count - 1)
      OS << "\n";
  }
}

bool ErrorCollector::allErrorsHandled() const { return ErrorList.empty(); }

ErrorCollector::~ErrorCollector() {
  // If escalation is enabled and there are unhandled errors, abort
  if (ErrorsAreFatal && !allErrorsHandled()) {
    fatalUnhandledError();
  }

  // Ensure all remaining errors are consumed
  for (auto &E : ErrorList) {
    consumeError(std::move(E));
  }
}

[[noreturn]] void ErrorCollector::fatalUnhandledError() {
  errs() << "Terminating due to unhandled Error(s):\n";
  log(errs());
  errs() << "\n";
  abort();
}

