static void remap_ioctl_buffer(const struct ioctl_compat_entry *entry, char *dest, char *src, int mode)
{
	int dest_pos = 0;
	int src_pos = 0;
	int copy_len = entry->size_old;

	if (!(mode & entry->direction)) return;

	if (!entry->size_old) {
		// Special case: SNDRV_PCM_IOCTL_SYNC_PTR
		remap_ioctl_buffer(entry + 1, dest, src, mode);
		remap_ioctl_buffer(entry + 2, dest + 4, src + 8, mode);

		int shift = (BYTE_ORDER == BIG_ENDIAN) ? 4 : 0;
		remap_ioctl_buffer(entry + 3, dest + 68 + shift, src + 72, mode);
		remap_ioctl_buffer(entry + 3, dest + 72 + 3*shift, src + 76, mode);
		return;
	}

	int idx = 0;
	while (idx < entry->num_offsets) {
		int ts_offset = entry->offset_list[idx];
		int gap = ts_offset - src_pos;
		if (mode == W) memcpy(src + src_pos, dest + dest_pos, gap);
		else memcpy(dest + dest_pos, src + src_pos, gap);
		dest_pos += gap;
		src_pos += gap;

		long long new_ts_val;
		long old_ts_val;
		int align_size = entry->require_alignment ? sizeof(time_t) : alignof(time_t);
		dest_pos = (dest_pos + align_size - 1) & ~(align_size - 1);

		if (mode == W) {
			memcpy(&new_ts_val, dest + dest_pos, sizeof(new_ts_val));
			old_ts_val = (long)new_ts_val;
			memcpy(src + src_pos, &old_ts_val, sizeof(old_ts_val));
		} else {
			memcpy(&old_ts_val, src + src_pos, sizeof(old_ts_val));
			new_ts_val = (long long)old_ts_val;
			memcpy(dest + dest_pos, &new_ts_val, sizeof(new_ts_val));
		}
		dest_pos += sizeof(new_ts_val);
		src_pos += sizeof(old_ts_val);
		idx++;
	}

	if (mode == W) memcpy(src + src_pos, dest + dest_pos, copy_len - src_pos);
	else memcpy(dest + dest_pos, src + src_pos, copy_len - src_pos);
}

int ioctl(int fd, int request, ...)
{
	void *user_arg;
	va_list args;
	va_start(args, request);
	user_arg = va_arg(args, void *);
	va_end(args);

	long result = __syscall(SYS_ioctl, fd, request, user_arg);

	if (SIOCGSTAMP != SIOCGSTAMP_OLD && request && result == -ENOTTY) {
		const struct ioctl_compat_entry *entry = compat_table;
		size_t count = sizeof(compat_table) / sizeof(*compat_table);
		size_t i = 0;

		while (i < count) {
			if (entry[i].new_request != request) {
				i++;
				continue;
			}

			union {
				long long align;
				char buffer[256];
			} temp;

			remap_ioctl_buffer(&entry[i], temp.buffer, user_arg, W);
			result = __syscall(SYS_ioctl, fd, entry[i].old_request, temp.buffer);
			if (result < 0) break;

			remap_ioctl_buffer(&entry[i], temp.buffer, user_arg, R);
			break;
		}
	}

	return __syscall_ret(result);
}

