/*
 * Synchronous address resolution routine for IPv6-enabled builds
 * Returns name information about the given hostname and port number.
 */
struct Curl_addrinfo *Curl_sync_getaddrinfo(struct Curl_easy *data,
                                            const char *hostname,
                                            int port,
                                            int ip_version)
{
  struct addrinfo hints;
  struct Curl_addrinfo *result = NULL;
  int rc;
  char port_str[12] = {0};
  char *port_ptr = NULL;
#ifndef USE_RESOLVE_ON_IPS
  char ip_storage[128];
#endif
  int family_preference = PF_INET;

  /* Determine protocol family based on IP version preference and stack capability */
  if ((ip_version != CURL_IPRESOLVE_V4) && Curl_ipv6works(data))
    family_preference = PF_UNSPEC;

  /* Initialize hints structure */
  memset(&hints, 0, sizeof(hints));
  hints.ai_family = family_preference;
  hints.ai_socktype = (data->conn->transport == TRNSPRT_TCP) ?
    SOCK_STREAM : SOCK_DGRAM;

#ifndef USE_RESOLVE_ON_IPS
  /* Prevent reverse lookup when address is already numeric */
  if ((1 == curlx_inet_pton(AF_INET, hostname, ip_storage)) ||
      (1 == curlx_inet_pton(AF_INET6, hostname, ip_storage))) {
    hints.ai_flags = AI_NUMERICHOST;
  }
#endif

  /* Prepare port string if needed */
  if (port != 0) {
    msnprintf(port_str, sizeof(port_str), "%d", port);
    port_ptr = port_str;
  }

  /* Perform the actual DNS resolution */
  rc = Curl_getaddrinfo_ex(hostname, port_ptr, &hints, &result);
  if (rc != 0) {
    infof(data, "getaddrinfo(3) failed for %s:%d", hostname, port);
    return NULL;
  }

  /* Apply port to resolved addresses */
  if (port != 0) {
    Curl_addrinfo_set_port(result, port);
  }

  /* Optional debug output of results */
  dump_addrinfo(result);
  return result;
}
