using namespace std;

int n;
vector<vector<int>> adj;
vector<int> depths;

// Perform a query with given nodes
pair<int, int> performQuery(const vector<int>& candidates) {
    if (candidates.empty()) return {-1, -1};

    cout << "? " << candidates.size();
    for (int node : candidates) {
        cout << " " << node;
    }
    cout << endl;

    int resultNode, dist;
    cin >> resultNode >> dist;

    if (resultNode == -1 && dist == -1) {
        exit(0);
    }
    return {resultNode, dist};
}

// DFS to compute depths from a starting node
void computeDepths(int start, vector<int>& depthArr) {
    fill(depthArr.begin(), depthArr.end(), -1);
    depthArr[start] = 0;

    vector<pair<int, int>> stack;
    stack.push_back({start, 0});

    while (!stack.empty()) {
        auto [node, d] = stack.back();
        stack.pop_back();

        for (int neighbor : adj[node]) {
            if (depthArr[neighbor] == -1) {
                depthArr[neighbor] = d + 1;
                stack.push_back({neighbor, d + 1});
            }
        }
    }
}

void solve() {
    cin >> n;
    adj.assign(n + 1, vector<int>());

    for (int i = 0; i < n - 1; ++i) {
        int u, v;
        cin >> u >> v;
        adj[u].push_back(v);
        adj[v].push_back(u);
    }

    // Step 1: Query all nodes to get initial information
    vector<int> allNodes(n);
    for (int i = 0; i < n; ++i) {
        allNodes[i] = i + 1;
    }

    auto [pathNode, totalDist] = performQuery(allNodes);

    // Step 2: Compute depths from node 1
    depths.assign(n + 1, 0);
    computeDepths(1, depths);

    int maxDepth = 0;
    for (int i = 1; i <= n; ++i) {
        maxDepth = max(maxDepth, depths[i]);
    }

    // Step 3: Find the deepest node on the path by climbing up from pathNode
    // We'll use iterative approach instead of binary search
    int deepestOnPath = pathNode;
    int currentDepth = depths[pathNode];

    // Create arrays for parent tracking
    vector<int> parent(n + 1, -1);
    vector<int> tempDepth(n + 1, -1);
    computeDepths(1, tempDepth);

    // Build parent array via DFS
    vector<int> dfsStack;
    dfsStack.push_back(1);
    parent[1] = 0;
    while (!dfsStack.empty()) {
        int u = dfsStack.back();
        dfsStack.pop_back();
        for (int v : adj[u]) {
            if (v != parent[u]) {
                parent[v] = u;
                dfsStack.push_back(v);
            }
        }
    }

    // Climb up from pathNode to find deepest node on path
    int candidate = pathNode;
    int bestDepth = depths[candidate];

    // Check all ancestors of pathNode
    int ancestor = candidate;
    while (ancestor != -1) {
        if (depths[ancestor] > bestDepth) {
            bestDepth = depths[ancestor];
            candidate = ancestor;
        }
        ancestor = parent[ancestor];
    }

    // Verify by querying nodes at or above current depth
    for (int d = depths[candidate]; d >= 0; --d) {
        vector<int> testNodes;
        for (int i = 1; i <= n; ++i) {
            if (depths[i] >= d) {
                testNodes.push_back(i);
            }
        }

        auto [queriedNode, queriedDist] = performQuery(testNodes);
        if (queriedDist == totalDist) {
            deepestOnPath = queriedNode;
            break;
        }
    }

    // Step 4: Find the second endpoint by computing distances from deepestOnPath
    vector<int> distFromDeepest(n + 1, -1);
    computeDepths(deepestOnPath, distFromDeepest);

    vector<int> potentialEndpoints;
    for (int i = 1; i <= n; ++i) {
        if (distFromDeepest[i] == totalDist) {
            potentialEndpoints.push_back(i);
        }
    }

    int secondEndpoint;
    if (potentialEndpoints.size() == 1) {
        secondEndpoint = potentialEndpoints[0];
    } else {
        // Query among candidates to identify the correct one
        auto [resNode, resDist] = performQuery(potentialEndpoints);
        secondEndpoint = resNode;
    }

    cout << "! " << deepestOnPath << " " << secondEndpoint << endl;

    string verdict;
    cin >> verdict;
    if (verdict != "Correct") {
        exit(0);
    }
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int testCaseCount;
    if (cin >> testCaseCount) {
        while (testCaseCount--) {
            solve();
        }
    }

    return 0;
}

