// ============================================================================
// ARM64 256-bit Field Multiplication with secp256k1 Reduction (Optimized)
// ============================================================================
void field_mul_arm64(uint64_t out[4], const uint64_t a[4], const uint64_t b[4]) noexcept {
    uint64_t t[8] = {0};

    // Compute partial products using schoolbook method
    for (int i = 0; i < 4; ++i) {
        uint64_t carry = 0;
        for (int j = 0; j < 4; ++j) {
            __asm__ (
                "mul    %1, %3, %4      \n\t"
                "umulh  %2, %3, %4      \n\t"
                : "=&r"(carry), "=&r"(t[i+j]), "=&r"(carry)
                : "r"(a[i]), "r"(b[j])
                : "cc"
            );

            // Accumulate into t[i+j]
            __asm__ (
                "adds   %0, %0, %1      \n\t"
                "adcs   %2, %2, %3      \n\t"
                : "+r"(t[i+j]), "+r"(carry), "+r"(t[i+j+1])
                : "r"(0)
                : "cc"
            );
        }
        t[i+4] += carry;
    }

    // secp256k1 reduction: p = 2^256 - c, c = 0x1000003D1
    constexpr uint64_t C = 0x1000003D1ULL;
    uint64_t r0 = t[0], r1 = t[1], r2 = t[2], r3 = t[3];

    // Reduce high limbs
    for (int i = 4; i < 8; ++i) {
        uint64_t hi, lo;
        __asm__ (
            "mul    %1, %2, %3      \n\t"
            "umulh  %0, %2, %3      \n\t"
            : "=&r"(hi), "=&r"(lo)
            : "r"(t[i]), "r"(C)
        );

        int pos = i - 4;
        switch(pos) {
            case 0:
                r0 += lo; r1 += hi; break;
            case 1:
                r1 += lo; r2 += hi; break;
            case 2:
                r2 += lo; r3 += hi; break;
            case 3:
                r3 += lo; 
                // Handle overflow from highest limb
                uint64_t overflow = hi;
                if (overflow > 0) {
                    uint64_t tmp_lo, tmp_hi;
                    __asm__ (
                        "mul    %1, %2, %3      \n\t"
                        "umulh  %0, %2, %3      \n\t"
                        : "=&r"(tmp_hi), "=&r"(tmp_lo)
                        : "r"(overflow), "r"(C)
                    );
                    r0 += tmp_lo; r1 += tmp_hi;
                }
                break;
        }
    }

    // Final normalization
    constexpr uint64_t P0 = 0xFFFFFFFEFFFFFC2FULL;
    constexpr uint64_t P1 = 0xFFFFFFFFFFFFFFFFULL;

    uint64_t s0, s1, s2, s3;
    bool borrow = false;

    __asm__ (
        "subs   %0, %4, %8      \n\t"
        "sbcs   %1, %5, %9      \n\t"
        "sbcs   %2, %6, %9      \n\t"
        "sbcs   %3, %7, %9      \n\t"
        "cset   %10, cc         \n\t"
        : "=&r"(s0), "=&r"(s1), "=&r"(s2), "=&r"(s3), "=r"(borrow)
        : "r"(r0), "r"(r1), "r"(r2), "r"(r3), "r"(P0), "r"(P1)
        : "cc"
    );

    // Branchless selection
    out[0] = borrow ? r0 : s0;
    out[1] = borrow ? r1 : s1;
    out[2] = borrow ? r2 : s2;
    out[3] = borrow ? r3 : s3;
}

// ============================================================================
// ARM64 256-bit Field Squaring with secp256k1 Reduction
// ============================================================================
void field_sqr_arm64(uint64_t out[4], const uint64_t a[4]) noexcept {
    uint64_t t[8] = {0};

    // Compute squares and cross products
    for (int i = 0; i < 4; ++i) {
        uint64_t sq_lo, sq_hi;
        __asm__ (
            "mul    %1, %2, %2      \n\t"
            "umulh  %0, %2, %2      \n\t"
            : "=&r"(sq_hi), "=&r"(sq_lo)
            : "r"(a[i])
        );
        t[i*2] += sq_lo;
        t[i*2+1] += sq_hi;
    }

    // Double cross terms
    for (int i = 0; i < 4; ++i) {
        for (int j = i + 1; j < 4; ++j) {
            uint64_t prod_lo, prod_hi;
            __asm__ (
                "mul    %1, %2, %3      \n\t"
                "umulh  %0, %2, %3      \n\t"
                : "=&r"(prod_hi), "=&r"(prod_lo)
                : "r"(a[i]), "r"(a[j])
            );

            int pos = i + j;
            t[pos] += prod_lo * 2;
            t[pos+1] += prod_hi * 2 + ((prod_lo & 0x8000000000000000ULL) ? 1 : 0);
        }
    }

    // Same reduction as multiplication
    constexpr uint64_t C = 0x1000003D1ULL;
    uint64_t r0 = t[0], r1 = t[1], r2 = t[2], r3 = t[3];

    for (int i = 4; i < 8; ++i) {
        uint64_t hi, lo;
        __asm__ (
            "mul    %1, %2, %3      \n\t"
            "umulh  %0, %2, %3      \n\t"
            : "=&r"(hi), "=&r"(lo)
            : "r"(t[i]), "r"(C)
        );

        int pos = i - 4;
        switch(pos) {
            case 0: r0 += lo; r1 += hi; break;
            case 1: r1 += lo; r2 += hi; break;
            case 2: r2 += lo; r3 += hi; break;
            case 3: 
                r3 += lo;
                if (hi > 0) {
                    uint64_t tmp_lo, tmp_hi;
                    __asm__ (
                        "mul    %1, %2, %3      \n\t"
                        "umulh  %0, %2, %3      \n\t"
                        : "=&r"(tmp_hi), "=&r"(tmp_lo)
                        : "r"(hi), "r"(C)
                    );
                    r0 += tmp_lo; r1 += tmp_hi;
                }
                break;
        }
    }

    // Normalize
    constexpr uint64_t P0 = 0xFFFFFFFEFFFFFC2FULL;
    constexpr uint64_t P1 = 0xFFFFFFFFFFFFFFFFULL;

    uint64_t s0, s1, s2, s3;
    bool borrow = false;

    __asm__ (
        "subs   %0, %4, %8      \n\t"
        "sbcs   %1, %5, %9      \n\t"
        "sbcs   %2, %6, %9      \n\t"
        "sbcs   %3, %7, %9      \n\t"
        "cset   %10, cc         \n\t"
        : "=&r"(s0), "=&r"(s1), "=&r"(s2), "=&r"(s3), "=r"(borrow)
        : "r"(r0), "r"(r1), "r"(r2), "r"(r3), "r"(P0), "r"(P1)
        : "cc"
    );

    out[0] = borrow ? r0 : s0;
    out[1] = borrow ? r1 : s1;
    out[2] = borrow ? r2 : s2;
    out[3] = borrow ? r3 : s3;
}

// ============================================================================
// ARM64 Field Addition/Subtraction
// ============================================================================
void field_add_arm64(uint64_t out[4], const uint64_t a[4], const uint64_t b[4]) noexcept {
    uint64_t sum[4];
    bool carry = false;

    __asm__ (
        "adds   %0, %4, %8      \n\t"
        "adcs   %1, %5, %9      \n\t"
        "adcs   %2, %6, %10     \n\t"
        "adcs   %3, %7, %11     \n\t"
        "cset   %12, cs         \n\t"
        : "=&r"(sum[0]), "=&r"(sum[1]), "=&r"(sum[2]), "=&r"(sum[3]), "=r"(carry)
        : "r"(a[0]), "r"(a[1]), "r"(a[2]), "r"(a[3]),
          "r"(b[0]), "r"(b[1]), "r"(b[2]), "r"(b[3])
        : "cc"
    );

    // Subtract prime if needed
    constexpr uint64_t P0 = 0xFFFFFFFEFFFFFC2FULL;
    constexpr uint64_t P1 = 0xFFFFFFFFFFFFFFFFULL;

    uint64_t diff[4];
    bool borrow = false;

    __asm__ (
        "subs   %0, %4, %8      \n\t"
        "sbcs   %1, %5, %9      \n\t"
        "sbcs   %2, %6, %9      \n\t"
        "sbcs   %3, %7, %9      \n\t"
        "cset   %10, cc         \n\t"
        : "=&r"(diff[0]), "=&r"(diff[1]), "=&r"(diff[2]), "=&r"(diff[3]), "=r"(borrow)
        : "r"(sum[0]), "r"(sum[1]), "r"(sum[2]), "r"(sum[3]),
          "r"(P0), "r"(P1)
        : "cc"
    );

    out[0] = borrow ? sum[0] : diff[0];
    out[1] = borrow ? sum[1] : diff[1];
    out[2] = borrow ? sum[2] : diff[2];
    out[3] = borrow ? sum[3] : diff[3];
}

void field_sub_arm64(uint64_t out[4], const uint64_t a[4], const uint64_t b[4]) noexcept {
    uint64_t diff[4];
    bool borrow = false;

    __asm__ (
        "subs   %0, %4, %8      \n\t"
        "sbcs   %1, %5, %9      \n\t"
        "sbcs   %2, %6, %9      \n\t"
        "sbcs   %3, %7, %9      \n\t"
        "csetm  %10, cc         \n\t"
        : "=&r"(diff[0]), "=&r"(diff[1]), "=&r"(diff[2]), "=&r"(diff[3]), "=r"(borrow)
        : "r"(a[0]), "r"(a[1]), "r"(a[2]), "r"(a[3]),
          "r"(b[0]), "r"(b[1]), "r"(b[2]), "r"(b[3])
        : "cc"
    );

    // Add prime if negative
    constexpr uint64_t P0 = 0xFFFFFFFEFFFFFC2FULL;
    constexpr uint64_t P1 = 0xFFFFFFFFFFFFFFFFULL;

    uint64_t result[4];

    if (borrow) {
        __asm__ (
            "adds   %0, %4, %8      \n\t"
            "adcs   %1, %5, %9      \n\t"
            "adcs   %2, %6, %9      \n\t"
            "adc    %3, %7, %9      \n\t"
            : "=&r"(result[0]), "=&r"(result[1]), "=&r"(result[2]), "=&r"(result[3])
            : "r"(diff[0]), "r"(diff[1]), "r"(diff[2]), "r"(diff[3]),
              "r"(P0), "r"(P1)
            : "cc"
        );
    } else {
        result[0] = diff[0];
        result[1] = diff[1];
        result[2] = diff[2];
        result[3] = diff[3];
    }

    out[0] = result[0];
    out[1] = result[1];
    out[2] = result[2];
    out[3] = result[3];
}

// ============================================================================
// ARM64 Field Negation
// ============================================================================
void field_neg_arm64(uint64_t out[4], const uint64_t a[4]) noexcept {
    constexpr uint64_t P0 = 0xFFFFFFFEFFFFFC2FULL;
    constexpr uint64_t P1 = 0xFFFFFFFFFFFFFFFFULL;

    uint64_t result[4];

    // Check if zero
    uint64_t is_zero = (a[0] | a[1] | a[2] | a[3]) == 0;

    if (!is_zero) {
        __asm__ (
            "subs   %0, %4, %8      \n\t"
            "sbcs   %1, %5, %9      \n\t"
            "sbcs   %2, %6, %9      \n\t"
            "sbcs   %3, %7, %9      \n\t"
            : "=&r"(result[0]), "=&r"(result[1]), "=&r"(result[2]), "=&r"(result[3])
            : "r"(P0), "r"(P1), "r"(a[0]), "r"(a[1]), "r"(a[2]), "r"(a[3])
            : "cc"
        );
    } else {
        result[0] = 0;
        result[1] = 0;
        result[2] = 0;
        result[3] = 0;
    }

    out[0] = result[0];
    out[1] = result[1];
    out[2] = result[2];
    out[3] = result[3];
}

