// Uses Floyd's Cycle Detection Algorithm (Tortoise and Hare) to find duplicate
class Solution {
public:
    int findDuplicate(vector<int>& nums) {
        int tortoise = nums[0];
        int hare = nums[0];
        int n = nums.size();

        // Phase 1: Find the intersection point in the cycle
        do {
            tortoise = nums[tortoise];
            hare = nums[nums[hare]];
        } while (tortoise != hare);

        // Phase 2: Find the entrance to the cycle (duplicate number)
        tortoise = nums[0];
        while (tortoise != hare) {
            tortoise = nums[tortoise];
            hare = nums[hare];
        }

        return hare; // or tortoise, both are equal here
    }
};

int main() {
    Solution solver;
    vector<int> numbers = {1, 3, 4, 2, 2};
    int answer = solver.findDuplicate(numbers);
    cout << "Duplicate: " << answer << endl;
    return 0;
}

