// Helper: Convert Duration to seconds as float64_t
double convertDurationToSeconds(const sen::Duration& dur)
{
    static auto secondsUnit = sen::UnitRegistry::get().searchUnitByAbbreviation("s").value();
    const auto& srcUnit = sen::QuantityTraits<sen::Duration>::unit();
    return sen::Unit::convert(srcUnit, *secondsUnit, static_cast<double>(dur.get()));
}

// Helper: Format padded string output
auto makePaddedString = [](const std::string& base, std::size_t totalWidth) -> std::string {
    if (base.size() >= totalWidth) return base;
    return base + std::string(totalWidth - base.size(), ' ');
};

void registerArchiveInfoCommand(CLI::App& rootApp)
{
    struct CommandOptions
    {
        std::filesystem::path archivePath;
    };

    auto opts = std::make_shared<CommandOptions>();
    auto subCmd = rootApp.add_subcommand("info", "Display summary information about an archive");
    subCmd->add_option("archive_path", opts->archivePath, "Path to the archive directory")
        ->required()
        ->check(CLI::ExistingDirectory);

    subCmd->callback([opts]() {
        try
        {
            sen::CustomTypeRegistry nativeTypes;
            sen::db::Input dbReader(opts->archivePath, nativeTypes);
            const auto& summary = dbReader.getSummary();

            const auto durationSec = convertDurationToSeconds(summary.lastTime - summary.firstTime);

            std::cout << "  path:            " << opts->archivePath.string() << "\n";
            std::cout << "  duration:        " << durationSec << "s\n";
            std::cout << "  start:           " << summary.firstTime.toLocalString() << "\n";
            std::cout << "  end:             " << summary.lastTime.toLocalString() << "\n";
            std::cout << "  objects:         " << summary.objectCount << "\n";
            std::cout << "  types:           " << summary.typeCount << "\n";
            std::cout << "  annotations:     " << summary.annotationCount << "\n";
            std::cout << "  keyframes:       " << summary.keyframeCount << "\n";
            std::cout << "  indexed objects: " << summary.indexedObjectCount << "\n";
        }
        catch (const std::exception& ex)
        {
            std::cerr << ex.what() << '\n';
            std::exit(EXIT_FAILURE);
        }
    });
}

void registerIndexedObjectsCommand(CLI::App& rootApp)
{
    struct CommandOptions
    {
        std::filesystem::path archivePath;
    };

    auto opts = std::make_shared<CommandOptions>();
    auto subCmd = rootApp.add_subcommand("indexed", "List indexed objects with metadata");
    subCmd->add_option("archive_path", opts->archivePath, "Path to the archive directory")
        ->required()
        ->check(CLI::ExistingDirectory);

    subCmd->callback([opts]() {
        try
        {
            sen::CustomTypeRegistry nativeTypes;
            sen::db::Input dbReader(opts->archivePath, nativeTypes);
            const auto& indexEntries = dbReader.getObjectIndexDefinitions();

            const std::string colName = "OBJECT NAME";
            const std::string colType = "TYPE NAME";
            const std::string colBus = "BUS";

            // Compute max widths for columns
            std::size_t nameMaxLen = colName.size();
            std::size_t typeMaxLen = colType.size();

            for (const auto& entry : indexEntries)
            {
                nameMaxLen = std::max(nameMaxLen, entry.name.size());
                typeMaxLen = std::max(typeMaxLen, entry.type->getQualifiedName().size());
            }

            // Print header
            std::ostringstream ossHeader;
            ossHeader << makePaddedString(colName, nameMaxLen)
                      << "    " << makePaddedString(colType, typeMaxLen)
                      << "    " << colBus;
            std::cout << ossHeader.str() << '\n';

            // Print rows
            for (const auto& entry : indexEntries)
            {
                const auto& typeName = entry.type->getQualifiedName();
                std::ostringstream ossRow;
                ossRow << makePaddedString(entry.name, nameMaxLen)
                       << "    " << makePaddedString(typeName, typeMaxLen)
                       << "    " << entry.session << '.' << entry.bus;
                std::cout << ossRow.str() << '\n';
            }
        }
        catch (const std::exception& ex)
        {
            std::cerr << ex.what() << '\n';
            std::exit(EXIT_FAILURE);
        }
    });
}

int executeMainProgram(int argc, char* argv[])
{
    CLI::App app {"Recording inspection utility\n"};
    app.name("sen archive");
    app.get_formatter()->column_width(12);  // NOLINT

    registerArchiveInfoCommand(app);
    registerIndexedObjectsCommand(app);

    app.footer("For help on specific commands run 'sen archive <command> --help'");
    CLI11_PARSE(app, argc, argv);
    return 0;
}

int main(int argc, char* argv[])
{
    sen::registerTerminateHandler();

    try
    {
        return executeMainProgram(argc, argv);
    }
    catch (const std::exception& ex)
    {
        std::fprintf(stderr, "Error detected: %s\n", ex.what());  // NOLINT
        return EXIT_FAILURE;
    }
    catch (...)
    {
        std::fputs("Unknown error detected\n", stderr);
        return EXIT_FAILURE;
    }
}

