int ask(const vector<int>& indices) {
    // Create a canonical representation by sorting the input
    vector<int> normalized = indices;
    sort(normalized.begin(), normalized.end());

    // Check if result is already cached
    if (memo.find(normalized) != memo.end()) {
        return memo[normalized];
    }

    // Output query to standard output
    cout << "? " << normalized.size();
    for (int idx : normalized) {
        cout << " " << idx;
    }
    cout << endl;
    cout.flush();

    // Read response from standard input
    int result;
    cin >> result;

    // Store in cache and return
    memo[normalized] = result;
    return result;
}

