//-----------------------------------------------------------------
/// @details
///		Initializes the classification task
//-----------------------------------------------------------------
Error Task::beginTask() noexcept {
    // Extract configuration
    json::Value &cfg = taskConfig();
    if (auto err = cfg.lookupAssign("wantsContext", m_wantsContext))
        return err;

    // Acquire source endpoint (read-only index mode)
    m_sourceEndpoint = IServiceEndpoint::getSourceEndpoint({
        .jobConfig = jobConfig(),
        .taskConfig = cfg,
        .openMode = OPEN_MODE::INDEX
    });
    if (!m_sourceEndpoint)
        return m_sourceEndpoint.ccode();

    // Acquire target endpoint (classification output mode)
    m_targetEndpoint = IServiceEndpoint::getTargetEndpoint({
        .jobConfig = jobConfig(),
        .taskConfig = cfg,
        .openMode = OPEN_MODE::CLASSIFY
    });
    if (!m_targetEndpoint)
        return m_targetEndpoint.ccode();

    // Delegate base initialization
    return Parent::beginTask();
}

//-----------------------------------------------------------------
/// @details
///		Parses incoming line and routes to parent for 'C'-prefixed entries
/// @param[in] line
///		A JSON-formatted string representing an entry
/// @param[in] parentUrl
///		URL context of the parent object
//-----------------------------------------------------------------
ErrorOr<Entry> Task::processLine(TextView line, const Url &parentUrl) noexcept {
    // Dispatch based on prefix "C"
    return Parent::processLine("C"_tv, line, parentUrl);
}

//-----------------------------------------------------------------
/// @details
///		Handles individual entry processing:
///		- Manages service pipe lifecycle
///		- Applies classification logic conditionally
///		- Updates monitoring stats and writes results/errors
/// @param[in,out] entry
///		The entry to process (may be modified in-place)
//-----------------------------------------------------------------
Error Task::processItem(Entry &entry) noexcept {
    // Pipe acquisition/release guard
    ErrorOr<ServicePipe> srcPipe;
    util::Guard cleanup{
        [&] { srcPipe = m_sourceEndpoint->getPipe(); },
        [&] {
            if (srcPipe)
                m_sourceEndpoint->putPipe(*srcPipe);
        }
    };

    // Early exit if pipe allocation fails
    if (!srcPipe)
        return srcPipe.ccode();

    // Determine if classification is needed
    const bool needsClassification = (entry.flags() & Entry::FLAGS::CLASSIFY);
    const bool alreadyClassified = entry.classificationId().has_value();

    if (needsClassification && (!alreadyClassified || m_wantsContext)) {
        // Perform classification
        if (auto ccode = Parent::processItem(entry, *srcPipe))
            return ccode;
        entry.changed(true);  // Mark as modified
    } else if (!needsClassification && alreadyClassified) {
        // Un-classify: mark changed even without reprocessing
        entry.changed(true);
    }

    // Always clear classification ID before output (per spec)
    entry.classificationId.reset();

    // Handle result/error paths
    if (entry.objectFailed()) {
        MONITOR(addFailed, 1, entry.size());
        return Parent::writeError(entry, entry.completionCode());
    } else {
        MONITOR(addCompleted, 1, entry.size());
        if (entry.changed()) {
            return Parent::writeResult('C', entry);
        }
    }

    return {};
}

