class Solution {
public:
    int minScoreTriangulation(vector<int>& values) {
        int size = values.size();
        int memo[50][50] = {0};

        // Fill DP table for intervals of increasing length
        for (int length = 2; length < size; ++length) {
            for (int left = 0; left + length < size; ++left) {
                int right = left + length;
                memo[left][right] = INT_MAX;

                // Try all possible triangulation points
                for (int mid = left + 1; mid < right; ++mid) {
                    int cost = values[left] * values[right] * values[mid] 
                             + memo[left][mid] 
                             + memo[mid][right];
                    memo[left][right] = min(memo[left][right], cost);
                }
            }
        }

        return memo[0][size - 1];
    }
};

