/* Autocorrelation-based LPC coefficient computation using Levinson-Durbin recursion */
/* Input : n samples of time-domain data
   Output: m LPC coefficients, residual energy */
float vorbis_lpc_from_data(float *data, float *lpci, int n, int m) {
    double *aut = (double*)alloca(sizeof(*aut) * (m + 1));
    double *lpc = (double*)alloca(sizeof(*lpc) * m);
    double residual_error;
    int i, j;

    /* Compute autocorrelation sequence for lags 0 to m */
    for (j = 0; j <= m; ++j) {
        double acc = 0.0;
        for (i = j; i < n; ++i)
            acc += static_cast<double>(data[i]) * data[i - j];
        aut[j] = acc;
    }

    /* Initialize error with zero-lag autocorrelation */
    residual_error = aut[0];

    /* Apply Durbin's recursion to compute LPC coefficients */
    for (i = 0; i < m; ++i) {
        double reflection = -aut[i + 1];

        if (residual_error == 0.0) {
            memset(lpci, 0, m * sizeof(*lpci));
            return 0.0f;
        }

        /* Update reflection coefficient using previous LPC coefficients */
        for (j = 0; j < i; ++j)
            reflection -= lpc[j] * aut[i - j];

        reflection /= residual_error;

        /* Store new reflection coefficient as next LPC coefficient */
        lpc[i] = reflection;

        /* Update existing LPC coefficients using symmetric update */
        for (j = 0; j < i / 2; ++j) {
            double temp = lpc[j];
            lpc[j] += reflection * lpc[i - 1 - j];
            lpc[i - 1 - j] += reflection * temp;
        }

        /* Handle middle coefficient for odd-order case */
        if (i % 2 == 0)
            lpc[j] += lpc[j] * reflection;

        /* Update prediction error */
        residual_error *= (1.0 - reflection * reflection);
    }

    /* Copy computed LPC coefficients to output buffer */
    for (j = 0; j < m; ++j)
        lpci[j] = static_cast<float>(lpc[j]);

    return static_cast<float>(residual_error);
}

/* Apply LPC filter to generate output signal from coefficients */
void vorbis_lpc_predict(float *coeff, float *prime, int m,
                        float *data, long n) {
    /* in: coeff[0..m-1] - LPC analysis coefficients
           prime[0..m-1] - initial conditions (size n+m-1 assumed)
       out: data[0..n-1] - synthesized samples */

    long i, j;
    float prediction;
    float *buffer = (float*)alloca(sizeof(*buffer) * (m + n));

    /* Initialize buffer with initial conditions or zeros */
    if (!prime) {
        for (i = 0; i < m; ++i)
            buffer[i] = 0.0f;
    } else {
        for (i = 0; i < m; ++i)
            buffer[i] = prime[i];
    }

    /* Generate output samples using direct-form I prediction */
    for (i = 0; i < n; ++i) {
        prediction = 0.0f;

        /* Compute predicted value using past samples and LPC coefficients */
        for (j = 0; j < m; ++j)
            prediction -= buffer[i + j] * coeff[m - 1 - j];

        /* Store new sample in buffer and output */
        buffer[i + m] = prediction;
        data[i] = prediction;
    }
}

