/// @file
/// @brief Aiwa based protocol.
/// Based off the RC-T501 RCU
/// Inspired by IRremoteESP8266's implementation
/// @see https://github.com/z3t0/Arduino-IRremote
// Supports:
//   Brand: Aiwa,  Model: RC-T501 RCU

const uint16_t kAiwaRcT501PreBits = 26;
const uint16_t kAiwaRcT501PostBits = 1;
const uint64_t kAiwaRcT501PreData = 0x1D8113FULL;  // 26-bits
const uint64_t kAiwaRcT501PostData = 1ULL;

#if SEND_AIWA_RC_T501
/// Send an Aiwa RC T501 formatted message.
/// Status: BETA / Should work.
/// @param[in] data The message to be sent.
/// @param[in] nbits The number of bits of the message to be sent.
///   Typically kAiwaRcT501Bits. Max is 37 = (64 - 27)
/// @param[in] repeat The number of times the command is to be repeated.
/// @see http://lirc.sourceforge.net/remotes/aiwa/RC-T501
void IRsend::sendAiwaRCT501(uint64_t payload, uint16_t payloadBitCount, uint16_t repeatCount) {
    auto buildFullMessage = [](uint64_t msg, uint16_t msgBits) -> uint64_t {
        uint64_t fullMsg = 0;
        fullMsg |= kAiwaRcT501PreData << (msgBits + kAiwaRcT501PostBits);
        fullMsg |= (msg & ((1ULL << msgBits) - 1)) << kAiwaRcT501PostBits;
        fullMsg |= kAiwaRcT501PostData;
        return fullMsg;
    };

    uint16_t totalBits = payloadBitCount + kAiwaRcT501PreBits + kAiwaRcT501PostBits;
    if (totalBits > 64) return;  // Avoid overflow beyond 64-bit

    uint64_t encodedMessage = buildFullMessage(payload, payloadBitCount);
    sendNEC(encodedMessage, totalBits, repeatCount);
}
#endif

#if DECODE_AIWA_RC_T501
/// Decode the supplied Aiwa RC T501 message.
/// Status: BETA / Should work.
/// @param[in,out] results Ptr to the data to decode & where to store the decode
///   result.
/// @param[in] offset The starting index to use when attempting to decode the
///   raw data. Typically/Defaults to kStartOffset.
/// @param[in] nbits The number of data bits to expect.
/// @param[in] strict Flag indicating if we should perform strict matching.
/// @return A boolean. True if it can decode it, false if it can't.
bool IRrecv::decodeAiwaRCT501(decode_results *results, uint16_t offset,
                              const uint16_t expectedPayloadBits, const bool strict) {
    // Early compliance check
    if (strict && expectedPayloadBits != kAiwaRcT501Bits)
        return false;

    uint16_t totalExpectedBits = expectedPayloadBits + kAiwaRcT501PreBits + kAiwaRcT501PostBits;
    if (totalExpectedBits > 64) return false;

    // Decode as non-strict NEC first
    if (!decodeNEC(results, offset, totalExpectedBits, false))
        return false;

    uint64_t rawValue = results->value;
    uint16_t actualBits = results->bits;

    if (actualBits < totalExpectedBits)
        return false;

    // Validate postfix
    if ((rawValue & 1ULL) != kAiwaRcT501PostData)
        return false;

    // Strip postfix
    rawValue >>= kAiwaRcT501PostBits;
    actualBits -= kAiwaRcT501PostBits;

    // Extract payload and prefix
    uint64_t payloadMask = (1ULL << actualBits) - 1;
    uint64_t extractedPayload = rawValue & payloadMask;
    rawValue >>= actualBits;
    actualBits -= kAiwaRcT501PreBits;

    // Verify prefix
    if (rawValue != kAiwaRcT501PreData)
        return false;

    // Final compliance check
    if (strict && actualBits != expectedPayloadBits)
        return false;

    // Populate decoded result
    results->value = extractedPayload;
    results->decode_type = AIWA_RC_T501;
    results->bits = actualBits;
    results->address = 0;
    results->command = 0;

    return true;
}
#endif

