struct Test::Attributes {
    std::shared_ptr<Tensor> inputA;
    std::shared_ptr<Tensor> inputB;
    std::shared_ptr<Tensor> outputC;
    std::shared_ptr<Tensor> expectedResult;
};

std::shared_ptr<Test> Test::build(
    std::unordered_map<std::string, std::vector<uint8_t>> attrs,
    std::unordered_map<std::string, std::shared_ptr<Tensor>> tensors,
    double rtol, double atol) {

    auto test = std::make_shared<Test>(rtol, atol);
    test->_attributes = new Attributes();

    // Validate required tensor keys exist
    const std::vector<std::string> requiredKeys = {"a", "b", "c", "ans"};
    for (const auto& key : requiredKeys) {
        if (tensors.find(key) == tensors.end()) {
            throw std::runtime_error("Invalid Test: missing tensor '" + key + "'");
        }
    }

    // Assign tensors to attributes using clearer naming
    test->_attributes->inputA   = tensors["a"];
    test->_attributes->inputB   = tensors["b"];
    test->_attributes->outputC  = tensors["c"];
    test->_attributes->expectedResult = tensors["ans"];

    return test;
}

std::shared_ptr<infiniop_test::Result> Test::run(
    infiniopHandle_t handle, infiniDevice_t device, int devId, size_t warmupCount, size_t iterCount) {

    infiniopSubDescriptor_t opDesc;

    // Move tensors to target device
    auto devA = _attributes->inputA->to(device, devId);
    auto devB = _attributes->inputB->to(device, devId);
    auto devC = _attributes->outputC->to(device, devId);

    // Create operator descriptor
    CHECK_OR(infiniopCreateSubDescriptor(handle, &opDesc,
                                         devC->desc(),
                                         devA->desc(),
                                         devB->desc()),
             return TEST_FAILED(OP_CREATION_FAILED, "Failed to create sub operator descriptor."));

    // Query and allocate workspace
    size_t workspaceSize;
    CHECK_OR(infiniopGetSubWorkspaceSize(opDesc, &workspaceSize),
             return TEST_FAILED(OP_CREATION_FAILED, "Failed to query workspace size."));

    void* workspacePtr = nullptr;
    CHECK_OR(infinirtMalloc(&workspacePtr, workspaceSize),
             return TEST_FAILED(OP_CREATION_FAILED, "Failed to allocate workspace memory."));

    // Execute operation once for correctness check
    CHECK_OR(infiniopSub(opDesc, workspacePtr, workspaceSize,
                         devC->data(),
                         devA->data(),
                         devB->data(),
                         nullptr),
             return TEST_FAILED(OP_EXECUTION_FAILED, "Sub operation failed during execution."));

    // Verify result against expected output
    try {
        allClose(devC, _attributes->expectedResult, _rtol, _atol);
    } catch (const std::exception& ex) {
        return TEST_FAILED(RESULT_INCORRECT, ex.what());
    }

    // Benchmark performance
    double totalTime = benchmark(
        [=]() {
            infiniopSub(opDesc, workspacePtr, workspaceSize,
                        devC->data(), devA->data(), devB->data(), nullptr);
        },
        warmupCount, iterCount);

    return TEST_PASSED(totalTime);
}

