// Storage for recorded moves
vector<pair<int, int>> moveLog;
// Global configuration
int numPoles, ballsPerPole;
vector<vector<int>> poleState;

// Execute a single ball transfer and record it
void transferBall(int src, int dst) {
    if (poleState[src].empty()) return; // Safety check

    int ball = poleState[src].back();
    poleState[src].pop_back();
    poleState[dst].push_back(ball);
    moveLog.push_back({src + 1, dst + 1});
}

