    poleState.resize(numPoles + 1); // Extra pole as buffer

    // Read initial state (colors remain 1-based)
    for (int i = 0; i < numPoles; ++i) {
        poleState[i].resize(ballsPerPole);
        for (int j = 0; j < ballsPerPole; ++j) {
            cin >> poleState[i][j];
