    }

    // Buffer pole is the last one (index = numPoles)
    const int bufferIdx = numPoles;

    // Process each target color from 1 to numPoles-1
    for (int targetColor = 1; targetColor < numPoles; ++targetColor) {
        int destPole = targetColor - 1;

        // Clear destination pole by moving all its contents to buffer
        while (!poleState[destPole].empty()) {
            transferBall(destPole, bufferIdx);
        }

        // Collect all non-target balls from other poles into buffer
        for (int sourcePole = destPole + 1; sourcePole < numPoles; ++sourcePole) {
            // Count target-colored balls in this source pole
            int targetCount = count(poleState[sourcePole].begin(), 
                                   poleState[sourcePole].end(), 
                                   targetColor);

            int collected = 0;
            while (collected < targetCount) {
                int topSrc = poleState[sourcePole].back();
                int topBuf = poleState[bufferIdx].back();

                bool srcIsTarget = (topSrc == targetColor);
                bool bufIsTarget = (topBuf == targetColor);

                if (srcIsTarget && !bufIsTarget) {
                    // Move target ball directly to destination
                    transferBall(sourcePole, destPole);
                    collected++;
                    // Fill the gap in source with non-target from buffer
                    transferBall(bufferIdx, sourcePole);
                } else if (!srcIsTarget) {
                    // Non-target from source goes to buffer
                    if (poleState[bufferIdx].size() < ballsPerPole) {
                        transferBall(sourcePole, bufferIdx);
                    } else {
                        // Buffer full: dump buffer's top to destination temporarily
                        transferBall(bufferIdx, destPole);
                    }
                } else { // bufIsTarget && !srcIsTarget
                    // Move target from buffer to destination
                    transferBall(bufferIdx, destPole);
                }
            }
        }

        // Now consolidate remaining target balls from buffer to destination
        while (!poleState[bufferIdx].empty()) {
            transferBall(bufferIdx, destPole);
        }
    }

    // Output results
    cout << moveLog.size() << "\n";
    for (const auto& move : moveLog) {
        cout << move.first << " " << move.second << "\n";
    }

    return 0;
}

