#include "llama.h"
#include <cstdio>
#include <cstring>
#include <iostream>
#include <string>
#include <vector>

static void show_help(int, char ** argv) {
    fprintf(stderr, "\nusage:\n");
    fprintf(stderr, "\n  %s --model model.gguf [--ctx context_size] [--ngl n_gpu_layers]\n", argv[0]);
    fprintf(stderr, "\n");
}

int main(int argc, char ** argv) {
    std::string model_file;
    int layers_on_gpu = 99;
    int context_length = 2048;

    // parse command line options
    for (int idx = 1; idx < argc; ++idx) {
        try {
            if (strcmp(argv[idx], "--model") == 0 || strcmp(argv[idx], "-m") == 0) {
                if (idx + 1 < argc) {
                    model_file = argv[++idx];
                } else {
                    show_help(argc, argv);
                    return 1;
                }
            } else if (strcmp(argv[idx], "--ctx") == 0 || strcmp(argv[idx], "-c") == 0) {
                if (idx + 1 < argc) {
                    context_length = std::stoi(argv[++idx]);
                } else {
                    show_help(argc, argv);
                    return 1;
                }
            } else if (strcmp(argv[idx], "--ngl") == 0 || strcmp(argv[idx], "-ngl") == 0) {
                if (idx + 1 < argc) {
                    layers_on_gpu = std::stoi(argv[++idx]);
                } else {
                    show_help(argc, argv);
                    return 1;
                }
            } else {
                show_help(argc, argv);
                return 1;
            }
        } catch (const std::exception & ex) {
            fprintf(stderr, "error: %s\n", ex.what());
            show_help(argc, argv);
            return 1;
        }
    }

    if (model_file.empty()) {
        show_help(argc, argv);
        return 1;
    }

    // suppress non-error logs
    llama_log_set([](enum ggml_log_level lvl, const char * msg, void * /*unused*/) {
        if (lvl >= GGML_LOG_LEVEL_ERROR) {
            fprintf(stderr, "%s", msg);
        }
    }, nullptr);

    // load all available backends
    ggml_backend_load_all();

    // configure and load the model
    llama_model_params mparams = llama_model_default_params();
    mparams.n_gpu_layers = layers_on_gpu;
    llama_model * model = llama_model_load_from_file(model_file.c_str(), mparams);
    if (!model) {
        fprintf(stderr, "%s: error: cannot load model\n", __func__);
        return 1;
    }

    const llama_vocab * vocab = llama_model_get_vocab(model);

    // setup inference context
    llama_context_params cparams = llama_context_default_params();
    cparams.n_ctx = context_length;
    cparams.n_batch = context_length;
    llama_context * ctx = llama_init_from_model(model, cparams);
    if (!ctx) {
        fprintf(stderr, "%s: error: failed to create context\n", __func__);
        return 1;
    }

    // build sampler chain
    llama_sampler * chain = llama_sampler_chain_init(llama_sampler_chain_default_params());
    llama_sampler_chain_add(chain, llama_sampler_init_min_p(0.05f, 1));
    llama_sampler_chain_add(chain, llama_sampler_init_temp(0.8f));
    llama_sampler_chain_add(chain, llama_sampler_init_dist(LLAMA_DEFAULT_SEED));

    // function to process a prompt and produce output tokens
    auto infer = [&](const std::string & input_text) -> std::string {
        std::string output_text;
        const bool first_turn = llama_memory_seq_pos_max(llama_get_memory(ctx), 0) == -1;

        // tokenize input
        const int input_len = -llama_tokenize(vocab, input_text.c_str(), input_text.size(), nullptr, 0, first_turn, true);
        std::vector<llama_token> tokens(input_len);
        if (llama_tokenize(vocab, input_text.c_str(), input_text.size(), tokens.data(), tokens.size(), first_turn, true) < 0) {
            GGML_ABORT("tokenization of input failed\n");
        }

        // prepare initial batch
        llama_batch batch = llama_batch_get_one(tokens.data(), tokens.size());
        llama_token next_token;

        while (true) {
            // ensure context capacity
            int total_slots = llama_n_ctx(ctx);
            int used_slots = llama_memory_seq_pos_max(llama_get_memory(ctx), 0) + 1;
            if (used_slots + batch.n_tokens > total_slots) {
                printf("\033[0m\n");
                fprintf(stderr, "context size exceeded\n");
                exit(0);
            }

            // decode current batch
            int status = llama_decode(ctx, batch);
            if (status != 0) {
                GGML_ABORT("decoding failed, code %d\n", status);
            }

            // select next token
            next_token = llama_sampler_sample(chain, ctx, -1);

            // stop on end-of-generation token
            if (llama_vocab_is_eog(vocab, next_token)) {
                break;
            }

            // convert token to string and print
            char piece[256];
            int len = llama_token_to_piece(vocab, next_token, piece, sizeof(piece), 0, true);
            if (len < 0) {
                GGML_ABORT("cannot convert token to text\n");
            }
            std::string fragment(piece, len);
            printf("%s", fragment.c_str());
            fflush(stdout);
            output_text += fragment;

            // prepare next-step batch
            batch = llama_batch_get_one(&next_token, 1);
        }

        return output_text;
    };

    // chat history management
    std::vector<llama_chat_message> conversation;
    std::vector<char> buffer(llama_n_ctx(ctx));
    int last_offset = 0;

    while (true) {
        // prompt user
        printf("\033[32m> \033[0m");
        std::string user_input;
        std::getline(std::cin, user_input);
        if (user_input.empty()) {
            break;
        }

        const char * chat_template = llama_model_chat_template(model, nullptr);

        // append new message
        conversation.push_back({"user", strdup(user_input.c_str())});
        int updated_len = llama_chat_apply_template(chat_template, conversation.data(), conversation.size(), true, buffer.data(), buffer.size());

        if (updated_len > static_cast<int>(buffer.size())) {
            buffer.resize(updated_len);
            updated_len = llama_chat_apply_template(chat_template, conversation.data(), conversation.size(), true, buffer.data(), buffer.size());
        }

        if (updated_len < 0) {
            fprintf(stderr, "chat template processing failed\n");
            return 1;
        }

        // extract only the new part as prompt
        std::string prompt(buffer.begin() + last_offset, buffer.begin() + updated_len);

        // generate assistant response
        printf("\033[33m");
        std::string reply = infer(prompt);
        printf("\n\033[0m");

        // store assistant reply
        conversation.push_back({"assistant", strdup(reply.c_str())});
        last_offset = llama_chat_apply_template(chat_template, conversation.data(), conversation.size(), false, nullptr, 0);

        if (last_offset < 0) {
            fprintf(stderr, "chat template processing failed\n");
            return 1;
        }
    }

    // cleanup
    for (auto & entry : conversation) {
        free(const_cast<char *>(entry.content));
    }
    llama_sampler_free(chain);
    llama_free(ctx);
    llama_model_free(model);

    return 0;
}

#include <nanobind/nanobind.h>
