#include <mscclpp/gpu.hpp>

namespace nb = nanobind;
using namespace mscclpp;

void register_executor(nb::module_& module) {
  // Register data type enumeration
  nb::enum_<DataType>(module, "DataType")
      .value("int32", DataType::INT32)
      .value("uint32", DataType::UINT32)
      .value("float16", DataType::FLOAT16)
      .value("float32", DataType::FLOAT32)
      .value("bfloat16", DataType::BFLOAT16);

  // Register packet type enumeration
  nb::enum_<PacketType>(module, "PacketType")
      .value("LL8", PacketType::LL8)
      .value("LL16", PacketType::LL16);

  // Bind ExecutionPlan class
  nb::class_<ExecutionPlan>(module, "ExecutionPlan")
      .def(nb::init<const std::string&>(), nb::arg("plan_path"))
      .def("name", &ExecutionPlan::name)
      .def("collective", &ExecutionPlan::collective)
      .def("min_message_size", &ExecutionPlan::minMessageSize)
      .def("max_message_size", &ExecutionPlan::maxMessageSize);

  // Helper lambda to cast raw pointers for execute call
  auto execute_wrapper = [](Executor* exec, int rank,
                            uintptr_t send_addr, uintptr_t recv_addr,
                            size_t send_size, size_t recv_size,
                            DataType dtype, const ExecutionPlan& plan,
                            uintptr_t stream_stream, PacketType pkt_type) {
    exec->execute(rank,
                  reinterpret_cast<void*>(send_addr),
                  reinterpret_cast<void*>(recv_addr),
                  send_size, recv_size,
                  dtype, plan,
                  static_cast<cudaStream_t>(stream_stream),
                  pkt_type);
  };

  // Bind Executor class with overloaded execute method
  nb::class_<Executor>(module, "Executor")
      .def(nb::init<std::shared_ptr<Communicator>>(), nb::arg("communicator"))
      .def("execute", execute_wrapper,
           nb::arg("rank"), nb::arg("send_buffer"), nb::arg("recv_buffer"),
           nb::arg("send_buffer_size"), nb::arg("recv_buffer_size"),
           nb::arg("data_type"), nb::arg("plan"), nb::arg("stream"),
           nb::arg("packet_type") = PacketType::LL16);
}

