#include <iostream>
#include <iomanip>
#include <cmath>

// Assume these headers are included elsewhere in full program:
// #include <Teuchos_RCP.hpp>
// #include <Teuchos_ParameterList.hpp>
// #include <Teuchos_XMLParameterListHelpers.hpp>
// #include "ROL_Ptr.hpp"
// #include "Intrepid2_Basis_HGRAD_QUAD_C2_FEM.hpp"
// #include "Intrepid2_DefaultCubatureFactory.hpp"
// #include "shards_CellTopology.hpp"
// #include "MeshManager_Rectangle.hpp"
// #include "FE.hpp"
// #include "Kokkos_Core.hpp"

int main() {
  int errorFlag = 0;
  std::ostream* outStream = &std::cout;

  try {
    // Load parameter list from XML file
    std::string configFilename = "input_04.xml";
    Teuchos::RCP<Teuchos::ParameterList> parameters
      = Teuchos::rcp( new Teuchos::ParameterList() );
    Teuchos::updateParametersFromXmlFile(configFilename, parameters.ptr());

    // Initialize mesh and DOF manager
    MeshManager_Rectangle<RealT, DeviceT> meshManager(*parameters);
    scalar_view nodeCoordinates = meshManager.getNodes();
    int_view elementToNodeMap = meshManager.getCellToNodeMap();

    *outStream << "Number of nodes = " << meshManager.getNumNodes() << std::endl;
    *outStream << "Number of cells = " << meshManager.getNumCells() << std::endl;
    *outStream << "Number of edges = " << meshManager.getNumEdges() << std::endl;

    ROL::Ptr<MeshManager<RealT, DeviceT>> meshManagerPtr = ROL::makePtrFromRef(meshManager);

    // Define finite element basis: quadratic Lagrange on quadrilateral
    basis_ptr feBasis = ROL::makePtr<Intrepid2::Basis_HGRAD_QUAD_C2_FEM<DeviceT, RealT, RealT>>();

    // Set up cubature
    ROL::Ptr<Intrepid2::Cubature<DeviceT, RealT, RealT>> integrationRule;
    shards::CellTopology cellShape = feBasis->getBaseCellTopology();     // e.g., quadrilateral
    Intrepid2::DefaultCubatureFactory cubFactory;                        // factory for standard cubatures
    int integrationOrder = 4;                                            // polynomial degree for exactness
    integrationRule = cubFactory.create<DeviceT, RealT, RealT>(cellShape, integrationOrder);

    // Populate cell-wise nodal coordinates
    scalar_view elementCoords("elementCoords", meshManager.getNumCells(), cellShape.getNodeCount(), cellShape.getDimension());
    for (int elemIdx = 0; elemIdx < meshManager.getNumCells(); ++elemIdx) {
      for (unsigned localNode = 0; localNode < cellShape.getNodeCount(); ++localNode) {
        for (unsigned dim = 0; dim < cellShape.getDimension(); ++dim) {
          unsigned globalNode = elementToNodeMap(elemIdx, localNode);
          elementCoords(elemIdx, localNode, dim) = nodeCoordinates(globalNode, dim);
        }
      }
    }

    // Construct FE object
    FE<RealT, DeviceT> finiteElement(elementCoords, feBasis, integrationRule);

    // --- Value integral test ---
    scalar_view valueEval1("valueEval1", meshManager.getNumCells(), integrationRule->getNumPoints());
    scalar_view valueEval2("valueEval2", meshManager.getNumCells(), integrationRule->getNumPoints());
    scalar_view valueIntegralPerCell("valueIntegralPerCell", meshManager.getNumCells());

    Kokkos::deep_copy(finiteElement.getCoefficientsView(valueEval1), static_cast<RealT>(1));
    Kokkos::deep_copy(finiteElement.getCoefficientsView(valueEval2), static_cast<RealT>(2));

    finiteElement.evaluateValue(valueEval1, finiteElement.makeCoefficientsView(valueEval1));
    finiteElement.evaluateValue(valueEval2, finiteElement.makeCoefficientsView(valueEval2));
    finiteElement.computeIntegral(valueIntegralPerCell, valueEval1, valueEval2);

    RealT valueIntegral = static_cast<RealT>(0);
    for (int i = 0; i < meshManager.getNumCells(); ++i) {
      valueIntegral += valueIntegralPerCell(i);
    }

    if (std::abs(valueIntegral - static_cast<RealT>(1000)) > std::sqrt(ROL::ROL_EPSILON<RealT>())) {
      errorFlag = -1;
    }

    // --- Gradient integral test ---
    scalar_view dofPositions("dofPositions", meshManager.getNumCells(), feBasis->getCardinality(), integrationRule->getDimension());
    finiteElement.computeDofCoords(dofPositions, elementCoords);

    scalar_view gradCoeffs1("gradCoeffs1", meshManager.getNumCells(), feBasis->getCardinality());
    scalar_view gradCoeffs2("gradCoeffs2", meshManager.getNumCells(), feBasis->getCardinality());

    for (int elemIdx = 0; elemIdx < meshManager.getNumCells(); ++elemIdx) {
      for (int localDof = 0; localDof < feBasis->getCardinality(); ++localDof) {
        RealT xCoord = dofPositions(elemIdx, localDof, 0);
        RealT yCoord = dofPositions(elemIdx, localDof, 1);
        gradCoeffs1(elemIdx, localDof) = xCoord + yCoord;
        gradCoeffs2(elemIdx, localDof) = static_cast<RealT>(2)*xCoord + static_cast<RealT>(3)*yCoord;
      }
    }

    scalar_view gradEval1("gradEval1", meshManager.getNumCells(), integrationRule->getNumPoints(), integrationRule->getDimension());
    scalar_view gradEval2("gradEval2", meshManager.getNumCells(), integrationRule->getNumPoints(), integrationRule->getDimension());
    scalar_view gradIntegralPerCell("gradIntegralPerCell", meshManager.getNumCells());

    finiteElement.evaluateGradient(gradEval1, gradCoeffs1);
    finiteElement.evaluateGradient(gradEval2, gradCoeffs2);
    finiteElement.computeIntegral(gradIntegralPerCell, gradEval1, gradEval2);

    RealT gradientIntegral = static_cast<RealT>(0);
    for (int i = 0; i < meshManager.getNumCells(); ++i) {
      gradientIntegral += gradIntegralPerCell(i);
    }

    if (std::abs(gradientIntegral - static_cast<RealT>(2500)) > std::sqrt(ROL::ROL_EPSILON<RealT>())) {
      errorFlag = -1;
    }

    *outStream << std::setprecision(14)
               << "\nvalueIntegral=" << valueIntegral
               << "  gradientIntegral=" << gradientIntegral << std::endl;

  } catch (std::logic_error& err) {
    *outStream << "Exception caught: " << err.what() << "\n";
    errorFlag = -1000;
  }

  if (errorFlag != 0) {
    std::cout << "End Result: TEST FAILED\n";
  } else {
    std::cout << "End Result: TEST PASSED\n";
  }

  return 0;
}

#include <iostream>
#include <cassert>
#include <cmath>
#include <cstdint>
#include <cstring>
#include <limits>

#if !defined(__riscv) && !defined(__s390__) && !defined(__ARM_NEON)
#include <immintrin.h>
#endif

#pragma GCC diagnostic push
#pragma GCC diagnostic ignored "-Wdouble-promotion"

// Reference rounding implementation used in quantization
inline static uint8_t round_reference(float value) {
    return static_cast<uint8_t>(static_cast<int8_t>(std::round(value)) + 8);
}

// Optimized rounding using single-precision math
inline static uint8_t round_fast(float value) {
    return static_cast<uint8_t>(static_cast<int8_t>(std::roundf(value)) + 8);
}

// Original SiLU implementation (double-precision constants)
inline static float silu_reference(float x) {
    return x / (1.0f + std::exp(-x));
}

// Optimized SiLU using float-specific math functions
inline static float silu_optimized(float x) {
    return x / (1.0f + std::expf(-x));
}

// Helper to safely reinterpret bits as float
inline static float bitcast_to_float(uint32_t bits) {
    float result;
    std::memcpy(&result, &bits, sizeof(result));
    return result;
}

int main() {
    // Test all non-finite or finite float values from max down to zero
    for (uint32_t val = std::numeric_limits<uint32_t>::max();; --val) {
        float f = bitcast_to_float(val);
        assert(!std::isfinite(f) || (round_reference(f) == round_fast(f)));
        if (val == 0) break;
    }

#ifdef __F16C__
    // Validate SiLU behavior under FP16 conversion
    for (uint16_t raw = 0; raw <= std::numeric_limits<uint16_t>::max(); ++raw) {
        float input = _cvtsh_ss(raw);
        float ref_out = silu_reference(input);
        float opt_out = silu_optimized(input);

        uint16_t ref_fp16 = _cvtss_sh(ref_out, 0);
        uint16_t opt_fp16 = _cvtss_sh(opt_out, 0);

        bool equal_or_adjacent =
            (ref_fp16 == opt_fp16) ||
            (std::nextafterf(ref_out, opt_out) == opt_out) ||
            (std::nextafterf(opt_out, ref_out) == ref_out);

        assert(equal_or_adjacent);
    }
#endif

    return 0;
}

