void OreRecipies::_init()
{
    // Initialize recipe mapping array
    map = new vector<Object*>[MAX_ORE_RECIPES];

    // Populate gold block -> ingot mapping
    ADD_OBJECT(map[0], Tile::goldBlock);
    ADD_OBJECT(map[0], new ItemInstance(Item::goldIngot, 9));

    // Populate iron block -> ingot mapping
    ADD_OBJECT(map[1], Tile::ironBlock);
    ADD_OBJECT(map[1], new ItemInstance(Item::ironIngot, 9));

    // Populate diamond block -> diamond mapping
    ADD_OBJECT(map[2], Tile::diamondBlock);
    ADD_OBJECT(map[2], new ItemInstance(Item::diamond, 9));

    // Populate emerald block -> emerald mapping
    ADD_OBJECT(map[3], Tile::emeraldBlock);
    ADD_OBJECT(map[3], new ItemInstance(Item::emerald, 9));

    // Populate lapis block -> blue dye mapping
    ADD_OBJECT(map[4], Tile::lapisBlock);
    ADD_OBJECT(map[4], new ItemInstance(Item::dye_powder, 9, DyePowderItem::BLUE));
}

void OreRecipies::addRecipes(Recipes* r)
{
    // Iterate through all registered ore recipes
    for (int idx = 0; idx < MAX_ORE_RECIPES; ++idx)
    {
        // Extract source tile and target item instance
        Tile* srcTile = static_cast<Tile*>(map[idx][0]->tile);
        ItemInstance* dstItem = static_cast<ItemInstance*>(map[idx][1]->iteminstance);

        // Add crafting recipe: Block → Ingot (3x3 shape)
        r->addShapedRecipy(
            new ItemInstance(srcTile),
            L"sssczg",
            L"###", 
            L"###", 
            L"###", 
            L'#', dstItem,
            L'D'
        );

        // Add crafting recipe: Ingot → Block (1x1 shape)
        r->addShapedRecipy(
            dstItem,
            L"sctg",
            L"#", 
            L'#', srcTile,
            L'D'
        );
    }
}

