// Static empty sector buffer
byteArray RegionFile::emptySector(SECTOR_BYTES);

// Constructor: Initialize region file from path and save file
RegionFile::RegionFile(ConsoleSaveFile *saveFile, File *path)
    : _lastModified(0), m_saveFile(saveFile), fileName(path), sizeDelta(0), m_bIsEmpty(false)
{
    // Allocate offset and timestamp tables
    m_chunkOffsets = new int[SECTOR_INTS];
    std::fill(m_chunkOffsets, m_chunkOffsets + SECTOR_INTS, 0);

    m_timestamps = new int[SECTOR_INTS];
    std::fill(m_timestamps, m_timestamps + SECTOR_INTS, 0);

    // Open or create file entry
    fileEntry = m_saveFile->createFile(fileName->getName());
    m_saveFile->setFilePointer(fileEntry, 0, nullptr, FILE_END);

    const auto fileSize = fileEntry->getFileSize();
    if (fileSize < SECTOR_BYTES) {
        m_bIsEmpty = true;
        sizeDelta += SECTOR_BYTES * 2; // Reserve space for initial sectors on first write
    } else {
        m_bIsEmpty = false;
    }

    // Align file size to sector boundary if needed
    if ((fileSize & 0xFFF) != 0) {
        const DWORD bytesToPad = 0x1000 - (fileSize & 0xFFF);
        std::unique_ptr<byte[]> padding(new byte[bytesToPad]{});
        DWORD written = 0;
        m_saveFile->writeFile(fileEntry, padding.get(), bytesToPad, &written);
    }

    // Initialize sector availability map
    const int totalSectors = m_bIsEmpty ? 2 : static_cast<int>(fileSize / SECTOR_BYTES);
    m_sectorAvailabilityMap.reserve(totalSectors);
    std::fill_n(std::back_inserter(m_sectorAvailabilityMap), totalSectors, true);
    m_sectorAvailabilityMap[0] = false; // Offset table sector
    m_sectorAvailabilityMap[1] = false; // Timestamp sector

    // Read existing metadata
    m_saveFile->setFilePointer(fileEntry, 0, nullptr, FILE_BEGIN);
    for (int i = 0; i < SECTOR_INTS; ++i) {
        unsigned int offset = 0;
        DWORD bytesRead = 0;
        if (!m_bIsEmpty) {
            m_saveFile->readFile(fileEntry, &offset, sizeof(offset), &bytesRead);
            if (m_saveFile->isSaveEndianDifferent()) System::ReverseULONG(&offset);
        }
        m_chunkOffsets[i] = static_cast<int>(offset);

        if (offset != 0 && ((offset >> 8) + (offset & 0xFF)) <= m_sectorAvailabilityMap.size()) {
            const unsigned int startSector = offset >> 8;
            const unsigned int numSectors = offset & 0xFF;
            for (unsigned int s = 0; s < numSectors; ++s) {
                m_sectorAvailabilityMap[startSector + s] = false;
            }
        }
    }

    // Read timestamps
    for (int i = 0; i < SECTOR_INTS; ++i) {
        int timestamp = 0;
        DWORD bytesRead = 0;
        if (!m_bIsEmpty) {
            m_saveFile->readFile(fileEntry, &timestamp, sizeof(timestamp), &bytesRead);
            if (m_saveFile->isSaveEndianDifferent()) System::ReverseINT(&timestamp);
        }
        m_timestamps[i] = timestamp;
    }
}

// Write all offsets and timestamps back to disk (used for cross-platform conversion)
void RegionFile::writeAllOffsets()
{
    if (!m_bIsEmpty) {
        m_saveFile->LockSaveAccess();

        DWORD written = 0;
        m_saveFile->setFilePointer(fileEntry, 0, nullptr, FILE_BEGIN);
        m_saveFile->writeFile(fileEntry, m_chunkOffsets, SECTOR_BYTES, &written);

        written = 0;
        m_saveFile->setFilePointer(fileEntry, SECTOR_BYTES, nullptr, FILE_BEGIN);
        m_saveFile->writeFile(fileEntry, m_timestamps, SECTOR_BYTES, &written);

        m_saveFile->ReleaseSaveAccess();
    }
}

// Destructor: Clean up resources
RegionFile::~RegionFile()
{
