// Get input stream for reading chunk data at (x,z)
DataInputStream* RegionFile::getChunkDataInputStream(int x, int z)
{
    if (outOfBounds(x, z)) return nullptr;

    const int offset = getOffset(x, z);
    if (offset == 0) return nullptr;

    const unsigned int sectorNum = offset >> 8;
    const unsigned int numSectors = offset & 0xFF;

    if (sectorNum + numSectors > m_sectorAvailabilityMap.size()) return nullptr;

    m_saveFile->LockSaveAccess();

    m_saveFile->setFilePointer(fileEntry, sectorNum * SECTOR_BYTES, nullptr, FILE_BEGIN);

    unsigned int length, decompressedLength;
    DWORD bytesRead = 0;

    m_saveFile->readFile(fileEntry, &length, sizeof(length), &bytesRead);
    if (m_saveFile->isSaveEndianDifferent()) System::ReverseULONG(&length);

    bool useRLE = false;
    if (length & 0x80000000) {
        useRLE = true;
        length &= 0x7FFFFFFF;
    }

    m_saveFile->readFile(fileEntry, &decompressedLength, sizeof(decompressedLength), &bytesRead);
    if (m_saveFile->isSaveEndianDifferent()) System::ReverseULONG(&decompressedLength);

    if (length > SECTOR_BYTES * numSectors) {
        m_saveFile->ReleaseSaveAccess();
        return nullptr;
    }

    MemSect(50);
    std::unique_ptr<byte[]> rawData(new byte[length]);
    std::unique_ptr<byte[]> decompressedData(new byte[decompressedLength]);
    MemSect(0);

    bytesRead = 0;
    m_saveFile->readFile(fileEntry, rawData.get(), length, &bytesRead);
    m_saveFile->ReleaseSaveAccess();

    Compression::getCompression()->SetDecompressionType(m_saveFile->getSavePlatform());

    unsigned int actualDecompLen = decompressedLength;
    if (useRLE) {
        Compression::getCompression()->DecompressLZXRLE(decompressedData.get(), &actualDecompLen, rawData.get(), length);
    } else {
        Compression::getCompression()->Decompress(decompressedData.get(), &actualDecompLen, rawData.get(), length);
    }

    Compression::getCompression()->SetDecompressionType(SAVE_FILE_PLATFORM_LOCAL);

    DataInputStream* stream = new DataInputStream(
        new ByteArrayInputStream(byteArray(decompressedData.release(), actualDecompLen))
    );
    return stream;
}

// Get output stream for writing chunk data
DataOutputStream* RegionFile::getChunkDataOutputStream(int x, int z)
{
    return new DataOutputStream(new ChunkBuffer(this, x, z));
}

// Write chunk data to disk
void RegionFile::write(int x, int z, byte* data, int length)
{
    // Compress data using RLE method
    std::unique_ptr<byte[]> compressed(new byte[length + 2048]);
    unsigned int compLen = length;
    Compression::getCompression()->CompressLZXRLE(compressed.get(), &compLen, data, length);

    const int sectorsRequired = (compLen + CHUNK_HEADER_SIZE) / SECTOR_BYTES + 1;
    if (sectorsRequired >= 256) return;

    m_saveFile->LockSaveAccess();

    const int currentOffset = getOffset(x, z);
    const int currentSector = currentOffset >> 8;
    const int currentAllocatedSectors = currentOffset & 0xFF;

#ifndef _CONTENT_PACKAGE
    if (currentSector < 0) __debugbreak();
#endif

    if (currentSector != 0 && currentAllocatedSectors == sectorsRequired) {
        // Overwrite in place
        write(currentSector, compressed.get(), length, compLen);
    } else {
        // Free old sectors
        for (int i = 0; i < currentAllocatedSectors; ++i) {
            m_sectorAvailabilityMap[currentSector + i] = true;
        }
        zero(currentSector, SECTOR_BYTES * currentAllocatedSectors);

        // Find free run
        auto it = std::find(m_sectorAvailabilityMap.begin(), m_sectorAvailabilityMap.end(), true);
        int runStart = static_cast<int>(it - m_sectorAvailabilityMap.begin());
        int runLength = 0;

        if (runStart != static_cast<int>(m_sectorAvailabilityMap.size())) {
            for (size_t i = runStart; i < m_sectorAvailabilityMap.size(); ++i) {
                if (runLength != 0) {
                    if (m_sectorAvailabilityMap[i]) ++runLength;
                    else runLength = 0;
                } else if (m_sectorAvailabilityMap[i]) {
                    runStart = static_cast<int>(i);
                    runLength = 1;
                }
                if (runLength >= sectorsRequired) break;
            }
        }

        if (runLength >= sectorsRequired) {
            // Reuse existing space
            const int newSector = runStart;
            setOffset(x, z, (newSector << 8) | sectorsRequired);
            for (int i = 0; i < sectorsRequired; ++i) {
                m_sectorAvailabilityMap[newSector + i] = false;
            }
            write(newSector, compressed.get(), length, compLen);
        } else {
            // Expand file
            m_saveFile->setFilePointer(fileEntry, 0, nullptr, FILE_END);
            const int newSector = static_cast<int>(m_sectorAvailabilityMap.size());

            DWORD written = 0;
            for (int i = 0; i < sectorsRequired; ++i) {
                m_saveFile->writeFile(fileEntry, emptySector.data, SECTOR_BYTES, &written);
                m_sectorAvailabilityMap.push_back(false);
            }
            sizeDelta += SECTOR_BYTES * sectorsRequired;

            write(newSector, compressed.get(), length, compLen);
            setOffset(x, z, (newSector << 8) | sectorsRequired);
        }
    }

    setTimestamp(x, z, static_cast<int>(System::currentTimeMillis() / 1000));
    m_saveFile->ReleaseSaveAccess();
}

// Internal write function for raw sector data
void RegionFile::write(int sectorNumber, byte* data, int length, unsigned int compLength)
{
    DWORD written = 0;
    m_saveFile->setFilePointer(fileEntry, sectorNumber * SECTOR_BYTES, nullptr, FILE_BEGIN);

    compLength |= 0x80000000; // Mark as RLE-compressed
    m_saveFile->writeFile(fileEntry, &compLength, sizeof(compLength), &written);
    compLength &= 0x7FFFFFFF;

    m_saveFile->writeFile(fileEntry, &length, sizeof(length), &written);
    m_saveFile->writeFile(fileEntry, data, compLength, &written);
}

// Zero out a region of the file
void RegionFile::zero(int sectorNumber, int length)
{
    DWORD written = 0;
    m_saveFile->setFilePointer(fileEntry, sectorNumber * SECTOR_BYTES, nullptr, FILE_BEGIN);
    m_saveFile->zeroFile(fileEntry, length, &written);
}

// Check coordinate bounds
bool RegionFile::outOfBounds(int x, int z)
{
    return x < 0 || x >= 32 || z < 0 || z >= 32;
}

// Accessor for chunk offset
int RegionFile::getOffset(int x, int z)
{
    return m_chunkOffsets[x + z * 32];
}

// Check if chunk exists
bool RegionFile::hasChunk(int x, int z)
{
    return getOffset(x, z) != 0;
}

// Insert initial two sectors (offset table + timestamps) if missing
void RegionFile::insertInitialSectors()
{
    m_saveFile->setFilePointer(fileEntry, 0, nullptr, FILE_BEGIN);
    DWORD written = 0;
    byte zeroSector[SECTOR_BYTES] = {};
    m_saveFile->writeFile(fileEntry, zeroSector, SECTOR_BYTES, &written);
    m_saveFile->writeFile(fileEntry, zeroSector, SECTOR_BYTES, &written);
    m_bIsEmpty = false;
}

// Set offset for chunk and ensure sectors exist
void RegionFile::setOffset(int x, int z, int offset)
{
    if (m_bIsEmpty) insertInitialSectors();

    DWORD written = 0;
    m_chunkOffsets[x + z * 32] = offset;
    m_saveFile->setFilePointer(fileEntry, (x + z * 32) * 4, nullptr, FILE_BEGIN);
    m_saveFile->writeFile(fileEntry, &offset, sizeof(offset), &written);
}

// Set timestamp for chunk and ensure sectors exist
void RegionFile::setTimestamp(int x, int z, int value)
{
    if (m_bIsEmpty) insertInitialSectors();

    DWORD written = 0;
    m_timestamps[x + z * 32] = value;
    m_saveFile->setFilePointer(fileEntry, SECTOR_BYTES + (x + z * 32) * 4, nullptr, FILE_BEGIN);
    m_saveFile->writeFile(fileEntry, &value, sizeof(value), &written);
}

// Close file handle
void RegionFile::close()
{
    m_saveFile->closeHandle(fileEntry);
}

