// --- Constants ---
constexpr i64 INF64 = 4e18;
constexpr int INF32 = 2e9;
constexpr i64 MOD   = 1'000'000'007LL;
constexpr i64 MOD9  = 998'244'353LL;
constexpr ld PI     = 3.14159265358979323846;

// --- Random Number Generator ---
mt19937_64 rng(chrono::steady_clock::now().time_since_epoch().count());

// --- Macros ---
#define all(x) (x).begin(), (x).end()
#define rall(x) (x).rbegin(), (x).rend()
#define sz(x) ((int)(x).size())
#define pb push_back
#define eb emplace_back
#define fi first
#define se second
#define v1(v, n) vec<i64> v(n)          
#define take(v) for(auto &x : v) cin >> x  
#define nl '\n'                        
#define YES cout << "YES" << nl       
#define NO cout << "NO" << nl

inline i64 gcd(i64 a, i64 b) { return std::gcd(a, b); }
inline i64 lcm(i64 a, i64 b) { return (a / std::gcd(a, b)) * b; }

// Optimized modular exponentiation
inline i64 modpow(i64 base, i64 exp, i64 mod = MOD) {
    i64 res = 1;
    base %= mod;
    while (exp > 0) {
        if (exp & 1) res = (res * base) % mod;
        base = (base * base) % mod;
        exp >>= 1;
    }
    return res;
}

void solve() {
    i64 n; cin >> n;

    v1(d, n); take(d);

    // Sort divisors to access min and max efficiently
    sort(all(d));

    // Candidate secret number: product of smallest and largest divisor
    i64 candidateX = d.front() * d.back();

    // Collect actual divisors of candidateX (excluding 1 and itself)
    vec<i64> computedDivs;

    // Iterate up to sqrt(candidateX) to find divisor pairs
    for (i64 k = 2; k * k <= candidateX; ++k) {
        if (candidateX % k == 0) {
            computedDivs.pb(k);
            if (k != candidateX / k) {
                computedDivs.pb(candidateX / k);
            }
        }
    }

    // Sort computed divisors for comparison
    sort(all(computedDivs));

    // Check if the input list matches the computed divisors
    if (computedDivs == d) {
        cout << candidateX << nl;
    } else {
        cout << -1 << nl;
    }
}

