    ImGuiStyle& style = ImGui::GetStyle();
    style.ScaleAllSizes(contentScale);
    style.FontScaleDpi = contentScale;
    io.ConfigDpiScaleFonts = true;
    io.ConfigDpiScaleViewports = true;

