                e.window.windowID == SDL_GetWindowID(window))
                running = true; // Keep running but handle close request
        }

        // Skip rendering when window is minimized
        if (SDL_GetWindowFlags(window) & SDL_WINDOW_MINIMIZED)
        {
            SDL_Delay(10);
            continue;
        }

        // Begin new frame for Dear ImGui
        ImGui_ImplSDLGPU3_NewFrame();
        ImGui_ImplSDL3_NewFrame();
        ImGui::NewFrame();

        // Demo window
        if (showDemoWindow)
            ImGui::ShowDemoWindow(&showDemoWindow);

        // Simple custom window
        {
            static float sliderValue = 0.0f;
            static int buttonClickCount = 0;

            ImGui::Begin("Hello, world!");
            ImGui::Text("This is some useful text.");
            ImGui::Checkbox("Demo Window", &showDemoWindow);
            ImGui::Checkbox("Another Window", &showAnotherWindow);
            ImGui::SliderFloat("float", &sliderValue, 0.0f, 1.0f);
            ImGui::ColorEdit3("clear color", (float*)&backgroundColor);

            if (ImGui::Button("Click Me"))
                buttonClickCount++;

            ImGui::SameLine();
            ImGui::Text("counter = %d", buttonClickCount);
            ImGui::Text("Performance: %.3f ms/frame (%.1f FPS)", 
                       1000.0f / io.Framerate, io.Framerate);
            ImGui::End();
        }

        // Additional window
        if (showAnotherWindow)
        {
            ImGui::Begin("Another Window", &showAnotherWindow);
            ImGui::Text("Hello from another window!");

            if (ImGui::Button("Close This Window"))
                showAnotherWindow = false;

            ImGui::End();
        }

        // Render Dear ImGui content
        ImGui::Render();
        ImDrawData* drawData = ImGui::GetDrawData();

        bool isMinimized = (drawData->DisplaySize.x <= 0.0f || drawData->DisplaySize.y <= 0.0f);

        // Acquire GPU resources for rendering
        SDL_GPUCommandBuffer* cmdBuffer = SDL_AcquireGPUCommandBuffer(gpuDevice);
        SDL_GPUTexture* swapchainTexture;

        SDL_WaitAndAcquireGPUSwapchainTexture(cmdBuffer, window, &swapchainTexture, nullptr, nullptr);

        if (swapchainTexture != nullptr && !isMinimized)
        {
            // Prepare draw data for GPU
            ImGui_ImplSDLGPU3_PrepareDrawData(drawData, cmdBuffer);

            // Setup render target
            SDL_GPUColorTargetInfo colorTarget = {};
            colorTarget.texture = swapchainTexture;
            colorTarget.clear_color = SDL_FColor { backgroundColor.x, backgroundColor.y, backgroundColor.z, backgroundColor.w };
            colorTarget.load_op = SDL_GPU_LOADOP_CLEAR;
            colorTarget.store_op = SDL_GPU_STOREOP_STORE;
            colorTarget.mip_level = 0;
            colorTarget.layer_or_depth_plane = 0;
            colorTarget.cycle = false;

            // Execute rendering pass
            SDL_GPURenderPass* renderPass = SDL_BeginGPURenderPass(cmdBuffer, &colorTarget, 1, nullptr);
            ImGui_ImplSDLGPU3_RenderDrawData(drawData, cmdBuffer, renderPass);
            SDL_EndGPURenderPass(renderPass);
        }

        // Handle multi-viewport updates
        if (io.ConfigFlags & ImGuiConfigFlags_ViewportsEnable)
        {
            ImGui::UpdatePlatformWindows();
            ImGui::RenderPlatformWindowsDefault();
        }

        // Submit GPU commands
        SDL_SubmitGPUCommandBuffer(cmdBuffer);
    }

    // Cleanup resources
    SDL_WaitForGPUIdle(gpuDevice);
    ImGui_ImplSDL3_Shutdown();
    ImGui_ImplSDLGPU3_Shutdown();
    ImGui::DestroyContext();

    SDL_ReleaseWindowFromGPUDevice(gpuDevice, window);
    SDL_DestroyGPUDevice(gpuDevice);
    SDL_DestroyWindow(window);
    SDL_Quit();

    return 0;
}

#include <apLib/ap.h>
