namespace ap::memory {

ErrorOr<Stats> stats() noexcept {
    Stats result;

    // Retrieve overall memory status of the system
    MEMORYSTATUSEX sysMemInfo;
    sysMemInfo.dwLength = sizeof(MEMORYSTATUSEX);
    GlobalMemoryStatusEx(&sysMemInfo);

    // Total virtual memory (page file size)
    result.virtualMemoryTotal = sysMemInfo.ullTotalPageFile;

    // Used virtual memory = total - available
    result.virtualMemoryUsed = sysMemInfo.ullTotalPageFile - sysMemInfo.ullAvailPageFile;

    // Process-specific memory info
    PROCESS_MEMORY_COUNTERS_EX procMemInfo;
    GetProcessMemoryInfo(GetCurrentProcess(),
                         reinterpret_cast<PPROCESS_MEMORY_COUNTERS>(&procMemInfo),
                         sizeof(procMemInfo));

    // Virtual memory used by current process (private working set / committed private bytes)
    result.virtualMemoryUsedByProcess = procMemInfo.PrivateUsage;

    // Total physical memory
    result.physicalMemoryTotal = sysMemInfo.ullTotalPhys;

    // Physical memory used by the system
    result.physicalMemoryUsed = sysMemInfo.ullTotalPhys - sysMemInfo.ullAvailPhys;

    // Physical memory currently used by this process (working set)
    result.physicalMemoryUsedByProcess = procMemInfo.WorkingSetSize;

    return result;
}

}  // namespace ap::memory

