#include <cstdio>
#include <vector>
#include <algorithm>
#include <numeric>
#include <cstdlib>
#include <ctime>
using namespace std;

const int MAXN = 43000;
const int MAXS = 2 * MAXN + 5;

int cur_distinct;
bool paired[MAXS];

int query(int x) {
    printf("? %d\n", x);
    fflush(stdout);
    int r;
    scanf("%d", &r);
    cur_distinct = r;
    return r;
}

void answer(int a, int b) {
    printf("! %d %d\n", a, b);
    fflush(stdout);
    paired[a] = paired[b] = true;
}

// Find the partner of 'r' among elements in vector 'L'
int locate_partner(int r, vector<int>& L) {
    int len = L.size();
    vector<bool> active(len, true);
    int left = 0, right = len;

    while (right - left > 1) {
        int mid = (left + right) / 2;

        // Toggle elements from [left, mid) to inactive
        for (int i = left; i < mid; ++i) {
            if (active[i]) {
                query(L[i]);
                active[i] = false;
            }
        }

        // Toggle elements from [mid, right) to active
        for (int i = mid; i < right; ++i) {
            if (!active[i]) {
                query(L[i]);
                active[i] = true;
            }
        }

        int original_count = cur_distinct;
        int after_insert = query(r); // Insert r temporarily

        if (after_insert > original_count) {
            // Partner lies in left half [left, mid)
            query(r); // Remove r

            // Remove remaining elements in [mid, right)
            for (int i = mid; i < right; ++i) {
                if (active[i]) {
                    query(L[i]);
                    active[i] = false;
                }
            }

            right = mid;
        } else {
            // Partner lies in right half [mid, right)
            query(r); // Remove r

            // Keep device as is (still contains [mid, right))
            left = mid;
        }
    }

    int matched = L[left];

    // Cleanup: remove all remaining elements from device
    for (int i = 0; i < len; ++i) {
        if (active[i]) {
            query(L[i]);
        }
    }

    return matched;
}

// Match slices in R with their partners in L
void pair_slices(vector<int> L, vector<int> R) {
    if (R.empty()) {
        for (int x : L) query(x);
        return;
    }

    if (R.size() == 1) {
        int candidate = R[0];
        query(candidate); // Temporarily remove candidate
        int partner = locate_partner(candidate, L);
        answer(candidate, partner);
        return;
    }

    // Divide and conquer approach
    int mid_index = L.size() / 2;
    vector<int> left_L(L.begin(), L.begin() + mid_index);
    vector<int> right_L(L.begin() + mid_index, L.end());

    // Remove right_L from device
    for (int x : right_L) query(x);

    // Classify R elements based on whether removing them changes distinct count
    vector<int> left_R, right_R;
    int current_count = cur_distinct;

    for (int r : R) {
        int new_count = query(r);
        if (new_count < current_count) {
            right_R.push_back(r);
        } else {
            left_R.push_back(r);
        }
        current_count = new_count;
    }

    // Now device contains only left_L
    // Add back left_R
    for (int r : left_R) query(r);
    pair_slices(left_L, left_R);

    // Device should be empty now
    // Add right_L and right_R
    for (int x : right_L) query(x);
    for (int r : right_R) query(r);
    pair_slices(right_L, right_R);
}

// Main solver function assuming device starts empty
void solve_problem(vector<int> items) {
    if (items.size() == 2) {
        answer(items[0], items[1]);
        return;
    }

    int total = items.size();
    int split_point = total / 2;

    vector<int> first_half(items.begin(), items.begin() + split_point);
    vector<int> second_half(items.begin() + split_point, items.end());

    // Query all elements in second_half to remove them from device
    for (int x : second_half) query(x);

    // Now device contains only first_half
    vector<int> match_first, match_second;
    int base_count = cur_distinct;

    // Try each element in second_half and see if it affects count
    for (int item : second_half) {
        int updated = query(item);
        if (updated < base_count) {
            match_second.push_back(item);
        } else {
            match_first.push_back(item);
        }
        base_count = updated;
    }

    // Now device contains only first_half
    // Re-add match_first elements
    for (int x : match_first) query(x);
    pair_slices(first_half, match_first);

    // Device should be empty now
    // Add back second_half and match_second
    for (int x : second_half) query(x);
    for (int x : match_second) query(x);
    pair_slices(second_half, match_second);
}

