  Utf8Helper::gDefault.setCollatorLanguage(
    "", LanguageType::Default, gIcuData.empty() ? nullptr : gIcuData.c_str());
}

// Initialize ICU data if not already initialized
void IcuInitializer::setup(const char* path) {
  // Skip initialization if already done
  if (!gIcuData.empty()) {
    return;
  }

  std::string icu_path;
  std::string exe_path = SdbLocateBinaryPath(path);

  // Prepare ICU data using language features
  gIcuData = LanguageFeature::prepareIcu(TEST_DIRECTORY, exe_path, icu_path, "basics_suite");

  // Apply ICU data if successfully loaded
  if (!gIcuData.empty()) {
    Utf8Helper::gDefault.setCollatorLanguage("", LanguageType::Default,
                                             gIcuData.c_str());
  }
}

