// Helper function to configure frame pass parameters for rendering
void SetupFrameParameters(hvt::FramePass& fp,
                          const TestHelpers::TestStage& stage,
                          const TestHelpers::TestContextPtr& ctx) {
    auto& params = fp.params();
    params.renderBufferSize = GfVec2i(ctx->width(), ctx->height());
    params.viewInfo.framing =
        hvt::ViewParams::GetDefaultFraming(ctx->width(), ctx->height());
    params.viewInfo.viewMatrix = stage.viewMatrix();
    params.viewInfo.projectionMatrix = stage.projectionMatrix();
    params.viewInfo.lights = stage.defaultLights();
    params.viewInfo.material = stage.defaultMaterial();
    params.viewInfo.ambient = stage.defaultAmbient();
    params.colorspace = HdxColorCorrectionTokens->sRGB;
    params.backgroundColor = TestHelpers::ColorDarkGrey;
    params.selectionColor = TestHelpers::ColorYellow;
    params.enablePresentation = ctx->presentationEnabled();
}

// Reusable render loop runner
bool RunRenderLoop(TestHelpers::TestContextPtr& ctx,
                   hvt::FramePass* fp,
                   const TestHelpers::TestStage& stage,
                   int iterations = 10) {
    int remaining = iterations;
    auto renderStep = [&]() -> bool {
        SetupFrameParameters(*fp, stage, ctx);
        fp->Render();
        return --remaining > 0;
    };
    ctx->run(renderStep, fp);
    return remaining <= 0;
}

