// Header mapping
void MappingTraits<Header>::mapping(IO &stream, Header &header) {
  stream.mapRequired("Architecture", header.Architecture);
  stream.mapOptional("Emulation", header.Emulation);
  stream.mapRequired("AddressSize", header.AddressSize);
  stream.mapRequired("ABIPageSize", header.ABIPageSize);
}

// Version mapping
void MappingTraits<Version>::mapping(IO &stream, Version &version) {
  stream.mapRequired("CompilerVersion", version.VendorVersion);
  stream.mapRequired("LinkerVersion", version.ELDVersion);
}

// ArchiveRecord mapping
void MappingTraits<ArchiveRecord>::mapping(IO &stream, ArchiveRecord &record) {
  stream.mapRequired("Origin", record.Origin);
  stream.mapRequired("Referred", record.Referred);
}

// Common symbol mapping
void MappingTraits<Common>::mapping(IO &stream, Common &common) {
  stream.mapRequired("Name", common.Name);
  stream.mapRequired("Size", common.Size);
  stream.mapOptional("InputPath", common.InputPath);
  stream.mapOptional("InputName", common.InputName);
}

// LinkStats mapping
void MappingTraits<LinkStats>::mapping(IO &stream, LinkStats &stats) {
  stream.mapRequired("Name", stats.Name);
  stream.mapRequired("Count", stats.Count);
}

// SymbolType bitset traits
void ScalarBitSetTraits<eld::LDYAML::SymbolType>::bitset(
    IO &stream, eld::LDYAML::SymbolType &symbolType) {
  IO.bitSetCase(symbolType, "STT_OBJECT", llvm::ELF::STT_OBJECT);
  IO.bitSetCase(symbolType, "STT_FUNC", llvm::ELF::STT_FUNC);
  IO.bitSetCase(symbolType, "STT_SECT", llvm::ELF::STT_SECTION);
  IO.bitSetCase(symbolType, "STT_FILE", llvm::ELF::STT_FILE);
  IO.bitSetCase(symbolType, "STT_COMMON", llvm::ELF::STT_COMMON);
  IO.bitSetCase(symbolType, "STT_TLS", llvm::ELF::STT_TLS);
  IO.bitSetCase(symbolType, "STT_GNU_IFUNC", llvm::ELF::STT_GNU_IFUNC);
}

// SymbolScope enumeration traits
void ScalarEnumerationTraits<eld::LDYAML::SymbolScope>::enumeration(
    IO &stream, eld::LDYAML::SymbolScope &scope) {
  IO.enumCase(scope, "Global", eld::ResolveInfo::Global);
  IO.enumCase(scope, "Weak", eld::ResolveInfo::Weak);
  IO.enumCase(scope, "Local", eld::ResolveInfo::Local);
  IO.enumCase(scope, "Absolute", eld::ResolveInfo::Absolute);
  IO.enumCase(scope, "None", eld::ResolveInfo::NoneBinding);
}

// Symbol mapping
void MappingTraits<eld::LDYAML::Symbol>::mapping(
    IO &stream, eld::LDYAML::Symbol &symbol) {
  stream.mapRequired("Symbol", symbol.Name);
  stream.mapRequired("Type", symbol.Type);
  stream.mapRequired("Scope", symbol.Scope);
  stream.mapRequired("Size", symbol.Size);
  stream.mapOptional("Value", symbol.Value);
}

// SimpleSymbol mapping
void MappingTraits<eld::LDYAML::SimpleSymbol>::mapping(
    IO &stream, eld::LDYAML::SimpleSymbol &symbol) {
  stream.mapRequired("Symbol", symbol.Name);
  stream.mapRequired("Type", symbol.Type);
  stream.mapRequired("Size", symbol.Size);
}

