void TransConstraint::Enter() {
    RndPollable::Enter();
    SnapToParent();
}

void TransConstraint::SetScaleVectorOnTransform(RndTransformable *trans, Vector3 &scaleVec) {
    MILO_ASSERT(trans, 0x80);
    Vector3 eulerAngles;
    Hmx::Matrix3 rotationMatrix;
    Transform worldXfm = trans->WorldXfm();
    MakeEuler(worldXfm.m, eulerAngles);
    MakeRotMatrix(eulerAngles, rotationMatrix, true);
    Scale(rotationMatrix, scaleVec, rotationMatrix);
    worldXfm.m = rotationMatrix;
    trans->SetWorldXfm(worldXfm);
}

void TransConstraint::SnapToParent() {
    if (!mParent || !mChild) return;

    Vector3 parentPos = mParent->WorldXfm().v;
    Vector3 childPos = mChild->WorldXfm().v;

    // Copy tracked components from parent to child position
    for (int axis = 0; axis < 3; ++axis) {
        if (mTracks[axis]) {
            childPos[axis] = parentPos[axis];
        }
    }
    mChild->SetWorldPos(childPos);

    if (mAffectScale) {
        Vector3 parentScale;
        Vector3 childScale;
        MakeScale(mParent->WorldXfm().m, parentScale);
        MakeScale(mChild->WorldXfm().m, childScale);

        for (int axis = 0; axis < 3; ++axis) {
            if (mTracks[axis]) {
                childScale[axis] = parentScale[axis];
            }
        }

        SetScaleVectorOnTransform(mChild, childScale);
    }
}

#include <iostream>
#include <vector>
#include <string>
#include <set>
#include <algorithm>

// Alternative implementation using different approach to collect words
void solve() {
    int n;
    std::cin >> n;

    std::set<std::string> collected;
    char current_char = 'a';

    // Process each starting character until we have enough words
    while (collected.size() < n && current_char <= 'z') {
        std::string base(1, current_char);
        int requested = 1;

        // Continue querying for more words with this prefix until satisfied
        while (true) {
            if (collected.size() >= n) break;

            std::cout << "query " << base << " " << requested << std::endl;
            int response_count;
            std::cin >> response_count;

            // Read the returned words
            for (int idx = 0; idx < response_count; ++idx) {
                std::string temp_word;
                std::cin >> temp_word;
                collected.insert(temp_word);
            }

            // If we got fewer words than requested, no more exist for this prefix
            if (response_count < requested) {
                break;
            }

            // If we've reached our target count, stop
            if (requested == n) {
                break;
            }

            // Increase query size for next iteration
            requested *= 2;
            if (requested > n) {
                requested = n;
            }
        }

        // Move to next character
        ++current_char;
    }

    // Output results
    std::cout << "answer";
    for (const std::string& w : collected) {
        std::cout << " " << w;
    }
    std::cout << std::endl;
}

int main() {
    // Optimize I/O operations
    std::ios::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int test_cases;
    std::cin >> test_cases;

    while (test_cases-- > 0) {
        solve();
    }

    return 0;
}

