int main() {
    int choice;
    int firstNum, secondNum, result;

    do {
        printf("Choose any option:\n");
        printf("1. Addition of two numbers\n");
        printf("2. Difference between two numbers\n");
        printf("3. Multiplication of two numbers\n");
        printf("4. Square of a number\n");
        printf("5. Cube of a number\n");
        printf("Enter your choice: ");
        scanf("%d", &choice);

        switch (choice) {
            case 1:
                printf("Enter two numbers: ");
                scanf("%d %d", &firstNum, &secondNum);
                result = firstNum + secondNum;
                printf("Sum of two numbers = %d\n", result);
                break;

            case 2:
                printf("Enter two numbers: ");
                scanf("%d %d", &firstNum, &secondNum);
                result = firstNum - secondNum;
                printf("Difference of two numbers = %d\n", result);
                break;

            case 3:
                printf("Enter two numbers: ");
                scanf("%d %d", &firstNum, &secondNum);
                result = firstNum * secondNum;
                printf("Product of two numbers = %d\n", result);
                break;

            case 4:
                printf("Enter a number: ");
                scanf("%d", &firstNum);
                result = firstNum * firstNum;
                printf("Square of the number = %d\n", result);
                break;

            case 5:
                printf("Enter a number: ");
                scanf("%d", &firstNum);
                result = firstNum * firstNum * firstNum;
                printf("Cube of the number = %d\n", result);
                break;

            default:
                printf("Invalid choice! Please try again.\n");
                continue; // Skip rest and prompt again
        }

        printf("\nDo you want to continue? (y/n): ");
        char ch;
        scanf(" %c", &ch); // space before %c skips whitespace
    } while (tolower(ch) == 'y');

    printf("Thank you!\n");
    return 0;
}

