#include <bits/stdc++.h>
using namespace std;
using lint = long long;

// Helper function to send query and parse response
vector<lint> ask(int numProbes, const vector<pair<lint, lint>>& coords) {
    cout << "? " << numProbes;
    for (const auto& [sx, ty] : coords) {
        cout << " " << sx << " " << ty;
    }
    cout << endl;
    cout.flush();

    string inputLine;
    if (cin.peek() == '\n') cin.ignore();
    getline(cin, inputLine);
    istringstream iss(inputLine);

    vector<lint> answers;
    lint temp;
    while (iss >> temp) {
        answers.push_back(temp);
    }
    return answers;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    lint boardSize, pointCount, waveCount;
    cin >> boardSize >> pointCount >> waveCount;

    // Strategy for sufficient number of waves: four-corner method
    if (waveCount >= 4) {
        lint boundary = boardSize + 1;
        vector<lint> cornerA, cornerB, cornerC, cornerD;

        // First wave: probe top-right corner
        cornerA = ask(1, {{boundary, boundary}});
        // Second wave: probe bottom-right corner
        cornerB = ask(1, {{boundary, -boundary}});
        // Third wave: probe top-left corner
        cornerC = ask(1, {{-boundary, boundary}});
        // Fourth wave: probe bottom-left corner
        cornerD = ask(1, {{-boundary, -boundary}});

        // Compute s_i and t_i from corner responses
        vector<lint> sVals(pointCount), tVals(pointCount);
        for (lint idx = 0; idx < pointCount; ++idx) {
            sVals[idx] = 2 * boundary - cornerA[idx];
            tVals[idx] = 2 * boundary - cornerB[idx];
        }

        // Build adjacency list for bipartite matching
        vector<vector<int>> graph(pointCount);
        for (int i = 0; i < pointCount; ++i) {
            for (int j = 0; j < pointCount; ++j) {
                lint s = sVals[i], t = tVals[j];
                lint sumST = s + t;
                lint diffST = s - t;

                if (sumST % 2 != 0 || diffST % 2 != 0) continue;

                lint x = sumST / 2;
                lint y = diffST / 2;

                if (abs(x) <= boardSize && abs(y) <= boardSize) {
                    graph[i].push_back(j);
                }
            }
        }

        // Kuhn-Munkres (Hungarian-style DFS-based bipartite matching)
        vector<int> assignment(pointCount, -1);
        vector<bool> visited(pointCount);

        function<bool(int)> augment = [&](int u) -> bool {
            for (int v : graph[u]) {
                if (!visited[v]) {
                    visited[v] = true;
                    if (assignment[v] == -1 || augment(assignment[v])) {
                        assignment[v] = u;
                        return true;
                    }
                }
            }
            return false;
        };

        for (int start = 0; start < pointCount; ++start) {
            fill(visited.begin(), visited.end(), false);
            augment(start);
        }

        // Validate perfect matching
        int matchedCount = count_if(assignment.begin(), assignment.end(),
                                    [](int x) { return x != -1; });
        if (matchedCount != pointCount) {
            cout << "!";
            for (int i = 0; i < pointCount; ++i) cout << " 0 0";
            cout << "\n";
            return 0;
        }

        // Reconstruct coordinates using matched pairs
        vector<pair<lint, lint>> points(pointCount);
        for (int j = 0; j < pointCount; ++j) {
            int i = assignment[j];
            lint s = sVals[i], t = tVals[j];
            lint x = (s + t) / 2;
            lint y = (s - t) / 2;
            points[i] = {x, y};
        }

        // Output final answer
        cout << "!";
        for (const auto& pt : points) {
            cout << " " << pt.first << " " << pt.second;
        }
        cout << "\n";

    } else {
        // Fallback for fewer waves: two-wave heuristic with pairing
        lint boundary = boardSize + 1;

        // First wave: two probes — top-right and bottom-left
        auto res1 = ask(2, {{boundary, boundary}, {-boundary, -boundary}});
        // Second wave: two probes — bottom-right and top-left
        auto res2 = ask(2, {{boundary, -boundary}, {-boundary, boundary}});

        sort(res1.begin(), res1.end());
        sort(res2.begin(), res2.end());

        vector<lint> sCandidates, tCandidates;

        // Pair smallest with largest in first set
        for (int i = 0; i < pointCount; ++i) {
            lint dSmall = res1[i];
            lint dLarge = res1[2 * pointCount - 1 - i];

            if (dSmall + dLarge != 4 * boundary) {
                cout << "!";
                for (int j = 0; j < pointCount; ++j) cout << " 0 0";
                cout << "\n";
                return 0;
            }
            sCandidates.push_back(2 * boundary - dSmall);
        }

        // Same pairing strategy for second set
        for (int i = 0; i < pointCount; ++i) {
            lint dSmall = res2[i];
            lint dLarge = res2[2 * pointCount - 1 - i];

            if (dSmall + dLarge != 4 * boundary) {
                cout << "!";
                for (int j = 0; j < pointCount; ++j) cout << " 0 0";
                cout << "\n";
                return 0;
            }
            tCandidates.push_back(2 * boundary - dSmall);
        }

        // Heuristic: assume sorted order corresponds to correct pairing
        sort(sCandidates.begin(), sCandidates.end());
        sort(tCandidates.begin(), tCandidates.end());

        vector<pair<lint, lint>> recoveredPoints(pointCount);
        for (int i = 0; i < pointCount; ++i) {
            lint s = sCandidates[i];
            lint t = tCandidates[i];
            lint x = (s + t) / 2;
            lint y = (s - t) / 2;
            recoveredPoints[i] = {x, y};
        }

        cout << "!";
        for (const auto& pt : recoveredPoints) {
            cout << " " << pt.first << " " << pt.second;
        }
        cout << "\n";
    }

    return 0;
}

#include <iostream>
#include <vector>
#include <algorithm>
#include <utility>

const int MAXN = 1001;
std::vector<int> graph[MAXN];
int vertex_color[MAXN];

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int n, edges;
    std::cin >> n >> edges;

    for (int i = 0; i < edges; ++i) {
        int a, b;
        std::cin >> a >> b;
        graph[a].emplace_back(b);
        graph[b].emplace_back(a);
    }

    // --- Initial coloring: process vertices by descending degree ---
    std::vector<std::pair<int, int>> sorted_vertices;
    for (int i = 1; i <= n; ++i) {
        sorted_vertices.emplace_back(-static_cast<int>(graph[i].size()), i);
    }
    std::sort(sorted_vertices.begin(), sorted_vertices.end());

    // Reset color array to zero (uncolored)
    for (const auto& [neg_degree, node] : sorted_vertices) {
        int neighbor_colors[4] = {0}; // Track usage of colors 1, 2, 3

        for (int neighbor : graph[node]) {
            if (vertex_color[neighbor] != 0) {
                neighbor_colors[vertex_color[neighbor]]++;
            }
        }

        // Choose the least conflicting color among 1, 2, 3
        int chosen_color = 1;
        for (int c = 2; c <= 3; ++c) {
            if (neighbor_colors[c] < neighbor_colors[chosen_color]) {
                chosen_color = c;
            }
        }
        vertex_color[node] = chosen_color;
    }

    // --- Local optimization phase ---
    const int max_passes = 100;
    for (int pass = 0; pass < max_passes; ++pass) {
        bool improved = false;

        for (int node = 1; node <= n; ++node) {
            int conflict_counts[4] = {0};
            for (int neighbor : graph[node]) {
                conflict_counts[vertex_color[neighbor]]++;
            }

            int current = vertex_color[node];
            int optimal = current;

            // Find better color assignment with fewer conflicts
            for (int c = 1; c <= 3; ++c) {
                if (conflict_counts[c] < conflict_counts[optimal]) {
                    optimal = c;
                }
            }

            if (optimal != current) {
                vertex_color[node] = optimal;
                improved = true;
            }
        }

        if (!improved) break;
    }

    // --- Final output ---
    for (int i = 1; i <= n; ++i) {
        std::cout << vertex_color[i];
        if (i < n) std::cout << ' ';
    }
    std::cout << '\n';

    return 0;
}

