namespace internal_trace {
    void log_debug(const char* format, ...) {
        char buffer[1024];
        va_list args;
        va_start(args, format);
        vsnprintf(buffer, sizeof(buffer), format, args);
        OutputDebugStringA(buffer);
        va_end(args);
    }

    std::string extract_filename(const std::string& path) {
        size_t pos = path.find_last_of("/\\");
        return (pos == std::string::npos) ? path : path.substr(pos + 1);
    }

    struct CallFrame {
        DWORD64 pc_address;
        std::string func_name;
        std::string mod_name;
        unsigned int line_number;
        std::string source_file;
    };

    inline std::vector<CallFrame> capture_stack() {
        HANDLE process_handle = GetCurrentProcess();
        HANDLE thread_handle = GetCurrentThread();

        if (!SymInitialize(process_handle, nullptr, TRUE)) {
            log_debug("SymInitialize failed.\n");
            return {};
        }

        SymSetOptions(SYMOPT_LOAD_LINES);

        CONTEXT ctx = {};
        ctx.ContextFlags = CONTEXT_FULL;
        RtlCaptureContext(&ctx);

        STACKFRAME frame = {};
#if defined(_WIN64)
        DWORD machine_type = IMAGE_FILE_MACHINE_AMD64;
        frame.AddrPC.Offset = ctx.Rip;
        frame.AddrFrame.Offset = ctx.Rbp;
        frame.AddrStack.Offset = ctx.Rsp;
#else
        DWORD machine_type = IMAGE_FILE_MACHINE_I386;
        frame.AddrPC.Offset = ctx.Eip;
        frame.AddrFrame.Offset = ctx.Ebp;
        frame.AddrStack.Offset = ctx.Esp;
#endif
        frame.AddrPC.Mode = AddrModeFlat;
        frame.AddrFrame.Mode = AddrModeFlat;
        frame.AddrStack.Mode = AddrModeFlat;

        bool first_entry = true;
        std::vector<CallFrame> frames;

        while (StackWalk(machine_type, process_handle, thread_handle,
                         &frame, &ctx, nullptr,
                         SymFunctionTableAccess, SymGetModuleBase, nullptr)) {
            CallFrame cf{};
            cf.pc_address = frame.AddrPC.Offset;

            DWORD64 base_addr = SymGetModuleBase(process_handle, frame.AddrPC.Offset);
            char module_path[MAX_PATH] = {};
            if (base_addr && GetModuleFileNameA((HMODULE)base_addr, module_path, MAX_PATH)) {
                cf.mod_name = extract_filename(module_path);
            } else {
                cf.mod_name = "Unknown Module";
            }

            char symbol_buffer[sizeof(IMAGEHLP_SYMBOL) + 256] = {};
            PIMAGEHLP_SYMBOL sym = reinterpret_cast<PIMAGEHLP_SYMBOL>(symbol_buffer);
            sym->SizeOfStruct = sizeof(IMAGEHLP_SYMBOL) + 256;
            sym->MaxNameLength = 255;

            DWORD64 displacement = 0;
            if (SymGetSymFromAddr(process_handle, frame.AddrPC.Offset, &displacement, sym)) {
                cf.func_name = sym->Name;
            } else {
                DWORD err = GetLastError();
                log_debug("Symbol resolution failed at 0x%llx: %lu\n", frame.AddrPC.Offset, err);
                cf.func_name = "Unknown Function";
            }

            IMAGEHLP_LINE line_info = {};
            line_info.SizeOfStruct = sizeof(IMAGEHLP_LINE);
            DWORD line_disp = 0;
            if (SymGetLineFromAddr(process_handle, frame.AddrPC.Offset, &line_disp, &line_info)) {
                cf.source_file = line_info.FileName;
                cf.line_number = line_info.LineNumber;
            } else {
                DWORD err = GetLastError();
                log_debug("Line info lookup failed for 0x%llx: %lu\n", frame.AddrPC.Offset, err);
                cf.line_number = 0;
            }

            if (!first_entry) {
                frames.push_back(cf);
            }
            first_entry = false;
        }

        SymCleanup(process_handle);
        return frames;
    }
} // namespace internal_trace
