namespace quadrants {

void print_traceback() {
#ifdef __APPLE__
    static std::mutex trace_mutex;
    void* stack_entries[128] = {};
    int count = backtrace(stack_entries, 128);
    char** symbols = backtrace_symbols(stack_entries, count);

    std::vector<std::string> formatted_frames;
    for (int idx = 0; idx < count; ++idx) {
        char func_name[1024] = {};
        char module[1024] = {};
        char addr_str[48] = {};
        int offset_val = 0;

        sscanf(symbols[idx], "%*s %s %s %s %*s %d",
               module, addr_str, func_name, &offset_val);

        int demangle_status = -1;
        char* demangled = abi::__cxa_demangle(func_name, nullptr, nullptr, &demangle_status);
        char frame_buf[4096] = {};
        snprintf(frame_buf, sizeof(frame_buf),
                 "* %28s | %7d | %s", module, offset_val, demangled ? demangled : func_name);
        if (demangled) free(demangled);

        formatted_frames.emplace_back(frame_buf);
    }
    free(symbols);

    formatted_frames.erase(formatted_frames.begin());
    std::reverse(formatted_frames.begin(), formatted_frames.end());

    std::lock_guard<std::mutex> lock(trace_mutex);

    printf("\n");
    printf(
        "                            * Quadrants Core - Stack Traceback *                        \n");
    printf(
        "==========================================================================================\n");
    printf(
        "|                       Module |  Offset | Function                                 |\n");
    printf(
        "|----------------------------------------------------------------------------------------|\n");

    std::reverse(formatted_frames.begin(), formatted_frames.end());
    for (const auto& entry : formatted_frames) {
        const size_t col_offset = 39;
        const size_t total_width = 86;
        const size_t func_col_width = total_width - col_offset - 2;

        size_t i = 0;
        for (; i < entry.size(); ++i) {
            putchar(entry[i]);
            if (i > col_offset + 3 && ((i - 3 - col_offset) % func_col_width == 0)) {
                printf(" |\n ");
                for (size_t k = 0; k < col_offset; ++k) putchar(' ');
                printf(" | ");
            }
        }
        size_t padding = func_col_width + 2 - ((i - 3 - col_offset) % func_col_width);
        for (size_t p = 0; p < padding; ++p) putchar(' ');
        printf("|\n");
    }
    printf(
        "==========================================================================================\n");
    printf("\n");

#elif defined(_WIN64)
    fmt::print(fg(fmt::color::magenta), "***********************************\n");
    fmt::print(fg(fmt::color::magenta), "* Quadrants Compiler Stack Traceback *\n");
    fmt::print(fg(fmt::color::magenta), "***********************************\n");

    auto frames = internal_trace::capture_stack();
    for (const auto& frame : frames) {
        fmt::print(fg(fmt::color::magenta), fmt::format("0x{:x}: ", frame.pc_address));
        fmt::print(fg(fmt::color::red), frame.func_name);
        if (!frame.source_file.empty()) {
            fmt::print(fg(fmt::color::magenta),
                       fmt::format("(line {} in {})", frame.line_number, frame.source_file));
        }
        fmt::print(fg(fmt::color::magenta), fmt::format(" in {}\n", frame.mod_name));
    }

#else
    constexpr int MAX_FRAMES = 1024;
    void* buffer[MAX_FRAMES];
    int num_frames = backtrace(buffer, MAX_FRAMES);
    char** str_list = backtrace_symbols(buffer, num_frames);
    if (!str_list) {
        perror("backtrace_symbols");
        std::exit(EXIT_FAILURE);
    }

    fmt::print(fg(fmt::color::magenta), "***********************************\n");
    fmt::print(fg(fmt::color::magenta), "* Quadrants Compiler Stack Traceback *\n");
    fmt::print(fg(fmt::color::magenta), "***********************************\n");

    for (int i = 1; i < num_frames; ++i) {
        std::string raw_line(str_list[i]);
        size_t paren_pos = raw_line.find('(');
        size_t plus_pos = raw_line.rfind('+');
        std::string result_line;

        if (paren_pos != std::string::npos &&
            plus_pos != std::string::npos &&
            paren_pos < plus_pos &&
            raw_line[paren_pos + 1] != '+') {
            std::string mangled = raw_line.substr(paren_pos + 1, plus_pos - paren_pos - 1);
            int status = -1;
            char* demangled = abi::__cxa_demangle(mangled.c_str(), nullptr, nullptr, &status);
            if (demangled) {
                result_line = raw_line.substr(0, paren_pos + 1) + demangled + raw_line.substr(plus_pos);
                free(demangled);
            } else {
                result_line = raw_line;
            }
        } else {
            result_line = raw_line;
        }

        fmt::print(fg(fmt::color::magenta), "{}\n", result_line);
    }
    std::free(str_list);
#endif

    fmt::print(
        fg(fmt::color::orange),
        "\nInternal error occurred. Check out this page for possible solutions:\n"
        "https://docs.taichi-lang.org/docs/install\n");
}

