#include <iostream>

struct B {
    int value;

    void modify() {
        value++;
        // This function can call any other member, const or not
        helper();
        inspect();
    }

    void inspect() const {
        // Since this is a const member function, we cannot modify 'value'
        // value++; // Error: cannot modify member of const object
        // modify(); // Error: non-const function cannot be called from const context
        helper();   // OK: helper() is const
    }

    void helper() const {
        // Also const - only allowed to call other const functions
        // value++; // Error: cannot modify in const function
        // modify(); // Error: cannot call non-const function
        inspect();  // OK: inspect() is also const
    }
};

// Function taking a non-const reference can call all member functions
void processNonConst(B& obj) {
    obj.modify();
    obj.inspect();
    obj.helper();
}

// Function taking a const reference can only call const member functions
void processConst(const B& obj) {
    // obj.modify(); // Error: modify() is non-const
    obj.inspect();  // OK: inspect() is const
    obj.helper();   // OK: helper() is const
}

#include "testLoopshapingConfigurations.h"

namespace ocs2 {

LoopshapingTestConfiguration::LoopshapingTestConfiguration(const std::string& configName) {
  // Load loopshaping definition from configuration file
  const std::string fullPath = resolveConfigurationPath(configName);
  loopshapingDefinition_ = loopshaping_property_tree::load(fullPath);

  // Determine dimensions
  systemStateDim_ = 1;  // Arbitrary value for system state size (used only to differentiate augmented state)
  filterStateDim_ = extractFilterStateDimension(*loopshapingDefinition_);
  inputDim_ = extractInputDimension(*loopshapingDefinition_);

  // Initialize time and perturbation magnitude
  t = 0.5;
  const scalar_t perturbationScale = 1e-2;

  // Generate random nominal and disturbed inputs/states
  generateRandomStateAndInputs(systemStateDim_, filterStateDim_, inputDim_,
                               x_sys_, u_sys_, x_filter_, u_filter_, x_, u_);
  generateRandomStateAndInputs(systemStateDim_, filterStateDim_, inputDim_,
                               x_sys_disturbance_, u_sys_disturbance_,
                               x_filter_disturbance_, u_filter_disturbance_,
                               x_disturbance_, u_disturbance_, perturbationScale);

  // Initialize pre-computation objects
  auto basePreComp = std::make_unique<PreComputation>();
  preComp_sys_ = std::move(basePreComp);
  preComp_ = std::make_unique<LoopshapingPreComputation>(*preComp_sys_, loopshapingDefinition_);
}

// Helper: extract input filter state dimension via accessor wrapper
size_t LoopshapingTestConfiguration::extractFilterStateDimension(const LoopshapingDefinition& def) {
  return def.getInputFilter().getNumStates();
}

// Helper: extract input dimension via accessor wrapper
size_t LoopshapingTestConfiguration::extractInputDimension(const LoopshapingDefinition& def) {
  return def.getInputFilter().getNumInputs();
}

// Helper: resolve absolute path to config file
std::string LoopshapingTestConfiguration::resolveConfigurationPath(const std::string& name) {
  return getAbsolutePathToConfigurationFile(name);
}

// Helper: populate system/filter states and inputs from augmented state/input
void LoopshapingTestConfiguration::generateRandomStateAndInputs(
    size_t sysDim, size_t filtDim, size_t inpDim,
    vector_t& xSys, vector_t& uSys,
    vector_t& xFilt, vector_t& uFilt,
    vector_t& xAug, vector_t& uAug,
    scalar_t scale) {
  // Randomize full augmented state and input
  xAug.resize(sysDim + filtDim);
  uAug.resize(inpDim);
  xAug.setRandom();
  uAug.setRandom();

  // Scale randomness
  xAug *= scale;
  uAug *= scale;

  // Decompose into system and filter components
  xSys = loopshapingDefinition_->getSystemState(xAug);
  uSys = loopshapingDefinition_->getSystemInput(xAug, uAug);
  xFilt = loopshapingDefinition_->getFilterState(xAug);
  uFilt = loopshapingDefinition_->getFilteredInput(xAug, uAug);
}

