  // PEM key only
  cert.setCertPem("");
  cert.setKeyPem("-----BEGIN PRIVATE KEY-----\nFAKE\n-----END PRIVATE KEY-----\n");
  EXPECT_FALSE(cert.hasFiles());
  EXPECT_TRUE(cert.hasPem());

  // Both PEMs
  cert.setCertPem("-----BEGIN CERTIFICATE-----\nFAKE\n-----END CERTIFICATE-----\n");
