#include <iostream>
#include <vector>
#include <string>
using namespace std;

int N, R;
vector<pair<int, int>> tree; // renamed from 'adj'
vector<int> ancestor;         // renamed from 'parent'

// Global state for constructing query strings during forced evaluation
string query_buffer;

// Recursively assign values to specific nodes in the circuit representation
void assign_value(int node_idx, int val) {
    if (node_idx >= N) {
        query_buffer[node_idx] = static_cast<char>('0' + val);
        return;
    }

    // Force both children to zero to isolate gate behavior
    assign_value(tree[node_idx].first, 0);
    assign_value(tree[node_idx].second, 0);

    // With both inputs zero, output = s[node_idx], so set s[node_idx] = desired output
    query_buffer[node_idx] = static_cast<char>('0' + val);
}

// Send a query and read the response
int send_query(const string& s) {
    cout << "? " << s << endl;
    int result;
    cin >> result;
    return result;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> N >> R;
    tree.resize(N);
    ancestor.assign(2 * N + 1, -1);

    for (int idx = 0; idx < N; ++idx) {
        cin >> tree[idx].first >> tree[idx].second;
        ancestor[tree[idx].first] = idx;
        ancestor[tree[idx].second] = idx;
    }

    string solution(N, ' ');

    // For each internal node i, determine whether it's an AND or OR gate
    for (int i = 0; i < N; ++i) {
        vector<int> sibling_nodes;
        int current = i;

        // Trace path upward to collect siblings along the way
        while (ancestor[current] != -1) {
            int parent = ancestor[current];
            if (tree[parent].first == current) {
                sibling_nodes.push_back(tree[parent].second);
            } else {
                sibling_nodes.push_back(tree[parent].first);
            }
            current = parent;
        }

        // --- Phase 1: Siblings fixed at 0 ---
        query_buffer.assign(2 * N + 1, '0');
        assign_value(tree[i].first, 0);
        assign_value(tree[i].second, 1);
        for (int sib : sibling_nodes) {
            assign_value(sib, 0);
        }
        int res_A = send_query(query_buffer);

        query_buffer.assign(2 * N + 1, '0');
        assign_value(tree[i].first, 0);
        assign_value(tree[i].second, 0);
        for (int sib : sibling_nodes) {
            assign_value(sib, 0);
        }
        int res_B = send_query(query_buffer);
        bool sensitive_when_sibs_zero = (res_A != res_B);

        // --- Phase 2: Siblings fixed at 1 ---
        query_buffer.assign(2 * N + 1, '0');
        assign_value(tree[i].first, 0);
        assign_value(tree[i].second, 1);
        for (int sib : sibling_nodes) {
            assign_value(sib, 1);
        }
        int res_C = send_query(query_buffer);

        query_buffer.assign(2 * N + 1, '0');
        assign_value(tree[i].first, 0);
        assign_value(tree[i].second, 0);
        for (int sib : sibling_nodes) {
            assign_value(sib, 1);
        }
        int res_D = send_query(query_buffer);
        bool sensitive_when_sibs_one = (res_C != res_D);

        // If either scenario shows sensitivity to input change, gate is OR
        if (sensitive_when_sibs_zero || sensitive_when_sibs_one) {
            solution[i] = '|';
        } else {
            solution[i] = '&';
        }
    }

    cout << "! " << solution << endl;
    return 0;
}

#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

// Structure to represent an operation: moving box 'v' to stack 'i'
struct Operation {
    int box_value;
    int destination_stack;
};

int main() {
    // Speed up I/O operations
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    if (!(cin >> n >> m)) return 0;

    // Create stacks (1-indexed; index 0 unused)
    vector<vector<int>> stacks(m + 1);

    // Initialize stacks with given configuration
    for (int i = 1; i <= m; ++i) {
        for (int j = 0; j < n / m; ++j) {
            int box;
            cin >> box;
            stacks[i].push_back(box);
        }
    }

    vector<Operation> operations;
    int next_target = 1;

    // Process all boxes in order from 1 to n
    while (next_target <= n) {
        int src_stack = -1;
        int box_position = -1;

        // Find the current target box in the stacks
        for (int s = 1; s <= m; ++s) {
            for (int pos = 0; pos < (int)stacks[s].size(); ++pos) {
                if (stacks[s][pos] == next_target) {
                    src_stack = s;
                    box_position = pos;
                    break;
                }
            }
            if (src_stack != -1) break;
        }

        // If the box is at the top of its stack, remove it directly
        if (box_position == (int)stacks[src_stack].size() - 1) {
            operations.push_back({next_target, 0});
            stacks[src_stack].pop_back();
            next_target++;
            continue;
        }

        // Otherwise, determine how many boxes above the target need to be moved
        int count_above = (int)stacks[src_stack].size() - 1 - box_position;

        int best_chunk_size = -1;
        int best_dest_stack = -1;
        long long highest_score = -2e18;

        // Evaluate possible chunk sizes and destinations
        for (int chunk = 1; chunk <= count_above; ++chunk) {
            int start_index = (int)stacks[src_stack].size() - chunk;

            // Find maximum value in this chunk
            int max_in_chunk = -1;
            for (int k = 0; k < chunk; ++k) {
                max_in_chunk = max(max_in_chunk, stacks[src_stack][start_index + k]);
            }

            // Try each possible destination stack
            for (int dest = 1; dest <= m; ++dest) {
                if (dest == src_stack) continue;

                int top_of_dest = stacks[dest].empty() ? 1000 : stacks[dest].back();

                long long evaluation;

                if (max_in_chunk < top_of_dest) {
                    // Valid placement: maintain decreasing order from bottom to top
                    evaluation = 200000LL + (long long)chunk * 1000 - (top_of_dest - max_in_chunk);
                } else {
                    // Invalid placement: place larger on smaller (not ideal but sometimes necessary)
                    evaluation = (long long)top_of_dest * 1000 + chunk;
                }

                if (evaluation > highest_score) {
                    highest_score = evaluation;
                    best_chunk_size = chunk;
                    best_dest_stack = dest;
                }
            }
        }

        // Execute the best move found
        int move_start = (int)stacks[src_stack].size() - best_chunk_size;
        int first_box_moved = stacks[src_stack][move_start];

        operations.push_back({first_box_moved, best_dest_stack});

        // Transfer the chunk to the destination stack
        vector<int> temp;
        temp.reserve(best_chunk_size);
        for (int k = 0; k < best_chunk_size; ++k) {
            temp.push_back(stacks[src_stack][move_start + k]);
        }

        // Remove moved boxes from source stack
        stacks[src_stack].resize(move_start);

        // Add boxes to destination stack
        for (int b : temp) {
            stacks[best_dest_stack].push_back(b);
        }
    }

    // Output all recorded operations
    for (const auto& op : operations) {
        cout << op.box_value << " " << op.destination_stack << "\n";
    }

    return 0;
}

#include "ucln_imp.h"

// Replaced macro with inline constant for clarity (equivalent to UCLN_TYPE_IS_COMMON)
#define UCLN_TYPE_IS_COMMON 1

namespace {

// Renamed arrays and added const-correctness where appropriate
static cleanupFunc* gCommonCleanupTable[UCLN_COMMON_COUNT] = {};
static cleanupFunc* gLibraryCleanupTable[UCLN_COMMON] = {};

} // anonymous namespace

/************************************************
 The cleanup sequence must follow a strict order.
 Ensure compliance with ucln.h specifications.
 ************************************************/
U_CAPI void U_EXPORT2
u_cleanup() {
    UTRACE_ENTRY_OC(UTRACE_U_CLEANUP);

    // Memory barrier via mutex lock/unlock pair — same semantics as original
    icu::umtx_lock(nullptr);
    icu::umtx_unlock(nullptr);

    // Perform library-level cleanup first
    ucln_lib_shutdown();

    // Then memory subsystem cleanup
    cmemory_cleanup();  // Undo any custom memory functions previously set

    // Tracing cleanup must occur last before returning
    UTRACE_EXIT();
}

// Refactored per-type cleanup function using early-exit pattern
U_CAPI void U_EXPORT2 ucln_cleanupOne(ECleanupLibraryType libId) {
    if (libId >= UCLN_START && libId < UCLN_COMMON) {
        auto& funcPtr = gLibraryCleanupTable[libId];
        if (funcPtr) {
            funcPtr();
            funcPtr = nullptr;
        }
    }
}

// Internal helper: register common cleanup handlers with thread-safety workaround
U_CFUNC void
ucln_common_registerCleanup(ECleanupCommonType phase,
                            cleanupFunc *handler) {
    U_ASSERT(phase > UCLN_COMMON_START && phase < UCLN_COMMON_COUNT);

    // Special handling for mutex type avoids recursive mutex init issue (see ticket 10295)
    if (phase == UCLN_COMMON_MUTEX) {
        gCommonCleanupTable[phase] = handler;
    } else {
        // Use local mutex guard for safe concurrent writes
        icu::Mutex guard;  // Local scope ensures release after assignment
        gCommonCleanupTable[phase] = handler;
    }

#if !UCLN_NO_AUTO_CLEANUP && (defined(UCLN_AUTO_ATEXIT) || defined(UCLN_AUTO_LOCAL))
    ucln_registerAutomaticCleanup();
#endif
}

// Public API: register library-level cleanup handlers
U_CAPI void U_EXPORT2
ucln_registerCleanup(ECleanupLibraryType libId,
                     cleanupFunc *handler) {
    U_ASSERT(libId > UCLN_START && libId < UCLN_COMMON);
    if (libId > UCLN_START && libId < UCLN_COMMON) {
        gLibraryCleanupTable[libId] = handler;
    }
}

// Shutdown routine: executes registered cleanup functions in reverse init order
U_CFUNC UBool ucln_lib_shutdown() {
    // Iterate over library types in ascending order (excluding sentinel)
    for (int32_t idx = UCLN_START + 1; idx < UCLN_COMMON; ++idx) {
        ucln_cleanupOne(static_cast<ECleanupLibraryType>(idx));
    }

    // Then handle common cleanup entries similarly
    for (int32_t idx = UCLN_COMMON_START + 1; idx < UCLN_COMMON_COUNT; ++idx) {
        auto& fn = gCommonCleanupTable[idx];
        if (fn) {
            fn();
            fn = nullptr;
        }
    }

#if !UCLN_NO_AUTO_CLEANUP && (defined(UCLN_AUTO_ATEXIT) || defined(UCLN_AUTO_LOCAL))
    ucln_unRegisterAutomaticCleanup();
#endif

    return true;
}

