double elapsed(double& t0) {
  const auto t1 =
    std::chrono::system_clock::now().time_since_epoch().count() / 1e6;
  const double diff = t1 - t0;
  t0 = t1;
  return diff;
}

using namespace irs;

TEST(Faiss, Dummy) {
  double t0 = 0.0;
  elapsed(t0);

  // Vector dimensionality
  int dim = 128;
  // Number of training vectors
  size_t train_count = 100'000;

  // Build IVF index with PQ compression
  std::string index_type = absl::StrCat("IVF1024,PQ32x4fs");
  auto* raw_index = index_factory(dim, index_type.c_str(), faiss::MetricType::METRIC_L2);
  ASSERT_TRUE(raw_index);

  auto& ivf_index = dynamic_cast<faiss::IndexIVF&>(*raw_index);

  std::mt19937 rng_engine{std::random_device{}()};

  // Generate and train on synthetic data
  {
    std::vector<float> training_data(train_count * dim);
    std::uniform_real_distribution<float> dist(-1.0f, 1.0f);

    printf("[%.3f s] Creating %zu training vectors in %d dimensions\n", elapsed(t0),
           train_count, dim);
    for (size_t i = 0; i < training_data.size(); ++i) {
      training_data[i] = dist(rng_engine);
    }

    printf("[%.3f s] Training IVF index...\n", elapsed(t0));
    ivf_index.train(train_count, training_data.data());
  }

  // Prepare database and queries
  size_t db_size = std::exchange(train_count, 0);
  std::vector<float> database(db_size * dim);
  std::uniform_real_distribution<float> dist(-1.0f, 1.0f);

  {
    printf("[%.3f s] Constructing database of %zu vectors\n", elapsed(t0), db_size);
    for (size_t i = 0; i < database.size(); ++i) {
      database[i] = dist(rng_engine);
    }

    printf("[%.3f s] Inserting vectors into index\n", elapsed(t0));
    ivf_index.add(db_size, database.data());

    printf("[%.3f s] Clustering imbalance factor: %g\n", elapsed(t0),
           ivf_index.invlists->imbalance_factor());

    // Extract some database points as queries
    constexpr int start_idx = 1234;
    constexpr int end_idx   = 1243;
    const size_t query_count = static_cast<size_t>(end_idx - start_idx);

    std::vector<float> queries(query_count * dim);
    for (int q = start_idx; q < end_idx; ++q) {
      for (int d = 0; d < dim; ++d) {
        queries[(q - start_idx) * dim + d] = database[q * dim + d];
      }
    }

    // Perform search
    constexpr int k_neighbors = 5;
    ivf_index.nprobe = 4;

    printf(
      "[%.3f s] Searching for %d nearest neighbors of %zu query vectors\n",
      elapsed(t0), k_neighbors, query_count);

    std::vector<faiss::idx_t> neighbor_ids(k_neighbors * query_count);
    std::vector<float> distances(k_neighbors * query_count);

    ivf_index.search(static_cast<faiss::idx_t>(query_count),
                     queries.data(),
                     k_neighbors,
                     distances.data(),
                     neighbor_ids.data());

    printf("[%.3f s] Search results:\n", elapsed(t0));
    for (size_t q = 0; q < query_count; ++q) {
      printf("query %2zu: ", q);
      for (int k = 0; k < k_neighbors; ++k) {
        printf("%7ld ", neighbor_ids[k + q * k_neighbors]);
      }
      printf("\n     dis: ");
      for (int k = 0; k < k_neighbors; ++k) {
        printf("%7g ", distances[k + q * k_neighbors]);
      }
      printf("\n");
    }

    printf("Note: NN distance > 0 due to quantization artifacts\n");
  }

  // Save index variants
  {
    const char* filename_with_postings = "/tmp/index_trained.faissindex_wi_posting";
    printf("[%.3f s] Saving full index to %s\n", elapsed(t0), filename_with_postings);
    faiss::write_index(&ivf_index, filename_with_postings);
  }

  {
    const char* filename_without_postings = "/tmp/index_trained.faissindex_wo_posting";
    printf("[%.3f s] Saving index without posting lists to %s\n", elapsed(t0),
           filename_without_postings);
    ivf_index.replace_invlists(nullptr, true);
    faiss::write_index(&ivf_index, filename_without_postings);
  }

  delete raw_index;
}

