// Helper: Trim leading/trailing quotes from ANSI string
inline std::string TrimQuotes(const std::string& input) {
    if (input.size() >= 2 && input.front() == '"' && input.back() == '"') {
        return input.substr(1, input.size() - 2);
    }
    return input;
}

// Helper: Convert narrow string to wide using RAII vector
inline std::wstring ToWideString(const std::string& narrow) {
    if (narrow.empty()) return {};
    int required = MultiByteToWideChar(CP_ACP, 0, narrow.c_str(), -1, nullptr, 0);
    if (required <= 0) return {};
    std::vector<wchar_t> buffer(required);
    MultiByteToWideChar(CP_ACP, 0, narrow.c_str(), -1, buffer.data(), required);
    return std::wstring(buffer.data());
}

// RunDLL entry point to start a game and inject into it
extern "C" __declspec(dllexport) void CALLBACK StartAndInject(HWND hwnd, HINSTANCE hInst, LPSTR lpszCmdLine,
                                                              int nCmdShow) {
    UNREFERENCED_PARAMETER(hwnd);
    UNREFERENCED_PARAMETER(hInst);
    UNREFERENCED_PARAMETER(nCmdShow);

    // Initialize logging configuration
    auto& configMgr = display_commander::config::DisplayCommanderConfigManager::GetInstance();
    configMgr.Initialize();
    configMgr.SetAutoFlushLogs(true);

    // Extract executable path from command line
    std::string rawCommandLine = (lpszCmdLine != nullptr) ? std::string(lpszCmdLine) : "";
    std::string targetExecutablePathA = TrimQuotes(rawCommandLine);

    if (targetExecutablePathA.empty()) {
        OutputDebugStringA(
            "StartAndInject: No executable path was supplied. Expected format:\n"
            "rundll32.exe zzz_display_commander.addon64,StartAndInject \"C:\\Path\\To\\game.exe\"");
        return;
    }

    // Convert to wide string
    std::wstring targetExecutablePathW = ToWideString(targetExecutablePathA);
    if (targetExecutablePathW.empty()) {
        OutputDebugStringA("StartAndInject: Wide conversion failed for executable path");
        return;
    }

    // Validate existence of the file
    if (!std::filesystem::exists(targetExecutablePathW)) {
        OutputDebugStringA(std::format("StartAndInject: Executable not found: {}", targetExecutablePathA).c_str());
        return;
    }

    OutputDebugStringA(std::format("StartAndInject: Launching process: {}", targetExecutablePathA).c_str());

    // Prepare process startup info
    STARTUPINFOW startupInfo{};
    PROCESS_INFORMATION procInfo{};
    startupInfo.cb = sizeof(startupInfo);

    // Build command line with quoted path
    std::wstring cmdLine = L"\"" + targetExecutablePathW + L"\"";

    if (!CreateProcessW(nullptr, &cmdLine[0], nullptr, nullptr, FALSE, 0, nullptr, nullptr, &startupInfo, &procInfo)) {
        DWORD lastErr = GetLastError();
        OutputDebugStringA(std::format("StartAndInject: Process creation failed. Error code: {} (0x{:X})", lastErr, lastErr).c_str());
        return;
    }

    // Close thread handle as it's not needed anymore
    CloseHandle(procInfo.hThread);

    OutputDebugStringA(std::format("StartAndInject: Process launched successfully (PID: {})", procInfo.dwProcessId).c_str());

    // Allow brief initialization time before injection
    Sleep(500);

    // Determine architecture via WoW64 check
    BOOL isWow64 = FALSE;
    IsWow64Process(procInfo.hProcess, &isWow64);

    // Locate appropriate ReShade DLL
    std::wstring reshadeDllPath = GetReShadeDllPath(isWow64 != FALSE);
    if (reshadeDllPath.empty()) {
        OutputDebugStringA("StartAndInject: Could not locate ReShade DLL path");
        CloseHandle(procInfo.hProcess);
        return;
    }

    // Perform injection
    bool injected = InjectIntoProcess(procInfo.dwProcessId, reshadeDllPath);
    CloseHandle(procInfo.hProcess);

    if (injected) {
        OutputDebugStringA(std::format("StartAndInject: Injection successful into PID {}", procInfo.dwProcessId).c_str());
    } else {
        OutputDebugStringA(std::format("StartAndInject: Injection failed for PID {}", procInfo.dwProcessId).c_str());
    }
}

// RunDLL entry point to wait for process and inject
extern "C" __declspec(dllexport) void CALLBACK WaitAndInject(HWND hwnd, HINSTANCE hInst, LPSTR lpszCmdLine,
                                                             int nCmdShow) {
    UNREFERENCED_PARAMETER(hwnd);
    UNREFERENCED_PARAMETER(hInst);
    UNREFERENCED_PARAMETER(nCmdShow);

    // Initialize logging system
    auto& configMgr = display_commander::config::DisplayCommanderConfigManager::GetInstance();
    configMgr.Initialize();
    configMgr.SetAutoFlushLogs(true);

    // Parse command line argument
    std::string rawInput = (lpszCmdLine != nullptr) ? std::string(lpszCmdLine) : "";
    std::string exeNameRaw = TrimQuotes(rawInput);

    if (exeNameRaw.empty()) {
        OutputDebugStringA(
            "WaitAndInject: No executable name specified. Usage:\n"
            "rundll32.exe zzz_display_commander.addon64,WaitAndInject \"game.exe\"");
        return;
    }

    // Normalize to wide string
    std::wstring exeNameW = ToWideString(exeNameRaw);
    if (exeNameW.empty()) {
        OutputDebugStringA("WaitAndInject: Failed to convert executable name to wide string");
        return;
    }

    // Extract just filename portion (e.g., "C:\\path\\game.exe" -> "game.exe")
    std::filesystem::path fullPath(exeNameW);
    std::wstring baseNameOnly = fullPath.filename().wstring();

    // Log both original and normalized name
    std::string baseNameA(baseNameOnly.begin(), baseNameOnly.end());
    OutputDebugStringA(std::format("WaitAndInject: Monitoring for process: '{}' (normalized: '{}')",
                                   exeNameRaw, baseNameA).c_str());
    std::cout << "WaitAndInject: Monitoring for process: '" << exeNameRaw
              << "' (normalized: '" << baseNameA << "')" << std::endl;

    // Begin infinite monitoring loop
    WaitForProcessAndInject(baseNameOnly);
}

