// Helper to compare two entity nodes recursively for equality
void NodeEqualityCheck(EntNode& left, EntNode& right) {
    assert(left.getFlags() == right.getFlags());
    assert(left.getChildCount() == right.getChildCount());
    assert(left.NameLength() == right.NameLength());
    assert(0 == memcmp(left.NamePtr(), right.NamePtr(), left.NameLength()));

    // Floating-point round-trip assumption: value comparison must be exact
    assert(left.ValueLength() == right.ValueLength());
    assert(0 == memcmp(left.ValuePtr(), right.ValuePtr(), left.ValueLength()));

    for (int idx = 0; idx < left.getChildCount(); ++idx) {
        NodeEqualityCheck(*left.ChildAt(idx), *right.ChildAt(idx));
    }
}

// Specialized comparison for mapentities root nodes (skipping metadata & header chunk differences)
void MapRootEqualityCheck(EntNode& originalRoot, EntNode& transformedRoot) {
    const int origChildCount = originalRoot.getChildCount();
    const int transChildCount = transformedRoot.getChildCount();

    if (origChildCount == transChildCount) {
        for (int i = 0; i < origChildCount - 1; ++i) {
            NodeEqualityCheck(originalRoot[i], transformedRoot[i]);
        }
    } else {
        // One node has an extra metadata child at front
        assert(origChildCount - 1 == transChildCount);
        assert(originalRoot[0].getName() == "metadata");
        assert(transformedRoot[0].getName() != "metadata");

        for (int j = 1; j < origChildCount - 1; ++j) {
            NodeEqualityCheck(originalRoot[j], transformedRoot[j - 1]);
        }
    }

    // Handle last child (header chunk or fallback)
    EntNode& finalOrig = originalRoot[origChildCount - 1];
    EntNode& finalTrans = transformedRoot[transChildCount - 1];

    if (finalOrig.getName() != "headerchunk") {
        assert(finalTrans.getName() != "headerchunk");
        NodeEqualityCheck(finalOrig, finalTrans);
    } else {
        assert(finalOrig.getChildCount() == finalTrans.getChildCount());
        // Skip first line of header (modified during serialization)
        for (int k = 1; k < finalOrig.getChildCount(); ++k) {
            NodeEqualityCheck(finalOrig[k], finalTrans[k]);
        }
    }
}

// Run round-trip test on all files matching extension in directory
void ExecuteTest(const fs::path& baseDir, const fs::path& ext, ResourceType type) {
    std::vector<fs::path> candidates;

    for (const auto& entry : fs::recursive_directory_iterator(baseDir)) {
        if (!entry.is_directory() && entry.path().extension() == ext) {
            candidates.emplace_back(entry.path());
        }
    }

    std::cout << "Running tests on " << candidates.size() << " files under " << baseDir << "\n";

    int processed = 0;
    for (const auto& filePath : candidates) {
        std::cout << filePath << "\n";

        // Deserialize original file
        EntityParser original(filePath.string(), ParsingMode::PERMISSIVE);

        // Serialize into binary buffer
        size_t bufferSize = static_cast<size_t>(fs::file_size(filePath) * 1.1);
        BinaryWriter serializer(bufferSize);
        int warnings = Reserializer::Serialize(*original.getRoot(), serializer, type, 
                                               original.eofblob, original.eofbloblength);
        if (warnings != 0) {
            std::cout << "Warnings encountered for: " << filePath << "\n";
        }

        // Deserialize serialized data again
        BinaryReader deserializer(serializer.GetBuffer(), serializer.GetFilledSize());
        std::string outputString;
        outputString.reserve(10000);
        Deserializer::DeserialSingle(deserializer, outputString, type);

        // Parse newly deserialized content
        EntityParser reconstructed(ParsingMode::PERMISSIVE, std::string_view(outputString), false);

        // Compare based on resource type
        if (type == rt_mapentities) {
            MapRootEqualityCheck(*original.getRoot(), *reconstructed.getRoot());
        } else {
            NodeEqualityCheck(*original.getRoot(), *reconstructed.getRoot());
        }

        ++processed;
    }
}

