BleKeyboard::BleKeyboard(String deviceName, String deviceManufacturer, uint8_t batteryLevel)
    : hid(nullptr), deviceName(String(deviceName).substring(0, 15)),
      deviceManufacturer(String(deviceManufacturer).substring(0, 15)), batteryLevel(batteryLevel) {}

void BleKeyboard::begin(const uint8_t *layout, uint16_t showAs) {
    appearance = showAs;
    _asciimap = layout;
    BLEDevice::init(deviceName.c_str());
    pServer = BLEDevice::createServer();
    pServer->setCallbacks(this);
    hid = new BLEHIDDevice(pServer);
    inputKeyboard = hid->inputReport(KEYBOARD_ID);
    outputKeyboard = hid->outputReport(KEYBOARD_ID);
    inputMediaKeys = hid->inputReport(MEDIA_KEYS_ID);
    inputKeyboard->setCallbacks(this);
    outputKeyboard->setCallbacks(this);
    inputMediaKeys->setCallbacks(this);
    hid->manufacturer()->setValue(deviceManufacturer);
    hid->pnp(0x02, vid, pid, version);
    hid->hidInfo(0x00, 0x01);
#if defined(USE_NIMBLE)
    BLEDevice::setSecurityAuth(true, true, true);
#else
    BLESecurity *pSecurity = new BLESecurity();
    pSecurity->setAuthenticationMode(ESP_LE_AUTH_REQ_SC_MITM_BOND);
#endif
    hid->reportMap((uint8_t *)_hidReportDescriptor, sizeof(_hidReportDescriptor));
    hid->startServices();
    onStarted(pServer);
    advertising = pServer->getAdvertising();
    advertising->setAppearance(appearance);
    if (_randUUID) {
        advertising->addServiceUUID(BLEUUID((uint16_t)(ESP.getEfuseMac() & 0xFFFF)));
    } else {
        advertising->addServiceUUID(hid->hidService()->getUUID());
    }
    advertising->setScanResponse(false);
    advertising->start();
    hid->setBatteryLevel(batteryLevel);
}

void BleKeyboard::end(void) {
    int connectedCount = pServer->getConnectedCount();
    if (connectedCount > 0) {
        for (int i = 0; i < connectedCount; ++i) {
            pServer->disconnect(pServer->getPeerInfo(i).getConnHandle());
        }
    }
    delete hid;
    BLEDevice::deinit();
    this->connected = false;
}

bool BleKeyboard::isConnected(void) { return this->connected; }

void BleKeyboard::setBatteryLevel(uint8_t level) {
    this->batteryLevel = level;
    if (hid != nullptr) {
        this->hid->setBatteryLevel(this->batteryLevel);
    }
}

void BleKeyboard::setName(String deviceName) { this->deviceName = deviceName; }

void BleKeyboard::setDelay(uint32_t ms) { this->_delay_ms = ms; }

void BleKeyboard::set_vendor_id(uint16_t vid) { this->vid = vid; }

void BleKeyboard::set_product_id(uint16_t pid) { this->pid = pid; }

void BleKeyboard::set_version(uint16_t version) { this->version = version; }

void BleKeyboard::sendReport(KeyReport *keys) {
    if (this->isConnected() && this->inputKeyboard->getSubscribedCount() > 0) {
        this->inputKeyboard->setValue((uint8_t *)keys, sizeof(KeyReport));
        this->inputKeyboard->notify();
#if defined(USE_NIMBLE)
        this->delay_ms(_delay_ms);
#endif
    }
}

void BleKeyboard::sendReport(MediaKeyReport *keys) {
    if (this->isConnected() && this->inputMediaKeys->getSubscribedCount() > 0) {
        this->inputMediaKeys->setValue((uint8_t *)keys, sizeof(MediaKeyReport));
        this->inputMediaKeys->notify();
#if defined(USE_NIMBLE)
        this->delay_ms(_delay_ms);
#endif
    }
}

size_t BleKeyboard::press(uint8_t k) {
    uint8_t idx;
    if (k >= 0xE0 && k < 0xE8) {
        // modifier key already in correct range
    } else if (k >= 0x88) {
        k = k - 0x88;
    } else if (k >= 0x80) {
        _keyReport.modifiers |= (1 << (k - 0x80));
        k = 0;
    } else {
        k = _asciimap[k];
        if (!k) {
            setWriteError();
            return 0;
        }
        if ((k & 0xC0) == 0xC0) {
            _keyReport.modifiers |= 0x40;
            k &= 0x3F;
        } else if ((k & 0x80) == 0x80) {
            _keyReport.modifiers |= 0x02;
            k &= 0x7F;
        }
        if (k == 0x32) k = 0x64;
    }

    bool alreadyPresent = false;
    for (idx = 0; idx < 6; ++idx) {
        if (_keyReport.keys[idx] == k) {
            alreadyPresent = true;
            break;
        }
    }

    if (!alreadyPresent) {
        for (idx = 0; idx < 6; ++idx) {
            if (_keyReport.keys[idx] == 0x00) {
                _keyReport.keys[idx] = k;
                break;
            }
        }
        if (idx == 6) {
            setWriteError();
            return 0;
        }
    }

    sendReport(&_keyReport);
    return 1;
}

size_t BleKeyboard::press(const MediaKeyReport k) {
    uint16_t incoming = k[1] | (k[0] << 8);
    uint16_t current = _mediaKeyReport[1] | (_mediaKeyReport[0] << 8);
    current |= incoming;
    _mediaKeyReport[0] = static_cast<uint8_t>((current >> 8) & 0xFF);
    _mediaKeyReport[1] = static_cast<uint8_t>(current & 0xFF);
    sendReport(&_mediaKeyReport);
    return 1;
}

size_t BleKeyboard::release(uint8_t k) {
    uint8_t idx;
    if (k >= 136) {
        k = k - 136;
    } else if (k >= 128) {
        _keyReport.modifiers &= ~(1 << (k - 128));
        k = 0;
    } else {
        k = pgm_read_byte(_asciimap + k);
        if (!k) { return 0; }
        if ((k & ALT_GR) == ALT_GR) {
            _keyReport.modifiers &= ~(0x40);
            k &= 0x3F;
        } else if ((k & SHIFT) == SHIFT) {
            _keyReport.modifiers &= ~(0x02);
            k &= 0x7F;
        }
        if (k == ISO_REPLACEMENT) { k = ISO_KEY; }
    }

    for (idx = 0; idx < 6; ++idx) {
        if (k != 0 && _keyReport.keys[idx] == k) {
            _keyReport.keys[idx] = 0x00;
        }
    }

    sendReport(&_keyReport);
    return 1;
}

size_t BleKeyboard::release(const MediaKeyReport k) {
    uint16_t incoming = k[1] | (k[0] << 8);
    uint16_t current = _mediaKeyReport[1] | (_mediaKeyReport[0] << 8);
    current &= ~incoming;
    _mediaKeyReport[0] = static_cast<uint8_t>((current >> 8) & 0xFF);
    _mediaKeyReport[1] = static_cast<uint8_t>(current & 0xFF);
    sendReport(&_mediaKeyReport);
    return 1;
}

void BleKeyboard::releaseAll(void) {
    for (int i = 0; i < 6; ++i) _keyReport.keys[i] = 0;
    _keyReport.modifiers = 0;
    _mediaKeyReport[0] = 0;
    _mediaKeyReport[1] = 0;
    sendReport(&_keyReport);
    sendReport(&_mediaKeyReport);
}

size_t BleKeyboard::write(uint8_t c) {
    size_t res = press(c);
    release(c);
    return res;
}

size_t BleKeyboard::write(const MediaKeyReport c) {
    size_t res = press(c);
    release(c);
    return res;
}

size_t BleKeyboard::write(const uint8_t *buffer, size_t size) {
    size_t written = 0;
    while (size-- > 0) {
        if (*buffer != '\r') {
            if (write(*buffer)) {
                ++written;
            } else {
                break;
            }
        }
        ++buffer;
    }
    return written;
}

void BleKeyboard::onConnect(BLEServer *pServer) {
    Serial.println("lib connected");
#if !defined(USE_NIMBLE)
    BLE2902 *desc = (BLE2902 *)this->inputKeyboard->getDescriptorByUUID(BLEUUID((uint16_t)0x2902));
    desc->setNotifications(true);
    desc = (BLE2902 *)this->inputMediaKeys->getDescriptorByUUID(BLEUUID((uint16_t)0x2902));
    desc->setNotifications(true);
#endif
}

void BleKeyboard::onDisconnect(BLEServer *pServer) {
    this->connected = false;
    Serial.println("lib disconnected");
#if !defined(USE_NIMBLE)
    BLE2902 *desc = (BLE2902 *)this->inputKeyboard->getDescriptorByUUID(BLEUUID((uint16_t)0x2902));
    desc->setNotifications(false);
    desc = (BLE2902 *)this->inputMediaKeys->getDescriptorByUUID(BLEUUID((uint16_t)0x2902));
    desc->setNotifications(false);
    advertising->start();
#endif
}

void BleKeyboard::onAuthenticationComplete(ble_gap_conn_desc *desc) {
    if (desc->sec_state.encrypted) {
        Serial.println("Paired successfully.");
        this->connected = true;
    } else {
        Serial.println("Pairing failed");
        this->connected = false;
    }
}

void BleKeyboard::onWrite(BLECharacteristic *me) {
    uint8_t *value = (uint8_t *)(me->getValue().c_str());
    ESP_LOGI(LOG_TAG, "special keys: %d", *value);
}

void BleKeyboard::delay_ms(uint64_t ms) {
    uint64_t start = esp_timer_get_time();
    if (ms > 0) {
        uint64_t end = start + (ms * 1000);
        if (start > end) {
            while (esp_timer_get_time() > end) {}
        }
        while (esp_timer_get_time() < end) {}
    }
}

void BleKeyboard::onSubscribe(
    NimBLECharacteristic *pCharacteristic, ble_gap_conn_desc *desc, uint16_t subValue
) {
    if (subValue == 0) {
        Serial.println("Client unsubscribed from notifications/indications.");
    } else {
        Serial.println("Client subscribed to notifications.");
    }
}

