namespace {

// Retrieve minimal alignment requirement for pinned memory on given device
std::size_t deriveMinAlignment(int dev_id) {
    auto& driver = c10::cuda::DriverAPI::get();
    CUmemAllocationProp mem_prop{};
    mem_prop.type = CU_MEM_ALLOCATION_TYPE_PINNED;
    mem_prop.location.type = CU_MEM_LOCATION_TYPE_DEVICE;
    mem_prop.location.id = dev_id;

    std::size_t align_size = 0;
    C10_CUDA_DRIVER_CHECK(driver.cuMemGetAllocationGranularity_(
        &align_size, &mem_prop, CU_MEM_ALLOC_GRANULARITY_MINIMUM));
    return align_size;
}

} // anonymous namespace

namespace torch::comms {

// Global hook function registered with allocator
void globalCachingAllocatorTraceCallback(
    const c10::cuda::CUDACachingAllocator::TraceEntry& entry) {
    CachingAllocatorHook::getInstance().handleMemoryEvent(entry);
}

// Singleton accessor with thread-safe initialization
CachingAllocatorHookImpl& CachingAllocatorHook::getInstance() {
    static std::once_flag init_once;
    std::call_once(init_once, [] { instance_ = std::make_unique<DefaultCachingAllocatorHookImpl>(); });
    return *instance_;
}

DefaultCachingAllocatorHookImpl::DefaultCachingAllocatorHookImpl() {
    at::globalContext().lazyInitDevice(c10::DeviceType::CUDA);
    setupMemoryPreHook();
    c10::cuda::CUDACachingAllocator::attachAllocatorTraceTracker(&globalCachingAllocatorTraceCallback);
}

void CachingAllocatorHookImpl::setupMemoryPreHook() {
    auto snapshot = c10::cuda::CUDACachingAllocator::snapshot();

    for (const auto& seg : snapshot.segments) {
        void* base_ptr = reinterpret_cast<void*>(seg.address);
        std::size_t size = seg.total_size;

        if (memory_registry_.count(base_ptr)) {
            throw std::runtime_error("Duplicate memory registration detected during pre-hook");
        }
        memory_registry_[base_ptr] = MemoryRecord{size, static_cast<int>(seg.device)};
    }

    pre_hook_active_ = true;
}

void CachingAllocatorHookImpl::handleMemoryEvent(
    const c10::cuda::CUDACachingAllocator::TraceEntry& te) {
    std::lock_guard<std::mutex> guard(lock_);

    switch (te.action_) {
        case c10::cuda::CUDACachingAllocator::TraceEntry::Action::SEGMENT_ALLOC: {
            void* ptr = reinterpret_cast<void*>(static_cast<uintptr_t>(te.addr_));
            std::size_t len = te.size_;

            if (memory_registry_.contains(ptr)) {
                LOG(ERROR) << "[CCA] SEGMENT_ALLOC: Already registered at 0x"
                           << std::hex << ptr << std::dec
                           << ", size=" << len
                           << ", existing_size=" << memory_registry_.at(ptr).length;
                throw std::runtime_error("Double registration attempt");
            }

            memory_registry_[ptr] = MemoryRecord{len, te.device_};

            for (auto& comm : active_comms_) {
                if (comm->getDevice().index() == te.device_) {
                    comm->register_address(TorchCommNCCLX::AddressWithLen(ptr, len));
                }
            }
            break;
        }

        case c10::cuda::CUDACachingAllocator::TraceEntry::Action::SEGMENT_MAP: {
            std::size_t total_bytes = te.size_;
            std::size_t chunk_align = deriveMinAlignment(te.device_);
            std::uintptr_t base_addr = static_cast<std::uintptr_t>(te.addr_);

            for (std::size_t offset = 0; offset < total_bytes; ) {
                std::size_t remaining = total_bytes - offset;
                if (remaining < chunk_align) {
                    LOG(ERROR) << "[CCA] SEGMENT_MAP: Invalid remainder "
                               << remaining << " at offset " << offset
                               << " (total=" << total_bytes << ", chunk=" << chunk_align << ")";
                    throw std::runtime_error("Unaligned segment map region");
                }

                void* chunk_ptr = reinterpret_cast<void*>(base_addr + offset);
                if (memory_registry_.contains(chunk_ptr)) {
                    LOG(ERROR) << "[CCA] SEGMENT_MAP: Duplicate chunk at 0x"
                               << std::hex << chunk_ptr << std::dec
                               << ", size=" << chunk_align;
                    throw std::runtime_error("Chunk already registered");
                }

                memory_registry_[chunk_ptr] = MemoryRecord{chunk_align, te.device_};

                for (auto& comm : active_comms_) {
                    if (comm->getDevice().index() == te.device_) {
                        comm->register_address(
                            TorchCommNCCLX::AddressWithLen(chunk_ptr, chunk_align));
                    }
                }

                offset += chunk_align;
            }
            break;
        }

        case c10::cuda::CUDACachingAllocator::TraceEntry::Action::SEGMENT_FREE: {
            void* addr = reinterpret_cast<void*>(static_cast<uintptr_t>(te.addr_));
            if (!memory_registry_.contains(addr)) {
                LOG(ERROR) << "[CCA] SEGMENT_FREE: Unregistered address 0x"
                           << std::hex << addr << std::dec
                           << ", size=" << te.size_;
                throw std::runtime_error("Attempt to free unregistered memory");
            }

            std::size_t reg_len = memory_registry_[addr].length;
            memory_registry_.erase(addr);

            for (auto& comm : active_comms_) {
                if (comm->getDevice().index() == te.device_) {
                    comm->deregister_address(TorchCommNCCLX::Address(addr));
                }
            }
            break;
        }

        case c10::cuda::CUDACachingAllocator::TraceEntry::Action::SEGMENT_UNMAP: {
            std::size_t total_unmap = te.size_;
            std::uintptr_t start_addr = static_cast<std::uintptr_t>(te.addr_);

            std::size_t offset = 0;
            while (offset < total_unmap) {
                void* candidate = reinterpret_cast<void*>(start_addr + offset);
                auto iter = memory_registry_.find(candidate);

                if (iter != memory_registry_.end() && iter->second.dev == te.device_) {
                    std::size_t chunk_len = iter->second.length;

                    for (auto& comm : active_comms_) {
                        if (comm->getDevice().index() == te.device_) {
                            comm->deregister_address(TorchCommNCCLX::Address(candidate));
                        }
                    }

                    memory_registry_.erase(iter);
                    offset += chunk_len;
                } else {
                    LOG(ERROR) << "[CCA] SEGMENT_UNMAP: Missing chunk at 0x"
                               << std::hex << candidate << std::dec
                               << ", offset=" << offset;
                    throw std::runtime_error("Inconsistent unmapping: expected registered chunk not found");
                }
            }
            break;
        }

        default:
            // Ignore unknown actions silently or log warning if needed
            break;
    }
}

void CachingAllocatorHookImpl::attachCommunicator(TorchCommNCCLX* comm) {
    std::lock_guard<std::mutex> guard(lock_);

    if (active_comms_.contains(comm)) {
        throw std::runtime_error("Communicator already attached");
    }

    for (const auto& [addr, rec] : memory_registry_) {
        if (rec.dev == comm->getDevice().index()) {
            comm->register_address(TorchCommNCCLX::AddressWithLen(addr, rec.length));
        }
    }

    active_comms_.insert(comm);
}

void CachingAllocatorHookImpl::detachCommunicator(TorchCommNCCLX* comm) {
    std::lock_guard<std::mutex> guard(lock_);

    if (!active_comms_.contains(comm)) {
        return; // Not an error per spec
    }

    for (const auto& [addr, rec] : memory_registry_) {
        if (rec.dev == comm->getDevice().index()) {
            comm->deregister_address(TorchCommNCCLX::Address(addr));
        }
    }

    active_comms_.erase(comm);
}

void CachingAllocatorHookImpl::resetAll() {
    std::lock_guard<std::mutex> guard(lock_);

    for (auto& comm : active_comms_) {
        for (const auto& [addr, rec] : memory_registry_) {
            if (rec.dev == comm->getDevice().index()) {
                comm->deregister_address(TorchCommNCCLX::Address(addr));
            }
        }
    }

    memory_registry_.clear();
    active_comms_.clear();
}

bool CachingAllocatorHookImpl::hasAttached(TorchCommNCCLX* comm) const {
    std::lock_guard<std::mutex> guard(const_cast<std::mutex&>(lock_));
    return active_comms_.contains(comm);
}

bool CachingAllocatorHookImpl::wasPreHookApplied() const {
    return pre_hook_active_;
}

