using lock_guard = std::unique_lock<std::mutex>;
std::mutex global_print_mutex{};

constexpr size_t TILE_SIZE = 32;

// Kernel: Transpose matrix using shared memory tiling
__global__ void
transpose_kernel(const int* __restrict__ input,
                 int* __restrict__ output,
                 int rows,
                 int cols)
{
    __shared__ int tile[TILE_SIZE][TILE_SIZE];

    const int tx = threadIdx.x;
    const int ty = threadIdx.y;

    const int global_row = blockIdx.y * blockDim.y + ty;
    const int global_col = blockIdx.x * blockDim.x + tx;

    if(global_row < rows && global_col < cols)
    {
        tile[ty][tx] = input[global_row * cols + global_col];
    }

    __syncthreads();

    const int new_row = blockIdx.x * blockDim.x + ty;
    const int new_col = blockIdx.y * blockDim.y + tx;

    if(new_row < cols && new_col < rows)
    {
        output[new_row * rows + new_col] = tile[tx][ty];
    }
}

void
run_transpose_task(int rank_id,
                   int thread_id,
                   int device_id,
                   size_t iter_count,
                   size_t sync_interval)
{
    roctxRangePush("run_transpose_task");

    constexpr int M_ROWS = 4960 * 2;
    constexpr int N_COLS = 4960 * 2;

    hipStream_t stream{};
    HIP_CHECK(hipSetDevice(device_id));
    HIP_CHECK(hipStreamCreate(&stream));

    {
        lock_guard lk{global_print_mutex};
        std::cout << "[transpose] Rank " << rank_id << ", thread " << thread_id
                  << " assigned to device " << device_id << std::endl;
    }

    // Generate pseudo-random data deterministically per thread
    std::mt19937_64 rng_engine{static_cast<uint64_t>(std::random_device{}()) *
                               static_cast<uint64_t>(rank_id + 1) *
                               static_cast<uint64_t>(thread_id + 1)};
    std::uniform_int_distribution<int> dist{0, 1000};

    const size_t bytes_per_elem = sizeof(int);
    const size_t total_elements = static_cast<size_t>(M_ROWS) * N_COLS;
    const size_t buffer_size    = total_elements * bytes_per_elem;

    auto host_input  = std::make_unique<int[]>(total_elements);
    auto host_output = std::make_unique<int[]>(total_elements);

    std::generate(host_input.get(), host_input.get() + total_elements, [&]() { return dist(rng_engine); });
    std::fill(host_output.get(), host_output.get() + total_elements, 0);

    int* dev_in  = nullptr;
    int* dev_out = nullptr;

    HIP_CHECK(hipMalloc(&dev_in, buffer_size));
    HIP_CHECK(hipMalloc(&dev_out, buffer_size));
    HIP_CHECK(hipMemsetAsync(dev_in, 0, buffer_size, stream));
    HIP_CHECK(hipMemsetAsync(dev_out, 0, buffer_size, stream));
    HIP_CHECK(hipMemcpyAsync(dev_in, host_input.get(), buffer_size, hipMemcpyHostToDevice, stream));
    HIP_CHECK(hipStreamSynchronize(stream));

    dim3 grid_dim(M_ROWS / TILE_SIZE, N_COLS / TILE_SIZE, 1);
    dim3 block_dim(TILE_SIZE, TILE_SIZE, 1);

    auto start_time = std::chrono::high_resolution_clock::now();

    for(size_t i = 0; i < iter_count; ++i)
    {
        transpose_kernel<<<grid_dim, block_dim, 0, stream>>>(dev_in, dev_out, M_ROWS, N_COLS);
        HIP_CHECK(hipGetLastError());
        if(i % sync_interval == sync_interval - 1)
        {
            HIP_CHECK(hipStreamSynchronize(stream));
        }
    }

    auto end_time = std::chrono::high_resolution_clock::now();
    HIP_CHECK(hipStreamSynchronize(stream));

    HIP_CHECK(hipMemcpyAsync(host_output.get(), dev_out, buffer_size, hipMemcpyDeviceToHost, stream));
    HIP_CHECK(hipStreamSynchronize(stream));

    double elapsed_seconds =
        std::chrono::duration<double>{end_time - start_time}.count();
    double gigabytes_transferred =
        static_cast<double>(buffer_size) * iter_count * 2.0 / (1ULL << 30);
    {
        lock_guard lk{global_print_mutex};
        std::cout << "[transpose][" << rank_id << "][" << thread_id << "] Runtime: "
                  << elapsed_seconds << " s\n";
        std::cout << "[transpose][" << rank_id << "][" << thread_id << "] Performance: "
                  << (gigabytes_transferred / elapsed_seconds) << " GB/s\n";
    }

    HIP_CHECK(hipStreamDestroy(stream));
    HIP_CHECK(hipFree(dev_in));
    HIP_CHECK(hipFree(dev_out));

    // Verify correctness on CPU
    verify_data(host_input.get(), host_output.get(), M_ROWS, N_COLS);

    delete[] host_input.release();
    delete[] host_output.release();

    roctxRangePop();
}

bool
verify_element(int val_in, int val_out, int row, int col, int rows, int cols)
{
    return val_in == val_out;
}

void
verify_data(const int* input, const int* output, int rows, int cols)
{
    std::vector<std::pair<int, int>> test_coords;
    test_coords.reserve(10);

    for(int i = 0; i < 10; ++i)
    {
        int r = rand() % rows;
        int c = rand() % cols;
        test_coords.emplace_back(r, c);
    }

    bool mismatch_found = false;
    for(const auto& [r, c] : test_coords)
    {
        int expected = input[r * cols + c];
        int actual   = output[c * rows + r];
        if(expected != actual)
        {
            lock_guard lk{global_print_mutex};
            std::cerr << "Mismatch at (" << r << "," << c << "): expected=" << expected
                      << ", got=" << actual << "\n";
            mismatch_found = true;
        }
    }

    if(!mismatch_found)
    {
        lock_guard lk{global_print_mutex};
        std::cout << "[transpose] All sampled elements verified successfully.\n";
    }
}

}  // namespace

void
run_transpose(size_t num_threads,
              size_t iterations,
              size_t sync_every_n)
{
    auto range_id = roctxRangeStart("run_transpose");

    int world_rank = 0;
    int world_size = 1;

    printf("[transpose] Threads: %zu | Iterations: %zu | Sync every %zu iters\n",
           num_threads,
           iterations,
           sync_every_n);

#if defined(USE_MPI)
    MPI_Comm_rank(MPI_COMM_WORLD, &world_rank);
    MPI_Comm_size(MPI_COMM_WORLD, &world_size);
#else
    (void) world_size;
#endif

    int device_count = 0;
    HIP_CHECK(hipGetDeviceCount(&device_count));
    printf("[transpose] Devices available: %i\n", device_count);

    std::vector<int> device_assignment(world_size * num_threads);
    for(size_t t = 0; t < num_threads; ++t)
    {
        for(int r = 0; r < world_size; ++r)
        {
            size_t idx = r * num_threads + t;
            device_assignment[idx] = (t + r) % device_count;
        }
    }

    const size_t base_idx = world_rank * num_threads;
    std::vector<std::thread> worker_threads;

    for(size_t tid = 1; tid < num_threads; ++tid)
    {
        worker_threads.emplace_back(
            run_transpose_task,
            world_rank,
            static_cast<int>(tid),
            device_assignment[base_idx + tid],
            iterations,
            sync_every_n);
    }

    run_transpose_task(world_rank, 0, device_assignment[base_idx], iterations, sync_every_n);

    for(auto& th : worker_threads)
    {
        if(th.joinable())
            th.join();
    }

#if defined(USE_MPI)
    MPI_Barrier(MPI_COMM_WORLD);
#endif

    roctxRangeStop(range_id);
}

