#include <iostream>
#include <vector>
#include <queue>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    // Store comparison results: cmp[i][j] = true if i < j
    vector<vector<bool>> cmp(n + 1, vector<bool>(n + 1, false));

    // Function to ask comparison and cache result
    auto compare = [&](int a, int b) -> bool {
        if (cmp[a][b]) return cmp[a][b];
        cout << "? " << a << " " << b << endl;
        char response;
        cin >> response;
        bool result = (response == '<');
        cmp[a][b] = result;
        cmp[b][a] = !result;
        return result;
    };

    // Build adjacency list and in-degree count
    vector<vector<int>> graph(n + 1);
    vector<int> indegree(n + 1, 0);

    // First pass: compare consecutive elements
    for (int i = 1; i < n; ++i) {
        if (compare(i, i + 1)) {
            graph[i].push_back(i + 1);
            indegree[i + 1]++;
        } else {
            graph[i + 1].push_back(i);
            indegree[i]++;
        }
    }

    // Second pass: compare elements with gap of 2 (for additional constraints)
    for (int i = 1; i <= n - 2; ++i) {
        if (compare(i, i + 2)) {
            graph[i].push_back(i + 2);
            indegree[i + 2]++;
        } else {
            graph[i + 2].push_back(i);
            indegree[i]++;
        }
    }

    // Topological sort using min-heap for lexicographically smallest order
    priority_queue<int, vector<int>, greater<int>> min_heap;
    for (int i = 1; i <= n; ++i) {
        if (indegree[i] == 0) {
            min_heap.push(i);
        }
    }

    vector<int> topo_order;
    while (!min_heap.empty()) {
        int node = min_heap.top();
        min_heap.pop();
        topo_order.push_back(node);

        for (int neighbor : graph[node]) {
            indegree[neighbor]--;
            if (indegree[neighbor] == 0) {
                min_heap.push(neighbor);
            }
        }
    }

    // Assign values according to topological order
    vector<int> result(n + 1);
    int current_value = 1;
    for (int node : topo_order) {
        result[node] = current_value++;
    }

    // Output final answer
    cout << "!";
    for (int i = 1; i <= n; ++i) {
        cout << " " << result[i];
    }
    cout << endl;

    return 0;
}

