#include <iostream>
#include <ruckig/ruckig.hpp>

int main() {
    using namespace ruckig;

    // Initialize the Ruckig trajectory generator for 3 degrees of freedom
    Ruckig<3> motion_planner(0.01);  // sampling time = 10 ms

    // Prepare input and output structures
    InputParameter<3> traj_input;
    OutputParameter<3> traj_output;

    // Configure initial state
    traj_input.current_position   = {0.0, 0.0, 0.5};
    traj_input.current_velocity   = {0.0, -2.2, -0.5};
    traj_input.current_acceleration = {0.0, 2.5, -0.5};

    // Define target state
    traj_input.target_position    = {5.0, -2.0, -3.5};
    traj_input.target_velocity    = {0.0, -0.5, -2.0};
    traj_input.target_acceleration = {0.0, 0.0, 0.5};

    // Set physical limits
    traj_input.max_velocity       = {3.0, 1.0, 3.0};
    traj_input.max_acceleration   = {3.0, 2.0, 1.0};
    traj_input.max_jerk           = {4.0, 3.0, 2.0};

    // Output header
    std::cout << "t | position" << std::endl;

    // Propagate trajectory step-by-step
    while (motion_planner.update(traj_input, traj_output) == Result::Working) {
        std::cout << traj_output.time << " | " << join(traj_output.new_position) << std::endl;
        traj_output.pass_to_input(traj_input);
    }

    // Report total duration
    std::cout << "Trajectory duration: " << traj_output.trajectory.get_duration() << " [s]." << std::endl;

    return 0;
}

#include "speye.h"

// Create an identity-like sparse matrix with ones on the main diagonal
template <typename T>
IGL_INLINE void igl::speye(const int m, const int n, Eigen::SparseMatrix<T> & I)
{
  // Determine the length of the diagonal (minimum of rows and columns)
  int diag_len = (m < n) ? m : n;

  // Initialize sparse matrix with dimensions m x n
  I = Eigen::SparseMatrix<T>(m, n);

  // Reserve space for diagonal entries
  I.reserve(diag_len);

  // Insert 1.0 at each diagonal position
  for (int idx = 0; idx < diag_len; ++idx) {
    I.insert(idx, idx) = static_cast<T>(1.0);
  }

  // Finalize the sparse matrix structure
  I.finalize();
}

// Overload for square matrices: calls the general version with m = n
template <typename T>
IGL_INLINE void igl::speye(const int n, Eigen::SparseMatrix<T> & I)
{
  return igl::speye(n, n, I);
}

