#include <faiss/utils/utils.h>
#include <fstream>
#include <iostream>
#include <omp.h>
#include <vector>
#include <faiss/IndexFlat.h>
#include <faiss/IndexIVFFlat.h>
#include "bench_utils.h"

int main() {
    const std::string experiment_tag = "blog_post_1";
    const std::string engine_name = "faiss_ivfflat";

#ifdef TINY_SCALE
    const std::string dataset_label = "openai";
    const size_t total_items = 999000;
    const size_t query_count = 1000;
    const size_t dim = 1536;
    const size_t cluster_count = 10000;
    const std::string data_path = "./data/data_openai.bin";
    const std::string query_path = "./data/data_openai_test.bin";
#else
    const std::string dataset_label = "cohere";
    const size_t total_items = 10000000;
    const size_t query_count = 1000;
    const size_t dim = 1024;
    const size_t cluster_count = 40000;
    const std::string data_path = "./data/data_cohere.bin";
    const std::string query_path = "./data/data_cohere_test.bin";
#endif

    const float sample_ratio = 1.0f;
    const int max_elem_per_cluster = static_cast<int>((total_items * sample_ratio) / cluster_count);
    const size_t thread_limit = omp_get_max_threads();
    omp_set_num_threads(thread_limit);

    std::cout << "=== FAISS IVFFlat Experiment on " << dataset_label << " ===" << std::endl;
    std::cout << "Dataset: " << dataset_label << " (items=" << total_items << ", dims=" << dim << ")\n";
    std::cout << "Clusters: " << cluster_count
              << ", Max items/centroid: " << max_elem_per_cluster
              << " (sample ratio: " << sample_ratio << ")\n";
    std::cout << "Compiler flags: " << faiss::get_compile_options() << std::endl;

    // Load data
    auto load_binary_data = [](const std::string& path, size_t count, size_t dimension) -> std::vector<float> {
        std::vector<float> buffer;
        buffer.resize(count * dimension);
        std::ifstream input(path, std::ios::binary);
        if (!input) {
            std::cerr << "Error: Cannot open file '" << path << "'\n";
            return {};
        }
        input.read(reinterpret_cast<char*>(buffer.data()), count * dimension * sizeof(float));
        return buffer;
    };

    std::vector<float> database = load_binary_data(data_path, total_items, dim);
    if (database.empty()) return 1;

    std::vector<float> test_queries = load_binary_data(query_path, query_count, dim);
    if (test_queries.empty()) return 1;

    // Construct IVFFlat index
    faiss::IndexFlatL2 quantizer(dim);
    faiss::IndexIVFFlat ivf_index(&quantizer, dim, cluster_count);
    ivf_index.cp.max_points_per_centroid = max_elem_per_cluster;
    ivf_index.cp.verbose = true;

    // Training phase
    bench_utils::TicToc timer;
    timer.Tic();
    ivf_index.train(total_items, database.data());
    timer.Toc();
    double training_duration_ms = timer.GetMilliseconds();
    std::cout << "\nTraining finished in " << training_duration_ms << " ms\n";

    // Assignment phase (adding vectors without retraining)
    timer.Reset();
    timer.Tic();
    ivf_index.add(total_items, database.data());
    timer.Toc();
    double indexing_duration_ms = timer.GetMilliseconds();
    std::cout << "Indexing (assignment) completed in " << indexing_duration_ms << " ms\n";
    std::cout << "Total time (train + add): " << (training_duration_ms + indexing_duration_ms) << " ms\n";

    // Recall evaluation if ground truth available
    std::string gt_file_path = bench_utils::get_ground_truth_path(dataset_label);
    std::ifstream gt_stream(gt_file_path);
    if (gt_stream.good()) {
        gt_stream.close();
        std::cout << "\n--- Evaluating Recall ---" << std::endl;
        std::cout << "Ground truth source: " << gt_file_path << std::endl;

        auto ground_truth_map = bench_utils::parse_ground_truth_json(gt_file_path);
        std::cout << "Processing " << query_count << " queries (loaded " << ground_truth_map.size()
                  << " entries from GT)" << std::endl;

        // Assign each database vector to its nearest centroid
        std::vector<faiss::idx_t> centroid_ids(total_items);
        std::vector<float> dist_to_centroids(total_items);
        const float* centroids = quantizer.get_xb();
        quantizer.search(total_items, database.data(), 1, dist_to_centroids.data(), centroid_ids.data());

        // Compute recall@10 and @100
        auto r10 = bench_utils::compute_recall(
            ground_truth_map, centroid_ids, test_queries.data(),
            centroids, query_count, cluster_count, dim, 10
        );
        bench_utils::print_recall_results(r10, 10);

        auto r100 = bench_utils::compute_recall(
            ground_truth_map, centroid_ids, test_queries.data(),
            centroids, query_count, cluster_count, dim, 100
        );
        bench_utils::print_recall_results(r100, 100);

        // Prepare config metadata
        std::unordered_map<std::string, std::string> meta;
        meta["niter"] = std::to_string(ivf_index.cp.niter);
        meta["nredo"] = std::to_string(ivf_index.cp.nredo);
        meta["max_points_per_centroid"] = std::to_string(ivf_index.cp.max_points_per_centroid);
        meta["sampling_fraction"] = std::to_string(sample_ratio);
        meta["verbose"] = ivf_index.cp.verbose ? "true" : "false";
        meta["training_time_ms"] = std::to_string(training_duration_ms);
        meta["indexing_time_ms"] = std::to_string(indexing_duration_ms);

        // Write results
        bench_utils::write_results_to_csv(
            experiment_tag,
            engine_name,
            dataset_label,
            ivf_index.cp.niter,
            ivf_index.cp.nredo,
            static_cast<int>(dim),
            total_items,
            static_cast<int>(cluster_count),
            training_duration_ms + indexing_duration_ms,
            static_cast<int>(thread_limit),
            0.0,
            meta,
            r10,
            r100
        );
    } else {
        std::cout << "\nGround truth not found at: " << gt_file_path << std::endl;
        std::cout << "Recall analysis skipped." << std::endl;
    }

    return 0;
}

