			if (HandlePtr)
			{
				EntryPtr->LogWindow->MultiOnWindowClosed.Remove(*HandlePtr);
			}
#else
			EntryPtr->LogWindow->MultiOnWindowClosed.RemoveRaw(this, &FLogWindowManager::OnWindowClosed);
#endif
		}
	}

	for (int32 OverflowIdx = 0; OverflowIdx < OverflowWindows.Num(); ++OverflowIdx)
	{
		if (TSharedPtr<SWindow> WinRef = OverflowWindows[OverflowIdx].Pin())
		{
#if TARGET_UE4_CL >= CL_DEPRECATEDEL
			const FDelegateHandle* HandlePtr = OnWindowClosedDelegateHandles.Find(WinRef.Get());
			if (HandlePtr)
			{
				WinRef->MultiOnWindowClosed.Remove(*HandlePtr);
			}
#else
			WinRef->MultiOnWindowClosed.RemoveRaw(this, &FLogWindowManager::OnWindowClosed);
#endif
		}
	}
}

void FLogWindowManager::Initialize(int32 InWidth, int32 InHeight)
{
	if (!bInitialized)
	{
		bInitialized = true;
		LogWidth = InWidth;
		LogHeight = InHeight;

		FDisplayMetrics Metrics;
		FSlateApplication::Get().GetDisplayMetrics(Metrics);

		const FPlatformRect& WorkArea = Metrics.PrimaryDisplayWorkAreaRect;
		const float AreaWidth = static_cast<float>(WorkArea.Right - WorkArea.Left);
		const float AreaHeight = static_cast<float>(WorkArea.Bottom - WorkArea.Top);

		const int32 HorizCount = static_cast<int32>(FMath::FloorToInteger(AreaWidth / static_cast<float>(LogWidth)));
		const int32 VertCount = static_cast<int32>(FMath::FloorToInteger(AreaHeight / static_cast<float>(LogHeight)));

		for (int32 Row = 0; Row < VertCount; ++Row)
		{
			for (int32 Col = 0; Col < HorizCount; ++Col)
			{
				FLogGridEntry NewEntry;
				const float TopPos = static_cast<float>(WorkArea.Top) + Row * LogHeight;
				const float LeftPos = static_cast<float>(WorkArea.Left) + Col * LogWidth;

				NewEntry.Top = TopPos;
				NewEntry.Bottom = TopPos + LogHeight;
				NewEntry.Left = LeftPos;
				NewEntry.Right = LeftPos + LogWidth;

				GridSpaces.Add(NewEntry);
			}
		}

#if 0
		for (int32 DebugIdx = 0; DebugIdx < GridSpaces.Num(); ++DebugIdx)
		{
			const FLogGridEntry& Entry = GridSpaces[DebugIdx];
			UE_LOG(LogUnitTest, Log, TEXT("Grid entry '%d': Top: %f, Bottom: %f, Left: %f, Right: %f"),
				DebugIdx, Entry.Top, Entry.Bottom, Entry.Left, Entry.Right);
		}
#endif
	}
}

TSharedPtr<SLogWindow> FLogWindowManager::CreateLogWindow(FString WindowTitle, ELogType FilterMask, bool bIsStatusOnly)
{
	TSharedPtr<SLogWindow> Result = nullptr;
	int32 TargetSlot = LocateNextAvailableSlot();
	bool bShouldMinimize = false;

	if (TargetSlot != INDEX_NONE)
	{
		LastLogWindowPos = TargetSlot;
		FLogGridEntry& Slot = GridSpaces[TargetSlot];

		Result = SNew(SLogWindow, WindowTitle, Slot.Left, Slot.Top, LogWidth, LogHeight)
			.bStatusWindow(bIsStatusOnly)
			.ExpectedFilters(FilterMask);

		Slot.LogWindow = Result;
	}
	else
	{
		UNIT_ASSERT(GridSpaces.Num() > 0);
		FLogGridEntry& OverflowSlot = GridSpaces[0];

		Result = SNew(SLogWindow, WindowTitle, OverflowSlot.Left, OverflowSlot.Top, LogWidth, LogHeight)
			.bStatusWindow(bIsStatusOnly)
			.ExpectedFilters(FilterMask);

		bShouldMinimize = true;
		OverflowWindows.Add(Result);
	}

	if (Result.IsValid())
	{
#if TARGET_UE4_CL >= CL_DEPRECATEDEL
		const FDelegateHandle NewHandle = Result->MultiOnWindowClosed.AddRaw(this, &FLogWindowManager::OnWindowClosed);
		OnWindowClosedDelegateHandles.Add(Result.Get(), NewHandle);
#else
		Result->MultiOnWindowClosed.AddRaw(this, &FLogWindowManager::OnWindowClosed);
#endif

		FSlateApplication::Get().AddWindow(Result.ToSharedRef());

		if (bShouldMinimize)
		{
			Result->Minimize();
		}
		else
		{
			Result->FlashWindow();
		}
	}

	return Result;
}

void FLogWindowManager::OnWindowClosed(const TSharedRef<SWindow>& ClosedRef)
{
	TSharedPtr<SLogWindow> ClosedPtr = StaticCastSharedRef<SLogWindow>(ClosedRef);
	if (!ClosedPtr.IsValid())
	{
		return;
	}

	// Clear grid slot if applicable
	int32 FreedSlotIndex = INDEX_NONE;
	for (int32 Idx = 0; Idx < GridSpaces.Num(); ++Idx)
	{
		if (GridSpaces[Idx].LogWindow == ClosedPtr)
		{
			FreedSlotIndex = Idx;
			GridSpaces[Idx].LogWindow.Reset();
			break;
		}
	}

	// Remove from overflow list regardless
	OverflowWindows.RemoveAll([&](const TWeakPtr<SLogWindow>& WeakPtr) {
		return WeakPtr.Pin() == ClosedPtr;
	});

	// Attempt to promote an overflow window into the freed slot
	if (FreedSlotIndex != INDEX_NONE && OverflowWindows.Num() > 0)
	{
		int32 PromotionIdx = INDEX_NONE;
		for (int32 i = 0; i < OverflowWindows.Num(); ++i)
		{
			TSharedPtr<SLogWindow> Win = OverflowWindows[i].Pin();
			if (Win && !Win->bHasMoved)
			{
				PromotionIdx = i;
				break;
			}
		}

		if (PromotionIdx != INDEX_NONE)
		{
			FLogGridEntry& TargetSlot = GridSpaces[FreedSlotIndex];
			TSharedPtr<SLogWindow> Promoted = OverflowWindows[PromotionIdx].Pin();

			if (Promoted.IsValid())
			{
				TargetSlot.LogWindow = Promoted;
				OverflowWindows.RemoveAt(PromotionIdx);
				Promoted->BringToFront();
				Promoted->MoveWindowTo(FVector2D(TargetSlot.Left, TargetSlot.Top));
				Promoted->FlashWindow();
			}
		}
	}

	// Notify unit test system
	if (GUnitTestManager != nullptr)
	{
		GUnitTestManager->NotifyLogWindowClosed(ClosedRef);
	}
}

int32 FLogWindowManager::LocateNextAvailableSlot()
{
	int32 FoundIndex = INDEX_NONE;
	const int32 TotalSlots = GridSpaces.Num();

	for (int32 Offset = 0; Offset < TotalSlots; ++Offset)
	{
		int32 ProbeIndex = (LastLogWindowPos + Offset + 1) % TotalSlots;
		if (!GridSpaces[ProbeIndex].LogWindow.IsValid())
		{
			FoundIndex = ProbeIndex;
			break;
		}
	}

	return FoundIndex;
}

