#include "shader_binding_tables.hpp"
#include "utils.hpp"

//--------------------------------------------------------------------------------------------------
// Constructs the Shader Binding Table (SBT) by extracting shader group handles from the pipeline
// and organizing them into appropriately sized regions for ray generation, miss, and closest-hit shaders.
//
Buffer SbtHelper::create_shader_binding_table(const vk::Pipeline &rtPipeline)
{
    // Define counts for shader groups: 1 raygen, 2 miss, 1 closest-hit
    uint32_t numMissShaders = 2;
    uint32_t numHitShaders  = 1;
    uint32_t totalShaderGroups = 1 + numMissShaders + numHitShaders;

    // Query handle size and alignment requirements from the device
    uint32_t rawHandleSize = rtProperties.shaderGroupHandleSize;
    uint32_t alignedHandleSize = utils::align_up(rawHandleSize, rtProperties.shaderGroupHandleAlignment);

    // Configure region strides and sizes per Vulkan spec for SBT layout
    uint32_t baseAlign = rtProperties.shaderGroupBaseAlignment;

    rgenRegion.setStride(utils::align_up(alignedHandleSize, baseAlign));
    rgenRegion.setSize(rgenRegion.stride); // Must match stride

    missRegion.setStride(alignedHandleSize);
    missRegion.setSize(
        utils::align_up(numMissShaders * alignedHandleSize, baseAlign));

    hitRegion.setStride(alignedHandleSize);
    hitRegion.setSize(
        utils::align_up(numHitShaders * alignedHandleSize, baseAlign));

    // Retrieve raw shader group handles from the pipeline
    uint32_t requiredDataSize = totalShaderGroups * rawHandleSize;
    std::vector<uint8_t> rawHandles = device.getRayTracingShaderGroupHandlesKHR<uint8_t>(
        rtPipeline, 0u, totalShaderGroups, requiredDataSize);

    // Compute total buffer size needed for the SBT
    vk::DeviceSize totalSbtSize = rgenRegion.size + missRegion.size + hitRegion.size;

    // Create host-visible, device-addressable buffer for the SBT
    Buffer rtSBTBuffer = utils::create_buffer(
        device,
        allocator,
        totalSbtSize,
        vk::BufferUsageFlagBits::eTransferSrc |
        vk::BufferUsageFlagBits::eShaderDeviceAddress |
        vk::BufferUsageFlagBits::eShaderBindingTableKHR,
        VMA_MEMORY_USAGE_AUTO_PREFER_HOST,
        VMA_ALLOCATION_CREATE_HOST_ACCESS_SEQUENTIAL_WRITE_BIT |
        VMA_ALLOCATION_CREATE_MAPPED_BIT);

    // Obtain device address for the SBT buffer
    vk::BufferDeviceAddressInfo addrInfo{rtSBTBuffer.buffer};
    vk::DeviceAddress baseAddress = device.getBufferAddress(addrInfo);

    // Assign base addresses for each region
    rgenRegion.setDeviceAddress(baseAddress);
    missRegion.setDeviceAddress(baseAddress + rgenRegion.size);
    hitRegion.setDeviceAddress(baseAddress + rgenRegion.size + missRegion.size);

    // Helper lambda to extract pointer to i-th raw handle
    auto fetchHandlePtr = [&](uint32_t index) -> const uint8_t* {
        return rawHandles.data() + index * rawHandleSize;
    };

    // Map the buffer and populate it with shader handles
    uint8_t* sbtMem = static_cast<uint8_t*>(rtSBTBuffer.allocationInfo.pMappedData);
    uint8_t* writeCursor = sbtMem;

    uint32_t currentGroupIndex = 0;

    // Copy raygen shader handle
    memcpy(writeCursor, fetchHandlePtr(currentGroupIndex++), rawHandleSize);
    writeCursor += rgenRegion.size;

    // Copy miss shader handles
    uint32_t missIdx = 0;
    while (missIdx < numMissShaders) {
        memcpy(writeCursor, fetchHandlePtr(currentGroupIndex++), rawHandleSize);
        writeCursor += missRegion.stride;
        ++missIdx;
    }

    // Copy closest-hit shader handles
    uint32_t hitIdx = 0;
    writeCursor = sbtMem + rgenRegion.size + missRegion.size;
    while (hitIdx < numHitShaders) {
        memcpy(writeCursor, fetchHandlePtr(currentGroupIndex++), rawHandleSize);
        writeCursor += hitRegion.stride;
        ++hitIdx;
    }

    return rtSBTBuffer;
}

