#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    if (!(cin >> N)) return 0;

    const int TOTAL = 2 * N;
    const int MAX_COORD = 100000;
    const int PERIMETER_BOUND = 400000;
    const int HALF_PERIM = PERIMETER_BOUND / 2; // 200000

    // Grid setup: divide the coordinate space into K x K cells
    const int CELL_SIZE = 1000;
    const int GRID_DIM = 100;

    // Difference grid: +1 for first N points (mackerels), -1 for next N (sardines)
    vector<vector<int>> diffGrid(GRID_DIM, vector<int>(GRID_DIM, 0));

    for (int idx = 0; idx < TOTAL; ++idx) {
        int x, y;
        cin >> x >> y;

        int gx = min(x / CELL_SIZE, GRID_DIM - 1);
        int gy = min(y / CELL_SIZE, GRID_DIM - 1);

        if (idx < N) 
            diffGrid[gy][gx] += 1;
        else 
            diffGrid[gy][gx] -= 1;
    }

    // Precompute cell boundaries
    vector<int> cellLeftX(GRID_DIM), cellRightX(GRID_DIM);
    vector<int> cellTopY(GRID_DIM), cellBottomY(GRID_DIM);

    for (int i = 0; i < GRID_DIM; ++i) {
        cellLeftX[i] = i * CELL_SIZE;
        cellTopY[i] = i * CELL_SIZE;
        cellRightX[i] = (i == GRID_DIM - 1) ? MAX_COORD : (i + 1) * CELL_SIZE - 1;
        cellBottomY[i] = (i == GRID_DIM - 1) ? MAX_COORD : (i + 1) * CELL_SIZE - 1;
    }

    long long maxDiff = LLONG_MIN;
    int bestL = 0, bestR = 0, bestT = 0, bestB = 0;

    // Try all possible top and bottom rows of cells
    for (int topRow = 0; topRow < GRID_DIM; ++topRow) {
        vector<int> colSum(GRID_DIM, 0);

        for (int botRow = topRow; botRow < GRID_DIM; ++botRow) {
            // Accumulate column sums from row 'botRow'
            for (int c = 0; c < GRID_DIM; ++c) {
                colSum[c] += diffGrid[botRow][c];
            }

            // Compute vertical span (height)
            int topCoord = cellTopY[topRow];
            int botCoord = cellBottomY[botRow];
            int height = botCoord - topCoord;

            // Remaining horizontal budget for perimeter constraint
            int remainingWidthBudget = HALF_PERIM - height;
            if (remainingWidthBudget < 0) break;

            // Prefix sums for column contributions
            vector<long long> prefix(GRID_DIM + 1, 0);
            for (int j = 0; j < GRID_DIM; ++j) {
                prefix[j + 1] = prefix[j] + colSum[j];
            }

            // Sliding window with deque to find best left boundary
            deque<pair<int, long long>> dq; // stores (index, prefix[index])

            for (int rightCol = 0; rightCol < GRID_DIM; ++rightCol) {
                // Maintain increasing order in deque (monotonic queue)
                while (!dq.empty() && dq.back().second >= prefix[rightCol]) {
                    dq.pop_back();
                }
                dq.emplace_back(rightCol, prefix[rightCol]);

                // Determine minimum left index allowed by width constraint
                long long minLeftX = (long long)cellRightX[rightCol] - remainingWidthBudget;
                int minLeftIdx;
                if (minLeftX <= 0) {
                    minLeftIdx = 0;
                } else {
                    minLeftIdx = (int)((minLeftX + CELL_SIZE - 1) / CELL_SIZE);
                }

                // Remove indices outside the valid range
                while (!dq.empty() && dq.front().first < minLeftIdx) {
                    dq.pop_front();
                }

                if (!dq.empty()) {
                    long long currentDiff = prefix[rightCol + 1] - dq.front().second;
                    if (currentDiff > maxDiff) {
                        maxDiff = currentDiff;
                        bestL = dq.front().first;
                        bestR = rightCol;
                        bestT = topRow;
                        bestB = botRow;
                    }
                }
            }
        }
    }

    // If no positive difference found, output full bounding box
    if (maxDiff <= 0) {
        cout << 4 << "\n";
        cout << 0 << " " << 0 << "\n";
        cout << MAX_COORD << " " << 0 << "\n";
        cout << MAX_COORD << " " << MAX_COORD << "\n";
        cout << 0 << " " << MAX_COORD << "\n";
        return 0;
    }

    // Extract rectangle coordinates
    int leftX = cellLeftX[bestL];
    int rightX = cellRightX[bestR];
    int topY = cellTopY[bestT];
    int bottomY = cellBottomY[bestB];

    // Final safety check on perimeter
    long long width = (long long)rightX - leftX;
    long long height = (long long)bottomY - topY;
    long long perimeter = 2 * (width + height);

    if (perimeter > PERIMETER_BOUND) {
        cout << 4 << "\n";
        cout << 0 << " " << 0 << "\n";
        cout << MAX_COORD << " " << 0 << "\n";
        cout << MAX_COORD << " " << MAX_COORD << "\n";
        cout << 0 << " " << MAX_COORD << "\n";
        return 0;
    }

    // Output final rectangle vertices in order
    cout << 4 << "\n";
    cout << leftX << " " << topY << "\n";
    cout << rightX << " " << topY << "\n";
    cout << rightX << " " << bottomY << "\n";
    cout << leftX << " " << bottomY << "\n";

    return 0;
}

