// Renamed class: FLanBeacon -> FLanDiscoverySocket
class FLanDiscoverySocket {
public:
    FSocket* SocketHandle;
    TSharedPtr<FInternetAddr> LocalAddress;
    TSharedPtr<FInternetAddr> TargetAddress;
    TSharedPtr<FInternetAddr> RemoteEndpoint;

    FLanDiscoverySocket()
        : SocketHandle(nullptr),
          LocalAddress(ISocketSubsystem::Get(PLATFORM_SOCKETSUBSYSTEM)->CreateInternetAddr()),
          TargetAddress(nullptr),
          RemoteEndpoint(ISocketSubsystem::Get(PLATFORM_SOCKETSUBSYSTEM)->CreateInternetAddr())
    {
    }

    ~FLanDiscoverySocket() {
        ISocketSubsystem* Subsystem = ISocketSubsystem::Get(PLATFORM_SOCKETSUBSYSTEM);
        if (SocketHandle) {
            Subsystem->DestroySocket(SocketHandle);
        }
    }

    bool IsValid() const {
        return SocketHandle != nullptr;
    }

    bool Setup(uint32 PortNumber) {
        ISocketSubsystem* Subsystem = ISocketSubsystem::Get(PLATFORM_SOCKETSUBSYSTEM);
        bool Result = false;

        // Acquire local binding address
        LocalAddress = Subsystem->GetLocalBindAddr(*GWarn);
        LocalAddress->SetPort(PortNumber);

        // Prepare broadcast destination
        TargetAddress = Subsystem->CreateInternetAddr(LocalAddress->GetProtocolType());
        TargetAddress->SetBroadcastAddress();
        TargetAddress->SetPort(PortNumber);

        // Create datagram socket
        SocketHandle = Subsystem->CreateSocket(NAME_DGram, TEXT("LAN Discovery"), LocalAddress->GetProtocolType());
        if (SocketHandle != nullptr) {
            SocketHandle->SetReuseAddr();
            SocketHandle->SetNonBlocking();
            SocketHandle->SetRecvErr();

            // Bind to local port
            if (SocketHandle->Bind(*LocalAddress)) {
                Result = SocketHandle->SetBroadcast();
            } else {
                UE_LOG_ONLINE(Error, TEXT("Binding failed for LAN discovery on %s"),
                    *LocalAddress->ToString(true));
            }
        } else {
            UE_LOG_ONLINE(Error, TEXT("Could not create LAN discovery socket"));
        }

        return Result && SocketHandle;
    }

    int32 FetchPacket(uint8* Buffer, int32 Capacity) {
        check(Buffer && Capacity > 0);
        int32 BytesReceived = 0;

        if (SocketHandle != nullptr) {
            SocketHandle->RecvFrom(Buffer, Capacity, BytesReceived, *RemoteEndpoint);
            if (BytesReceived > 0) {
                UE_LOG_ONLINE(Verbose, TEXT("Received %d bytes from %s"), 
                    BytesReceived, *RemoteEndpoint->ToString(true));
            }
        }
        return BytesReceived;
    }

    bool SendToNetwork(const uint8* Data, int32 Size) {
        int32 BytesTransferred = 0;
        UE_LOG_ONLINE(Verbose, TEXT("Sending %d bytes to %s"), Size, *TargetAddress->ToString(true));
        bool SentSuccessfully = SocketHandle->SendTo(Data, Size, BytesTransferred, *TargetAddress);
        return SentSuccessfully && (BytesTransferred == Size);
    }
};

// Renamed class: FLANSession -> FLanServerFinder
class FLanServerFinder {
private:
    FLanDiscoverySocket* BeaconSocket;
    ELanBeaconState CurrentState;
    FGuid SessionIdentifier;
    TArray<uint8> RetryBuffer;

    float SearchDurationRemaining;
    float RetryIntervalRemaining;

    uint64 ClientChallengeValue;
    uint32 GameIdentifier;
    uint32 PacketPlatformMask;
    uint32 MaxPacketSize;
    float QueryTimeoutDuration;
    float RetryDelayDuration;

public:
    FLanServerFinder()
        : BeaconSocket(nullptr),
          CurrentState(ELanBeaconState::NotUsingLanBeacon),
          SessionIdentifier(FGuid::NewGuid()),
          SearchDurationRemaining(0.0f),
          RetryIntervalRemaining(0.0f),
          ClientChallengeValue(0),
          GameIdentifier(-1),
          PacketPlatformMask(0),
          MaxPacketSize(LAN_BEACON_MAX_PACKET_SIZE),
          QueryTimeoutDuration(5.0f),
          RetryDelayDuration(1.0f)
    {
    }

    ~FLanServerFinder() {
        Shutdown();
    }

    void Shutdown() {
        CurrentState = ELanBeaconState::NotUsingLanBeacon;
        if (BeaconSocket) {
            delete BeaconSocket;
            BeaconSocket = nullptr;
        }
        OnQueryPacketDelegates.Clear();
        OnResponsePacketDelegates.Clear();
        OnSearchTimeoutDelegates.Clear();
        RetryBuffer.Empty();
        CachedResponses.Empty();
    }

    bool StartHosting(int32 AnnouncePort, FOnValidQueryPacketDelegate& Delegate) {
        bool Success = false;

        if (BeaconSocket != nullptr) {
            Shutdown();
        }

        SessionIdentifier = FGuid::NewGuid();
        BeaconSocket = new FLanDiscoverySocket();

        if (BeaconSocket->Setup(AnnouncePort)) {
            AddQueryDelegate(Delegate);
            CurrentState = ELanBeaconState::Hosting;
            Success = true;
            UE_LOG_ONLINE(Verbose, TEXT("Listening for LAN queries on port %d"), AnnouncePort);
        } else {
            UE_LOG_ONLINE(Warning, TEXT("Failed to initialize LAN discovery socket %s"),
                ISocketSubsystem::Get(PLATFORM_SOCKETSUBSYSTEM)->GetSocketError());
        }

        return Success;
    }

    bool InitiateSearch(FNboSerializeToBuffer& RequestPacket, 
                        FOnValidResponsePacketDelegate& ResponseHandler,
                        FOnSearchingTimeoutDelegate& TimeoutHandler) {
        bool Success = true;

        if (BeaconSocket != nullptr) {
            Shutdown();
        }

        SessionIdentifier = FGuid::NewGuid();
        CachedResponses.Reset();

        BeaconSocket = new FLanDiscoverySocket();
        if (!BeaconSocket->Setup(LanAnnouncePort)) {
            UE_LOG_ONLINE(Warning, TEXT("Socket creation failed for port %d: %s"),
                LanAnnouncePort,
                ISocketSubsystem::Get(PLATFORM_SOCKETSUBSYSTEM)->GetSocketError());
            Success = false;
        }

        if (BeaconSocket && Success) {
            if (BeaconSocket->SendToNetwork(RequestPacket.GetBuffer().GetData(), RequestPacket.GetByteCount())) {
                UE_LOG_ONLINE(Verbose, TEXT("Discovery packet transmitted"));

                CurrentState = ELanBeaconState::Searching;
                SearchDurationRemaining = QueryTimeoutDuration;
                RetryBuffer.Reset();
                RetryBuffer.Append(RequestPacket.GetBuffer().GetData(), RequestPacket.GetByteCount());
                RetryIntervalRemaining = RetryDelayDuration;

                AddResponseDelegate(ResponseHandler);
                AddTimeoutDelegate(TimeoutHandler);
            } else {
                UE_LOG_ONLINE(Warning, TEXT("Failed to send discovery broadcast: %s"),
                    ISocketSubsystem::Get(PLATFORM_SOCKETSUBSYSTEM)->GetSocketError());
                Success = false;
            }
        }

        return Success;
    }

    void Update(float DeltaTime) {
        if (CurrentState == ELanBeaconState::NotUsingLanBeacon) {
            return;
        }

        uint8 PacketData[MaxPacketSize];
        bool ContinueReading = true;

        while (ContinueReading) {
            int32 BytesAvailable = BeaconSocket ? BeaconSocket->FetchPacket(PacketData, MaxPacketSize) : 0;

            if (BytesAvailable > 0) {
                switch (CurrentState) {
                    case ELanBeaconState::Hosting:
                        uint64 ChallengeValue;
                        if (ValidateIncomingQuery(PacketData, BytesAvailable, ChallengeValue)) {
                            TriggerQueryDelegates(&PacketData[LAN_BEACON_PACKET_HEADER_SIZE], 
                                BytesAvailable - LAN_BEACON_PACKET_HEADER_SIZE, ChallengeValue);
                        }
                        break;

                    case ELanBeaconState::Searching:
                        FGuid ResponseIdentifier;
                        if (ValidateIncomingResponse(PacketData, BytesAvailable, ResponseIdentifier)) {
                            bool bIsDuplicate = false;
                            CachedResponses.Add(ResponseIdentifier, &bIsDuplicate);
                            if (!bIsDuplicate) {
                                TriggerResponseDelegates(&PacketData[LAN_BEACON_PACKET_HEADER_SIZE],
                                    BytesAvailable - LAN_BEACON_PACKET_HEADER_SIZE);
                            }
                        }
                        break;
                }
            } else {
                if (CurrentState == ELanBeaconState::Searching) {
                    RetryIntervalRemaining -= DeltaTime;

                    if (BeaconSocket && (RetryIntervalRemaining <= 0.0f) && (SearchDurationRemaining > RetryDelayDuration)) {
                        if (BeaconSocket->SendToNetwork(RetryBuffer.GetData(), RetryBuffer.Num())) {
                            UE_LOG_ONLINE(Verbose, TEXT("Retransmitted discovery packet"));
                        } else {
                            UE_LOG_ONLINE(Warning, TEXT("Retry transmission failed: %s"),
                                ISocketSubsystem::Get(PLATFORM_SOCKETSUBSYSTEM)->GetSocketError());
                        }
                        RetryIntervalRemaining = RetryDelayDuration;
                    }

                    SearchDurationRemaining -= DeltaTime;
                    if (SearchDurationRemaining <= 0.0f) {
                        TriggerTimeoutDelegates();
                    }
                }
                ContinueReading = false;
            }
        }
    }

    void GenerateHostResponse(FNboSerializeToBuffer& Output, uint64 ClientNonce) {
        Output << LAN_BEACON_PACKET_VERSION
               << (uint8)FPlatformProperties::IsLittleEndian()
               << GameIdentifier
               << LAN_SERVER_RESPONSE1 << LAN_SERVER_RESPONSE2
               << ClientNonce
               << SessionIdentifier;
    }

    void GenerateClientRequest(FNboSerializeToBuffer& Output, uint64 ClientNonce) {
        Output << LAN_BEACON_PACKET_VERSION
               << (uint8)FPlatformProperties::IsLittleEndian()
               << GameIdentifier
               << LAN_SERVER_QUERY1 << LAN_SERVER_QUERY2
               << ClientNonce
               << SessionIdentifier;
    }

    bool TransmitPacket(const uint8* Data, int32 Size) {
        bool Result = false;
        if (BeaconSocket) {
            Result = BeaconSocket->SendToNetwork(Data, Size);
            if (!Result) {
                UE_LOG_ONLINE(Warning, TEXT("Broadcast error code: %d"), 
                    (int32)ISocketSubsystem::Get(PLATFORM_SOCKETSUBSYSTEM)->GetLastErrorCode());
            }
        }
        return Result;
    }

    bool ValidateIncomingQuery(const uint8* Data, uint32 Size, uint64& OutChallenge) {
        OutChallenge = 0;
        bool Valid = false;

        if (Size == LAN_BEACON_PACKET_HEADER_SIZE) {
            FNboSerializeFromBuffer Reader(Data, Size);
            uint8 Version = 0;
            Reader >> Version;

            if (Version == LAN_BEACON_PACKET_VERSION) {
                uint8 Platform = 255;
                Reader >> Platform;

                if (Platform & PacketPlatformMask) {
                    int32 GameId = -1;
                    Reader >> GameId;

                    if (GameId == GameIdentifier) {
                        uint8 SQ1 = 0, SQ2 = 0;
                        Reader >> SQ1 >> SQ2;

                        Valid = (SQ1 == LAN_SERVER_QUERY1 && SQ2 == LAN_SERVER_QUERY2);
                        Reader >> OutChallenge;

                        FGuid BeaconId;
                        Reader >> BeaconId;
                    }
                }
            }
        }
        return Valid;
    }

    bool ValidateIncomingResponse(const uint8* Data, uint32 Size, FGuid& OutIdentifier) {
        bool Valid = false;

        if (Size > LAN_BEACON_PACKET_HEADER_SIZE) {
            FNboSerializeFromBuffer Reader(Data, Size);
            uint8 Version = 0;
            Reader >> Version;

            if (Version == LAN_BEACON_PACKET_VERSION) {
                uint8 Platform = 255;
                Reader >> Platform;

                if (Platform & PacketPlatformMask) {
                    int32 GameId = -1;
                    Reader >> GameId;

                    if (GameId == GameIdentifier) {
                        uint8 SQ1 = 0, SQ2 = 0;
                        Reader >> SQ1 >> SQ2;

                        if (SQ1 == LAN_SERVER_RESPONSE1 && SQ2 == LAN_SERVER_RESPONSE2) {
                            uint64 Nonce = 0;
                            Reader >> Nonce;

                            if (Nonce == ClientChallengeValue) {
                                FGuid BeaconId;
                                Reader >> BeaconId;
                                Valid = !Reader.HasOverflow();
                                if (Valid) {
                                    OutIdentifier = BeaconId;
                                }
                            }
                        }
                    }
                }
            }
        }
        return Valid;
    }

private:
    TMap<FGuid, bool> CachedResponses;

    void AddQueryDelegate(FOnValidQueryPacketDelegate& Delegate) {
        OnQueryPacketDelegates.Add(Delegate);
    }

    void AddResponseDelegate(FOnValidResponsePacketDelegate& Delegate) {
        OnResponsePacketDelegates.Add(Delegate);
    }

    void AddTimeoutDelegate(FOnSearchingTimeoutDelegate& Delegate) {
        OnSearchTimeoutDelegates.Add(Delegate);
    }

    void TriggerQueryDelegates(const uint8* Data, int32 Length, uint64 Nonce) {
        OnQueryPacketDelegates.ExecuteIfBound(Data, Length, Nonce);
    }

    void TriggerResponseDelegates(const uint8* Data, int32 Length) {
        OnResponsePacketDelegates.ExecuteIfBound(Data, Length);
    }

    void TriggerTimeoutDelegates() {
        OnSearchTimeoutDelegates.ExecuteIfBound();
    }
};

