/// Helper macro to reduce repetition in angle comparisons
#define EXPECT_ANGLE_NEAR(expected, actual, tolerance) \
    EXPECT_NEAR(toDeg((actual)), (expected), (tolerance))

/// @test
/// Verify default-initialized quaternion has correct components
/// @requirements(SEN-1060)
TEST(QuaternionTest, initialization)
{
  Quatd q {};
  EXPECT_DOUBLE_EQ(q.getX(), 0.0);
  EXPECT_DOUBLE_EQ(q.getY(), 0.0);
  EXPECT_DOUBLE_EQ(q.getZ(), 0.0);
  EXPECT_DOUBLE_EQ(q.getW(), 1.0);
}

/// @test
/// Validate rotation generation via axis-angle input
/// @requirements(SEN-1060)
TEST(QuaternionTest, rotation)
{
  Quatd q {};
  EXPECT_DOUBLE_EQ(q.getX(), 0.0);
  EXPECT_DOUBLE_EQ(q.getY(), 0.0);
  EXPECT_DOUBLE_EQ(q.getZ(), 0.0);
  EXPECT_DOUBLE_EQ(q.getW(), 1.0);

  q.makeRotate(pi, Vec3d{1.0, 0.0, 0.0});
  EXPECT_NEAR(q.getX(), 1.0, 0.005);
  EXPECT_NEAR(q.getY(), 0.0, 0.005);
  EXPECT_NEAR(q.getZ(), 0.0, 0.005);
  EXPECT_NEAR(q.getW(), 0.0, 0.005);

  q.makeRotate(pi / 2.0, Vec3d{0.0, 1.0, 0.0});
  EXPECT_NEAR(q.getX(), 0.707, 0.005);
  EXPECT_NEAR(q.getY(), 0.0, 0.005);
  EXPECT_NEAR(q.getZ(), -0.707, 0.005);
  EXPECT_NEAR(q.getW(), 0.0, 0.005);
}

/// @test
/// Test Euler angle conversion and construction from yaw-pitch-bank angles
/// @requirements(SEN-1060)
TEST(QuaternionTest, eulerOperations)
{
  // Case 1: Rotation about Z-axis by 30 degrees
  Quat q1 = Quat<f64>(0, 0, toRad(30.0));
  EXPECT_NEAR(q1.getX(), 0.2588, 0.005);
  EXPECT_NEAR(q1.getY(), 0.0, 0.005);
  EXPECT_NEAR(q1.getZ(), 0.0, 0.005);
  EXPECT_NEAR(q1.getW(), 0.9659, 0.005);

  auto eul1 = q1.getRotateInEulerYPB();
  EXPECT_ANGLE_NEAR(0.0, eul1.getX(), 0.005);
  EXPECT_ANGLE_NEAR(0.0, eul1.getY(), 0.005);
  EXPECT_ANGLE_NEAR(30.0, eul1.getZ(), 0.005);

  // Case 2: Rotate 60° around X-axis → should yield ~90° Yaw (Z-axis in YPB convention)
  Quat q2;
  q2.makeRotate(toRad(60.0), 1.0, 0.0, 0.0);
  auto eul2 = q2.getRotateInEulerYPB();
  EXPECT_ANGLE_NEAR(0.0, eul2.getX(), 0.005);
  EXPECT_ANGLE_NEAR(0.0, eul2.getY(), 0.005);
  EXPECT_ANGLE_NEAR(90.0, eul2.getZ(), 0.005);

  // Case 3: Rotation about Y-axis by 30 degrees
  Quat q3 = Quat<f64>(0, toRad(30.0), 0);
  EXPECT_NEAR(q3.getX(), 0.0, 0.005);
  EXPECT_NEAR(q3.getY(), 0.2588, 0.005);
  EXPECT_NEAR(q3.getZ(), 0.0, 0.005);
  EXPECT_NEAR(q3.getW(), 0.9659, 0.005);
}

/// @test
/// Ensure normalized quaternions maintain unit length
/// @requirements(SEN-1060)
TEST(QuaternionTest, length)
{
  Quat q1 = Quat<f64>(0, 0, toRad(15.0));
  EXPECT_NEAR(q1.length(), 1.0, 0.00001);
  EXPECT_NEAR(q1.length2(), 1.0, 0.00001);

  Quat q2 = Quat<f64>(toRad(60.0), toRad(22.0), toRad(15.0));
  EXPECT_NEAR(q2.length(), 1.0, 0.00001);
  EXPECT_NEAR(q2.length2(), 1.0, 0.00001);
}

/// @test
/// Validate conjugate operation and its effect on Euler representation
/// @requirements(SEN-1060)
TEST(QuaternionTest, conjugate)
{
  Quat q = Quat<f64>(0, toRad(60.0), toRad(15.0));
  q = q.conj();
  auto eul = q.getRotateInEulerYPB();

  EXPECT_NEAR(toDeg(eul.getX()), 24.146, 0.001);
  EXPECT_NEAR(toDeg(eul.getY()), -56.774, 0.001);
  EXPECT_NEAR(toDeg(eul.getZ()), -28.186, 0.001);
}

/// @test
/// Confirm inverse yields same result as conjugate for unit quaternions
/// @requirements(SEN-1060)
TEST(QuaternionTest, inverse)
{
  Quat q = Quat<f64>(0, toRad(60.0), toRad(15.0));
  q = q.inverse();
  auto eul = q.getRotateInEulerYPB();

  EXPECT_NEAR(toDeg(eul.getX()), 24.146, 0.001);
  EXPECT_NEAR(toDeg(eul.getY()), -56.774, 0.001);
  EXPECT_NEAR(toDeg(eul.getZ()), -28.186, 0.001);
}

/// @test
/// Interpolate between two quaternions using spherical linear interpolation
/// @requirements(SEN-1060)
TEST(QuaternionTest, slerp)
{
  Quat start = Quat<f64>(0, 0, toRad(15.0));
  Quat end   = Quat<f64>(0, 0, toRad(55.0));
  Quat mid;

  mid.slerp(0.1, start, end);
  auto eul1 = mid.getRotateInEulerYPB();
  EXPECT_ANGLE_NEAR(19.0, eul1.getZ(), 0.001);

  mid.slerp(0.2, start, end);
  auto eul2 = mid.getRotateInEulerYPB();
  EXPECT_ANGLE_NEAR(23.0, eul2.getZ(), 0.001);
}

