#include <gtest/gtest.h>
#include <iostream>
#include <ocs2_core/misc/LinearInterpolation.h>
#include <Eigen/Dense>

namespace {

// Helper to print test data for debugging
void printTestData(const std::vector<double>& times, const std::vector<Eigen::Matrix<double, 2, 1>, Eigen::aligned_allocator<Eigen::Matrix<double, 2, 1>>>& values) {
    std::cout << "TEST DATA" << std::endl;
    for (size_t k = 0; k < times.size(); ++k) {
        std::cout << "time: " << times[k] << " v: " << values[k].transpose() << std::endl;
    }
}

// Generic interpolation test helper
void runInterpolationTest(
    double queryTime,
    int expectedIndex,
    double expectedValue,
    const std::vector<double>& timePoints,
    const std::vector<Eigen::Matrix<double, 2, 1>, Eigen::aligned_allocator<Eigen::Matrix<double, 2, 1>>>& dataPoints
) {
    auto indexAlphaPair = ocs2::LinearInterpolation::timeSegment(queryTime, timePoints);
    auto interpolatedValue = ocs2::LinearInterpolation::interpolate(indexAlphaPair, dataPoints);

    int foundIndex = indexAlphaPair.first;
    double alpha = indexAlphaPair.second;

    std::cout << "time: " << queryTime << " index: " << foundIndex << " v: " << interpolatedValue.transpose()
              << " alpha: " << alpha << std::endl;

    EXPECT_EQ(foundIndex, expectedIndex);
    EXPECT_DOUBLE_EQ(interpolatedValue(0), expectedValue);
    ASSERT_TRUE(std::isfinite(alpha));
    ASSERT_GE(alpha, 0.0);
    ASSERT_LE(alpha, 1.0);
}

} // namespace

TEST(testLinearInterpolation, testInterpolation) {
    using Vector2d = Eigen::Matrix<double, 2, 1>;

    std::vector<double> timeVec = {0.0, 1.0, 2.0, 3.0, 3.0, 4.0};
    std::vector<Vector2d, Eigen::aligned_allocator<Vector2d>> valueVec;
    for (const auto& t_k : timeVec) {
        valueVec.emplace_back(t_k * Vector2d::Ones());
    }

    printTestData(timeVec, valueVec);

    // Before start
    runInterpolationTest(-1.0, 0, 0.0, timeVec, valueVec);

    // At start
    runInterpolationTest(timeVec[0], 0, timeVec[0], timeVec, valueVec);

    // First interval - off center
    double t01_offcenter = 0.25 * timeVec[0] + 0.75 * timeVec[1];
    runInterpolationTest(t01_offcenter, 0, t01_offcenter, timeVec, valueVec);

    // First interval - midpoint
    double t01_mid = 0.5 * timeVec[0] + 0.5 * timeVec[1];
    runInterpolationTest(t01_mid, 0, t01_mid, timeVec, valueVec);

    // Boundary to second interval (same as t[1])
    runInterpolationTest(timeVec[1], 0, timeVec[1], timeVec, valueVec);

    // Event time (duplicate at index 3)
    runInterpolationTest(timeVec[3], 2, timeVec[3], timeVec, valueVec);

    // Last interval (between duplicate and next)
    double t45_mid = 0.5 * timeVec[4] + 0.5 * timeVec[5];
    runInterpolationTest(t45_mid, 4, t45_mid, timeVec, valueVec);

    // At end
    runInterpolationTest(timeVec.back(), 4, timeVec.back(), timeVec, valueVec);

    // Beyond end
    runInterpolationTest(timeVec.back() + 1.0, 4, timeVec.back(), timeVec, valueVec);
}

TEST(testLinearInterpolation, testEventTimeInterpolation) {
    {  // Only an event (identical times)
        std::vector<double> eventTimes{1.0, 1.0};
        auto indexAlpha = ocs2::LinearInterpolation::timeSegment(1.0, eventTimes);
        ASSERT_EQ(indexAlpha.first, 0);
        ASSERT_TRUE(std::isfinite(indexAlpha.second));
        ASSERT_GE(indexAlpha.second, 0.0);
        ASSERT_LE(indexAlpha.second, 1.0);
    }

    {  // Short time between samples near event
        constexpr auto eps = ocs2::numeric_traits::weakEpsilon<ocs2::scalar_t>();
        std::vector<double> sampleTimes{0.0, 1.0, 1.0 + eps, 2.0};

        // Left side of duplicate: should use segment [1, 1+eps], fully right → alpha=1.0
        auto lhsAlpha = ocs2::LinearInterpolation::timeSegment(1.0 + 0.1 * eps, sampleTimes);
        ASSERT_EQ(lhsAlpha.first, 1);
        ASSERT_DOUBLE_EQ(lhsAlpha.second, 1.0);

        // Right side of duplicate: should use segment [1, 1+eps], fully left → alpha=0.0
        auto rhsAlpha = ocs2::LinearInterpolation::timeSegment(1.0 + 0.9 * eps, sampleTimes);
        ASSERT_EQ(rhsAlpha.first, 1);
        ASSERT_DOUBLE_EQ(rhsAlpha.second, 0.0);
    }
}

TEST(testLinearInterpolation, testSizeOneTime) {
    using Vector2d = Eigen::Matrix<double, 2, 1>;

    std::vector<double> singleTime{1.0};
    std::vector<Vector2d, Eigen::aligned_allocator<Vector2d>> singleValue;
    for (const auto& t_k : singleTime) {
        singleValue.emplace_back(t_k * Vector2d::Ones());
    }

    printTestData(singleTime, singleValue);

    // Before time
    runInterpolationTest(-1.0, 0, 1.0, singleTime, singleValue);

    // Beyond time
    runInterpolationTest(2.0, 0, 1.0, singleTime, singleValue);
}

TEST(testLinearInterpolation, testDifferentEigenSizes) {
    using MatrixX = Eigen::MatrixXd;

    std::vector<double> times = {0.0, 1.0};
    std::vector<MatrixX, Eigen::aligned_allocator<MatrixX>> data = {
        MatrixX::Zero(2, 3),
        MatrixX::Ones(4, 4)
    };

    MatrixX result;

    result = ocs2::LinearInterpolation::interpolate(0.4, times, data);
    EXPECT_TRUE(result.isApprox(data[0]));

    result = ocs2::LinearInterpolation::interpolate(0.6, times, data);
    EXPECT_TRUE(result.isApprox(data[1]));

    result = ocs2::LinearInterpolation::interpolate(-0.1, times, data);
    EXPECT_TRUE(result.isApprox(data[0]));

    result = ocs2::LinearInterpolation::interpolate(1.1, times, data);
    EXPECT_TRUE(result.isApprox(data[1]));
}

