C4JStorage::EMessageResult ConsoleUIController::RequestMessageBox(UINT titleId, UINT messageId, UINT *optionIds, UINT optionCount, DWORD padIndex,
                        int(*callbackFunction)(LPVOID,int,const C4JStorage::EMessageResult), LPVOID callbackParam, 
                        CXuiStringTable *stringTable, WCHAR *formatString, DWORD focusButton, bool isError)
