// Request message box with default values for UGC-related messages
C4JStorage::EMessageResult ConsoleUIController::RequestUGCMessageBox(UINT title/* = -1 */, UINT message/* = -1 */, int playerIndex/* = -1*/, 
                        int(*callbackFunction)(LPVOID,int,const C4JStorage::EMessageResult)/* = NULL*/, LPVOID callbackParam/* = NULL*/)
{
    // Use default strings if not specified
    if (title == -1)
    {
        title = IDS_CONNECTION_FAILED;
    }
    if (message == -1)
    {
        message = IDS_NO_USER_CREATED_CONTENT_PRIVILEGE_SINGLE_LOCAL;
    }

    // Default to primary player if not specified
    if (playerIndex == -1) 
        playerIndex = ProfileManager.GetPrimaryPad();

    UINT optionIds[1];
    optionIds[0] = IDS_CONFIRM_OK;

    return ui.RequestMessageBox(title, message, optionIds, 1, playerIndex, callbackFunction, callbackParam, app.GetStringTable(), NULL, 0, false);
}

