#include <iostream>
#include <windows.h>
#include <GL/gl.h>
#include <tchar.h>

// Redefine some constants to avoid dependency on specific headers
#ifndef CS_OWNDC
#define CS_OWNDC 0x0002
#endif

// Data structures
struct OpenGLContextData {
    HDC hDC;
};

// Global state variables
static HGLRC g_OpenGLRenderingContext = nullptr;
static OpenGLContextData g_MainWindowContext;
static int g_WindowWidth = 1280;
static int g_WindowHeight = 800;

// Function declarations
bool InitializeOpenGLContext(HWND hwnd, OpenGLContextData* context);
void CleanupOpenGLContext(HWND hwnd, OpenGLContextData* context);
void SwapWindowBuffers(OpenGLContextData* context);
LRESULT CALLBACK WindowProcedure(HWND hwnd, UINT message, WPARAM wParam, LPARAM lParam);

// Helper function to create OpenGL context
bool InitializeOpenGLContext(HWND hwnd, OpenGLContextData* context) {
    HDC hdc = GetDC(hwnd);

    PIXELFORMATDESCRIPTOR pfd = {};
    pfd.nSize = sizeof(pfd);
    pfd.nVersion = 1;
    pfd.dwFlags = PFD_DRAW_TO_WINDOW | PFD_SUPPORT_OPENGL | PFD_DOUBLEBUFFER;
    pfd.iPixelType = PFD_TYPE_RGBA;
    pfd.cColorBits = 32;

    int pixelFormat = ChoosePixelFormat(hdc, &pfd);
    if (pixelFormat == 0) {
        ReleaseDC(hwnd, hdc);
        return false;
    }

    if (!SetPixelFormat(hdc, pixelFormat, &pfd)) {
        ReleaseDC(hwnd, hdc);
        return false;
    }

    ReleaseDC(hwnd, hdc);

    // Create rendering context
    if (!g_OpenGLRenderingContext) {
        g_OpenGLRenderingContext = wglCreateContext(context->hDC);
    }

    return true;
}

// Helper function to clean up OpenGL resources
void CleanupOpenGLContext(HWND hwnd, OpenGLContextData* context) {
    if (g_OpenGLRenderingContext) {
        wglMakeCurrent(nullptr, nullptr);
        wglDeleteContext(g_OpenGLRenderingContext);
        g_OpenGLRenderingContext = nullptr;
    }

    if (context && context->hDC) {
        ReleaseDC(hwnd, context->hDC);
        context->hDC = nullptr;
    }
}

// Helper function to swap buffers
void SwapWindowBuffers(OpenGLContextData* context) {
    if (context && context->hDC) {
        ::SwapBuffers(context->hDC);
    }
}

// Main entry point
int WINAPI WinMain(HINSTANCE hInstance, HINSTANCE hPrevInstance, LPSTR lpCmdLine, int nCmdShow) {
    // Register window class
    WNDCLASSEXW wc = {};
    wc.cbSize = sizeof(WNDCLASSEXW);
    wc.style = CS_OWNDC;
    wc.lpfnWndProc = WindowProcedure;
    wc.hInstance = hInstance;
    wc.lpszClassName = L"OpenGL_DearImGui_Window";
    wc.hCursor = LoadCursor(nullptr, IDC_ARROW);

    ATOM registeredClass = RegisterClassExW(&wc);
    if (!registeredClass) {
        return 1;
    }

    // Calculate window size with borders
    RECT rect = { 0, 0, g_WindowWidth, g_WindowHeight };
    AdjustWindowRect(&rect, WS_OVERLAPPEDWINDOW, FALSE);

    // Create main window
    HWND hwnd = CreateWindowW(
        wc.lpszClassName,
        L"Dear ImGui OpenGL Example",
        WS_OVERLAPPEDWINDOW,
        CW_USEDEFAULT, CW_USEDEFAULT,
        rect.right - rect.left,
        rect.bottom - rect.top,
        nullptr, nullptr,
        hInstance,
        nullptr
    );

    if (!hwnd) {
        UnregisterClassW(wc.lpszClassName, hInstance);
        return 1;
    }

    // Initialize OpenGL context
    g_MainWindowContext.hDC = GetDC(hwnd);
    if (!InitializeOpenGLContext(hwnd, &g_MainWindowContext)) {
        CleanupOpenGLContext(hwnd, &g_MainWindowContext);
        DestroyWindow(hwnd);
        UnregisterClassW(wc.lpszClassName, hInstance);
        return 1;
    }

    // Show and update window
    ShowWindow(hwnd, SW_SHOWNORMAL);
    UpdateWindow(hwnd);

    // Set up OpenGL viewport
    glViewport(0, 0, g_WindowWidth, g_WindowHeight);

    // Clear color setup
    ImVec4 clear_color = ImVec4(0.45f, 0.55f, 0.60f, 1.00f);

    // Main loop
    bool isRunning = true;
    while (isRunning) {
        // Process messages
        MSG msg;
        while (PeekMessage(&msg, nullptr, 0, 0, PM_REMOVE)) {
            TranslateMessage(&msg);
            DispatchMessage(&msg);

            if (msg.message == WM_QUIT) {
                isRunning = false;
            }
        }

        if (!isRunning) break;

        // Render frame
        glClearColor(clear_color.x, clear_color.y, clear_color.z, clear_color.w);
        glClear(GL_COLOR_BUFFER_BIT);

        // Draw a simple colored rectangle as placeholder for Dear ImGui rendering
        glBegin(GL_QUADS);
        glColor3f(0.2f, 0.6f, 0.9f);
        glVertex2f(-0.8f, -0.8f);
        glVertex2f(0.8f, -0.8f);
        glVertex2f(0.8f, 0.8f);
        glVertex2f(-0.8f, 0.8f);
        glEnd();

        // Present frame
        SwapWindowBuffers(&g_MainWindowContext);

        // Small delay to prevent excessive CPU usage
        Sleep(1);
    }

    // Cleanup
    CleanupOpenGLContext(hwnd, &g_MainWindowContext);
    DestroyWindow(hwnd);
    UnregisterClassW(wc.lpszClassName, hInstance);

    return 0;
}

// Window procedure
LRESULT CALLBACK WindowProcedure(HWND hwnd, UINT message, WPARAM wParam, LPARAM lParam) {
    switch (message) {
        case WM_SIZE:
            if (wParam != SIZE_MINIMIZED) {
                g_WindowWidth = LOWORD(lParam);
                g_WindowHeight = HIWORD(lParam);
                glViewport(0, 0, g_WindowWidth, g_WindowHeight);
            }
            return 0;

        case WM_DESTROY:
            PostQuitMessage(0);
            return 0;

        default:
            return DefWindowProcW(hwnd, message, wParam, lParam);
    }
}

