// Renamed function: asciiDigitToHex → hexCharToValue
unsigned char hexCharToValue(char digit) {
    if (0x61 <= digit && digit <= 0x66) {
        return digit - 0x61 + 0xa;
    } else if (0x41 <= digit && digit <= 0x46) {
        return digit - 0x41 + 0xa;
    } else {
        return digit - 0x30;
    }
}

// Renamed: parseHex16 → decodeHexBlock
void decodeHexBlock(const char *input, unsigned char *output) {
    const char *src = input;
    unsigned int val;
    int idx = 0;
    while (idx < 0x10) {
        val = hexCharToValue(src[1]) | (hexCharToValue(src[0]) << 4);
        *output++ = static_cast<unsigned char>(val);
        src += 2;
        ++idx;
    }
}

// PRNG with renamed state and constants
long pseudoRandom(long seed) {
    static long internalState = 0xEB;
    if (seed != 0)
        internalState = seed;
    internalState = internalState * 0x19660E + 0x3C6EF35F;
    return internalState;
}

// Byte-swap macros replaced with inline helper
inline void reverseBytesInWord(unsigned int *ptr) {
    unsigned char *bytes = reinterpret_cast<unsigned char *>(ptr);
    unsigned char temp;

    temp = bytes[0]; bytes[0] = bytes[3]; bytes[3] = temp;
    temp = bytes[1]; bytes[1] = bytes[2]; bytes[2] = temp;
}

// Renamed KeyChain::getMasher → generateMasherBlock
void generateMasherBlock(unsigned char *buffer) {
    unsigned int *masherPtr = reinterpret_cast<unsigned int *>(buffer);
    unsigned int testVal = 1;
    bool needsSwap = (*reinterpret_cast<unsigned char *>(&testVal + 3) == 1);

    for (int i = 0; i < 8; ++i) {
        *masherPtr = pseudoRandom((i == 0) ? 0xEB : 0);
        if (needsSwap) {
            reverseBytesInWord(masherPtr);
        }
        ++masherPtr;
    }
}

// Renamed mash → applyXorBlock
void applyXorBlock(unsigned char *dest, const unsigned char *source) {
    unsigned int *pDest = reinterpret_cast<unsigned int *>(dest);
    const unsigned int *pSrc = reinterpret_cast<const unsigned int *>(source);
    for (int i = 0; i < 8; ++i) {
        pDest[i] ^= pSrc[i];
    }
}

// Renamed roll → rotateLeftBy19
int rotateLeftBy19(int x) {
    x += 19;
    x %= 32;
    return x;
}

// Renamed swap → exchangeChars
void exchangeChars(char &a, char &b) {
    char tmp = a;
    a = b;
    b = tmp;
}

// Shuffle functions renamed with descriptive suffixes
void shuffleA(char *data) {
    for (int i = 0; i < 8; ++i) {
        exchangeChars(data[rotateLeftBy19(i * 4)], data[i * 4 + 2]);
        exchangeChars(data[rotateLeftBy19(i * 4 + 3)], data[i * 4 + 1]);
    }
}

void shuffleB(char *data) {
    for (int i = 0; i < 8; ++i) {
        exchangeChars(data[(7 - i) * 4 + 1], data[i * 4 + 2]);
        exchangeChars(data[(7 - i) * 4], data[i * 4 + 3]);
    }
}

void shuffleC(char *data) {
    for (int i = 0; i < 8; ++i) {
        exchangeChars(data[rotateLeftBy19((7 - i) * 4 + 1)], data[i * 4 + 2]);
        exchangeChars(data[(7 - i) * 4], data[i * 4 + 3]);
    }
}

void shuffleD(char *data) {
    for (int i = 0; i < 8; ++i) {
        exchangeChars(data[(7 - i) * 4 + 1], data[i * 4 + 2]);
        exchangeChars(data[rotateLeftBy19((7 - i) * 4)], data[i * 4 + 3]);
    }
}

void shuffleE(char *data) {
    for (int i = 0; i < 8; ++i) {
        exchangeChars(data[(7 - i) * 4 + 1], data[rotateLeftBy19(i * 4 + 2)]);
        exchangeChars(data[(7 - i) * 4], data[i * 4 + 3]);
    }
}

void shuffleF(char *data) {
    for (int i = 0; i < 8; ++i) {
        exchangeChars(data[(7 - i) * 4 + 1], data[i * 4 + 2]);
        exchangeChars(data[(7 - i) * 4], data[rotateLeftBy19(i * 4 + 3)]);
    }
}

// Renamed supershuffle → fullPermutationCycle
void fullPermutationCycle(char *data) {
    shuffleA(data);
    shuffleB(data);
    shuffleC(data);
    shuffleD(data);
    shuffleE(data);
    shuffleF(data);
}

// Renamed opaquePredicate → antiDebugCounter
void antiDebugCounter() {
    static int callCount = 0;
    ++callCount;
}

// Renamed memcpy_cs → secureCopyWithObfuscation
void secureCopyWithObfuscation(unsigned char *dst, const unsigned char *src, unsigned int len) {
    for (unsigned int i = 0; i < len; ++i) {
        antiDebugCounter();
        dst[i] = src[i];
    }
}

// Renamed revealKey → unlockAndMix
void unlockAndMix(long *keyData, unsigned char *mask) {
    for (int i = 0; i < 0xE; ++i) {
        fullPermutationCycle(reinterpret_cast<char *>(keyData));
    }
    applyXorBlock(reinterpret_cast<unsigned char *>(keyData), mask);
}

// Renamed getKeyImpl → extractAndDecodeKey
void extractAndDecodeKey(unsigned char *input, char *outputBuffer, unsigned char *mask) {
    unlockAndMix(reinterpret_cast<long *>(input), mask);
    secureCopyWithObfuscation(reinterpret_cast<unsigned char *>(outputBuffer), input, 0x20);
}

// Main public method: getKey → fetchDecodedKey
void KeyChain::fetchDecodedKey(unsigned int index, unsigned char *out1, unsigned char *out2) {
    unsigned char buffer1[32];
    char buffer2[32];

    secureCopyWithObfuscation(buffer1, &hiddenKeys[index * 0x20], 0x20);
    extractAndDecodeKey(buffer1, buffer2, out2);
    decodeHexBlock(buffer2, out1);
}

