/* Tunable guard frequency settings */
size_t opt_san_guard_large = SAN_GUARD_LARGE_EVERY_N_EXTENTS_DEFAULT;
size_t opt_san_guard_small = SAN_GUARD_SMALL_EVERY_N_EXTENTS_DEFAULT;

/* UAF detection alignment setting: -1 disables; otherwise >= LG_PAGE */
ssize_t opt_lg_san_uaf_align = SAN_LG_UAF_ALIGN_DEFAULT;

/*
 * Mask used to detect non-fast-path cache bin pointers.
 * Initialized in san_init(); set to all 1s when disabled.
 */
uintptr_t san_cache_bin_nonfast_mask = SAN_CACHE_BIN_NONFAST_MASK_DEFAULT;

// Helper: compute guarded address range based on placement flags
static inline void
san_compute_guarded_bounds(edata_t *edata, uintptr_t *out_left_guard,
    uintptr_t *out_right_guard, uintptr_t *out_base_addr,
    size_t unguarded_size, bool left_guard, bool right_guard) {
	assert(!edata_guarded_get(edata));
	assert(unguarded_size % PAGE == 0);

	*out_base_addr = (uintptr_t)edata_base_get(edata);

	if (left_guard) {
		*out_left_guard = *out_base_addr;
		*out_base_addr += SAN_PAGE_GUARD;
	} else {
		*out_left_guard = 0;
	}

	if (right_guard) {
		*out_right_guard = *out_base_addr + unguarded_size;
	} else {
		*out_right_guard = 0;
	}
}

// Helper: compute original (unguarded) address range from guarded edata
static inline void
san_compute_unguarded_bounds(edata_t *edata, uintptr_t *out_left_guard,
    uintptr_t *out_right_guard, uintptr_t *out_base_addr,
    size_t unguarded_size, bool left_guard, bool right_guard) {
	assert(edata_guarded_get(edata));
	assert(unguarded_size % PAGE == 0);

	uintptr_t base = (uintptr_t)edata_base_get(edata);
	*out_base_addr = base;

	if (right_guard) {
		*out_right_guard = base + unguarded_size;
	} else {
		*out_right_guard = 0;
	}

	if (left_guard) {
		*out_left_guard = base - SAN_PAGE_GUARD;
		assert(*out_left_guard != 0);
		*out_base_addr = *out_left_guard;
	} else {
		*out_left_guard = 0;
	}
}

// Guard pages in memory region described by edata
void
san_guard_pages(tsdn_t *tsdn, ehooks_t *ehooks, edata_t *edata, emap_t *emap,
    bool left, bool right, bool remap) {
	if (!(left || right)) {
		return;
	}

	if (remap) {
		emap_deregister_boundary(tsdn, emap, edata);
	}

	size_t raw_size = edata_size_get(edata);
	size_t usable_size = (left && right)
	    ? san_two_side_unguarded_sz(raw_size)
	    : san_one_side_unguarded_sz(raw_size);

	uintptr_t lg1 = 0, lg2 = 0, addr = 0;
	san_compute_guarded_bounds(edata, &lg1, &lg2, &addr, usable_size, left, right);

	assert(edata_state_get(edata) == extent_state_active);

	ehooks_guard(tsdn, ehooks, (void *)lg1, (void *)lg2);

	edata_size_set(edata, usable_size);
	edata_addr_set(edata, (void *)addr);
	edata_guarded_set(edata, true);

	if (remap) {
		emap_register_boundary(tsdn, emap, edata, SC_NSIZES,
		    /* slab */ false);
	}
}

// Internal unguard implementation (shared between normal and pre-destroy paths)
static void
san_unguard_pages_core(tsdn_t *tsdn, ehooks_t *ehooks, edata_t *edata,
    emap_t *emap, bool left, bool right, bool do_remap) {
	if (!(left || right)) {
		return;
	}

	if (do_remap) {
		assert(edata_state_get(edata) == extent_state_active);
		emap_deregister_boundary(tsdn, emap, edata);
	} else {
		assert(edata_state_get(edata) == extent_state_retained);
	}

	size_t current_usz = edata_size_get(edata);
	size_t full_size = (left && right)
	    ? san_two_side_guarded_sz(current_usz)
	    : san_one_side_guarded_sz(current_usz);

	uintptr_t lg1 = 0, lg2 = 0, addr = 0;
	san_compute_unguarded_bounds(edata, &lg1, &lg2, &addr, current_usz, left, right);

	ehooks_unguard(tsdn, ehooks, (void *)lg1, (void *)lg2);

	edata_size_set(edata, full_size);
	edata_addr_set(edata, (void *)addr);
	edata_guarded_set(edata, false);

	if (do_remap) {
		emap_register_boundary(tsdn, emap, edata, SC_NSIZES,
		    /* slab */ false);
	}
}

// Standard unguard with remapping
void
san_unguard_pages(tsdn_t *tsdn, ehooks_t *ehooks, edata_t *edata,
    emap_t *emap, bool left, bool right) {
	san_unguard_pages_core(tsdn, ehooks, edata, emap, left, right,
	    /* do_remap */ true);
}

// Pre-destroy unguard: skip remap, only unguard right side (per bump alloc)
void
san_unguard_pages_pre_destroy(tsdn_t *tsdn, ehooks_t *ehooks, edata_t *edata,
    emap_t *emap) {
	emap_assert_not_mapped(tsdn, emap, edata);

	san_unguard_pages_core(tsdn, ehooks, edata, emap,
	    /* left */ false, /* right */ true, /* do_remap */ false);
}

// Check if stashed pointer has been corrupted (UAF detection)
static bool
san_stashed_ptr_is_corrupted(void *ptr, size_t size) {
	if (san_junk_ptr_should_slow()) {
		const char *bytes = (const char *)ptr;
		for (size_t i = 0; i < size; ++i) {
			if (bytes[i] != (char)uaf_detect_junk) {
				return true;
			}
		}
		return false;
	}

	void *first, *mid, *last;
	san_junk_ptr_locations(ptr, size, &first, &mid, &last);

	return *(uintptr_t *)first != uaf_detect_junk ||
	       *(uintptr_t *)mid   != uaf_detect_junk ||
	       *(uintptr_t *)last  != uaf_detect_junk;
}

// Validate all stashed pointers for write-after-free
void
san_check_stashed_ptrs(void **ptrs, size_t count, size_t usize) {
	for (size_t idx = 0; idx < count; ++idx) {
		void *stashed = ptrs[idx];
		assert(stashed != nullptr);
		assert(cache_bin_nonfast_aligned(stashed));

		if (unlikely(san_stashed_ptr_is_corrupted(stashed, usize))) {
			safety_check_fail("<jemalloc>: Write-after-free "
			    "detected on deallocated pointer %p (size %zu).\n",
			    stashed, usize);
		}
	}
}

// Initialize per-TSD sanitizer counters
void
tsd_san_init(tsd_t *tsd) {
	*tsd_san_extents_until_guard_smallp_get(tsd) = opt_san_guard_small;
	*tsd_san_extents_until_guard_largep_get(tsd) = opt_san_guard_large;
}

// Global sanitizer initialization
void
san_init(ssize_t lg_uaf_align) {
	assert(lg_uaf_align == -1 || lg_uaf_align >= LG_PAGE);

	if (lg_uaf_align == -1) {
		san_cache_bin_nonfast_mask = (uintptr_t)-1;
		return;
	}

	uintptr_t shift = (uintptr_t)1 << lg_uaf_align;
	san_cache_bin_nonfast_mask = shift - 1;
}

