using namespace idiomata;

int main() {
    // Test signed division by 3 using multiplication with magic constant and arithmetic shift
    std::vector<LocalInsn> test_seq1 = {
        {0, "imul", {"reg_a", "reg_a", "magic_const_1"}},
        {4, "sar", {"reg_a", "shift_amount_1"}}
    };
    std::unordered_map<std::string, std::string> constants1 = {
        {"0x55555556", "magic_const_1"},
        {"0x2", "shift_amount_1"}
    };
    std::unordered_map<std::string, std::string> registers1 = { {"eax", "reg_a"} };
    assert(SequenceResolver(test_seq1, constants1, registers1).resolve_divs() == 3);

    // Test signed division by 5 with extra shift step
    std::vector<LocalInsn> test_seq2 = {
        {0, "imul", {"reg_b", "reg_b", "magic_const_2"}},
        {4, "sar", {"reg_b", "shift_amount_2"}},
        {8, "sar", {"reg_b", "extra_shift"}}
    };
    std::unordered_map<std::string, std::string> constants2 = {
        {"0x99999999", "magic_const_2"},
        {"0x20", "shift_amount_2"}, // 32 in hex
        {"0x1", "extra_shift"}
    };
    std::unordered_map<std::string, std::string> registers2 = { {"ebx", "reg_b"} };
    assert(SequenceResolver(test_seq2, constants2, registers2).resolve_divs() == 5);

    // Test unsigned division by 5 using logical shift
    std::vector<LocalInsn> test_seq3 = {
        {0, "mul", {"reg_c", "reg_c", "magic_unsigned"}},
        {4, "shr", {"reg_c", "log_shift"}}
    };
    std::unordered_map<std::string, std::string> constants3 = {
        {"0xcccccccd", "magic_unsigned"},
        {"0x2", "log_shift"}
    };
    std::unordered_map<std::string, std::string> registers3 = { {"ecx", "reg_c"} };
    assert(SequenceResolver(test_seq3, constants3, registers3).resolve_divu() == 5);

    // Test modulo via bitmask (power-of-two modulus)
    std::vector<LocalInsn> test_seq4 = {
        {0, "and", {"reg_d", "bitmask"}}
    };
    std::unordered_map<std::string, std::string> constants4 = {
        {"0xf", "bitmask"}
    };
    std::unordered_map<std::string, std::string> registers4 = { {"edx", "reg_d"} };
    assert(SequenceResolver(test_seq4, constants4, registers4).resolve_modu() == 16);

    // Test multiplication via left shift
    std::vector<LocalInsn> test_seq5 = {
        {0, "shl", {"reg_e", "shift_val"}}
    };
    std::unordered_map<std::string, std::string> constants5 = {
        {"0x3", "shift_val"}
    };
    std::unordered_map<std::string, std::string> registers5 = { {"esi", "reg_e"} };
    assert(SequenceResolver(test_seq5, constants5, registers5).resolve_mul() == 8);

    std::cout << "All idiom semantic resolution tests passed!" << std::endl;
    return 0;
}

#include <vector>
#include <algorithm>
#include <limits>

class Solution {
public:
    double mincostToHireWorkers(std::vector<int>& quality, std::vector<int>& wage, int k) {
        const int totalWorkers = quality.size();
        double bestCost = std::numeric_limits<double>::max();

        // Try each worker as the "baseline" for wage ratio calculation
        for (int idx = 0; idx < totalWorkers; ++idx) {
            double baseRatio = static_cast<double>(wage[idx]) / quality[idx];

            // Collect all valid wages under this ratio constraint
            std::vector<double> qualifyingWages;
            for (int jdx = 0; jdx < totalWorkers; ++jdx) {
                // Check if this worker can be hired without violating minimum wage requirement
                double requiredWage = baseRatio * quality[jdx];
                if (requiredWage >= wage[jdx]) {
                    qualifyingWages.push_back(requiredWage);
                }
            }

            // Skip if not enough workers qualify
            if (qualifyingWages.size() < static_cast<size_t>(k)) {
                continue;
            }

            // Sort to get the k smallest wages
            std::sort(qualifyingWages.begin(), qualifyingWages.end());

            // Compute sum of k smallest wages
            double currentSum = 0.0;
            for (int pos = 0; pos < k; ++pos) {
                currentSum += qualifyingWages[pos];
            }

            // Update minimum cost found so far
            if (currentSum < bestCost) {
                bestCost = currentSum;
            }
        }

        return bestCost;
    }
};

#include <vector>
#include <algorithm>

class Solution {
public:
    int findDuplicate(std::vector<int>& nums) {
        // Sort the array to bring duplicates next to each other
        std::sort(nums.begin(), nums.end());

        int duplicateValue = 0;
        int size = nums.size();

        // Traverse the sorted array to find adjacent equal elements
        for (int index = 0; index < size - 1; ++index) {
            if (nums[index] == nums[index + 1]) {
                duplicateValue = nums[index];
                break;  // Found the duplicate, exit early
            }
        }

        return duplicateValue;
    }
};

#include <iostream>
#include <vector>
#include <algorithm>
#include <set>
using namespace std;

const int MAX_NODES = 100005;
vector<int> children[MAX_NODES];
int left_bound[MAX_NODES], right_bound[MAX_NODES];
bool leaf_flag[MAX_NODES];
vector<vector<int>> bags_list;
vector<pair<int, int>> tree_connections;

// Compute L[u] and R[u]: min and max node in subtree rooted at u
void compute_subtree_bounds(int node) {
    if (children[node].empty()) {
        leaf_flag[node] = true;
        left_bound[node] = right_bound[node] = node;
    } else {
        leaf_flag[node] = false;
        left_bound[node] = MAX_NODES;
        right_bound[node] = -1;
        for (int child : children[node]) {
            compute_subtree_bounds(child);
            left_bound[node] = min(left_bound[node], left_bound[child]);
            right_bound[node] = max(right_bound[node], right_bound[child]);
        }
    }
}

// Recursive function to build the decomposition; returns {first_bag_id, last_bag_id}
pair<int, int> construct_decomposition(int node, int parent) {
    // Leaf case: create a single bag containing node and possibly parent
    if (leaf_flag[node]) {
        vector<int> bag_content;
        bag_content.push_back(node);
        if (parent != 0 && parent != node)
            bag_content.push_back(parent);

        sort(bag_content.begin(), bag_content.end());
        bag_content.erase(unique(bag_content.begin(), bag_content.end()), bag_content.end());

        bags_list.push_back(bag_content);
        int bag_id = bags_list.size();
        return {bag_id, bag_id};
    }

    int num_children = children[node].size();
    bool is_root_node = (node == 1);
    int special_node = is_root_node ? left_bound[node] : -1;

    // Process each child recursively
    vector<pair<int, int>> child_ranges(num_children);
    for (int idx = 0; idx < num_children; ++idx) {
        child_ranges[idx] = construct_decomposition(children[node][idx], node);
    }

    // Build NodeBag_1: includes node, parent (if applicable), first child, its subtree min, and possibly root's L
    vector<int> nb1;
    nb1.push_back(node);
    if (parent != 0 && parent != node) nb1.push_back(parent);
    nb1.push_back(children[node][0]);
    nb1.push_back(left_bound[children[node][0]]);
    if (special_node != -1) nb1.push_back(special_node);

    sort(nb1.begin(), nb1.end());
    nb1.erase(unique(nb1.begin(), nb1.end()), nb1.end());
    bags_list.push_back(nb1);
    int current_bag_id = bags_list.size();
    int start_bag_id = current_bag_id;

    // Link to first child's decomposition
    tree_connections.push_back({current_bag_id, child_ranges[0].first});
    int previous_bag = current_bag_id;

    // Iterate over remaining children to build intermediate bags
    for (int i = 0; i < num_children - 1; ++i) {
        int right_end = right_bound[children[node][i]];
        int left_next = left_bound[children[node][i + 1]];

        // CycleBag_i
        vector<int> cycle_bag;
        cycle_bag.push_back(node);
        if (parent != 0 && parent != node) cycle_bag.push_back(parent);
        cycle_bag.push_back(right_end);
        cycle_bag.push_back(left_next);
        if (special_node != -1) cycle_bag.push_back(special_node);

        sort(cycle_bag.begin(), cycle_bag.end());
        cycle_bag.erase(unique(cycle_bag.begin(), cycle_bag.end()), cycle_bag.end());
        bags_list.push_back(cycle_bag);
        int cycle_id = bags_list.size();

        // Connect l_i (end of child i) → cycle bag
        tree_connections.push_back({child_ranges[i].second, cycle_id});
        // Connect previous bag → cycle bag
        tree_connections.push_back({previous_bag, cycle_id});

        // NodeBag_{i+1}
        int next_child = children[node][i + 1];
        vector<int> next_nb;
        next_nb.push_back(node);
        if (parent != 0 && parent != node) next_nb.push_back(parent);
        next_nb.push_back(next_child);
        next_nb.push_back(left_next);
        if (special_node != -1) next_nb.push_back(special_node);

        sort(next_nb.begin(), next_nb.end());
        next_nb.erase(unique(next_nb.begin(), next_nb.end()), next_nb.end());
        bags_list.push_back(next_nb);
        int next_bag_id = bags_list.size();

        // Cycle bag → next node bag
        tree_connections.push_back({cycle_id, next_bag_id});
        // Next node bag → f_{i+1} (start of child i+1's decomposition)
        tree_connections.push_back({next_bag_id, child_ranges[i + 1].first});

        previous_bag = next_bag_id;
    }

    // Final TailBag: connects last child and its rightmost node
    int last_child = children[node].back();
    int last_right = right_bound[last_child];

    vector<int> tail_bag;
    tail_bag.push_back(node);
    if (parent != 0 && parent != node) tail_bag.push_back(parent);
    tail_bag.push_back(last_child);
    tail_bag.push_back(last_right);
    if (special_node != -1) tail_bag.push_back(special_node);

    sort(tail_bag.begin(), tail_bag.end());
    tail_bag.erase(unique(tail_bag.begin(), tail_bag.end()), tail_bag.end());
    bags_list.push_back(tail_bag);
    int final_bag_id = bags_list.size();

    // Connect last child's end → tail bag
    tree_connections.push_back({child_ranges.back().second, final_bag_id});
    // Connect previous bag → tail bag
    tree_connections.push_back({previous_bag, final_bag_id});

    return {start_bag_id, final_bag_id};
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    if (!(cin >> N)) return 0;

    for (int i = 0; i < N - 1; ++i) {
        int parent;
        cin >> parent;
        children[parent].push_back(i + 2);
    }

    compute_subtree_bounds(1);
    construct_decomposition(1, 0);

    cout << bags_list.size() << "\n";
    for (const auto& bag : bags_list) {
        cout << bag.size();
        for (int val : bag) {
            cout << " " << val;
        }
        cout << "\n";
    }

    for (const auto& conn : tree_connections) {
        cout << conn.first << " " << conn.second << "\n";
    }

    return 0;
}

