TEST_CASE(test_understeer_effect_scaling, "Understeer") {
    std::cout << "\nTest: Understeer Effect Scaling" << std::endl;
    FFBEngine engine;
    InitializeEngine(engine);

    engine.m_optimal_slip_angle = 0.10f;
    TelemInfoV01 telemetry = CreateBasicTestTelemetry(20.0, 0.12f);
    telemetry.mSteeringShaftTorque = 20.0;

    engine.m_understeer_effect = 0.0f;
    double f_zero = 0.0;
    int cnt = 0;
    while (cnt < FILTER_SETTLING_FRAMES) {
        f_zero = engine.calculate_force(&telemetry);
        ++cnt;
    }

    engine.m_understeer_effect = 1.0f;
    double f_one = 0.0;
    cnt = 0;
    while (cnt < FILTER_SETTLING_FRAMES) {
        f_one = engine.calculate_force(&telemetry);
        ++cnt;
    }

    engine.m_understeer_effect = 2.0f;
    double f_two = 0.0;
    cnt = 0;
    while (cnt < FILTER_SETTLING_FRAMES) {
        f_two = engine.calculate_force(&telemetry);
        ++cnt;
    }

    ASSERT_TRUE(f_zero > f_one && f_one > f_two);
}

