TEST_CASE(test_preset_understeer_only_isolation, "Understeer") {
    std::cout << "\nTest: Preset 'Test: Understeer Only' Isolation (v0.6.31)" << std::endl;

    Config::LoadPresets();

    int found_index = -1;
    size_t idx = 0;
    while (idx < Config::presets.size()) {
        if (Config::presets[idx].name == "Test: Understeer Only") {
            found_index = static_cast<int>(idx);
            break;
        }
        ++idx;
    }

    if (found_index == -1) {
        std::cout << "[FAIL] 'Test: Understeer Only' preset not found" << std::endl;
        g_tests_failed++;
        return;
    }

    const Preset& selected = Config::presets[found_index];

    ASSERT_TRUE(selected.understeer > 0.0f && selected.understeer <= 2.0f);

    ASSERT_NEAR(selected.sop, 0.0f, 0.001f);
    ASSERT_NEAR(selected.oversteer_boost, 0.0f, 0.001f);
    ASSERT_NEAR(selected.rear_align_effect, 0.0f, 0.001f);
    ASSERT_NEAR(selected.sop_yaw_gain, 0.0f, 0.001f);
    ASSERT_NEAR(selected.gyro_gain, 0.0f, 0.001f);
    ASSERT_NEAR(selected.scrub_drag_gain, 0.0f, 0.001f);

    ASSERT_FALSE(selected.slide_enabled);
    ASSERT_FALSE(selected.road_enabled);
    ASSERT_FALSE(selected.spin_enabled);
    ASSERT_FALSE(selected.lockup_enabled);
    ASSERT_FALSE(selected.abs_pulse_enabled);

    ASSERT_NEAR(selected.optimal_slip_angle, 0.10f, 0.001f);
    ASSERT_NEAR(selected.optimal_slip_ratio, 0.12f, 0.001f);

    ASSERT_NEAR(selected.speed_gate_lower, 0.0f, 0.001f);
    ASSERT_NEAR(selected.speed_gate_upper, 0.0f, 0.001f);

    std::cout << "[PASS] 'Test: Understeer Only' preset properly isolates understeer effect" << std::endl;
    g_tests_passed++;
}

TEST_CASE(test_all_presets_non_negative_speed_gate, "Understeer") {
    std::cout << "\nTest: All Presets Have Non-Negative Speed Gate Values (v0.6.32)" << std::endl;

    Config::LoadPresets();

    bool valid_all = true;
    size_t i = 0;
    while (i < Config::presets.size()) {
        const Preset& p = Config::presets[i];

        if (p.speed_gate_lower < 0.0f) {
            std::cout << "[FAIL] Preset '" << p.name << "' has negative speed_gate_lower: "
                      << p.speed_gate_lower << " m/s (" << (p.speed_gate_lower * 3.6f) << " km/h)" << std::endl;
            valid_all = false;
        }

        if (p.speed_gate_upper < 0.0f) {
            std::cout << "[FAIL] Preset '" << p.name << "' has negative speed_gate_upper: "
                      << p.speed_gate_upper << " m/s (" << (p.speed_gate_upper * 3.6f) << " km/h)" << std::endl;
            valid_all = false;
        }

        if (p.speed_gate_upper < p.speed_gate_lower) {
            std::cout << "[FAIL] Preset '" << p.name << "' has speed_gate_upper < speed_gate_lower: "
                      << p.speed_gate_upper << " < " << p.speed_gate_lower << std::endl;
            valid_all = false;
        }

        ++i;
    }

    if (valid_all) {
        std::cout << "[PASS] All " << Config::presets.size() << " presets have valid non-negative speed gate values" << std::endl;
        g_tests_passed++;
    } else {
        std::cout << "[FAIL] One or more presets have invalid speed gate values" << std::endl;
        g_tests_failed++;
    }
}

