// Helper to determine keyboard mode based on language and platform
static C_4JInput::EKeyboardMode GetKeyboardModeForPlatformAndLanguage() {
#if defined(_XBOX_ONE)
    int lang = XGetLanguage();
    switch (lang) {
        case XC_LANGUAGE_JAPANESE:
        case XC_LANGUAGE_KOREAN:
        case XC_LANGUAGE_TCHINESE:
            return C_4JInput::EKeyboardMode_Email;
        default:
            return C_4JInput::EKeyboardMode_Alphabet;
    }
#else
    return C_4JInput::EKeyboardMode_Alphabet;
#endif
