// Helper to set all sign lines to empty string
static void ClearSignLines(SignTileEntity* sign) {
    static const std::wstring empty = L"";
    for (int i = 0; i < 4; ++i) {
        sign->SetMessage(i, empty);
    }
}

UIScene_SignEntryMenu::UIScene_SignEntryMenu(int playerIndex, void* initDataPtr, UILayer* parentLayer)
    : UIScene(playerIndex, parentLayer), m_iEditingLine(0), m_bConfirmed(false), m_bIgnoreInput(false)
{
    initialiseMovie();

    auto* inputInitData = static_cast<SignEntryScreenInput*>(initDataPtr);
    m_sign = inputInitData->sign;

    // Initialize text input lines from existing sign content
    for (int i = 0; i < 4; ++i) {
        m_textInputLines[i].init(m_sign->GetMessage(i).c_str(), i);
    }

    // UI setup
    m_buttonConfirm.init(app.GetString(IDS_DONE), eControl_Confirm);
    m_labelMessage.init(app.GetString(IDS_EDIT_SIGN_MESSAGE));
    parentLayer->addComponent(playerIndex, eUIComponent_MenuBackground);
}

UIScene_SignEntryMenu::~UIScene_SignEntryMenu() {
    m_parentLayer->removeComponent(eUIComponent_MenuBackground);
}

std::wstring UIScene_SignEntryMenu::getMoviePath() const {
    return app.GetLocalPlayerCount() > 1 ? L"SignEntryMenuSplit" : L"SignEntryMenu";
}

void UIScene_SignEntryMenu::updateTooltips() {
    ui.SetTooltips(m_iPad, IDS_TOOLTIPS_SELECT, IDS_TOOLTIPS_BACK);
}

void UIScene_SignEntryMenu::tick() {
    if (!UIScene::tick()) return;

    if (m_bConfirmed) {
        m_bConfirmed = false;

        // Commit edited lines back to the sign
        for (int lineIdx = 0; lineIdx < 4; ++lineIdx) {
            std::wstring currentText = m_textInputLines[lineIdx].getLabel();
            m_sign->SetMessage(lineIdx, currentText);
        }

        m_sign->setChanged();

        // Send update packet if client-side
        Minecraft* pMinecraft = Minecraft::GetInstance();
        if (pMinecraft && pMinecraft->level && pMinecraft->level->isClientSide) {
            auto player = pMinecraft->localplayers[m_iPad];
            if (player && player->connection && player->connection->isStarted()) {
                SignUpdatePacket packet(
                    m_sign->x, m_sign->y, m_sign->z,
                    m_sign->IsVerified(), m_sign->IsCensored(),
                    m_sign->GetMessages()
                );
                player->connection->send(std::make_shared<SignUpdatePacket>(packet));
            }
        }

        ui.CloseUIScenes(m_iPad);
    }
}

void UIScene_SignEntryMenu::handleInput(int playerIndex, int key, bool repeat, bool pressed, bool released, bool& handled) {
    if (m_bConfirmed || m_bIgnoreInput) return;

    ui.AnimateKeyPress(playerIndex, key, repeat, pressed, released);

    switch (key) {
        case ACTION_MENU_CANCEL:
            if (pressed) {
                ClearSignLines(m_sign);
                navigateBack();
                ui.PlayUISFX(eSFX_Back);
                handled = true;
            }
            break;

        case ACTION_MENU_OK:
#ifdef __ORBIS__
        case ACTION_MENU_TOUCHPAD_PRESS:
#endif
        case ACTION_MENU_UP:
        case ACTION_MENU_DOWN:
            sendInputToMovie(key, repeat, pressed, released);
            handled = true;
            break;
    }
}

int UIScene_SignEntryMenu::KeyboardCompleteCallback(void* param, bool success) {
    auto* self = static_cast<UIScene_SignEntryMenu*>(param);
    self->m_bIgnoreInput = false;

    if (success) {
        uint16_t buffer[128] = {};
        InputManager.GetText(buffer);
        self->m_textInputLines[self->m_iEditingLine].setLabel(reinterpret_cast<wchar_t*>(buffer));
    }

    return 0;
}

void UIScene_SignEntryMenu::handlePress(F64 controlId, F64 childId) {
    switch (static_cast<int>(controlId)) {
        case eControl_Confirm:
            m_bConfirmed = true;
            break;

        case eControl_Line1:
        case eControl_Line2:
        case eControl_Line3:
        case eControl_Line4: {
            m_iEditingLine = static_cast<int>(controlId);
            m_bIgnoreInput = true;

            std::wstring initialText = m_textInputLines[m_iEditingLine].getLabel();
            std::wstring title = app.GetString(IDS_SIGN_TITLE);

            InputManager.RequestKeyboard(
                title,
                initialText,
                static_cast<DWORD>(m_iPad),
                15,
                &UIScene_SignEntryMenu::KeyboardCompleteCallback,
                this,
                GetKeyboardModeForPlatformAndLanguage()
            );
            break;
        }
    }
}

void UIScene_SignEntryMenu::handleDestroy() {
#if defined(__PSVITA__)
    app.DebugPrintf("missing InputManager.DestroyKeyboard on Vita !!!!!!\n");
#endif

#if defined(__PS3__) || defined(__ORBIS__) || defined(_DURANGO)
    InputManager.DestroyKeyboard();
#endif
}

