// Helper to determine whether an index entry needs loading
static bool requiresLoading(const catalog::IndexCatalogEntry* entry) {
    return entry && 
           entry->getIndexType() == HNSWIndexCatalogEntry::TYPE_NAME &&
           !entry->isLoaded();
}

// Load auxiliary info and physical index from storage
static void prepareHNSWIndex(main::ClientContext* ctx,
                             catalog::IndexCatalogEntry* entry,
                             storage::StorageManager& storageMgr) {
    // Deserialize and attach aux info
    entry->setAuxInfo(HNSWIndexAuxInfo::deserialize(entry->getAuxBufferReader()));

    // Retrieve corresponding node table
    auto& baseTable = *storageMgr.getTable(entry->getTableID());
    auto& nodeTable = baseTable.cast<storage::NodeTable>();

    // Fetch the on-disk index instance by name
    auto optIndex = nodeTable.getIndexHolder(entry->getIndexName());
    if (!optIndex.has_value()) {
        throw std::runtime_error("Expected HNSW index not found in node table");
    }

    auto& diskIndex = optIndex.value().get();
    if (diskIndex.isLoaded()) {
        return; // Already loaded — nothing to do
    }

    // Trigger load operation on the index
    diskIndex.load(ctx, &storageMgr);
}

// Initialize all HNSW indexes that are not yet loaded
static void initializeLoadedHNSWIndexes(main::ClientContext* context) {
    auto& storageMgr = storage::StorageManager::Get(*context);
    auto& catalogRef = catalog::Catalog::Get(*context);
    auto txn = transaction::Transaction::Get(*context);

    for (auto&& entryPtr : catalogRef.getIndexEntries(txn)) {
        if (requiresLoading(entryPtr.get())) {
            prepareHNSWIndex(context, entryPtr.get(), storageMgr);
        }
    }
}

// Public load function: registers functions and initializes indexes
void VectorExtension::load(main::ClientContext* context) {
    auto& dbInstance = *context->getDatabase();

    // Register query-time vector search function
    extension::ExtensionUtils::addTableFunc<QueryVectorIndexFunction>(dbInstance);

    // Internal DDL helpers for HNSW index creation/finalization/drop
    extension::ExtensionUtils::addInternalStandaloneTableFunc<InternalCreateHNSWIndexFunction>(dbInstance);
    extension::ExtensionUtils::addInternalStandaloneTableFunc<InternalFinalizeHNSWIndexFunction>(dbInstance);
    extension::ExtensionUtils::addInternalStandaloneTableFunc<InternalDropHNSWIndexFunction>(dbInstance);

    // Public-facing index management functions
    extension::ExtensionUtils::addStandaloneTableFunc<CreateVectorIndexFunction>(dbInstance);
    extension::ExtensionUtils::addStandaloneTableFunc<DropVectorIndexFunction>(dbInstance);

    // Register the on-disk HNSW index type with the engine
    extension::ExtensionUtils::registerIndexType(dbInstance, OnDiskHNSWIndex::getIndexType());

    // Finally, ensure any pre-existing HNSW indexes are loaded
    initializeLoadedHNSWIndexes(context);
}

} // namespace vector_extension

