// Worker for establishing connection to Git repository
FName FGitConnectWorker::GetName() const
{
    return "Connect";
}

bool FGitConnectWorker::Execute(FGitSourceControlCommand& InCommand)
{
    check(InCommand.Operation->GetName() == GetName());

    // Verify Git binary is available and functional
    if (InCommand.PathToGitBinary.Len() > 0 && 
        GitSourceControlUtils::CheckGitAvailability(InCommand.PathToGitBinary))
    {
        // Prepare directories for status update: Content and Config folders
        TArray<FString> ProjectDirs;
        ProjectDirs.Add(FPaths::ConvertRelativePathToFull(FPaths::ProjectContentDir()));
        ProjectDirs.Add(FPaths::ConvertRelativePathToFull(FPaths::ProjectConfigDir()));

        InCommand.bCommandSuccessful = GitSourceControlUtils::RunUpdateStatus(
            InCommand.PathToGitBinary, 
            InCommand.PathToRepositoryRoot, 
            ProjectDirs, 
            InCommand.ErrorMessages, 
            States
        );

        if (!InCommand.bCommandSuccessful || InCommand.ErrorMessages.Num() > 0)
        {
            StaticCastSharedRef<FConnect>(InCommand.Operation)->SetErrorText(
                LOCTEXT("NotAGitRepository", "Failed to enable Git source control. You need to initialize the project as a Git repository first.")
            );
            InCommand.bCommandSuccessful = false;
        }
    }
    else
    {
        StaticCastSharedRef<FConnect>(InCommand.Operation)->SetErrorText(
            LOCTEXT("GitNotFound", "Failed to enable Git source control. You need to install Git and specify a valid path to git executable.")
        );
        InCommand.bCommandSuccessful = false;
    }

    return InCommand.bCommandSuccessful;
}

bool FGitConnectWorker::UpdateStates() const
{
    return GitSourceControlUtils::UpdateCachedStates(States);
}

// Helper function to format commit result messages
static FText FormatCommitResult(const TArray<FString>& Results)
{
    if (Results.Num() >= 1)
    {
        const FString& FirstLine = Results[0];
        return FText::Format(LOCTEXT("CommitMessage", "Committed {0}."), FText::FromString(FirstLine));
    }
    return LOCTEXT("CommitMessageUnknown", "Submitted revision.");
}

// Worker for committing changes to Git repository
FName FGitCheckInWorker::GetName() const
{
    return "CheckIn";
}

bool FGitCheckInWorker::Execute(FGitSourceControlCommand& InCommand)
{
    check(InCommand.Operation->GetName() == GetName());
    TSharedRef<FCheckIn, ESPMode::ThreadSafe> Operation = StaticCastSharedRef<FCheckIn>(InCommand.Operation);

    // Create temporary file for commit message
    FGitScopedTempFile CommitMsgFile(Operation->GetDescription());

    if (CommitMsgFile.GetFilename().Len() > 0)
    {
        TArray<FString> Parameters;
        FString ParamCommitMsgFilename = TEXT("--file=\"");
        ParamCommitMsgFilename += FPaths::ConvertRelativePathToFull(CommitMsgFile.GetFilename());
        ParamCommitMsgFilename += TEXT("\"");
        Parameters.Add(ParamCommitMsgFilename);

        InCommand.bCommandSuccessful = GitSourceControlUtils::RunCommit(
            InCommand.PathToGitBinary,
            InCommand.PathToRepositoryRoot,
            Parameters,
            InCommand.Files,
            InCommand.InfoMessages,
            InCommand.ErrorMessages
        );

        if (InCommand.bCommandSuccessful)
        {
            // Clean up deleted files from cache
            FGitSourceControlModule& GitSourceControl = FModuleManager::GetModuleChecked<FGitSourceControlModule>("GitSourceControl");
            FGitSourceControlProvider& Provider = GitSourceControl.GetProvider();

            TArray<TSharedRef<ISourceControlState, ESPMode::ThreadSafe>> LocalStates;
            Provider.GetState(InCommand.Files, LocalStates, EStateCacheUsage::Use);

            for (const auto& State : LocalStates)
            {
                if (State->IsDeleted())
                {
                    Provider.RemoveFileFromCache(State->GetFilename());
                }
            }

            Operation->SetSuccessMessage(FormatCommitResult(InCommand.InfoMessages));
            const FString Message = (InCommand.InfoMessages.Num() > 0) ? InCommand.InfoMessages[0] : TEXT("");
            UE_LOG(LogSourceControl, Log, TEXT("commit successful: %s"), *Message);
        }
    }

    // Refresh file states after commit
    GitSourceControlUtils::RunUpdateStatus(
        InCommand.PathToGitBinary,
        InCommand.PathToRepositoryRoot,
        InCommand.Files,
        InCommand.ErrorMessages,
        States
    );

    return InCommand.bCommandSuccessful;
}

bool FGitCheckInWorker::UpdateStates() const
{
    return GitSourceControlUtils::UpdateCachedStates(States);
}

