void FrustumCuller::setup(double offsetX, double offsetY, double offsetZ) {
    xOff = offsetX;
    yOff = offsetY;
    zOff = offsetZ;
}

bool FrustumCuller::isBoxFullyInsideFrustum(double minX, double minY, double minZ, 
                                            double maxX, double maxY, double maxZ) {
    return frustum->cubeFullyInFrustum(minX - xOff, minY - yOff, minZ - zOff,
                                       maxX - xOff, maxY - yOff, maxZ - zOff);
}

bool FrustumCuller::isBoxIntersectingFrustum(double minX, double minY, double minZ,
                                             double maxX, double maxY, double maxZ) {
    return frustum->cubeInFrustum(minX - xOff, minY - yOff, minZ - zOff,
                                  maxX - xOff, maxY - yOff, maxZ - zOff);
}

bool FrustumCuller::isVisible(AABB *boundingBox) {
    return isBoxIntersectingFrustum(boundingBox->x0, boundingBox->y0, boundingBox->z0,
                                    boundingBox->x1, boundingBox->y1, boundingBox->z1);
}

