export Ui::Child number(f64 value, Ui::Send<f64> onChange, f64 step) {
    auto decrementHandler = [onChange, value, step](auto& n) {
        onChange(n, value - step);
    };

    auto incrementHandler = [onChange, value, step](auto& n) {
        onChange(n, value + step);
    };

    return Ui::hflow(
               Ui::button(decrementHandler, Ui::ButtonStyle::subtle(), Mdi::MINUS),
               Ui::labelMedium("{:.02}", value) | Ui::insets({0, 4}) | Ui::center(),
               Ui::button(incrementHandler, Ui::ButtonStyle::subtle(), Mdi::PLUS)
           ) |
           Ui::box({
               .borderRadii = 4,
               .borderWidth = 1,
               .borderFill = Ui::GRAY800,
           }) |
           Ui::focusable();
}

