void MultiDOFJointTrajectoryDisplay::updateTrajectory() {
  // Update internal state from properties
  show_connection_ = property_show_connection_->getBool();
  show_transform_rotation_ = property_show_transform_rotation_->getBool();
  show_velocity_linear_ = property_show_velocity_linear_->getBool();
  show_velocity_angular_ = property_show_velocity_angular_->getBool();
  show_acceleration_linear_ = property_show_acceleration_linear_->getBool();
  show_acceleration_angular_ = property_show_acceleration_angular_->getBool();
  size_transform_rotation_ = property_size_transform_rotation_->getFloat();
  scale_velocity_linear_ = property_scale_velocity_linear_->getFloat();
  scale_velocity_angular_ = property_scale_velocity_angular_->getFloat();
  scale_acceleration_linear_ = property_scale_acceleration_linear_->getFloat();
  scale_acceleration_angular_ = property_scale_acceleration_angular_->getFloat();

  color_connection_ = rviz::qtToOgre(property_color_connection_->getColor());
  color_velocity_linear_ = rviz::qtToOgre(property_color_velocity_linear_->getColor());
  color_velocity_angular_ = rviz::qtToOgre(property_color_velocity_angular_->getColor());
  color_acceleration_linear_ = rviz::qtToOgre(property_color_acceleration_linear_->getColor());
  color_acceleration_angular_ = rviz::qtToOgre(property_color_acceleration_angular_->getColor());

  alpha_val_ = property_alpha_val_->getFloat();
  color_connection_.a = alpha_val_;
  color_velocity_linear_.a = alpha_val_;
  color_velocity_angular_.a = alpha_val_;
  color_acceleration_linear_.a = alpha_val_;
  color_acceleration_angular_.a = alpha_val_;

  // Prepare captions
  std::vector<std::vector<std::string>> captions_list;
  const auto& traj_points = current_trajectory_->points;
  const auto& joint_names = current_trajectory_->joint_names;

  for (size_t idx_point = 0; idx_point < traj_points.size(); ++idx_point) {
    std::vector<std::string> point_captions;
    for (size_t idx_joint = 0; idx_joint < joint_names.size(); ++idx_joint) {
      std::ostringstream oss;
      oss << joint_names[idx_joint] << ": t" << idx_point << " = " << traj_points[idx_point].time_from_start.toSec() << "s";
      point_captions.push_back(oss.str());
    }
    captions_list.push_back(point_captions);
  }

  font_size_ = property_font_size_->getFloat();
  show_text_ = property_show_text_->getBool();

  // Build visuals
  std::vector<boost::shared_ptr<MultiDOFJointTrajectoryPointVisual>> visuals_points;
  std::vector<boost::shared_ptr<MultiDOFJointTrajectoryPointConnectionVisual>> visuals_connections;

  trajectory_msgs::MultiDOFJointTrajectoryPoint prev_point;
  trajectory_msgs::MultiDOFJointTrajectoryPoint curr_point = traj_points[0];

  // First point
  visuals_points.emplace_back(boost::make_shared<MultiDOFJointTrajectoryPointVisual>(
      context_->getSceneManager(), scene_node_, curr_point, show_transform_rotation_, show_velocity_linear_,
      show_velocity_angular_, show_acceleration_linear_, show_acceleration_angular_, size_transform_rotation_,
      diameter_arrows_, scale_velocity_linear_, scale_velocity_angular_, scale_acceleration_linear_,
      scale_acceleration_angular_, alpha_val_, color_velocity_linear_, color_velocity_angular_,
      color_acceleration_linear_, color_acceleration_angular_, captions_list[0], font_size_, show_text_));

  // Remaining points and connections
  size_t total_points = traj_points.size();
  size_t i = 1;
  while (i < total_points) {
    prev_point = curr_point;
    curr_point = traj_points[i];

    visuals_connections.emplace_back(boost::make_shared<MultiDOFJointTrajectoryPointConnectionVisual>(
        context_->getSceneManager(), scene_node_, prev_point, curr_point, show_connection_, color_connection_));

    visuals_points.emplace_back(boost::make_shared<MultiDOFJointTrajectoryPointVisual>(
        context_->getSceneManager(), scene_node_, curr_point, show_transform_rotation_, show_velocity_linear_,
        show_velocity_angular_, show_acceleration_linear_, show_acceleration_angular_, size_transform_rotation_,
        diameter_arrows_, scale_velocity_linear_, scale_velocity_angular_, scale_acceleration_linear_,
        scale_acceleration_angular_, alpha_val_, color_velocity_linear_, color_velocity_angular_,
        color_acceleration_linear_, color_acceleration_angular_, captions_list[i], font_size_, show_text_));

    ++i;
  }

  visuals_points_.push_back(visuals_points);
  visuals_connections_.push_back(visuals_connections);
}

