#include <iostream>
#include <vector>
#include <numeric>
#include <algorithm>
#include <random>
using namespace std;

// Perform a query between positions i and j; handles termination on -1
int ask(int pos1, int pos2) {
    cout << "? " << pos1 << " " << pos2 << endl;
    int result;
    cin >> result;
    if (result == -1) exit(0);
    return result;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int total;
    if (!(cin >> total)) return 0;

    // Start with all possible indices as candidates for containing zero
    vector<int> possibles(total);
    iota(possibles.begin(), possibles.end(), 1);

    mt19937_64 rng(1337);  // Use 64-bit Mersenne Twister for better randomness

    // Phase 1: Select a promising pivot candidate
    int chosen = -1;
    if (total > 20) {
        const int trialCount = 8;
        const int testCount = 4;

        // Shuffle indices to get random order
        vector<int> shuffled(total);
        iota(shuffled.begin(), shuffled.end(), 1);
        shuffle(shuffled.begin(), shuffled.end(), rng);

        vector<int> trials;
        for (int i = 0; i < trialCount; ++i)
            trials.push_back(shuffled[i]);

        vector<int> tests;
        for (int i = trialCount; i < trialCount + testCount; ++i)
            tests.push_back(shuffled[i]);

        long long bestCost = -1;

        for (int candidate : trials) {
            long long cost = 0;
            for (int tester : tests) {
                cost += ask(candidate, tester);
            }
            if (bestCost == -1 || cost < bestCost) {
                bestCost = cost;
                chosen = candidate;
            }
        }
    } else {
        uniform_int_distribution<int> dist(0, total - 1);
        chosen = possibles[dist(rng)];
    }

    // Phase 2: Filter candidates using the pivot
    int lowest = -1;
    vector<pair<int, int>> outcomes;
    outcomes.reserve(total);

    for (int idx : possibles) {
        if (idx == chosen) continue;
        int val = ask(idx, chosen);
        if (lowest == -1 || val < lowest) {
            lowest = val;
        }
        outcomes.emplace_back(idx, val);
    }

    vector<int> nextSet;
    nextSet.push_back(chosen);
    for (auto& [index, value] : outcomes) {
        if (value == lowest) {
            nextSet.push_back(index);
        }
    }
    possibles = move(nextSet);

    // Phase 3: Iteratively narrow down to one candidate
    while (possibles.size() > 1) {
        int external = -1;
        while (true) {
            uniform_int_distribution<int> dist(1, total);
            external = dist(rng);
            bool found = false;
            for (int c : possibles) {
                if (c == external) {
                    found = true;
                    break;
                }
            }
            if (!found) break;
        }

        lowest = -1;
        outcomes.clear();
        for (int pos : possibles) {
            int res = ask(pos, external);
            if (lowest == -1 || res < lowest) {
                lowest = res;
            }
            outcomes.emplace_back(pos, res);
        }

        nextSet.clear();
        for (auto& [idx, val] : outcomes) {
            if (val == lowest) {
                nextSet.push_back(idx);
            }
        }
        possibles = move(nextSet);
    }

    // Phase 4: Reconstruct full array
    int zeroPos = possibles[0];
    vector<int> values(total + 1);
    values[zeroPos] = 0;

    for (int i = 1; i <= total; ++i) {
        if (i == zeroPos) continue;
        values[i] = ask(i, zeroPos);  // Since x | 0 = x
    }

    cout << "!";
    for (int i = 1; i <= total; ++i) {
        cout << " " << values[i];
    }
    cout << endl;

    return 0;
}

#include "tempbuf.h"
namespace {
    static inline size_t ExpandSize(size_t current, size_t needed) noexcept {
        size_t totalRequired = current + needed;
        size_t newSize = 1;
        while (newSize < totalRequired) {
            newSize <<= 1;
        }
        return newSize;
    }
} // namespace
void TTempBufOutput::DoWrite(const void* data, size_t length) {
    size_t availableSpace = Capacity() - Size();
    if (Y_LIKELY(length <= availableSpace)) {
        Append(data, length);
    } else {
        size_t currentDataSize = Size();
        size_t requiredCapacity = ExpandSize(currentDataSize, length);
        TTempBuf tempBuffer(requiredCapacity);
        tempBuffer.Append(Data(), currentDataSize);
        tempBuffer.Append(data, length);
        *this = static_cast<TTempBuf&>(tempBuffer);
    }
}

