// Helper: Convert Python bytes to std::vector<uint8_t> safely
std::vector<uint8_t> BytesToVector(const py::bytes& b) {
    Py_ssize_t len = PyBytes_Size(b.ptr());
    const char* data = PyBytes_AsString(b.ptr());
    if (!data || len < 0) {
        throw std::runtime_error("Invalid Python bytes object");
    }
    return std::vector<uint8_t>(reinterpret_cast<const uint8_t*>(data),
                                reinterpret_cast<const uint8_t*>(data) + len);
}

