ScreenSpaceAmbientOcclusion::ScreenSpaceAmbientOcclusion(const Eigen::Vector2i& size) {
  ssae = std::make_unique<ScreenSpaceAttributeEstimation>(size);

  std::string vert_path = get_data_path() + "/shader/texture.vert";
  std::string frag_path = get_data_path() + "/shader/ssao.frag";

  if (!ssao_shader.compile_and_link(vert_path, frag_path)) {
    // Shader initialization failed; constructor continues but shader remains invalid
    return;
  }
}

ScreenSpaceAmbientOcclusion::~ScreenSpaceAmbientOcclusion() = default;

void ScreenSpaceAmbientOcclusion::set_size(const Eigen::Vector2i& size) {
  if (ssae) {
    ssae->set_size(size);
  }
}

void ScreenSpaceAmbientOcclusion::draw(const TextureRenderer& renderer, 
                                       const glk::Texture& color_texture, 
                                       const glk::Texture& depth_texture, 
                                       const TextureRendererInput::Ptr& input, 
                                       glk::FrameBuffer* frame_buffer) {
  // First compute screen-space attributes
  if (ssae) {
    ssae->draw(renderer, color_texture, depth_texture, input, frame_buffer);
  }

  // Bind output buffer if provided
  if (frame_buffer) {
    frame_buffer->bind();
  }

  // Disable depth testing for full-screen quad rendering
  glDisable(GL_DEPTH_TEST);

  // Use SSAO shader and bind textures
  if (ssao_shader.is_valid()) {
    ssao_shader.bind();

    // Set texture unit bindings
    ssao_shader.set_uniform("color_sampler",     0);
    ssao_shader.set_uniform("position_sampler", 1);
    ssao_shader.set_uniform("normal_sampler",   2);
    ssao_shader.set_uniform("occlusion_sampler",3);

    // Bind textures to their respective units
    color_texture.bind(GL_TEXTURE0);
    if (ssae) {
      ssae->position().bind(GL_TEXTURE1);
      ssae->normal().bind(GL_TEXTURE2);
      ssae->occlusion().bind(GL_TEXTURE3);
    }

    // Render full-screen quad
    renderer.draw_plain(ssao_shader);
  }

  // Restore depth test state
  glEnable(GL_DEPTH_TEST);

  // Unbind framebuffer if it was bound earlier
  if (frame_buffer) {
    frame_buffer->unbind();
  }
}

