using json = nlohmann::json;
using namespace nlohmann::literals;

// Helper function to display UBJSON bytes in human-readable form
void show_ubjson_byte(std::uint8_t b)
{
    if (b >= 32 && b <= 126)
    {
        std::cout << static_cast<char>(b);
    }
    else
    {
        std::cout << static_cast<int>(b);
    }
}

int main()
{
    // Build a JSON object from raw string literal
    json obj = R"({"compact": true, "schema": false})"_json;

    // Convert to UBJSON format (binary representation)
    std::vector<std::uint8_t> ubjson_bytes = json::to_ubjson(obj);

    // Output the raw byte stream
    for (std::uint8_t byte : ubjson_bytes)
    {
        show_ubjson_byte(byte);
    }
    std::cout << '\n';

    // Create a numeric array
    json numbers = {1, 2, 3, 4, 5, 6, 7, 8};

    // Generate three variants of UBJSON encoding:
    // 1. Standard encoding
    std::vector<std::uint8_t> standard_ubjson = json::to_ubjson(numbers);

    // 2. Size-optimized encoding
    std::vector<std::uint8_t> size_optimized = json::to_ubjson(numbers, true);

    // 3. Size + type optimized encoding
    std::vector<std::uint8_t> full_optimized = json::to_ubjson(numbers, true, true);

    // Print each variant on separate lines
    for (std::uint8_t b : standard_ubjson)
    {
        show_ubjson_byte(b);
    }
    std::cout << '\n';

    for (std::uint8_t b : size_optimized)
    {
        show_ubjson_byte(b);
    }
    std::cout << '\n';

    for (std::uint8_t b : full_optimized)
    {
        show_ubjson_byte(b);
    }
    std::cout << '\n';

    return 0;
}

#include <cstdlib>
#include <iostream>
#include <boost/bind.hpp>
#include "asio.hpp"
#include "asio/ssl.hpp"

enum { buffer_size = 1024 };

class secure_client
{
public:
  secure_client(asio::io_context& ctx,
      asio::ssl::context& ssl_ctx,
      asio::ip::tcp::resolver::results_type targets)
    : ssl_socket_(ctx, ssl_ctx)
  {
    ssl_socket_.set_verify_mode(asio::ssl::verify_peer);
    ssl_socket_.set_verify_callback(
        boost::bind(&secure_client::check_certificate, this, _1, _2));

    asio::async_connect(ssl_socket_.lowest_layer(), targets,
        boost::bind(&secure_client::on_connection_established, this,
          asio::placeholders::error));
  }

  bool check_certificate(bool is_valid,
      asio::ssl::verify_context& vrfy_ctx)
  {
    // This callback allows custom certificate validation logic.
    // Here we extract and display the subject name for demonstration.
    char cn_name[256];
    X509* cert = X509_STORE_CTX_get_current_cert(vrfy_ctx.native_handle());
    X509_NAME_oneline(X509_get_subject_name(cert), cn_name, 256);
    std::cout << "Certificate subject: " << cn_name << "\n";
    return is_valid;
  }

  void on_connection_established(const asio::error_code& err)
  {
    if (!err)
    {
      ssl_socket_.async_handshake(asio::ssl::stream_base::client,
          boost::bind(&secure_client::on_tls_handshake, this,
            asio::placeholders::error));
    }
    else
    {
      std::cerr << "Connection failed: " << err.message() << "\n";
    }
  }

  void on_tls_handshake(const asio::error_code& err)
  {
    if (!err)
    {
      std::cout << "TLS handshake successful. Enter message: ";
      std::cin.getline(msg_buffer_, buffer_size);
      size_t len = strlen(msg_buffer_);

      asio::async_write(ssl_socket_,
          asio::buffer(msg_buffer_, len),
          boost::bind(&secure_client::on_message_sent, this,
            asio::placeholders::error,
            asio::placeholders::bytes_transferred));
    }
    else
    {
      std::cerr << "TLS handshake failed: " << err.message() << "\n";
    }
  }

  void on_message_sent(const asio::error_code& err, size_t sent_bytes)
  {
    if (!err)
    {
      asio::async_read(ssl_socket_,
          asio::buffer(resp_buffer_, sent_bytes),
          boost::bind(&secure_client::on_response_received, this,
            asio::placeholders::error,
            asio::placeholders::bytes_transferred));
    }
    else
    {
      std::cerr << "Sending data failed: " << err.message() << "\n";
    }
  }

  void on_response_received(const asio::error_code& err, size_t bytes_read)
  {
    if (!err)
    {
      std::cout << "Server reply:\n";
      std::cout.write(resp_buffer_, bytes_read);
      std::cout << "\n";
    }
    else
    {
      std::cerr << "Reading response failed: " << err.message() << "\n";
    }
  }

private:
  asio::ssl::stream<asio::ip::tcp::socket> ssl_socket_;
  char msg_buffer_[buffer_size];
  char resp_buffer_[buffer_size];
};

int main(int argc, char* argv[])
{
  try
  {
    if (argc != 3)
    {
      std::cerr << "Usage: client <hostname> <service>\n";
      return EXIT_FAILURE;
    }

    asio::io_context ioc;
    asio::ip::tcp::resolver resolver(ioc);
    auto endpoints = resolver.resolve(argv[1], argv[2]);

    asio::ssl::context ssl_context(asio::ssl::context::sslv23);
    ssl_context.load_verify_file("ca.pem");

    secure_client client_obj(ioc, ssl_context, endpoints);
    ioc.run();
  }
  catch (const std::exception& ex)
  {
    std::cerr << "Runtime error: " << ex.what() << "\n";
    return EXIT_FAILURE;
  }

  return EXIT_SUCCESS;
}

