int main() {
    const int thread_count = 8;
    std::thread worker_threads[thread_count];

    for (int idx = 0; idx < thread_count; ++idx) {
        worker_threads[idx] = std::thread([idx]() {
            const int message_count = 1000;
            for (int msg_idx = 0; msg_idx < message_count; ++msg_idx) {
                const int log_category = std::rand() % 4;

                switch (log_category) {
                    case 0: 
                        LOG_INF("Thread %d: %d\n", idx, msg_idx); 
                        break;
                    case 1: 
                        LOG_WRN("Thread %d: %d\n", idx, msg_idx); 
                        break;
                    case 2: 
                        LOG_ERR("Thread %d: %d\n", idx, msg_idx); 
                        break;
                    case 3: 
                        LOG_DBG("Thread %d: %d\n", idx, msg_idx); 
                        break;
                    default:
                        break;
                }

                if (std::rand() % 10 < 5) {
                    common_log_set_timestamps(common_log_main(), std::rand() % 2);
                    common_log_set_prefix(common_log_main(), std::rand() % 2);
