namespace {
inline bool hasRandomAccess(const TFilePath &path) {
  const std::string &format = path.getType();
  if (format == "pli") return false;
  return format == "tlv" || 
         path.getDots() == "..";  // Multi-file levels do support random access
}

void adjustBitDepth(TPropertyGroup *props, int requiredBpp, bool onlyIncrease) {
  TEnumProperty *bppProp = dynamic_cast<TEnumProperty*>(props->getProperty("Bits Per Pixel"));
  if (bppProp) {
    typedef TEnumProperty::Range Range;
    const Range &options = bppProp->getRange();

    int currentIdx = bppProp->getIndex();
    int currentVal = onlyIncrease ? std::stoi(bppProp->getValueAsString()) : 0;
    int bestVal = (std::numeric_limits<int>::max)(), bestIdx = -1;

    for (size_t i = 0; i < options.size(); ++i) {
      int entryBpp = std::stoi(options[i]);
      if ((entryBpp % requiredBpp == 0) && currentVal <= entryBpp && entryBpp < bestVal) {
        bestVal = entryBpp;
        bestIdx = static_cast<int>(i);
      }
    }

    if (bestIdx >= 0) bppProp->setIndex(bestIdx);
  }

  if (requiredBpp % 32 == 0) {
    TBoolProperty *alphaProp = dynamic_cast<TBoolProperty*>(props->getProperty("Alpha Channel"));
    if (alphaProp) alphaProp->setValue(true);
  }
}
}  // namespace

