LevelUpdater::LevelUpdater()
    : m_pg(nullptr)
    , m_inputLevel(nullptr)
    , m_currIdx(0)
    , m_imageInfo(nullptr)
    , m_usingTempFile(false)
    , m_isOpen(false) {}

LevelUpdater::LevelUpdater(TXshSimpleLevel *sl)
    : m_pg(nullptr)
    , m_inputLevel(nullptr)
    , m_imageInfo(nullptr)
    , m_currIdx(0)
    , m_isOpen(false)
    , m_usingTempFile(false) {
  initialize(sl);
}

LevelUpdater::LevelUpdater(const TFilePath &path, TPropertyGroup *lwProps,
                           const TFrameId &templateFId)
    : m_pg(nullptr)
    , m_inputLevel(nullptr)
    , m_imageInfo(nullptr)
    , m_currIdx(0)
    , m_isOpen(false)
    , m_usingTempFile(false) {
  initialize(path, lwProps, templateFId);
}

LevelUpdater::~LevelUpdater() {
  try {
    finalize();
  } catch (...) {
  }
}

void LevelUpdater::resetState() {
  m_lw     = TLevelWriterP();
  m_lwPath = TFilePath();
  m_lr     = TLevelReaderP();
  m_inputLevel = TLevelP();
  m_sl     = TXshSimpleLevelP();

  delete m_pg;
  m_pg = nullptr;

  if (m_imageInfo) {
    delete m_imageInfo->m_properties;
    delete m_imageInfo;
    m_imageInfo = nullptr;
  }

  m_fids.clear();
  m_currIdx = 0;
  m_usingTempFile = false;
  m_isOpen = false;
}

void LevelUpdater::loadSourceInfo(const TFilePath &path) {
  try {
    m_lr = TLevelReaderP(path);
    assert(m_lr);
    m_lr->enableRandomAccessRead(true);
    m_inputLevel = m_lr->loadInfo();

    const TImageInfo *info = m_lr->getImageInfo();
    if (info) {
      m_imageInfo = new TImageInfo(*info);
      if (info->m_properties)
        m_imageInfo->m_properties = info->m_properties->clone();
    }
  } catch (...) {
    m_lr = TLevelReaderP();
    m_inputLevel = TLevelP(nullptr);

    if (m_imageInfo) {
      delete m_imageInfo->m_properties;
      delete m_imageInfo;
      m_imageInfo = nullptr;
    }
  }
}

void LevelUpdater::constructProperties(const TFilePath &path) {
  m_pg = (m_imageInfo && m_imageInfo->m_properties)
             ? m_imageInfo->m_properties->clone()
             : Tiio::makeWriterProperties(path.getType());

  if (!m_pg) {
    resetState();
    throw TException("Unrecognized file format");
  }
  assert(m_pg);
}

void LevelUpdater::initialize(const TFilePath &path, TPropertyGroup *pg,
                              const TFrameId &templateFId) {
  assert(!m_lw);

  bool levelExists = TSystem::doesExistFileOrLevel(path);
  if (levelExists)
    loadSourceInfo(path);

  if (pg)
    m_pg = pg->clone();
  else
    constructProperties(path);

  try {
    m_usingTempFile = levelExists && !hasRandomAccess(path);

    if (m_usingTempFile) {
      m_lwPath = createTempFilePath(path);
      m_lw = TLevelWriterP(m_lwPath, m_pg->clone());

      if (m_inputLevel)
        for (TLevel::Iterator it = m_inputLevel->begin();
             it != m_inputLevel->end(); ++it)
          m_fids.push_back(it->first);
    } else {
      m_lr = TLevelReaderP();
      m_lw = TLevelWriterP(path, m_pg->clone());
      m_lwPath = m_lw->getFilePath();
    }
  } catch (...) {
    resetState();
    throw;
  }

  TDimension iconSize = Preferences::instance()->getIconSize();
  assert(iconSize.lx > 0 && iconSize.ly > 0);
  m_lw->setIconSize(iconSize);

  if (!templateFId.isNoFrame()) 
    m_lw->setFrameFormatTemplateFId(templateFId);

  m_isOpen = true;
}

void LevelUpdater::initialize(TXshSimpleLevel *sl) {
  assert(!m_lw);
  assert(sl && sl->getScene());
  m_sl = sl;

  const TFilePath &path = sl->getScene()->decodeFilePath(sl->getPath());
  bool levelExists = TSystem::doesExistFileOrLevel(path);

  if (levelExists)
    loadSourceInfo(path);

  constructProperties(path);

  LevelProperties *levelProps = sl->getProperties();
  assert(levelProps);

  if (levelProps->hasAlpha() || !levelExists) {
    int bpp = levelProps->hasAlpha()
                  ? std::min(32, levelProps->getBpp())
                  : levelProps->getBpp();
    adjustBitDepth(m_pg, bpp, levelExists);
  }

  try {
    m_usingTempFile = levelExists && !hasRandomAccess(path);

    if (m_usingTempFile) {
      m_lwPath = createTempFilePath(path);
      m_lw = TLevelWriterP(m_lwPath, m_pg->clone());
    } else {
      m_lr = TLevelReaderP();
      m_lw = TLevelWriterP(path, m_pg->clone());
      m_lwPath = path;
    }
  } catch (...) {
    resetState();
    throw;
  }

  sl->getFids(m_fids);

  TDimension iconSize = Preferences::instance()->getIconSize();
  assert(iconSize.lx > 0 && iconSize.ly > 0);
  m_lw->setIconSize(iconSize);

  if (sl->getContentHistory())
    m_lw->setContentHistory(m_sl->getContentHistory()->clone());

  m_isOpen = true;
}

TFilePath LevelUpdater::createTempFilePath(const TFilePath &original) {
  TFilePath tempPath;
  int counter = 1;
  for (;;) {
    tempPath = original.withName(
        original.getWideName() + L"_ottmp" + std::to_wstring(counter++));
    if (!TSystem::doesExistFileOrLevel(tempPath)) break;
  }
  return tempPath;
}

void LevelUpdater::appendFrames(int endIndex) {
  if (m_sl) {
    for (; m_currIdx < endIndex; ++m_currIdx) {
      TImageP img = m_sl->getFullsampledFrame(m_fids[m_currIdx],
                                              ImageManager::dontPutInCache);
      assert(img);

      if (!img && m_lr) {
        img = m_lr->getFrameReader(m_fids[m_currIdx])->load();
        if (img) img->setPalette(m_sl->getPalette());
      }

      if (img) m_lw->getFrameWriter(m_fids[m_currIdx])->save(img);
    }
  } else if (m_lr) {
    for (; m_currIdx < endIndex; ++m_currIdx) {
      TImageP img = m_lr->getFrameReader(m_fids[m_currIdx])->load();
      if (img) m_lw->getFrameWriter(m_fids[m_currIdx])->save(img);
    }
  }
}

void LevelUpdater::updateFrame(const TFrameId &fid, const TImageP &img) {
  resume();

  if (!m_usingTempFile) {
    m_lw->getFrameWriter(fid)->save(img);
    return;
  }

  int insertPos = std::lower_bound(m_fids.begin() + m_currIdx, m_fids.end(), fid) -
                  m_fids.begin();
  appendFrames(insertPos);

  m_lw->getFrameWriter(fid)->save(img);

  if (m_currIdx < static_cast<int>(m_fids.size()) && m_fids[m_currIdx] == fid) 
    ++m_currIdx;
}

void LevelUpdater::finalize() {
  if (!m_isOpen) return;

  resume();

  try {
    if (m_usingTempFile) {
      appendFrames(static_cast<int>(m_fids.size()));

      if (m_lr) {
        TFilePath finalPath(m_lr->getFilePath()), tempPath(m_lw->getFilePath());

        m_lr = TLevelReaderP();
        m_lw = TLevelWriterP();

        if (!TFileStatus(tempPath).doesExist())
          throw TSystemException(tempPath, "cant find!");

        TSystem::removeFileOrLevel_throw(finalPath);
        TSystem::renameFileOrLevel_throw(finalPath, tempPath);

        if (finalPath.getType() == "tlv") {
          TFilePath finalPalette = finalPath.withType("tpl");
          TFilePath tempPalette  = tempPath.withType("tpl");
          if (TFileStatus(finalPalette).doesExist()) {
            if (TFileStatus(tempPalette).doesExist())
              TSystem::deleteFile(finalPalette);
            TSystem::renameFile(finalPalette, tempPalette);
          }

          TFilePath finalHistory = finalPath.withType("hst");
          TFilePath tempHistory  = tempPath.withType("hst");
          if (TFileStatus(tempHistory).doesExist()) {
            if (TFileStatus(finalHistory).doesExist())
              TSystem::deleteFile(finalHistory);
            TSystem::renameFile(finalHistory, tempHistory);
          }
        }
      }
    }

    resetState();
  } catch (...) {
    resetState();
    throw;
  }
}

void LevelUpdater::flushData() {
  assert(m_isOpen);
  if (!m_lw) return;

  try {
    m_lw = TLevelWriterP();
  } catch (...) {
    resetState();
    throw;
  }
}

void LevelUpdater::resume() {
  assert(m_isOpen);
  if (m_lw) return;

  try {
    m_lw = TLevelWriterP(m_lwPath, m_pg->clone());
  } catch (...) {
    resetState();
    throw;
  }
}

#include <iostream>
#include <algorithm>
#include <vector>
using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int b, w, x, y;
    if (!(cin >> b >> w >> x >> y)) return 0;

    // Handle special cases first
    if (b == 1) {
        // Create grid with 1 black component and w white components
        // Pattern: alternating '.' and '@' in row 1, all '@' in row 2
        int cols = 2 * w - 1;
        cout << "2 " << cols << "\n";

        // First row: white islands separated by black tiles
        for (int j = 0; j < cols; ++j) {
            cout << (j % 2 == 0 ? '.' : '@');
        }
        cout << "\n";

        // Second row: all black tiles to connect the black parts
        for (int j = 0; j < cols; ++j) {
            cout << '@';
        }
        cout << "\n";
    } 
    else if (w == 1) {
        // Create grid with b black components and 1 white component
        // Pattern: alternating '@' and '.' in row 1, all '.' in row 2
        int cols = 2 * b - 1;
        cout << "2 " << cols << "\n";

        // First row: black islands separated by white tiles
        for (int j = 0; j < cols; ++j) {
            cout << (j % 2 == 0 ? '@' : '.');
        }
        cout << "\n";

        // Second row: all white tiles to connect the white parts
        for (int j = 0; j < cols; ++j) {
            cout << '.';
        }
        cout << "\n";
    } 
    else {
        // General case: b > 1 and w > 1
        // Use 4 rows to create required number of connected components

        int w_section_width = (w - 1 > 0) ? 2 * (w - 1) - 1 : 0;
        int b_section_width = (b - 1 > 0) ? 2 * (b - 1) - 1 : 0;
        int total_cols = max(w_section_width, b_section_width);

        cout << "4 " << total_cols << "\n";

        // Row 1: w-1 white islands (pattern: .@.@.)
        for (int j = 0; j < total_cols; ++j) {
            if (j < w_section_width) {
                cout << (j % 2 == 0 ? '.' : '@');
            } else {
                cout << '@'; // Fill with background color (black)
            }
        }
        cout << "\n";

        // Row 2: All black tiles (connects black areas from row 1)
        for (int j = 0; j < total_cols; ++j) {
            cout << '@';
        }
        cout << "\n";

        // Row 3: All white tiles (connects white areas from row 4)
        for (int j = 0; j < total_cols; ++j) {
            cout << '.';
        }
        cout << "\n";

        // Row 4: b-1 black islands (pattern: @.@.@)
        for (int j = 0; j < total_cols; ++j) {
            if (j < b_section_width) {
                cout << (j % 2 == 0 ? '@' : '.');
            } else {
                cout << '.'; // Fill with background color (white)
            }
        }
        cout << "\n";
    }

    return 0;
}

#include "track_generator/utils.hpp"
#include "routing/vehicle_mask.hpp"
#include "base/assert.hpp"
#include "base/logging.hpp"
#include <string>
#include <gflags/gflags.h>

// Define command-line flags for input/output directories and vehicle type
DEFINE_string(inputDir, "", "Path to KML files containing waypoints.");
DEFINE_string(outputDir, "", "Path where converted smooth tracks will be saved.");
DEFINE_int32(vehicleType, 0,
             "Numeric identifier corresponding to routing::VehicleType. "
             "Defaults to pedestrian mode.");
DEFINE_bool(showHelp, false, "Display usage information and exit.");

int main(int argc, char ** argv)
{
  // Set program usage message
  gflags::SetUsageMessage(
      "This utility generates smoother trajectories from waypoint sequences in KML files. "
      "Input KMLs must define points within a LineString element. When route construction fails, "
      "the original path is preserved unchanged. The tool supports batch processing of multiple KML files "
      "in the specified input directory.\n\n"
      "Example invocation:\n"
      "./track_generator_tool -inputDir=/path/to/input/kmls/ -outputDir=/path/to/output/tracks/");

  // Parse command-line arguments
  gflags::ParseCommandLineFlags(&argc, &argv, false /* remove_flags */);

  // Handle help request or no arguments
  if (argc == 1 || FLAGS_showHelp)
  {
    gflags::ShowUsageWithFlags(argv[0]);
    return 0;
  }

  // Validate required parameters
  bool missingInput = FLAGS_inputDir.empty();
  bool missingOutput = FLAGS_outputDir.empty();

  if (missingInput || missingOutput)
  {
    LOG(LINFO, (missingInput ? "Input" : "Output", "directory is required."));
    gflags::ShowUsageWithFlags(argv[0]);
    return 1;
  }

  // Execute track generation with validated parameters
  track_generator_tool::GenerateTracks(
      FLAGS_inputDir,
      FLAGS_outputDir,
      static_cast<routing::VehicleType>(FLAGS_vehicleType));

  return 0;
}

#include <iostream>
#include <string>
#include <memory>
#include <csignal>
#include <cstring>
#include <gz/transport/Node.hh>
#include <gz/msgs/image.pb.h>
#include <gst/gst.h>
#include <gst/app/gstappsrc.h>

// Pipeline components
static GstElement *stream_pipeline = nullptr;
static GMainLoop *main_event_loop = nullptr;
static GstElement *custom_app_source = nullptr;
static bool pipeline_initialized = false;

// Configuration parameters
std::string DESTINATION_ADDRESS = "127.0.0.1";
int UDP_PORT = 5600;
int FRAMES_PER_SECOND = 10;

// Frame handler: processes incoming image messages from Gazebo
void handle_image_data(const gz::msgs::Image &frame_msg) {
    if (!custom_app_source) return;

    // Set up media caps only once on first valid frame
    if (!pipeline_initialized) {
        GstCaps *media_caps = gst_caps_new_simple("video/x-raw",
            "format", G_TYPE_STRING, "RGB",
            "width", G_TYPE_INT, frame_msg.width(),
            "height", G_TYPE_INT, frame_msg.height(),
            "framerate", GST_TYPE_FRACTION, FRAMES_PER_SECOND, 1,
            nullptr);

        gst_app_src_set_caps(GST_APP_SRC(custom_app_source), media_caps);
        gst_caps_unref(media_caps);

        std::cout << "GStreamer initialized for resolution: "
                  << frame_msg.width() << "x" << frame_msg.height() << std::endl;
        pipeline_initialized = true;
    }

    // Transfer pixel data into GStreamer buffer
    const auto &raw_data = frame_msg.data();
    gsize buffer_size = raw_data.size();

    GstBuffer *new_buffer = gst_buffer_new_allocate(nullptr, buffer_size, nullptr);
    if (new_buffer) {
        gst_buffer_fill(new_buffer, 0, raw_data.data(), buffer_size);

        GstFlowReturn push_result = gst_app_src_push_buffer(
            GST_APP_SRC(custom_app_source), new_buffer);

        if (push_result != GST_FLOW_OK) {
            g_warning("Failed to enqueue buffer in appsrc");
        }
    } else {
        g_warning("Memory allocation for GStreamer buffer failed");
    }
}

// Detect presence of NVIDIA hardware encoder
bool has_nvidia_hardware_support() {
    GstElementFactory *encoder_factory = gst_element_factory_find("nvh264enc");
    bool supported = (encoder_factory != nullptr);
    if (supported) {
        gst_object_unref(encoder_factory);
    }
    return supported;
}

// Signal handler for graceful shutdown
void interrupt_handler(int signal_code) {
    (void)signal_code;
    if (main_event_loop) {
        g_main_loop_quit(main_event_loop);
    }
}

int main(int argument_count, char *arguments[]) {
    if (argument_count < 3) {
        std::cerr << "Usage: ./gz_gst_bridge <topic_name> <ip_address> [port] [fps]\n";
        return EXIT_FAILURE;
    }

    std::string topic_name = arguments[1];
    DESTINATION_ADDRESS = arguments[2];

    if (argument_count > 3) {
        try {
            UDP_PORT = std::stoi(arguments[3]);
        } catch (...) {
            std::cerr << "Invalid port number; using default.\n";
        }
    }

    if (argument_count > 4) {
        try {
            FRAMES_PER_SECOND = std::stoi(arguments[4]);
        } catch (...) {
            std::cerr << "Invalid framerate; using default.\n";
        }
    }

    // Initialize GStreamer subsystem
    gst_init(&argument_count, &arguments);

    // Create Gazebo transport node
    gz::transport::Node gazebo_node;

    // Construct pipeline string conditionally based on GPU support
    std::string pipeline_desc;
    std::string endpoint_spec = "host=" + DESTINATION_ADDRESS + " port=" + std::to_string(UDP_PORT);

    if (has_nvidia_hardware_support()) {
        std::cout << "Detected NVIDIA GPU encoder (nvh264enc)\n";
        pipeline_desc =
            "appsrc name=source ! queue max-size-buffers=1 leaky=downstream ! "
            "videoconvert ! "
            "nvh264enc preset=low-latency-hq zerolatency=true rc-mode=cbr bitrate=2048 qp-min=15 qp-max=35 gop-size=30 ! "
            "rtph264pay config-interval=1 mtu=1400 ! udpsink sync=false " + endpoint_spec;
    } else {
        std::cout << "Falling back to CPU-based x264 encoder\n";
        pipeline_desc =
            "appsrc name=source ! queue max-size-buffers=1 leaky=downstream ! "
            "videoconvert ! "
            "x264enc speed-preset=ultrafast tune=zerolatency bitrate=2048 key-int-max=30 ! "
            "rtph264pay config-interval=1 mtu=1400 ! udpsink sync=false " + endpoint_spec;
    }

    // Launch pipeline with error reporting
    GError *build_error = nullptr;
    stream_pipeline = gst_parse_launch(pipeline_desc.c_str(), &build_error);
    if (!stream_pipeline) {
        std::cerr << "Pipeline construction failed: " << build_error->message << std::endl;
        g_error_free(build_error);
        return EXIT_FAILURE;
    }

    // Retrieve and configure appsrc element
    custom_app_source = gst_bin_get_by_name(GST_BIN(stream_pipeline), "source");
    g_object_set(custom_app_source, "format", GST_FORMAT_TIME, nullptr);
    g_object_set(custom_app_source, "is-live", TRUE, nullptr);
    g_object_set(custom_app_source, "do-timestamp", TRUE, nullptr);
    g_object_set(custom_app_source, "leaky-type", 2, nullptr); // Drop outdated buffers
    g_object_set(custom_app_source, "max-bytes", 0U, nullptr);
    g_object_set(custom_app_source, "max-buffers", 2U, nullptr);

    // Start pipeline processing
    gst_element_set_state(stream_pipeline, GST_STATE_PLAYING);

    // Subscribe to Gazebo image topic
    if (!gazebo_node.Subscribe(topic_name, handle_image_data)) {
        std::cerr << "Unable to subscribe to topic: " << topic_name << std::endl;
        return EXIT_FAILURE;
    }

    std::cout << "Streaming '" << topic_name << "' -> "
              << DESTINATION_ADDRESS << ":" << UDP_PORT
              << " @ " << FRAMES_PER_SECOND << " FPS\n";

    // Enter event loop
    main_event_loop = g_main_loop_new(nullptr, FALSE);
    signal(SIGINT, interrupt_handler);
    g_main_loop_run(main_event_loop);

    // Cleanup resources
    gst_element_set_state(stream_pipeline, GST_STATE_NULL);
    gst_object_unref(custom_app_source);
    gst_object_unref(stream_pipeline);
    g_main_loop_unref(main_event_loop);

    return EXIT_SUCCESS;
}

