namespace infiniop_test::rope {

struct Test::Attributes {
    infiniopRoPEAlgo_t algorithm;
    std::shared_ptr<Tensor> output;
    std::shared_ptr<Tensor> input;
    std::shared_ptr<Tensor> position_ids;
    std::shared_ptr<Tensor> sine_table;
    std::shared_ptr<Tensor> cosine_table;
    std::shared_ptr<Tensor> reference;
};

std::shared_ptr<Test> Test::build(
    std::unordered_map<std::string, std::vector<uint8_t>> params,
    std::unordered_map<std::string, std::shared_ptr<Tensor>> tensors,
    double rel_tol, double abs_tol) {

    auto test_obj = std::make_shared<Test>(rel_tol, abs_tol);
    test_obj->_attributes = new Attributes();

    if (!check_names(params, Test::attribute_names()) ||
        tensors.find("y") == tensors.end() ||
        tensors.find("x") == tensors.end() ||
        tensors.find("pos_ids") == tensors.end() ||
        tensors.find("sin_table") == tensors.end() ||
        tensors.find("cos_table") == tensors.end() ||
        tensors.find("ans") == tensors.end()) {
        throw std::runtime_error("Invalid Test");
    }

    auto& attr = test_obj->_attributes;
    attr->algorithm = *reinterpret_cast<infiniopRoPEAlgo_t*>(params["algo"].data());
    attr->output      = tensors["y"];
    attr->input       = tensors["x"];
    attr->position_ids = tensors["pos_ids"];
    attr->sine_table  = tensors["sin_table"];
    attr->cosine_table = tensors["cos_table"];
    attr->reference   = tensors["ans"];

    return test_obj;
}

std::shared_ptr<infiniop_test::Result> Test::run(
    infiniopHandle_t handle, infiniDevice_t dev, int dev_id, size_t pre_runs, size_t num_runs) {

    infiniopRoPEDescriptor_t op_desc;
    infiniopRoPEAlgo_t algo = _attributes->algorithm;

    auto y_tensor = _attributes->output->to(dev, dev_id);
    auto x_tensor = _attributes->input->to(dev, dev_id);
    auto pos_tensor = _attributes->position_ids->to(dev, dev_id);
    auto sin_tensor = _attributes->sine_table->to(dev, dev_id);
    auto cos_tensor = _attributes->cosine_table->to(dev, dev_id);

    CHECK_OR(infiniopCreateRoPEDescriptor(handle, &op_desc,
                                          y_tensor->desc(),
                                          x_tensor->desc(),
                                          pos_tensor->desc(),
                                          sin_tensor->desc(),
                                          cos_tensor->desc(),
                                          algo),
             return TEST_FAILED(OP_CREATION_FAILED, "Failed to create op descriptor."));

    size_t workspace_bytes;
    CHECK_OR(infiniopGetRoPEWorkspaceSize(op_desc, &workspace_bytes),
             return TEST_FAILED(OP_CREATION_FAILED, "Failed to get workspace size."));

    void* workspace_mem;
    CHECK_OR(infinirtMalloc(&workspace_mem, workspace_bytes),
             return TEST_FAILED(OP_CREATION_FAILED, "Failed to allocate workspace."));

    // Execute once for correctness check
    CHECK_OR(infiniopRoPE(op_desc, workspace_mem, workspace_bytes,
                          y_tensor->data(),
                          x_tensor->data(),
                          pos_tensor->data(),
                          sin_tensor->data(),
                          cos_tensor->data(),
                          nullptr),
             return TEST_FAILED(OP_EXECUTION_FAILED, "Failed during execution."));

    try {
        allClose(y_tensor, _attributes->reference, _rtol, _atol);
    } catch (const std::exception& err) {
        return TEST_FAILED(RESULT_INCORRECT, err.what());
    }

    double duration_ms = 0.0;
    duration_ms = benchmark(
        [=]() {
            infiniopRoPE(
                op_desc, workspace_mem, workspace_bytes,
                y_tensor->data(),
                x_tensor->data(),
                pos_tensor->data(),
                sin_tensor->data(),
                cos_tensor->data(),
                nullptr);
        },
        pre_runs, num_runs);

    return TEST_PASSED(duration_ms);
}

std::vector<std::string> Test::attribute_names() {
    return {"algo"};
}

std::vector<std::string> Test::tensor_names() {
    return {"y", "x", "pos_ids", "sin_table", "cos_table", "ans"};
}

std::vector<std::string> Test::output_names() {
    return {"y"};
}

std::string Test::toString() const {
    std::ostringstream stream;
    stream << op_name() << '\n';
    stream << "- y: " << _attributes->output->info() << '\n';
    stream << "- x: " << _attributes->input->info() << '\n';
    stream << "- pos_ids: " << _attributes->position_ids->info() << '\n';
    stream << "- sin_table: " << _attributes->sine_table->info() << '\n';
    stream << "- cos_table: " << _attributes->cosine_table->info() << '\n';
    stream << "- algo: " << _attributes->algorithm << '\n';
    stream << std::scientific << std::setprecision(2);
    stream << "- rtol=" << _rtol << ", atol=" << _atol << '\n';
    return stream.str();
}

Test::~Test() {
    delete _attributes;
}

