#include <iostream>
#include <vector>
#include <cmath>
#include <algorithm>
#include <random>
#include <chrono>
#include <functional>

// Helper function to compute smallest prime factor table up to n
std::vector<int> build_spf_table(int n) {
    std::vector<int> spf(n + 1);
    for (int i = 1; i <= n; ++i) spf[i] = i;
    for (int i = 2; i * i <= n; ++i) {
        if (spf[i] == i) { // i is prime
            for (int j = i * i; j <= n; j += i) {
                if (spf[j] == j) spf[j] = i;
            }
        }
    }
    return spf;
}

// Multiplicative function generator: f(i) = f(p) * f(i/p) for i = p * (i/p)
int compute_value(int idx, const std::vector<int>& spf, const std::vector<int>& prime_vals) {
    if (idx == 1) return 1;
    int p = spf[idx];
    int q = idx / p;
    return prime_vals[p] * prime_vals[q];
}

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int N;
    if (!(std::cin >> N)) return 0;

    auto spf = build_spf_table(N);

    // Precompute primes in range [2, N]
    std::vector<bool> is_prime(N + 1, true);
    is_prime[0] = is_prime[1] = false;
    for (int i = 2; i * i <= N; ++i) {
        if (is_prime[i]) {
            for (int j = i * i; j <= N; j += i) {
                is_prime[j] = false;
            }
        }
    }

    // Initial deterministic pass: minimize max prefix sum greedily
    std::vector<int> best_sequence(N + 1, 0);
    std::vector<int> trial_sequence(N + 1, 0);
    trial_sequence[1] = 1;

    long long current_sum = 1;
    long long best_max_abs = 1;

    for (int i = 2; i <= N; ++i) {
        if (is_prime[i]) {
            trial_sequence[i] = (current_sum >= 0) ? -1 : 1;
        } else {
            trial_sequence[i] = compute_value(i, spf, trial_sequence);
        }
        current_sum += trial_sequence[i];
        best_max_abs = std::max(best_max_abs, std::llabs(current_sum));
    }

    best_sequence = trial_sequence;

    // Randomized refinement phase
    std::mt19937_64 rng(std::chrono::steady_clock::now().time_since_epoch().count());
    auto start = std::chrono::steady_clock::now();
    const auto MAX_TIME_MS = std::chrono::milliseconds(800);

    for (int attempt = 0; attempt < 500; ++attempt) {
        auto now = std::chrono::steady_clock::now();
        if (std::chrono::duration_cast<std::chrono::milliseconds>(now - start) > MAX_TIME_MS) break;

        trial_sequence.assign(N + 1, 0);
        trial_sequence[1] = 1;

        long long running_sum = 1;
        long long run_max = 1;
        bool viable = true;

        // For each index, decide value based on current sum and randomness
        for (int i = 2; i <= N; ++i) {
            if (is_prime[i]) {
                std::uniform_int_distribution<int> dist(0, 1);
                if (std::abs(running_sum) <= (attempt % 3)) {
                    trial_sequence[i] = (dist(rng) == 0) ? 1 : -1;
                } else {
                    trial_sequence[i] = (running_sum > 0) ? -1 : 1;
                }
            } else {
                trial_sequence[i] = compute_value(i, spf, trial_sequence);
            }

            running_sum += trial_sequence[i];
            run_max = std::max(run_max, std::llabs(running_sum));

            if (run_max >= best_max_abs) {
                viable = false;
                break;
            }
        }

        if (viable && run_max < best_max_abs) {
            best_max_abs = run_max;
            best_sequence = trial_sequence;
            if (best_max_abs <= 2) break;
        }
    }

    // Output final sequence
    for (int i = 1; i <= N; ++i) {
        std::cout << best_sequence[i];
        if (i < N) std::cout << ' ';
    }
    std::cout << '\n';

    return 0;
}

