// Command-line flag to toggle display of only simple regions
static cl::opt<bool> showSimpleOnly("simple-regions-only",
                                    cl::desc("Restrict RegionViewer output to simple regions"),
                                    cl::Hidden,
                                    cl::init(false));

namespace llvm {

// Overloaded label generation for RegionNode
std::string DOTGraphTraits<RegionNode *>::getNodeLabel(RegionNode *node,
                                                       RegionNode * /*graph*/) {
  if (!node->isSubRegion()) {
    BasicBlock *bb = node->getNodeAs<BasicBlock>();
    return isSimple()
               ? DOTGraphTraits<DOTFuncInfo *>::getSimpleNodeLabel(bb, nullptr)
               : DOTGraphTraits<DOTFuncInfo *>::getCompleteNodeLabel(bb, nullptr);
  }
  return "Subregion";
}

// Specialization for RegionInfo* graph traits
template <>
struct DOTGraphTraits<RegionInfo *> : public DOTGraphTraits<RegionNode *> {
  explicit DOTGraphTraits(bool simpleMode = false)
      : DOTGraphTraits<RegionNode *>(simpleMode) {}

  static std::string getGraphName(const RegionInfo *) { return "Region Graph"; }

  std::string getNodeLabel(RegionNode *node, RegionInfo *ri) override {
    Region *topLevel = ri->getTopLevelRegion();
    return DOTGraphTraits<RegionNode *>::getNodeLabel(
        node, reinterpret_cast<RegionNode *>(topLevel));
  }

  std::string getEdgeAttributes(RegionNode *srcNode,
                                GraphTraits<RegionInfo *>::ChildIteratorType it,
                                RegionInfo *ri) override {
    RegionNode *dstNode = *it;
    if (srcNode->isSubRegion() || dstNode->isSubRegion())
      return "";

    BasicBlock *srcBB = srcNode->getNodeAs<BasicBlock>();
    BasicBlock *dstBB = dstNode->getNodeAs<BasicBlock>();

    // Detect backedges: check if destination dominates source via region nesting
    Region *r = ri->getRegionFor(dstBB);
    while (r && r->getParent()) {
      if (r->getParent()->getEntry() == dstBB)
        r = r->getParent();
      else
        break;
    }

    if (r && r->getEntry() == dstBB && r->contains(srcBB))
      return "constraint=false";

    return "";
  }

  // Recursively print subregions as nested clusters
  static void emitRegionClusters(const Region &region,
                                 GraphWriter<RegionInfo *> &gw,
                                 unsigned level = 0) {
    raw_ostream &out = gw.getOStream();
    const void *addr = &region;
    out.indent(2 * level) << "subgraph cluster_" << addr << " {\n";
    out.indent(2 * (level + 1)) << "label=\"\";\n";

    bool isSimple = region.isSimple();
    if (!showSimpleOnly || isSimple) {
      out.indent(2 * (level + 1)) << "style=filled;\n";
      out.indent(2 * (level + 1)) << "color=" << ((region.getDepth() * 2 % 12) + 1) << "\n";
    } else {
      out.indent(2 * (level + 1)) << "style=solid;\n";
      out.indent(2 * (level + 1)) << "color=" << ((region.getDepth() * 2 % 12) + 2) << "\n";
    }

    // Recurse into child regions
    for (const auto *child : region)
      emitRegionClusters(*child, gw, level + 1);

    // Emit leaf basic blocks that belong directly to this region
    const RegionInfo &ri = *static_cast<const RegionInfo*>(region.getRegionInfo());
    for (BasicBlock *bb : region.blocks()) {
      if (ri.getRegionFor(bb) == &region)
        out.indent(2 * (level + 1)) << "Node" << static_cast<const void *>(
            ri.getTopLevelRegion()->getBBNode(bb)) << ";\n";
    }

    out.indent(2 * level) << "}\n";
  }

  static void addCustomGraphFeatures(const RegionInfo *ri,
                                     GraphWriter<RegionInfo *> &gw) {
    raw_ostream &out = gw.getOStream();
    out << "\tcolorscheme=\"paired12\"\n";
    emitRegionClusters(*ri->getTopLevelRegion(), gw, 4);
  }
};

