#ifndef NDEBUG
// Internal utilities for interactive viewing
static void launchRegionView(RegionInfo *ri, bool brief) {
  assert(ri && "RegionInfo must be non-null");
  Function *F = ri->getTopLevelRegion()->getEntry()->getParent();
  std::string title = DOTGraphTraits<RegionInfo *>::getGraphName(ri);
  ViewGraph(ri, "reg", brief,
            Twine(title) + " for '" + F->getName() + "'");
}

static void runWithPassManager(const Function *func, FunctionPass *pass) {
  assert(func && "Function required");
  assert(!func->isDeclaration() && "Function must be defined");

  Function *mutableF = const_cast<Function *>(func);
  legacy::FunctionPassManager fpm(mutableF->getParent());
  fpm.add(pass);
  fpm.doInitialization();
  fpm.run(*mutableF);
  fpm.doFinalization();
}

void llvm::viewRegion(RegionInfo *ri) { launchRegionView(ri, false); }
void llvm::viewRegion(const Function *f) {
  runWithPassManager(f, createRegionViewerPass());
}
void llvm::viewRegionOnly(RegionInfo *ri) { launchRegionView(ri, true); }
void llvm::viewRegionOnly(const Function *f) {
  runWithPassManager(f, createSimpleRegionViewerPass());
}
#endif

