// Test parsing of unreachable call specification
TEST(PropertySpecTest, ParseUnreachCall_Variant) {
  PropertySpec spec;
  std::string err_msg;

  std::string input = "CHECK( init(main()), LTL(G ! call(reach_error())) )\n";
  ASSERT_TRUE(PropertySpec::parseFromString(input, spec, err_msg)) << err_msg;
  ASSERT_FALSE(spec.isEmpty());
  ASSERT_EQ(spec.getRules().size(), 1u);
  EXPECT_EQ(spec.getRules()[0].propertyType, PropertyKind::UnreachCall);
  EXPECT_EQ(spec.getRules()[0].functionName, "reach_error");
  EXPECT_EQ(spec.getRules()[0].specType, PropertyType::CHECK);
}

// Test parsing of memory safety specification
TEST(PropertySpecTest, ParseMemSafety_Variant) {
  PropertySpec spec;
  std::string err_msg;

  std::string input = "CHECK( init(main()), LTL(G valid-deref) )\n";
  ASSERT_TRUE(PropertySpec::parseFromString(input, spec, err_msg)) << err_msg;
  ASSERT_FALSE(spec.isEmpty());
  ASSERT_EQ(spec.getRules().size(), 1u);
  EXPECT_EQ(spec.getRules()[0].propertyType, PropertyKind::MemSafety);
  EXPECT_EQ(spec.getRules()[0].specType, PropertyType::CHECK);
}

// Test parsing of no-overflow specification
TEST(PropertySpecTest, ParseNoOverflow_Variant) {
  PropertySpec spec;
  std::string err_msg;

  std::string input = "CHECK( init(main()), LTL(G ! overflow) )\n";
  ASSERT_TRUE(PropertySpec::parseFromString(input, spec, err_msg)) << err_msg;
