#include "stdafx.h"
#include "EnderCrystalModel.h"

// Constructor: Initialize the ender crystal components
EnderCrystalModel::EnderCrystalModel(float g) 
{
	// Create the outer glass shell component
	glassShell = new ModelPart(this, L"glass");
	glassShell->texOffs(0, 0)->addBox(-4, -4, -4, 8, 8, 8);

	// Create the inner cubic core component
	coreCube = new ModelPart(this, L"cube");
	coreCube->texOffs(32, 0)->addBox(-4, -4, -4, 8, 8, 8);

	// Create the base platform component
	basePlatform = new ModelPart(this, L"base");
	basePlatform->texOffs(0, 16)->addBox(-6, 0, -6, 12, 4, 12);

	// Precompile all parts to prevent first-render lag
	glassShell->compile(1.0f/16.0f);
	coreCube->compile(1.0f/16.0f);
	basePlatform->compile(1.0f/16.0f);
}

// Render the ender crystal with animation and rotation
void EnderCrystalModel::render(shared_ptr<Entity> entity, float time, float r, float bob, float yRot, float xRot, float scale, bool usecompiled)
{
	glPushMatrix();

	// Apply base scaling and vertical offset
	glScalef(2.0f, 2.0f, 2.0f);
	glTranslatef(0.0f, -0.5f, 0.0f);

	// Render the base platform
	basePlatform->render(scale, usecompiled);

	// Apply rotation around Y-axis and position for main body
	glRotatef(r, 0.0f, 1.0f, 0.0f);
	glTranslatef(0.0f, 0.8f + bob, 0.0f);

	// First glass shell layer with diagonal rotation
	glRotatef(60.0f, 0.7071f, 0.0f, 0.7071f);
	glassShell->render(scale, usecompiled);

	// Scale down and add second glass shell layer
	float shrinkFactor = 14 / 16.0f;
	glScalef(shrinkFactor, shrinkFactor, shrinkFactor);
	glRotatef(60.0f, 0.7071f, 0.0f, 0.7071f);
	glRotatef(r, 0.0f, 1.0f, 0.0f);
	glassShell->render(scale, usecompiled);

	// Scale down again for inner core
	glScalef(shrinkFactor, shrinkFactor, shrinkFactor);
	glRotatef(60.0f, 0.7071f, 0.0f, 0.7071f);
	glRotatef(r, 0.0f, 1.0f, 0.0f);
	coreCube->render(scale, usecompiled);

	glPopMatrix();
}

#include <iostream>
#include <vector>
#include <cstdlib>
using namespace std;

// Global state tracking variables
int startDepth;
int currentDepth;
int moveCount = 0;

// Constants for safety limits
const int MAX_ALLOWED_MOVES = 100000;
const int SAFETY_MARGIN = 95000;

// Function to query the depth (distance to exit)
int get_depth() {
    cout << "query" << endl;
    int d;
    if (!(cin >> d)) exit(0);
    return d;
}

// Function to move along edge of color c
void traverse_edge(int c) {
    cout << "move " << c << endl;
    int result;
    if (!(cin >> result)) exit(0);
    moveCount++;
    if (result == 1) {
        // Exit reached
        exit(0);
    }
}

// Stores the sequence of upward moves taken so far
vector<int> path_history;

// Tracks which edge leads back down to the previous node
int downward_edge = -1;

// Safely ascend one level using at most 3 moves and 1 query
void safe_ascend() {
    // Determine candidate colors excluding the downward edge
    vector<int> options;
    for (int col = 0; col < 3; ++col) {
        if (col != downward_edge) {
            options.push_back(col);
        }
    }

    // Try first option
    int trial_col = options[0];
    traverse_edge(trial_col);

    // Check if we moved up or down
    int new_depth = get_depth();
    if (new_depth < currentDepth) {
        // Successful upward move
        currentDepth = new_depth;
        downward_edge = trial_col;
        path_history.push_back(trial_col);
    } else {
        // Failed: moved down instead, revert and try other option
        traverse_edge(trial_col); // Go back

        int alt_col = options[1];
        traverse_edge(alt_col);

        // This must be correct since only two upward options exist
        currentDepth--;
        downward_edge = alt_col;
        path_history.push_back(alt_col);
    }
}

// Initial step to determine direction when no prior knowledge exists
void first_move() {
    // Try color 0
    traverse_edge(0);
    int d = get_depth();
    if (d < currentDepth) {
        currentDepth = d;
        downward_edge = 0;
        path_history.push_back(0);
        return;
    }
    traverse_edge(0); // Revert

    // Try color 1
    traverse_edge(1);
    d = get_depth();
    if (d < currentDepth) {
        currentDepth = d;
        downward_edge = 1;
        path_history.push_back(1);
        return;
    }
    traverse_edge(1); // Revert

    // Must be color 2
    traverse_edge(2);
    currentDepth--;
    downward_edge = 2;
    path_history.push_back(2);
}

int main() {
    // Read starting depth
    if (!(cin >> startDepth)) return 0;
    currentDepth = startDepth;

    // Already at root/exit
    if (currentDepth == 0) return 0;

    // First move initialization
    first_move();

    // Continue until reaching the root
    while (currentDepth > 0) {
        // If approaching move limit, disable batching and use safe steps
        if (moveCount > SAFETY_MARGIN) {
            safe_ascend();
            continue;
        }

        // Attempt pattern detection in move history for optimization
        int best_period = -1;
        int hist_size = path_history.size();

        // Look for repeating patterns up to length 20
        for (int period = 1; period <= 20 && period * 2 <= hist_size; ++period) {
            bool is_match = true;
            // Compare last 'period' elements with preceding 'period' elements
            for (int offset = 0; offset < period; ++offset) {
                if (path_history[hist_size - period + offset] != 
                    path_history[hist_size - 2 * period + offset]) {
                    is_match = false;
                    break;
                }
            }
            if (is_match) {
                best_period = period;
                break;
            }
        }

        if (best_period != -1) {
            // Found a repeating pattern — attempt batch execution
            int batch_size = min(best_period, currentDepth);

            // Build predicted move sequence from pattern
            vector<int> predicted_moves;
            for (int i = 0; i < batch_size; ++i) {
                predicted_moves.push_back(path_history[hist_size - best_period + i]);
            }

            // Execute batched moves
            for (int col : predicted_moves) {
                traverse_edge(col);
            }

            // Verify correctness with one query
            int actual_depth = get_depth();

            if (actual_depth == currentDepth - batch_size) {
                // Prediction was correct
                currentDepth = actual_depth;
                downward_edge = predicted_moves.back();
                path_history.insert(path_history.end(), 
                                   predicted_moves.begin(), 
                                   predicted_moves.end());
            } else {
                // Prediction failed — backtrack and fall back to safe step
                for (int i = batch_size - 1; i >= 0; --i) {
                    traverse_edge(predicted_moves[i]);
                }
                safe_ascend();
            }
        } else {
            // No pattern found — use safe step
            safe_ascend();
        }
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;
using i64 = long long;

// Optimized constants for large number operations
constexpr i64 MOD  = 1'000'000'007LL;
constexpr i64 INF64 = 4e18;

// Helper function to compute cube of a number
i64 cube(i64 n) {
    return n * n * n;
}

void solve() {
    // Observation: The k-th group in the sequence has sum equal to k^3
    // Example:
    // Group 1: [1] → sum = 1 = 1³
    // Group 2: [3,5] → sum = 8 = 2³
    // Group 3: [7,9,11] → sum = 27 = 3³
    // etc.

    i64 k;
    cin >> k;

    // Compute cube using helper function instead of direct multiplication
    i64 result = cube(k);

    cout << result << '\n';
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    solve();
    return 0;
}

