#include <iostream>
#include <vector>
#include <map>
#include <stack>
using namespace std;

// Memoization map to store previously computed query results
map<pair<int, int>, pair<int, int>> memoized_results;

// Function to execute a query and cache the result
pair<int, int> execute_query(int left, int right) {
    if (left > right) {
        return {-1, 0};
    }

    // Check if result is already cached
    auto key = make_pair(left, right);
    if (memoized_results.find(key) != memoized_results.end()) {
        return memoized_results[key];
    }

    cout << "? " << left << " " << right << endl;
    int value, frequency;
    cin >> value >> frequency;

    // Handle invalid response
    if (value == -1 && frequency == -1) {
        exit(1);
    }

    // Store result in cache before returning
    memoized_results[key] = {value, frequency};
    return {value, frequency};
}

// Result array (1-indexed)
vector<int> solution;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;
    solution.assign(n + 1, 0);

    // Stack-based iterative approach for divide-and-conquer
    stack<pair<int, int>> segments;
    segments.push({1, n});

    while (!segments.empty()) {
        auto [l, r] = segments.top();
        segments.pop();

        if (l > r) continue;

        auto [mode_value, mode_count] = execute_query(l, r);

        // Binary search to find the rightmost position of the mode block
        int right_boundary = r;
        int low = l + mode_count - 1;
        int high = r;

        while (low <= high) {
            int mid = low + (high - low) / 2;
            auto [q_val, q_freq] = execute_query(l, mid);

            if (q_val == mode_value && q_freq >= mode_count) {
                right_boundary = mid;
                high = mid - 1;
            } else {
                low = mid + 1;
            }
        }

        int left_boundary = right_boundary - mode_count + 1;

        // Fill the identified segment with the mode value
        for (int i = left_boundary; i <= right_boundary; ++i) {
            solution[i] = mode_value;
        }

        // Add remaining subsegments to process
        segments.push({l, left_boundary - 1});
        segments.push({right_boundary + 1, r});
    }

    // Output final answer
    cout << "! ";
    for (int i = 1; i <= n; ++i) {
        cout << solution[i];
        if (i < n) cout << " ";
    }
    cout << endl;

    return 0;
}

