#define SOL_ALL_SAFETIES_ON 1
#include <sol/sol.hpp>
#include <iostream>

// Function that adds 20 to the input integer
int addTwenty(int number) {
    return 20 + number;
}

// Function that prepends a message to the input string
std::string prependMessage(std::string inputText) {
    return "received: " + inputText;
}

// Fallback function for variadic arguments
sol::variadic_results handleVariadicArgs(
     sol::this_state state, sol::variadic_args arguments) {
    sol::variadic_results results;
    if (arguments.size() == 2) {
        // If two integer arguments are provided, sum them
        results.push_back({ state,
            sol::in_place,
            arguments.get<int>(0) + arguments.get<int>(1) });
    }
    else {
        // Default return value for other cases
        results.push_back({ state, sol::in_place, 52 });
    }
    return results;
}

int main(int, char*[]) {
    std::cout << "=== overloading with fallback ==="
              << std::endl;

    sol::state luaEnvironment;
    luaEnvironment.open_libraries();

    // Register overloaded function 'f' with three variants
    luaEnvironment.set_function(
         "f", sol::overload(addTwenty, prependMessage, handleVariadicArgs));

    // Execute Lua scripts to test different argument types
    luaEnvironment.script("print(f(1))");      // Calls addTwenty
    luaEnvironment.script("print(f('hi'))");   // Calls prependMessage
    luaEnvironment.script("print(f(22, 11))"); // Calls handleVariadicArgs (sum)
    luaEnvironment.script("print(f({}))");     // Calls handleVariadicArgs (default)

    return 0;
}

