// Trial configuration data instance
MinecraftDynamicConfigurations::Dynamic_Config_Trial_Data MinecraftDynamicConfigurations::trialData;

// Flag indicating whether initial update cycle has begun
bool MinecraftDynamicConfigurations::s_bFirstUpdateStarted = false;

// Tracks which configurations have been updated
bool MinecraftDynamicConfigurations::s_bUpdatedConfigs[MinecraftDynamicConfigurations::eDynamic_Config_Max];

// Current configuration being processed
MinecraftDynamicConfigurations::EDynamic_Configs MinecraftDynamicConfigurations::s_eCurrentConfig = MinecraftDynamicConfigurations::eDynamic_Config_Max;

// Size-related tracking variables
size_t MinecraftDynamicConfigurations::s_currentConfigSize = 0;
size_t MinecraftDynamicConfigurations::s_dataWrittenSize = 0;
byte* MinecraftDynamicConfigurations::s_dataWritten = nullptr;

// Main tick function: triggers full update on first run
void MinecraftDynamicConfigurations::Tick()
{
	if (!s_bFirstUpdateStarted)
	{
		RefreshAllConfigs();
		s_bFirstUpdateStarted = true;
	}
}

// Returns the trial time in seconds
DWORD MinecraftDynamicConfigurations::GetTrialTime()
{
	return trialData.trialTimeSeconds;
}

// Reset all config flags and start updating from first unprocessed config
void MinecraftDynamicConfigurations::RefreshAllConfigs()
{
	DWORD idx = 0;
	while (idx < eDynamic_Config_Max)
	{
		s_bUpdatedConfigs[idx] = false;
		++idx;
	}
	ProcessNextConfig();
}

// Find and process next unprocessed configuration
void MinecraftDynamicConfigurations::ProcessNextConfig()
{
	EDynamic_Configs cfgToProcess = eDynamic_Config_Max;
	DWORD i = 0;
	while (i < eDynamic_Config_Max)
	{
		if (!s_bUpdatedConfigs[i])
		{
			cfgToProcess = static_cast<EDynamic_Configs>(i);
			break;
		}
		++i;
	}

	if (cfgToProcess < eDynamic_Config_Max)
	{
		ApplyConfigurationUpdate(cfgToProcess);
	}
}

// Initiates async retrieval of configuration size
void MinecraftDynamicConfigurations::ApplyConfigurationUpdate(EDynamic_Configs id)
{
	app.DebugPrintf("DynamicConfig: Attempting to update dynamic configuration %d\n", id);

	HRESULT hr = Sentient::SenDynamicConfigGetSize(
		id,
		&s_currentConfigSize,
		&MinecraftDynamicConfigurations::OnSizeReadyCallback,
		nullptr
	);

	switch (hr)
	{
	case S_OK:
		s_eCurrentConfig = id;
		break;
	case E_FAIL:
		app.DebugPrintf("DynamicConfig: Failed to get size for config\n");
		break;
	case Sentient::SENTIENT_E_NOT_INITIALIZED:
		app.DebugPrintf("DynamicConfig: Failed to get size for config as sentient not initialized\n");
		break;
	case E_POINTER:
		app.DebugPrintf("DynamicConfig: Failed to get size for config as pointer is invalid\n");
		break;
	}

	if (FAILED(hr))
	{
		s_bUpdatedConfigs[id] = true;
		ProcessNextConfig();
	}
}

// Callback after size request completes — proceeds to fetch raw bytes
void MinecraftDynamicConfigurations::OnSizeReadyCallback(HRESULT taskResult, void* userData)
{
	if (SUCCEEDED(taskResult))
	{
		s_dataWritten = new byte[s_currentConfigSize];
		HRESULT hr = Sentient::SenDynamicConfigGetBytes(
			s_eCurrentConfig,
			s_currentConfigSize,
			&s_dataWrittenSize,
			s_dataWritten,
			&MinecraftDynamicConfigurations::OnDataReadyCallback,
			nullptr
		);

		switch (hr)
		{
		case S_OK:
			break;
		case E_FAIL:
			app.DebugPrintf("DynamicConfig : Failed to get bytes for config\n");
			break;
		case Sentient::SENTIENT_E_NOT_INITIALIZED:
			app.DebugPrintf("DynamicConfig : Failed to get bytes for config as sentient not initialized\n");
			break;
		case E_POINTER:
			app.DebugPrintf("DynamicConfig: Failed to get bytes for config as pointer is NULL\n");
			break;
		}

		if (FAILED(hr))
		{
			s_bUpdatedConfigs[s_eCurrentConfig] = true;
			ProcessNextConfig();
		}
	}
	else
	{
		s_bUpdatedConfigs[s_eCurrentConfig] = true;
		ProcessNextConfig();
		app.DebugPrintf("MinecraftDynamicConfigurations::OnSizeReadyCallback : FAILED\n");
	}
}

// Callback after data retrieval — parses and stores config
void MinecraftDynamicConfigurations::OnDataReadyCallback(HRESULT taskResult, void* userData)
{
	if (SUCCEEDED(taskResult) && s_currentConfigSize == s_dataWrittenSize)
	{
		switch (s_eCurrentConfig)
		{
		case eDynamic_Config_Trial:
		{
			int version = *reinterpret_cast<int*>(s_dataWritten);
			if (version == DYNAMIC_CONFIG_TRIAL_VERSION)
			{
				memcpy(&trialData, s_dataWritten + sizeof(int), sizeof(_dynamic_config_trial_data_version1));
				app.DebugPrintf("Updated dynamic config TRIAL: timer is %d\n", trialData.trialTimeSeconds);
			}
			break;
		}
		}
	}
	else
	{
		app.DebugPrintf("MinecraftDynamicConfigurations::OnDataReadyCallback : FAILED\n");
	}

	delete[] s_dataWritten;
	s_dataWritten = nullptr;
	s_bUpdatedConfigs[s_eCurrentConfig] = true;
	ProcessNextConfig();
}

#include <engLib/eng.h>
namespace engine::store::pythonBase {

Error IPythonInstanceBase::writeQuestions(
    const pybind11::object &question) noexcept {
    py::object dummy_result;
    Error err_code;
    LOGPIPE();

    // Check if the WriteQuestions method is available in Python
    if ((m_pyMethods & PythonMethod::WriteQuestions) == 0)
        return Parent::writeQuestions(question);

    // Create a wrapper function to invoke the Python method safely
    auto python_call = [this, &question]() -> Error {
        try {
            m_pyInstance.attr("writeQuestions")(question);
        } catch (...) {
            // Handle exceptions internally; return appropriate error
            return Error::Generic;
        }
        return Error::None;
    };

    // Execute the Python call and capture result
    err_code = executePython(python_call);

    // If parent invocation is required based on error code
    if (shouldInvokeParent(err_code))
        return Parent::writeQuestions(question);

    return err_code;
}

Error IPythonInstanceBase::writeAnswers(
    const pybind11::object &answers) noexcept {
    py::object dummy_result;
    Error err_code;
    LOGPIPE();

    // Verify whether WriteAnswers is supported
    if ((m_pyMethods & PythonMethod::WriteAnswers) == 0)
        return Parent::writeAnswers(answers);

    // Wrap the Python method invocation in a lambda
    auto python_call = [this, &answers]() -> Error {
        try {
            m_pyInstance.attr("writeAnswers")(answers);
        } catch (...) {
            return Error::Generic;
        }
        return Error::None;
    };

    // Run the Python code and store outcome
    err_code = executePython(python_call);

    // Decide whether fallback to base implementation is needed
    if (shouldInvokeParent(err_code))
        return Parent::writeAnswers(answers);

    return err_code;
}

}  // namespace engine::store::pythonBase

