// Helper function to verify that a type correctly implements absl::Hash
template <typename Factory>
testing::AssertionResult CheckAbslHashImplementation(Factory&& factory) {
    using T = std::decay_t<decltype(factory())>;
    TVector<T> samples;

    // Generate 1000 random instances of the type
    for (int idx = 0; idx < 1000; ++idx) {
        samples.push_back(factory());
    }

    return absl::VerifyTypeImplementsAbslHashCorrectly(samples);
}

} // anonymous namespace

TEST(AbslHashes, ValueType) {
    EXPECT_TRUE(CheckAbslHashImplementation([] {
        return TValueTypeInfo{R, R};
    }));
}

