    // Helper to register common attributes for data members
    template<typename T>
    inline auto make_common_attributes(const char* name, const char* pretty, const char* tooltip) {
        return entt::attributes{
            entt::attribute{"name", name},
            entt::attribute{"pretty_name", pretty},
            entt::attribute{"tooltip", tooltip}
        };
    }

    // Helper to register bounded float fields (e.g., radius, length)
    inline auto make_bounded_float_attrs(const char* name, const char* pretty, const char* tooltip, float min_val = 0.0f, float step = 0.1f) {
        auto attrs = make_common_attributes(name, pretty, tooltip);
        attrs.emplace_back(entt::attribute{"min", min_val});
        attrs.emplace_back(entt::attribute{"step", step});
        return attrs;
    }

