        try_save(ar, ser20::make_nvp("collision_type", obj.collision_type));
    }

    template<typename Archive>
    void load_mesh(Archive& ar, physics_mesh_shape& obj) {
        try_load(ar, ser20::make_nvp("center", obj.center));
