        try_save(ar, ser20::make_nvp("material", obj.get_material()));
        try_save(ar, ser20::make_nvp("shapes", obj.get_shapes()));
    }

    template<typename Archive>
    void load_physics_component(Archive& ar, physics_component& obj) {
        bool val_bool{};
        if (try_load(ar, ser20::make_nvp("is_using_gravity", val_bool))) {
            obj.set_is_using_gravity(val_bool);
        }

        if (try_load(ar, ser20::make_nvp("is_kinematic", val_bool))) {
