        }

        if (try_load(ar, ser20::make_nvp("is_sensor", val_bool))) {
            obj.set_is_sensor(val_bool);
        }

        bool autoscale_default = true;
        if (try_load(ar, ser20::make_nvp("is_autoscaled", autoscale_default))) {
            obj.set_is_autoscaled(autoscale_default);
        }

        float mass_default = 1.0f;
        if (try_load(ar, ser20::make_nvp("mass", mass_default))) {
            obj.set_mass(mass_default);
        }

        layer_mask inc_mask{};
        if (try_load(ar, ser20::make_nvp("include_layers", inc_mask))) {
            obj.set_collision_include_mask(inc_mask);
        }

        layer_mask exc_mask{};
        if (try_load(ar, ser20::make_nvp("exclude_layers", exc_mask))) {
            obj.set_collision_exclude_mask(exc_mask);
        }

        math::bvec3 freeze_pos{};
        if (try_load(ar, ser20::make_nvp("freeze_position", freeze_pos))) {
            obj.set_freeze_position(freeze_pos);
        }

        math::bvec3 freeze_rot{};
        if (try_load(ar, ser20::make_nvp("freeze_rotation", freeze_rot))) {
