        std::vector<physics_compound_shape> shps{};
        if (try_load(ar, ser20::make_nvp("shapes", shps))) {
            obj.set_shapes(shps);
        }
    }

    // Explicit instantiations
    #define INSTANTIATE_SERIALIZATION(T) \
